const lessonsById: Record<string, LessonData> = JSON.parse("{\"mc-mod1-les1\":{\"$schema\":\"../../../packages/platform/schema/lesson.schema.json\",\"id\":\"mc-mod1-les1\",\"courseId\":\"medchem\",\"moduleId\":\"mc-mod-01\",\"title\":{\"tr\":\"Termodinamik Aktivite ve Ferguson İlkesi\",\"ar\":\"النشاط الديناميكي الحراري ومبدأ Ferguson\",\"en\":\"Thermodynamic Activity & The Ferguson Principle\"},\"order\":1,\"access\":\"free\",\"objective\":{\"tr\":\"Yapı-spesifik ve yapı-nonspesifik ilaçları ayırt etmek ve etkiyi termodinamik aktivite (bağıl doygunluk) ile tahmin etmek.\",\"ar\":\"التمييز بين الأدوية النوعية وغير النوعية بنيوياً والتنبؤ بالتأثير عبر النشاط الديناميكي الحراري (التشبع النسبي).\",\"en\":\"Differentiate structurally specific from non-specific drugs and predict biological action from relative thermodynamic saturation.\"},\"misconceptions\":[{\"tr\":\"Tüm ilaçların spesifik bir protein reseptörüne kilit-anahtar uyumuyla bağlandığı yanılgısı.\",\"ar\":\"الاعتقاد الخاطئ بأن جميع الأدوية تتطلب ارتباطاً نوعياً مع مستقبل بروتيني كالقفل والمفتاح.\",\"en\":\"The misconception that all pharmacological agents must bind stereoselective lock-and-key protein receptors.\"},{\"tr\":\"Farklı kimyasal yapılardaki genel anesteziklerin farklı hücresel etki mekanizmalarına sahip olduğu varsayımı.\",\"ar\":\"الافتراض الخاطئ بأن المخدرات العامة متباينة البنية الكيميائية تعمل بآليات خلوية مستقلة.\",\"en\":\"The assumption that chemically diverse general anesthetics operate via distinct cellular mechanisms.\"},{\"tr\":\"Homolog serilerde karbon zinciri uzadıkça aktivitenin sonsuza kadar artacağı yanılgısı.\",\"ar\":\"الاعتقاد الخاطئ بأن الفاعلية الحيوية في السلاسل المتماثلة تستمر بالزيادة إلى ما لا نهاية مع طول السلسلة.\",\"en\":\"The misconception that increasing alkyl chain length in a homologous series boosts potency indefinitely.\"}],\"sources\":[{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":17},{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":18},{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":19},{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":20},{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":23},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":10},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":13},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":24},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":25}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Foye's Principles of Medicinal Chemistry\",\"edition\":\"8th ed.\",\"topic\":\"Thermodynamic Activity & Ferguson Principle\"},{\"id\":\"cit-ref-02\",\"book\":\"Wilson and Gisvold's Textbook of Organic Medicinal and Pharmaceutical Chemistry\",\"edition\":\"12th ed.\",\"topic\":\"Physicochemical Properties and Drug Action\"},{\"id\":\"cit-ref-03\",\"book\":\"Burger's Medicinal Chemistry and Drug Discovery\",\"edition\":\"8th ed.\",\"topic\":\"Drug-Receptor Interactions and Non-specific Action\"}],\"spacedReviewCards\":[{\"cardId\":\"mc-mod1-les1-card1\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Ferguson Saturation Threshold\",\"prompt\":\"What relative biophasic saturation range (Pt / P0) characterizes structurally non-specific volatile anesthetics?\",\"answer\":\"A relative thermodynamic saturation of roughly 0.03 to 0.05 (or a few percent saturation) produces surgical anesthesia across non-specific agents.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod1-les1-card2\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Chemical Structure Alteration\",\"prompt\":\"How does minor chemical modification affect structurally specific versus structurally non-specific drugs?\",\"answer\":\"Specific drugs lose activity or convert to antagonists; non-specific drugs experience altered volatility or pharmacokinetics without mechanism change.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod1-les1-card3\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Solubility Cutoff Phenomenon\",\"prompt\":\"Why does biological activity plunge abruptly past a critical alkyl chain length in a homologous series?\",\"answer\":\"Hyper-lipophilic molecules cannot dissolve in polar intercellular fluid, preventing physical transport across the aqueous barrier to the biophase.\",\"box\":1,\"intervalDays\":1}],\"steps\":[{\"id\":\"mc-mod1-les1-step-01\",\"stage\":\"hook\",\"stageIndex\":1,\"title\":{\"tr\":\"Kasa Giriş: Gramlar ve Miligramlar Paradoksu\",\"ar\":\"مدخل سريري: مفارقة الغرامات والمليغرامات\",\"en\":\"Clinical Case: The Grams vs Milligrams Paradox\"},\"prompt\":{\"tr\":\"Dietil eter anestezisi onlarca gram gerektirirken, urasilin tek bir atomu değişerek üretilen 5-fluorourasil miligramlarla tümör hücresini öldürür. Bu devasa doz ve duyarlılık farkının kökeni nedir?\",\"ar\":\"يتطلب التخدير بالإيثر عشرات الغرامات، بينما يقتل 5-فلورويوراسيل الناتج عن استبدال ذرة واحدة في اليوراسيل الأورام بالمليغرامات. ما أصل هذا الفارق الهائل في الجرعة والحساسية؟\",\"en\":\"While ether anesthesia requires tens of grams, 5-fluorouracil kills tumor cells at milligram doses via a single atom substitution on uracil. What fundamentally explains this massive difference in dose and sensitivity?\"},\"predictThenReveal\":true,\"config\":{\"caseStudy\":\"Ether (non-specific, gram doses) vs 5-FU (specific, milligram doses)\",\"explanation\":{\"tr\":\"Spesifik ilaçlar hücredeki tek bir hedef enzimi veya reseptörü kilit-anahtar uyumuyla bloke ederken, genel anestezikler membran lipidlerini fiziksel olarak doyurmak zorundadır (Slayt 20, 23).\",\"ar\":\"تثبط الأدوية النوعية إنزيماً أو مستقبلاً وحيداً كالقفل والمفتاح، بينما تتطلب المخدرات العامة تشبيع دهون الغشاء فيزيائياً بجرعات ضخمة (شريحة 20، 23).\",\"en\":\"Structurally specific agents inhibit a single enzyme/receptor at micro-doses, whereas general anesthetics must physically saturate membrane lipids at gram scales.\"}},\"technicalTerms\":[{\"term\":\"yapı-spesifik mekanizma\",\"arContext\":\"آلية نوعية بنيوياً\"},{\"term\":\"yapı-nonspesifik mekanizma\",\"arContext\":\"آلية غير نوعية بنيوياً\"}],\"hints\":[{\"tr\":\"Hedefin tek bir protein cebi mi yoksa tüm hücre zarı mı olduğunu düşünün.\",\"ar\":\"فكر هل الهدف هو جيب بروتيني مفرد أم كامل الغشاء الخلوي.\",\"en\":\"Consider whether the target is a discrete protein pocket or the entire bulk cell membrane.\"},{\"tr\":\"Spesifik kilit-anahtar bağlanması ile fiziksel membran doygunluğu arasındaki farkı hatırlayın.\",\"ar\":\"تذكر الفرق بين الارتباط النوعي كالقفل والمفتاح والتشبع الغشائي الفيزيائي.\",\"en\":\"Recall the contrast between lock-and-key receptor binding and physical membrane saturation.\"},{\"tr\":\"Eter gram düzeyinde fiziksel membran doygunluğu yaparken, 5-FU miligramla enzimi bloke eder.\",\"ar\":\"يحدث الإيثر تشبيعاً فيزيائياً بالغرامات بينما يثبط 5-FU الإنزيم بالمليغرامات.\",\"en\":\"Ether requires grams to physically saturate membranes; 5-FU acts at milligrams by inhibiting thymidylate synthase.\"}],\"sources\":[{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":20},{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":23}]},{\"id\":\"mc-mod1-les1-step-02\",\"stage\":\"question\",\"stageIndex\":2,\"title\":{\"tr\":\"Tahmin: Kimyasal Çeşitlilik ve Ortak Anestezi\",\"ar\":\"تنبؤ: التنوع الكيميائي والتخدير المشترك\",\"en\":\"Prediction: Chemical Diversity and Shared Anesthesia\"},\"prompt\":{\"tr\":\"Kloroform (CHCl3), azot protoksit (N2O) ve dietil eter tamamen farklı kimyasal yapılara sahiptir. Farklı yapılardaki bu gazlar cerrahi anestezide nasıl ortak bir biyolojik etki oluşturabilir?\",\"ar\":\"يمتلك الكلوروفورم (CHCl3) وأكسيد النيتروز (N2O) وإيثر ثنائي الإيثيل بنى كيميائية شديدة التباين. كيف يمكن لهذه الغازات المختلفة إحداث نفس التخدير الجراحي؟\",\"en\":\"Chloroform (CHCl3), nitrous oxide (N2O), and diethyl ether have completely different chemical structures. How can such structurally diverse gases produce an identical surgical anesthetic state?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-2a\",\"text\":{\"tr\":\"Hepsi beyinde tek bir 'anestezi reseptörü' proteinine kovalent bağlarla bağlanır.\",\"ar\":\"ترتبط جميعها بروابط تساهمية مع مستقبل بروتيني مفرد للتخدير في الدماغ.\",\"en\":\"They all bind covalently to a single dedicated 'anesthesia receptor' protein in the brain.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: 'Tüm ilaçlar tek bir spesifik reseptöre bağlanır.' Yapı-nonspesifik gazlar kovalent bağ yapmaz ve ortak bir reseptör cebine ihtiyaç duymaz (Slayt 23).\",\"ar\":\"مغالطة: 'جميع الأدوية ترتبط بمستقبل مفرد'. الغازات غير النوعية لا تشكل روابط تساهمية ولا تتطلب جيب مستقبل مشترك (شريحة 23).\",\"en\":\"Misconception: 'All depressants bind one receptor.' Structurally non-specific volatile agents act without covalent binding to a shared receptor.\"}},{\"id\":\"opt-2b\",\"text\":{\"tr\":\"Kimyasal yapıdan bağımsız olarak, hücre membranında eşit bağıl doygunluk oluşturarak etki ederler.\",\"ar\":\"تؤثر عبر إحداث تشبع نسبي متساوٍ في الغشاء الخلوي، بمعزل عن بنيتها الكيميائية.\",\"en\":\"They act by achieving equivalent relative saturation in cell membranes, independent of chemical structure.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Ferguson ilkesine göre yapı-nonspesifik ilaçlar, zarda benzer termodinamik doygunluğa ulaştıklarında benzer etki gösterirler (Slayt 18, 23).\",\"ar\":\"صحيح! وفق مبدأ Ferguson، تحدث المواد غير النوعية بنيوياً نفس التأثير عند وصولها لنفس التشبع الثرموديناميكي الغشائي (شريحة 18، 23).\",\"en\":\"Correct! Ferguson's principle proves chemically diverse non-specific depressants produce identical depression at comparable thermodynamic biophasic saturation.\"}},{\"id\":\"opt-2c\",\"text\":{\"tr\":\"Kanda hızla parçalanıp aynı ortak aktif metabolite dönüşürler.\",\"ar\":\"تتفكك سريعاً في مجرى الدم متحولة إلى نفس المستقلب الفعال المشترك.\",\"en\":\"They undergo rapid enzymatic cleavage in blood into a single shared active metabolite.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: 'Uçucu gazlar ortak bir metabolite dönüşerek etki eder.' Uçucu anestezikler büyük oranda metabolize olmadan, akciğerlerden değişmeden atılırlar.\",\"ar\":\"مغالطة: 'تتحول المخدرات لمستقلب مشترك'. تُطرح المخدرات الاستنشاقية عبر الرئتين دون تغير بنيوي يذكر.\",\"en\":\"Misconception: 'Volatile agents act through common metabolites.' Inhalation anesthetics act physically and are eliminated largely unchanged via the lungs.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-2a\",\"text\":\"Hepsi beyinde tek bir anestezi reseptörüne kovalent bağlanır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yapı-nonspesifik gazlar ortak bir reseptör cebine bağlanmazlar.\"},{\"id\":\"opt-2b\",\"text\":\"Kimyasal yapıdan bağımsız olarak, hücre membranında eşit bağıl doygunluk oluştururlar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Ferguson ilkesine göre benzer termodinamik doygunluk benzer etki üretir.\"},{\"id\":\"opt-2c\",\"text\":\"Kanda parçalanıp aynı ortak aktif metabolite dönüşürler.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Uçucu anestezikler metabolize olmadan akciğerlerden değişmeden atılırlar.\"}],\"revealedOutcome\":{\"tr\":\"Farklı kimyasal yapılardaki gazlar, membran lipidlerinde eşit bağıl doygunluk (termodinamik aktivite) oluşturarak anestezi meydana getirir.\",\"ar\":\"تحدث الغازات المتباينة كيميائياً التخدير عبر توليد نفس التشبع النسبي (النشاط الثرموديناميكي) في دهون الأغشية.\",\"en\":\"Structurally diverse volatile agents induce anesthesia by establishing identical relative saturation in membrane lipids.\"},\"explanation\":{\"tr\":\"Ferguson'a göre aktiviteden endobiyofazdaki bağıl doygunluk derecesi sorumludur; kimyasal yapı değişken olsa da benzer etki görülür (Slayt 18, 23).\",\"ar\":\"وفق Ferguson، فإن درجة التشبع النسبي في الطور الحيوي الداخلي هي المسؤولة عن التأثير بمعزل عن الهيكل الكيميائي (شريحة 18، 23).\",\"en\":\"According to Ferguson, relative biophasic saturation dictates potency; diverse structures produce comparable depression at equal saturation.\"}},\"technicalTerms\":[{\"term\":\"termodinamik aktivite\",\"arContext\":\"النشاط الديناميكي الحراري\"},{\"term\":\"biyofaz\",\"arContext\":\"الطور الحيوي\"}],\"hints\":[{\"tr\":\"Bu gazların moleküler şekilleri birbirine benzer mi?\",\"ar\":\"هل تتشابه الأشكال الجزيئية لهذه الغازات؟\",\"en\":\"Do the molecular shapes of chloroform, nitrous oxide, and ether resemble each other?\"},{\"tr\":\"Şekiller tamamen farklıysa, ortak etki kimyasal kilide değil fiziksel faz dengesine dayanır.\",\"ar\":\"إذا كانت الأشكال شديدة التباين، فإن التأثير المشترك يعتمد على توازن الأطوار الفيزيائي.\",\"en\":\"If molecular shapes share no common template, action relies on physical phase partitioning.\"},{\"tr\":\"Ferguson prensibine göre kimyasal yapıdan bağımsız eşit bağıl doygunluk ortak etkiyi açıklar.\",\"ar\":\"وفق مبدأ Ferguson، يفسر تساوي التشبع النسبي التأثير المشترك بمعزل عن البنية.\",\"en\":\"Ferguson's principle demonstrates equal relative biophasic saturation produces equal depression.\"}],\"sources\":[{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":18},{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":23}]},{\"id\":\"mc-mod1-les1-step-03\",\"stage\":\"intuition\",\"stageIndex\":3,\"title\":{\"tr\":\"Fiziksel Sezgi: Dinamik Denge ve Kaçma Eğilimi\",\"ar\":\"حدس فيزيائي: التوازن الديناميكي وميل الهروب\",\"en\":\"Physical Intuition: Dynamic Equilibrium & Escaping Tendency\"},\"prompt\":{\"tr\":\"Ekzobiyofaz (kan/dış ortam) ile endobiyofaz (hücre membranı) arasında dinamik bir denge vardır. Molekülün sulu ortamdan kaçıp membran lipidlerine sığınma eğilimi termodinamik aktiviteyi belirler.\",\"ar\":\"ينشأ توازن ديناميكي بين الطور الخارجي (الدم) والطور الحيوي الداخلي (الغشاء). ميل الجزيء للهروب من الوسط المائي نحو دهون الغشاء يحدد النشاط الديناميكي الحراري.\",\"en\":\"A dynamic equilibrium exists between the exobiophase (blood/external medium) and endobiophase (cell membrane). A molecule's thermodynamic tendency to escape water into lipid bilayers dictates its activity.\"},\"predictThenReveal\":false,\"config\":{\"model\":\"PhaseEquilibriumEscapingTendency\",\"explanation\":{\"tr\":\"Molekülün sudan kaçma eğilimi, faz dengesinde zardaki kimyasal potansiyeli dış ortamdaki bağıl basınca (Pt / P0) eşitler (Slayt 18).\",\"ar\":\"ميل الجزيء للهروب من الماء يجعل الكمون الكيميائي في الغشاء مساوياً للضغط النسبي الخارجي (Pt / P0) عند التوازن (شريحة 18).\",\"en\":\"A molecule's aqueous escaping tendency equalizes its chemical potential in lipid membranes with external relative saturation (Pt / P0).\"}},\"technicalTerms\":[{\"term\":\"ekzobiyofaz\",\"arContext\":\"الطور الحيوي الخارجي\"},{\"term\":\"endobiyofaz\",\"arContext\":\"الطور الحيوي الداخلي\"},{\"term\":\"kaçma eğilimi\",\"arContext\":\"ميل الهروب الثرموديناميكي\"}],\"hints\":[{\"tr\":\"İki faz arasındaki dengeyi düşünün: moleküller sulu fazdan sürekli membran fazına geçer.\",\"ar\":\"فكر في التوازن بين طورين: تنتقل الجزيئات باستمرار من الطور المائي إلى الغشاء.\",\"en\":\"Consider partition equilibrium: molecules constantly exchange between aqueous and membrane phases.\"},{\"tr\":\"Denge kurulduğunda endobiyofazdaki kimyasal potansiyel ekzobiyofaza eşitlenir.\",\"ar\":\"عند التوازن يتساوى الكمون الكيميائي الداخلي مع الخارجي.\",\"en\":\"At dynamic equilibrium, chemical potential in the endobiophase equals that in the exobiophase.\"},{\"tr\":\"Bu eşitlik sayesinde doğrudan ölçülemeyen zardaki aktivite, dış ortamdaki Pt / P0 ile ölçülür.\",\"ar\":\"يتيح هذا التوازن قياس النشاط الغشائي الداخلي عبر قياس نسبة التشبع الخارجية Pt / P0.\",\"en\":\"This equilibrium allows unmeasurable membrane activity to be quantified by external Pt / P0.\"}],\"sources\":[{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":18}]},{\"id\":\"mc-mod1-les1-step-04\",\"stage\":\"visual_explanation\",\"stageIndex\":4,\"title\":{\"tr\":\"Görsel Karşılaştırma: Yapısal Hassasiyet vs Nonspesifiklik\",\"ar\":\"مقارنة بصرية: الحساسية البنيوية مقابل اللانوعية\",\"en\":\"Visual Comparison: Structural Sensitivity vs Non-specificity\"},\"prompt\":{\"tr\":\"Urasile tek flor eklenmesi (5-FU) veya tolbutamiddeki metilin klora dönmesi (klorpropamid) etkiyi radikal değiştirir. Anesteziklerde ise yapı değişimi etki tipini değil sadece uçuculuğu değiştirir.\",\"ar\":\"إضافة الفلور لليوراسيل (5-FU) أو استبدال الميثيل بالكلور في التولبوتاميد يغير التأثير جذرياً. أما في المخدرات، فتغير البنية يبدل التطاير فقط دون نوع التأثير.\",\"en\":\"Adding fluorine to uracil (5-FU) or replacing methyl with chlorine in tolbutamide radically alters activity. In volatile depressants, structural changes only shift volatility, not pharmacological effect.\"},\"predictThenReveal\":false,\"config\":{\"comparisonType\":\"SpecificVsNonSpecificStructuralSensitivity\",\"classicalModelFraming\":{\"tr\":\"Klasik modelde ketamin ve N2O genel anestezik membran teorisi içinde anılsa da, modern farmakolojide spesifik reseptör hedefleri (NMDA blokajı) tanımlanmıştır.\",\"ar\":\"على الرغم من إدراج الكيتامين و N2O في النموذج الكلاسيكي ضمن نظرية التخدير الغشائي، إلا أن علم الأدوية الحديث حدد لهما أهدافاً جزيئية نوعية (تثبيط مستقبلات NMDA).\",\"en\":\"While classical models grouped ketamine and N2O under non-specific membrane anesthesia, modern pharmacology identifies specific molecular receptor targets (NMDA antagonism).\"},\"explanation\":{\"tr\":\"Klasik modelde ketamin ve N2O genel anestezik membran teorisi içinde anılsa da, modern farmakolojide spesifik reseptör hedefleri (NMDA blokajı) tanımlanmıştır (Slayt 20-23).\",\"ar\":\"على الرغم من إدراج الكيتامين و N2O في النموذج الكلاسيكي ضمن نظرية التخدير الغشائي، إلا أن علم الأدوية الحديث حدد لهما أهدافاً جزيئية نوعية (تثبيط مستقبلات NMDA) (شريحة 20-23).\",\"en\":\"While classical models grouped ketamine and N2O under non-specific membrane anesthesia, modern pharmacology identifies specific molecular receptor targets (NMDA antagonism).\"}},\"technicalTerms\":[{\"term\":\"antimetabolit\",\"arContext\":\"مضاد استقلاب\"},{\"term\":\"yapısal duyarlılık\",\"arContext\":\"الحساسية البنيوية\"}],\"hints\":[{\"tr\":\"Urasil ile 5-fluorourasil arasındaki tek atomluk farkı inceleyin.\",\"ar\":\"تأمل الفارق في ذرة واحدة بين اليوراسيل و 5-فلورويوراسيل.\",\"en\":\"Examine the single-atom substitution between uracil and 5-fluorouracil.\"},{\"tr\":\"Spesifik ilaçlarda tek bir atom değişimi ilacı antimetabolite veya antagoniste çevirir.\",\"ar\":\"في الأدوية النوعية، يحول تغير ذرة واحدة الدواء إلى مضاد استقلاب أو مضاد تنافسي.\",\"en\":\"In specific agents, a single atom modification converts a metabolite into an antagonist.\"},{\"tr\":\"Nonspesifik anesteziklerde ise moleküler yapı tamamen değişse bile genel anestezi korunur.\",\"ar\":\"في المخدرات غير النوعية، يستمر التخدير العام حتى مع التغير الجذري في البنية.\",\"en\":\"In non-specific anesthetics, CNS depression persists despite radical architectural divergences.\"}],\"sources\":[{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":20},{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":21},{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":22},{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":23}]},{\"id\":\"mc-mod1-les1-step-05\",\"stage\":\"interactive_artifact\",\"stageIndex\":5,\"title\":{\"tr\":\"İnteraktif Simülatör: Bağıl Doygunluk ve Biyofaz\",\"ar\":\"محاكاة تفاعلية: التشبع النسبي والطور الحيوي\",\"en\":\"Interactive Simulator: Relative Saturation & Biophase\"},\"prompt\":{\"tr\":\"Simülatörde kısmi basınç oranını (Pt / P0) değiştirin. Doygun buhar basıncının yüzde birkaçı düzeyinde zardaki termodinamik kaçma eğiliminin genel anestezi eşiğine nasıl ulaştığını gözlemleyin.\",\"ar\":\"غير نسبة الضغط الجزئي (Pt / P0) في المحاكي. راقب كيف يصل ميل الهروب الثرموديناميكي في الغشاء إلى عتبة التخدير الجراحي عند نسبة مئوية ضئيلة من التشبع.\",\"en\":\"Adjust the partial pressure ratio (Pt / P0) in the simulator. Observe how thermodynamic escaping tendency into the membrane achieves the surgical anesthesia threshold at a few percent saturation.\"},\"predictThenReveal\":false,\"widgetType\":\"ThermodynamicActivityFergusonSlider\",\"widget\":{\"type\":\"ThermodynamicActivityFergusonSlider\",\"config\":{\"defaultPtP0\":0.03,\"anesthesiaThresholdRange\":[0.03,0.05],\"teaches\":{\"tr\":\"Uçucu anestezikler doymuş buhar basınçlarının yüzde birkaçında cerrahi anestezi oluşturur.\",\"ar\":\"تحدث المخدرات الاستنشاقية تخديراً جراحياً عند نسبة مئوية ضئيلة من ضغط بخارها المشبع.\",\"en\":\"Volatile anesthetics produce surgical anesthesia at a few percent of their saturation pressure.\"}}},\"config\":{\"defaultPtP0\":0.03,\"explanation\":{\"tr\":\"Termodinamik aktivite a = Pt / P0 dır. Bağıl doygunluk yükseldikçe moleküller zarda toplanır ve membran fonksiyonunu bozar (Slayt 18).\",\"ar\":\"النشاط الثرموديناميكي a = Pt / P0. مع ارتفاع التشبع النسبي تتكدس الجزيئات في الغشاء وتثبط وظيفته (شريحة 18).\",\"en\":\"Thermodynamic activity a = Pt / P0. As relative saturation rises, molecules partition into lipid bilayers, impairing membrane dynamics.\"}},\"technicalTerms\":[{\"term\":\"bağıl doygunluk\",\"arContext\":\"التشبع النسبي\"},{\"term\":\"termodinamik kaçma eğilimi\",\"arContext\":\"ميل الهروب الثرموديناميكي\"}],\"hints\":[{\"tr\":\"Kaydırıcıyı hareket ettirerek Pt / P0 oranını artırın.\",\"ar\":\"حرك شريط التمرير لزيادة نسبة Pt / P0.\",\"en\":\"Drag the slider to increase the Pt / P0 ratio.\"},{\"tr\":\"Yüzde birkaç doygunluk oranına ulaşıldığında anestezi eşiği aşılır.\",\"ar\":\"عند بلوغ نسبة مئوية ضئيلة من التشبع يتم تجاوز عتبة التخدير.\",\"en\":\"Surgical anesthesia threshold is crossed at a few percent biophasic saturation.\"},{\"tr\":\"Uçucu anestezikler için termodinamik aktivite bağıl buhar basıncı ile ölçülür.\",\"ar\":\"يقاس النشاط الديناميكي للغازات المتطايرة عبر ضغط البخار النسبي.\",\"en\":\"For volatile agents, thermodynamic activity is directly measured as relative vapor pressure.\"}],\"sources\":[{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":18}]},{\"id\":\"mc-mod1-les1-step-06\",\"stage\":\"guided_discovery\",\"stageIndex\":6,\"title\":{\"tr\":\"Rehberli Keşif: Mutlak Doz vs Bağıl Doygunluk\",\"ar\":\"استكشاف موجه: الجرعة المطلقة مقابل التشبع النسبي\",\"en\":\"Guided Discovery: Absolute Dose vs Relative Saturation\"},\"prompt\":{\"tr\":\"İki uçucu anestezikten birinin kanda oluşturduğu kısmi basınç diğerinden kat kat yüksektir; ancak her ikisi de kendi doymuş buhar basınçlarının eşit bir kesrinde (aynı Pt / P0 oranında) anestezi yapar. Termodinamik güçleri nasıldır?\",\"ar\":\"يحدث مخدر استنشاقي تخديراً عند ضغط جزئي أعلى بأضعاف من مخدر آخر، لكن كلاهما يحقق التخدير عند نفس الكسر من ضغط بخاره المشبع (نفس نسبة Pt / P0). كيف تُقارن قوتهما الثرموديناميكية؟\",\"en\":\"One volatile anesthetic requires a much higher partial pressure in blood than another, yet both produce anesthesia at the exact same fraction of their saturation vapor pressure (identical Pt / P0). How do their thermodynamic potencies compare?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-6a\",\"text\":{\"tr\":\"Termodinamik olarak eşit güçtedirler; çünkü her ikisi de aynı bağıl doygunluk kesrinde aynı biyofazik depresyonu oluşturur.\",\"ar\":\"متساويان في القوة الثرموديناميكية؛ كلاهما أحدث نفس التثبيط الحيوي عند نفس كسر التشبع النسبي.\",\"en\":\"They possess equal thermodynamic potency; both produce equal depression at the exact same relative saturation fraction.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Ferguson ilkesine göre yapı-nonspesifik etki bağıl doygunluk kesrine bağlıdır; oranlar eşitse termodinamik etki güçleri eşittir (Slayt 18).\",\"ar\":\"صحيح! وفق مبدأ Ferguson، يعتمد التأثير غير النوعي على نسبة التشبع، وتساوي النسبة يعني تماثل القوة الثرموديناميكية (شريحة 18).\",\"en\":\"Correct! Ferguson's principle proves non-specific depression is governed by relative saturation; equal saturation means equal thermodynamic potency.\"}},{\"id\":\"opt-6b\",\"text\":{\"tr\":\"Daha düşük kısmi basınç gerektiren ajan kat kat daha güçlüdür çünkü daha az molekülle aynı klinik anesteziyi sağlamıştır.\",\"ar\":\"المخدر الذي تطلب ضغطاً أقل أقوى بأضعاف لأنه حقق نفس النتيجة السريرية بجزيئات أقل.\",\"en\":\"The agent requiring lower partial pressure is far more potent because it achieved anesthesia with fewer molecules.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: 'Düşük mutlak doz yüksek termodinamik güç demektir.' Yapı-nonspesifik gazlarda mutlak doz buharlaşma kolaylığını yansıtır; termodinamik güçleri eşittir.\",\"ar\":\"مغالطة: 'الجرعة المطلقة الأقل تعني قوة حيوية أعلى'. في الغازات غير النوعية، الجرعة تعكس التطاير فقط بينما الفعالية الثرموديناميكية متماثلة.\",\"en\":\"Misconception: 'Lower absolute dose signifies superior intrinsic potency.' In non-specific depressants, absolute concentration reflects volatility, not receptor affinity.\"}},{\"id\":\"opt-6c\",\"text\":{\"tr\":\"Daha yüksek kısmi basınç gerektiren ajan daha güçlüdür çünkü zarda daha fazla molekül biriktirerek felç yapar.\",\"ar\":\"المخدر الذي تطلب ضغطاً أعلى أقوى لأنه يكدس جزيئات أكثر داخل الغشاء مسبباً شللاً حيوياً أعمق.\",\"en\":\"The agent requiring higher partial pressure is more potent because more molecules accumulate to produce neural paralysis.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: 'Daha yüksek miligram sayısı daha güçlü etki yapar.' Bağıl doygunluk eşit olduğunda zardaki termodinamik aktivite aynıdır.\",\"ar\":\"مغالطة: 'الكمية الأكبر تعني تأثيراً أقوى'. عند تساوي التشبع النسبي، يتساوى النشاط الثرموديناميكي في الغشاء تماماً.\",\"en\":\"Misconception: 'Higher molar quantity implies superior potency.' Thermodynamic activity in the membrane is identical at equal saturation.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-6a\",\"text\":\"Termodinamik olarak eşit güçtedirler; aynı bağıl doygunlukta aynı etkiyi verirler.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Ferguson ilkesine göre bağıl doygunluk eşitse etki güçleri eşittir.\"},{\"id\":\"opt-6b\",\"text\":\"Düşük kısmi basınç gerektiren ajan kat kat daha güçlüdür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Mutlak dozdaki fark buharlaşma kolaylığını yansıtır, intrensek gücü değil.\"},{\"id\":\"opt-6c\",\"text\":\"Yüksek kısmi basınç gerektiren ajan daha güçlüdür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Bağıl doygunluk eşitse zardaki termodinamik aktivite aynıdır.\"}],\"revealedOutcome\":{\"tr\":\"Mutlak basınçları farklı olsa da eşit bağıl doygunluk kesrinde etki eden anesteziklerin termodinamik güçleri eşittir.\",\"ar\":\"رغم اختلاف ضغطهما المطلق، فإن المخدرين اللذين يؤثران عند نفس التشبع النسبي يمتلكان قوة ثرموديناميكية متساوية.\",\"en\":\"Despite differing absolute pressures, volatile anesthetics acting at identical relative saturation share equal thermodynamic potency.\"},\"explanation\":{\"tr\":\"Mutlak dozdaki fark maddelerin doymuş buhar basınçlarından (P0) kaynaklanır; bağıl doygunluk (Pt / P0) eşitse termodinamik etki aynıdır (Slayt 18).\",\"ar\":\"الفارق في الجرعة المطلقة ناتج عن تباين ضغط البخار المشبع (P0)؛ وعند تساوي نسبة التشبع (Pt / P0) يتطابق الأثر الثرموديناميكي (شريحة 18).\",\"en\":\"Absolute dose differences reflect pure saturation vapor pressures (P0); at equal relative saturation (Pt / P0), thermodynamic depression is identical.\"}},\"technicalTerms\":[{\"term\":\"mutlak doz\",\"arContext\":\"الجرعة المطلقة\"},{\"term\":\"termodinamik güç\",\"arContext\":\"القوة الثرموديناميكية\"}],\"hints\":[{\"tr\":\"Ferguson eşitliğine bakın: a = Pt / P0.\",\"ar\":\"انظر لمعادلة Ferguson: a = Pt / P0.\",\"en\":\"Look at the Ferguson equation: a = Pt / P0.\"},{\"tr\":\"Her iki ajan da doymuş buhar basıncının aynı kesrinde etki göstermiştir.\",\"ar\":\"أحدث كلا المخدرين تأثيراً عند نفس الكسر من ضغط بخارهما المشبع.\",\"en\":\"Both anesthetics produced surgical depression at the identical saturation fraction.\"},{\"tr\":\"Biyofazdaki kaçma eğilimi mutlak basınca değil, bu bağıl orana bağlıdır.\",\"ar\":\"ميل الهروب في الطور الحيوي محكوم بالنسبة النسبية وليس بالضغط المطلق.\",\"en\":\"Escaping tendency into the biophase is determined by relative saturation, not absolute pressure.\"}],\"sources\":[{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":18},{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":23}]},{\"id\":\"mc-mod1-les1-step-07\",\"stage\":\"formal_explanation\",\"stageIndex\":7,\"title\":{\"tr\":\"Çözünürlük Sınırı ve Kesilme (Cutoff) Olayı\",\"ar\":\"حد الذوبانية وظاهرة الانقطاع (Cutoff)\",\"en\":\"Solubility Limit & The Cutoff Phenomenon\"},\"prompt\":{\"tr\":\"Homolog serilerde karbon zinciri uzadıkça yağda çözünürlük ve etki önce artar. Ancak belli bir tepe noktadan sonra zincir uzatılınca biyolojik aktivite neden aniden düşer veya tamamen yok olur?\",\"ar\":\"في السلاسل المتماثلة تزداد الذوبانية الدهنية والفاعلية أولاً مع طول السلسلة. لكن بعد ذروة معينة، إذا أطلنا السلسلة، لماذا تهبط الفاعلية الحيوية فجأة أو تنعدم تماماً؟\",\"en\":\"In homologous series, lipid solubility and activity initially rise as the carbon chain elongates. However, past a peak threshold, why does further elongation cause biological activity to plunge or vanish?\"},\"predictThenReveal\":false,\"config\":{\"mechanism\":\"HomologousSeriesCutoff\",\"polarBarrier\":\"intercellular_fluid\",\"explanation\":{\"tr\":\"Homolog serilerde aktivitenin bir maksimumdan sonra hızla düşmesi, hücreler arası sıvının polar karakterde olmasıyla açıklanır (Çözünürlük Slayt 10, 13).\",\"ar\":\"يفسر هبوط الفعالية بعد الذروة في السلاسل المتماثلة بكون السوائل بين الخلوية ذات طبيعة قطبية مائية تعجز الجزيئات الشحمية عن عبورها (شريحة 10، 13).\",\"en\":\"The post-peak activity plunge in homologous series occurs because intercellular fluid is polar, preventing hyper-lipophilic molecules from reaching biophasic sites.\"}},\"technicalTerms\":[{\"term\":\"homolog seri\",\"arContext\":\"سلسلة متماثلة\"},{\"term\":\"kesilme noktası (cutoff)\",\"arContext\":\"نقطة الانقطاع الفاعلي\"}],\"hints\":[{\"tr\":\"Hücreler arasındaki sıvının polar karakterde olduğunu hatırlayın (Slayt 13).\",\"ar\":\"تذكر أن السائل بين الخلوي ذو طبيعة قطبية مائية (شريحة 13).\",\"en\":\"Recall that intercellular fluids possess a polar aqueous character (Slide 13).\"},{\"tr\":\"Aşırı yağseven uzun zincirli moleküller bu sulu sıvıda çözünemez hale gelir.\",\"ar\":\"الجزيئات مفرطة الشحمية طويلة السلسلة تفقد قدرتها تماماً على الذوبان في هذا السائل المائي.\",\"en\":\"Hyper-lipophilic long-chain molecules cannot dissolve in this aqueous intercellular fluid.\"},{\"tr\":\"Çözünemeyen ilaç hedef hücre zarlarına taşınamaz ve etki aniden kaybolur.\",\"ar\":\"الدواء العاجز عن الذوبان لا يمكن نقله للأغشية المستهدفة فيختفي التأثير فجأة.\",\"en\":\"Undissolved drug cannot be transported to target membranes, causing activity to abruptly terminate.\"}],\"sources\":[{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":10},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":13}]},{\"id\":\"mc-mod1-les1-step-08\",\"stage\":\"concept_check\",\"stageIndex\":8,\"title\":{\"tr\":\"Kavram Kontrolü: Özgüllük Sınıflandırması\",\"ar\":\"اختبار مفهوم: تصنيف النوعية\",\"en\":\"Concept Check: Specificity Classification\"},\"prompt\":{\"tr\":\"Aşağıdaki klinik senaryolardan hangisi bir ilacın 'yapı-nonspesifik' (yapı-özgül olmayan) mekanizmayla etki ettiğini kesin olarak kanıtlar?\",\"ar\":\"أي من السيناريوهات السريرية التالية يثبت بشكل قاطع أن الدواء يعمل بآلية 'غير نوعية بنيوياً'؟\",\"en\":\"Which clinical scenario definitively proves that a drug operates through a 'structurally non-specific' mechanism?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-8a\",\"text\":{\"tr\":\"İlacın tek bir amino asit mutasyonu taşıyan hücrelerde tüm etkisini tamamen kaybetmesi.\",\"ar\":\"فقدان الدواء لفاعليته كلياً في الخلايا التي تحمل طفرة في حمض أميني واحد.\",\"en\":\"The drug completely losing its activity in cells harboring a single amino acid point mutation.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Tek bir nokta mutasyonla etki kaybı, hedefin stereoselektif kilit-anahtar reseptörü olduğunu (yapı-spesifik) gösterir (Slayt 20).\",\"ar\":\"مغالطة: فقدان التأثير بطفرة نقطية يثبت الارتباط بمستقبل نوعي فراغي كالقفل والمفتاح (دواء نوعي) (شريحة 20).\",\"en\":\"Misconception: Sensitivity to point mutations denotes a stereoselective lock-and-key receptor (structurally specific drug).\"}},{\"id\":\"opt-8b\",\"text\":{\"tr\":\"Molekülün saf bir enantiyomerinin rasemik karışımdan yüz kat daha güçlü etki etmesi.\",\"ar\":\"إظهار متخايل فراغي نقي فاعلية تفوق الخليط الراسيمي بمئة ضعف.\",\"en\":\"A pure enantiomer displaying 100-fold higher biological potency than the racemic mixture.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Enantiyomer seçiciliği, ilacın kiral bir reseptör cebine bağlandığını (yapı-spesifik mekanizma) kanıtlar.\",\"ar\":\"مغالطة: الانتقائية الفراغية للمتخايلات تثبت الارتباط بجيب مستقبل كيرالي نوعي.\",\"en\":\"Misconception: Enantiomeric selectivity proves stereochemical fit within a chiral receptor binding pocket.\"}},{\"id\":\"opt-8c\",\"text\":{\"tr\":\"Tamamen farklı kimyasal yapıdaki bileşiklerle birlikte, zardaki benzer bağıl doygunlukta aynı depresif etkiyi göstermesi.\",\"ar\":\"إحداث نفس الأثر التثبيطي عند تساوي التشبع النسبي في الغشاء بالتشارك مع مركبات مختلفة البنية كلياً.\",\"en\":\"Displaying identical depressive action alongside chemically unrelated compounds at comparable relative biophasic saturation.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Kimyasal yapıdan bağımsız olarak eşit bağıl doygunlukta görülen etki, yapı-nonspesifik etki mekanizmasının tanımıdır (Slayt 18, 23).\",\"ar\":\"صحيح! التأثير المشترك عند تساوي التشبع النسبي بمعزل عن البنية الكيميائية هو المعيار الحاسم للأدوية غير النوعية (شريحة 18، 23).\",\"en\":\"Correct! Similar biological depression at equal relative biophasic saturation independent of chemical structure defines non-specific action.\"}},{\"id\":\"opt-8d\",\"text\":{\"tr\":\"İlacın monoklonal antikor ile nötralize edildiğinde etkisinin derhal tamamen durması.\",\"ar\":\"توقف مفعول الدواء كلياً فور معادلته بواسطة جسم مضاد وحيد النسيلة.\",\"en\":\"The drug's pharmacological effect being immediately halted upon neutralization by a monoclonal antibody.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Antikorla nötralizasyon spesifik bir hedefin varlığını gösterir, nonspesifik membran depresyonunu değil.\",\"ar\":\"مغالطة: التعادل بالأضداد يتطلب استهدافاً نوعياً لجزيء مفرد ولا ينطبق على التثبيط الغشائي العام.\",\"en\":\"Misconception: Monoclonal antibody neutralization signifies specific molecular targeting, not non-specific membrane effects.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-8a\",\"text\":\"Tek bir amino asit mutasyonu taşıyan hücrelerde tüm etkisini kaybetmesi.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Nokta mutasyon duyarlılığı yapı-spesifik reseptör bağlanmasını gösterir.\"},{\"id\":\"opt-8b\",\"text\":\"Saf enantiyomerinin rasemik karışımdan 100 kat güçlü olması.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Enantiyomer seçiciliği kiral reseptör etkileşimini kanıtlar.\"},{\"id\":\"opt-8c\",\"text\":\"Farklı kimyasal yapıdaki bileşiklerle benzer bağıl doygunlukta aynı etkiyi vermesi.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Kimyasal yapıdan bağımsız eşit bağıl doygunluk nonspesifik mekanizmayı tanımlar.\"},{\"id\":\"opt-8d\",\"text\":\"Monoklonal antikorla nötralize edildiğinde etkisinin durması.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Antikorla nötralizasyon spesifik hedef varlığını gösterir.\"}],\"revealedOutcome\":{\"tr\":\"Kimyasal yapıdan bağımsız olarak eşit bağıl doygunlukta görülen etki, yapı-nonspesifik etki mekanizmasını tanımlar.\",\"ar\":\"التأثير المشترك عند تساوي التشبع النسبي بمعزل عن البنية هو المعيار الحاسم للأدوية غير النوعية.\",\"en\":\"Similar depression at equal relative saturation independent of structure defines non-specific action.\"},\"explanation\":{\"tr\":\"Ferguson prensibine göre yapı-nonspesifik ilaçlar stereokimyasal reseptörlere değil, biyofazdaki termodinamik aktiviteye dayanır (Slayt 18, 23).\",\"ar\":\"وفق Ferguson، تعتمد الأدوية غير النوعية على النشاط الثرموديناميكي في الطور الحيوي وليس على المستقبلات الفراغية (شريحة 18، 23).\",\"en\":\"Ferguson demonstrated non-specific action depends on thermodynamic biophasic saturation rather than receptor stereochemistry.\"}},\"technicalTerms\":[{\"term\":\"yapı-nonspesifik mekanizma\",\"arContext\":\"آلية غير نوعية بنيوياً\"},{\"term\":\"enantiyomer seçiciliği\",\"arContext\":\"انتقائية المتخايلات الفراغية\"}],\"hints\":[{\"tr\":\"Spesifik reseptör bağlanması ile fiziksel membran doygunluğu arasındaki farkı hatırlayın.\",\"ar\":\"تذكر الفارق الجوهري بين الارتباط بمستقبل نوعي والتشبع الفيزيائي للغشاء.\",\"en\":\"Recall the fundamental distinction between specific receptor binding and physical membrane saturation.\"},{\"tr\":\"Nonspesifik etkide kimyasal yapının ne olduğu değil, doymuşluk kesri önemlidir.\",\"ar\":\"في التأثير غير النوعي، المعيار هو نسبة التشبع وليس نوع البنية الكيميائية.\",\"en\":\"In non-specific depression, the saturation fraction governs rather than chemical identity.\"},{\"tr\":\"Farklı yapıdaki gazların aynı bağıl doygunlukta anestezi yapması Ferguson un ana kuralıdır.\",\"ar\":\"إحداث غازات متباينة التخدير عند نفس التشبع النسبي هو القاعدة المركزية لـ Ferguson.\",\"en\":\"Diverse gases inducing depression at equivalent saturation is Ferguson's definitive hallmark.\"}],\"sources\":[{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":18},{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":23}]},{\"id\":\"mc-mod1-les1-step-09\",\"stage\":\"application\",\"stageIndex\":9,\"title\":{\"tr\":\"Uygulama: Tiyopental ve Yeniden Dağılım Kinetiği\",\"ar\":\"تطبيق سريري: الثيوبنتال وحركية إعادة التوزع\",\"en\":\"Application: Thiopental & Redistribution Kinetics\"},\"prompt\":{\"tr\":\"Tiyopental pentobarbitalden çok daha lipofiliktir ve beyne hızla geçer. Ancak hastada anestezi etkisi dakikalar içinde aniden sonlanır. Bu kısa etkinin gerçek mekanizması nedir?\",\"ar\":\"الثيوبنتال أكثر شحمية بكثير من البنتوباربيتال ويعبر الدماغ فوراً. ومع ذلك يزول تأثيره التخديري في دقائق معدودة. ما هي الآلية الحقيقية لهذا التأثير القصير؟\",\"en\":\"Thiopental is far more lipophilic than pentobarbital and crosses the BBB immediately. Yet surgical anesthesia terminates within minutes. What is the true mechanism of this ultrashort action?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-9a\",\"text\":{\"tr\":\"Beyin parankiminde bulunan spesifik enzimler tarafından saniyeler içinde hızla parçalanır.\",\"ar\":\"يتفكك سريعاً في ثوانٍ بواسطة إنزيمات نوعية داخل النسيج الدماغي.\",\"en\":\"It is degraded within seconds by specific metabolic enzymes located inside brain parenchyma.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Tiyopental beyinde hızla yıkılmaz; karaciğerde yavaş metabolize olur. Etkinin bitişi metabolizmaya değil doku dağılımına bağlıdır.\",\"ar\":\"مغالطة: لا يُخرب الثيوبنتال سريعاً في الدماغ بل يستقلب ببطء كبدياً؛ وزوال الأثر سببه إعادة التوزع النسيجي.\",\"en\":\"Misconception: Thiopental is not rapidly cleaved in brain tissue; hepatic metabolism is slow and does not terminate initial anesthesia.\"}},{\"id\":\"opt-9b\",\"text\":{\"tr\":\"Beyinden hızla çıkıp önce iyi kanlanan kas ve iç organlara, ardından yağ dokusuna yeniden dağılır.\",\"ar\":\"يغادر الدماغ بسرعة ويعاد توزعه أولاً إلى العضلات والأحشاء ثم لاحقاً إلى النسيج الدهني.\",\"en\":\"It exits the brain rapidly, redistributing first to well-perfused lean tissues and muscle, and later to fat depots.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Tiyopentalin plazma ve beyin konsantrasyonu hızla düşer; çünkü ilaç hızla kas ve iç organlara, ardından yağ dokusuna yeniden dağılır (Slayt 25).\",\"ar\":\"صحيح! تهبط مستويات الثيوبنتال الدماغية والدموية سريعاً بسبب إعادة توزعه إلى العضلات والأحشاء ثم تراكمه في النسيج الدهني (شريحة 25).\",\"en\":\"Correct! Blood and brain levels plunge because thiopental promptly redistributes into well-perfused muscle and viscera, then sequesters into fat depots.\"}},{\"id\":\"opt-9c\",\"text\":{\"tr\":\"Yüksek lipofilitesi nedeniyle böbreklerden idrarla değişmeden derhal atılır.\",\"ar\":\"يُطرح كلوياً فوراً مع البول دون تغير نظراً لشحميته الفائقة.\",\"en\":\"Due to high lipophilicity, it undergoes immediate and unchanged filtration via the kidneys.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Lipofilik moleküller böbrek tübüllerinden geri emilir, doğrudan atılamaz (Slayt 24).\",\"ar\":\"مغالطة: يُعاد امتصاص الجزيئات الشحمية من الأنابيب الكلوية ولا يمكن طرحها مباشرة دون استقلاب (شريحة 24).\",\"en\":\"Misconception: Lipophilic compounds undergo tubular reabsorption and cannot clear directly via urine without prior metabolism.\"}},{\"id\":\"opt-9d\",\"text\":{\"tr\":\"GABA reseptörlerinden kovalent olarak kopup bir daha bağlanamaz.\",\"ar\":\"ينفصل تساهمياً عن مستقبلات GABA ويعجز عن الارتباط مجدداً.\",\"en\":\"It detaches irreversibly from GABA receptors and cannot re-engage binding pockets.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Barbitüratlar kovalent bağ yapmazlar; etki sonlanması reseptör kopmasından değil doku kaçışından kaynaklanır.\",\"ar\":\"مغالطة: لا تشكل الباربيتورات روابط تساهمية؛ وزوال الأثر ناجم عن هروب الجزيئات نسيجياً.\",\"en\":\"Misconception: Barbiturates do not bind covalently; termination reflects pharmacokinetic tissue redistribution.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-9a\",\"text\":\"Beyin parankiminde bulunan spesifik enzimlerce saniyeler içinde parçalanır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Tiyopental beyinde hızla yıkılmaz; karaciğerde yavaş metabolize olur.\"},{\"id\":\"opt-9b\",\"text\":\"Beyinden çıkıp önce kas ve iç organlara, ardından yağ dokusuna yeniden dağılır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Plazma ve beyin konsantrasyonu yeniden dağılım nedeniyle hızla düşer.\"},{\"id\":\"opt-9c\",\"text\":\"Yüksek lipofilitesi nedeniyle böbreklerden idrarla derhal atılır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Lipofilik moleküller böbrek tübüllerinden geri emilir.\"},{\"id\":\"opt-9d\",\"text\":\"GABA reseptörlerinden kovalent olarak kopup bir daha bağlanamaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Barbitüratlar kovalent bağ yapmazlar.\"}],\"revealedOutcome\":{\"tr\":\"Tiyopentalin plazma ve beyin düzeyi hızla düşer; çünkü ilaç önce iyi kanlanan kas ve iç organlara, ardından yağ dokusuna yeniden dağılır.\",\"ar\":\"تهبط مستويات الثيوبنتال الدماغية سريعاً بسبب إعادة توزعه إلى العضلات والأحشاء ثم تراكمه البطيء في النسيج الدهني.\",\"en\":\"Thiopental brain concentrations fall rapidly due to redistribution into well-perfused lean tissues and subsequent slow accumulation in adipose tissue.\"},\"explanation\":{\"tr\":\"Partisyon katsayısı yüksek olan tiyopental beyne hızla geçer, ancak plazma ve beyin seviyesi yeniden dağılım ile dakikalar içinde düşer (Slayt 24, 25).\",\"ar\":\"يعبر الثيوبنتال عالي الشحمية الدماغ فوراً، لكن مستوياته تهبط سريعاً نتيجة إعادة التوزع إلى العضلات والدهون (شريحة 24، 25).\",\"en\":\"Highly lipophilic thiopental penetrates the BBB instantly, but tissue redistribution rapidly terminates central anesthesia.\"}},\"technicalTerms\":[{\"term\":\"yeniden dağılım (redistribüsyon)\",\"arContext\":\"إعادة التوزع النسيجي\"},{\"term\":\"partisyon katsayısı\",\"arContext\":\"معامل التوزع\"}],\"hints\":[{\"tr\":\"Tiyopentalin vücutta kan akımı yüksek ve düşük dokular arasındaki geçişini düşünün.\",\"ar\":\"فكر في انتقال الثيوبنتال بين الأنسجة عالية التروية والأنسجة منخفضة التروية.\",\"en\":\"Consider thiopental shifting from highly perfused organs to poorly perfused tissues.\"},{\"tr\":\"İlaç beyinden hızla ayrılıp kas, iç organlar ve yağ dokusuna transfer olur.\",\"ar\":\"يغادر الدواء الدماغ بسرعة منتقلاً نحو العضلات والأحشاء والدهون.\",\"en\":\"The drug quickly departs brain tissue, equilibrating into muscle, viscera, and fat.\"},{\"tr\":\"Bu süreç metabolizma değil, fizikokimyasal bir yeniden dağılım olayıdır.\",\"ar\":\"هذه العملية ليست استقلاباً بل إعادة توزع فيزيوكيميائية سريعة.\",\"en\":\"This mechanism represents physical pharmacokinetic redistribution rather than hepatic clearance.\"}],\"sources\":[{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":24},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":25}]},{\"id\":\"mc-mod1-les1-step-10\",\"stage\":\"retrieval\",\"stageIndex\":10,\"title\":{\"tr\":\"Geri Çağırma: Yapı-Spesifik İlacın Temel Kriteri\",\"ar\":\"استرجاع: المعيار الجوهري للأدوية النوعية\",\"en\":\"Retrieval: Core Criterion for Structurally Specific Drugs\"},\"prompt\":{\"tr\":\"Aşağıdaki özelliklerden hangisi bir ilacın 'yapı-spesifik' (yapı-özgül) etki mekanizmasına sahip olduğunu gösteren en temel kriterdir?\",\"ar\":\"أي من الخصائص التالية تمثل المعيار الأساسي الدال على أن الدواء يعمل بآلية 'نوعية بنيوياً'؟\",\"en\":\"Which of the following characteristics represents the core defining criterion of a 'structurally specific' drug?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-10a\",\"text\":{\"tr\":\"Temel bir yapı taşıması, yapısındaki küçük değişikliklerin etkiyi tamamen yok edebilmesi veya tersine çevirebilmesi.\",\"ar\":\"امتلاك هيكل أساسي يؤدي أي تعديل طفيف فيه إلى زوال التأثير كلياً أو قلبه إلى تأثير مضاد.\",\"en\":\"Possessing a fundamental pharmacophore where minor structural modifications abolish or invert activity.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Slayt 20: 'Yapı Spesifik İlaçlar: Temel bir yapı taşırlar. Yapıdaki küçük değişiklikler aktiviteyi tamamen ortadan kaldırabilir yada tersi aktiviteye neden olabilir.'\",\"ar\":\"صحيح! شريحة 20: 'الأدوية النوعية بنيوياً تمتلك هيكلاً أساسياً، والتعديلات الطفيفة قد تلغي التأثير تماماً أو تسبب تأثيراً مضاداً'.\",\"en\":\"Correct! Slide 20: 'Structurally Specific Drugs: Possess a core structure. Minor structural alterations can completely abolish activity or trigger antagonist effects.'\"}},{\"id\":\"opt-10b\",\"text\":{\"tr\":\"Kimyasal yapısının tamamen değişken olabilmesi ve sadece biyofazdaki termodinamik doygunlukla etki göstermesi.\",\"ar\":\"إمكانية تنوع بنيته الكيميائية كلياً واعتماد تأثيره فقط على التشبع الثرموديناميكي في الطور الحيوي.\",\"en\":\"Having a completely variable chemical structure and acting purely through thermodynamic biophasic saturation.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Bu ifade eter ve kloroform gibi 'yapı-nonspesifik' ilaçları tanımlar (Slayt 23).\",\"ar\":\"مغالطة: هذا التعريف يخص الأدوية غير النوعية بنيوياً مثل الإيثر والكلوروفورم (شريحة 23).\",\"en\":\"Misconception: This describes structurally non-specific drugs like ether and chloroform.\"}},{\"id\":\"opt-10c\",\"text\":{\"tr\":\"Yalnızca gaz fazında uygulanabilmesi ve sadece santral sinir sistemi depresyonu yapabilmesi.\",\"ar\":\"إمكانية تطبيقه في الطور الغازي حصراً واقتصار تأثيره على تثبيط الجهاز العصبي المركزي.\",\"en\":\"Being administrable exclusively in the gaseous state and causing only central depression.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Uçucu anestezikler nonspesifiktir; ancak spesifik ilaçlar her yoldan verilebilir ve tüm sistemleri etkiler.\",\"ar\":\"مغالطة: المخدرات الاستنشاقية غير نوعية، بينما تعطى الأدوية النوعية بكافة الطرق وتؤثر على جميع أجهزة الجسم.\",\"en\":\"Misconception: Specific drugs can be administered via oral, parenteral, or topical routes and act on all physiological systems.\"}},{\"id\":\"opt-10d\",\"text\":{\"tr\":\"Etkisinin yalnızca kandaki fiziksel çözünürlük katsayısı ile doğrudan orantılı olması.\",\"ar\":\"تناسب تأثيره طرداً وبشكل حصري مع معامل الذوبانية الفيزيائية في الدم.\",\"en\":\"Its biological activity being solely and directly proportional to blood solubility.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Fiziksel çözünürlük Meyer-Overton nonspesifik kuralıdır; spesifik ilaçlar reseptör bağlanmasına dayanır.\",\"ar\":\"مغالطة: الذوبانية الفيزيائية تخص قاعدة Meyer-Overton للأدوية غير النوعية؛ بينما تعتمد الأدوية النوعية على المستقبلات.\",\"en\":\"Misconception: Bulk solubility governs Meyer-Overton non-specific action; specific drugs rely on receptor affinity.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-10a\",\"text\":\"Temel bir yapı taşıması; küçük değişikliklerin aktiviteyi yok edebilmesi veya tersine çevirmesi.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Slayt 20: Temel yapı taşırlar ve küçük modifikasyonlar etkiyi yok edebilir.\"},{\"id\":\"opt-10b\",\"text\":\"Kimyasal yapısının değişken olabilmesi ve sadece doygunlukla etki etmesi.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Bu özellik yapı-nonspesifik ilaçları tanımlar.\"},{\"id\":\"opt-10c\",\"text\":\"Yalnızca gaz fazında uygulanabilmesi ve sadece SSS depresyonu yapması.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Spesifik ilaçlar her yoldan verilebilir ve tüm sistemleri etkiler.\"},{\"id\":\"opt-10d\",\"text\":\"Etkisinin yalnızca kandaki fiziksel çözünürlükle orantılı olması.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Fiziksel çözünürlük nonspesifik teoriyi temsil eder.\"}],\"revealedOutcome\":{\"tr\":\"Yapı-spesifik ilaçlar temel bir kimyasal iskelet taşır; bu iskeletteki en ufak modifikasyon aktiviteyi yok edebilir veya zıt etkiye (antagonist) yol açabilir.\",\"ar\":\"تمتلك الأدوية النوعية هيكلاً كيميائياً أساسياً؛ وأي تعديل طفيف فيه قد يلغي التأثير تماماً أو يؤدي لتأثير مضاد.\",\"en\":\"Structurally specific drugs possess a fundamental template where minor chemical alterations abolish activity or induce antagonism.\"},\"explanation\":{\"tr\":\"Düşük dozlarda etki eden yapı-spesifik ilaçlar, reseptörlerine komplementer uyumla bağlandıkları için yapısal değişikliklere aşırı duyarlıdır (Slayt 20).\",\"ar\":\"نظراً لارتباطها بالمستقبلات بتوافق تكاملي عالي، تكون الأدوية النوعية الفعالة بجرعات منخفضة شديدة الحساسية للتعديل البنيوي (شريحة 20).\",\"en\":\"Acting at low doses via receptor complementarity, structurally specific agents are exquisitely sensitive to chemical modification.\"}},\"technicalTerms\":[{\"term\":\"yapı-spesifik ilaç\",\"arContext\":\"دواء نوعي بنيوياً\"},{\"term\":\"antagonist\",\"arContext\":\"مناهض / مضاد تنافسي\"}],\"hints\":[{\"tr\":\"Urasil ile 5-fluorourasil örneğini hatırlayın.\",\"ar\":\"تذكر مثال اليوراسيل و 5-فلورويوراسيل.\",\"en\":\"Recall the transition from uracil to 5-fluorouracil.\"},{\"tr\":\"Spesifik ilaçlar kilit-anahtar uyumu ile biyolojik hedefe bağlanırlar.\",\"ar\":\"ترتبط الأدوية النوعية بالأهداف الحيوية وفق نموذج القفل والمفتاح.\",\"en\":\"Structurally specific drugs engage targets through lock-and-key complementarity.\"},{\"tr\":\"Tek bir atomun değişmesi kilit yuvasını bozar ve etkiyi tamamen ortadan kaldırır.\",\"ar\":\"تغيير ذرة واحدة يفسد التوافق مع جيب القفل فيلغي التأثير تماماً.\",\"en\":\"Altering a single atom disrupts pocket complementarity, terminating drug action.\"}],\"sources\":[{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":20}]},{\"id\":\"mc-mod1-les1-step-11\",\"stage\":\"connection\",\"stageIndex\":11,\"title\":{\"tr\":\"İleri Bağlantı: Çözünürlük ve İyonizasyon (Ders 2)\",\"ar\":\"ربط مفاهيمي: الذوبانية والتأين (الدرس 2)\",\"en\":\"Conceptual Bridge: Solubility & Ionization (Lesson 2)\"},\"prompt\":{\"tr\":\"Termodinamik aktivite molekülün sulu fazdan lipid zara kaçışını açıklar. Bir sonraki derste bu kaçışı yöneten asit-baz iyonizasyon dengesini (Henderson-Hasselbalch) inceleyeceğiz.\",\"ar\":\"يفسر النشاط الثرموديناميكي هروب الجزيء من الماء نحو الغشاء. في الدرس القادم، سندرس توازن التأين الحمضي-الأساسي (Henderson-Hasselbalch) الذي يتحكم بهذا العبور.\",\"en\":\"Thermodynamic activity explains how neutral molecules escape water into membranes. In the next lesson, we will explore the acid-base ionization equilibrium (Henderson-Hasselbalch) governing this crossing.\"},\"predictThenReveal\":false,\"config\":{\"nextLesson\":\"mc-mod1-les2\",\"bridgingConcept\":\"HendersonHasselbalchIonization\",\"explanation\":{\"tr\":\"İyonlaşmış türler sulu ortamda polar bağlarla kalırken, iyonlaşmamış nötr formlar lipid membranlara kolayca geçer (Çözünürlük Slayt 9, 13).\",\"ar\":\"تبقى الأشكال المتأينة في الوسط المائي بروابط قطبية، بينما تعبر الأشكال المعتدلة غير المتأينة الأغشية الدهنية بسهولة (شريحة 9، 13).\",\"en\":\"Ionized species remain partitioned in polar water, whereas un-ionized neutral molecules readily diffuse across lipid membranes.\"}},\"technicalTerms\":[{\"term\":\"iyonizasyon dengesi\",\"arContext\":\"توازن التأين\"},{\"term\":\"Henderson-Hasselbalch denklemi\",\"arContext\":\"معادلة Henderson-Hasselbalch\"}],\"hints\":[{\"tr\":\"İyonlaşmış moleküller sulu ortamda kalma eğilimindedir.\",\"ar\":\"تميل الجزيئات المتأينة للبقاء في الوسط المائي.\",\"en\":\"Ionized molecules exhibit a strong preference for polar aqueous environments.\"},{\"tr\":\"Yalnızca iyonlaşmamış nötr form lipid membranlardan geçebilir.\",\"ar\":\"فقط الشكل المعتدل غير المتأين يستطيع عبور الأغشية الدهنية.\",\"en\":\"Only the un-ionized neutral fraction diffuses passively across lipid membranes.\"},{\"tr\":\"Henderson-Hasselbalch denklemi bu oranı ortam pH sı ve pKa ile belirler.\",\"ar\":\"تحدد معادلة Henderson-Hasselbalch هذه النسبة بناءً على pH الوسط و pKa الدواء.\",\"en\":\"The Henderson-Hasselbalch equation defines this ratio from ambient pH and drug pKa.\"}],\"sources\":[{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":9},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":13}]},{\"id\":\"mc-mod1-les1-step-12\",\"stage\":\"mastery_check\",\"stageIndex\":12,\"title\":{\"tr\":\"Ustalık Sınavı: Halotan Vakasında Yapısal ve Termodinamik Kanıtlar\",\"ar\":\"اختبار الإتقان: أدلة البنية والديناميكا الحرارية في حالة الهالوتان\",\"en\":\"Mastery Assessment: Halothane Structure & Thermodynamic Evidence\"},\"prompt\":{\"tr\":\"Halotan (2-bromo-2-kloro-1,1,1-trifluoroetan), eter ve kloroformdan çok farklı bir yapıda olmasına rağmen cerrahi anestezi oluşturur. Halotanın yapı-nonspesifik olduğunu hangi yapısal ve termodinamik kanıtlar gösterir?\",\"ar\":\"يحدث الهالوتان تخديراً جراحياً رغم اختلاف بنيته كلياً عن الإيثر والكلوروفورم. ما هي الأدلة البنيوية والحرارية التي تثبت أنه دواء غير نوعي بنيوياً؟\",\"en\":\"Halothane produces surgical anesthesia despite possessing a structure entirely distinct from ether and chloroform. What structural and thermodynamic evidence proves halothane acts via a structurally non-specific mechanism?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-12a\",\"text\":{\"tr\":\"Halotan tek bir kovalent reseptör bağı oluşturarak nanogram düzeyindeki mikroskobik dozlarda geri dönüşsüz felç yapar.\",\"ar\":\"يشكل الهالوتان رابطة تساهمية مع مستقبل مفرد مسبباً شللاً لا رجعة فيه بجرعات مجهرية بالنانوغرام.\",\"en\":\"Halothane forms an irreversible covalent bond with a single receptor at microscopic nanogram doses.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Bu senaryo alkilleyici sitotoksik ajanları tanımlar; halotan kovalent bağ yapmaz ve gram düzeyinde verilir.\",\"ar\":\"مغالطة: هذا السلوك يصف العوامل السامة المؤلكلة؛ الهالوتان لا يشكل روابط تساهمية ويُعطى بجرعات غرامية.\",\"en\":\"Misconception: This describes cytotoxic alkylating agents; halothane binds non-covalently and requires gram-scale administration.\"}},{\"id\":\"opt-12b\",\"text\":{\"tr\":\"Belirli bir farmakofor taşımaması, farklı yapılı uçucu gazlarla benzer bağıl doygunlukta aynı etkiyi vermesi ve yapı değişiminin sadece fizikokimyasal özellikleri etkilemesi.\",\"ar\":\"عدم امتلاكه لمجموعة نوعية، وإحداثه نفس الأثر عند تشبع نسبي مماثل لغازات متباينة، واقتصار أثر التعديل على الخواص الفيزيوكيميائية.\",\"en\":\"Lacking a stereoselective pharmacophore, sharing depressant action with diverse volatile gases at comparable relative saturation, with structural edits altering only physical properties.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Tebrikler! Hem kimyasal yapının değişkenliği hem de bağıl doygunluk prensibi (Ferguson) halotanın yapı-nonspesifik etki mekanizmasını eksiksiz kanıtlar (Slayt 14, 18, 23).\",\"ar\":\"تهانينا! يثبت تنوع البنية ومبدأ التشبع النسبي (Ferguson) معاً أن الهالوتان دواء غير نوعي بنيوياً بشكل قاطع (شريحة 14، 18، 23).\",\"en\":\"Congratulations! Both structural insensitivity and biophasic relative saturation (Ferguson) conclusively prove halothane's non-specific physical mechanism.\"}},{\"id\":\"opt-12c\",\"text\":{\"tr\":\"Moleküler yapısından bağımsız olarak, sadece buhar basıncı sayısal olarak yüksek bir değer olduğu için nonspesifiktir.\",\"ar\":\"كونه غير نوعي لمجرد أن ضغط بخاره المشبع يمثل قيمة عددية مرتفعة، بمعزل عن بنيته الجزيئية.\",\"en\":\"Being non-specific solely because its saturation vapor pressure is a numerically high value, irrespective of molecular structure.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Tek başına hiçbir sayısal değer nonspesifikliğin kanıtı olamaz; farmakofor yokluğu ve biyofazik bağıl doygunluk birlikte değerlendirilmelidir.\",\"ar\":\"مغالطة: لا يمكن لرقم بمفرده إثبات اللانوعية؛ المعيار هو غياب المجموعة الفعالة والتكافؤ في التشبع النسبي في الطور الحيوي.\",\"en\":\"Misconception: A number alone never proves non-specificity; absence of a pharmacophore and biophasic relative saturation together establish the mechanism.\"}},{\"id\":\"opt-12d\",\"text\":{\"tr\":\"Taşıdığı halojen atomlarının beyindeki tüm enzim aktif bölgelerini kimyasal olarak geri dönüşsüz inaktive etmesi.\",\"ar\":\"تعطيل ذرات الهالوجين التي يحملها لجميع المواقع النشطة للإنزيمات في الدماغ كيميائياً ولا رجعة فيه.\",\"en\":\"Its halogen atoms irreversibly inactivating all enzyme catalytic pockets throughout brain tissue.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Halotandaki halojenler uçuculuk ve lipofilitesini belirler; intihar enzim inhibitörü olarak davranmazlar.\",\"ar\":\"مغالطة: تحدد الهالوجينات في الهالوتان التطاير والشحمية فقط، ولا تعمل كمثبطات انتحارية للإنزيمات.\",\"en\":\"Misconception: Halogens in halothane modulate volatility and partition kinetics; they do not function as suicide enzyme inhibitors.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-12a\",\"text\":\"Tek bir kovalent reseptör bağı yaparak nanogram düzeyinde etki eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Bu davranış alkilleyici sitotoksik ajanları tanımlar.\"},{\"id\":\"opt-12b\",\"text\":\"Farmakofor taşımaması, farklı yapılı gazlarla benzer bağıl doygunlukta aynı etkiyi vermesi.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Tebrikler! Yapısal bağımsızlık ve Ferguson bağıl doygunluğu nonspesifikliği kanıtlar.\"},{\"id\":\"opt-12c\",\"text\":\"Sadece buhar basıncı sayısal olarak yüksek bir değer olduğu için.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Tek başına hiçbir sayısal değer nonspesifikliğin kanıtı olamaz.\"},{\"id\":\"opt-12d\",\"text\":\"Halojen atomlarının beyindeki tüm enzimleri inaktive etmesi.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Halojenler uçuculuk ve lipofilitesini belirler, enzim zehiri değildir.\"}],\"revealedOutcome\":{\"tr\":\"Halotan belirli bir farmakofor taşımaması ve farklı yapılı anesteziklerle benzer bağıl doygunlukta anestezi yapması nedeniyle yapı-nonspesifiktir.\",\"ar\":\"يعتبر الهالوتان غير نوعي بنيوياً لغياب المجموعة الفعالة وتماثل أثره عند نفس التشبع النسبي مع مخدرات متباينة البنية كلياً.\",\"en\":\"Halothane is structurally non-specific because it lacks a discrete pharmacophore and shares clinical depression at comparable relative saturation.\"},\"explanation\":{\"tr\":\"2-Bromo-2-kloro-1,1,1-trifluoroetan (halotan), eter ve kloroform gibi genel anesteziklerle benzer bağıl doygunlukta zarı doymuş hale getirerek etki gösterir (Slayt 14, 18, 23).\",\"ar\":\"يؤثر الهالوتان (2-برومو-2-كلورو-1،1،1-ثلاثي فلورو إيثان) عبر تشبيع الغشاء عند نفس التشبع النسبي كالإيثر والكلوروفورم (شريحة 14، 18، 23).\",\"en\":\"Halothane (2-bromo-2-chloro-1,1,1-trifluoroethane) operates by physically saturating membrane lipids at comparable relative thermodynamic activity.\"}},\"technicalTerms\":[{\"term\":\"halotan\",\"arContext\":\"هالوتان\"},{\"term\":\"termodinamik doygunluk\",\"arContext\":\"التشبع الديناميكي الحراري\"}],\"hints\":[{\"tr\":\"Halotanın kimyasal yapısını kloroform ve dietil eter ile karşılaştırın.\",\"ar\":\"قارن بنية الهالوتان الكيميائية مع الكلوروفورم وإيثر ثنائي الإيثيل.\",\"en\":\"Compare halothane's molecular structure with chloroform and diethyl ether.\"},{\"tr\":\"Sayısal bir değer tek başına etki mekanizmasını açıklayabilir mi?\",\"ar\":\"هل يمكن لقيمة عددية بمفردها تفسير آلية التأثير؟\",\"en\":\"Can a numerical value in isolation prove an underlying mechanism of action?\"},{\"tr\":\"Hem yapısal çeşitlilik hem de Ferguson bağıl doygunluk kuralı birlikte düşünülmelidir.\",\"ar\":\"يجب الجمع بين التنوع البنيوي وقاعدة Ferguson للتشبع النسبي معاً.\",\"en\":\"Combine absence of a stereoselective pharmacophore with Ferguson relative biophasic saturation.\"}],\"sources\":[{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":14},{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":18},{\"file\":\"Farmasötik ve Medisinal Kimya 1-Giriş.pdf\",\"page\":23}]}]},\"mc-mod1-les2\":{\"$schema\":\"../../../packages/platform/schema/lesson.schema.json\",\"id\":\"mc-mod1-les2\",\"courseId\":\"medchem\",\"moduleId\":\"mc-mod-01\",\"title\":{\"tr\":\"Çözünürlük, İyonizasyon ve Dielektrik Sabiti\",\"ar\":\"الذوبانية، التأين وثابت العزل الكهربائي\",\"en\":\"Solubility, Ionization & Dielectric Constant\"},\"order\":2,\"access\":\"free\",\"objective\":{\"tr\":\"Henderson-Hasselbalch bağıntısıyla fizyolojik kompartmanlarda ilaç iyonizasyonunu hesaplamak; membran geçirgenliği, iyon tuzağı ve dielektrik çözünürlük ilkelerini öngörmek.\",\"ar\":\"حساب درجة تأين الأدوية عبر علاقة Henderson-Hasselbalch في الحجيرات الحيوية والتنبؤ بنفوذية الأغشية والحصار الأيوني وثابت العزل الكهربائي.\",\"en\":\"Calculate drug ionization across physiological compartments using Henderson-Hasselbalch, and predict membrane permeation, ion trapping, and formulation solubility.\"},\"misconceptions\":[{\"tr\":\"Asitlerin daima yüklü, bazların ise daima nötr olduğu ya da zayıf bazların asidik ortamda nötr kaldığı yanılgısı.\",\"ar\":\"الاعتقاد الخاطئ بأن الأحماض مشحونة دوماً والقواعد محايدة، أو أن القواعد الضعيفة تبقى متعادلة في الوسط الحامضي.\",\"en\":\"The misconception that acids are always charged and bases neutral, or that weak bases remain un-ionized in acidic media.\"},{\"tr\":\"Midede nötr fraksiyonun (%99) yüksek olmasının, aspirinin mideden ince bağırsaktan daha fazla emilmesini sağlayacağı yanılgısı (yüzey alanını göz ardı etme).\",\"ar\":\"الافتراض الخاطئ بأن النسبة العالية للكسر المتعادل (99%) في المعدة تجعل امتصاص الأسبرين المعدي أكبر من المعوي متجاهلاً مساحة السطح.\",\"en\":\"The assumption that a 99% un-ionized fraction in the stomach causes more total aspirin to be absorbed there than in the small intestine (ignoring surface area).\"},{\"tr\":\"Dielektrik sabitinin yalnızca çözücünün fiziksel yoğunluğunu temsil ettiği ve iyonik kristal kafes ayrışmasını etkilemediği varsayımı.\",\"ar\":\"الاعتقاد الخاطئ بأن ثابت العزل الكهربائي يمثل فقط كثافة المذيب الفيزيائية ولا يحدد تفكك الشبكة البلورية للأملاح.\",\"en\":\"The misconception that the dielectric constant merely represents solvent density and does not govern ionic crystal lattice dissociation.\"}],\"sources\":[{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":2},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":5},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":6},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":7},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":9},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":11},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":16},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":17}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Foye's Principles of Medicinal Chemistry\",\"edition\":\"8th ed.\",\"topic\":\"Physicochemical Properties: Ionization, pKa, and Partitioning\",\"chapter\":\"Chapter 2\",\"page\":\"35-48\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Wilson and Gisvold's Textbook of Organic Medicinal and Pharmaceutical Chemistry\",\"edition\":\"12th ed.\",\"topic\":\"Solubility, Ionization, and Biological Membrane Transit\",\"chapter\":\"Chapter 3\",\"page\":\"55-72\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"mc-mod1-les2-card1\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Aspirin Emilim Paradoksu ve Yüzey Alanı\",\"prompt\":\"Midede %99 nötr olan aspirinin %90'ından fazlası neden ince bağırsaktan emilir?\",\"answer\":\"İnce bağırsağın ~32 m²'lik geniş emilim yüzey alanı ve yoğun mezenterik kan akımı, %0.1'lik nötr fraksiyonu hızla emerek Le Chatelier dengesini sürekli nötr forma kaydırır.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod1-les2-card2\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Henderson-Hasselbalch 50:50 Kuralı ve 1-2 Birim Kuralı\",\"prompt\":\"Ortam pH'sı zayıf bir asidin pKa'sına eşit olduğunda, 1 birim ve 2 birim üzerine çıktığında iyonize yüzdeleri ne olur?\",\"answer\":\"pH = pKa iken %50; pH = pKa + 1 iken %90.9; pH = pKa + 2 iken %99.0 iyonizedir.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod1-les2-card3\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Dielektrik Sabiti ve Coulomb Çekimi\",\"prompt\":\"Suyun yüksek dielektrik sabiti (ε = 80.4) iyonik tuzların kristal kafesinden çözünmesini nasıl sağlar?\",\"answer\":\"Coulomb yasasına göre (F = q1·q2 / ε·r²) çözücünün dielektrik sabiti zıt iyonlar arasındaki elektrostatik çekim kuvvetini 80 kat azaltarak kristal kafesin ayrışmasını sağlar.\",\"box\":1,\"intervalDays\":1}],\"steps\":[{\"id\":\"mc-mod1-les2-step-01\",\"stage\":\"hook\",\"stageIndex\":1,\"title\":{\"tr\":\"Klinik İkilem: Aspirin Emilim Paradoksu\",\"ar\":\"معضلة سريرية: مفارقة امتصاص الأسبرين\",\"en\":\"Clinical Dilemma: The Aspirin Absorption Paradox\"},\"prompt\":{\"tr\":\"Aspirin (pKa 3.5) midede %99 nötr, bağırsakta %99.9 iyonizedir. Ancak aspirinin %90'ından fazlası mideden değil bağırsaktan emilir! Yüklü iyon zardan sızamazken bu nasıl gerçekleşir?\",\"ar\":\"يتواجد <span dir='ltr'>aspirin</span> (pKa 3.5) في المعدة بنسبة 99% متعادلاً، وفي الأمعاء بنسبة 99.9% متأيّناً. ومع ذلك يُمتص 90% منه معوياً! كيف يعبر الجزيء المشحون؟\",\"en\":\"Aspirin (pKa 3.5) is 99% un-ionized in stomach, yet 99.9% ionized in intestine. Still, over 90% is absorbed intestinally! If charged ions cannot cross bilayers, how does this occur?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-1a\",\"text\":{\"tr\":\"İnce bağırsağın geniş mikrovillüs yüzey alanı (~32 m²), midedeki yüksek nötr molekül oranını bütünüyle gölgede bırakır.\",\"ar\":\"المساحة الكبيرة للزغابات المعوية (~32 م²) والتروية الدموية تتفوق تماماً على نسبة الجزيئات المتعادلة في المعدة.\",\"en\":\"The intestine's absorptive microvillar surface area (~32 m²) completely dwarfs the stomach's favorable un-ionized fraction.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Fick kanununa göre emilim; geçirgenlik katsayısı ile yüzey alanının çarpımıdır. ~32 m² yüzey alanı kimyasal iyonizasyon dezavantajını ezer geçer.\",\"ar\":\"صحيح! وفق قانون فيك، يعتمد الامتصاص على جداء النفوذية ومساحة السطح؛ مساحة ~32 م² تتغلب على عائق التأين تماماً.\",\"en\":\"Correct! By Fick's law, total absorption is permeability times surface area. A ~32 m² surface area easily overcomes the low un-ionized fraction.\"}},{\"id\":\"opt-1b\",\"text\":{\"tr\":\"İyonize aspirin bağırsak epitelindeki aktif anyon pompalarıyla enerji harcanarak içeri çekilir.\",\"ar\":\"يُمتص الأسبرين المتأين بواسطة مضخات أنيونية نشطة تستهلك ATP في خلايا الأمعاء.\",\"en\":\"Ionized aspirin is actively pumped across intestinal enterocytes by energy-consuming anion transporters.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Aspirin aktif taşıyıcılarla değil, %0.1'lik nötr fraksiyonun pasif difüzyonu ve Le Chatelier kayması ile emilir.\",\"ar\":\"مغالطة: لا يعتمد الأسبرين على النقل النشط، بل على الانتشار السلبي للكسر المتعادل (0.1%) مع انزياح توازن لوشاتيليه.\",\"en\":\"Misconception: Aspirin is absorbed passively via its 0.1% un-ionized fraction, which is replenished instantaneously by Le Chatelier's principle.\"}},{\"id\":\"opt-1c\",\"text\":{\"tr\":\"Mide asidi aspirini anında kimyasal olarak parçalayarak emilmesini imkansız kılar.\",\"ar\":\"يقوم حمض المعدة بتفكيك جزيء الأسبرين كيميائياً على الفور مما يمنع امتصاصه.\",\"en\":\"Gastric hydrochloric acid instantly decomposes aspirin chemically, preventing any gastric absorption.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Aspirin asidik midede stabildir; kimyasal hidroliz bağırsak ve kanda yavaş gerçekleşir.\",\"ar\":\"مغالطة: الأسبرين مستقر في حمض المعدة؛ وتفككه المائي بطيء يحدث لاحقاً في الأمعاء والدم.\",\"en\":\"Misconception: Aspirin is chemically stable in gastric acid; ester hydrolysis occurs gradually in blood and liver.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-1a\",\"text\":\"İnce bağırsağın devasa mikrovillüs yüzey alanı midedeki nötr oranı gölgede bırakır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Yüzey alanı çarpanı kimyasal iyonizasyon dezavantajını ezer.\"},{\"id\":\"opt-1b\",\"text\":\"İyonize aspirin aktif taşıyıcı pompalarla emilir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Aspirin pasif difüzyonla emilir.\"},{\"id\":\"opt-1c\",\"text\":\"Mide asidi aspirini parçalar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Aspirin asitte stabildir.\"}],\"revealedOutcome\":{\"tr\":\"Aspirin midede neredeyse tamamen nötr olmasına rağmen, bağırsağın 30 kat büyük yüzey alanı (~32 m²) ve dinamik denge kayması nedeniyle bağırsaktan emilir.\",\"ar\":\"رغم تعادل الأسبرين في المعدة، فإن مساحة الأمعاء الأكبر بـ 30 ضعفاً (~32 م²) وانزياح التوازن يجعلان الامتصاص معوياً بامتياز.\",\"en\":\"Despite favorable gastric neutral fraction, the intestine's 30-fold greater surface area (~32 m²) drives >90% of total absorption.\"},\"explanation\":{\"tr\":\"pH-partisyon hipotezine göre sadece nötr moleküller geçer; ancak toplam emilim hızı = Geçirgenlik x Yüzey Alanı x Gradyan dır (Slayt 2, 11).\",\"ar\":\"وفق فرضية pH-partition، تنفذ الجزيئات المتعادلة فقط؛ لكن معدل الامتصاص الكلي = النفوذية × مساحة السطح × مدروج التركيز (شريحة 2، 11).\",\"en\":\"By the pH-partition hypothesis, only neutral molecules permeate; yet total flux equals Permeability x Surface Area x Concentration Gradient.\"}},\"technicalTerms\":[{\"term\":\"pH-partisyon hipotezi\",\"arContext\":\"فرضية pH-partition\"},{\"term\":\"pasif difüzyon\",\"arContext\":\"الانتشار السلبي\"}],\"hints\":[{\"tr\":\"Midenin iç yüzey alanı ile ince bağırsağın villüs alanlarını kıyaslayın.\",\"ar\":\"قارن مساحة السطح الداخلي للمعدة مع مساحة الزغابات في الأمعاء الدقيقة.\",\"en\":\"Compare the anatomical surface area of the stomach with intestinal microvilli.\"},{\"tr\":\"Fick difüzyon kanununu düşünün: Toplam akı yüzey alanıyla doğru orantılıdır.\",\"ar\":\"تذكر قانون فيك للانتشار: يتناسب التدفق الكلي طرداً مع مساحة سطح الغشاء.\",\"en\":\"Recall Fick's law: total mass flux is directly proportional to membrane surface area.\"},{\"tr\":\"Mide ~1 m² iken ince bağırsak ~32 m² dir; 30 katlık alan farkı az miktardaki nötr ilacı hızla çeker.\",\"ar\":\"تبلغ مساحة المعدة ~1 م² بينما الأمعاء ~32 م²؛ فارق الثلاثين ضعفاً يسحب الدواء المتعادل فوراً.\",\"en\":\"Stomach area is ~1 m² vs intestine ~32 m²; this 30-fold area difference drives rapid systemic uptake.\"}],\"sources\":[{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":2},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":11}]},{\"id\":\"mc-mod1-les2-step-02\",\"stage\":\"question\",\"stageIndex\":2,\"title\":{\"tr\":\"Tahmin: Nötr Fraksiyon vs Emilim Alanı\",\"ar\":\"تنبؤ: الكسر المتعادل مقابل مساحة الامتصاص\",\"en\":\"Prediction: Neutral Fraction vs Absorption Area\"},\"prompt\":{\"tr\":\"Bir ilacın zardan pasif emilim miktarını belirleyen temel faktör yalnızca nötr molekül yüzdesi midir, yoksa emilim yüzey alanı ve kan akımı da belirleyici midir?\",\"ar\":\"هل تقتصر كمية امتصاص الدواء بالانتشار البسيط على نسبة الجزيئات المتعادلة فقط، أم أن مساحة سطح الامتصاص والتروية الدموية تشاركان بالحسم؟\",\"en\":\"Is the total passive absorption of a drug determined solely by its un-ionized fraction, or do mucosal surface area and local blood flow dictate overall uptake?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-2a\",\"text\":{\"tr\":\"Fick kanununa göre toplam emilim; membran geçirgenliği, yüzey alanı ve konsantrasyon gradyanının ortak fonksiyonudur.\",\"ar\":\"وفق قانون فيك، الامتصاص محصلة مشتركة للنفوذية الغشائية ومساحة السطح ومدروج التركيز.\",\"en\":\"By Fick's law, total absorption is the integrated product of membrane permeability, surface area, and concentration gradient.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Kimyasal iyonizasyon geçirgenliği (P) belirlerken, anatomik alan (A) toplam molekül geçiş hızını tayin eder.\",\"ar\":\"صحيح! يحدد التأين الكيميائي النفوذية الغشائية، بينما تحدد المساحة التشريحية معدل انتقال الجزيئات الكلي.\",\"en\":\"Correct! Ionization dictates intrinsic permeability (P), but anatomical surface area (A) dictates overall mass transfer rate.\"}},{\"id\":\"opt-2b\",\"text\":{\"tr\":\"Yalnızca nötr yüzde belirler; mide emilimi zayıf asitlerde bağırsaktan daima kat kat hızlıdır.\",\"ar\":\"تحدد النسبة المتعادلة وحدها الامتصاص؛ وامتصاص الأحماض الضعيفة في المعدة أسرع دوماً من الأمعاء.\",\"en\":\"Only un-ionized fraction matters; weak acids are always absorbed far faster in the stomach than intestine.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Nötr yüzde birim alandaki hızı artırır; ancak mide yüzey alanı o kadar küçüktür ki toplam emilen miktar bağırsaktan az kalır.\",\"ar\":\"مغالطة: النسبة المتعادلة ترفع سرعة العبور لوحدة المساحة فقط، لكن صغر مساحة المعدة يجعل إجمالي الممتص ضئيلاً.\",\"en\":\"Misconception: Un-ionized fraction increases flux per unit area, but the stomach's small area limits total drug quantity.\"}},{\"id\":\"opt-2c\",\"text\":{\"tr\":\"Yüzey alanı tamamen önemsizdir; molekül ağırlığı 500 Da altındaki tüm ilaçlar mideden difüze olur.\",\"ar\":\"مساحة السطح غير مهمة تماماً؛ فجميع الأدوية دون 500 دالتون تنفذ عبر المعدة بحرية.\",\"en\":\"Surface area is irrelevant; all drugs under 500 Da diffuse across the stomach regardless of area.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Lipinski kuralındaki molekül ağırlığı tek başına emilimi garantilemez; yüzey alanı olmadan emilim yavaşlar.\",\"ar\":\"مغالطة: الوزن الجزيئي وحده لا يضمن الامتصاص؛ فبدون مساحة سطح كافية يتباطأ العبور الحيوي.\",\"en\":\"Misconception: Low molecular weight permits membrane crossing, but insufficient surface area severely limits rate.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-2a\",\"text\":\"Toplam emilim; geçirgenlik, yüzey alanı ve gradyanın çarpımıdır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Fick kanunu alan ve geçirgenliği çarpar.\"},{\"id\":\"opt-2b\",\"text\":\"Yalnızca nötr yüzde belirler.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Alan faktörü ihmal edilemez.\"},{\"id\":\"opt-2c\",\"text\":\"Yüzey alanı önemsizdir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Yüzey alanı ana belirleyicidir.\"}],\"revealedOutcome\":{\"tr\":\"Emilim hızı dQ/dt = P · A · (C1 - C2) dir. Geçirgenlik midede yüksek olsa da, bağırsağın alanı (A) 30 kat daha geniştir (~32 m² vs ~1 m²).\",\"ar\":\"معدل الامتصاص dQ/dt = P · A · (C1 - C2). ورغم ارتفاع النفوذية في المعدة، فإن مساحة الأمعاء تفوقها بثلاثين ضعفاً (~32 م² مقابل ~1 م²).\",\"en\":\"Absorption rate dQ/dt = P · A · (C1 - C2). Permeability is higher in stomach, but intestinal area (A) is ~30-fold greater (~32 m² vs ~1 m²).\"},\"explanation\":{\"tr\":\"Mide emilimi kimyasal olarak mümkündür fakat anatomik yüzey alanı kısıtlılığı nedeniyle toplam biyoyararlanıma katkısı düşüktür (Slayt 2, 11).\",\"ar\":\"امتصاص المعدة ممكن كيميائياً لكن مساحتها المحدودة تجعل مساهمتها في التوافر الحيوي الإجمالي ثانوية (شريحة 2، 11).\",\"en\":\"Gastric absorption occurs chemically, but limited anatomical area makes its contribution to total bioavailability minor.\"}},\"technicalTerms\":[{\"term\":\"Fick difüzyon kanunu\",\"arContext\":\"قانون فيك للانتشار\"},{\"term\":\"biyoyararlanım\",\"arContext\":\"التوافر الحيوي\"}],\"hints\":[{\"tr\":\"Fick kanununun bileşenlerini hatırlayın: Akı = P x A x ΔC.\",\"ar\":\"تذكر عناصر قانون فيك: التدفق = النفوذية × المساحة × مدروج التركيز.\",\"en\":\"Recall the components of Fick's first law: Flux = P x A x ΔC.\"},{\"tr\":\"Yalnızca kimyasal form (P) değil, fiziksel temas yüzeyi (A) de hesaba katılmalıdır.\",\"ar\":\"لا تنظر للشكل الكيميائي فقط، بل احسب مساحة التلامس الفيزيائية أيضاً.\",\"en\":\"Consider both intrinsic permeability (P) and physical contact surface area (A).\"},{\"tr\":\"Geçirgenlik yüksek olsa bile küçük yüzey alanı toplam emilim miktarını sınırlar.\",\"ar\":\"حتى مع النفوذية العالية، فإن صغر المساحة يقيد كمية الدواء الكلية الممتصة.\",\"en\":\"Even with superior permeability, low surface area severely restricts total absorbed drug mass.\"}],\"sources\":[{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":2}]},{\"id\":\"mc-mod1-les2-step-03\",\"stage\":\"intuition\",\"stageIndex\":3,\"title\":{\"tr\":\"Sezgisel Model: Dar Elek ve Dev Sünger\",\"ar\":\"نموذج حدسي: المصفاة الضيقة والإسفنجة العملاقة\",\"en\":\"Intuitive Model: Tight Sieve vs Giant Sponge\"},\"prompt\":{\"tr\":\"Mide (~1 m²) dar bir geçit gibidir. Bağırsak (~32 m²) ise geniş villüs kıvrımlarıyla dev bir süngerdir. Azıcık sızan nötr ilaç bile bu yüzeyde anında emilir.\",\"ar\":\"المعدة (~1 م²) كممر ضيق، بينما الأمعاء (~32 م²) إسفنجة واسعة الزغابات؛ حتى التسرب الضئيل للدواء المتعادل يُمتص عبر هذا السطح في الحال.\",\"en\":\"The stomach (~1 m²) is a narrow passage. The intestine (~32 m²) is a vast folded sponge: even a small neutral fraction is absorbed rapidly.\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-3a\",\"text\":{\"tr\":\"Bağırsaktaki %0.1'lik nötr aspirin emildikçe, Le Chatelier ilkesi gereği iyonize aspirin anında nötr forma dönüşerek emilimi sürdürür.\",\"ar\":\"كلما امتُص كسر 0.1% المتعادل في الأمعاء، ينزاح توازن لوشاتيليه فوراً لتحويل مزيد من الأيونات إلى شكل متعادل.\",\"en\":\"As the 0.1% neutral aspirin is absorbed, Le Chatelier's principle shifts the equilibrium to instantly generate more neutral drug.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel! İyonizasyon statik bir kilit değildir. Nötr molekül zardan geçip kana karıştıkça, geride kalan iyonlar proton alarak nötrleşir ve tükenene kadar emilir.\",\"ar\":\"رائع! التأين توازن حركي؛ فكلما نفذ جزيء متعادل للدم، يلتقط أيون آخر بروتوناً ليعوض النقص حتى يكتمل الامتصاص.\",\"en\":\"Excellent! Ionization is a dynamic equilibrium. As neutral drug exits into blood, remaining ions protonate, driving continuous complete absorption.\"}},{\"id\":\"opt-3b\",\"text\":{\"tr\":\"İyonize moleküller bir kez oluştuktan sonra asla tekrar nötr forma dönemezler.\",\"ar\":\"بمجرد تشكل الجزيئات المتأينة تصبح عاجزة نهائياً عن العودة للشكل المتعادل.\",\"en\":\"Once molecules become ionized in aqueous solution, they can never revert back to the neutral state.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Asit-baz iyonizasyonu dinamik ve mikrosaniyeler içinde tersinir bir kimyasal dengedir (HA <=> H+ + A-).\",\"ar\":\"مغالطة: تفاعل الحمض والقاعدة توازن كيميائي حركي وعكوس فائق السرعة (HA <=> H+ + A-).\",\"en\":\"Misconception: Acid-base dissociation is a rapid, dynamic, and fully reversible chemical equilibrium.\"}},{\"id\":\"opt-3c\",\"text\":{\"tr\":\"Sünger etkisi sadece suda çözünen vitaminlerde görülür, sentetik ilaçlarda işlemez.\",\"ar\":\"ينطبق تأثير الإسفنجة على الفيتامينات الذوابة بالماء فقط ولا يعمل مع الأدوية المصنعة.\",\"en\":\"The sponge sink effect applies solely to water-soluble vitamins, not synthetic pharmaceuticals.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Biyofiziksel yüzey alanı ve dinamik kütle etkisi kuralları tüm kimyasal moleküller için evrenseldir.\",\"ar\":\"مغالطة: قوانين مساحة السطح وفعل الكتلة الحركية عامة وشاملة لجميع الجزيئات الدوائية.\",\"en\":\"Misconception: Biophysical surface area sink principles govern all small-molecule drugs universally.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-3a\",\"text\":\"Nötr form emildikçe Le Chatelier ilkesiyle iyonize form nötr forma dönüşür.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Dinamik denge sürekli nötr molekül üretir.\"},{\"id\":\"opt-3b\",\"text\":\"İyonize molekül nötr forma dönemez.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: İyonizasyon dengesi tersinirdir.\"},{\"id\":\"opt-3c\",\"text\":\"Sünger modeli sentetik ilaçlarda işlemez.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Fizikokimyasal kurallar evrenseldir.\"}],\"revealedOutcome\":{\"tr\":\"İnce bağırsak dev bir lavabo (sink) görevi görür; nötr aspirin kana geçtikçe denge sağa kayar ve tüm doz emilir.\",\"ar\":\"تعمل الأمعاء كبالوعة تصريف حيوية؛ وبامتصاص الجزيئات المتعادلة ينزاح التوازن لامتصاص كامل الجرعة.\",\"en\":\"The intestine acts as a dynamic sink; systemic removal of neutral drug continually shifts the equilibrium to absorb the full dose.\"},\"explanation\":{\"tr\":\"Kandaki kan akımı emilen nötr ilacı hızla uzaklaştırır (sink koşulları). Bu durum lümendeki iyon dengesini sürekli protonlanmaya zorlar (Slayt 2, 3).\",\"ar\":\"يجرف التدفق الدموي الدواء المتعادل فور نفوذه (شروط البالوعة)، مما يجبر الأيونات المتبقية في اللمعة على التعادل باستمرار (شريحة 2، 3).\",\"en\":\"Mesenteric blood flow rapidly sweeps away absorbed neutral drug (sink conditions), driving continuous de novo protonation in the lumen.\"}},\"technicalTerms\":[{\"term\":\"Le Chatelier dengesi\",\"arContext\":\"توازن لوشاتيليه\"},{\"term\":\"lavabo koşulları\",\"arContext\":\"شروط البالوعة الحيوية\"}],\"hints\":[{\"tr\":\"Dinamik kimyasal dengelerde ürünlerden biri ortamdan çekilirse ne olur?\",\"ar\":\"ماذا يحدث في التوازنات الكيميائية الحركية عند سحب أحد النواتج من الوسط باستمرار؟\",\"en\":\"What happens in a dynamic equilibrium when one product is continuously removed from the system?\"},{\"tr\":\"Le Chatelier prensibini hatırlayın: Nötr HA azaldıkça A- iyonları proton bağlar.\",\"ar\":\"تذكر مبدأ لوشاتيليه: مع تناقص HA المتعادل تلتقط أيونات A⁻ البروتونات لتعويضه.\",\"en\":\"Recall Le Chatelier's principle: as neutral HA diffuses away, A- re-protonates.\"},{\"tr\":\"Bağırsaktaki kan akımı nötr molekülü hızla uzaklaştırır; denge sürekli nötr üretir.\",\"ar\":\"يجرف الدم الجزيئات المتعادلة سريعاً؛ فيستمر التوازن بإنتاج شكل متعادل حتى امتصاص كامل الدواء.\",\"en\":\"Capillary blood flow clears absorbed drug; the equilibrium continuously generates neutral molecules until fully absorbed.\"}],\"sources\":[{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":3}]},{\"id\":\"mc-mod1-les2-step-04\",\"stage\":\"visual_explanation\",\"stageIndex\":4,\"title\":{\"tr\":\"Görsel Mekanizma: Membran Dielektrik Bariyeri\",\"ar\":\"آلية بصرية: حاجز العزل الكهربائي الغشائي\",\"en\":\"Visual Mechanism: Bilayer Dielectric Barrier\"},\"prompt\":{\"tr\":\"Fosfolipid çift tabakasının iç çekirdeği hidrokarbon kuyruklardan oluşur (ε ≈ 2). Nötr HA rahatça geçerken, yüklü A⁻ hidrasyon kalkanı nedeniyle hidrokarbon çekirdeğe giremez ve itilir.\",\"ar\":\"تتكون نواة الغشاء الفسفوليبيدي من ذيول هيدروكربونية (ε ≈ 2). يعبر HA المتعادل بسلاسة، بينما يعجز A⁻ المشحون عن اختراق الوسط الهيدروكربوني لتمسكه بغلاف الإماهة.\",\"en\":\"The phospholipid bilayer core is an apolar hydrocarbon layer (ε ≈ 2). Neutral HA diffuses across, while charged A- cannot shed its rigid hydration shell and is electrostatically repelled.\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-4a\",\"text\":{\"tr\":\"İyonik yükün su moleküllerini soyması için gereken desolvatasyon serbest enerjisi devasadır; apolar lipid ortam bu enerjiyi karşılayamaz.\",\"ar\":\"طاقة نزع غلاف الإماهة عن الأيون المشحون هائلة جداً؛ والوسط الدهني غير القطبي عاجز عن تعويض هذا الفقد الطاقي.\",\"en\":\"The desolvation free energy penalty to strip water from an ion is immense; the apolar lipid bilayer cannot compensate for this energetic cost.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Born denklemine göre bir iyonu yüksek dielektrikli sudan (ε = 80) düşük dielektrikli lipide (ε = 2) taşımak aşırı yüksek pozitif serbest enerji (ΔG > 0) gerektirir.\",\"ar\":\"صحيح! وفق معادلة بورن، نقل أيون من الماء (ε = 80) إلى الغشاء الدهني (ε = 2) يتطلب طاقة حرة موجبة هائلة.\",\"en\":\"Correct! By the Born equation, transferring an ion from water (ε = 80) to lipid (ε = 2) incurs a massive positive free energy penalty (ΔG > 0).\"}},{\"id\":\"opt-4b\",\"text\":{\"tr\":\"Fosfolipid başları pozitif yüklüdür ve negatif A⁻ iyonlarını kovalent bağlarla parçalar.\",\"ar\":\"رؤوس الفسفوليبيد موجبة الشحنة وتقوم بتفكيك أيونات A⁻ بروابط تساهمية.\",\"en\":\"Phospholipid headgroups are positively charged and cleave negative A- anions via covalent bond formation.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Membran fosfolipidleri ilaçlarla kovalent bağ yapmaz; engel kimyasal parçalanma değil, elektrostatik dielektrik itmedir.\",\"ar\":\"مغالطة: لا تشكل دهون الغشاء روابط تساهمية مع الأدوية؛ فالعائق هو التنافر الكهروستاتيكي وليس التفكك الكيميائي.\",\"en\":\"Misconception: Biological membrane lipids do not covalently bind drugs; the barrier is electrostatic desolvation.\"}},{\"id\":\"opt-4c\",\"text\":{\"tr\":\"Dielektrik sabiti düşük ortamlar iyonların yükünü nötrleştirerek lipitte çözünmelerini sağlar.\",\"ar\":\"البيئات منخفضة العزل الكهربائي تعادل شحنة الأيونات وتسمح بذوبانها في الدهون.\",\"en\":\"Low dielectric media neutralize ionic charges, promoting high solubility within hydrocarbon chains.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Düşük dielektrikli ortamlar yükü nötrleştirmez; tersine elektrostatik itmeyi şiddetlendirir.\",\"ar\":\"مغالطة: الأوساط منخفضة العزل لا تعادل الشحنة، بل تضاعف قوى التنافر الكهروستاتيكي وتمنع ذوبان الشوارد.\",\"en\":\"Misconception: Low dielectric media do not neutralize ions; they intensify electrostatic repulsion against charge entry.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-4a\",\"text\":\"İyonik yükün su kalkanını soyması için gereken desolvatasyon enerjisi devasadır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Desolvatasyon cezası iyonların geçişini engeller.\"},{\"id\":\"opt-4b\",\"text\":\"Fosfolipidler iyonları kovalent olarak parçalar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Membranda kovalent parçalanma olmaz.\"},{\"id\":\"opt-4c\",\"text\":\"Düşük dielektrik iyonu nötrleştirir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Düşük dielektrik iyon girişine karşı direnç yaratır.\"}],\"revealedOutcome\":{\"tr\":\"Born enerjisi bariyeri: Su (ε = 80) ile yağ (ε = 2) arasındaki devasa dielektrik uçurumu, iyonize türleri sulu kompartmanda kilitli tutar.\",\"ar\":\"حاجز طاقة بورن: الفارق الهائل في العزل الكهربائي بين الماء (ε = 80) والدهن (ε = 2) يقفل الباب أمام الشوارد المتأينة.\",\"en\":\"Born energy barrier: The huge dielectric disparity between water (ε = 80) and lipid (ε = 2) traps ionized species in aqueous compartments.\"},\"explanation\":{\"tr\":\"İyonize maddeler (A⁻, BH⁺) kalın bir hidrasyon kabuğuna sahiptir. Bu kabuğun lipid fazında soyulması termodinamik olarak imkansızdır (Slayt 6, 11).\",\"ar\":\"تحاط الشوارد المتأينة (A⁻, BH⁺) بغلاف إماهة مائي كثيف، ونزع هذا الغلاف في وسط دهني مستحيل ديناميكياً (شريحة 6، 11).\",\"en\":\"Ionized species possess rigid hydration shells; desolvating them inside a low-dielectric hydrocarbon core is thermodynamically prohibitive.\"}},\"technicalTerms\":[{\"term\":\"dielektrik sabiti\",\"arContext\":\"ثابت العزل الكهربائي\"},{\"term\":\"desolvatasyon enerjisi\",\"arContext\":\"طاقة إزالة الإماهة\"}],\"hints\":[{\"tr\":\"Suyun dielektrik sabiti (ε = 80) ile lipid zarın dielektrik sabitini (ε = 2) kıyaslayın.\",\"ar\":\"قارن ثابت العزل الكهربائي للماء (ε = 80) مع غشاء الدهون (ε = 2).\",\"en\":\"Compare the dielectric constant of water (ε = 80) with lipid membranes (ε = 2).\"},{\"tr\":\"Yüklü bir iyonu saran su moleküllerini (hidrasyon kabuğu) soymak enerji ister mi?\",\"ar\":\"هل يتطلب نزع جزيئات الماء المحيطة بالأيون (غلاف الإماهة) طاقة؟\",\"en\":\"Does stripping the structured hydration shell from a charged ion require energy?\"},{\"tr\":\"Yüksek desolvatasyon enerjisi nedeniyle iyonlar düşük dielektrikli lipid çekirdeğe giremez.\",\"ar\":\"بسبب طاقة نزع الإماهة المرتفعة تعجز الأيونات عن اختراق النواة الدهنية منخفضة العزل.\",\"en\":\"Immense desolvation penalty prevents hydrated ions from partitioning into the low-dielectric lipid core.\"}],\"sources\":[{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":6},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":11}]},{\"id\":\"mc-mod1-les2-step-05\",\"stage\":\"interactive_artifact\",\"stageIndex\":5,\"title\":{\"tr\":\"İnteraktif Simülatör: İyonizasyon Dengesi\",\"ar\":\"محاكاة تفاعلية: توازن التأين\",\"en\":\"Interactive Simulator: Ionization Equilibrium\"},\"prompt\":{\"tr\":\"Simülatörde aspirin (pKa 3.5) için pH sürgüsünü 1.5'ten 7.4'e getirin. Henderson-Hasselbalch dengesi değiştikçe zardan geçen parçacık akısını ve logD değerini izleyin.\",\"ar\":\"حرك شريط pH في المحاكي من 1.5 إلى 7.4 لدواء <span dir='ltr'>aspirin</span> (pKa 3.5). راقب تغير توازن Henderson-Hasselbalch وتدفق الجزيئات عبر الغشاء.\",\"en\":\"In the simulator, slide pH from 1.5 to 7.4 for aspirin (pKa 3.5). Observe how the Henderson-Hasselbalch equilibrium shifts particle flux across the membrane in real time.\"},\"predictThenReveal\":false,\"widgetType\":\"IonizationChamber\",\"widget\":{\"type\":\"IonizationChamber\",\"config\":{\"drugName\":\"Aspirin (Asetilsalisilik Asit)\",\"pKa\":3.5,\"drugType\":\"weak_acid\",\"compartmentA\":{\"name\":\"Mide Lümeni (Stomach)\",\"defaultPh\":1.5,\"minPh\":1,\"maxPh\":8.5,\"surfaceAreaM2\":1},\"compartmentB\":{\"name\":\"Sistemik Kan (Blood)\",\"ph\":7.4,\"surfaceAreaM2\":32},\"maxParticleCount\":20,\"equationRef\":\"Helander & Fändriks (2014); Foye Principles of Medicinal Chemistry 8th ed.\"}},\"config\":{\"drugName\":\"Aspirin (Asetilsalisilik Asit)\",\"pKa\":3.5,\"drugType\":\"weak_acid\",\"compartmentA\":{\"name\":\"Mide Lümeni (Stomach)\",\"defaultPh\":1.5,\"minPh\":1,\"maxPh\":8.5,\"surfaceAreaM2\":1},\"compartmentB\":{\"name\":\"Sistemik Kan (Blood)\",\"ph\":7.4,\"surfaceAreaM2\":32},\"maxParticleCount\":20,\"explanation\":{\"tr\":\"Midede (pH 1.5) aspirin %99 nötrdür ancak alan 1 m² dir. İnce bağırsakta (pH 6.5) nötr fraksiyon %0.1'dir ancak alan ~32 m² ve mezenterik kan akımı emilimi hızla sürdürür.\",\"ar\":\"في المعدة (pH 1.5) يكون الأسبرين 99% متعادلاً ولكن المساحة 1 م². وفي الأمعاء (pH 6.5) يكون 0.1% فقط متعادلاً ولكن المساحة ~32 م² والتروية تسحب الدواء باستمرار.\",\"en\":\"In the stomach (pH 1.5), aspirin is 99% un-ionized but area is only 1 m². In the intestine (pH 6.5), the un-ionized fraction is 0.1% but ~32 m² area and sink conditions sustain massive overall uptake.\"}},\"technicalTerms\":[{\"term\":\"Henderson-Hasselbalch\",\"arContext\":\"معادلة Henderson-Hasselbalch\"},{\"term\":\"logD\",\"arContext\":\"معامل التوزع logD\"}],\"hints\":[{\"tr\":\"pH sürgüsünü 1.5 ten 3.5 e ve ardından 7.4 e yavaşça çekin.\",\"ar\":\"اسحب شريط pH ببطء من 1.5 إلى 3.5 ثم إلى 7.4.\",\"en\":\"Gradually drag the pH slider from 1.5 to 3.5, and then up to 7.4.\"},{\"tr\":\"pH tam olarak 3.5 e geldiğinde nötr ve iyonize yüzdeleri ne oldu?\",\"ar\":\"عندما يصبح pH مطابقاً تماماً لـ 3.5، ماذا تصبح النسبة بين المتعادل والمتأين؟\",\"en\":\"When pH reaches exactly 3.5, what happens to the percentages of neutral and ionized species?\"},{\"tr\":\"pH = pKa noktasında tam %50 nötr, %50 iyonize denge kurulur; pH arttıkça iyonizasyon logaritmik uçar.\",\"ar\":\"عند pH = pKa يتساوى الطرفان بدقة 50% لكل منهما؛ ومع زيادة pH يتصاعد التأين لوغاريتمياً.\",\"en\":\"At pH = pKa, exact 50:50 equilibrium is reached; higher pH drives exponential ionization.\"}],\"sources\":[{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":2},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":11}]},{\"id\":\"mc-mod1-les2-step-06\",\"stage\":\"guided_discovery\",\"stageIndex\":6,\"title\":{\"tr\":\"Rehberli Keşif: 50:50 Kuralı ve Logaritmik Sıçrama\",\"ar\":\"استكشاف موجه: قاعدة 50:50 والقفزات اللوغاريتمية\",\"en\":\"Guided Discovery: The 50:50 Rule & Logarithmic Shifts\"},\"prompt\":{\"tr\":\"Zayıf bir asidin pKa değerine tam eşit bir pH ortamında iyonize ve nötr molekül oranları ne olur? pH değerini 1 ve 2 birim artırırsak oranlar nasıl değişir?\",\"ar\":\"في وسط يساوي فيه pH تماماً قيمة pKa لحمض ضعيف، ما هي نسبة الجزيئات المتأينة والمتعادلة؟ وكيف تتغير إذا رفعنا pH بمقدار وحدة ووحدتين؟\",\"en\":\"When ambient pH equals a weak acid's pKa, what is the ratio of ionized to neutral molecules? How does this ratio shift at 1 and 2 units above pKa?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-6a\",\"text\":{\"tr\":\"pH = pKa iken tam %50:%50 dengededir; +1 pH biriminde %90.9 iyonize, +2 pH biriminde %99.0 iyonizedir.\",\"ar\":\"عند pH = pKa يتساوى الطرفان بنسبة 50%:50%؛ وعند زيادة وحدة يصبح 90.9% متأيّناً، وعند وحدتين يصبح 99.0% متأيّناً.\",\"en\":\"At pH = pKa, species are in exact 50:50 balance; at +1 pH unit it is 90.9% ionized, and at +2 pH units it is 99.0% ionized.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Henderson-Hasselbalch logaritmik bir fonksiyondur: 1 birim fark 10 kat oran (10/1), 2 birim fark 100 kat oran (100/1) yaratır.\",\"ar\":\"صحيح! معادلة Henderson-Hasselbalch دالة لوغاريتمية: فارق وحدة يعطي نسبة 10 أضعاف، وفارق وحدتين يعطي نسبة 100 ضعف.\",\"en\":\"Correct! Henderson-Hasselbalch is logarithmic: a 1-unit shift creates a 10:1 ratio (90.9%), while a 2-unit shift creates a 100:1 ratio (99.0%).\"}},{\"id\":\"opt-6b\",\"text\":{\"tr\":\"pH = pKa iken %100 nötrdür; her 1 pH birimi artışı iyonizasyonu doğrusal olarak %10 artırır.\",\"ar\":\"عند pH = pKa يكون 100% متعادلاً؛ وكل زيادة بمقدار وحدة ترفع التأين خطياً بنسبة 10%.\",\"en\":\"At pH = pKa, it is 100% neutral; each 1-unit pH increase produces a linear 10% gain in ionization.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: İyonizasyon doğrusal (lineer) değil logaritmiktir. pH = pKa da nötr ve iyonize miktarları birbirine eşittir.\",\"ar\":\"مغالطة: التأين دالة لوغاريتمية وليست خطية؛ وعند pH = pKa يتساوى المتعادل مع المتأين تماماً.\",\"en\":\"Misconception: Ionization is logarithmic, not linear. At pH = pKa, neutral and ionized fractions are exactly equal.\"}},{\"id\":\"opt-6c\",\"text\":{\"tr\":\"pH = pKa anında ilaç çöker ve çözünürlük tamamen sıfıra iner.\",\"ar\":\"عند نقطة pH = pKa يترسب الدواء وتهبط الذوبانية إلى الصفر تماماً.\",\"en\":\"At pH = pKa, the drug precipitates out of solution and solubility drops to zero.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: pH = pKa çökelme noktası değildir; hem nötr hem iyonize formun çözeltide dengede bulunduğu noktadır.\",\"ar\":\"مغالطة: نقطة pH = pKa ليست نقطة ترسيب، بل نقطة توازن ذائبة بين الشكلين المتعادل والمتأين.\",\"en\":\"Misconception: pH = pKa is not a precipitation threshold; both species remain in solution at dynamic equilibrium.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-6a\",\"text\":\"pH = pKa iken %50:%50; +1 birimde %90.9, +2 birimde %99.0 iyonizedir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Logaritmik denge 10 ve 100 katlık sıçramalar yapar.\"},{\"id\":\"opt-6b\",\"text\":\"pH = pKa iken %100 nötrdür; artış doğrusaldır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Asit-baz dengesi doğrusal değildir.\"},{\"id\":\"opt-6c\",\"text\":\"pH = pKa anında ilaç çöker.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Çökme değil denge noktasıdır.\"}],\"revealedOutcome\":{\"tr\":\"Asit-baz dengesinde 1 birimlik pH değişimi iyonize/nötr oranını 10 kat, 2 birimlik değişim ise 100 kat kaydırır.\",\"ar\":\"في توازن الحمض والقاعدة، يغير فارق وحدة pH النسبة بعشرة أضعاف، بينما يغيرها فارق وحدتين بمئة ضعف.\",\"en\":\"In acid-base equilibrium, a 1-unit pH shift alters the ionization ratio 10-fold, and a 2-unit shift alters it 100-fold.\"},\"explanation\":{\"tr\":\"Henderson-Hasselbalch: pH - pKa = log([A-]/[HA]). Fark 0 ise oran 1 dir (%50). Fark +1 ise oran 10 dur (%90.9). Fark +2 ise oran 100 dür (%99.0) (Slayt 2).\",\"ar\":\"علاقة Henderson-Hasselbalch: pH - pKa = log([A-]/[HA]). إذا كان الفارق 0 فالنسبة 1 (50%). وإذا كان +1 فالنسبة 10 (90.9%). وإذا كان +2 فالنسبة 100 (99.0%) (شريحة 2).\",\"en\":\"Henderson-Hasselbalch: pH - pKa = log([A-]/[HA]). When Δ = 0, ratio = 1 (50%). When Δ = +1, ratio = 10 (90.9%). When Δ = +2, ratio = 100 (99.0%).\"}},\"technicalTerms\":[{\"term\":\"50:50 iyonizasyon kuralı\",\"arContext\":\"قاعدة التأين 50:50\"},{\"term\":\"Henderson-Hasselbalch\",\"arContext\":\"معادلة Henderson-Hasselbalch\"}],\"hints\":[{\"tr\":\"Henderson-Hasselbalch denkleminde log([A-]/[HA]) ifadesine odaklanın.\",\"ar\":\"ركز على تعبير log([A-]/[HA]) في معادلة Henderson-Hasselbalch.\",\"en\":\"Focus on the term log([A-]/[HA]) in the Henderson-Hasselbalch equation.\"},{\"tr\":\"pH = pKa olduğunda log(oran) = 0 olur; 10^0 kaça eşittir?\",\"ar\":\"عندما يكون pH = pKa يصبح log(النسبة) = 0؛ ما قيمة 10^0؟\",\"en\":\"When pH = pKa, log(ratio) = 0; what does 10^0 equal?\"},{\"tr\":\"10^0 = 1 olduğundan [A-] = [HA] yani %50:%50 dir; her bir pH birimi 10 katlık sıçrama yapar.\",\"ar\":\"بما أن 10^0 = 1، فإن [A-] = [HA] أي 50%:50%؛ وكل وحدة pH إضافية تقفز بالنسب 10 أضعاف.\",\"en\":\"Since 10^0 = 1, [A-] = [HA] (50:50); each additional pH unit produces a 10-fold logarithmic leap.\"}],\"sources\":[{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":2}]},{\"id\":\"mc-mod1-les2-step-07\",\"stage\":\"formal_explanation\",\"stageIndex\":7,\"title\":{\"tr\":\"Matematiksel Model: Henderson-Hasselbalch Denklemi\",\"ar\":\"النموذج الرياضي: معادلة Henderson-Hasselbalch\",\"en\":\"Mathematical Model: Henderson-Hasselbalch Equation\"},\"prompt\":{\"tr\":\"Fenobarbital (pKa 7.4) kanda (pH 7.4) tam %50 nötrdür. İdrar asitleşip pH 5.4 olduğunda Henderson-Hasselbalch ile tübüldeki nötr HA oranını hesaplayın: pH - pKa = log([A-]/[HA]).\",\"ar\":\"يتواجد <span dir='ltr'>fenobarbital</span> (pKa 7.4) في الدم (pH 7.4) بنسبة 50% متعادلاً. عند تحميض البول إلى pH 5.4، احسب نسبة HA المتعادلة عبر: pH - pKa = log([A-]/[HA]).\",\"en\":\"Phenobarbital (pKa 7.4) is 50% neutral in plasma (pH 7.4). When tubular urine acidifies to pH 5.4, calculate the neutral HA fraction using: pH - pKa = log([A-]/[HA]).\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-7a\",\"text\":{\"tr\":\"pH - pKa = -2.0; [A-]/[HA] = 1/100 dür. Fenobarbital %99 nötr HA olur ve tübülden kana geri emilir.\",\"ar\":\"pH - pKa = -2.0؛ نسبة [A-]/[HA] = 1/100. يصبح الفينوباربيتال 99% متعادلاً ويعاد امتصاصه إلى الدم.\",\"en\":\"pH - pKa = -2.0; [A-]/[HA] = 1/100. Phenobarbital is 99% neutral HA, driving passive reabsorption back into blood.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz! pH, pKa'nın 2 birim altına indiğinde zayıf asit protonlanır (%99 nötrleşir). Nötr molekül tübül membranından hızla geri emilerek zehirlenmeyi ağırlaştırır.\",\"ar\":\"ممتاز! بهبوط pH بمقدار وحدتين دون pKa يلتقط الحمض البروتونات (99% متعادل)، فينفذ عبر النبيبات ليعود لمجرى الدم مفاقماً التسمم.\",\"en\":\"Flawless! At 2 units below pKa, weak acids are 99% protonated/neutral, causing massive tubular reabsorption and worsening toxicity.\"}},{\"id\":\"opt-7b\",\"text\":{\"tr\":\"pH - pKa = -2.0; [A-]/[HA] = 100/1 dir. Fenobarbital %99 iyonizedir ve idrarla hızla atılır.\",\"ar\":\"pH - pKa = -2.0؛ نسبة [A-]/[HA] = 100/1. يصبح الدواء 99% متأيّناً ويُطرح سريعاً مع البول.\",\"en\":\"pH - pKa = -2.0; [A-]/[HA] = 100/1. Phenobarbital is 99% ionized, causing rapid renal excretion.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Negatif logaritmik değer (10^-2 = 0.01) iyonize formun azaldığını gösterir, arttığını değil.\",\"ar\":\"مغالطة: القيمة اللوغاريتمية السالبة (10^-2 = 0.01) تعني انخفاض الشوارد المتأينة وليس زيادتها.\",\"en\":\"Misconception: A negative log difference (10^-2 = 0.01) indicates dominant neutral acid, not dominant ionized conjugate base.\"}},{\"id\":\"opt-7c\",\"text\":{\"tr\":\"Asidik idrarda pKa değeri değişir ve fenobarbital her iki formda eşit dağılır.\",\"ar\":\"تتغير قيمة pKa في البول الحامضي ويتوزع الدواء بالتساوي بين الشكلين.\",\"en\":\"In acidic urine, the drug's fundamental pKa shifts, maintaining an even 50:50 distribution.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: pKa molekülün içsel termodinamik sabitidir; ortamın pH sı değişse de pKa değişmez.\",\"ar\":\"مغالطة: pKa ثابت ثرموديناميكي متأصل في الجزيء ولا يتغير بتغير pH الوسط الخارجي.\",\"en\":\"Misconception: pKa is an intrinsic molecular thermodynamic constant and does not change with ambient pH.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-7a\",\"text\":\"pH - pKa = -2.0; fenobarbital %99 nötr HA olur ve kana geri emilir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Asit idrar asit ilacı nötrleştirip geri emer.\"},{\"id\":\"opt-7b\",\"text\":\"Fenobarbital %99 iyonizedir ve hızla atılır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Asit ortam asidin iyonlaşmasını baskılar.\"},{\"id\":\"opt-7c\",\"text\":\"pKa değeri değişir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: pKa sabiti değişmez.\"}],\"revealedOutcome\":{\"tr\":\"İdrar asitleştiğinde fenobarbital nötr HA formuna geçerek (%99) böbrek tübüllerinden kana geri emilir; atılım durma noktasına gelir.\",\"ar\":\"عند تحميض البول يتحول الفينوباربيتال إلى شكله المتعادل HA بنسبة 99% ليعاد امتصاصه كلوياً ويتوقف إطراحه.\",\"en\":\"Acidifying urine forces phenobarbital into its 99% neutral HA state, driving passive tubular reabsorption and halting elimination.\"},\"explanation\":{\"tr\":\"Zayıf asitler için % İyonize = 100 / (1 + 10^(pKa - pH)) dir. pKa - pH = 7.4 - 5.4 = 2.0; % İyonize = 100 / (1 + 100) = %0.99 dur (Slayt 2).\",\"ar\":\"للأحماض الضعيفة % التأين = 100 / (1 + 10^(pKa - pH)). الفارق 2.0؛ % التأين = 100 / 101 = 0.99% (شريحة 2).\",\"en\":\"For weak acids, % Ionized = 100 / (1 + 10^(pKa - pH)). Here, pKa - pH = 2.0; % Ionized = 100 / 101 = 0.99% (99% neutral).\"}},\"technicalTerms\":[{\"term\":\"tübüler geri emilim\",\"arContext\":\"إعادة الامتصاص النبيبي\"},{\"term\":\"asit dissosiyasyon sabiti\",\"arContext\":\"ثابت التفكك الحامضي pKa\"}],\"hints\":[{\"tr\":\"pH (5.4) değerinden pKa (7.4) değerini çıkarın: 5.4 - 7.4 = ?\",\"ar\":\"اطرح قيمة pKa (7.4) من pH (5.4): 5.4 - 7.4 = ؟\",\"en\":\"Subtract pKa (7.4) from pH (5.4): 5.4 - 7.4 = ?\"},{\"tr\":\"Fark -2 dir; 10^(-2) = 1/100 dür. Bu oran [A-] / [HA] dır.\",\"ar\":\"الناتج هو -2؛ و 10^(-2) = 1/100، وهذه تمثل نسبة [A-] / [HA].\",\"en\":\"The difference is -2; 10^(-2) = 1/100, which represents the ratio of [A-] to [HA].\"},{\"tr\":\"1 iyonize moleküle karşılık 100 nötr molekül vardır; yani ilaç %99 nötrleşmiştir ve kana geri döner.\",\"ar\":\"يقابل كل جزيء متأين 100 جزيء متعادل؛ أي أن الدواء متعادل بنسبة 99% وسيعود للدم.\",\"en\":\"There are 100 neutral molecules for every 1 ion; the drug is 99% un-ionized and reabsorbed into blood.\"}],\"sources\":[{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":2}]},{\"id\":\"mc-mod1-les2-step-08\",\"stage\":\"concept_check\",\"stageIndex\":8,\"title\":{\"tr\":\"Kavram Kontrolü: Zayıf Bazların İyonlaşma Tuzağı\",\"ar\":\"فحص المفهوم: فخ تأين القواعد الضعيفة\",\"en\":\"Concept Check: The Weak Base Ionization Trap\"},\"prompt\":{\"tr\":\"Zayıf bir baz olan diazepam (pKa 3.3), pH 1.3 olan mide sıvısında hangi formda baskındır ve zardan geçebilir mi?\",\"ar\":\"دواء <span dir='ltr'>diazepam</span> قاعدة ضعيفة (pKa 3.3)، في سائل المعدة ذي pH 1.3 بأي شكل يتواجد غالباً وهل يعبر الغشاء؟\",\"en\":\"For weak base diazepam (pKa 3.3) in gastric fluid at pH 1.3, which species predominates, and can it passively cross mucosal membranes?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-8a\",\"text\":{\"tr\":\"pH < pKa olduğu için %99 oranında protonlanmış katyonik (BH+) formdadır; zardan pasif olarak geçemez.\",\"ar\":\"بما أن pH < pKa يتواجد بنسبة 99% بشكله الكاتيوني المشحون (BH+) ويعجز عن عبور الغشاء.\",\"en\":\"Since pH < pKa, it is 99% protonated in the cationic (BH+) form and cannot passively cross membranes.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Tebrikler! Bazlar asit ortamda proton alarak iyonlaşır (B + H+ <=> BH+). pH, pKa nın 2 birim altında olduğu için ilaç %99 yüklüdür.\",\"ar\":\"تهانينا! تلتقط القواعد البروتونات في الوسط الحامضي لتتأين (B + H+ <=> BH+). وبفارق وحدتين يتأين 99% من الدواء.\",\"en\":\"Congratulations! Bases accept protons in acidic media (B + H+ <=> BH+). At 2 pH units below pKa, it is 99% cationic.\"}},{\"id\":\"opt-8b\",\"text\":{\"tr\":\"Baz olduğu için asidik ortamda nötr (B) kalır; mideden hızla kana difüze olur.\",\"ar\":\"لكونه قاعدة يبقى متعادلاً (B) في الوسط الحامضي ويمتص سريعاً عبر المعدة.\",\"en\":\"Because it is a base, it remains neutral (B) in acid and rapidly diffuses across the stomach into blood.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: En yaygın öğrenci hatası! Bazlar asit ortamda nötr kalmaz; ortamdaki bol protonları bağlayarak pozitif yüklenirler.\",\"ar\":\"مغالطة: الخطأ الطلابي الأكثر شيوعاً! لا تبقى القواعد متعادلة في الحمض، بل تلتقط البروتونات وتصبح مشحونة إيجابياً.\",\"en\":\"Misconception: A classic trap! Bases do not stay neutral in acid; high proton concentrations force them into the charged BH+ state.\"}},{\"id\":\"opt-8c\",\"text\":{\"tr\":\"pKa değeri 7 den küçük olduğu için diazepam aslında bir asittir ve anyon oluşturur.\",\"ar\":\"بما أن قيمة pKa أقل من 7، فإن الديازيبام حمض في الحقيقة ويشكل شحنة سالبة.\",\"en\":\"Because its pKa is below 7, diazepam actually behaves as an acid and dissociates into an anion.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: pKa değerinin 7 den küçük olması bileşiği asit yapmaz; zayıf bazların konjuge asit pKa sı da düşük olabilir.\",\"ar\":\"مغالطة: كون pKa أقل من 7 لا يعني أنه حمض؛ فالقواعد شديدة الضعف تمتلك pKa منخفضاً لحمضها المقترن.\",\"en\":\"Misconception: A pKa below 7 does not make a compound an acid; very weak bases have low conjugate acid pKa values.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-8a\",\"text\":\"pH < pKa olduğu için %99 protonlanmış katyondur (BH+) ve zarı geçemez.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Bazlar asitte protonlanıp yüklenir.\"},{\"id\":\"opt-8b\",\"text\":\"Baz olduğu için asitte nötr kalır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Bazlar asitte iyonlaşır.\"},{\"id\":\"opt-8c\",\"text\":\"pKa < 7 olduğu için asittir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: pKa düşüklüğü bazlığı dışlamaz.\"}],\"revealedOutcome\":{\"tr\":\"Zayıf bazlar asidik ortamda protonlanarak (BH+) iyonlaşır. Midede diazepam %99 katyonik formdadır ve emilemez.\",\"ar\":\"تتأين القواعد الضعيفة في الوسط الحامضي باكتساب بروتون (BH+)؛ وفي المعدة يكون الديازيبام 99% كاتيوني الشحنة وغير قابل للامتصاص.\",\"en\":\"Weak bases accept protons to become cationic (BH+) in acidic environments. In the stomach, diazepam is 99% charged and cannot permeate.\"},\"explanation\":{\"tr\":\"Zayıf bazlar için % İyonize = 100 / (1 + 10^(pH - pKa)) dir. pH - pKa = 1.3 - 3.3 = -2.0; % İyonize = 100 / (1 + 0.01) = %99.0 dur (Slayt 2).\",\"ar\":\"للقواعد الضعيفة % التأين = 100 / (1 + 10^(pH - pKa)). الفارق -2.0؛ % التأين = 100 / (1 + 0.01) = 99.0% (شريحة 2).\",\"en\":\"For weak bases, % Ionized = 100 / (1 + 10^(pH - pKa)). Here, pH - pKa = -2.0; % Ionized = 100 / 1.01 = 99.0%.\"}},\"technicalTerms\":[{\"term\":\"zayıf baz iyonizasyonu\",\"arContext\":\"تأين القاعدة الضعيفة\"},{\"term\":\"katyonik form\",\"arContext\":\"الشكل الكاتيوني المشحون\"}],\"hints\":[{\"tr\":\"Diazepam bir zayıf bazdır: B + H+ <=> BH+ dengesini yazın.\",\"ar\":\"الديازيبام قاعدة ضعيفة: اكتب معادلة التوازن B + H+ <=> BH+.\",\"en\":\"Diazepam is a weak base: write the equilibrium B + H+ <=> BH+.\"},{\"tr\":\"Asidik ortamda (pH 1.3) serbest H+ konsantrasyonu çok yüksektir; baz bu protonları alır mı, verir mi?\",\"ar\":\"في الوسط الحامضي (pH 1.3) يتوفر فائض هائل من البروتونات H+؛ هل تلتقطها القاعدة أم تمنحها؟\",\"en\":\"In acidic media (pH 1.3), protons (H+) are abundant; does a base accept or donate protons?\"},{\"tr\":\"Baz proton alarak pozitif yüklü BH+ formuna geçer; pH < pKa durumunda bazlar iyonizedir.\",\"ar\":\"تلتقط القاعدة البروتون لتتحول إلى كتيون BH+ موجب الشحنة؛ وعندما يكون pH < pKa تتأين القواعد.\",\"en\":\"Bases accept protons to become positively charged BH+ cations; at pH < pKa, weak bases are ionized.\"}],\"sources\":[{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":2}]},{\"id\":\"mc-mod1-les2-step-09\",\"stage\":\"application\",\"stageIndex\":9,\"title\":{\"tr\":\"Klinik Uygulama: Zehirlenmede İyon Tuzağı\",\"ar\":\"تطبيق سريري: الحصار الأيوني في التسمم\",\"en\":\"Clinical Application: Ion Trapping in Overdose\"},\"prompt\":{\"tr\":\"Akut aspirin zehirlenmesinde hastaya IV sodyum bikarbonat verilerek idrar pH'sı 5.5'ten 7.5'e yükseltilir. Bu müdahale aspirinin renal tübüler geri emilimini nasıl engeller?\",\"ar\":\"في تسمم <span dir='ltr'>aspirin</span> الحاد، يُعطى المريض بيكربونات الصوديوم وريدياً لرفع pH البول من 5.5 إلى 7.5. كيف تمنع هذه القلونة عودة امتصاص الأسبرين كلوياً؟\",\"en\":\"In acute aspirin toxicity, IV sodium bicarbonate raises urine pH from 5.5 to 7.5. How does this alkalinization prevent renal tubular reabsorption of salicylate?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-9a\",\"text\":{\"tr\":\"İdrarda aspirin %99.99 oranında iyonize (A-) hale gelir; yüklü anyon lipid tübül hücresinden kana dönemeyip idrarla atılır (iyon tuzağı).\",\"ar\":\"يصبح الأسبرين 99.99% متأيّناً (A-) في البول؛ ويعجز الأنيون المشحون عن اختراق جدار النبيبات ليعود للدم فيُطرح مع البول (حصار أيوني).\",\"en\":\"Salicylate becomes 99.99% ionized (A-) in alkaline urine; the charged anion cannot cross tubular membranes back into blood and is trapped.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika klinik akıl yürütme! İdrar pH sı (7.5), aspirinin pKa sından (3.5) tam 4 birim yüksektir. İyonizasyon oranı 10.000:1 e fırlar ve tübüler geri emilim sıfırlanır.\",\"ar\":\"استنتاج سريري رائع! يرتفع pH البول (7.5) بأربع وحدات كاملة فوق pKa الأسبرين (3.5)؛ فتقفز نسبة التأين إلى 10,000:1 ويتوقف الامتصاص تماماً.\",\"en\":\"Superb clinical deduction! Urine pH (7.5) is 4 units above pKa (3.5), driving ionization to 10,000:1 and abolishing tubular reabsorption.\"}},{\"id\":\"opt-9b\",\"text\":{\"tr\":\"Bikarbonat aspirine doğrudan kovalent bağlanarak böbrek glomerül filtresinde çökeltir.\",\"ar\":\"ترتبط البيكربونات بالأسبرين تساهمياً مما يؤدي لترسيبه في مرشح الكبيبات الكلوية.\",\"en\":\"Bicarbonate binds covalently to aspirin, causing it to precipitate in renal glomerular filters.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Bikarbonat ilaca kovalent bağlanmaz; ortamın proton derişimini düşürerek asidin iyonlaşmasını sağlar.\",\"ar\":\"مغالطة: لا تشكل البيكربونات روابط تساهمية مع الدواء، بل ترفع قلوية الوسط مما يجبر الحمض على منح بروتونه والتأين.\",\"en\":\"Misconception: Bicarbonate does not form covalent adducts; it acts strictly by neutralizing protons to drive conjugate base ionization.\"}},{\"id\":\"opt-9c\",\"text\":{\"tr\":\"İdrar bazikleşince böbrek kan damarları büzülür ve süzülme durur.\",\"ar\":\"عند قلونة البول تنقبض أوعية الكلى الدموية ويتوقف الترشيح الكبيبي.\",\"en\":\"Alkalinizing urine causes severe renal vasoconstriction, shutting down glomerular filtration entirely.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Bikarbonat böbrek filtrasyonunu durdurmaz; tam tersine tübüler lümendeki atılımı katbekat artırır.\",\"ar\":\"مغالطة: لا توقف البيكربونات وظيفة الكلى، بل تزيد التصفية الكلوية للدواء في اللمعة البولية أضعافاً مضاعفة.\",\"en\":\"Misconception: Alkalinization does not impair renal hemodynamics; it dramatically accelerates tubular clearance.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-9a\",\"text\":\"Aspirin %99.99 iyonize (A-) olur; tübülden kana dönemeyip atılır (iyon tuzağı).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Bazik idrar asit ilacı iyonize edip lümende hapseder.\"},{\"id\":\"opt-9b\",\"text\":\"Bikarbonat aspirine kovalent bağlanıp çöktürür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Kovalent bağlanma olmaz.\"},{\"id\":\"opt-9c\",\"text\":\"Damarlar büzülür ve süzülme durur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Filtrasyon durmaz, atılım artar.\"}],\"revealedOutcome\":{\"tr\":\"Renal iyon tuzağı: İdrar pH 7.5 yapıldığında aspirin 10.000 kat iyonize forma geçer ve tübül hücresi membranından kana kaçamaz.\",\"ar\":\"الحصار الأيوني الكلوي: عند رفع pH البول إلى 7.5 يتأين الأسبرين بنسبة 10,000 ضعف ويعجز عن النفاذ عبر جدار النبيبات ليعود للدم.\",\"en\":\"Renal ion trapping: At urine pH 7.5, aspirin is ionized 10,000-fold, completely barring passive diffusion across tubular membranes back into blood.\"},\"explanation\":{\"tr\":\"Aspirin (pKa 3.5): pH 7.5 te pH - pKa = 4.0 dir. İyonize/nötr oranı 10^4 = 10.000 dir. Salisilat lümende hapsedilir (Slayt 2, 9).\",\"ar\":\"الأسبرين (pKa 3.5): عند pH 7.5 يكون الفارق 4.0؛ نسبة المتأين إلى المتعادل 10^4 = 10,000؛ فيُحبس الساليسيلات في اللمعة ويُطرح (شريحة 2، 9).\",\"en\":\"For aspirin (pKa 3.5): at pH 7.5, Δ = 4.0. The ionized/neutral ratio is 10^4 = 10,000:1, trapping salicylate in the tubular lumen.\"}},\"technicalTerms\":[{\"term\":\"iyon tuzağı\",\"arContext\":\"الحصار الأيوني\"},{\"term\":\"alkalinizasyon\",\"arContext\":\"القلونة البولية\"}],\"hints\":[{\"tr\":\"Aspirinin pKa sı 3.5 tir; idrar pH sı 7.5 yapıldığında aradaki fark kaçtır?\",\"ar\":\"تبلغ قيمة pKa للأسبرين 3.5؛ عندما يصبح pH البول 7.5 كم يبلغ الفارق بينهما؟\",\"en\":\"Aspirin pKa is 3.5; when urine pH is raised to 7.5, what is the difference (pH - pKa)?\"},{\"tr\":\"Fark 4 birimdir; 10^4 = 10.000 kat iyonize A- fazlalığı oluşur.\",\"ar\":\"الفارق هو 4 وحدات؛ مما يولد فائضاً بمقدار 10^4 = 10,000 ضعف لصالح الأيون A⁻.\",\"en\":\"The difference is 4 units; 10^4 creates a 10,000-fold excess of charged A- anion.\"},{\"tr\":\"Yüklü A- tübül epitelinden geri emilemez ve idrara hapsedilerek hızla vücuttan atılır.\",\"ar\":\"يعجز الأيون A⁻ عن العبور السلبي فيحاصَر في البول ويُطرح سريعاً من الجسم.\",\"en\":\"Charged A- cannot cross lipophilic tubular membranes, becoming trapped in urine and excreted.\"}],\"sources\":[{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":2},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":9}]},{\"id\":\"mc-mod1-les2-step-10\",\"stage\":\"retrieval\",\"stageIndex\":10,\"title\":{\"tr\":\"Geri Çağırma: Apsede Anestezi Neden İflas Eder?\",\"ar\":\"استرجاع: لماذا يفشل التخدير في الخراج الملتهب؟\",\"en\":\"Retrieval: Why Does Anesthesia Fail in an Abscess?\"},\"prompt\":{\"tr\":\"Zayıf baz olan lidokain (pKa 7.9) iltihaplı ve asidik (pH 5.9) apse dokusuna enjekte edildiğinde lokal anestezi neden tutmaz? Ağrı iletimi neden durdurulamaz?\",\"ar\":\"عند حقن <span dir='ltr'>lidokain</span> القاعدي (pKa 7.9) في خراج ملتهب وحامضي (pH 5.9)، لماذا يفشل التخدير الموضعي وتستمر إشارات الألم دون توقف؟\",\"en\":\"When weak base lidocaine (pKa 7.9) is injected into acidic abscess tissue (pH 5.9), local anesthesia fails completely. Why cannot nerve conduction be blocked?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-10a\",\"text\":{\"tr\":\"pH, pKa'nın 2 birim altındadır; lidokain %99 katyonik (BH+) olur, hidrofobik sinir kılıfını aşıp akson içine girip sodyum kanalını bloke edemez.\",\"ar\":\"بما أن pH أقل بوحدتين من pKa يتأين الليدوكائين بنسبة 99% ككاتيون (BH+)، فيعجز عن عبور غمد العصب الدهني لحظر قنوات الصوديوم.\",\"en\":\"pH is 2 units below pKa; lidocaine is 99% cationic (BH+), preventing it from penetrating the axonal nerve sheath to block sodium channels from within.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel! Lokal anestezikler sodyum kanalını aksonun iç yüzünden bloke eder. Aksonun içine girebilmek için nötr (B) olmalıdırlar; asidik apse ilacı dışarıda iyon tuzağına düşürür.\",\"ar\":\"إجابة متقنة! تحظر المخدرات الموضعية قنوات الصوديوم من الوجه الداخلي للخلية العصبية؛ والوسط الحامضي للخراج يحبسها في الخارج كشوارد.\",\"en\":\"Superb! Local anesthetics block sodium channels from the intracellular axoplasmic face. In an acidic abscess, cationic lidocaine cannot penetrate the nerve.\"}},{\"id\":\"opt-10b\",\"text\":{\"tr\":\"İltihap dokusundaki bakteriler lidokain molekülünü enzimleriyle parçalayarak besin olarak tüketir.\",\"ar\":\"تفرز بكتيريا الخراج إنزيمات تفكك جزيء الليدوكائين وتتغذى عليه فوراً.\",\"en\":\"Abscess bacteria secrete destructive enzymes that rapidly digest lidocaine molecules as nutrients.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Anestezi başarısızlığı bakteriyel yıkımdan değil, doku asidozunun ilacı zardan geçemeyen yüklü BH+ formuna kilitlemesinden kaynaklanır.\",\"ar\":\"مغالطة: فشل التخدير لا يعود للتفكك البكتيري بل إلى حموضة النسيج التي تقفل الدواء في الشكل المشحون العاجز عن النفاذ.\",\"en\":\"Misconception: Anesthetic failure is caused by biophysical protonation, not bacterial enzymatic degradation.\"}},{\"id\":\"opt-10c\",\"text\":{\"tr\":\"Asidik ortam sodyum kanallarını kalıcı olarak tahrip ettiği için lidokain bağlanacak reseptör bulamaz.\",\"ar\":\"يقوم الوسط الحامضي بتدمير قنوات الصوديوم فلا يجد الليدوكائين مستقبلاً ليرتبط به.\",\"en\":\"The acidic abscess environment permanently destroys voltage-gated sodium channels, leaving no binding targets.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Sodyum kanalları sapasağlamdır ve aksiyon potansiyeli üretmeye devam eder; sorun ilacın kanala ulaşamamasıdır.\",\"ar\":\"مغالطة: قنوات الصوديوم سليمة وتواصل توليد كمونات العمل؛ العائق يكمن في عجز الدواء عن الوصول لموقع الارتباط.\",\"en\":\"Misconception: Sodium channels remain structurally intact and continue firing; lidocaine simply cannot reach its intracellular binding site.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-10a\",\"text\":\"Lidokain %99 katyonik (BH+) olur, hidrofobik sinir kılıfını aşıp akson içine giremez.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Akson zarı yüklü lidokaine geçit vermez.\"},{\"id\":\"opt-10b\",\"text\":\"Bakteriler lidokaini parçalar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Sorun bakteriyel yıkım değildir.\"},{\"id\":\"opt-10c\",\"text\":\"Asit sodyum kanallarını tahrip eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Kanallar aktiftir, ilaç hedefe ulaşamaz.\"}],\"revealedOutcome\":{\"tr\":\"Lokal anestezi paradoksu: Asidik apsede (pH 5.9) lidokain (pKa 7.9) %99 protonlanır; yüklü molekül akson lipid zarını geçip sodyum kanalını içeriden tıkayamaz.\",\"ar\":\"مفارقة التخدير الموضعي: في الخراج الحامضي (pH 5.9) يتأين الليدوكائين (pKa 7.9) بنسبة 99% ككاتيون عاجز عن اختراق غمد العصب.\",\"en\":\"Local anesthetic paradox: In an acidic abscess (pH 5.9), lidocaine (pKa 7.9) is 99% cationic, preventing it from crossing the nerve sheath to block the channel.\"},\"explanation\":{\"tr\":\"Zayıf baz lidokain için pH - pKa = 5.9 - 7.9 = -2.0 dir. Nötr baz fraksiyonu yalnızca %1 dir. Sodyum kanalı aksonun iç yüzündedir (Slayt 2, 9, 11).\",\"ar\":\"لليدوكائين القاعدي: pH - pKa = 5.9 - 7.9 = -2.0؛ الكسر المتعادل لا يتعدى 1% فقط، وموقع حظر القناة يقع في الجانب الداخلي (شريحة 2، 9، 11).\",\"en\":\"For lidocaine: pH - pKa = -2.0; un-ionized base is only 1%. Because the binding site is intracellular, the ionized drug remains locked outside.\"}},\"technicalTerms\":[{\"term\":\"aksonal penetrasyon\",\"arContext\":\"النفاذ المحواري العصبي\"},{\"term\":\"lokal anestezik mekanizması\",\"arContext\":\"آلية المخدر الموضعي\"}],\"hints\":[{\"tr\":\"Lidokain zayıf bir bazdır (pKa 7.9); apse dokusu ise asidiktir (pH 5.9).\",\"ar\":\"الليدوكائين قاعدة ضعيفة (pKa 7.9)؛ بينما نسيج الخراج حامضي (pH 5.9).\",\"en\":\"Lidocaine is a weak base (pKa 7.9); the abscess tissue is acidic (pH 5.9).\"},{\"tr\":\"pH < pKa durumunda zayıf baz hangi formdadır? Nötr mü, katyonik mi?\",\"ar\":\"عندما يكون pH < pKa ما هو الشكل الغالب للقاعدة الضعيفة؟ متعادل أم كاتيوني مشحون؟\",\"en\":\"When pH < pKa, which form dominates for a weak base? Neutral or cationic?\"},{\"tr\":\"Lidokain %99 oranında katyoniktir (BH+); yağlı sinir zarını aşıp kanalın iç ağzına ulaşamaz.\",\"ar\":\"يتأين الليدوكائين بنسبة 99% ككاتيون (BH+) فيعجز عن عبور غمد العصب الدهني للوصول للقناة.\",\"en\":\"Lidocaine is 99% cationic (BH+); it cannot traverse the lipophilic nerve sheath to access the channel pore.\"}],\"sources\":[{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":2},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":9},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":11}]},{\"id\":\"mc-mod1-les2-step-11\",\"stage\":\"connection\",\"stageIndex\":11,\"title\":{\"tr\":\"İleri Bağlantı: Çözücü Dielektrik Sabiti (ε)\",\"ar\":\"ربط مفاهيمي: ثابت العزل الكهربائي للمذيبات\",\"en\":\"Forward Connection: Solvent Dielectric Constant (ε)\"},\"prompt\":{\"tr\":\"Su (ε = 80.4) tuzları çözerken, hekzan (ε = 1.9) neden çözemez? Coulomb yasasına göre dielektrik sabiti iyonik kristal kafes çekimini (F = q1·q2 / ε·r²) nasıl zayıflatır?\",\"ar\":\"يذيب الماء (ε = 80.4) الأملاح، بينما يعجز الهكسان (ε = 1.9). وفق قانون كولوم، كيف يُضعف ثابت العزل التجاذب البلوري الأيوني: F = q1·q2 / ε·r²؟\",\"en\":\"Water (ε = 80.4) readily dissolves salts, while hexane (ε = 1.9) cannot. How does dielectric constant weaken crystal lattice attraction according to Coulomb's law: F = q1·q2 / ε·r²?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-11a\",\"text\":{\"tr\":\"Yüksek ε değeri zıt yükler arasındaki elektrostatik çekim kuvvetini 80 kat zayıflatarak iyonların solvatasyon kabuğuna ayrışmasını sağlar.\",\"ar\":\"تخفض قيمة ε العالية قوة التجاذب الكهروستاتيكي بين الشحنات المتعاكسة بمقدار 80 ضعفاً مما يسمح بتفكك الأيونات وإماهتها.\",\"en\":\"A high ε value reduces electrostatic attractive force between opposite charges by 80-fold, allowing water to solvate and separate individual ions.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Coulomb kuvveti paydadaki ε ile ters orantılıdır. Suda (ε = 80) iyonlar arası çekim 80 kat zayıflarken, hekzanda (ε = 1.9) kristal kafes asla ayrılamaz.\",\"ar\":\"صحيح! تتناسب قوة كولوم عكساً مع ε في المقام؛ ففي الماء تضعف قوة التجاذب 80 مرة، بينما في الهكسان تستحيل فرملة قوى التجاذب البلورية.\",\"en\":\"Correct! Coulomb force is inversely proportional to ε in the denominator. Water weakens lattice attractions 80-fold; hexane cannot dissociate them.\"}},{\"id\":\"opt-11b\",\"text\":{\"tr\":\"Hekzanın dielektrik sabiti düşük olduğu için tuz iyonlarıyla kovalent bağlar kurarak çökelmeyi hızlandırır.\",\"ar\":\"لكون ثابت عزل الهكسان منخفضاً، فإنه يشكل روابط تساهمية مع الأيونات تعجل الترسيب.\",\"en\":\"Because hexane has a low dielectric constant, it forms strong covalent bonds with salt ions, precipitating them.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Hekzan apolar bir hidrokarbondur; iyonlarla kovalent bağ yapamaz, sadece elektrostatik çekimi zayıflatamaz.\",\"ar\":\"مغالطة: الهكسان هيدروكربون غير قطبي لا يشكل روابط تساهمية مع الشوارد؛ وعجزه يكمن في عدم إضعاف التجاذب الكهروستاتيكي.\",\"en\":\"Misconception: Hexane is an inert non-polar hydrocarbon; it forms no covalent bonds, but simply fails to shield electrostatic charges.\"}},{\"id\":\"opt-11c\",\"text\":{\"tr\":\"Dielektrik sabiti yalnızca çözücünün kaynama noktasını belirler; iyon ayrışmasında hiçbir rol oynamaz.\",\"ar\":\"يحدد ثابت العزل الكهربائي درجة غليان المذيب فقط، ولا دور له في تفكك الشوارد إطلاقاً.\",\"en\":\"The dielectric constant solely dictates solvent boiling point and plays zero role in ionic lattice dissociation.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Dielektrik sabiti çözücünün yükleri yalıtma kapasitesidir ve çözünme termodinamiğinin temel parametresidir.\",\"ar\":\"مغالطة: ثابت العزل هو قدرة المذيب على عزل الشحنات الكهربائية ويمثل الركيزة الأساسية لذوبان الأملاح.\",\"en\":\"Misconception: The dielectric constant measures charge-shielding capacity and is the primary determinant of salt solubility.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-11a\",\"text\":\"Yüksek ε elektrostatik çekimi 80 kat zayıflatarak iyonların ayrışmasını sağlar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Coulomb kuvveti paydadaki ε ile ters orantılıdır.\"},{\"id\":\"opt-11b\",\"text\":\"Hekzan tuzla kovalent bağ kurar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Hekzan kovalent bağ yapmaz.\"},{\"id\":\"opt-11c\",\"text\":\"Dielektrik sabiti iyon ayrışmasını etkilemez.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Dielektrik sabiti iyonik çözünmeyi yönetir.\"}],\"revealedOutcome\":{\"tr\":\"Dielektrik sabiti kuralı: Çözücünün dielektrik sabiti (ε) ne kadar yüksekse, kristal kafesteki zıt iyonların çekim kuvveti o kadar zayıflar ve tuz çözünür.\",\"ar\":\"قاعدة ثابت العزل: كلما ارتفع ثابت عزل المذيب (ε)، ضعفت قوة التجاذب بين شحنات الشبكة البلورية وذاب الملح.\",\"en\":\"Dielectric law: The higher the solvent dielectric constant (ε), the weaker the inter-ionic lattice attraction, driving spontaneous salt dissolution.\"},\"explanation\":{\"tr\":\"Coulomb yasası: F = (q1·q2) / (ε·r²). Suyun ε değeri (80.37) kristal bağları kırarken, hekzanın ε değeri (1.89) iyonları ayıramaz (Slayt 6, 7).\",\"ar\":\"قانون كولوم: F = (q1·q2) / (ε·r²). يكسر ثابت عزل الماء (80.37) روابط البلورة، بينما يعجز عزل الهكسان (1.89) تماماً (شريحة 6، 7).\",\"en\":\"Coulomb's Law: F = (q1·q2) / (ε·r²). Water's high dielectric constant (80.37) breaks ionic crystal bonds; hexane (1.89) cannot.\"}},\"technicalTerms\":[{\"term\":\"dielektrik sabiti\",\"arContext\":\"ثابت العزل الكهربائي\"},{\"term\":\"Coulomb yasası\",\"arContext\":\"قانون كولوم\"}],\"hints\":[{\"tr\":\"Coulomb formülüne bakın: F = (q1·q2) / (ε·r²). Paydadaki ε büyürse kuvvet (F) ne olur?\",\"ar\":\"انظر لصيغة كولوم: F = (q1·q2) / (ε·r²). ماذا يحدث للقوة (F) عندما تزداد ε في المقام؟\",\"en\":\"Look at Coulomb's formula: F = (q1·q2) / (ε·r²). If ε in the denominator increases, what happens to force (F)?\"},{\"tr\":\"Paydadaki dielektrik sabiti büyüdükçe, artı ve eksi iyonları birbirine çeken kuvvet azalır.\",\"ar\":\"مع ازدياد ثابت العزل في المقام، تتضاءل القوة التي تجذب الأيونات الموجبة والسالبة لبعضها.\",\"en\":\"As dielectric constant increases in the denominator, the electrostatic attraction between ions weakens.\"},{\"tr\":\"Su çekim kuvvetini 80 kat azaltarak iyonları ayırır; hekzan (ε = 1.9) çekimi azaltamaz ve tuz kristal kalır.\",\"ar\":\"يقلص الماء قوة الجذب بـ 80 ضعفاً محرراً الشوارد؛ بينما يعجز الهكسان (ε = 1.9) عن ذلك فيبقى الملح متبلوراً.\",\"en\":\"Water reduces attraction 80-fold, solvating ions; hexane (ε = 1.9) fails to shield charges, leaving salt crystals intact.\"}],\"sources\":[{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":6},{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":7}]},{\"id\":\"mc-mod1-les2-step-12\",\"stage\":\"mastery_check\",\"stageIndex\":12,\"title\":{\"tr\":\"Ustalık Sınavı: Siprofloksasin İkili pKa ve Zwitterion\",\"ar\":\"اختبار الإتقان: سيبروفلوكساسين وثنائي pKa والزوترأيون\",\"en\":\"Mastery Assessment: Ciprofloxacin Dual pKa & Zwitterion\"},\"prompt\":{\"tr\":\"Siprofloksasinin iki pKa değeri vardır: Karboksilik asit (pKa1 = 6.1) ve piperazin azotu (pKa2 = 8.7). Fizyolojik kanda (pH 7.4) bu ilacın baskın türü ve net yükü nedir?\",\"ar\":\"يمتلك <span dir='ltr'>ciprofloxacin</span> قيمتي pKa: حمض كربوكسيلي (pKa1 = 6.1) ونيتروجين بيبيرازين (pKa2 = 8.7). في دم الإنسان (pH 7.4)، ما هي الشحنة الصافية للجزيء؟\",\"en\":\"Ciprofloxacin has dual pKa values: carboxylic acid (pKa1 = 6.1) and piperazine nitrogen (pKa2 = 8.7). In blood at pH 7.4, what is the predominant molecular species and net charge?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-12a\",\"text\":{\"tr\":\"Karboksil grubu deprotonlanmış (-COO-), piperazin azotu protonlanmıştır (-NH2+); molekül nötr net yüke sahip amfoterik zwitterion formundadır.\",\"ar\":\"تكون مجموعة الكربوكسيل فاقدة للبروتون (-COO-)، ونيتروجين البيبيرازين مكتسباً للبروتون (-NH2+)؛ فيتشكل زوترأيون محايد المحصلة.\",\"en\":\"The carboxyl group is deprotonated (-COO-) and the piperazine nitrogen is protonated (-NH2+); the molecule exists predominantly as a zwitterion with net zero charge.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz ustalık transferi! pH 7.4, asidik pKa1 in (6.1) üzerinde olduğu için karboksil deprotonlanıp eksi yüklenir; bazik pKa2 nin (8.7) altında olduğu için amin protonlanıp artı yüklenir. Molekül zwitteriondur.\",\"ar\":\"إتقان استثنائي لنقل المعرفة! يقع pH 7.4 فوق pKa1 (6.1) فيتأين الكربوكسيل سالباً، ودون pKa2 (8.7) فيتأين الأمين موجباً، مشكلاً زوترأيون متوازن الشحنة.\",\"en\":\"Exceptional mastery transfer! Since pH 7.4 > pKa1 (6.1), the acid deprotonates (-1); since pH 7.4 < pKa2 (8.7), the base protonates (+1), forming a net-neutral zwitterion.\"}},{\"id\":\"opt-12b\",\"text\":{\"tr\":\"Her iki fonksiyonel grup da deprotonlanmıştır; molekül kanda net -2 anyonik yüke sahiptir.\",\"ar\":\"تكون المجموعتان فاقدتين للبروتون؛ ويمتلك الجزيء شحنة سالبة صافية (-2) في الدم.\",\"en\":\"Both functional groups are deprotonated; the molecule carries a net -2 anionic charge in blood.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Piperazin azotunun pKa sı 8.7 dir. pH 7.4 te proton kaybetmez; aksine protonlanmış formda kalır.\",\"ar\":\"مغالطة: يبلغ pKa البيبيرازين 8.7؛ وعند pH 7.4 لا يفقد بروتونه بل يظل كاتيونا موجباً.\",\"en\":\"Misconception: Piperazine pKa is 8.7. At pH 7.4, ambient pH is below pKa, so the amine remains protonated.\"}},{\"id\":\"opt-12c\",\"text\":{\"tr\":\"Her iki grup da tamamen yüksüzdür; molekül kanda zwitterion oluşturamaz.\",\"ar\":\"تكون المجموعتان خاليتين من أي شحنة؛ ولا يمكن للجزيء تشكيل زوترأيون في الدم.\",\"en\":\"Both groups are fully un-ionized; the molecule cannot form a zwitterion in aqueous plasma.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Zwitterion molekülün yüksüz olması demek değil, eşit sayıda artı ve eksi yük taşıyarak net yükünün sıfır olması demektir.\",\"ar\":\"مغالطة: الزوترأيون لا يعني غياب الشحنات، بل حمل شحنتين موجبة وسالبة متساويتين بحيث تكون المحصلة صفراً.\",\"en\":\"Misconception: A zwitterion is not devoid of charge; it carries equal and opposite positive and negative charges.\"}},{\"id\":\"opt-12d\",\"text\":{\"tr\":\"Siprofloksasin fizyolojik pH 7.4 te tamamen çöker ve kanda çözünemez.\",\"ar\":\"يترسب السيبروفلوكساسين بالكامل عند pH 7.4 ويعجز عن الذوبان في الدم.\",\"en\":\"Ciprofloxacin precipitates completely at physiological pH 7.4 and is insoluble in blood.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Zwitterion formunda çözünürlük izoelektrik noktada minimuma inse de tamamen sıfırlanmaz; terapötik konsantrasyonlarda çözünür kalır.\",\"ar\":\"مغالطة: رغم تدني الذوبانية عند النقطة متساوية الكهربائية، إلا أنه لا يترسب في التراكيز العلاجية بالدم.\",\"en\":\"Misconception: While solubility reaches a minimum at the isoelectric point, therapeutic concentrations remain soluble.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-12a\",\"text\":\"Karboksil (-COO-) ve piperazin (-NH2+); net nötr zwitterion formundadır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Karboksil eksi, amin artı; net yük sıfırdır.\"},{\"id\":\"opt-12b\",\"text\":\"Her iki grup deprotonlanmıştır (-2 yük).\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Bazik amin pH 7.4 te protonludur.\"},{\"id\":\"opt-12c\",\"text\":\"Her iki grup yüksüzdür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Her iki grup da yüklüdür (zwitterion).\"},{\"id\":\"opt-12d\",\"text\":\"Kanda tamamen çöker.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Terapötik düzeyde çözünür kalır.\"}],\"revealedOutcome\":{\"tr\":\"Tebrikler! Modül 1 Ustalık Sınavı tamamlandı. Siprofloksasinin fizyolojik pH 7.4 te zwitterion (amfoterik) formda olduğunu ve Henderson-Hasselbalch ilkelerini başarıyla kanıtladınız. +50 XP.\",\"ar\":\"تهانينا! اكتمل اختبار إتقان الوحدة 1 بنجاح. أثبتت أن السيبروفلوكساسين يتواجد كزوترأيون عند pH 7.4 واستوعبت مبادئ Henderson-Hasselbalch بامتياز. +50 XP.\",\"en\":\"Congratulations! Module 1 Mastery Check passed. You proved ciprofloxacin exists as a zwitterion at pH 7.4 and demonstrated rigorous command of Henderson-Hasselbalch principles. +50 XP.\"},\"explanation\":{\"tr\":\"Amfoterik moleküllerde: pH > pKa1 (7.4 > 6.1) olduğundan asit deprotonlanır (-COO-). pH < pKa2 (7.4 < 8.7) olduğundan baz protonlanır (-NH2+). Molekül net sıfır yüklü zwitteriondur (Slayt 9).\",\"ar\":\"في الجزيئات المذبذبة: بما أن pH > pKa1 (7.4 > 6.1) يفقد الحمض بروتونه (-COO-)؛ وبما أن pH < pKa2 (7.4 < 8.7) يكتسب الأمين بروتوناً (-NH2+)، مشكلاً زوترأيون محايد الشحنة (شريحة 9).\",\"en\":\"In amphoteric compounds: pH > pKa1 (7.4 > 6.1) deprotonates the acid (-COO-); pH < pKa2 (7.4 < 8.7) protonates the base (-NH2+), yielding a net-zero zwitterion.\"}},\"technicalTerms\":[{\"term\":\"zwitterion\",\"arContext\":\"الزوترأيون المزدوج الشحنة\"},{\"term\":\"amfoterik bileşik\",\"arContext\":\"مركب مذبذب (amfoterik)\"}],\"hints\":[{\"tr\":\"Karboksilik asit (pKa 6.1) için pH 7.4 te deprotonasyon durumuna bakın: pH > pKa mıdır?\",\"ar\":\"بالنسبة للحمض (pKa 6.1) عند pH 7.4: هل pH > pKa؟\",\"en\":\"For the carboxylic acid (pKa 6.1) at pH 7.4: is pH > pKa?\"},{\"tr\":\"Piperazin azotu (pKa 8.7) için pH 7.4 te protonasyon durumuna bakın: pH < pKa mıdır?\",\"ar\":\"بالنسبة للأمين القاعدي (pKa 8.7) عند pH 7.4: هل pH < pKa؟\",\"en\":\"For the basic piperazine amine (pKa 8.7) at pH 7.4: is pH < pKa?\"},{\"tr\":\"Karboksil eksi (-COO-) ve amin artı (-NH2+) yüklüdür; ikisi birbirini nötrler ve zwitterion oluşur.\",\"ar\":\"يحمل الكربوكسيل شحنة سالبة (-COO-) والأمين شحنة موجبة (-NH2+)؛ فتتعادل الشحنتان لتشكيل زوترأيون.\",\"en\":\"Carboxyl carries -1 (-COO-) and amine carries +1 (-NH2+); opposite charges balance to form a zwitterion.\"}],\"sources\":[{\"file\":\"İlaçlarda Yapı Etki İlişkileri-Çözünürlük.pdf\",\"page\":9}]}]},\"mc-mod2-les1\":{\"$schema\":\"../../../packages/platform/schema/lesson.schema.json\",\"id\":\"mc-mod2-les1\",\"courseId\":\"medchem\",\"moduleId\":\"mc-mod-02\",\"title\":{\"tr\":\"Fonksiyonel Gruplar ve Moleküller Arası Bağlar\",\"ar\":\"المجموعات الوظيفية والروابط بين الجزيئات\",\"en\":\"Functional Groups & Intermolecular Forces\"},\"order\":1,\"access\":\"free\",\"objective\":{\"tr\":\"İlaç-reseptör bağlanma kuvvetlerini (iyonik, H-bağı, hidrofobik, van der Waals) değerlendirmek ve serbest enerji toplamıyla SAR afinite değişimlerini öngörmek.\",\"ar\":\"تقييم قوى الارتباط بين الدواء والمستقبِل (الأيونية، الهيدروجينية، الكارهة للماء، وفان دير فالس) والتنبؤ بتغيرات الألفة في علاقات SAR عبر تراكم الطاقة الحرة.\",\"en\":\"Evaluate non-covalent drug-receptor binding forces (ionic, H-bonding, hydrophobic, van der Waals) and predict SAR affinity shifts via free energy summation.\"},\"misconceptions\":[{\"tr\":\"Kovalent bağların her zaman en üstün ve arzu edilen ilaç-reseptör etkileşimi olduğu yanılgısı.\",\"ar\":\"الاعتقاد الخاطئ بأن الروابط التساهمية هي دوماً النمط الأمثل والأكثر تفضيلاً في تفاعل الدواء مع المستقبِل.\",\"en\":\"The misconception that covalent bonds are always the superior and most desirable drug-receptor interaction.\"},{\"tr\":\"Bireysel olarak zayıf olan kovalent olmayan bağların (2-7 kcal/mol) nanomolar (nM) afinite sağlayamayacağı varsayımı.\",\"ar\":\"الافتراض الخاطئ بأن الروابط غير التساهمية لضعفها الفردي عاجزة عن تحقيق ألفة ارتباط نانومولية (nM) عالية الإحكام.\",\"en\":\"The assumption that individually weak non-covalent bonds (2-7 kcal/mol) cannot produce nanomolar (nM) binding affinity.\"},{\"tr\":\"Hidrofobik etkileşimin karbon atomlarının birbirini manyetik gibi çekmesinden kaynaklandığı düşüncesi.\",\"ar\":\"الظن الخاطئ بأن التأثير الكاره للماء ينشأ من قوة تجاذب ذاتية بين ذرات الكربون كالجاذبية المغناطيسية.\",\"en\":\"The misconception that hydrophobic interactions arise from an intrinsic magnetic-like attraction between carbon atoms.\"}],\"sources\":[{\"file\":\"Fonksiyonel gruplar.pdf\",\"page\":2},{\"file\":\"Fonksiyonel gruplar.pdf\",\"page\":3},{\"file\":\"Fonksiyonel gruplar.pdf\",\"page\":5},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":4},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":7},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":8},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":14},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":15},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":24},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":25},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":33}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Foye's Principles of Medicinal Chemistry\",\"edition\":\"8th ed.\",\"topic\":\"Drug-Receptor Interactions and Non-Covalent Binding Forces\",\"chapter\":\"Chapter 2\",\"page\":\"25-38\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Wilson and Gisvold's Textbook of Organic Medicinal and Pharmaceutical Chemistry\",\"edition\":\"12th ed.\",\"topic\":\"Intermolecular Forces, Hydrogen Bonding, and Hydrophobic Interactions\",\"chapter\":\"Chapter 3\",\"page\":\"42-59\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"mc-mod2-les1-card1\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Non-Kovalent Bağ Enerjileri Hiyerarşisi\",\"prompt\":\"İlaç-reseptör etkileşiminde kovalent olmayan bağların güç sıralaması nasıldır?\",\"answer\":\"İyonik (5-10 kcal/mol) > Hidrojen bağı (2-7 kcal/mol) > İyon-dipol (1-5 kcal/mol) > Hidrofobik (0.5-2 kcal/mol) > Van der Waals (0.5-1 kcal/mol).\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod2-les1-card2\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Hidrofobik Etkileşimin Entropik Doğası\",\"prompt\":\"İlaç ve reseptörün apolar kısımlarının bir araya gelmesini sağlayan gerçek itici güç nedir?\",\"answer\":\"Apolar yüzeyleri saran düzenli klatrat su kafeslerinin yıkılması sonucu serbest kalan su moleküllerinin sistem entropisini artırmasıdır (+ΔS).\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod2-les1-card3\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Ester vs Amit Biyoizosterik Kararlılığı\",\"prompt\":\"Prokaindeki ester grubu amite dönüştürüldüğünde (prokainamid) etki süresi neden uzar?\",\"answer\":\"Amit bağı rezonans kararlılığı nedeniyle psödokolinesteraz enziminin nükleofilik hidrolizine dirençlidir; plazma yarılanma ömrü katbekat uzar.\",\"box\":1,\"intervalDays\":1}],\"steps\":[{\"id\":\"mc-mod2-les1-step-01\",\"stage\":\"hook\",\"stageIndex\":1,\"title\":{\"tr\":\"Klinik İkilem: Kovalent Tuzak Paradoksu\",\"ar\":\"معضلة سريرية: فخ الروابط التساهمية\",\"en\":\"Clinical Dilemma: The Covalent Trap Dilemma\"},\"prompt\":{\"tr\":\"Kovalent bağlar (50-150 kcal/mol) kopmaz güçtedir. Ancak ilaçların %95'i hedeflerine zayıf kovalent olmayan bağlarla bağlanır. Neden tüm ilaçları kalıcı kovalent bağ yapacak şekilde tasarlamıyoruz?\",\"ar\":\"تمتلك الروابط التساهمية (50-150 kcal/mol) قوة لا تنكسر. ومع ذلك ترتبط 95% من الأدوية بروابط غير تساهمية ضعيفة. لماذا لا نصمم جميع الأدوية بروابط تساهمية دائمة؟\",\"en\":\"Covalent bonds (50-150 kcal/mol) are unbreakable at body temperature. Yet 95% of drugs rely on weak non-covalent forces. Why don't chemists design all drugs to form permanent covalent bonds?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-1a\",\"text\":{\"tr\":\"Kalıcı kovalent bağlar reseptörü ömür boyu kilitler; doz ayarlanamaz, toksisite ve immünolojik aşırı duyarlılık (haptenleşme) riski fırlar.\",\"ar\":\"تحظر الروابط التساهمية الدائمة المستقبِل مدى الحياة؛ مما يمنع ضبط الجرعة ويرفع مخاطر التسمم والتحسس المناعي بشكل خطير.\",\"en\":\"Permanent covalent bonds lock targets irreversibly, preventing dose titration and triggering severe toxicity and immunological haptenization.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Kovalent bağın kırılması imkansızdır; etki yalnızca yeni reseptör senteziyle biter. Bu durum geri dönüşümsüz organ hasarına ve immün yanıtlara yol açar.\",\"ar\":\"صحيح! يستحيل كسر الرابطة التساهمية تلقائياً؛ ولا يزول التأثير إلا باصطناع مستقبِلات جديدة مما يهدد بنخر نسيجي دائم وتفاعلات مناعية.\",\"en\":\"Correct! Covalent bonds cannot dissociate spontaneously; effect termination requires de novo protein synthesis, creating high risks of toxicity.\"}},{\"id\":\"opt-1b\",\"text\":{\"tr\":\"Kovalent bağlar biyolojik ortamda saniyeler içinde su molekülleri tarafından kendiliğinden hidroliz edilir.\",\"ar\":\"تتفكك الروابط التساهمية تلقائياً في البيئة الحيوية بواسطة جزيئات الماء خلال ثوانٍ معدودة.\",\"en\":\"Covalent bonds are spontaneously hydrolyzed by ambient water molecules within seconds in biological fluids.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Kovalent bağlar 50-150 kcal/mol gibi devasa bir enerjiye sahiptir ve suyla kendiliğinden dakikalar içinde kopmaz.\",\"ar\":\"مغالطة: تمتلك الروابط التساهمية طاقة هائلة (50-150 kcal/mol) ولا يمكن للماء كسرها تلقائياً عند حرارة الجسم.\",\"en\":\"Misconception: Covalent bonds possess massive activation energies (50-150 kcal/mol) and do not spontaneously hydrolyze in water.\"}},{\"id\":\"opt-1c\",\"text\":{\"tr\":\"İnsan proteinlerinde kovalent bağ oluşturabilecek hiçbir nükleofilik amino asit grubu bulunmaz.\",\"ar\":\"تخلو بروتينات جسم الإنسان من أي مجموعات أمينية أليفة للنواة قادرة على تشكيل روابط تساهمية.\",\"en\":\"Human proteins contain zero nucleophilic amino acid residues capable of participating in covalent reactions.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Reseptör ve enzimlerde kovalent saldırı yapabilen nükleofilik Serin (-OH), Sistein (-SH) ve Lizin (-NH2) kalıntıları bolca bulunur.\",\"ar\":\"مغالطة: تعج البروتينات بمجموعات محبة للنواة نشطة مثل سيرين (-OH)، سيستئين (-SH)، ولايسين (-NH2).\",\"en\":\"Misconception: Enzymes and receptors are rich in reactive nucleophilic residues such as Serine (-OH), Cysteine (-SH), and Lysine (-NH2).\"}}]},\"config\":{\"options\":[{\"id\":\"opt-1a\",\"text\":\"Kalıcı kovalent bağlar reseptörü kilitler; doz ayarlanamaz ve toksisite fırlar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Reversibilite eksikliği toksisite doğurur.\"},{\"id\":\"opt-1b\",\"text\":\"Kovalent bağlar suda saniyeler içinde hidroliz olur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Kovalent bağlar aşırı kararlıdır.\"},{\"id\":\"opt-1c\",\"text\":\"İnsanda kovalent bağ yapacak amino asit yoktur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Ser, Cys, Lys nükleofilik kalıntılardır.\"}],\"revealedOutcome\":{\"tr\":\"Kovalent olmayan bağlar ilaca 'aç-kapa' esnekliği kazandırır; sinyal iletimi fizyolojik olarak sonlandırılabilir ve antagonistlerle yarışabilir.\",\"ar\":\"تمنح الروابط غير التساهمية الدواء مرونة ديناميكية عكوسة، مما يسمح بإنهاء الإشارة الحيوية في الوقت المناسب ومنافسة الضادات.\",\"en\":\"Non-covalent bonds provide dynamic on-off flexibility, allowing biological signals to terminate and enabling competitive antagonism.\"},\"explanation\":{\"tr\":\"Kovalent ilaçlar (organofosfatlar, azotlu hardallar) kalıcı inaktivasyon yapar. Çoğu ilaçta ise reversibilite ve güvenlik için non-kovalent bağlar tercih edilir (Slayt 4, 8, 9).\",\"ar\":\"تحدث الأدوية التساهمية حظرًا دائمًا. بينما تفضل الأدوية العلاجية الروابط غير التساهمية لتحقيق الأمان والعكوسية (شريحة 4، 8، 9).\",\"en\":\"Covalent drugs cause irreversible inactivation. For most therapies, non-covalent reversibility is essential for clinical safety.\"}},\"technicalTerms\":[{\"term\":\"kovalent bağ\",\"arContext\":\"الرابطة التساهمية\"},{\"term\":\"non-kovalent bağ\",\"arContext\":\"الرابطة غير التساهمية\"}],\"hints\":[{\"tr\":\"Bir ilacın reseptörüne ömür boyu yapışıp hiç ayrılmaması durumunda hastaya ne olur?\",\"ar\":\"ماذا يحدث للمريض إذا التصق الدواء بمستقبله إلى الأبد دون أي انفصال؟\",\"en\":\"What happens to a patient if a drug binds its target receptor permanently without ever releasing?\"},{\"tr\":\"Tersinir (reversible) bağlanma, ilacın vücuttan atılmasıyla etkinin sonlanmasını sağlar.\",\"ar\":\"الارتباط العكوس يضمن انتهاء التأثير الدوائي بمجرد تصفية الدواء من الجسم.\",\"en\":\"Reversible binding ensures pharmacological actions terminate naturally as drug concentration falls.\"},{\"tr\":\"Kovalent bağlar dozu geri almayı imkansız kılar; non-kovalent bağlar güvenli ve titre edilebilir tedavi sağlar.\",\"ar\":\"تجعل الروابط التساهمية التراجع عن الجرعة مستحيلاً؛ بينما تتيح الروابط غير التساهمية علاجاً آمناً قابلاً للمعايرة.\",\"en\":\"Covalent bonding makes dose titration impossible; non-covalent binding guarantees safe, titratable therapeutics.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":4},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":8},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":9}]},{\"id\":\"mc-mod2-les1-step-02\",\"stage\":\"question\",\"stageIndex\":2,\"title\":{\"tr\":\"Tahmin: Bireysel Zayıflık vs Toplamsal Güç\",\"ar\":\"توقع: الضعف الفردي مقابل القوة التراكمية\",\"en\":\"Prediction: Individual Weakness vs Cumulative Power\"},\"prompt\":{\"tr\":\"Bireysel bir hidrojen bağı yalnızca 2-7 kcal/mol enerji sağlarken, non-kovalent bir ilaç hedef reseptörüne nasıl pikomolar (pM) veya nanomolar (nM) düzeyinde sımsıkı tutunabilir?\",\"ar\":\"بينما تمنح الرابطة الهيدروجينية المنفردة 2-7 kcal/mol فقط، كيف يستطيع دواء غير تساهمي التشبث بمستقبله بقوة نانومولية (nM) أو بيكومولية (pM) فائقة الإحكام؟\",\"en\":\"An individual hydrogen bond yields only 2-7 kcal/mol. How can a non-covalent drug achieve nanomolar (nM) or picomolar (pM) binding affinity without forming covalent bonds?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-2a\",\"text\":{\"tr\":\"Çoklu non-kovalent temas noktalarının (iyonik, H-bağı, hidrofobik) serbest enerjileri toplanarak devasa bir toplam bağlanma serbest enerjisi (ΔG° = -12 kcal/mol) oluşturur.\",\"ar\":\"تتراكم الطاقات الحرة لنقاط التلامس المتعددة (أيونية، هيدروجينية، كارهة للماء) لتولد طاقة ارتباط كلية هائلة (ΔG° = -12 kcal/mol).\",\"en\":\"The free energies of multiple discrete non-covalent contacts (ionic, H-bonds, hydrophobic) sum together into a massive net binding free energy (ΔG° = -12 kcal/mol).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Termodinamik kural: ΔG°_toplam = Σ ΔG°_bireysel dir. 1 iyonik bağ, 2 hidrojen bağı ve hidrofobik temaslar bir araya gelince sub-nanomolar afinite doğar.\",\"ar\":\"صحيح! القاعدة الثرموديناميكية: ΔG°_الكلية = مجموع ΔG°_الفردية. باجتماع رابطة أيونية مع رابطتين هيدروجينيتين ومناطق كارهة للماء تتولد ألفة نانومولية مذهلة.\",\"en\":\"Correct! Thermodynamically, ΔG°_total = Σ ΔG°_individual. Combining an ionic anchor, 2 H-bonds, and hydrophobic surfaces yields sub-nanomolar affinity.\"}},{\"id\":\"opt-2b\",\"text\":{\"tr\":\"Reseptör proteini ilacı sarınca moleküler ağırlığı 10 katına çıkar ve kütle çekimiyle tutulur.\",\"ar\":\"عندما يحيط بروتين المستقبِل بالدواء يتضاعف وزنه الجزيئي 10 مرات فيثبت بقوى التجاذب الثقالي.\",\"en\":\"When the receptor protein envelops the drug, its molecular weight increases 10-fold, trapping it via gravitational mass attraction.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Moleküler ölçekte kütle çekimi sıfırdır; bağlanmayı yalnızca elektrostatik ve kuantum mekaniksel kuvvetler yönetir.\",\"ar\":\"مغالطة: قوى الجاذبية الثقالية مهملة تماماً على المستوى الجزيئي؛ والفيزياء الكهروستاتيكية هي الحاكمة حصراً.\",\"en\":\"Misconception: Gravitational forces are completely negligible at the molecular scale; binding is governed strictly by electrostatics and thermodynamics.\"}},{\"id\":\"opt-2c\",\"text\":{\"tr\":\"Nanomolar afinite yalnızca kovalent bağlarla mümkündür; non-kovalent ilaçlar daima mikromolar (µM) düzeyinde kalır.\",\"ar\":\"تقتصر الألفة النانومولية على الروابط التساهمية فقط؛ بينما تبقى الأدوية غير التساهمية دوماً في المدى الميكرومولي (µM).\",\"en\":\"Nanomolar affinity is strictly impossible without covalent bonds; non-covalent drugs never exceed micromolar (µM) affinity.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Çoğu klinik ilaç (örn. atorvastatin, fentanil) tamamen kovalent olmayan bağlarla sub-nanomolar afiniteye ulaşır.\",\"ar\":\"مغالطة: تحقق معظم الأدوية المعتمدة (مثل أتورفاستاتين وفنتانيل) ألفة دون النانومولية عبر روابط غير تساهمية بالكامل.\",\"en\":\"Misconception: Most potent clinical drugs (e.g. atorvastatin, fentanyl) achieve sub-nanomolar affinity purely through non-covalent networks.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-2a\",\"text\":\"Çoklu non-kovalent temas noktalarının serbest enerjileri toplanarak devasa afinite üretir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Bireysel bağ enerjileri toplanır.\"},{\"id\":\"opt-2b\",\"text\":\"Kütle çekimiyle tutulur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Moleküler düzeyde yerçekimi sıfırdır.\"},{\"id\":\"opt-2c\",\"text\":\"Nanomolar güç sadece kovalent bağla olur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Non-kovalent ağlar pikomolar afiniteye ulaşabilir.\"}],\"revealedOutcome\":{\"tr\":\"Bireysel zayıf bağlar sinerjik biçimde toplanır: 10-15 zayıf bağ birleştiğinde toplam bağlanma enerjisi -10 ila -15 kcal/mol e ulaşır (Kd = 0.1 nM).\",\"ar\":\"تتآزر الروابط الضعيفة تراكمياً: باجتماع 10-15 تماساً ضعيفاً تبلغ الطاقة الحرة -10 إلى -15 kcal/mol محققة ألفة نانومولية فائقة (Kd = 0.1 nM).\",\"en\":\"Individually weak contacts sum synergistically: 10-15 non-covalent interactions achieve net ΔG° = -10 to -15 kcal/mol (Kd = 0.1 nM).\"},\"explanation\":{\"tr\":\"Termodinamik formül: ΔG° = -RT ln(Ka) = 2.303 RT log10(Kd). Her -1.42 kcal/mol luk serbest enerji kazancı afiniteyi tam 10 kat artırır (Slayt 8, 34).\",\"ar\":\"المعادلة الثرموديناميكية: ΔG° = -RT ln(Ka). كل ربح مقداره -1.42 kcal/mol في الطاقة الحرة يضاعف الألفة بمقدار 10 مرات (شريحة 8، 34).\",\"en\":\"Thermodynamic relation: ΔG° = -RT ln(Ka). Every -1.42 kcal/mol increment in free energy enhances binding affinity by a full 10-fold order of magnitude.\"}},\"technicalTerms\":[{\"term\":\"serbest bağlanma enerjisi\",\"arContext\":\"طاقة الارتباط الحرة ΔG\"},{\"term\":\"afinite sabiti\",\"arContext\":\"ثابت الألفة Kd\"}],\"hints\":[{\"tr\":\"Tek bir iplik kolayca kopar; binlerce iplikten örülen bir halat kopar mı?\",\"ar\":\"يسهل قطع خيط منفرد؛ لكن هل ينقطع حبل مجدول من آلاف الخيوط بسهولة؟\",\"en\":\"A single thread snaps easily; does a thick rope woven from thousands of threads break?\"},{\"tr\":\"Termodinamikte bağımsız temas noktalarının serbest enerjileri (ΔG) cebirsel olarak toplanır.\",\"ar\":\"في الديناميكا الحرارية، تجمع الطاقات الحرة (ΔG) لنقاط التلامس المستقلة جبرياً.\",\"en\":\"In thermodynamics, free energies (ΔG) of independent contact points sum algebraically.\"},{\"tr\":\"İyonik, H-bağı ve hidrofobik enerjiler toplanarak -12 kcal/mol oluşturur ve nanomolar afinite sağlar.\",\"ar\":\"تتراكم طاقات الروابط الأيونية والهيدروجينية والكارهة للماء لتشكل -12 kcal/mol محققة ألفة نانومولية.\",\"en\":\"Summing ionic, H-bond, and hydrophobic contributions reaches -12 kcal/mol, unlocking nanomolar potency.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":8},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":33}]},{\"id\":\"mc-mod2-les1-step-03\",\"stage\":\"intuition\",\"stageIndex\":3,\"title\":{\"tr\":\"Sezgisel Model: Cırt Cırt (Velcro) vs Japon Yapıştırıcısı\",\"ar\":\"نموذج حدسي: شريط فيلكرو مقابل الغراء الخارق\",\"en\":\"Intuitive Model: Velcro vs Superglue\"},\"prompt\":{\"tr\":\"Kovalent bağ Japon yapıştırıcısı gibidir; tek noktadan yapışır ama sökmek yüzeyi yırtar. Non-kovalent bağlanma ise cırt cırt (Velcro) gibidir; yüzlerce minik kanca birleşince tutar, çekince iz bırakmadan ayrılır.\",\"ar\":\"الرابطة التساهمية كالغراء الخارق؛ تلتحم بنقطة واحدة لكن نزعها يدمر السطح. بينما الارتباط غير التساهمي كشريط فيلكرو؛ مئات الخطافات الدقيقة تمسك بإحكام وتنفصل عند السحب بنظافة.\",\"en\":\"Covalent binding is like superglue: unbreakable, but tearing it off destroys the surface. Non-covalent binding is like Velcro: hundreds of micro-hooks hold tightly together, yet peel off cleanly when needed.\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-3a\",\"text\":{\"tr\":\"Cırt cırt modeli, ilacın reseptörüne yüksek afinite ve seçicilikle tutunurken, gerektiğinde yan etki yaratmadan ayrılabilmesini (tersinirliği) açıklar.\",\"ar\":\"يفسر نموذج فيلكرو قدرة الدواء على التثبت بألفة ونوعية عاليتين، مع إمكانية الانفصال النظيف عكوسياً عند الحاجة.\",\"en\":\"The Velcro model explains how a drug achieves high affinity and stereoselectivity while retaining reversible dissociation to avoid toxicity.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz analoji kavrayışı! Velcro mekanizması hem yüksek tutunma kuvvetini hem de geri dönüşümlü (reversibl) ayrılabilmeyi mükemmel açıklar.\",\"ar\":\"فهم استثنائي للمقاربة! يجسد شريط فيلكرو كلاً من قوة التثبيت العالية والانفصال العكوس النظيف دون إتلاف الهدف.\",\"en\":\"Flawless analogical understanding! The Velcro model beautifully reconciles high multi-point binding affinity with reversible dissociation.\"}},{\"id\":\"opt-3b\",\"text\":{\"tr\":\"Japon yapıştırıcısı modeli, tüm tansiyon ve astım ilaçlarında hedeflenen ideal farmakolojik davranıştır.\",\"ar\":\"يمثل الغراء الخارق السلوك الدوائي المثالي المنشود في جميع أدوية الضغط والربو.\",\"en\":\"The superglue model represents the ideal pharmacological mechanism sought for all cardiovascular and asthma drugs.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Kalıcı yapışma tansiyon veya astım ilaçlarında ölümcül hipotansiyon veya bronkospazma yol açar; tersinir etki şarttır.\",\"ar\":\"مغالطة: الارتباط الدائم في أدوية الضغط يسبب هبوطاً دموياً قاتلاً؛ فالعكوسية شرط لا غنى عنه للأمان.\",\"en\":\"Misconception: Permanent target destruction in cardiovascular drugs causes fatal hypotension; reversible control is mandatory.\"}},{\"id\":\"opt-3c\",\"text\":{\"tr\":\"Cırt cırt kancaları reseptör proteinini parçalayarak geri dönüşümsüz inaktivasyona sebep olur.\",\"ar\":\"تقوم خطافات فيلكرو بتمزيق بروتين المستقبِل مسببة تثبيطاً غير عكوس.\",\"en\":\"Velcro hooks physically shred the receptor protein, inducing irreversible target destruction.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Non-kovalent bağlar proteini tahrip etmez; bağlar termal hareketle iz bırakmadan kendiliğinden açılır.\",\"ar\":\"مغالطة: الروابط غير التساهمية لا تتلف البروتين؛ وتتلاشى نقاط التلامس بالاهتزاز الحراري الطبيعي دون أي أثر.\",\"en\":\"Misconception: Non-covalent contacts cause zero covalent damage; complexes dissociate cleanly via thermal kinetic motion.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-3a\",\"text\":\"Cırt cırt modeli, yüksek afinite ile tersinir ayrılabilme dengesini açıklar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Çoklu temaslar sıkı tutar ama ayrılabilir.\"},{\"id\":\"opt-3b\",\"text\":\"Japon yapıştırıcısı tüm ilaçlarda idealdir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Kalıcı bağ kontrolsüz toksisite yaratır.\"},{\"id\":\"opt-3c\",\"text\":\"Cırt cırt reseptörü parçalar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Non-kovalent bağ proteini yırtmaz.\"}],\"revealedOutcome\":{\"tr\":\"Velcro ilkesi: İlaç ve reseptör birbirine binlerce nanometre karelik mikromimariyle uyar; temas kesilince reseptör orijinal haline döner.\",\"ar\":\"مبدأ فيلكرو: يتطابق الدواء والمستقبِل بهندسة جزيئية دقيقة؛ وعند زوال التلامس يعود المستقبِل لحالته الطبيعية الأصلية.\",\"en\":\"The Velcro principle: Drugs fit receptor pockets with complementary micromorphology; upon dissociation, targets return to baseline.\"},\"explanation\":{\"tr\":\"Reversibilite ilacın yarılanma ömrünü ve etki süresini yönetilebilir kılar. Vücut ilacı klerensle temizledikçe reseptör serbest kalır (Slayt 4, 8).\",\"ar\":\"تتيح العكوسية التحكم بعمر النصف ومدة التأثير الدوائي. ومع تصفية الجسم للدواء يستعيد المستقبِل حريته (شريحة 4، 8).\",\"en\":\"Reversibility allows drug action to terminate as plasma clearance reduces concentration, restoring receptor availability.\"}},\"technicalTerms\":[{\"term\":\"tersinir bağlanma\",\"arContext\":\"الارتباط العكوس\"},{\"term\":\"moleküler seçicilik\",\"arContext\":\"النوعية الجزيئية\"}],\"hints\":[{\"tr\":\"Cırt cırt bandının yüzlerce minik plastik kancasından tek birini çekmek ne kadar kolaydır?\",\"ar\":\"ما مدى سهولة نزع خطاف بلاستيكي واحد من شريط فيلكرو؟\",\"en\":\"How easy is it to pull open a single plastic micro-hook on a Velcro strip?\"},{\"tr\":\"Tek kanca zayıftır ama tüm şerit bastırıldığında ayırmak ciddi bir kuvvet gerektirir.\",\"ar\":\"الخطاف المنفرد ضعيف، لكن عند ضغط الشريط كاملاً يتطلب فصله قوة ملموسة.\",\"en\":\"One hook is weak, but hundreds pressed together require substantial energy to separate.\"},{\"tr\":\"Bu model, zayıf hidrojen bağlarının ve van der Waals temaslarının birleşerek nasıl nanomolar afinite ürettiğini açıklar.\",\"ar\":\"يفسر هذا كيف تتحد الروابط الهيدروجينية وقوى فان دير فالس لتوليد ألفة نانومولية هائلة.\",\"en\":\"This explains how weak H-bonds and van der Waals contacts combine to produce nanomolar target affinity.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":4},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":8}]},{\"id\":\"mc-mod2-les1-step-04\",\"stage\":\"visual_explanation\",\"stageIndex\":4,\"title\":{\"tr\":\"Görsel Mekanizma: 4 Temel Bağ Kuvveti Hiyerarşisi\",\"ar\":\"آلية بصرية: هرمية قوى الارتباط الأربع الأساسية\",\"en\":\"Visual Mechanism: The 4-Force Binding Hierarchy\"},\"prompt\":{\"tr\":\"İlaç-reseptör bağları güç sırasına göre dizilir: İyonik (5-10 kcal/mol, uzun menzilli 1/r²), Hidrojen bağı (2-7 kcal/mol, 180° yönlü), Hidrofobik (0.5-2 kcal/mol), van der Waals (0.5-1 kcal/mol, kısa menzilli 1/r⁶).\",\"ar\":\"تصنف قوى الارتباط حسب قوتها: الأيونية (5-10 kcal/mol، طويلة المدى 1/r²)، الهيدروجينية (2-7 kcal/mol، اتجاهية 180°)، الكارهة للماء (0.5-2 kcal/mol)، وفان دير فالس (0.5-1 kcal/mol، قصيرة المدى 1/r⁶).\",\"en\":\"Forces rank by strength: Ionic (5-10 kcal/mol, long-range 1/r²), Hydrogen bond (2-7 kcal/mol, strict 180° directionality), Hydrophobic (0.5-2 kcal/mol), and van der Waals (0.5-1 kcal/mol, short-range 1/r⁶).\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-4a\",\"text\":{\"tr\":\"İyonik bağ ilacı reseptör cebine uzaktan çeken ilk kılavuz güçtür; hidrojen bağı ise katı 180° açı geometrisiyle stereoseçiciliği kilitler.\",\"ar\":\"تمثل الرابطة الأيونية القوة الموجهة بعيدة المدى لسحب الدواء نحو الجيب، بينما تحسم الرابطة الهيدروجينية الانتقائية الفراغية بزاوية 180° الصارمة.\",\"en\":\"Ionic bonds act as long-range electrostatic guides drawing drugs into pockets, while hydrogen bonds lock stereoselective fit via rigid 180° geometry.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel! İyonik bağlar mesafenin karesiyle (1/r²) zayıflar ve ilacı uzaktan yakalar. Hidrojen bağı ise doğrusal (180°) olmadığında gücünün yarısını kaybeder; seçiciliğin efendisidir.\",\"ar\":\"رائع! تضعف القوى الأيونية مع مربع المسافة (1/r²) فتجذب الدواء من بعيد، بينما تفقد الرابطة الهيدروجينية نصف قوتها عند انحرافها عن 180° حاكمةً الانتقائية.\",\"en\":\"Superb! Ionic forces decay with 1/r², acting at distance. Hydrogen bonds lose >50% energy if deflected 30° from 180°, dictating stereoselective fit.\"}},{\"id\":\"opt-4b\",\"text\":{\"tr\":\"Van der Waals kuvvetleri en uzun menzilli kuvvettir ve ilacı 10 nanometre mesafeden yakalar.\",\"ar\":\"قوى فان دير فالس هي الأطول مدى وتلتقط الدواء من مسافة 10 نانومتر.\",\"en\":\"Van der Waals dispersion forces possess the longest operational range, capturing ligands from 10 nanometers away.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Van der Waals kuvvetleri mesafenin 6. kuvvetiyle (1/r⁶) aşırı hızlı söner; yalnızca atomlar birbirine temas ettiğinde (0.3-0.4 nm) devreye girer.\",\"ar\":\"مغالطة: تتلاشى قوى فان دير فالس مع القوة السادسة للمسافة (1/r⁶) بسرعة فائقة؛ ولا تعمل إلا عند التلامس المباشر (0.3-0.4 نانومتر).\",\"en\":\"Misconception: Van der Waals forces decay rapidly with 1/r⁶ and operate only at intimate contact distances (0.3-0.4 nm).\"}},{\"id\":\"opt-4c\",\"text\":{\"tr\":\"Hidrojen bağları tamamen yönsüzdür; donör ve akseptör atomlar herhangi bir açıyla eşit güçte bağlanır.\",\"ar\":\"الروابط الهيدروجينية غير اتجاهية بالكامل؛ وترتبط الذرات المانحة والآخذة بأي زاوية بنفس القوة.\",\"en\":\"Hydrogen bonds are strictly non-directional; donor and acceptor atoms bind with equal strength regardless of angle.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Hidrojen bağları son derece yönlüdür. Donör-H-Akseptör açısı 180° doğrultusunda olmadığında bağ dramatik biçimde zayıflar.\",\"ar\":\"مغالطة: الروابط الهيدروجينية اتجاهية بامتياز؛ وأي انحراف عن استقامة 180° بين المانح والبروتون والآخذ يضعف الرابطة بشدة.\",\"en\":\"Misconception: Hydrogen bonds are acutely directional; maximum orbital overlap requires a linear 180° geometry.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-4a\",\"text\":\"İyonik bağ uzaktan çeker; hidrojen bağı 180° açıyla seçiciliği kilitler.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Menzil ve yönlülük hiyerarşisi bağlanmayı yönetir.\"},{\"id\":\"opt-4b\",\"text\":\"Van der Waals en uzun menzilli kuvvettir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Van der Waals 1/r⁶ ile aşırı kısa menzillidir.\"},{\"id\":\"opt-4c\",\"text\":\"Hidrojen bağları yönsüzdür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: 180° açı geometrisi şarttır.\"}],\"revealedOutcome\":{\"tr\":\"Bağ korelasyonu: Uzun menzilli iyonik çekim ilacı cebe çeker; hidrofobik çöküş yerleştirir; yönlü hidrojen bağları ve van der Waals temasları seçiciliği kilitler.\",\"ar\":\"تكامل الروابط: الجذب الأيوني بعيد المدى يسحب الدواء، والانهيار الكاره للماء يثبته، وتراصف الروابط الهيدروجينية يحكم القفل النوعي.\",\"en\":\"Binding orchestration: Long-range ionic attraction steers the drug; hydrophobic collapse seats it; directional H-bonds lock selectivity.\"},\"explanation\":{\"tr\":\"Bağ enerjileri tablosu (Slayt 7, 14, 16, 24): İyonik (5-10 kcal/mol) > H-bağı (2-7 kcal/mol) > Hidrofobik (0.5-2 kcal/mol) > van der Waals (0.5-1 kcal/mol).\",\"ar\":\"جدول طاقات الروابط (شريحة 7، 14، 16، 24): أيونية (5-10) > هيدروجينية (2-7) > كارهة للماء (0.5-2) > فان دير فالس (0.5-1 kcal/mol).\",\"en\":\"Energy hierarchy: Ionic (5-10 kcal/mol) > H-bond (2-7 kcal/mol) > Hydrophobic (0.5-2 kcal/mol) > van der Waals (0.5-1 kcal/mol).\"}},\"technicalTerms\":[{\"term\":\"iyonik çekim menzili\",\"arContext\":\"مدى التجاذب الأيوني\"},{\"term\":\"hidrojen bağı yönlülüğü\",\"arContext\":\"اتجاهية الرابطة الهيدروجينية\"}],\"hints\":[{\"tr\":\"Farklı bağların mesafe bağımlılıklarını düşünün: 1/r² vs 1/r⁶.\",\"ar\":\"قارن اعتماد القوى المختلفة على المسافة: 1/r² مقابل 1/r⁶.\",\"en\":\"Consider distance dependence: 1/r² for Coulombic vs 1/r⁶ for dispersion forces.\"},{\"tr\":\"Hangi kuvvet en uzaktan çeker? Hangi kuvvet katı bir 180° açı geometrisi gerektirir?\",\"ar\":\"أي قوة تجذب من أبعد مسافة؟ وأي قوة تتطلب زاوية هندسية صارمة بـ 180 درجة؟\",\"en\":\"Which force pulls from the greatest distance? Which requires strict linear geometry?\"},{\"tr\":\"İyonik bağ uzun menzilli çekici kılavuzdur; hidrojen bağı 180° doğrusal açıyla stereoseçiciliği sağlar.\",\"ar\":\"الرابطة الأيونية دليل جاذب بعيد المدى؛ والرابطة الهيدروجينية باستقامة 180° تؤمن القفل الفراغي النوعي.\",\"en\":\"Ionic bonds steer drugs from distance; hydrogen bonds lock stereoselective fit via 180° alignment.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":7},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":14},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":16},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":24}]},{\"id\":\"mc-mod2-les1-step-05\",\"stage\":\"interactive_artifact\",\"stageIndex\":5,\"title\":{\"tr\":\"İnteraktif Simülatör: SAR Analizi ve Bağ Optimizasyonu\",\"ar\":\"محاكاة تفاعلية: استكشاف SAR وتحسين الروابط\",\"en\":\"Interactive Simulator: SAR Explorer & Binding Optimization\"},\"prompt\":{\"tr\":\"Simülatörde prokain iskeletinde R1 aromatik halka ve R2 amin gruplarını değiştirin. Hidrofobik kütle ve iyonik etkileşimin afiniteyi (Kd) nanomolar düzeye indirmesini izleyin.\",\"ar\":\"في المحاكي، عدل المجموعتين R1 و R2 على هيكل البروكائين. راقب كيف يؤدي التلامس الكاره للماء والأيوني إلى تعزيز الألفة (Kd) لتصل لمستوى النانومول.\",\"en\":\"In the simulator, swap R1 aromatic and R2 amine substituents on the procaine core. Observe how hydrophobic bulk and ionic anchors drive Kd into nanomolar potency.\"},\"predictThenReveal\":false,\"widgetType\":\"SarExplorer\",\"widget\":{\"type\":\"SarExplorer\",\"config\":{\"scaffoldName\":\"Lokal Anestezik Prokain Türevleri\",\"scaffoldDescription\":\"Sodyum kanalı vestibülünde hidrofobik ve iyonik temasları optimize ederek afiniteyi artırın.\",\"baseLogP\":1.9,\"basePka\":8.9,\"baseAffinityNm\":1200,\"positions\":[{\"positionName\":\"R1 (Aromatik para-sübstitüent)\",\"defaultOptionId\":\"r1-h\",\"options\":[{\"id\":\"r1-h\",\"name\":\"Hidrojen (-H)\",\"structureSnippet\":\"-H\",\"deltaLogP\":0,\"deltaPka\":0,\"affinityMultiplier\":1,\"toxicityRisk\":\"low\"},{\"id\":\"r1-nh2\",\"name\":\"Amino (-NH2, Prokain)\",\"structureSnippet\":\"-NH2\",\"deltaLogP\":-0.4,\"deltaPka\":0.1,\"affinityMultiplier\":4,\"toxicityRisk\":\"low\"},{\"id\":\"r1-butox\",\"name\":\"Butoksi (-O-C4H9, Dibukain tipi)\",\"structureSnippet\":\"-O-C4H9\",\"deltaLogP\":1.6,\"deltaPka\":0,\"affinityMultiplier\":25,\"toxicityRisk\":\"low\"}]},{\"positionName\":\"R2 (Terminal bazik amin)\",\"defaultOptionId\":\"r2-dimethyl\",\"options\":[{\"id\":\"r2-dimethyl\",\"name\":\"Dimetilamino (-N(CH3)2)\",\"structureSnippet\":\"-N(CH3)2\",\"deltaLogP\":0,\"deltaPka\":-0.2,\"affinityMultiplier\":1.5,\"toxicityRisk\":\"low\"},{\"id\":\"r2-diethyl\",\"name\":\"Dietilamino (-N(C2H5)2)\",\"structureSnippet\":\"-N(C2H5)2\",\"deltaLogP\":0.6,\"deltaPka\":0.2,\"affinityMultiplier\":5,\"toxicityRisk\":\"low\"}]}],\"targetGoal\":{\"description\":\"Kd <= 20 nM ve logP 2.5 - 4.0 aralığına ulaşın.\",\"minLogP\":2.5,\"maxLogP\":4,\"maxAffinityNm\":20,\"targetOptionIds\":[\"r1-butox\",\"r2-diethyl\"]},\"explanation\":\"Aromatik halkaya lipofilik butoksi zinciri ve bazik dietilamino grubu eklendiğinde hidrofobik ve iyonik bağlar sinerji oluşturur; Kd 1200 nM den 10 nM e iner.\",\"source\":{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":33}}},\"config\":{\"scaffoldName\":\"Lokal Anestezik Prokain Türevleri\",\"scaffoldDescription\":\"Sodyum kanalı vestibülünde hidrofobik ve iyonik temasları optimize ederek afiniteyi artırın.\",\"baseLogP\":1.9,\"basePka\":8.9,\"baseAffinityNm\":1200,\"positions\":[{\"positionName\":\"R1 (Aromatik para-sübstitüent)\",\"defaultOptionId\":\"r1-h\",\"options\":[{\"id\":\"r1-h\",\"name\":\"Hidrojen (-H)\",\"structureSnippet\":\"-H\",\"deltaLogP\":0,\"deltaPka\":0,\"affinityMultiplier\":1,\"toxicityRisk\":\"low\"},{\"id\":\"r1-nh2\",\"name\":\"Amino (-NH2, Prokain)\",\"structureSnippet\":\"-NH2\",\"deltaLogP\":-0.4,\"deltaPka\":0.1,\"affinityMultiplier\":4,\"toxicityRisk\":\"low\"},{\"id\":\"r1-butox\",\"name\":\"Butoksi (-O-C4H9, Dibukain tipi)\",\"structureSnippet\":\"-O-C4H9\",\"deltaLogP\":1.6,\"deltaPka\":0,\"affinityMultiplier\":25,\"toxicityRisk\":\"low\"}]},{\"positionName\":\"R2 (Terminal bazik amin)\",\"defaultOptionId\":\"r2-dimethyl\",\"options\":[{\"id\":\"r2-dimethyl\",\"name\":\"Dimetilamino (-N(CH3)2)\",\"structureSnippet\":\"-N(CH3)2\",\"deltaLogP\":0,\"deltaPka\":-0.2,\"affinityMultiplier\":1.5,\"toxicityRisk\":\"low\"},{\"id\":\"r2-diethyl\",\"name\":\"Dietilamino (-N(C2H5)2)\",\"structureSnippet\":\"-N(C2H5)2\",\"deltaLogP\":0.6,\"deltaPka\":0.2,\"affinityMultiplier\":5,\"toxicityRisk\":\"low\"}]}],\"targetGoal\":{\"description\":\"Kd <= 20 nM ve logP 2.5 - 4.0 aralığına ulaşın.\",\"minLogP\":2.5,\"maxLogP\":4,\"maxAffinityNm\":20,\"targetOptionIds\":[\"r1-butox\",\"r2-diethyl\"]},\"explanation\":\"Aromatik halkaya butoksi zinciri ve terminal dietilamin takıldığında hidrofobik ve iyonik bağlar sinerji kurarak Kd değerini 10 nM düzeyine çeker (Slayt 33).\",\"source\":{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":33}},\"technicalTerms\":[{\"term\":\"SAR optimizasyonu\",\"arContext\":\"تحسين علاقات البنية بالفعالية SAR\"},{\"term\":\"afinite çarpanı\",\"arContext\":\"مضاعف الألفة\"}],\"hints\":[{\"tr\":\"R1 konumuna butoksi zinciri takarak lipofilik cebi doldurun.\",\"ar\":\"ثبت سلسلة بوتوكسي في الموضع R1 لملء الجيب الكاره للماء.\",\"en\":\"Install the butoxy chain at R1 to engage the hydrophobic subpocket.\"},{\"tr\":\"R2 konumunda dietilamino grubunu seçerek aspartatla iyonik bağı güçlendirin.\",\"ar\":\"اختر ثنائي إيثيل أمين في R2 لتعزيز الرابطة الأيونية مع الأسبارتات.\",\"en\":\"Select diethylamine at R2 to optimize ionic anchoring with receptor aspartate.\"},{\"tr\":\"Butoksi (-O-C4H9) ve dietilamino (-N(Et)2) kombinasyonu afiniteyi 125 kat artırarak Kd yi 10 nM e düşürür.\",\"ar\":\"مزيج البوتوكسي وثنائي إيثيل أمين يضاعف الألفة 125 مرة ويهبط بـ Kd إلى 10 نانومول.\",\"en\":\"Combining butoxy (-O-C4H9) and diethylamino (-N(Et)2) boosts affinity 125-fold, achieving Kd = 10 nM.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":33}]},{\"id\":\"mc-mod2-les1-step-06\",\"stage\":\"guided_discovery\",\"stageIndex\":6,\"title\":{\"tr\":\"Rehberli Keşif: Hidrofobik Paradoks ve Su Entropisi\",\"ar\":\"استكشاف موجه: مفارقة كره الماء وإنتروبيا الماء\",\"en\":\"Guided Discovery: The Hydrophobic Paradox & Water Entropy\"},\"prompt\":{\"tr\":\"Karbon-karbon atomları birbirini kuvvetle çekmez. O halde apolar iki halkanın sulu ortamda birbirine sımsıkı yapışmasını sağlayan gerçek termodinamik itici güç nedir?\",\"ar\":\"لا تتجاذب ذرات الكربون فيما بينها بقوة. ما هي القوة الثرموديناميكية الحقيقية التي تدفع حلقتين غير قطبيتين للالتصاق بإحكام في وسط مائي؟\",\"en\":\"Carbon atoms have negligible intrinsic attraction for each other. What actual thermodynamic driving force glues two apolar rings together in an aqueous biological environment?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-6a\",\"text\":{\"tr\":\"Apolar yüzeyleri saran düzenli buzsu su kafeslerinin (klatrat) yıkılması ve serbest kalan suların sistem entropisini devasa artırmasıdır (ΔS > 0).\",\"ar\":\"انهيار أقفاص الماء الجليدية المنظمة (klatrat) المحيطة بالسطوح غير القطبية، وتحرر جزيئات الماء رافعةً إنتروبيا النظام بشدة (ΔS > 0).\",\"en\":\"The collapse of ordered, ice-like water clathrate cages surrounding apolar surfaces, releasing water molecules to massively increase entropy (ΔS > 0).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika bilimsel kavrayış! Hidrofobik etki karbonların çekimi değildir. Su molekülleri apolar yüzeyden kurtulup serbest faza geçince sistemin entropisi (düzensizliği) fırlar ve ΔG negatifleşir.\",\"ar\":\"استيعاب علمي باهر! التأثير الكاره للماء ليس تجاذباً كربونياً، بل تحرر جزيئات الماء من قيود الترتيب نحو العشوائية (ΔS > 0) مما يجعل ΔG سالبة.\",\"en\":\"Brilliant scientific deduction! The hydrophobic effect is not carbon attraction; it is driven by water molecules breaking free from rigid cages, surging entropy (+ΔS).\"}},{\"id\":\"opt-6b\",\"text\":{\"tr\":\"Karbon atomları arasında gizli bir kovalent rezonans bağı oluşmasıdır.\",\"ar\":\"تشكل رابطة رنينية تساهمية خفية بين ذرات الكربون.\",\"en\":\"The spontaneous formation of a hidden covalent resonance bond between non-polar carbon atoms.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Apolar gruplar arasında kovalent bağ kurulmaz; hidrofobik etkileşim tamamen entropik bir solvent fenomenidir.\",\"ar\":\"مغالطة: لا تتشكل أي روابط تساهمية بين المجموعات غير القطبية؛ فالظاهرة حركية إنتروبية للمذيب حصراً.\",\"en\":\"Misconception: No covalent bonds form; the hydrophobic effect is purely an entropic solvent phenomenon.\"}},{\"id\":\"opt-6c\",\"text\":{\"tr\":\"Suyun dielektrik sabitinin sıfıra inerek karbonları manyetik gibi birbirine itmesidir.\",\"ar\":\"هبوط ثابت عزل الماء للصفر مما يدفع ذرات الكربون للتجاذب كالمغناطيس.\",\"en\":\"Water's dielectric constant dropping to zero, magnetically forcing carbon rings into contact.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Suyun dielektrik sabiti 80 dir ve sıfıra inmez; etkileşim elektriksel itme değil termodinamik düzensizlik kazancıdır.\",\"ar\":\"مغالطة: ثابت عزل الماء مرتفع (80) ولا يهبط للصفر؛ والقوة الدافعة هي ربح العشوائية الثرموديناميكية وليست قوى مغناطيسية.\",\"en\":\"Misconception: Bulk water retains its high dielectric constant (~80); the driving force is thermodynamic entropy gain, not dielectric collapse.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-6a\",\"text\":\"Buzsu su kafeslerinin (klatrat) yıkılması ve suyun entropisini artırmasıdır (ΔS > 0).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Hidrofobik etki entropik bir su olayıdır.\"},{\"id\":\"opt-6b\",\"text\":\"Karbonlar arası kovalent rezonanstır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Kovalent bağ kurulmaz.\"},{\"id\":\"opt-6c\",\"text\":\"Dielektrik sabiti sıfıra iner.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Su dielektrik sabiti sabittir.\"}],\"revealedOutcome\":{\"tr\":\"Hidrofobik etki itici gücü: İki nonpolar yüzey birleştiğinde su molekülleri klatrat kafesinden kurtulur; termodinamik serbest enerji ΔG = ΔH - TΔS gereği hızla negatifleşir.\",\"ar\":\"المحرك الكاره للماء: بتلاصق السطوح غير القطبية تتحرر جزيئات الماء المنظمة؛ وتتحول الطاقة الحرة ΔG = ΔH - TΔS إلى سالبة بعفوية.\",\"en\":\"Hydrophobic driving engine: As apolar surfaces bury, clathrate water is liberated; binding free energy turns negative via ΔG = ΔH - TΔS.\"},\"explanation\":{\"tr\":\"Apolar gruplar suda çözünemez çünkü etraflarında su aşırı düzenli klatrat kafesleri kurar (ΔS < 0). İlaç reseptöre oturunca su serbest kalır ve entropi artar (ΔS > 0) (Slayt 25).\",\"ar\":\"يعجز الكربون عن الذوبان لأن الماء يحاصره بأقفاص جليدية منظمة (ΔS < 0). وبتثبت الدواء يتحرر الماء لترتفع الإنتروبيا (ΔS > 0) (شريحة 25).\",\"en\":\"Non-polar groups force surrounding water into ordered clathrates (ΔS < 0). Desolvation releases trapped water, driving binding via entropy gain (+ΔS).\"}},\"technicalTerms\":[{\"term\":\"klatrat kafesi\",\"arContext\":\"قفص الكلاثرات المائي\"},{\"term\":\"hidrofobik entropi\",\"arContext\":\"إنتروبيا كره الماء\"}],\"hints\":[{\"tr\":\"Apolar bir yağ damlası suya konduğunda su molekülleri yağın etrafında nasıl dizilir?\",\"ar\":\"عند وضع قطرة زيت في الماء، كيف تنتظم جزيئات الماء حول سطح الزيت؟\",\"en\":\"When an oil drop enters water, how do surrounding water molecules arrange themselves?\"},{\"tr\":\"Su molekülleri hareket özgürlüklerini kaybedip buz benzeri düzenli bir kılıf (klatrat) kurar.\",\"ar\":\"تفقد جزيئات الماء حرية حركتها مشكلة غلافاً جليدياً مفرط التنظيم (klatrat).\",\"en\":\"Water molecules lose rotational freedom to form highly ordered, rigid clathrate cages.\"},{\"tr\":\"İlaç reseptör cebine oturunca bu sular serbest faza kaçar; entropi (ΔS) artar ve bağlanmayı sürükler.\",\"ar\":\"بدخول الدواء جيب المستقبِل تتحرر هذه المياه نحو الوسط؛ فتزداد الإنتروبيا (ΔS) دافعة الارتباط.\",\"en\":\"Binding releases ordered water into bulk solvent, surging entropy (+ΔS) and thermodynamically driving complexation.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":25}]},{\"id\":\"mc-mod2-les1-step-07\",\"stage\":\"formal_explanation\",\"stageIndex\":7,\"title\":{\"tr\":\"Matematiksel Model: Serbest Enerji Toplamı ve Kd\",\"ar\":\"النموذج الرياضي: تراكم الطاقة الحرة وحساب Kd\",\"en\":\"Mathematical Model: Free Energy Summation & Kd\"},\"prompt\":{\"tr\":\"Bir ilaç reseptörle 1 iyonik (-5 kcal/mol), 2 hidrojen bağı (-3 kcal/mol her biri) ve hidrofobik temas (-3 kcal/mol) kuruyor. Toplam ΔG° ve Kd nedir? (ΔG° = -RT ln Ka).\",\"ar\":\"يشكل دواء مع مستقبله: رابطة أيونية (-5 kcal/mol)، رابطتين هيدروجينيتين (-3 لكل منهما)، وتماساً كارهاً للماء (-3). ما هي ΔG° الكلية و Kd؟ (ΔG° = -RT ln Ka).\",\"en\":\"A drug forms 1 ionic bond (-5 kcal/mol), 2 H-bonds (-3 kcal/mol each), and hydrophobic contacts (-3 kcal/mol). What is total ΔG° and Kd? (ΔG° = -RT ln Ka).\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-7a\",\"text\":{\"tr\":\"ΔG° = -14 kcal/mol dür; 37°C de her -1.42 kcal/mol afiniteyi 10 kat artırdığı için Kd ≈ 0.1 nM (sub-nanomolar) düzeyinde süper afinite üretir.\",\"ar\":\"ΔG° = -14 kcal/mol؛ وبما أن كل -1.42 kcal/mol تضاعف الألفة 10 مرات عند 37°C، تنتج ألفة فائقة بحدود Kd ≈ 0.1 nM (دون النانومول).\",\"en\":\"ΔG° = -14 kcal/mol; since every -1.42 kcal/mol enhances affinity by 10-fold at 37°C, Kd reaches ~0.1 nM (sub-nanomolar potency).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Matematiksel olarak kusursuz! ΔG° = -5 + 2(-3) + (-3) = -14 kcal/mol. Log10(Ka) = 14 / 1.42 ≈ 9.86; Kd = 1/Ka ≈ 1.4 x 10^-10 M (0.14 nM).\",\"ar\":\"حساب رياضي متقن! ΔG° = -5 + 2(-3) + (-3) = -14 kcal/mol. وبقسمتها على 1.42 ينتج Log10(Ka) ≈ 9.86؛ أي Kd ≈ 0.14 نانومول.\",\"en\":\"Flawless mathematical deduction! ΔG° = -5 - 6 - 3 = -14 kcal/mol. Dividing by 1.42 kcal/mol yields log10(Ka) ~ 9.9, so Kd ~ 0.14 nM.\"}},{\"id\":\"opt-7b\",\"text\":{\"tr\":\"ΔG° = -5 kcal/mol dür; çünkü sadece en güçlü olan iyonik bağ hesaba katılır, zayıf bağlar ihmal edilir.\",\"ar\":\"ΔG° = -5 kcal/mol؛ لأن الرابطة الأيونية الأقوى هي التي تحسب فقط وتُهمل الروابط الضعيفة.\",\"en\":\"ΔG° = -5 kcal/mol; only the strongest ionic bond counts, while weaker non-covalent forces are ignored.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Termodinamikte tüm eşzamanlı temasların serbest enerjileri toplanır; zayıf bağlar ihmal edilemez.\",\"ar\":\"مغالطة: في الديناميكا الحرارية تجمع كافة الطاقات الحرة المتزامنة ولا يجوز إهمال أي تلامس.\",\"en\":\"Misconception: In binding thermodynamics, all simultaneous contacts contribute additively to net free energy.\"}},{\"id\":\"opt-7c\",\"text\":{\"tr\":\"ΔG° pozitif (+14 kcal/mol) çıkar; ilaç reseptöre spontan olarak bağlanamaz.\",\"ar\":\"تكون ΔG° موجبة (+14 kcal/mol)؛ وبالتالي لا يمكن للدواء الارتباط بالمستقبِل بعفوية.\",\"en\":\"ΔG° is positive (+14 kcal/mol); the drug cannot bind the receptor spontaneously.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Kararlı bağ oluşumu dışarıya enerji verir (ekzotermik/ekzergonik); bu nedenle bağlanma serbest enerjisi daima negatiftir (ΔG° < 0).\",\"ar\":\"مغالطة: تشكيل الروابط المستقرة يحرر طاقة حرة؛ لذا تكون طاقة الارتباط سالبة دوماً (ΔG° < 0) في المركبات التلقائية.\",\"en\":\"Misconception: Spontaneous stable complex formation releases free energy; binding ΔG° is always negative.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-7a\",\"text\":\"ΔG° = -14 kcal/mol; sub-nanomolar afinite (Kd ≈ 0.1 nM) üretir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Bireysel enerjiler toplanıp Kd yi belirler.\"},{\"id\":\"opt-7b\",\"text\":\"ΔG° = -5 kcal/mol; zayıf bağlar ihmal edilir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Tüm temaslar kümülatif katkı sağlar.\"},{\"id\":\"opt-7c\",\"text\":\"ΔG° pozitiftir (+14 kcal/mol).\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Bağlanma ekzergoniktir (ΔG < 0).\"}],\"revealedOutcome\":{\"tr\":\"Kümülatif afinite: ΔG° = -14 kcal/mol serbest enerjisi, Kütle Hareketi Kanununa göre Kd = 0.14 nM gibi olağanüstü yüksek bir bağlanma gücü oluşturur.\",\"ar\":\"الألفة التراكمية: طاقة حرة قدرها ΔG° = -14 kcal/mol تحقق ألفة ارتباط فائقة بمقدار Kd = 0.14 نانومول وفق قانون فعل الكتلة.\",\"en\":\"Cumulative potency: Net ΔG° = -14 kcal/mol yields an exceptional binding constant of Kd = 0.14 nM via the Law of Mass Action.\"},\"explanation\":{\"tr\":\"Toplam ΔG° = -5 + 2(-3) + (-3) = -14 kcal/mol. 37°C de (310 K) ΔG° = -1.42 log10(Ka) dır. log10(Ka) = 9.86 => Kd = 1.4 x 10^-10 M (Slayt 8, 34).\",\"ar\":\"المجموع: ΔG° = -5 + 2(-3) + (-3) = -14 kcal/mol. عند 37 مئوية ΔG° = -1.42 log10(Ka). ينتج log10(Ka) = 9.86 أي Kd = 1.4 x 10^-10 M (شريحة 8، 34).\",\"en\":\"Total ΔG° = -5 + 2(-3) + (-3) = -14 kcal/mol. At 310 K, ΔG° = -1.42 log10(Ka), giving log10(Ka) = 9.86, or Kd = 0.14 nM.\"}},\"technicalTerms\":[{\"term\":\"termodinamik toplam\",\"arContext\":\"المجموع الثرموديناميكي\"},{\"term\":\"denge sabiti Ka\",\"arContext\":\"ثابت التوازن Ka\"}],\"hints\":[{\"tr\":\"Verilen tüm bağ enerjilerini cebirsel olarak toplayın: (-5) + 2x(-3) + (-3) = ?\",\"ar\":\"اجمع كافة طاقات الروابط المعطاة جبرياً: (-5) + 2×(-3) + (-3) = ؟\",\"en\":\"Sum all given binding free energies algebraically: (-5) + 2x(-3) + (-3) = ?\"},{\"tr\":\"Toplam serbest enerji -14 kcal/mol dür.\",\"ar\":\"تبلغ الطاقة الحرة الإجمالية الناتجة -14 kcal/mol.\",\"en\":\"The total binding free energy sums to -14 kcal/mol.\"},{\"tr\":\"Fizyolojik sıcaklıkta her -1.42 kcal/mol Ka yı 10 kat artırır; -14 kcal/mol Kd yi 0.1 nM seviyesine çeker.\",\"ar\":\"عند حرارة الجسم يضاعف كل -1.42 kcal/mol الألفة 10 مرات؛ فتصل Kd مع -14 kcal/mol لمستوى 0.1 نانومول.\",\"en\":\"At 37°C, every -1.42 kcal/mol multiplies Ka 10-fold; -14 kcal/mol drives Kd down to ~0.1 nM.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":8},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":33}]},{\"id\":\"mc-mod2-les1-step-08\",\"stage\":\"concept_check\",\"stageIndex\":8,\"title\":{\"tr\":\"Kavram Kontrolü: Fenolün Metilasyonu (-OH -> -OCH3)\",\"ar\":\"فحص المفهوم: ميثلة الفينول (-OH -> -OCH3)\",\"en\":\"Concept Check: Phenol Methylation (-OH -> -OCH3)\"},\"prompt\":{\"tr\":\"Bir ilacın fenolik -OH grubu reseptördeki bir serin karboniline hidrojen bağı donörü (vericisi) olarak bağlanmaktadır. Bu grup metillenip anisol (-OCH3) yapılırsa afinite nasıl değişir?\",\"ar\":\"ترتبط مجموعة -OH الفينولية في دواء كمانح لرابطة هيدروجينية مع كربونيل السيرين. إذا تمت ميثلة المجموعة إلى ميثوكسي (-OCH3)، كيف تتأثر ألفة الدواء؟\",\"en\":\"A drug's phenolic -OH acts as a critical hydrogen bond donor to a receptor carbonyl. If this group is methylated to an ether (-OCH3), what happens to binding affinity?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-8a\",\"text\":{\"tr\":\"Eter oksijeninde asidik hidrojen atomu bulunmadığından donör özelliği tamamen yok olur; H-bağı kopar ve afinite 10 ila 100 kat birden düşer.\",\"ar\":\"يخلو أكسجين الإيثر من أي هيدروجين قطبي مانح؛ فتفقد المجموعة قدرتها كمانح للرابطة وتهبط الألفة بمقدار 10 إلى 100 ضعف.\",\"en\":\"Ether oxygens lack polar hydrogen atoms and cannot act as H-bond donors; the critical bond is lost, dropping affinity by 10- to 100-fold.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Tebrikler! Alkol ve fenoller hem donör (HBD) hem akseptördür (HBA). Eterler (-OCH3) ise yalnızca akseptördür (HBA); donör olamazlar. Karbonil de akseptör olduğundan iki akseptör birbirini iter.\",\"ar\":\"تهانينا! الفينولات مانحة وآخذة في آن واحد. بينما الإيثرات (-OCH3) آخذة فقط ولا تمنح؛ وبما أن الكربونيل آخذ أيضاً، يتنافر الآخذان وتفقد الرابطة.\",\"en\":\"Congratulations! Phenols are both donors and acceptors. Ethers are solely acceptors; since carbonyls are also acceptors, donor loss abolishes binding.\"}},{\"id\":\"opt-8b\",\"text\":{\"tr\":\"Metil grubu elektron sağladığı için hidrojen bağı iki kat güçlenir ve afinite artar.\",\"ar\":\"تقدم مجموعة الميثيل كثافة إلكترونية تضاعف قوة الرابطة الهيدروجينية وترفع الألفة.\",\"en\":\"The methyl group donates electron density, doubling the strength of the hydrogen bond and increasing affinity.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Ortada bağ yapacak bir hidrojen atomu kalmamıştır (-OCH3); olmayan hidrojen bağı güçlenemez.\",\"ar\":\"مغالطة: لم يعد هناك أي ذرة هيدروجين قطبية لتصنع الرابطة أصلاً؛ فلا يمكن تقوية رابطة تلاشت.\",\"en\":\"Misconception: There is no longer a polar hydrogen atom on the oxygen; a non-existent hydrogen bond cannot be strengthened.\"}},{\"id\":\"opt-8c\",\"text\":{\"tr\":\"Eterler fenollerle tamamen aynı hidrojen bağlama kapasitesine sahiptir; afinite değişmez.\",\"ar\":\"تمتلك الإيثرات نفس قدرة الفينول تماماً على تشكيل الروابط الهيدروجينية؛ ولا تتغير الألفة.\",\"en\":\"Ethers possess identical hydrogen-bonding capacity to phenols; binding affinity remains entirely unchanged.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Donör (HBD) ile Akseptör (HBA) farkını kaçırdınız. Eter donör olamaz.\",\"ar\":\"مغالطة: خلطت بين المانح (HBD) والآخذ (HBA). الإيثر عاجز عن القيام بدور المانح.\",\"en\":\"Misconception: Conflating H-bond donors with acceptors. Ethers can only accept, never donate.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-8a\",\"text\":\"Eterde donör hidrojen yoktur; bağ kopar ve afinite 10-100 kat düşer.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! -OCH3 donör olamaz.\"},{\"id\":\"opt-8b\",\"text\":\"Metil grubu bağı güçlendirir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Donör hidrojen kaybolmuştur.\"},{\"id\":\"opt-8c\",\"text\":\"Eter ve fenol aynı bağlanır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Eter donör olamaz.\"}],\"revealedOutcome\":{\"tr\":\"Donör kaybı: -OH grubu hem donör hem akseptördür. -OCH3 grubunda donör hidrojen kalmadığı için serin karboniliyle H-bağı kurulamaz; afinite çöker.\",\"ar\":\"فقدان المانح: مجموعة -OH مانحة وآخذة معاً. أما -OCH3 فخالية من هيدروجين المنح؛ فتعجز عن الارتباط بكربونيل السيرين وتنهار الألفة.\",\"en\":\"Donor loss: -OH is both donor and acceptor. Methylating to -OCH3 removes the donor proton, abolishing the contact with receptor carbonyl.\"},\"explanation\":{\"tr\":\"Fonksiyonel gruplar slayt 3 ve 5: Fenoller HBD + HBA dır. Eterler yalnızca HBA dır. Reseptör partneri C=O (HBA) olduğundan donör eksikliği bağı yok eder.\",\"ar\":\"المجموعات الوظيفية شريحة 3 و 5: الفينول HBD + HBA؛ بينما الإيثر HBA فقط. ولما كان الشريك C=O آخذاً HBA، يتلاشى الارتباط لغياب المانح.\",\"en\":\"Functional groups slides 3 & 5: Phenols are HBD + HBA; ethers are HBA only. Pairing two acceptors (ether O and carbonyl C=O) causes repulsion.\"}},\"technicalTerms\":[{\"term\":\"H-bağı donörü\",\"arContext\":\"مانح الرابطة الهيدروجينية HBD\"},{\"term\":\"H-bağı akseptörü\",\"arContext\":\"آخذ الرابطة الهيدروجينية HBA\"}],\"hints\":[{\"tr\":\"Fenol (-OH) ile metil eter (-OCH3) arasındaki fark nedir? Hangi atom eksildi?\",\"ar\":\"ما الفارق البنيوي بين الفينول (-OH) وإيثر الميثيل (-OCH3)؟ أي ذرة اختفت؟\",\"en\":\"What is the structural difference between a phenol (-OH) and a methyl ether (-OCH3)?\"},{\"tr\":\"Oksijene bağlı hidrojen atomu metil ile değiştirildiğinde donör (verici) hidrojen kalır mı?\",\"ar\":\"عند استبدال الهيدروجين المرتبط بالأكسجين بمجموعة ميثيل، هل يتبقى هيدروجين مانح؟\",\"en\":\"When the hydroxyl hydrogen is replaced with methyl, does a donor proton remain?\"},{\"tr\":\"Eter oksijeni donör olamaz; serin karbonili de alıcıdır. İki alıcı birbirine hidrojen bağı yapamaz.\",\"ar\":\"أكسجين الإيثر آخذ فقط؛ وكربونيل السيرين آخذ أيضاً. لا يمكن لآخذين تشكيل رابطة هيدروجينية.\",\"en\":\"Ether oxygen cannot donate; receptor carbonyl is also an acceptor. Two acceptors cannot form a hydrogen bond.\"}],\"sources\":[{\"file\":\"Fonksiyonel gruplar.pdf\",\"page\":3},{\"file\":\"Fonksiyonel gruplar.pdf\",\"page\":5},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":15}]},{\"id\":\"mc-mod2-les1-step-09\",\"stage\":\"application\",\"stageIndex\":9,\"title\":{\"tr\":\"Klinik Vaka: Dibukain Çok Noktalı Kenetlenmesi\",\"ar\":\"حالة سريرية: الالتحام متعدد النقاط للـ Dibucaine\",\"en\":\"Clinical Case: Dibucaine Multi-Anchor Vestibular Binding\"},\"prompt\":{\"tr\":\"Dibukain en güçlü ve en uzun etkili lokal anesteziktir. Kinolin halkası, butoksi zinciri, amit bağı ve tersiyer amini sodyum kanalı vestibülüne aynı anda nasıl kenetlenir?\",\"ar\":\"يعتبر <span dir='ltr'>dibucaine</span> من أقوى المخدرات الموضعية وأطولها تأثيراً. كيف تلتحم حلقة الكينولين، وسلسلة البوتوكسي، ورابطة الأميد، والأمين الثالثي في قناة الصوديوم بالتزامن؟\",\"en\":\"Dibucaine is an extraordinarily potent, long-acting local anesthetic. How do its quinoline ring, butoxy chain, amide group, and tertiary amine simultaneously anchor into the sodium channel?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-9a\",\"text\":{\"tr\":\"Kinolin aromatik π-istiflenmesi, butoksi hidrofobik cep, amit hidrojen bağı ve protonlanmış amin aspartatla iyonik bağ kurarak 4 noktadan kenetlenir.\",\"ar\":\"يرتبط الكينولين بتراصف π، والبوتوكسي بالجيب الكاره للماء، والأميد بالرابطة الهيدروجينية، والأمين المتأين برابطة أيونية مع الأسبارتات عبر 4 نقاط التحام.\",\"en\":\"Quinoline forms aromatic π-π stacking, butoxy buries into a hydrophobic trench, amide hydrogen bonds, and protonated amine forms an ionic salt bridge with aspartate.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika klinik SAR sentezi! Dibukain bu 4 farklı bağ kuvvetini aynı anda koordine ettiği için prokainden 20 kat daha güçlü ve uzun etkilidir.\",\"ar\":\"تحليل سريري مبهر! لتنسيق دواء Dibucaine هذه القوى الأربع بالتزامن، يفوق البروكائين بـ 20 ضعفاً في القوة والمدة.\",\"en\":\"Superb clinical SAR synthesis! Because dibucaine coordinates all 4 forces simultaneously, it is 20 times more potent and longer-acting than procaine.\"}},{\"id\":\"opt-9b\",\"text\":{\"tr\":\"Dibukain sodyum kanalındaki sistein kalıntılarına kovalent bağlanarak kanalı kalıcı olarak yok eder.\",\"ar\":\"يرتبط الدواء بروابط تساهمية مع ثيول السيستئين في قناة الصوديوم مدمراً القناة نهائياً.\",\"en\":\"Dibucaine binds covalently to cysteine residues, permanently destroying the voltage-gated sodium channel.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Dibukain kovalent bir toksin değildir; etkisi sodyum kanallarını tahrip etmeden tamamen tersinir biçimde sonlanır.\",\"ar\":\"مغالطة: ليس الديبوكائين مركباً تساهمياً ساماً؛ بل ينتهي تأثيره التخديري عكوسياً دون أي تخريب هيكلي للقناة.\",\"en\":\"Misconception: Dibucaine is not a covalent alkylating toxin; its block is potent but completely reversible.\"}},{\"id\":\"opt-9c\",\"text\":{\"tr\":\"Yalnızca tersiyer amin etkilidir; kinolin ve butoksi grupları reseptör dışına bakar ve bağlanmaya katılmaz.\",\"ar\":\"الأمين الثالثي هو الفعال حصراً؛ بينما تتجه حلقة الكينولين والبوتوكسي لخارج المستقبِل دون مساهمة.\",\"en\":\"Only the tertiary amine participates in binding; the quinoline and butoxy groups project outward into empty solvent.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Kinolin ve butoksi grupları kesilirse afinite 100 kat düşer; bu lipofilik gruplar bağlanma enerjisinin yarısını sağlar.\",\"ar\":\"مغالطة: إزالة الكينولين أو البوتوكسي تسقط الألفة بمئة ضعف؛ فهذه المجموعات تؤمن نصف طاقة الارتباط الحرة.\",\"en\":\"Misconception: Truncating the quinoline or butoxy groups drops affinity 100-fold; they provide half of the total binding energy.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-9a\",\"text\":\"Kinolin π-istiflenmesi, butoksi hidrofobik, amit H-bağı ve amin iyonik bağ kurar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! 4 noktalı kenetlenme devasa afinite sağlar.\"},{\"id\":\"opt-9b\",\"text\":\"Sodyum kanalına kovalent bağlanır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Dibukain kovalent bağ yapmaz.\"},{\"id\":\"opt-9c\",\"text\":\"Yalnızca tersiyer amin bağlanır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Kinolin ve butoksi afinitenin yarısını üretir.\"}],\"revealedOutcome\":{\"tr\":\"Çok noktalı kenetlenme: Dibukain farmakoforu kinolin (π-istiflenme), butoksi (hidrofobik kılıf), amit (H-bağı) ve amin (iyonik tuz köprüsü) ile sodyum kanalını bloke eder.\",\"ar\":\"الالتحام متعدد النقاط: يثبت فارماكوفور الديبوكائين نفسه عبر كينولين (تراصف π)، وبوتوكسي (كاره للماء)، وأميد (رابطة H)، وأمين (جسر ملحي أيوني).\",\"en\":\"Multi-anchor pharmacophore: Dibucaine coordinates quinoline (π-stacking), butoxy (hydrophobic), amide (H-bond), and amine (ionic bridge).\"},\"explanation\":{\"tr\":\"Slayt 33 vaka analizi: Dibukainin 4 fonksiyonel grubu reseptörün 4 farklı alt bölgesine tam geometrik uyum gösterir; bu durum ona en yüksek lokal anestezik gücü kazandırır.\",\"ar\":\"تحليل حالة الشريحة 33: تتطابق مجموعات الديبوكائين الأربع هندسياً مع 4 جيوب فرعية في المستقبِل؛ مما يمنحه أعلى فعالية تخدير موضعي.\",\"en\":\"Slide 33 case analysis: Dibucaine's 4 functional groups fit 4 distinct receptor subpockets with geometric precision, conferring top-tier clinical potency.\"}},\"technicalTerms\":[{\"term\":\"farmakofor kenetlenmesi\",\"arContext\":\"التحام الفارماكوفور\"},{\"term\":\"π-istiflenmesi\",\"arContext\":\"تراصف أوربيتالات π\"}],\"hints\":[{\"tr\":\"Dibukain molekülündeki 4 farklı kimyasal parçayı inceleyin: Kinolin, butoksi, amit ve bazik amin.\",\"ar\":\"تفحص الأجزاء الكيميائية الأربعة في جزيء الديبوكائين: كينولين، بوتوكسي، أميد، وأمين قاعدي.\",\"en\":\"Inspect the 4 structural components of dibucaine: quinoline ring, butoxy chain, amide, and basic amine.\"},{\"tr\":\"Her grup hangi non-kovalent bağ türünü kurabilir? Aromatik halka? Alkil zinciri? Karbonil? Katyon?\",\"ar\":\"ما نوع الرابطة التي تقدمها كل مجموعة؟ حلقة عطرية؟ سلسلة ألكيلية؟ كربونيل؟ وكاتيون؟\",\"en\":\"What bond type can each group form? Aromatic ring? Alkyl chain? Carbonyl? Cation?\"},{\"tr\":\"Kinolin π-π, butoksi hidrofobik, amit H-bağı ve amin iyonik bağ yaparak kanalı 4 koldan kilitler.\",\"ar\":\"يقدم الكينولين تراصف π، والبوتوكسي تماساً كارهاً للماء، والأميد رابطة H، والأمين جسراً أيونياً محكماً.\",\"en\":\"Quinoline provides π-π stacking, butoxy hydrophobic packing, amide an H-bond, and amine an ionic salt bridge.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":33}]},{\"id\":\"mc-mod2-les1-step-10\",\"stage\":\"retrieval\",\"stageIndex\":10,\"title\":{\"tr\":\"Geri Çağırma: Ester vs Amit Değişimi (Prokain vs Prokainamid)\",\"ar\":\"استرجاع: استبدال الإستر بالأميد (Procaine مقابل Procainamide)\",\"en\":\"Retrieval: Ester vs Amide Swap (Procaine vs Procainamide)\"},\"prompt\":{\"tr\":\"Prokaindeki ester bağı (-COO-) amit bağına (-CONH-) dönüştürülerek prokainamid elde edilir. Reseptör bağlanması korunurken etki süresi neden dakikalardan saatlere uzar?\",\"ar\":\"عند استبدال رابطة الإستر (-COO-) في البروكائين برابطة أميد (-CONH-) ينتج بروكايناميد. مع بقاء الارتباط سلبياً، لماذا تمتد مدة التأثير من دقائق إلى ساعات؟\",\"en\":\"Converting procaine's ester (-COO-) into an amide (-CONH-) yields procainamide. Why does duration of action expand from minutes to hours while receptor binding affinity is preserved?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-10a\",\"text\":{\"tr\":\"Amit bağındaki azot elektron çifti karbonille güçlü rezonans yapar; psödokolinesteraz enziminin nükleofilik saldırısına direnerek hidrolizi engeller.\",\"ar\":\"يقدم زوج إلكترونات نيتروجين الأميد رنيناً قوياً مع الكربونيل؛ مما يصد هجوم إنزيم كولينستيراز المائي ويحمي الرابطة من التفكك السريع.\",\"en\":\"Amide nitrogen lone pairs delocalize strongly into the carbonyl via resonance, conferring chemical resistance to pseudocholinesterase hydrolysis.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Esterler plazma bütirilkolinesterazı tarafından 15 dakikada hidroliz edilirken, amitler rezonans kararlılığı sayesinde saatlerce dolaşımda aktif kalır.\",\"ar\":\"صحيح! تتفكك الإسترات بإنزيمات البلازما خلال 15 دقيقة، بينما تحافظ الأميدات على استقرارها لساعات بفضل طاقة الرنين الإلكترونية.\",\"en\":\"Correct! Esters are cleaved in minutes by plasma esterases; amides resist hydrolysis due to resonance stabilization of the C-N bond.\"}},{\"id\":\"opt-10b\",\"text\":{\"tr\":\"Amit grubu ilacın böbrek glomerüllerinden filtrasyonunu tamamen durdurur.\",\"ar\":\"توقف مجموعة الأميد ترشيح الدواء عبر كبيبات الكلى بالكامل.\",\"en\":\"The amide group completely halts glomerular filtration in the kidneys.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Fark böbrek filtrasyonundan değil, plazma enzimlerinin hidroliz hızındaki devasa farktan kaynaklanır.\",\"ar\":\"مغالطة: الفارق لا يعود للترشيح الكلوي بل للتباين الصاعق في سرعة التفكك الإنزيمي بين الإستر والأميد.\",\"en\":\"Misconception: The kinetic difference stems from metabolic enzymatic hydrolysis rates, not renal filtration.\"}},{\"id\":\"opt-10c\",\"text\":{\"tr\":\"Ester bağı kovalent bağlanırken, amit bağı iyonik bağlanır.\",\"ar\":\"ترتبط رابطة الإستر تساهمياً، بينما ترتبط رابطة الأميد أيونياً.\",\"en\":\"Esters bind biological receptors covalently, whereas amides bind purely through ionic attractions.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Ne ester ne amit sodyum kanalına kovalent bağlanır; ikisi de hidrojen bağı akseptörü olarak davranır.\",\"ar\":\"مغالطة: لا يشكل الإستر ولا الأميد روابط تساهمية مع قناة الصوديوم؛ فكلاهما يعمل كآخذ للرابطة الهيدروجينية.\",\"en\":\"Misconception: Neither functional group forms covalent bonds to sodium channels; both serve as non-covalent H-bond partners.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-10a\",\"text\":\"Amit azotu rezonansla karbonili kararlı kılar; kolinesteraz hidrolizine direnir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Amit bağı esterden çok daha kararlıdır.\"},{\"id\":\"opt-10b\",\"text\":\"Böbrek filtrasyonunu durdurur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Fark plazma hidrolizindedir.\"},{\"id\":\"opt-10c\",\"text\":\"Ester kovalent bağlanır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: İkisi de non-kovalent bağlanır.\"}],\"revealedOutcome\":{\"tr\":\"Biyoizosterik kararlılık: Esterden amite geçiş (prokain -> prokainamid), reseptör H-bağını korurken metabolik yıkımı 20 kat yavaşlatır.\",\"ar\":\"الاستقرار التماثلي الحيوي: الانتقال من الإستر للأميد يحافظ على الرابطة الهيدروجينية ويبطئ التفكك الاستقلابي بمقدار 20 ضعفاً.\",\"en\":\"Bioisosteric stability: The ester-to-amide shift preserves receptor H-bonding while slowing enzymatic hydrolysis 20-fold.\"},\"explanation\":{\"tr\":\"Fonksiyonel gruplar slayt 11: Ester bağı plazma esterazlarına son derece hassastır. Amit bağında ise N atomu elektronlarını C=O ya vererek kısmi çift bağ karakteri kazanır ve hidrolize direnir.\",\"ar\":\"المجموعات الوظيفية شريحة 11: الإستر شديد الحساسية لإستراز البلازما؛ بينما يمنح نيتروجين الأميد إلكتروناته للكربونيل ليكتسب صفة الرابطة المزدوجة المقاومة للماء.\",\"en\":\"Functional groups slide 11: Esters are cleaved rapidly by plasma esterases; amides possess partial double-bond character resisting nucleophilic attack.\"}},\"technicalTerms\":[{\"term\":\"esteraz hidrolizi\",\"arContext\":\"الحلمهة بواسطة الإستراز\"},{\"term\":\"amit rezonansı\",\"arContext\":\"رنين الرابطة الأميدية\"}],\"hints\":[{\"tr\":\"Kandaki psödokolinesteraz enzimi hangi bağı dakikalar içinde parçalar? Ester mi, amit mi?\",\"ar\":\"أي رابطة يفككها إنزيم كولينستيراز البلازما خلال دقائق؟ الإستر أم الأميد؟\",\"en\":\"Which chemical bond does plasma pseudocholinesterase hydrolyze within minutes? Ester or amide?\"},{\"tr\":\"Amit bağındaki azotun serbest elektron çifti karbonil karbonuna delokalize olur (rezonans).\",\"ar\":\"يتشارك زوج إلكترونات النيتروجين في الأميد مع كربونيل الكربون بالرنين الإلكتروني.\",\"en\":\"The nitrogen lone pair in an amide delocalizes into the carbonyl carbon via resonance.\"},{\"tr\":\"Rezonans kararlılığı amiti enzimatik hidrolize dirençli kılar; ilaç kanda saatlerce parçalanmadan kalır.\",\"ar\":\"يمنح الرنين الأميد مناعة ضد التفكك الإنزيمي، فيستمر الدواء في الدم لساعات دون تحلل.\",\"en\":\"Resonance stabilization makes the amide bond resistant to enzymatic attack, vastly extending duration.\"}],\"sources\":[{\"file\":\"Fonksiyonel gruplar.pdf\",\"page\":2},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":4}]},{\"id\":\"mc-mod2-les1-step-11\",\"stage\":\"connection\",\"stageIndex\":11,\"title\":{\"tr\":\"İleri Bağlantı: Heterosiklik Halkalar ve π-İstiflenmesi (Modül 3)\",\"ar\":\"ربط مفاهيمي: الحلقات غير المتجانسة وتراصف π (الوحدة 3)\",\"en\":\"Forward Connection: Heterocycles & π-Stacking (Module 3)\"},\"prompt\":{\"tr\":\"Benzen halkası yerine piridin, imidazol veya tiyofen getirmek ilacın reseptörle π-istiflenmesini, hidrojen bağı akseptörlüğünü ve suda çözünürlüğünü nasıl aynı anda optimize eder?\",\"ar\":\"كيف يؤدي استبدال حلقة البنزين بالبيريدين أو الإيميدازول أو الثيوفين إلى تحسين تراصف π، وقبول الروابط الهيدروجينية، والذوبانية المائية في آن واحد؟\",\"en\":\"How does replacing a benzene ring with pyridine, imidazole, or thiophene simultaneously modulate aromatic π-stacking, hydrogen bond accepting capability, and aqueous solubility?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-11a\",\"text\":{\"tr\":\"Heteroatomlar (N, O, S) aromatik halkaya kalıcı dipol momenti ve H-bağı akseptörlüğü katar; bu durum Modül 3 teki biyoizosterik optimizasyonun temelidir.\",\"ar\":\"تمنح الذرات غير المتجانسة (N, O, S) عزم ثنائي قطب وقدرة على قبول الروابط الهيدروجينية؛ وهو جوهر التحسين الحيوي التماثلي في الوحدة 3.\",\"en\":\"Heteroatoms (N, O, S) introduce permanent ring dipole moments and H-bond accepting sites, forming the basis of bioisosteric optimization in Module 3.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Benzen tamamen simetrik ve apolardır. Piridin ve imidazol ise hem aromatik π-istiflenmesi yapar hem de azot üzerindeki elektron çiftiyle H-bağı kabul eder.\",\"ar\":\"صحيح! البنزين متناظر وغير قطبي تماماً. بينما يحقق البيريدين والإيميدازول تراصف π مع قبول الروابط الهيدروجينية بزوج إلكترونات النيتروجين.\",\"en\":\"Correct! Benzene is purely apolar; pyridine and imidazole preserve aromatic π-stacking while introducing basic H-bond acceptor lone pairs.\"}},{\"id\":\"opt-11b\",\"text\":{\"tr\":\"Heterosiklik halkalar aromatikliği tamamen yok ederek molekülü alifatik hidrokarbona çevirir.\",\"ar\":\"تدمر الحلقات غير المتجانسة العطرية بالكامل وتحول الجزيء إلى هيدروكربون أليفاتي.\",\"en\":\"Heterocycles completely destroy aromaticity, converting planar aromatic rings into floppy aliphatic chains.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Piridin, pirazol ve tiyofen Hückel 4n+2 kuralına uyan tam aromatik halkalardır; aromatiklikleri yok olmaz.\",\"ar\":\"مغالطة: تخضع حلقات البيريدين والثيوفين لقاعدة هوكل (4n+2) وتمتلك عطرية حقيقية مستقرة تماماً.\",\"en\":\"Misconception: Pyridine and thiophene strictly follow Hückel's 4n+2 rule and remain fully aromatic planar rings.\"}},{\"id\":\"opt-11c\",\"text\":{\"tr\":\"Heterosiklik halkaların ilaç tasarımında kullanımı toksisite nedeniyle farmakopelerde yasaklanmıştır.\",\"ar\":\"يحظر استخدام الحلقات غير المتجانسة في تصميم الأدوية بسبب سميتها العالية في دساتير الأدوية.\",\"en\":\"Heterocyclic rings are prohibited by international pharmacopeias due to extreme cellular toxicity.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: FDA onaylı küçük moleküllü ilaçların %80 den fazlası en az bir heterosiklik halka içerir.\",\"ar\":\"مغالطة: أكثر من 80% من الأدوية المعتمدة عالمياً تحتوي على حلقة غير متجانسة واحدة على الأقل.\",\"en\":\"Misconception: Over 80% of all FDA-approved small-molecule drugs contain at least one heterocyclic ring scaffold.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-11a\",\"text\":\"Heteroatomlar dipol ve H-bağı katar; biyoizosterik optimizasyonun temelidir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Heterohalkalar aromatikliği H-bağıyla birleştirir.\"},{\"id\":\"opt-11b\",\"text\":\"Aromatikliği yok eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Heterosiklikler tam aromatiktir.\"},{\"id\":\"opt-11c\",\"text\":\"İlaçlarda kullanımları yasaktır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: İlaçların %80 inde heterohalka vardır.\"}],\"revealedOutcome\":{\"tr\":\"Modül 2 den Modül 3 e köprü: Heterosiklik halkalar (piridin, imidazol, tiyofen) aromatik π-istiflenmesini korurken hidrojen bağı pencereleri açarak ilacı mükemmelleştirir.\",\"ar\":\"جسر العبور للوحدة 3: تدمج الحلقات غير المتجانسة تراصف π مع فتح نوافذ الروابط الهيدروجينية لتحسين الأدوية.\",\"en\":\"Bridge to Module 3: Heterocycles blend aromatic π-stacking with versatile H-bonding portals to optimize lead compounds.\"},\"explanation\":{\"tr\":\"Fonksiyonel gruplar slayt 16-25: Heteroatomlar halkanın elektron yoğunluğunu değiştirir. Bir sonraki modülde klasik ve klasik olmayan biyoizosterizmi bu halkalarla inceleyeceğiz.\",\"ar\":\"المجموعات الوظيفية شريحة 16-25: تغير الذرات غير المتجانسة الكثافة الإلكترونية، وسنستكشف دورها التماثلي الحيوي بالتفصيل في الوحدة 3.\",\"en\":\"Functional groups slides 16-25: Heteroatoms modulate ring electrostatics, setting the stage for classical bioisosterism in Module 3.\"}},\"technicalTerms\":[{\"term\":\"heterosiklik halka\",\"arContext\":\"الحلقة غير المتجانسة\"},{\"term\":\"biyoizosterizm\",\"arContext\":\"التماثل الحيوي\"}],\"hints\":[{\"tr\":\"Benzen halkasındaki bir -CH= grubunu azot (-N=) ile değiştirirseniz ne elde edersiniz? (Piridin).\",\"ar\":\"إذا استبدلت مجموعة -CH= في البنزين بذرة نيتروجين (-N=)، ماذا ينتج؟ (بيريدين).\",\"en\":\"If you replace a -CH= group in benzene with a nitrogen atom (-N=), what ring is formed? (Pyridine).\"},{\"tr\":\"Piridin azotu üzerindeki ortaklanmamış elektron çifti ne yapabilir? Hidrojen bağı kabul edebilir mi?\",\"ar\":\"ما الذي يمكن لزوج إلكترونات نيتروجين البيريدين فعله؟ هل يقبل رابطة هيدروجينية؟\",\"en\":\"What can the lone pair on the pyridine nitrogen do? Can it act as an H-bond acceptor?\"},{\"tr\":\"Heteroatomlar aromatikliği bozmadan moleküle hidrojen bağı ve polarite kazandırır.\",\"ar\":\"تمنح الذرات غير المتجانسة الجزيء قطبية وقبولاً للروابط الهيدروجينية دون المساس بالعطرية.\",\"en\":\"Heteroatoms impart hydrogen-bonding capability and polarity without compromising aromatic π-stacking.\"}],\"sources\":[{\"file\":\"Fonksiyonel gruplar.pdf\",\"page\":16},{\"file\":\"Fonksiyonel gruplar.pdf\",\"page\":25}]},{\"id\":\"mc-mod2-les1-step-12\",\"stage\":\"mastery_check\",\"stageIndex\":12,\"title\":{\"tr\":\"Ustalık Sınavı: Ters Çevrilmiş Amit ve 1000 Katlık Afinite Kaybı\",\"ar\":\"اختبار الإتقان: الأميد المعكوس وفقدان الألفة بمقدار 1000 ضعف\",\"en\":\"Mastery Assessment: Inverted Amide & 1000-Fold Affinity Loss\"},\"prompt\":{\"tr\":\"Yeni bir kinaz inhibitöründe amit bağı (-NH-CO-) ters çevrilip (-CO-NH-) yapıldığında afinite 1000 kat düşmektedir (ΔΔG° = +4.2 kcal/mol). Bu devasa kaybın kesin moleküler nedeni nedir?\",\"ar\":\"في مثبط كينيز جديد، يؤدي عكس رابطة الأميد من (-NH-CO-) إلى (-CO-NH-) إلى هبوط الألفة بمقدار 1000 ضعف (ΔΔG° = +4.2 kcal/mol). ما هو السبب الجزيئي الدقيق؟\",\"en\":\"In a novel kinase inhibitor, inverting an amide linkage from -NH-CO- to -CO-NH- crashes target affinity 1000-fold (ΔΔG° = +4.2 kcal/mol). What precise molecular interaction explains this loss?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-12a\",\"text\":{\"tr\":\"Reseptörün rijit cebinde donör (-NH-) ve akseptör (C=O) geometrik konumları yer değiştirmiştir; 180° doğrusal H-bağı kopmuş ve elektrostatik dipol itmesi doğmuştur.\",\"ar\":\"تبادلت المجموعتان المانحة (-NH-) والآخذة (C=O) موضعيهما الهندسيين؛ فانكسرت استقامة الرابطة الهيدروجينية 180° ونشأ تنافر ثنائي قطب.\",\"en\":\"The donor (-NH-) and acceptor (C=O) positions are inverted relative to rigid receptor residues; the linear 180° H-bond is lost and dipole repulsion is created.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz ustalık çıkarımı! Hidrojen bağları son derece yönlüdür. Donör ve akseptörün yer değiştirmesi, reseptördeki karşılık gelen gruplarla (donör-donör ve akseptör-akseptör) şiddetli elektrostatik itmeye yol açar; her 1.42 kcal/mol luk kayıp afiniteyi 10 kat düşürür (4.2 kcal/mol = 1000 kat!).\",\"ar\":\"استنتاج استثنائي فائق الدقة! الروابط الهيدروجينية اتجاهية بصرامة. يؤدي عكس الأميد إلى تنافر آخذ-آخذ ومانح-مانح؛ وكل فقد بمقدار 1.42 kcal/mol يسقط الألفة 10 أضعاف (4.2 تعني هبوطاً بألف ضعف!).\",\"en\":\"Exceptional mastery deduction! H-bonds are acutely directional. Inverting the amide forces donor-donor and acceptor-acceptor clashes; losing 4.2 kcal/mol causes an exact 1000-fold affinity collapse.\"}},{\"id\":\"opt-12b\",\"text\":{\"tr\":\"Amit bağı ters çevrildiğinde molekülün moleküler ağırlığı iki katına çıkmış ve kanala sığmamıştır.\",\"ar\":\"أدى عكس رابطة الأميد إلى مضاعفة الوزن الجزيئي فلم يعد الجزيء يتسع داخل القناة.\",\"en\":\"Inverting the amide bond doubles the drug's molecular weight, preventing entry into the binding pocket.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: İzomerik bir düzenlemedir; atom sayısı ve moleküler ağırlık tamamen aynı kalır.\",\"ar\":\"مغالطة: هذا تحول تماكبي بنيوي؛ والوزن الجزيئي وعدد الذرات متطابقان تماماً دون أي تغيير.\",\"en\":\"Misconception: This is a constitutional rearrangement; the atom count and molecular weight remain identical.\"}},{\"id\":\"opt-12c\",\"text\":{\"tr\":\"Amit bağı ters dönünce tüm kovalent bağlar kendiliğinden koparak molekülü ikiye bölmüştür.\",\"ar\":\"انكسرت الروابط التساهمية تلقائياً عند عكس الأميد وانشطر الجزيء لنصفين.\",\"en\":\"Inverting the amide causes spontaneous covalent bond fission, cleaving the drug into two fragments.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Kimyasal bağlar sağlamdır; kayıp reaksiyonel parçalanmadan değil, reseptör cebindeki 3 boyutlu geometrik uyumsuzluktan kaynaklanır.\",\"ar\":\"مغالطة: الجزيء متماسك كيميائياً؛ والخلل يكمن في التنافر الهندسي الفراغي داخل جيب المستقبِل.\",\"en\":\"Misconception: Covalent bonds remain intact; the affinity loss is purely due to 3D spatial and electrostatic mismatch.\"}},{\"id\":\"opt-12d\",\"text\":{\"tr\":\"-CO-NH- bağı kimyasal olarak elektrik yükü taşıyamaz ve van der Waals teması kuramaz.\",\"ar\":\"تعجز رابطة -CO-NH- عن حمل شحنات ولا يمكنها تشكيل قوى فان دير فالس إطلاقاً.\",\"en\":\"The -CO-NH- group cannot carry partial charges and is incapable of forming van der Waals interactions.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanılgı: Her iki amit formu da güçlü dipol momentine ve van der Waals temaslarına sahiptir.\",\"ar\":\"مغالطة: يمتلك كلا شكلي الأميد عزماً ثنائي قطب قوياً وتماسات فان دير فالس حقيقية.\",\"en\":\"Misconception: Both amide orientations possess strong dipole moments (~3.5 Debye) and van der Waals surfaces.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-12a\",\"text\":\"Donör ve akseptör yer değiştirmiş; 180° H-bağı kopup dipol itmesi doğmuştur.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Yönlü H-bağının kopması 1000 katlık kayıp yaratır.\"},{\"id\":\"opt-12b\",\"text\":\"Molekül ağırlığı iki katına çıkmıştır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Molekül ağırlığı değişmez.\"},{\"id\":\"opt-12c\",\"text\":\"Kovalent bağlar kendiliğinden kopmuştur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Molekül parçalanmaz, geometrik uyum bozulur.\"},{\"id\":\"opt-12d\",\"text\":\"-CO-NH- bağı elektrik yükü taşımaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanılgı: Amit bağı güçlü dipol taşır.\"}],\"revealedOutcome\":{\"tr\":\"Tebrikler! Modül 2 Ders 1 Ustalık Sınavını geçtiniz. Hidrojen bağlarının katı 180° yönlülüğünü ve ΔΔG° = 4.2 kcal/mol enerji kaybının 1000 katlık afinite çöküşüne denk geldiğini kanıtladınız. +50 XP.\",\"ar\":\"تهانينا! لقد اجتزت اختبار إتقان الدرس 1 من الوحدة 2 بنجاح. أثبتت أن اتجاهية الرابطة الهيدروجينية 180° وفقدان 4.2 kcal/mol يعادلان انهيار الألفة بمقدار 1000 ضعف تماماً. +50 XP.\",\"en\":\"Congratulations! You passed the Module 2 Lesson 1 Mastery Check. You proved that strict 180° H-bond directionality and ΔΔG° = +4.2 kcal/mol corresponds precisely to a 1000-fold affinity collapse. +50 XP.\"},\"explanation\":{\"tr\":\"Amitin ters çevrilmesi hidrojen bağının donör (C=O...) ve akseptör (...H-N) vektörlerini ters çevirir. Doğrusal 180° temas kopar ve ΔΔG° = +4.2 kcal/mol lük kayıp (3 x 1.42 kcal/mol) afiniteyi 10^3 = 1000 kat düşürür (Slayt 16, 33).\",\"ar\":\"عكس الأميد يعكس متجهات الرابطة الهيدروجينية؛ فتنكسر استقامة 180°، ويؤدي فقد 4.2 kcal/mol (أي 3 × 1.42) إلى هبوط الألفة بمقدار 10^3 = 1000 ضعف بدقة (شريحة 16، 33).\",\"en\":\"Inverting the amide flips the H-bond donor/acceptor vectors. Breaking the linear 180° bond costs ΔΔG° = +4.2 kcal/mol (3 x 1.42 kcal/mol), dropping affinity by exactly 10^3 = 1000-fold.\"}},\"technicalTerms\":[{\"term\":\"ters amit izomeri\",\"arContext\":\"المصاوغ الأميدي المعكوس\"},{\"term\":\"afinite çöküşü\",\"arContext\":\"انهيار الألفة الدوائية\"}],\"hints\":[{\"tr\":\"Amit bağı -NH-CO- iken donör kimdir? Akseptör kimdir? Ters çevrilince (-CO-NH-) ne olur?\",\"ar\":\"في الرابطة -NH-CO-، من هو المانح ومن هو الآخذ؟ وماذا يحدث عند عكسها إلى -CO-NH-؟\",\"en\":\"In the amide -NH-CO-, which atom donates and which accepts? What happens when inverted to -CO-NH-?\"},{\"tr\":\"Reseptörün aktif cebindeki hidrojen bağı partnerleri sabittir; donörün karşısına donör gelirse ne olur?\",\"ar\":\"مواقع الارتباط في جيب المستقبِل ثابتة؛ ماذا يحدث عندما يقابل المانح مانحاً آخر؟\",\"en\":\"The receptor pocket's partners are fixed in 3D space; what happens when a donor faces another donor?\"},{\"tr\":\"Donör ve akseptör yer değiştirince 180° H-bağı kopar; 4.2 kcal/mol kayıp afiniteyi 1000 kat (10³) düşürür.\",\"ar\":\"بانعكاس المانح والآخذ تنكسر استقامة الرابطة الهيدروجينية؛ وفقد 4.2 kcal/mol يسقط الألفة بمقدار 1000 ضعف.\",\"en\":\"Inverting donor and acceptor destroys the 180° H-bond; losing 4.2 kcal/mol (3 x 1.42) collapses Kd by 1000-fold.\"}],\"sources\":[{\"file\":\"Fonksiyonel gruplar.pdf\",\"page\":2},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":16},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":33}]}]},\"mc-mod2-les2\":{\"$schema\":\"../../../packages/platform/schema/lesson.schema.json\",\"id\":\"mc-mod2-les2\",\"courseId\":\"medchem\",\"moduleId\":\"mc-mod-02\",\"title\":{\"tr\":\"Optik Kiralite ve Easson-Stedman 3-Noktalı Bağlanma\",\"ar\":\"الكيرالية الضوئية ونموذج Easson-Stedman ثلاثي النقاط\",\"en\":\"Optical Chirality & Easson-Stedman 3-Point Attachment\"},\"order\":2,\"access\":\"free\",\"objective\":{\"tr\":\"Easson-Stedman 3-noktalı bağlanma hipotezini uygulayarak stereoselektif reseptör bağlanmasını öngörmek, eudismik oranları hesaplamak ve distomer klinik farmakolojisini açıklamak.\",\"ar\":\"تطبيق فرضية Easson-Stedman ثلاثية النقاط للتنبؤ بالارتباط الانتقائي الفراغي، وحساب النسب الإيوديزمية، واستنتاج الدوائيات السريرية للمصاوغ الأضعف (distomer).\",\"en\":\"Apply the Easson-Stedman 3-point attachment hypothesis to predict stereoselective receptor binding, calculate eudismic ratios, and deduce distomer clinical pharmacology.\"},\"misconceptions\":[{\"tr\":\"İki enantiyomerin fizyolojik ortamlarda ve reseptörlerde aynı biyolojik güce sahip olduğu yanılgısı.\",\"ar\":\"الظن الخاطئ بأن المصاوغين المرآويين يمتلكان نفس التأثير والألفة في الأهداف البيولوجية.\",\"en\":\"The misconception that enantiomers possess identical pharmacological activity and target affinity in biological systems.\"},{\"tr\":\"Asimetrik bir reseptörün enantiyomerleri ayırt edebilmesi için 2 temas noktasının yeterli olduğu düşüncesi.\",\"ar\":\"الاعتقاد الخاطئ بأن نقطتي اتصال تكفيان للمستقبل غير المتناظر للتمييز الحاسم بين المصاوغين.\",\"en\":\"The belief that two contact points are sufficient for an asymmetric receptor to discriminate between mirror enantiomers.\"},{\"tr\":\"Saf (R)-talidomid uygulamasının gebelerde fokomeli teratojenitesini önleyebileceği varsayımı.\",\"ar\":\"الافتراض الخاطئ بأن إعطاء (R)-thalidomide النقي كان سينقذ الأجنة من تشوهات الفقمية (phocomelia).\",\"en\":\"The assumption that administering pure (R)-thalidomide could have prevented phocomelia teratogenicity in pregnant patients.\"},{\"tr\":\"Tüm kiral ilaçlarda distomeri izole etmenin ilacı klinik olarak mutlaka daha üstün kılacağı yanılgısı.\",\"ar\":\"الاعتقاد الخاطئ بأن فصل المصاوغ الأضعف دوماً ما يجعل الدواء متفوقاً سريرياً في كافة الحالات.\",\"en\":\"The misconception that developing single enantiomers is always clinically superior, overlooking synergistic desirable racemates.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":13},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":16},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":22},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":23},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":25},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":26},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":28},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":30},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":31},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":32},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":33},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":35},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":42}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Foye's Principles of Medicinal Chemistry\",\"edition\":\"8th ed.\",\"topic\":\"Stereochemistry and Drug Action: Easson-Stedman Model and Eudismic Ratios\",\"chapter\":\"Chapter 2\",\"page\":\"35-52\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Wilson and Gisvold's Textbook of Organic Medicinal and Pharmaceutical Chemistry\",\"edition\":\"12th ed.\",\"topic\":\"Physicochemical Properties and Stereochemistry in Drug Design\",\"chapter\":\"Chapter 3\",\"page\":\"60-78\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"mc-mod2-les2-card1\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Easson-Stedman Hipotezi\",\"prompt\":\"Easson-Stedman modeline göre (R)-adrenalin neden (S)-adrenalinden ve dopaminden 45-100 kat daha güçlüdür?\",\"answer\":\"(R)-adrenalin katekol, protonlanmış amin ve kiral beta-OH olmak üzere 3 noktadan tam kenetlenir; (S)-adrenalin ve dopamin ise beta-OH bağını kuramayıp sadece 2 noktadan bağlanır.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod2-les2-card2\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Pfeiffer Kuralı\",\"prompt\":\"Pfeiffer kuralına göre bir ilacın reseptör afinitesi ile enantiyomerler arası güç farkı (Eudismik Oran) nasıl ilişkilidir?\",\"answer\":\"Afinite ne kadar yüksekse (doz ne kadar düşükse), reseptör cebi kiral kusurlara o derece az tolerans gösterir ve Eudismik Oran katlanarak artar.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod2-les2-card3\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Talidomid İn Vivo Rasemizasyonu\",\"prompt\":\"Saf (R)-talidomid uygulanması gebelerde fokomeli teratojenitesini neden engelleyemez?\",\"answer\":\"Talidomidin asidik kiral protonu fizyolojik pH'ta keto-enol tautomerisiyle kendiliğinden 4-5 saatte rasemize olur; teratojenik (S)-izomeri in vivo ortamda kaçınılmaz olarak oluşur.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod2-les2-card4\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Asetilkolin Biyoaktif Konformasyonları\",\"prompt\":\"Asetilkolin molekülünün muskarinik ve nikotinik reseptörleri ayırt etmesini sağlayan uzaysal parametre nedir?\",\"answer\":\"Katlanmış (gauche) formda N+ ile ester O mesafesi 3.3 Å olup muskarinik reseptörlere; uzamış (anti) formda 4.4 Å olup nikotinik reseptörlere kenetlenir.\",\"box\":1,\"intervalDays\":1}],\"translations\":{\"tr\":{\"title\":\"Optik Kiralite ve Easson-Stedman 3-Noktalı Bağlanma\"},\"ar\":{\"title\":\"الكيرالية الضوئية ونموذج Easson-Stedman ثلاثي النقاط\"}},\"steps\":[{\"id\":\"mc-mod2-les2-step-01\",\"stage\":\"hook\",\"stageIndex\":1,\"type\":\"predict_reveal\",\"title\":{\"tr\":\"Klinik Kiralite: Tek Bir Oksijenin 100 Katlık Uçurumu\",\"ar\":\"لغز الكيرالية: فارق القوة لمئة ضعف لذرة أكسجين واحدة\",\"en\":\"The Epinephrine Single Oxygen Potency Cliff\"},\"prompt\":{\"tr\":\"Dopamine tek bir alifatik -OH grubu eklenince (R)-adrenalin oluşur ve kardiyak etki gücü 100 kat artar. Ancak aynı -OH grubuna sahip ayna görüntüsü (S)-adrenalin dopaminle aynı zayıf güçtedir. Neden?\",\"ar\":\"إضافة مجموعة -OH للدوبامين تنتج (R)-adrenalin لترتفع القوة القلبية بمئة ضعف. لكن المصاوغ المرآوي (S)-adrenalin بنفس الـ -OH يملك نفس فاعلية الدوبامين الضعيفة تماماً! لماذا؟\",\"en\":\"Adding an aliphatic -OH to dopamine forms (R)-epinephrine, boosting cardiac potency 100-fold. Yet mirror (S)-epinephrine has that identical -OH, but displays zero potency gain over dopamine! Why?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-1a\",\"text\":{\"tr\":\"(S)-adrenalinde kiral merkez ters döndüğünde -OH grubu reseptör cebinden dışarı, sulu çözücüye bakar; hidrojen bağı hiç kurulamaz.\",\"ar\":\"عند انقلاب المركز الكيرالي في (S)-adrenalin، تتجه مجموعة -OH نحو المذيب المائي خارج الجيب، فتنعدم الرابطة الهيدروجينية.\",\"en\":\"Inverting the chiral center in (S)-epinephrine directs the -OH group away from the receptor into solvent, eliminating hydrogen bonding.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Reseptör aktif cebi asimetriktir. Katekol ve amin cebe oturduğunda, (S)-adrenalinin -OH grubu boşluğa bakar ve dopamin gibi yalnızca 2 temas noktasıyla bağlanır.\",\"ar\":\"صحيح! جيب المستقبل غير متناظر. عند رسو الكاتيكول والأمين، تتجه مجموعة -OH في (S)-adrenalin إلى الخارج ليرتبط بنقطتين فقط كالدوبامين.\",\"en\":\"Correct! The binding pocket is asymmetric. When catechol and amine dock, (S)-epinephrine's -OH faces solvent, reducing it to the 2-point binding of dopamine.\"}},{\"id\":\"opt-1b\",\"text\":{\"tr\":\"(S)-adrenalindeki -OH grubu karaciğerde hemen sülfatlandığı için reseptöre ulaşamadan hızla inaktive olur.\",\"ar\":\"تتخرب مجموعة -OH في (S)-adrenalin بالكبد مباشرة عبر الارتباط بالكبريتات قبل وصولها للمستقبل.\",\"en\":\"The -OH group in (S)-epinephrine is rapidly sulfated in the liver before reaching the receptor.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Metabolik eliminasyon yanılgısı: Her iki enantiyomer de aynı fiziksel faz II enzimlerine maruz kalır; güç farkı reseptörün aktif cebindeki uzaysal 3 boyutlu kilit-anahtar uyumsuzluğundan kaynaklanır.\",\"ar\":\"خطأ الاستقلاب: يخضع كلا المصاوغين لنفس الأنزيمات الكبدية؛ الفارق ينبع مباشرة من عدم التطابق الهندسي الفراغي داخل جيب المستقبل.\",\"en\":\"Metabolic misconception: Both enantiomers face identical phase II enzymes; the 100-fold cliff stems from 3D steric mismatch directly inside the receptor binding pocket.\"}},{\"id\":\"opt-1c\",\"text\":{\"tr\":\"(S)-adrenalin reseptöre kovalent bağlanarak kanalı bloke eder, bu yüzden agonistik sinyal iletimi sıfıra iner.\",\"ar\":\"يرتبط (S)-adrenalin تساهمياً بالمستقبل فيغلقه تماماً مانعاً أي نقل للإشارة المنبهة.\",\"en\":\"(S)-epinephrine forms an irreversible covalent bond that blocks receptor signaling.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kovalent blokaj yanılgısı: Adrenalin reseptörüne kovalent değil, tamamen geri dönüşümlü non-kovalent (iyonik, H-bağı, pi-pi) bağlarla bağlanır; (S)-adrenalin bir bloker değildir.\",\"ar\":\"خطأ الارتباط التساهمي: يرتبط الأدرينالين بروابط غير تساهمية عكوسة، والمصاوغ (S) ليس حاصراً تساهمياً بل منبه ضعيف الألفة.\",\"en\":\"Covalent block misconception: Adrenaline binds reversibly via non-covalent forces; (S)-epinephrine is not a covalent blocker, but a weak 2-point agonist.\"}}]},\"technicalTerms\":[{\"term\":\"kiralite\",\"arContext\":\"الكيرالية\"},{\"term\":\"enantiyomer\",\"arContext\":\"المصاوغ المرآوي (enantiyomer)\"}],\"hints\":[{\"tr\":\"Dopamin molekülünde kiral merkez yoktur; iki temel temas noktasıyla (katekol ve amin) reseptöre tutunur.\",\"ar\":\"لا يمتلك الدوبامين مركزاً كيرالياً؛ ويرتبط بالمستقبل بنقطتي تماس أساسيتين فقط (الكاتيكول والأمين).\",\"en\":\"Dopamine lacks a chiral center, anchoring into the pocket via only two pharmacophoric contact points.\"},{\"tr\":\"(R) ve (S) enantiyomerlerinin ayna görüntüleri 3 boyutlu uzayda üst üste çakışmaz. Bir gruptaki uzaysal yönelim ters döner.\",\"ar\":\"المصاوغان المرآويان لا ينطبقان في الفراغ ثلاثي الأبعاد، مما يقلب الاتجاه الهندسي لإحدى المجموعات.\",\"en\":\"Mirror-image enantiomers cannot superimpose in 3D space; inverting configuration points one substituent into empty space.\"},{\"tr\":\"(R)-adrenalinde beta-OH grubu reseptör serin kalıntısıyla hidrojen bağı yaparken, (S)-adrenalinde aynı grup cebin dışına yönelir ve hidrojen bağı enerjisi sıfıra düşer.\",\"ar\":\"في (R)-adrenalin تشكل beta-OH رابطة هيدروجينية مع السيرين، بينما في (S)-adrenalin تبتعد المجموعة عن الجيب لتنعدم طاقة الرابطة.\",\"en\":\"In (R)-epinephrine the beta-OH donates a critical H-bond to serine; in (S)-epinephrine it points into bulk water, yielding zero H-bonding energy.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":25}],\"config\":{\"options\":[{\"id\":\"opt-1a\",\"text\":\"(S)-adrenalinde kiral merkez ters döndüğünde -OH grubu reseptör cebinden dışarı, sulu çözücüye bakar; hidrojen bağı hiç kurulamaz.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Reseptör aktif cebi asimetriktir. Katekol ve amin cebe oturduğunda, (S)-adrenalinin -OH grubu boşluğa bakar ve dopamin gibi yalnızca 2 temas noktasıyla bağlanır.\"},{\"id\":\"opt-1b\",\"text\":\"(S)-adrenalindeki -OH grubu karaciğerde hemen sülfatlandığı için reseptöre ulaşamadan hızla inaktive olur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Metabolik eliminasyon yanılgısı: Her iki enantiyomer de aynı fiziksel faz II enzimlerine maruz kalır; güç farkı reseptörün aktif cebindeki uzaysal 3 boyutlu kilit-anahtar uyumsuzluğundan kaynaklanır.\"},{\"id\":\"opt-1c\",\"text\":\"(S)-adrenalin reseptöre kovalent bağlanarak kanalı bloke eder, bu yüzden agonistik sinyal iletimi sıfıra iner.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kovalent blokaj yanılgısı: Adrenalin reseptörüne kovalent değil, tamamen geri dönüşümlü non-kovalent (iyonik, H-bağı, pi-pi) bağlarla bağlanır; (S)-adrenalin bir bloker değildir.\"}],\"revealedOutcome\":{\"tr\":\"(S)-adrenalin reseptöre yaklaştığında katekol ve amin bağlanır ancak -OH grubu boşluğa bakar; hidrojen bağı enerjisi (-14 kJ/mol) tamamen kaybedilir.\",\"ar\":\"عند اقتراب (S)-adrenalin من جيب المستقبل، يرسو الكاتيكول والأمين بينما تواجه مجموعة -OH المذيب، فتضيع طاقة الرابطة الهيدروجينية (-14 kJ/mol) تماماً.\",\"en\":\"When (S)-epinephrine docks, catechol and amine bind but the -OH group points out into solvent, losing the -14 kJ/mol H-bond stabilization.\"},\"explanation\":{\"tr\":\"Easson-Stedman 3-nokta hipotezine göre (R)-adrenalin 3 noktadan tam bağlanırken, (S)-adrenalin tıpkı deoksiadrenalin (epinin) gibi yalnızca 2 temas noktası kurabilir (Slayt 25).\",\"ar\":\"وفق فرضية Easson-Stedman، يرسو (R)-adrenalin بثلاث نقاط كاملة، بينما يرتبط (S)-adrenalin بنقطتين فقط تماماً كالدوبامين/الإبينين منزوع الهيدروكسيل (شريحة 25).\",\"en\":\"Under the Easson-Stedman hypothesis, (R)-epinephrine engages 3 complementary loci, while (S)-epinephrine forms only 2 contacts like des-hydroxy epinine.\"}}},{\"id\":\"mc-mod2-les2-step-02\",\"stage\":\"question\",\"stageIndex\":2,\"type\":\"question\",\"title\":{\"tr\":\"Aktif Soru: Kiral Ayrım İçin Kaç Temas Noktası Gerekir?\",\"ar\":\"سؤال تفاعلي: كم نقطة اتصال تلزم للتمييز الكيرالي؟\",\"en\":\"Active Question: Minimum Points for Chiral Recognition\"},\"prompt\":{\"tr\":\"Asimetrik bir reseptör cebinin iki kiral ayna görüntüsünü (enantiyomeri) birbirinden kesin olarak ayırt edebilmesi ve birine yüksek afinite göstermesi için en az kaç uzaysal temas noktası gereklidir?\",\"ar\":\"كم عدد نقاط الاتصال الفراغية كحد أدنى التي يحتاجها جيب المستقبل غير المتناظر للتمييز الدقيق بين مصاوغين مرآويين وإبداء ألفة أعلى لأحدهما؟\",\"en\":\"For an asymmetric receptor pocket to unequivocally distinguish between two mirror-image enantiomers and display stereoselective affinity, what is the absolute minimum number of spatial contact points required?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-2a\",\"text\":{\"tr\":\"En az 3 temas noktası (3-boyutlu uzayda kiral bir asimetri düzlemi oluşturmak için zorunludur).\",\"ar\":\"3 نقاط اتصال على الأقل (لتحديد مستوٍ فراغي غير متناظر ثلاثي الأبعاد بشكل حاسم).\",\"en\":\"At least 3 contact points (essential to establish an asymmetric plane in 3D space).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika! Easson-Stedman hipotezine göre uzayda 2 nokta yalnızca bir eksen belirler; molekül bu eksen etrafında dönerek her iki enantiyomeri de aynı temasla bağlayabilir. Asimetrik ayrım için asgari 3 nokta şarttır.\",\"ar\":\"ممتاز! وفق فرضية Easson-Stedman، تحدد نقطتا اتصال خطاً مستقيماً يمكن للدواء الدوران حوله؛ التمييز الفراغي الكيرالي يتطلب 3 نقاط تماس حتماً.\",\"en\":\"Brilliant! By the Easson-Stedman hypothesis, two points merely define a line around which a ligand can rotate. Stereoselective chiral discrimination strictly requires at least 3 points.\"}},{\"id\":\"opt-2b\",\"text\":{\"tr\":\"Yalnızca 2 temas noktası yeterlidir; bir iyonik ve bir hidrofobik bağ enantiyomeri sabitlemek için kafi gelir.\",\"ar\":\"يكفي نقطتا اتصال فقط؛ فرابطة أيونية وأخرى كارهة للماء تكفيان لتثبيت المصاوغ.\",\"en\":\"Only 2 contact points are sufficient; one ionic and one hydrophobic bond lock the enantiomer.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"2-nokta yanılgısı: İki nokta etrafında serbest rotasyon mümkündür. Hem (R) hem (S) enantiyomeri aynı iki noktaya eşit güçle tutunabilir; kiral ayrım doğamaz.\",\"ar\":\"خطأ النقطتين: دوران الجزيء حول محور نقطتين يسمح لكلا المصاوغين بالارتباط بنفس القوة تماماً دون أي تمييز كيرالي.\",\"en\":\"Two-point misconception: Rotation around a two-point axis allows both (R) and (S) enantiomers to engage those two loci identically, producing zero chiral discrimination.\"}},{\"id\":\"opt-2c\",\"text\":{\"tr\":\"En az 4 temas noktası gerekir; çünkü karbon sp3 hibritleşmesinde 4 bağ taşır.\",\"ar\":\"يلزم 4 نقاط اتصال على الأقل لأن كربون sp3 يرتبط بأربعة روابط.\",\"en\":\"At least 4 contact points are required because an sp3 carbon has 4 valence bonds.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Dört bağ yanılgısı: Kiral karbonda 4 farklı grup bulunur, ancak dördüncü grup (genellikle küçük bir -H) reseptör yüzeyinden dışarıya doğru bakar. Yüzeyde 3 temas noktası kiral ayrım için hem gerekli hem yeterlidir.\",\"ar\":\"خطأ الروابط الأربعة: يحمل الكربون الكيرالي 4 مجموعات، لكن المجموعة الرابعة (غالباً -H) تتجه نحو الخارج؛ 3 نقاط تماس سطحية كافية وضرورية تماماً للتمييز الكيرالي.\",\"en\":\"Four-bond misconception: An sp3 chiral center has 4 substituents, but the 4th (often -H) projects away from the surface; 3 surface contacts are mathematically necessary and sufficient.\"}}]},\"technicalTerms\":[{\"term\":\"Easson-Stedman hipotezi\",\"arContext\":\"فرضية Easson-Stedman\"},{\"term\":\"asimetrik merkez\",\"arContext\":\"المركز غير المتناظر\"}],\"hints\":[{\"tr\":\"Düz bir çizgiyi (2 noktayı) çevirdiğinizde simetri bozulur mu, yoksa bir düzlem (3 nokta) mi gerekir?\",\"ar\":\"هل يكفي خط مستقيم (نقطتان) لكسر التناظر الفراغي، أم تحتاج إلى مستوٍ (3 نقاط)؟\",\"en\":\"Can two points define chirality, or do you require a 3-point plane to distinguish spatial orientation?\"},{\"tr\":\"İki temas noktası etrafında molekül dönebilir ve her iki enantiyomer de aynı 2 bağı kurabilir (dopamin örneğinde olduğu gibi).\",\"ar\":\"حول نقطتي تماس، يمكن للجزيء أن يدور ليحقق كلا المصاوغين نفس الارتباط (كما في الدوبامين).\",\"en\":\"A molecule can freely pivot around a two-point axis, permitting both enantiomers to engage equally.\"},{\"tr\":\"Easson-Stedman kuralına göre 3 boyutlu kiral seçicilik için asgari 3 tamamlayıcı etkileşim noktası şarttır.\",\"ar\":\"وفق قاعدة Easson-Stedman، يلزم ما لا يقل عن ثلاث نقاط تفاعل تكميلية للتمييز الكيرالي ثلاثي الأبعاد.\",\"en\":\"Under the Easson-Stedman rule, chiral discrimination strictly demands a minimum of 3 complementary contact loci.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":25}],\"config\":{\"options\":[{\"id\":\"opt-2a\",\"text\":\"En az 3 temas noktası (3-boyutlu uzayda kiral bir asimetri düzlemi oluşturmak için zorunludur).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika! Easson-Stedman hipotezine göre uzayda 2 nokta yalnızca bir eksen belirler; molekül bu eksen etrafında dönerek her iki enantiyomeri de aynı temasla bağlayabilir. Asimetrik ayrım için asgari 3 nokta şarttır.\"},{\"id\":\"opt-2b\",\"text\":\"Yalnızca 2 temas noktası yeterlidir; bir iyonik ve bir hidrofobik bağ enantiyomeri sabitlemek için kafi gelir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"2-nokta yanılgısı: İki nokta etrafında serbest rotasyon mümkündür. Hem (R) hem (S) enantiyomeri aynı iki noktaya eşit güçle tutunabilir; kiral ayrım doğamaz.\"},{\"id\":\"opt-2c\",\"text\":\"En az 4 temas noktası gerekir; çünkü karbon sp3 hibritleşmesinde 4 bağ taşır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Dört bağ yanılgısı: Kiral karbonda 4 farklı grup bulunur, ancak dördüncü grup (genellikle küçük bir -H) reseptör yüzeyinden dışarıya doğru bakar. Yüzeyde 3 temas noktası kiral ayrım için hem gerekli hem yeterlidir.\"}],\"revealedOutcome\":{\"tr\":\"İki temas noktası etrafında molekül 360° dönebilir; kiral asimetriyi ve enantiyomerik farkı sabitlemek için kesinlikle asgari 3 nokta gerekir.\",\"ar\":\"يمكن للجزيء الدوران بحرية حول محور يربط نقطتي تماس؛ يلزم حتماً 3 نقاط غير متحدة في خط لتثبيت التمايز الفراغي الكيرالي.\",\"en\":\"A molecule freely pivots around a two-point axis; stereochemical discrimination mathematically requires at least 3 non-coplanar contacts.\"},\"explanation\":{\"tr\":\"Uzayda iki nokta bir eksen tanımlar ve simetriyi kıramaz. Easson-Stedman kuralı kiral ayrım için en az 3 tamamlayıcı etkileşimi şart koşar (Slayt 25).\",\"ar\":\"تحدد نقطتان في الفضاء محوراً مستقيماً عاجزاً عن كسر التناظر. تشترط قاعدة Easson-Stedman ثلاث نقاط تكميلية على الأقل للتمييز الفراغي (شريحة 25).\",\"en\":\"Two points define a linear axis unable to break symmetry. The Easson-Stedman rule proves chiral recognition demands at least 3 contact loci.\"}}},{\"id\":\"mc-mod2-les2-step-03\",\"stage\":\"intuition\",\"stageIndex\":3,\"type\":\"intuition\",\"title\":{\"tr\":\"Sezgisel Model: Sağ El ve Sağ Eldiven Uyuşumu\",\"ar\":\"النموذج الحسي: اليد اليمنى والقفاز الأيمن\",\"en\":\"Intuitive Mental Model: The Right Hand in the Right Glove\"},\"prompt\":{\"tr\":\"Elinizi bir eldivene soktuğunuzu düşünün. Sağ elinizi sağ eldivene oturtabilirsiniz ama sol eldivene oturmaz. Neden simetrik bir top her iki eldivene de girerken eliniz giremez?\",\"ar\":\"تخيل ارتداء قفاز. يدك اليمنى تلائم القفاز الأيمن حصراً ولا تلائم الأيسر. لماذا تدخل كرة متناظرة في كلا القفازين بسلاسة بينما تعجز يدك؟\",\"en\":\"Consider slipping your hand into a glove. Your right hand fits a right glove, but never a left glove. Why does a symmetric tennis ball fit either glove easily, while your hand cannot?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-3a\",\"text\":{\"tr\":\"Sağ el en az 3 asimetrik referans noktasına sahiptir (başparmak, avuç içi, parmak uçları); top ise tekdüze simetriktir.\",\"ar\":\"تمتلك اليد 3 نقاط إسناد غير متناظرة على الأقل (الإبهام، الراحة، الأصابع)، بينما الكرة متناظرة منتظمة.\",\"en\":\"The hand possesses at least 3 asymmetric reference features (thumb, palm, fingers), whereas a ball is uniformly symmetric.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Tam olarak öyle! Eldiven kiral bir reseptördür. Başparmak yuvası, avuç yüzeyi ve parmak yuvaları 3 farklı koordinat oluşturur. Top akiraldir (2 temas noktası gibi), bu yüzden her iki eldivene de uyar.\",\"ar\":\"بالضبط! القفاز مستقبل كيرالي بـ 3 إحداثيات (الإبهام والراحة والأصابع). والكرة متناظرة عديمة الكيرالية فتلائم كلا القفازين دون تمييز.\",\"en\":\"Spot on! The glove is a chiral receptor with 3 distinct coordinates (thumb, palm, fingers). A symmetric ball is achiral, docking into either glove identically.\"}},{\"id\":\"opt-3b\",\"text\":{\"tr\":\"Eldiven kumaşı sağ elin yaydığı pozitif elektrostatik yükü iter, sol eli çeker.\",\"ar\":\"نسيج القفاز يتنافر مع الشحنة الموجبة لليد اليمنى وينجذب لليد اليسرى.\",\"en\":\"Glove fabric repels the positive electrostatic field of the right hand and attracts the left.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Fiziksel yük yanılgısı: Sorun elektriksel yük değil, 3 boyutlu kiral geometrinin uzaysal çakışmazlığıdır.\",\"ar\":\"خطأ الشحنة: المسألة لا تتعلق بشحنات كهربائية بل بعدم التطابق الهندسي الفراغي ثلاثي الأبعاد.\",\"en\":\"Electrostatic misconception: The obstacle is not charge repulsion, but 3D geometric non-superimposability.\"}},{\"id\":\"opt-3c\",\"text\":{\"tr\":\"Sağ el sol eldivene girerken kovalent bağları parçalayarak kumaşı deler.\",\"ar\":\"اليد اليمنى تمزق الروابط التساهمية في القفاز الأيسر عند محاولة ارتدائه.\",\"en\":\"The right hand shears covalent bonds of the left glove when forced inside.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kovalent yıkım yanılgısı: Kiral uyumsuzluk bağ kopması değil, sterik çakışma ve temas noktalarının boşlukta kalmasıdır.\",\"ar\":\"خطأ التخريب التساهمي: التنافر الكيرالي ينشأ من إعاقة فراغية وابتعاد نقاط التماس، وليس من كسر روابط تساهمية.\",\"en\":\"Destruction misconception: Stereochemical mismatch is pure steric clash and misaligned contacts, not covalent bond breaking.\"}}]},\"technicalTerms\":[{\"term\":\"uzaysal komplementerlik\",\"arContext\":\"التطابق الفراغي\"},{\"term\":\"kiral ayrım\",\"arContext\":\"التمييز الكيرالي\"}],\"hints\":[{\"tr\":\"Başparmak, avuç içi ve parmakların oluşturduğu 3 boyutlu üçgeni hayal edin.\",\"ar\":\"تخيل المثلث ثلاثي الأبعاد المتشكل من الإبهام وراحة اليد والأصابع.\",\"en\":\"Visualize the 3D triangular coordinate frame formed by thumb, palm, and fingers.\"},{\"tr\":\"Eğer sadece 2 özelliğiniz olsaydı (örneğin sadece silindirik bir kol), eldiven fark etmezdi.\",\"ar\":\"لو كنت تملك ميزتين فقط (كذراع أسطواني)، لما اختلف القفاز الأيمن عن الأيسر.\",\"en\":\"If you had only 2 reference features (like a cylinder), either glove would fit equally well.\"},{\"tr\":\"Kiralitenin tanınması için eldivenin 3 temas cebinin (başparmak yuvası, avuç yüzeyi, parmak yuvaları) elin 3 noktasıyla eşleşmesi şarttır.\",\"ar\":\"للتمييز الكيرالي، يجب أن تتطابق جيوب القفاز الثلاثة مع معالم اليد الثلاثة في آن واحد.\",\"en\":\"Chiral recognition requires 3 distinct receptor alcoves matching 3 ligand pharmacophores simultaneously.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":13}],\"config\":{\"options\":[{\"id\":\"opt-3a\",\"text\":\"Sağ el en az 3 asimetrik referans noktasına sahiptir (başparmak, avuç içi, parmak uçları); top ise tekdüze simetriktir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Tam olarak öyle! Eldiven kiral bir reseptördür. Başparmak yuvası, avuç yüzeyi ve parmak yuvaları 3 farklı koordinat oluşturur. Top akiraldir (2 temas noktası gibi), bu yüzden her iki eldivene de uyar.\"},{\"id\":\"opt-3b\",\"text\":\"Eldiven kumaşı sağ elin yaydığı pozitif elektrostatik yükü iter, sol eli çeker.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Fiziksel yük yanılgısı: Sorun elektriksel yük değil, 3 boyutlu kiral geometrinin uzaysal çakışmazlığıdır.\"},{\"id\":\"opt-3c\",\"text\":\"Sağ el sol eldivene girerken kovalent bağları parçalayarak kumaşı deler.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kovalent yıkım yanılgısı: Kiral uyumsuzluk bağ kopması değil, sterik çakışma ve temas noktalarının boşlukta kalmasıdır.\"}],\"revealedOutcome\":{\"tr\":\"Eldiven 3 boyutlu kiral bir ceptir (başparmak, avuç, parmak yuvaları); sağ el tam otururken sol el uyumsuzluk yaşar. Top ise akiraldir.\",\"ar\":\"القفاز جيب كيرالي ثلاثي الأبعاد (الإبهام والراحة والأصابع). تلائمه اليد اليمنى حصراً بينما الكرة متناظرة عديمة الكيرالية فتلائم الاثنين.\",\"en\":\"A glove is a 3D chiral pocket (thumb, palm, fingers). The right hand fits snugly while a symmetric ball lacks chirality and enters either glove.\"},\"explanation\":{\"tr\":\"Reseptörler L-amino asitlerden yapılmış şiral makromoleküllerdir. Ligandın 3 farklı noktası reseptörün 3 cebiyle eşleştiğinde seçicilik doğar (Slayt 2, 25).\",\"ar\":\"المستقبلات جزيئات ضخمة كيرالية مبنية من L-أحماض أمينية. تنشأ النوعية عندما تتطابق 3 نقاط في الليغاند مع 3 جيوب في المستقبل (شريحة 2، 25).\",\"en\":\"Receptors are chiral macromolecules built from L-amino acids. Selectivity arises when 3 pharmacophores align with 3 receptor sub-pockets.\"}}},{\"id\":\"mc-mod2-les2-step-04\",\"stage\":\"visual_explanation\",\"stageIndex\":4,\"type\":\"visual_explanation\",\"title\":{\"tr\":\"Görsel Reseptör Mimarisi: Adrenerjik Bağlanma Cebi\",\"ar\":\"الهندسة البصرية للمستقبل: جيب الارتباط الأدريناليني\",\"en\":\"Visual Architecture: The Adrenergic Binding Alcove\"},\"prompt\":{\"tr\":\"Beta-adrenerjik reseptör cebini inceleyin: Asp113 iyonik bir kuyu, Ser204/207 hidrojen bağı sırtı ve Phe290 aromatik ceptir. (R)-adrenalin bu üç noktaya nasıl aynı anda kenetlenir?\",\"ar\":\"تأمل جيب مستقبل بيتا الأدريناليني: يمثل Asp113 فجوة أيونية، وSer204/207 جسراً هيدروجينياً، وPhe290 جيباً عطرياً. كيف يرسو (R)-adrenalin في هذه النقاط الثلاث معاً؟\",\"en\":\"Examine the beta-adrenergic pocket: Asp113 forms an anionic pit, Ser204/207 forms an H-bonding ridge, and Phe290 provides aromatic stacking. How does (R)-epinephrine dock into all three simultaneously?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-4a\",\"text\":{\"tr\":\"Katekol halkası Phe290'a pi-istiflenir, protonlanmış sekonder amin Asp113 ile tuz köprüsü kurar, kiral (R)-beta-OH ise serin kalıntısıyla hidrojen bağı yapar.\",\"ar\":\"تتراكب حلقة الكاتيكول مع Phe290، ويشكل الأمين الثانوي جسراً أيونياً مع Asp113، وترتبط (R)-beta-OH بهيدروجين مع السيرين.\",\"en\":\"The catechol ring pi-stacks with Phe290, protonated secondary amine forms a salt bridge with Asp113, and chiral (R)-beta-OH forms an H-bond with serine.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel! (R)-adrenalin üç farmakoforunu reseptörün tamamlayıcı üç bölgesine aynı anda oturtarak -42 kJ/mol bağlanma serbest enerjisi elde eder. Üç nokta da eksiksiz kilitlenir.\",\"ar\":\"ممتاز! يرسو (R)-adrenalin بمجموعاته الثلاث في المواقع التكميلية الثلاثة محرراً طاقة ارتباط -42 kJ/mol بتعشيق كامل.\",\"en\":\"Perfect! (R)-epinephrine docks all three pharmacophores into complementary receptor zones, yielding -42 kJ/mol binding free energy.\"}},{\"id\":\"opt-4b\",\"text\":{\"tr\":\"Katekol halkası Asp113 ile kovalent ester bağı oluşturur ve diğer iki grup serbest kalır.\",\"ar\":\"تشكل حلقة الكاتيكول رابطة إستر تساهمية مع Asp113 وتبقى المجموعتان طليقتين.\",\"en\":\"The catechol ring forms a covalent ester bond with Asp113, leaving the other groups free.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kovalent ester yanılgısı: Aspartat bir karboksilattır; katekolle ester yapmaz. Protonlanmış amonyumu iyonik elektrostatik çekimle bağlar.\",\"ar\":\"خطأ الإستر التساهمي: لا يشكل الأسبارتات إستراً مع الكاتيكول، بل يربط الأمين الكاتيوني المشحون بجسر ملحي أيوني.\",\"en\":\"Covalent ester misconception: Asp113 does not esterify catechol; it forms an electrostatic ionic salt bridge with the cationic protonated amine.\"}},{\"id\":\"opt-4c\",\"text\":{\"tr\":\"Sekonder amin Phe290 içine gömülerek van der Waals bağı kurar, katekol ise çözücüye bakar.\",\"ar\":\"ينغمس الأمين الثانوي في Phe290 ليشكل روابط فان دير فالس بينما يواجه الكاتيكول المذيب.\",\"en\":\"The secondary amine buries into Phe290 for van der Waals contacts while catechol points to solvent.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Ters yönelim yanılgısı: Yüklü amin hidrofiliktir, aromatik cebe değil anyonik Asp113'e yönelir. Apolar katekol halkası Phe290 aromatik cebine oturur.\",\"ar\":\"خطأ التوجيه المعكوس: الأمين المشحون محب للماء فينجذب لأسبارتات Asp113 الأيوني، بينما تقبع حلقة الكاتيكول في جيب Phe290 العطري.\",\"en\":\"Inverted orientation misconception: The charged amine seeks anionic Asp113, while the aromatic catechol ring nests into the Phe290 pi-stacking alcove.\"}}]},\"technicalTerms\":[{\"term\":\"adrenerjik reseptör\",\"arContext\":\"المستقبل الأدريناليني\"},{\"term\":\"farmakofor\",\"arContext\":\"الفارماكوفور\"}],\"hints\":[{\"tr\":\"Her fonksiyonel grubun karşıt kimyasal doğasını eşleştirin: (+) yüklü amin (-) yüklü aspartatı arar.\",\"ar\":\"طابق الطبيعة الكيميائية لكل مجموعة: الأمين موجب الشحنة ينجذب لأسبارتات سالب الشحنة.\",\"en\":\"Pair complementary chemistries: positively charged ammonium seeks negatively charged aspartate carboxylate.\"},{\"tr\":\"Aromatik katekol halkası aromatik fenilalanin ile etkileşir; polar alkol ise serin kalıntısıyla H-bağı kurar.\",\"ar\":\"تتفاعل حلقة الكاتيكول العطرية مع الفينيل ألانين، بينما يشكل الكحول رابطة هيدروجينية مع السيرين.\",\"en\":\"The aromatic catechol interacts with aromatic phenylalanine, while the polar alcohol donates an H-bond to serine.\"},{\"tr\":\"(R)-adrenalin 3 farmakoforunu (amin, katekol, beta-OH) reseptörün 3 tamamlayıcı cebine (Asp113, Phe290, Ser204) aynı anda oturtarak tam kenetlenir.\",\"ar\":\"يحقق (R)-adrenalin تعشيقاً تاماً بتطابق معالمه الثلاثة مع جيوب المستقبل الثلاثة (Asp113, Phe290, Ser204).\",\"en\":\"(R)-epinephrine aligns its three pharmacophoric groups simultaneously into Asp113, Phe290, and Ser204.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":25}],\"config\":{\"options\":[{\"id\":\"opt-4a\",\"text\":\"Katekol halkası Phe290'a pi-istiflenir, protonlanmış sekonder amin Asp113 ile tuz köprüsü kurar, kiral (R)-beta-OH ise serin kalıntısıyla hidrojen bağı yapar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel! (R)-adrenalin üç farmakoforunu reseptörün tamamlayıcı üç bölgesine aynı anda oturtarak -42 kJ/mol bağlanma serbest enerjisi elde eder. Üç nokta da eksiksiz kilitlenir.\"},{\"id\":\"opt-4b\",\"text\":\"Katekol halkası Asp113 ile kovalent ester bağı oluşturur ve diğer iki grup serbest kalır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kovalent ester yanılgısı: Aspartat bir karboksilattır; katekolle ester yapmaz. Protonlanmış amonyumu iyonik elektrostatik çekimle bağlar.\"},{\"id\":\"opt-4c\",\"text\":\"Sekonder amin Phe290 içine gömülerek van der Waals bağı kurar, katekol ise çözücüye bakar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Ters yönelim yanılgısı: Yüklü amin hidrofiliktir, aromatik cebe değil anyonik Asp113'e yönelir. Apolar katekol halkası Phe290 aromatik cebine oturur.\"}],\"revealedOutcome\":{\"tr\":\"(R)-adrenalin Asp113 ile tuz köprüsü, Phe290 ile pi-istiflenmesi ve Ser kalıntısıyla H-bağı kurarak 3 noktadan kilitlenir (-42 kJ/mol).\",\"ar\":\"يرسو (R)-adrenalin بثلاث نقاط: جسر ملحي مع Asp113، وتراصف بي مع Phe290، ورابطة هيدروجينية مع السيرين محققاً -42 kJ/mol.\",\"en\":\"(R)-epinephrine anchors at 3 loci: salt bridge with Asp113, pi-stacking with Phe290, and H-bond with Ser, yielding -42 kJ/mol.\"},\"explanation\":{\"tr\":\"Beta-2 adrenerjik reseptörün bağlanma cebi Asp113 (TM3), Ser204/207 (TM5) ve Phe290 (TM6) amino asitleriyle 3 boyutlu kiral üçgeni oluşturur (Slayt 4, 25).\",\"ar\":\"يشكل جيب مستقبل بيتا-2 الأدريناليني مثلثاً فراغياً كيرالياً عبر الثمالات Asp113 (TM3) و Ser204/207 (TM5) و Phe290 (TM6) (شريحة 4، 25).\",\"en\":\"The beta-2 adrenergic receptor binding pocket forms a 3D chiral triad via Asp113 (TM3), Ser204/207 (TM5), and Phe290 (TM6).\"}}},{\"id\":\"mc-mod2-les2-step-05\",\"stage\":\"interactive_artifact\",\"stageIndex\":5,\"type\":\"receptor_ligand_matcher\",\"widgetType\":\"ReceptorLigandMatcher\",\"title\":{\"tr\":\"İnteraktif Laboratuvar: Easson-Stedman 3-Noktalı Eşleşme\",\"ar\":\"مختبر تفاعلي: مطابقة Easson-Stedman ثلاثية النقاط\",\"en\":\"Interactive Lab: 3-Point Easson-Stedman Receptor Matching\"},\"prompt\":{\"tr\":\"(R)-adrenalinin fonksiyonel gruplarını beta-2 adrenerjik reseptörün tamamlayıcı amino asit cepleriyle eşleştirin. 3 noktalı kusursuz kenetlenmeyi tamamlayıp afiniteyi doğrulayın.\",\"ar\":\"طابق المجموعات الوظيفية لـ (R)-adrenalin مع ثمالات الأحماض الأمينية المكملة في مستقبل بيتا-2 الأدريناليني. أكمل التعشيق ثلاثي النقاط وتحقق من الألفة.\",\"en\":\"Match the functional groups of (R)-epinephrine with complementary amino acid residues in the beta-2 adrenergic receptor. Complete the 3-point attachment to verify affinity.\"},\"predictThenReveal\":false,\"config\":{\"title\":\"Easson-Stedman 3-Noktalı Adrenerjik Eşleşme\",\"prompt\":\"(R)-adrenalin gruplarını reseptörün tamamlayıcı amino asit cepleriyle eşleştirin.\",\"drugName\":\"(R)-Adrenalin\",\"receptorName\":\"Beta-2 Adrenerjik Reseptör (β2-AR)\",\"pairs\":[{\"id\":\"pair_amine\",\"drugGroup\":\"Protonlanmış Sekonder Amin (-NH2+CH3)\",\"correctResidueId\":\"res_asp113\",\"bondType\":\"ionic\",\"energyKcalMol\":\"-5 to -10 kcal/mol\",\"explanation\":\"Asp113 TM3 karboksilat anyonu ile güçlü bir tuz köprüsü elektrostatik bağı kurar.\"},{\"id\":\"pair_beta_oh\",\"drugGroup\":\"Kiral Alifatik (R)-β-OH Grubu\",\"correctResidueId\":\"res_asn293\",\"bondType\":\"h_bond\",\"energyKcalMol\":\"-3 to -5 kcal/mol\",\"explanation\":\"Asn293/Ser165 yan zinciri ile kiral yönelimli hidrojen bağı yapar; (S)-izomerinde bu temas kaybolur.\"},{\"id\":\"pair_catechol\",\"drugGroup\":\"Aromatik Katekol Halkası (3,4-(OH)2-Ph)\",\"correctResidueId\":\"res_phe290\",\"bondType\":\"pi_pi\",\"energyKcalMol\":\"-3 to -5 kcal/mol\",\"explanation\":\"Phe290 TM6 fenil halkası ile pi-pi istiflenmesi ve Ser204/207 ile ek H-bağları kurar.\"}],\"residues\":[{\"id\":\"res_asp113\",\"residueName\":\"Asp113 (TM3 Karboksilat Anyonu)\",\"description\":\"Negatif yüklü elektrostatik anyonik tuz köprüsü cebi\"},{\"id\":\"res_asn293\",\"residueName\":\"Asn293/Ser165 (Kiral β-OH Cebi)\",\"description\":\"Alifatik hidroksil grubu için spesifik hidrojen bağı akseptörü/donörü\"},{\"id\":\"res_phe290\",\"residueName\":\"Phe290 (TM6 Aromatik Halka Cebi)\",\"description\":\"Aromatik halka için pi-pi istiflenme ve van der Waals cebi\"},{\"id\":\"res_leu275\",\"residueName\":\"Leu275 (Apolar Alifatik Yan Zincir)\",\"description\":\"Hidrofobik apolar kalıntı (katyon veya H-bağı yapmaz)\"},{\"id\":\"res_glu107\",\"residueName\":\"Glu107 (Dış Hücresel İlmek Karboksilatı)\",\"description\":\"Bağlanma cebinin dışında kalan çözücüye açık kalıntı\"}],\"source\":{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":25}},\"technicalTerms\":[{\"term\":\"tuz köprüsü\",\"arContext\":\"الجسر الملحي\"},{\"term\":\"pi-pi istiflenmesi\",\"arContext\":\"تراكب باي-باي (pi-pi stacking)\"}],\"hints\":[{\"tr\":\"Pozitif yüklü amonyum grubunu negatif yüklü aspartat karboksilatına bağlayın.\",\"ar\":\"صل مجموعة الأمونيوم موجبة الشحنة بأسبارتات كربوكسيلات سالب الشحنة.\",\"en\":\"Connect the positively charged ammonium group to the negatively charged aspartate carboxylate.\"},{\"tr\":\"Alifatik beta-hidroksil hidrojen bağı akseptörü olan Asn293/Ser165 cebine yerleşir.\",\"ar\":\"تستقر مجموعة بيتا-هيدروكسيل الأليفاتية في جيب Asn293 المستقبل للروابط الهيدروجينية.\",\"en\":\"The aliphatic beta-hydroxyl docks into the Asn293/Ser165 hydrogen-bonding acceptor alcove.\"},{\"tr\":\"Amin -> Asp113, (R)-beta-OH -> Asn293, Katekol -> Phe290 eşleşmesini yapın.\",\"ar\":\"طابق الأمين مع Asp113، و (R)-beta-OH مع Asn293، والكاتيكول مع Phe290.\",\"en\":\"Pair Amine -> Asp113, (R)-beta-OH -> Asn293, and Catechol -> Phe290 to complete docking.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":25}],\"widget\":{\"type\":\"ReceptorLigandMatcher\",\"config\":{\"title\":\"Easson-Stedman 3-Noktalı Adrenerjik Eşleşme\",\"prompt\":\"(R)-adrenalin gruplarını reseptörün tamamlayıcı amino asit cepleriyle eşleştirin.\",\"drugName\":\"(R)-Adrenalin\",\"receptorName\":\"Beta-2 Adrenerjik Reseptör (β2-AR)\",\"pairs\":[{\"id\":\"pair_amine\",\"drugGroup\":\"Protonlanmış Sekonder Amin (-NH2+CH3)\",\"correctResidueId\":\"res_asp113\",\"bondType\":\"ionic\",\"energyKcalMol\":\"-5 to -10 kcal/mol\",\"explanation\":\"Asp113 TM3 karboksilat anyonu ile güçlü bir tuz köprüsü elektrostatik bağı kurar.\"},{\"id\":\"pair_beta_oh\",\"drugGroup\":\"Kiral Alifatik (R)-β-OH Grubu\",\"correctResidueId\":\"res_asn293\",\"bondType\":\"h_bond\",\"energyKcalMol\":\"-3 to -5 kcal/mol\",\"explanation\":\"Asn293/Ser165 yan zinciri ile kiral yönelimli hidrojen bağı yapar; (S)-izomerinde bu temas kaybolur.\"},{\"id\":\"pair_catechol\",\"drugGroup\":\"Aromatik Katekol Halkası (3,4-(OH)2-Ph)\",\"correctResidueId\":\"res_phe290\",\"bondType\":\"pi_pi\",\"energyKcalMol\":\"-3 to -5 kcal/mol\",\"explanation\":\"Phe290 TM6 fenil halkası ile pi-pi istiflenmesi ve Ser204/207 ile ek H-bağları kurar.\"}],\"residues\":[{\"id\":\"res_asp113\",\"residueName\":\"Asp113 (TM3 Karboksilat Anyonu)\",\"description\":\"Negatif yüklü elektrostatik anyonik tuz köprüsü cebi\"},{\"id\":\"res_asn293\",\"residueName\":\"Asn293/Ser165 (Kiral β-OH Cebi)\",\"description\":\"Alifatik hidroksil grubu için spesifik hidrojen bağı akseptörü/donörü\"},{\"id\":\"res_phe290\",\"residueName\":\"Phe290 (TM6 Aromatik Halka Cebi)\",\"description\":\"Aromatik halka için pi-pi istiflenme ve van der Waals cebi\"},{\"id\":\"res_leu275\",\"residueName\":\"Leu275 (Apolar Alifatik Yan Zincir)\",\"description\":\"Hidrofobik apolar kalıntı (katyon veya H-bağı yapmaz)\"},{\"id\":\"res_glu107\",\"residueName\":\"Glu107 (Dış Hücresel İlmek Karboksilatı)\",\"description\":\"Bağlanma cebinin dışında kalan çözücüye açık kalıntı\"}],\"source\":{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":25}}}},{\"id\":\"mc-mod2-les2-step-06\",\"stage\":\"guided_discovery\",\"stageIndex\":6,\"type\":\"guided_discovery\",\"title\":{\"tr\":\"Rehberli Keşif: Eudismik Oran ve Pfeiffer Kuralı\",\"ar\":\"استكشاف موجه: النسبة الإيوديزمية وقاعدة Pfeiffer\",\"en\":\"Guided Discovery: Eudismic Ratio and Pfeiffer's Rule\"},\"prompt\":{\"tr\":\"Eutomerin afinitesinin distomere oranına Eudismik Oran (ER) denir. Pfeiffer kuralına göre, bir ilacın reseptörüne olan afinitesi arttıkça (gereken dozu düştükçe) ER değeri nasıl değişir?\",\"ar\":\"تسمى نسبة ألفة المصاوغ الأقوى إلى الأضعف بالنسبة الإيوديزمية (ER). وفق قاعدة Pfeiffer، كلما زادت ألفة الدواء نحو مستقبله (وقلت جرعته المطلوبة)، كيف تتغير قيمة ER؟\",\"en\":\"The ratio of eutomer to distomer potency is the Eudismic Ratio (ER). According to Pfeiffer's Rule, as a drug's target affinity increases (dose decreases), how does its ER change?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-6a\",\"text\":{\"tr\":\"ER katlanarak artar; çünkü yüksek afinite reseptör cebine kusursuz uzaysal komplementerlik gerektirir ve kiral kusurlara tolerans sıfırlanır.\",\"ar\":\"ترتفع ER بشكل هائل؛ لأن الألفة العالية تتطلب تطابقاً فراغياً مثالياً في جيب المستقبل وتنعدم مرونة التسامح مع العيوب الكيرالية.\",\"en\":\"ER increases dramatically; high affinity demands strict 3D complementarity, leaving near-zero tolerance for chiral misfit.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Carl Pfeiffer (1956) göstermiştir ki, pikomolar/nanomolar afiniteli ilaçlar reseptör cebini milimetrik doldurur; distomerdeki tek bir eksik bağ afiniteyi 100-1000 kat düşürür.\",\"ar\":\"صحيح! أثبت كارل فايفر (1956) أن الأدوية عالية الألفة تملأ جيب المستقبل بإحكام تام؛ وغياب رابطة واحدة في المصاوغ الأضعف يخفض الألفة مئات الأضعاف.\",\"en\":\"Correct! Carl Pfeiffer (1956) established that high-affinity ligands occupy pockets with rigid complementarity; losing one contact penalizes potency 100- to 1000-fold.\"}},{\"id\":\"opt-6b\",\"text\":{\"tr\":\"ER bire yaklaşır (1.0); çünkü yüksek afiniteli ilaçlar reseptörü her yönelimde bağlayabilir.\",\"ar\":\"تقترب ER من الواحد (1.0)؛ لأن الأدوية عالية الألفة ترتبط بالمستقبل في أي اتجاه فراغي.\",\"en\":\"ER approaches unity (1.0); high-affinity drugs can bind the pocket regardless of orientation.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Ters tolerans yanılgısı: Yüksek afinite kiral toleransı artırmaz, sıfırlar! Düşük afiniteli (mikromolar) ilaçlar gevşek bağlandığı için kiral kusurları tolere eder ve ER 1'e yaklaşır.\",\"ar\":\"خطأ التسامح المعكوس: الألفة العالية تلغي التسامح الكيرالي تماماً! الأدوية ضعيفة الألفة فقط ترتبط برخاوة وتتسامح مع العيوب الكيرالية مقتربة من 1.\",\"en\":\"Inverted tolerance misconception: High affinity abolishes chiral tolerance. Only low-affinity drugs bind loosely enough to tolerate chiral misfits (ER -> 1).\"}},{\"id\":\"opt-6c\",\"text\":{\"tr\":\"ER sabit kalır; eudismik oran sadece molekül ağırlığına bağlı olup afiniteyle değişmez.\",\"ar\":\"تبقى ER ثابتة؛ فالنسبة الإيوديزمية تعتمد حصراً على الوزن الجزيئي ولا تتأثر بالألفة.\",\"en\":\"ER remains constant; eudismic ratios depend solely on molecular weight rather than target affinity.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Molekül ağırlığı yanılgısı: İki enantiyomerin molekül ağırlığı ve atom bileşimi tamamen aynıdır. ER doğrudan 3 boyutlu reseptör kilit-anahtar seçiciliğine bağlıdır.\",\"ar\":\"خطأ الوزن الجزيئي: يمتلك المصاوغان نفس الوزن الجزيئي تماماً. ترتبط ER مباشرة بدرجة الإحكام الفراغي في جيب المستقبل.\",\"en\":\"Molecular weight misconception: Enantiomers share identical molecular weight; ER reflects pocket stereoselectivity exclusively.\"}}]},\"technicalTerms\":[{\"term\":\"eudismik oran\",\"arContext\":\"النسبة الإيوديزمية (eudismic ratio)\"},{\"term\":\"Pfeiffer kuralı\",\"arContext\":\"قاعدة Pfeiffer\"},{\"term\":\"ötomer\",\"arContext\":\"المصاوغ الفعال (eutomer)\"},{\"term\":\"distomer\",\"arContext\":\"المصاوغ الأضعف (distomer)\"}],\"hints\":[{\"tr\":\"Çok dar ve hassas bir anahtar deliğine milimetrik yanlış bir anahtar soktuğunuzu düşünün.\",\"ar\":\"تخيل إدخال مفتاح به خطأ ميكروني في قفل شديد الدقة والإحكام.\",\"en\":\"Imagine trying to insert an imperfect key into a microscopic, ultra-precise lock.\"},{\"tr\":\"Pfeiffer (1956) gözlemlemiştir: Mikromolar afiniteli ilaçlarda enantiyomer farkı az iken, pikomolar ilaçlarda fark yüzlerce kata çıkar.\",\"ar\":\"لاحظ فايفر (1956): الفارق بين المصاوغات طفيف في الأدوية الميكرومولية، لكنه يتسع لمئات الأضعاف في الأدوية البيكومولية.\",\"en\":\"Pfeiffer (1956) noted: micromolar ligands show minimal enantiomer differences, whereas picomolar ligands display 100- to 1000-fold gaps.\"},{\"tr\":\"Pfeiffer kuralı gereğince afinite arttıkça reseptör-ligand uyumu sıkılaşır; distomerin eksik bağı afiniteyi dramatik biçimde düşürür ve ER katlanarak artar.\",\"ar\":\"وفق قاعدة Pfeiffer، كلما زادت الألفة زاد إحكام الجيب، فتهوي ألفة المصاوغ الناقص وتتضاعف ER.\",\"en\":\"By Pfeiffer's rule, tighter baseline binding enforces rigid stereocomplementarity, magnifying the eudismic ratio.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":28}],\"config\":{\"options\":[{\"id\":\"opt-6a\",\"text\":\"ER katlanarak artar; çünkü yüksek afinite reseptör cebine kusursuz uzaysal komplementerlik gerektirir ve kiral kusurlara tolerans sıfırlanır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Carl Pfeiffer (1956) göstermiştir ki, pikomolar/nanomolar afiniteli ilaçlar reseptör cebini milimetrik doldurur; distomerdeki tek bir eksik bağ afiniteyi 100-1000 kat düşürür.\"},{\"id\":\"opt-6b\",\"text\":\"ER bire yaklaşır (1.0); çünkü yüksek afiniteli ilaçlar reseptörü her yönelimde bağlayabilir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Ters tolerans yanılgısı: Yüksek afinite kiral toleransı artırmaz, sıfırlar! Düşük afiniteli (mikromolar) ilaçlar gevşek bağlandığı için kiral kusurları tolere eder ve ER 1'e yaklaşır.\"},{\"id\":\"opt-6c\",\"text\":\"ER sabit kalır; eudismik oran sadece molekül ağırlığına bağlı olup afiniteyle değişmez.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Molekül ağırlığı yanılgısı: İki enantiyomerin molekül ağırlığı ve atom bileşimi tamamen aynıdır. ER doğrudan 3 boyutlu reseptör kilit-anahtar seçiciliğine bağlıdır.\"}],\"revealedOutcome\":{\"tr\":\"Afinite arttıkça Eudismik Oran (ER) katlanarak yükselir; çünkü yüksek afinite kusursuz kilit-anahtar uyumu gerektirir (Pfeiffer Kuralı).\",\"ar\":\"مع ازدياد الألفة ترتفع النسبة اليوديزمية (ER) أُسياً؛ لأن الألفة الفائقة تتطلب تطابقاً كيرالياً ميليمترياً (قاعدة Pfeiffer).\",\"en\":\"As affinity surges, Eudismic Ratio (ER) increases exponentially; high affinity strictly demands precise lock-and-key complementarity.\"},\"explanation\":{\"tr\":\"Pfeiffer (1956) kuralı: Yüksek afiniteli (nM/pM) ilaçlarda cebin kiral toleransı sıfırdır; gevşek bağlanan mikromolar ilaçlarda ise ER 1'e yaklaşır (Slayt 28).\",\"ar\":\"قاعدة Pfeiffer (1956): في أدوية الألفة الفائقة (nM/pM) ينعدم التسامح مع العيوب الكيرالية؛ بينما تقترب ER من 1 في الأدوية الضعيفة (شريحة 28).\",\"en\":\"Pfeiffer's rule (1956): High-affinity drugs exhibit extreme chiral discrimination; weakly bound ligands tolerate stereocenter inversion.\"}}},{\"id\":\"mc-mod2-les2-step-07\",\"stage\":\"formal_explanation\",\"stageIndex\":7,\"type\":\"formal_explanation\",\"title\":{\"tr\":\"Termodinamik Temel: Kiral Serbest Enerji Farkı\",\"ar\":\"الأساس الديناميكي الحراري: فرق الطاقة الحرة الكيرالية\",\"en\":\"Thermodynamic Foundation: Chiral Free Energy Gap\"},\"prompt\":{\"tr\":\"Vücut sıcaklığında (310 K) her 1.42 kcal/mol (5.94 kJ/mol) serbest enerji farkı afinitada 10 kat değişim yaratır. (R)-adrenalin ekstra -3.3 kcal/mol (-14 kJ/mol) kazanıyorsa ER nedir?\",\"ar\":\"عند حرارة الجسم (310 K)، يمنح كل 1.42 kcal/mol فارقاً في الألفة بعشرة أضعاف. إذا كسب (R)-adrenalin طاقة إضافية قدرها -3.3 kcal/mol (-14 kJ/mol)، فما هي قيمة ER؟\",\"en\":\"At body temperature (310 K), every 1.42 kcal/mol (5.94 kJ/mol) free energy shift produces a 10-fold affinity change. If (R)-epinephrine gains an extra -3.3 kcal/mol (-14 kJ/mol), what is the ER?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-7a\",\"text\":{\"tr\":\"Yaklaşık 200 kat (ΔΔG / 1.42 = 3.3 / 1.42 ≈ 2.32 log birimi; 10^2.32 ≈ 210 kat).\",\"ar\":\"حوالي 200 ضعف (ΔΔG / 1.42 = 3.3 / 1.42 ≈ 2.32 في المقياس اللوغاريتمي؛ 10^2.32 ≈ 210 أضعاف).\",\"en\":\"Approximately 200-fold (ΔΔG / 1.42 = 3.3 / 1.42 ≈ 2.32 log decades; 10^2.32 ≈ 210-fold).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz termodinamik hesap! ΔΔG° = 2.303 RT log10(ER). 3.3 kcal/mol'lük tek bir hidrojen bağı enerjisi, logaritmik ilişki sebebiyle afiniteyi 200 kattan fazla artırır.\",\"ar\":\"حساب ديناميكي حراري متقن! طاقة رابطة هيدروجينية واحدة (3.3 kcal/mol) تضاعف الألفة بأكثر من 200 ضعف بسبب العلاقة اللوغاريتمية الأسية.\",\"en\":\"Flawless thermodynamic calculation! ΔΔG° = 2.303 RT log10(ER). A single 3.3 kcal/mol H-bond magnifies affinity over 200-fold exponentially.\"}},{\"id\":\"opt-7b\",\"text\":{\"tr\":\"Yalnızca 2.3 kat (enerjiler logaritmik değil lineer orantılıdır).\",\"ar\":\"2.3 ضعفاً فقط (لأن الطاقات تتناسب خطياً وليس لوغاريتمياً).\",\"en\":\"Only 2.3-fold (free energies scale linearly with affinity rather than logarithmically).\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Lineer ölçek yanılgısı: Gibbs serbest enerjisi denge sabitiyle logaritmik ilişkilidir (ΔG = -RT ln K); serbest enerjideki aritmetik artış afiniteyi üssel olarak çarpar.\",\"ar\":\"خطأ التناسب الخطي: ترتبط طاقة غيبس لوغاريتمياً مع ثابت التوازن؛ الزيادة الخطية في الطاقة تضاعف الألفة أسياً.\",\"en\":\"Linear scale misconception: Gibbs free energy scales logarithmically with equilibrium constant; arithmetic energy additions multiply affinity exponentially.\"}},{\"id\":\"opt-7c\",\"text\":{\"tr\":\"Tam olarak 33 kat (3.3 kcal/mol doğrudan 10 ile çarpılarak bulunur).\",\"ar\":\"33 ضعفاً تماماً (بضرب 3.3 kcal/mol مباشرة في معامل 10).\",\"en\":\"Exactly 33-fold (multiplying 3.3 kcal/mol directly by a factor of 10).\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Doğrudan çarpma yanılgısı: Logaritmik üs hesabında 10^2.32 hesaplanmalıdır; 10 ile çarpım yapılmaz (10^2 = 100, 10^2.32 ≈ 210).\",\"ar\":\"خطأ الضرب المباشر: يجب رفع الأساس 10 إلى القوة 2.32، ولا يجوز الضرب في 10 مباشرة (10^2.32 ≈ 210).\",\"en\":\"Direct product misconception: You must evaluate 10 raised to the power 2.32, which equals ~210, not 10 multiplied by 2.32.\"}}]},\"technicalTerms\":[{\"term\":\"Gibbs serbest enerjisi\",\"arContext\":\"طاقة غيبس الحرة\"},{\"term\":\"bağlanma sabiti\",\"arContext\":\"ثابت الارتباط\"}],\"hints\":[{\"tr\":\"Termodinamik formülü hatırlayın: ΔΔG° = 2.303 RT log10(ER). 310 K'de 2.303 RT ≈ 1.42 kcal/mol.\",\"ar\":\"تذكر المعادلة الديناميكية الحرارية: ΔΔG° = 2.303 RT log10(ER). عند 310 K، 2.303 RT ≈ 1.42 kcal/mol.\",\"en\":\"Recall the thermodynamic equation: ΔΔG° = 2.303 RT log10(ER). At 310 K, 2.303 RT ≈ 1.42 kcal/mol.\"},{\"tr\":\"Log10(ER) = 3.3 / 1.42 ≈ 2.32. Buradan ER = 10^2.32 hesaplanır.\",\"ar\":\"Log10(ER) = 3.3 / 1.42 ≈ 2.32. ومنها نحسب ER = 10^2.32.\",\"en\":\"Log10(ER) = 3.3 / 1.42 ≈ 2.32. Hence, ER = 10^2.32.\"},{\"tr\":\"10^2 = 100 ve 10^0.32 ≈ 2.1 olduğundan, ER = 100 × 2.1 ≈ 210 (yaklaşık 200 kat).\",\"ar\":\"بما أن 10^2 = 100 و 10^0.32 ≈ 2.1، فإن ER = 100 × 2.1 ≈ 210 (حوالي 200 ضعف).\",\"en\":\"Since 10^2 = 100 and 10^0.32 ≈ 2.1, ER = 100 × 2.1 ≈ 210 (~200-fold).\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":23}],\"config\":{\"options\":[{\"id\":\"opt-7a\",\"text\":\"Yaklaşık 200 kat (ΔΔG / 1.42 = 3.3 / 1.42 ≈ 2.32 log birimi; 10^2.32 ≈ 210 kat).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz termodinamik hesap! ΔΔG° = 2.303 RT log10(ER). 3.3 kcal/mol'lük tek bir hidrojen bağı enerjisi, logaritmik ilişki sebebiyle afiniteyi 200 kattan fazla artırır.\"},{\"id\":\"opt-7b\",\"text\":\"Yalnızca 2.3 kat (enerjiler logaritmik değil lineer orantılıdır).\",\"isCorrect\":false,\"misconceptionFeedback\":\"Lineer ölçek yanılgısı: Gibbs serbest enerjisi denge sabitiyle logaritmik ilişkilidir (ΔG = -RT ln K); serbest enerjideki aritmetik artış afiniteyi üssel olarak çarpar.\"},{\"id\":\"opt-7c\",\"text\":\"Tam olarak 33 kat (3.3 kcal/mol doğrudan 10 ile çarpılarak bulunur).\",\"isCorrect\":false,\"misconceptionFeedback\":\"Doğrudan çarpma yanılgısı: Logaritmik üs hesabında 10^2.32 hesaplanmalıdır; 10 ile çarpım yapılmaz (10^2 = 100, 10^2.32 ≈ 210).\"}],\"revealedOutcome\":{\"tr\":\"Tek bir H-bağı (3.3 kcal/mol), logaritmik Gibbs denkleminde (ΔΔG° = 2.303 RT log10(ER)) afiniteyi 200 kattan fazla artırır (10^2.32 ≈ 210).\",\"ar\":\"تؤدي رابطة هيدروجينية مفردة (3.3 kcal/mol) وفق معادلة غيبس اللوغاريتمية إلى مضاعفة الألفة بأكثر من 200 ضعف (10^2.32 ≈ 210).\",\"en\":\"A single H-bond (3.3 kcal/mol) magnifies affinity by over 200-fold via the logarithmic Gibbs relation (10^2.32 ≈ 210).\"},\"explanation\":{\"tr\":\"37°C'de her 1.42 kcal/mol'lük serbest enerji artışı afiniteyi 10 kat artırır. 3.3 kcal/mol / 1.42 = 2.32 log birimi = 210 kat eudismik oran (Slayt 25, 28).\",\"ar\":\"عند 37 مئوية، كل 1.42 kcal/mol في طاقة الارتباط ترفع الألفة بمقدار 10 أضعاف. بالتالي 3.3 / 1.42 = 2.32 لوغاريتمي = 210 ضعفاً في ER (شريحة 25، 28).\",\"en\":\"At 37 C, each 1.42 kcal/mol free energy increment multiplies affinity by 10-fold. Thus 3.3 / 1.42 = 2.32 log units = 210-fold ER.\"}}},{\"id\":\"mc-mod2-les2-step-08\",\"stage\":\"concept_check\",\"stageIndex\":8,\"type\":\"concept_check\",\"title\":{\"tr\":\"Kavram Kontrolü: İki İlacın Pfeiffer Kıyaslaması\",\"ar\":\"فحص المفاهيم: مقارنة دوائين وفق قاعدة Pfeiffer\",\"en\":\"Concept Check: Comparing High vs Low Affinity Drugs\"},\"prompt\":{\"tr\":\"İlaç A reseptörüne 0.2 nM afiniteyle bağlanan güçlü bir agonisttir. İlaç B ise aynı reseptöre 50 μM afiniteyle bağlanan zayıf bir liganddır. Pfeiffer kuralına göre hangisinin eudismik oranı büyüktür?\",\"ar\":\"يرتبط الدواء A بمستقبله بألفة 0.2 nM وهو منبه قوي، بينما يرتبط الدواء B بألفة ضعيفة 50 μM. وفق قاعدة Pfeiffer، أي الدوائين يملك نسبة إيوديزمية (ER) أكبر بكثير؟\",\"en\":\"Drug A binds its receptor with 0.2 nM affinity. Drug B binds the same target weakly at 50 μM. According to Pfeiffer's Rule, which drug exhibits a vastly higher eudismic ratio?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-8a\",\"text\":{\"tr\":\"İlaç A; sub-nanomolar afinite sıkı ve rijit kiral komplementerlik gerektirir, distomerin eksik kontağı afiniteyi sertçe düşürür.\",\"ar\":\"الدواء A؛ لأن الألفة دون النانومولية تتطلب تطابقاً كيرالياً شديد الإحكام، وغياب رابطة واحدة في distomer يخفض الألفة بقسوة.\",\"en\":\"Drug A; sub-nanomolar binding demands rigid 3D complementarity, causing a massive potency penalty for distomer misorientation.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! 0.2 nM afiniteye sahip İlaç A cebi kusursuz doldurmalıdır; distomerin bir bağ kaybetmesi afiniteyi 500-1000 kat düşürür. 50 μM'lik İlaç B ise zaten gevşek bağlıdır.\",\"ar\":\"صحيح! يتطلب الدواء A بألفة 0.2 nM تطابقاً محكماً يرفع ER لمئات الأضعاف، بينما يرتبط الدواء B برخاوة تتقارب فيها المصاوغات.\",\"en\":\"Correct! High-affinity 0.2 nM binding demands near-perfect fit, amplifying the distomer deficit into a massive ER, unlike loose 50 μM binding.\"}},{\"id\":\"opt-8b\",\"text\":{\"tr\":\"İlaç B; mikromolar ilaçlar daha fazla moleküle ihtiyaç duyduğundan enantiyomerler arası fark daha büyüktür.\",\"ar\":\"الدواء B؛ لأن الأدوية الميكرومولية تتطلب عدداً أكبر من الجزيئات مما يضخم الفارق بين المصاوغات.\",\"en\":\"Drug B; micromolar drugs require higher concentrations, amplifying the apparent difference between enantiomers.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Konsantrasyon yanılgısı: Yüksek konsantrasyon gevşek bağlanmayı simgeler. Gevşek bağlanma kiral kusurları tolere eder; bu yüzden İlaç B'nin enantiyomerleri birbirine yakın güçte kalır (ER yakındır 1'e).\",\"ar\":\"خطأ التركيز: التركيز العالي يعكس ارتباطاً رخواً غير محكم يتسامح مع عيوب الكيرالية؛ فتقترب نسبة ER للدواء B من الواحد.\",\"en\":\"Concentration misconception: High micromolar doses signify loose binding that easily accommodates chiral flaws, driving ER toward unity.\"}},{\"id\":\"opt-8c\",\"text\":{\"tr\":\"Her ikisinin de ER değeri aynıdır; eudismik oran reseptör afinitesinden bağımsızdır.\",\"ar\":\"كلاهما يمتلك نفس قيمة ER؛ فالنسبة الإيوديزمية مستقلة تماماً عن درجة ألفة المستقبل.\",\"en\":\"Both have identical ER values; eudismic ratios are independent of baseline target affinity.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Bağımsızlık yanılgısı: Pfeiffer kuralının ana temeli tam olarak afinite ile ER arasındaki doğrudan pozitif korelasyondur.\",\"ar\":\"خطأ الاستقلالية: جوهر قاعدة Pfeiffer يكمن في وجود ارتباط طردي وثيق بين ارتفاع الألفة وارتفاع النسبة الإيوديزمية.\",\"en\":\"Independence misconception: Pfeiffer's rule explicitly establishes a direct positive correlation between baseline affinity and eudismic ratio.\"}}]},\"technicalTerms\":[{\"term\":\"Pfeiffer kuralı\",\"arContext\":\"قاعدة Pfeiffer\"},{\"term\":\"reseptör afinitesi\",\"arContext\":\"ألفة المستقبل\"}],\"hints\":[{\"tr\":\"Pfeiffer kuralını hatırlayın: Afinite ne kadar yüksek (Kd ne kadar küçük) olursa ER o kadar büyür.\",\"ar\":\"تذكر قاعدة Pfeiffer: كلما زادت الألفة (صغرت Kd) تضاعفت النسبة الإيوديزمية ER.\",\"en\":\"Recall Pfeiffer's rule: greater affinity (lower Kd) drives a substantially higher eudismic ratio.\"},{\"tr\":\"0.2 nM (pikomolar seviye) ile 50 μM (50000 nM) arasında 250.000 katlık afinite farkı vardır.\",\"ar\":\"الفارق بين 0.2 nM و 50 μM (أي 50000 nM) يصل إلى 250,000 ضعف في الألفة الأساسية.\",\"en\":\"There is a 250,000-fold affinity gap between 0.2 nM and 50 μM baseline binding.\"},{\"tr\":\"İlaç A son derece dar bir afinite penceresine sahiptir; enantiyomer farkı yüzlerce kat olurken, İlaç B'nin enantiyomerleri birbirine yakın güçte kalır.\",\"ar\":\"يمتلك الدواء A نافذة ألفة شديدة الدقة؛ مما يرفع فارق المصاوغات لمئات الأضعاف مقارنة بالدواء B.\",\"en\":\"Drug A demands extreme stereocomplementarity, yielding a massive ER, while Drug B binds loosely with near-equal enantiomer potency.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":28}],\"config\":{\"options\":[{\"id\":\"opt-8a\",\"text\":\"İlaç A; sub-nanomolar afinite sıkı ve rijit kiral komplementerlik gerektirir, distomerin eksik kontağı afiniteyi sertçe düşürür.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! 0.2 nM afiniteye sahip İlaç A cebi kusursuz doldurmalıdır; distomerin bir bağ kaybetmesi afiniteyi 500-1000 kat düşürür. 50 μM'lik İlaç B ise zaten gevşek bağlıdır.\"},{\"id\":\"opt-8b\",\"text\":\"İlaç B; mikromolar ilaçlar daha fazla moleküle ihtiyaç duyduğundan enantiyomerler arası fark daha büyüktür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Konsantrasyon yanılgısı: Yüksek konsantrasyon gevşek bağlanmayı simgeler. Gevşek bağlanma kiral kusurları tolere eder; bu yüzden İlaç B'nin enantiyomerleri birbirine yakın güçte kalır (ER yakındır 1'e).\"},{\"id\":\"opt-8c\",\"text\":\"Her ikisinin de ER değeri aynıdır; eudismik oran reseptör afinitesinden bağımsızdır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Bağımsızlık yanılgısı: Pfeiffer kuralının ana temeli tam olarak afinite ile ER arasındaki doğrudan pozitif korelasyondur.\"}],\"revealedOutcome\":{\"tr\":\"İlaç A (Kd = 0.2 nM) çok daha yüksek eudismik orana (ER >> 100) sahip olur; İlaç B (Kd = 50 μM) gevşek bağlanıp ER ≈ 1 kalır.\",\"ar\":\"يمتلك الدواء A (Kd = 0.2 nM) نسبة يوديزمية أعلى بكثير (ER >> 100)، بينما يرتبط الدواء B بارتخاء فتبقى ER قريبة من 1.\",\"en\":\"Drug A (Kd = 0.2 nM) exhibits a vastly higher Eudismic Ratio (ER >> 100); Drug B binds loosely with ER approaching 1.\"},\"explanation\":{\"tr\":\"Pfeiffer kuralına göre eudismik oran eutomer afinitesiyle doğru orantılıdır. Pikomolar İlaç A katı kiral ayrım gösterirken mikromolar İlaç B göstermez (Slayt 28).\",\"ar\":\"وفق قاعدة Pfeiffer، تتناسب ER طرداً مع ألفة الأوتومر. يظهر الدواء A تمييزاً كيرالياً حاداً بينما يعجز الدواء B عن ذلك (شريحة 28).\",\"en\":\"Under Pfeiffer's rule, ER correlates directly with eutomer affinity. Picomolar Drug A enforces rigid chiral discrimination, unlike Drug B.\"}}},{\"id\":\"mc-mod2-les2-step-09\",\"stage\":\"application\",\"stageIndex\":9,\"type\":\"clinical_vignette\",\"title\":{\"tr\":\"Klinik Vaka: Prilokain ve Methemoglobinemi Toksisitesi\",\"ar\":\"حالة سريرية: البريلوكائين وسمية الميتهيموغلوبين\",\"en\":\"Clinical Vignette: Prilocaine and Methemoglobinemia Toxicity\"},\"prompt\":{\"tr\":\"Diş hekimliğinde lokal anestezik prilokain rasemat olarak kullanılır. Yüksek doz uygulanan hastada siyanoz gelişir. Hangi enantiyomerin metaboliti ferro demiri ferri demire oksitleyerek methemoglobinemiye yol açmıştır?\",\"ar\":\"يُستخدم المخدر الموضعي prilocaine كخليط راسيمي. بعد جرعة عالية يصاب المريض بالزرقة ونقص الأكسجة. أي المصاوغين ينتج مستقلباً يؤكسد حديد الهيموغلوبين مسبباً ميتهيموغلوبين الدم؟\",\"en\":\"Local anesthetic prilocaine is administered as a racemate. Following a high dose, a patient develops cyanosis. Which enantiomer undergoes metabolic hydrolysis to produce the hematotoxic metabolite o-toluidine?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-9a\",\"text\":{\"tr\":\"R(-)-prilokain; hepatik amidazlarca selektif hidrolize edilerek o-toluidin oluşturur ve hemoglobindeki Fe2+'yi Fe3+'e oksitler.\",\"ar\":\"المصاوغ R(-)-prilocaine؛ يُحلمه في الكبد انتقائياً ليعطي o-toluidine الذي يؤكسد Fe2+ إلى Fe3+ في الهيموغلوبين.\",\"en\":\"R(-)-prilocaine; selectively hydrolyzed by hepatic amidases to form o-toluidine, which oxidizes Fe2+ to Fe3+.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kesinlikle doğru! S(+)-prilokain güvenli ve aktif lokal anesteziktir. Distomer olan R(-)-prilokain ise karaciğerde stereoselektif hidrolize uğrar ve açığa çıkan o-toluidin methemoglobinemiye neden olur.\",\"ar\":\"صحيح تماماً! المصاوغ S(+) مخدر موضعي آمن وفعال، بينما يخضع المصاوغ الأضعف R(-) لحلمهة كبدية انتقائية محرراً o-toluidine السام للدم.\",\"en\":\"Spot on! S(+)-prilocaine is the active, non-toxic anesthetic. Distomer R(-)-prilocaine undergoes stereoselective hepatic hydrolysis, liberating o-toluidine which induces methemoglobinemia.\"}},{\"id\":\"opt-9b\",\"text\":{\"tr\":\"S(+)-prilokain; aktif anestezik olduğu için sinir kılıfındaki hemoglobinleri doğrudan parçalar.\",\"ar\":\"المصاوغ S(+)-prilocaine؛ لأنه المخدر الفعال فيخرب هيموغلوبين غمد العصب مباشرة.\",\"en\":\"S(+)-prilocaine; being the active anesthetic, it directly lyses hemoglobin molecules.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Eutomer toksisitesi yanılgısı: S(+)-enantiyomeri methemoglobinemi yapmaz; toksisite distomer olan R(-)-formunun metabolitinden doğar.\",\"ar\":\"خطأ سمية المصاوغ الفعال: لا يسبب المصاوغ S(+) ميتهيموغلوبين الدم؛ السمية تنشأ حصراً من مستقلب المصاوغ R(-).\",\"en\":\"Eutomer toxicity misconception: S(+)-prilocaine is non-toxic; methemoglobinemia stems entirely from the hepatic metabolite of distomer R(-)-prilocaine.\"}},{\"id\":\"opt-9c\",\"text\":{\"tr\":\"Her iki enantiyomer de eşit oranda parçalanır; toksisite stereoselektif değildir.\",\"ar\":\"يتحلل كلا المصاوغين بنفس المعدل تماماً؛ فالسمية ليست انتقائية فراغياً.\",\"en\":\"Both enantiomers undergo equal hydrolysis; toxicity is completely non-stereoselective.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Eşit metabolizma yanılgısı: Hepatik enzimler şiral proteinlerdir ve enantiyomerleri farklı hızlarda dönüştürür; prilokain hidrolizi belirgin biçimde R-selektiftir.\",\"ar\":\"خطأ التماثل الاستقلابي: الأنزيمات الكبدية بروتينات كيرالية تميز المصاوغات وتفكك المصاوغ R بسرعة وانتقائية أعلى بكثير.\",\"en\":\"Equal metabolism misconception: Hepatic amidases are chiral proteins that hydrolyze R(-)-prilocaine with high stereoselectivity.\"}}]},\"technicalTerms\":[{\"term\":\"stereoselektif hidroliz\",\"arContext\":\"الحلمهة الانتقائية الفراغية\"},{\"term\":\"methemoglobinemi\",\"arContext\":\"ميتهيموغلوبين الدم\"},{\"term\":\"o-toluidin\",\"arContext\":\"أورثو-تولويدين\"}],\"hints\":[{\"tr\":\"Methemoglobinemiye yol açan metabolit o-toluidin (orto-toluidin) bileşiğidir.\",\"ar\":\"المستقلب المسبب لميتهيموغلوبين الدم هو أورثو-تولويدين (o-toluidine).\",\"en\":\"The toxic culprit oxidizing hemoglobin is the metabolite ortho-toluidine (o-toluidine).\"},{\"tr\":\"S(+)-prilokain arzu edilen aktif ötomerdir; R(-)-prilokain ise toksik distomerdir.\",\"ar\":\"المصاوغ S(+)-prilocaine هو الفعال المرغوب، بينما R(-)-prilocaine هو المصاوغ السام.\",\"en\":\"S(+)-prilocaine is the therapeutic eutomer; R(-)-prilocaine is the toxic distomer.\"},{\"tr\":\"R(-)-prilokain karaciğerde amido-hidrolaz ile selektif hidrolize uğrar; açığa çıkan o-toluidin Fe2+'yi Fe3+'e yükseltgeyerek methemoglobinemi yapar.\",\"ar\":\"يتحلل R(-)-prilocaine في الكبد ليعطي o-toluidine الذي يؤكسد Fe2+ إلى Fe3+ مسبباً المرض.\",\"en\":\"R(-)-prilocaine undergoes stereoselective amide hydrolysis to liberate o-toluidine, oxidizing Fe2+ to Fe3+.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":32}],\"config\":{\"options\":[{\"id\":\"opt-9a\",\"text\":\"R(-)-prilokain; hepatik amidazlarca selektif hidrolize edilerek o-toluidin oluşturur ve hemoglobindeki Fe2+'yi Fe3+'e oksitler.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kesinlikle doğru! S(+)-prilokain güvenli ve aktif lokal anesteziktir. Distomer olan R(-)-prilokain ise karaciğerde stereoselektif hidrolize uğrar ve açığa çıkan o-toluidin methemoglobinemiye neden olur.\"},{\"id\":\"opt-9b\",\"text\":\"S(+)-prilokain; aktif anestezik olduğu için sinir kılıfındaki hemoglobinleri doğrudan parçalar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Eutomer toksisitesi yanılgısı: S(+)-enantiyomeri methemoglobinemi yapmaz; toksisite distomer olan R(-)-formunun metabolitinden doğar.\"},{\"id\":\"opt-9c\",\"text\":\"Her iki enantiyomer de eşit oranda parçalanır; toksisite stereoselektif değildir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Eşit metabolizma yanılgısı: Hepatik enzimler şiral proteinlerdir ve enantiyomerleri farklı hızlarda dönüştürür; prilokain hidrolizi belirgin biçimde R-selektiftir.\"}],\"revealedOutcome\":{\"tr\":\"R(-)-prilokain karaciğerde amido-hidrolaz ile hidroliz edilerek o-toluidine dönüşür; o-toluidin hemoglobindeki Fe2+'yi Fe3+'e oksitleyerek methemoglobinemi yapar.\",\"ar\":\"يتحلمه R(-)-prilocaine كبدياً بإنزيم أميدو-هيدرولاز إلى o-toluidine، الذي يؤكسد حديد الهيموغلوبين Fe2+ إلى Fe3+ مسبباً ميتهيموغلوبينيميا.\",\"en\":\"R(-)-prilocaine is selectively hydrolyzed by hepatic amidases to o-toluidine, which oxidizes Fe2+ to Fe3+, triggering methemoglobinemia.\"},\"explanation\":{\"tr\":\"S(+)-prilokain aktif ve güvenlidir. Ancak distomer olan R(-)-formunun selektif metaboliti o-toluidin kanda oksijen taşınmasını engeller (Slayt 32).\",\"ar\":\"المصاوغ S(+)-prilocaine فعال وآمن، لكن المستقلب الانتقائي للمصاوغ R(-) الخامل (o-toluidine) يعطل نقل الأكسجين في الدم (شريحة 32).\",\"en\":\"S(+)-prilocaine is an effective, safe local anesthetic. However, the selective metabolite of the R(-) distomer (o-toluidine) induces methemoglobinemia.\"}}},{\"id\":\"mc-mod2-les2-step-10\",\"stage\":\"retrieval\",\"stageIndex\":10,\"type\":\"retrieval\",\"title\":{\"tr\":\"Aralıklı Hatırlama: Talidomid İn Vivo Rasemizasyonu\",\"ar\":\"استرجاع متباعد: الانقلاب الكيرالي التلقائي للثاليدوميد\",\"en\":\"Spaced Retrieval: In Vivo Racemization of Thalidomide\"},\"prompt\":{\"tr\":\"Gebelerde sabah bulantısı için saf R(+)-talidomid üretilip verilseydi fokomeli (fetal uzuv agenezi) faciası tamamen önlenebilir miydi? Neden?\",\"ar\":\"لو تم تصنيع وإعطاء R(+)-thalidomide نقياً للحوامل لعلاج الغثيان، هل كان بالإمكان تجنب كارثة الفقمية (تشوه الأطراف) تماماً؟ ولماذا؟\",\"en\":\"If pharmaceutical companies had manufactured and administered pure R(+)-thalidomide to pregnant patients, would phocomelia birth defects have been prevented? Why or why not?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-10a\",\"text\":{\"tr\":\"Hayır; talidomidin asidik kiral protonu plazmada keto-enol tautomerisiyle 4-5 saatte kendiliğinden rasemize olur (R -> S dönüşümü kaçınılmazdır).\",\"ar\":\"كلا؛ فالبروتون الكيرالي الحمضي للثاليدوميد ينقلب تلقائياً في البلازما عبر التوتوميرية (keto-enol) خلال 4-5 ساعات ليعيد تكوين المصاوغ المشوه S.\",\"en\":\"No; thalidomide's acidic chiral proton undergoes rapid in vivo keto-enol tautomerism, spontaneously racemizing into the teratogenic S-isomer within 4-5 hours.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kritik farmasötik gerçek! Talidomidin kiral karbonundaki proton iki karbonil arasında asidiktir; fizyolojik pH'ta hızla kopup düzlemsel ara ürün üzerinden her iki enantiyomere döner. Saf R verilse bile 4-5 saatte teratojenik S oluşur.\",\"ar\":\"حقيقة صيدلانية بالغة الأهمية! البروتون الكيرالي يقع بين مجموعتي كربونيل حمضيتين؛ فيفقد تلقائياً عند pH الفيزيولوجي ليعيد تشكيل المصاوغ السام S خلال ساعات.\",\"en\":\"Critical pharmaceutical reality! The chiral proton flanked by carbonyls is acidic; at physiological pH it deprotonates to an achiral planar enolate, racemizing in vivo within 4-5 hours.\"}},{\"id\":\"opt-10b\",\"text\":{\"tr\":\"Evet; R(+)-enantiyomeri kimyasal olarak kararlıdır ve vücutta asla S(-)-enantiyomerine dönüşemez.\",\"ar\":\"نعم؛ لأن المصاوغ R(+) مستقر كيميائياً تماماً ويستحيل تحوله في الجسم إلى المصاوغ S(-).\",\"en\":\"Yes; the R(+)-enantiomer is stereochemically stable and cannot interconvert in biological media.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kiral kararlılık yanılgısı: Kiral merkezler her zaman statik değildir; alfa-asidik proton taşıyan moleküller fizyolojik koşullarda kendiliğinden kiral inversiyona / rasemizasyona uğrar.\",\"ar\":\"خطأ ثبات الكيرالية: ليست كل المراكز الكيرالية خاملة؛ فالبروتونات الحمضية المجاورة للكربونيل تسمح بالانقلاب الكيرالي التلقائي في سوائل الجسم.\",\"en\":\"Chiral stability misconception: Chiral centers with acidic alpha-protons spontaneously racemize at physiological pH via planar enol intermediates.\"}},{\"id\":\"opt-10c\",\"text\":{\"tr\":\"Evet; çünkü S(-)-talidomid plasenta bariyerini geçebilirken saf R(+) asla plasentayı geçemez.\",\"ar\":\"نعم؛ لأن المصاوغ S(-) يعبر المشيمة بينما يعجز المصاوغ R(+) النقي عن عبورها نهائياً.\",\"en\":\"Yes; because only the S(-)-enantiomer crosses the placenta while pure R(+) is completely blocked.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Membran bariyeri yanılgısı: Her iki enantiyomer de aynı lipofilik yapıdadır ve plasenta membranını pasif difüzyonla kolayca geçer.\",\"ar\":\"خطأ الحاجز المشيمي: يمتلك كلا المصاوغين نفس الخصائص المحبة للدهن ويعبران المشيمة بسهولة بالانتشار المنفعل.\",\"en\":\"Placental barrier misconception: Both enantiomers possess identical lipophilicity and freely diffuse across placental membranes.\"}}]},\"technicalTerms\":[{\"term\":\"kiral rasemizasyon\",\"arContext\":\"الراسمة الكيرالية الحيوية\"},{\"term\":\"keto-enol tautomerisi\",\"arContext\":\"التوتوميرية كيتو-إينول\"},{\"term\":\"teratojenite\",\"arContext\":\"التشوه الجنيني\"}],\"hints\":[{\"tr\":\"Talidomidin kiral merkezindeki hidrojen atomu iki karbonil grubunun arasındadır (asidiktir).\",\"ar\":\"تقع ذرة الهيدروجين في المركز الكيرالي للثاليدوميد بين مجموعتي كربونيل (فهي حمضية).\",\"en\":\"The hydrogen atom at thalidomide's chiral center is flanked by two electron-withdrawing carbonyls (acidic).\"},{\"tr\":\"Fizyolojik pH'ta (7.4) bu proton kolayca kopar ve düzlemsel enolat ara ürünü üzerinden her iki taraftan geri bağlanır.\",\"ar\":\"عند درجة الحموضة الفيزيولوجية (7.4) ينفصل هذا البروتون بسهولة مشكلاً وسيطاً مستوياً ينقلب للجهتين.\",\"en\":\"At physiological pH 7.4, this proton dissociates, forming a planar enolate intermediate that protonates from either face.\"},{\"tr\":\"In vivo kiral rasemizasyon nedeniyle saf R-talidomid birkaç saat içinde 50:50 rasemik karışıma döner; teratojenik S-formu vücutta mutlaka oluşur.\",\"ar\":\"بسبب الراسمة التلقائية في الجسم، يتحول R النقي إلى خليط 50:50 خلال ساعات منتجاً المصاوغ المشوه S حتماً.\",\"en\":\"Due to in vivo chiral racemization, pure R-thalidomide reaches a 50:50 racemic mixture in 4-5 hours, inevitability producing teratogenic S-thalidomide.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":31}],\"config\":{\"options\":[{\"id\":\"opt-10a\",\"text\":\"Hayır; talidomidin asidik kiral protonu plazmada keto-enol tautomerisiyle 4-5 saatte kendiliğinden rasemize olur (R -> S dönüşümü kaçınılmazdır).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kritik farmasötik gerçek! Talidomidin kiral karbonundaki proton iki karbonil arasında asidiktir; fizyolojik pH'ta hızla kopup düzlemsel ara ürün üzerinden her iki enantiyomere döner. Saf R verilse bile 4-5 saatte teratojenik S oluşur.\"},{\"id\":\"opt-10b\",\"text\":\"Evet; R(+)-enantiyomeri kimyasal olarak kararlıdır ve vücutta asla S(-)-enantiyomerine dönüşemez.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kiral kararlılık yanılgısı: Kiral merkezler her zaman statik değildir; alfa-asidik proton taşıyan moleküller fizyolojik koşullarda kendiliğinden kiral inversiyona / rasemizasyona uğrar.\"},{\"id\":\"opt-10c\",\"text\":\"Evet; çünkü S(-)-talidomid plasenta bariyerini geçebilirken saf R(+) asla plasentayı geçemez.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Membran bariyeri yanılgısı: Her iki enantiyomer de aynı lipofilik yapıdadır ve plasenta membranını pasif difüzyonla kolayca geçer.\"}],\"revealedOutcome\":{\"tr\":\"Facia önlenemezdi; talidomidin kiral merkezindeki asidik hidrojen plazmada keto-enol tautomerisiyle 4-5 saatte kendiliğinden rasemize olur (R -> S).\",\"ar\":\"لم تكن الكارثة لتُمنع؛ إذ يخضع البروتون الكيرالي الحمضي في الثاليدوميد لتحول إينولي تلقائي في البلازما ليعيد تشكيل الخليط الراسيمي خلال 4-5 ساعات.\",\"en\":\"Phocomelia would not have been prevented; the acidic chiral proton undergoes rapid spontaneous keto-enol racemization in plasma within 4-5 hours.\"},\"explanation\":{\"tr\":\"Talidomidin kiral karbonundaki proton komşu iki karbonil nedeniyle asidiktir; pH 7.4'te hızla enolat üzerinden kopar ve saf R verilse bile S oluşur (Slayt 30, 31).\",\"ar\":\"بروتون ذرة الكربون الكيرالية في الثاليدوميد حمضي لوقوعه بين مجموعتي كربونيل؛ فيتحول تلقائياً إلى المصاوغ S المشوه للأجنة حتى لو أُعطي R نقياً (شريحة 30، 31).\",\"en\":\"The chiral proton flanked by two carbonyls is acidic; at physiological pH it tautomerizes, regenerating teratogenic (S)-thalidomide from pure (R).\"}}},{\"id\":\"mc-mod2-les2-step-11\",\"stage\":\"connection\",\"stageIndex\":11,\"type\":\"connection\",\"title\":{\"tr\":\"Bağlantı: Asetilkolinin Muskarinik vs Nikotinik Konformasyonu\",\"ar\":\"ربط المفاهيم: هيئات الأستيل كولين المسكارينية مقابل النيكوتينية\",\"en\":\"Cross-Topic Bridge: Acetylcholine Gauche vs Anti Conformations\"},\"prompt\":{\"tr\":\"Asetilkolin tekli bağ rotasyonuyla iki ana konformasyonda bulunur. Gauche (katlanmış) formu muskarinik reseptöre, anti (uzamış) formu nikotinik reseptöre bağlanır. Bu seçiciliğin geometrik temeli nedir?\",\"ar\":\"يوجد أستيل كولين في هيئتين رئيسيتين بدوران الروابط. تلائم هيئة gauche (المطوية) المستقبلات المسكارينية، وهيئة anti (الممتدة) المستقبلات النيكوتينية. ما الأساس الهندسي؟\",\"en\":\"Acetylcholine exists in two interconverting conformers. The gauche (folded) conformer activates muscarinic receptors; anti (extended) activates nicotinic receptors. What is the spatial basis of this subtype selectivity?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-11a\",\"text\":{\"tr\":\"Kuvaterner amonyum (N+) ile ester oksijeni arasındaki mesafe gauche formda 3.3 Å (muskarinik uyumlu), anti formda ise 4.4 Å (nikotinik uyumlu) dur.\",\"ar\":\"المسافة بين الأمونيوم (N+) وأكسجين الإستر تبلغ 3.3 Å في هيئة gauche (مطابقة للمسكاريني)، و4.4 Å في هيئة anti (مطابقة للنيكوتيني).\",\"en\":\"The distance between quaternary ammonium (N+) and ester oxygen is 3.3 Å in gauche (muscarinic fit) versus 4.4 Å in anti (nicotinic fit).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel bağlantı! Tekli sigma bağlarının dönmesiyle N+ ile O arasındaki mesafe 3.3 Å (katlanmış) ile 4.4 Å (açık) arasında değişir. Bu mesafe rijit siklopropan türevleriyle dondurularak ispatlanmıştır.\",\"ar\":\"ربط ممتاز! بدوران الرابطة الأحادية تتغير المسافة بين N+ و O بين 3.3 Å (مطوية) و 4.4 Å (ممتدة)، وهو ما تم إثباته بربط الجزيء بحلقة سيكلوبروبان صلبة.\",\"en\":\"Outstanding bridge! Torsional rotation around C-C single bonds alters the N+ to O distance from 3.3 Å (folded, muscarinic) to 4.4 Å (extended, nicotinic), verified with rigid cyclopropyl analogs.\"}},{\"id\":\"opt-11b\",\"text\":{\"tr\":\"Gauche formunda ester bağı parçalanarak serbest asetik asit açığa çıkar ve muskarinik reseptörü uyarır.\",\"ar\":\"في هيئة gauche ينكسر الإستر متحرراً إلى حمض الخل الذي ينبه المستقبل المسكاريني.\",\"en\":\"In the gauche conformer, the ester bond breaks into acetic acid to trigger muscarinic receptors.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Hidroliz yanılgısı: Konformasyonel izomeri kimyasal bağ kırılması içermez; molekül kovalent olarak bütündür, yalnızca uzaysal dönme açısı değişir.\",\"ar\":\"خطأ الحلمهة: لا تتضمن المصاوغة التشكيلية أي كسر للروابط الكيميائية؛ بل يتغير اتجاه الدوران الفراغي فقط مع بقاء الجزيء سليماً.\",\"en\":\"Hydrolysis misconception: Conformational isomerism involves zero bond breakage; the molecule remains intact, only changing its dihedral torsion angle.\"}},{\"id\":\"opt-11c\",\"text\":{\"tr\":\"Anti konformasyonunda asetilkolin pozitif yükünü kaybederek yüksüz bir moleküle dönüşür.\",\"ar\":\"في هيئة anti يفقد أستيل كولين شحنته الموجبة ويتحول إلى جزيء غير مشحون.\",\"en\":\"In the anti conformation, acetylcholine loses its formal positive charge to become neutral.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yük kaybı yanılgısı: Kuvaterner amonyum kalıcı pozitif yüklüdür (dörde bağlı azot); konformasyonel dönme molekülün net yükünü etkilemez.\",\"ar\":\"خطأ فقدان الشحنة: يحمل الأمونيوم الرباعي شحنة موجبة دائمة لا تتأثر مطلقاً بالدوران التشكيل الفراغي.\",\"en\":\"Charge loss misconception: Quaternary ammonium carries a permanent positive charge regardless of dihedral angle.\"}}]},\"technicalTerms\":[{\"term\":\"konformasyonel izomeri\",\"arContext\":\"المصاوغة التشكيلية (الهيئية)\"},{\"term\":\"biyoaktif konformasyon\",\"arContext\":\"الهيئة الفعالة حيوياً\"},{\"term\":\"rotamer\",\"arContext\":\"المصاوغ الدوراني\"}],\"hints\":[{\"tr\":\"Rijit siklopropan analogları (trans-asetilsiklopropil vs cis-asetilsiklopropil) bu mesafeyi dondurarak kanıtlamıştır.\",\"ar\":\"أثبتت مشتقات السيكلوبروبان الصلبة الفارق بتثبيت المسافة الفراغية.\",\"en\":\"Rigid cyclopropyl analogs freeze the pharmacophore distance, demonstrating receptor subtype selectivity.\"},{\"tr\":\"Muskarinik cepte N+ ile O mesafesi yaklaşık 3.3 Å iken, nikotinik cepte mesafe daha geniştir (4.4 Å).\",\"ar\":\"تبلغ المسافة في الجيب المسكاريني 3.3 Å، بينما تتسع في الجيب النيكوتيني إلى 4.4 Å.\",\"en\":\"Muscarinic pockets recognize a compact 3.3 Å span; nicotinic pockets require an extended 4.4 Å pharmacophore.\"},{\"tr\":\"Gauche formunda N+ ve O arasındaki mesafe 3.3 Å olup muskarinik cebe; uzamış anti formunda 4.4 Å olup nikotinik cebe kusursuz geometrik uyum gösterir.\",\"ar\":\"في هيئة gauche تبلغ المسافة 3.3 Å ملائمة للمسكاريني، وفي هيئة anti تبلغ 4.4 Å ملائمة للنيكوتيني.\",\"en\":\"Gauche geometry maintains 3.3 Å between N+ and O for muscarinic docking; extended anti geometry establishes 4.4 Å for nicotinic binding.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":42}],\"config\":{\"options\":[{\"id\":\"opt-11a\",\"text\":\"Kuvaterner amonyum (N+) ile ester oksijeni arasındaki mesafe gauche formda 3.3 Å (muskarinik uyumlu), anti formda ise 4.4 Å (nikotinik uyumlu) dur.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel bağlantı! Tekli sigma bağlarının dönmesiyle N+ ile O arasındaki mesafe 3.3 Å (katlanmış) ile 4.4 Å (açık) arasında değişir. Bu mesafe rijit siklopropan türevleriyle dondurularak ispatlanmıştır.\"},{\"id\":\"opt-11b\",\"text\":\"Gauche formunda ester bağı parçalanarak serbest asetik asit açığa çıkar ve muskarinik reseptörü uyarır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Hidroliz yanılgısı: Konformasyonel izomeri kimyasal bağ kırılması içermez; molekül kovalent olarak bütündür, yalnızca uzaysal dönme açısı değişir.\"},{\"id\":\"opt-11c\",\"text\":\"Anti konformasyonunda asetilkolin pozitif yükünü kaybederek yüksüz bir moleküle dönüşür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yük kaybı yanılgısı: Kuvaterner amonyum kalıcı pozitif yüklüdür (dörde bağlı azot); konformasyonel dönme molekülün net yükünü etkilemez.\"}],\"revealedOutcome\":{\"tr\":\"Asetilkolinin N+ ile ester oksijeni arasındaki mesafe gauche konformasyonunda 3.3 Å (muskarinik), anti konformasyonunda 4.4 Å (nikotinik) dir.\",\"ar\":\"تبلغ المسافة بين N+ وأكسجين الإستر في أسيتيل كولين 3.3 أنغستروم في هيئة gauche (مسكارينية)، و 4.4 أنغستروم في هيئة anti (نيكوتينية).\",\"en\":\"The N+ to ester oxygen distance in acetylcholine is 3.3 A in the gauche conformer (muscarinic) and 4.4 A in the anti conformer (nicotinic).\"},\"explanation\":{\"tr\":\"Konformasyonel esneklik asetilkolinin farklı mesafelerdeki iki reseptörü uyarmasını sağlar. Rijit siklopropan analogları bu mesafeleri kanıtlamıştır (Slayt 42).\",\"ar\":\"تتيح المرونة الفراغية لأسيتيل كولين تنشيط مستقبلين بأبعاد متباينة. وقد أثبتت نظائر السيكلوبروبان الصلبة هذا التباين الهندسي (شريحة 42).\",\"en\":\"Conformational flexibility permits acetylcholine to activate two distinct targets with different pharmacophoric distances (3.3 A vs 4.4 A).\"}}},{\"id\":\"mc-mod2-les2-step-12\",\"stage\":\"mastery_check\",\"stageIndex\":12,\"type\":\"mastery_check\",\"title\":{\"tr\":\"Ustalık Sınavı: Yeni Kiral Bronkodilatör Tasarımı\",\"ar\":\"اختبار الإتقان: تصميم موسع قصبات كيرالي جديد\",\"en\":\"Mastery Challenge: Novel Chiral Beta-2 Bronchodilator Design\"},\"prompt\":{\"tr\":\"Yeni bir astım ilacı adayında (R)-izomeri beta-2 reseptörüne 2 nM afiniteyle bağlanırken, (S)-izomeri 400 nM afinite göstermektedir. Bu ilacın eudismik oranı ve kiral bağlanma serbest enerji farkı nedir?\",\"ar\":\"مرشح دوائي جديد للربو: يرتبط المصاوغ (R) بمستقبل بيتا-2 بألفة 2 nM بينما يرتبط المصاوغ (S) بألفة 400 nM. ما هي النسبة الإيوديزمية وفرق الطاقة الحرة للارتباط؟\",\"en\":\"In a novel asthma drug candidate, the (R)-isomer binds beta-2 receptors with 2 nM affinity, while the (S)-isomer shows 400 nM affinity. What is the eudismic ratio and chiral free energy difference?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-12a\",\"text\":{\"tr\":\"ER = 200; ΔΔG° = -3.27 kcal/mol (-13.7 kJ/mol); (R)-izomeri Easson-Stedman 3-nokta bağlanmasını tamamlarken (S) sadece 2 noktadan tutunur.\",\"ar\":\"ER = 200؛ وΔΔG° = -3.27 kcal/mol (-13.7 kJ/mol)؛ يحقق (R) تعشيق Easson-Stedman ثلاثي النقاط بينما يقتصر (S) على نقطتين فقط.\",\"en\":\"ER = 200; ΔΔG° = -3.27 kcal/mol (-13.7 kJ/mol); (R) satisfies 3-point Easson-Stedman attachment while (S) binds via only 2 contacts.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Tebrikler, tam bir uzman cevabı! ER = 400 nM / 2 nM = 200. ΔΔG° = 1.42 kcal/mol × log10(200) = 1.42 × 2.301 ≈ 3.27 kcal/mol (-13.7 kJ/mol). Bu enerji Easson-Stedman 3. temas noktası olan güçlü bir hidrojen bağına tam olarak karşılık gelir.\",\"ar\":\"تهانينا، إتقان مذهل! ER = 400/2 = 200. و ΔΔG° = 1.42 × log10(200) = 3.27 kcal/mol. يمثل هذا الفارق تماماً طاقة الرابطة الهيدروجينية للنقطة الثالثة في نموذج Easson-Stedman.\",\"en\":\"Mastery demonstrated! ER = 400 nM / 2 nM = 200. ΔΔG° = 1.42 kcal/mol × log10(200) = 3.27 kcal/mol (-13.7 kJ/mol), matching the exact free energy contribution of the 3rd Easson-Stedman contact.\"}},{\"id\":\"opt-12b\",\"text\":{\"tr\":\"ER = 20; ΔΔG° = -1.42 kcal/mol; iki izomer arasındaki fark tek bir van der Waals bağı kadardır.\",\"ar\":\"ER = 20؛ وΔΔG° = -1.42 kcal/mol؛ الفارق بين المصاوغين يعادل رابطة فان دير فالس واحدة فقط.\",\"en\":\"ER = 20; ΔΔG° = -1.42 kcal/mol; the difference between isomers equates to a single van der Waals bond.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Oranlama hatası: 400 / 2 = 200'dür (20 değil). 1.42 kcal/mol yalnızca 10 katlık bir afinite değişimine karşılık gelir; burada ise 200 katlık dev bir fark vardır.\",\"ar\":\"خطأ حسابي: 400 / 2 = 200 (وليس 20). طاقة 1.42 تعادل فارق 10 أضعاف فقط، بينما الفارق الفعلي 200 ضعف.\",\"en\":\"Arithmetic error: 400 / 2 = 200 (not 20). A 1.42 kcal/mol shift produces only a 10-fold difference, whereas this case features a 200-fold gap.\"}},{\"id\":\"opt-12c\",\"text\":{\"tr\":\"ER = 400; ΔΔG° = -5.0 kcal/mol; (S)-izomeri reseptörde tam kovalent inaktivasyon yapar.\",\"ar\":\"ER = 400؛ وΔΔG° = -5.0 kcal/mol؛ يقوم المصاوغ (S) بتعطيل تساهمي كامل للمستقبل.\",\"en\":\"ER = 400; ΔΔG° = -5.0 kcal/mol; the (S)-isomer causes irreversible covalent receptor inactivation.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kd yanılgısı: ER iki afinitenin birbirine oranıdır (400/2 = 200); distomerin afinite sayısı doğrudan ER olamaz. Ayrıca ligand non-kovalent bir agonisttir.\",\"ar\":\"خطأ النسبة: ER هي النسبة بين القيمتين (400/2 = 200)، وليست قيمة distomer المفردة؛ والارتباط عكوس غير تساهمي.\",\"en\":\"Ratio misconception: ER is the ratio of distomer to eutomer Kd (400 / 2 = 200), not the distomer Kd alone; furthermore, binding is non-covalent.\"}}]},\"technicalTerms\":[{\"term\":\"Easson-Stedman 3-nokta bağlanması\",\"arContext\":\"نموذج Easson-Stedman ثلاثي النقاط\"},{\"term\":\"eudismik oran\",\"arContext\":\"النسبة الإيوديزمية\"}],\"hints\":[{\"tr\":\"Eudismik oranı bulun: ER = Distomer Kd / Eutomer Kd = 400 nM / 2 nM.\",\"ar\":\"احسب النسبة الإيوديزمية: ER = Kd للمصاوغ الأضعف / Kd للمصاوغ الأقوى = 400 / 2.\",\"en\":\"Find the eudismic ratio: ER = Distomer Kd / Eutomer Kd = 400 nM / 2 nM.\"},{\"tr\":\"ER = 200. Şimdi termodinamik hesabı yapın: log10(200) = log10(2) + log10(100) = 0.301 + 2 = 2.301.\",\"ar\":\"ER = 200. الآن احسب القيمة اللوغاريتمية: log10(200) = 2.301.\",\"en\":\"ER = 200. Evaluate the logarithm: log10(200) = 2.301.\"},{\"tr\":\"ΔΔG° = 1.42 kcal/mol × 2.301 ≈ 3.27 kcal/mol (-13.7 kJ/mol). Bu değer Easson-Stedman 3. noktası olan hidrojen bağının serbest enerji katkısıdır.\",\"ar\":\"ΔΔG° = 1.42 × 2.301 ≈ 3.27 kcal/mol (-13.7 kJ/mol). يمثل هذا الفارق تماماً طاقة النقطة الثالثة.\",\"en\":\"ΔΔG° = 1.42 kcal/mol × 2.301 ≈ 3.27 kcal/mol (-13.7 kJ/mol), representing the 3rd Easson-Stedman H-bond contact.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":25}],\"config\":{\"options\":[{\"id\":\"opt-12a\",\"text\":\"ER = 200; ΔΔG° = -3.27 kcal/mol (-13.7 kJ/mol); (R)-izomeri Easson-Stedman 3-nokta bağlanmasını tamamlarken (S) sadece 2 noktadan tutunur.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Tebrikler, tam bir uzman cevabı! ER = 400 nM / 2 nM = 200. ΔΔG° = 1.42 kcal/mol × log10(200) = 1.42 × 2.301 ≈ 3.27 kcal/mol (-13.7 kJ/mol). Bu enerji Easson-Stedman 3. temas noktası olan güçlü bir hidrojen bağına tam olarak karşılık gelir.\"},{\"id\":\"opt-12b\",\"text\":\"ER = 20; ΔΔG° = -1.42 kcal/mol; iki izomer arasındaki fark tek bir van der Waals bağı kadardır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Oranlama hatası: 400 / 2 = 200'dür (20 değil). 1.42 kcal/mol yalnızca 10 katlık bir afinite değişimine karşılık gelir; burada ise 200 katlık dev bir fark vardır.\"},{\"id\":\"opt-12c\",\"text\":\"ER = 400; ΔΔG° = -5.0 kcal/mol; (S)-izomeri reseptörde tam kovalent inaktivasyon yapar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kd yanılgısı: ER iki afinitenin birbirine oranıdır (400/2 = 200); distomerin afinite sayısı doğrudan ER olamaz. Ayrıca ligand non-kovalent bir agonisttir.\"}],\"revealedOutcome\":{\"tr\":\"ER = 200 dür; ΔΔG° = -3.27 kcal/mol (-13.7 kJ/mol) olup Easson-Stedman 3. temas noktası olan güçlü bir hidrojen bağına tam olarak uyar.\",\"ar\":\"النسبة ER = 200؛ وفارق طاقة الارتباط ΔΔG° = -3.27 kcal/mol (-13.7 kJ/mol)، وهو ما يطابق تماماً طاقة الرابطة الهيدروجينية كنقطة تماس ثالثة.\",\"en\":\"ER = 200; DeltaDelta G = -3.27 kcal/mol (-13.7 kJ/mol), perfectly matching the free energy contribution of the third Easson-Stedman H-bond contact.\"},\"explanation\":{\"tr\":\"ER = 400 nM / 2 nM = 200. ΔΔG° = 1.42 kcal/mol × log10(200) = 1.42 × 2.301 ≈ 3.27 kcal/mol (-13.7 kJ/mol). Easson-Stedman modeli kanıtlanmıştır (Slayt 25, 28).\",\"ar\":\"النسبة ER = 400 / 2 = 200. وطاقة الارتباط ΔΔG° = 1.42 × log10(200) = 1.42 × 2.301 ≈ 3.27 kcal/mol، مما يثبت نموذج Easson-Stedman (شريحة 25، 28).\",\"en\":\"ER = 400 / 2 = 200. DeltaDelta G = 1.42 kcal/mol x log10(200) = 1.42 x 2.301 = 3.27 kcal/mol (-13.7 kJ/mol), proving the Easson-Stedman model.\"}}}]},\"mc-mod3-les1\":{\"$schema\":\"../../../packages/platform/schema/lesson.schema.json\",\"id\":\"mc-mod3-les1\",\"courseId\":\"medchem\",\"moduleId\":\"mc-mod-03\",\"title\":{\"tr\":\"Klasik Biyoizosterizm ve Grimm Hidrit Yer Değiştirme\",\"ar\":\"التشابه الحيوي الكلاسيكي وإزاحة هيدريد Grimm\",\"en\":\"Classical Bioisosterism & Grimm Hydride Displacement\"},\"order\":1,\"access\":\"free\",\"objective\":{\"tr\":\"Grimm hidrit yer değiştirme kuralı ve klasik biyoizosterik serileri uygulayarak öncü moleküllerde metabolik stabiliteyi ve hedef reseptör seçiciliğini optimize etmek.\",\"ar\":\"تطبيق قاعدة إزاحة هيدريد Grimm وسلاسل التشابه الحيوي الكلاسيكية لتحسين الثباتية الاستقلابية وانتقائية المستقبل في المركبات الطليعية.\",\"en\":\"Apply Grimm's Hydride Displacement Law and classical bioisosteric series to replace atoms/groups, predicting changes in receptor recognition and metabolic fate.\"},\"misconceptions\":[{\"tr\":\"Biyoizosterik grupların periyodik tabloda mutlaka aynı dikey sütunda (aynı element ailesinde) yer alması gerektiği yanılgısı.\",\"ar\":\"الظن الخاطئ بوجوب انتماء المجموعات البيوإيزوستيرية حتماً إلى نفس العمود الرأسي (نفس العائلة) في الجدول الدوري.\",\"en\":\"The misconception that bioisosteres must belong to the exact same column or element family in the periodic table.\"},{\"tr\":\"Biyoizosterik değişimin daima ana molekül gibi agonist farmakolojik aktivite göstereceği düşüncesi (antimetabolitlerin göz ardı edilmesi).\",\"ar\":\"الاعتقاد الخاطئ بأن التبديل البيوإيزوستيري ينتج دوماً تأثيراً منبهاً (agonist) مماثلاً للمركب الأصلي متجاهلاً مضادات الاستقلاب.\",\"en\":\"The belief that bioisosteric modifications always yield agonistic activity, overlooking bioisosteric antimetabolites and antagonists.\"},{\"tr\":\"Flor atomunun van der Waals yarıçapının hidrojenden çok büyük olduğu veya proteini iyonik parçaladığı yanılgısı.\",\"ar\":\"الظن الخاطئ بأن نصف قطر فان دير فالس للفلور أكبر بكثير من الهيدروجين أو أنه يحطم البروتينات أيونياً.\",\"en\":\"The assumption that fluorine has a vastly larger van der Waals radius than hydrogen or physically cleaves proteins.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":1},{\"file\":\"Biyoizosterizm.pdf\",\"page\":2},{\"file\":\"Biyoizosterizm.pdf\",\"page\":3},{\"file\":\"Biyoizosterizm.pdf\",\"page\":4},{\"file\":\"Biyoizosterizm.pdf\",\"page\":5},{\"file\":\"Biyoizosterizm.pdf\",\"page\":6},{\"file\":\"Biyoizosterizm.pdf\",\"page\":7},{\"file\":\"Biyoizosterizm.pdf\",\"page\":8},{\"file\":\"Biyoizosterizm.pdf\",\"page\":11},{\"file\":\"Biyoizosterizm.pdf\",\"page\":13},{\"file\":\"Biyoizosterizm.pdf\",\"page\":14},{\"file\":\"Biyoizosterizm.pdf\",\"page\":15}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Foye's Principles of Medicinal Chemistry\",\"edition\":\"8th ed.\",\"topic\":\"Bioisosterism and Molecular Modification in Drug Design\",\"chapter\":\"Chapter 2\",\"page\":\"45-62\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Wilson and Gisvold's Textbook of Organic Medicinal and Pharmaceutical Chemistry\",\"edition\":\"12th ed.\",\"topic\":\"Isosterism and Bioisosterism in Drug Discovery\",\"chapter\":\"Chapter 3\",\"page\":\"75-92\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"mc-mod3-les1-card1\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Grimm Hidrit Deplasman Kuralı\",\"prompt\":\"Grimm hidrit kuralına göre bir atoma bir hidrojen (H•) eklendiğinde hangi grubun elektronik özelliklerini kazanır?\",\"answer\":\"Periyodik tabloda bir sonraki (bir sağındaki) grubun değerlik elektronu kabuk özelliklerini kazanır; böylece -CH3, -NH2, -OH ve -F izosterik psödoatomlar oluşturur.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod3-les1-card2\",\"courseId\":\"medchem\",\"drugOrConcept\":\"5-Fluorourasil ve İntihar Substratı\",\"prompt\":\"5-Fluorourasil (5-FU) timidilat sentaz enzimini hangi mekanizmayla irreversibl bloke eder?\",\"answer\":\"Flor (1.47 Å) hidrojenle (1.20 Å) neredeyse aynı boyuttadır ve enzimi aldatır; ancak C-F bağı (116 kcal/mol) koparılamadığından kovalent üçlü kompleks kalıcı kilitlenir.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod3-les1-card3\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Fenotiyazin-Dibenzazepin Dönüşümü\",\"prompt\":\"Klorpromazindeki (fenotiyazin) -S- köprüsü -CH2-CH2- ile değiştirildiğinde (imipramin) klinik etki nasıl değişir?\",\"answer\":\"Molekülün 3 boyutlu katlanma açısı değişir; dopamin D2 bloker antipsikotik etki kaybolur ve yerini monoamin geri alım blokeri trisiklik antidepresan etki alır.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod3-les1-card4\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Benzen-Tiyofen Halka Eşdeğerliği\",\"prompt\":\"Benzen halkasındaki -CH=CH- grubu yerine tek bir kükürt atomu (-S-) konulduğunda (Tiyofen) aromatiklik neden korunur?\",\"answer\":\"Hansberg kuralına göre kükürt atomunun d-orbitalleri ve serbest elektron çifti aromatik pi-delokalizasyonuna katılarak 6 pi elektronlu Hückel aromatik rezonansını sürdürür.\",\"box\":1,\"intervalDays\":1}],\"translations\":{\"tr\":{\"title\":\"Klasik Biyoizosterizm ve Grimm Hidrit Yer Değiştirme\"},\"ar\":{\"title\":\"التشابه الحيوي الكلاسيكي وإزاحة هيدريد Grimm\"}},\"steps\":[{\"id\":\"mc-mod3-les1-step-01\",\"stage\":\"hook\",\"stageIndex\":1,\"type\":\"predict_reveal\",\"title\":{\"tr\":\"Metabolik Kamuflaj: Urasil vs 5-Fluorourasil Paradoksu\",\"ar\":\"التمويه الاستقلابي: مفارقة اليوراسيل و5-فلورويوراسيل\",\"en\":\"Metabolic Camouflage: The Uracil vs 5-FU Paradox\"},\"prompt\":{\"tr\":\"Doğal urasildeki tek bir hidrojen yerine flor takılınca molekül öldürücü bir antikanser ilacına (5-FU) dönüşür. Enzim flor atomunu neden hidrojen zannedip tuzağa düşer?\",\"ar\":\"استبدال هيدروجين واحد في اليوراسيل الطبيعي بذرة فلور يحوله لسلاح قاتل للسرطان (5-FU). لماذا يظن الأنزيم الفلور هيدروجيناً ويقع في الفخ القاتل؟\",\"en\":\"Replacing a single hydrogen on natural uracil with fluorine creates the lethal anticancer drug 5-FU. Why does thymidylate synthase mistake fluorine for hydrogen and walk into a trap?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-1a\",\"text\":{\"tr\":\"Florun van der Waals yarıçapı (1.47 Å) hidrojene (1.20 Å) çok yakındır; enzim sterik olarak aldanır ancak sağlam C-F bağını (116 kcal/mol) koparamaz.\",\"ar\":\"نصف قطر فان دير فالس للفلور (1.47 Å) مقارب جداً للهيدروجين (1.20 Å)؛ فينخدع الأنزيم فراغياً لكنه يعجز عن كسر رابطة C-F الفولاذية (116 kcal/mol).\",\"en\":\"Fluorine's van der Waals radius (1.47 Å) closely matches hydrogen (1.20 Å); the enzyme docks it, but cannot break the unbreakable C-F bond (116 kcal/mol).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Flor, hidrojene sterik olarak en yakın atomdur (1.47 Å vs 1.20 Å). Enzim cebine kusursuz oturur, fakat C-5'ten flor ayrılamadığı için timidilat sentaz kovalent olarak kilitlenir.\",\"ar\":\"صحيح! الفلور أقرب الذرات حجماً للهيدروجين؛ يرسو بدقة في جيب الأنزيم، لكن استعصاء كسر رابطة C-F يعطل الأنزيم تساهمياً بشكل غير عكوس.\",\"en\":\"Correct! Fluorine is the closest steric mimic of hydrogen (1.47 Å vs 1.20 Å). It docks seamlessly, but thymidylate synthase cannot abstract fluorine, forming a permanent covalent dead-end complex.\"}},{\"id\":\"opt-1b\",\"text\":{\"tr\":\"Flor pozitif yük taşıdığı için enzimin aktif bölgesindeki negatif yüklü aspartatları iyonik olarak parçalar.\",\"ar\":\"يحمل الفلور شحنة موجبة تخرب أسبارتات الأنزيم سالبة الشحنة بروابط أيونية عنيفة.\",\"en\":\"Fluorine carries a positive formal charge that electrostatically cleaves active site aspartates.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yük yanılgısı: Flor periyodik tablonun en elektronegatif elementidir; asla pozitif yük taşımaz ve proteinleri iyonik olarak parçalamaz.\",\"ar\":\"خطأ الشحنة: الفلور العنصر الأعلى كهروسلبية في الطبيعة؛ لا يحمل شحنة موجبة ولا يخرب البروتينات أيونياً.\",\"en\":\"Charge misconception: Fluorine is the most electronegative element; it never bears a positive charge or electrostatically cleaves residues.\"}},{\"id\":\"opt-1c\",\"text\":{\"tr\":\"Flor atomu urasilin molekül ağırlığını 10 kat artırarak enzimin aktif bölgesini fiziksel olarak tıkar.\",\"ar\":\"تضاعف ذرة الفلور الوزن الجزيئي لليوراسيل 10 أضعاف فتسد الموقع الفعال مادياً.\",\"en\":\"The fluorine atom increases uracil's molecular weight 10-fold, physically jamming the active site.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Hacim yanılgısı: Florun atom ağırlığı 19 g/mol'dür; urasile sadece 18 kütle birimi ekler, devasa bir sterik tıkanma yaratmaz.\",\"ar\":\"خطأ الكتلة: الوزن الذري للفلور 19 g/mol؛ يضيف 18 وحدة كتلة فقط لليوراسيل ولا يسبب انسداداً فراغياً هائلاً.\",\"en\":\"Mass misconception: Fluorine adds only 18 atomic mass units to uracil; it does not physically obstruct the catalytic pocket via sheer bulk.\"}}]},\"technicalTerms\":[{\"term\":\"biyoizoster\",\"arContext\":\"المتشابه الحيوي (bioisostere)\"},{\"term\":\"intihar substratı\",\"arContext\":\"الركيزة الانتحارية (suicide substrate)\"}],\"hints\":[{\"tr\":\"Flor atomunun boyutunu ve hidrojene olan fiziksel benzerliğini düşünün.\",\"ar\":\"فكر في الحجم الفراغي للفلور والتشابه الفيزيائي المذهل مع الهيدروجين.\",\"en\":\"Consider the van der Waals radius of fluorine compared to hydrogen.\"},{\"tr\":\"Florun van der Waals yarıçapı 1.47 Å iken hidrojeninki 1.20 Å'dur. Ancak C-F kovalent bağı 116 kcal/mol ile aşırı güçlüdür.\",\"ar\":\"نصف قطر الفلور 1.47 Å مقابل 1.20 Å للهيدروجين، غير أن رابطة C-F التساهمية تبلغ طاقتها 116 kcal/mol.\",\"en\":\"Fluorine has a van der Waals radius of 1.47 Å versus 1.20 Å for hydrogen, but forms an ultra-stable C-F bond (116 kcal/mol).\"},{\"tr\":\"Enzim flor atomunu boyutsal olarak hidrojen zanneder; fakat timin sentezinde hidrür transferi basamağında C-F bağı koparılamaz ve enzim irreversibl intihar inhibisyonuna uğrar.\",\"ar\":\"ينخدع الأنزيم بحجم الفلور، لكنه يعجز عن كسر رابطة C-F في خطوة نزع البروتون فيتعطل نهائياً بآلية التثبيط الانتحاري.\",\"en\":\"The active site accommodates fluorine stereochemically, but fails to abstract it during hydride transfer, irreversibly disabling the enzyme.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":11}],\"config\":{\"options\":[{\"id\":\"opt-1a\",\"text\":\"Florun van der Waals yarıçapı (1.47 Å) hidrojene (1.20 Å) çok yakındır; enzim sterik olarak aldanır ancak sağlam C-F bağını (116 kcal/mol) koparamaz.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Flor, hidrojene sterik olarak en yakın atomdur (1.47 Å vs 1.20 Å). Enzim cebine kusursuz oturur, fakat C-5'ten flor ayrılamadığı için timidilat sentaz kovalent olarak kilitlenir.\"},{\"id\":\"opt-1b\",\"text\":\"Flor pozitif yük taşıdığı için enzimin aktif bölgesindeki negatif yüklü aspartatları iyonik olarak parçalar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yük yanılgısı: Flor periyodik tablonun en elektronegatif elementidir; asla pozitif yük taşımaz ve proteinleri iyonik olarak parçalamaz.\"},{\"id\":\"opt-1c\",\"text\":\"Flor atomu urasilin molekül ağırlığını 10 kat artırarak enzimin aktif bölgesini fiziksel olarak tıkar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Hacim yanılgısı: Florun atom ağırlığı 19 g/mol'dür; urasile sadece 18 kütle birimi ekler, devasa bir sterik tıkanma yaratmaz.\"}],\"revealedOutcome\":{\"tr\":\"Florun van der Waals yarıçapı (1.47 Å) hidrojene (1.20 Å) çok yakındır; enzim sterik olarak aldanır ancak sağlam C-F bağını (116 kcal/mol) koparamaz.\",\"ar\":\"نصف قطر فان دير فالس للفلور (1.47 Å) مقارب جداً للهيدروجين (1.20 Å)؛ فينخدع الأنزيم فراغياً لكنه يعجز عن كسر رابطة C-F الفولاذية (116 kcal/mol).\",\"en\":\"Fluorine's van der Waals radius (1.47 Å) closely matches hydrogen (1.20 Å); the enzyme docks it, but cannot break the unbreakable C-F bond (116 kcal/mol).\"},\"explanation\":{\"tr\":\"Doğru! Flor, hidrojene sterik olarak en yakın atomdur (1.47 Å vs 1.20 Å). Enzim cebine kusursuz oturur, fakat C-5'ten flor ayrılamadığı için timidilat sentaz kovalent olarak kilitlenir.\",\"ar\":\"صحيح! الفلور أقرب الذرات حجماً للهيدروجين؛ يرسو بدقة في جيب الأنزيم، لكن استعصاء كسر رابطة C-F يعطل الأنزيم تساهمياً بشكل غير عكوس.\",\"en\":\"Correct! Fluorine is the closest steric mimic of hydrogen (1.47 Å vs 1.20 Å). It docks seamlessly, but thymidylate synthase cannot abstract fluorine, forming a permanent covalent dead-end complex.\"}}},{\"id\":\"mc-mod3-les1-step-02\",\"stage\":\"question\",\"stageIndex\":2,\"type\":\"question\",\"title\":{\"tr\":\"Aktif Soru: Biyoizosterler Aynı Element Grubunda mı Olmalıdır?\",\"ar\":\"سؤال تفاعلي: هل يجب أن تنتمي المتشابهات لنفس المجموعة؟\",\"en\":\"Active Question: Must Bioisosteres Share Element Families?\"},\"prompt\":{\"tr\":\"Bir öncü ilaçta biyoizosterik değişim yaparken, yer değiştiren atom veya fonksiyonel grupların periyodik tabloda mutlaka aynı dikey sütunda (aynı element ailesinde) yer alması zorunlu mudur?\",\"ar\":\"عند إجراء استبدال بيوإيزوستيري في دواء طليعي، هل يشترط حتماً أن تنتمي الذرات أو المجموعات المتبادلة لنفس العمود الرأسي (نفس العائلة) في الجدول الدوري؟\",\"en\":\"When designing bioisosteric replacements in a lead drug, is it strictly mandatory that exchanging atoms or functional groups belong to the exact same vertical column in the periodic table?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-2a\",\"text\":{\"tr\":\"Hayır; Grimm hidrit kuralına göre farklı gruptaki atomlar hidrojen eklenerek (psödoatom oluşturarak) birbirinin değerlik elektronunu ve hacmini taklit edebilir.\",\"ar\":\"كلا؛ وفق قاعدة إزاحة هيدريد Grimm، يمكن لذرات من مجموعات مختلفة محاكاة إلكترونات وحجم بعضها عند إضافة الهيدروجين لتشكيل ذرات زائفة.\",\"en\":\"No; Grimm's hydride displacement law proves atoms from different groups mimic each other's valence electrons and volume when bonded to hydrogen.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika! C (Grup 14), N (Grup 15), O (Grup 16) ve F (Grup 17) farklı sütunlardadır; ancak -CH3, -NH2, -OH ve -F gruplarının hepsi 9 değerlik elektronlu monovalan izosterlerdir.\",\"ar\":\"ممتاز! تنتمي عناصر C و N و O و F لأعمدة مختلفة، لكن مجموعات -CH3 و -NH2 و -OH و -F جميعها إيزوستيرات أحادية التكافؤ بـ 9 إلكترونات تكافؤ خارجية.\",\"en\":\"Brilliant! C, N, O, and F occupy distinct columns, yet -CH3, -NH2, -OH, and -F form an identical 9-electron monovalent pseudoatom family.\"}},{\"id\":\"opt-2b\",\"text\":{\"tr\":\"Evet; kimyasal benzerlik yalnızca aynı gruptaki elementler (örneğin yalnızca F, Cl, Br, I arasında) geçerlidir.\",\"ar\":\"نعم؛ التشابه الكيميائي ينطبق حصراً على عناصر نفس المجموعة الرأسية (مثل التبادل بين F و Cl و Br فقط).\",\"en\":\"Yes; chemical similarity strictly applies only to elements within the exact same vertical family (e.g., exclusively F, Cl, Br, I).\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Element ailesi yanılgısı: Yalnızca aynı sütun elemanları değil; farklı sütun atomları hidrit alarak (Grimm psödoatomları: -CH3 ~ -NH2 ~ -OH ~ -F) kusursuz izosterler oluşturur.\",\"ar\":\"خطأ العائلة الواحدة: لا يقتصر الأمر على نفس العمود؛ إذ تكتسب الذرات هيدريدات لتشكل إيزوستيرات مثالية (-CH3 ~ -NH2 ~ -OH ~ -F).\",\"en\":\"Same-column misconception: Isosterism transcends periodic families; different group elements acquire hydrides to form cross-column pseudoatoms.\"}},{\"id\":\"opt-2c\",\"text\":{\"tr\":\"Evet; çünkü farklı periyot ve gruptaki atomların elektronegatiflikleri daima zıt olmak zorundadır.\",\"ar\":\"نعم؛ لأن الكهروسلبية لذرات المجموعات المختلفة يجب أن تكون متعاكسة دوماً.\",\"en\":\"Yes; because atoms from different groups must possess completely opposing electronegativities.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Elektronegatiflik yanılgısı: Elektronegatiflik periyot boyunca kademeli değişir; karbon, azot ve oksijen benzer boyutlarda kovalent bağ kurabilir.\",\"ar\":\"خطأ الكهروسلبية: تتغير الكهروسلبية تدريجياً، وتستطيع ذرات C و N و O تشكيل روابط تساهمية بأبعاد متقاربة.\",\"en\":\"Electronegativity misconception: Electronegativity gradients vary smoothly, allowing C, N, O, and F fragments to exhibit compatible bonding geometries.\"}}]},\"technicalTerms\":[{\"term\":\"Grimm hidrit kuralı\",\"arContext\":\"قاعدة إزاحة هيدريد Grimm\"},{\"term\":\"psödoatom\",\"arContext\":\"الذرة الزائفة (pseudoatom)\"}],\"hints\":[{\"tr\":\"Karbon (Grup 14), azot (Grup 15), oksijen (Grup 16) ve flor (Grup 17) gruplarını düşünün.\",\"ar\":\"تأمل عناصر الكربون (المجموعة 14) والنيتروجين (15) والأكسجين (16) والفلور (17).\",\"en\":\"Examine Carbon (Group 14), Nitrogen (Group 15), Oxygen (Group 16), and Fluorine (Group 17).\"},{\"tr\":\"-CH3, -NH2, -OH ve -F gruplarının değerlik elektron sayılarını toplayın. Ne fark ettiniz?\",\"ar\":\"اجمع إلكترونات التكافؤ للمجموعات: -CH3 و -NH2 و -OH و -F. ماذا تلاحظ؟\",\"en\":\"Sum outer valence electrons for -CH3, -NH2, -OH, and -F. Notice any pattern?\"},{\"tr\":\"Grimm yasasına göre farklı gruplardaki atomlar hidrojen kazanarak aynı değerlik kabuğunu (psödoatom) oluşturur; aynı sütunda olma şartı yoktur.\",\"ar\":\"وفق قانون غريم، تكتسب الذرات هيدروجينات لتتطابق في غلاف التكافؤ الخارجي دون اشتراط وجودها في نفس العمود.\",\"en\":\"By Grimm's law, atoms across different periodic columns gain hydrides to form isoelectronic pseudoatoms; vertical family matching is not required.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":3}],\"config\":{\"options\":[{\"id\":\"opt-2a\",\"text\":\"Hayır; Grimm hidrit kuralına göre farklı gruptaki atomlar hidrojen eklenerek (psödoatom oluşturarak) birbirinin değerlik elektronunu ve hacmini taklit edebilir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika! C (Grup 14), N (Grup 15), O (Grup 16) ve F (Grup 17) farklı sütunlardadır; ancak -CH3, -NH2, -OH ve -F gruplarının hepsi 9 değerlik elektronlu monovalan izosterlerdir.\"},{\"id\":\"opt-2b\",\"text\":\"Evet; kimyasal benzerlik yalnızca aynı gruptaki elementler (örneğin yalnızca F, Cl, Br, I arasında) geçerlidir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Element ailesi yanılgısı: Yalnızca aynı sütun elemanları değil; farklı sütun atomları hidrit alarak (Grimm psödoatomları: -CH3 ~ -NH2 ~ -OH ~ -F) kusursuz izosterler oluşturur.\"},{\"id\":\"opt-2c\",\"text\":\"Evet; çünkü farklı periyot ve gruptaki atomların elektronegatiflikleri daima zıt olmak zorundadır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Elektronegatiflik yanılgısı: Elektronegatiflik periyot boyunca kademeli değişir; karbon, azot ve oksijen benzer boyutlarda kovalent bağ kurabilir.\"}],\"revealedOutcome\":{\"tr\":\"Hayır; Grimm hidrit kuralına göre farklı gruptaki atomlar hidrojen eklenerek (psödoatom oluşturarak) birbirinin değerlik elektronunu ve hacmini taklit edebilir.\",\"ar\":\"كلا؛ وفق قاعدة إزاحة هيدريد Grimm، يمكن لذرات من مجموعات مختلفة محاكاة إلكترونات وحجم بعضها عند إضافة الهيدروجين لتشكيل ذرات زائفة.\",\"en\":\"No; Grimm's hydride displacement law proves atoms from different groups mimic each other's valence electrons and volume when bonded to hydrogen.\"},\"explanation\":{\"tr\":\"Harika! C (Grup 14), N (Grup 15), O (Grup 16) ve F (Grup 17) farklı sütunlardadır; ancak -CH3, -NH2, -OH ve -F gruplarının hepsi 9 değerlik elektronlu monovalan izosterlerdir.\",\"ar\":\"ممتاز! تنتمي عناصر C و N و O و F لأعمدة مختلفة، لكن مجموعات -CH3 و -NH2 و -OH و -F جميعها إيزوستيرات أحادية التكافؤ بـ 9 إلكترونات تكافؤ خارجية.\",\"en\":\"Brilliant! C, N, O, and F occupy distinct columns, yet -CH3, -NH2, -OH, and -F form an identical 9-electron monovalent pseudoatom family.\"}}},{\"id\":\"mc-mod3-les1-step-03\",\"stage\":\"intuition\",\"stageIndex\":3,\"type\":\"intuition\",\"title\":{\"tr\":\"Sezgisel Model: Grimm'in Atomik Kamuflajı\",\"ar\":\"النموذج الحسي: تمويه غريم الذري\",\"en\":\"Intuitive Mental Model: Grimm's Atomic Camouflage\"},\"prompt\":{\"tr\":\"Bir askere sahte rütbe işareti takıldığında bir üst rütbeli gibi görünür. Periyodik tablodaki bir atoma bir proton ve elektron (H•) taktığınızda neden bir sonraki grubun atomu gibi davranır?\",\"ar\":\"تخيل جندياً يرتدي شارة رتبة أعلى ليبدو كضابط. عندما تضيف بروتوناً وإلكتروناً (H•) لذرة في الجدول الدوري، لماذا تتصرف كعنصر المجموعة التالية؟\",\"en\":\"Imagine a soldier donning a higher badge to disguise as the next rank. When you attach a proton and electron (H•) to an atom, why does it mimic the next periodic group?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-3a\",\"text\":{\"tr\":\"Eklenen hidrojen değerlik kabuğuna tam 1 elektron katar; çekirdek yüküyle birlikte atomun dış kabuk elektron sayısı bir sağındaki gruba eşitlenir.\",\"ar\":\"يمنح الهيدروجين المضاف إلكتروناً واحداً لغلاف التكافؤ، ليتطابق عدد إلكترونات الغلاف الخارجي تماماً مع عنصر المجموعة المجاورة.\",\"en\":\"The added hydrogen contributes exactly 1 valence electron, aligning the outer shell electron count with the adjacent periodic group.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Tam olarak öyle! Hans Erlenmeyer'in (1932) psödoatom kuralı: C+3H (-CH3), N+2H (-NH2), O+1H (-OH) ve F grupları aynı değerlik kabuğunu (7 valans elektronu) paylaşan monovalan psödoatomlardır (Slayt 3).\",\"ar\":\"بالضبط! قاعدة هانس إرلنماير (1932) لأشباه الذرات: C+3H (-CH3) و N+2H (-NH2) و O+1H (-OH) والفلور تتقاسم نفس غلاف التكافؤ كأشباه ذرات أحادية التكافؤ (شريحة 3).\",\"en\":\"Spot on! Hans Erlenmeyer's (1932) pseudoatom law: C+3H (-CH3), N+2H (-NH2), O+1H (-OH), and F share identical valence electron configurations (Slide 3).\"}},{\"id\":\"opt-3b\",\"text\":{\"tr\":\"Hidrojen atomu ana atomun çekirdeğini nükleer füzyonla dönüştürerek yeni bir elemente çevirir.\",\"ar\":\"يقوم الهيدروجين باندماج نووي يغير نواة الذرة الأصلية لعنصر جديد كلياً.\",\"en\":\"The hydrogen atom triggers nuclear fusion, transmuting the core nucleus into a new element.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Nükleer füzyon yanılgısı: Bu bir nükleer tepkime değil, kimyasal kovalent bağ ve değerlik elektronu düzenlenmesidir.\",\"ar\":\"خطأ الاندماج النووي: هذا تفاعل تساهمي وإعادة ترتيب لإلكترونات التكافؤ، وليس اندماجاً نووياً للأنوية.\",\"en\":\"Nuclear transmutation misconception: Hydride displacement is electronic valence camouflage via covalent bonding, not nuclear transmutation.\"}},{\"id\":\"opt-3c\",\"text\":{\"tr\":\"Hidrojen moleküldeki tüm kovalent bağları kopararak serbest radikal fırtınası başlatır.\",\"ar\":\"يحطم الهيدروجين كافة الروابط التساهمية مشعلاً عاصفة من الجذور الحرة.\",\"en\":\"The hydrogen shears all existing covalent bonds, generating a destructive radical storm.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Radikalik yıkım yanılgısı: Grimm kuralı stabil kovalent bağlar ve kararlı psödoatomlar üretir.\",\"ar\":\"خطأ الجذور الحرة: تنتج قاعدة غريم جزيئات تساهمية مستقرة تماماً ولا تطلق جذوراً حرة مخربة.\",\"en\":\"Radical storm misconception: Grimm's law yields stable, ground-state covalent pseudoatoms, not reactive free radicals.\"}}]},\"technicalTerms\":[{\"term\":\"değerlik elektronu\",\"arContext\":\"إلكترون التكافؤ (valence electron)\"},{\"term\":\"psödoatom\",\"arContext\":\"الذرة الزائفة\"}],\"hints\":[{\"tr\":\"Hidrojen atomunun değerlik kabuğuna kaç elektron katkı sağladığını düşünün.\",\"ar\":\"كم إلكتروناً تضيف ذرة الهيدروجين إلى غلاف التكافؤ الخارجي؟\",\"en\":\"How many valence electrons does a single hydrogen atom contribute?\"},{\"tr\":\"C (4e) + 1H -> 5e (N gibi). C (4e) + 2H -> 6e (O gibi). C (4e) + 3H -> 7e (Halojen gibi).\",\"ar\":\"كربون (4) + H يماثل نيتروجين (5). كربون (4) + 2H يماثل أكسجين (6). كربون (4) + 3H يماثل هالوجين (7).\",\"en\":\"C (4e) + 1H -> 5e (like N). C (4e) + 2H -> 6e (like O). C (4e) + 3H -> 7e (like Halogen).\"},{\"tr\":\"Her eklenen H• değerlik kabuğunu 1 elektron artırır; bu sayede -CH3, -NH2, -OH ve -F grupları aynı dış değerlik elektronuna sahip psödoatomlar haline gelir.\",\"ar\":\"تزيد كل ذرة H الغلاف بإلكترون واحد؛ لتصبح مجموعات -CH3 و -NH2 و -OH و -F ذرات زائفة بنفس إلكترونات التكافؤ الخارجية.\",\"en\":\"Each added hydride shifts valence by +1, creating isoelectronic pseudoatoms across -CH3, -NH2, -OH, and -F.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":4}],\"config\":{\"options\":[{\"id\":\"opt-3a\",\"text\":\"Eklenen hidrojen değerlik kabuğuna tam 1 elektron katar; çekirdek yüküyle birlikte atomun dış kabuk elektron sayısı bir sağındaki gruba eşitlenir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Tam olarak öyle! Hans Erlenmeyer'in (1932) psödoatom kuralı: C+3H (-CH3), N+2H (-NH2), O+1H (-OH) ve F grupları aynı değerlik kabuğunu (7 valans elektronu) paylaşan monovalan psödoatomlardır (Slayt 3).\"},{\"id\":\"opt-3b\",\"text\":\"Hidrojen atomu ana atomun çekirdeğini nükleer füzyonla dönüştürerek yeni bir elemente çevirir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Nükleer füzyon yanılgısı: Bu bir nükleer tepkime değil, kimyasal kovalent bağ ve değerlik elektronu düzenlenmesidir.\"},{\"id\":\"opt-3c\",\"text\":\"Hidrojen moleküldeki tüm kovalent bağları kopararak serbest radikal fırtınası başlatır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Radikalik yıkım yanılgısı: Grimm kuralı stabil kovalent bağlar ve kararlı psödoatomlar üretir.\"}],\"revealedOutcome\":{\"tr\":\"Eklenen hidrojen değerlik kabuğuna tam 1 elektron katar; çekirdek yüküyle birlikte atomun dış kabuk elektron sayısı bir sağındaki gruba eşitlenir.\",\"ar\":\"يمنح الهيدروجين المضاف إلكتروناً واحداً لغلاف التكافؤ، ليتطابق عدد إلكترونات الغلاف الخارجي تماماً مع عنصر المجموعة المجاورة.\",\"en\":\"The added hydrogen contributes exactly 1 valence electron, aligning the outer shell electron count with the adjacent periodic group.\"},\"explanation\":{\"tr\":\"Tam olarak öyle! Hans Erlenmeyer'in (1932) psödoatom kuralı: C+3H (-CH3), N+2H (-NH2), O+1H (-OH) ve F grupları aynı değerlik kabuğunu (7 valans elektronu) paylaşan monovalan psödoatomlardır (Slayt 3).\",\"ar\":\"بالضبط! قاعدة هانس إرلنماير (1932) لأشباه الذرات: C+3H (-CH3) و N+2H (-NH2) و O+1H (-OH) والفلور تتقاسم نفس غلاف التكافؤ كأشباه ذرات أحادية التكافؤ (شريحة 3).\",\"en\":\"Spot on! Hans Erlenmeyer's (1932) pseudoatom law: C+3H (-CH3), N+2H (-NH2), O+1H (-OH), and F share identical valence electron configurations (Slide 3).\"}}},{\"id\":\"mc-mod3-les1-step-04\",\"stage\":\"visual_explanation\",\"stageIndex\":4,\"type\":\"visual_explanation\",\"title\":{\"tr\":\"Görsel Değerlik Mimarisi: Grimm Tablosu ve Langmuir İzosterleri\",\"ar\":\"الهندسة البصرية للتكافؤ: جدول غريم وإيزوستيرات لانغموير\",\"en\":\"Visual Valence Architecture: Grimm's Table & Langmuir Isosteres\"},\"prompt\":{\"tr\":\"Langmuir, N2O ve CO2 gazlarının 20°C'de birebir aynı viskoziteye (148 x 10^-6 Pa·s) ve dansiteye sahip olduğunu kanıtlamıştır. Bu fiziksel özdeşliğin kuantum ve elektronik temeli nedir?\",\"ar\":\"أثبت لانغموير أن غازي N2O و CO2 يمتلكان نفس اللزوجة تماماً (148 x 10^-6 Pa·s) والكثافة عند 20°C. ما هو الأساس الكمي والإلكتروني لهذا التطابق؟\",\"en\":\"Langmuir proved that N2O and CO2 gases possess identical viscosity (148 x 10^-6 Pa·s) and density at 20°C. What is the fundamental quantum and electronic basis for this physical identity?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-4a\",\"text\":{\"tr\":\"Her iki molekül de 16 değerlik elektronu, 22 toplam elektron ve özdeş doğrusal geometriye sahiptir; dış elektron bulutları neredeyse ayırt edilemezdir.\",\"ar\":\"يمتلك كلا الجزيئين 16 إلكترون تكافؤ، و22 إلكتروناً كلياً، وهندسة خطية متطابقة، مما يجعل السحب الإلكترونية الخارجية متماثلة تماماً.\",\"en\":\"Both molecules share 16 valence electrons, 22 total electrons, and identical linear geometries, creating virtually indistinguishable electron clouds.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! N2O ve CO2 klasik Langmuir izosterleridir. Aynı elektron sayısı ve uzaysal orbital dağılımı viskozite, kırılma indisi ve dielektrik sabiti gibi fiziksel özellikleri ikiz kardeş yapar.\",\"ar\":\"صحيح! N2O و CO2 إيزوستيران كلاسيكيان وفق لانغموير. تماثل إلكترونات التكافؤ والهندسة الفراغية يولد تطابقاً شبه تام في اللزوجة والكثافة ومعامل الانكسار.\",\"en\":\"Correct! N2O and CO2 are classical Langmuir isosteres. Matching valence electrons (16) and linear geometries generate near-identical fluid viscosities and dielectric properties.\"}},{\"id\":\"opt-4b\",\"text\":{\"tr\":\"Her iki molekülde de tüm atomlar karbon atomuna dönüşmüştür.\",\"ar\":\"تحولت كافة الذرات في كلا الجزيئين إلى ذرات كربون متماثلة.\",\"en\":\"All constituent atoms in both gases have transmuted into carbon.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Atomik dönüşüm yanılgısı: N2O azot ve oksijenden, CO2 karbon ve oksijenden oluşur; benzerlik atom çekirdeklerinden değil değerlik kabuğu elektron dağılımından kaynaklanır.\",\"ar\":\"خطأ التماثل الذري: يتركب N2O من نيتروجين وأكسجين، بينما CO2 من كربون وأكسجين؛ التماثل ينبع من الغلاف الإلكتروني الخارجي.\",\"en\":\"Atomic identity misconception: The gases possess different atomic nuclei; identical properties arise from shared valence electron counts and geometries.\"}},{\"id\":\"opt-4c\",\"text\":{\"tr\":\"N2O ve CO2 gazları sadece sıvı helyum sıcaklığında (-269°C) aynı davranışı sergiler.\",\"ar\":\"يتصرف الغازان بشكل متماثل فقط عند درجة حرارة الهيليوم السائل (-269°C).\",\"en\":\"N2O and CO2 behave identically only near absolute zero in liquid helium.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Sıcaklık kısıtı yanılgısı: Tablo verileri oda sıcaklığında (20°C) tam eşit viskoziteyi göstermektedir.\",\"ar\":\"خطأ الحرارة: بيانات سلايدات الجامعة تثبت تطابق اللزوجة عند درجة حرارة الغرفة (20°C).\",\"en\":\"Temperature misconception: Slide 2 data confirms identical viscosity measured at ambient room temperature (20°C).\"}}]},\"technicalTerms\":[{\"term\":\"Langmuir izosteri\",\"arContext\":\"إيزوستير لانغموير (Langmuir isostere)\"},{\"term\":\"değerlik kabuğu\",\"arContext\":\"غلاف التكافؤ\"}],\"hints\":[{\"tr\":\"N (7e x 2) + O (8e) = 22 elektron. C (6e) + O (8e x 2) = 22 elektron.\",\"ar\":\"احسب الإلكترونات: N (7×2) + O (8) = 22 إلكتروناً. C (6) + O (8×2) = 22 إلكتروناً.\",\"en\":\"Total electrons: N (7x2) + O (8) = 22. C (6) + O (8x2) = 22.\"},{\"tr\":\"Değerlik elektronlarını sayın: N2O (5+5+6 = 16), CO2 (4+6+6 = 16).\",\"ar\":\"إلكترونات التكافؤ الخارجية: N2O (5+5+6 = 16) و CO2 (4+6+6 = 16).\",\"en\":\"Valence electrons: N2O (5+5+6 = 16), CO2 (4+6+6 = 16).\"},{\"tr\":\"Eşit değerlik elektronu (16) ve toplam elektron (22) sayısı ile lineer 3 atomlu geometri Langmuir izosterizminin kusursuz kanıtıdır.\",\"ar\":\"تطابق إلكترونات التكافؤ (16) والإلكترونات الكلية (22) مع الهندسة الخطية هو برهان إيزوستيرية لانغموير الكلاسيكية.\",\"en\":\"Matching 16 valence electrons, 22 total electrons, and triatomic linear geometry define classical Langmuir isosteres.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":2}],\"config\":{\"options\":[{\"id\":\"opt-4a\",\"text\":\"Her iki molekül de 16 değerlik elektronu, 22 toplam elektron ve özdeş doğrusal geometriye sahiptir; dış elektron bulutları neredeyse ayırt edilemezdir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! N2O ve CO2 klasik Langmuir izosterleridir. Aynı elektron sayısı ve uzaysal orbital dağılımı viskozite, kırılma indisi ve dielektrik sabiti gibi fiziksel özellikleri ikiz kardeş yapar.\"},{\"id\":\"opt-4b\",\"text\":\"Her iki molekülde de tüm atomlar karbon atomuna dönüşmüştür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Atomik dönüşüm yanılgısı: N2O azot ve oksijenden, CO2 karbon ve oksijenden oluşur; benzerlik atom çekirdeklerinden değil değerlik kabuğu elektron dağılımından kaynaklanır.\"},{\"id\":\"opt-4c\",\"text\":\"N2O ve CO2 gazları sadece sıvı helyum sıcaklığında (-269°C) aynı davranışı sergiler.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Sıcaklık kısıtı yanılgısı: Tablo verileri oda sıcaklığında (20°C) tam eşit viskoziteyi göstermektedir.\"}],\"revealedOutcome\":{\"tr\":\"Her iki molekül de 16 değerlik elektronu, 22 toplam elektron ve özdeş doğrusal geometriye sahiptir; dış elektron bulutları neredeyse ayırt edilemezdir.\",\"ar\":\"يمتلك كلا الجزيئين 16 إلكترون تكافؤ، و22 إلكتروناً كلياً، وهندسة خطية متطابقة، مما يجعل السحب الإلكترونية الخارجية متماثلة تماماً.\",\"en\":\"Both molecules share 16 valence electrons, 22 total electrons, and identical linear geometries, creating virtually indistinguishable electron clouds.\"},\"explanation\":{\"tr\":\"Doğru! N2O ve CO2 klasik Langmuir izosterleridir. Aynı elektron sayısı ve uzaysal orbital dağılımı viskozite, kırılma indisi ve dielektrik sabiti gibi fiziksel özellikleri ikiz kardeş yapar.\",\"ar\":\"صحيح! N2O و CO2 إيزوستيران كلاسيكيان وفق لانغموير. تماثل إلكترونات التكافؤ والهندسة الفراغية يولد تطابقاً شبه تام في اللزوجة والكثافة ومعامل الانكسار.\",\"en\":\"Correct! N2O and CO2 are classical Langmuir isosteres. Matching valence electrons (16) and linear geometries generate near-identical fluid viscosities and dielectric properties.\"}}},{\"id\":\"mc-mod3-les1-step-05\",\"stage\":\"interactive_artifact\",\"stageIndex\":5,\"type\":\"structure_identifier\",\"widgetType\":\"StructureIdentifier\",\"title\":{\"tr\":\"İnteraktif Laboratuvar: Biyoizosterik Köprü Tanımlayıcı\",\"ar\":\"مختبر تفاعلي: محدد الجسور البيوإيزوستيرية\",\"en\":\"Interactive Lab: Bioisosteric Pharmacophore Identifier\"},\"prompt\":{\"tr\":\"Difenhidramin antihistaminik molekülünü inceleyin. İki aromatik halka ile bazik amin arasındaki klasik bivalan (iki değerlikli) biyoizosterik köprü oksijen atomunu (-O-) seçerek doğrulayın.\",\"ar\":\"تأمل جزيء مضاد الهيستامين diphenhydramine. حدد ذرة أكسجين الجسر البيوإيزوستيري ثنائي التكافؤ (-O-) الواقعة بين الحلقتين والأمين القاعدي.\",\"en\":\"Inspect the antihistamine diphenhydramine. Locate and select the classical bivalent bioisosteric bridge oxygen atom (-O-) positioned between the aromatic rings and basic amine.\"},\"predictThenReveal\":false,\"config\":{\"title\":\"Difenhidramin Bivalan İzosterik Köprüsü\",\"prompt\":\"Moleküldeki bivalan (-O-) biyoizosterik köprü atomunu seçin.\",\"moleculeName\":\"Difenhidramin (Diphenhydramine)\",\"smiles\":\"O(CCN(C)C)C(c1ccccc1)c2ccccc2\",\"atoms\":[{\"id\":\"atom_O\",\"label\":\"-O- (Bivalan Eter Köprüsü)\",\"x\":200,\"y\":120,\"isTarget\":true,\"hintName\":\"Eter Oksijeni\",\"distractorRationale\":\"Doğru bivalan biyoizosterik köprü! -CH2-, -NH- veya -S- ile değiştirilebilir.\"},{\"id\":\"atom_CH\",\"label\":\"CH (Metin Karbonu)\",\"x\":140,\"y\":120,\"isTarget\":false,\"hintName\":\"Santral Karbon\",\"distractorRationale\":\"Bu atom iki fenil halkasını bağlayan santral kiral metin karbonudur, izosterik köprü değildir.\"},{\"id\":\"atom_N\",\"label\":\"N (Tersiyer Amin Azotu)\",\"x\":320,\"y\":120,\"isTarget\":false,\"hintName\":\"Bazik Amin Azotu\",\"distractorRationale\":\"Tersiyer amin azotu katyonik farmakofordur, bivalan omurga köprüsü değildir.\"},{\"id\":\"atom_Ph1\",\"label\":\"Ph1 (Aromatik Halka 1)\",\"x\":80,\"y\":70,\"isTarget\":false,\"hintName\":\"Fenil Halkası 1\",\"distractorRationale\":\"Fenil halkası monovalan aril grubudur.\"},{\"id\":\"atom_Ph2\",\"label\":\"Ph2 (Aromatik Halka 2)\",\"x\":80,\"y\":170,\"isTarget\":false,\"hintName\":\"Fenil Halkası 2\",\"distractorRationale\":\"Fenil halkası monovalan aril grubudur.\"}],\"bonds\":[{\"from\":\"atom_Ph1\",\"to\":\"atom_CH\",\"order\":\"single\"},{\"from\":\"atom_Ph2\",\"to\":\"atom_CH\",\"order\":\"single\"},{\"from\":\"atom_CH\",\"to\":\"atom_O\",\"order\":\"single\"},{\"from\":\"atom_O\",\"to\":\"atom_N\",\"order\":\"single\"}],\"targetDescription\":\"İki aril halkası ile amin zincirini bağlayan bivalan eter oksijeni (-O-)\",\"explanation\":\"Bivalan köprü oksijeni (-O-), Grimm hidrit serisinde -NH-, -CH2- ve -S- ile tam izosterdir; bu köprünün değişimi etanolamin, etilendiamin ve propilamin antihistaminik sınıflarını türetir.\",\"source\":{\"file\":\"Biyoizosterizm.pdf\",\"page\":13}},\"technicalTerms\":[{\"term\":\"bivalan izoster\",\"arContext\":\"إيزوستير ثنائي التكافؤ (bivalent isostere)\"},{\"term\":\"antihistaminik farmakofor\",\"arContext\":\"فارماكوفور مضادات الهيستامين\"}],\"hints\":[{\"tr\":\"Santral CH karbonu ile dimetilaminoetil zinciri arasındaki köprü atomunu arayın.\",\"ar\":\"ابحث عن ذرة الجسر الرابطة بين كربون CH وسلسلة ثنائي ميثيل أمينو إيثيل.\",\"en\":\"Look for the bridging atom connecting the central CH carbon to the dimethylaminoethyl chain.\"},{\"tr\":\"Difenhidramin bir aminoalkil eterdir; köprü atomu oksijendir (-O-).\",\"ar\":\"ديفينهيدرامين هو إيثر أمينو ألكيل؛ وذرة الجسر هي الأكسجين (-O-).\",\"en\":\"Diphenhydramine is an aminoalkyl ether; its core connecting bridge atom is oxygen (-O-).\"},{\"tr\":\"-O- atomunu seçin. Bu köprü -NH- (pirilamin) veya -CH2- (klorfeniramin) ile biyoizosteriktir.\",\"ar\":\"اختر ذرة الأكسجين (-O-). هذا الجسر متكافئ حيوياً مع -NH- ومع -CH2-.\",\"en\":\"Select the -O- atom. This bridge is classically bioisosteric with -NH- (pyrilamine) and -CH2- (chlorpheniramine).\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":13}],\"widget\":{\"type\":\"StructureIdentifier\",\"config\":{\"title\":\"Difenhidramin Bivalan İzosterik Köprüsü\",\"prompt\":\"Moleküldeki bivalan (-O-) biyoizosterik köprü atomunu seçin.\",\"moleculeName\":\"Difenhidramin (Diphenhydramine)\",\"smiles\":\"O(CCN(C)C)C(c1ccccc1)c2ccccc2\",\"atoms\":[{\"id\":\"atom_O\",\"label\":\"-O- (Bivalan Eter Köprüsü)\",\"x\":200,\"y\":120,\"isTarget\":true,\"hintName\":\"Eter Oksijeni\",\"distractorRationale\":\"Doğru bivalan biyoizosterik köprü! -CH2-, -NH- veya -S- ile değiştirilebilir.\"},{\"id\":\"atom_CH\",\"label\":\"CH (Metin Karbonu)\",\"x\":140,\"y\":120,\"isTarget\":false,\"hintName\":\"Santral Karbon\",\"distractorRationale\":\"Bu atom iki fenil halkasını bağlayan santral kiral metin karbonudur, izosterik köprü değildir.\"},{\"id\":\"atom_N\",\"label\":\"N (Tersiyer Amin Azotu)\",\"x\":320,\"y\":120,\"isTarget\":false,\"hintName\":\"Bazik Amin Azotu\",\"distractorRationale\":\"Tersiyer amin azotu katyonik farmakofordur, bivalan omurga köprüsü değildir.\"},{\"id\":\"atom_Ph1\",\"label\":\"Ph1 (Aromatik Halka 1)\",\"x\":80,\"y\":70,\"isTarget\":false,\"hintName\":\"Fenil Halkası 1\",\"distractorRationale\":\"Fenil halkası monovalan aril grubudur.\"},{\"id\":\"atom_Ph2\",\"label\":\"Ph2 (Aromatik Halka 2)\",\"x\":80,\"y\":170,\"isTarget\":false,\"hintName\":\"Fenil Halkası 2\",\"distractorRationale\":\"Fenil halkası monovalan aril grubudur.\"}],\"bonds\":[{\"from\":\"atom_Ph1\",\"to\":\"atom_CH\",\"order\":\"single\"},{\"from\":\"atom_Ph2\",\"to\":\"atom_CH\",\"order\":\"single\"},{\"from\":\"atom_CH\",\"to\":\"atom_O\",\"order\":\"single\"},{\"from\":\"atom_O\",\"to\":\"atom_N\",\"order\":\"single\"}],\"targetDescription\":\"İki aril halkası ile amin zincirini bağlayan bivalan eter oksijeni (-O-)\",\"explanation\":\"Bivalan köprü oksijeni (-O-), Grimm hidrit serisinde -NH-, -CH2- ve -S- ile tam izosterdir; bu köprünün değişimi etanolamin, etilendiamin ve propilamin antihistaminik sınıflarını türetir.\",\"source\":{\"file\":\"Biyoizosterizm.pdf\",\"page\":13}}}},{\"id\":\"mc-mod3-les1-step-06\",\"stage\":\"guided_discovery\",\"stageIndex\":6,\"type\":\"guided_discovery\",\"title\":{\"tr\":\"Rehberli Keşif: Hansberg Kuralı ve Tiyofen-Benzen Eşdeğerliği\",\"ar\":\"استكشاف موجه: قاعدة هانسبرغ وتكافؤ الثيوفين والبنزين\",\"en\":\"Guided Discovery: The Hansberg Rule & Ring Equivalence\"},\"prompt\":{\"tr\":\"Benzen halkasındaki iki karbonlu -CH=CH- grubu çıkarılıp yerine tek bir kükürt atomu (-S-) takıldığında tiyofen halkası oluşur. Bu değişim aromatikliği ve reseptör uyumunu nasıl korur?\",\"ar\":\"عند استبدال مجموعة -CH=CH- ثنائية الكربون في البنزين بذرة كبريت واحدة (-S-)، يتكون الثيوفين. كيف يحافظ هذا التبديل على العطرية والتطابق مع المستقبل؟\",\"en\":\"Replacing a two-carbon -CH=CH- segment of benzene with a single divalent sulfur atom (-S-) yields thiophene. How does this maintain aromaticity and receptor fit?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-6a\",\"text\":{\"tr\":\"Kükürt atomu 2 değerlik elektronunu ve d-orbitallerini aromatik pi-bulutuna katarak 6 pi elektronlu Hückel aromatik rezonansını ve benzer halka çevresini korur.\",\"ar\":\"تشارك ذرة الكبريت بزوج إلكتروني ومدارات d في سحابة باي، محققة رنين هوكل العطري بـ 6 إلكترونات ومحيطاً جزيئياً مكافئاً.\",\"en\":\"Sulfur donates 2 valence electrons and utilizes d-orbitals to sustain a 6 pi-electron Hückel aromatic resonance with similar steric perimeter.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz keşif! Hansberg kuralı gereğince -CH=CH- (iki sp2 karbonu, 2 pi elektronu) ile -S- (kükürtün serbest çifti, 2 elektron) elektronik ve uzaysal olarak denktir. Tiyofen benzenin kusursuz halka izosteridir.\",\"ar\":\"اكتشاف متقن! وفق قاعدة هانسبرغ، يتطابق -CH=CH- مع -S- إلكترونياً وفراغياً؛ مما يجعل الثيوفين إيزوستيراً حلقياً نموذجياً للبنزين.\",\"en\":\"Superb discovery! By the Hansberg rule, -CH=CH- (2 pi electrons) and divalent -S- (lone pair donation) are isoelectronic ring equivalents, maintaining a 6 pi aromatic sextet.\"}},{\"id\":\"opt-6b\",\"text\":{\"tr\":\"Kükürt atomu benzeni anında parçalayarak düz zincirli bir alkene çevirir.\",\"ar\":\"تحطم ذرة الكبريت حلقة البنزين فوراً محولة إياها إلى ألكين خطي مفتوح.\",\"en\":\"The sulfur atom instantly disrupts the ring into an open-chain aliphatic alkene.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Halka parçalanma yanılgısı: Tiyofen son derece kararlı 5-üyeli aromatik bir halkadır; halka açılması olmaz.\",\"ar\":\"خطأ انكسار الحلقة: الثيوفين حلقة خماسية عطرية شديدة الثبات ولا تتحلل لسلسلة مفتوحة.\",\"en\":\"Ring opening misconception: Thiophene is an exceptionally stable 5-membered aromatic heteroaryl ring, not an acyclic fragment.\"}},{\"id\":\"opt-6c\",\"text\":{\"tr\":\"Tiyofen aromatik değildir; tamamen apolar bir sikloalkandır.\",\"ar\":\"الثيوفين مركب غير عطري، بل هو سيكلوألكان لاقطبي بالكامل.\",\"en\":\"Thiophene lacks aromaticity; it is purely a saturated nonpolar cycloalkane.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Aromatiklik yanılgısı: Tiyofen kükürtün ortaklanmamış elektron çifti sayesinde [4n+2] pi elektron kuralına tam uyan aromatik bir heteroarildir.\",\"ar\":\"خطأ اللاعطرية: الثيوفين مركب عطري بامتياز يحقق قاعدة هوكل [4n+2] عبر مساهمة زوج إلكترونات الكبريت.\",\"en\":\"Non-aromatic misconception: Thiophene satisfies Hückel's [4n+2] rule through sulfur lone-pair delocalization, exhibiting strong aromatic resonance.\"}}]},\"technicalTerms\":[{\"term\":\"Hansberg kuralı\",\"arContext\":\"قاعدة هانسبرغ (Hansberg rule)\"},{\"term\":\"halka ekivalanı\",\"arContext\":\"المكافئ الحلقي (ring equivalent)\"}],\"hints\":[{\"tr\":\"Benzen 6 pi elektronuna sahiptir. Tiyofende 4 karbon (4 pi) + kükürtün elektron çifti (2e) kaç eder?\",\"ar\":\"يمتلك البنزين 6 إلكترونات باي. في الثيوفين: 4 إلكترونات من الكربون + زوج إلكتروني من الكبريت = ؟\",\"en\":\"Benzene has 6 pi electrons. In thiophene: 4 pi electrons from carbons + 2 from sulfur = ?\"},{\"tr\":\"Hückel kuralını hatırlayın: 4n + 2 = 6 pi elektronu. Kükürtün serbest elektron çifti pi sistemine delokalize olur.\",\"ar\":\"تذكر قاعدة هوكل: 4n + 2 = 6 إلكترونات باي. يتشارك زوج الكبريت في الرنين الحلقي.\",\"en\":\"Recall Hückel's rule: 4n + 2 = 6 pi electrons. Sulfur's lone pair delocalizes into the aromatic ring.\"},{\"tr\":\"Hansberg kuralına göre -CH=CH- ile -S- biyoizosterik halka ekivalanıdır; kükürtün d-orbitalleri rezonansı güçlendirir.\",\"ar\":\"وفق قاعدة هانسبرغ، يعتبر -CH=CH- و -S- مكافئين حلقيين بيوإيزوستيريين؛ وتعزز مدارات d للكبريت الرنين.\",\"en\":\"By the Hansberg rule, -CH=CH- and -S- are classical ring equivalents, preserving aromatic planar binding geometry.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":4}],\"config\":{\"options\":[{\"id\":\"opt-6a\",\"text\":\"Kükürt atomu 2 değerlik elektronunu ve d-orbitallerini aromatik pi-bulutuna katarak 6 pi elektronlu Hückel aromatik rezonansını ve benzer halka çevresini korur.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz keşif! Hansberg kuralı gereğince -CH=CH- (iki sp2 karbonu, 2 pi elektronu) ile -S- (kükürtün serbest çifti, 2 elektron) elektronik ve uzaysal olarak denktir. Tiyofen benzenin kusursuz halka izosteridir.\"},{\"id\":\"opt-6b\",\"text\":\"Kükürt atomu benzeni anında parçalayarak düz zincirli bir alkene çevirir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Halka parçalanma yanılgısı: Tiyofen son derece kararlı 5-üyeli aromatik bir halkadır; halka açılması olmaz.\"},{\"id\":\"opt-6c\",\"text\":\"Tiyofen aromatik değildir; tamamen apolar bir sikloalkandır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Aromatiklik yanılgısı: Tiyofen kükürtün ortaklanmamış elektron çifti sayesinde [4n+2] pi elektron kuralına tam uyan aromatik bir heteroarildir.\"}],\"revealedOutcome\":{\"tr\":\"Kükürt atomu 2 değerlik elektronunu ve d-orbitallerini aromatik pi-bulutuna katarak 6 pi elektronlu Hückel aromatik rezonansını ve benzer halka çevresini korur.\",\"ar\":\"تشارك ذرة الكبريت بزوج إلكتروني ومدارات d في سحابة باي، محققة رنين هوكل العطري بـ 6 إلكترونات ومحيطاً جزيئياً مكافئاً.\",\"en\":\"Sulfur donates 2 valence electrons and utilizes d-orbitals to sustain a 6 pi-electron Hückel aromatic resonance with similar steric perimeter.\"},\"explanation\":{\"tr\":\"Kusursuz keşif! Hansberg kuralı gereğince -CH=CH- (iki sp2 karbonu, 2 pi elektronu) ile -S- (kükürtün serbest çifti, 2 elektron) elektronik ve uzaysal olarak denktir. Tiyofen benzenin kusursuz halka izosteridir.\",\"ar\":\"اكتشاف متقن! وفق قاعدة هانسبرغ، يتطابق -CH=CH- مع -S- إلكترونياً وفراغياً؛ مما يجعل الثيوفين إيزوستيراً حلقياً نموذجياً للبنزين.\",\"en\":\"Superb discovery! By the Hansberg rule, -CH=CH- (2 pi electrons) and divalent -S- (lone pair donation) are isoelectronic ring equivalents, maintaining a 6 pi aromatic sextet.\"}}},{\"id\":\"mc-mod3-les1-step-07\",\"stage\":\"formal_explanation\",\"stageIndex\":7,\"type\":\"formal_explanation\",\"title\":{\"tr\":\"Formal Farmakoloji: H1-Antihistaminik Köprü Evrimi\",\"ar\":\"الدوائيات المنهجية: تطور جسور مضادات الهيستامين H1\",\"en\":\"Formal Pharmacology: H1-Antihistamine Bridge Evolution\"},\"prompt\":{\"tr\":\"Genel H1-antihistaminik yapısında Ar1(Ar2)CH-X-(CH2)2-N(CH3)2 köprüsü bulunur. X atomu -O-'dan (difenhidramin) -CH2-'ye (klorfeniramin) dönüştürüldüğünde klinik sedasyon neden sert biçimde düşer?\",\"ar\":\"في الصيغة العامة لمضادات H1: Ar1(Ar2)CH-X-(CH2)2-N(CH3)2. عندما يستبدل الجسر X من -O- (ديفينهيدرامين) إلى -CH2- (كلورفينيرامين)، لماذا ينخفض النعاس بشدة؟\",\"en\":\"In the general H1-antihistamine pharmacophore Ar1(Ar2)CH-X-(CH2)2-N(CH3)2, when bridge X transitions from -O- (diphenhydramine) to -CH2- (chlorpheniramine), why does clinical sedation drop sharply?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-7a\",\"text\":{\"tr\":\"Eter oksijeninin (-O-) kalkması santral antikolinerjik muskarinik afiniteyi azaltır; propilamin köprüsü (-CH2-) periferik H1 seçiciliğini artırarak MSS sedasyonunu düşürür.\",\"ar\":\"يزيل نزع الأكسجين الألفة للمستقبلات المسكارينية المركزية؛ ويعزز جسر البروبيل أمين (-CH2-) الانتقائية لمستقبل H1 المحيطي مخفضاً النعاس.\",\"en\":\"Replacing the ether oxygen (-O-) diminishes central muscarinic anticholinergic affinity; the propylamine chain (-CH2-) enhances peripheral H1 selectivity, reducing sedation.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! X = -O- (etanolaminler) güçlü antikolinerjik etkiyle derin sedasyon yapar (Benadryl). X = -CH2- (alkilaminler/propilaminler) ise muskarinik afiniteyi düşürür, H1 potansiyelini korur ve sedasyonu minimize eder.\",\"ar\":\"صحيح! يمنح جسر -O- تأثيراً مسكارينياً منوماً قوياً؛ بينما يلغي جسر -CH2- التأثير المسكاريني محافظاً على قوة H1 بانخفاض ملموس في النعاس.\",\"en\":\"Correct! The ether oxygen (-O-) mimics acetylcholine's ester oxygen, driving central M1 sedation (diphenhydramine); the -CH2- propylamine link strips muscarinic affinity while retaining potent H1 blockade.\"}},{\"id\":\"opt-7b\",\"text\":{\"tr\":\"-CH2- köprüsü kan-beyin bariyerini aşamayacak kadar devasa bir kovalent polimere dönüşür.\",\"ar\":\"يتحول جسر -CH2- إلى بوليمر تساهمي ضخم يعجز تماماً عن عبور الحاجز الدماغي الدموي.\",\"en\":\"The -CH2- bridge polymerizes into a massive macromolecule completely barred from crossing the BBB.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Polimerleşme yanılgısı: Tek bir metilen grubu polimerleşmez; molekül küçük, lipofilik bir propilamindir.\",\"ar\":\"خطأ البلمرة: ذرة الميثيلين المفردة لا تتبلمر؛ الجزيء مركب صغير محب للدهن يخترق الأغشية بكفاءة.\",\"en\":\"Polymerization misconception: An aliphatic methylene unit does not self-polymerize; chlorpheniramine remains a small, highly diffusable small molecule.\"}},{\"id\":\"opt-7c\",\"text\":{\"tr\":\"Klorfeniramin antihistaminik etkisini tamamen kaybederek bir antibiyotiğe dönüşür.\",\"ar\":\"يفقد كلورفينيرامين تأثيره المضاد للهيستامين بالكامل ويتحول إلى مضاد حيوي.\",\"en\":\"Chlorpheniramine completely loses antihistaminic properties and turns into an antibiotic.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Aktivite kaybı yanılgısı: Klorfeniramin tarihin en güçlü klasik H1-antihistaminiklerinden biridir; etki kaybolmaz, yan etki profili düzelir.\",\"ar\":\"خطأ فقدان التأثير: كلورفينيرامين من أقوى مضادات الهيستامين تاريخياً؛ تحسن انتقائيته يقلل الآثار الجانبية فقط.\",\"en\":\"Loss of activity misconception: Chlorpheniramine is among the most potent first-generation H1 antagonists known; its selectivity profile simply sharpens.\"}}]},\"technicalTerms\":[{\"term\":\"etanolamin antihistaminik\",\"arContext\":\"مضادات الهيستامين الإيثانولامينية\"},{\"term\":\"propilamin antihistaminik\",\"arContext\":\"مضادات الهيستامين البروبيل أمينية\"}],\"hints\":[{\"tr\":\"Difenhidraminin uyku yapıcı etkisi H1 blokajının yanı sıra muskarinik M1 reseptörlerini de güçlü bloke etmesinden kaynaklanır.\",\"ar\":\"ينجم نعاس ديفينهيدرامين عن إحصار مستقبلات المسكارين M1 بالإضافة إلى إحصار H1.\",\"en\":\"Diphenhydramine's drowsiness stems from off-target central muscarinic M1 blockade alongside H1 antagonism.\"},{\"tr\":\"Köprüdeki oksijen (-O-) asetilkolin ester oksijenini taklit eder; -CH2- ise bu antikolinerjik taklidi bozar.\",\"ar\":\"يحاكي أكسجين الإيثر (-O-) أكسجين الأستيل كولين، بينما يكسر جسر -CH2- هذا التشابه المسكاريني.\",\"en\":\"The ether oxygen (-O-) mimics the ester oxygen of acetylcholine; replacing it with -CH2- abrogates muscarinic cross-reactivity.\"},{\"tr\":\"Eterden (-O-) alkile (-CH2-) geçiş muskarinik yan etkiyi ve sedasyonu azaltırken yüksek H1 antihistaminik gücü korur.\",\"ar\":\"يحافظ الانتقال من الإيثر (-O-) إلى الألكيل (-CH2-) على فاعلية H1 مع خفض الآثار الجانبية المسكارينية والنعاس.\",\"en\":\"Switching from ether (-O-) to alkyl (-CH2-) preserves potent H1 blockade while stripping anticholinergic sedative liability.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":13}],\"config\":{\"options\":[{\"id\":\"opt-7a\",\"text\":\"Eter oksijeninin (-O-) kalkması santral antikolinerjik muskarinik afiniteyi azaltır; propilamin köprüsü (-CH2-) periferik H1 seçiciliğini artırarak MSS sedasyonunu düşürür.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! X = -O- (etanolaminler) güçlü antikolinerjik etkiyle derin sedasyon yapar (Benadryl). X = -CH2- (alkilaminler/propilaminler) ise muskarinik afiniteyi düşürür, H1 potansiyelini korur ve sedasyonu minimize eder.\"},{\"id\":\"opt-7b\",\"text\":\"-CH2- köprüsü kan-beyin bariyerini aşamayacak kadar devasa bir kovalent polimere dönüşür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Polimerleşme yanılgısı: Tek bir metilen grubu polimerleşmez; molekül küçük, lipofilik bir propilamindir.\"},{\"id\":\"opt-7c\",\"text\":\"Klorfeniramin antihistaminik etkisini tamamen kaybederek bir antibiyotiğe dönüşür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Aktivite kaybı yanılgısı: Klorfeniramin tarihin en güçlü klasik H1-antihistaminiklerinden biridir; etki kaybolmaz, yan etki profili düzelir.\"}],\"revealedOutcome\":{\"tr\":\"Eter oksijeninin (-O-) kalkması santral antikolinerjik muskarinik afiniteyi azaltır; propilamin köprüsü (-CH2-) periferik H1 seçiciliğini artırarak MSS sedasyonunu düşürür.\",\"ar\":\"يزيل نزع الأكسجين الألفة للمستقبلات المسكارينية المركزية؛ ويعزز جسر البروبيل أمين (-CH2-) الانتقائية لمستقبل H1 المحيطي مخفضاً النعاس.\",\"en\":\"Replacing the ether oxygen (-O-) diminishes central muscarinic anticholinergic affinity; the propylamine chain (-CH2-) enhances peripheral H1 selectivity, reducing sedation.\"},\"explanation\":{\"tr\":\"Doğru! X = -O- (etanolaminler) güçlü antikolinerjik etkiyle derin sedasyon yapar (Benadryl). X = -CH2- (alkilaminler/propilaminler) ise muskarinik afiniteyi düşürür, H1 potansiyelini korur ve sedasyonu minimize eder.\",\"ar\":\"صحيح! يمنح جسر -O- تأثيراً مسكارينياً منوماً قوياً؛ بينما يلغي جسر -CH2- التأثير المسكاريني محافظاً على قوة H1 بانخفاض ملموس في النعاس.\",\"en\":\"Correct! The ether oxygen (-O-) mimics acetylcholine's ester oxygen, driving central M1 sedation (diphenhydramine); the -CH2- propylamine link strips muscarinic affinity while retaining potent H1 blockade.\"}}},{\"id\":\"mc-mod3-les1-step-08\",\"stage\":\"concept_check\",\"stageIndex\":8,\"type\":\"concept_check\",\"title\":{\"tr\":\"Kavram Kontrolü: 2-Tiyenilalanin ve Biyoizosterik Antagonizma\",\"ar\":\"فحص المفاهيم: 2-ثينيل ألانين والمناهضة الاستقلابية\",\"en\":\"Concept Check: 2-Thienylalanine & Bioisosteric Antagonism\"},\"prompt\":{\"tr\":\"Doğal amino asit fenilalanindeki fenil halkası yerine tiyofen halkası konulursa (2-tiyenilalanin) biyolojik sonuç ne olur? Biyoizosterler daima ana molekül gibi agonist mi davranır?\",\"ar\":\"إذا استبدلت حلقة الفينيل في الحمض الأميني الطبيعي فينيل ألانين بحلقة ثيوفين (2-thienylalanine)، فما النتيجة البيولوجية؟ هل تعمل المتشابهات كمنبهات دوماً؟\",\"en\":\"What occurs biologically when the phenyl ring of natural phenylalanine is replaced with thiophene (2-thienylalanine)? Do bioisosteres always act as agonists like the parent molecule?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-8a\",\"text\":{\"tr\":\"Hayır; 2-tiyenilalanin fenilalanin t-RNA sentetaz enzimini yarışmalı bloke eden öldürücü bir antimetabolit (antagonist) haline gelir.\",\"ar\":\"كلا؛ يتحول 2-thienylalanine إلى مضاد استقلاب (antimetabolite) قاتل يثبط أنزيم فينيل ألانين t-RNA sentetaz تنافسياً.\",\"en\":\"No; 2-thienylalanine becomes a lethal antimetabolite (antagonist) competitively blocking phenylalanine t-RNA synthetase.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel kavram kavrayışı! Biyoizosterizm her zaman benzer etki (agonist) doğurmaz. Reseptör veya enzime bağlanıp katalitik fonksiyonu bozarak güçlü antimetabolit/antagonist etki yaratabilir (Slide 14).\",\"ar\":\"فهم استثنائي! لا تنتج البيوإيزوستيرية منبهاً دوماً؛ بل ترتبط بالموقع الفعال معطلة الوظيفة الحيوية كمضاد استقلاب حاسم.\",\"en\":\"Outstanding conceptual mastery! Bioisosterism frequently yields competitive antagonists or antimetabolites that dock into catalytic pockets but block turnover.\"}},{\"id\":\"opt-8b\",\"text\":{\"tr\":\"Evet; biyoizosterizm tanımı gereği oluşan tüm türevler ana molekülle birebir aynı agonistik proteini sentezletir.\",\"ar\":\"نعم؛ بحكم تعريف البيوإيزوستيرية يجب أن تنتج كافة المشتقات نفس البروتين الطبيعي بنفس الفعالية.\",\"en\":\"Yes; by definition, all bioisosteres must yield identical agonistic physiological protein synthesis.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Zorunlu agonist yanılgısı: En yaygın öğrenci yanılgısı biyoizosterlerin mutlaka agonist olacağıdır. Biyoizosterik antimetabolitler (5-FU, 2-tiyenilalanin, sülfanilamid) enzim blokajı yapar.\",\"ar\":\"خطأ التنبيه الإجباري: أشهر الأخطاء الشائعة؛ فمضادات الاستقلاب (5-FU وثينيل ألانين) إيزوستيرات حيوية تعطل الأنزيمات.\",\"en\":\"Obligate agonist misconception: Bioisosteric replacement frequently generates potent antimetabolites (5-FU, sulfonamides, 2-thienylalanine) that abort enzymatic pathways.\"}},{\"id\":\"opt-8c\",\"text\":{\"tr\":\"Tiyofen halkası insan vücudunda derhal sülfürik aside parçalanarak pH'ı sıfıra indirir.\",\"ar\":\"تتحلل حلقة الثيوفين فوراً إلى حمض الكبريتيك في الجسم البشري خافضة pH للصفر.\",\"en\":\"The thiophene ring hydrolyzes instantly into sulfuric acid, dropping physiological pH to zero.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kimyasal parçalanma yanılgısı: Tiyofen fizyolojik koşullarda son derece dayanıklı bir aromatik heterohalkadır; sülfürik aside hidroliz olmaz.\",\"ar\":\"خطأ التحلل الكيميائي: الثيوفين حلقة عطرية منيعة في الشروط الفيزيولوجية ولا تتحلل إطلاقاً لحمض كبريت.\",\"en\":\"Chemical hydrolysis misconception: Thiophene is an aromatic heterocycle chemically robust to spontaneous hydrolysis under biological conditions.\"}}]},\"technicalTerms\":[{\"term\":\"antimetabolit\",\"arContext\":\"مضاد الاستقلاب (antimetabolite)\"},{\"term\":\"biyoizosterik antagonizma\",\"arContext\":\"المناهضة البيوإيزوستيرية\"}],\"hints\":[{\"tr\":\"Urasil -> 5-Fluorourasil ve PABA -> Sülfanilamid örneklerini hatırlayın.\",\"ar\":\"تذكر أمثلة اليوراسيل -> 5-فلورويوراسيل و PABA -> سلفانيلاميد.\",\"en\":\"Recall how Uracil -> 5-FU and PABA -> Sulfanilamide function in cells.\"},{\"tr\":\"Biyoizoster enzimin aktif bölgesine bağlanabilir ancak doğal enzimatik reaksiyonu yürütemez.\",\"ar\":\"يرتبط المتشابه بالموقع الفعال للأنزيم لكنه يعجز عن استكمال التفاعل الحيوي الطبيعي.\",\"en\":\"The bioisostere docks into the active pocket with high affinity, but prevents catalytic turnover.\"},{\"tr\":\"2-tiyenilalanin fenilalanin sentetazı kilitler; protein sentezini durduran klasik bir biyoizosterik antimetabolittir.\",\"ar\":\"يعطل 2-thienylalanine أنزيم بناء فينيل ألانين متصرفاً كمضاد استقلاب قاتل للخلايا السرطانية.\",\"en\":\"2-thienylalanine competitively poisons phenylalanine-tRNA synthetase, serving as a classical bioisosteric antimetabolite.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":14}],\"config\":{\"options\":[{\"id\":\"opt-8a\",\"text\":\"Hayır; 2-tiyenilalanin fenilalanin t-RNA sentetaz enzimini yarışmalı bloke eden öldürücü bir antimetabolit (antagonist) haline gelir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel kavram kavrayışı! Biyoizosterizm her zaman benzer etki (agonist) doğurmaz. Reseptör veya enzime bağlanıp katalitik fonksiyonu bozarak güçlü antimetabolit/antagonist etki yaratabilir (Slide 14).\"},{\"id\":\"opt-8b\",\"text\":\"Evet; biyoizosterizm tanımı gereği oluşan tüm türevler ana molekülle birebir aynı agonistik proteini sentezletir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Zorunlu agonist yanılgısı: En yaygın öğrenci yanılgısı biyoizosterlerin mutlaka agonist olacağıdır. Biyoizosterik antimetabolitler (5-FU, 2-tiyenilalanin, sülfanilamid) enzim blokajı yapar.\"},{\"id\":\"opt-8c\",\"text\":\"Tiyofen halkası insan vücudunda derhal sülfürik aside parçalanarak pH'ı sıfıra indirir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kimyasal parçalanma yanılgısı: Tiyofen fizyolojik koşullarda son derece dayanıklı bir aromatik heterohalkadır; sülfürik aside hidroliz olmaz.\"}],\"revealedOutcome\":{\"tr\":\"Hayır; 2-tiyenilalanin fenilalanin t-RNA sentetaz enzimini yarışmalı bloke eden öldürücü bir antimetabolit (antagonist) haline gelir.\",\"ar\":\"كلا؛ يتحول 2-thienylalanine إلى مضاد استقلاب (antimetabolite) قاتل يثبط أنزيم فينيل ألانين t-RNA sentetaz تنافسياً.\",\"en\":\"No; 2-thienylalanine becomes a lethal antimetabolite (antagonist) competitively blocking phenylalanine t-RNA synthetase.\"},\"explanation\":{\"tr\":\"Mükemmel kavram kavrayışı! Biyoizosterizm her zaman benzer etki (agonist) doğurmaz. Reseptör veya enzime bağlanıp katalitik fonksiyonu bozarak güçlü antimetabolit/antagonist etki yaratabilir (Slide 14).\",\"ar\":\"فهم استثنائي! لا تنتج البيوإيزوستيرية منبهاً دوماً؛ بل ترتبط بالموقع الفعال معطلة الوظيفة الحيوية كمضاد استقلاب حاسم.\",\"en\":\"Outstanding conceptual mastery! Bioisosterism frequently yields competitive antagonists or antimetabolites that dock into catalytic pockets but block turnover.\"}}},{\"id\":\"mc-mod3-les1-step-09\",\"stage\":\"application\",\"stageIndex\":9,\"type\":\"clinical_vignette\",\"title\":{\"tr\":\"Klinik Vaka: Klorpromazinden İmipramine Büyük Dönüşüm\",\"ar\":\"حالة سريرية: التحول الدوائي من كلوربرومازين إلى إيميبرامين\",\"en\":\"Clinical Vignette: The Chlorpromazine to Imipramine Morph\"},\"prompt\":{\"tr\":\"Antipsikotik klorpromazin (fenotiyazin) -S- köprüsü taşır. Bu köprü iki karbonlu etilenle (-CH2-CH2-) değiştirildiğinde (imipramin) klinik etki nasıl dopamin antipsikotiğinden trisiklik antidepresana döner?\",\"ar\":\"يمتلك مضاد الذهان chlorpromazine جسر -S-. عند استبدال هذا الجسر بإيثيلين ثنائي الكربون (-CH2-CH2-) في imipramine، كيف ينقلب التأثير من مضاد ذهان إلى مضاد اكتئاب؟\",\"en\":\"Antipsychotic chlorpromazine features an -S- bridge. When replaced by a divalent ethylene bridge (-CH2-CH2-) in imipramine, how does clinical activity flip from dopamine antipsychotic to tricyclic antidepressant?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-9a\",\"text\":{\"tr\":\"İki karbonlu köprü trisiklik halkanın dihedral bükülme açısını düzlemsellikten çıkarıp katlar; D2 reseptör uyumu kaybolurken NET ve SERT taşıyıcılarına afinite fırlar.\",\"ar\":\"يغير جسر الكربونين زاوية الانثناء الفراغية للحلقات الثلاث كاسراً استواءها، فتزول ألفة D2 وتكتسب ألفة شديدة لناقلي NET و SERT.\",\"en\":\"The ethylene bridge distorts the tricyclic dihedral angle away from planarity; dopamine D2 affinity is lost while NET and SERT reuptake inhibition surges.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kesinlikle doğru! Fenotiyazindeki kükürt (-S-) halkaları daha düzlemsel tutarak dopamin D2 reseptörüne kilitler. İmipramindeki -CH2CH2- köprüsü ise halkayı dik bir açıyla büker; nöroleptik etki biter, trisiklik antidepresan etki başlar (Slide 15).\",\"ar\":\"صحيح تماماً! يحافظ الكبريت على شبه استواء الحلقات ملائماً لمستقبل D2؛ بينما يثني جسر -CH2CH2- الحلقات بزاوية حادة لتلائم نواقل السيروتونين والنورأدرينالين.\",\"en\":\"Spot on! The -S- bridge enforces planarity required for dopamine D2 antagonism; swapping it for -CH2-CH2- buckles the tricyclic core into a folded butterfly geometry that selectively binds NET and SERT.\"}},{\"id\":\"opt-9b\",\"text\":{\"tr\":\"İmipramin vücutta tamamen eriyerek doğrudan serotonine dönüşür.\",\"ar\":\"يتحلل إيميبرامين في الجسم بشكل كامل متحولاً مباشرة إلى جزيئات سيروتونين.\",\"en\":\"Imipramine completely dissolves in vivo, directly converting into serotonin molecules.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Dönüşüm yanılgısı: İlaç nörotransmitere dönüşmez; nörotransmiter geri alım pompalarını (SERT/NET) allosterik/kompetitif inhibe eder.\",\"ar\":\"خطأ التحلل لناقل: لا يتحول الدواء إلى ناقل عصبي بل يثبط مضخات إعادة قبط السيروتونين والنورأدرينالين.\",\"en\":\"Transmutation misconception: Imipramine does not convert into serotonin; it blocks the reuptake transport machinery.\"}},{\"id\":\"opt-9c\",\"text\":{\"tr\":\"Kükürt atomu olmadan hiçbir ilaç dopamin reseptörüne yaklaşamaz.\",\"ar\":\"يستحيل على أي دواء الاقتراب من مستقبل الدوبامين دون وجود ذرة كبريت.\",\"en\":\"No drug can interact with dopamine receptors without containing an essential sulfur atom.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kükürt zorunluluğu yanılgısı: Haloperidol gibi onlarca güçlü antipsikotikte kükürt atomu bulunmaz; ana faktör 3 boyutlu moleküler geometridir.\",\"ar\":\"خطأ حتمية الكبريت: مضادات ذهان شهيرة كالهالوبيريدول تخلو من الكبريت؛ الفيصل هو الزاوية الفراغية ثلاثية الأبعاد.\",\"en\":\"Sulfur necessity misconception: Potent dopamine antagonists like haloperidol contain no sulfur; the determinant is 3D conformational dihedral geometry.\"}}]},\"technicalTerms\":[{\"term\":\"fenotiyazin çekirdeği\",\"arContext\":\"نواة الفينوثيازين (phenothiazine core)\"},{\"term\":\"dibenzazepin çekirdeği\",\"arContext\":\"نواة الديبنزازيبين (dibenzazepine core)\"}],\"hints\":[{\"tr\":\"Trisiklik çekirdeğin 3 boyutlu bükülme açısını (kelebek kanadı geometrisini) düşünün.\",\"ar\":\"فكر في زاوية انثناء النواة ثلاثية الحلقات (هندسة أجنحة الفراشة).\",\"en\":\"Consider the 3D butterfly dihedral bending angle of the tricyclic ring system.\"},{\"tr\":\"Düzlemsel yapılar dopamin D2 reseptörlerine otururken, bükük yapılar monoamin taşıyıcılarını (SERT/NET) bloke eder.\",\"ar\":\"تلائم البنى شبه المستوية مستقبلات D2، بينما تلائم البنى المنثنية نواقل المونوأمين (SERT/NET).\",\"en\":\"Nearly planar rings satisfy dopamine D2 receptors; sharply folded butterfly rings fit monoamine transporters.\"},{\"tr\":\"-S- yerine -CH2-CH2- konulması molekülün dihedral katlanma açısını artırarak antipsikotikten antidepresana farmakolojik profil kayması yaratır.\",\"ar\":\"يزيد استبدال -S- بـ -CH2-CH2- زاوية الانثناء محولاً الفعالية من مضاد ذهان إلى مضاد اكتئاب ثلاثي الحلقات.\",\"en\":\"Swapping -S- for -CH2-CH2- alters the central dihedral crease, flipping pharmacology from neuroleptic to tricyclic antidepressant.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":15}],\"config\":{\"options\":[{\"id\":\"opt-9a\",\"text\":\"İki karbonlu köprü trisiklik halkanın dihedral bükülme açısını düzlemsellikten çıkarıp katlar; D2 reseptör uyumu kaybolurken NET ve SERT taşıyıcılarına afinite fırlar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kesinlikle doğru! Fenotiyazindeki kükürt (-S-) halkaları daha düzlemsel tutarak dopamin D2 reseptörüne kilitler. İmipramindeki -CH2CH2- köprüsü ise halkayı dik bir açıyla büker; nöroleptik etki biter, trisiklik antidepresan etki başlar (Slide 15).\"},{\"id\":\"opt-9b\",\"text\":\"İmipramin vücutta tamamen eriyerek doğrudan serotonine dönüşür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Dönüşüm yanılgısı: İlaç nörotransmitere dönüşmez; nörotransmiter geri alım pompalarını (SERT/NET) allosterik/kompetitif inhibe eder.\"},{\"id\":\"opt-9c\",\"text\":\"Kükürt atomu olmadan hiçbir ilaç dopamin reseptörüne yaklaşamaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kükürt zorunluluğu yanılgısı: Haloperidol gibi onlarca güçlü antipsikotikte kükürt atomu bulunmaz; ana faktör 3 boyutlu moleküler geometridir.\"}],\"revealedOutcome\":{\"tr\":\"İki karbonlu köprü trisiklik halkanın dihedral bükülme açısını düzlemsellikten çıkarıp katlar; D2 reseptör uyumu kaybolurken NET ve SERT taşıyıcılarına afinite fırlar.\",\"ar\":\"يغير جسر الكربونين زاوية الانثناء الفراغية للحلقات الثلاث كاسراً استواءها، فتزول ألفة D2 وتكتسب ألفة شديدة لناقلي NET و SERT.\",\"en\":\"The ethylene bridge distorts the tricyclic dihedral angle away from planarity; dopamine D2 affinity is lost while NET and SERT reuptake inhibition surges.\"},\"explanation\":{\"tr\":\"Kesinlikle doğru! Fenotiyazindeki kükürt (-S-) halkaları daha düzlemsel tutarak dopamin D2 reseptörüne kilitler. İmipramindeki -CH2CH2- köprüsü ise halkayı dik bir açıyla büker; nöroleptik etki biter, trisiklik antidepresan etki başlar (Slide 15).\",\"ar\":\"صحيح تماماً! يحافظ الكبريت على شبه استواء الحلقات ملائماً لمستقبل D2؛ بينما يثني جسر -CH2CH2- الحلقات بزاوية حادة لتلائم نواقل السيروتونين والنورأدرينالين.\",\"en\":\"Spot on! The -S- bridge enforces planarity required for dopamine D2 antagonism; swapping it for -CH2-CH2- buckles the tricyclic core into a folded butterfly geometry that selectively binds NET and SERT.\"}}},{\"id\":\"mc-mod3-les1-step-10\",\"stage\":\"retrieval\",\"stageIndex\":10,\"type\":\"retrieval\",\"title\":{\"tr\":\"Aralıklı Hatırlama: Flor Atomunun Metabolik Kalkanı\",\"ar\":\"استرجاع متباعد: الدرع الاستقلابي لذرة الفلور\",\"en\":\"Spaced Retrieval: Fluorine's Metabolic Shield\"},\"prompt\":{\"tr\":\"İlaç tasarımında aromatik bir halkadaki -H yerine -F atomu takılması (örn. Ezetimib) sitokrom P450 hidroksilasyonunu nasıl engeller? Bağ enerjisi ve atom çapı farkı nedir?\",\"ar\":\"في تصميم الأدوية، كيف يمنع استبدال -H بـ -F على حلقة عطرية (مثل Ezetimibe) أكسدة السيتوكروم P450؟ ما هو فارق طاقة الرابطة ونصف القطر؟\",\"en\":\"In rational drug design, how does replacing an aromatic -H with -F (e.g., Ezetimibe) block CYP450 hydroxylation? What are the relative bond energies and atomic radii?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-10a\",\"text\":{\"tr\":\"C-F bağ enerjisi (116 kcal/mol) C-H'den (98 kcal/mol) çok daha sağlamdır; van der Waals yarıçapı ise (1.47 Å vs 1.20 Å) reseptör uyumunu bozmadan oksidasyonu bloke eder.\",\"ar\":\"طاقة رابطة C-F تبلغ (116 kcal/mol) وهي أقوى بكثير من C-H (98 kcal/mol)؛ ونصف قطرها (1.47 Å مقابل 1.20 Å) يحفظ أبعاد الجيب مانعاً الأكسدة.\",\"en\":\"C-F bond energy (116 kcal/mol) vastly exceeds C-H (98 kcal/mol); its van der Waals radius (1.47 Å vs 1.20 Å) blocks oxidation without steric pocket penalty.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Tam bir farmasötik kimya klasiği! Flor atomu hidrojene sterik olarak en yakın elementtir (1.47 Å vs 1.20 Å), ancak karbonun en güçlü tekli bağını (116 kcal/mol) kurar. CYP enzimleri bu bağı koparıp fenol yapamaz.\",\"ar\":\"حقيقة كلاسيكية! الفلور أقرب العناصر حجماً للهيدروجين (1.47 Å مقابل 1.20 Å)، ويشكل أقوى رابطة أحادية (116 kcal/mol) عاصية على أكسدة السيتوكروم.\",\"en\":\"A medicinal chemistry cornerstone! Fluorine is steric twin to hydrogen (1.47 Å vs 1.20 Å) but forms an indestructible 116 kcal/mol C-F covalent bond immune to CYP insertion.\"}},{\"id\":\"opt-10b\",\"text\":{\"tr\":\"Flor atomu hidrojenin 5 katı büyüklükte olduğu için sitokrom enzimini fiziksel olarak parçalar.\",\"ar\":\"حجم ذرة الفلور 5 أضعاف الهيدروجين مما يؤدي لتمزيق أنزيم السيتوكروم مادياً.\",\"en\":\"Fluorine is 5 times larger than hydrogen, physically destroying cytochrome enzymes upon contact.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Boyut yanılgısı: Flor hidrojenden sadece %20 büyüktür (1.47 Å vs 1.20 Å); enzimi parçalamaz.\",\"ar\":\"خطأ الحجم: الفلور أكبر من الهيدروجين بنسبة 20% فقط؛ ولا يخرب الأنزيم ميكانيكياً.\",\"en\":\"Size misconception: Fluorine is barely 20% larger than hydrogen; it docks without gross steric clashing.\"}},{\"id\":\"opt-10c\",\"text\":{\"tr\":\"C-F bağı C-H bağından çok daha zayıftır (30 kcal/mol); bu yüzden flor hemen kopup çözeltiye geçer.\",\"ar\":\"رابطة C-F أضعف بكثير من C-H (30 kcal/mol)، لذلك ينفصل الفلور فوراً في المحلول.\",\"en\":\"The C-F bond is far weaker than C-H (30 kcal/mol), rapidly cleaving off into bulk solution.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Zayıf bağ yanılgısı: C-F organik kimyadaki en güçlü tekli kovalent bağlardan biridir (116 kcal/mol).\",\"ar\":\"خطأ ضعف الرابطة: رابطة C-F من أقوى الروابط التساهمية الأحادية في الكيمياء العضوية (116 kcal/mol).\",\"en\":\"Weak bond misconception: C-F is one of the strongest single covalent bonds in organic chemistry (116 kcal/mol).\"}}]},\"technicalTerms\":[{\"term\":\"metabolik blokaj\",\"arContext\":\"الحجب الاستقلابي (metabolic blocking)\"},{\"term\":\"van der Waals yarıçapı\",\"arContext\":\"نصف قطر فان دير فالس\"}],\"hints\":[{\"tr\":\"Flor atomunun bağ kuvveti ve van der Waals yarıçapı değerlerini hatırlayın.\",\"ar\":\"تذكر قيم طاقة رابطة الفلور ونصف قطر فان دير فالس مقارنة بالهيدروجين.\",\"en\":\"Recall the bond dissociation energy and van der Waals radius of fluorine.\"},{\"tr\":\"C-F bağı 116 kcal/mol, C-H bağı 98 kcal/mol'dür. Van der Waals yarıçapları 1.47 Å ve 1.20 Å'dur.\",\"ar\":\"رابطة C-F تبلغ 116 kcal/mol مقابل 98 لـ C-H. وأنصاف الأقطار 1.47 Å و 1.20 Å.\",\"en\":\"C-F bond energy is 116 kcal/mol vs C-H 98 kcal/mol. Van der Waals radii are 1.47 Å and 1.20 Å.\"},{\"tr\":\"C-F bağı CYP enzimlerinin oksidatif koparma gücünün çok üzerindedir; sterik hacmi bozmadan ilaca metabolik zırh kazandırır.\",\"ar\":\"تتجاوز قوة C-F قدرة أنزيمات الأكسدة؛ مما يمنح الدواء درعاً استقلابياً دون تشويه الحجم الفراغي.\",\"en\":\"C-F bond strength defies CYP450 radical cleavage while fitting the pocket seamlessly.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":11}],\"config\":{\"options\":[{\"id\":\"opt-10a\",\"text\":\"C-F bağ enerjisi (116 kcal/mol) C-H'den (98 kcal/mol) çok daha sağlamdır; van der Waals yarıçapı ise (1.47 Å vs 1.20 Å) reseptör uyumunu bozmadan oksidasyonu bloke eder.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Tam bir farmasötik kimya klasiği! Flor atomu hidrojene sterik olarak en yakın elementtir (1.47 Å vs 1.20 Å), ancak karbonun en güçlü tekli bağını (116 kcal/mol) kurar. CYP enzimleri bu bağı koparıp fenol yapamaz.\"},{\"id\":\"opt-10b\",\"text\":\"Flor atomu hidrojenin 5 katı büyüklükte olduğu için sitokrom enzimini fiziksel olarak parçalar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Boyut yanılgısı: Flor hidrojenden sadece %20 büyüktür (1.47 Å vs 1.20 Å); enzimi parçalamaz.\"},{\"id\":\"opt-10c\",\"text\":\"C-F bağı C-H bağından çok daha zayıftır (30 kcal/mol); bu yüzden flor hemen kopup çözeltiye geçer.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Zayıf bağ yanılgısı: C-F organik kimyadaki en güçlü tekli kovalent bağlardan biridir (116 kcal/mol).\"}],\"revealedOutcome\":{\"tr\":\"C-F bağ enerjisi (116 kcal/mol) C-H'den (98 kcal/mol) çok daha sağlamdır; van der Waals yarıçapı ise (1.47 Å vs 1.20 Å) reseptör uyumunu bozmadan oksidasyonu bloke eder.\",\"ar\":\"طاقة رابطة C-F تبلغ (116 kcal/mol) وهي أقوى بكثير من C-H (98 kcal/mol)؛ ونصف قطرها (1.47 Å مقابل 1.20 Å) يحفظ أبعاد الجيب مانعاً الأكسدة.\",\"en\":\"C-F bond energy (116 kcal/mol) vastly exceeds C-H (98 kcal/mol); its van der Waals radius (1.47 Å vs 1.20 Å) blocks oxidation without steric pocket penalty.\"},\"explanation\":{\"tr\":\"Tam bir farmasötik kimya klasiği! Flor atomu hidrojene sterik olarak en yakın elementtir (1.47 Å vs 1.20 Å), ancak karbonun en güçlü tekli bağını (116 kcal/mol) kurar. CYP enzimleri bu bağı koparıp fenol yapamaz.\",\"ar\":\"حقيقة كلاسيكية! الفلور أقرب العناصر حجماً للهيدروجين (1.47 Å مقابل 1.20 Å)، ويشكل أقوى رابطة أحادية (116 kcal/mol) عاصية على أكسدة السيتوكروم.\",\"en\":\"A medicinal chemistry cornerstone! Fluorine is steric twin to hydrogen (1.47 Å vs 1.20 Å) but forms an indestructible 116 kcal/mol C-F covalent bond immune to CYP insertion.\"}}},{\"id\":\"mc-mod3-les1-step-11\",\"stage\":\"connection\",\"stageIndex\":11,\"type\":\"connection\",\"title\":{\"tr\":\"Bağlantı: Klasik Kuralların Sınırı ve Tetrazol Devrimi\",\"ar\":\"ربط المفاهيم: حدود القواعد الكلاسيكية وثورة التترازول\",\"en\":\"Cross-Topic Bridge: Limits of Classical Rules & The Tetrazole Leap\"},\"prompt\":{\"tr\":\"Grimm kuralları değerlik elektron eşitliğine dayanır. Ancak 5 üyeli 4 azotlu bir tetrazol halkası karboksilik asidin (-COOH) yerini mükemmel doldurur. Grimm kuralları bu devrimi neden açıklayamaz?\",\"ar\":\"تعتمد قواعد غريم على تكافؤ الإلكترونات. ومع ذلك تحل حلقة التترازول الخماسية ذات النيتروجينات الأربعة محل حمض الكربوكسيل (-COOH) بكفاءة. لماذا تعجز قواعد غريم عن تفسير هذا؟\",\"en\":\"Grimm's law relies on strict valence electron matching. Yet a 5-membered, 4-nitrogen tetrazole ring bioisosterically replaces carboxylic acid (-COOH). Why do classical rules fail to explain this leap?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-11a\",\"text\":{\"tr\":\"Tetrazol halkası klasik atom sayısı ve değerlik kurallarına uymaz; ancak pKa (4.5-4.9), negatif yük delokalizasyonu ve sterik hacim açısından karboksilatı taklit eden 'Non-Klasik' bir biyoizosterdir.\",\"ar\":\"لا يتبع التترازول قواعد عدد الذرات الكلاسيكية؛ لكنه يحاكي الكربوكسيل في pKa (4.5-4.9) وتوزع الشحنة السالبة كـ 'متشابه حيوي غير كلاسيكي'.\",\"en\":\"Tetrazole violates classical atom/valence counts; it mimics carboxylate via pKa (4.5-4.9), planar charge delocalization, and volume as a 'Non-Classical' bioisostere.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika bir köprü! Klasik izosterizm Langmuir ve Grimm kurallarıyla sınırlıdır. Tetrazol, sülfonamid veya siklik yapılar gibi modern ilaç keşif araçları ise 'Non-Klasik Biyoizosterler' sınıfını oluşturur (Gelecek Ders!).\",\"ar\":\"جسر مفاهيمي رائع! تقف القواعد الكلاسيكية عاجزة هنا؛ فالتترازول يمثل ثورة المتشابهات غير الكلاسيكية التي سندرسها في الدرس القادم.\",\"en\":\"Brilliant bridge! Classical rules dictate electron/atom equivalence. Tetrazoles mimic carboxylate through electronic field distribution and acidity, launching Non-Classical Bioisosterism.\"}},{\"id\":\"opt-11b\",\"text\":{\"tr\":\"Tetrazol aslında bir karboksilik asit molekülüdür; azot atomları mikroskopta karbon gibi görünür.\",\"ar\":\"التترازول في الحقيقة حمض كربوكسيلي، وتبدو ذرات النيتروجين كالكربون تماماً تحت المجهر.\",\"en\":\"Tetrazole is literally a carboxylic acid whose nitrogens merely look like carbons under microscopy.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Fiziksel kimlik yanılgısı: Tetrazol tamamen farklı heteroatomlardan oluşur; 4 azot ve 1 karbon taşır.\",\"ar\":\"خطأ الهوية الذرية: التترازول حلقة مغايرة تحتوي 4 ذرات نيتروجين وذرة كربون، ولا تمتلك ذرات أكسجين.\",\"en\":\"Chemical identity misconception: Tetrazole is an entirely different 5-membered heterocyclic system packed with 4 nitrogens.\"}},{\"id\":\"opt-11c\",\"text\":{\"tr\":\"Grimm kuralları sadece inorganik tuzlar için geçerlidir; ilaç kimyasında hiç kullanılmaz.\",\"ar\":\"قواعد غريم تنطبق حصراً على الأملاح غير العضوية ولا علاقة لها بالكيمياء الدوائية.\",\"en\":\"Grimm's laws apply strictly to inorganic mineral salts and have zero relevance to medchem.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kural geçersizliği yanılgısı: Grimm kuralları klasik biyoizosterizmin temel taşıdır (-F, -OH, -NH2, vb.); ancak non-klasik halkaları kapsayamaz.\",\"ar\":\"خطأ نفي القاعدة: قواعد غريم هي حجر الأساس للتبديل الكلاسيكي، لكنها تعجز عن تفسير الأنظمة الحلقية المعقدة.\",\"en\":\"Relevance misconception: Grimm's law is fundamental to classical bioisosterism (-F, -OH, -NH2, -S-), but cannot explain advanced non-classical mimics.\"}}]},\"technicalTerms\":[{\"term\":\"non-klasik biyoizoster\",\"arContext\":\"المتشابه الحيوي غير الكلاسيكي (non-classical bioisostere)\"},{\"term\":\"tetrazol halkası\",\"arContext\":\"حلقة التترازول (tetrazole ring)\"}],\"hints\":[{\"tr\":\"Klasik izosterler atom sayısı ve değerlik elektronları açısından birbirine uyar.\",\"ar\":\"تتطابق الإيزوستيرات الكلاسيكية في عدد الذرات وإلكترونات التكافؤ.\",\"en\":\"Classical isosteres match atom numbers and outer valence electrons.\"},{\"tr\":\"Tetrazolde 5 halka atomu varken, -COOH grubunda 3 atom vardır. Değerlik elektron sayıları eşit değildir.\",\"ar\":\"يمتلك التترازول 5 ذرات حلقية بينما تمتلك -COOH 3 ذرات فقط، ولا تتطابق إلكترونات التكافؤ.\",\"en\":\"Tetrazole contains 5 ring atoms versus 3 in -COOH; valence electrons do not match.\"},{\"tr\":\"Tetrazol klasik kuralları aşan, elektronik yüzey ve pKa uyumu sağlayan modern bir 'Non-Klasik Biyoizoster' örneğidir.\",\"ar\":\"يمثل التترازول نموذجاً للمتشابهات غير الكلاسيكية التي تحاكي السطح الإلكتروني ودرجة الحموضة pKa.\",\"en\":\"Tetrazole is the quintessential Non-Classical Bioisostere, mimicking carboxylate pKa (~4.8) via delocalized aromatic resonance.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":9}],\"config\":{\"options\":[{\"id\":\"opt-11a\",\"text\":\"Tetrazol halkası klasik atom sayısı ve değerlik kurallarına uymaz; ancak pKa (4.5-4.9), negatif yük delokalizasyonu ve sterik hacim açısından karboksilatı taklit eden 'Non-Klasik' bir biyoizosterdir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika bir köprü! Klasik izosterizm Langmuir ve Grimm kurallarıyla sınırlıdır. Tetrazol, sülfonamid veya siklik yapılar gibi modern ilaç keşif araçları ise 'Non-Klasik Biyoizosterler' sınıfını oluşturur (Gelecek Ders!).\"},{\"id\":\"opt-11b\",\"text\":\"Tetrazol aslında bir karboksilik asit molekülüdür; azot atomları mikroskopta karbon gibi görünür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Fiziksel kimlik yanılgısı: Tetrazol tamamen farklı heteroatomlardan oluşur; 4 azot ve 1 karbon taşır.\"},{\"id\":\"opt-11c\",\"text\":\"Grimm kuralları sadece inorganik tuzlar için geçerlidir; ilaç kimyasında hiç kullanılmaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kural geçersizliği yanılgısı: Grimm kuralları klasik biyoizosterizmin temel taşıdır (-F, -OH, -NH2, vb.); ancak non-klasik halkaları kapsayamaz.\"}],\"revealedOutcome\":{\"tr\":\"Tetrazol halkası klasik atom sayısı ve değerlik kurallarına uymaz; ancak pKa (4.5-4.9), negatif yük delokalizasyonu ve sterik hacim açısından karboksilatı taklit eden 'Non-Klasik' bir biyoizosterdir.\",\"ar\":\"لا يتبع التترازول قواعد عدد الذرات الكلاسيكية؛ لكنه يحاكي الكربوكسيل في pKa (4.5-4.9) وتوزع الشحنة السالبة كـ 'متشابه حيوي غير كلاسيكي'.\",\"en\":\"Tetrazole violates classical atom/valence counts; it mimics carboxylate via pKa (4.5-4.9), planar charge delocalization, and volume as a 'Non-Classical' bioisostere.\"},\"explanation\":{\"tr\":\"Harika bir köprü! Klasik izosterizm Langmuir ve Grimm kurallarıyla sınırlıdır. Tetrazol, sülfonamid veya siklik yapılar gibi modern ilaç keşif araçları ise 'Non-Klasik Biyoizosterler' sınıfını oluşturur (Gelecek Ders!).\",\"ar\":\"جسر مفاهيمي رائع! تقف القواعد الكلاسيكية عاجزة هنا؛ فالتترازول يمثل ثورة المتشابهات غير الكلاسيكية التي سندرسها في الدرس القادم.\",\"en\":\"Brilliant bridge! Classical rules dictate electron/atom equivalence. Tetrazoles mimic carboxylate through electronic field distribution and acidity, launching Non-Classical Bioisosterism.\"}}},{\"id\":\"mc-mod3-les1-step-12\",\"stage\":\"mastery_check\",\"stageIndex\":12,\"type\":\"mastery_check\",\"title\":{\"tr\":\"Ustalık Sınavı: Kararsız Ester Köprüsünü Kurtarma\",\"ar\":\"اختبار الإتقان: إنقاذ جسر الإستر القابل للتفكك\",\"en\":\"Mastery Challenge: Rescuing a Metabolically Labile Ester Bridge\"},\"prompt\":{\"tr\":\"Yeni bir kinaz inhibitörü öncü bileşiğinde bulunan ester köprüsü (-COO-) plazma esterazlarınca hızla parçalanmaktadır. Geometriyi korurken hidroliz direncini artıran iki klasik bivalan biyoizosterik köprü öneriniz:\",\"ar\":\"يتفكك جسر الإستر (-COO-) في مرشح مثبط كينيز جديد سريعاً بأنزيمات البلازما. اقترح بديلين بيوإيزوستيريين كلاسيكيين ثنائيي التكافؤ لزيادة الثبات مع الحفاظ على الهندسة:\",\"en\":\"A promising kinase inhibitor contains an ester bridge (-COO-) rapidly cleaved by plasma esterases. Propose two classical bivalent bioisosteric replacements that enhance metabolic stability while preserving binding geometry:\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-12a\",\"text\":{\"tr\":\"Amit (-CO-NH-) ve keton (-CO-CH2-) köprüleri; bivalan geometriyi ve karbonil dipolünü korurken esteraz hidrolizine yüksek kimyasal direnç sağlarlar.\",\"ar\":\"جسرا الأميد (-CO-NH-) والكيتون (-CO-CH2-)؛ يحافظان على التكافؤ الثنائي وتطابق الكربونيل مع مقاومة فائقة لحلمهة الأستراز.\",\"en\":\"Amide (-CO-NH-) and ketone (-CO-CH2-) bridges; they preserve bivalent geometry and carbonyl dipole while conferring robust resistance to esterase cleavage.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Ustalık seviyesi tebrikler! Slide 6 bivalan izosterler: -CO-O- (ester), -CO-NH- (amit) ve -CO-CH2- (keton). Amit ve keton izosterleri esterazların nükleofilik atağına karşı katbekat dirençlidir ve ilacın in vivo yarı ömrünü kurtarır.\",\"ar\":\"إتقان مبهر! وفق السلايد 6: الإيزوستيرات ثنائية التكافؤ هي -CO-O- و -CO-NH- و -CO-CH2-. تقاوم الأميدات والكيتونات الحلمهة الأنزيمية رافعة نصف العمر الحيوي.\",\"en\":\"Mastery demonstrated! Slide 6 bivalent isosteres: -CO-O- (ester), -CO-NH- (amide), and -CO-CH2- (ketone). Amides and ketones resist esterase hydrolysis, dramatically extending half-life.\"}},{\"id\":\"opt-12b\",\"text\":{\"tr\":\"Sülfürik asit (-SO4-) ve perklorat (-ClO4-) köprüleri; enzimleri kovalent asitle parçalarlar.\",\"ar\":\"جسرا حمض الكبريتيك (-SO4-) والبيركلورات (-ClO4-)؛ يحطمان الأنزيمات تساهمياً بالحموضة.\",\"en\":\"Sulfuric acid (-SO4-) and perchlorate (-ClO4-) bridges; they covalently digest enzymes with strong acidity.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Reaktif tuz yanılgısı: Bu gruplar kararsız, aşırı reaktif veya toksik anyonlardır; bivalan karbonil izosteri değildir.\",\"ar\":\"خطأ الأملاح الشاردية: هذه مجموعات كيميائية مؤكسدة وسامة ولا تمثل إيزوستيرات كربونيل ثنائية التكافؤ.\",\"en\":\"Reactive salt misconception: These are reactive or toxic inorganic anions, not bivalent carbonyl bioisosteres.\"}},{\"id\":\"opt-12c\",\"text\":{\"tr\":\"Yalnızca saf altın atomu (-Au-); hiçbir enzim metalleri tanıyamaz.\",\"ar\":\"ذرة الذهب النقي فقط (-Au-)؛ لأنه لا يوجد أنزيم يستطيع التعرف على المعادن.\",\"en\":\"Exclusively a metallic gold atom (-Au-); no biological enzymes can recognize transition metals.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Metal yanılgısı: Organik köprüler biyoizosterik psödoatomlarla modifiye edilir, metalik altın köprüsü kimyasal olarak anlamsızdır.\",\"ar\":\"خطأ المعادن: يتم تعديل المركبات العضوية بذرات زائفة كلاسيكية؛ استخدام ذرة ذهب أمر مستحيل كيميائياً.\",\"en\":\"Metallic misconception: Organic pharmacophores are modified via organic bioisosteric pseudoatoms, not transition metals.\"}}]},\"technicalTerms\":[{\"term\":\"bivalan biyoizoster\",\"arContext\":\"المتشابه الحيوي ثنائي التكافؤ\"},{\"term\":\"esteraz direnci\",\"arContext\":\"المقاومة لأنزيمات الإستراز\"}],\"hints\":[{\"tr\":\"Slide 6'daki bivalan grup izosterlerini hatırlayın: -CO-O- ile ne izosterdir?\",\"ar\":\"تذكر إيزوستيرات المجموعات ثنائية التكافؤ من السلايد 6: ما هو إيزوستير -CO-O-؟\",\"en\":\"Recall bivalent group isosteres from Slide 6: what is isosteric with -CO-O-?\"},{\"tr\":\"Prokain'den (ester) prokainamid'e (amit) geçişi ve keton türevlerini düşünün.\",\"ar\":\"فكر في التحول الشهير من بروكائين (إستر) إلى بروكائيناميد (أميد).\",\"en\":\"Think of the transition from procaine (ester) to procainamide (amide).\"},{\"tr\":\"Ester köprüsünün (-CO-O-) klasik bivalan izosterleri amit (-CO-NH-) ve keton köprüleridir (-CO-CH2-).\",\"ar\":\"الإيزوستيرات ثنائية التكافؤ الكلاسيكية للإستر (-CO-O-) هي الأميد (-CO-NH-) والكيتون (-CO-CH2-).\",\"en\":\"Classical bivalent bioisosteres of an ester (-CO-O-) are the amide (-CO-NH-) and ketone (-CO-CH2-) bridges.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":6}],\"config\":{\"options\":[{\"id\":\"opt-12a\",\"text\":\"Amit (-CO-NH-) ve keton (-CO-CH2-) köprüleri; bivalan geometriyi ve karbonil dipolünü korurken esteraz hidrolizine yüksek kimyasal direnç sağlarlar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Ustalık seviyesi tebrikler! Slide 6 bivalan izosterler: -CO-O- (ester), -CO-NH- (amit) ve -CO-CH2- (keton). Amit ve keton izosterleri esterazların nükleofilik atağına karşı katbekat dirençlidir ve ilacın in vivo yarı ömrünü kurtarır.\"},{\"id\":\"opt-12b\",\"text\":\"Sülfürik asit (-SO4-) ve perklorat (-ClO4-) köprüleri; enzimleri kovalent asitle parçalarlar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Reaktif tuz yanılgısı: Bu gruplar kararsız, aşırı reaktif veya toksik anyonlardır; bivalan karbonil izosteri değildir.\"},{\"id\":\"opt-12c\",\"text\":\"Yalnızca saf altın atomu (-Au-); hiçbir enzim metalleri tanıyamaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Metal yanılgısı: Organik köprüler biyoizosterik psödoatomlarla modifiye edilir, metalik altın köprüsü kimyasal olarak anlamsızdır.\"}],\"revealedOutcome\":{\"tr\":\"Amit (-CO-NH-) ve keton (-CO-CH2-) köprüleri; bivalan geometriyi ve karbonil dipolünü korurken esteraz hidrolizine yüksek kimyasal direnç sağlarlar.\",\"ar\":\"جسرا الأميد (-CO-NH-) والكيتون (-CO-CH2-)؛ يحافظان على التكافؤ الثنائي وتطابق الكربونيل مع مقاومة فائقة لحلمهة الأستراز.\",\"en\":\"Amide (-CO-NH-) and ketone (-CO-CH2-) bridges; they preserve bivalent geometry and carbonyl dipole while conferring robust resistance to esterase cleavage.\"},\"explanation\":{\"tr\":\"Ustalık seviyesi tebrikler! Slide 6 bivalan izosterler: -CO-O- (ester), -CO-NH- (amit) ve -CO-CH2- (keton). Amit ve keton izosterleri esterazların nükleofilik atağına karşı katbekat dirençlidir ve ilacın in vivo yarı ömrünü kurtarır.\",\"ar\":\"إتقان مبهر! وفق السلايد 6: الإيزوستيرات ثنائية التكافؤ هي -CO-O- و -CO-NH- و -CO-CH2-. تقاوم الأميدات والكيتونات الحلمهة الأنزيمية رافعة نصف العمر الحيوي.\",\"en\":\"Mastery demonstrated! Slide 6 bivalent isosteres: -CO-O- (ester), -CO-NH- (amide), and -CO-CH2- (ketone). Amides and ketones resist esterase hydrolysis, dramatically extending half-life.\"}}}]},\"mc-mod3-les2\":{\"$schema\":\"../../../packages/platform/schema/lesson.schema.json\",\"id\":\"mc-mod3-les2\",\"courseId\":\"medchem\",\"moduleId\":\"mc-mod-03\",\"title\":{\"tr\":\"Klasik Olmayan Biyoizosterler: Karboksilik Asit ve Tetrazol\",\"ar\":\"المتشابهات الحيوية غير الكلاسيكية: حمض الكربوكسيل والتترازول\",\"en\":\"Non-Classical Bioisosteres: Carboxylic Acid & Tetrazole\"},\"order\":2,\"access\":\"free\",\"objective\":{\"tr\":\"Karboksilik asit, tetrazol, sülfonamid ve hidroksimetil gibi non-klasik biyoizosterleri uygulayarak ilaçların oral biyoyararlanımını, metabolik kararlılığını ve reseptör seçiciliğini optimize etmek.\",\"ar\":\"تطبيق المتشابهات الحيوية غير الكلاسيكية (التترازول، السلفوناميد، وهيدروكسي ميثيل) لتحسين التوافر الحيوي الفموي، والثباتية الاستقلابية، وانتقائية المستقبل في الأدوية.\",\"en\":\"Design non-classical bioisosteric replacements (tetrazole, sulfonamide, hydroxymethyl) to optimize oral bioavailability, resolve pharmacokinetic liabilities, and evade metabolic inactivation.\"},\"misconceptions\":[{\"tr\":\"4 adet azot içeren 1H-tetrazol halkasının amonyak veya piridin gibi bazik olması gerektiği yanılgısı.\",\"ar\":\"الظن الخاطئ بوجوب كون حلقة 1H-tetrazole المحتوية على 4 نيتروجينات قاعدية كالأمونيا أو البيريدين.\",\"en\":\"The misconception that a 4-nitrogen tetrazole ring must be basic like ammonia or pyridine.\"},{\"tr\":\"Karboksilik asit ve tetrazolün fizyolojik pH'ta aynı oranda iyonize olmalarına rağmen membran geçirgenliklerinin aynı olacağı varsayımı (desolvasyon cezasının göz ardı edilmesi).\",\"ar\":\"الافتراض الخاطئ بتماثل النفاذية الغشائية للحمض والتترازول لتشابه تأينهما متجاهلاً فارق طاقة نزع الماء (desolvation).\",\"en\":\"The assumption that carboxylic acid and tetrazole share identical membrane permeability simply because both are ionized at physiological pH.\"},{\"tr\":\"Biyoizosterik değişimin yalnızca atom sayısı ve değerlik elektronları eşit olan gruplarla (klasik izosterizm) yapılabileceği düşüncesi.\",\"ar\":\"الاعتقاد الخاطئ بأن التبديل البيوإيزوستيري يقتصر حصراً على المجموعات المتطابقة في عدد الذرات وإلكترونات التكافؤ.\",\"en\":\"The belief that bioisosteric design is strictly limited to groups with identical atom counts and valence electrons.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":5},{\"file\":\"Biyoizosterizm.pdf\",\"page\":9},{\"file\":\"Biyoizosterizm.pdf\",\"page\":10},{\"file\":\"Biyoizosterizm.pdf\",\"page\":11},{\"file\":\"Biyoizosterizm.pdf\",\"page\":12},{\"file\":\"Biyoizosterizm.pdf\",\"page\":14},{\"file\":\"Biyoizosterizm.pdf\",\"page\":15}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Foye's Principles of Medicinal Chemistry\",\"edition\":\"8th ed.\",\"topic\":\"Non-Classical Bioisosteres: Acid Isosteres, Tetrazoles, and Peptidomimetics\",\"chapter\":\"Chapter 2\",\"page\":\"50-68\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Wilson and Gisvold's Textbook of Organic Medicinal and Pharmaceutical Chemistry\",\"edition\":\"12th ed.\",\"topic\":\"Bioisosterism in Drug Design: Non-Classical Replacements and Carboxylic Acid Mimics\",\"chapter\":\"Chapter 3\",\"page\":\"80-101\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"mc-mod3-les2-card1\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Tetrazol Halkasının Asitlik Mekanizması\",\"prompt\":\"1H-tetrazol halkası 4 adet azot içermesine rağmen neden bir baz değil, karboksilik asit gibi asidiktir (pKa 4.5-4.9)?\",\"answer\":\"Deprotonlandığında oluşan negatif yük, 5 üyeli düzlemsel aromatik halkanın 4 elektronegatif azotu üzerinde rezonansla delokalize olur ve konjuge bazı aşırı kararlı kılar.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod3-les2-card2\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Tetrazolün Biyoyararlanım Üstünlüğü\",\"prompt\":\"Karboksilik asit yerine tetrazol halkası geçirilmesi (örn. Losartan) oral biyoyararlanımı neden 10 kat artırır?\",\"answer\":\"Tetrazolün negatif yükü delokalize olduğundan hidrasyon kafesi küçüktür (desolvasyon cezası düşüktür) ve lipofilisitesi (logP) ~1.3 birim daha yüksektir.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod3-les2-card3\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Salbütamol Hidroksimetil Modifikasyonu\",\"prompt\":\"Salbütamolde adrenalinin meta-fenolik -OH grubu neden hidroksimetil (-CH2OH) ile değiştirilmiştir?\",\"answer\":\"Beta-2 reseptör serini ile hidrojen bağını korurken, katekol geometrisini bozarak COMT enziminin hızlı metabolik metilasyonunu tamamen bloke etmek için.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod3-les2-card4\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Sülfanilamid Antimetaboliti\",\"prompt\":\"Sülfanilamid bakterilerde hangi doğal metabolitin non-klasik biyoizosterik antimetabolitidir?\",\"answer\":\"p-Aminobenzoik asidin (PABA); dihidropteroat sentaz enzimini yarışmalı bloke ederek folik asit sentezini durdurur.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod3-les2-card5\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Halka-Zincir Biyoizosterizmi (Dietilstilbestrol vs Estradiol)\",\"prompt\":\"trans-Dietilstilbestrol (DES) açık zincirli bir difenil yapısı olmasına rağmen nasıl 4 halkalı rijit steroid çekirdeğine sahip 17beta-estradiolü taklit eder?\",\"answer\":\"DES in iki etil grubu fenol halkalarını sterik olarak öyle bir açıyla kilitler ki, estradiolün 12.1 Å mesafeli iki hidroksil grubu uzayda birebir taklit edilir (Slide 12).\",\"box\":1,\"intervalDays\":1}],\"translations\":{\"tr\":{\"title\":\"Klasik Olmayan Biyoizosterler: Karboksilik Asit ve Tetrazol\"},\"ar\":{\"title\":\"المتشابهات الحيوية غير الكلاسيكية: حمض الكربوكسيل والتترازول\"}},\"steps\":[{\"id\":\"mc-mod3-les2-step-01\",\"stage\":\"hook\",\"stageIndex\":1,\"type\":\"predict_reveal\",\"title\":{\"tr\":\"Losartan Devrimi ve Dört Azotlu Asit Çelişkisi\",\"ar\":\"ثورة اللوسارتان ومفارقة النيتروجينات الأربعة الحامضية\",\"en\":\"The Losartan Breakthrough & The 4-Nitrogen Acid Paradox\"},\"prompt\":{\"tr\":\"Peptid kökenli tansiyon ilacı öncülerinde benzoik asit (-COOH) bağırsaktan emilmiyor ve biyoyararlanım <%3 kalıyordu. Kimyagerler asidi çıkarıp 4 azotlu tetrazol taktılar; emilim 10 kat arttı! 4 azotlu halka nasıl asit gibi davranır?\",\"ar\":\"فشلت طليعة خافضات الضغط الببتيدية لضعف امتصاص حمض البنزويك (-COOH) وتوافره الحيوي (<3%). استبدل الكيميائيون الحمض بحلقة تترازول بـ 4 نيتروجينات؛ فارتفع الامتصاص 10 أضعاف! كيف تتصرف حلقة 4 نيتروجينات كحمض؟\",\"en\":\"Early peptide-derived AT1 antagonists failed clinically because benzoic acid (-COOH) had <3% bioavailability. Chemists replaced -COOH with a 4-nitrogen tetrazole ring, boosting bioavailability 10-fold! How can a 4-nitrogen ring act like an acid?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-1a\",\"text\":{\"tr\":\"Tetrazol halkasındaki N-H protonu ayrıldığında negatif yük 4 azot atomu üzerine rezonansla yayılır; konjuge baz aşırı kararlı hale gelerek asidik pKa (4.5-4.9) üretir.\",\"ar\":\"عند فقد بروتون N-H في التترازول، تتوزع الشحنة السالبة بالرنين على 4 ذرات نيتروجين؛ مما يمنح القاعدة المقترنة ثباتاً استثنائياً وسلوكاً حامضياً (pKa 4.5-4.9).\",\"en\":\"Deprotonating the tetrazole N-H disperses the negative charge across 4 nitrogens via aromatic resonance, conferring an acidic pKa (4.5-4.9) identical to carboxylates.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Tetrazol halkası 4 elektronegatif azota sahiptir. Deprotonasyonla oluşan negatif yük 5 üyeli düzlemsel aromatik halka boyunca yayılır; konjuge baz kararlı olduğundan pKa'sı karboksilik aside (4.5-4.9) eşitlenir.\",\"ar\":\"صحيح! تمتلك حلقة التترازول 4 ذرات نيتروجين كهروسلبية. تتوزع الشحنة السالبة الناتجة عن نزع البروتون على الحلقة العطرية؛ مما يمنحها ثباتاً وقيمة pKa حامضية (4.5-4.9) تماثل الكربوكسيل.\",\"en\":\"Correct! Tetrazole contains 4 electronegative nitrogens. The deprotonated conjugate base is stabilized by planar aromatic resonance, yielding an acidic pKa (4.5-4.9) mimicking carboxylic acid.\"}},{\"id\":\"opt-1b\",\"text\":{\"tr\":\"4 azot atomu bağırsak lümenindeki hidroklorik asidi emerek molekülü kimyasal olarak asitlendirir.\",\"ar\":\"تمتص ذرات النيتروجين الأربع حمض كلور الماء المعوي لترفع حموضة الجزيء كيميائياً.\",\"en\":\"The 4 nitrogen atoms absorb hydrochloric acid in the gut lumen, chemically acidifying the drug.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Dış asit absorbsiyonu yanılgısı: Asitlik ilacın çevreden asit çekmesi değil, molekülün kendi içsel proton verme yatkınlığı ve anyon kararlılığıdır.\",\"ar\":\"خطأ امتصاص الحمض: الحامضية خاصية بنيوية ذاتية تعتمد على منح البروتون وثبات الأنيون، وليست امتصاصاً لأحماض المعدة.\",\"en\":\"Acid absorption misconception: Acidity is an intrinsic thermodynamic tendency to dissociate a proton, not external acid uptake.\"}},{\"id\":\"opt-1c\",\"text\":{\"tr\":\"Tetrazol aslında kuvvetli bir bazdır; bağırsak hücre zarlarını delerek pasif sızıntı oluşturur.\",\"ar\":\"التترازول في الحقيقة قاعدة قوية؛ تثقب أغشية الخلايا المعوية مسببة تسرباً للداخل.\",\"en\":\"Tetrazole is actually a strong base that chemically punctures gut membranes to leak inside.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Bazik membran hasarı yanılgısı: Tetrazol fizyolojik pH'ta zayıf asit anyonudur (pKa ~4.8), baz değildir ve membranları delmez.\",\"ar\":\"خطأ تخريب الغشاء: التترازول حمض ضعيف يتأين عند pH الفيزيولوجي، وليس قاعدة أكالة تخرب جدار الأمعاء.\",\"en\":\"Basic puncture misconception: Tetrazole is a weak acid (pKa ~4.8), not a corrosive base that punctures cellular membranes.\"}}]},\"technicalTerms\":[{\"term\":\"tetrazol halkası\",\"arContext\":\"حلقة التترازول (tetrazole ring)\"},{\"term\":\"non-klasik biyoizoster\",\"arContext\":\"المتشابه الحيوي غير الكلاسيكي\"}],\"hints\":[{\"tr\":\"Bir asidin gücünü, protonunu verdikten sonra geriye kalan konjuge bazının kararlılığı belirler.\",\"ar\":\"تتحدد قوة أي حمض بمدى استقرار وثبات قاعدته المقترنة بعد فقد البروتون.\",\"en\":\"Acid strength is determined by the thermodynamic stability of its deprotonated conjugate base.\"},{\"tr\":\"Tetrazol 5 üyeli düzlemsel bir halkadır ve 4 adet elektronegatif azot atomu taşır.\",\"ar\":\"التترازول حلقة خماسية مستوية تحتوي 4 ذرات نيتروجين عالية الكهروسلبية.\",\"en\":\"Tetrazole is a planar 5-membered aromatic ring containing 4 electronegative nitrogen atoms.\"},{\"tr\":\"Negatif yük 4 azot atomu üzerine rezonansla delokalize olur; bu rezonans kararlılığı tetrazole karboksilik asitle aynı pKa'yı kazandırır.\",\"ar\":\"تتوزع الشحنة السالبة بالرنين على ذرات النيتروجين الأربع، مانحة التترازول حامضية مطابقة لحمض الكربوكسيل.\",\"en\":\"Resonance delocalizes the negative charge across all 4 nitrogens, stabilizing the anion and producing an acidic pKa of 4.5-4.9.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":9}],\"config\":{\"options\":[{\"id\":\"opt-1a\",\"text\":\"Tetrazol halkasındaki N-H protonu ayrıldığında negatif yük 4 azot atomu üzerine rezonansla yayılır; konjuge baz aşırı kararlı hale gelerek asidik pKa (4.5-4.9) üretir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Tetrazol halkası 4 elektronegatif azota sahiptir. Deprotonasyonla oluşan negatif yük 5 üyeli düzlemsel aromatik halka boyunca yayılır; konjuge baz kararlı olduğundan pKa'sı karboksilik aside (4.5-4.9) eşitlenir.\"},{\"id\":\"opt-1b\",\"text\":\"4 azot atomu bağırsak lümenindeki hidroklorik asidi emerek molekülü kimyasal olarak asitlendirir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Dış asit absorbsiyonu yanılgısı: Asitlik ilacın çevreden asit çekmesi değil, molekülün kendi içsel proton verme yatkınlığı ve anyon kararlılığıdır.\"},{\"id\":\"opt-1c\",\"text\":\"Tetrazol aslında kuvvetli bir bazdır; bağırsak hücre zarlarını delerek pasif sızıntı oluşturur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Bazik membran hasarı yanılgısı: Tetrazol fizyolojik pH'ta zayıf asit anyonudur (pKa ~4.8), baz değildir ve membranları delmez.\"}],\"revealedOutcome\":{\"tr\":\"Tetrazol halkasındaki N-H protonu ayrıldığında negatif yük 4 azot atomu üzerine rezonansla yayılır; konjuge baz aşırı kararlı hale gelerek asidik pKa (4.5-4.9) üretir.\",\"ar\":\"عند فقد بروتون N-H في التترازول، تتوزع الشحنة السالبة بالرنين على 4 ذرات نيتروجين؛ مما يمنح القاعدة المقترنة ثباتاً استثنائياً وسلوكاً حامضياً (pKa 4.5-4.9).\",\"en\":\"Deprotonating the tetrazole N-H disperses the negative charge across 4 nitrogens via aromatic resonance, conferring an acidic pKa (4.5-4.9) identical to carboxylates.\"},\"explanation\":{\"tr\":\"Doğru! Tetrazol halkası 4 elektronegatif azota sahiptir. Deprotonasyonla oluşan negatif yük 5 üyeli düzlemsel aromatik halka boyunca yayılır; konjuge baz kararlı olduğundan pKa'sı karboksilik aside (4.5-4.9) eşitlenir.\",\"ar\":\"صحيح! تمتلك حلقة التترازول 4 ذرات نيتروجين كهروسلبية. تتوزع الشحنة السالبة الناتجة عن نزع البروتون على الحلقة العطرية؛ مما يمنحها ثباتاً وقيمة pKa حامضية (4.5-4.9) تماثل الكربوكسيل.\",\"en\":\"Correct! Tetrazole contains 4 electronegative nitrogens. The deprotonated conjugate base is stabilized by planar aromatic resonance, yielding an acidic pKa (4.5-4.9) mimicking carboxylic acid.\"}}},{\"id\":\"mc-mod3-les2-step-02\",\"stage\":\"question\",\"stageIndex\":2,\"type\":\"question\",\"title\":{\"tr\":\"Aktif Soru: Azotlu Bir Halka Nasıl Asit Olur?\",\"ar\":\"سؤال تفاعلي: كيف تتصرف حلقة نيتروجينية كحمض؟\",\"en\":\"Active Question: How Can a Nitrogen Ring Act Like an Acid?\"},\"prompt\":{\"tr\":\"Amonyak (NH3) ve piridin gibi azotlu bileşikler bazik iken, 1H-tetrazol halkasının karboksilik asitle neredeyse aynı asidik pKa değerine (~4.8) sahip olmasının kuantum kimyasal nedeni nedir?\",\"ar\":\"بينما تعتبر المركبات النيتروجينية كالأمونيا والبيريدين قاعدية، ما هو السبب الكيميائي الكمي لامتلاك حلقة 1H-tetrazole قيمة pKa حامضية (~4.8) مطابقة لحمض الكربوكسيل؟\",\"en\":\"While nitrogenous compounds like ammonia and pyridine are basic, what fundamental quantum-chemical mechanism grants the 1H-tetrazole ring an acidic pKa (~4.8) virtually identical to a carboxylic acid?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-2a\",\"text\":{\"tr\":\"Deprotonasyon sonucu oluşan anyon, 5 üyeli düzlemsel halkada 6 pi-elektronlu aromatik Hückel sextetini korur ve negatif yük 4 elektronegatif azota delokalize olur.\",\"ar\":\"يحافظ الأنيون الناتج عن نزع البروتون على سداسي هوكل العطري بـ 6 إلكترونات باي المستوية، وتتوزع الشحنة السالبة على 4 ذرات نيتروجين كهروسلبية.\",\"en\":\"The deprotonated anion preserves a planar 6 pi-electron aromatic Hückel sextet, delocalizing negative charge across 4 electronegative nitrogens.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel! Piridin veya amonyakta azotun serbest elektron çifti lokalizedir ve proton bağlar (bazdır). Tetrazolden proton ayrıldığında ise oluşan tetrazolat anyonu 6 pi-elektronlu aromatik bir sextet oluşturarak olağanüstü kararlı hale gelir.\",\"ar\":\"ممتاز! في الأمونيا يكون الزوج الإلكتروني موضعياً فيستقبل بروتوناً (قاعدة). أما في التترازول فينتج أنيون عطري مستوٍ بـ 6 إلكترونات باي شديد الاستقرار.\",\"en\":\"Brilliant! Ammonia's lone pair is localized and basic. In tetrazole, deprotonation yields an aromatic 6 pi-electron sextet delocalized over 4 nitrogens, creating profound conjugate base stability.\"}},{\"id\":\"opt-2b\",\"text\":{\"tr\":\"Tetrazol halkasındaki azotlar oda sıcaklığında oksijen atomuna dönüşerek karbonil bağı oluşturur.\",\"ar\":\"تتحول ذرات النيتروجين في التترازول عند حرارة الغرفة إلى ذرات أكسجين لتشكل كربونيل.\",\"en\":\"The nitrogens in tetrazole spontaneously transmute into oxygens at room temperature to form carbonyls.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Atom dönüşüm yanılgısı: Kimyasal atomlar birbirine dönüşmez; benzerlik elektronik yük delokalizasyonundan doğar.\",\"ar\":\"خطأ التحول الذري: لا تتحول الذرات لبعضها؛ التشابه الحيوي ينبع من التطابق في الحجم الفراغي وتوزع الشحنة.\",\"en\":\"Transmutation misconception: Atoms never transmute chemically; bioisosterism relies on electrostatic surface matching.\"}},{\"id\":\"opt-2c\",\"text\":{\"tr\":\"Azot atomları pozitif proton yayarak çözeltiyi asitlendiren radyoaktif izotoplar içerir.\",\"ar\":\"تحتوي ذرات النيتروجين على نظائر مشعة تطلق بروتونات موجبة ترفع حموضة المحلول.\",\"en\":\"The nitrogens contain radioactive isotopes emitting free protons to acidify surrounding media.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Radyoaktif yanılgı: İlaç kimyasında kararlı izotoplar kullanılır; pKa kimyasal asit ayrışma dengesidir.\",\"ar\":\"خطأ الإشعاع: تستخدم الأدوية نظائر مستقرة كيميائياً، وقيمة pKa تعبر عن توازن كيميائي عكوس.\",\"en\":\"Radioactivity misconception: Drug molecules are stable organic compounds; pKa represents chemical dissociation equilibrium.\"}}]},\"technicalTerms\":[{\"term\":\"Hückel aromatik sexteti\",\"arContext\":\"سداسي هوكل العطري (Hückel sextet)\"},{\"term\":\"konjuge baz kararlılığı\",\"arContext\":\"ثبات القاعدة المقترنة\"}],\"hints\":[{\"tr\":\"Aromatiklik kuralını hatırlayın: 4n + 2 pi-elektronu içeren halkalar aşırı kararlıdır.\",\"ar\":\"تذكر قاعدة العطرية: الحلقات المحتوية على 4n + 2 إلكترون باي تكون فائقة الثبات.\",\"en\":\"Recall Hückel's aromaticity rule: planar rings with 4n + 2 pi-electrons are exceptionally stable.\"},{\"tr\":\"N-H protonu ayrılınca geriye kalan elektron çifti halkanın pi-sistemine katılarak 6 pi-elektronlu aromatik bir anyon kurar.\",\"ar\":\"عند مغادرة البروتون، ينضم الزوج الإلكتروني لسحابة باي مشكلاً أنيوناً عطرياً بـ 6 إلكترونات.\",\"en\":\"When the N-H proton departs, the remaining electron pair joins the cyclic pi system, completing a 6 pi aromatic anion.\"},{\"tr\":\"Bu aromatik delokalizasyon protonun kolayca ayrılmasını sağlar; sonuçta pKa ~4.8 olan karboksilik asit benzeri asidik bir merkez doğar.\",\"ar\":\"يسهل هذا الرنين خروج البروتون، منتجاً مركزاً حامضياً بـ pKa ~4.8 مطابقاً لحمض الكربوكسيل.\",\"en\":\"This aromatic delocalization strongly drives deprotonation, producing an acidic pKa of ~4.8 matching carboxylates.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":9}],\"config\":{\"options\":[{\"id\":\"opt-2a\",\"text\":\"Deprotonasyon sonucu oluşan anyon, 5 üyeli düzlemsel halkada 6 pi-elektronlu aromatik Hückel sextetini korur ve negatif yük 4 elektronegatif azota delokalize olur.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel! Piridin veya amonyakta azotun serbest elektron çifti lokalizedir ve proton bağlar (bazdır). Tetrazolden proton ayrıldığında ise oluşan tetrazolat anyonu 6 pi-elektronlu aromatik bir sextet oluşturarak olağanüstü kararlı hale gelir.\"},{\"id\":\"opt-2b\",\"text\":\"Tetrazol halkasındaki azotlar oda sıcaklığında oksijen atomuna dönüşerek karbonil bağı oluşturur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Atom dönüşüm yanılgısı: Kimyasal atomlar birbirine dönüşmez; benzerlik elektronik yük delokalizasyonundan doğar.\"},{\"id\":\"opt-2c\",\"text\":\"Azot atomları pozitif proton yayarak çözeltiyi asitlendiren radyoaktif izotoplar içerir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Radyoaktif yanılgı: İlaç kimyasında kararlı izotoplar kullanılır; pKa kimyasal asit ayrışma dengesidir.\"}],\"revealedOutcome\":{\"tr\":\"Deprotonasyon sonucu oluşan anyon, 5 üyeli düzlemsel halkada 6 pi-elektronlu aromatik Hückel sextetini korur ve negatif yük 4 elektronegatif azota delokalize olur.\",\"ar\":\"يحافظ الأنيون الناتج عن نزع البروتون على سداسي هوكل العطري بـ 6 إلكترونات باي المستوية، وتتوزع الشحنة السالبة على 4 ذرات نيتروجين كهروسلبية.\",\"en\":\"The deprotonated anion preserves a planar 6 pi-electron aromatic Hückel sextet, delocalizing negative charge across 4 electronegative nitrogens.\"},\"explanation\":{\"tr\":\"Mükemmel! Piridin veya amonyakta azotun serbest elektron çifti lokalizedir ve proton bağlar (bazdır). Tetrazolden proton ayrıldığında ise oluşan tetrazolat anyonu 6 pi-elektronlu aromatik bir sextet oluşturarak olağanüstü kararlı hale gelir.\",\"ar\":\"ممتاز! في الأمونيا يكون الزوج الإلكتروني موضعياً فيستقبل بروتوناً (قاعدة). أما في التترازول فينتج أنيون عطري مستوٍ بـ 6 إلكترونات باي شديد الاستقرار.\",\"en\":\"Brilliant! Ammonia's lone pair is localized and basic. In tetrazole, deprotonation yields an aromatic 6 pi-electron sextet delocalized over 4 nitrogens, creating profound conjugate base stability.\"}}},{\"id\":\"mc-mod3-les2-step-03\",\"stage\":\"intuition\",\"stageIndex\":3,\"type\":\"intuition\",\"title\":{\"tr\":\"Sezgisel Model: Yayılmış Bulut vs Kilitli Küre\",\"ar\":\"النموذج الحسي: سحابة منتشرة مقابل شحنة محتبسة\",\"en\":\"Intuitive Mental Model: Diffuse Cloud vs Locked Sphere\"},\"prompt\":{\"tr\":\"Ağır bir yükü iki parmağınızla taşımak canınızı yakar, ancak sırt çantasının geniş askılarına yaymak yükü hafifletir. Negatif yükün iki oksijen yerine beş halka atomuna yayılması biyoyararlanımı nasıl etkiler?\",\"ar\":\"حمل ثقل بإصبعين يسبب ألماً شديداً، بينما توزيعه على حقيبة ظهر عريضة يخفف العبء. كيف يؤثر توزيع الشحنة السالبة على خمس ذرات بدلاً من ذرتي أكسجين على الامتصاص؟\",\"en\":\"Pinching a heavy weight with two fingers is painful, but spreading it across a wide backpack strap feels effortless. How does delocalizing -1 charge across five ring atoms boost membrane permeability?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-3a\",\"text\":{\"tr\":\"Yük yayılınca su molekülleri sıkı bir hidrasyon kafesi oluşturamaz (desolvasyon cezası 6 sudan 2 suya iner); molekül lipit membranlardan sürtünmesizce süzülür.\",\"ar\":\"بتوزع الشحنة تعجز المياه عن تشكيل قفص هيدرات صلب (تهبط المياه المحتجزة من 6 إلى 2)؛ فيعبر الجزيء الأغشية الدهنية بسلاسة.\",\"en\":\"Diffusing the charge prevents tight water trapping (desolvation drops from 6 to 2 waters); the lipophilic ring easily traverses lipid membranes.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika bir fizikokimyasal sezgi! Karboksilatta negatif yük 2 oksijende yoğunlaşır ve 6 su molekülünü katı bir buz kafesi gibi kilitler (yüksek desolvasyon engeli). Tetrazolda ise yük 5 atoma yayıldığı için su gevşek tutunur (sadece 2 su); zar geçişi 10 kat hızlanır.\",\"ar\":\"حدس فيزيوكيميائي رائع! يركز الكربوكسيل الشحنة على ذرتي أكسجين فيحتجز 6 جزيئات ماء بقسوة. أما التترازول فيوزعها برقة محتجزاً جزيئين فقط؛ فتنخفض طاقة نزع الماء ويعبر الغشاء أسرع بـ 10 مرات.\",\"en\":\"Brilliant biophysical intuition! Carboxylate concentrates charge on 2 oxygens, locking 6 water molecules tightly. Tetrazole spreads charge over 5 atoms, trapping only 2 waters and slashing the desolvation penalty.\"}},{\"id\":\"opt-3b\",\"text\":{\"tr\":\"Geniş yük dağılımı molekülü o kadar ağırlaştırır ki yerçekimiyle bağırsaktan kana doğru akar.\",\"ar\":\"يجعل توزع الشحنة الجزيء ثقيلاً جداً فيسحبه الامتصاص لداخل الدم بفعل الجاذبية.\",\"en\":\"Charge diffusion makes the molecule so dense that gravity pulls it across the intestinal lining.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yerçekimi yanılgısı: İlaç emilimi yerçekimiyle değil, pasif difüzyon ve Fick kanununa göre kimyasal gradyanla yürür.\",\"ar\":\"خطأ الجاذبية: الامتصاص تحكمه قوانين فيك للانتشار المنفعل والانحلال الدهني وليس الجاذبية الأرضية.\",\"en\":\"Gravity misconception: Drug absorption follows passive diffusion and Fick's law across chemical gradients, not gravitational forces.\"}},{\"id\":\"opt-3c\",\"text\":{\"tr\":\"Yükün yayılması su moleküllerini buharlaştırarak bağırsak lümenini tamamen kurutur.\",\"ar\":\"يؤدي انتشار الشحنة إلى تبخير جزيئات الماء وتجفيف لمعة الأمعاء بالكامل.\",\"en\":\"Spreading the charge evaporates surrounding water, completely desiccating the intestinal lumen.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Termal buharlaşma yanılgısı: İlaç molekülleri su buharlaştırmaz; hidrasyon serbest enerjisi moleküler seviyede su ayrışmasını belirler.\",\"ar\":\"خطأ التبخير: الجزيئات الدوائية لا تبخر الماء؛ بل تحدد طاقة الإماهة الحرة مدى سهولة التحرر من الماء.\",\"en\":\"Evaporation misconception: Small molecules do not boil water; desolvation free energy governs stripping hydration shells.\"}}]},\"technicalTerms\":[{\"term\":\"desolvasyon cezası\",\"arContext\":\"طاقة نزع الماء (desolvation penalty)\"},{\"term\":\"hidrasyon kafesi\",\"arContext\":\"قفص الإماهة (hydration cage)\"}],\"hints\":[{\"tr\":\"Karboksilat anyonunun etrafını saran su moleküllerini hayal edin: Yük yoğunlaştıkça su daha sıkı kilitlenir.\",\"ar\":\"تخيل جزيئات الماء المحيطة بشحنة الكربوكسيل: كلما تركزت الشحنة ارتبط الماء بقوة أكبر.\",\"en\":\"Picture the hydration shell around carboxylate: concentrated charge traps water molecules tightly.\"},{\"tr\":\"Bir ilacın lipit zardan geçebilmesi için önce etrafındaki su moleküllerini üzerinden soyup atması (desolvasyon) gerekir.\",\"ar\":\"لعبور الغشاء الدهني، يجب أن يتجرد الدواء أولاً من قفص الماء المحيط به.\",\"en\":\"To enter a lipid membrane, a drug must shed its surrounding water molecules (desolvation).\"},{\"tr\":\"Tetrazolda yük yayıldığı için su molekülleri zayıf tutunur; desolvasyon enerjisi düşer ve zar geçirgenliği fırlar.\",\"ar\":\"يرتبط الماء برخاوة مع التترازول بسبب تشتت الشحنة، فتهبط طاقة نزع الماء وتقفز النفاذية.\",\"en\":\"Tetrazole's diffuse charge weakly holds water, minimizing desolvation cost and multiplying lipid permeability.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":9}],\"config\":{\"options\":[{\"id\":\"opt-3a\",\"text\":\"Yük yayılınca su molekülleri sıkı bir hidrasyon kafesi oluşturamaz (desolvasyon cezası 6 sudan 2 suya iner); molekül lipit membranlardan sürtünmesizce süzülür.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika bir fizikokimyasal sezgi! Karboksilatta negatif yük 2 oksijende yoğunlaşır ve 6 su molekülünü katı bir buz kafesi gibi kilitler (yüksek desolvasyon engeli). Tetrazolda ise yük 5 atoma yayıldığı için su gevşek tutunur (sadece 2 su); zar geçişi 10 kat hızlanır.\"},{\"id\":\"opt-3b\",\"text\":\"Geniş yük dağılımı molekülü o kadar ağırlaştırır ki yerçekimiyle bağırsaktan kana doğru akar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yerçekimi yanılgısı: İlaç emilimi yerçekimiyle değil, pasif difüzyon ve Fick kanununa göre kimyasal gradyanla yürür.\"},{\"id\":\"opt-3c\",\"text\":\"Yükün yayılması su moleküllerini buharlaştırarak bağırsak lümenini tamamen kurutur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Termal buharlaşma yanılgısı: İlaç molekülleri su buharlaştırmaz; hidrasyon serbest enerjisi moleküler seviyede su ayrışmasını belirler.\"}],\"revealedOutcome\":{\"tr\":\"Yük yayılınca su molekülleri sıkı bir hidrasyon kafesi oluşturamaz (desolvasyon cezası 6 sudan 2 suya iner); molekül lipit membranlardan sürtünmesizce süzülür.\",\"ar\":\"بتوزع الشحنة تعجز المياه عن تشكيل قفص هيدرات صلب (تهبط المياه المحتجزة من 6 إلى 2)؛ فيعبر الجزيء الأغشية الدهنية بسلاسة.\",\"en\":\"Diffusing the charge prevents tight water trapping (desolvation drops from 6 to 2 waters); the lipophilic ring easily traverses lipid membranes.\"},\"explanation\":{\"tr\":\"Harika bir fizikokimyasal sezgi! Karboksilatta negatif yük 2 oksijende yoğunlaşır ve 6 su molekülünü katı bir buz kafesi gibi kilitler (yüksek desolvasyon engeli). Tetrazolda ise yük 5 atoma yayıldığı için su gevşek tutunur (sadece 2 su); zar geçişi 10 kat hızlanır.\",\"ar\":\"حدس فيزيوكيميائي رائع! يركز الكربوكسيل الشحنة على ذرتي أكسجين فيحتجز 6 جزيئات ماء بقسوة. أما التترازول فيوزعها برقة محتجزاً جزيئين فقط؛ فتنخفض طاقة نزع الماء ويعبر الغشاء أسرع بـ 10 مرات.\",\"en\":\"Brilliant biophysical intuition! Carboxylate concentrates charge on 2 oxygens, locking 6 water molecules tightly. Tetrazole spreads charge over 5 atoms, trapping only 2 waters and slashing the desolvation penalty.\"}}},{\"id\":\"mc-mod3-les2-step-04\",\"stage\":\"visual_explanation\",\"stageIndex\":4,\"type\":\"visual_explanation\",\"title\":{\"tr\":\"Görsel Profil: Karboksilik Asit vs 1H-Tetrazol\",\"ar\":\"الملف البصري: حمض الكربوكسيل مقابل 1H-تترازول\",\"en\":\"Visual Profile: Carboxylic Acid vs 1H-Tetrazole\"},\"prompt\":{\"tr\":\"Karboksilik asit (-COOH) ile 1H-tetrazolün fizikokimyasal profilini kıyaslayın: Her ikisinin de pKa'sı asidiktir (~4.2-4.8). Ancak tetrazolün logP'si 1.3 birim daha yüksektir. Bu durum klinik performansı nasıl değiştirir?\",\"ar\":\"قارن الخواص بين -COOH و 1H-tetrazole: كلاهما حامضي (pKa ~4.2-4.8). لكن logP للتترازول أعلى بـ 1.3 وحدة. كيف يغير هذا الأداء السريري؟\",\"en\":\"Compare carboxylic acid (-COOH) and 1H-tetrazole: both are acidic (pKa ~4.2-4.8). Yet tetrazole's logP is 1.3 units higher. How does this lipophilicity advantage transform clinical pharmacokinetics?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-4a\",\"text\":{\"tr\":\"Tetrazol AT1 reseptöründeki arginin ile iyonik bağı korurken, 10 kat artan lipofilisitesi sayesinde oral emilimi %3'ten %33'e çıkarır ve metabolik glukuronidasyona direnir.\",\"ar\":\"يحفظ التترازول الرابطة الأيونية مع أرجنين المستقبل AT1، وبفضل زيادة الانحلال بالدهن 10 أضعاف يقفز الامتصاص من 3% إلى 33% ويقاوم الاقتران بالغلوبيولين.\",\"en\":\"Tetrazole preserves the essential ionic salt bridge with receptor arginine while its 10-fold lipophilicity gain multiplies bioavailability from 3% to 33% and evades glucuronidation.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Tetrazolün logP değeri ~2.1 iken karboksilik asidinki ~0.8'dir. ΔlogP ≈ +1.3 olması ilacın biyolojik membranlardan geçişini 10 kat artırır. Ayrıca açil glukuronid oluşumunu önleyerek klerensi stabilize eder.\",\"ar\":\"صحيح! تبلغ logP للتترازول ~2.1 مقابل ~0.8 للكربوكسيل؛ هذا الفارق (+1.3) يرفع النفاذية المعوية 10 أضعاف ويمنع تكوين غلوكورونيدات الأسيل السامة.\",\"en\":\"Correct! Tetrazole's logP (~2.1) exceeds -COOH (~0.8) by +1.3 log units, yielding a 10-fold permeability boost while eliminating reactive acyl glucuronide formation.\"}},{\"id\":\"opt-4b\",\"text\":{\"tr\":\"Tetrazol kana geçtiği anda çöker ve damarları tıkayarak tansiyonu mekanik olarak düşürür.\",\"ar\":\"يترسب التترازول فور دخوله الدم فيسد الأوعية خافضاً الضغط ميكانيكياً.\",\"en\":\"Tetrazole precipitates in plasma upon absorption, mechanically obstructing arterioles to lower blood pressure.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Damar tıkanıklığı yanılgısı: Losartan tamamen çözünür bir oral tablettir; mekanik tıkaç değil biyokimyasal AT1 reseptör antagonistidir.\",\"ar\":\"خطأ الانسداد الميكانيكي: لوسارتان دواء ذواب بالكامل ولا يترسب في الأوعية؛ تأثيره ناتج عن إحصار مستقبلات AT1.\",\"en\":\"Vessel occlusion misconception: Losartan is fully soluble; it lowers pressure pharmacologically via AT1 receptor blockade, not arterial plugging.\"}},{\"id\":\"opt-4c\",\"text\":{\"tr\":\"logP'nin artması ilacın idrara geçişini imkansız kılarak vücutta ömür boyu kalmasını sağlar.\",\"ar\":\"تمنع زيادة logP طرح الدواء في البول نهائياً ليبقى في الجسم مدى الحياة.\",\"en\":\"Elevated logP completely prevents renal excretion, trapping the drug in the body indefinitely.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Ömür boyu tutulum yanılgısı: Losartan hepatik CYP oksidasyonuyla karboksilik asit metabolitine (EXP-3174) çevrilir ve safra/idrarla dengeli atılır.\",\"ar\":\"خطأ البقاء الأبدي: يُستقلب لوسارتان كبدياً ليعطي مستقلب EXP-3174 الفعال ويُطرح بتوازن عبر البول والصفراء.\",\"en\":\"Indefinite retention misconception: Losartan is metabolized by CYP2C9 to active metabolite EXP-3174 and cleared via biliary and renal routes.\"}}]},\"technicalTerms\":[{\"term\":\"lipofilisite farkı (ΔlogP)\",\"arContext\":\"فارق الانحلال الدهني (ΔlogP)\"},{\"term\":\"açil glukuronidasyonu\",\"arContext\":\"اقتران أسيل غلوكورونيد\"}],\"hints\":[{\"tr\":\"LogP logaritmik bir ölçektir: 1 birimlik artış lipofilisitede 10 kat artış demektir.\",\"ar\":\"مقياس logP لوغاريتمي: زيادة وحدة واحدة تعني تضاعف الانحلال بالدهن 10 مرات.\",\"en\":\"LogP is logarithmic: a 1.3-unit increase corresponds to over a 10-fold increase in lipid partitioning.\"},{\"tr\":\"Karboksilik asit taşıyan öncünün biyoyararlanımı <%3 iken, tetrazollü losartanın biyoyararlanımı %33'tür.\",\"ar\":\"قفز التوافر الحيوي من أقل من 3% في طليعة الكربوكسيل إلى 33% في اللوسارتان.\",\"en\":\"Bioavailability jumped from <3% in the carboxylate precursor to 33% in tetrazole-bearing losartan.\"},{\"tr\":\"Tetrazol karboksilatın arginin ile yaptığı iyonik bağı korurken, yüksek lipofilisitesiyle oral emilimi katlar.\",\"ar\":\"يحفظ التترازول الارتباط الأيوني الأساسي مع الأرجنين، رافعاً الامتصاص الفموي بفضل انحلاله الدهني المتفوق.\",\"en\":\"Tetrazole preserves the essential ionic interaction with receptor arginine while boosting oral uptake via superior lipophilicity.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":9}],\"config\":{\"options\":[{\"id\":\"opt-4a\",\"text\":\"Tetrazol AT1 reseptöründeki arginin ile iyonik bağı korurken, 10 kat artan lipofilisitesi sayesinde oral emilimi %3'ten %33'e çıkarır ve metabolik glukuronidasyona direnir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Tetrazolün logP değeri ~2.1 iken karboksilik asidinki ~0.8'dir. ΔlogP ≈ +1.3 olması ilacın biyolojik membranlardan geçişini 10 kat artırır. Ayrıca açil glukuronid oluşumunu önleyerek klerensi stabilize eder.\"},{\"id\":\"opt-4b\",\"text\":\"Tetrazol kana geçtiği anda çöker ve damarları tıkayarak tansiyonu mekanik olarak düşürür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Damar tıkanıklığı yanılgısı: Losartan tamamen çözünür bir oral tablettir; mekanik tıkaç değil biyokimyasal AT1 reseptör antagonistidir.\"},{\"id\":\"opt-4c\",\"text\":\"logP'nin artması ilacın idrara geçişini imkansız kılarak vücutta ömür boyu kalmasını sağlar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Ömür boyu tutulum yanılgısı: Losartan hepatik CYP oksidasyonuyla karboksilik asit metabolitine (EXP-3174) çevrilir ve safra/idrarla dengeli atılır.\"}],\"revealedOutcome\":{\"tr\":\"Tetrazol AT1 reseptöründeki arginin ile iyonik bağı korurken, 10 kat artan lipofilisitesi sayesinde oral emilimi %3'ten %33'e çıkarır ve metabolik glukuronidasyona direnir.\",\"ar\":\"يحفظ التترازول الرابطة الأيونية مع أرجنين المستقبل AT1، وبفضل زيادة الانحلال بالدهن 10 أضعاف يقفز الامتصاص من 3% إلى 33% ويقاوم الاقتران بالغلوبيولين.\",\"en\":\"Tetrazole preserves the essential ionic salt bridge with receptor arginine while its 10-fold lipophilicity gain multiplies bioavailability from 3% to 33% and evades glucuronidation.\"},\"explanation\":{\"tr\":\"Doğru! Tetrazolün logP değeri ~2.1 iken karboksilik asidinki ~0.8'dir. ΔlogP ≈ +1.3 olması ilacın biyolojik membranlardan geçişini 10 kat artırır. Ayrıca açil glukuronid oluşumunu önleyerek klerensi stabilize eder.\",\"ar\":\"صحيح! تبلغ logP للتترازول ~2.1 مقابل ~0.8 للكربوكسيل؛ هذا الفارق (+1.3) يرفع النفاذية المعوية 10 أضعاف ويمنع تكوين غلوكورونيدات الأسيل السامة.\",\"en\":\"Correct! Tetrazole's logP (~2.1) exceeds -COOH (~0.8) by +1.3 log units, yielding a 10-fold permeability boost while eliminating reactive acyl glucuronide formation.\"}}},{\"id\":\"mc-mod3-les2-step-05\",\"stage\":\"interactive_artifact\",\"stageIndex\":5,\"type\":\"sar_explorer\",\"widgetType\":\"SarExplorer\",\"title\":{\"tr\":\"İnteraktif Laboratuvar: Losartan Asidik İzoster Kaşifi\",\"ar\":\"مختبر تفاعلي: مستكشف إيزوستيرات لوسارتان الحامضية\",\"en\":\"Interactive Lab: Losartan Acidic Bioisostere Explorer\"},\"prompt\":{\"tr\":\"Losartan bifenil iskeletinde R1 pozisyonundaki asidik fonksiyonel grubu değiştirin. Hedef: pKa < 5.0 ve logP > 1.8 sağlayarak oral biyoyararlanımı ve reseptör afinitesini optimize edin.\",\"ar\":\"غير المجموعة الوظيفية الحامضية في الموضع R1 لهيكل لوسارتان. الهدف: تحقيق pKa < 5.0 و logP > 1.8 لتحسين التوافر الحيوي الفموي والألفة نحو المستقبل.\",\"en\":\"Modify the acidic functional group at position R1 of the losartan scaffold. Goal: Achieve pKa < 5.0 and logP > 1.8 to maximize oral bioavailability and target affinity.\"},\"predictThenReveal\":false,\"config\":{\"scaffoldName\":\"Bifenil AT1 Reseptör Bloker İskeleti (Losartan Core)\",\"scaffoldDescription\":\"Bifenil iskeletinde orto-konumundaki asidik grubu biyoizosterik olarak optimize edin.\",\"baseLogP\":0.8,\"basePka\":4.2,\"baseAffinityNm\":120,\"positions\":[{\"positionName\":\"R1 (Orto-Asidik Pozisyon)\",\"defaultOptionId\":\"opt_cooh\",\"options\":[{\"id\":\"opt_cooh\",\"name\":\"Karboksilik Asit (-COOH)\",\"structureSnippet\":\"-COOH\",\"deltaLogP\":0,\"deltaPka\":0,\"affinityMultiplier\":1,\"toxicityRisk\":\"low\"},{\"id\":\"opt_tetrazole\",\"name\":\"1H-Tetrazol Halkası\",\"structureSnippet\":\"-CN4H\",\"deltaLogP\":1.3,\"deltaPka\":0.6,\"affinityMultiplier\":12,\"toxicityRisk\":\"low\"},{\"id\":\"opt_ester\",\"name\":\"Metil Ester (-COOCH3)\",\"structureSnippet\":\"-COOCH3\",\"deltaLogP\":1.8,\"deltaPka\":8,\"affinityMultiplier\":0.05,\"toxicityRisk\":\"low\"},{\"id\":\"opt_sulfonamide\",\"name\":\"Açilsülfonamid (-CONHSO2CH3)\",\"structureSnippet\":\"-CONHSO2CH3\",\"deltaLogP\":0.9,\"deltaPka\":0.3,\"affinityMultiplier\":8,\"toxicityRisk\":\"low\"}]}],\"targetGoal\":{\"description\":\"logP > 1.8 ve Kd <= 15 nM ile yüksek oral biyoyararlanım ve güçlü AT1 blokajı sağlayın.\",\"minLogP\":1.8,\"maxLogP\":2.5,\"maxAffinityNm\":15,\"targetOptionIds\":[\"opt_tetrazole\"]},\"explanation\":\"1H-tetrazol halkası karboksilatın asidik pKa'sını (~4.8) korurken lipofilisiteyi artırır (logP 0.8 -> 2.1), desolvasyon cezasını azaltır ve oral biyoyararlanımı %3'ten %33'e fırlatır.\",\"source\":{\"file\":\"Biyoizosterizm.pdf\",\"page\":9}},\"technicalTerms\":[{\"term\":\"bifenil iskeleti\",\"arContext\":\"هيكل ثنائي الفينيل (biphenyl core)\"},{\"term\":\"AT1 reseptör blokeri\",\"arContext\":\"حاصر مستقبلات AT1\"}],\"hints\":[{\"tr\":\"Metil ester nötrdür; asidik proton taşımadığından AT1 reseptör afinitesini yok eder.\",\"ar\":\"إستر الميثيل غير حامضي؛ فغياب الشحنة السالبة يدمر الألفة لمستقبل AT1 تماماً.\",\"en\":\"The methyl ester lacks an acidic proton, abolishing the ionic salt bridge and destroying affinity.\"},{\"tr\":\"Karboksilik asit çok polardır (logP 0.8); oral emilimi düşüktür.\",\"ar\":\"حمض الكربوكسيل شديد القطبية (logP 0.8)، مما يحد من امتصاصه الفموي.\",\"en\":\"Carboxylic acid is too polar (logP 0.8), suffering from poor membrane permeability.\"},{\"tr\":\"1H-tetrazol seçeneğini takın: logP 2.1'e çıkar ve Kd 10 nM seviyesine iner.\",\"ar\":\"اختر 1H-tetrazole: يقفز logP إلى 2.1 وتهبط Kd إلى 10 nM محققة الهدف.\",\"en\":\"Install 1H-tetrazole: logP reaches 2.1 and Kd drops to 10 nM, satisfying all target criteria.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":9}],\"widget\":{\"type\":\"SarExplorer\",\"config\":{\"scaffoldName\":\"Bifenil AT1 Reseptör Bloker İskeleti (Losartan Core)\",\"scaffoldDescription\":\"Bifenil iskeletinde orto-konumundaki asidik grubu biyoizosterik olarak optimize edin.\",\"baseLogP\":0.8,\"basePka\":4.2,\"baseAffinityNm\":120,\"positions\":[{\"positionName\":\"R1 (Orto-Asidik Pozisyon)\",\"defaultOptionId\":\"opt_cooh\",\"options\":[{\"id\":\"opt_cooh\",\"name\":\"Karboksilik Asit (-COOH)\",\"structureSnippet\":\"-COOH\",\"deltaLogP\":0,\"deltaPka\":0,\"affinityMultiplier\":1,\"toxicityRisk\":\"low\"},{\"id\":\"opt_tetrazole\",\"name\":\"1H-Tetrazol Halkası\",\"structureSnippet\":\"-CN4H\",\"deltaLogP\":1.3,\"deltaPka\":0.6,\"affinityMultiplier\":12,\"toxicityRisk\":\"low\"},{\"id\":\"opt_ester\",\"name\":\"Metil Ester (-COOCH3)\",\"structureSnippet\":\"-COOCH3\",\"deltaLogP\":1.8,\"deltaPka\":8,\"affinityMultiplier\":0.05,\"toxicityRisk\":\"low\"},{\"id\":\"opt_sulfonamide\",\"name\":\"Açilsülfonamid (-CONHSO2CH3)\",\"structureSnippet\":\"-CONHSO2CH3\",\"deltaLogP\":0.9,\"deltaPka\":0.3,\"affinityMultiplier\":8,\"toxicityRisk\":\"low\"}]}],\"targetGoal\":{\"description\":\"logP > 1.8 ve Kd <= 15 nM ile yüksek oral biyoyararlanım ve güçlü AT1 blokajı sağlayın.\",\"minLogP\":1.8,\"maxLogP\":2.5,\"maxAffinityNm\":15,\"targetOptionIds\":[\"opt_tetrazole\"]},\"explanation\":\"1H-tetrazol halkası karboksilatın asidik pKa'sını (~4.8) korurken lipofilisiteyi artırır (logP 0.8 -> 2.1), desolvasyon cezasını azaltır ve oral biyoyararlanımı %3'ten %33'e fırlatır.\",\"source\":{\"file\":\"Biyoizosterizm.pdf\",\"page\":9}}}},{\"id\":\"mc-mod3-les2-step-06\",\"stage\":\"guided_discovery\",\"stageIndex\":6,\"type\":\"guided_discovery\",\"title\":{\"tr\":\"Rehberli Keşif: Fenolik Hidroksil ve Salbütamol Devrimi\",\"ar\":\"استكشاف موجه: الهيدروكسيل الفينولي وثورة السالبوتامول\",\"en\":\"Guided Discovery: Phenolic Hydroxyl & The Salbutamol Leap\"},\"prompt\":{\"tr\":\"Adrenalindeki meta-fenolik -OH grubu COMT enzimiyle hızla metillenerek dakikalar içinde etkisizleşir. Salbütamolde bu -OH yerine hidroksimetil (-CH2OH) konulması etki süresini nasıl saatlere uzatır?\",\"ar\":\"تتخرب مجموعة -OH الفينولية في الأدرينالين بأنزيم COMT خلال دقائق. كيف يؤدي استبدالها بـ hydroxymethyl (-CH2OH) في السالبوتامول إلى إطالة التأثير لساعات؟\",\"en\":\"Adrenaline's meta-phenolic -OH is rapidly methylated by COMT within minutes. In salbutamol, how does swapping this -OH for hydroxymethyl (-CH2OH) extend bronchodilator duration from minutes to hours?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-6a\",\"text\":{\"tr\":\"Hidroksimetil grubu beta-2 reseptör serini ile hidrojen bağını korur; ancak katekol geometrisi bozulduğu için COMT enzimi substrat olarak tanıyamaz.\",\"ar\":\"تحفظ مجموعة هيدروكسي ميثيل الرابطة الهيدروجينية مع سيرين مستقبل بيتا-2؛ لكن تشوه هندسة الكاتيكول يعطل تعرف أنزيم COMT عليها.\",\"en\":\"The hydroxymethyl group donates an essential H-bond to beta-2 receptor serine, but destroys catechol geometry so COMT cannot recognize it.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika bir keşif! Adrenalin COMT enzimi tarafından saniyeler içinde inaktive edilir. Salbütamoldeki -CH2OH grubu araya 1 karbon sokarak katekol cebi uyumunu bozar; COMT enzimi metilasyon yapamaz ama beta-2 reseptör H-bağı aynen korunur (Slide 10).\",\"ar\":\"اكتشاف رائع! يثبط COMT الأدرينالين خلال ثوانٍ. تفصل ذرة الكربون الإضافية في -CH2OH زاوية التفاعل مع أنزيم COMT فيفشل في تثبيطه، بينما يبقى الارتباط الهيدروجيني مع مستقبل بيتا-2 سليماً.\",\"en\":\"Superb discovery! Adrenaline is cleared rapidly by COMT. Adding a methylene spacer (-CH2OH) disrupts catechol recognition by COMT while preserving H-bonding with beta-2 receptor serine.\"}},{\"id\":\"opt-6b\",\"text\":{\"tr\":\"-CH2OH grubu COMT enzimini kovalent olarak patlatıp karaciğeri yok eder.\",\"ar\":\"تفجر مجموعة -CH2OH أنزيم COMT تساهمياً مخربة الكبد.\",\"en\":\"The -CH2OH group violently detonates COMT enzymes, obliterating liver tissue.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Enzim patlaması yanılgısı: Salbütamol son derece güvenli bir astım ilacıdır; enzim yıkımı değil sterik substrat uyuşmazlığı vardır.\",\"ar\":\"خطأ التخريب: السالبوتامول دواء آمن وموجه؛ الآلية تعتمد على عدم التعرف الفراغي وليس تفجير الأنزيم.\",\"en\":\"Enzyme explosion misconception: Salbutamol is a safe selective bronchodilator; it evades COMT via steric evasion, not enzymatic lysis.\"}},{\"id\":\"opt-6c\",\"text\":{\"tr\":\"Salbütamol kovalent bir bağla akciğer bronşlarına ömür boyu kaynaklanır.\",\"ar\":\"يلتحم السالبوتامول برابطة تساهمية دائمة مدى الحياة مع القصبات الهوائية.\",\"en\":\"Salbutamol welds permanently into bronchial tissue through irreversible covalent bonds.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kovalent kaynak yanılgısı: Salbütamol geri dönüşümlü bir beta-2 agonistidir; etki süresi kovalent bağlanmadan değil COMT direncinden uzar.\",\"ar\":\"خطأ الارتباط التساهمي: يرتبط السالبوتامول بروابط غير تساهمية عكوسة؛ وطول المفعول ينبع من مقاومة الاستقلاب.\",\"en\":\"Covalent binding misconception: Salbutamol binds reversibly via non-covalent forces; its extended duration arises from metabolic COMT resistance.\"}}]},\"technicalTerms\":[{\"term\":\"katekol-O-metiltransferaz (COMT)\",\"arContext\":\"أنزيم COMT\"},{\"term\":\"hidroksimetil biyoizosteri\",\"arContext\":\"إيزوستير هيدروكسي ميثيل\"}],\"hints\":[{\"tr\":\"COMT enziminin metilasyon yapabilmesi için yan yana iki fenolik -OH (katekol) grubu görmesi şarttır.\",\"ar\":\"يشترط أنزيم COMT وجود مجموعتي فينول متجاورتين (كاتيكول) ليرتبط وينقل الميثيل.\",\"en\":\"COMT strictly requires an ortho-dihydroxy benzene (catechol) architecture to methylate.\"},{\"tr\":\"Hidroksimetil (-CH2OH) grubunda oksijen aromatik halkaya doğrudan bağlı değildir; arada bir karbon vardır.\",\"ar\":\"في مجموعة هيدروكسي ميثيل (-CH2OH)، يفصل كربون أليفاتي بين الأكسجين والحلقة العطرية.\",\"en\":\"In hydroxymethyl (-CH2OH), an aliphatic carbon separates the oxygen from the aromatic ring.\"},{\"tr\":\"Bu aralık COMT enzimini engeller, ancak beta-2 reseptör serini ile hidrojen bağı kurmaya devam eder.\",\"ar\":\"تمنع هذه المسافة أنزيم COMT بينما تحافظ على الرابطة الهيدروجينية مع سيرين مستقبل بيتا-2.\",\"en\":\"This spacer frustrates COMT binding while preserving the essential hydrogen bond with receptor serine.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":10}],\"config\":{\"options\":[{\"id\":\"opt-6a\",\"text\":\"Hidroksimetil grubu beta-2 reseptör serini ile hidrojen bağını korur; ancak katekol geometrisi bozulduğu için COMT enzimi substrat olarak tanıyamaz.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika bir keşif! Adrenalin COMT enzimi tarafından saniyeler içinde inaktive edilir. Salbütamoldeki -CH2OH grubu araya 1 karbon sokarak katekol cebi uyumunu bozar; COMT enzimi metilasyon yapamaz ama beta-2 reseptör H-bağı aynen korunur (Slide 10).\"},{\"id\":\"opt-6b\",\"text\":\"-CH2OH grubu COMT enzimini kovalent olarak patlatıp karaciğeri yok eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Enzim patlaması yanılgısı: Salbütamol son derece güvenli bir astım ilacıdır; enzim yıkımı değil sterik substrat uyuşmazlığı vardır.\"},{\"id\":\"opt-6c\",\"text\":\"Salbütamol kovalent bir bağla akciğer bronşlarına ömür boyu kaynaklanır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kovalent kaynak yanılgısı: Salbütamol geri dönüşümlü bir beta-2 agonistidir; etki süresi kovalent bağlanmadan değil COMT direncinden uzar.\"}],\"revealedOutcome\":{\"tr\":\"Hidroksimetil grubu beta-2 reseptör serini ile hidrojen bağını korur; ancak katekol geometrisi bozulduğu için COMT enzimi substrat olarak tanıyamaz.\",\"ar\":\"تحفظ مجموعة هيدروكسي ميثيل الرابطة الهيدروجينية مع سيرين مستقبل بيتا-2؛ لكن تشوه هندسة الكاتيكول يعطل تعرف أنزيم COMT عليها.\",\"en\":\"The hydroxymethyl group donates an essential H-bond to beta-2 receptor serine, but destroys catechol geometry so COMT cannot recognize it.\"},\"explanation\":{\"tr\":\"Harika bir keşif! Adrenalin COMT enzimi tarafından saniyeler içinde inaktive edilir. Salbütamoldeki -CH2OH grubu araya 1 karbon sokarak katekol cebi uyumunu bozar; COMT enzimi metilasyon yapamaz ama beta-2 reseptör H-bağı aynen korunur (Slide 10).\",\"ar\":\"اكتشاف رائع! يثبط COMT الأدرينالين خلال ثوانٍ. تفصل ذرة الكربون الإضافية في -CH2OH زاوية التفاعل مع أنزيم COMT فيفشل في تثبيطه، بينما يبقى الارتباط الهيدروجيني مع مستقبل بيتا-2 سليماً.\",\"en\":\"Superb discovery! Adrenaline is cleared rapidly by COMT. Adding a methylene spacer (-CH2OH) disrupts catechol recognition by COMT while preserving H-bonding with beta-2 receptor serine.\"}}},{\"id\":\"mc-mod3-les2-step-07\",\"stage\":\"formal_explanation\",\"stageIndex\":7,\"type\":\"formal_explanation\",\"title\":{\"tr\":\"Formal Farmakoloji: PABA vs Sülfanilamid Antimetaboliti\",\"ar\":\"الدوائيات المنهجية: PABA مقابل سلفانيلاميد كمضاد استقلاب\",\"en\":\"Formal Pharmacology: PABA vs Sulfanilamide Antimetabolite\"},\"prompt\":{\"tr\":\"Bakteriler folik asit sentezinde p-aminobenzoik asit (PABA) kullanır. Sülfanilamid (-SO2NH2), PABA'nın (-COOH) non-klasik biyoizosteri olarak dihidropteroat sentaz enzimini hangi mekanizmayla felç eder?\",\"ar\":\"تستخدم الجراثيم PABA لبناء حمض الفوليك. كيف يشل السلفانيلاميد (-SO2NH2) كمتشابه غير كلاسيكي لحمض الكربوكسيل أنزيم dihydropteroate synthase؟\",\"en\":\"Bacteria require p-aminobenzoic acid (PABA) to synthesize folic acid. How does sulfanilamide (-SO2NH2), acting as a non-classical bioisostere of -COOH, competitively paralyze dihydropteroate synthase?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-7a\",\"text\":{\"tr\":\"Sülfonamid grubu benzer geometrik boyuta ve polariteye sahiptir; enzimin aktif cebine yarışmalı oturur ancak pteridin halkasına bağlanamaz ve sahte ürün sentezi durdurur.\",\"ar\":\"تمتلك مجموعة السلفوناميد حجماً وقطبية مشابهة؛ فترسو تنافسياً في جيب الأنزيم مانعة إتمام اصطناع الفولات وتوقف تكاثر البكتيريا.\",\"en\":\"The sulfonamide group shares matching geometry and charge distribution, competitively docking into the active site while aborting downstream folate condensation.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Sülfanilamidin -SO2NH2 grubu PABA'nın -COOH grubu ile tetrahedral geometri ve yük polaritesi açısından non-klasik biyoizosteriktir. Dihidropteroat sentazı yarışmalı bloke ederek bakteriyostatik etki sağlar (Slide 15).\",\"ar\":\"صحيح! تشابه مجموعة -SO2NH2 مجموعة -COOH فراغياً وقطبياً؛ فتحتل الموقع الفعال وتوقف اصطناع الفوليك جاعلة البكتيريا عاجزة عن الانقسام.\",\"en\":\"Correct! The -SO2NH2 group is a non-classical bioisostere of -COOH, mimicking geometry and charge distribution to competitively inhibit dihydropteroate synthase.\"}},{\"id\":\"opt-7b\",\"text\":{\"tr\":\"Sülfanilamid bakteri hücresini fiziksel olarak kurşun geçirmez bir zırhla kaplar.\",\"ar\":\"يغلف السلفانيلاميد الخلية البكتيرية بدرع مضاد للرصاص يمنع حركتها.\",\"en\":\"Sulfanilamide physically coats bacterial walls with bulletproof armor.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Fiziksel zırh yanılgısı: Sülfanilamid metabolik bir enzim inhibitörüdür, hücre duvarı zırhı değildir.\",\"ar\":\"خطأ الدرع الفيزيائي: السلفانيلاميد مثبط أنزيمي استقلابي وليس درعاً جدارياً.\",\"en\":\"Armor misconception: Sulfanilamide is an intracellular antimetabolite enzyme inhibitor, not a physical surface coating.\"}},{\"id\":\"opt-7c\",\"text\":{\"tr\":\"Sülfanilamid insan DNA'sını hedef alarak tüm vücut hücrelerini yok eder.\",\"ar\":\"يستهدف السلفانيلاميد DNA البشري مدمراً كافة خلايا الجسم.\",\"en\":\"Sulfanilamide targets human host DNA, obliterating mammalian cells.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Konak toksisitesi yanılgısı: İnsanlar folik asidi diyetle hazır alır, de novo sentezlemez; bu yüzden sülfamitler selektif toksiktir.\",\"ar\":\"خطأ سمية المضيف: يحصل الإنسان على حمض الفوليك جاهزاً من الغذاء ولا يصنعه؛ لذا يتميز السلفانيلاميد بسمية انتقائية ممتازة.\",\"en\":\"Host toxicity misconception: Humans obtain folate preformed from diet lacking dihydropteroate synthase; sulfonamides exhibit excellent selective toxicity.\"}}]},\"technicalTerms\":[{\"term\":\"dihidropteroat sentaz\",\"arContext\":\"أنزيم دي هيدروبتيروات سنثاز\"},{\"term\":\"sülfonamid izosteri\",\"arContext\":\"إيزوستير السلفوناميد\"}],\"hints\":[{\"tr\":\"PABA: p-NH2-C6H4-COOH. Sülfanilamid: p-NH2-C6H4-SO2NH2.\",\"ar\":\"قارن الصيغتين: PABA ينتهي بـ -COOH، بينما السلفانيلاميد ينتهي بـ -SO2NH2.\",\"en\":\"Compare structures: PABA bears a -COOH, whereas sulfanilamide bears a -SO2NH2 group.\"},{\"tr\":\"-SO2NH2 grubu -COOH ile benzer atomlar arası mesafeye ve negatif yük polaritesine sahiptir.\",\"ar\":\"تمتلك مجموعة -SO2NH2 أبعاداً فراغية وقطبية شحنة مماثلة لمجموعة -COOH.\",\"en\":\"-SO2NH2 mimics the interatomic distance and electronegative charge density of -COOH.\"},{\"tr\":\"Sülfanilamid enzimi PABA gibi aldatır ve aktif cebi tıkayarak folik asit sentezini yarışmalı olarak durdurur.\",\"ar\":\"يخدع السلفانيلاميد الأنزيم كبديل لـ PABA، محتلاً الجيب ومعطلاً بناء الفوليك تنافسياً.\",\"en\":\"Sulfanilamide acts as an antimetabolite decoy, competitively blocking PABA utilization in folate synthesis.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":15}],\"config\":{\"options\":[{\"id\":\"opt-7a\",\"text\":\"Sülfonamid grubu benzer geometrik boyuta ve polariteye sahiptir; enzimin aktif cebine yarışmalı oturur ancak pteridin halkasına bağlanamaz ve sahte ürün sentezi durdurur.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Sülfanilamidin -SO2NH2 grubu PABA'nın -COOH grubu ile tetrahedral geometri ve yük polaritesi açısından non-klasik biyoizosteriktir. Dihidropteroat sentazı yarışmalı bloke ederek bakteriyostatik etki sağlar (Slide 15).\"},{\"id\":\"opt-7b\",\"text\":\"Sülfanilamid bakteri hücresini fiziksel olarak kurşun geçirmez bir zırhla kaplar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Fiziksel zırh yanılgısı: Sülfanilamid metabolik bir enzim inhibitörüdür, hücre duvarı zırhı değildir.\"},{\"id\":\"opt-7c\",\"text\":\"Sülfanilamid insan DNA'sını hedef alarak tüm vücut hücrelerini yok eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Konak toksisitesi yanılgısı: İnsanlar folik asidi diyetle hazır alır, de novo sentezlemez; bu yüzden sülfamitler selektif toksiktir.\"}],\"revealedOutcome\":{\"tr\":\"Sülfonamid grubu benzer geometrik boyuta ve polariteye sahiptir; enzimin aktif cebine yarışmalı oturur ancak pteridin halkasına bağlanamaz ve sahte ürün sentezi durdurur.\",\"ar\":\"تمتلك مجموعة السلفوناميد حجماً وقطبية مشابهة؛ فترسو تنافسياً في جيب الأنزيم مانعة إتمام اصطناع الفولات وتوقف تكاثر البكتيريا.\",\"en\":\"The sulfonamide group shares matching geometry and charge distribution, competitively docking into the active site while aborting downstream folate condensation.\"},\"explanation\":{\"tr\":\"Doğru! Sülfanilamidin -SO2NH2 grubu PABA'nın -COOH grubu ile tetrahedral geometri ve yük polaritesi açısından non-klasik biyoizosteriktir. Dihidropteroat sentazı yarışmalı bloke ederek bakteriyostatik etki sağlar (Slide 15).\",\"ar\":\"صحيح! تشابه مجموعة -SO2NH2 مجموعة -COOH فراغياً وقطبياً؛ فتحتل الموقع الفعال وتوقف اصطناع الفوليك جاعلة البكتيريا عاجزة عن الانقسام.\",\"en\":\"Correct! The -SO2NH2 group is a non-classical bioisostere of -COOH, mimicking geometry and charge distribution to competitively inhibit dihydropteroate synthase.\"}}},{\"id\":\"mc-mod3-les2-step-08\",\"stage\":\"concept_check\",\"stageIndex\":8,\"type\":\"concept_check\",\"title\":{\"tr\":\"Kavram Kontrolü: İntestinal pH ve İyonizasyon Paradoksu\",\"ar\":\"فحص المفاهيم: درجة حموضة الأمعاء ومفارقة التأين\",\"en\":\"Concept Check: Intestinal pH & The Ionization Paradox\"},\"prompt\":{\"tr\":\"İnce bağırsak lümeninde (pH 6.5) karboksilik asitli bir ilaç (pKa 4.2) %99.5 oranında iyonizedir. Tetrazol analogu (pKa 4.9) ise %97.5 iyonizedir. Tetrazolün membran geçirgenliği neden yine de katbekat üstündür?\",\"ar\":\"عند pH الأمعاء 6.5، يتأين حمض الكربوكسيل (pKa 4.2) بنسبة 99.5%، بينما يتأين التترازول (pKa 4.9) بنسبة 97.5%. لماذا تفوق نفاذية التترازول نظيره بأضعاف مضاعفة؟\",\"en\":\"At intestinal pH 6.5, carboxylic acid (pKa 4.2) is 99.5% ionized, while tetrazole (pKa 4.9) is 97.5% ionized. Why does tetrazole still display drastically superior membrane flux?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-8a\",\"text\":{\"tr\":\"Tetrazolün hem nötr formu daha lipofiliktir (ΔlogP ~+1.3) hem de anyonik formunun hidrasyon enerjisi çok düşüktür; zardan geçiş desolvasyon bariyeri önemsizleşir.\",\"ar\":\"يمتلك التترازول انحلالاً دهنياً أعلى (ΔlogP ~+1.3) وطاقة إماهة شاردية منخفضة جداً؛ مما يجعل حاجز نزع الماء لعبور الغشاء ضئيلاً للغاية.\",\"en\":\"Tetrazole exhibits higher intrinsic lipophilicity (ΔlogP ~+1.3) and a vastly lower ionic desolvation penalty, slashing the thermodynamic barrier for membrane partitioning.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz çıkarım! %97.5 iyonize olması %2.5 nötr form demektir (karboksilik asidin 5 katı serbest nötr fraksiyon). Ayrıca delokalize tetrazolat anyonunun desolvasyon cezası çok düşük olduğundan anyonik halde bile zardan pasif sızabilir.\",\"ar\":\"استنتاج متقن! نسبة تأين 97.5% تعني وجود 2.5% من الشكل النيتروني غير المشحون (5 أضعاف الكربوكسيل). كما أن الشحنة المشتتة تقلل طاقة نزع الماء مما يسمح بنفاذية نفاثة.\",\"en\":\"Superb deduction! 97.5% ionization leaves 2.5% neutral species (5x more than carboxylate's 0.5%). Furthermore, diffuse charge delocalization dramatically lowers the desolvation barrier.\"}},{\"id\":\"opt-8b\",\"text\":{\"tr\":\"İyonize olan moleküller lipit zarlardan yüksüz moleküllere göre 1000 kat daha hızlı geçer.\",\"ar\":\"تعبر الجزيئات المتأينة الأغشية الدهنية بسرعة تفوق الجزيئات غير المشحونة بألف مرة.\",\"en\":\"Ionized species penetrate lipid bilayers 1000 times faster than neutral lipophilic molecules.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"İyon difüzyon yanılgısı: İyonik yükler hidrofobik lipit çift katmanından neredeyse hiç geçemez; desolvasyon bariyeri devasadır.\",\"ar\":\"خطأ نفاذية الأيونات: تعجز الشحنات عن عبور صلب الغشاء الدهني اللاقطبي؛ الحقيقة أن الشكل غير المتأين هو المسؤول عن العبور.\",\"en\":\"Ion diffusion misconception: Hydrophobic lipid bilayers strongly repel charged species due to immense Born desolvation energy.\"}},{\"id\":\"opt-8c\",\"text\":{\"tr\":\"pH 6.5'te tetrazol kovalent bağlarını parçalayarak gaz haline gelir ve buharlaşır.\",\"ar\":\"يتفكك التترازول عند pH 6.5 إلى غاز يتبخر عبر جدار الأمعاء.\",\"en\":\"At pH 6.5, tetrazole fragments into volatile gas that evaporates across the gut mucosa.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Buharlaşma yanılgısı: Tetrazol fizyolojik sıvılarda stabil, çözünür bir katıdır; gaza dönüşmez.\",\"ar\":\"خطأ التبخر: التترازول مركب حلقي شديد الثبات ولا يتحول لغاز إطلاقاً.\",\"en\":\"Evaporation misconception: Tetrazole is a chemically stable aromatic heterocycle; it does not fragment into gas.\"}}]},\"technicalTerms\":[{\"term\":\"Henderson-Hasselbalch dengesi\",\"arContext\":\"توازن هندرسون-هاسلبالخ\"},{\"term\":\"nötr fraksiyon emilimi\",\"arContext\":\"امتصاص الجزء غير المتأين\"}],\"hints\":[{\"tr\":\"Henderson-Hasselbalch eşitliğini düşünün: pH - pKa farkına göre nötr fraksiyonu hesaplayın.\",\"ar\":\"فكر في معادلة هندرسون-هاسلبالخ لحساب نسبة الجزء غير المتأين عند pH 6.5.\",\"en\":\"Apply Henderson-Hasselbalch: calculate the non-ionized fraction at pH 6.5.\"},{\"tr\":\"Karboksilik asitte nötr fraksiyon %0.5 iken, tetrazolda nötr fraksiyon %2.5'tir (5 kat daha fazla).\",\"ar\":\"الجزء غير المتأين في الكربوكسيل 0.5%، بينما في التترازول يبلغ 2.5% (أعلى بـ 5 أضعاف).\",\"en\":\"Non-ionized fraction: 0.5% for carboxylate vs 2.5% for tetrazole (a 5-fold surplus).\"},{\"tr\":\"Tetrazolün hem nötr fraksiyonu 5 kat fazladır hem de logP değeri 10 kat daha yüksektir; bu iki faktör zardan geçişi patlatır.\",\"ar\":\"يمتلك التترازول جزءاً غير متأين أعلى بـ 5 أضعاف مع انحلال دهني أعلى بـ 10 أضعاف، مما يضاعف الامتصاص.\",\"en\":\"A 5-fold higher non-ionized fraction combined with a 10-fold higher intrinsic logP drives dramatic membrane flux.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":9}],\"config\":{\"options\":[{\"id\":\"opt-8a\",\"text\":\"Tetrazolün hem nötr formu daha lipofiliktir (ΔlogP ~+1.3) hem de anyonik formunun hidrasyon enerjisi çok düşüktür; zardan geçiş desolvasyon bariyeri önemsizleşir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz çıkarım! %97.5 iyonize olması %2.5 nötr form demektir (karboksilik asidin 5 katı serbest nötr fraksiyon). Ayrıca delokalize tetrazolat anyonunun desolvasyon cezası çok düşük olduğundan anyonik halde bile zardan pasif sızabilir.\"},{\"id\":\"opt-8b\",\"text\":\"İyonize olan moleküller lipit zarlardan yüksüz moleküllere göre 1000 kat daha hızlı geçer.\",\"isCorrect\":false,\"misconceptionFeedback\":\"İyon difüzyon yanılgısı: İyonik yükler hidrofobik lipit çift katmanından neredeyse hiç geçemez; desolvasyon bariyeri devasadır.\"},{\"id\":\"opt-8c\",\"text\":\"pH 6.5'te tetrazol kovalent bağlarını parçalayarak gaz haline gelir ve buharlaşır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Buharlaşma yanılgısı: Tetrazol fizyolojik sıvılarda stabil, çözünür bir katıdır; gaza dönüşmez.\"}],\"revealedOutcome\":{\"tr\":\"Tetrazolün hem nötr formu daha lipofiliktir (ΔlogP ~+1.3) hem de anyonik formunun hidrasyon enerjisi çok düşüktür; zardan geçiş desolvasyon bariyeri önemsizleşir.\",\"ar\":\"يمتلك التترازول انحلالاً دهنياً أعلى (ΔlogP ~+1.3) وطاقة إماهة شاردية منخفضة جداً؛ مما يجعل حاجز نزع الماء لعبور الغشاء ضئيلاً للغاية.\",\"en\":\"Tetrazole exhibits higher intrinsic lipophilicity (ΔlogP ~+1.3) and a vastly lower ionic desolvation penalty, slashing the thermodynamic barrier for membrane partitioning.\"},\"explanation\":{\"tr\":\"Kusursuz çıkarım! %97.5 iyonize olması %2.5 nötr form demektir (karboksilik asidin 5 katı serbest nötr fraksiyon). Ayrıca delokalize tetrazolat anyonunun desolvasyon cezası çok düşük olduğundan anyonik halde bile zardan pasif sızabilir.\",\"ar\":\"استنتاج متقن! نسبة تأين 97.5% تعني وجود 2.5% من الشكل النيتروني غير المشحون (5 أضعاف الكربوكسيل). كما أن الشحنة المشتتة تقلل طاقة نزع الماء مما يسمح بنفاذية نفاثة.\",\"en\":\"Superb deduction! 97.5% ionization leaves 2.5% neutral species (5x more than carboxylate's 0.5%). Furthermore, diffuse charge delocalization dramatically lowers the desolvation barrier.\"}}},{\"id\":\"mc-mod3-les2-step-09\",\"stage\":\"application\",\"stageIndex\":9,\"type\":\"clinical_vignette\",\"title\":{\"tr\":\"Klinik Vaka: ARB'lerde Açil Glukuronidasyon Toksisitesinden Kaçış\",\"ar\":\"حالة سريرية: تفادي سمية غلوكورونيدات الأسيل في مركبات ARB\",\"en\":\"Clinical Vignette: Evading Acyl Glucuronide Toxicity in ARBs\"},\"prompt\":{\"tr\":\"Karboksilik asit taşıyan NSAİİ'ler ve ARB öncüleri karaciğerde açil glukuronidlere dönüşerek toksik reaktif metabolitler oluşturur. Losartan ve kandesartandaki tetrazol halkası bu toksisiteyi ve hızlı klerensi nasıl önler?\",\"ar\":\"تتحول مضادات الالتهاب الحاملة لـ -COOH في الكبد إلى غلوكورونيدات أسيل سامة تفاعلية. كيف تمنع حلقة التترازول في لوسارتان وكانيديسارتان هذه السمية والتصفية السريعة؟\",\"en\":\"Carboxylic acid drugs frequently form chemically reactive acyl glucuronides, triggering hepatotoxicity. How does the tetrazole ring in ARBs like losartan and candesartan abolish this toxic liability and rapid clearance?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-9a\",\"text\":{\"tr\":\"Tetrazol halkası UGT enzimlerinin açil glukuronidasyon nükleofilik atağına dirençlidir; reaktif elektrofilik esterler oluşturmaz ve yarılanma ömrünü uzatır.\",\"ar\":\"تقاوم حلقة التترازول أنزيمات UGT؛ فلا تشكل إسترات كهرومحبّة سامة وتطيل نصف العمر الحيوي بأمان تام.\",\"en\":\"Tetrazole resists UGT nucleophilic acyl transfer, preventing the generation of reactive electrophilic acyl glucuronides and dramatically extending duration.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kesinlikle doğru! Karboksilik asitler UGT enzimlerince 1-O-açil glukuronidlere çevrilir. Bu metabolitler protein lizini ile kovalent bağ yaparak immünolojik toksisiteye yol açar. Tetrazol halkası ise açil ester oluşturamaz; güvenli ve uzun etki sağlar.\",\"ar\":\"صحيح تماماً! تشكل الأحماض غلوكورونيدات أسيل تفاعلية تتصل تساهمياً ببروتينات الكبد مسببة سمية نسيجية. بينما يعجز التترازول عن تشكيل هذه الروابط الخطرة.\",\"en\":\"Spot on! Carboxylic acids form reactive 1-O-acyl glucuronides that covalently haptenate host proteins. Tetrazole cannot form reactive acyl-linked conjugates, eliminating idiosyncratic toxicity.\"}},{\"id\":\"opt-9b\",\"text\":{\"tr\":\"Tetrazol tüm karaciğer enzimlerini irreversibl felç ederek metabolizmayı tamamen durdurur.\",\"ar\":\"يشل التترازول كافة أنزيمات الكبد معطلاً الاستقلاب في الجسم نهائياً.\",\"en\":\"Tetrazole irreversibly paralyzes all hepatic metabolic enzymes, shutting down liver clearance completely.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Karaciğer felci yanılgısı: ARB'ler güvenli kronik ilaçlardır; hepatik enzim yıkımı yapmazlar.\",\"ar\":\"خطأ شلل الكبد: أدوية ARB آمنة ومدروسة كبدياً؛ ولا تسبب شللاً استقلابياً.\",\"en\":\"Liver failure misconception: ARBs are well-tolerated antihypertensives that undergo controlled CYP oxidation without hepatic damage.\"}},{\"id\":\"opt-9c\",\"text\":{\"tr\":\"Tetrazol karaciğere hiç uğramadan yalnızca tükürük bezleri üzerinden doğrudan atılır.\",\"ar\":\"يطرح التترازول حصراً عبر الغدد اللعابية دون المرور بالكبد نهائياً.\",\"en\":\"Tetrazole bypasses liver transit entirely, being excreted exclusively into saliva.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Tükürük eliminasyon yanılgısı: Losartan karaciğerde kontrollü olarak CYP2C9/3A4 ile aktif karboksilatına (EXP-3174) oksitlenir.\",\"ar\":\"خطأ اللعاب: يمر الدواء بالدوران البابي الكبدي الطبيعي ويطرح بالبول والبراز.\",\"en\":\"Salivary misconception: Losartan undergoes first-pass hepatic oxidation to form active EXP-3174 before biliary and renal excretion.\"}}]},\"technicalTerms\":[{\"term\":\"açil glukuronid toksisitesi\",\"arContext\":\"سمية غلوكورونيد الأسيل (acyl glucuronide toxicity)\"},{\"term\":\"anjiyotensin reseptör blokeri (ARB)\",\"arContext\":\"حاصرات مستقبلات الأنجيوتنسين (ARB)\"}],\"hints\":[{\"tr\":\"Karboksilik asitlerin Faz II glukuronidasyonunda açil bağı kararsızdır; proteinlerle istenmeyen kovalent bağlar kurar.\",\"ar\":\"تكون رابطة أسيل غلوكورونيد الناتجة عن الكربوكسيل غير مستقرة كيميائياً وتتفاعل مع البروتينات.\",\"en\":\"Carboxylic acid Phase II glucuronidation yields chemically labile acyl-linked electrophiles.\"},{\"tr\":\"Tetrazol bir karboksilik asit değildir; açil grubu taşımaz.\",\"ar\":\"التترازول حلقة عطرية ولا يحتوي على مجموعة كربونيل أسيلية.\",\"en\":\"Tetrazole is an aromatic ring lacking a carbonyl group, precluding acyl ester conjugation.\"},{\"tr\":\"Tetrazol açil glukuronidasyona uğramaz; böylece reaktif metabolit toksisitesi ortadan kalkar ve yarı ömür uzar.\",\"ar\":\"يقاوم التترازول هذا النمط من الاقتران، مما يزيل السمية التفاعلية ويطيل عمر الدواء في البلازما.\",\"en\":\"Tetrazole resists acyl glucuronidation, eliminating reactive metabolite formation and sustaining predictable exposure.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":9}],\"config\":{\"options\":[{\"id\":\"opt-9a\",\"text\":\"Tetrazol halkası UGT enzimlerinin açil glukuronidasyon nükleofilik atağına dirençlidir; reaktif elektrofilik esterler oluşturmaz ve yarılanma ömrünü uzatır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kesinlikle doğru! Karboksilik asitler UGT enzimlerince 1-O-açil glukuronidlere çevrilir. Bu metabolitler protein lizini ile kovalent bağ yaparak immünolojik toksisiteye yol açar. Tetrazol halkası ise açil ester oluşturamaz; güvenli ve uzun etki sağlar.\"},{\"id\":\"opt-9b\",\"text\":\"Tetrazol tüm karaciğer enzimlerini irreversibl felç ederek metabolizmayı tamamen durdurur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Karaciğer felci yanılgısı: ARB'ler güvenli kronik ilaçlardır; hepatik enzim yıkımı yapmazlar.\"},{\"id\":\"opt-9c\",\"text\":\"Tetrazol karaciğere hiç uğramadan yalnızca tükürük bezleri üzerinden doğrudan atılır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Tükürük eliminasyon yanılgısı: Losartan karaciğerde kontrollü olarak CYP2C9/3A4 ile aktif karboksilatına (EXP-3174) oksitlenir.\"}],\"revealedOutcome\":{\"tr\":\"Tetrazol halkası UGT enzimlerinin açil glukuronidasyon nükleofilik atağına dirençlidir; reaktif elektrofilik esterler oluşturmaz ve yarılanma ömrünü uzatır.\",\"ar\":\"تقاوم حلقة التترازول أنزيمات UGT؛ فلا تشكل إسترات كهرومحبّة سامة وتطيل نصف العمر الحيوي بأمان تام.\",\"en\":\"Tetrazole resists UGT nucleophilic acyl transfer, preventing the generation of reactive electrophilic acyl glucuronides and dramatically extending duration.\"},\"explanation\":{\"tr\":\"Kesinlikle doğru! Karboksilik asitler UGT enzimlerince 1-O-açil glukuronidlere çevrilir. Bu metabolitler protein lizini ile kovalent bağ yaparak immünolojik toksisiteye yol açar. Tetrazol halkası ise açil ester oluşturamaz; güvenli ve uzun etki sağlar.\",\"ar\":\"صحيح تماماً! تشكل الأحماض غلوكورونيدات أسيل تفاعلية تتصل تساهمياً ببروتينات الكبد مسببة سمية نسيجية. بينما يعجز التترازول عن تشكيل هذه الروابط الخطرة.\",\"en\":\"Spot on! Carboxylic acids form reactive 1-O-acyl glucuronides that covalently haptenate host proteins. Tetrazole cannot form reactive acyl-linked conjugates, eliminating idiosyncratic toxicity.\"}}},{\"id\":\"mc-mod3-les2-step-10\",\"stage\":\"retrieval\",\"stageIndex\":10,\"type\":\"retrieval\",\"title\":{\"tr\":\"Aralıklı Hatırlama: Prokain vs Prokainamid Yarı Ömür Farkı\",\"ar\":\"استرجاع متباعد: فارق نصف العمر بين البروكائين والبروكائيناميد\",\"en\":\"Spaced Retrieval: Procaine vs Procainamide Half-Life\"},\"prompt\":{\"tr\":\"Prokain (ester) plazmada psödokolinesteraz ile saniyeler içinde hidroliz olurken, amit izosteri olan prokainamidin yarılanma ömrü neden 3-4 saate uzar? Hangi bağ kararlılığı devreye girer?\",\"ar\":\"بينما يتحلل البروكائين (إستر) خلال ثوانٍ بأنزيمات الكولينستراز، لماذا يمتد نصف عمر نظيره الأميدي بروكائيناميد إلى 3-4 ساعات؟ ما نوع ثبات الرابطة؟\",\"en\":\"While ester procaine is cleaved by pseudocholinesterase in seconds, why does its amide bioisostere procainamide survive for 3-4 hours in plasma? What orbital resonance protects it?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-10a\",\"text\":{\"tr\":\"Azotun serbest elektron çifti karbonile güçlü rezonansla katılarak (kısmi çift bağ karakteri) karbonil karbonunun elektrofilikliğini düşürür ve esterazların nükleofilik atağını engeller.\",\"ar\":\"يشارك زوج إلكترونات النيتروجين برنين قوي مع الكربونيل (مانحاً طابع الرابطة المزدوجة)؛ مخفضاً كهرومحبيتها ومقاوماً حلمهة الأستراز.\",\"en\":\"Nitrogen lone-pair resonance into the carbonyl imparts partial double-bond character, dampening electrophilicity and shielding against esterase nucleophilic attack.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika bir bağ teorisi hatırlaması! Amit azotunun ortaklanmamış elektron çifti karbonil ile güçlü rezonans yapar. C-N bağı kısmi çift bağ karakteri kazanır ve karbonil karbonu elektrofilik nükleofilik hidrolize dirençli hale gelir (Slide 15).\",\"ar\":\"تذكر ممتاز لنظرية الروابط! يشارك زوج النيتروجين برنين كثيف مع الكربونيل مانحاً الرابطة طابعاً مزدوجاً يجعلها منيعة على الحلمهة الاسترازية.\",\"en\":\"Superb resonance recall! Amide nitrogen delocalizes its lone pair into the carbonyl, creating partial double-bond character that thwarts esterase nucleophilic attack.\"}},{\"id\":\"opt-10b\",\"text\":{\"tr\":\"Prokainamid molekülü kandaki kalsiyum ile taşlaşarak katı bir kireç tabakasına dönüşür.\",\"ar\":\"يتكلس جزيء بروكائيناميد مع كالسيوم الدم متحولاً إلى ترسبات حجرية صلبة.\",\"en\":\"Procainamide binds serum calcium, precipitating into an impenetrable limestone matrix.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kireçlenme yanılgısı: Prokainamid çözünür bir Sınıf IA antiaritmiktir; kalsiyum çökeltisi yapmaz.\",\"ar\":\"خطأ التكلس: البروكائيناميد دواء قلبي نظامي ذواب بالكامل ولا يتفاعل ترسبياً مع الكالسيوم.\",\"en\":\"Calcification misconception: Procainamide is a soluble Class IA antiarrhythmic small molecule, not a calcium precipitant.\"}},{\"id\":\"opt-10c\",\"text\":{\"tr\":\"Amit bağı ester bağından 100 kat daha zayıftır, bu yüzden enzimler bağı bulamaz.\",\"ar\":\"رابطة الأميد أضعف بمئة مرة من الإستر مما يجعل الأنزيم عاجزاً عن رصدها.\",\"en\":\"Amide bonds are 100-fold weaker than esters, hiding from enzyme recognition.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Zayıf bağ yanılgısı: Amit bağı rezonans sayesinde esterden çok daha dayanıklıdır ve hidrolize dirençlidir.\",\"ar\":\"خطأ ضعف الرابطة: رابطة الأميد أكثر ثباتاً ومقاومة للحلمهة بمراحل مقارنة بالإستر.\",\"en\":\"Weak bond misconception: Amide bonds possess greater thermodynamic and kinetic stability against hydrolysis than esters.\"}}]},\"technicalTerms\":[{\"term\":\"amit rezonans kararlılığı\",\"arContext\":\"ثبات رنين الأميد (amide resonance)\"},{\"term\":\"psödokolinesteraz hidrolizi\",\"arContext\":\"حلمهة أنزيم كولينستراز الكاذب\"}],\"hints\":[{\"tr\":\"Esterde oksijen atomu vardır (-COO-); amitte ise azot atomu (-CONH-) bulunur.\",\"ar\":\"يحتوي الإستر على أكسجين (-COO-)، بينما يحتوي الأميد على نيتروجين (-CONH-).\",\"en\":\"Esters contain oxygen (-COO-); amides contain nitrogen (-CONH-).\"},{\"tr\":\"Azot, oksijene göre elektron çiftini karbonile çok daha hevesle verir (daha az elektronegatiftir).\",\"ar\":\"يتنازل النيتروجين عن زوجه الإلكتروني للكربونيل بسهولة أكبر من الأكسجين لقلة كهروسلبيته.\",\"en\":\"Nitrogen is less electronegative than oxygen, donating its lone pair into the carbonyl more readily.\"},{\"tr\":\"Bu güçlü rezonans amit bağını düzlemsel ve kısmi çift bağlı kılar; esteraz enzimleri amiti parçalayamaz.\",\"ar\":\"يمنح هذا الرنين الرابطة طابعاً مزدوجاً مستوياً يجعلها مستعصية على التحلل بأنزيمات الإستراز.\",\"en\":\"This robust resonance imparts partial double-bond character, rendering procainamide refractory to plasma esterases.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":15}],\"config\":{\"options\":[{\"id\":\"opt-10a\",\"text\":\"Azotun serbest elektron çifti karbonile güçlü rezonansla katılarak (kısmi çift bağ karakteri) karbonil karbonunun elektrofilikliğini düşürür ve esterazların nükleofilik atağını engeller.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika bir bağ teorisi hatırlaması! Amit azotunun ortaklanmamış elektron çifti karbonil ile güçlü rezonans yapar. C-N bağı kısmi çift bağ karakteri kazanır ve karbonil karbonu elektrofilik nükleofilik hidrolize dirençli hale gelir (Slide 15).\"},{\"id\":\"opt-10b\",\"text\":\"Prokainamid molekülü kandaki kalsiyum ile taşlaşarak katı bir kireç tabakasına dönüşür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kireçlenme yanılgısı: Prokainamid çözünür bir Sınıf IA antiaritmiktir; kalsiyum çökeltisi yapmaz.\"},{\"id\":\"opt-10c\",\"text\":\"Amit bağı ester bağından 100 kat daha zayıftır, bu yüzden enzimler bağı bulamaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Zayıf bağ yanılgısı: Amit bağı rezonans sayesinde esterden çok daha dayanıklıdır ve hidrolize dirençlidir.\"}],\"revealedOutcome\":{\"tr\":\"Azotun serbest elektron çifti karbonile güçlü rezonansla katılarak (kısmi çift bağ karakteri) karbonil karbonunun elektrofilikliğini düşürür ve esterazların nükleofilik atağını engeller.\",\"ar\":\"يشارك زوج إلكترونات النيتروجين برنين قوي مع الكربونيل (مانحاً طابع الرابطة المزدوجة)؛ مخفضاً كهرومحبيتها ومقاوماً حلمهة الأستراز.\",\"en\":\"Nitrogen lone-pair resonance into the carbonyl imparts partial double-bond character, dampening electrophilicity and shielding against esterase nucleophilic attack.\"},\"explanation\":{\"tr\":\"Harika bir bağ teorisi hatırlaması! Amit azotunun ortaklanmamış elektron çifti karbonil ile güçlü rezonans yapar. C-N bağı kısmi çift bağ karakteri kazanır ve karbonil karbonu elektrofilik nükleofilik hidrolize dirençli hale gelir (Slide 15).\",\"ar\":\"تذكر ممتاز لنظرية الروابط! يشارك زوج النيتروجين برنين كثيف مع الكربونيل مانحاً الرابطة طابعاً مزدوجاً يجعلها منيعة على الحلمهة الاسترازية.\",\"en\":\"Superb resonance recall! Amide nitrogen delocalizes its lone pair into the carbonyl, creating partial double-bond character that thwarts esterase nucleophilic attack.\"}}},{\"id\":\"mc-mod3-les2-step-11\",\"stage\":\"connection\",\"stageIndex\":11,\"type\":\"connection\",\"title\":{\"tr\":\"Bağlantı: Faz I/II Metabolizmasını Biyoizosterizm ile Savuşturmak\",\"ar\":\"ربط المفاهيم: درء استقلاب الطور الأول والثاني بالبيوإيزوستيرية\",\"en\":\"Cross-Topic Bridge: Evading Phase I/II Metabolism via Bioisosterism\"},\"prompt\":{\"tr\":\"Non-klasik biyoizosterik modifikasyonlar (tetrazol, amit, hidroksimetil), ilaçları Faz I sitokrom oksidasyonundan ve Faz II UGT/SULT konjugasyonundan nasıl korur? Gelecek metabolizma modülüyle bağlantıyı kurun:\",\"ar\":\"كيف تحمي التعديلات غير الكلاسيكية (التترازول، الأميد، هيدروكسي ميثيل) الأدوية من أكسدة السيتوكروم واقتران UGT/SULT؟ اربط بموديول الاستقلاب القادم:\",\"en\":\"How do non-classical bioisosteric replacements (tetrazole, amide, hydroxymethyl) shield drug candidates from Phase I CYP oxidation and Phase II UGT/SULT clearance? Connect to Module 5 Drug Metabolism:\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-11a\",\"text\":{\"tr\":\"Hassas metabolik odak noktalarını (karboksilat, katekol -OH, ester) enzimatik tanımanın dışına çıkararak ilaca metabolik direnç kazandırır ve yarı ömrü rasyonel olarak uzatır.\",\"ar\":\"تبعد المواقع الاستقلابية الحساسة (الكربوكسيل، الكاتيكول، الإستر) عن التعرف الأنزيمي؛ مانحة الدواء ثباتاً استقلابياً يطيل فاعليته.\",\"en\":\"They replace metabolically vulnerable soft spots (carboxylate, catechol -OH, ester) with enzyme-refractory mimics, rationally extending therapeutic half-life.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel köprü! Biyoizosterizm farmakoforun reseptör cebindeki temasını korurken, vücudun Faz I ve Faz II metabolik makinelerine (CYP, UGT, SULT, COMT, esterazlar) karşı moleküle kamuflaj zırhı giydirir.\",\"ar\":\"ربط رائع! تحفظ المتشابهات الحيوية الارتباط الفعال بالمستقبل، بينما توفر درع تمويه ضد ترسانة أنزيمات الاستقلاب الكبدية (CYP و UGT و COMT).\",\"en\":\"Superb bridge! Bioisosterism preserves receptor pharmacophore contacts while cloaking vulnerable functional groups from Phase I (CYP) and Phase II (UGT, SULT, COMT) enzymes.\"}},{\"id\":\"opt-11b\",\"text\":{\"tr\":\"Biyoizosterik ilaçlar vücuttaki tüm sitokrom ve glukuronidaz genlerini susturur.\",\"ar\":\"تقوم الأدوية البيوإيزوستيرية بإسكات وتثبيط كافة جينات السيتوكروم والغلوبيولين في الجسم.\",\"en\":\"Bioisosteres permanently silence all CYP and UGT gene transcription in human tissues.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Gen susturma yanılgısı: İlaç substrat yapısı değişir; hastanın genomu veya metabolik enzimleri genetik olarak susturulmaz.\",\"ar\":\"خطأ إسكات الجينات: التعديل يتم في بنية الدواء المتفاعلة وليس عبر تعطيل جينات المريض.\",\"en\":\"Gene silencing misconception: Bioisosteric modification alters ligand structure, not host metabolic gene expression.\"}},{\"id\":\"opt-11c\",\"text\":{\"tr\":\"Metabolizmadan kaçan her ilaç zehirli bir radyoaktif atığa dönüşür.\",\"ar\":\"يتحول كل دواء يفلت من الاستقلاب إلى نفايات مشعة سامة.\",\"en\":\"Any drug evading hepatic metabolism inevitably degrades into radioactive biohazard.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Radyoaktif atık yanılgısı: Kararlı ilaçlar böbreklerden veya safradan değişmeden güvenle atılır.\",\"ar\":\"خطأ الإشعاع: تطرح الأدوية المقاومة للاستقلاب بسلام دون تغير عبر الكلى أو الصفراء.\",\"en\":\"Radioactive hazard misconception: Stable drugs are cleared intact via renal filtration or biliary transport without radiochemical degradation.\"}}]},\"technicalTerms\":[{\"term\":\"Faz I/II metabolizma kamuflajı\",\"arContext\":\"تمويه استقلاب الطور الأول والثاني\"},{\"term\":\"metabolik odak noktası (soft spot)\",\"arContext\":\"الموقع الاستقلابي القابل للتخريب\"}],\"hints\":[{\"tr\":\"İlaç metabolizmasında amaç molekülü hidrofilik yapıp vücuttan atmaktır.\",\"ar\":\"يهدف استقلاب الدواء إلى زيادة قطبيته وتسهيل طرحه خارج الجسم.\",\"en\":\"Drug metabolism transforms lipophilic xenobiotics into polar conjugates for excretion.\"},{\"tr\":\"Enzimler belirli kimyasal grupları tanır (örneğin COMT katekol arar, esteraz ester arar, UGT karboksilat arar).\",\"ar\":\"تتعرف الأنزيمات على مجموعات محددة (يبحث COMT عن الكاتيكول، والأستراز عن الإستر، و UGT عن الكربوكسيل).\",\"en\":\"Metabolic enzymes recognize specific motifs (COMT targets catechols, esterases target esters, UGT targets carboxylates).\"},{\"tr\":\"Biyoizosterik gruplar bu enzimlerin nükleofilik veya oksidatif atağını sterik/elektronik olarak boşa çıkarır.\",\"ar\":\"تحبط المجموعات البيوإيزوستيرية هجوم هذه الأنزيمات فراغياً وإلكترونياً.\",\"en\":\"Bioisosteres subvert metabolic attack electronically and sterically while maintaining receptor fit.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":10}],\"config\":{\"options\":[{\"id\":\"opt-11a\",\"text\":\"Hassas metabolik odak noktalarını (karboksilat, katekol -OH, ester) enzimatik tanımanın dışına çıkararak ilaca metabolik direnç kazandırır ve yarı ömrü rasyonel olarak uzatır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel köprü! Biyoizosterizm farmakoforun reseptör cebindeki temasını korurken, vücudun Faz I ve Faz II metabolik makinelerine (CYP, UGT, SULT, COMT, esterazlar) karşı moleküle kamuflaj zırhı giydirir.\"},{\"id\":\"opt-11b\",\"text\":\"Biyoizosterik ilaçlar vücuttaki tüm sitokrom ve glukuronidaz genlerini susturur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Gen susturma yanılgısı: İlaç substrat yapısı değişir; hastanın genomu veya metabolik enzimleri genetik olarak susturulmaz.\"},{\"id\":\"opt-11c\",\"text\":\"Metabolizmadan kaçan her ilaç zehirli bir radyoaktif atığa dönüşür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Radyoaktif atık yanılgısı: Kararlı ilaçlar böbreklerden veya safradan değişmeden güvenle atılır.\"}],\"revealedOutcome\":{\"tr\":\"Hassas metabolik odak noktalarını (karboksilat, katekol -OH, ester) enzimatik tanımanın dışına çıkararak ilaca metabolik direnç kazandırır ve yarı ömrü rasyonel olarak uzatır.\",\"ar\":\"تبعد المواقع الاستقلابية الحساسة (الكربوكسيل، الكاتيكول، الإستر) عن التعرف الأنزيمي؛ مانحة الدواء ثباتاً استقلابياً يطيل فاعليته.\",\"en\":\"They replace metabolically vulnerable soft spots (carboxylate, catechol -OH, ester) with enzyme-refractory mimics, rationally extending therapeutic half-life.\"},\"explanation\":{\"tr\":\"Mükemmel köprü! Biyoizosterizm farmakoforun reseptör cebindeki temasını korurken, vücudun Faz I ve Faz II metabolik makinelerine (CYP, UGT, SULT, COMT, esterazlar) karşı moleküle kamuflaj zırhı giydirir.\",\"ar\":\"ربط رائع! تحفظ المتشابهات الحيوية الارتباط الفعال بالمستقبل، بينما توفر درع تمويه ضد ترسانة أنزيمات الاستقلاب الكبدية (CYP و UGT و COMT).\",\"en\":\"Superb bridge! Bioisosterism preserves receptor pharmacophore contacts while cloaking vulnerable functional groups from Phase I (CYP) and Phase II (UGT, SULT, COMT) enzymes.\"}}},{\"id\":\"mc-mod3-les2-step-12\",\"stage\":\"mastery_check\",\"stageIndex\":12,\"type\":\"mastery_check\",\"title\":{\"tr\":\"Ustalık Sınavı: COX-2 İnhibitöründe Asidik İzoster Tasarımı\",\"ar\":\"اختبار الإتقان: تصميم إيزوستير حامضي لمثبط COX-2\",\"en\":\"Mastery Challenge: Non-Classical Acidic Isostere in COX-2 Design\"},\"prompt\":{\"tr\":\"Yeni bir COX-2 inhibitörü adayı terminal -COOH grubu yüzünden yalnızca %4 biyoyararlanım göstermekte ve mide ülseri yapmaktadır. COX-2 aktif cebindeki arginin ile bağı koruyan ve emilimi artıran non-klasik asidik izoster öneriniz:\",\"ar\":\"يعاني مرشح مثبط COX-2 جديد من توافر حيوي ضعيف (4%) وقرحة معدية بسبب مجموعة -COOH. اقترح بديلاً حامضياً غير كلاسيكي يرفع الامتصاص ويحفظ الارتباط بأرجنين COX-2:\",\"en\":\"A promising COX-2 inhibitor suffers from 4% oral bioavailability and gastric ulceration due to a terminal -COOH. Propose a non-classical acidic bioisostere that preserves active site arginine binding while maximizing lipophilicity:\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-12a\",\"text\":{\"tr\":\"1H-Tetrazol veya metilsülfonamid (-SO2NHCH3); asidik pKa (~4.5-5.5) ile Arg513'e iyonik bağı korurken lipofilisiteyi artırır, desolvasyonu düşürür ve mide irritasyonunu önler.\",\"ar\":\"1H-Tetrazole أو ميثيل سلفوناميد؛ يحافظان على pKa الحامضية والارتباط الأيوني مع Arg513 مع رفع النفاذية الدهنية وتجنب التخريش المعدي.\",\"en\":\"1H-Tetrazole or methyl sulfonamide; preserving acidic pKa (~4.5-5.5) for ionic docking to Arg513 while boosting logP, slashing desolvation, and eliminating gastric ulceration.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Tebrikler, mükemmel bir farmasötik kimya çözümü! Terminal -COOH yerine tetrazol veya sülfonamid getirilmesi: 1) pKa'yı ~4.5-5.5 aralığında tutarak Arg513 ile tuz köprüsünü korur, 2) logP'yi artırıp desolvasyonu azaltarak biyoyararlanımı fırlatır, 3) lokal serbest asit etkisini kırarak mide mukozasını korur.\",\"ar\":\"تهانينا، حل دوائي متقن! استبدال -COOH بالتترازول أو السلفوناميد: 1) يحفظ الرابطة الأيونية مع Arg513، 2) يرفع التوافر الحيوي لتقليل طاقة نزع الماء، 3) يحمي الغشاء المعدي من القرحة.\",\"en\":\"Mastery demonstrated! Swapping terminal -COOH for tetrazole or sulfonamide preserves ionic pairing with Arg513, multiplies oral bioavailability via lowered desolvation, and spares gastric mucosa from direct acid injury.\"}},{\"id\":\"opt-12b\",\"text\":{\"tr\":\"Kuvaterner amonyum (-N+Me3); kalıcı pozitif yüküyle mide asidini nötralize eder ancak COX-2'ye hiç bağlanamaz.\",\"ar\":\"أمونيوم رباعي (-N+Me3)؛ يعادل حمض المعدة بشحنته الموجبة لكنه يفقد الارتباط تماماً مع COX-2.\",\"en\":\"Quaternary ammonium (-N+Me3); neutralizes gastric acid but completely destroys COX-2 active site binding.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Zıt yük yanılgısı: Reseptördeki hedef amino asit Arginindir (pozitif katyonik guanidinyum). Pozitif amonyum takılırsa iki pozitif yük birbirini iter ve afinite sıfıra iner.\",\"ar\":\"خطأ تنافر الشحنات: ثمالة الأرجنين في الموقع الفعال موجبة الشحنة؛ إضافة أمونيوم موجب يسبب تنافراً كهربائياً عنيفاً يلغي الفعالية.\",\"en\":\"Charge clash misconception: Target Arg513 bears a positive guanidinium ion; an ammonium substituent causes severe electrostatic repulsion.\"}},{\"id\":\"opt-12c\",\"text\":{\"tr\":\"Sadece saf benzen halkası; hiçbir fonksiyonel grup taşımayan moleküller tüm enzimlere eşit bağlanır.\",\"ar\":\"حلقة بنزين مجردة؛ فالجزيئات الخالية من المجموعات ترتبط بكافة الأنزيمات بالتساوي.\",\"en\":\"An unsubstituted benzene ring; functional-group-free scaffolds bind all enzymes equally.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Apolar yanılgı: Arg513 katyonu güçlü bir iyonik/dipol eşleşme arar; apolar benzen halkası bu bağı sağlayamaz.\",\"ar\":\"خطأ اللاقطبية: يتطلب جيب أرجنين Arg513 مجموعة حامضية قطبية؛ ولا تستطيع حلقة البنزين المجردة تشكيل هذا الجسر الأيوني.\",\"en\":\"Apolar misconception: Arg513 requires a complementary acidic anionic pharmacophore; an apolar benzene ring cannot form the crucial salt bridge.\"}}]},\"technicalTerms\":[{\"term\":\"COX-2 aktif cebi\",\"arContext\":\"جيب COX-2 الفعال\"},{\"term\":\"asidik biyoizosterik değişim\",\"arContext\":\"التبديل البيوإيزوستيري الحامضي\"}],\"hints\":[{\"tr\":\"Hedef amino asit Arginindir (pozitif guanidinyum başı taşır). Karşısına negatif/asidik bir grup gelmelidir.\",\"ar\":\"الحمض الأميني المستهدف هو الأرجنين (موجب الشحنة)؛ لذا يلزم وجود مجموعة مقابلة ذات شحنة سالبة/حامضية.\",\"en\":\"Target Arg513 bears a cationic guanidinium group, requiring a complementary acidic/anionic partner.\"},{\"tr\":\"Karboksilik asidin asidik pKa'sını (~4.5-5.5) taklit eden ancak daha lipofilik olan non-klasik grupları hatırlayın.\",\"ar\":\"تذكر المتشابهات غير الكلاسيكية التي تحاكي حامضية الكربوكسيل مع انحلال دهني أفضل.\",\"en\":\"Recall non-classical groups that mimic carboxylic acid pKa (~4.5-5.5) with higher lipophilicity.\"},{\"tr\":\"1H-tetrazol veya sülfonamid grupları Arg513 ile tuzu korur, logP'yi artırıp biyoyararlanımı kurtarır ve mide tahrişini önler.\",\"ar\":\"يحقق التترازول أو السلفوناميد الرابطة الأيونية مع رفع النفاذية ومنع تخريش المعدة.\",\"en\":\"1H-tetrazole or acyl sulfonamide preserves the Arg513 salt bridge, elevates logP, and abolishes ulcerogenicity.\"}],\"sources\":[{\"file\":\"Biyoizosterizm.pdf\",\"page\":9}],\"config\":{\"options\":[{\"id\":\"opt-12a\",\"text\":\"1H-Tetrazol veya metilsülfonamid (-SO2NHCH3); asidik pKa (~4.5-5.5) ile Arg513'e iyonik bağı korurken lipofilisiteyi artırır, desolvasyonu düşürür ve mide irritasyonunu önler.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Tebrikler, mükemmel bir farmasötik kimya çözümü! Terminal -COOH yerine tetrazol veya sülfonamid getirilmesi: 1) pKa'yı ~4.5-5.5 aralığında tutarak Arg513 ile tuz köprüsünü korur, 2) logP'yi artırıp desolvasyonu azaltarak biyoyararlanımı fırlatır, 3) lokal serbest asit etkisini kırarak mide mukozasını korur.\"},{\"id\":\"opt-12b\",\"text\":\"Kuvaterner amonyum (-N+Me3); kalıcı pozitif yüküyle mide asidini nötralize eder ancak COX-2'ye hiç bağlanamaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Zıt yük yanılgısı: Reseptördeki hedef amino asit Arginindir (pozitif katyonik guanidinyum). Pozitif amonyum takılırsa iki pozitif yük birbirini iter ve afinite sıfıra iner.\"},{\"id\":\"opt-12c\",\"text\":\"Sadece saf benzen halkası; hiçbir fonksiyonel grup taşımayan moleküller tüm enzimlere eşit bağlanır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Apolar yanılgı: Arg513 katyonu güçlü bir iyonik/dipol eşleşme arar; apolar benzen halkası bu bağı sağlayamaz.\"}],\"revealedOutcome\":{\"tr\":\"1H-Tetrazol veya metilsülfonamid (-SO2NHCH3); asidik pKa (~4.5-5.5) ile Arg513'e iyonik bağı korurken lipofilisiteyi artırır, desolvasyonu düşürür ve mide irritasyonunu önler.\",\"ar\":\"1H-Tetrazole أو ميثيل سلفوناميد؛ يحافظان على pKa الحامضية والارتباط الأيوني مع Arg513 مع رفع النفاذية الدهنية وتجنب التخريش المعدي.\",\"en\":\"1H-Tetrazole or methyl sulfonamide; preserving acidic pKa (~4.5-5.5) for ionic docking to Arg513 while boosting logP, slashing desolvation, and eliminating gastric ulceration.\"},\"explanation\":{\"tr\":\"Tebrikler, mükemmel bir farmasötik kimya çözümü! Terminal -COOH yerine tetrazol veya sülfonamid getirilmesi: 1) pKa'yı ~4.5-5.5 aralığında tutarak Arg513 ile tuz köprüsünü korur, 2) logP'yi artırıp desolvasyonu azaltarak biyoyararlanımı fırlatır, 3) lokal serbest asit etkisini kırarak mide mukozasını korur.\",\"ar\":\"تهانينا، حل دوائي متقن! استبدال -COOH بالتترازول أو السلفوناميد: 1) يحفظ الرابطة الأيونية مع Arg513، 2) يرفع التوافر الحيوي لتقليل طاقة نزع الماء، 3) يحمي الغشاء المعدي من القرحة.\",\"en\":\"Mastery demonstrated! Swapping terminal -COOH for tetrazole or sulfonamide preserves ionic pairing with Arg513, multiplies oral bioavailability via lowered desolvation, and spares gastric mucosa from direct acid injury.\"}}}]},\"mc-mod4-les1\":{\"$schema\":\"../../../packages/platform/schema/lesson.schema.json\",\"id\":\"mc-mod4-les1\",\"courseId\":\"medchem\",\"moduleId\":\"mc-mod-04\",\"title\":{\"tr\":\"Ötomerler, Distomerler ve Pfeiffer Kuralı\",\"ar\":\"المصاوغات النشطة والمصاوغات الخاملة وقاعدة Pfeiffer\",\"en\":\"Eutomers, Distomers & Pfeiffer's Rule\"},\"order\":1,\"access\":\"free\",\"objective\":{\"tr\":\"Pfeiffer kuralını ve Easson-Stedman modelini uygulayarak ötomer/distomer afinite uçurumlarını, eudismik oranları (ER) ve stereoselektif klinik toksisiteyi öngörmek.\",\"ar\":\"تطبيق قاعدة Pfeiffer ونموذج Easson-Stedman للتنبؤ بفوارق الألفة بين المصاوغات، والنسب الإيوديزمية (ER)، والسمية السريرية الانتقائية فراغياً.\",\"en\":\"Apply Pfeiffer's rule and the Easson-Stedman model to quantify eutomer/distomer affinity gaps, calculate eudismic ratios (ER), and predict stereoselective clinical toxicity.\"},\"misconceptions\":[{\"tr\":\"Distomerin (düşük afiniteli enantiyomer) her zaman biyolojik olarak tamamen atıl ve zararsız bir seyirci olduğu yanılgısı.\",\"ar\":\"الظن الخاطئ بأن المصاوغ الأضعف (distomer) عديم الفعالية والسمية تماماً دائماً ومجرد متفرج خامل.\",\"en\":\"The misconception that the distomer is always an inert, harmless bystander in biological systems.\"},{\"tr\":\"Pfeiffer kuralının düşük afiniteli ve non-spesifik ilaçlarda da yüksek eudismik oranlar üreteceği varsayımı.\",\"ar\":\"الافتراض الخاطئ بأن قاعدة Pfeiffer تنتج نسباً إيوديزمية هائلة حتى في الأدوية ضعيفة الألفة وغير النوعية.\",\"en\":\"The assumption that Pfeiffer's rule yields massive eudismic ratios even for low-affinity, non-specific drugs.\"},{\"tr\":\"Saf ötomer geliştirmenin (kiral geçiş) in vivo rasemize olan moleküllerde dahi toksisiteyi tamamen çözeceği düşüncesi (talidomid yanılgısı).\",\"ar\":\"الاعتقاد الخاطئ بأن عزل المصاوغ الفعال النقي يحل مشكلة السمية دوماً حتى في الجزيئات التي ترسمز حيوياً في بلازما الدم.\",\"en\":\"The belief that developing a single enantiomer always solves toxicity, overlooking in vivo spontaneous racemization.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":23},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":24},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":25},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":26},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":27},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":28},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":29},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":30},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":31},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":32},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":33},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":35}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Foye's Principles of Medicinal Chemistry\",\"edition\":\"8th ed.\",\"topic\":\"Stereochemistry, Eutomers, Distomers, and Pfeiffer's Rule\",\"chapter\":\"Chapter 2\",\"page\":\"38-55\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Wilson and Gisvold's Textbook of Organic Medicinal and Pharmaceutical Chemistry\",\"edition\":\"12th ed.\",\"topic\":\"Stereoselective Drug-Receptor Interactions and Eudismic Analysis\",\"chapter\":\"Chapter 3\",\"page\":\"65-85\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"mc-mod4-les1-card1\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Ötomer, Distomer ve Eudismik Oran\",\"prompt\":\"Ötomer (Eutomer), Distomer ve Eudismik Oran (ER) nasıl tanımlanır?\",\"answer\":\"Ötomer hedef reseptörde yüksek afiniteli aktif enantiyomer; distomer düşük afiniteli veya istenmeyen izomerdir. Eudismik Oran (ER) = Ötomer Potensi / Distomer Potensidir.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod4-les1-card2\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Carl Pfeiffer Kuralı\",\"prompt\":\"Carl Pfeiffer Kuralı (1956) afinite ile Eudismik Oran arasındaki ilişkiyi nasıl açıklar?\",\"answer\":\"Bir ilacın reseptörüne afinitesi ne kadar yüksekse (dozu ne kadar düşükse), aktif ötomer ile distomer arasındaki güç farkı (ER) o derece katlanarak artar.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod4-les1-card3\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Epinin Kanıtı\",\"prompt\":\"Epinin (deoksiadrenalin) Easson-Stedman 3-nokta hipotezini nasıl kanıtlar?\",\"answer\":\"Epinin kiral beta-OH grubundan tamamen yoksundur; afinitesi tam olarak beta-OH grubu cebin dışına bakan zayıf (S)-adrenalin düzeyindedir (2-nokta kenetlenmesi kanıtı).\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod4-les1-card4\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Pisenadol Enantiyomer Çifti\",\"prompt\":\"Pisenadol (Picenadol) enantiyomer çiftinin benzersiz farmakolojik davranışı nedir?\",\"answer\":\"(+)-Pisenadol güçlü bir mu-opioid reseptör agonisti (analjezik) iken, (-)-pisenadol mu-opioid reseptör antagonistidir (bloker); rasemat ise parsiyel agonisttir.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod4-les1-card5\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Arzu Edilen Rasemat: Bupivakain\",\"prompt\":\"Bupivakain neden 'arzu edilen rasemat' (desirable racemate) olarak klinikte tek izomerine tercih edilir?\",\"answer\":\"R(+)-bupivakain güçlü lokal anestezik iken, S(-)-bupivakain lokal vazokonstrüksiyon yaparak ilacın dokuda kalış süresini uzatır ve sistemik kardiyotoksisiteyi azaltır.\",\"box\":1,\"intervalDays\":1}],\"translations\":{\"tr\":{\"title\":\"Ötomerler, Distomerler ve Pfeiffer Kuralı\"},\"ar\":{\"title\":\"المصاوغات النشطة والمصاوغات الخاملة وقاعدة Pfeiffer\"}},\"steps\":[{\"id\":\"mc-mod4-les1-step-01\",\"stage\":\"hook\",\"stageIndex\":1,\"type\":\"predict_reveal\",\"title\":{\"tr\":\"Muskarin Paradoksu: 700 Katlık Afinite Uçurumu\",\"ar\":\"مفارقة المسكارين: فارق الألفة بـ 700 ضعف\",\"en\":\"The Muscarine Paradox: The 700-Fold Potency Cliff\"},\"prompt\":{\"tr\":\"Doğal (+)-muskarin asetilkolin reseptörünü sentetik ayna görüntüsü (-)-muskarinden tam 700 kat daha güçlü uyarır. Genel anesteziklerde ise enantiyomerler eşit güçtedir. Neden bazı ilaçlarda enantiyomer farkı yüzlerce kat iken diğerlerinde sıfırdır?\",\"ar\":\"ينبه (+)-muscarine الطبيعي مستقبل الأستيل كولين بقوة تفوق نظيره المرآوي (-)-muscarine بـ 700 ضعف! بينما تتساوى مصاوغات المخدرات العامة. لماذا يتسع فارق المصاوغات لمئات الأضعاف في أدوية وينعدم في أخرى؟\",\"en\":\"Natural (+)-muscarine activates acetylcholine receptors 700-fold more potently than mirror (-)-muscarine. Yet volatile anesthetics show identical enantiomer potency. Why does enantiomeric difference explode to hundreds-fold for some drugs, but vanish to zero in others?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-1a\",\"text\":{\"tr\":\"Yüksek afiniteli muskarin dar ve rijit bir cebe milimetrik 3-nokta uyumuyla oturur; genel anestezikler ise lipid membranda gevşek ve spesifik olmayan bağlar kurar.\",\"ar\":\"يرسو المسكارين عالي الألفة في جيب ضيق بتطابق ثلاثي النقاط دقيق؛ بينما ترتبط المخدرات العامة برخاوة غير نوعية في الغشاء الدهني.\",\"en\":\"High-affinity muscarine binds a narrow, rigid pocket demanding 3-point stereocomplementarity; volatile anesthetics act via loose, structurally non-specific membrane partitioning.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Muskarinik reseptör dar ve asimetrik bir 3D kilit-anahtar cebine sahiptir. (+)-Muskarin (ötomer) 3 temas noktasını kusursuz kilitlerken, (-)-muskarin (distomer) stereokimyasal uyumsuzluk yüzünden bu bağı kaybeder (ER = 700). Anestezikler ise gevşek bağlanır.\",\"ar\":\"صحيح! يمتلك مستقبل المسكارين جيباً فراغياً ثلاثي الأبعاد شديد الدقة؛ يحقق (+)-muscarine تعشيقاً ثلاثي النقاط كاملاً بينما يفشل (-)-muscarine بفارق 700 ضعف. أما المخدرات العامة فترتبط برخاوة دون اشتراط تطابق كيرالي.\",\"en\":\"Correct! Muscarinic receptors feature a rigid stereoselective pocket where (+)-muscarine docks via 3-point complementarity (ER = 700). General anesthetics act via loose, non-specific membrane partitioning where stereochemistry is tolerated.\"}},{\"id\":\"opt-1b\",\"text\":{\"tr\":\"(-)-Muskarin aynadan geçerken radyoaktif ışıma yaparak tüm atomlarını anında parçalar.\",\"ar\":\"يطلق (-)-muscarine إشعاعاً نووياً يحطم كافة ذراته فور انعكاسه في المرآة.\",\"en\":\"(-)-Muscarine emits ionizing radiation that disintegrates its atoms upon mirror reflection.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Radyoaktif yıkım yanılgısı: Enantiyomerler kararlı kimyasal moleküllerdir; fark nükleer parçalanma değil reseptör aktif cebindeki 3 boyutlu uyumsuzluktur.\",\"ar\":\"خطأ الإشعاع: المصاوغات جزيئات كيميائية مستقرة؛ الفارق يعود لعدم التطابق الفراغي داخل جيب المستقبل وليس للنشاط الإشعاعي.\",\"en\":\"Radioactive decay misconception: Enantiomers are stable organic molecules; potency differences arise from 3D active site complementarity, not atomic transmutation.\"}},{\"id\":\"opt-1c\",\"text\":{\"tr\":\"İnsan vücudunda yalnızca sağ elli molekülleri parçalayan devasa bir makas enzimi bulunur.\",\"ar\":\"يمتلك جسم الإنسان مقصاً أنزيمياً عملاقاً يحطم الجزيئات يمينية التدوير حصراً.\",\"en\":\"The human body possesses a giant scissor enzyme that hydrolyzes all dextrorotatory molecules.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Genel kiral makas yanılgısı: Vücutta tüm sağ elli molekülleri yıkan tek bir enzim yoktur; her reseptör ve enzim kendi spesifik cebine göre stereoseçicidir.\",\"ar\":\"خطأ المقص الشامل: لا يوجد أنزيم عام يحطم كل مصاوغ يميني؛ بل يمتلك كل مستقبل وإنزيم جيباً خاصاً يحدد انتقائيته الفراغية.\",\"en\":\"Universal scissor misconception: There is no universal stereospecific destructive enzyme; stereoselectivity is mediated pocket-by-pocket across unique macromolecular targets.\"}}]},\"technicalTerms\":[{\"term\":\"ötomer (eutomer)\",\"arContext\":\"المصاوغ الفعال (eutomer)\"},{\"term\":\"distomer\",\"arContext\":\"المصاوغ الأضعف (distomer)\"},{\"term\":\"eudismik oran (ER)\",\"arContext\":\"النسبة الإيوديزمية (eudismic ratio)\"}],\"hints\":[{\"tr\":\"İki molekülün hedef reseptör cebindeki 3 boyutlu kilit-anahtar uyumunu düşünün.\",\"ar\":\"فكر في نموذج القفل والمفتاح ثلاثي الأبعاد داخل جيب المستقبل المستهدف.\",\"en\":\"Consider the 3D lock-and-key complementarity inside the macromolecular binding pocket.\"},{\"tr\":\"Pfeiffer kuralına göre afinite arttıkça reseptör cebinin kiral seçiciliği aşırı artar.\",\"ar\":\"وفق قاعدة Pfeiffer، كلما زادت الألفة زادت الانتقائية الفراغية لجيب المستقبل بشكل هائل.\",\"en\":\"By Pfeiffer's rule, higher intrinsic affinity enforces rigorous pocket stereospecificity.\"},{\"tr\":\"Muskarin nanomolar seviyede rijit 3-nokta teması kurar; genel anestezikler ise hücresel membranlara gevşek ve spesifik olmayan şekilde dağılır.\",\"ar\":\"يرتبط المسكارين بتعشيق نانومولي صلب ثلاثي النقاط؛ بينما تتوزع المخدرات العامة برخاوة غير نوعية في الأغشية.\",\"en\":\"Muscarine demands tight 3-point stereochemical alignment, whereas volatile anesthetics act via loose, non-specific membrane partitioning.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":26}],\"config\":{\"options\":[{\"id\":\"opt-1a\",\"text\":\"Yüksek afiniteli muskarin dar ve rijit bir cebe milimetrik 3-nokta uyumuyla oturur; genel anestezikler ise lipid membranda gevşek ve spesifik olmayan bağlar kurar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Muskarinik reseptör dar ve asimetrik bir 3D kilit-anahtar cebine sahiptir. (+)-Muskarin (ötomer) 3 temas noktasını kusursuz kilitlerken, (-)-muskarin (distomer) stereokimyasal uyumsuzluk yüzünden bu bağı kaybeder (ER = 700). Anestezikler ise gevşek bağlanır.\"},{\"id\":\"opt-1b\",\"text\":\"(-)-Muskarin aynadan geçerken radyoaktif ışıma yaparak tüm atomlarını anında parçalar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Radyoaktif yıkım yanılgısı: Enantiyomerler kararlı kimyasal moleküllerdir; fark nükleer parçalanma değil reseptör aktif cebindeki 3 boyutlu uyumsuzluktur.\"},{\"id\":\"opt-1c\",\"text\":\"İnsan vücudunda yalnızca sağ elli molekülleri parçalayan devasa bir makas enzimi bulunur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Genel kiral makas yanılgısı: Vücutta tüm sağ elli molekülleri yıkan tek bir enzim yoktur; her reseptör ve enzim kendi spesifik cebine göre stereoseçicidir.\"}],\"revealedOutcome\":{\"tr\":\"Yüksek afiniteli muskarin dar ve rijit bir cebe milimetrik 3-nokta uyumuyla oturur; genel anestezikler ise lipid membranda gevşek ve spesifik olmayan bağlar kurar.\",\"ar\":\"يرسو المسكارين عالي الألفة في جيب ضيق بتطابق ثلاثي النقاط دقيق؛ بينما ترتبط المخدرات العامة برخاوة غير نوعية في الغشاء الدهني.\",\"en\":\"High-affinity muscarine binds a narrow, rigid pocket demanding 3-point stereocomplementarity; volatile anesthetics act via loose, structurally non-specific membrane partitioning.\"},\"explanation\":{\"tr\":\"Doğru! Muskarinik reseptör dar ve asimetrik bir 3D kilit-anahtar cebine sahiptir. (+)-Muskarin (ötomer) 3 temas noktasını kusursuz kilitlerken, (-)-muskarin (distomer) stereokimyasal uyumsuzluk yüzünden bu bağı kaybeder (ER = 700). Anestezikler ise gevşek bağlanır.\",\"ar\":\"صحيح! يمتلك مستقبل المسكارين جيباً فراغياً ثلاثي الأبعاد شديد الدقة؛ يحقق (+)-muscarine تعشيقاً ثلاثي النقاط كاملاً بينما يفشل (-)-muscarine بفارق 700 ضعف. أما المخدرات العامة فترتبط برخاوة دون اشتراط تطابق كيرالي.\",\"en\":\"Correct! Muscarinic receptors feature a rigid stereoselective pocket where (+)-muscarine docks via 3-point complementarity (ER = 700). General anesthetics act via loose, non-specific membrane partitioning where stereochemistry is tolerated.\"}}},{\"id\":\"mc-mod4-les1-step-02\",\"stage\":\"question\",\"stageIndex\":2,\"type\":\"question\",\"title\":{\"tr\":\"Aktif Soru: Distomer Daima Etkisiz Bir Seyirci midir?\",\"ar\":\"سؤال تفاعلي: هل المصاوغ الخامل مجرد متفرج عديم الأثر؟\",\"en\":\"Active Question: Is the Distomer Always an Inert Bystander?\"},\"prompt\":{\"tr\":\"Kiral bir ilacın düşük afiniteli enantiyomeri (distomer) vücutta yalnızca etkisiz, pasif bir seyirci midir, yoksa bağımsız klinik ve toksikolojik etkilere yol açabilir mi?\",\"ar\":\"هل يقتصر دور المصاوغ الأضعف (distomer) في الجسم على كونه متفرجاً خامل الشحنة، أم يمكن أن يحدث تأثيرات سريرية وسمية مستقلة بذاتها؟\",\"en\":\"Is the low-affinity enantiomer (distomer) of a chiral drug merely an inert bystander in vivo, or can it exert independent pharmacological and toxicological actions?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-2a\",\"text\":{\"tr\":\"Hayır; distomer hedef dışı reseptörlere bağlanarak bağımsız toksisite oluşturabilir (talidomid, prilokain) veya hedef reseptörde tam zıt antagonist etki gösterebilir (pisenadol).\",\"ar\":\"كلا؛ يمكن للـ distomer أن يسبب سمية خطيرة بارتباطه بأهداف أخرى (ثاليدوميد، بريلوكائين) أو يناهض نفس المستقبل (بيسينادول).\",\"en\":\"No; distomers can mediate severe off-target toxicity (thalidomide, prilocaine) or act as functional antagonists at the target receptor (picenadol).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika! Distomer biyolojik olarak masum değildir. Hedef reseptörde inaktif olsa bile karaciğerde toksik metabolit üretebilir (prilokain -> o-toluidin), teratojenik etki yapabilir (S-talidomid) veya zıt antagonist olabilir (pisenadol).\",\"ar\":\"ممتاز! ليس distomer بريئاً بيولوجياً؛ إذ يمكن أن يتحول لمستقلب سام في الكبد (بريلوكائين)، أو يسبب تشوهاً جنينياً (ثاليدوميد)، أو يعاكس المستقبل كمضاد (بيسينادول).\",\"en\":\"Brilliant! Distomers are pharmacologically active xenobiotics; they can generate toxic metabolites (prilocaine -> o-toluidine), induce teratogenesis (S-thalidomide), or act as opposing antagonists (picenadol).\"}},{\"id\":\"opt-2b\",\"text\":{\"tr\":\"Evet; distomer tanımı gereği vücutta hiçbir biyomoleküle dokunamaz ve suda hemen buharlaşır.\",\"ar\":\"نعم؛ بحكم تعريفه يعجز distomer عن لمس أي جزيء حيوي ويتبخر في الماء فوراً.\",\"en\":\"Yes; by definition, distomers cannot interact with any biomolecules and immediately evaporate.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Mutlak atıllık yanılgısı: Distomerler kimyasal olarak aktiftir; diğer enzim ve reseptörlerle etkileşerek ciddi yan etkilere yol açabilir.\",\"ar\":\"خطأ الخمول المطلق: جزيئات distomer نشطة كيميائياً وتتفاعل مع أنزيمات ومستقبلات أخرى مسببة سميات خطيرة.\",\"en\":\"Absolute inertness misconception: Distomers are chemically identical isomers that interact with other off-target receptors and metabolic enzymes.\"}},{\"id\":\"opt-2c\",\"text\":{\"tr\":\"Evet; çünkü böbrekler düşük afiniteli izomerleri saniyeler içinde tespit edip yok eder.\",\"ar\":\"نعم؛ لأن الكلى ترصد المصاوغات ضعيفة الألفة وتطرحها خلال أجزاء من الثانية.\",\"en\":\"Yes; because the kidneys filter and destroy low-affinity enantiomers within microseconds.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Böbrek seçicilik yanılgısı: Glomerüler filtrasyon stereoseçici değildir; molekül ağırlığı ve proteine bağlanmaya bakar.\",\"ar\":\"خطأ الانتقائية الكلوية: الترشيح الكبيبي غير انتقائي فراغياً؛ ويعتمد على الوزن الجزيئي والارتباط البروتيني.\",\"en\":\"Renal stereoselection misconception: Glomerular filtration is non-stereoselective, driven by molecular size and plasma protein binding.\"}}]},\"technicalTerms\":[{\"term\":\"distomer toksisitesi\",\"arContext\":\"سمية المصاوغ الخامل (distomer toxicity)\"},{\"term\":\"hedef dışı etki\",\"arContext\":\"التأثير خارج الهدف (off-target effect)\"}],\"hints\":[{\"tr\":\"Talidomid faciasını ve prilokain kaynaklı methemoglobinemiyi düşünün.\",\"ar\":\"تذكر كارثة الثاليدوميد المشوهة وميتهيموغلوبين الدم الناجم عن البريلوكائين.\",\"en\":\"Think of the thalidomide phocomelia catastrophe and prilocaine-induced cyanosis.\"},{\"tr\":\"Bir izomer ana reseptörde zayıf bağlansa bile başka bir enzimin aktif bölgesine mükemmel oturabilir.\",\"ar\":\"حتى لو ارتبط المصاوغ بضعف بالمستقبل الرئيسي، فقد يلائم جيب أنزيم آخر بإحكام مسبباً كارثة.\",\"en\":\"Even if an isomer binds weakly to the therapeutic receptor, it may fit an off-target enzyme or receptor perfectly.\"},{\"tr\":\"Distomerler inaktif olabileceği gibi toksik (talidomid), metabolik yük (prilokain) veya hedef reseptörde antagonist (pisenadol) olabilir.\",\"ar\":\"قد يكون distomer خاملاً، أو ساماً (ثاليدوميد)، أو مولداً لمستقلب خطير (بريلوكائين)، أو مضاداً معطِلاً (بيسينادول).\",\"en\":\"Distomers can manifest as inert ballast, toxic culprits (thalidomide), precursor to toxic metabolites (prilocaine), or opposing antagonists (picenadol).\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":29}],\"config\":{\"options\":[{\"id\":\"opt-2a\",\"text\":\"Hayır; distomer hedef dışı reseptörlere bağlanarak bağımsız toksisite oluşturabilir (talidomid, prilokain) veya hedef reseptörde tam zıt antagonist etki gösterebilir (pisenadol).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika! Distomer biyolojik olarak masum değildir. Hedef reseptörde inaktif olsa bile karaciğerde toksik metabolit üretebilir (prilokain -> o-toluidin), teratojenik etki yapabilir (S-talidomid) veya zıt antagonist olabilir (pisenadol).\"},{\"id\":\"opt-2b\",\"text\":\"Evet; distomer tanımı gereği vücutta hiçbir biyomoleküle dokunamaz ve suda hemen buharlaşır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Mutlak atıllık yanılgısı: Distomerler kimyasal olarak aktiftir; diğer enzim ve reseptörlerle etkileşerek ciddi yan etkilere yol açabilir.\"},{\"id\":\"opt-2c\",\"text\":\"Evet; çünkü böbrekler düşük afiniteli izomerleri saniyeler içinde tespit edip yok eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Böbrek seçicilik yanılgısı: Glomerüler filtrasyon stereoseçici değildir; molekül ağırlığı ve proteine bağlanmaya bakar.\"}],\"revealedOutcome\":{\"tr\":\"Hayır; distomer hedef dışı reseptörlere bağlanarak bağımsız toksisite oluşturabilir (talidomid, prilokain) veya hedef reseptörde tam zıt antagonist etki gösterebilir (pisenadol).\",\"ar\":\"كلا؛ يمكن للـ distomer أن يسبب سمية خطيرة بارتباطه بأهداف أخرى (ثاليدوميد، بريلوكائين) أو يناهض نفس المستقبل (بيسينادول).\",\"en\":\"No; distomers can mediate severe off-target toxicity (thalidomide, prilocaine) or act as functional antagonists at the target receptor (picenadol).\"},\"explanation\":{\"tr\":\"Harika! Distomer biyolojik olarak masum değildir. Hedef reseptörde inaktif olsa bile karaciğerde toksik metabolit üretebilir (prilokain -> o-toluidin), teratojenik etki yapabilir (S-talidomid) veya zıt antagonist olabilir (pisenadol).\",\"ar\":\"ممتاز! ليس distomer بريئاً بيولوجياً؛ إذ يمكن أن يتحول لمستقلب سام في الكبد (بريلوكائين)، أو يسبب تشوهاً جنينياً (ثاليدوميد)، أو يعاكس المستقبل كمضاد (بيسينادول).\",\"en\":\"Brilliant! Distomers are pharmacologically active xenobiotics; they can generate toxic metabolites (prilocaine -> o-toluidine), induce teratogenesis (S-thalidomide), or act as opposing antagonists (picenadol).\"}}},{\"id\":\"mc-mod4-les1-step-03\",\"stage\":\"intuition\",\"stageIndex\":3,\"type\":\"intuition\",\"title\":{\"tr\":\"Sezgisel Model: Kasa Kilidi vs Bahçe Kapısı Mandalı\",\"ar\":\"النموذج الحسي: قفل الخزنة المصرفية مقابل مزلاج الباب\",\"en\":\"Intuitive Mental Model: Bank Vault vs Screen Door Latch\"},\"prompt\":{\"tr\":\"Yüksek güvenlikli bir banka kasası milimetrik bir anahtar dişi ister; anahtardaki tek bir kusur kilidi açmaz. Gevşek bir bahçe mandalını ise herhangi bir tel açabilir. Bu model Pfeiffer kuralını nasıl açıklar?\",\"ar\":\"يتطلب قفل الخزنة المصرفية تطابقاً ميكرونياً؛ وخطأ واحد يمنع الفتح. بينما يفتح مزلاج الباب الرخو بأي سلك. كيف يفسر هذا النموذج قاعدة Pfeiffer؟\",\"en\":\"A high-security bank vault requires microscopic key alignment; a single notch error blocks opening. But a loose garden latch opens with any bent wire. How does this explain Pfeiffer's rule?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-3a\",\"text\":{\"tr\":\"Yüksek afiniteli ilaçlar dar cebi kusursuz doldurmalıdır (enantiyomer hatası affedilmez, ER fırlar); zayıf ilaçlar ise gevşek bağlanır, kiral hataları tolere eder (ER bire yaklaşır).\",\"ar\":\"تتطلب الأدوية عالية الألفة تطابقاً ميكرونياً ضيقاً يرفع ER؛ بينما ترتبط الأدوية الضعيفة برخاوة تتسامح مع العيوب الكيرالية مقتربة من 1.\",\"en\":\"High-affinity drugs demand strict complementary fit (zero chiral tolerance, ER explodes); low-affinity drugs bind loosely, tolerating stereochemical mismatch (ER -> 1).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika bir zihinsel model! Carl Pfeiffer 1956'da bunu keşfetmiştir: Pikomolar/nanomolar afiniteye sahip ilaçlar reseptör cebini milimetrik doldurur; distomerdeki tek bir temas kaybı afiniteyi yüzlerce kat düşürür. Mikromolar ilaçlar ise gevşek tutunur ve kiral hatayı tolere eder.\",\"ar\":\"نموذج ذهني رائع! أثبت كارل فايفر (1956): تتطلب الأدوية البيكومولية تطابقاً شديد الإحكام؛ وغياب رابطة واحدة في distomer يهوي بالألفة مئات الأضعاف. أما الأدوية الرخوة فتتسامح مع الخطأ الكيرالي.\",\"en\":\"Brilliant mental model! Carl Pfeiffer (1956) recognized that high-affinity binding enforces rigid active site complementarity; losing one contact heavily penalizes the distomer. Loose, low-affinity binding easily tolerates inverted chiral centers.\"}},{\"id\":\"opt-3b\",\"text\":{\"tr\":\"Banka kasaları pozitif yüklüdür, bahçe kapıları ise negatif elektrik yüküyle çalışır.\",\"ar\":\"خزائن البنوك موجبة الشحنة، بينما تعمل بوابات الحدائق بالكهرباء السالبة.\",\"en\":\"Bank vaults carry positive static charge, while garden gates operate via negative electricity.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Elektrik yükü yanılgısı: Bu bir fiziksel elektrostatik yük meselesi değil, 3 boyutlu kavitelerdeki uzaysal sterik tolerans modelidir.\",\"ar\":\"خطأ الشحنة: المسألة لا تتعلق بشحنات كهربائية بل بمرونة التسامح الفراغي ثلاثي الأبعاد في الجيب.\",\"en\":\"Charge misconception: This analogy addresses 3D spatial complementarity and steric tolerance, not electrostatic charges.\"}},{\"id\":\"opt-3c\",\"text\":{\"tr\":\"Gevşek bahçe kapısı ilaç moleküllerini kovalent olarak parçalayan bir nükleofildir.\",\"ar\":\"مزلاج الباب الرخو كهرومحب يحطم جزيئات الدواء تساهمياً.\",\"en\":\"The loose latch is a reactive nucleophile that covalently cleaves drug ligands.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Reaktif kovalent yanılgı: Model gevşek, spesifik olmayan non-kovalent bağlanmayı simgeler.\",\"ar\":\"خطأ التفاعل التساهمي: يمثل المزلاج الارتباط الرخو غير النوعي ضعيف الألفة.\",\"en\":\"Covalent misconception: The latch illustrates weak, reversible non-specific binding.\"}}]},\"technicalTerms\":[{\"term\":\"Pfeiffer kuralı\",\"arContext\":\"قاعدة Pfeiffer\"},{\"term\":\"kiral tolerans\",\"arContext\":\"التسامح الكيرالي (chiral tolerance)\"}],\"hints\":[{\"tr\":\"Banka kasası mikron düzeyinde dar ve rijit bir anahtar yarığına sahiptir.\",\"ar\":\"يمتلك قفل الخزنة شقاً دقيقاً ضيقاً لا يتسامح مع أي انحراف.\",\"en\":\"A bank vault keyway is rigid and narrow, demanding zero deviation.\"},{\"tr\":\"Afinite ne kadar yüksekse, ligand reseptör cebine o kadar sıkı ve kusursuz oturmak zorundadır.\",\"ar\":\"كلما ارتفعت الألفة، توجب على اللجين الاستقرار بإحكام تام داخل جيب المستقبل.\",\"en\":\"The higher the affinity, the more tightly the ligand must complement pocket geometry.\"},{\"tr\":\"Yüksek afiniteli kilitte tek bir yanlış diş kilidi açtırmaz (ER devasa büyür); gevşek mandalda ise dişlerin yönü fark etmez (ER 1'e yaklaşır).\",\"ar\":\"في القفل الدقيق يمنع سن واحد خاطئ الفتح (يرتفع ER هائلاً)؛ بينما لا يؤثر اتجاه الأسنان في المزلاج الرخو (يقترب ER من 1).\",\"en\":\"In a high-affinity lock, one misaligned contact ruins binding (huge ER); in a loose pocket, stereochemical flaws are forgiven (ER -> 1).\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":28}],\"config\":{\"options\":[{\"id\":\"opt-3a\",\"text\":\"Yüksek afiniteli ilaçlar dar cebi kusursuz doldurmalıdır (enantiyomer hatası affedilmez, ER fırlar); zayıf ilaçlar ise gevşek bağlanır, kiral hataları tolere eder (ER bire yaklaşır).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika bir zihinsel model! Carl Pfeiffer 1956'da bunu keşfetmiştir: Pikomolar/nanomolar afiniteye sahip ilaçlar reseptör cebini milimetrik doldurur; distomerdeki tek bir temas kaybı afiniteyi yüzlerce kat düşürür. Mikromolar ilaçlar ise gevşek tutunur ve kiral hatayı tolere eder.\"},{\"id\":\"opt-3b\",\"text\":\"Banka kasaları pozitif yüklüdür, bahçe kapıları ise negatif elektrik yüküyle çalışır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Elektrik yükü yanılgısı: Bu bir fiziksel elektrostatik yük meselesi değil, 3 boyutlu kavitelerdeki uzaysal sterik tolerans modelidir.\"},{\"id\":\"opt-3c\",\"text\":\"Gevşek bahçe kapısı ilaç moleküllerini kovalent olarak parçalayan bir nükleofildir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Reaktif kovalent yanılgı: Model gevşek, spesifik olmayan non-kovalent bağlanmayı simgeler.\"}],\"revealedOutcome\":{\"tr\":\"Yüksek afiniteli ilaçlar dar cebi kusursuz doldurmalıdır (enantiyomer hatası affedilmez, ER fırlar); zayıf ilaçlar ise gevşek bağlanır, kiral hataları tolere eder (ER bire yaklaşır).\",\"ar\":\"تتطلب الأدوية عالية الألفة تطابقاً ميكرونياً ضيقاً يرفع ER؛ بينما ترتبط الأدوية الضعيفة برخاوة تتسامح مع العيوب الكيرالية مقتربة من 1.\",\"en\":\"High-affinity drugs demand strict complementary fit (zero chiral tolerance, ER explodes); low-affinity drugs bind loosely, tolerating stereochemical mismatch (ER -> 1).\"},\"explanation\":{\"tr\":\"Harika bir zihinsel model! Carl Pfeiffer 1956'da bunu keşfetmiştir: Pikomolar/nanomolar afiniteye sahip ilaçlar reseptör cebini milimetrik doldurur; distomerdeki tek bir temas kaybı afiniteyi yüzlerce kat düşürür. Mikromolar ilaçlar ise gevşek tutunur ve kiral hatayı tolere eder.\",\"ar\":\"نموذج ذهني رائع! أثبت كارل فايفر (1956): تتطلب الأدوية البيكومولية تطابقاً شديد الإحكام؛ وغياب رابطة واحدة في distomer يهوي بالألفة مئات الأضعاف. أما الأدوية الرخوة فتتسامح مع الخطأ الكيرالي.\",\"en\":\"Brilliant mental model! Carl Pfeiffer (1956) recognized that high-affinity binding enforces rigid active site complementarity; losing one contact heavily penalizes the distomer. Loose, low-affinity binding easily tolerates inverted chiral centers.\"}}},{\"id\":\"mc-mod4-les1-step-04\",\"stage\":\"visual_explanation\",\"stageIndex\":4,\"type\":\"visual_explanation\",\"title\":{\"tr\":\"Dört Biyolojik Filtre: Enantiyomerlerin Vücuttaki Yolculuğu\",\"ar\":\"المرشحات البيولوجية الأربعة: رحلة المصاوغات في الجسم\",\"en\":\"Four Biological Filters: Enantiomer In Vivo Journey\"},\"prompt\":{\"tr\":\"Enantiyomerler vücutta 4 kiral filtreyle karşılaşır: LAT-1 taşıyıcısı, albumin plazma proteini, CYP450 enzimleri ve hedef reseptör. LAT-1 taşıyıcısının L-Dopa'yı beyne alıp D-Dopa'yı reddetmesi hangi filtreye örnektir?\",\"ar\":\"تواجه المصاوغات 4 مرشحات كيرالية: ناقل LAT-1، ألبومين البلازما، أنزيمات CYP450، والمستقبل. إدخال LAT-1 لـ L-Dopa للدماغ ورفض D-Dopa يمثل أي مرشح؟\",\"en\":\"Enantiomers face 4 chiral filters: LAT-1 transporters, albumin binding, CYP450 oxidation, and target receptors. LAT-1 transporting L-Dopa across the BBB while rejecting D-Dopa exemplifies which filter?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-4a\",\"text\":{\"tr\":\"Membran taşıyıcı stereoseçiciliği; taşıyıcı protein kiral bir cep içerir ve yalnızca L-konfigürasyonundaki amino asit iskeletini tanıyarak aktif olarak içeri taşır.\",\"ar\":\"انتقائية النواقل الغشائية؛ يمتلك بروتين النقل جيباً كيرالياً يتعرف حصراً على هيئة L للحمض الأميني وينقله فعالاً.\",\"en\":\"Membrane transporter stereoselectivity; the carrier protein possesses an asymmetric binding alcove that strictly accepts the L-enantiomer for active transport.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel! Slide 24'teki 4 biyolojik filtre: 1) Membran taşıyıcı seçiciliği (LAT-1 L-Dopa'yı taşır, D-Dopa'yı taşımaz), 2) Plazma proteini bağlanması, 3) Metabolik enzimler (CYP2C19 S-heksobarbitali yıkar, R değişmeden kalır), 4) Reseptör stereoseçiciliği.\",\"ar\":\"ممتاز! مرشحات السلايد 24: 1) انتقائية النواقل (LAT-1 ينقل L-Dopa ويرفض D-Dopa)، 2) الارتباط بألبومين البلازما، 3) أنزيمات الاستقلاب (CYP2C19 يؤكسد S-hexobarbital)، 4) انتقائية المستقبل.\",\"en\":\"Perfect! Slide 24 details the 4 biological chiral filters: 1) Active transporter stereoselection (LAT-1 recognizes L-Dopa, rejecting D-Dopa), 2) Plasma protein binding (albumin/AAG), 3) Metabolic enzymes (CYP2C19 stereoselective oxidation of S-hexobarbital), and 4) Target receptor stereo-docking.\"}},{\"id\":\"opt-4b\",\"text\":{\"tr\":\"Plazma proteini filtresi; D-Dopa albümine bağlanarak böbreklerden hızla buharlaşır.\",\"ar\":\"مرشح بروتين البلازما؛ يرتبط D-Dopa بالألبومين ليتبخر عبر الكلى فوراً.\",\"en\":\"Plasma protein filtration; D-Dopa binds albumin and evaporates through renal tubules.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Buharlaşma yanılgısı: D-Dopa buharlaşmaz; kan-beyin bariyerini geçemediği için periferde kalır ve dekarboksile olur.\",\"ar\":\"خطأ التبخر: لا يتبخر D-Dopa بل يعجز عن عبور الحاجز الدماغي الدموي ويتخرب محيطياً.\",\"en\":\"Evaporation misconception: D-Dopa cannot cross the blood-brain barrier because LAT-1 stereoselectively rejects it.\"}},{\"id\":\"opt-4c\",\"text\":{\"tr\":\"Tüm filtreler aynı anda kovalent bağ kurarak D-Dopa'yı kalıcı plastik bir maddeye çevirir.\",\"ar\":\"تشكل كافة المرشحات روابط تساهمية تحول D-Dopa لبلاستيك صلب.\",\"en\":\"All filters establish covalent bonds, transmuting D-Dopa into an insoluble polymer.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kovalent polimerleşme yanılgısı: LAT-1 geri dönüşümlü bir aktif taşıyıcıdır; polimerizasyon yapmaz.\",\"ar\":\"خطأ البلمرة: LAT-1 ناقل عبر غشائي عكوس ولا يشكل بوليمرات بلاستيكية.\",\"en\":\"Polymerization misconception: LAT-1 is a membrane transport protein that operates via non-covalent conformational cycling.\"}}]},\"technicalTerms\":[{\"term\":\"LAT-1 taşıyıcısı\",\"arContext\":\"ناقل LAT-1 للأحماض الأمينية\"},{\"term\":\"biyolojik kiral filtreler\",\"arContext\":\"المرشحات الحيوية الكيرالية\"}],\"hints\":[{\"tr\":\"L-Dopa Parkinson tedavisinde kan-beyin bariyerini aşmak zorundadır.\",\"ar\":\"يجب أن يعبر L-Dopa الحاجز الدماغي الدموي لعلاج الباركنسون.\",\"en\":\"L-Dopa must cross the blood-brain barrier to treat Parkinson's disease.\"},{\"tr\":\"Beyin damarlarındaki LAT-1 proteini doğal L-amino asitleri içeri alan kiral bir taşıyıcıdır.\",\"ar\":\"ناقل LAT-1 في الأوعية الدماغية ناقل كيرالي يدخل أحماض L الأمينية الطبيعية حصراً.\",\"en\":\"LAT-1 in cerebral capillary endothelia is a stereoselective transporter recognizing L-configured amino acids.\"},{\"tr\":\"LAT-1 D-Dopa'yı tanımaz ve geçirmez; bu durum membran taşıyıcı stereoseçiciliğinin en çarpıcı kanıtıdır.\",\"ar\":\"يرفض LAT-1 مصاوغ D-Dopa؛ مما يثبت انتقائية النواقل الغشائية الفراغية.\",\"en\":\"LAT-1 strictly excludes D-Dopa, demonstrating the first line of in vivo pharmacokinetic chiral filtering.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":24}],\"config\":{\"options\":[{\"id\":\"opt-4a\",\"text\":\"Membran taşıyıcı stereoseçiciliği; taşıyıcı protein kiral bir cep içerir ve yalnızca L-konfigürasyonundaki amino asit iskeletini tanıyarak aktif olarak içeri taşır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel! Slide 24'teki 4 biyolojik filtre: 1) Membran taşıyıcı seçiciliği (LAT-1 L-Dopa'yı taşır, D-Dopa'yı taşımaz), 2) Plazma proteini bağlanması, 3) Metabolik enzimler (CYP2C19 S-heksobarbitali yıkar, R değişmeden kalır), 4) Reseptör stereoseçiciliği.\"},{\"id\":\"opt-4b\",\"text\":\"Plazma proteini filtresi; D-Dopa albümine bağlanarak böbreklerden hızla buharlaşır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Buharlaşma yanılgısı: D-Dopa buharlaşmaz; kan-beyin bariyerini geçemediği için periferde kalır ve dekarboksile olur.\"},{\"id\":\"opt-4c\",\"text\":\"Tüm filtreler aynı anda kovalent bağ kurarak D-Dopa'yı kalıcı plastik bir maddeye çevirir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kovalent polimerleşme yanılgısı: LAT-1 geri dönüşümlü bir aktif taşıyıcıdır; polimerizasyon yapmaz.\"}],\"revealedOutcome\":{\"tr\":\"Membran taşıyıcı stereoseçiciliği; taşıyıcı protein kiral bir cep içerir ve yalnızca L-konfigürasyonundaki amino asit iskeletini tanıyarak aktif olarak içeri taşır.\",\"ar\":\"انتقائية النواقل الغشائية؛ يمتلك بروتين النقل جيباً كيرالياً يتعرف حصراً على هيئة L للحمض الأميني وينقله فعالاً.\",\"en\":\"Membrane transporter stereoselectivity; the carrier protein possesses an asymmetric binding alcove that strictly accepts the L-enantiomer for active transport.\"},\"explanation\":{\"tr\":\"Mükemmel! Slide 24'teki 4 biyolojik filtre: 1) Membran taşıyıcı seçiciliği (LAT-1 L-Dopa'yı taşır, D-Dopa'yı taşımaz), 2) Plazma proteini bağlanması, 3) Metabolik enzimler (CYP2C19 S-heksobarbitali yıkar, R değişmeden kalır), 4) Reseptör stereoseçiciliği.\",\"ar\":\"ممتاز! مرشحات السلايد 24: 1) انتقائية النواقل (LAT-1 ينقل L-Dopa ويرفض D-Dopa)، 2) الارتباط بألبومين البلازما، 3) أنزيمات الاستقلاب (CYP2C19 يؤكسد S-hexobarbital)، 4) انتقائية المستقبل.\",\"en\":\"Perfect! Slide 24 details the 4 biological chiral filters: 1) Active transporter stereoselection (LAT-1 recognizes L-Dopa, rejecting D-Dopa), 2) Plasma protein binding (albumin/AAG), 3) Metabolic enzymes (CYP2C19 stereoselective oxidation of S-hexobarbital), and 4) Target receptor stereo-docking.\"}}},{\"id\":\"mc-mod4-les1-step-05\",\"stage\":\"interactive_artifact\",\"stageIndex\":5,\"type\":\"dose_response_curve\",\"widgetType\":\"DoseResponseCurve\",\"widget\":{\"type\":\"DoseResponseCurve\",\"config\":{\"title\":\"Pisenadol Enantiyomer Çifti: Agonist ve Antagonist Eğrileri\",\"prompt\":\"(+)-Pisenadol agonisti ile (-)-pisenadol antagonistinin eğrilerini karşılaştırın.\",\"defaultEc50\":10,\"defaultEmax\":100,\"defaultHillSlope\":1,\"modes\":[\"agonist\",\"competitive_antagonist\",\"partial_agonist\"],\"source\":{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":35},\"explanation\":\"(+)-Pisenadol mu-opioid reseptörünü tam aktive eden bir ötomerdir; (-)-pisenadol ise aynı cebi bloke eden distomerik kompetitif antagonisttir. Rasemat ise parsiyel agonist profil sergiler.\"}},\"title\":{\"tr\":\"İnteraktif Laboratuvar: Pisenadol Enantiyomer Doz-Yanıt Eğrisi\",\"ar\":\"مختبر تفاعلي: منحنى الجرعة والاستجابة لمصاوغات البيسينادول\",\"en\":\"Interactive Lab: Picenadol Enantiomer Dose-Response Curve\"},\"prompt\":{\"tr\":\"(+)-Pisenadol tam agonist, (-)-pisenadol ise kompetitif antagonisttir. Eğrileri değiştirerek antagonizma modunda sağa kaymayı ve rasematın parsiyel agonist profilini inceleyin.\",\"ar\":\"(+)-Picenadol منبه كامل، بينما (-)-picenadol مضاد تنافسي. بدل الأنماط لتلاحظ إزاحة المنحنى لليمين وسلوك الخليط الراسيمي كمنبه جزئي.\",\"en\":\"(+)-Picenadol is a full agonist; (-)-picenadol is a competitive antagonist. Toggle modes to observe the rightward EC50 shift and the partial agonist behavior of the racemate.\"},\"predictThenReveal\":false,\"config\":{\"title\":\"Pisenadol Enantiyomer Çifti: Agonist ve Antagonist Eğrileri\",\"prompt\":\"(+)-Pisenadol agonisti ile (-)-pisenadol antagonistinin eğrilerini karşılaştırın.\",\"defaultEc50\":10,\"defaultEmax\":100,\"defaultHillSlope\":1,\"modes\":[\"agonist\",\"competitive_antagonist\",\"partial_agonist\"],\"source\":{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":35},\"explanation\":\"(+)-Pisenadol mu-opioid reseptörünü tam aktive eden bir ötomerdir; (-)-pisenadol ise aynı cebi bloke eden distomerik kompetitif antagonisttir. Rasemat ise parsiyel agonist profil sergiler.\"},\"technicalTerms\":[{\"term\":\"enantiyomerik antagonizma\",\"arContext\":\"المناهضة بين المصاوغات (enantiomeric antagonism)\"},{\"term\":\"sağa kayma (surmountable shift)\",\"arContext\":\"إزاحة المنحنى لليمين\"}],\"hints\":[{\"tr\":\"(+)-Pisenadol morfin benzeri güçlü bir analjezik agonisttir (Emax = %100).\",\"ar\":\"(+)-Picenadol منبه مسكن قوي مشابه للمورفين (Emax = 100%).\",\"en\":\"(+)-Picenadol acts as a full opioid analgesic agonist (Emax = 100%).\"},{\"tr\":\"(-)-Pisenadol nalokson benzeri bir antagonisttir; agonist eğrisini sağa kaydırır.\",\"ar\":\"(-)-Picenadol مضاد منافس شبيه بالنالوكسون؛ يزيح منحنى الجرعة لليمين.\",\"en\":\"(-)-Picenadol acts as a competitive antagonist, shifting the agonist curve rightward.\"},{\"tr\":\"İki izomer birlikte verildiğinde (rasemat), antagonist ötomeri frenler ve ortaya parsiyel agonist bir profil çıkar.\",\"ar\":\"عند إعطاء المصاوغين معاً كخليط راسيمي، يكبح المضاد المنبه ليظهر سلوك المنبه الجزئي.\",\"en\":\"In the racemate, mutual competition produces an intermediate partial agonist profile.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":35}]},{\"id\":\"mc-mod4-les1-step-06\",\"stage\":\"guided_discovery\",\"stageIndex\":6,\"type\":\"guided_discovery\",\"title\":{\"tr\":\"Rehberli Keşif: Epinin Kanıtı ve Easson-Stedman Hipotezi\",\"ar\":\"استكشاف موجه: برهان الإيبينين وفرضية Easson-Stedman\",\"en\":\"Guided Discovery: The Epinine Proof & Easson-Stedman Model\"},\"prompt\":{\"tr\":\"R(-)-adrenalin 3 noktadan kenetlenir (ER = 45); S(+)-adrenalinde beta-OH çözücüye bakar (2 nokta). beta-OH grubu hiç bulunmayan deoksiadrenalin (epinin) test edildiğinde afinitesi neden tam olarak S(+)-adrenalinle aynı çıkar?\",\"ar\":\"يرتبط R(-)-adrenalin بـ 3 نقاط (ER = 45)، وفي S(+)-adrenalin تتجه beta-OH للخارج (نقطتان). لماذا تتطابق ألفة epinine المجرد من beta-OH تماماً مع S(+)-adrenalin؟\",\"en\":\"R(-)-epinephrine docks via 3 points (ER = 45); S(+)-epinephrine's beta-OH faces solvent (2 points). When epinine (lacking beta-OH entirely) is tested, why does its affinity exactly equal S(+)-epinephrine?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-6a\",\"text\":{\"tr\":\"Easson-Stedman hipotezini doğrular: S(+)-adrenalinin beta-OH grubu bağlanmaya hiçbir enerji katkısı sağlamaz (0 kcal/mol); molekül tıpkı akiral epinin gibi sadece 2 temas noktasıyla tutunur.\",\"ar\":\"يثبت فرضية Easson-Stedman: لا تقدم beta-OH في S(+)-adrenalin أي طاقة ربط (0 kcal/mol)، فيرتبط بنقطتين تماماً كالإيبينين غير الكيرالي.\",\"en\":\"It proves the Easson-Stedman hypothesis: S(+)-epinephrine's misaligned beta-OH contributes 0 kcal/mol binding energy, engaging the exact same 2 contact points as achiral epinine.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika bir bilimsel çıkarım! Slide 25'te vurgulandığı gibi: R(-)-adrenalin 3 noktadan (katekol, amin, beta-OH) tam kenetlenir. S(+)-adrenalinde ise kiral konfigürasyon ters olduğu için beta-OH çözücüye bakar ve bağlanamaz. Epinin (deoksiadrenalin) beta-OH taşımamasına rağmen S-adrenalinle aynı güçtedir; çünkü ikisi de reseptöre yalnızca 2 noktadan tutunur!\",\"ar\":\"استنتاج علمي باهر! يرسو R(-)-adrenalin بثلاث نقاط كاملة؛ بينما في S(+)-adrenalin تتجه beta-OH للمذيب فتنعدم مساهمتها. ويمتلك epinine نفس القوة تماماً لأنه يرتبط بنقطتين فقط، مما يثبت صحة نموذج Easson-Stedman الحاسم.\",\"en\":\"Flawless deduction! Slide 25 highlights this classic benchmark: R(-)-epinephrine engages 3 points. In S(+)-epinephrine, the inverted beta-OH points into bulk solvent, providing 0 kcal/mol. Deoxyadrenaline (epinine) lacks beta-OH entirely and displays identical affinity, proving 2-point attachment.\"}},{\"id\":\"opt-6b\",\"text\":{\"tr\":\"Epinin vücutta kendiliğinden R(-)-adrenalin hormonuna dönüşerek kalbi aşırı uyarır.\",\"ar\":\"يتحول الإيبينين في الجسم تلقائياً إلى هرمون R(-)-adrenalin منبهاً القلب.\",\"en\":\"Epinine spontaneously synthesizes a chiral beta-OH in plasma, becoming R(-)-adrenaline.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kendiliğinden kiral sentez yanılgısı: Epinin akiral bir feniletilamindir; in vivo ortamda kendiliğinden şiral hidroksillenmez.\",\"ar\":\"خطأ الاصطناع التلقائي: الإيبينين مركب غير كيرالي ولا يكتسب هيدروكسيلاً فراغياً في البلازما تلقائياً.\",\"en\":\"Spontaneous synthesis misconception: Epinine is an achiral molecule; it does not spontaneously hydroxylate stereospecifically in plasma.\"}},{\"id\":\"opt-6c\",\"text\":{\"tr\":\"S(+)-adrenalin ve epinin reseptöre hiç bağlanamaz; yalnızca plasebo etkisi yaratırlar.\",\"ar\":\"يعجز كلاهما عن الارتباط بالمستقبل نهائياً ويقتصران على تأثير الغفل (بلاسيبو).\",\"en\":\"Neither S(+)-epinephrine nor epinine binds the receptor, producing only placebo effects.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Afinite sıfır yanılgısı: Her iki molekül de mikromolar düzeyde gerçek 2 noktalı adrenerjik agonisttir; afiniteleri sıfır değildir.\",\"ar\":\"خطأ انعدام الألفة: كلاهما يرتبط بألفة ميكرومولية حقيقية بنقطتين؛ والألفة ليست صفراً.\",\"en\":\"Zero affinity misconception: Both molecules bind with genuine micromolar affinity via 2 contact points.\"}}]},\"technicalTerms\":[{\"term\":\"Easson-Stedman 3-nokta hipotezi\",\"arContext\":\"فرضية Easson-Stedman ثلاثية النقاط\"},{\"term\":\"epinin (deoksiadrenalin)\",\"arContext\":\"إيبينين (منزوع الأكسجين)\"}],\"hints\":[{\"tr\":\"R(-)-adrenalinde 3 temas noktası vardır: Katekol, Sekonder Amin ve Beta-OH.\",\"ar\":\"يمتلك R(-)-adrenalin ثلاث نقاط تماس: الكاتيكول، الأمين، و beta-OH.\",\"en\":\"R(-)-epinephrine makes 3 contacts: catechol ring, secondary amine, and beta-OH.\"},{\"tr\":\"S(+)-adrenalin katekol ve amini bağlar; ancak beta-OH cebin dışına bakar (2 temas).\",\"ar\":\"يربط S(+)-adrenalin الكاتيكول والأمين؛ لكن beta-OH تتجه للخارج (تماس بنقطتين).\",\"en\":\"S(+)-epinephrine docks catechol and amine; its beta-OH faces solvent (2 contacts).\"},{\"tr\":\"Epininde beta-OH hiç yoktur; o da katekol ve amin olmak üzere tam 2 noktadan bağlanır. 2 temas = 2 temas!\",\"ar\":\"يخلو الإيبينين من beta-OH فيرتبط بنقطتين أيضاً؛ تماس بنقطتين = تماس بنقطتين!\",\"en\":\"Epinine completely lacks beta-OH, making the exact same 2 contacts as S(+)-epinephrine: 2 contacts = 2 contacts!\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":25}],\"config\":{\"options\":[{\"id\":\"opt-6a\",\"text\":\"Easson-Stedman hipotezini doğrular: S(+)-adrenalinin beta-OH grubu bağlanmaya hiçbir enerji katkısı sağlamaz (0 kcal/mol); molekül tıpkı akiral epinin gibi sadece 2 temas noktasıyla tutunur.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika bir bilimsel çıkarım! Slide 25'te vurgulandığı gibi: R(-)-adrenalin 3 noktadan (katekol, amin, beta-OH) tam kenetlenir. S(+)-adrenalinde ise kiral konfigürasyon ters olduğu için beta-OH çözücüye bakar ve bağlanamaz. Epinin (deoksiadrenalin) beta-OH taşımamasına rağmen S-adrenalinle aynı güçtedir; çünkü ikisi de reseptöre yalnızca 2 noktadan tutunur!\"},{\"id\":\"opt-6b\",\"text\":\"Epinin vücutta kendiliğinden R(-)-adrenalin hormonuna dönüşerek kalbi aşırı uyarır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kendiliğinden kiral sentez yanılgısı: Epinin akiral bir feniletilamindir; in vivo ortamda kendiliğinden şiral hidroksillenmez.\"},{\"id\":\"opt-6c\",\"text\":\"S(+)-adrenalin ve epinin reseptöre hiç bağlanamaz; yalnızca plasebo etkisi yaratırlar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Afinite sıfır yanılgısı: Her iki molekül de mikromolar düzeyde gerçek 2 noktalı adrenerjik agonisttir; afiniteleri sıfır değildir.\"}],\"revealedOutcome\":{\"tr\":\"Easson-Stedman hipotezini doğrular: S(+)-adrenalinin beta-OH grubu bağlanmaya hiçbir enerji katkısı sağlamaz (0 kcal/mol); molekül tıpkı akiral epinin gibi sadece 2 temas noktasıyla tutunur.\",\"ar\":\"يثبت فرضية Easson-Stedman: لا تقدم beta-OH في S(+)-adrenalin أي طاقة ربط (0 kcal/mol)، فيرتبط بنقطتين تماماً كالإيبينين غير الكيرالي.\",\"en\":\"It proves the Easson-Stedman hypothesis: S(+)-epinephrine's misaligned beta-OH contributes 0 kcal/mol binding energy, engaging the exact same 2 contact points as achiral epinine.\"},\"explanation\":{\"tr\":\"Harika bir bilimsel çıkarım! Slide 25'te vurgulandığı gibi: R(-)-adrenalin 3 noktadan (katekol, amin, beta-OH) tam kenetlenir. S(+)-adrenalinde ise kiral konfigürasyon ters olduğu için beta-OH çözücüye bakar ve bağlanamaz. Epinin (deoksiadrenalin) beta-OH taşımamasına rağmen S-adrenalinle aynı güçtedir; çünkü ikisi de reseptöre yalnızca 2 noktadan tutunur!\",\"ar\":\"استنتاج علمي باهر! يرسو R(-)-adrenalin بثلاث نقاط كاملة؛ بينما في S(+)-adrenalin تتجه beta-OH للمذيب فتنعدم مساهمتها. ويمتلك epinine نفس القوة تماماً لأنه يرتبط بنقطتين فقط، مما يثبت صحة نموذج Easson-Stedman الحاسم.\",\"en\":\"Flawless deduction! Slide 25 highlights this classic benchmark: R(-)-epinephrine engages 3 points. In S(+)-epinephrine, the inverted beta-OH points into bulk solvent, providing 0 kcal/mol. Deoxyadrenaline (epinine) lacks beta-OH entirely and displays identical affinity, proving 2-point attachment.\"}}},{\"id\":\"mc-mod4-les1-step-07\",\"stage\":\"formal_explanation\",\"stageIndex\":7,\"type\":\"formal_explanation\",\"title\":{\"tr\":\"Formal Termodinamik: Pfeiffer Kuralı ve Gibbs Enerji Uçurumu\",\"ar\":\"الديناميكا الحرارية المنهجية: قاعدة Pfeiffer وفجوة طاقة غيبس\",\"en\":\"Formal Thermodynamics: Pfeiffer's Rule & Gibbs Energy Gap\"},\"prompt\":{\"tr\":\"Vücut sıcaklığında (310 K) her 1.42 kcal/mol (5.94 kJ/mol) enerji farkı afiniteyi 10 kat artırır. (+)-Muskarinin 700 katlık eudismik oranı (ER = 700) ötomer ile distomer arasında kaç kcal/mol'lük serbest enerji farkına karşılık gelir?\",\"ar\":\"عند 310 K، يمنح كل 1.42 kcal/mol فارقاً في الألفة بعشرة أضعاف. كم يبلغ فارق طاقة غيبس الحرة المقابل لنسبة إيوديزمية ER = 700 في (+)-muscarine؟\",\"en\":\"At 310 K, every 1.42 kcal/mol free energy gap scales affinity by 10-fold. What Gibbs free energy difference (ΔΔG°) accounts for the massive 700-fold eudismic ratio (ER = 700) of (+)-muscarine?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-7a\",\"text\":{\"tr\":\"Yaklaşık -4.04 kcal/mol (-16.9 kJ/mol); log10(700) = 2.845 ve 1.42 x 2.845 ≈ 4.04 kcal/mol (mükemmel konumlanmış iki hidrojen bağına eşdeğer enerji).\",\"ar\":\"حوالي -4.04 kcal/mol (-16.9 kJ/mol)؛ حيث log10(700) = 2.845 و 1.42 × 2.845 ≈ 4.04 kcal/mol (ما يعادل رابطتين هيدروجينيتين متقنتين).\",\"en\":\"Approximately -4.04 kcal/mol (-16.9 kJ/mol); log10(700) = 2.845 and 1.42 x 2.845 ≈ 4.04 kcal/mol, equating to two optimal hydrogen bonds.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika bir termodinamik hesap! ΔΔG° = 2.303 RT log10(ER). 310 K'de 2.303 RT ≈ 1.42 kcal/mol. log10(700) ≈ 2.845. ΔΔG° = 1.42 x 2.845 ≈ 4.04 kcal/mol. Bu enerji iki güçlü hidrojen bağına veya bir iyonik bağa denktir!\",\"ar\":\"حساب ديناميكي حراري بارع! ΔΔG° = 2.303 RT log10(ER). عند 310 K: 1.42 × log10(700) = 1.42 × 2.845 ≈ 4.04 kcal/mol؛ أي ما يوازي رابطتين هيدروجينيتين نموذجيتين!\",\"en\":\"Superb thermodynamic rigor! ΔΔG° = 2.303 RT log10(ER). At 310 K, 1.42 x log10(700) = 1.42 x 2.845 ≈ 4.04 kcal/mol, representing the free energy contribution of two cooperative hydrogen bonds.\"}},{\"id\":\"opt-7b\",\"text\":{\"tr\":\"Tam olarak -700 kcal/mol; serbest enerji doğrudan ER katsayısına eşittir.\",\"ar\":\"-700 kcal/mol تماماً؛ فالطاقة الحرة تتساوى حسابياً مع معامل ER.\",\"en\":\"Exactly -700 kcal/mol; free energy scales directly 1:1 with the numerical ER value.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Doğrudan eşitlik yanılgısı: Enerji lineer değil logaritmiktir: ΔΔG° = 2.303 RT log10(ER).\",\"ar\":\"خطأ التناسب الخطي: ترتبط طاقة غيبس لوغاريتمياً مع نسبة الألفة وليس تناسباً خطياً بسيطاً.\",\"en\":\"Linear equivalence misconception: Gibbs free energy scales logarithmically with equilibrium binding ratios: ΔΔG° = 2.303 RT log10(ER).\"}},{\"id\":\"opt-7c\",\"text\":{\"tr\":\"Yalnızca -0.1 kcal/mol; kiral farklar termodinamik olarak önemsizdir.\",\"ar\":\"-0.1 kcal/mol فقط؛ فالفروق الكيرالية مهملة ديناميكياً حرارياً.\",\"en\":\"Merely -0.1 kcal/mol; chiral differences are thermodynamically trivial.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Önemsizlik yanılgısı: 4 kcal/mol biyolojik sistemlerde devasa bir farktır ve afiniteyi 700 kat çarpar.\",\"ar\":\"خطأ إهمال الفارق: طاقة 4 kcal/mol هائلة بيولوجياً وتضاعف الألفة بـ 700 ضعف.\",\"en\":\"Triviality misconception: A 4 kcal/mol free energy gap in biological media translates into a massive 700-fold affinity divergence.\"}}]},\"technicalTerms\":[{\"term\":\"Gibbs serbest enerji farkı (ΔΔG°)\",\"arContext\":\"فارق طاقة غيبس الحرة (ΔΔG°)\"},{\"term\":\"logaritmik afinite ölçeği\",\"arContext\":\"المقياس اللوغاريتمي للألفة\"}],\"hints\":[{\"tr\":\"Termodinamik formülü hatırlayın: ΔΔG° = 2.303 RT log10(ER).\",\"ar\":\"تذكر معادلة غيبس: ΔΔG° = 2.303 RT log10(ER).\",\"en\":\"Recall the thermodynamic relationship: ΔΔG° = 2.303 RT log10(ER).\"},{\"tr\":\"310 K'de 2.303 RT ≈ 1.42 kcal/mol'dür. log10(700) = log10(7) + log10(100) = 0.845 + 2 = 2.845.\",\"ar\":\"عند 310 K يكون 2.303 RT ≈ 1.42 kcal/mol. و log10(700) = 2.845.\",\"en\":\"At 310 K, 2.303 RT ≈ 1.42 kcal/mol. Evaluate log10(700) = 2.845.\"},{\"tr\":\"1.42 kcal/mol'ü 2.845 ile çarparak yaklaşık 4.04 kcal/mol bulursunuz.\",\"ar\":\"اضرب 1.42 في 2.845 لتحصل على حوالي 4.04 kcal/mol.\",\"en\":\"Multiply 1.42 by 2.845 to obtain approximately 4.04 kcal/mol.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":28}],\"config\":{\"options\":[{\"id\":\"opt-7a\",\"text\":\"Yaklaşık -4.04 kcal/mol (-16.9 kJ/mol); log10(700) = 2.845 ve 1.42 x 2.845 ≈ 4.04 kcal/mol (mükemmel konumlanmış iki hidrojen bağına eşdeğer enerji).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika bir termodinamik hesap! ΔΔG° = 2.303 RT log10(ER). 310 K'de 2.303 RT ≈ 1.42 kcal/mol. log10(700) ≈ 2.845. ΔΔG° = 1.42 x 2.845 ≈ 4.04 kcal/mol. Bu enerji iki güçlü hidrojen bağına veya bir iyonik bağa denktir!\"},{\"id\":\"opt-7b\",\"text\":\"Tam olarak -700 kcal/mol; serbest enerji doğrudan ER katsayısına eşittir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Doğrudan eşitlik yanılgısı: Enerji lineer değil logaritmiktir: ΔΔG° = 2.303 RT log10(ER).\"},{\"id\":\"opt-7c\",\"text\":\"Yalnızca -0.1 kcal/mol; kiral farklar termodinamik olarak önemsizdir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Önemsizlik yanılgısı: 4 kcal/mol biyolojik sistemlerde devasa bir farktır ve afiniteyi 700 kat çarpar.\"}],\"revealedOutcome\":{\"tr\":\"Yaklaşık -4.04 kcal/mol (-16.9 kJ/mol); log10(700) = 2.845 ve 1.42 x 2.845 ≈ 4.04 kcal/mol (mükemmel konumlanmış iki hidrojen bağına eşdeğer enerji).\",\"ar\":\"حوالي -4.04 kcal/mol (-16.9 kJ/mol)؛ حيث log10(700) = 2.845 و 1.42 × 2.845 ≈ 4.04 kcal/mol (ما يعادل رابطتين هيدروجينيتين متقنتين).\",\"en\":\"Approximately -4.04 kcal/mol (-16.9 kJ/mol); log10(700) = 2.845 and 1.42 x 2.845 ≈ 4.04 kcal/mol, equating to two optimal hydrogen bonds.\"},\"explanation\":{\"tr\":\"Harika bir termodinamik hesap! ΔΔG° = 2.303 RT log10(ER). 310 K'de 2.303 RT ≈ 1.42 kcal/mol. log10(700) ≈ 2.845. ΔΔG° = 1.42 x 2.845 ≈ 4.04 kcal/mol. Bu enerji iki güçlü hidrojen bağına veya bir iyonik bağa denktir!\",\"ar\":\"حساب ديناميكي حراري بارع! ΔΔG° = 2.303 RT log10(ER). عند 310 K: 1.42 × log10(700) = 1.42 × 2.845 ≈ 4.04 kcal/mol؛ أي ما يوازي رابطتين هيدروجينيتين نموذجيتين!\",\"en\":\"Superb thermodynamic rigor! ΔΔG° = 2.303 RT log10(ER). At 310 K, 1.42 x log10(700) = 1.42 x 2.845 ≈ 4.04 kcal/mol, representing the free energy contribution of two cooperative hydrogen bonds.\"}}},{\"id\":\"mc-mod4-les1-step-08\",\"stage\":\"concept_check\",\"stageIndex\":8,\"type\":\"concept_check\",\"title\":{\"tr\":\"Kavram Kontrolü: İki İlacın Pfeiffer Analizi\",\"ar\":\"فحص المفاهيم: تحليل دوائين وفق قاعدة Pfeiffer\",\"en\":\"Concept Check: Two-Drug Pfeiffer Eudismic Audit\"},\"prompt\":{\"tr\":\"İlaç X hedef reseptörüne Kd = 0.05 nM (pikomolar) ile bağlanır. İlaç Y ise aynı reseptöre Kd = 20 μM (mikromolar) ile bağlanır. Pfeiffer kuralına göre hangisinin eudismik oranı (ER) devasa büyüktür?\",\"ar\":\"يرتبط الدواء X بمستقبله بألفة Kd = 0.05 nM (بيكومولار)، بينما يرتبط الدواء Y بألفة Kd = 20 μM (ميكرومولار). وفق قاعدة Pfeiffer، أي الدوائين يملك نسبة ER هائلة؟\",\"en\":\"Drug X binds its target with Kd = 0.05 nM (picomolar affinity). Drug Y binds the same receptor with Kd = 20 μM. According to Pfeiffer's rule, which candidate will display a massive eudismic ratio?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-8a\",\"text\":{\"tr\":\"İlaç X; pikomolar bağlanma reseptör cebine mikron düzeyinde kusursuz 3D komplementerlik gerektirir, distomerin tek bir eksik teması afiniteyi 500-1000 kat düşürür.\",\"ar\":\"الدواء X؛ تتطلب الألفة البيكومولية تطابقاً فراغياً ثلاثي الأبعاد فائق الإحكام، وغياب رابطة واحدة في distomer يخفض الألفة مئات الأضعاف.\",\"en\":\"Drug X; picomolar binding demands extreme 3D steric complementarity, meaning a single misaligned contact in the distomer penalizes affinity 500- to 1000-fold.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Pfeiffer kuralı gereğince: Afinite ne kadar yüksekse (doz ne kadar düşükse), iki enantiyomer arasındaki güç farkı o derece devasadır. İlaç X (0.05 nM) enantiyomer kusurlarını affetmez; İlaç Y (20 μM) ise gevşek bağlanır ve ER ~ 1-2 civarında kalır.\",\"ar\":\"صحيح! وفق قاعدة Pfeiffer: كلما ارتفعت الألفة، اتسعت فجوة القوة بين المصاوغين. لا يتسامح الدواء X (0.05 nM) مع أي خلل؛ بينما يرتبط Y (20 μM) برخاوة وتتقارب مصاوغاته.\",\"en\":\"Correct! Pfeiffer's rule dictates that sub-nanomolar ligands display immense chiral discrimination because the binding pocket demands near-flawless 3D contact network alignment.\"}},{\"id\":\"opt-8b\",\"text\":{\"tr\":\"İlaç Y; mikromolar ilaçlar yüksek dozda verildiği için enantiyomerler arası fark daha net görülür.\",\"ar\":\"الدواء Y؛ لأن الجرعات العالية للمركبات الميكرومولية تضخم الفارق بين المصاوغات.\",\"en\":\"Drug Y; micromolar drugs require high therapeutic doses, magnifying the apparent difference.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Doz yanılgısı: Yüksek doz gevşek bağlanmayı gösterir; gevşek cepler kiral kusurları tolere eder ve ER 1'e yaklaşır.\",\"ar\":\"خطأ الجرعة: تعكس الجرعات العالية ارتباطاً رخواً يتسامح مع عيوب الكيرالية؛ فتهبط نسبة ER مقتربة من الواحد.\",\"en\":\"Dose misconception: High doses signify loose, non-discriminating binding pockets where chiral inversions are readily accommodated (ER -> 1).\"}},{\"id\":\"opt-8c\",\"text\":{\"tr\":\"Her ikisi de tamamen aynı ER değerine sahiptir; Pfeiffer kuralı sadece antibiyotiklerde geçerlidir.\",\"ar\":\"كلاهما يمتلك نفس ER تماماً؛ فقاعدة Pfeiffer تنطبق على المضادات الحيوية حصراً.\",\"en\":\"Both possess identical ER values; Pfeiffer's rule applies exclusively to antimicrobial agents.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kural sınırlaması yanılgısı: Pfeiffer kuralı tüm reseptör-ligand sistemleri için evrensel bir biyofiziksel prensiptir.\",\"ar\":\"خطأ حصر القاعدة: قاعدة Pfeiffer مبدأ بيوفيزيائي شامل ينطبق على كافة أجهزة ومستقبلات الجسم.\",\"en\":\"Class limitation misconception: Pfeiffer's rule is a universal biophysical relationship across all receptor-ligand interactions.\"}}]},\"technicalTerms\":[{\"term\":\"pikomolar afinite\",\"arContext\":\"ألفة بيكومولية\"},{\"term\":\"reseptör sterik kısıtlaması\",\"arContext\":\"الإحكام الفراغي للمستقبل\"}],\"hints\":[{\"tr\":\"0.05 nM ile 20 μM (20000 nM) arasında 400.000 katlık bir afinite farkı vardır.\",\"ar\":\"الفارق بين 0.05 nM و 20 μM (أي 20000 nM) يصل إلى 400,000 ضعف في الألفة.\",\"en\":\"There is a 400,000-fold affinity gap between 0.05 nM and 20 μM.\"},{\"tr\":\"Pfeiffer kuralını anımsayın: Afinite arttıkça Eudismik Oran (ER) katlanarak büyür.\",\"ar\":\"تذكر قاعدة Pfeiffer: كلما زادت الألفة تضاعفت النسبة الإيوديزمية ER أسياً.\",\"en\":\"Remember Pfeiffer's rule: higher baseline affinity drives exponentially higher eudismic ratios.\"},{\"tr\":\"İlaç X'in reseptör cebi kusursuz uyum ister; distomer bir temas kaybederse afinite çöker (ER > 500). İlaç Y'de ise ER ~ 1'e yakındır.\",\"ar\":\"يتطلب جيب X تطابقاً مثالياً يرفع ER لأكثر من 500؛ بينما يقترب ER للدواء Y من 1.\",\"en\":\"Drug X's pocket enforces rigorous fit (ER > 500); Drug Y binds loosely with near-equal enantiomeric potency (ER -> 1).\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":28}],\"config\":{\"options\":[{\"id\":\"opt-8a\",\"text\":\"İlaç X; pikomolar bağlanma reseptör cebine mikron düzeyinde kusursuz 3D komplementerlik gerektirir, distomerin tek bir eksik teması afiniteyi 500-1000 kat düşürür.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Pfeiffer kuralı gereğince: Afinite ne kadar yüksekse (doz ne kadar düşükse), iki enantiyomer arasındaki güç farkı o derece devasadır. İlaç X (0.05 nM) enantiyomer kusurlarını affetmez; İlaç Y (20 μM) ise gevşek bağlanır ve ER ~ 1-2 civarında kalır.\"},{\"id\":\"opt-8b\",\"text\":\"İlaç Y; mikromolar ilaçlar yüksek dozda verildiği için enantiyomerler arası fark daha net görülür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Doz yanılgısı: Yüksek doz gevşek bağlanmayı gösterir; gevşek cepler kiral kusurları tolere eder ve ER 1'e yaklaşır.\"},{\"id\":\"opt-8c\",\"text\":\"Her ikisi de tamamen aynı ER değerine sahiptir; Pfeiffer kuralı sadece antibiyotiklerde geçerlidir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kural sınırlaması yanılgısı: Pfeiffer kuralı tüm reseptör-ligand sistemleri için evrensel bir biyofiziksel prensiptir.\"}],\"revealedOutcome\":{\"tr\":\"İlaç X; pikomolar bağlanma reseptör cebine mikron düzeyinde kusursuz 3D komplementerlik gerektirir, distomerin tek bir eksik teması afiniteyi 500-1000 kat düşürür.\",\"ar\":\"الدواء X؛ تتطلب الألفة البيكومولية تطابقاً فراغياً ثلاثي الأبعاد فائق الإحكام، وغياب رابطة واحدة في distomer يخفض الألفة مئات الأضعاف.\",\"en\":\"Drug X; picomolar binding demands extreme 3D steric complementarity, meaning a single misaligned contact in the distomer penalizes affinity 500- to 1000-fold.\"},\"explanation\":{\"tr\":\"Doğru! Pfeiffer kuralı gereğince: Afinite ne kadar yüksekse (doz ne kadar düşükse), iki enantiyomer arasındaki güç farkı o derece devasadır. İlaç X (0.05 nM) enantiyomer kusurlarını affetmez; İlaç Y (20 μM) ise gevşek bağlanır ve ER ~ 1-2 civarında kalır.\",\"ar\":\"صحيح! وفق قاعدة Pfeiffer: كلما ارتفعت الألفة، اتسعت فجوة القوة بين المصاوغين. لا يتسامح الدواء X (0.05 nM) مع أي خلل؛ بينما يرتبط Y (20 μM) برخاوة وتتقارب مصاوغاته.\",\"en\":\"Correct! Pfeiffer's rule dictates that sub-nanomolar ligands display immense chiral discrimination because the binding pocket demands near-flawless 3D contact network alignment.\"}}},{\"id\":\"mc-mod4-les1-step-09\",\"stage\":\"application\",\"stageIndex\":9,\"type\":\"clinical_vignette\",\"title\":{\"tr\":\"Klinik Vaka: Prilokain Distomeri ve Methemoglobinemi Toksisitesi\",\"ar\":\"حالة سريرية: المصاوغ السام للبريلوكائين وميتهيموغلوبين الدم\",\"en\":\"Clinical Vignette: Prilocaine Distomer & Methemoglobinemia Toxicity\"},\"prompt\":{\"tr\":\"Rasemik prilokain ile lokal anestezi uygulanan hastada siyanoz gelişir. Toksisite araştırmasında S(+) ötomerinin güvenli anestezik olduğu, ancak R(-) distomerinin methemoglobinemiye yol açtığı saptanır. Hangi metabolik mekanizma suçludur?\",\"ar\":\"أصيب مريض بالزرقة ونقص الأكسجة بعد تخدير موضعي بـ prilocaine الراسيمي. أثبتت الفحوصات أمان S(+) بينما سبب R(-) ميتهيموغلوبين الدم. ما الآلية الاستقلابية المسؤولة؟\",\"en\":\"Following regional anesthesia with racemic prilocaine, a patient develops cyanosis. Analysis reveals S(+)-prilocaine is a safe local anesthetic, but R(-)-distomer triggers methemoglobinemia. What metabolic mechanism is responsible?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-9a\",\"text\":{\"tr\":\"R(-) distomeri karaciğerde amido-hidrolaz ile stereoselektif hidrolize uğrayarak o-toluidin oluşturur; bu metabolit hemoglobindeki Fe2+'yi Fe3+'e oksitleyerek oksijen taşınmasını felç eder.\",\"ar\":\"يتحلل المصاوغ R(-) كبدياً بأنزيم أميدو-هيدرولاز انتقائياً محرراً o-toluidine؛ الذي يؤكسد حديد الهيموغلوبين من Fe2+ إلى Fe3+ شالاً نقل الأكسجين.\",\"en\":\"R(-)-distomer undergoes stereoselective hepatic amide hydrolysis to o-toluidine, which oxidizes hemoglobin Fe2+ to Fe3+, paralyzing oxygen transport.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kesinlikle doğru! Slide 32'deki klasik vaka: S(+)-prilokain güvenli bir anesteziktir. Distomer R(-)-prilokain ise hepatik amidazlarca selektif hidroliz edilir ve o-toluidin açığa çıkar. Bu aromatik amin hemoglobini methemoglobine oksitleyerek doku hipoksisine yol açar.\",\"ar\":\"صحيح تماماً! حالة السلايد 32 الكلاسيكية: S(+)-prilocaine مخدر آمن. بينما يتحلل R(-) انتقائياً في الكبد ليعطي o-toluidine الذي يؤكسد حديد الهيموغلوبين معطلاً نقل الأكسجين ومسبباً الزرقة.\",\"en\":\"Spot on! Slide 32 details this landmark case: S(+)-prilocaine is therapeutic. Distomer R(-)-prilocaine is stereoselectively cleaved by hepatic amidases into o-toluidine, which oxidizes Fe2+ to Fe3+, causing life-threatening methemoglobinemia.\"}},{\"id\":\"opt-9b\",\"text\":{\"tr\":\"S(+) ötomeri kandaki alyuvarları kovalent olarak parçalayıp serbest demir salar.\",\"ar\":\"يحطم المصاوغ S(+) كريات الدم الحمراء تساهمياً محرراً الحديد الحر.\",\"en\":\"S(+)-eutomer covalently lyses red blood cells to release uncomplexed iron.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Ötomer suçlama yanılgısı: S(+) izomeri güvenli ve etkindir; toksisite distomerin stereoselektif metabolitinden doğar.\",\"ar\":\"خطأ اتهام المصاوغ الفعال: المصاوغ S(+) آمن تماماً، والسمية تنشأ حصراً من مستقلب المصاوغ الخامل R(-).\",\"en\":\"Blaming eutomer misconception: S(+)-prilocaine is safe and non-toxic; methemoglobinemia is driven exclusively by the metabolite of distomer R(-)-prilocaine.\"}},{\"id\":\"opt-9c\",\"text\":{\"tr\":\"Prilokain akciğerlerdeki oksijen gazını emerek nitrojen gazına çevirir.\",\"ar\":\"يمتص البريلوكائين غاز الأكسجين الرئوي محولاً إياه إلى غاز النيتروجين.\",\"en\":\"Prilocaine absorbs pulmonary oxygen gas and chemically transmutes it into nitrogen.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Gaz dönüşüm yanılgısı: Lokal anestezikler gaz transmutasyonu yapmaz; mekanizma eritrosit içi demir oksidasyonudur.\",\"ar\":\"خطأ تحول الغاز: المخدرات الموضعية لا تحول الغازات؛ بل تؤكسد مستقلباتها حديد الهيموغلوبين كيميائياً.\",\"en\":\"Gas transmutation misconception: Local anesthetics do not transmute respiratory gases; toxicity is driven by intraerythrocytic iron oxidation.\"}}]},\"technicalTerms\":[{\"term\":\"methemoglobinemi\",\"arContext\":\"ميتهيموغلوبين الدم (methemoglobinemia)\"},{\"term\":\"o-toluidin metaboliti\",\"arContext\":\"مستقلب أورثو-تولويدين\"}],\"hints\":[{\"tr\":\"Methemoglobinemi kanda Fe2+'nin Fe3+'e dönüşerek oksijen bağlayamaması durumudur.\",\"ar\":\"ميتهيموغلوبين الدم هو أكسدة حديد الهيموغلوبين من Fe2+ إلى Fe3+ مما يمنع حمل الأكسجين.\",\"en\":\"Methemoglobinemia occurs when ferrous Fe2+ oxidizes to ferric Fe3+, precluding O2 transport.\"},{\"tr\":\"Karaciğerdeki amidazlar R(-)-prilokaini parçalayarak aromatik o-toluidin açığa çıkarır.\",\"ar\":\"تحلل أنزيمات الكبد R(-)-prilocaine محررة مركب أورثو-تولويدين العطري.\",\"en\":\"Hepatic amidases selectively hydrolyze R(-)-prilocaine to liberate the toxic arylamine o-toluidine.\"},{\"tr\":\"R(-) distomerinin bu stereoselektif hidrolizi toksisite kaynağıdır; S(+) izomeri bu metaboliti vermez.\",\"ar\":\"هذه الحلمهة الانتقائية لـ R(-) هي مصدر السمية؛ بينما لا ينتج المصاوغ S(+) هذا المستقلب المؤكسد.\",\"en\":\"Stereoselective hydrolysis of the R(-)-distomer generates o-toluidine; S(+)-prilocaine does not trigger this toxic pathway.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":32}],\"config\":{\"options\":[{\"id\":\"opt-9a\",\"text\":\"R(-) distomeri karaciğerde amido-hidrolaz ile stereoselektif hidrolize uğrayarak o-toluidin oluşturur; bu metabolit hemoglobindeki Fe2+'yi Fe3+'e oksitleyerek oksijen taşınmasını felç eder.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kesinlikle doğru! Slide 32'deki klasik vaka: S(+)-prilokain güvenli bir anesteziktir. Distomer R(-)-prilokain ise hepatik amidazlarca selektif hidroliz edilir ve o-toluidin açığa çıkar. Bu aromatik amin hemoglobini methemoglobine oksitleyerek doku hipoksisine yol açar.\"},{\"id\":\"opt-9b\",\"text\":\"S(+) ötomeri kandaki alyuvarları kovalent olarak parçalayıp serbest demir salar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Ötomer suçlama yanılgısı: S(+) izomeri güvenli ve etkindir; toksisite distomerin stereoselektif metabolitinden doğar.\"},{\"id\":\"opt-9c\",\"text\":\"Prilokain akciğerlerdeki oksijen gazını emerek nitrojen gazına çevirir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Gaz dönüşüm yanılgısı: Lokal anestezikler gaz transmutasyonu yapmaz; mekanizma eritrosit içi demir oksidasyonudur.\"}],\"revealedOutcome\":{\"tr\":\"R(-) distomeri karaciğerde amido-hidrolaz ile stereoselektif hidrolize uğrayarak o-toluidin oluşturur; bu metabolit hemoglobindeki Fe2+'yi Fe3+'e oksitleyerek oksijen taşınmasını felç eder.\",\"ar\":\"يتحلل المصاوغ R(-) كبدياً بأنزيم أميدو-هيدرولاز انتقائياً محرراً o-toluidine؛ الذي يؤكسد حديد الهيموغلوبين من Fe2+ إلى Fe3+ شالاً نقل الأكسجين.\",\"en\":\"R(-)-distomer undergoes stereoselective hepatic amide hydrolysis to o-toluidine, which oxidizes hemoglobin Fe2+ to Fe3+, paralyzing oxygen transport.\"},\"explanation\":{\"tr\":\"Kesinlikle doğru! Slide 32'deki klasik vaka: S(+)-prilokain güvenli bir anesteziktir. Distomer R(-)-prilokain ise hepatik amidazlarca selektif hidroliz edilir ve o-toluidin açığa çıkar. Bu aromatik amin hemoglobini methemoglobine oksitleyerek doku hipoksisine yol açar.\",\"ar\":\"صحيح تماماً! حالة السلايد 32 الكلاسيكية: S(+)-prilocaine مخدر آمن. بينما يتحلل R(-) انتقائياً في الكبد ليعطي o-toluidine الذي يؤكسد حديد الهيموغلوبين معطلاً نقل الأكسجين ومسبباً الزرقة.\",\"en\":\"Spot on! Slide 32 details this landmark case: S(+)-prilocaine is therapeutic. Distomer R(-)-prilocaine is stereoselectively cleaved by hepatic amidases into o-toluidine, which oxidizes Fe2+ to Fe3+, causing life-threatening methemoglobinemia.\"}}},{\"id\":\"mc-mod4-les1-step-10\",\"stage\":\"retrieval\",\"stageIndex\":10,\"type\":\"retrieval\",\"title\":{\"tr\":\"Aralıklı Hatırlama: Ketamin ve Esketamin Ayrımı\",\"ar\":\"استرجاع متباعد: التمييز الفارماكولوجي بين الكيتامين والإسكيتامين\",\"en\":\"Spaced Retrieval: Ketamine vs Esketamine Divergence\"},\"prompt\":{\"tr\":\"Genel anestezik ketamin rasemat olarak kullanıldığında hastalarda postoperatif disfori ve halüsinasyonlar görülür. Saf S(+)-ketamin (Esketamin) geliştirildiğinde klinik tablo nasıl değişir? Distomerin rolü nedir?\",\"ar\":\"يسبب كيتامين الراسيمي هلوسات واضطراب ما بعد الجراحة. عند تطوير S(+)-ketamine (Esketamine) النقي، كيف يتغير الأداء السريري؟ وما دور distomer؟\",\"en\":\"Racemic ketamine causes emergence delirium, dysphoria, and hallucinations. When pure S(+)-ketamine (Esketamine) is administered, how does the clinical profile change? What was the distomer's contribution?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-10a\",\"text\":{\"tr\":\"S(+)-ötomer 3-4 kat daha güçlü anestezik ve antidepresandır; psikotomimetik halüsinasyon ve kabuslardan ise distomer olan R(-)-ketamin sorumludur.\",\"ar\":\"يمتلك S(+) قوة تخدير ومضادة للاكتئاب أعلى بـ 3-4 أضعاف؛ بينما يتحمل المصاوغ R(-) مسؤولية الهلوسة والاضطراب النفسي.\",\"en\":\"S(+)-eutomer is 3-4x more potent as an anesthetic and rapid antidepressant; distomer R(-)-ketamine is responsible for dysphoria and emergence delirium.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kesinlikle doğru! Slide 35'te açıklandığı üzere: Esketamin [S(+)-ketamin] NMDA reseptöründe PCP cebini güçlü bloke ederek 3-4 kat yüksek anestezik/antidepresan etki sunar. R(-)-ketamin distomeri ise ajitasyon, disfori ve kabusların ana kaynağıdır.\",\"ar\":\"صحيح تماماً! وفق السلايد 35: Esketamin [S(+)] أقوى بـ 3-4 أضعاف في التخدير ومكافحة الاكتئاب السريع. بينما يسبب distomer [R(-)] الكوابيس والاضطراب النفسي.\",\"en\":\"Spot on! Slide 35 details that S(+)-ketamine (Esketamine) is 3-4x more potent at NMDA receptors, while distomer R(-)-ketamine drives post-operative emergence delirium, nightmares, and dysphoria.\"}},{\"id\":\"opt-10b\",\"text\":{\"tr\":\"Esketamin hastanın hafızasını tamamen silerek hastaneyi unutturur.\",\"ar\":\"يمحو الإسكيتامين ذاكرة المريض بالكامل فينسى دخوله المستشفى.\",\"en\":\"Esketamine permanently erases patient long-term memory, inducing complete amnesia.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kalıcı amnezi yanılgısı: Esketamin güvenli bir NMDA reseptör blokeridir; kalıcı hafıza silinmesi yapmaz.\",\"ar\":\"خطأ فقدان الذاكرة الدائم: الإسكيتامين دواء تخديري نوعي ولا يسبب محواً دائماً للذاكرة طويلة الأمد.\",\"en\":\"Permanent amnesia misconception: Esketamine is a safe, reversible NMDA antagonist that produces anesthesia without permanent retrograde amnesia.\"}},{\"id\":\"opt-10c\",\"text\":{\"tr\":\"Her iki enantiyomer de eşit güçte halüsinasyon yapar; ayrıştırma hiçbir fayda sağlamaz.\",\"ar\":\"يسبب كلا المصاوغين الهلوسة بنفس الشدة تماماً؛ وفصلهما عديم الفائدة.\",\"en\":\"Both enantiomers induce identical hallucinations; chiral switching offers zero benefit.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Eşit psikoz yanılgısı: Halüsinatif distomer R(-) izomeridir; saf S(+) kullanımı psikotomimetik yan etkileri dramatik biçimde azaltır.\",\"ar\":\"خطأ التماثل النفسي: المصاوغ R(-) هو المسؤول الأول عن الهلوسات؛ وعزل S(+) النقي يقلل الآثار النفسية بشكل ملحوظ.\",\"en\":\"Equal psychosis misconception: Emergence dysphoria is predominantly driven by the R(-)-distomer; isolating S(+)-ketamine significantly refines tolerability.\"}}]},\"technicalTerms\":[{\"term\":\"esketamin [S(+)-ketamin]\",\"arContext\":\"إسكيتامين [S(+)]\"},{\"term\":\"NMDA reseptör blokajı\",\"arContext\":\"إحصار مستقبلات NMDA\"}],\"hints\":[{\"tr\":\"Ketamin disosiyatif bir anesteziktir ve NMDA reseptörlerini bloke eder.\",\"ar\":\"الكيتامين مخدر فصامي يثبط مستقبلات NMDA في الدماغ.\",\"en\":\"Ketamine is a dissociative anesthetic targeting the NMDA receptor channel.\"},{\"tr\":\"S(+) izomeri arzu edilen güçlü anestezik ve hızlı etkili antidepresandır.\",\"ar\":\"المصاوغ S(+) هو المخدر القوي ومضاد الاكتئاب السريع المرغوب.\",\"en\":\"The S(+)-isomer is the potent anesthetic and rapid-acting antidepressant eutomer.\"},{\"tr\":\"R(-) izomeri kabus, dezoryantasyon ve halüsinasyonlara yol açan distomerdir; kiral ayırma bu yan etkileri azaltır.\",\"ar\":\"المصاوغ R(-) هو المسؤول عن الكوابيس والهلوسات؛ والفصل الكيرالي يقلل هذه المضاعفات.\",\"en\":\"The R(-)-isomer is the distomer responsible for delirium and hallucinations; chiral purification refines patient recovery.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":35}],\"config\":{\"options\":[{\"id\":\"opt-10a\",\"text\":\"S(+)-ötomer 3-4 kat daha güçlü anestezik ve antidepresandır; psikotomimetik halüsinasyon ve kabuslardan ise distomer olan R(-)-ketamin sorumludur.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kesinlikle doğru! Slide 35'te açıklandığı üzere: Esketamin [S(+)-ketamin] NMDA reseptöründe PCP cebini güçlü bloke ederek 3-4 kat yüksek anestezik/antidepresan etki sunar. R(-)-ketamin distomeri ise ajitasyon, disfori ve kabusların ana kaynağıdır.\"},{\"id\":\"opt-10b\",\"text\":\"Esketamin hastanın hafızasını tamamen silerek hastaneyi unutturur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kalıcı amnezi yanılgısı: Esketamin güvenli bir NMDA reseptör blokeridir; kalıcı hafıza silinmesi yapmaz.\"},{\"id\":\"opt-10c\",\"text\":\"Her iki enantiyomer de eşit güçte halüsinasyon yapar; ayrıştırma hiçbir fayda sağlamaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Eşit psikoz yanılgısı: Halüsinatif distomer R(-) izomeridir; saf S(+) kullanımı psikotomimetik yan etkileri dramatik biçimde azaltır.\"}],\"revealedOutcome\":{\"tr\":\"S(+)-ötomer 3-4 kat daha güçlü anestezik ve antidepresandır; psikotomimetik halüsinasyon ve kabuslardan ise distomer olan R(-)-ketamin sorumludur.\",\"ar\":\"يمتلك S(+) قوة تخدير ومضادة للاكتئاب أعلى بـ 3-4 أضعاف؛ بينما يتحمل المصاوغ R(-) مسؤولية الهلوسة والاضطراب النفسي.\",\"en\":\"S(+)-eutomer is 3-4x more potent as an anesthetic and rapid antidepressant; distomer R(-)-ketamine is responsible for dysphoria and emergence delirium.\"},\"explanation\":{\"tr\":\"Kesinlikle doğru! Slide 35'te açıklandığı üzere: Esketamin [S(+)-ketamin] NMDA reseptöründe PCP cebini güçlü bloke ederek 3-4 kat yüksek anestezik/antidepresan etki sunar. R(-)-ketamin distomeri ise ajitasyon, disfori ve kabusların ana kaynağıdır.\",\"ar\":\"صحيح تماماً! وفق السلايد 35: Esketamin [S(+)] أقوى بـ 3-4 أضعاف في التخدير ومكافحة الاكتئاب السريع. بينما يسبب distomer [R(-)] الكوابيس والاضطراب النفسي.\",\"en\":\"Spot on! Slide 35 details that S(+)-ketamine (Esketamine) is 3-4x more potent at NMDA receptors, while distomer R(-)-ketamine drives post-operative emergence delirium, nightmares, and dysphoria.\"}}},{\"id\":\"mc-mod4-les1-step-11\",\"stage\":\"connection\",\"stageIndex\":11,\"type\":\"connection\",\"title\":{\"tr\":\"Bağlantı: Reseptör Stereoseçiciliği ve Allosterik Modülasyon\",\"ar\":\"ربط المفاهيم: الانتقائية الفراغية والتشكيل الخيفي للمستقبلات\",\"en\":\"Cross-Topic Bridge: Target Stereoselectivity & Allosteric Tuning\"},\"prompt\":{\"tr\":\"Pfeiffer kuralı ve Easson-Stedman 3-nokta bağlanması, farmakolojideki ters agonist (inverse agonist) ve allosterik modülatörlerin stereoseçiciliğini nasıl aydınlatır? Gelecek farmakoloji modülleriyle bağlantıyı kurun:\",\"ar\":\"كيف تضيء قاعدة Pfeiffer ونموذج Easson-Stedman الانتقائية الفراغية للمنبهات العكسية والمعدلات الخيفية؟ اربط بموديولات الفارماكولوجيا القادمة:\",\"en\":\"How do Pfeiffer's rule and Easson-Stedman 3-point attachment illuminate the stereoselective design of inverse agonists and allosteric modulators? Connect to upcoming Pharmacology modules:\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-11a\",\"text\":{\"tr\":\"Reseptörün aktif ve inaktif konformasyonları farklı 3D cepler sunar; ötomer yalnızca hedef konformasyonu stabilize eden 3 noktayı kilitlerken, distomer ters konformasyona oturabilir veya bağlanamaz.\",\"ar\":\"توفر هيئات المستقبل النشطة وغير النشطة جيوباً فراغية مختلفة؛ يقفل eutomer النقاط الثلاث للهيئة المستهدفة بينما يرسو distomer في الهيئة المعاكسة أو يفشل بالارتباط.\",\"en\":\"Active and inactive receptor states expose distinct 3D pockets; the eutomer satisfies 3-point contacts on the desired state, while distomers fail to bind or stabilize opposing states.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz bağlantı! Reseptörler dinamik proteinlerdir. Aktif durum (Ra) ile inaktif durum (Ri) farklı 3 boyutlu kaviteler sunar. Easson-Stedman modeli gereğince ötomer tek bir durumu 3 noktadan kilitlerken, distomer ters durumu stabilize ederek ters agonist veya nötr antagonist olabilir.\",\"ar\":\"ربط استثنائي! المستقبلات بروتينات ديناميكية. تقدم الهيئة النشطة وغير النشطة جيوباً فراغية متمايزة. يقفل eutomer هيئة واحدة بثلاث نقاط، بينما قد يثبت distomer الهيئة المعاكسة كمنبه عكسي.\",\"en\":\"Outstanding bridge! GPCRs equilibrate between active (Ra) and inactive (Ri) states with distinct 3D pockets. The eutomer stereoselectively locks 3 contacts on Ra (agonist) or Ri (inverse agonist), while the distomer may lack contacts or stabilize the opposing state.\"}},{\"id\":\"opt-11b\",\"text\":{\"tr\":\"Ters agonistler reseptör proteininin amino asit dizilimini genetik olarak mutasyona uğratır.\",\"ar\":\"تحدث المنبهات العكسية طفرات جينية في تسلسل الأحماض الأمينية للمستقبل.\",\"en\":\"Inverse agonists genetically mutate the primary amino acid sequence of the receptor.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Genetik mutasyon yanılgısı: Ligandlar proteini mutasyona uğratmaz; mevcut uzaysal konformasyonel dengeleri (Ri vs Ra) kaydırır.\",\"ar\":\"خطأ الطفرة الجينية: لا تعدل الأدوية الجينات بل تغير التوازن التشكلي الفراغي للمستقبلات.\",\"en\":\"Genetic mutation misconception: Pharmacological ligands modulate existing conformational equilibria, not host genetic sequences.\"}},{\"id\":\"opt-11c\",\"text\":{\"tr\":\"Allosterik modülatörlerde kiralite tamamen önemsizdir; tüm enantiyomerler eşit etki eder.\",\"ar\":\"الكيرالية عديمة الأهمية في المعدلات الخيفية وتعمل كافة المصاوغات بنفس القوة.\",\"en\":\"Chirality is irrelevant to allosteric sites; all enantiomers behave identically.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Allosterik akiralite yanılgısı: Allosterik cepler de kiral protein kaviteleridir ve Pfeiffer kuralına tam olarak uyarlar.\",\"ar\":\"خطأ لاكيرالية المواقع الخيفية: المواقع الخيفية جيوب كيرالية تخضع بالكامل لقاعدة Pfeiffer ونموذج النقاط الثلاث.\",\"en\":\"Allosteric achirality misconception: Allosteric pockets are asymmetric chiral protein cavities that strictly obey Pfeiffer's rule.\"}}]},\"technicalTerms\":[{\"term\":\"ters agonist (inverse agonist)\",\"arContext\":\"المنبه العكسي (inverse agonist)\"},{\"term\":\"konformasyonel stereoseçicilik\",\"arContext\":\"الانتقائية الفراغية للتشكيل\"}],\"hints\":[{\"tr\":\"Reseptörler tek bir katı yapı değil, aktif ve inaktif haller arasında salınan dinamik proteinlerdir.\",\"ar\":\"المستقبلات ليست هياكل جامدة بل بروتينات تتأرجح بين حالات نشطة وخاملة.\",\"en\":\"Receptors are dynamic macromolecules fluctuating between active and inactive states.\"},{\"tr\":\"Aktif halin cebi ile inaktif halin cebi farklı 3 boyutlu şekillere sahiptir.\",\"ar\":\"يمتلك جيب الحالة النشطة شكلاً فراغياً مختلفاً تماماً عن جيب الحالة الخاملة.\",\"en\":\"The 3D pocket of the active conformation differs substantially from the inactive state.\"},{\"tr\":\"Easson-Stedman 3-nokta kenetlenmesi yalnızca doğru konformasyona uyar; ötomer o durumu stabilize ederek sinyali açar veya kapatır.\",\"ar\":\"يطابق تعشيق Easson-Stedman هيئة واحدة فقط؛ فيثبتها eutomer لتفعيل الإشارة أو تثبيطها.\",\"en\":\"3-point attachment locks only the matching state; the eutomer stabilizes that conformation to direct signaling.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":2}],\"config\":{\"options\":[{\"id\":\"opt-11a\",\"text\":\"Reseptörün aktif ve inaktif konformasyonları farklı 3D cepler sunar; ötomer yalnızca hedef konformasyonu stabilize eden 3 noktayı kilitlerken, distomer ters konformasyona oturabilir veya bağlanamaz.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz bağlantı! Reseptörler dinamik proteinlerdir. Aktif durum (Ra) ile inaktif durum (Ri) farklı 3 boyutlu kaviteler sunar. Easson-Stedman modeli gereğince ötomer tek bir durumu 3 noktadan kilitlerken, distomer ters durumu stabilize ederek ters agonist veya nötr antagonist olabilir.\"},{\"id\":\"opt-11b\",\"text\":\"Ters agonistler reseptör proteininin amino asit dizilimini genetik olarak mutasyona uğratır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Genetik mutasyon yanılgısı: Ligandlar proteini mutasyona uğratmaz; mevcut uzaysal konformasyonel dengeleri (Ri vs Ra) kaydırır.\"},{\"id\":\"opt-11c\",\"text\":\"Allosterik modülatörlerde kiralite tamamen önemsizdir; tüm enantiyomerler eşit etki eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Allosterik akiralite yanılgısı: Allosterik cepler de kiral protein kaviteleridir ve Pfeiffer kuralına tam olarak uyarlar.\"}],\"revealedOutcome\":{\"tr\":\"Reseptörün aktif ve inaktif konformasyonları farklı 3D cepler sunar; ötomer yalnızca hedef konformasyonu stabilize eden 3 noktayı kilitlerken, distomer ters konformasyona oturabilir veya bağlanamaz.\",\"ar\":\"توفر هيئات المستقبل النشطة وغير النشطة جيوباً فراغية مختلفة؛ يقفل eutomer النقاط الثلاث للهيئة المستهدفة بينما يرسو distomer في الهيئة المعاكسة أو يفشل بالارتباط.\",\"en\":\"Active and inactive receptor states expose distinct 3D pockets; the eutomer satisfies 3-point contacts on the desired state, while distomers fail to bind or stabilize opposing states.\"},\"explanation\":{\"tr\":\"Kusursuz bağlantı! Reseptörler dinamik proteinlerdir. Aktif durum (Ra) ile inaktif durum (Ri) farklı 3 boyutlu kaviteler sunar. Easson-Stedman modeli gereğince ötomer tek bir durumu 3 noktadan kilitlerken, distomer ters durumu stabilize ederek ters agonist veya nötr antagonist olabilir.\",\"ar\":\"ربط استثنائي! المستقبلات بروتينات ديناميكية. تقدم الهيئة النشطة وغير النشطة جيوباً فراغية متمايزة. يقفل eutomer هيئة واحدة بثلاث نقاط، بينما قد يثبت distomer الهيئة المعاكسة كمنبه عكسي.\",\"en\":\"Outstanding bridge! GPCRs equilibrate between active (Ra) and inactive (Ri) states with distinct 3D pockets. The eutomer stereoselectively locks 3 contacts on Ra (agonist) or Ri (inverse agonist), while the distomer may lack contacts or stabilize the opposing state.\"}}},{\"id\":\"mc-mod4-les1-step-12\",\"stage\":\"mastery_check\",\"stageIndex\":12,\"type\":\"mastery_check\",\"title\":{\"tr\":\"Ustalık Sınavı: Yeni Analjezik Adayında Ödismik Analiz ve Kiral Geçiş\",\"ar\":\"اختبار الإتقان: التحليل الإيوديزمي والتحول الكيرالي لمرشح مسكن جديد\",\"en\":\"Mastery Challenge: Eudismic Audit & Chiral Switch of a Novel Analgesic\"},\"prompt\":{\"tr\":\"Yeni bir analjezik adayında (R)-ötomer Kd = 1.5 nM, (S)-distomer Kd = 1500 nM olarak ölçülmüştür. Bu ilacın Eudismik Oranını (ER), serbest enerji farkını (ΔΔG°) ve saf ötomer geliştirmenin rasyonelliğini değerlendirin:\",\"ar\":\"في مرشح مسكن جديد: بلغت Kd لـ (R)-eutomer قيمة 1.5 nM، و (S)-distomer قيمة 1500 nM. احسب النسبة الإيوديزمية (ER)، وفارق الطاقة الحرة (ΔΔG°)، وقيم جدوى التحول الكيرالي:\",\"en\":\"In a novel analgesic candidate, (R)-eutomer exhibits Kd = 1.5 nM and (S)-distomer Kd = 1500 nM. Calculate the Eudismic Ratio (ER), free energy difference (ΔΔG°), and evaluate the rationale for a chiral switch:\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-12a\",\"text\":{\"tr\":\"ER = 1000; ΔΔG° = -4.26 kcal/mol (-17.8 kJ/mol); Pfeiffer kuralına tam uyan devasa bir kiral seçicilik vardır. Molekül asidik alfa-proton taşımıyorsa saf (R)-ötomer geliştirilmesi zorunludur.\",\"ar\":\"ER = 1000؛ و ΔΔG° = -4.26 kcal/mol (-17.8 kJ/mol)؛ انتقائية كيرالية هائلة تحقق قاعدة Pfeiffer. إذا خلا الجزيء من بروتون ألفا حمضي، فإن تطوير (R) النقي إلزامي.\",\"en\":\"ER = 1000; ΔΔG° = -4.26 kcal/mol (-17.8 kJ/mol); demonstrating immense Pfeiffer chiral fidelity. If the molecule lacks acidic alpha-protons, a single-enantiomer chiral switch is mandatory.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Tebrikler, mükemmel bir farmasötik kimya analizi! 1) ER = 1500 nM / 1.5 nM = 1000. 2) ΔΔG° = 1.42 x log10(1000) = 1.42 x 3 = -4.26 kcal/mol (-17.8 kJ/mol). 3) 1000 katlık fark distomerin %99.9 gereksiz veya potansiyel toksik metabolik yük olduğunu gösterir; kiral inversiyon yoksa saf ötomer geliştirilmelidir.\",\"ar\":\"تهانينا، تحليل دوائي عبقري! 1) ER = 1500 / 1.5 = 1000. 2) ΔΔG° = 1.42 × 3 = -4.26 kcal/mol (-17.8 kJ/mol). 3) يثبت فارق الألف ضعف أن distomer عبء استقلابي سام محتمل؛ وتطوير المصاوغ النقي ضرورة تنظيمية وعلاجية.\",\"en\":\"Mastery demonstrated! 1) ER = 1500 nM / 1.5 nM = 1000. 2) ΔΔG° = 1.42 x log10(1000) = 1.42 x 3 = -4.26 kcal/mol (-17.8 kJ/mol). 3) A 1000-fold gap proves the distomer is 99.9% inert ballast or toxic liability; pure eutomer development is chemically and clinically indicated.\"}},{\"id\":\"opt-12b\",\"text\":{\"tr\":\"ER = 10; ΔΔG° = -1.42 kcal/mol; iki izomer arasında klinik olarak anlamlı bir fark yoktur.\",\"ar\":\"ER = 10؛ و ΔΔG° = -1.42 kcal/mol؛ لا يوجد فارق سريري ذو شأن بين المصاوغين.\",\"en\":\"ER = 10; ΔΔG° = -1.42 kcal/mol; there is no clinically meaningful difference between isomers.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Oranlama hatası: 1500 nM / 1.5 nM = 1000'dir (10 değil). 1000 katlık fark 3 log dekadına ve ~4.26 kcal/mol serbest enerjiye karşılık gelir.\",\"ar\":\"خطأ حسابي: 1500 / 1.5 = 1000 (وليس 10). يعادل فارق الألف ضعف 3 مراتب لوغاريتمية وطاقة حرة قدرها 4.26 kcal/mol.\",\"en\":\"Arithmetic error: 1500 nM / 1.5 nM = 1000 (not 10). A 1000-fold ratio equates to 3 log decades and -4.26 kcal/mol free energy.\"}},{\"id\":\"opt-12c\",\"text\":{\"tr\":\"ER = 1500; ΔΔG° = -10 kcal/mol; distomer vücutta kendiliğinden saf altına dönüşür.\",\"ar\":\"ER = 1500؛ و ΔΔG° = -10 kcal/mol؛ يتحول distomer تلقائياً لذهب نقي.\",\"en\":\"ER = 1500; ΔΔG° = -10 kcal/mol; the distomer transmutes spontaneously into elemental gold.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Simya yanılgısı: ER iki afinitenin oranıdır (1000), distomer Kd'si değildir ve organik maddeler altına dönüşmez.\",\"ar\":\"خطأ خيالي: ER هي النسبة بين القيمتين (1000) وليست قيمة Kd لـ distomer؛ والمصاوغات العضوية لا تتحول لمعادن.\",\"en\":\"Transmutation misconception: ER is the ratio of Kd values (1000), not the distomer Kd itself; organic molecules do not turn into precious metals.\"}}]},\"technicalTerms\":[{\"term\":\"kiral geçiş (chiral switch)\",\"arContext\":\"التحول الكيرالي (chiral switch)\"},{\"term\":\"ödismik analiz\",\"arContext\":\"التحليل الإيوديزمي (eudismic analysis)\"}],\"hints\":[{\"tr\":\"Eudismik oranı hesaplayın: ER = Kd(distomer) / Kd(ötomer) = 1500 / 1.5.\",\"ar\":\"احسب النسبة الإيوديزمية: ER = Kd(distomer) / Kd(eutomer) = 1500 / 1.5.\",\"en\":\"Calculate the eudismic ratio: ER = Kd(distomer) / Kd(eutomer) = 1500 / 1.5.\"},{\"tr\":\"ER = 1000. log10(1000) = 3. Şimdi serbest enerjiyi bulun: 1.42 kcal/mol x 3 = 4.26 kcal/mol.\",\"ar\":\"ER = 1000. و log10(1000) = 3. احسب الطاقة الحرة: 1.42 × 3 = 4.26 kcal/mol.\",\"en\":\"ER = 1000. Since log10(1000) = 3, multiply: 1.42 kcal/mol x 3 = 4.26 kcal/mol.\"},{\"tr\":\"1000 katlık afinite farkı devasa bir kiral üstünlüktür; molekül in vivo rasemize olmuyorsa saf ötomer geliştirilmesi kesinlikle rasyoneldir.\",\"ar\":\"يمثل فارق الألف ضعف تفوقاً كيرالياً هائلاً؛ وإذا خلا الدواء من الراسمة التلقائية فإن تطوير المصاوغ النقي خيار حاسم.\",\"en\":\"A 1000-fold affinity gap represents profound stereospecificity, making a single-enantiomer chiral switch highly compelling.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":23}],\"config\":{\"options\":[{\"id\":\"opt-12a\",\"text\":\"ER = 1000; ΔΔG° = -4.26 kcal/mol (-17.8 kJ/mol); Pfeiffer kuralına tam uyan devasa bir kiral seçicilik vardır. Molekül asidik alfa-proton taşımıyorsa saf (R)-ötomer geliştirilmesi zorunludur.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Tebrikler, mükemmel bir farmasötik kimya analizi! 1) ER = 1500 nM / 1.5 nM = 1000. 2) ΔΔG° = 1.42 x log10(1000) = 1.42 x 3 = -4.26 kcal/mol (-17.8 kJ/mol). 3) 1000 katlık fark distomerin %99.9 gereksiz veya potansiyel toksik metabolik yük olduğunu gösterir; kiral inversiyon yoksa saf ötomer geliştirilmelidir.\"},{\"id\":\"opt-12b\",\"text\":\"ER = 10; ΔΔG° = -1.42 kcal/mol; iki izomer arasında klinik olarak anlamlı bir fark yoktur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Oranlama hatası: 1500 nM / 1.5 nM = 1000'dir (10 değil). 1000 katlık fark 3 log dekadına ve ~4.26 kcal/mol serbest enerjiye karşılık gelir.\"},{\"id\":\"opt-12c\",\"text\":\"ER = 1500; ΔΔG° = -10 kcal/mol; distomer vücutta kendiliğinden saf altına dönüşür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Simya yanılgısı: ER iki afinitenin oranıdır (1000), distomer Kd'si değildir ve organik maddeler altına dönüşmez.\"}],\"revealedOutcome\":{\"tr\":\"ER = 1000; ΔΔG° = -4.26 kcal/mol (-17.8 kJ/mol); Pfeiffer kuralına tam uyan devasa bir kiral seçicilik vardır. Molekül asidik alfa-proton taşımıyorsa saf (R)-ötomer geliştirilmesi zorunludur.\",\"ar\":\"ER = 1000؛ و ΔΔG° = -4.26 kcal/mol (-17.8 kJ/mol)؛ انتقائية كيرالية هائلة تحقق قاعدة Pfeiffer. إذا خلا الجزيء من بروتون ألفا حمضي، فإن تطوير (R) النقي إلزامي.\",\"en\":\"ER = 1000; ΔΔG° = -4.26 kcal/mol (-17.8 kJ/mol); demonstrating immense Pfeiffer chiral fidelity. If the molecule lacks acidic alpha-protons, a single-enantiomer chiral switch is mandatory.\"},\"explanation\":{\"tr\":\"Tebrikler, mükemmel bir farmasötik kimya analizi! 1) ER = 1500 nM / 1.5 nM = 1000. 2) ΔΔG° = 1.42 x log10(1000) = 1.42 x 3 = -4.26 kcal/mol (-17.8 kJ/mol). 3) 1000 katlık fark distomerin %99.9 gereksiz veya potansiyel toksik metabolik yük olduğunu gösterir; kiral inversiyon yoksa saf ötomer geliştirilmelidir.\",\"ar\":\"تهانينا، تحليل دوائي عبقري! 1) ER = 1500 / 1.5 = 1000. 2) ΔΔG° = 1.42 × 3 = -4.26 kcal/mol (-17.8 kJ/mol). 3) يثبت فارق الألف ضعف أن distomer عبء استقلابي سام محتمل؛ وتطوير المصاوغ النقي ضرورة تنظيمية وعلاجية.\",\"en\":\"Mastery demonstrated! 1) ER = 1500 nM / 1.5 nM = 1000. 2) ΔΔG° = 1.42 x log10(1000) = 1.42 x 3 = -4.26 kcal/mol (-17.8 kJ/mol). 3) A 1000-fold gap proves the distomer is 99.9% inert ballast or toxic liability; pure eutomer development is chemically and clinically indicated.\"}}}]},\"mc-mod4-les2\":{\"$schema\":\"../../../packages/platform/schema/lesson.schema.json\",\"id\":\"mc-mod4-les2\",\"courseId\":\"medchem\",\"moduleId\":\"mc-mod-04\",\"title\":{\"tr\":\"Konformasyonel İzomerizm: Rijit ve Esnek İskeletler\",\"ar\":\"التماكب التشكلي: الهياكل الجاسئة والمرنة\",\"en\":\"Conformational Isomerism: Rigid & Flexible Scaffolds\"},\"order\":2,\"access\":\"free\",\"objective\":{\"tr\":\"Asetilkolin ve histamin gibi esnek moleküllerde konformasyonel kısıtlama ve rijit analog tasarımını uygulayarak reseptör alt tip seçiciliğini artırmayı ve bağlanma entropi cezasını düşürmeyi öğrenmek.\",\"ar\":\"تطبيق استراتيجيات التجسئة الهيكلية والتقييد التشكلي على الجزيئات المرنة كأستيل كولين والهستامين لتحسين الانتقائية الفرعية وخفض ضريبة الإنتروبيا.\",\"en\":\"Design conformationally restricted and rigid drug scaffolds to lock bioactive conformers, eliminate conformational entropy penalties, and maximize receptor subtype selectivity.\"},\"misconceptions\":[{\"tr\":\"Molekülün çözeltideki en kararlı (en düşük enerjili) konformasyonunun her zaman reseptöre bağlanan konformasyon olduğu yanılgısı (Biyoaktif Konformasyon Paradoksu).\",\"ar\":\"الظن الخاطئ بأن التشكيل الفراغي الأكثر استقراراً والأدنى طاقة في المحلول الحر هو دائماً التشكيل الذي يرتبط بالمستقبل.\",\"en\":\"The misconception that the global minimum energy conformer in aqueous solution is always the conformer that binds the receptor.\"},{\"tr\":\"Çok sayıda serbest dönebilen tekli bağa sahip aşırı esnek moleküllerin reseptör ceplerine daha kolay uyum sağlayıp daha güçlü bağlanacağı yanılgısı (Entropi cezası göz ardı edilir).\",\"ar\":\"الاعتقاد الخاطئ بأن الجزيئات مفرطة المرونة ترتبط بقوة أكبر لقدرتها على التكيف متجاهلاً ضريبة الإنتروبيا التشكيلية الهائلة.\",\"en\":\"The belief that high molecular flexibility improves affinity, ignoring the massive conformational entropy penalty upon binding.\"},{\"tr\":\"Asetilkolinin muskarinik ve nikotinik reseptörleri aynı 3 boyutlu uzaysal konformasyonda aktive ettiği düşüncesi.\",\"ar\":\"الظن الخاطئ بأن الأسيتيل كولين ينشط المستقبلات المسكارينية والنيكوتينية بنفس التشكيل الفراغي المتطابق.\",\"en\":\"The assumption that acetylcholine activates both muscarinic and nicotinic receptors in an identical spatial conformation.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":8},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":39},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":40},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":41},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":42},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":43}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Foye's Principles of Medicinal Chemistry\",\"edition\":\"8th ed.\",\"topic\":\"Conformational Isomerism, Rigidification, and Bioactive Conformations\",\"chapter\":\"Chapter 2\",\"page\":\"45-62\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Wilson and Gisvold's Textbook of Organic Medicinal and Pharmaceutical Chemistry\",\"edition\":\"12th ed.\",\"topic\":\"Conformational Factors in Drug Action: Acetylcholine and Histamine Rotamers\",\"chapter\":\"Chapter 2\",\"page\":\"35-50\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"mc-mod4-les2-card1\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Asetilkolin Gauche vs Anti Mesafeleri\",\"prompt\":\"Asetilkolinin muskarinik ve nikotinik reseptörleri bağlayan konformerlerinde N+ ile ester O arası mesafeler nedir?\",\"answer\":\"Katlanmış (gauche) formda 3.3 Å (muskarinik); uzamış (anti) formda 4.4 Å (nikotinik) mesafededir (Slayt 42).\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod4-les2-card2\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Biyoaktif Konformasyon Paradoksu\",\"prompt\":\"Bir ilacın çözeltideki en düşük enerjili konformasyonu reseptöre bağlanan form olmak zorunda mıdır?\",\"answer\":\"Hayır; reseptör bağlanma entalpisi (ΔH), daha yüksek enerjili bir biyoaktif konformasyona geçiş enerjisini karşılar.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod4-les2-card3\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Histamin H1 vs H2 Mesafeleri\",\"prompt\":\"Histaminin H1 ve H2 reseptörlerine bağlanan rotamerlerindeki farmakoforik mesafeler nedir?\",\"answer\":\"H1 için uzamış transoid A formu 4.55 Å; H2 için katlanmış gauche B formu 3.60 Å mesafededir (Slayt 43).\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod4-les2-card4\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Rijit İskelet Tasarımının Entropi Kazancı\",\"prompt\":\"Esnek bir molekülü halka içine alarak dondurmak bağlanma serbest enerjisini (ΔG) neden katlar?\",\"answer\":\"Rotasyonel bağlar donduğunda bağlanma anındaki konformasyonel entropi kaybı (-TΔS) silinir; her bağ ~2.5-4 kJ/mol kazandırır.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod4-les2-card5\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Siklopropil Asetilkolin Testi\",\"prompt\":\"Asetilkolinin (+)-cis ve (+)-trans siklopropil analogları hangi reseptörleri seçici olarak uyarır?\",\"answer\":\"(+)-Cis analog sadece muskarinik, (+)-trans analog ise sadece nikotinik reseptörleri uyarır (Slayt 42).\",\"box\":1,\"intervalDays\":1}],\"translations\":{\"tr\":{\"title\":\"Konformasyonel İzomerizm: Rijit ve Esnek İskeletler\"},\"ar\":{\"title\":\"التماكب التشكلي: الهياكل الجاسئة والمرنة\"}},\"steps\":[{\"id\":\"mc-mod4-les2-step-01\",\"stage\":\"hook\",\"stageIndex\":1,\"type\":\"predict_reveal\",\"title\":{\"tr\":\"İki Ayrı Reseptör, Tek Bir Esnek Molekül\",\"ar\":\"مستقبلان مختلفان لجزيء مرن واحد\",\"en\":\"The Acetylcholine Paradox: One Molecule, Two Shapes\"},\"prompt\":{\"tr\":\"Asetilkolin kalpte muskarinik, çizgili kasta nikotinik reseptörleri uyarır. Esnek bir ester zincirine sahip tek bir molekül, iki tamamen farklı reseptör cebini nasıl ayrı ayrı aktive edebilir?\",\"ar\":\"ينشط الأسيتيل كولين المستقبلات المسكارينية في القلب والنيكوتينية في العضلات. كيف ينشط جزيء مرن واحد نوعين متباعدين تماماً من المستقبلات دون التباس؟\",\"en\":\"Acetylcholine activates muscarinic receptors in the heart and nicotinic receptors in skeletal muscle. How can a single flexible molecule selectively trigger two radically different receptor pockets?\"},\"predictThenReveal\":true,\"technicalTerms\":[{\"term\":\"konformasyonel izomerizm\",\"arContext\":\"التماكب التشكلي\"},{\"term\":\"rotamer\",\"arContext\":\"المتشكل الدوراني\"}],\"hints\":[{\"tr\":\"Tekli sigma bağlarının etrafında serbest dönme serbestliğini düşünün.\",\"ar\":\"فكر في حرية الدوران حول الروابط الأحادية سيغما.\",\"en\":\"Consider the freedom of rotation around single sigma bonds.\"},{\"tr\":\"Molekül uzayda katlanabilir veya uzayabilir; iki formun atomlar arası mesafeleri farklıdır.\",\"ar\":\"يمكن للجزيء أن ينطوي أو يمتد؛ فالمسافات بين الذرات تختلف في الشكلين.\",\"en\":\"The molecule can fold or extend, altering interatomic pharmacophoric distances.\"},{\"tr\":\"Asetilkolin tekli bağlarını döndürerek katlanmış (gauche) formda muskarinik, uzamış (anti) formda nikotinik reseptöre oturur.\",\"ar\":\"يدور أستيل كولين ليتبنى تشكيلاً مطوياً مع المسكاريني وتشكيلاً ممتداً مع النيكوتيني.\",\"en\":\"Acetylcholine rotates to adopt a folded gauche conformer for muscarinic and an extended anti conformer for nicotinic receptors.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":42}],\"conceptCheck\":{\"options\":[{\"id\":\"opt-1a\",\"text\":{\"tr\":\"Tekli bağları etrafında dönerek farklı konformerler alır: Katlanmış (gauche) form muskarinik, uzamış (anti) form nikotinik cebe uyar.\",\"ar\":\"يدور حول روابطه الأحادية: التشكيل المطوي (gauche) يلائم المسكاريني والممتد (anti) يلائم النيكوتيني.\",\"en\":\"It rotates around sigma bonds: The folded gauche conformer fits muscarinic, while extended anti fits nicotinic receptors.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Tam isabet! Tekli bağlar etrafında dönme ile oluşan rotamerler sayesinde asetilkolin iki farklı cepte iki farklı biyoaktif geometri sunar (Slayt 42).\",\"ar\":\"صحيح تماماً! الدوران الحر حول الروابط ينتج متشكلي gauche و anti بمسافات فراغية مطابقة لكلا المستقبلين.\",\"en\":\"Spot on! Free rotation around single bonds generates folded gauche and extended anti rotamers custom-tailored to each receptor pocket (Slide 42).\"}},{\"id\":\"opt-1b\",\"text\":{\"tr\":\"Asetilkolin iki farklı reseptöre bağlanabilmek için kanda enzimatik olarak iki farklı kovalent izomere parçalanıp yeniden sentezlenir.\",\"ar\":\"يتفكك الأستيل كولين إنزيمياً في الدم إلى مماكبين تساهميين مختلفين ثم يعاد تركيبه ليرتبط بكل مستقبل.\",\"en\":\"Acetylcholine enzymatically cleaves and resynthesizes in blood into two distinct covalent isomers to bind each receptor.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kovalent izomerizasyon yanılgısı: Reseptör alt tiplerine bağlanmak için kovalent bağların kırılıp oluşmasına gerek yoktur; molekül tekli C-C ve C-O bağları etrafında nanosaniyelik hızla dönerek farklı uzaysal konformasyonlar (rotamerler) üretir.\",\"ar\":\"مغالطة التماكب التساهمي: لا حاجة لكسر روابط تساهمية؛ الجزيء يدور بسرعة نانوثانية حول روابطه الأحادية ليعطي تشكيلات فراغية مختلفة.\",\"en\":\"Covalent isomerization misconception: No covalent bond cleavage is required; the molecule rotates around single bonds in nanoseconds to generate distinct conformers.\"}},{\"id\":\"opt-1c\",\"text\":{\"tr\":\"Asetilkolinin kuaterner amonyum grubu o kadar güçlü bir pozitif yüktür ki reseptör cep şekli ne olursa olsun elektrostatik çekim tek başına iki reseptörü de ayrım yapmaksızın aktive eder.\",\"ar\":\"شحنة الأمونيوم الرباعية قوية جداً بحيث تجذب وتنشط كلا المستقبلين كهربائياً بغض النظر عن الشكل الفراغي للجيب.\",\"en\":\"Acetylcholine's quaternary ammonium positive charge is so strong that electrostatic attraction alone activates both receptors regardless of pocket shape.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yalnızca iyonik çekim yanılgısı: İyonik bağ reseptöre ilk yanaşmayı sağlasa da, farmakofor grupları (amonyum ve ester oksijenleri) arasındaki mesafenin reseptör cebine uymaması durumunda bağlanma ve aktivasyon gerçekleşemez.\",\"ar\":\"مغالطة الجذب الأيوني الحصري: الرابطة الأيونية تقرب الجزيء لكن تطابق المسافة الفراغية بين مجموعات الفارماكوفور وجيب المستقبل ضروري للارتباط والتنشيط.\",\"en\":\"Ionic-only attraction fallacy: Ionic attraction initiates binding, but precise pharmacophoric distance match inside the pocket is mandatory for activation.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-1a\",\"text\":\"Tekli bağları etrafında dönerek farklı konformerler alır: Katlanmış (gauche) form muskarinik, uzamış (anti) form nikotinik cebe uyar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Tam isabet! Tekli bağlar etrafında dönme ile oluşan rotamerler sayesinde asetilkolin iki farklı cepte iki farklı biyoaktif geometri sunar (Slayt 42).\"},{\"id\":\"opt-1b\",\"text\":\"Asetilkolin iki farklı reseptöre bağlanabilmek için kanda enzimatik olarak iki farklı kovalent izomere parçalanıp yeniden sentezlenir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kovalent izomerizasyon yanılgısı: Reseptör alt tiplerine bağlanmak için kovalent bağların kırılıp oluşmasına gerek yoktur; molekül tekli C-C ve C-O bağları etrafında nanosaniyelik hızla dönerek farklı uzaysal konformasyonlar (rotamerler) üretir.\"},{\"id\":\"opt-1c\",\"text\":\"Asetilkolinin kuaterner amonyum grubu o kadar güçlü bir pozitif yüktür ki reseptör cep şekli ne olursa olsun elektrostatik çekim tek başına iki reseptörü de ayrım yapmaksızın aktive eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yalnızca iyonik çekim yanılgısı: İyonik bağ reseptöre ilk yanaşmayı sağlasa da, farmakofor grupları (amonyum ve ester oksijenleri) arasındaki mesafenin reseptör cebine uymaması durumunda bağlanma ve aktivasyon gerçekleşemez.\"}],\"revealedOutcome\":{\"tr\":\"Tekli bağları etrafında dönerek farklı konformerler alır: Katlanmış (gauche) form muskarinik, uzamış (anti) form nikotinik cebe uyar.\",\"ar\":\"يدور حول روابطه الأحادية: التشكيل المطوي (gauche) يلائم المسكاريني والممتد (anti) يلائم النيكوتيني.\",\"en\":\"It rotates around sigma bonds: The folded gauche conformer fits muscarinic, while extended anti fits nicotinic receptors.\"},\"explanation\":{\"tr\":\"Tam isabet! Tekli bağlar etrafında dönme ile oluşan rotamerler sayesinde asetilkolin iki farklı cepte iki farklı biyoaktif geometri sunar (Slayt 42).\",\"ar\":\"صحيح تماماً! الدوران الحر حول الروابط ينتج متشكلي gauche و anti بمسافات فراغية مطابقة لكلا المستقبلين.\",\"en\":\"Spot on! Free rotation around single bonds generates folded gauche and extended anti rotamers custom-tailored to each receptor pocket (Slide 42).\"}}},{\"id\":\"mc-mod4-les2-step-02\",\"stage\":\"question\",\"stageIndex\":2,\"type\":\"question\",\"title\":{\"tr\":\"Biyoaktif Konformasyon Paradoksu\",\"ar\":\"مفارقة التشكيل الحيوي الفعال\",\"en\":\"The Bioactive Conformation Conundrum\"},\"prompt\":{\"tr\":\"Bir molekülün sulu çözeltideki en düşük enerjili en kararlı konformasyonu, reseptöre bağlandığı andaki biyoaktif konformasyonu olmak zorunda mıdır?\",\"ar\":\"هل يجب بالضرورة أن يكون التشكيل الفراغي الأكثر استقراراً والأدنى طاقة في المحلول هو ذاته التشكيل الفعال المرتبط بالمستقبل؟\",\"en\":\"Must a flexible drug's lowest-energy ground state conformer in solution be the exact bioactive conformation that binds the receptor?\"},\"technicalTerms\":[{\"term\":\"biyoaktif konformasyon\",\"arContext\":\"التشكيل الحيوي الفعال\"}],\"hints\":[{\"tr\":\"Reseptör cebi ile ligand arasında yeni bağlar kurulurken ne açığa çıkar?\",\"ar\":\"ما الذي يتحرر عند تشكل روابط جديدة بين الدواء وجيب المستقبل؟\",\"en\":\"What is released when new noncovalent bonds form between drug and receptor?\"},{\"tr\":\"Bağlanma entalpisi (ΔH), molekülün enerji bariyerini aşmasına yardım edebilir mi?\",\"ar\":\"هل يمكن لطاقة الارتباط (ΔH) أن تعوض طاقة إجهاد التشكيل؟\",\"en\":\"Can binding enthalpy (ΔH) compensate for the energetic cost of adopting a higher-energy rotamer?\"},{\"tr\":\"Reseptöre bağlanan form en düşük enerjili form olmak zorunda değildir; bağlanma serbest enerjisi farkı karşılar.\",\"ar\":\"ليس بالضرورة؛ طاقة الارتباط تعوض الانتقال إلى تشكيل أعلى طاقة.\",\"en\":\"Not necessarily; favorable binding free energy readily offsets the modest strain of adopting a higher-energy conformer.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":39}],\"conceptCheck\":{\"options\":[{\"id\":\"opt-2a\",\"text\":{\"tr\":\"Hayır; reseptörle kurulan non-kovalan bağların açığa çıkardığı bağlanma enerjisi, daha yüksek enerjili bir biyoaktif konformasyonu sübvanse eder.\",\"ar\":\"لا؛ فطاقة الارتباط الناتجة عن الروابط مع المستقبل تعوض تكلفة تبني تشكيل حيوي أعلى طاقة.\",\"en\":\"No; the favorable binding enthalpy from drug-receptor contacts easily offsets the energetic cost of a higher-energy conformer.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel! Bu kural farmasötik kimyanın temelidir: Çözeltide %1 oranında bulunan yüksek enerjili bir konformer, reseptöre kusursuz bağlanıp biyoaktif form olabilir (Slayt 39).\",\"ar\":\"رائع! التشكيل الحيوي الفعال ليس بالضرورة التشكيل الأكثر وفرة أو الأقل طاقة في المحلول الحر.\",\"en\":\"Excellent! A minor conformer present at <1% in solution can be the true bioactive species if its receptor contacts provide massive stabilizing enthalpy (Slide 39).\"}},{\"id\":\"opt-2b\",\"text\":{\"tr\":\"Evet; termodinamik kuralları gereği reseptörler yalnızca mutlak global minimumdaki molekülleri kabul edebilir.\",\"ar\":\"نعم؛ تفرض قوانين الديناميكا الحرارية قبول التشكيل الأدنى طاقة فقط.\",\"en\":\"Yes; thermodynamic laws dictate that receptors only accept molecules in their absolute global energy minimum.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"En düşük enerji dogması: Reseptör bir spektrometre değildir; ligand-reseptör kompleksinin toplam serbest enerjisi minimuma iner, serbest ligantın değil.\",\"ar\":\"فخ طاقة القاع: العبرة بالطاقة الحرة الكلية للمعقد (الدواء-المستقبل) وليس للدواء بمفرده في الماء.\",\"en\":\"Ground-state dogma: What must be minimized is the free energy of the overall drug-receptor complex, not the isolated ligand in water.\"}},{\"id\":\"opt-2c\",\"text\":{\"tr\":\"Evet; çünkü reseptörün bağlanma cebi tamamen katı ve hareketsizdir, ligantın yüksek enerjili bir forma bükülmesine izin verecek esnekliğe sahip değildir.\",\"ar\":\"نعم، لأن جيب المستقبل صلب وثابت تماماً ولا يملك أي مرونة تسمح بارتباط مركب منحني بشكل عالي الطاقة.\",\"en\":\"Yes, because the receptor binding pocket is completely rigid and immutable, lacking any flexibility to accommodate strained conformations.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Rijit anahtar-kilit yanılgısı: Koshland'ın indüklenmiş uyum (induced-fit) teorisine göre hem reseptör hem ligant bağlanma sırasında birbirine uyum sağlayacak konformasyonel değişiklikler geçirir.\",\"ar\":\"مغالطة القفل والمفتاح الجاسئ: وفقاً لنظرية التلاؤم المحثوث (induced-fit)، يخضع كل من المستقبل والربيطة لتغيرات تشكلية للتكيف المتبادل.\",\"en\":\"Rigid lock-and-key fallacy: Under induced-fit theory, both the receptor pocket and the ligand undergo mutual conformational adaptations upon binding.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-2a\",\"text\":\"Hayır; reseptörle kurulan non-kovalan bağların açığa çıkardığı bağlanma enerjisi, daha yüksek enerjili bir biyoaktif konformasyonu sübvanse eder.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel! Bu kural farmasötik kimyanın temelidir: Çözeltide %1 oranında bulunan yüksek enerjili bir konformer, reseptöre kusursuz bağlanıp biyoaktif form olabilir (Slayt 39).\"},{\"id\":\"opt-2b\",\"text\":\"Evet; termodinamik kuralları gereği reseptörler yalnızca mutlak global minimumdaki molekülleri kabul edebilir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"En düşük enerji dogması: Reseptör bir spektrometre değildir; ligand-reseptör kompleksinin toplam serbest enerjisi minimuma iner, serbest ligantın değil.\"},{\"id\":\"opt-2c\",\"text\":\"Evet; çünkü reseptörün bağlanma cebi tamamen katı ve hareketsizdir, ligantın yüksek enerjili bir forma bükülmesine izin verecek esnekliğe sahip değildir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Rijit anahtar-kilit yanılgısı: Koshland'ın indüklenmiş uyum (induced-fit) teorisine göre hem reseptör hem ligant bağlanma sırasında birbirine uyum sağlayacak konformasyonel değişiklikler geçirir.\"}],\"revealedOutcome\":{\"tr\":\"Hayır; reseptörle kurulan non-kovalan bağların açığa çıkardığı bağlanma enerjisi, daha yüksek enerjili bir biyoaktif konformasyonu sübvanse eder.\",\"ar\":\"لا؛ فطاقة الارتباط الناتجة عن الروابط مع المستقبل تعوض تكلفة تبني تشكيل حيوي أعلى طاقة.\",\"en\":\"No; the favorable binding enthalpy from drug-receptor contacts easily offsets the energetic cost of a higher-energy conformer.\"},\"explanation\":{\"tr\":\"Mükemmel! Bu kural farmasötik kimyanın temelidir: Çözeltide %1 oranında bulunan yüksek enerjili bir konformer, reseptöre kusursuz bağlanıp biyoaktif form olabilir (Slayt 39).\",\"ar\":\"رائع! التشكيل الحيوي الفعال ليس بالضرورة التشكيل الأكثر وفرة أو الأقل طاقة في المحلول الحر.\",\"en\":\"Excellent! A minor conformer present at <1% in solution can be the true bioactive species if its receptor contacts provide massive stabilizing enthalpy (Slide 39).\"}}},{\"id\":\"mc-mod4-les2-step-03\",\"stage\":\"intuition\",\"stageIndex\":3,\"type\":\"intuition\",\"title\":{\"tr\":\"Sezgisel Model: Sallanan İp vs Kilitli Anahtar\",\"ar\":\"نموذج حدسي: الحبل المتأرجح مقابل المفتاح الثابت\",\"en\":\"Mental Model: Wild Rope vs Pre-Cast Key\"},\"prompt\":{\"tr\":\"Serbest dönen 4 tekli bağı olan esnek bir molekül reseptöre bağlanırken neden büyük bir termodinamik ceza öder?\",\"ar\":\"لماذا تدفع جزيئة مرنة تمتلك 4 روابط أحادية دوارة ضريبة ديناميكية حرارية باهظة عند ارتباطها بالمستقبل؟\",\"en\":\"Why does an ultra-flexible drug molecule with 4 rotatable bonds pay a massive thermodynamic penalty when locking into a receptor pocket?\"},\"technicalTerms\":[{\"term\":\"konformasyonel entropi\",\"arContext\":\"الإنتروبيا التشكيلية\"}],\"hints\":[{\"tr\":\"Çözeltide yüzlerce farklı biçimde sallanan bir ipi tek bir şekle soktuğunuzda düzensizlik (entropi) ne olur?\",\"ar\":\"ماذا يحدث للعشوائية (الإنتروبيا) عندما تجبر حبلاً حراً يتلوى بمئات الأشكال على التزام شكل واحد؟\",\"en\":\"What happens to molecular disorder (entropy) when a rope twisting in hundreds of states is forced into one fixed shape?\"},{\"tr\":\"Termodinamikte düzenin bedeli (-TΔS) pozitiftir; bu bağlanma serbest enerjisini (ΔG) zayıflatır.\",\"ar\":\"ضريبة النظام الإيجابية (-TΔS) تضعف طاقة الارتباط الحرة.\",\"en\":\"The thermodynamic penalty of enforced order (-TΔS > 0) directly opposes and weakens binding affinity.\"},{\"tr\":\"Dönen bağların donması konformasyonel entropi cezası üretir; rijit moleküller bu cezadan muaftır.\",\"ar\":\"تجميد الروابط الدوارة يفرض ضريبة إنتروبية باهظة؛ بينما الهياكل الجاسئة معفاة منها.\",\"en\":\"Freezing rotatable bonds creates a severe conformational entropy penalty; pre-organized rigid scaffolds evade this penalty.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":41}],\"conceptCheck\":{\"options\":[{\"id\":\"opt-3a\",\"text\":{\"tr\":\"Serbest rotasyon yapan bağların tek bir şekilde donması entropi cezası (-TΔS) üretir ve afiniteyi zayıflatır.\",\"ar\":\"تجميد الروابط الحرة في هيئة واحدة يولد ضريبة إنتروبيا (-TΔS) تنقص من طاقة الارتباط الكلية.\",\"en\":\"Freezing freely rotating bonds into a single pose incurs a heavy conformational entropy penalty (-TΔS), weakening affinity.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika analiz! Her serbest dönebilen bağ için ~2.5-4.0 kJ/mol entropik bedel ödenir. Bu nedenle esnek moleküller cebe oturmakta zorlanır.\",\"ar\":\"تحليل رائع! كل رابطة حرة تتجمد تكلف ~2.5 إلى 4 كيلوجول/مول كضريبة إنتروبية تضعف الارتباط.\",\"en\":\"Brilliant! Freezing each rotatable bond costs ~2.5-4.0 kJ/mol in entropic penalty. Pre-organizing the scaffold saves this energy.\"}},{\"id\":\"opt-3b\",\"text\":{\"tr\":\"Esnek moleküllerin reseptör cebine girmesi sterik olarak imkansızdır; bu yüzden esnek ilaçlar reseptör içine hiç nüfuz edemez.\",\"ar\":\"دخول الجزيئات المرنة إلى جيب المستقبل مستحيل فراغياً بسبب الإعاقة الحجمية؛ لذلك لا تنفذ إطلاقاً.\",\"en\":\"Flexible molecules face insurmountable steric bulk preventing entry into narrow receptor pockets entirely.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Sterik giriş engeli yanılgısı: Esnek moleküller cebe rahatlıkla girer; sorun cebe girememeleri değil, cebe oturduklarında kaybettikleri rotasyonel serbestliğin termodinamik bir entropi bedeli doğurmasıdır.\",\"ar\":\"مغالطة عائق الدخول الفراغي: الجزيئات المرنة تدخل بسهولة؛ المشكلة تكمن في ضريبة الإنتروبيا التشكيلية الناتجة عن فقدان حرية الدوران.\",\"en\":\"Steric block fallacy: Flexible molecules enter easily; the limitation is the severe thermodynamic entropy loss from freezing rotatable bonds.\"}},{\"id\":\"opt-3c\",\"text\":{\"tr\":\"Dönen bağlar ilacın biyolojik zarları geçmesini engeller; esnek moleküller yağ fazında tamamen çözünmez kalır.\",\"ar\":\"الروابط الدوارة تمنع الدواء من عبور الأغشية الحيوية، فتبقى الجزيئات المرنة غير ذوابة بالدهون تماماً.\",\"en\":\"Rotating bonds prevent drugs from crossing biological membranes; flexible drugs remain completely insoluble in lipids.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Membran geçişi yanılgısı: Esnek moleküller çözücüye göre konformasyon değiştirerek zarları kolayca geçebilir; ancak reseptöre kilitlenme afiniteleri entropi kaybı nedeniyle düşüktür.\",\"ar\":\"مغالطة عبور الغشاء: الجزيئات المرنة تعبر الأغشية بسهولة بتغيير تشكلها؛ لكن ألفة ارتباطها تنخفض بسبب ضريبة الإنتروبيا.\",\"en\":\"Membrane transit fallacy: Flexible molecules readily cross membranes by adapting conformers, but binding affinity suffers from entropy loss.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-3a\",\"text\":\"Serbest rotasyon yapan bağların tek bir şekilde donması entropi cezası (-TΔS) üretir ve afiniteyi zayıflatır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika analiz! Her serbest dönebilen bağ için ~2.5-4.0 kJ/mol entropik bedel ödenir. Bu nedenle esnek moleküller cebe oturmakta zorlanır.\"},{\"id\":\"opt-3b\",\"text\":\"Esnek moleküllerin reseptör cebine girmesi sterik olarak imkansızdır; bu yüzden esnek ilaçlar reseptör içine hiç nüfuz edemez.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Sterik giriş engeli yanılgısı: Esnek moleküller cebe rahatlıkla girer; sorun cebe girememeleri değil, cebe oturduklarında kaybettikleri rotasyonel serbestliğin termodinamik bir entropi bedeli doğurmasıdır.\"},{\"id\":\"opt-3c\",\"text\":\"Dönen bağlar ilacın biyolojik zarları geçmesini engeller; esnek moleküller yağ fazında tamamen çözünmez kalır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Membran geçişi yanılgısı: Esnek moleküller çözücüye göre konformasyon değiştirerek zarları kolayca geçebilir; ancak reseptöre kilitlenme afiniteleri entropi kaybı nedeniyle düşüktür.\"}],\"revealedOutcome\":{\"tr\":\"Serbest rotasyon yapan bağların tek bir şekilde donması entropi cezası (-TΔS) üretir ve afiniteyi zayıflatır.\",\"ar\":\"تجميد الروابط الحرة في هيئة واحدة يولد ضريبة إنتروبيا (-TΔS) تنقص من طاقة الارتباط الكلية.\",\"en\":\"Freezing freely rotating bonds into a single pose incurs a heavy conformational entropy penalty (-TΔS), weakening affinity.\"},\"explanation\":{\"tr\":\"Harika analiz! Her serbest dönebilen bağ için ~2.5-4.0 kJ/mol entropik bedel ödenir. Bu nedenle esnek moleküller cebe oturmakta zorlanır.\",\"ar\":\"تحليل رائع! كل رابطة حرة تتجمد تكلف ~2.5 إلى 4 كيلوجول/مول كضريبة إنتروبية تضعف الارتباط.\",\"en\":\"Brilliant! Freezing each rotatable bond costs ~2.5-4.0 kJ/mol in entropic penalty. Pre-organizing the scaffold saves this energy.\"}}},{\"id\":\"mc-mod4-les2-step-04\",\"stage\":\"visual_explanation\",\"stageIndex\":4,\"type\":\"visual_explanation\",\"title\":{\"tr\":\"Asetilkolinin İki Yüzü: Gauche vs Anti\",\"ar\":\"وجها الأسيتيل كولين: المتطابق والممتد\",\"en\":\"Structural Profiles: Gauche vs Anti Rotamers\"},\"prompt\":{\"tr\":\"Asetilkolinin kuaterner azotu ile ester oksijeni arasındaki mesafe katlanmış (gauche) formda 3.3 Å, uzamış (anti) formda 4.4 Å'dür. Bu fark neyi belirler?\",\"ar\":\"المسافة بين نيتروجين الأسيتيل كولين وأكسجين الإستر هي 3.3 أنغستروم في التشكيل المطوي و4.4 في الممتد. ماذا يحدد هذا؟\",\"en\":\"The distance between acetylcholine's quaternary nitrogen and ester oxygen is 3.3 Å in the folded gauche conformer and 4.4 Å in the extended anti conformer. What does this dictate?\"},\"technicalTerms\":[{\"term\":\"gauche konformasyon\",\"arContext\":\"تشكيل غوش المطوي\"},{\"term\":\"anti konformasyon\",\"arContext\":\"تشكيل أنتي الممتد\"}],\"hints\":[{\"tr\":\"3.3 Å ve 4.4 Å mesafeleri iki farklı reseptör cebinin bağlanma noktalarına karşılık gelir.\",\"ar\":\"المسافتان 3.3 و 4.4 أنغستروم تقابلان نقطتي ارتباط في جيبي مستقبلين مختلفين.\",\"en\":\"The 3.3 Å and 4.4 Å spans match distinct pharmacophore distances in two different receptor subtypes.\"},{\"tr\":\"Kalp kası muskarinik, çizgili kas nikotinik cepleri farklı mesafeler arar.\",\"ar\":\"يتطلب الجيب المسكاريني في القلب والنيكوتيني في العضلات مسافات فراغية متباينة.\",\"en\":\"Muscarinic GPCRs and nicotinic ion channels require completely different interaction geometries.\"},{\"tr\":\"3.3 Å katlanmış form muskarinik reseptöre, 4.4 Å uzamış form nikotinik reseptöre bağlanır.\",\"ar\":\"الشكل المطوي 3.3 يربط المسكاريني والشكل الممتد 4.4 يربط النيكوتيني.\",\"en\":\"The 3.3 Å folded gauche rotamer binds muscarinic receptors; the 4.4 Å extended anti rotamer binds nicotinic receptors.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":42}],\"conceptCheck\":{\"options\":[{\"id\":\"opt-4a\",\"text\":{\"tr\":\"Reseptör alt tip seçiciliğini: 3.3 Å katlanmış form muskarinik cebe, 4.4 Å uzamış form nikotinik cebe tam oturur.\",\"ar\":\"الانتقائية الفرعية للمستقبل: المطوي (3.3 Å) يلائم المسكاريني والممتد (4.4 Å) يلائم النيكوتيني.\",\"en\":\"Subtype selectivity: The 3.3 Å gauche form binds muscarinic, while the 4.4 Å anti form binds nicotinic receptors.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz bilgi! Slayt 40 ve 42: Newman projeksiyonlarında çapraz (staggered) gauche (3.3 Å) ve anti (4.4 Å) rotamerleri enerji çukurlarıdır; çakışık (eclipsed) formlar ise sterik itme tepeleridir. Gauche formu muskarinik, anti formu nikotinik reseptöre seçicilik sağlar.\",\"ar\":\"دقة مثالية! شريحة 40 و 42: في مساقط نيومان (Newman projections) تمثل الهيئات المتقاطعة (staggered) كـ gauche (3.3 Å) و anti (4.4 Å) قيعان استقرار، بينما الهيئات المكسوفة (eclipsed) قمم طاقة. يلائم gauche المسكاريني و anti النيكوتيني.\",\"en\":\"Flawless! Slides 40 & 42: In Newman projections, staggered gauche (3.3 Å) and anti (4.4 Å) rotamers are energy troughs; eclipsed forms are torsional energy peaks. Gauche binds muscarinic GPCRs; anti binds nicotinic channels.\"}},{\"id\":\"opt-4b\",\"text\":{\"tr\":\"Molekülün lipofilitesini: Uzamış form tüm kutupları açığa çıkardığı için katlanmış forma göre 100 kat daha fazla suda çözünür.\",\"ar\":\"محبة الدهون: التشكيل الممتد يكشف المجموعات القطبية فيكون أكثر ذوباناً بالماء بـ 100 مرة مقارنة بالمنطوي.\",\"en\":\"Lipophilicity: The extended form exposes all polar groups, making it 100-fold more water-soluble than folded.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yalnızca çözünürlük yanılgısı: Rotamerler arası mesafe farkının birincil klinik sonucu çözünürlük değil, farmakoforik mesafenin değişmesiyle muskarinik ve nikotinik reseptörler arasındaki alt tip seçiciliğidir.\",\"ar\":\"مغالطة حصر الأثر في الذوبانية: النتيجة السريرية الجوهرية لتباعد المسافة هي الانتقائية للمستقبلات المسكارينية مقابل النيكوتينية.\",\"en\":\"Solubility-only misconception: The paramount pharmacological outcome is pharmacophore distance matching receptor subtypes, not simple bulk solubility.\"}},{\"id\":\"opt-4c\",\"text\":{\"tr\":\"İlacın pKa değerini: Uzamış form kuaterner amonyumun iyonlaşmasını engellerken katlanmış form iyonlaşmayı artırır.\",\"ar\":\"قيمة pKa: التشكيل الممتد يمنع تأين الأمونيوم الرباعي بينما التشكيل المنطوي يزيد من تأينه.\",\"en\":\"Drug pKa: The extended conformation prevents quaternary ammonium ionization while the folded form enhances it.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kuaterner amonyum pKa yanılgısı: Asetilkolinin kuaterner amonyum azotu pH'tan bağımsız olarak kalıcı ve tam yüklüdür (%100 iyonize); konformasyon değişimi yük durumunu değiştirmez.\",\"ar\":\"مغالطة pKa الأمونيوم الرباعي: نيتروجين الأمونيوم الرباعي مشحون دائماً بنسبة 100% بغض النظر عن pH أو التشكيل الفراغي.\",\"en\":\"Quaternary ammonium pKa fallacy: The quaternary ammonium nitrogen is permanently 100% ionized regardless of pH or conformation.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-4a\",\"text\":\"Reseptör alt tip seçiciliğini: 3.3 Å katlanmış form muskarinik cebe, 4.4 Å uzamış form nikotinik cebe tam oturur.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz bilgi! Slayt 40 ve 42: Newman projeksiyonlarında çapraz (staggered) gauche (3.3 Å) ve anti (4.4 Å) rotamerleri enerji çukurlarıdır; çakışık (eclipsed) formlar ise sterik itme tepeleridir. Gauche formu muskarinik, anti formu nikotinik reseptöre seçicilik sağlar.\"},{\"id\":\"opt-4b\",\"text\":\"Molekülün lipofilitesini: Uzamış form tüm kutupları açığa çıkardığı için katlanmış forma göre 100 kat daha fazla suda çözünür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yalnızca çözünürlük yanılgısı: Rotamerler arası mesafe farkının birincil klinik sonucu çözünürlük değil, farmakoforik mesafenin değişmesiyle muskarinik ve nikotinik reseptörler arasındaki alt tip seçiciliğidir.\"},{\"id\":\"opt-4c\",\"text\":\"İlacın pKa değerini: Uzamış form kuaterner amonyumun iyonlaşmasını engellerken katlanmış form iyonlaşmayı artırır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kuaterner amonyum pKa yanılgısı: Asetilkolinin kuaterner amonyum azotu pH'tan bağımsız olarak kalıcı ve tam yüklüdür (%100 iyonize); konformasyon değişimi yük durumunu değiştirmez.\"}],\"revealedOutcome\":{\"tr\":\"Reseptör alt tip seçiciliğini: 3.3 Å katlanmış form muskarinik cebe, 4.4 Å uzamış form nikotinik cebe tam oturur.\",\"ar\":\"الانتقائية الفرعية للمستقبل: المطوي (3.3 Å) يلائم المسكاريني والممتد (4.4 Å) يلائم النيكوتيني.\",\"en\":\"Subtype selectivity: The 3.3 Å gauche form binds muscarinic, while the 4.4 Å anti form binds nicotinic receptors.\"},\"explanation\":{\"tr\":\"Kusursuz bilgi! Slayt 40 ve 42: Newman projeksiyonlarında çapraz (staggered) gauche (3.3 Å) ve anti (4.4 Å) rotamerleri enerji çukurlarıdır; çakışık (eclipsed) formlar ise sterik itme tepeleridir. Gauche formu muskarinik, anti formu nikotinik reseptöre seçicilik sağlar.\",\"ar\":\"دقة مثالية! شريحة 40 و 42: في مساقط نيومان (Newman projections) تمثل الهيئات المتقاطعة (staggered) كـ gauche (3.3 Å) و anti (4.4 Å) قيعان استقرار، بينما الهيئات المكسوفة (eclipsed) قمم طاقة. يلائم gauche المسكاريني و anti النيكوتيني.\",\"en\":\"Flawless! Slides 40 & 42: In Newman projections, staggered gauche (3.3 Å) and anti (4.4 Å) rotamers are energy troughs; eclipsed forms are torsional energy peaks. Gauche binds muscarinic GPCRs; anti binds nicotinic channels.\"}}},{\"id\":\"mc-mod4-les2-step-05\",\"stage\":\"interactive_artifact\",\"stageIndex\":5,\"type\":\"receptor_ligand_matcher\",\"widgetType\":\"ReceptorLigandMatcher\",\"title\":{\"tr\":\"İnteraktif Eşleştirici: Asetilkolin Konformerleri\",\"ar\":\"المطابق التفاعلي: تشكيلات الأسيتيل كولين\",\"en\":\"Interactive Matcher: Acetylcholine Conformer Pharmacophores\"},\"prompt\":{\"tr\":\"Asetilkolinin gauche (3.3 Å) ve anti (4.4 Å) rotamerlerini ile rijit siklopropil analoglarını doğru reseptör cepleriyle eşleştirin.\",\"ar\":\"طابق متشكلي أستيل كولين gauche (3.3 Å) و anti (4.4 Å) ونظائرهما الجاسئة مع الجيوب المستقبلية الصحيحة.\",\"en\":\"Match acetylcholine's gauche (3.3 Å) and anti (4.4 Å) rotamers and rigid cyclopropyl analogs to their selective receptor pockets.\"},\"config\":{\"title\":\"Asetilkolin Konformerleri ve Rijit Analog Eşleştiricisi\",\"prompt\":\"Konformerleri ve rijit analogları doğru reseptör cebiyle eşleştirin.\",\"drugName\":\"Asetilkolin ve Siklopropil Analogları\",\"receptorName\":\"Muskarinik (M1) ve Nikotinik (nAChR) Reseptör Cepleri\",\"pairs\":[{\"id\":\"pair_gauche\",\"drugGroup\":\"Katlanmış Gauche Form (3.3 Å)\",\"correctResidueId\":\"res_muscarinic\",\"bondType\":\"ionic\",\"energyKcalMol\":\"5-10 kcal/mol\",\"explanation\":\"3.3 Å katlanmış mesafe Muskarinik M1 reseptör cebindeki Asp105 ve hidrojen bağı noktalarına tam kenetlenir.\"},{\"id\":\"pair_anti\",\"drugGroup\":\"Uzamış Anti Form (4.4 Å)\",\"correctResidueId\":\"res_nicotinic\",\"bondType\":\"pi_pi\",\"energyKcalMol\":\"2-7 kcal/mol\",\"explanation\":\"4.4 Å uzamış mesafe Nikotinik nAChR cebindeki Trp149 katyon-pi ve Tyr93 dipol cebine kusursuz oturur.\"},{\"id\":\"pair_cis_cyclo\",\"drugGroup\":\"(+)-Cis-Asetilsiklopropil\",\"correctResidueId\":\"res_muscarinic\",\"bondType\":\"ionic\",\"energyKcalMol\":\"5-10 kcal/mol\",\"explanation\":\"Cis-siklopropil halkası gauche geometriyi rijit olarak dondurur; sadece muskarinik reseptörleri uyarır (Slayt 42).\"},{\"id\":\"pair_trans_cyclo\",\"drugGroup\":\"(+)-Trans-Asetilsiklopropil\",\"correctResidueId\":\"res_nicotinic\",\"bondType\":\"pi_pi\",\"energyKcalMol\":\"2-7 kcal/mol\",\"explanation\":\"Trans-siklopropil halkası anti geometriyi rijit olarak dondurur; sadece nikotinik reseptörleri uyarır (Slayt 42).\"}],\"residues\":[{\"id\":\"res_muscarinic\",\"residueName\":\"Muskarinik M1 Reseptör Cebi (3.3 Å)\",\"description\":\"Katlanmış 3.3 Å farmakofor arayan dar, derin GPCR aktif cebi.\"},{\"id\":\"res_nicotinic\",\"residueName\":\"Nikotinik nAChR Cebi (4.4 Å)\",\"description\":\"Uzamış 4.4 Å farmakofor arayan pentamerik iyon kanalı cebi.\"},{\"id\":\"res_steric_clash\",\"residueName\":\"Sterik İtme / Uyumsuz Cep\",\"description\":\"Yanlış geometrideki rotamerleri dışarı iten sterik engel bölgesi.\"}],\"source\":{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":42}},\"technicalTerms\":[{\"term\":\"rijit analog\",\"arContext\":\"النظير الجاسئ\"}],\"hints\":[{\"tr\":\"Gauche ve cis-analogları 3.3 Å kısa mesafeyi temsil eder.\",\"ar\":\"يمثل تشكيل gauche والنظير cis المسافة القصيرة 3.3 أنغستروم.\",\"en\":\"Gauche rotamers and cis-analogs represent the compact 3.3 Å distance.\"},{\"tr\":\"Anti ve trans-analogları 4.4 Å uzun mesafeyi temsil eder.\",\"ar\":\"يمثل تشكيل anti والنظير trans المسافة الطويلة 4.4 أنغستروم.\",\"en\":\"Anti rotamers and trans-analogs represent the extended 4.4 Å distance.\"},{\"tr\":\"Kısa mesafe muskarinik cebe, uzun mesafe nikotinik cebe kenetlenir.\",\"ar\":\"المسافة القصيرة تلائم المسكاريني، والمسافة الطويلة تلائم النيكوتيني.\",\"en\":\"Compact distance docks into muscarinic; extended distance docks into nicotinic receptors.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":42}],\"widget\":{\"type\":\"ReceptorLigandMatcher\",\"config\":{\"title\":\"Asetilkolin Konformerleri ve Rijit Analog Eşleştiricisi\",\"prompt\":\"Konformerleri ve rijit analogları doğru reseptör cebiyle eşleştirin.\",\"drugName\":\"Asetilkolin ve Siklopropil Analogları\",\"receptorName\":\"Muskarinik (M1) ve Nikotinik (nAChR) Reseptör Cepleri\",\"pairs\":[{\"id\":\"pair_gauche\",\"drugGroup\":\"Katlanmış Gauche Form (3.3 Å)\",\"correctResidueId\":\"res_muscarinic\",\"bondType\":\"ionic\",\"energyKcalMol\":\"5-10 kcal/mol\",\"explanation\":\"3.3 Å katlanmış mesafe Muskarinik M1 reseptör cebindeki Asp105 ve hidrojen bağı noktalarına tam kenetlenir.\"},{\"id\":\"pair_anti\",\"drugGroup\":\"Uzamış Anti Form (4.4 Å)\",\"correctResidueId\":\"res_nicotinic\",\"bondType\":\"pi_pi\",\"energyKcalMol\":\"2-7 kcal/mol\",\"explanation\":\"4.4 Å uzamış mesafe Nikotinik nAChR cebindeki Trp149 katyon-pi ve Tyr93 dipol cebine kusursuz oturur.\"},{\"id\":\"pair_cis_cyclo\",\"drugGroup\":\"(+)-Cis-Asetilsiklopropil\",\"correctResidueId\":\"res_muscarinic\",\"bondType\":\"ionic\",\"energyKcalMol\":\"5-10 kcal/mol\",\"explanation\":\"Cis-siklopropil halkası gauche geometriyi rijit olarak dondurur; sadece muskarinik reseptörleri uyarır (Slayt 42).\"},{\"id\":\"pair_trans_cyclo\",\"drugGroup\":\"(+)-Trans-Asetilsiklopropil\",\"correctResidueId\":\"res_nicotinic\",\"bondType\":\"pi_pi\",\"energyKcalMol\":\"2-7 kcal/mol\",\"explanation\":\"Trans-siklopropil halkası anti geometriyi rijit olarak dondurur; sadece nikotinik reseptörleri uyarır (Slayt 42).\"}],\"residues\":[{\"id\":\"res_muscarinic\",\"residueName\":\"Muskarinik M1 Reseptör Cebi (3.3 Å)\",\"description\":\"Katlanmış 3.3 Å farmakofor arayan dar, derin GPCR aktif cebi.\"},{\"id\":\"res_nicotinic\",\"residueName\":\"Nikotinik nAChR Cebi (4.4 Å)\",\"description\":\"Uzamış 4.4 Å farmakofor arayan pentamerik iyon kanalı cebi.\"},{\"id\":\"res_steric_clash\",\"residueName\":\"Sterik İtme / Uyumsuz Cep\",\"description\":\"Yanlış geometrideki rotamerleri dışarı iten sterik engel bölgesi.\"}],\"source\":{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":42}}}},{\"id\":\"mc-mod4-les2-step-06\",\"stage\":\"guided_discovery\",\"stageIndex\":6,\"type\":\"guided_discovery\",\"title\":{\"tr\":\"Siklopropan Halkasıyla Dondurma Deneyi\",\"ar\":\"تجربة التجميد بحلقة البروبان الحلقي\",\"en\":\"The Cyclopropane Ring Freezing Experiment\"},\"prompt\":{\"tr\":\"Bilim insanları asetilkolin zincirine siklopropan halkası ekleyerek dönmeyi durdurdu. (+)-Trans-analog sadece nikotinik, (+)-cis-analog sadece muskarinik etki gösterdi. Bu neyi ispatlar?\",\"ar\":\"جمد العلماء دوران الأستيل كولين بإقحام حلقة بروبان حلقي. نشط متماكب trans المستقبل النيكوتيني فقط، ونشط cis المسكاريني فقط. ما الذي يثبته هذا؟\",\"en\":\"Chemists inserted a cyclopropane ring to freeze acetylcholine's rotation. The (+)-trans analog activated only nicotinic, while (+)-cis activated only muscarinic receptors. What does this definitively prove?\"},\"technicalTerms\":[{\"term\":\"konformasyonel kısıtlama\",\"arContext\":\"التقييد التشكلي\"}],\"hints\":[{\"tr\":\"Esnek asetilkolin her iki reseptörü uyarırken, dondurulmuş halkalı moleküller sadece birini uyardı.\",\"ar\":\"بينما نشط أستيل كولين المرن كلا المستقبلين، نشطت النظائر المجمدة مستقبلاً واحداً فقط.\",\"en\":\"Flexible acetylcholine hit both targets, but rigid locked analogs activated only one target each.\"},{\"tr\":\"Bu deney, her reseptör alt tipinin liganddan farklı bir geometrik şekil talep ettiğinin kanıtıdır.\",\"ar\":\"يثبت هذا أن كل نوع فرعي من المستقبلات يشترط شكلاً هندسياً مستقلاً للارتباط.\",\"en\":\"This proves each receptor subtype requires an unequivocal spatial pharmacophoric geometry.\"},{\"tr\":\"Biyoaktif konformasyon hipotezini doğrular: Muskarinik reseptör gauche, nikotinik reseptör anti şekli ister.\",\"ar\":\"يؤكد فرضية التشكيل الحيوي: المسكاريني يطلب شكل gauche، والنيكوتيني يطلب anti.\",\"en\":\"It validates bioactive conformation theory: Muscarinic requires gauche; nicotinic requires anti.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":42}],\"conceptCheck\":{\"options\":[{\"id\":\"opt-6a\",\"text\":{\"tr\":\"Biyoaktif konformasyon teorisini: Her reseptör alt tipi esnek molekülün kendine uyan tek bir uzaysal formunu seçerek bağlar.\",\"ar\":\"نظرية التشكيل الحيوي الفعال: كل نوع فرعي من المستقبلات يختار وينشط بتشكيل هندسي محدد وحيد.\",\"en\":\"Bioactive conformation theory: Each receptor subtype selects and binds a single distinct spatial geometry.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika çıkarım! Slayt 42'de belirtildiği gibi rijit siklopropil analogları, asetilkolinin iki farklı reseptörde iki farklı biyoaktif konformasyon sergilediğinin kesin kimyasal kanıtıdır.\",\"ar\":\"استنتاج رائع! تثبت نظائر البروبان الحلقي الجاسئة أن أستيل كولين يمتلك تشكيلين حيويين متمايزين لكل مستقبل.\",\"en\":\"Outstanding deduction! As shown on Slide 42, rigid cyclopropyl analogs provide definitive chemical proof of subtype-specific bioactive conformations.\"}},{\"id\":\"opt-6b\",\"text\":{\"tr\":\"Siklopropil halkasının elektron çekici etkisiyle ester grubunun reaktivitesini artırıp asetilkolinesteraz enzimini inhibe ettiğini.\",\"ar\":\"أن حلقة السيكلوبروبيل تزيد تفاعلية الإستر وتسحب الإلكترونات مما يثبط إنزيم أستيل كولين إستراز بشكل مباشر.\",\"en\":\"The cyclopropyl ring withdraws electrons to enhance ester reactivity and directly inhibit acetylcholinesterase.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Enzim inhibisyonu yanılgısı: Siklopropil halkası asetilkolinesteraz inhibitörü olarak değil; N-O atomlar arası mesafeyi (3.3 Å vs 4.4 Å) kovalent bir halka ile dondurarak reseptör alt tip seçiciliğini kanıtlamak için tasarlanmıştır.\",\"ar\":\"مغالطة التثبيط الإنزيمي: حلقة السيكلوبروبيل صممت لتجميد المسافة الفراغية وإثبات انتقائية المستقبل وليس لتثبيط الإنزيم.\",\"en\":\"Enzyme inhibition misconception: The cyclopropyl ring was designed to lock interatomic distance and demonstrate receptor subtype selectivity, not inhibit AChE.\"}},{\"id\":\"opt-6c\",\"text\":{\"tr\":\"Trans-izomerin iki kiral merkeze sahip olmasının ilacın yalnızca kan plazmasındaki albümine bağlanmasını sağladığını.\",\"ar\":\"أن امتلاك المماكب trans لمركزين كيراليين يجعله يرتبط حصرياً بألبومين البلازما بدلاً من المستقبلات.\",\"en\":\"The trans isomer having two chiral centers causes the drug to bind exclusively to serum albumin rather than receptors.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Plazma proteini yanılgısı: Kiral siklopropil analogları albümine bağlanma amacıyla değil, muskarinik ve nikotinik reseptörlerin kiral ve boyutsal cep geometrisini haritalamak için geliştirilmiştir.\",\"ar\":\"مغالطة بروتينات البلازما: طورت مشتقات السيكلوبروبيل الكيرالية لرسم خريطة المستقبلات المسكارينية والنيكوتينية وليس للارتباط بالألبومين.\",\"en\":\"Plasma protein fallacy: Chiral cyclopropyl analogs were synthesized to probe chiral receptor pharmacophore geometry, not target albumin.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-6a\",\"text\":\"Biyoaktif konformasyon teorisini: Her reseptör alt tipi esnek molekülün kendine uyan tek bir uzaysal formunu seçerek bağlar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika çıkarım! Slayt 42'de belirtildiği gibi rijit siklopropil analogları, asetilkolinin iki farklı reseptörde iki farklı biyoaktif konformasyon sergilediğinin kesin kimyasal kanıtıdır.\"},{\"id\":\"opt-6b\",\"text\":\"Siklopropil halkasının elektron çekici etkisiyle ester grubunun reaktivitesini artırıp asetilkolinesteraz enzimini inhibe ettiğini.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Enzim inhibisyonu yanılgısı: Siklopropil halkası asetilkolinesteraz inhibitörü olarak değil; N-O atomlar arası mesafeyi (3.3 Å vs 4.4 Å) kovalent bir halka ile dondurarak reseptör alt tip seçiciliğini kanıtlamak için tasarlanmıştır.\"},{\"id\":\"opt-6c\",\"text\":\"Trans-izomerin iki kiral merkeze sahip olmasının ilacın yalnızca kan plazmasındaki albümine bağlanmasını sağladığını.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Plazma proteini yanılgısı: Kiral siklopropil analogları albümine bağlanma amacıyla değil, muskarinik ve nikotinik reseptörlerin kiral ve boyutsal cep geometrisini haritalamak için geliştirilmiştir.\"}],\"revealedOutcome\":{\"tr\":\"Biyoaktif konformasyon teorisini: Her reseptör alt tipi esnek molekülün kendine uyan tek bir uzaysal formunu seçerek bağlar.\",\"ar\":\"نظرية التشكيل الحيوي الفعال: كل نوع فرعي من المستقبلات يختار وينشط بتشكيل هندسي محدد وحيد.\",\"en\":\"Bioactive conformation theory: Each receptor subtype selects and binds a single distinct spatial geometry.\"},\"explanation\":{\"tr\":\"Harika çıkarım! Slayt 42'de belirtildiği gibi rijit siklopropil analogları, asetilkolinin iki farklı reseptörde iki farklı biyoaktif konformasyon sergilediğinin kesin kimyasal kanıtıdır.\",\"ar\":\"استنتاج رائع! تثبت نظائر البروبان الحلقي الجاسئة أن أستيل كولين يمتلك تشكيلين حيويين متمايزين لكل مستقبل.\",\"en\":\"Outstanding deduction! As shown on Slide 42, rigid cyclopropyl analogs provide definitive chemical proof of subtype-specific bioactive conformations.\"}}},{\"id\":\"mc-mod4-les2-step-07\",\"stage\":\"formal_explanation\",\"stageIndex\":7,\"type\":\"formal_explanation\",\"title\":{\"tr\":\"Histamin H1 ve H2 Konformer Ayrımı\",\"ar\":\"التمييز التشكلي للهستامين بين H1 و H2\",\"en\":\"Histamine Dilemma: H1 Bronchoconstriction vs H2 Acid\"},\"prompt\":{\"tr\":\"Histaminin uzamış transoid A konformeri (4.55 Å) H1 reseptörüne, katlanmış B konformeri (3.60 Å) H2 reseptörüne bağlanır. Bu rijit ayrım neden hayati bir klinik kazançtır?\",\"ar\":\"يرتبط تشكيل هستامين الممتد A (4.55 Å) بمستقبل H1، والمطوي B (3.60 Å) بمستقبل H2. لماذا يعد التقييد التشكلي مكسباً سريرياً حاسماً؟\",\"en\":\"Histamine's extended conformer A (4.55 Å) binds H1 receptors, while folded conformer B (3.60 Å) binds H2. Why is rigid analog design clinically vital?\"},\"technicalTerms\":[{\"term\":\"H1 reseptörü\",\"arContext\":\"مستقبل الهستامين 1\"},{\"term\":\"H2 reseptörü\",\"arContext\":\"مستقبل الهستامين 2\"}],\"hints\":[{\"tr\":\"H1 uyarısı alerji ve bronkospazm yaparken, H2 uyarısı mide asidi salgılar.\",\"ar\":\"تنشيط H1 يسبب الحساسية وتضيق القصبات، وتنشيط H2 يفرز حمض المعدة.\",\"en\":\"H1 activation mediates allergies and bronchoconstriction; H2 activation stimulates gastric acid.\"},{\"tr\":\"Esnek histamin her iki etkiyi birden tetikler; rijit bir molekül ise sadece birini hedefler.\",\"ar\":\"الهستامين المرن يطلق كلا الأثرين معاً، بينما يستهدف الجزيء الجاسئ أحدهما حصراً.\",\"en\":\"Flexible histamine triggers both pathways, whereas a rigidified analog selectively addresses only one.\"},{\"tr\":\"3.60 Å katlanmış mesafede dondurulan rijit ligandlar alerjik yan etki yapmadan sadece mide asidini bloke eder.\",\"ar\":\"تجميد المسافة عند 3.60 Å يثبط حمض المعدة حصراً دون تداخل مع مستقبلات الحساسية.\",\"en\":\"Freezing the pharmacophore at 3.60 Å selectively blocks gastric acid without causing allergic cross-reactivity.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":43}],\"conceptCheck\":{\"options\":[{\"id\":\"opt-7a\",\"text\":{\"tr\":\"Esnek histamin iki reseptörü de uyarırken, mesafesi kilitlenen rijit analoglar alerjik yan etki yapmadan sadece mide asidini selektif bloke eder.\",\"ar\":\"بينما ينشط الهستامين المرن المستقبلين، فإن تثبيت المسافة يسمح بحجب حمض المعدة دون آثار حساسية.\",\"en\":\"While flexible histamine triggers both, rigidified analogs lock the exact distance to block gastric acid without allergic cross-reactivity.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Tebrikler! Slayt 43'e göre: Histamin A konformeri (4.55 Å) H1 bronkokonstriksiyonunu, B konformeri (3.60 Å) H2 mide asidini yönetir. Simetidin gibi H2 blokerleri bu konformasyonel tasarımla doğmuştur.\",\"ar\":\"تهانينا! شريحة 43: التشكيل A بمسافة 4.55 Å يخص H1، والتشكيل B بمسافة 3.60 Å يخص H2. أدوية قرحة المعدة (H2 blockers) صممت بناء على هذا المبدأ.\",\"en\":\"Congratulations! Slide 43 documents: Conformer A (4.55 Å) governs H1 allergic response; Conformer B (3.60 Å) governs H2 gastric acid. Blockbusters like cimetidine were engineered using this exact rigid constraint.\"}},{\"id\":\"opt-7b\",\"text\":{\"tr\":\"H1 ve H2 reseptörlerinin aslında tek bir protein olduğunu ve ayrımın önemsiz olduğunu göstermek için.\",\"ar\":\"لإثبات أن مستقبلي H1 و H2 بروتين واحد متطابق ولا فائدة من التمييز بينهما.\",\"en\":\"To demonstrate that H1 and H2 receptors are an identical single protein with meaningless differences.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Monolitik reseptör yanılgısı: H1 (Gq kenetli) ve H2 (Gs kenetli) tamamen farklı genler ve proteinlerdir.\",\"ar\":\"خطأ تماثل المستقبلات: مستقبلا H1 و H2 مختلفان تماماً جينياً ووظيفياً.\",\"en\":\"Identical receptor misconception: H1 (Gq-coupled) and H2 (Gs-coupled) are distinct GPCR genes with divergent signaling cascades.\"}},{\"id\":\"opt-7c\",\"text\":{\"tr\":\"Histamin H1 ve H2 reseptörlerinin aynı farmakofor mesafesini talep ettiğini, dolayısıyla rijit analogların seçicilik sağlayamayacağını.\",\"ar\":\"أن مستقبلي H1 و H2 يتطلبان نفس المسافة الفارماكوفورية تماماً وبالتالي لا يمكن تحقيق أي انتقائية بالتجسئة.\",\"en\":\"Histamine H1 and H2 receptors require identical pharmacophoric distances, making conformational restriction useless for selectivity.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Özdeş cep yanılgısı: Slayt 43: H1 reseptörü transoid A konformasyonunu (4.55 Å), H2 reseptörü ise gauche B konformasyonunu (3.60 Å) seçer; aradaki 0.95 Å'luk fark selektif antihistaminik ve antiülser ilaçların temelidir.\",\"ar\":\"مغالطة الجيب المتطابق: شريحة 43: مستقبل H1 يختار transoid A (4.55 Å) ومستقبل H2 يختار gauche B (3.60 Å)؛ فارق 0.95 Å هو أساس الأدوية النوعية.\",\"en\":\"Identical pocket misconception: Slide 43: H1 prefers transoid A (4.55 Å) while H2 prefers gauche B (3.60 Å); this 0.95 Å difference governs selectivity.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-7a\",\"text\":\"Esnek histamin iki reseptörü de uyarırken, mesafesi kilitlenen rijit analoglar alerjik yan etki yapmadan sadece mide asidini selektif bloke eder.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Tebrikler! Slayt 43'e göre: Histamin A konformeri (4.55 Å) H1 bronkokonstriksiyonunu, B konformeri (3.60 Å) H2 mide asidini yönetir. Simetidin gibi H2 blokerleri bu konformasyonel tasarımla doğmuştur.\"},{\"id\":\"opt-7b\",\"text\":\"H1 ve H2 reseptörlerinin aslında tek bir protein olduğunu ve ayrımın önemsiz olduğunu göstermek için.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Monolitik reseptör yanılgısı: H1 (Gq kenetli) ve H2 (Gs kenetli) tamamen farklı genler ve proteinlerdir.\"},{\"id\":\"opt-7c\",\"text\":\"Histamin H1 ve H2 reseptörlerinin aynı farmakofor mesafesini talep ettiğini, dolayısıyla rijit analogların seçicilik sağlayamayacağını.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Özdeş cep yanılgısı: Slayt 43: H1 reseptörü transoid A konformasyonunu (4.55 Å), H2 reseptörü ise gauche B konformasyonunu (3.60 Å) seçer; aradaki 0.95 Å'luk fark selektif antihistaminik ve antiülser ilaçların temelidir.\"}],\"revealedOutcome\":{\"tr\":\"Esnek histamin iki reseptörü de uyarırken, mesafesi kilitlenen rijit analoglar alerjik yan etki yapmadan sadece mide asidini selektif bloke eder.\",\"ar\":\"بينما ينشط الهستامين المرن المستقبلين، فإن تثبيت المسافة يسمح بحجب حمض المعدة دون آثار حساسية.\",\"en\":\"While flexible histamine triggers both, rigidified analogs lock the exact distance to block gastric acid without allergic cross-reactivity.\"},\"explanation\":{\"tr\":\"Tebrikler! Slayt 43'e göre: Histamin A konformeri (4.55 Å) H1 bronkokonstriksiyonunu, B konformeri (3.60 Å) H2 mide asidini yönetir. Simetidin gibi H2 blokerleri bu konformasyonel tasarımla doğmuştur.\",\"ar\":\"تهانينا! شريحة 43: التشكيل A بمسافة 4.55 Å يخص H1، والتشكيل B بمسافة 3.60 Å يخص H2. أدوية قرحة المعدة (H2 blockers) صممت بناء على هذا المبدأ.\",\"en\":\"Congratulations! Slide 43 documents: Conformer A (4.55 Å) governs H1 allergic response; Conformer B (3.60 Å) governs H2 gastric acid. Blockbusters like cimetidine were engineered using this exact rigid constraint.\"}}},{\"id\":\"mc-mod4-les2-step-08\",\"stage\":\"concept_check\",\"stageIndex\":8,\"type\":\"concept_check\",\"title\":{\"tr\":\"Nöroleptik Bütirofenonlarda Sandalye Konformasyonu\",\"ar\":\"تشكيل الكرسي في البوتيروفينونات المضادة للذهان\",\"en\":\"Butyrophenone Neuroleptics: Equatorial vs Axial\"},\"prompt\":{\"tr\":\"Haloperidol benzeri bütirofenon nöroleptiklerde 4-hidroksipiperidin halkası sandalye konformasyonundadır. Aromatik sübstitüentin ekvatoryal veya aksiyal yönelimi aktiviteyi nasıl değiştirir?\",\"ar\":\"في مضادات الذهان مثل هالوبيريدول تتبنى حلقة بيبيريدين تشكيل الكرسي. كيف يغير التوجه الاستوائي أو المحوري الفعالية؟\",\"en\":\"In butyrophenone neuroleptics, the piperidine ring adopts a chair conformation. How does the equatorial versus axial orientation of the 4-aryl group impact antipsychotic potency?\"},\"technicalTerms\":[{\"term\":\"sandalye konformasyonu\",\"arContext\":\"تشكيل الكرسي\"},{\"term\":\"ekvatoryal konum\",\"arContext\":\"الموقع الاستوائي\"}],\"hints\":[{\"tr\":\"Sikloheksan/piperidin sandalye konformasyonunda aksiyal gruplar 1,3-diaxial itmeye maruz kalır.\",\"ar\":\"في تشكيل الكرسي، تتعرض المجموعات المحورية (axial) لتنافر sterik مع الهيدروجينات المجاورة.\",\"en\":\"In chair conformations, axial substituents experience severe 1,3-diaxial steric clash.\"},{\"tr\":\"Ekvatoryal grup halkanın çevresine doğru uzanarak reseptör düzlemine engelsizce yanaşır.\",\"ar\":\"تمتد المجموعة الاستوائية (equatorial) نحو المحيط الخارجي فتقترب من جيب المستقبل بلا عائق.\",\"en\":\"Equatorial substituents project outward into the equatorial plane, docking unobstructed into receptor sub-pockets.\"},{\"tr\":\"Ekvatoryal aril grubu dopamin D2 cebine tam oturur; aksiyal bükülme afiniteyi şiddetle düşürür.\",\"ar\":\"المجموعة الاستوائية تلائم جيب دوبامين D2 بدقة، بينما يسقط التوجه المحوري الألفة بشدة.\",\"en\":\"The equatorial aryl conformer binds dopamine D2 pockets with high affinity; axial orientation destroys binding.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":41}],\"conceptCheck\":{\"options\":[{\"id\":\"opt-8a\",\"text\":{\"tr\":\"Ekvatoryal konumdaki aril grubu dopamin D2 cebine kusursuz oturur; aksiyal bükülme sterik itmeyle afiniteyi 100 kat düşürür.\",\"ar\":\"المجموعة الاستوائية تلائم جيب مستقبل دوبامين D2 تماماً؛ بينما يقلل التوجه المحوري الألفة بمقدار 100 ضعف بسبب الإعاقة الفراغية.\",\"en\":\"The equatorial 4-aryl conformer docks perfectly into dopamine D2 pockets; axial orientation causes steric clash, dropping affinity 100-fold.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kesinlikle doğru! Slayt 41'e göre: 4-(4-hidroksipiperidino)bütirofenonlarda piperidin halkasındaki sübstitüentin ekvatoryal/aksiyal konformasyonu nöroleptik etkinin varlığını belirler.\",\"ar\":\"صحيح بدقة! شريحة 41: يحدد التشكيل الاستوائي/المحوري في حلقة البيبيريدين قوة الفعالية المضادة للذهان.\",\"en\":\"Precisely correct! Slide 41 documents that equatorial vs axial orientation on the piperidine chair dictates neuroleptic potency at dopamine D2 receptors.\"}},{\"id\":\"opt-8b\",\"text\":{\"tr\":\"Aksiyal aril grubu halkanın merkezine yöneldiği için reseptörle hidrofobik teması artırır ve daima ekvatoryal forma göre daha yüksek afinite gösterir.\",\"ar\":\"المجموعة العطرية المحورية تتجه نحو مركز الحلقة فتزيد التلامس الكاره للماء وتعطي دائماً ألفة أعلى من الاستوائية.\",\"en\":\"The axial aryl group points toward the ring core to maximize hydrophobic contact, consistently conferring higher affinity than equatorial.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"1,3-diaksiyal itme yanılgısı: Aksiyal konumdaki hacimli aril grupları halkanın diğer aksiyal hidrojenleriyle şiddetli sterik çakışmaya (1,3-diaxial strain) girer; bu nedenle molekül ekvatoryal konformasyonu tercih eder.\",\"ar\":\"مغالطة الإجهاد ثنائي المحور: المجموعات الحجمية في الموقع المحوري تعاني من تنافر فراغي شديد (1,3-diaxial strain)؛ لذا يفضل الجزيء التشكيل الاستوائي.\",\"en\":\"1,3-diaxial misconception: Bulky axial aryls suffer severe steric strain with syn-axial hydrogens, making equatorial orientation energetically favored.\"}},{\"id\":\"opt-8c\",\"text\":{\"tr\":\"Piperidin halkası fizyolojik sıcaklıkta o kadar hızlı ring-flip yapar ki ekvatoryal ve aksiyal konformerler farmakolojik olarak ayırt edilemez.\",\"ar\":\"حلقة البيبيريدين تقلب بسرعة فائقة في الحرارة الفسيولوجية بحيث يستحيل تفريق التشكيل الاستوائي عن المحوري دوائياً.\",\"en\":\"The piperidine ring undergoes such rapid chair flipping at body temperature that equatorial and axial conformers are pharmacologically indistinguishable.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Ayırt edilemezlik yanılgısı: Halka dönüşümü hızlı olsa da, reseptör cebi iki konformerden yalnızca birini (biyoaktif formu) seçerek bağlar; bu seçim afiniteler arasında devasa farklar yaratır.\",\"ar\":\"مغالطة التكافؤ الدوائي: رغم سرعة الانقلاب، ينتقي جيب المستقبل تشكيلاً واحداً فقط للارتباط؛ مما يولد فارقاً هائلاً في الألفة.\",\"en\":\"Indistinguishability fallacy: Despite rapid interconversion in solution, the rigid receptor pocket binds only one bioactive conformer, yielding vast affinity differences.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-8a\",\"text\":\"Ekvatoryal konumdaki aril grubu dopamin D2 cebine kusursuz oturur; aksiyal bükülme sterik itmeyle afiniteyi 100 kat düşürür.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kesinlikle doğru! Slayt 41'e göre: 4-(4-hidroksipiperidino)bütirofenonlarda piperidin halkasındaki sübstitüentin ekvatoryal/aksiyal konformasyonu nöroleptik etkinin varlığını belirler.\"},{\"id\":\"opt-8b\",\"text\":\"Aksiyal aril grubu halkanın merkezine yöneldiği için reseptörle hidrofobik teması artırır ve daima ekvatoryal forma göre daha yüksek afinite gösterir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"1,3-diaksiyal itme yanılgısı: Aksiyal konumdaki hacimli aril grupları halkanın diğer aksiyal hidrojenleriyle şiddetli sterik çakışmaya (1,3-diaxial strain) girer; bu nedenle molekül ekvatoryal konformasyonu tercih eder.\"},{\"id\":\"opt-8c\",\"text\":\"Piperidin halkası fizyolojik sıcaklıkta o kadar hızlı ring-flip yapar ki ekvatoryal ve aksiyal konformerler farmakolojik olarak ayırt edilemez.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Ayırt edilemezlik yanılgısı: Halka dönüşümü hızlı olsa da, reseptör cebi iki konformerden yalnızca birini (biyoaktif formu) seçerek bağlar; bu seçim afiniteler arasında devasa farklar yaratır.\"}],\"revealedOutcome\":{\"tr\":\"Ekvatoryal konumdaki aril grubu dopamin D2 cebine kusursuz oturur; aksiyal bükülme sterik itmeyle afiniteyi 100 kat düşürür.\",\"ar\":\"المجموعة الاستوائية تلائم جيب مستقبل دوبامين D2 تماماً؛ بينما يقلل التوجه المحوري الألفة بمقدار 100 ضعف بسبب الإعاقة الفراغية.\",\"en\":\"The equatorial 4-aryl conformer docks perfectly into dopamine D2 pockets; axial orientation causes steric clash, dropping affinity 100-fold.\"},\"explanation\":{\"tr\":\"Kesinlikle doğru! Slayt 41'e göre: 4-(4-hidroksipiperidino)bütirofenonlarda piperidin halkasındaki sübstitüentin ekvatoryal/aksiyal konformasyonu nöroleptik etkinin varlığını belirler.\",\"ar\":\"صحيح بدقة! شريحة 41: يحدد التشكيل الاستوائي/المحوري في حلقة البيبيريدين قوة الفعالية المضادة للذهان.\",\"en\":\"Precisely correct! Slide 41 documents that equatorial vs axial orientation on the piperidine chair dictates neuroleptic potency at dopamine D2 receptors.\"}}},{\"id\":\"mc-mod4-les2-step-09\",\"stage\":\"application\",\"stageIndex\":9,\"type\":\"clinical_vignette\",\"title\":{\"tr\":\"Entropik Tasarım: Rotasyonel Serbestlik Tasarrufu\",\"ar\":\"التصميم الإنتروبي: توفير حرية الدوران\",\"en\":\"Quantitative Thermodynamics: Rotatable Bond Savings\"},\"prompt\":{\"tr\":\"Bir ilaç tasarımcısı, 5 adet serbest dönebilen tekli bağı bir sikloheksil halkası içine kilitleyerek rijit hale getirmiştir. Bağlanma serbest enerjisinde (ΔG) beklenen termodinamik kazanç nedir?\",\"ar\":\"قام مصمم أدوية بتجميد 5 روابط أحادية دوارة داخل حلقة سداسية صلبة. ما هو الكسب الديناميكي الحراري المتوقع في طاقة الارتباط الحرة (ΔG)؟\",\"en\":\"A medicinal chemist rigidifies a flexible lead by locking 5 rotatable bonds into a fused cyclohexyl scaffold. What is the expected thermodynamic gain in binding free energy (ΔG)?\"},\"technicalTerms\":[{\"term\":\"bağlanma serbest enerjisi (ΔG)\",\"arContext\":\"طاقة الارتباط الحرة\"}],\"hints\":[{\"tr\":\"Her serbest dönebilen bağ için tasarruf edilen ortalama entropik enerjiyi hatırlayın.\",\"ar\":\"تذكر متوسط الطاقة الإنتروبية الموفرة لكل رابطة دوارة متجمدة.\",\"en\":\"Recall the average entropic energy saved per frozen rotatable bond (~2.5-4.0 kJ/mol).\"},{\"tr\":\"5 bağ için toplam kazanç: 5 × (2.5 ila 4.0 kJ/mol) = 12.5 ila 20.0 kJ/mol.\",\"ar\":\"الحصيلة لـ 5 روابط: 5 × (2.5 إلى 4.0) = 12.5 إلى 20 كيلوجول/مول.\",\"en\":\"Multiply 5 bonds by ~3 kJ/mol: ~15 kJ/mol favorable shift in ΔG.\"},{\"tr\":\"15 kJ/mol serbest enerji kazancı, Kd afinitesinde 100 ila 1000 kat artışa karşılık gelir.\",\"ar\":\"كسب 15 كيلوجول/مول يرفع ألفة الارتباط بمقدار 100 إلى 1000 ضعف.\",\"en\":\"A 15 kJ/mol gain in ΔG translates to a 100- to 1000-fold increase in binding affinity (Kd drops).\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":41}],\"conceptCheck\":{\"options\":[{\"id\":\"opt-9a\",\"text\":{\"tr\":\"Her donan bağ için ~2.5-4.0 kJ/mol entropi tasarrufu sağlanır; toplamda ~15 kJ/mol kazanç afiniteyi (Kd) 100-1000 kat artırır.\",\"ar\":\"توفر كل رابطة مجمدة ~2.5-4.0 كيلوجول/مول؛ وحصيلة ~15 كيلوجول/مول ترفع الألفة بمقدار 100 إلى 1000 ضعف.\",\"en\":\"Each frozen bond saves ~2.5-4.0 kJ/mol in entropy penalty; ~15 kJ/mol total gain boosts affinity (drops Kd) 100- to 1000-fold.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Olağanüstü biyofiziksel kavrayış! ΔG = ΔH - TΔS denkleminde bağların önceden kilitlenmesi TΔS kaybını sıfırlayarak bağlanmayı kat kat güçlü kılar.\",\"ar\":\"فهم فيزيائي حيوي استثنائي! تثبيت الروابط مسبقاً يلغي ضريبة الإنتروبيا التشكيلية فيرفع الألفة بشكل أسي.\",\"en\":\"Extraordinary biophysical deduction! In ΔG = ΔH - TΔS, pre-organizing the scaffold eliminates conformational entropy loss, driving exponential affinity increases.\"}},{\"id\":\"opt-9b\",\"text\":{\"tr\":\"Serbest bağları dondurmak molekül ağırlığını azalttığı için difüzyon katsayısını 10 kat artırır ama bağlanma afinitesini hiç etkilemez.\",\"ar\":\"تجميد الروابط ينقص الوزن الجزيئي فيزيد سرعة الانتشار 10 أضعاف لكنه لا يغير ألفة الارتباط إطلاقاً.\",\"en\":\"Freezing rotatable bonds reduces molecular weight, accelerating diffusion 10-fold without altering binding affinity.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Molekül ağırlığı yanılgısı: Rotasyonel bağları halkaya kilitlemek molekül ağırlığını neredeyse değiştirmez; afinite artışının temel nedeni termodinamik konformasyonel entropi (-TΔS) cezasının silinmesidir.\",\"ar\":\"مغالطة الوزن الجزيئي: تقييد الروابط لا يغير الوزن الجزيئي؛ زيادة الألفة سببها إلغاء ضريبة الإنتروبيا التشكيلية (-TΔS).\",\"en\":\"Molecular weight fallacy: Rigidification barely alters molecular weight; affinity spikes because the conformational entropy penalty (-TΔS) is eliminated.\"}},{\"id\":\"opt-9c\",\"text\":{\"tr\":\"Bağların dondurulması entalpiyi (ΔH) 100 kJ/mol yükselterek ilacın reseptörle kovalent bağ kurmasını sağlar.\",\"ar\":\"تجميد الروابط يرفع الإنثالبيا (ΔH) بمقدار 100 kJ/mol مما يدفع الدواء لتشكيل روابط تساهمية مع المستقبل.\",\"en\":\"Freezing bonds drives enthalpy (ΔH) up by 100 kJ/mol, enabling the drug to form irreversible covalent bonds with the receptor.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kovalent bağlanma yanılgısı: İskeleti rijit hale getirmek molekülü kovalent yapmaz; non-kovalan bağlanmada entalpiden ziyade entropik kayıpları önleyerek serbest enerjiyi (ΔG = ΔH - TΔS) negatifleştirir.\",\"ar\":\"مغالطة الارتباط التساهمي: التجسئة لا تجعل الدواء تساهمياً؛ بل تحسن طاقة جيبس الحرة بمنع ضياع الإنتروبيا في التفاعلات غير التساهمية.\",\"en\":\"Covalent binding fallacy: Rigidification does not confer covalent reactivity; it enhances free energy (ΔG = ΔH - TΔS) by preventing non-covalent entropy penalties.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-9a\",\"text\":\"Her donan bağ için ~2.5-4.0 kJ/mol entropi tasarrufu sağlanır; toplamda ~15 kJ/mol kazanç afiniteyi (Kd) 100-1000 kat artırır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Olağanüstü biyofiziksel kavrayış! ΔG = ΔH - TΔS denkleminde bağların önceden kilitlenmesi TΔS kaybını sıfırlayarak bağlanmayı kat kat güçlü kılar.\"},{\"id\":\"opt-9b\",\"text\":\"Serbest bağları dondurmak molekül ağırlığını azalttığı için difüzyon katsayısını 10 kat artırır ama bağlanma afinitesini hiç etkilemez.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Molekül ağırlığı yanılgısı: Rotasyonel bağları halkaya kilitlemek molekül ağırlığını neredeyse değiştirmez; afinite artışının temel nedeni termodinamik konformasyonel entropi (-TΔS) cezasının silinmesidir.\"},{\"id\":\"opt-9c\",\"text\":\"Bağların dondurulması entalpiyi (ΔH) 100 kJ/mol yükselterek ilacın reseptörle kovalent bağ kurmasını sağlar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kovalent bağlanma yanılgısı: İskeleti rijit hale getirmek molekülü kovalent yapmaz; non-kovalan bağlanmada entalpiden ziyade entropik kayıpları önleyerek serbest enerjiyi (ΔG = ΔH - TΔS) negatifleştirir.\"}],\"revealedOutcome\":{\"tr\":\"Her donan bağ için ~2.5-4.0 kJ/mol entropi tasarrufu sağlanır; toplamda ~15 kJ/mol kazanç afiniteyi (Kd) 100-1000 kat artırır.\",\"ar\":\"توفر كل رابطة مجمدة ~2.5-4.0 كيلوجول/مول؛ وحصيلة ~15 كيلوجول/مول ترفع الألفة بمقدار 100 إلى 1000 ضعف.\",\"en\":\"Each frozen bond saves ~2.5-4.0 kJ/mol in entropy penalty; ~15 kJ/mol total gain boosts affinity (drops Kd) 100- to 1000-fold.\"},\"explanation\":{\"tr\":\"Olağanüstü biyofiziksel kavrayış! ΔG = ΔH - TΔS denkleminde bağların önceden kilitlenmesi TΔS kaybını sıfırlayarak bağlanmayı kat kat güçlü kılar.\",\"ar\":\"فهم فيزيائي حيوي استثنائي! تثبيت الروابط مسبقاً يلغي ضريبة الإنتروبيا التشكيلية فيرفع الألفة بشكل أسي.\",\"en\":\"Extraordinary biophysical deduction! In ΔG = ΔH - TΔS, pre-organizing the scaffold eliminates conformational entropy loss, driving exponential affinity increases.\"}}},{\"id\":\"mc-mod4-les2-step-10\",\"stage\":\"retrieval\",\"stageIndex\":10,\"type\":\"retrieval\",\"title\":{\"tr\":\"Aralıklı Hatırlama: Konfigürasyon vs Konformasyon\",\"ar\":\"استرجاع متباعد: التشكيل الفراغي مقابل التماكب البنائي\",\"en\":\"Spaced Retrieval: Conformation vs Configuration\"},\"prompt\":{\"tr\":\"Optik enantiyomerler (konfigürasyon) ile rotamerler (konformasyon) arasındaki temel kimyasal ayrım nedir?\",\"ar\":\"ما الفارق الكيميائي الجوهري الحاسم بين المصاوغات الضوئية المرآوية والمتشكلات الدورانية؟\",\"en\":\"What is the fundamental physical-chemical boundary separating enantiomers (configuration) from rotamers (conformation)?\"},\"technicalTerms\":[{\"term\":\"konfigürasyon\",\"arContext\":\"التشكيل التكويني\"},{\"term\":\"konformasyon\",\"arContext\":\"التشكيل الفراغي\"}],\"hints\":[{\"tr\":\"Birbirine dönüştürmek için kovalent bağ kırmak gerekir mi gerekmez mi?\",\"ar\":\"هل يتطلب التحويل كسر روابط تساهمية أم لا؟\",\"en\":\"Does interconversion require breaking and reforming covalent bonds?\"},{\"tr\":\"Enantiyomerler kovalent bağ kırılmadan birbirine dönüşemez; rotamerler tekli bağ dönmesiyle dinamik olarak dönüşür.\",\"ar\":\"لا تتحول المصاوغات المرآوية إلا بكسر الروابط؛ بينما تتحول الروتانيرات بالدوران الحر فقط.\",\"en\":\"Enantiomers require covalent bond cleavage; rotamers interconvert dynamically via thermal rotation.\"},{\"tr\":\"Konfigürasyon kovalent bağ kırılması şart koşar; konformasyon serbest döner.\",\"ar\":\"التكوين يشترط كسر الروابط؛ والتشكيل يدور بحرية.\",\"en\":\"Configuration requires covalent bond breaking; conformation rotates freely around single bonds.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":8},{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":39}],\"conceptCheck\":{\"options\":[{\"id\":\"opt-10a\",\"text\":{\"tr\":\"Konfigürasyon izomerleri ancak kovalent bağ kırılıp yeniden oluşarak dönüşebilir; konformerler ise tekil bağlar etrafında enerji harcamaksızın döner.\",\"ar\":\"تتحول المصاوغات التكوينية حصراً بكسر روابط تساهمية وإعادة بنائها؛ بينما تدور المتشكلات الفراغية حول الروابط الأحادية بحرية.\",\"en\":\"Configuration isomers only interconvert by breaking covalent bonds; conformers interconvert dynamically via rotation around single bonds.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Tam bir sınav klasiği! Slayt 8 ve 39'un özeti: Konfigürasyon (enantiyomerler, cis/trans) kovalent bağ kırılması gerektirirken, konformasyon dinamik dengededir.\",\"ar\":\"قاعدة ذهبية! شريحة 8 و 39: التماكب التكويني يتطلب كسر الروابط، بينما التماكب التشكلي دوران حر في توازن ديناميكي.\",\"en\":\"Textbook gold standard! Slides 8 and 39: Configuration requires covalent bond rupture; conformation interconverts via thermal single-bond rotation.\"}},{\"id\":\"opt-10b\",\"text\":{\"tr\":\"Konfigürasyon izomerleri oda sıcaklığında saniyede milyonlarca kez birbirine dönüşürken, konformasyonlar yalnızca yüksek ısıda değişir.\",\"ar\":\"المتماكبات التكوينية تتحول تلقائياً ملايين المرات في الثانية، بينما التشكيلات الفراغية تتغير فقط بالحرارة العالية.\",\"en\":\"Configurational isomers interconvert millions of times per second, whereas conformers require high thermal energy to flip.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Hız ve mekanizma tersliği yanılgısı: Tam tersi! Oda sıcaklığında nanotaniyelerde dönen yapılar konformerlerdir; konfigürasyonel izomerlerin (R/S, cis/trans) birbirine dönüşmesi için kovalent bağ kırılması şarttır.\",\"ar\":\"مغالطة عكس الآلية والسرعة: العكس تماماً! التشكيلات تدور في نانوثوانٍ؛ بينما المتماكبات التكوينية تتطلب كسر روابط تساهمية.\",\"en\":\"Interconversion rate inversion fallacy: Opposite! Conformers rotate in nanoseconds; configurational isomers (R/S, cis/trans) require covalent bond cleavage.\"}},{\"id\":\"opt-10c\",\"text\":{\"tr\":\"Konformasyonel izomerler sadece optikçe aktif kiral moleküllerde görülür; akiral moleküllerde konformasyon oluşamaz.\",\"ar\":\"التماكب التشكلي يحدث حصراً في الجزيئات الكيرالية ذات الفعالية الضوئية، ولا وجود له في الجزيئات غير الكيرالية.\",\"en\":\"Conformational isomerism occurs exclusively in optically active chiral molecules; achiral molecules cannot possess conformers.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kiralite bağımlılığı yanılgısı: Konformasyonel izomerizm kiraliteye bağlı değildir; etan veya asetilkolin gibi akiral moleküller bile tekli bağları etrafında dönerek sonsuz sayıda konformasyon alır.\",\"ar\":\"مغالطة اشتراط الكيرالية: التماكب التشكلي لا يرتبط بالكيرالية؛ فحتى الجزيئات غير الكيرالية كالإيثان والأستيل كولين تدور وتأخذ أشكالاً لا نهائية.\",\"en\":\"Chirality dependence fallacy: Conformation does not require chirality; even achiral molecules like ethane or acetylcholine adopt infinite rotamers.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-10a\",\"text\":\"Konfigürasyon izomerleri ancak kovalent bağ kırılıp yeniden oluşarak dönüşebilir; konformerler ise tekil bağlar etrafında enerji harcamaksızın döner.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Tam bir sınav klasiği! Slayt 8 ve 39'un özeti: Konfigürasyon (enantiyomerler, cis/trans) kovalent bağ kırılması gerektirirken, konformasyon dinamik dengededir.\"},{\"id\":\"opt-10b\",\"text\":\"Konfigürasyon izomerleri oda sıcaklığında saniyede milyonlarca kez birbirine dönüşürken, konformasyonlar yalnızca yüksek ısıda değişir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Hız ve mekanizma tersliği yanılgısı: Tam tersi! Oda sıcaklığında nanotaniyelerde dönen yapılar konformerlerdir; konfigürasyonel izomerlerin (R/S, cis/trans) birbirine dönüşmesi için kovalent bağ kırılması şarttır.\"},{\"id\":\"opt-10c\",\"text\":\"Konformasyonel izomerler sadece optikçe aktif kiral moleküllerde görülür; akiral moleküllerde konformasyon oluşamaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kiralite bağımlılığı yanılgısı: Konformasyonel izomerizm kiraliteye bağlı değildir; etan veya asetilkolin gibi akiral moleküller bile tekli bağları etrafında dönerek sonsuz sayıda konformasyon alır.\"}],\"revealedOutcome\":{\"tr\":\"Konfigürasyon izomerleri ancak kovalent bağ kırılıp yeniden oluşarak dönüşebilir; konformerler ise tekil bağlar etrafında enerji harcamaksızın döner.\",\"ar\":\"تتحول المصاوغات التكوينية حصراً بكسر روابط تساهمية وإعادة بنائها؛ بينما تدور المتشكلات الفراغية حول الروابط الأحادية بحرية.\",\"en\":\"Configuration isomers only interconvert by breaking covalent bonds; conformers interconvert dynamically via rotation around single bonds.\"},\"explanation\":{\"tr\":\"Tam bir sınav klasiği! Slayt 8 ve 39'un özeti: Konfigürasyon (enantiyomerler, cis/trans) kovalent bağ kırılması gerektirirken, konformasyon dinamik dengededir.\",\"ar\":\"قاعدة ذهبية! شريحة 8 و 39: التماكب التكويني يتطلب كسر الروابط، بينما التماكب التشكلي دوران حر في توازن ديناميكي.\",\"en\":\"Textbook gold standard! Slides 8 and 39: Configuration requires covalent bond rupture; conformation interconverts via thermal single-bond rotation.\"}}},{\"id\":\"mc-mod4-les2-step-11\",\"stage\":\"connection\",\"stageIndex\":11,\"type\":\"connection\",\"title\":{\"tr\":\"Modül Köprüsü: Sitokrom P450 ve Metabolik Cep Uyumu\",\"ar\":\"جسر الموديول: تطابق السيتوكروم P450 والجيب الاستقلابي\",\"en\":\"Module Bridge: Conformation Meets Phase I Metabolism\"},\"prompt\":{\"tr\":\"Bir ilacın esnek konformasyonel yapısı, karaciğerde Sitokrom P450 enzimlerinin oksitleyeceği metabolik zayıf noktaları (soft-spots) nasıl belirler?\",\"ar\":\"كيف يحدد التشكيل الفراغي المرن للدواء نقاط الضعف الاستقلابية التي ستؤكسدها إنزيمات السيتوكروم P450 في الكبد؟\",\"en\":\"How does a drug's dynamic conformational flexibility determine which metabolic soft-spots are presented to the heme iron-oxo radical of Cytochrome P450?\"},\"technicalTerms\":[{\"term\":\"metabolik zayıf nokta (soft-spot)\",\"arContext\":\"نقطة الضعف الاستقلابية\"}],\"hints\":[{\"tr\":\"CYP450 aktif bölgesinde reaktif bir demir-okso radikali (Fe4+=O) bulunur.\",\"ar\":\"يحتوي الجيب النشط لـ CYP450 على جذر أكسيد الحديد التفاعلي.\",\"en\":\"The CYP450 catalytic pocket contains an iron-oxo radical intermediate ([Fe4+=O]•+).\"},{\"tr\":\"İlacın hangi pozisyonunun hidroksilleneceği, molekülün cebe hangi konformasyonda yanaştığına bağlıdır.\",\"ar\":\"يعتمد موقع الهدرلة على التشكيل الفراغي الذي يقدمه الدواء لجذر الحديد.\",\"en\":\"Which atom is oxygenated depends on which conformation presents that bond closest to the heme iron.\"},{\"tr\":\"Enzime bağlanan biyoaktif konformasyon, reaktif radikale en yakın karbonu metabolize eder (Modül 5 Faz I temeli).\",\"ar\":\"التشكيل المرتبط بالإنزيم يقدم الكربون الأقرب لجذر الأكسجين ليتم أكسدته.\",\"en\":\"The conformer bound inside the catalytic cleft presents the closest carbon to the radical center (Module 5 Phase I bridge).\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":41}],\"conceptCheck\":{\"options\":[{\"id\":\"opt-11a\",\"text\":{\"tr\":\"İlaç CYP450 cebine oturduğunda en kararlı değil, enzimin demir-okso merkezine en yakın uzanan konformasyon hidroksillenir.\",\"ar\":\"عندما يستقر الدواء في جيب CYP450، فإن التشكيل الذي يوجه الرابطة الأقرب لمركز جذر الحديد هو الذي يتأكسد.\",\"en\":\"When docked into CYP450, the conformation presenting a C-H bond closest to the iron-oxo radical is selectively hydroxylated.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika modül köprüsü! Peptidomimetiklerde ve makrosiklik moleküllerde (makrosiklizasyon) iskelet rijitlenerek hem biyoaktif konformasyon korunur hem de CYP450 metabolik soft-spot'larının enzime yanaşması engellenir (Modül 5 Faz I temeli).\",\"ar\":\"ربط موديولي رائع! في أشباه الببتيدات (peptidomimetics) والجزيئات الحلقية الضخمة (macrocyclization)، يتم تجسئة الهيكل للحفاظ على التشكل الحيوي ومنع وصول نقاط الضعف الاستقلابية لإنزيمات CYP450.\",\"en\":\"Masterful bridge! In peptidomimetics and macrocycles (macrocyclization), scaffold rigidification locks the bioactive pose while sterically shielding metabolic soft-spots from CYP450 oxidation (Module 5 Phase I bridge).\"}},{\"id\":\"opt-11b\",\"text\":{\"tr\":\"Sitokrom P450 enzimleri yalnızca dairesel halkaları tanır; zincirleri parçalayamaz.\",\"ar\":\"تتعرف إنزيمات CYP450 على الحلقات فقط ولا تؤكسد السلاسل الأليفاتية المفتوحة.\",\"en\":\"Cytochrome P450 enzymes only recognize closed rings and cannot oxidize open aliphatic chains.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Enzim kısıtlama yanılgısı: CYP450 hem aromatik halkaları hem de alifatik yan zincirleri (ω ve ω-1) hızla hidroksiller.\",\"ar\":\"خطأ قصر الإنزيم: تؤكسد إنزيمات CYP450 السلاسل الأليفاتية والحلقات العطرية على حد سواء.\",\"en\":\"Enzyme restriction fallacy: CYP450 readily hydroxylates aliphatic chains (at omega and omega-1 positions) as well as aromatic rings.\"}},{\"id\":\"opt-11c\",\"text\":{\"tr\":\"Bir molekülün karaciğerde metabolize olabilmesi için mutlaka çözeltideki mutlak en düşük enerjili konformasyonunda olması zorunludur.\",\"ar\":\"لكي يستقلب الجزيء في الكبد، يجب أن يكون حتماً في التشكيل الأدنى طاقة والأكثر استقراراً في المحلول.\",\"en\":\"For a drug to be metabolized in the liver, it must strictly adopt its absolute global minimum energy conformation.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Metabolik minimum yanılgısı: Tıpkı reseptörlerde olduğu gibi, enzim ceplerinde de ilacın katalitik merkezle en uygun mesafeyi kurduğu konformasyon metabolize edilir; bu form serbest çözeltideki en kararlı form olmak zorunda değildir.\",\"ar\":\"مغالطة الأدنى طاقة بالاستقلاب: تماماً كالمستقبلات، جيب الإنزيم يفضل التشكيل الذي يضع الرابطة بمحاذاة المركز التحفيزي حتى لو كان أعلى طاقة في المحلول.\",\"en\":\"Metabolic minimum fallacy: Like receptors, catalytic enzyme active sites bind the conformer presenting the bond to the heme iron, regardless of solution minimum.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-11a\",\"text\":\"İlaç CYP450 cebine oturduğunda en kararlı değil, enzimin demir-okso merkezine en yakın uzanan konformasyon hidroksillenir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika modül köprüsü! Peptidomimetiklerde ve makrosiklik moleküllerde (makrosiklizasyon) iskelet rijitlenerek hem biyoaktif konformasyon korunur hem de CYP450 metabolik soft-spot'larının enzime yanaşması engellenir (Modül 5 Faz I temeli).\"},{\"id\":\"opt-11b\",\"text\":\"Sitokrom P450 enzimleri yalnızca dairesel halkaları tanır; zincirleri parçalayamaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Enzim kısıtlama yanılgısı: CYP450 hem aromatik halkaları hem de alifatik yan zincirleri (ω ve ω-1) hızla hidroksiller.\"},{\"id\":\"opt-11c\",\"text\":\"Bir molekülün karaciğerde metabolize olabilmesi için mutlaka çözeltideki mutlak en düşük enerjili konformasyonunda olması zorunludur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Metabolik minimum yanılgısı: Tıpkı reseptörlerde olduğu gibi, enzim ceplerinde de ilacın katalitik merkezle en uygun mesafeyi kurduğu konformasyon metabolize edilir; bu form serbest çözeltideki en kararlı form olmak zorunda değildir.\"}],\"revealedOutcome\":{\"tr\":\"İlaç CYP450 cebine oturduğunda en kararlı değil, enzimin demir-okso merkezine en yakın uzanan konformasyon hidroksillenir.\",\"ar\":\"عندما يستقر الدواء في جيب CYP450، فإن التشكيل الذي يوجه الرابطة الأقرب لمركز جذر الحديد هو الذي يتأكسد.\",\"en\":\"When docked into CYP450, the conformation presenting a C-H bond closest to the iron-oxo radical is selectively hydroxylated.\"},\"explanation\":{\"tr\":\"Harika modül köprüsü! Peptidomimetiklerde ve makrosiklik moleküllerde (makrosiklizasyon) iskelet rijitlenerek hem biyoaktif konformasyon korunur hem de CYP450 metabolik soft-spot'larının enzime yanaşması engellenir (Modül 5 Faz I temeli).\",\"ar\":\"ربط موديولي رائع! في أشباه الببتيدات (peptidomimetics) والجزيئات الحلقية الضخمة (macrocyclization)، يتم تجسئة الهيكل للحفاظ على التشكل الحيوي ومنع وصول نقاط الضعف الاستقلابية لإنزيمات CYP450.\",\"en\":\"Masterful bridge! In peptidomimetics and macrocycles (macrocyclization), scaffold rigidification locks the bioactive pose while sterically shielding metabolic soft-spots from CYP450 oxidation (Module 5 Phase I bridge).\"}}},{\"id\":\"mc-mod4-les2-step-12\",\"stage\":\"mastery_check\",\"stageIndex\":12,\"type\":\"mastery_check\",\"title\":{\"tr\":\"Ustalık Sınavı: Dopamin Agonistinde Rijit Halka Tasarımı\",\"ar\":\"اختبار الإتقان: تصميم حلقة صلبة لناهض الدوبامين\",\"en\":\"Mastery Transfer: Rigidification of Dopamine D2 Leads\"},\"prompt\":{\"tr\":\"Dopamin D2 reseptörü transoid (anti) etilamin konformasyonunu şart koşar. 4 dönebilen bağı olan esnek öncü bir liganttan sub-nanomolar afiniteli rijit bir türev tasarlamak için ne yaparsınız?\",\"ar\":\"يشترط مستقبل الدوبامين D2 تشكيل الإيثيل أمين الممتد (anti). لتصميم مشتق جاسئ فائق الألفة من ربيطة مرنة تمتلك 4 روابط دوارة، ماذا تفعل؟\",\"en\":\"Dopamine D2 receptors strictly require a trans-coplanar (anti) ethylamine geometry. To evolve a flexible 4-rotatable-bond lead into a sub-nanomolar drug, what structural design do you propose?\"},\"technicalTerms\":[{\"term\":\"konformasyonel rigidifikasyon\",\"arContext\":\"التجسئة التشكيلية\"}],\"hints\":[{\"tr\":\"D2 reseptörünün istediği geometri transoid (anti) uzamış formdur.\",\"ar\":\"الهندسة التي يشترطها مستقبل D2 هي الشكل الممتد anti.\",\"en\":\"The geometry demanded by the D2 receptor is the trans-coplanar (anti) extended pose.\"},{\"tr\":\"Esnek etilamin zincirini bu anti-biçimde sabitleyen halkalı bir iskelet (tetralin / 2-aminotetralin) düşünün.\",\"ar\":\"فكر في هيكل حلقي يجمد سلسلة الإيثيل أمين في شكل anti مثل حلقة التترالين.\",\"en\":\"Consider cyclizing the ethylamine chain into a bicyclic tetralin scaffold locking the anti conformation.\"},{\"tr\":\"Zinciri trans-tetralin içine kaynaştırmak anti-geometriyi dondurur, entropi cezasını silerek afiniteyi katlar.\",\"ar\":\"دمج السلسلة في حلقة trans-tetralin يجمد شكل anti ويوفر ضريبة الإنتروبيا فيرفع الألفة بشدة.\",\"en\":\"Fusing the chain into a trans-tetralin ring locks the anti geometry and eliminates entropy penalties, boosting affinity.\"}],\"sources\":[{\"file\":\"İlaçlarda  İzomeri.pdf\",\"page\":41}],\"conceptCheck\":{\"options\":[{\"id\":\"opt-12a\",\"text\":{\"tr\":\"Etilamin zincirini 2-aminotetralin halkası içine kaynaştırıp anti-geometriyi dondurur, entropi cezasını silerek sub-nanomolar afinite sağlarız.\",\"ar\":\"ندمج سلسلة الإيثيل أمين داخل حلقة 2-aminotetralin لتجميد شكل anti وإلغاء ضريبة الإنتروبيا لتحقيق ألفة عالية.\",\"en\":\"Fuse the ethylamine chain into a 2-aminotetralin scaffold to lock the anti geometry, eliminating entropy penalties to achieve sub-nanomolar affinity.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz bir farmasötik kimya transferi! Esnek dopamin iskeletini trans-tetralin içine kilitlemek (-TΔS) cezasını (~12 kJ/mol) siler ve molekülü doğrudan D2 agonistine (örn. rotigotin) dönüştürür.\",\"ar\":\"إتقان مبهر في الكيمياء الدوائية! تجميد هيكل الدوبامين في حلقة التترالين يوفر طاقة الإنتروبيا وينتج ناهضات دوبامين قوية مثل روتيغوتين.\",\"en\":\"Flawless medicinal chemistry transfer! Locking dopamine's flexible ethylamine chain into a trans-tetralin ring saves ~12 kJ/mol in entropic penalty, yielding sub-nanomolar D2 agonists like rotigotine.\"}},{\"id\":\"opt-12b\",\"text\":{\"tr\":\"Etilamin zincirini siklopropan halkası ile cis-koplanar (katlanmış) konformasyonda dondurarak amino grubunun katekol hidroksilleri ile molekül içi hidrojen bağı yapmasını sağlarız.\",\"ar\":\"تجميد سلسلة الإيثيل أمين في حلقة سيكلوبروبيل بتشكيل cis المطوي لتشكيل روابط هيدروجينية داخلية مع هيدروكسيلات الكاتيكول.\",\"en\":\"Lock the ethylamine into a cis-coplanar cyclopropyl ring so the amine forms an intramolecular hydrogen bond with the catechol OH groups.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Molekül içi H-bağı vs reseptör geometrisi yanılgısı: Katlanmış (cis) form molekül içinde kararlı hissettirse de, dopamin D2 reseptörü kesin olarak uzamış anti-geometriyi (transoid) şart koşar; cis türevleri D2 afinitesini kaybeder.\",\"ar\":\"مغالطة الرابطة الهيدروجينية الداخلية: رغم أن التشكيل المطوي مستقر داخلياً، إلا أن مستقبل D2 يشترط التشكيل الممتد transoid؛ مشتقات cis تفقد الألفة تماماً.\",\"en\":\"Intramolecular H-bond fallacy: While cis folding appears internally stable, the D2 receptor pocket strictly demands the extended transoid geometry.\"}},{\"id\":\"opt-12c\",\"text\":{\"tr\":\"Esnekliği daha da artırmak için etilamin zincirine 3 ilave serbest dönen karbon ekleyerek molekülün reseptör cebindeki tüm amino asitleri aynı anda taramasını sağlarız.\",\"ar\":\"زيادة المرونة بإضافة 3 كربونات حرة الدوران إلى السلسلة لتمكين الجزيء من مسح والتوافق مع جميع الأحماض الأمينية في المستقبل معاً.\",\"en\":\"Add 3 more rotatable carbons to the ethylamine chain to maximize flexibility so the molecule can simultaneously contact all pocket residues.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Daha fazla esneklik yanılgısı: Serbest dönen bağ sayısını artırmak entropi cezasını (-TΔS) dramatik şekilde büyütür ve bağlanma afinitesini yıkar; hedefimiz esnekliği artırmak değil, biyoaktif formu kilitlemektir.\",\"ar\":\"مغالطة المرونة الزائدة: زيادة الروابط الدوارة تضخم ضريبة الإنتروبيا التشكيلية وتدمر الألفة؛ الهدف ليس زيادة المرونة بل قفل التشكيل الحيوي.\",\"en\":\"Flexibility fallacy: Adding rotatable bonds escalates the conformational entropy penalty, crushing affinity; medicinal design seeks rigidification.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-12a\",\"text\":\"Etilamin zincirini 2-aminotetralin halkası içine kaynaştırıp anti-geometriyi dondurur, entropi cezasını silerek sub-nanomolar afinite sağlarız.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz bir farmasötik kimya transferi! Esnek dopamin iskeletini trans-tetralin içine kilitlemek (-TΔS) cezasını (~12 kJ/mol) siler ve molekülü doğrudan D2 agonistine (örn. rotigotin) dönüştürür.\"},{\"id\":\"opt-12b\",\"text\":\"Etilamin zincirini siklopropan halkası ile cis-koplanar (katlanmış) konformasyonda dondurarak amino grubunun katekol hidroksilleri ile molekül içi hidrojen bağı yapmasını sağlarız.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Molekül içi H-bağı vs reseptör geometrisi yanılgısı: Katlanmış (cis) form molekül içinde kararlı hissettirse de, dopamin D2 reseptörü kesin olarak uzamış anti-geometriyi (transoid) şart koşar; cis türevleri D2 afinitesini kaybeder.\"},{\"id\":\"opt-12c\",\"text\":\"Esnekliği daha da artırmak için etilamin zincirine 3 ilave serbest dönen karbon ekleyerek molekülün reseptör cebindeki tüm amino asitleri aynı anda taramasını sağlarız.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Daha fazla esneklik yanılgısı: Serbest dönen bağ sayısını artırmak entropi cezasını (-TΔS) dramatik şekilde büyütür ve bağlanma afinitesini yıkar; hedefimiz esnekliği artırmak değil, biyoaktif formu kilitlemektir.\"}],\"revealedOutcome\":{\"tr\":\"Etilamin zincirini 2-aminotetralin halkası içine kaynaştırıp anti-geometriyi dondurur, entropi cezasını silerek sub-nanomolar afinite sağlarız.\",\"ar\":\"ندمج سلسلة الإيثيل أمين داخل حلقة 2-aminotetralin لتجميد شكل anti وإلغاء ضريبة الإنتروبيا لتحقيق ألفة عالية.\",\"en\":\"Fuse the ethylamine chain into a 2-aminotetralin scaffold to lock the anti geometry, eliminating entropy penalties to achieve sub-nanomolar affinity.\"},\"explanation\":{\"tr\":\"Kusursuz bir farmasötik kimya transferi! Esnek dopamin iskeletini trans-tetralin içine kilitlemek (-TΔS) cezasını (~12 kJ/mol) siler ve molekülü doğrudan D2 agonistine (örn. rotigotin) dönüştürür.\",\"ar\":\"إتقان مبهر في الكيمياء الدوائية! تجميد هيكل الدوبامين في حلقة التترالين يوفر طاقة الإنتروبيا وينتج ناهضات دوبامين قوية مثل روتيغوتين.\",\"en\":\"Flawless medicinal chemistry transfer! Locking dopamine's flexible ethylamine chain into a trans-tetralin ring saves ~12 kJ/mol in entropic penalty, yielding sub-nanomolar D2 agonists like rotigotine.\"}}}]},\"mc-mod5-les1\":{\"$schema\":\"../../../packages/platform/schema/lesson.schema.json\",\"id\":\"mc-mod5-les1\",\"courseId\":\"medchem\",\"moduleId\":\"mc-mod-05\",\"title\":{\"tr\":\"Faz I Fonksiyonelleşme: Sitokrom P450 ve Hidroksilasyon Mekanizmaları\",\"ar\":\"المرحلة الأولى من التحول الحيوي: آليات أكسدة وهدرلة CYP450\",\"en\":\"Phase I Functionalization: Cytochrome P450 Hydroxylation Mechanisms\"},\"order\":1,\"access\":\"free\",\"objective\":{\"tr\":\"Sitokrom P450 katalitik döngüsünü, okso-ferril radikalini, alifatik ve aromatik hidroksilasyonu (NIH kayması) ile oksidatif dealkilasyon mekanizmalarını analiz etmek.\",\"ar\":\"تحليل الدورة التحفيزية لـ CYP450، والجذر الحديدي الأوكسيدي، والهدرلة الأليفاتية والعطرية (انزياح NIH)، وآليات نزع الألكيل الأكسيدي.\",\"en\":\"Analyze the Cytochrome P450 catalytic cycle, the oxo-ferryl radical intermediate, aliphatic and aromatic hydroxylation (NIH shift), and oxidative dealkylation mechanisms.\"},\"misconceptions\":[{\"tr\":\"Metabolizmanın daima ilacı zehirsizleştirdiği ve etkisini sonlandırdığı yanılgısı (aktif metabolitler ve biyoaktivasyon göz ardı edilir).\",\"ar\":\"الظن الخاطئ بأن الاستقلاب يؤدي حتماً إلى إبطال فعالية الدواء متجاهلاً التنشيط الحيوي للأدوية الطليعية والمستقلبات السامة.\",\"en\":\"The misconception that metabolism always detoxifies drugs and terminates pharmacologic action, ignoring bioactivation and active metabolites.\"},{\"tr\":\"Aromatik hidroksilasyonda hidrojen atomunun doğrudan koptuğu ve aren oksit ara ürününün (NIH kaymasının) oluşmadığı düşüncesi.\",\"ar\":\"الاعتقاد الخاطئ بأن الهدرلة العطرية تحدث بفقد مباشر للبروتون دون تشكل أكسيد الآرين كمركب وسيط أو حدوث انزياح NIH.\",\"en\":\"The belief that aromatic hydroxylation involves simple direct substitution without an electrophilic arene oxide intermediate and NIH hydride shift.\"},{\"tr\":\"Oksidatif dealkilasyonda heteroatom-karbon bağının doğrudan enzim tarafından kesildiği varsayımı (kararsız alfa-hidroksialkil ara ürünü bilinmez).\",\"ar\":\"الافتراض الخاطئ بأن إنزيم CYP450 يقطع رابطة كربون-ذرة غير متجانسة مباشرة دون المرور بمركب ألفا-هيدروكسي غير المستقر.\",\"en\":\"The false assumption that CYP450 directly cleaves the carbon-heteroatom bond rather than oxygenating the adjacent alpha-carbon to collapse spontaneously.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":1},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":4},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":14},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":15},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":16},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":20},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":21},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":28}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Foye's Principles of Medicinal Chemistry\",\"edition\":\"8th ed.\",\"topic\":\"Phase I Drug Metabolism: Cytochrome P450 Oxygenations, NIH Shift, and Hydrolysis\",\"chapter\":\"Chapter 4: Drug Biotransformation\",\"page\":\"115-148\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Wilson and Gisvold's Textbook of Organic Medicinal and Pharmaceutical Chemistry\",\"edition\":\"12th ed.\",\"topic\":\"Metabolic Oxidation of Aliphatic and Aromatic Carbons, Dealkylation, and Amide Hydrolysis\",\"chapter\":\"Chapter 4: Metabolic Changes of Drugs and Related Organic Compounds\",\"page\":\"120-165\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"mc-mod5-les1-card1\",\"courseId\":\"medchem\",\"drugOrConcept\":\"CYP450 Katalitik Döngüsü ve Aktif Oksijen\",\"prompt\":\"Sitokrom P450 monooksijenaz döngüsünde inert C-H bağlarını oksitleyen nihai reaktif tür nedir ve elektronlar nereden gelir?\",\"answer\":\"[Fe4+=O]•+ (okso-ferril radikal katyonu); NADPH kofaktöründen NADPH-CYP450 redüktaz enzimi aracılığıyla 2 elektron aktarılmasıyla üretilir.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod5-les1-card2\",\"courseId\":\"medchem\",\"drugOrConcept\":\"NIH Kayması (NIH Shift)\",\"prompt\":\"Aromatik hidroksilasyon sırasında gözlenen NIH kayması nedir ve hangi ara ürün üzerinden gerçekleşir?\",\"answer\":\"Aromatik halkanın epoksitlenmesiyle oluşan aren oksit ara ürünü açılırken, komşu hidritin (veya döteryumun) 1,2-karbon göçü yapması ve keto-enol tautomerisiyle fenol oluşturmasıdır.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod5-les1-card3\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Oksidatif N- ve O-Dealkilasyon Mekanizması\",\"prompt\":\"CYP450 enzimleri heteroatoma (N, O, S) bağlı alkil gruplarını (örn. Fenasetin, Diazepam) hangi mekanizmayla koparır?\",\"answer\":\"Heteroatoma komşu alfa-karbon hidroksillenir; oluşan kararsız hemiaminal veya hemiasetal ara ürünü kendiliğinden parçalanarak aldehit (formaldehit) ve dealkile ilaç açığa çıkarır.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod5-les1-card4\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Alifatik omega vs (omega-1) Oksidasyonu\",\"prompt\":\"Barbitüratlarda (pentobarbital) alifatik yan zincir oksidasyonunda neden sekonder alkol (omega-1) primer alkolden (omega) daha baskındır?\",\"answer\":\"Sekonder C-H bağından hidrojen radikali koparılması sonucu oluşan sekonder alkil radikali, primer radikale göre termodinamik olarak daha kararlıdır.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod5-les1-card5\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Ester vs Amit Hidroliz Kinetiği (Prokain vs Prokainamid)\",\"prompt\":\"Lokal anestezik prokain dakikalar içinde inaktive olurken, antiaritmik prokainamid neden saatlerce plazmada kararlı kalır?\",\"answer\":\"Plazma bütirilkolinesteraz ve karboksilesterazları ester bağını (prokain) saniyeler-dakikalar içinde hidroliz eder; amidazlar ise amit bağını (prokainamid) çok yavaş yıkar (t1/2 ≈ 3-4 saat).\",\"box\":1,\"intervalDays\":1}],\"translations\":{\"tr\":{\"title\":\"Faz I Fonksiyonelleşme: Sitokrom P450 ve Hidroksilasyon Mekanizmaları\"},\"ar\":{\"title\":\"المرحلة الأولى من التحول الحيوي: آليات أكسدة وهدرلة CYP450\"},\"en\":{\"title\":\"Phase I Functionalization: Cytochrome P450 Hydroxylation Mechanisms\"}},\"steps\":[{\"id\":\"mc-mod5-les1-step-01\",\"stage\":\"hook\",\"stageIndex\":1,\"type\":\"predict_reveal\",\"title\":{\"tr\":\"Fenasetin Bilmecesi: Ağrı Kesen Molekül Hangisi?\",\"ar\":\"لغز الفيناسيتين: أي الجزيئات يسكن الألم حقاً؟\",\"en\":\"The Phenacetin Puzzle: Which Molecule Truly Relieves Pain?\"},\"prompt\":{\"tr\":\"Yıllarca ağrı kesici olarak kullanılan fenasetin, karaciğer mikrozomlarında CYP2D6 eksikliği olan hastalarda hiç etki göstermez. Kanda analjezik etkiyi oluşturan asıl molekül kimdir ve karaciğer onu nasıl üretir?\",\"ar\":\"فشل الفيناسيتين المسكن تاريخياً في تسكين ألم مرضى يعانون من عوز CYP2D6. ما هو الجزيء الحقيقي المسؤول عن التسكين في الدم، وكيف ينتجه الكبد؟\",\"en\":\"Phenacetin was widely used as an analgesic, yet patients deficient in CYP2D6 experienced zero pain relief. What molecule actually produces the analgesic effect in blood, and how does the liver create it?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-1a\",\"text\":{\"tr\":\"Fenasetin bir ön ilaçtır; karaciğer CYP enzimiyle oksidatif O-deetilasyona uğrayarak etil grubunu formaldehit olarak atar ve aktif parasetamolü açığa çıkarır.\",\"ar\":\"الفيناسيتين طليعة دوائية؛ يخضع لنزع إيثيل أكسيدي بإنزيمات CYP الكبدية طارحاً الألدهيد ومحرراً الباراسيتامول الفعال.\",\"en\":\"Phenacetin is a prodrug; hepatic CYP enzymes perform oxidative O-deethylation to cleave the ethyl group, releasing active paracetamol.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Tam isabet! Slayt 20'de gösterildiği gibi fenasetin etil eter yapısındadır. CYP enzimi etil grubunun alfa-karbonunu hidroksiller; oluşan kararsız hemiasetal asetaldehit bırakarak fenolik -OH grubunu (parasetamol) açığa çıkarır. Analjezik etkiyi oluşturan asıl tür parasetamoldür.\",\"ar\":\"إصابة دقيقة! كما في الشريحة 20، يمتلك الفيناسيتين إيثر إيثيلي. يهدرل CYP كربون ألفا ليتشكل هيمي أسيتال غير مستقر ينشطر محرراً أسيتالدهيد والباراسيتامول الفعال صاحب التأثير المسكن الحقيقي.\",\"en\":\"Direct hit! As shown in Slide 20, phenacetin is an ethyl ether. CYP oxygenates the alpha-methylene carbon to form an unstable hemiacetal that collapses, liberating acetaldehyde and active paracetamol.\"}},{\"id\":\"opt-1b\",\"text\":{\"tr\":\"Fenasetin gastrointestinal kanalda mide asidi ve pepsin tarafından doğrudan parasetamole hidroliz edilir; karaciğer metabolizmasına gerek kalmaz.\",\"ar\":\"يتحلمه الفيناسيتين في السبيل الهضمي بواسطة حمض المعدة والببسين مباشرة إلى باراسيتامول دون الحاجة لاستقلاب كبدي.\",\"en\":\"Phenacetin is hydrolyzed directly by stomach acid and pepsin into paracetamol in the gut lumen without requiring liver CYP enzymes.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Mide hidrolizi yanılgısı: Eter bağları asidik mide ortamında stabildir ve non-enzimatik hidrolize dirençlidir; O-dealkilasyon karaciğer mikrozomal CYP enzimleri tarafından gerçekleştirilir.\",\"ar\":\"مغالطة الحلمهة المعدية: الروابط الإيثرية مستقرة تماماً في الوسط المعدي الحمضي؛ تفاعل نزع الألكيل عن الأكسجين يتم حصرياً بإنزيمات CYP الكبدية.\",\"en\":\"Gastric hydrolysis fallacy: Ether linkages resist acid hydrolysis in the stomach; oxidative O-dealkylation strictly requires hepatic microsomal CYP monooxygenases.\"}},{\"id\":\"opt-1c\",\"text\":{\"tr\":\"Fenasetin herhangi bir metabolik dönüşüme uğramaz; etoksi grubu sayesinde doğrudan COX enzimini parasetamolden daha güçlü inhibe eder.\",\"ar\":\"لا يخضع الفيناسيتين لأي استقلاب؛ إذ تثبط مجموعته الإيثوكسية إنزيم COX بشكل أقوى من الباراسيتامول مباشرة.\",\"en\":\"Phenacetin undergoes no metabolic transformation; its intact ethoxy group directly inhibits COX enzymes more potently than paracetamol.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Doğrudan intakt etki yanılgısı: Etoksi grubunun sterik engeli COX cebine oturmayı engeller; analjezik etki ancak etil grubunun kopup serbest fenolik hidroksilin (parasetamol) açığa çıkmasıyla doğar.\",\"ar\":\"مغالطة الفعالية المباشرة: الإعاقة الحجمية للإيثوكسي تمنع ملاءمة جيب COX؛ التأثير المسكن ينشأ فقط بعد تحرر هيدروكسيل الفينول الحر (باراسيتامول).\",\"en\":\"Direct intact efficacy misconception: Bulky ethoxy steric hindrance impedes COX binding; analgesia depends on liberating the free phenolic hydroxyl (paracetamol).\"}}]},\"technicalTerms\":[{\"term\":\"oksidatif O-dealkilasyon\",\"arContext\":\"نزع الألكيل الأكسيدي (oxidative O-dealkylation)\"},{\"term\":\"ön ilaç biyoaktivasyonu\",\"arContext\":\"تنشيط الأدوية الطليعية\"}],\"hints\":[{\"tr\":\"Fenasetin molekülü p-etoksiasetanilit yapısındadır (etil eter taşır).\",\"ar\":\"يمتلك جزيء الفيناسيتين بنية بارا-إيثوكسي أسيتانيليد (إيثر إيثيلي).\",\"en\":\"Phenacetin possesses a p-ethoxyacetanilide structure containing an ethyl ether.\"},{\"tr\":\"Parasetamolün kimyasal yapısını hatırlayın: p-asetamidofenol (serbest fenolik -OH taşır).\",\"ar\":\"تذكر بنية الباراسيتامول: بارا-أسيتاميدوفينول (يحمل مجموعة هيدروكسيل فينولية حرة).\",\"en\":\"Recall paracetamol's structure: p-acetamidophenol bearing a free phenolic -OH.\"},{\"tr\":\"Karaciğer CYP450 enzimleri etil grubunu oksitleyerek parasetamole çevirir.\",\"ar\":\"تؤكسد إنزيمات CYP450 الكبدية مجموعة الإيثيل لتطلق الباراسيتامول.\",\"en\":\"Hepatic CYP450 oxidizes the ethyl carbon to release free paracetamol and an aldehyde.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":20}],\"config\":{\"options\":[{\"id\":\"opt-1a\",\"text\":\"Fenasetin bir ön ilaçtır; karaciğer CYP enzimiyle oksidatif O-deetilasyona uğrayarak etil grubunu formaldehit olarak atar ve aktif parasetamolü açığa çıkarır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Tam isabet! Slayt 20'de gösterildiği gibi fenasetin etil eter yapısındadır. CYP enzimi etil grubunun alfa-karbonunu hidroksiller; oluşan kararsız hemiasetal asetaldehit bırakarak fenolik -OH grubunu (parasetamol) açığa çıkarır. Analjezik etkiyi oluşturan asıl tür parasetamoldür.\"},{\"id\":\"opt-1b\",\"text\":\"Fenasetin gastrointestinal kanalda mide asidi ve pepsin tarafından doğrudan parasetamole hidroliz edilir; karaciğer metabolizmasına gerek kalmaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Mide hidrolizi yanılgısı: Eter bağları asidik mide ortamında stabildir ve non-enzimatik hidrolize dirençlidir; O-dealkilasyon karaciğer mikrozomal CYP enzimleri tarafından gerçekleştirilir.\"},{\"id\":\"opt-1c\",\"text\":\"Fenasetin herhangi bir metabolik dönüşüme uğramaz; etoksi grubu sayesinde doğrudan COX enzimini parasetamolden daha güçlü inhibe eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Doğrudan intakt etki yanılgısı: Etoksi grubunun sterik engeli COX cebine oturmayı engeller; analjezik etki ancak etil grubunun kopup serbest fenolik hidroksilin (parasetamol) açığa çıkmasıyla doğar.\"}],\"revealedOutcome\":{\"tr\":\"Fenasetin bir ön ilaçtır; karaciğer CYP enzimiyle oksidatif O-deetilasyona uğrayarak etil grubunu formaldehit olarak atar ve aktif parasetamolü açığa çıkarır.\",\"ar\":\"الفيناسيتين طليعة دوائية؛ يخضع لنزع إيثيل أكسيدي بإنزيمات CYP الكبدية طارحاً الألدهيد ومحرراً الباراسيتامول الفعال.\",\"en\":\"Phenacetin is a prodrug; hepatic CYP enzymes perform oxidative O-deethylation to cleave the ethyl group, releasing active paracetamol.\"},\"explanation\":{\"tr\":\"Tam isabet! Slayt 20'de gösterildiği gibi fenasetin etil eter yapısındadır. CYP enzimi etil grubunun alfa-karbonunu hidroksiller; oluşan kararsız hemiasetal asetaldehit bırakarak fenolik -OH grubunu (parasetamol) açığa çıkarır. Analjezik etkiyi oluşturan asıl tür parasetamoldür.\",\"ar\":\"إصابة دقيقة! كما في الشريحة 20، يمتلك الفيناسيتين إيثر إيثيلي. يهدرل CYP كربون ألفا ليتشكل هيمي أسيتال غير مستقر ينشطر محرراً أسيتالدهيد والباراسيتامول الفعال صاحب التأثير المسكن الحقيقي.\",\"en\":\"Direct hit! As shown in Slide 20, phenacetin is an ethyl ether. CYP oxygenates the alpha-methylene carbon to form an unstable hemiacetal that collapses, liberating acetaldehyde and active paracetamol.\"}}},{\"id\":\"mc-mod5-les1-step-02\",\"stage\":\"question\",\"stageIndex\":2,\"type\":\"question\",\"title\":{\"tr\":\"Oksijen Paradoksu: İnert C-H Bağı Nasıl Oksitlenir?\",\"ar\":\"مفارقة الأكسجين: كيف تتأكسد روابط C-H الخاملة؟\",\"en\":\"The Oxygen Paradox: How to Oxidize Inert C-H Bonds?\"},\"prompt\":{\"tr\":\"Soluduğumuz moleküler oksijen (O2) oda sıcaklığında son derece tembel ve reaktif olmayan bir gazdır. Karaciğerdeki CYP450 hem demiri, inert bir C-H bağına oksijen sokmak için O2'yi nasıl aktive eder?\",\"ar\":\"غاز الأكسجين الجزيئي (O2) خامل كيميائياً في حرارة الغرفة. كيف ينشط حديد الهيم في CYP450 الأكسجين ليقحمه داخل رابطة C-H أليفاتية خاملة؟\",\"en\":\"Molecular oxygen (O2) is triplet ground-state and unreactive toward stable bonds. How does the heme iron of CYP450 activate O2 to insert an oxygen atom into an unreactive aliphatic C-H bond?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-2a\",\"text\":{\"tr\":\"NADPH-P450 redüktazdan 2 elektron ve proton alarak O2'yi parçalar; aşırı reaktif demir(IV)-okso radikal katyonu ([Fe4+=O]•+) üretir.\",\"ar\":\"يستقبل إلكترونين من NADPH عبر إنزيم الريدوكتاز ليفصم O2، مولداً جذر حديد(IV)-أوكسو فائق التفاعلية ([Fe4+=O]•+).\",\"en\":\"It accepts 2 electrons from NADPH via P450 reductase and protons to cleave O2, generating a hyper-reactive iron(IV)-oxo radical cation ([Fe4+=O]•+).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz kimyasal kavrayış! Slayt 14 ve Foye Bölüm 4'ün temeli: Sitokrom P450 katalitik döngüsünde Fe3+ heme önce substrate bağlanır, NADPH-redüktazdan ilk elektronu alarak Fe2+'ye indirgenir, O2 bağlar ve ikinci elektronla perokso köprüsü kurar. Su ayrılarak oluşan reaktif tür [Fe4+=O]•+ (okso-ferril radikali) inert C-H bağlarını hidroksilleme gücüne sahiptir.\",\"ar\":\"إدراك كيميائي فذ! الشريحة 14: يرتبط Fe3+ بالدواء، ويستقبل إلكتروناً أولاً ليصبح Fe2+، ثم يربط O2 ويستقبل الإلكترون الثاني. بانفصال الماء يتشكل جذر [Fe4+=O]•+ (الحديد الأوكسيدي الفيريل) القادر على هدرلة أعتى الروابط الأليفاتية.\",\"en\":\"Masterful biophysical insight! Slide 14: Substrate binding triggers first electron transfer reducing Fe3+ to Fe2+, binding O2, followed by a second electron and protonation to release H2O and yield the reactive oxo-ferryl radical cation [Fe4+=O]•+.\"}},{\"id\":\"opt-2b\",\"text\":{\"tr\":\"Hem demirindeki Fe2+, moleküler oksijeni hidrojen peroksite (H2O2) indirger ve ortama serbest H2O2 salarak C-H bağını oksitler.\",\"ar\":\"يقوم حديد الهيم Fe2+ بإرجاع الأكسجين إلى فوق أكسيد الهيدروجين (H2O2) مطلقاً إياه في العصارة الخلوية لأكسدة الرابطة.\",\"en\":\"Heme Fe2+ reduces molecular oxygen to hydrogen peroxide (H2O2) and releases free peroxide into the cytosol to attack C-H bonds.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Serbest peroksit yanılgısı: Katalitik döngüde serbest peroksit hücresel ortama salınmaz; oksijen hem demirine koordineli kalır ve yüksek enerjili oksen-demir radikal ara ürünü [Fe4+=O]•+ oluşturur.\",\"ar\":\"مغالطة البيروكسيد الحر: لا ينطلق بيروكسيد حر في الخلية؛ يبقى الأكسجين مرتبطاً بالحديد مشكلاً وسيط أوكسو-حديد عالي الطاقة [Fe4+=O]•+.\",\"en\":\"Free peroxide fallacy: Catalysis does not leak free toxic H2O2 into the cytosol; oxygen stays coordinated to form the high-energy ferryl-oxo radical [Fe4+=O]•+.\"}},{\"id\":\"opt-2c\",\"text\":{\"tr\":\"Enzim doğrudan sitozoldeki serbest hidroksit (OH-) iyonlarını substratın C-H bağına transfer ederek nükleofilik yer değiştirme yapar.\",\"ar\":\"يقوم الإنزيم بنقل أيونات الهيدروكسيد الحرة (OH-) مباشرة من العصارة الخلوية لاستبدال رابطة C-H نكليوفيلياً.\",\"en\":\"The enzyme recruits ambient cytosolic hydroxide ions (OH-) to directly displace hydride at the inert C-H bond via nucleophilic substitution.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Nükleofilik hidroksit atağı yanılgısı: Alifatik ve aromatik C-H bağları non-polardır ve serbest OH- ile yer değiştirmez; CYP450 elektrofilik bir radikal hidrojen koparma mekanizması kullanır.\",\"ar\":\"مغالطة الاستبدال النكليوفيلي: روابط C-H غير قطبية وخاملة لا تتفاعل مع OH-؛ يعتمد CYP450 آلية جذرية إلكتروفيلية لانتزاع الهيدروجين.\",\"en\":\"Nucleophilic hydroxide fallacy: Inert non-polar C-H bonds do not undergo nucleophilic attack by OH-; CYP450 utilizes electrophilic radical hydrogen abstraction.\"}}]},\"technicalTerms\":[{\"term\":\"okso-ferril radikal katyonu\",\"arContext\":\"جذر الحديد الأوكسيدي الفيريل ([Fe4+=O]•+)\"},{\"term\":\"NADPH-sitokrom P450 redüktaz\",\"arContext\":\"إنزيم NADPH-P450 ريدوكتاز\"}],\"hints\":[{\"tr\":\"CYP450 enziminin merkezinde bir hem halkası ve bağlı Fe3+ iyonu bulunur.\",\"ar\":\"يحتوي مركز إنزيم CYP450 على حلقة هيم متصلة بأيون Fe3+.\",\"en\":\"The core of Cytochrome P450 contains a heme porphyrin ring coordinating an iron ion.\"},{\"tr\":\"Oksijenin aktive edilmesi için dışarıdan 2 elektrona (NADPH kofaktörüne) ihtiyaç vardır.\",\"ar\":\"يتطلب تنشيط الأكسجين زوجاً من الإلكترونات من كوفاكتور NADPH.\",\"en\":\"Activating oxygen requires 2 electrons delivered sequentially from NADPH.\"},{\"tr\":\"İki elektron ve iki proton su çıkarır; geriye kalan reaktif tür [Fe4+=O]•+ okso-ferril radikalidir.\",\"ar\":\"ينتج عن انتقال الإلكترونات والبروتونات خروج جزيء ماء وتشكل جذر [Fe4+=O]•+ فائق التفاعلية.\",\"en\":\"Water departs, leaving behind the reactive ferryl-oxo intermediate that attacks aliphatic bonds.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":14}],\"config\":{\"options\":[{\"id\":\"opt-2a\",\"text\":\"NADPH-P450 redüktazdan 2 elektron ve proton alarak O2'yi parçalar; aşırı reaktif demir(IV)-okso radikal katyonu ([Fe4+=O]•+) üretir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz kimyasal kavrayış! Slayt 14 ve Foye Bölüm 4'ün temeli: Sitokrom P450 katalitik döngüsünde Fe3+ heme önce substrate bağlanır, NADPH-redüktazdan ilk elektronu alarak Fe2+'ye indirgenir, O2 bağlar ve ikinci elektronla perokso köprüsü kurar. Su ayrılarak oluşan reaktif tür [Fe4+=O]•+ (okso-ferril radikali) inert C-H bağlarını hidroksilleme gücüne sahiptir.\"},{\"id\":\"opt-2b\",\"text\":\"Hem demirindeki Fe2+, moleküler oksijeni hidrojen peroksite (H2O2) indirger ve ortama serbest H2O2 salarak C-H bağını oksitler.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Serbest peroksit yanılgısı: Katalitik döngüde serbest peroksit hücresel ortama salınmaz; oksijen hem demirine koordineli kalır ve yüksek enerjili oksen-demir radikal ara ürünü [Fe4+=O]•+ oluşturur.\"},{\"id\":\"opt-2c\",\"text\":\"Enzim doğrudan sitozoldeki serbest hidroksit (OH-) iyonlarını substratın C-H bağına transfer ederek nükleofilik yer değiştirme yapar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Nükleofilik hidroksit atağı yanılgısı: Alifatik ve aromatik C-H bağları non-polardır ve serbest OH- ile yer değiştirmez; CYP450 elektrofilik bir radikal hidrojen koparma mekanizması kullanır.\"}],\"revealedOutcome\":{\"tr\":\"NADPH-P450 redüktazdan 2 elektron ve proton alarak O2'yi parçalar; aşırı reaktif demir(IV)-okso radikal katyonu ([Fe4+=O]•+) üretir.\",\"ar\":\"يستقبل إلكترونين من NADPH عبر إنزيم الريدوكتاز ليفصم O2، مولداً جذر حديد(IV)-أوكسو فائق التفاعلية ([Fe4+=O]•+).\",\"en\":\"It accepts 2 electrons from NADPH via P450 reductase and protons to cleave O2, generating a hyper-reactive iron(IV)-oxo radical cation ([Fe4+=O]•+).\"},\"explanation\":{\"tr\":\"Kusursuz kimyasal kavrayış! Slayt 14 ve Foye Bölüm 4'ün temeli: Sitokrom P450 katalitik döngüsünde Fe3+ heme önce substrate bağlanır, NADPH-redüktazdan ilk elektronu alarak Fe2+'ye indirgenir, O2 bağlar ve ikinci elektronla perokso köprüsü kurar. Su ayrılarak oluşan reaktif tür [Fe4+=O]•+ (okso-ferril radikali) inert C-H bağlarını hidroksilleme gücüne sahiptir.\",\"ar\":\"إدراك كيميائي فذ! الشريحة 14: يرتبط Fe3+ بالدواء، ويستقبل إلكتروناً أولاً ليصبح Fe2+، ثم يربط O2 ويستقبل الإلكترون الثاني. بانفصال الماء يتشكل جذر [Fe4+=O]•+ (الحديد الأوكسيدي الفيريل) القادر على هدرلة أعتى الروابط الأليفاتية.\",\"en\":\"Masterful biophysical insight! Slide 14: Substrate binding triggers first electron transfer reducing Fe3+ to Fe2+, binding O2, followed by a second electron and protonation to release H2O and yield the reactive oxo-ferryl radical cation [Fe4+=O]•+.\"}}},{\"id\":\"mc-mod5-les1-step-03\",\"stage\":\"intuition\",\"stageIndex\":3,\"type\":\"intuition\",\"title\":{\"tr\":\"Sezgisel Model: Oksijen Sıçraması (Radical Rebound)\",\"ar\":\"النموذج الحدسي: ارتداد الهيدروكسيل الجذري (Oxygen Rebound)\",\"en\":\"Mental Model: The Radical Rebound Mechanism\"},\"prompt\":{\"tr\":\"CYP450'nin okso-ferril türü [Fe4+=O]•+, ilaç molekülündeki C-H bağına nasıl saldırır? Karbon atomu ile oksijen arasındaki evlilik hangi adımlarla kurulur?\",\"ar\":\"كيف يهاجم جذر [Fe4+=O]•+ رابطة C-H في جزيء الدواء؟ ما هي الخطوات المجهرية التي تربط ذرة الكربون بالأكسجين؟\",\"en\":\"How does the activated oxo-ferryl species [Fe4+=O]•+ attack a drug's C-H bond? Through what microscopic sequence is the new C-OH bond forged?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-3a\",\"text\":{\"tr\":\"Önce C-H bağından bir hidrojen radikali (H•) kopararak Fe-OH ve karbon radikali (C•) üretir; ardından hidroksil grubu hemen geri sıçrayarak (rebound) C-OH bağını kurar.\",\"ar\":\"ينتزع أولاً جذر هيدروجين (H•) مشكلاً جذر كربونياً و Fe-OH، ثم يرتد جذر الهيدروكسيل فورياً ليرتبط بالكربون صانعاً C-OH.\",\"en\":\"It first abstracts a hydrogen radical (H•) to generate a carbon radical (C•) and Fe-OH, followed by instantaneous hydroxyl radical rebound to forge C-OH.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika sezgi! John Groves tarafından aydınlatılan 'Oksijen Sıçraması' (Oxygen Rebound) mekanizması: 1. Adım: Okso-ferril oksijeni ilaçtaki hidrojeni radikalik koparır (H-abstraction). 2. Adım: Oluşan karbon radikali kafes içinde bekleyen Fe-OH'taki •OH ile pikosaniyeler içinde birleşir (rebound).\",\"ar\":\"حدس علمي بارع! آلية ارتداد الأكسجين (Oxygen Rebound): الخطوة 1: ينتزع الأكسجين الفيريل ذرة هيدروجين كجذر حر مشكلاً كربوناً جذرياً. الخطوة 2: يرتد جذر •OH في أجزاء من البيكوثانية ليلتحم بالكربون مشكلاً الكحول.\",\"en\":\"Superb intuition! The Groves 'Oxygen Rebound' mechanism: Step 1 involves hydrogen atom abstraction yielding a transient carbon-centered radical and Fe(IV)-OH. Step 2 is ultrafast radical recombination (rebound) yielding the alcohol.\"}},{\"id\":\"opt-3b\",\"text\":{\"tr\":\"Oksijen atomu doğrudan C-C bağı arasına bir kama gibi girerek karbon atomlarını birbirinden ayırır ve molekülü ikiye böler.\",\"ar\":\"تدخل ذرة الأكسجين مباشرة كإسفين بين رابطة C-C فتفصل ذرتي الكربون وتقسم الجزيء إلى نصفين.\",\"en\":\"The oxygen atom wedges directly into C-C sigma bonds, cleaving the carbon skeleton into two smaller fragments.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"C-C klivaj yanılgısı: Standart monooksijenasyon C-C bağlarını koparmaz; hidroksilasyon yalnızca bir C-H bağını C-OH bağına dönüştürür (oksijen geri sıçrama mekanizması).\",\"ar\":\"مغالطة انشطار الهيكل الكربوني: الأكسدة الأحادية القياسية لا تكسر روابط C-C؛ الهدرلة تحول فقط رابطة C-H إلى C-OH عبر آلية الارتداد.\",\"en\":\"C-C cleavage fallacy: Standard monooxygenation preserves carbon frameworks; hydroxylation converts a C-H bond into C-OH via the oxygen rebound pathway.\"}},{\"id\":\"opt-3c\",\"text\":{\"tr\":\"Hem demiri substratın tüm elektronlarını çekerek ilacı serbest bir karbokatyon haline getirir; ortamdaki su molekülü bu karbokatyonu yakalar.\",\"ar\":\"يسحب حديد الهيم جميع الإلكترونات من الركيزة محولاً إياها إلى كربوكاتيون حر تلتقطه جزيئات الماء المحيطة.\",\"en\":\"Heme iron strips two electrons to form a free carbocation intermediate that is subsequently trapped by bulk solvent water molecules.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Karbokatyon ve su hidrasyonu yanılgısı: CYP450 oksidasyonunda oksijen kaynağı su (H2O) değil, moleküler oksijendir (O2); ara ürün ise karbokatyon değil serbest radikaldir.\",\"ar\":\"مغالطة الإماهة بالماء: مصدر الأكسجين في CYP450 هو الأكسجين الجزيئي O2 وليس ماء الوسط H2O، والوسيط جذري وليس كربوكاتيون.\",\"en\":\"Carbocation solvent hydration fallacy: The incorporated oxygen originates from molecular O2, not water (H2O), and proceeds via radical rebound, not carbocations.\"}}]},\"technicalTerms\":[{\"term\":\"oksijen sıçraması (oxygen rebound)\",\"arContext\":\"ارتداد الأكسجين الجذري (oxygen rebound)\"},{\"term\":\"karbon radikali ara ürünü\",\"arContext\":\"مركب الكربون الجذري الوسيط\"}],\"hints\":[{\"tr\":\"Okso-ferril radikali hidrojen açlığı çeken güçlü bir kimyasal türdür.\",\"ar\":\"جذر الأوكسو فيريل جائع لانتزاع الهيدروجين بشراهة كيميائية بالغة.\",\"en\":\"The oxo-ferryl radical possesses an immense thermodynamic drive to abstract hydrogen.\"},{\"tr\":\"C-H bağındaki hidrojen bir elektronuyla birlikte oksijene çekildiğinde karbon üzerinde ne kalır?\",\"ar\":\"عندما يُنتزع الهيدروجين بإلكترونه نحو الأكسجين، ماذا يتبقى على ذرة الكربون؟\",\"en\":\"When hydrogen is stripped with one electron, an unpaired electron remains on carbon.\"},{\"tr\":\"Karbon radikali oluştuktan hemen sonra demire bağlı •OH grubu karbona geri sıçrayarak C-OH bağını kapatır.\",\"ar\":\"فور تشكل جذر الكربون، يرتد جذر •OH من الحديد ليلتحم بالكربون مشكلاً C-OH.\",\"en\":\"The iron-bound •OH rapidly rebounds onto the transient carbon radical to close the C-OH bond.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":14}],\"config\":{\"options\":[{\"id\":\"opt-3a\",\"text\":\"Önce C-H bağından bir hidrojen radikali (H•) kopararak Fe-OH ve karbon radikali (C•) üretir; ardından hidroksil grubu hemen geri sıçrayarak (rebound) C-OH bağını kurar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika sezgi! John Groves tarafından aydınlatılan 'Oksijen Sıçraması' (Oxygen Rebound) mekanizması: 1. Adım: Okso-ferril oksijeni ilaçtaki hidrojeni radikalik koparır (H-abstraction). 2. Adım: Oluşan karbon radikali kafes içinde bekleyen Fe-OH'taki •OH ile pikosaniyeler içinde birleşir (rebound).\"},{\"id\":\"opt-3b\",\"text\":\"Oksijen atomu doğrudan C-C bağı arasına bir kama gibi girerek karbon atomlarını birbirinden ayırır ve molekülü ikiye böler.\",\"isCorrect\":false,\"misconceptionFeedback\":\"C-C klivaj yanılgısı: Standart monooksijenasyon C-C bağlarını koparmaz; hidroksilasyon yalnızca bir C-H bağını C-OH bağına dönüştürür (oksijen geri sıçrama mekanizması).\"},{\"id\":\"opt-3c\",\"text\":\"Hem demiri substratın tüm elektronlarını çekerek ilacı serbest bir karbokatyon haline getirir; ortamdaki su molekülü bu karbokatyonu yakalar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Karbokatyon ve su hidrasyonu yanılgısı: CYP450 oksidasyonunda oksijen kaynağı su (H2O) değil, moleküler oksijendir (O2); ara ürün ise karbokatyon değil serbest radikaldir.\"}],\"revealedOutcome\":{\"tr\":\"Önce C-H bağından bir hidrojen radikali (H•) kopararak Fe-OH ve karbon radikali (C•) üretir; ardından hidroksil grubu hemen geri sıçrayarak (rebound) C-OH bağını kurar.\",\"ar\":\"ينتزع أولاً جذر هيدروجين (H•) مشكلاً جذر كربونياً و Fe-OH، ثم يرتد جذر الهيدروكسيل فورياً ليرتبط بالكربون صانعاً C-OH.\",\"en\":\"It first abstracts a hydrogen radical (H•) to generate a carbon radical (C•) and Fe-OH, followed by instantaneous hydroxyl radical rebound to forge C-OH.\"},\"explanation\":{\"tr\":\"Harika sezgi! John Groves tarafından aydınlatılan 'Oksijen Sıçraması' (Oxygen Rebound) mekanizması: 1. Adım: Okso-ferril oksijeni ilaçtaki hidrojeni radikalik koparır (H-abstraction). 2. Adım: Oluşan karbon radikali kafes içinde bekleyen Fe-OH'taki •OH ile pikosaniyeler içinde birleşir (rebound).\",\"ar\":\"حدس علمي بارع! آلية ارتداد الأكسجين (Oxygen Rebound): الخطوة 1: ينتزع الأكسجين الفيريل ذرة هيدروجين كجذر حر مشكلاً كربوناً جذرياً. الخطوة 2: يرتد جذر •OH في أجزاء من البيكوثانية ليلتحم بالكربون مشكلاً الكحول.\",\"en\":\"Superb intuition! The Groves 'Oxygen Rebound' mechanism: Step 1 involves hydrogen atom abstraction yielding a transient carbon-centered radical and Fe(IV)-OH. Step 2 is ultrafast radical recombination (rebound) yielding the alcohol.\"}}},{\"id\":\"mc-mod5-les1-step-04\",\"stage\":\"visual_explanation\",\"stageIndex\":4,\"type\":\"visual_explanation\",\"title\":{\"tr\":\"Aromatik Oksidasyon ve NIH Kayması Mekanizması\",\"ar\":\"الأكسدة العطرية وآلية انزياح NIH\",\"en\":\"Aromatic Oxygenation & The NIH Hydride Shift\"},\"prompt\":{\"tr\":\"Benzen halkası CYP450 ile oksitlendiğinde önce kararsız bir aren oksit (epoksit) oluşur. Epoksit açılırken hidrojen atomu neden çözeltiye fırlamak yerine yan karbona göç eder (NIH Kayması)?\",\"ar\":\"عند أكسدة حلقة البنزين بـ CYP450 يتشكل أكسيد الآرين (إيبوكسيد). عند فتح الإيبوكسيد، لماذا ينتقل الهيدروجين للكربون المجاور (انزياح NIH) بدلاً من الانفصال للمحلول؟\",\"en\":\"When a benzene ring is oxidized by CYP450, an unstable arene oxide epoxide forms. As it opens, why does the hydrogen atom migrate to the adjacent carbon (NIH Shift) rather than releasing into solvent?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-4a\",\"text\":{\"tr\":\"Epoksit açıldığında oluşan karbokatyonda pozitif yükü nötralize etmek için 1,2-hidrit göçü gerçekleşir; ardından keto-enol tautomerisi fenolü oluşturur.\",\"ar\":\"يؤدي فتح الإيبوكسيد لتشكل كربوكاتيون يفرض هجرة هيدريد 1،2 لمعادلة الشحنة، يليه تحول كيتو-إينول مشكلاً الفينول المستقر.\",\"en\":\"Epoxide cleavage creates a carbocation intermediate that triggers an intramolecular 1,2-hydride shift to relieve charge, followed by keto-enol tautomerism to phenol.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz mekanizma! Slayt 16 verisi: Aren oksit halkası açıldığında komşu karbonda karbokatyon oluşur. Ulusal Sağlık Enstitüleri'nde (NIH) döteryum izotopuyla kanıtlanan bu olayda, hidrojen atomu 1,2-kayması ile komşu karbona geçer. Oluşan dienon ara ürünü hızla enolize olarak (aromatikleşerek) kararlı fenole dönüşür.\",\"ar\":\"تحليل كيميائي استثنائي! الشريحة 16: عند فتح حلقة أكسيد الآرين ينشأ كربوكاتيون مجاور. كما أثبتت تجارب النظائر في NIH، يهاجر الهيدروجين انتقالاً داخلياً (1,2-hydride shift)، ثم يستعيد المركب عطريته بالتحول الإينولي السريع إلى فينول.\",\"en\":\"Flawless mechanistic derivation! Slide 16: Arene oxide ring opening creates a zwitterionic carbocation. Intramolecular 1,2-hydride migration (the NIH shift, proven by deuterium labeling) generates a cyclohexadienone that enolizes to restore aromatic stability.\"}},{\"id\":\"opt-4b\",\"text\":{\"tr\":\"Epoksit halkası açıldıktan sonra komşu karbondaki hidrojen doğrudan çözeltiye bir proton (H+) olarak ayrılır; hiçbir atom göç etmez.\",\"ar\":\"بعد انفتاح حلقة الإيبوكسيد، ينفصل هيدروجين الكربون المجاور كبروتون حر في المحلول دون حدوث أي هجرة للذرات.\",\"en\":\"Upon epoxide opening, the adjacent hydrogen departs directly into bulk solution as a free proton without intramolecular migration.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Doğrudan proton kaybı yanılgısı: Slayt 16: İzotop deneyleri hidrojenin çözeltiye gitmediğini, pozitif yüklü komşu karbona göç ettiğini (NIH 1,2-hidrit kayması) kanıtlamıştır.\",\"ar\":\"مغالطة الفقد المباشر للبروتون: شريحة 16: أثبتت النظائر أن الهيدروجين لا يغادر للمحلول بل يهاجر للكربون المجاور (هجرة NIH الهيدريدية 1،2).\",\"en\":\"Direct proton departure fallacy: Slide 16: Isotope tracing proves hydrogen does not leave into solvent; it migrates to adjacent carbocation (NIH 1,2-hydride shift).\"}},{\"id\":\"opt-4c\",\"text\":{\"tr\":\"Aren oksit halkası doğrudan epoksit hidrolaz olmaksızın dioksetana oksitlenir ve benzen halkası fenol oluşturmadan parçalanır.\",\"ar\":\"تتأكسد حلقة الأرين أوكسيد تلقائياً إلى ديوكسيتان وينشطر البنزين دون تشكل أي فينول مستقر.\",\"en\":\"The arene oxide oxidizes spontaneously into a dioxetane intermediate, cleaving the benzene ring without generating phenol.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Halka parçalanma yanılgısı: Aren oksit halka parçalanmasına uğramaz; keto-enol tautomerisi yoluyla kararlı fenol yapısına geri döner.\",\"ar\":\"مغالطة تفكك الحلقة: الأرين أوكسيد لا يفكك الحلقة العطرية بل يعيد تشكيل الفينول المستقر عبر التماكب الكيتوني-الإينولي.\",\"en\":\"Ring fragmentation fallacy: Arene oxides do not fragment the aromatic nucleus; keto-enol tautomerism re-aromatizes the system to stable phenol.\"}}]},\"technicalTerms\":[{\"term\":\"aren oksit (epoksit)\",\"arContext\":\"أكسيد الآرين (arene oxide)\"},{\"term\":\"NIH kayması (1,2-hidrit göçü)\",\"arContext\":\"انزياح NIH (هجرة هيدريد 1,2)\"}],\"hints\":[{\"tr\":\"CYP450 benzen halkasına saldırdığında ilk ürün 3 üyeli bir aren oksit halkasıdır.\",\"ar\":\"أول ناتج لهجوم CYP450 على البنزين هو حلقة أكسيد الآرين الثلاثية.\",\"en\":\"CYP attack on an aromatic bond produces a strained 3-membered arene oxide.\"},{\"tr\":\"Aren oksit halkası açıldığında yanındaki karbonda pozitif yük (karbokatyon) belirir.\",\"ar\":\"يولد انفتاح حلقة الإيبوكسيد شحنة موجبة (كربوكاتيون) على ذرة الكربون المجاورة.\",\"en\":\"Ring opening leaves an electron-deficient carbocation on the adjacent ring carbon.\"},{\"tr\":\"Pozitif yüke komşu karbon üzerindeki hidrojen 1,2-göçü yapar (NIH kayması) ve keto formu enolize olarak fenole döner.\",\"ar\":\"يهاجر الهيدروجين هجرة 1،2 لمعادلة الكربوكاتيون، ثم يستعيد المركب عطريته متحولاً إلى فينول.\",\"en\":\"Intramolecular 1,2-hydride shift neutralizes the cation, forming a ketone that tautomerizes to phenol.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":16}],\"config\":{\"options\":[{\"id\":\"opt-4a\",\"text\":\"Epoksit açıldığında oluşan karbokatyonda pozitif yükü nötralize etmek için 1,2-hidrit göçü gerçekleşir; ardından keto-enol tautomerisi fenolü oluşturur.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz mekanizma! Slayt 16 verisi: Aren oksit halkası açıldığında komşu karbonda karbokatyon oluşur. Ulusal Sağlık Enstitüleri'nde (NIH) döteryum izotopuyla kanıtlanan bu olayda, hidrojen atomu 1,2-kayması ile komşu karbona geçer. Oluşan dienon ara ürünü hızla enolize olarak (aromatikleşerek) kararlı fenole dönüşür.\"},{\"id\":\"opt-4b\",\"text\":\"Epoksit halkası açıldıktan sonra komşu karbondaki hidrojen doğrudan çözeltiye bir proton (H+) olarak ayrılır; hiçbir atom göç etmez.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Doğrudan proton kaybı yanılgısı: Slayt 16: İzotop deneyleri hidrojenin çözeltiye gitmediğini, pozitif yüklü komşu karbona göç ettiğini (NIH 1,2-hidrit kayması) kanıtlamıştır.\"},{\"id\":\"opt-4c\",\"text\":\"Aren oksit halkası doğrudan epoksit hidrolaz olmaksızın dioksetana oksitlenir ve benzen halkası fenol oluşturmadan parçalanır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Halka parçalanma yanılgısı: Aren oksit halka parçalanmasına uğramaz; keto-enol tautomerisi yoluyla kararlı fenol yapısına geri döner.\"}],\"revealedOutcome\":{\"tr\":\"Epoksit açıldığında oluşan karbokatyonda pozitif yükü nötralize etmek için 1,2-hidrit göçü gerçekleşir; ardından keto-enol tautomerisi fenolü oluşturur.\",\"ar\":\"يؤدي فتح الإيبوكسيد لتشكل كربوكاتيون يفرض هجرة هيدريد 1،2 لمعادلة الشحنة، يليه تحول كيتو-إينول مشكلاً الفينول المستقر.\",\"en\":\"Epoxide cleavage creates a carbocation intermediate that triggers an intramolecular 1,2-hydride shift to relieve charge, followed by keto-enol tautomerism to phenol.\"},\"explanation\":{\"tr\":\"Kusursuz mekanizma! Slayt 16 verisi: Aren oksit halkası açıldığında komşu karbonda karbokatyon oluşur. Ulusal Sağlık Enstitüleri'nde (NIH) döteryum izotopuyla kanıtlanan bu olayda, hidrojen atomu 1,2-kayması ile komşu karbona geçer. Oluşan dienon ara ürünü hızla enolize olarak (aromatikleşerek) kararlı fenole dönüşür.\",\"ar\":\"تحليل كيميائي استثنائي! الشريحة 16: عند فتح حلقة أكسيد الآرين ينشأ كربوكاتيون مجاور. كما أثبتت تجارب النظائر في NIH، يهاجر الهيدروجين انتقالاً داخلياً (1,2-hydride shift)، ثم يستعيد المركب عطريته بالتحول الإينولي السريع إلى فينول.\",\"en\":\"Flawless mechanistic derivation! Slide 16: Arene oxide ring opening creates a zwitterionic carbocation. Intramolecular 1,2-hydride migration (the NIH shift, proven by deuterium labeling) generates a cyclohexadienone that enolizes to restore aromatic stability.\"}}},{\"id\":\"mc-mod5-les1-step-05\",\"stage\":\"interactive_artifact\",\"stageIndex\":5,\"type\":\"metabolism_map\",\"widgetType\":\"MetabolismMap\",\"title\":{\"tr\":\"İnteraktif Metabolizma Haritası: Diazepam Biyotransformasyonu\",\"ar\":\"خريطة الاستقلاب التفاعلية: التحول الحيوي للديازيبام\",\"en\":\"Interactive Metabolism Map: Diazepam Biotransformation Pathways\"},\"prompt\":{\"tr\":\"Diazepam molekülünün Faz I metabolik bölgelerini inceleyin. İlacın sedatif etki süresini 100 saate kadar uzatan majör aktif metabolit yolunu (N1-demetilasyon) harita üzerinde tespit edin.\",\"ar\":\"استكشف مواقع استقلاب الديازيبام في المرحلة الأولى. حدد المسار الرئيسي المسؤول عن تكوين المستقلب الفعال طويل الأمد (نزع الميثيل N1).\",\"en\":\"Explore the Phase I metabolic soft-spots on Diazepam. Identify the primary bioactivation site responsible for generating the long-acting sedative metabolite Nordiazepam.\"},\"predictThenReveal\":false,\"config\":{\"drugName\":\"Diazepam\",\"prompt\":\"Nordiazepam aktif metabolitini oluşturan N1-demetilasyon bölgesini seçin.\",\"moleculeSvgDescription\":\"Diazepam 1,4-benzodiazepin çekirdeği, N1-metil ve C3 pozisyonları\",\"sites\":[{\"id\":\"site_n1_demethylation\",\"label\":\"N1-Demetilasyon\",\"x\":120,\"y\":60,\"enzyme\":\"CYP2C19 / CYP3A4\",\"phase\":\"Phase I\",\"reactionType\":\"Oksidatif N-Dealkilasyon\",\"metaboliteOutcome\":\"Aktif metabolit Nordiazepam (t1/2 ≈ 50-100 saat) oluşturarak anksiyolitik etki süresini günlerce uzatır.\",\"toxicityFlag\":\"active_metabolite\",\"isTargetSite\":true},{\"id\":\"site_c3_hydroxylation\",\"label\":\"C3-Alifatik Hidroksilasyon\",\"x\":260,\"y\":120,\"enzyme\":\"CYP3A4\",\"phase\":\"Phase I\",\"reactionType\":\"Alifatik C-Hidroksilasyon\",\"metaboliteOutcome\":\"Temazepam ve takiben Oksazepam aktif metabolitlerine dönüşür; Faz II glukuronidasyonu için hazır -OH açığa çıkar.\",\"toxicityFlag\":\"active_metabolite\",\"isTargetSite\":false},{\"id\":\"site_c4_aromatic_oxidation\",\"label\":\"C4'-Aromatik Hidroksilasyon\",\"x\":380,\"y\":200,\"enzyme\":\"CYP2C19\",\"phase\":\"Phase I\",\"reactionType\":\"Aromatik Oksidasyon (NIH Kayması)\",\"metaboliteOutcome\":\"4'-Hidroksidiazepam fenolik metabolitini oluşturur; hızla inaktive edilerek atılır.\",\"toxicityFlag\":\"non_toxic\",\"isTargetSite\":false}],\"source\":{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":20},\"explanation\":\"CYP2C19 ve CYP3A4 diazepamın N1-metil grubunu oksitleyerek formaldehit koparır ve nordiazepama dönüştürür. Nordiazepamın eliminasyon yarı ömrü 50-100 saat olup yaşlılarda kümülatif sedasyona yol açar.\"},\"widget\":{\"type\":\"MetabolismMap\",\"config\":{\"drugName\":\"Diazepam\",\"prompt\":\"Nordiazepam aktif metabolitini oluşturan N1-demetilasyon bölgesini seçin.\",\"moleculeSvgDescription\":\"Diazepam 1,4-benzodiazepin çekirdeği, N1-metil ve C3 pozisyonları\",\"sites\":[{\"id\":\"site_n1_demethylation\",\"label\":\"N1-Demetilasyon\",\"x\":120,\"y\":60,\"enzyme\":\"CYP2C19 / CYP3A4\",\"phase\":\"Phase I\",\"reactionType\":\"Oksidatif N-Dealkilasyon\",\"metaboliteOutcome\":\"Aktif metabolit Nordiazepam (t1/2 ≈ 50-100 saat) oluşturarak anksiyolitik etki süresini günlerce uzatır.\",\"toxicityFlag\":\"active_metabolite\",\"isTargetSite\":true},{\"id\":\"site_c3_hydroxylation\",\"label\":\"C3-Alifatik Hidroksilasyon\",\"x\":260,\"y\":120,\"enzyme\":\"CYP3A4\",\"phase\":\"Phase I\",\"reactionType\":\"Alifatik C-Hidroksilasyon\",\"metaboliteOutcome\":\"Temazepam ve takiben Oksazepam aktif metabolitlerine dönüşür; Faz II glukuronidasyonu için hazır -OH açığa çıkar.\",\"toxicityFlag\":\"active_metabolite\",\"isTargetSite\":false},{\"id\":\"site_c4_aromatic_oxidation\",\"label\":\"C4'-Aromatik Hidroksilasyon\",\"x\":380,\"y\":200,\"enzyme\":\"CYP2C19\",\"phase\":\"Phase I\",\"reactionType\":\"Aromatik Oksidasyon (NIH Kayması)\",\"metaboliteOutcome\":\"4'-Hidroksidiazepam fenolik metabolitini oluşturur; hızla inaktive edilerek atılır.\",\"toxicityFlag\":\"non_toxic\",\"isTargetSite\":false}],\"source\":{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":20},\"explanation\":\"CYP2C19 ve CYP3A4 diazepamın N1-metil grubunu oksitleyerek formaldehit koparır ve nordiazepama dönüştürür. Nordiazepamın eliminasyon yarı ömrü 50-100 saat olup yaşlılarda kümülatif sedasyona yol açar.\"}},\"technicalTerms\":[{\"term\":\"oksidatif N-demetilasyon\",\"arContext\":\"نزع الميثيل النيتروجيني الأكسيدي\"},{\"term\":\"aktif metabolit birikimi\",\"arContext\":\"تراكم المستقلبات الفعالة\"}],\"hints\":[{\"tr\":\"Nordiazepam, diazepamın N1 pozisyonundaki metil (-CH3) grubunun ayrılmış halidir.\",\"ar\":\"النورديازيبام هو ديازيبام فاقد لمجموعة الميثيل (-CH3) عند الموضع N1.\",\"en\":\"Nordiazepam is des-methyl diazepam lacking the N1 methyl substituent.\"},{\"tr\":\"CYP2C19 ve CYP3A4 heteroatoma komşu metil grubunu oksitleyerek formaldehit açığa çıkarır.\",\"ar\":\"تؤكسد إنزيمات CYP مجموعة الميثيل المجاورة للنيتروجين محررة فورمالدهيد.\",\"en\":\"CYP enzymes oxygenate the methyl carbon adjacent to nitrogen, expelling formaldehyde.\"},{\"tr\":\"N1-Demetilasyon bölgesi haritada hedef aktif metabolit yoludur.\",\"ar\":\"موقع نزع الميثيل N1 هو مسار المستقلب الفعال المستهدف على الخريطة.\",\"en\":\"The N1-demethylation locus is the primary target active metabolite pathway.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":20}]},{\"id\":\"mc-mod5-les1-step-06\",\"stage\":\"guided_discovery\",\"stageIndex\":6,\"type\":\"guided_discovery\",\"title\":{\"tr\":\"Rehberli Keşif: Oksidatif Dealkilasyonun Kararsız Ara Ürünü\",\"ar\":\"استكشاف موجه: المركب الوسيط غير المستقر لنزع الألكيل الأكسيدي\",\"en\":\"Guided Discovery: The Unstable Intermediate of Dealkylation\"},\"prompt\":{\"tr\":\"CYP450 bir N-metil veya O-etil grubunu koparırken heteroatom-karbon bağını doğrudan makas gibi kesmez. Molekülde önce hangi kararsız ara ürün oluşur ve neden kendiliğinden çöker?\",\"ar\":\"عندما يقتطع CYP450 مجموعة N-ميثيل أو O-إيثيل، فإنه لا يقطع الرابطة مباشرة كمقص. ما هو المركب الوسيط غير المستقر المتشكل ولماذا ينشطر ذاتياً؟\",\"en\":\"When CYP450 removes an N-methyl or O-ethyl group, it does not directly snip the heteroatom-carbon bond like a pair of scissors. What unstable intermediate forms, and why does it collapse spontaneously?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-6a\",\"text\":{\"tr\":\"Alkil grubunun alfa-karbonu hidroksillenerek kararsız bir hemiaminal veya hemiasetal oluşur; serbest elektron çifti itmesiyle aldehit koparak ayrılır.\",\"ar\":\"يهدرل كربون ألفا مشكلاً هيمي أمينال أو هيمي أسيتال غير مستقر؛ فينشطر تلقائياً بطرد الألدهيد بتدافع الإلكترونات.\",\"en\":\"The alkyl alpha-carbon is hydroxylated to an unstable hemiaminal or hemiacetal; lone-pair repulsion triggers spontaneous collapse to an aldehyde and the dealkylated drug.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel kimyasal keşif! Slayt 20 kuralı: R-X-CH3 önce R-X-CH2OH'a (alfa-hidroksialkil) dönüşür. Aynı karbona hem heteroatom (N/O) hem -OH bağlı olması termodinamik olarak son derece kararsızdır; heteroatomun serbest elektron çifti karbon-heteroatom çift bağı oluştururken aldehit (formaldehit) serbest kalır.\",\"ar\":\"اكتشاف كيميائي استثنائي! قاعدة الشريحة 20: يتحول R-X-CH3 إلى R-X-CH2OH. اجتماع الهيدروكسيل وذرة النيتروجين أو الأكسجين على نفس الكربون يجعل البنية غير مستقرة، فتطرد فورمالدهيد تلقائياً.\",\"en\":\"Brilliant chemical insight! Slide 20 principle: R-X-CH3 is first oxygenated to an alpha-hydroxyalkyl intermediate [R-X-CH2OH]. Bearing both a heteroatom and an OH on the same carbon creates severe thermodynamic instability, spontaneously eliminating an aldehyde.\"}},{\"id\":\"opt-6b\",\"text\":{\"tr\":\"Enzim heteroatom ile alkil grubu arasındaki bağı doğrudan homolitik olarak koparır ve serbest metil radikalleri açığa çıkarır.\",\"ar\":\"يقوم الإنزيم بكسر الرابطة بين الذرة غير المتجانسة ومجموعة الألكيل كسرًا متجانساً مطلقاً جذور ميثيل حرة.\",\"en\":\"The enzyme directly homolytically cleaves the heteroatom-carbon bond, releasing highly reactive free methyl radicals into solution.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Doğrudan heteroatom bağı kopması yanılgısı: Slayt 20: Dealkilasyon doğrudan heteroatom bağına saldırmaz; alkilin alfa-karbonunu hidroksilleyerek kararsız hemiaminal/hemiasetal üzerinden parçalanır.\",\"ar\":\"مغالطة الكسر المباشر للرابطة: شريحة 20: لا يهاجم الإنزيم الرابطة مباشرة، بل يهدرل كربون ألفا مشكلاً وسيط هيمي أمينال غير مستقر يتفكك تلقائياً.\",\"en\":\"Direct bond cleavage fallacy: Slide 20: Dealkylation does not attack the heteroatom bond directly; alpha-carbon hydroxylation forms an unstable hemiaminal/hemiacetal intermediate.\"}},{\"id\":\"opt-6c\",\"text\":{\"tr\":\"Dealkilasyon reaksiyonunda alkil grubu önce karboksilik aside dönüşür, ardından dekarboksilaz enzimi ile CO2 olarak uçar.\",\"ar\":\"تتحول مجموعة الألكيل أولاً إلى حمض كربوكسيلي كامل ثم ينزع إنزيم الديكاربوكسيلاز غاز CO2.\",\"en\":\"The alkyl substituent is fully oxidized to a carboxylic acid before a decarboxylase cleaves it as carbon dioxide gas.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Dekarboksilasyon yanılgısı: Alkil grupları karboksilik aside gitmez; alfa-karbon hidroksilasyonu sonucu aldehit (formaldehit veya asetaldehit) olarak açığa çıkar.\",\"ar\":\"مغالطة نزع الكربوكسيل: لا تتحول السلسلة لحمض كربوكسيلي، بل تتحرر كألدهيد (فورمالدهيد أو أسيتالدهيد) عند انهيار وسيط ألفا-هيدروكسي.\",\"en\":\"Decarboxylation fallacy: Alkyl fragments are liberated as aldehydes (formaldehyde, acetaldehyde) upon alpha-hydroxy intermediate collapse, not as CO2.\"}}]},\"technicalTerms\":[{\"term\":\"hemiaminal / carbinolamine\",\"arContext\":\"كاربينول أمين / هيمي أمينال (carbinolamine)\"},{\"term\":\"spontan heterolitik parçalanma\",\"arContext\":\"الانشطار غير المتجانس التلقائي\"}],\"hints\":[{\"tr\":\"Bir karbon atomuna aynı anda hem azot (veya oksijen) hem de -OH bağlı olduğunda ne olur?\",\"ar\":\"ماذا يحدث عند ارتباط ذرة نيتروجين (أو أكسجين) ومجموعة -OH بنفس ذرة الكربون؟\",\"en\":\"What happens when a single carbon bears both a heteroatom (N or O) and an -OH group?\"},{\"tr\":\"Oluşan yapı bir hemiasetal veya hemiaminaldir ve oda sıcaklığında hızla çöker.\",\"ar\":\"البنية المتشكلة هي هيمي أسيتال أو هيمي أمينال غير مستقرة وتتفكك فوراً.\",\"en\":\"The resulting geminal adduct is inherently unstable and undergoes rapid expulsion.\"},{\"tr\":\"Heteroatoma komşu alfa-hidroksilasyon tamamlandığında formaldehit ayrılır ve dealkile ürün açığa çıkar.\",\"ar\":\"بانفصال الفورمالدهيد الناتج عن هدرلة كربون ألفا، يتحرر المركب منزوع الألكيل.\",\"en\":\"Alpha-hydroxylation spontaneously eliminates an aldehyde, unmasking the parent heteroatom.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":20}],\"config\":{\"options\":[{\"id\":\"opt-6a\",\"text\":\"Alkil grubunun alfa-karbonu hidroksillenerek kararsız bir hemiaminal veya hemiasetal oluşur; serbest elektron çifti itmesiyle aldehit koparak ayrılır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel kimyasal keşif! Slayt 20 kuralı: R-X-CH3 önce R-X-CH2OH'a (alfa-hidroksialkil) dönüşür. Aynı karbona hem heteroatom (N/O) hem -OH bağlı olması termodinamik olarak son derece kararsızdır; heteroatomun serbest elektron çifti karbon-heteroatom çift bağı oluştururken aldehit (formaldehit) serbest kalır.\"},{\"id\":\"opt-6b\",\"text\":\"Enzim heteroatom ile alkil grubu arasındaki bağı doğrudan homolitik olarak koparır ve serbest metil radikalleri açığa çıkarır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Doğrudan heteroatom bağı kopması yanılgısı: Slayt 20: Dealkilasyon doğrudan heteroatom bağına saldırmaz; alkilin alfa-karbonunu hidroksilleyerek kararsız hemiaminal/hemiasetal üzerinden parçalanır.\"},{\"id\":\"opt-6c\",\"text\":\"Dealkilasyon reaksiyonunda alkil grubu önce karboksilik aside dönüşür, ardından dekarboksilaz enzimi ile CO2 olarak uçar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Dekarboksilasyon yanılgısı: Alkil grupları karboksilik aside gitmez; alfa-karbon hidroksilasyonu sonucu aldehit (formaldehit veya asetaldehit) olarak açığa çıkar.\"}],\"revealedOutcome\":{\"tr\":\"Alkil grubunun alfa-karbonu hidroksillenerek kararsız bir hemiaminal veya hemiasetal oluşur; serbest elektron çifti itmesiyle aldehit koparak ayrılır.\",\"ar\":\"يهدرل كربون ألفا مشكلاً هيمي أمينال أو هيمي أسيتال غير مستقر؛ فينشطر تلقائياً بطرد الألدهيد بتدافع الإلكترونات.\",\"en\":\"The alkyl alpha-carbon is hydroxylated to an unstable hemiaminal or hemiacetal; lone-pair repulsion triggers spontaneous collapse to an aldehyde and the dealkylated drug.\"},\"explanation\":{\"tr\":\"Mükemmel kimyasal keşif! Slayt 20 kuralı: R-X-CH3 önce R-X-CH2OH'a (alfa-hidroksialkil) dönüşür. Aynı karbona hem heteroatom (N/O) hem -OH bağlı olması termodinamik olarak son derece kararsızdır; heteroatomun serbest elektron çifti karbon-heteroatom çift bağı oluştururken aldehit (formaldehit) serbest kalır.\",\"ar\":\"اكتشاف كيميائي استثنائي! قاعدة الشريحة 20: يتحول R-X-CH3 إلى R-X-CH2OH. اجتماع الهيدروكسيل وذرة النيتروجين أو الأكسجين على نفس الكربون يجعل البنية غير مستقرة، فتطرد فورمالدهيد تلقائياً.\",\"en\":\"Brilliant chemical insight! Slide 20 principle: R-X-CH3 is first oxygenated to an alpha-hydroxyalkyl intermediate [R-X-CH2OH]. Bearing both a heteroatom and an OH on the same carbon creates severe thermodynamic instability, spontaneously eliminating an aldehyde.\"}}},{\"id\":\"mc-mod5-les1-step-07\",\"stage\":\"formal_explanation\",\"stageIndex\":7,\"type\":\"formal_explanation\",\"title\":{\"tr\":\"Alifatik Oksidasyon: Omega vs (Omega-1) Seçiciliği\",\"ar\":\"الأكسدة الأليفاتية: انتقائية أوميغا مقابل (أوميغا-1)\",\"en\":\"Aliphatic Oxidation: Omega vs. (Omega-1) Regioselectivity\"},\"prompt\":{\"tr\":\"Pentobarbital gibi barbitüratların alifatik yan zincirleri karaciğerde oksitlenirken, neden uçtaki primer metil karbonundan (omega) ziyade sondan bir önceki sekonder karbon (omega-1) baskın olarak hidroksillenir?\",\"ar\":\"عند أكسدة السلسلة الأليفاتية للباربيتورات (كالبنتوباربيتال)، لماذا تُهدرل ذرة الكربون الثانوية قبل الأخيرة (أوميغا-1) مفضلة على الميثيل الطرفي (أوميغا)؟\",\"en\":\"When the aliphatic side chains of barbiturates (e.g., pentobarbital) undergo hepatic oxidation, why does secondary (omega-1) hydroxylation strongly predominate over terminal (omega) methyl oxidation?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-7a\",\"text\":{\"tr\":\"Sekonder C-H bağından hidrojen koparılmasıyla oluşan sekonder alkil radikali, primer radikale göre termodinamik olarak çok daha kararlıdır.\",\"ar\":\"الجذر الكربوني الثانوي الناتج عن نزع هيدروجين من C-H ثانوية أكثر استقراراً ديناميكياً وحرارياً من الجذر الأولي.\",\"en\":\"Hydrogen abstraction from a secondary methylene C-H yields a secondary alkyl radical, which is thermodynamically far more stable than a primary radical.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Tam bir fiziksel organik kimya zaferi! Slayt 15 ilkesi: C-H bağ enerjileri tersiyer < sekonder < primer sırasını izler. CYP450 okso-ferril radikali en kolay koparabileceği bağı tercih eder; sekonder C-H bağının bağ disosiasyon enerjisi (~395 kJ/mol) primer metilden (~420 kJ/mol) düşüktür. Bu nedenle (omega-1) sekonder alkol metaboliti açık ara baskındır.\",\"ar\":\"انتصار كيميائي فيزيائي فذ! الشريحة 15: طاقة تفكك روابط C-H تتبع الترتيب: ثالثي < ثانوي < أولي. طاقة كسر الرابطة الثانوية (~395 kJ/mol) أقل من الميثيل الطرفي (~420 kJ/mol)، مما يجعل جذر (أوميغا-1) أسهل تشكلاً ومستقلبه هو السائد.\",\"en\":\"Physical organic chemistry triumph! Slide 15 principle: C-H bond dissociation energies follow 3° < 2° < 1°. Abstracting a secondary hydrogen requires ~25 kJ/mol less energy than primary C-H, making the (omega-1) radical pathway dramatically favored.\"}},{\"id\":\"opt-7b\",\"text\":{\"tr\":\"Terminal metil grubu sterik olarak en engelli bölgedir, bu yüzden enzim oraya asla yanaşamaz ve sadece (omega-1)'e ulaşabilir.\",\"ar\":\"مجموعة الميثيل الطرفية محجوبة فراغياً تماماً ولذلك يستحيل على الإنزيم الوصول إليها فيكتفي بأوميغا-1.\",\"en\":\"The terminal methyl carbon is sterically shielded, preventing CYP enzyme access and restricting oxidation exclusively to (omega-1).\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Metil sterik engel yanılgısı: Terminal metil (omega) sterik olarak en açık pozisyondur; ancak (omega-1) hidroksilasyonu sekonder radikal kararlılığı nedeniyle termodinamik olarak sıklıkla baskındır.\",\"ar\":\"مغالطة الإعاقة الحجمية للميثيل: الميثيل الطرفي هو الأكثر انكشافاً فراغياً؛ لكن أكسدة أوميغا-1 تسود ديناميكياً لاستقرار الجذر الثانوي.\",\"en\":\"Methyl steric hindrance fallacy: Terminal methyl (omega) is sterically unhindered; however, (omega-1) oxidation frequently dominates due to secondary radical resonance stability.\"}},{\"id\":\"opt-7c\",\"text\":{\"tr\":\"Karaciğer enzimleri moleküler kütlesi çift olan yan zincirleri tanırken, tek sayılı karbon zincirlerini metabolize edemez.\",\"ar\":\"إنزيمات الكبد تستقلب فقط السلاسل الجانبية ذات الأعداد الزوجية من الكربون وتعجز عن التعرف على السلاسل الفردية.\",\"en\":\"Hepatic enzymes possess an obligate preference for even-numbered carbon chains, completely unable to metabolize odd-numbered alkyl substituents.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Karbon sayısı kuralı yanılgısı: Yağ asidi beta-oksidasyonu ile karıştırılan bir yanılgıdır; CYP450 mono-oksijenazlar zincir uzunluğundan bağımsız olarak alifatik C-H bağlarını hidroksiller.\",\"ar\":\"مغالطة عدد الكربونات: خلط مع أكسدة بيتا للحموض الدسمة؛ إنزيمات CYP تهدرل روابط C-H الأليفاتية بغض النظر عن طول السلسلة.\",\"en\":\"Chain number parity fallacy: Conflates fatty acid beta-oxidation with CYP450; microsomal monooxygenases oxidize alkyl C-H bonds irrespective of chain parity.\"}}]},\"technicalTerms\":[{\"term\":\"omega ve (omega-1) oksidasyonu\",\"arContext\":\"أكسدة أوميغا و (أوميغا-1)\"},{\"term\":\"bağ disosiasyon enerjisi (BDE)\",\"arContext\":\"طاقة تفكك الرابطة (BDE)\"}],\"hints\":[{\"tr\":\"Alifatik zincirde terminal karbon primer (-CH3), bir önceki karbon sekonderdir (-CH2-).\",\"ar\":\"في السلسلة الأليفاتية، الكربون الطرفي أولي (-CH3) وما قبله ثانوي (-CH2-).\",\"en\":\"In an alkyl chain, the terminal carbon is primary (-CH3) and the internal carbon is secondary (-CH2-).\"},{\"tr\":\"Organik kimyada radikal kararlılığı sıralamasını hatırlayın: Tersiyer > Sekonder > Primer.\",\"ar\":\"تذكر ترتيب استقرار الجذور الحرة في الكيمياء العضوية: ثالثي > ثانوي > أولي.\",\"en\":\"Recall radical intermediate stability in organic chemistry: Tertiary > Secondary > Primary.\"},{\"tr\":\"Sekonder radikali oluşturmak daha az enerji gerektirdiği için (omega-1) hidroksilasyonu majör yoldur.\",\"ar\":\"تشكيل الجذر الثانوي يتطلب طاقة أقل، مما يجعل هدرلة (أوميغا-1) هي المسار الغالب.\",\"en\":\"Because secondary C-H bonds have lower dissociation energy, (omega-1) hydroxylation is energetically favored.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":15}],\"config\":{\"options\":[{\"id\":\"opt-7a\",\"text\":\"Sekonder C-H bağından hidrojen koparılmasıyla oluşan sekonder alkil radikali, primer radikale göre termodinamik olarak çok daha kararlıdır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Tam bir fiziksel organik kimya zaferi! Slayt 15 ilkesi: C-H bağ enerjileri tersiyer < sekonder < primer sırasını izler. CYP450 okso-ferril radikali en kolay koparabileceği bağı tercih eder; sekonder C-H bağının bağ disosiasyon enerjisi (~395 kJ/mol) primer metilden (~420 kJ/mol) düşüktür. Bu nedenle (omega-1) sekonder alkol metaboliti açık ara baskındır.\"},{\"id\":\"opt-7b\",\"text\":\"Terminal metil grubu sterik olarak en engelli bölgedir, bu yüzden enzim oraya asla yanaşamaz ve sadece (omega-1)'e ulaşabilir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Metil sterik engel yanılgısı: Terminal metil (omega) sterik olarak en açık pozisyondur; ancak (omega-1) hidroksilasyonu sekonder radikal kararlılığı nedeniyle termodinamik olarak sıklıkla baskındır.\"},{\"id\":\"opt-7c\",\"text\":\"Karaciğer enzimleri moleküler kütlesi çift olan yan zincirleri tanırken, tek sayılı karbon zincirlerini metabolize edemez.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Karbon sayısı kuralı yanılgısı: Yağ asidi beta-oksidasyonu ile karıştırılan bir yanılgıdır; CYP450 mono-oksijenazlar zincir uzunluğundan bağımsız olarak alifatik C-H bağlarını hidroksiller.\"}],\"revealedOutcome\":{\"tr\":\"Sekonder C-H bağından hidrojen koparılmasıyla oluşan sekonder alkil radikali, primer radikale göre termodinamik olarak çok daha kararlıdır.\",\"ar\":\"الجذر الكربوني الثانوي الناتج عن نزع هيدروجين من C-H ثانوية أكثر استقراراً ديناميكياً وحرارياً من الجذر الأولي.\",\"en\":\"Hydrogen abstraction from a secondary methylene C-H yields a secondary alkyl radical, which is thermodynamically far more stable than a primary radical.\"},\"explanation\":{\"tr\":\"Tam bir fiziksel organik kimya zaferi! Slayt 15 ilkesi: C-H bağ enerjileri tersiyer < sekonder < primer sırasını izler. CYP450 okso-ferril radikali en kolay koparabileceği bağı tercih eder; sekonder C-H bağının bağ disosiasyon enerjisi (~395 kJ/mol) primer metilden (~420 kJ/mol) düşüktür. Bu nedenle (omega-1) sekonder alkol metaboliti açık ara baskındır.\",\"ar\":\"انتصار كيميائي فيزيائي فذ! الشريحة 15: طاقة تفكك روابط C-H تتبع الترتيب: ثالثي < ثانوي < أولي. طاقة كسر الرابطة الثانوية (~395 kJ/mol) أقل من الميثيل الطرفي (~420 kJ/mol)، مما يجعل جذر (أوميغا-1) أسهل تشكلاً ومستقلبه هو السائد.\",\"en\":\"Physical organic chemistry triumph! Slide 15 principle: C-H bond dissociation energies follow 3° < 2° < 1°. Abstracting a secondary hydrogen requires ~25 kJ/mol less energy than primary C-H, making the (omega-1) radical pathway dramatically favored.\"}}},{\"id\":\"mc-mod5-les1-step-08\",\"stage\":\"concept_check\",\"stageIndex\":8,\"type\":\"concept_check\",\"title\":{\"tr\":\"Kavram Kontrolü: Amfetamin ve Oksidatif Deaminasyon\",\"ar\":\"تحقق المفاهيم: الأمفيتامين ونزع الأمين الأكسيدي\",\"en\":\"Concept Check: Amphetamine & Oxidative Deamination\"},\"prompt\":{\"tr\":\"Amfetamin primer bir amin taşır. CYP450 enzimi amfetaminin amino grubuna komşu alfa-karbonunu hidroksillediğinde ortaya hangi son ürünler çıkar?\",\"ar\":\"يحمل الأمفيتامين أميناً أولياً. عندما يهدرل إنزيم CYP450 كربون ألفا المجاور لمجموعة الأمين، ما هي النواتج النهائية المتشكلة؟\",\"en\":\"Amphetamine bears a primary aliphatic amine. When Cytochrome P450 hydroxylates the alpha-carbon adjacent to the amine group, what final products are generated?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-8a\",\"text\":{\"tr\":\"Oluşan kararsız karbinolamin kendiliğinden amonyak (NH3) gazı bırakarak fenilasetona (keton) dönüşür.\",\"ar\":\"يتحول الكاربينول أمين غير المستقر المتشكل تلقائياً إلى فينيل أسيتون (كيتون) محرراً غاز الأمونيا (NH3).\",\"en\":\"The transient carbinolamine intermediate spontaneously expels ammonia (NH3) to yield phenylacetone (ketone).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika reaksiyon takibi! Slayt 13 ve 24: Alfa-karbonun hidroksillenmesiyle oluşan geminal amino-alkol (karbinolamin) termodinamik olarak aşırı kararsızdır. Spontan olarak amonyak eliminasyonu yapar ve fenilaseton ketonuna dönüşür.\",\"ar\":\"تتبع استثنائي للتفاعل! الشريحة 13 و 24: الكاربينول أمين المتشكل بهدرلة كربون ألفا غير مستقر إطلاقاً؛ ينشطر تلقائياً بطرد الأمونيا ليعطي كيتون فينيل أسيتون.\",\"en\":\"Outstanding mechanistic tracking! Slide 13 & 24: Hydroxylation of the alpha-carbon produces a geminal carbinolamine that spontaneously fragments, eliminating ammonia to leave phenylacetone.\"}},{\"id\":\"opt-8b\",\"text\":{\"tr\":\"Oluşan ara ürün kararlı bir nitro türevidir; amonyak ayrılması gerçekleşmez ve molekül idrara hiç atılamaz.\",\"ar\":\"المركب الوسيط هو مشتق نيترو مستقر؛ لا يحدث انفصال للأمونيا ولا يطرح الجزيء في البول.\",\"en\":\"The intermediate forms a stable nitro derivative; ammonia never leaves, preventing ketone conversion.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kararlı nitro türevi yanılgısı: Alfa-karbona hidroksil eklenmesi (-C(OH)(NH2)-) karbinolamin ara ürününü doğurur; bu yapı termodinamik olarak kararsızdır ve hızla amonyak kaybederek fenilasetona parçalanır.\",\"ar\":\"مغالطة مشتق النيترو: إضافة الهيدروكسيل لكربون ألفا تعطي كاربينول أمين غير مستقر ينشطر فوراً محرراً الأمونيا والفينيل أسيتون.\",\"en\":\"Stable nitro misconception: Alpha-carbon hydroxylation generates a transient carbinolamine; this intermediate spontaneously expels ammonia to yield phenylacetone.\"}},{\"id\":\"opt-8c\",\"text\":{\"tr\":\"CYP enzimi doğrudan C-N bağını homolitik olarak kırar ve serbest fenilpropanil radikali açığa çıkar.\",\"ar\":\"يشطر إنزيم CYP رابطة C-N مباشرة وبشكل تجانسي محرراً جذراً حراً من فينيل بروبانيل.\",\"en\":\"CYP directly cleaves the C-N single bond homolytically, releasing a phenylpropanyl radical.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Doğrudan bağ kırılması yanılgısı: CYP450 doğrudan C-N bağını koparmaz; mekanizma her zaman alfa-C-H bağının hidroksillenmesi ve ardından kendiliğinden kimyasal eliminasyondur.\",\"ar\":\"مغالطة الكسر المباشر: لا يكسر CYP رابطة C-N مباشرة؛ بل يهدرل كربون ألفا لتشجيع الانفصال التلقائي للأمونيا.\",\"en\":\"Direct cleavage misconception: CYP enzymes do not directly sever C-N bonds; they hydroxylate the adjacent alpha-carbon to trigger spontaneous elimination.\"}}]},\"technicalTerms\":[{\"term\":\"oksidatif deaminasyon\",\"arContext\":\"نزع الأمين الأكسيدي (oxidative deamination)\"},{\"term\":\"amonyak eliminasyonu\",\"arContext\":\"طرح الأمونيا\"}],\"hints\":[{\"tr\":\"Amfetaminde azot atomu primer amin halindedir (-CH(CH3)-NH2).\",\"ar\":\"تحمل جزيئة الأمفيتامين أميناً أولياً مرتبطاً بكربون ألفا (-CH(CH3)-NH2).\",\"en\":\"Amphetamine contains a primary amine located on a chiral alpha-carbon.\"},{\"tr\":\"Alfa-karbon hidroksillendiğinde ortaya çıkan C(OH)-NH2 grubu kararsızdır.\",\"ar\":\"المجموعة الناتجة عن هدرلة كربون ألفا C(OH)-NH2 غير مستقرة كيميائياً.\",\"en\":\"The resulting geminal carbinolamine C(OH)-NH2 is chemically transient.\"},{\"tr\":\"Azot atomu amonyak (NH3) olarak ayrılırken geriye keton (fenilaseton) kalır.\",\"ar\":\"ينفصل النيتروجين كغاز أمونيا (NH3) متبقياً كيتون (فينيل أسيتون).\",\"en\":\"Nitrogen departs as ammonia (NH3), leaving behind the neutral ketone phenylacetone.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":21}],\"config\":{\"options\":[{\"id\":\"opt-8a\",\"text\":\"Oluşan kararsız karbinolamin kendiliğinden amonyak (NH3) gazı bırakarak fenilasetona (keton) dönüşür.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika reaksiyon takibi! Slayt 13 ve 24: Alfa-karbonun hidroksillenmesiyle oluşan geminal amino-alkol (karbinolamin) termodinamik olarak aşırı kararsızdır. Spontan olarak amonyak eliminasyonu yapar ve fenilaseton ketonuna dönüşür.\"},{\"id\":\"opt-8b\",\"text\":\"Oluşan ara ürün kararlı bir nitro türevidir; amonyak ayrılması gerçekleşmez ve molekül idrara hiç atılamaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kararlı nitro türevi yanılgısı: Alfa-karbona hidroksil eklenmesi (-C(OH)(NH2)-) karbinolamin ara ürününü doğurur; bu yapı termodinamik olarak kararsızdır ve hızla amonyak kaybederek fenilasetona parçalanır.\"},{\"id\":\"opt-8c\",\"text\":\"CYP enzimi doğrudan C-N bağını homolitik olarak kırar ve serbest fenilpropanil radikali açığa çıkar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Doğrudan bağ kırılması yanılgısı: CYP450 doğrudan C-N bağını koparmaz; mekanizma her zaman alfa-C-H bağının hidroksillenmesi ve ardından kendiliğinden kimyasal eliminasyondur.\"}],\"revealedOutcome\":{\"tr\":\"Oluşan kararsız karbinolamin kendiliğinden amonyak (NH3) gazı bırakarak fenilasetona (keton) dönüşür.\",\"ar\":\"ينشطر الكاربينول أمين غير المستقر تلقائياً طارحاً غاز الأمونيا (NH3) ومتحولاً إلى فينيل أسيتون (كيتون).\",\"en\":\"The unstable carbinolamine intermediate spontaneously eliminates ammonia (NH3) gas, collapsing into phenylacetone (ketone).\"},\"explanation\":{\"tr\":\"Harika! Slayt 21'deki klasik mekanizma: Primer aminlerde alfa-hidroksilasyon imin/karbinolamin ara ürünü üretir. Su ve elektron düzenlenmesiyle amonyak (NH3) ayrılır ve molekül keton türevine (fenilaseton) dönüşerek santral stimülan etkisini tamamen kaybeder.\",\"ar\":\"رائع! آلية الشريحة 21 الكلاسيكية: في الأمينات الأولية ينتج عن هدرلة كربون ألفا وسيط هيمي أمينال ينشطر طارحاً الأمونيا ومكوناً فينيل أسيتون فاقد للفعالية المنبهة.\",\"en\":\"Spot on! Slide 21 textbook mechanism: Alpha-hydroxylation of a primary amine produces an unstable carbinolamine. Loss of ammonia (NH3) yields phenylacetone, terminating central stimulant activity.\"}}},{\"id\":\"mc-mod5-les1-step-09\",\"stage\":\"application\",\"stageIndex\":9,\"type\":\"clinical_vignette\",\"title\":{\"tr\":\"Klinik Vaka: Prokain (Ester) vs Prokainamid (Amit) Kinetiği\",\"ar\":\"حالة سريرية: حركية البروكائين (إستر) مقابل البروكايناميد (أميد)\",\"en\":\"Clinical Vignette: Procaine (Ester) vs. Procainamide (Amide) Kinetics\"},\"prompt\":{\"tr\":\"Lokal anestezik prokain (ester) enjeksiyondan 15 dakika sonra plazmada tamamen parçalanırken, benzer yapıdaki antiaritmik prokainamid (amit) saatlerce kanda kalır. Bu kinetik uçurumun kimyasal nedeni nedir?\",\"ar\":\"يتفكك مخدر البروكائين (إستر) كلياً خلال 15 دقيقة في البلازما، بينما يمكث شبيهه البروكايناميد (أميد) ساعات بالدم لعلاج اللانظميات. ما سبب هذا الفارق الحركي؟\",\"en\":\"Local anesthetic procaine (ester) is completely cleared within 15 minutes of injection, whereas procainamide (amide) persists in blood for 4 hours to treat arrhythmias. What chemical principle explains this kinetic gap?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-9a\",\"text\":{\"tr\":\"Kandaki psödokolinesterazlar esterleri (prokain) dakikalar içinde yıkar; amit bağındaki azot rezonansı ise bağı kararlı kılar ve hepatik amidazlarca çok yavaş hidroliz edilir.\",\"ar\":\"تحلمه كولين إستراز البلازما الإستر (بروكائين) في دقائق؛ بينما يعزز رنين نيتروجين الأميد ثبات الرابطة ويجعل حلمهتها الكبدية بطيئة للغاية.\",\"en\":\"Blood pseudocholinesterases hydrolyze esters (procaine) within minutes; nitrogen lone-pair resonance stabilizes amide bonds, making procainamide hydrolysis by amidases orders of magnitude slower.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika klinik kavrayış! Slayt 28 ve Modül 3 biyoizosterizm prensibi: Plazmada bol miktarda bulunan psödokolinesteraz ve karboksilesteraz enzimleri ester bağını hızla yarar (prokain t1/2 < 1 dk). Amit grubundaki azotun serbest elektron çifti karbonil ile rezonans yaparak çift bağ karakteri kazandırır (%40). Bu rezonans kararlılığı ve amidazların düşük hızı nedeniyle prokainamid 3-4 saatlik yarı ömre ulaşır.\",\"ar\":\"ربط سريري فذ! الشريحة 28: إسترازات البلازما تشطر الإستر في لمح البصر (بروكائين t1/2 < 1 دقيقة). بينما يمنح رنين زوج إلكترونات النيتروجين في الأميد خواص الرابطة المضاعفة (40%)، مما يمنحه ثباتاً هائلاً ونصف عمر 3-4 ساعات.\",\"en\":\"Superb clinical insight! Slide 28 benchmark: Abundant circulating butyrylcholinesterases cleave ester procaine within seconds. In procainamide, nitrogen lone-pair delocalization imparts partial double-bond character to the amide, resisting esterases and demanding slow amidase clearance (t1/2 ≈ 3-4 hours).\"}},{\"id\":\"opt-9b\",\"text\":{\"tr\":\"Prokainamid bir amit olduğu için plazmada çözünmez ve kan damarı endoteline yapışıp depolanır.\",\"ar\":\"بما أن بروكائيناميد أميد، فإنه لا يذوب في البلازما ويلتصق ببطانة الأوعية الدموية مترسباً.\",\"en\":\"Because procainamide is an amide, it is insoluble in plasma and precipitates onto vascular endothelium.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Çözünmezlik yanılgısı: Prokainamid tersiyer amin grubu sayesinde fizyolojik pH'ta tuz formundadır ve suda mükemmel çözünür; yarı ömrü vasküler depolanmadan değil, amidaz hidrolizine kimyasal dirençten kaynaklanır.\",\"ar\":\"مغالطة عدم الذوبان: يمتلك بروكائيناميد أميناً ثالثياً يجعله عالي الذوبان في ماء البلازما؛ وثباته ناجم عن مقاومة الأميداز وليس الترسيب.\",\"en\":\"Insolubility misconception: Procainamide possesses a basic tertiary amine and is water-soluble at pH 7.4; its longevity reflects amide resonance stability against esterases, not vascular precipitation.\"}},{\"id\":\"opt-9c\",\"text\":{\"tr\":\"Ester ve amit bağlarının hidroliz hızları aynıdır; prokainamidin kanda uzun kalmasının sebebi böbrek tübüllerinden hiç filtre edilmemesidir.\",\"ar\":\"سرعة حلمهة الإستر والأميد متطابقة؛ وبقاء بروكائيناميد يعود فقط إلى عدم ترشيحه كلوياً نهائياً.\",\"en\":\"Ester and amide hydrolysis rates are identical; procainamide persists purely because it completely avoids renal glomerular filtration.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Eşit kinetik yanılgısı: Plazma psödokolinesterazları esterleri saniyeler içinde hidroliz eder (prokain t1/2 < 1 dk); amit bağı ise rezonans ile kısmi çift bağ karakteri kazandığından ancak hepatik amidazlarca saatler içinde yavaşça yıkanabilir (Slayt 28).\",\"ar\":\"مغالطة التكافؤ الحركي: تشطر إسترازات البلازما الإستر في ثوانٍ؛ بينما تكتسب رابطة الأميد خواص الرابطة المزدوجة بالرنين وتتطلب حلمهة كبدية بطيئة لساعات (شريحة 28).\",\"en\":\"Kinetic equivalence fallacy: Circulating pseudocholinesterases hydrolyze esters in seconds; the amide bond is stabilized by nitrogen resonance, demanding much slower hepatic amidase clearance (Slide 28).\"}}]},\"technicalTerms\":[{\"term\":\"plazma psödokolinesterazı\",\"arContext\":\"كولين إستراز البلازما الكاذب\"},{\"term\":\"amit rezonans kararlılığı\",\"arContext\":\"ثبات الرنين في الرابطة الأميدية\"}],\"hints\":[{\"tr\":\"Prokain bir karboksilik asit esteri (-COO-), prokainamid ise bir amittir (-CONH-).\",\"ar\":\"البروكائين إستر كربوكسيلي (-COO-)، بينما البروكايناميد أميد (-CONH-).\",\"en\":\"Procaine features an ester (-COO-), while procainamide features an amide (-CONH-).\"},{\"tr\":\"Kanda ve dokularda yaygın bulunan esteraz enzimleri ester bağlarını saniyeler içinde hidroliz eder.\",\"ar\":\"إنزيمات الإستراز المتوفرة في البلازما تحلمه روابط الإستر في ثوانٍ معدودة.\",\"en\":\"Ubiquitous plasma esterases cleave ester bonds within seconds to minutes.\"},{\"tr\":\"Amit bağı azotunun rezonansı bağı güçlendirir; bu yüzden karaciğer amidazları amiti çok daha yavaş yıkar.\",\"ar\":\"رنين إلكترونات نيتروجين الأميد يضاعف قوة الرابطة فتتحلل ببطء شديد بواسطة الأميداز الكبدي.\",\"en\":\"Amide resonance imparts partial double-bond character, rendering procainamide refractory to plasma esterases.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":28}],\"config\":{\"options\":[{\"id\":\"opt-9a\",\"text\":\"Kandaki psödokolinesterazlar esterleri (prokain) dakikalar içinde yıkar; amit bağındaki azot rezonansı ise bağı kararlı kılar ve hepatik amidazlarca çok yavaş hidroliz edilir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika klinik kavrayış! Slayt 28 ve Modül 3 biyoizosterizm prensibi: Plazmada bol miktarda bulunan psödokolinesteraz ve karboksilesteraz enzimleri ester bağını hızla yarar (prokain t1/2 < 1 dk). Amit grubundaki azotun serbest elektron çifti karbonil ile rezonans yaparak çift bağ karakteri kazandırır (%40). Bu rezonans kararlılığı ve amidazların düşük hızı nedeniyle prokainamid 3-4 saatlik yarı ömre ulaşır.\"},{\"id\":\"opt-9b\",\"text\":\"Prokainamid bir amit olduğu için plazmada çözünmez ve kan damarı endoteline yapışıp depolanır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Çözünmezlik yanılgısı: Prokainamid tersiyer amin grubu sayesinde fizyolojik pH'ta tuz formundadır ve suda mükemmel çözünür; yarı ömrü vasküler depolanmadan değil, amidaz hidrolizine kimyasal dirençten kaynaklanır.\"},{\"id\":\"opt-9c\",\"text\":\"Ester ve amit bağlarının hidroliz hızları aynıdır; prokainamidin kanda uzun kalmasının sebebi böbrek tübüllerinden hiç filtre edilmemesidir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Eşit kinetik yanılgısı: Plazma psödokolinesterazları esterleri saniyeler içinde hidroliz eder (prokain t1/2 < 1 dk); amit bağı ise rezonans ile kısmi çift bağ karakteri kazandığından ancak hepatik amidazlarca saatler içinde yavaşça yıkanabilir (Slayt 28).\"}],\"revealedOutcome\":{\"tr\":\"Kandaki psödokolinesterazlar esterleri (prokain) dakikalar içinde yıkar; amit bağındaki azot rezonansı ise bağı kararlı kılar ve hepatik amidazlarca çok yavaş hidroliz edilir.\",\"ar\":\"تحلمه كولين إستراز البلازما الإستر (بروكائين) في دقائق؛ بينما يعزز رنين نيتروجين الأميد ثبات الرابطة ويجعل حلمهتها الكبدية بطيئة للغاية.\",\"en\":\"Blood pseudocholinesterases hydrolyze esters (procaine) within minutes; nitrogen lone-pair resonance stabilizes amide bonds, making procainamide hydrolysis by amidases orders of magnitude slower.\"},\"explanation\":{\"tr\":\"Harika klinik kavrayış! Slayt 28 ve Modül 3 biyoizosterizm prensibi: Plazmada bol miktarda bulunan psödokolinesteraz ve karboksilesteraz enzimleri ester bağını hızla yarar (prokain t1/2 < 1 dk). Amit grubundaki azotun serbest elektron çifti karbonil ile rezonans yaparak çift bağ karakteri kazandırır (%40). Bu rezonans kararlılığı ve amidazların düşük hızı nedeniyle prokainamid 3-4 saatlik yarı ömre ulaşır.\",\"ar\":\"ربط سريري فذ! الشريحة 28: إسترازات البلازما تشطر الإستر في لمح البصر (بروكائين t1/2 < 1 دقيقة). بينما يمنح رنين زوج إلكترونات النيتروجين في الأميد خواص الرابطة المضاعفة (40%)، مما يمنحه ثباتاً هائلاً ونصف عمر 3-4 ساعات.\",\"en\":\"Superb clinical insight! Slide 28 benchmark: Abundant circulating butyrylcholinesterases cleave ester procaine within seconds. In procainamide, nitrogen lone-pair delocalization imparts partial double-bond character to the amide, resisting esterases and demanding slow amidase clearance (t1/2 ≈ 3-4 hours).\"}}},{\"id\":\"mc-mod5-les1-step-10\",\"stage\":\"retrieval\",\"stageIndex\":10,\"type\":\"retrieval\",\"title\":{\"tr\":\"Aralıklı Hatırlama: Aktif Metabolit Kaskadı\",\"ar\":\"استرجاع تباعدي: تتابع المستقلبات الفعالة\",\"en\":\"Spaced Retrieval: The Active Metabolite Cascade\"},\"prompt\":{\"tr\":\"Diazepam vücutta önce Nordiazepam'a, ardından Oksazepam'a metabolize olur. Bu iki basamaklı Faz I kaskadında sırasıyla hangi iki kimyasal reaksiyon gerçekleşir?\",\"ar\":\"يتحول الديازيبام في الجسم إلى نورديازيبام ثم إلى أوكسازيبام. ما هما التفاعلان الكيميائيان المتتاليان في هذه السلسلة من المرحلة الأولى؟\",\"en\":\"Diazepam is metabolically transformed into Nordiazepam and subsequently into Oxazepam. What two sequential Phase I reactions drive this active cascade?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-10a\",\"text\":{\"tr\":\"1. Basamak: N1-Demetilasyon (Nordiazepam); 2. Basamak: C3-Alifatik Hidroksilasyon (Oksazepam).\",\"ar\":\"الخطوة 1: نزع ميثيل N1 (نورديازيبام)؛ الخطوة 2: هدرلة أليفاتية عند C3 (أوكسازيبام).\",\"en\":\"Step 1: Oxidative N1-demethylation (yielding Nordiazepam); Step 2: Aliphatic C3-hydroxylation (yielding Oxazepam).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz hatırlama! Slayt 6 ve 20: Diazepam önce N1-pozisyonundaki metil grubunu CYP2C19/3A4 ile kaybederek Nordiazepam olur. Ardından CYP3A4 7 üyeli diazepin halkasının C3 karbonunu hidroksilleyerek Oksazepam'ı üretir. Her iki ürün de güçlü sedatiftir.\",\"ar\":\"استرجاع مثالي! شريحة 6 و 20: يفقد الديازيبام أولاً ميثيل N1 ليصبح نورديازيبام، ثم يهدرل CYP3A4 كربون C3 في حلقة الديازيبين لينتج الأوكسازيبام. وكلا المستقلبين مهدئان نشطان.\",\"en\":\"Flawless retrieval! Slides 6 & 20: Diazepam first undergoes N1-demethylation to yield nordiazepam. Subsequent C3-hydroxylation of the diazepine ring generates oxazepam. Both metabolites retain potent GABA-A sedative activity.\"}},{\"id\":\"opt-10b\",\"text\":{\"tr\":\"1. Basamak: Glukuronidasyon; 2. Basamak: Sülfat konjugasyonu.\",\"ar\":\"الخطوة 1: الاقتران بالجلوكورونيد؛ الخطوة 2: الاقتران بالكبريتات.\",\"en\":\"Step 1: Glucuronidation conjugation; Step 2: Sulfate ester conjugation.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Faz karışıklığı yanılgısı: Glukuronidasyon ve sülfasyon Faz II sentetik konjugasyonlarıdır; oksazepam üretimi ise Faz I fonksiyonelleşmesidir (oksidasyon).\",\"ar\":\"خطأ خلط المراحل: الجلوكورونيد والكبريتات من تفاعلات المرحلة الثانية، بينما إنتاج الأوكسازيبام أكسدة من المرحلة الأولى.\",\"en\":\"Phase confusion: Glucuronidation and sulfation are Phase II synthetic conjugations; oxazepam generation is entirely Phase I oxidation.\"}},{\"id\":\"opt-10c\",\"text\":{\"tr\":\"1. Basamak: Klor atomunun sodyumla değişimi; 2. Basamak: Halkanın açılması.\",\"ar\":\"الخطوة 1: استبدال ذرة الكلور بصوديوم؛ الخطوة 2: انفتاح الحلقة.\",\"en\":\"Step 1: Displacement of the chlorine atom by sodium; Step 2: Cleavage of the diazepine ring.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Aromatik klor değişimi yanılgısı: Diazepamın C7 klor atomu metabolik olarak son derece kararlıdır ve değişmez; halka da intakt kalır.\",\"ar\":\"خطأ استبدال الكلور: ذرة الكلور C7 في الديازيبام خاملة استقلابياً ولا تُستبدل، وتبقى الحلقة سليمة.\",\"en\":\"Chlorine substitution misconception: The C7 aryl chloride is metabolically inert during initial Phase I pathways; the heterocyclic ring remains closed.\"}}]},\"technicalTerms\":[{\"term\":\"kaskad metabolizması\",\"arContext\":\"تتابع الاستقلاب (metabolic cascade)\"},{\"term\":\"C3-hidroksilasyonu\",\"arContext\":\"الهدرلة عند الموضع C3\"}],\"hints\":[{\"tr\":\"İlk basamakta diazepamın N1 atomuna bağlı bir karbonlu metil grubu ayrılır.\",\"ar\":\"في الخطوة الأولى تُقتطع مجموعة الميثيل ذات الكربون الواحد من ذرة N1.\",\"en\":\"The first step cleaves the one-carbon methyl group linked to nitrogen N1.\"},{\"tr\":\"İkinci basamakta 7 üyeli diazepin halkasına bir hidroksil (-OH) grubu eklenir.\",\"ar\":\"في الخطوة الثانية تُضاف مجموعة هيدروكسيل (-OH) لحلقة الديازيبين.\",\"en\":\"The second step introduces a hydroxyl group (-OH) onto the diazepine ring at position 3.\"},{\"tr\":\"Sıralama: N-demetilasyon (Nordiazepam) ardından C3-hidroksilasyondur (Oksazepam).\",\"ar\":\"الترتيب هو: نزع الميثيل N1 (نورديازيبام) يليه هدرلة C3 (أوكسازيبام).\",\"en\":\"The sequence is N1-demethylation followed by C3-hydroxylation.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":6}],\"config\":{\"options\":[{\"id\":\"opt-10a\",\"text\":\"1. Basamak: N1-Demetilasyon (Nordiazepam); 2. Basamak: C3-Alifatik Hidroksilasyon (Oksazepam).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz hatırlama! Slayt 6 ve 20: Diazepam önce N1-pozisyonundaki metil grubunu CYP2C19/3A4 ile kaybederek Nordiazepam olur. Ardından CYP3A4 7 üyeli diazepin halkasının C3 karbonunu hidroksilleyerek Oksazepam'ı üretir. Her iki ürün de güçlü sedatiftir.\"},{\"id\":\"opt-10b\",\"text\":\"1. Basamak: Glukuronidasyon; 2. Basamak: Sülfat konjugasyonu.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Faz karışıklığı yanılgısı: Glukuronidasyon ve sülfasyon Faz II sentetik konjugasyonlarıdır; oksazepam üretimi ise Faz I fonksiyonelleşmesidir (oksidasyon).\"},{\"id\":\"opt-10c\",\"text\":\"1. Basamak: Klor atomunun sodyumla değişimi; 2. Basamak: Halkanın açılması.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Aromatik klor değişimi yanılgısı: Diazepamın C7 klor atomu metabolik olarak son derece kararlıdır ve değişmez; halka da intakt kalır.\"}],\"revealedOutcome\":{\"tr\":\"1. Basamak: N1-Demetilasyon (Nordiazepam); 2. Basamak: C3-Alifatik Hidroksilasyon (Oksazepam).\",\"ar\":\"الخطوة 1: نزع ميثيل N1 (نورديازيبام)؛ الخطوة 2: هدرلة أليفاتية عند C3 (أوكسازيبام).\",\"en\":\"Step 1: Oxidative N1-demethylation (yielding Nordiazepam); Step 2: Aliphatic C3-hydroxylation (yielding Oxazepam).\"},\"explanation\":{\"tr\":\"Kusursuz hatırlama! Slayt 6 ve 20: Diazepam önce N1-pozisyonundaki metil grubunu CYP2C19/3A4 ile kaybederek Nordiazepam olur. Ardından CYP3A4 7 üyeli diazepin halkasının C3 karbonunu hidroksilleyerek Oksazepam'ı üretir. Her iki ürün de güçlü sedatiftir.\",\"ar\":\"استرجاع مثالي! شريحة 6 و 20: يفقد الديازيبام أولاً ميثيل N1 ليصبح نورديازيبام، ثم يهدرل CYP3A4 كربون C3 في حلقة الديازيبين لينتج الأوكسازيبام. وكلا المستقلبين مهدئان نشطان.\",\"en\":\"Flawless retrieval! Slides 6 & 20: Diazepam first undergoes N1-demethylation to yield nordiazepam. Subsequent C3-hydroxylation of the diazepine ring generates oxazepam. Both metabolites retain potent GABA-A sedative activity.\"}}},{\"id\":\"mc-mod5-les1-step-11\",\"stage\":\"connection\",\"stageIndex\":11,\"type\":\"connection\",\"title\":{\"tr\":\"Geniş Bağlantı: Epoksit Hidrolaz ve Toksikolojik Kalkan\",\"ar\":\"آفاق متقدمة: إيبوكسيد هيدرولاز والدرع السمومي الخلوي\",\"en\":\"Broader Connection: Epoxide Hydrolase as a Toxicological Shield\"},\"prompt\":{\"tr\":\"Aromatik hidroksilasyonda oluşan aren oksitler (epoksitler) son derece reaktif elektrofillerdir. Karaciğerdeki Epoksit Hidrolaz enzimi bu kanserojenik reaktifleri nasıl etkisiz hale getirir?\",\"ar\":\"تعد أكاسيد الآرين (الإيبوكسيدات) الناتجة عن الأكسدة العطرية إلكتروفيلات عالية الخطورة. كيف يبطل إنزيم إيبوكسيد هيدرولاز الكبدي سميتها ويمنع السرطان؟\",\"en\":\"Arene oxide epoxides formed during aromatic oxygenation are mutagens and electrophiles. How does hepatic Epoxide Hydrolase neutralize these reactive intermediates to prevent cellular toxicity?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-11a\",\"text\":{\"tr\":\"Aren oksit halkasına su molekülü (H2O) katarak DNA'ya bağlanamayan kararlı trans-dihidrodiollere hidroliz eder.\",\"ar\":\"يضيف جزيء ماء (H2O) إلى حلقة أكسيد الآرين محولاً إياها إلى مركب trans-dihydrodiol المستقر العاجز عن طفرة DNA.\",\"en\":\"It adds a water molecule (H2O) across the arene oxide ring, converting it into a stable trans-dihydrodiol that cannot alkylate DNA.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika toksikolojik kavrayış! Slayt 16 ve 29: Eğer aren oksit hemen hidroliz edilmezse hücredeki nükleofilik DNA bazlarına ve protein tiyollerine kovalent bağlanarak mutajenez ve doku nekrozu yapar. Mikrozomal ve sitozolik Epoksit Hidrolaz enzimi stereospesifik su katılmasıyla trans-dihidrodiolleri oluşturur ve DNA'yı kollar.\",\"ar\":\"رؤية سمومية متعمقة! الشريحة 16 و 29: إذا نجا أكسيد الآرين من التحلل، يهاجم قواعد DNA وبروتينات الخلية بروابط تساهمية مسبباً السرطان والتنخر. يتدخل إيبوكسيد هيدرولاز بإضافة الماء ليصنع مركب trans-dihydrodiol الآمن.\",\"en\":\"Profound toxicological bridge! Slides 16 & 29: Unchecked arene oxides alkylate guanine bases in DNA, initiating carcinogenesis. Epoxide Hydrolase provides a defensive shield, catalyzing trans-addition of H2O to generate unreactive dihydrodiols.\"}},{\"id\":\"opt-11b\",\"text\":{\"tr\":\"Epoksit halkasını doğrudan benzoik asit ve formaldehite parçalayarak idrara gönderir.\",\"ar\":\"يفكك حلقة الإيبوكسيد مباشرة إلى حمض بنزويك وفورمالدهيد للطرح البولي.\",\"en\":\"Cleaves the epoxide ring directly into benzoic acid and formaldehyde fragments for rapid urinary elimination.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Halka parçalama yanılgısı: Epoksit hidrolaz molekülü parçalamaz; su katarak trans-1,2-dihidrodiol türevi oluşturur (Slayt 16 ve 29).\",\"ar\":\"مغالطة التجزئة: لا يجزئ الإنزيم الجزيء، بل يضيف جزيء ماء مشكلاً مشتق ترانس-1،2-ثنائي الهيدرو ديول (شريحة 16 و 29).\",\"en\":\"Fragmentation fallacy: Epoxide hydrolase does not fragment the scaffold; it stereospecifically adds water to form trans-dihydrodiols (Slides 16 & 29).\"}},{\"id\":\"opt-11c\",\"text\":{\"tr\":\"Epoksit hidrolaz enzimi sadece bakterilerde bulunur; insan vücudunda aren oksitler yalnızca glutatyonla temizlenebilir.\",\"ar\":\"إنزيم إيبوكسيد هيدرولاز يوجد فقط في البكتيريا؛ وفي جسم الإنسان يتم تنظيف الأرين أوكسيد حصراً بالجلوتاثيون.\",\"en\":\"Epoxide hydrolase exists solely in bacteria; human cells rely exclusively on glutathione for arene oxide neutralization.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yalnızca glutatyon yanılgısı: İnsan karaciğer mikrozom ve sitozolünde güçlü epoksit hidrolaz enzimleri bulunur; dihidrodiol oluşumu karsinojeniteyi önleyen primer savunma hattıdır.\",\"ar\":\"مغالطة حصر الحماية بالجلوتاثيون: تمتلك الخلايا الكبدية البشرية إنزيم إيبوكسيد هيدرولاز ميكروزومي عالي الفعالية كخط دفاع أساسي.\",\"en\":\"Glutathione-exclusive fallacy: Human liver microsomes express abundant epoxide hydrolase; dihydrodiol conversion is a primary cellular defense.\"}}]},\"technicalTerms\":[{\"term\":\"epoksit hidrolaz\",\"arContext\":\"إنزيم إيبوكسيد هيدرولاز (epoxide hydrolase)\"},{\"term\":\"trans-dihidrodiol metaboliti\",\"arContext\":\"مستقلب trans-dihydrodiol\"}],\"hints\":[{\"tr\":\"Epoksitler üç üyeli gergin ve elektrofilik eter halkalarıdır.\",\"ar\":\"الإيبوكسيدات حلقات إيثرية ثلاثية مجهدة وشديدة الألفة للإلكترونات.\",\"en\":\"Epoxides are strained 3-membered cyclic ethers that act as electrophiles.\"},{\"tr\":\"Hücredeki nükleofilik DNA bazları bu halkaya saldırırsa mutasyon oluşur.\",\"ar\":\"إذا هاجمت قواعد DNA النيوكليوفيلية هذه الحلقة تحدث طفرات سرطانية.\",\"en\":\"If cellular nucleophiles (DNA, proteins) attack the ring, mutations and necrosis occur.\"},{\"tr\":\"Epoksit hidrolaz su (H2O) katarak iki hidroksil grubu içeren trans-dihidrodiol türevine çevirir.\",\"ar\":\"يضيف إيبوكسيد هيدرولاز الماء ليحوله إلى مركب diol يحمل مجموعتي هيدروكسيل غير ضار.\",\"en\":\"Epoxide hydrolase adds water to open the ring into a benign trans-dihydrodiol.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":29}],\"config\":{\"options\":[{\"id\":\"opt-11a\",\"text\":\"Aren oksit halkasına su molekülü (H2O) katarak DNA'ya bağlanamayan kararlı trans-dihidrodiollere hidroliz eder.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika toksikolojik kavrayış! Slayt 16 ve 29: Eğer aren oksit hemen hidroliz edilmezse hücredeki nükleofilik DNA bazlarına ve protein tiyollerine kovalent bağlanarak mutajenez ve doku nekrozu yapar. Mikrozomal ve sitozolik Epoksit Hidrolaz enzimi stereospesifik su katılmasıyla trans-dihidrodiolleri oluşturur ve DNA'yı kollar.\"},{\"id\":\"opt-11b\",\"text\":\"Epoksit halkasını doğrudan benzoik asit ve formaldehite parçalayarak idrara gönderir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Halka parçalama yanılgısı: Epoksit hidrolaz molekülü parçalamaz; su katarak trans-1,2-dihidrodiol türevi oluşturur (Slayt 16 ve 29).\"},{\"id\":\"opt-11c\",\"text\":\"Epoksit hidrolaz enzimi sadece bakterilerde bulunur; insan vücudunda aren oksitler yalnızca glutatyonla temizlenebilir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yalnızca glutatyon yanılgısı: İnsan karaciğer mikrozom ve sitozolünde güçlü epoksit hidrolaz enzimleri bulunur; dihidrodiol oluşumu karsinojeniteyi önleyen primer savunma hattıdır.\"}],\"revealedOutcome\":{\"tr\":\"Aren oksit halkasına su molekülü (H2O) katarak DNA'ya bağlanamayan kararlı trans-dihidrodiollere hidroliz eder.\",\"ar\":\"يضيف جزيء ماء (H2O) إلى حلقة أكسيد الآرين محولاً إياها إلى مركب trans-dihydrodiol المستقر العاجز عن طفرة DNA.\",\"en\":\"It adds a water molecule (H2O) across the arene oxide ring, converting it into a stable trans-dihydrodiol that cannot alkylate DNA.\"},\"explanation\":{\"tr\":\"Harika toksikolojik kavrayış! Slayt 16 ve 29: Eğer aren oksit hemen hidroliz edilmezse hücredeki nükleofilik DNA bazlarına ve protein tiyollerine kovalent bağlanarak mutajenez ve doku nekrozu yapar. Mikrozomal ve sitozolik Epoksit Hidrolaz enzimi stereospesifik su katılmasıyla trans-dihidrodiolleri oluşturur ve DNA'yı kollar.\",\"ar\":\"رؤية سمومية متعمقة! الشريحة 16 و 29: إذا نجا أكسيد الآرين من التحلل، يهاجم قواعد DNA وبروتينات الخلية بروابط تساهمية مسبباً السرطان والتنخر. يتدخل إيبوكسيد هيدرولاز بإضافة الماء ليصنع مركب trans-dihydrodiol الآمن.\",\"en\":\"Profound toxicological bridge! Slides 16 & 29: Unchecked arene oxides alkylate guanine bases in DNA, initiating carcinogenesis. Epoxide Hydrolase provides a defensive shield, catalyzing trans-addition of H2O to generate unreactive dihydrodiols.\"}}},{\"id\":\"mc-mod5-les1-step-12\",\"stage\":\"mastery_check\",\"stageIndex\":12,\"type\":\"mastery_check\",\"title\":{\"tr\":\"Ustalık Sınavı: Döteryum Kinetik İzotop Etkisi ve İlaç Tasarımı\",\"ar\":\"اختبار التمكن: تأثير نظائر الديوتيريوم الحركي وتصميم الأدوية\",\"en\":\"Mastery Check: Deuterium Kinetic Isotope Effect in Drug Design\"},\"prompt\":{\"tr\":\"Bir ilaç adayının metabolik zayıf noktasındaki C-H bağı döteryum (C-D) ile değiştirilir. C-D bağının disosiasyon enerjisi daha yüksek olduğundan (kH/kD ≈ 6.5), Faz I klirensi ve yarı ömrü nasıl değişir?\",\"ar\":\"استُبدلت رابطة C-H برابطة ديوتيريوم (C-D) في موقع استقلابي ضعيف. مع ارتفاع طاقة تفكك C-D (kH/kD ≈ 6.5)، كيف يتأثر معدل التصفية ونصف العمر الحيوي للدواء؟\",\"en\":\"A metabolic soft-spot C-H bond is deuterated to C-D. Since C-D has higher zero-point bond energy (kH/kD ≈ 6.5), how do the drug's Phase I metabolic clearance and elimination half-life respond?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-12a\",\"text\":{\"tr\":\"C-D bağının CYP450 tarafından koparılması yavaşlar; metabolik klirens dramatik şekilde düşer ve eliminasyon yarı ömrü belirgin biçimde uzar.\",\"ar\":\"يتباطأ كسر رابطة C-D بواسطة CYP450؛ فتهبط التصفية الاستقلابية بشكل ملحوظ ويمتد نصف عمر الإطراح الدوائي طويلاً.\",\"en\":\"CYP-mediated hydrogen abstraction slows markedly; metabolic clearance plunges and elimination half-life is substantially prolonged.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Muazzam bir farmasötik kimya ustalığı! Kinetik İzotop Etkisi (KIE): Döteryum hidrojenden iki kat ağırdır; C-D bağının sıfır noktası titreşim enerjisi daha düşüktür ve bağı kırmak ~5 kJ/mol daha fazla enerji ister. CYP450'nin hız kısıtlayıcı basamağı C-H koparılması olduğundan, döterizasyon reaksiyon hızını 6-7 kat yavaşlatır. Bu strateji FDA onaylı döterlenmiş ilaçlarda (örn. dötotetrabenazin) günde tek doza geçişi sağlamıştır.\",\"ar\":\"تمكن كيميائي صيدلاني استثنائي! تأثير النظائر الحركي (KIE): الديوتيريوم أثقل بمرتين من الهيدروجين، ورابطة C-D أقوى بنحو 5 kJ/mol. بما أن كسر الرابطة هو الخطوة المحددة للسرعة في CYP450، فإن استبدالها بديوتيريوم يبطئ الأيض 6-7 أضعاف، وهو أساس الأدوية المديترة مثل deutetrabenazine.\",\"en\":\"Flawless mastery! Kinetic Isotope Effect (KIE): Deuterium doubles hydrogen's atomic mass, lowering zero-point vibrational energy and requiring ~5 kJ/mol more activation energy to break. Because C-H abstraction is the rate-limiting step in CYP catalysis, deuteration slows clearance by 6-7 fold (pioneered in FDA-approved deutetrabenazine).\"}},{\"id\":\"opt-12b\",\"text\":{\"tr\":\"Döteryum ikamesi bağ kopma enerjisini düşürür; bu yüzden ilaç 10 kat daha hızlı metabolize edilip hızla tükenir.\",\"ar\":\"استبدال الديوتيريوم يقلل طاقة كسر الرابطة؛ مما يسرع استقلاب الدواء 10 أضعاف ويسرع التخلص منه.\",\"en\":\"Deuterium substitution weakens bond dissociation energy, causing the drug to metabolize 10-fold faster and clear prematurely.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Bağ zayıflaması yanılgısı: C-D bağı C-H bağına göre daha ağır ve daha kararlıdır (sıfır noktası titreşim enerjisi daha düşüktür); kopması daha zordur ve metabolizmayı yavaşlatır (Kinetik İzotop Etkisi).\",\"ar\":\"مغالطة ضعف الرابطة: رابطة C-D أقوى وأثقل من C-H وتتطلب طاقة تنشيط أعلى لكسرها؛ مما يبطئ الاستقلاب (أثر النظائر الحركي).\",\"en\":\"Bond weakening fallacy: C-D bonds have lower zero-point vibrational energy and higher dissociation energy; heavier deuterium slows cleavage (Kinetic Isotope Effect).\"}},{\"id\":\"opt-12c\",\"text\":{\"tr\":\"Döteryum izotopik olarak hidrojenle aynı kütleye sahip olduğundan enzim hızında ve yarı ömürde hiçbir kinetik değişiklik saptanamaz.\",\"ar\":\"الديوتيريوم يملك نفس كتلة الهيدروجين نظائرياً ولذلك لا يطرأ أي تغيير حركي على سرعة الإنزيم أو العمر النصفي.\",\"en\":\"Deuterium possesses identical mass to hydrogen, so zero kinetic changes in enzymatic rate or drug half-life can ever be detected.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Özdeş kütle yanılgısı: Döteryum çekirdeğinde 1 proton ve 1 nötron barındırarak hidrojenden 2 kat daha ağırdır; bu kütle iki katlanması kH/kD = 6-8'e varan devasa primer kinetik izotop etkisi yaratır.\",\"ar\":\"مغالطة تطابق الكتلة: الديوتيريوم يحوي نيوتروناً إضافياً فيزن ضعف الهيدروجين؛ مما يولد فارقاً حركياً هائلاً يصل لـ 6-8 أضعاف.\",\"en\":\"Identical mass misconception: Deuterium contains a neutron, doubling its atomic mass; this 100% mass increase creates a large primary kinetic isotope effect (kH/kD = 6-8).\"}}]},\"technicalTerms\":[{\"term\":\"kinetik izotop etkisi (KIE)\",\"arContext\":\"تأثير النظائر الحركي (kinetic isotope effect)\"},{\"term\":\"metabolik stabilite optimizasyonu\",\"arContext\":\"تحسين الثباتية الاستقلابية\"}],\"hints\":[{\"tr\":\"Döteryum hidrojenin bir nötron fazlası olan kararlı ağır izotopudur.\",\"ar\":\"الديوتيريوم نظير ثقيل ومستقر للهيدروجين يحمل نيوتروناً إضافياً.\",\"en\":\"Deuterium is a stable, non-radioactive heavy isotope of hydrogen.\"},{\"tr\":\"C-D bağı C-H bağına göre daha kuvvetlidir ve koparılması daha zordur.\",\"ar\":\"رابطة C-D أقوى وأكثر ثباتاً من رابطة C-H ويصعب كسرها.\",\"en\":\"The C-D bond has lower zero-point energy and is significantly harder to break.\"},{\"tr\":\"CYP450 enzimi C-D bağını çok daha yavaş koparır; bu durum ilacın yarı ömrünü uzatır.\",\"ar\":\"يكسر CYP رابطة C-D ببطء شديد، مما يخفض التصفية ويطيل نصف عمر الدواء في الجسم.\",\"en\":\"Slower bond cleavage reduces clearance, extending the drug's therapeutic half-life.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":16}],\"config\":{\"options\":[{\"id\":\"opt-12a\",\"text\":\"C-D bağının CYP450 tarafından koparılması yavaşlar; metabolik klirens dramatik şekilde düşer ve eliminasyon yarı ömrü belirgin biçimde uzar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Muazzam bir farmasötik kimya ustalığı! Kinetik İzotop Etkisi (KIE): Döteryum hidrojenden iki kat ağırdır; C-D bağının sıfır noktası titreşim enerjisi daha düşüktür ve bağı kırmak ~5 kJ/mol daha fazla enerji ister. CYP450'nin hız kısıtlayıcı basamağı C-H koparılması olduğundan, döterizasyon reaksiyon hızını 6-7 kat yavaşlatır. Bu strateji FDA onaylı döterlenmiş ilaçlarda (örn. dötotetrabenazin) günde tek doza geçişi sağlamıştır.\"},{\"id\":\"opt-12b\",\"text\":\"Döteryum ikamesi bağ kopma enerjisini düşürür; bu yüzden ilaç 10 kat daha hızlı metabolize edilip hızla tükenir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Bağ zayıflaması yanılgısı: C-D bağı C-H bağına göre daha ağır ve daha kararlıdır (sıfır noktası titreşim enerjisi daha düşüktür); kopması daha zordur ve metabolizmayı yavaşlatır (Kinetik İzotop Etkisi).\"},{\"id\":\"opt-12c\",\"text\":\"Döteryum izotopik olarak hidrojenle aynı kütleye sahip olduğundan enzim hızında ve yarı ömürde hiçbir kinetik değişiklik saptanamaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Özdeş kütle yanılgısı: Döteryum çekirdeğinde 1 proton ve 1 nötron barındırarak hidrojenden 2 kat daha ağırdır; bu kütle iki katlanması kH/kD = 6-8'e varan devasa primer kinetik izotop etkisi yaratır.\"}],\"revealedOutcome\":{\"tr\":\"C-D bağının CYP450 tarafından koparılması yavaşlar; metabolik klirens dramatik şekilde düşer ve eliminasyon yarı ömrü belirgin biçimde uzar.\",\"ar\":\"يتباطأ كسر رابطة C-D بواسطة CYP450؛ فتهبط التصفية الاستقلابية بشكل ملحوظ ويمتد نصف عمر الإطراح الدوائي طويلاً.\",\"en\":\"CYP-mediated hydrogen abstraction slows markedly; metabolic clearance plunges and elimination half-life is substantially prolonged.\"},\"explanation\":{\"tr\":\"Muazzam bir farmasötik kimya ustalığı! Kinetik İzotop Etkisi (KIE): Döteryum hidrojenden iki kat ağırdır; C-D bağının sıfır noktası titreşim enerjisi daha düşüktür ve bağı kırmak ~5 kJ/mol daha fazla enerji ister. CYP450'nin hız kısıtlayıcı basamağı C-H koparılması olduğundan, döterizasyon reaksiyon hızını 6-7 kat yavaşlatır. Bu strateji FDA onaylı döterlenmiş ilaçlarda (örn. dötotetrabenazin) günde tek doza geçişi sağlamıştır.\",\"ar\":\"تمكن كيميائي صيدلاني استثنائي! تأثير النظائر الحركي (KIE): الديوتيريوم أثقل بمرتين من الهيدروجين، ورابطة C-D أقوى بنحو 5 kJ/mol. بما أن كسر الرابطة هو الخطوة المحددة للسرعة في CYP450، فإن استبدالها بديوتيريوم يبطئ الأيض 6-7 أضعاف، وهو أساس الأدوية المديترة مثل deutetrabenazine.\",\"en\":\"Flawless mastery! Kinetic Isotope Effect (KIE): Deuterium doubles hydrogen's atomic mass, lowering zero-point vibrational energy and requiring ~5 kJ/mol more activation energy to break. Because C-H abstraction is the rate-limiting step in CYP catalysis, deuteration slows clearance by 6-7 fold (pioneered in FDA-approved deutetrabenazine).\"}}}]},\"mc-mod5-les2\":{\"$schema\":\"../../../packages/platform/schema/lesson.schema.json\",\"id\":\"mc-mod5-les2\",\"courseId\":\"medchem\",\"moduleId\":\"mc-mod-05\",\"title\":{\"tr\":\"Faz II Konjugasyonu: Glukuronidasyon, Sülfasyon ve Glutatyon Detoksifikasyonu\",\"ar\":\"المرحلة الثانية: مسارات الاقتران بالجلوكورونيد والكبريتات والجلوتاثيون\",\"en\":\"Phase II Conjugation: Glucuronidation, Sulfation & Glutathione Pathways\"},\"order\":2,\"access\":\"free\",\"objective\":{\"tr\":\"UGT, SULT, NAT, GST transferaz enzimlerini, aktif kofaktörlerini (UDPGA, PAPS, Asetil-KoA, GSH), parasetamol hepatotoksisitesini ve metenamin üriner aktivasyonunu analiz etmek.\",\"ar\":\"تحليل إنزيمات التحويل UGT و SULT و NAT و GST، وكواشفها المنشطة، وآلية سمية الباراسيتامول وترياق NAC، وتنشيط الميثينامين البولي.\",\"en\":\"Analyze Phase II transferase mechanisms (UGT, SULT, NAT, GST), active cofactors (UDPGA, PAPS, Acetyl-CoA, GSH), paracetamol hepatotoxicity with NAC rescue, and urinary methenamine activation.\"},\"misconceptions\":[{\"tr\":\"Tüm Faz II konjugasyon reaksiyonlarının polariteyi ve suda çözünürlüğü mutlaka artırdığı yanılgısı (Asetilasyon polariteyi azaltır ve kristalüri yapar!).\",\"ar\":\"الظن الخاطئ بأن جميع تفاعلات الاقتران تزيد من قطبية الدواء وذوبانيته (الأستلة تقلل القطبية وتسبب البيلة البلورية!).\",\"en\":\"The misconception that all Phase II conjugations increase water solubility (Acetylation actually decreases polarity, causing sulfadiazine crystalluria!).\"},{\"tr\":\"Parasetamol aşırı dozunda karaciğer hasarının parasetamolün kendisi tarafından oluşturulduğu düşüncesi (Gerçek toksin CYP2E1'in ürettiği elektrofil NAPQI'dir).\",\"ar\":\"الاعتقاد الخاطئ بأن الباراسيتامول نفسه يدمر الكبد (السم الفعلي هو NAPQI الناتج عن CYP2E1 عند نفاد مخزون الجلوتاثيون).\",\"en\":\"The misconception that paracetamol itself directly destroys hepatocytes, ignoring CYP2E1 bioactivation to the electrophilic NAPQI quinoneimine.\"},{\"tr\":\"Bütün Faz II transferaz enzimlerinin sitozolde bulunduğu düşüncesi (UGT enzimi mikrozomaldir, endoplazmik retikulum membranına gömülüdür).\",\"ar\":\"الاعتقاد الخاطئ بوجود جميع إنزيمات الاقتران في السيتوزول (إنزيم UGT ميكروزومي مدمج في غشاء الشبكة الإندوبلازمية).\",\"en\":\"The false assumption that all Phase II transferases reside in the cytosol, missing that UGT is an integral endoplasmic reticulum membrane enzyme.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":2},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":4},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":31},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":32},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":33},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":35},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":36},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":40},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":43},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":44}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Foye's Principles of Medicinal Chemistry\",\"edition\":\"8th ed.\",\"topic\":\"Phase II Conjugation Pathways: Glucuronidation, Sulfation, Acetylation, and Glutathione\",\"chapter\":\"Chapter 4: Drug Biotransformation\",\"page\":\"135-168\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Wilson and Gisvold's Textbook of Organic Medicinal and Pharmaceutical Chemistry\",\"edition\":\"12th ed.\",\"topic\":\"Conjugation Reactions, Mercapturic Acid Synthesis, and Paracetamol Hepatotoxicity\",\"chapter\":\"Chapter 4: Metabolic Changes of Drugs and Related Organic Compounds\",\"page\":\"150-185\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"mc-mod5-les2-card1\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Glukuronidasyon vs Sülfasyon Kinetiği\",\"prompt\":\"Parasetamolün fenolik -OH grubu için yarışan UGT ve SULT enzimlerinin afinite ve kapasite farkı nedir?\",\"answer\":\"SULT yüksek afiniteli / düşük kapasitelidir (terapötik düşük dozda etkindir, hızla doyar); UGT ise düşük afiniteli / yüksek kapasitelidir (büyük yükleri metabolize eder).\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod5-les2-card2\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Asetilasyon İstisnası ve Kristalüri\",\"prompt\":\"Faz II konjugasyonları genelde polariteyi artırırken, asetilasyon (NAT-2) neden sülfadiazin kristalürisine yol açar?\",\"answer\":\"Asetilasyon bazik amino grubunu nötr amite çevirerek molekülün polaritesini ve iyonlaşmasını azaltır; N4-asetilsülfadiazin asidik idrarda çözünmeyip böbrek tübüllerinde çöker.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod5-les2-card3\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Parasetamol Hepatotoksisitesi ve NAC Antidotu\",\"prompt\":\"Parasetamol aşırı dozunda karaciğer nekrozunu başlatan olay nedir ve N-asetilsistein (NAC) bunu nasıl önler?\",\"answer\":\"SULT ve UGT doyunca CYP2E1 aşırı miktarda elektrofil NAPQI üretir; hepatik glutatyon (GSH) >%70 tükenince NAPQI proteinlere kovalent bağlanır. NAC, sistein havuzunu artırarak GSH sentezini yeniler.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod5-les2-card4\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Merkaptürik Asit Sentez Yolu\",\"prompt\":\"Toksik elektrofillere bağlanan glutatyon (GSH) idrarla atılacak merkaptürik aside nasıl dönüştürülür?\",\"answer\":\"GSH konjugatından gamma-glutamiltranspeptidaz glutamatı, dipeptidaz ise glisini koparır; kalan sistein konjugatı NAT ile N-asetillenerek merkaptürik asit oluşturur.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"mc-mod5-les2-card5\",\"courseId\":\"medchem\",\"drugOrConcept\":\"Metenamin Ön İlacı ve İdrar pH Şartı\",\"prompt\":\"Metenamin (hekzametilentetramin) kanda stabilken idrarda bakterileri nasıl öldürür ve bunun ön şartı nedir?\",\"answer\":\"Kanda ve pH 7.4'te inaktiftir; idrar pH'ı <5.5 (asidik) olduğunda kendiliğinden hidroliz olarak 6 formaldehit açığa çıkarır ve bakteriyel proteinleri denatüre eder.\",\"box\":1,\"intervalDays\":1}],\"translations\":{\"tr\":{\"title\":\"Faz II Konjugasyonu: Glukuronidasyon, Sülfasyon ve Glutatyon Detoksifikasyonu\"},\"ar\":{\"title\":\"المرحلة الثانية: مسارات الاقتران بالجلوكورونيد والكبريتات والجلوتاثيون\"},\"en\":{\"title\":\"Phase II Conjugation: Glucuronidation, Sulfation & Glutathione Pathways\"}},\"steps\":[{\"id\":\"mc-mod5-les2-step-01\",\"stage\":\"hook\",\"stageIndex\":1,\"type\":\"predict_reveal\",\"title\":{\"tr\":\"Sessiz Zehirlenme: 15 Gram Parasetamol ve 48 Saatlik Uçurum\",\"ar\":\"التسمم الصامت: 15 غراماً من الباراسيتامول وهاوية الـ 48 ساعة\",\"en\":\"The Silent Overdose: 15 Grams of Paracetamol & The 48-Hour Cliff\"},\"prompt\":{\"tr\":\"15 gram parasetamol yutan bir genç ilk 6 saatte tamamen sağlıklıdır; ne bulantı ne ağrı duyar. Ancak 48 saat sonra karaciğer enzimleri 10.000 U/L'ye fırlar ve fulminan nekroz başlar. Hangi koruyucu kalkan çökmüştür?\",\"ar\":\"تناول مريض 15 غراماً من الباراسيتامول وبدا سليماً تماماً في الساعات الست الأولى. بعد 48 ساعة قفزت إنزيمات الكبد فوق 10,000 وحدة وبدأ التنخر الكبدي المميت. ما هو الدرع الواقي الذي انهار؟\",\"en\":\"A patient ingests 15 grams of paracetamol and feels completely fine for the first 6 hours. Yet at 48 hours, liver transaminases exceed 10,000 U/L with fatal hepatic necrosis. What cellular defense shield collapsed?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-1a\",\"text\":{\"tr\":\"Karaciğerdeki UGT ve SULT enzimleri doymuş, CYP2E1 toksik NAPQI üretmiş ve hücresel koruyucu glutatyon (GSH) rezervi tamamen tükenmiştir.\",\"ar\":\"تشبعت إنزيمات UGT و SULT، فحول CYP2E1 الفائض إلى NAPQI السام ونفد مخزون الجلوتاثيون (GSH) الخلوي بالكامل.\",\"en\":\"UGT and SULT conjugations became saturated, shunting paracetamol to CYP2E1 to generate toxic NAPQI which exhausted hepatic glutathione (GSH) reserves.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Tam isabet! Slayt 35-36 mekanizması: Terapötik dozlarda parasetamolün %95'i glukuronidasyon ve sülfasyonla temizlenir. Aşırı dozda bu iki yol doyar; CYP2E1 devreye girerek elektrofilik NAPQI oluşturur. Hepatik glutatyon (GSH) rezervi >%70 tükendiğinde, NAPQI hepatosit proteinlerine kovalent bağlanıp hücre ölümünü başlatır.\",\"ar\":\"إصابة دقيقة! الشريحة 35-36: في الجرعات العادية يُطرح 95% بالاقتران السليم. عند الجرعة الزائدة تتشبع هذه الإنزيمات، وينشط CYP2E1 منتجاً NAPQI السام. عند نفاد الجلوتاثيون (>70%)، يهاجم NAPQI بروتينات الكبد تساهمياً مسبباً الموت الخلوي.\",\"en\":\"Exact hit! Slides 35-36 mechanism: Therapeutic paracetamol is cleared safely (>95%) by glucuronidation and sulfation. Overdose saturates these transferases, shunting the drug to CYP2E1 to produce electrophilic NAPQI. Once hepatic GSH falls below 30%, NAPQI covalently attacks mitochondrial proteins.\"}},{\"id\":\"opt-1b\",\"text\":{\"tr\":\"Parasetamol doğrudan santral COX enzimlerini kalıcı olarak bloke etmiş; prostaglandin sentezinin sıfırlanmasıyla mide ve damar perfüzyonu çökmüştür.\",\"ar\":\"قام الباراسيتامول بتثبيط إنزيمات COX المركزية بشكل دائم، مما أوقف البروستاغلاندين وسبب انهيار التروية الدموية.\",\"en\":\"Paracetamol irreversibly blocks central and peripheral COX enzymes, obliterating prostaglandin synthesis and collapsing systemic perfusion.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"COX blokajı yanılgısı: Parasetamolün analjezik/antipiretik etkisi santral COX inhibisyonuna dayanır ancak bu mekanizma ölümcül değildir; hepatotoksisitenin tek nedeni CYP2E1 ile oluşan reaktif elektrofilik metabolit NAPQI'dir.\",\"ar\":\"مغالطة تثبيط COX: التأثير المسكن يعتمد على تثبيط COX، لكن السمية الكبدية القاتلة تنشأ حصراً من تشكل المستقلب الإلكتروفيلي التفاعلي NAPQI بواسطة CYP2E1.\",\"en\":\"COX inhibition fallacy: Analgesia stems from central COX inhibition, but lethal hepatotoxicity is strictly caused by the electrophilic reactive metabolite NAPQI generated by CYP2E1.\"}},{\"id\":\"opt-1c\",\"text\":{\"tr\":\"Aşırı dozda ana parasetamol molekülü değişmeden hepatosit nükleusuna girerek doğrudan DNA zincirlerine interkale olup hücreleri öldürmüştür.\",\"ar\":\"دخلت جزيئات الباراسيتامول السليمة دون استقلاب إلى نواة الخلايا الكبدية واندست مباشرة في شريط DNA مسببة الموت الخلوي.\",\"en\":\"Intact unchanged paracetamol accumulates in hepatocyte nuclei and intercalates directly into genomic DNA to trigger acute cellular lysis.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Doğrudan intakt ilaç toksisitesi yanılgısı: Parasetamol molekülünün kendisi hepatotoksik veya DNA interkalatörü değildir; toksisite ancak ana ilacın CYP2E1 enzimiyle reaktif elektrofilik NAPQI'ye biyotransforme olmasıyla başlar.\",\"ar\":\"مغالطة السمية المباشرة للدواء الأصلي: الباراسيتامول السليم غير سام بحد ذاته؛ السمية تتطلب التحول الحيوي عبر CYP2E1 إلى المركب الإلكتروفيلي NAPQI.\",\"en\":\"Direct parent toxicity fallacy: Intact paracetamol is biologically inert to DNA; toxicity strictly requires enzymatic bioactivation by CYP2E1 into electrophilic NAPQI.\"}}]},\"technicalTerms\":[{\"term\":\"glutatyon (GSH) tükenmesi\",\"arContext\":\"استنزاف الجلوتاثيون (GSH depletion)\"},{\"term\":\"N-asetil-p-benzokinonimin (NAPQI)\",\"arContext\":\"المركب السام NAPQI\"}],\"hints\":[{\"tr\":\"Parasetamolün normal temizleme yolları (glukuronidasyon ve sülfasyon) aşırı dozda kapasitesini aşar.\",\"ar\":\"تتجاوز الجرعة الزائدة الطاقة الاستيعابية لمسارات الاقتران الطبيعية (الجلوكورونيد والكبريتات).\",\"en\":\"Excessive doses rapidly overwhelm the saturation capacity of primary conjugation pathways.\"},{\"tr\":\"CYP2E1 enzimi fazlalığı oksitleyerek reaktif bir kinonimin elektrofiline (NAPQI) çevirir.\",\"ar\":\"يؤكسد CYP2E1 الفائض ليحوله إلى إلكتروفيل كينونيمين عالي السمية (NAPQI).\",\"en\":\"Diverted substrate is oxidized by CYP2E1 into the electrophilic toxin NAPQI.\"},{\"tr\":\"Karaciğerdeki koruyucu tripeptit (glutatyon) bittiğinde NAPQI hücre proteinlerini yok etmeye başlar.\",\"ar\":\"عندما ينفد ببتيد الجلوتاثيون الواقي بالكبد، يبدأ NAPQI بتدمير بروتينات الخلية.\",\"en\":\"When protective glutathione reserves run out, NAPQI attacks vital hepatocyte proteins.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":35}],\"config\":{\"options\":[{\"id\":\"opt-1a\",\"text\":\"Karaciğerdeki UGT ve SULT enzimleri doymuş, CYP2E1 toksik NAPQI üretmiş ve hücresel koruyucu glutatyon (GSH) rezervi tamamen tükenmiştir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Tam isabet! Slayt 35-36 mekanizması: Terapötik dozlarda parasetamolün %95'i glukuronidasyon ve sülfasyonla temizlenir. Aşırı dozda bu iki yol doyar; CYP2E1 devreye girerek elektrofilik NAPQI oluşturur. Hepatik glutatyon (GSH) rezervi >%70 tükendiğinde, NAPQI hepatosit proteinlerine kovalent bağlanıp hücre ölümünü başlatır.\"},{\"id\":\"opt-1b\",\"text\":\"Parasetamol doğrudan santral COX enzimlerini kalıcı olarak bloke etmiş; prostaglandin sentezinin sıfırlanmasıyla mide ve damar perfüzyonu çökmüştür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"COX blokajı yanılgısı: Parasetamolün analjezik/antipiretik etkisi santral COX inhibisyonuna dayanır ancak bu mekanizma ölümcül değildir; hepatotoksisitenin tek nedeni CYP2E1 ile oluşan reaktif elektrofilik metabolit NAPQI'dir.\"},{\"id\":\"opt-1c\",\"text\":\"Aşırı dozda ana parasetamol molekülü değişmeden hepatosit nükleusuna girerek doğrudan DNA zincirlerine interkale olup hücreleri öldürmüştür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Doğrudan intakt ilaç toksisitesi yanılgısı: Parasetamol molekülünün kendisi hepatotoksik veya DNA interkalatörü değildir; toksisite ancak ana ilacın CYP2E1 enzimiyle reaktif elektrofilik NAPQI'ye biyotransforme olmasıyla başlar.\"}],\"revealedOutcome\":{\"tr\":\"Karaciğerdeki UGT ve SULT enzimleri doymuş, CYP2E1 toksik NAPQI üretmiş ve hücresel koruyucu glutatyon (GSH) rezervi tamamen tükenmiştir.\",\"ar\":\"تشبعت إنزيمات UGT و SULT، فحول CYP2E1 الفائض إلى NAPQI السام ونفد مخزون الجلوتاثيون (GSH) الخلوي بالكامل.\",\"en\":\"UGT and SULT conjugations became saturated, shunting paracetamol to CYP2E1 to generate toxic NAPQI which exhausted hepatic glutathione (GSH) reserves.\"},\"explanation\":{\"tr\":\"Tam isabet! Slayt 35-36 mekanizması: Terapötik dozlarda parasetamolün %95'i glukuronidasyon ve sülfasyonla temizlenir. Aşırı dozda bu iki yol doyar; CYP2E1 devreye girerek elektrofilik NAPQI oluşturur. Hepatik glutatyon (GSH) rezervi >%70 tükendiğinde, NAPQI hepatosit proteinlerine kovalent bağlanıp hücre ölümünü başlatır.\",\"ar\":\"إصابة دقيقة! الشريحة 35-36: في الجرعات العادية يُطرح 95% بالاقتران السليم. عند الجرعة الزائدة تتشبع هذه الإنزيمات، وينشط CYP2E1 منتجاً NAPQI السام. عند نفاد الجلوتاثيون (>70%)، يهاجم NAPQI بروتينات الكبد تساهمياً مسبباً الموت الخلوي.\",\"en\":\"Exact hit! Slides 35-36 mechanism: Therapeutic paracetamol is cleared safely (>95%) by glucuronidation and sulfation. Overdose saturates these transferases, shunting the drug to CYP2E1 to produce electrophilic NAPQI. Once hepatic GSH falls below 30%, NAPQI covalently attacks mitochondrial proteins.\"}}},{\"id\":\"mc-mod5-les2-step-02\",\"stage\":\"question\",\"stageIndex\":2,\"type\":\"question\",\"title\":{\"tr\":\"Glukuronidasyon vs Sülfasyon: Hangi Yol Ne Zaman Kazanır?\",\"ar\":\"الجلوكورونيد مقابل الكبريتات: من يحسم سباق الاستقلاب؟\",\"en\":\"Glucuronidation vs. Sulfation: When Does Each Pathway Win?\"},\"prompt\":{\"tr\":\"Parasetamolün tek bir fenolik -OH grubu vardır. Hem UGT hem SULT enzimleri bu grup için yarışır. Terapötik düşük dozda sülfasyon, yüksek dozda ise neden glukuronidasyon baskındır?\",\"ar\":\"يمتلك الباراسيتامول مجموعة هيدروكسيل فينولية وحيدة تتنافس عليها إنزيمات UGT و SULT. لماذا تسود الكبرتة في الجرعات المنخفضة ويسود الجلوكورونيد في المرتفعة؟\",\"en\":\"Paracetamol presents a single phenolic -OH. Both UGT and SULT compete for this exact locus. Why does sulfation dominate at low therapeutic doses, while glucuronidation takes over at higher doses?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-2a\",\"text\":{\"tr\":\"SULT yüksek afiniteli/düşük kapasitelidir (PAPS kofaktörü hızla biter); UGT ise düşük afiniteli/yüksek kapasitelidir (büyük ilaç yüklerini taşır).\",\"ar\":\"إنزيم SULT ذو ألفة عالية وسعة منخفضة (ينفد كاشف PAPS سريعاً)؛ بينما UGT ذو ألفة أقل وسعة هائلة لاستيعاب الجرعات الكبيرة.\",\"en\":\"SULT exhibits high affinity but low capacity (PAPS cofactor depletes rapidly); UGT has lower affinity but enormous capacity to clear heavy drug loads.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel farmakokinetik kavrayış! Slayt 32-33 ve Foye prensibi: Sülfotransferazların Km değeri düşüktür (yüksek afinite), bu yüzden 500 mg'lık dozda sülfasyon (%35) çok etkindir. Ancak hücredeki PAPS kofaktör havuzu kısıtlıdır ve SULT hızla doygunluğa (Vmax) ulaşır. Mikrozomal UGT ise glikoz metabolizmasından beslenen devasa UDPGA havuzuna sahiptir ve yüksek dozları glukuronidasyon (%60) sırtlar.\",\"ar\":\"فهم حركي دوائي رائع! الشريحة 32-33: يمتلك SULT قيمة Km منخفضة (شراهة عالية) فيعمل بكفاءة بالجرعات العادية، لكن مخزون كاشف PAPS محدود ويتشبع الإنزيم سريعاً. بالمقابل، يمتلك UGT سعة ضخمة مدعومة بمخزون UDPGA الوفير المشتق من الجلوكوز.\",\"en\":\"Flawless pharmacokinetic insight! Slides 32-33: SULT possesses low Km (high affinity), efficiently sulfating paracetamol at therapeutic doses. However, PAPS pools are easily depleted. UGT exhibits high capacity fed by abundant glycogen-derived UDPGA, handling the bulk load.\"}},{\"id\":\"opt-2b\",\"text\":{\"tr\":\"Fenolik -OH grubu yüksek dozda sterik engele uğrar; SULT enzimi aromatik halkaları tanıyamaz hale gelirken UGT yalnızca alifatik zincirlere bağlanır.\",\"ar\":\"تتعرض مجموعة الفينول لإعاقة فراغية بالجرعات العالية، فيعجز SULT عن تمييز الحلقات العطرية بينما يختص UGT بالسلاسل الأليفاتية.\",\"en\":\"High drug concentrations induce steric hindrance at the phenolic ring, preventing SULT binding while UGT selectively targets aliphatic chains.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Substrat özgüllüğü yanılgısı: Hem SULT hem UGT fenolik -OH gruplarını mükemmel tanır; yolak baskınlığındaki değişim sterik engelden değil, enzimlerin Km değerleri ve hücre içi kofaktör (PAPS vs UDPGA) kapasitesinden kaynaklanır.\",\"ar\":\"مغالطة نوعية الركيزة: يتعرف كلا الإنزيمين على الفينول بكفاءة؛ التبدل يعود لقيم Km وسعة المخزون الخلوي للمرافقات الإنزيمية (PAPS مقابل UDPGA).\",\"en\":\"Substrate selectivity misconception: Both enzymes efficiently conjugate phenols; pathway shifting is driven by differential Km values and intracellular cofactor reserves (PAPS vs UDPGA).\"}},{\"id\":\"opt-2c\",\"text\":{\"tr\":\"Sülfat konjugatları kanda kararsızdır; yüksek ilaç derişiminde kimyasal denge geri döner ve sülfatlar hızla hidroliz edilerek serbest ilaca dönüşür.\",\"ar\":\"مركبات الكبريتات غير مستقرة بالدم؛ عند التراكيز العالية ينعكس التوازن الكيميائي وتتحلمه الكبريتات بسرعة محررة الدواء الأصلي.\",\"en\":\"Sulfate conjugates are chemically unstable in circulation; elevated drug concentrations shift equilibrium toward spontaneous back-hydrolysis into parent paracetamol.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Geri hidroliz yanılgısı: Parasetamol sülfat kovalent bağlı son derece kararlı bir metabolittir ve kanda kendiliğinden hidroliz olmaz; düşük dozda baskın olmasının nedeni yüksek afinite (düşük Km), yüksek dozda doymasının nedeni ise kısıtlı PAPS havuzudur.\",\"ar\":\"مغالطة الحلمهة العكسية: كبريتات الباراسيتامول مركب تساهمي مستقر للغاية لا يتحلمه في الدم؛ سيطرة المسار بالجرع المنخفضة سببها الألفة العالية ونفاذ PAPS لاحقاً.\",\"en\":\"Reverse hydrolysis fallacy: Paracetamol sulfate is a highly stable covalent metabolite in plasma; saturation arises from stoichiometric depletion of PAPS cofactors.\"}}]},\"technicalTerms\":[{\"term\":\"Km ve Vmax enzim kinetiği\",\"arContext\":\"حركية الإنزيمات Km و Vmax\"},{\"term\":\"kofaktör doygunluğu\",\"arContext\":\"تشبع الكواشف المانحة (cofactor saturation)\"}],\"hints\":[{\"tr\":\"Düşük dozda ilaca ilk sarılan enzim yüksek afiniteli olandır (Km değeri küçüktür).\",\"ar\":\"في التراكيز المنخفضة، يرتبط الإنزيم صاحب الألفة الفائقة (قيمة Km صغيرة) أولاً.\",\"en\":\"At low substrate concentrations, the high-affinity enzyme (lower Km) dominates.\"},{\"tr\":\"Sülfasyon kofaktörü PAPS hücrede sınırlı miktardadır ve hızla tükenir.\",\"ar\":\"كاشف الكبرتة PAPS يتواجد بكميات خلوية محدودة ويتشبع سريعاً.\",\"en\":\"The sulfate donor PAPS is present in limited stoichiometric supply in cytosol.\"},{\"tr\":\"Glukuronidasyon kofaktörü UDPGA glikozdan üretilir; kapasitesi sülfasyondan kat kat geniştir.\",\"ar\":\"كاشف UDPGA مشتق من الجلوكوز ويمتلك سعة استيعابية تفوق الكبريتات بأضعاف.\",\"en\":\"UDPGA is derived from abundant glycogen stores, providing immense glucuronidation capacity.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":32}],\"config\":{\"options\":[{\"id\":\"opt-2a\",\"text\":\"SULT yüksek afiniteli/düşük kapasitelidir (PAPS kofaktörü hızla biter); UGT ise düşük afiniteli/yüksek kapasitelidir (büyük ilaç yüklerini taşır).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel farmakokinetik kavrayış! Slayt 32-33 ve Foye prensibi: Sülfotransferazların Km değeri düşüktür (yüksek afinite), bu yüzden 500 mg'lık dozda sülfasyon (%35) çok etkindir. Ancak hücredeki PAPS kofaktör havuzu kısıtlıdır ve SULT hızla doygunluğa (Vmax) ulaşır. Mikrozomal UGT ise glikoz metabolizmasından beslenen devasa UDPGA havuzuna sahiptir ve yüksek dozları glukuronidasyon (%60) sırtlar.\"},{\"id\":\"opt-2b\",\"text\":\"Fenolik -OH grubu yüksek dozda sterik engele uğrar; SULT enzimi aromatik halkaları tanıyamaz hale gelirken UGT yalnızca alifatik zincirlere bağlanır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Substrat özgüllüğü yanılgısı: Hem SULT hem UGT fenolik -OH gruplarını mükemmel tanır; yolak baskınlığındaki değişim sterik engelden değil, enzimlerin Km değerleri ve hücre içi kofaktör (PAPS vs UDPGA) kapasitesinden kaynaklanır.\"},{\"id\":\"opt-2c\",\"text\":\"Sülfat konjugatları kanda kararsızdır; yüksek ilaç derişiminde kimyasal denge geri döner ve sülfatlar hızla hidroliz edilerek serbest ilaca dönüşür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Geri hidroliz yanılgısı: Parasetamol sülfat kovalent bağlı son derece kararlı bir metabolittir ve kanda kendiliğinden hidroliz olmaz; düşük dozda baskın olmasının nedeni yüksek afinite (düşük Km), yüksek dozda doymasının nedeni ise kısıtlı PAPS havuzudur.\"}],\"revealedOutcome\":{\"tr\":\"SULT yüksek afiniteli/düşük kapasitelidir (PAPS kofaktörü hızla biter); UGT ise düşük afiniteli/yüksek kapasitelidir (büyük ilaç yüklerini taşır).\",\"ar\":\"إنزيم SULT ذو ألفة عالية وسعة منخفضة (ينفد كاشف PAPS سريعاً)؛ بينما UGT ذو ألفة أقل وسعة هائلة لاستيعاب الجرعات الكبيرة.\",\"en\":\"SULT exhibits high affinity but low capacity (PAPS cofactor depletes rapidly); UGT has lower affinity but enormous capacity to clear heavy drug loads.\"},\"explanation\":{\"tr\":\"Mükemmel farmakokinetik kavrayış! Slayt 32-33 ve Foye prensibi: Sülfotransferazların Km değeri düşüktür (yüksek afinite), bu yüzden 500 mg'lık dozda sülfasyon (%35) çok etkindir. Ancak hücredeki PAPS kofaktör havuzu kısıtlıdır ve SULT hızla doygunluğa (Vmax) ulaşır. Mikrozomal UGT ise glikoz metabolizmasından beslenen devasa UDPGA havuzuna sahiptir ve yüksek dozları glukuronidasyon (%60) sırtlar.\",\"ar\":\"فهم حركي دوائي رائع! الشريحة 32-33: يمتلك SULT قيمة Km منخفضة (شراهة عالية) فيعمل بكفاءة بالجرعات العادية، لكن مخزون كاشف PAPS محدود ويتشبع الإنزيم سريعاً. بالمقابل، يمتلك UGT سعة ضخمة مدعومة بمخزون UDPGA الوفير المشتق من الجلوكوز.\",\"en\":\"Flawless pharmacokinetic insight! Slides 32-33: SULT possesses low Km (high affinity), efficiently sulfating paracetamol at therapeutic doses. However, PAPS pools are easily depleted. UGT exhibits high capacity fed by abundant glycogen-derived UDPGA, handling the bulk load.\"}}},{\"id\":\"mc-mod5-les2-step-03\",\"stage\":\"intuition\",\"stageIndex\":3,\"type\":\"intuition\",\"title\":{\"tr\":\"Sezgisel Model: Otoban Gişesi vs Konteyner Limanı\",\"ar\":\"النموذج الحدسي: كشك المرور السريع مقابل الميناء التجاري العملاق\",\"en\":\"Mental Model: The Express Tollbooth vs. The Mega Port\"},\"prompt\":{\"tr\":\"SULT ve UGT enzimlerini anlamak için gişe modelini düşünün. SULT tek şeritli hızlı gişedir; UGT ise 20 kapılı devasa konteyner limanıdır. İlaç dozu arttığında trafikte ne yaşanır?\",\"ar\":\"تخيل أن SULT كشك مرور سريع بممر واحد، بينما UGT ميناء تجاري بعشرين رصيفاً. ماذا يحدث لحركة المرور الاستقلابية عند تدفق شحنة أدوية ضخمة؟\",\"en\":\"Picture SULT as a single-lane fast express tollbooth and UGT as a 20-berth container mega-port. What happens to metabolic traffic when a massive surge of drug molecules arrives?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-3a\",\"text\":{\"tr\":\"SULT tek şeridi hızla tıkanır ve doyuma ulaşır; kalan tüm trafik UGT'nin devasa limanına akar.\",\"ar\":\"يختنق مسار SULT سريعاً ويصل لأقصى طاقته، فتتحول قوافل الجزيئات بأكملها إلى أرصفة UGT الضخمة.\",\"en\":\"The single SULT lane jams and reaches full saturation; all remaining traffic is routed through UGT's massive deep-water terminal.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika bir zihinsel model! SULT enziminin PAPS rezervi azdır; 500 mg parasetamolde hızlıca çalışır ama 2-3 gramda tamamen kilitlenir. UGT ise karaciğer glikojen depolarından beslenen tükenmez UDPGA stoğuyla tüm trafiği sırtlar. Doz 10 gramı aştığında ise her iki gişe de çöker ve arabalar uçuruma (CYP2E1 toksik yoluna) yuvarlanır.\",\"ar\":\"نموذج ذهني عبقري! ينفد كاشف PAPS في مسار SULT سريعاً عند زيادة الجرعة، فيتولى UGT العبء الأكبر بفضل فيض كواشف UDPGA. لكن عند تجاوز 10 غرامات، تنهار كل المنافذ وتهوي الجزيئات في هاوية CYP2E1 لتكوين السم NAPQI.\",\"en\":\"Superb conceptual anchor! SULT's low PAPS capacity saturates at modest doses. UGT's massive UDPGA reservoir absorbs the bulk overflow. When intake exceeds 10 grams, even UGT saturates, forcing molecules down the catastrophic CYP2E1 shunt.\"}},{\"id\":\"opt-3b\",\"text\":{\"tr\":\"Kapasite aşılınca karaciğer değişmemiş lipofilik ilacı hızla safra kanallarına pompalar ve enterohepatik döngüyle tüm ilaç feçesle atılır.\",\"ar\":\"عند تجاوز السعة، يضخ الكبد الدواء غير المتغير إلى القنوات الصفراوية ليُطرح تماماً عبر الدوران المعوي الكبدي في البراز.\",\"en\":\"Upon capacity overload, hepatocytes actively pump unconjugated lipophilic drug into bile canaliculi for complete elimination in feces via enterohepatic recirculation.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Enterohepatik kaçış yanılgısı: Lipofilik ksenobiyotikler konjuge edilmeden safraya verimli bir şekilde atılamaz; safraya atılan metabolitler çoğunlukla polar glukuronitlerdir. Ana ilaç kanda dolaşmaya devam eder ve CYP2E1 ile oksitlenir.\",\"ar\":\"مغالطة الطرح الصفراوي: لا يمكن طرح الأدوية المحبة للدهون في الصفراء دون اقتران قطبي؛ الدواء الحر غير المقترن يبقى في الدم ليتأكسد عبر CYP2E1.\",\"en\":\"Biliary clearance misconception: Lipophilic xenobiotics cannot be efficiently eliminated in bile without polar conjugation; excess drug remains circulating and enters CYP2E1 oxidation.\"}},{\"id\":\"opt-3c\",\"text\":{\"tr\":\"Karaciğer enzimleri doyunca böbrek glomerülleri filtre etme kapasitesini 50 kat artırarak değişmemiş serbest ilacı hızla idrara süzer.\",\"ar\":\"عند تشبع إنزيمات الكبد، تضاعف الكبيبات الكلوية سعة الترشيح 50 ضعفاً لتصفية الدواء الحر غير المتغير في البول بسرعة.\",\"en\":\"Once hepatic enzymes saturate, glomerular filtration upregulates 50-fold to eliminate the excess lipophilic paracetamol unchanged directly in urine.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Böbrek kompanzasyonu yanılgısı: Parasetamol zayıf lipofiliktir ve böbrek tübüllerinden pasif olarak geri emilir; idrarla atılabilmesi için mutlaka Faz II enzimleri (özellikle UGT) tarafından polar bir konjugata çevrilmesi şarttır.\",\"ar\":\"مغالطة التعويض الكلوي: الباراسيتامول محب للدهون جزئياً ويُعاد امتصاصه عبر الأنابيب الكلوية؛ التخلص منه في البول يتطلب حتماً تحويله لمشتق قطبي مقترن عبر UGT.\",\"en\":\"Renal compensation fallacy: Unconjugated paracetamol is passively reabsorbed across renal tubules; rapid urinary clearance strictly requires conversion to polar Phase II conjugates.\"}}]},\"technicalTerms\":[{\"term\":\"biyotransformasyon doygunluğu\",\"arContext\":\"تشبع التحول الحيوي (biotransformation saturation)\"},{\"term\":\"toksik şantlanma (pathway shunting)\",\"arContext\":\"التحول نحو المسار السام\"}],\"hints\":[{\"tr\":\"Hızlı ama dar bir kapı yoğun yük altında ilk önce tıkanır.\",\"ar\":\"البوابة السريعة الضيقة هي أول ما يختنق عند تدفق الحشود الكبيرة.\",\"en\":\"A fast but narrow gateway is the first to become overwhelmed by a surge.\"},{\"tr\":\"Geniş liman (UGT) kapasitesi sayesinde aşırı yükü göğüsleyebilir.\",\"ar\":\"الميناء الواسع (UGT) قادر على استيعاب الحمولات الضخمة بفضل سعته الفائقة.\",\"en\":\"The high-capacity terminal (UGT) accommodates the bulk load.\"},{\"tr\":\"Kapasite aşıldığında metabolizma alternatif toksik yola (CYP) kayar.\",\"ar\":\"عند فيضان الطاقة الاستيعابية، تنحرف الجزيئات للمسار السام البديل (CYP).\",\"en\":\"When both safe outlets overflow, molecules are shunted to the toxic CYP pathway.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":32}],\"config\":{\"options\":[{\"id\":\"opt-3a\",\"text\":\"SULT tek şeridi hızla tıkanır ve doyuma ulaşır; kalan tüm trafik UGT'nin devasa limanına akar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika bir zihinsel model! SULT enziminin PAPS rezervi azdır; 500 mg parasetamolde hızlıca çalışır ama 2-3 gramda tamamen kilitlenir. UGT ise karaciğer glikojen depolarından beslenen tükenmez UDPGA stoğuyla tüm trafiği sırtlar. Doz 10 gramı aştığında ise her iki gişe de çöker ve arabalar uçuruma (CYP2E1 toksik yoluna) yuvarlanır.\"},{\"id\":\"opt-3b\",\"text\":\"Kapasite aşılınca karaciğer değişmemiş lipofilik ilacı hızla safra kanallarına pompalar ve enterohepatik döngüyle tüm ilaç feçesle atılır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Enterohepatik kaçış yanılgısı: Lipofilik ksenobiyotikler konjuge edilmeden safraya verimli bir şekilde atılamaz; safraya atılan metabolitler çoğunlukla polar glukuronitlerdir. Ana ilaç kanda dolaşmaya devam eder ve CYP2E1 ile oksitlenir.\"},{\"id\":\"opt-3c\",\"text\":\"Karaciğer enzimleri doyunca böbrek glomerülleri filtre etme kapasitesini 50 kat artırarak değişmemiş serbest ilacı hızla idrara süzer.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Böbrek kompanzasyonu yanılgısı: Parasetamol zayıf lipofiliktir ve böbrek tübüllerinden pasif olarak geri emilir; idrarla atılabilmesi için mutlaka Faz II enzimleri (özellikle UGT) tarafından polar bir konjugata çevrilmesi şarttır.\"}],\"revealedOutcome\":{\"tr\":\"SULT tek şeridi hızla tıkanır ve doyuma ulaşır; kalan tüm trafik UGT'nin devasa limanına akar.\",\"ar\":\"يختنق مسار SULT سريعاً ويصل لأقصى طاقته، فتتحول قوافل الجزيئات بأكملها إلى أرصفة UGT الضخمة.\",\"en\":\"The single SULT lane jams and reaches full saturation; all remaining traffic is routed through UGT's massive deep-water terminal.\"},\"explanation\":{\"tr\":\"Harika bir zihinsel model! SULT enziminin PAPS rezervi azdır; 500 mg parasetamolde hızlıca çalışır ama 2-3 gramda tamamen kilitlenir. UGT ise karaciğer glikojen depolarından beslenen tükenmez UDPGA stoğuyla tüm trafiği sırtlar. Doz 10 gramı aştığında ise her iki gişe de çöker ve arabalar uçuruma (CYP2E1 toksik yoluna) yuvarlanır.\",\"ar\":\"نموذج ذهني عبقري! ينفد كاشف PAPS في مسار SULT سريعاً عند زيادة الجرعة، فيتولى UGT العبء الأكبر بفضل فيض كواشف UDPGA. لكن عند تجاوز 10 غرامات، تنهار كل المنافذ وتهوي الجزيئات في هاوية CYP2E1 لتكوين السم NAPQI.\",\"en\":\"Superb conceptual anchor! SULT's low PAPS capacity saturates at modest doses. UGT's massive UDPGA reservoir absorbs the bulk overflow. When intake exceeds 10 grams, even UGT saturates, forcing molecules down the catastrophic CYP2E1 shunt.\"}}},{\"id\":\"mc-mod5-les2-step-04\",\"stage\":\"visual_explanation\",\"stageIndex\":4,\"type\":\"visual_explanation\",\"title\":{\"tr\":\"Asetilasyon Paradoksu: Sülfadiazin Neden Böbrekte Çöker?\",\"ar\":\"مفارقة الأستلة: لماذا يترسب السلفاديازين في الكلى؟\",\"en\":\"The Acetylation Paradox: Why Does Sulfadiazine Precipitate in Kidneys?\"},\"prompt\":{\"tr\":\"Genel kural: 'Faz II konjugasyonları molekülü daha polar ve suda çözünür yapar.' Ancak sülfadiazin karaciğerde N4-asetillendiğinde böbrek tübüllerinde kristalüri (çökelme) yapar! Bu kural dışı çelişkinin kimyasal sebebi nedir?\",\"ar\":\"القاعدة: تفاعلات المرحلة الثانية تزيد القطبية والذوبانية. لكن أستلة السلفاديازين تؤدي لترسبه بلورياً في الكلى! ما هو السبب الكيميائي لهذا الاستثناء؟\",\"en\":\"General dogma states Phase II conjugation increases polarity and water solubility. Yet N4-acetylation of sulfadiazine precipitates in renal tubules as crystalluria! What chemical mechanism explains this paradox?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-4a\",\"text\":{\"tr\":\"Asetilasyon bazik primer amini nötr amite çevirir; iyonlaşma ve polarite azalır. Oluşan N4-asetil türevi asidik idrarda suda çözünmez ve çöker.\",\"ar\":\"تحول الأستلة الأمين الأولي القاعدي إلى أميد حيادي، فتنقص القطبية والتأين؛ مما يجعل المستقلب غير ذؤوب في البول الحمضي فيترسب.\",\"en\":\"Acetylation converts the basic primary amine into a neutral amide, decreasing polarity and ionization; the N4-acetyl metabolite is poorly soluble in acidic urine.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel kimyasal analiz! Slayt 2 ve 31'in en kritik sınav istisnası: Glukuronidasyon ve sülfasyon moleküle asidik iyonize gruplar takarken, N-asetilasyon (NAT-2) lipofilisiteyi artırır veya nötr bırakır. Sülfadiazin molekülündeki p-amino grubu asetillendiğinde çözünürlük dramatik şekilde düşer. Asidik idrarda kristalleşerek böbrek yetmezliği yapar (bu yüzden sülfonamidlerde bol su ve NaHCO3 verilir).\",\"ar\":\"تحليل كيميائي استثنائي! الشريحة 2 و 31: بينما يضيف الجلوكورونيد شحنات قطبية، فإن الأستلة (NAT-2) تقلل القطبية والذوبانية المائية. مركب N4-acetylsulfadiazine يترسب كبلورات إبرية في النبيبات الكلوية مسبباً بيلة بلورية وقصوراً كلوياً، لذا يُعطى المريض بيكربونات الصوديوم لجعل البول قلوياً.\",\"en\":\"Masterful chemical deduction! Slides 2 & 31 benchmark: Unlike glucuronidation, N-acetylation (NAT-2) masks the basic amine as a neutral lipophilic acetamide. N4-acetylsulfadiazine possesses drastically lower water solubility at acidic urine pH, forming sharp crystals that lacerate renal tubules unless alkalinized with NaHCO3.\"}},{\"id\":\"opt-4b\",\"text\":{\"tr\":\"N4-Asetil türevi idrardaki kalsiyum ve magnezyum iyonlarını şelatlayarak çözünmeyen inorganik taş kompleksleri oluşturur.\",\"ar\":\"يشلب مشتق N4-أسيتيل أيونات الكالسيوم والمغنيسيوم في البول مشكلاً معقدات حصوية غير قابلة للذوبان.\",\"en\":\"The N4-acetyl derivative chelates urinary calcium and magnesium cations, precipitating insoluble inorganic mineral complexes.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Şelasyon ve taş tipi yanılgısı: Kristalüri bir kalsiyum taşı değildir; ilacın primer amin grubunun nötr amite dönüşmesiyle asidik idrarda çözünürlüğünü kaybetmesinden doğan doğrudan organik kristal çökmesidir.\",\"ar\":\"مغالطة التشليب المعدني: البلورات ليست حصى كالسيوم؛ بل هي ترسب مباشر للمركب العضوي بعد فقدانه القطبية وتحول الأمين إلى أميد متعادل في بول حمضي.\",\"en\":\"Cation chelation misconception: Crystalluria is not a mineral calcium stone; it is direct organic precipitation caused by converting a basic amine into a neutral, poorly soluble amide.\"}},{\"id\":\"opt-4c\",\"text\":{\"tr\":\"Karaciğer enzimleri sülfonamid kükürdünü sülfona oksitler; bu sülfon türevi tübül epitelindeki proteinlerle kovalent çapraz bağ kurar.\",\"ar\":\"تؤكسد إنزيمات الكبد كبريت السلفوناميد إلى سلفون؛ ويرتبط هذا المشتق تساهمياً مع بروتينات الظهارة النبيبية.\",\"en\":\"Hepatic enzymes oxidize sulfonamide sulfur into an insoluble sulfone that covalently cross-links with tubular epithelial membrane proteins.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kükürt oksidasyonu yanılgısı: Kristalüriye yol açan metabolizma S-oksidasyon değil, para-amino grubunun NAT-2 ile N-asetilasyonudur; oluşan N4-asetilsülfadiazin asidik idrarda polaritesini kaybederek çöker.\",\"ar\":\"مغالطة أكسدة الكبريت: المسؤول عن البلورات هو تفاعل N-أسيتيل عبر NAT-2 للأمين العطري وليس أكسدة الكبريت؛ حيث يفقد المشتق انحلاليته في البول الحمضي.\",\"en\":\"Sulfur oxidation fallacy: Crystalluria is caused by NAT-2 N-acetylation of the aromatic amino group, not S-oxidation; the resulting N4-acetyl derivative loses solubility at acidic urine pH.\"}}]},\"technicalTerms\":[{\"term\":\"kristalüri (crystalluria)\",\"arContext\":\"البيلة البلورية (crystalluria)\"},{\"term\":\"N-asetilasyon polarite istisnası\",\"arContext\":\"استثناء انخفاض القطبية بالأستلة\"}],\"hints\":[{\"tr\":\"Asetilasyon reaksiyonunda moleküle bir asetil grubu (-COCH3) takılır.\",\"ar\":\"في تفاعل الأستلة تُضاف مجموعة أسيتيل كارهة للماء (-COCH3).\",\"en\":\"Acetylation attaches a hydrophobic two-carbon acetyl group (-COCH3).\"},{\"tr\":\"Bazik primer amin (-NH2) nötr bir amite (-NHCOCH3) dönüştüğünde iyonlaşma kabiliyeti kaybolur.\",\"ar\":\"بتحول الأمين الأولي إلى أميد حيادي، تفقد الجزيئة قدرتها على التأين الحمضي.\",\"en\":\"Converting a polar basic amine into a neutral amide destroys its ability to ionize.\"},{\"tr\":\"Polaritesi azalan metabolit asidik idrarda çözünemez ve tübüllerde kristalleşir.\",\"ar\":\"يعجز المستقلب منخفض القطبية عن الذوبان في البول الحمضي فيترسب.\",\"en\":\"The un-ionized, low-polarity metabolite precipitates out of solution in acidic urine.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":2}],\"config\":{\"options\":[{\"id\":\"opt-4a\",\"text\":\"Asetilasyon bazik primer amini nötr amite çevirir; iyonlaşma ve polarite azalır. Oluşan N4-asetil türevi asidik idrarda suda çözünmez ve çöker.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel kimyasal analiz! Slayt 2 ve 31'in en kritik sınav istisnası: Glukuronidasyon ve sülfasyon moleküle asidik iyonize gruplar takarken, N-asetilasyon (NAT-2) lipofilisiteyi artırır veya nötr bırakır. Sülfadiazin molekülündeki p-amino grubu asetillendiğinde çözünürlük dramatik şekilde düşer. Asidik idrarda kristalleşerek böbrek yetmezliği yapar (bu yüzden sülfonamidlerde bol su ve NaHCO3 verilir).\"},{\"id\":\"opt-4b\",\"text\":\"N4-Asetil türevi idrardaki kalsiyum ve magnezyum iyonlarını şelatlayarak çözünmeyen inorganik taş kompleksleri oluşturur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Şelasyon ve taş tipi yanılgısı: Kristalüri bir kalsiyum taşı değildir; ilacın primer amin grubunun nötr amite dönüşmesiyle asidik idrarda çözünürlüğünü kaybetmesinden doğan doğrudan organik kristal çökmesidir.\"},{\"id\":\"opt-4c\",\"text\":\"Karaciğer enzimleri sülfonamid kükürdünü sülfona oksitler; bu sülfon türevi tübül epitelindeki proteinlerle kovalent çapraz bağ kurar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kükürt oksidasyonu yanılgısı: Kristalüriye yol açan metabolizma S-oksidasyon değil, para-amino grubunun NAT-2 ile N-asetilasyonudur; oluşan N4-asetilsülfadiazin asidik idrarda polaritesini kaybederek çöker.\"}],\"revealedOutcome\":{\"tr\":\"Asetilasyon bazik primer amini nötr amite çevirir; iyonlaşma ve polarite azalır. Oluşan N4-asetil türevi asidik idrarda suda çözünmez ve çöker.\",\"ar\":\"تحول الأستلة الأمين الأولي القاعدي إلى أميد حيادي، فتنقص القطبية والتأين؛ مما يجعل المستقلب غير ذؤوب في البول الحمضي فيترسب.\",\"en\":\"Acetylation converts the basic primary amine into a neutral amide, decreasing polarity and ionization; the N4-acetyl metabolite is poorly soluble in acidic urine.\"},\"explanation\":{\"tr\":\"Mükemmel kimyasal analiz! Slayt 2 ve 31'in en kritik sınav istisnası: Glukuronidasyon ve sülfasyon moleküle asidik iyonize gruplar takarken, N-asetilasyon (NAT-2) lipofilisiteyi artırır veya nötr bırakır. Sülfadiazin molekülündeki p-amino grubu asetillendiğinde çözünürlük dramatik şekilde düşer. Asidik idrarda kristalleşerek böbrek yetmezliği yapar (bu yüzden sülfonamidlerde bol su ve NaHCO3 verilir).\",\"ar\":\"تحليل كيميائي استثنائي! الشريحة 2 و 31: بينما يضيف الجلوكورونيد شحنات قطبية، فإن الأستلة (NAT-2) تقلل القطبية والذوبانية المائية. مركب N4-acetylsulfadiazine يترسب كبلورات إبرية في النبيبات الكلوية مسبباً بيلة بلورية وقصوراً كلوياً، لذا يُعطى المريض بيكربونات الصوديوم لجعل البول قلوياً.\",\"en\":\"Masterful chemical deduction! Slides 2 & 31 benchmark: Unlike glucuronidation, N-acetylation (NAT-2) masks the basic amine as a neutral lipophilic acetamide. N4-acetylsulfadiazine possesses drastically lower water solubility at acidic urine pH, forming sharp crystals that lacerate renal tubules unless alkalinized with NaHCO3.\"}}},{\"id\":\"mc-mod5-les2-step-05\",\"stage\":\"interactive_artifact\",\"stageIndex\":5,\"type\":\"metabolism_map\",\"widgetType\":\"MetabolismMap\",\"title\":{\"tr\":\"İnteraktif Metabolizma Haritası: Parasetamol Yolakları\",\"ar\":\"خريطة الاستقلاب التفاعلية: مسارات الباراسيتامول\",\"en\":\"Interactive Metabolism Map: Paracetamol Biotransformation Divergence\"},\"prompt\":{\"tr\":\"Parasetamolün karaciğerdeki 4 temel metabolik yolağını inceleyin. Aşırı dozda ölümcül hepatotoksisiteye yol açan sitokrom P450 biyoaktivasyon bölgesini harita üzerinde belirleyin.\",\"ar\":\"تفحص مسارات الباراسيتامول الأربعة في الكبد. حدد موقع التنشيط الحيوي عبر CYP450 المسؤول عن السمية الكبدية القاتلة عند الجرعة المفرطة.\",\"en\":\"Explore the 4 primary hepatic pathways of paracetamol. Identify the cytochrome P450 bioactivation site responsible for generating the fatal hepatotoxic metabolite.\"},\"predictThenReveal\":false,\"config\":{\"drugName\":\"Paracetamol (Asetaminofen)\",\"prompt\":\"Hepatotoksik kinonimin (NAPQI) oluşturan CYP2E1 biyoaktivasyon bölgesini seçin.\",\"moleculeSvgDescription\":\"Parasetamol p-asetamidofenol iskeleti, fenolik -OH ve asetamid azotu\",\"sites\":[{\"id\":\"site_glucuronidation\",\"label\":\"4-O-Glukuronidasyon\",\"x\":120,\"y\":50,\"enzyme\":\"UGT1A6 / UGT1A9\",\"phase\":\"Phase II\",\"reactionType\":\"O-Glukuroniltransferaz Konjugasyonu\",\"metaboliteOutcome\":\"Majör güvenli yol (%60); yüksek oranda polar, suda çözünen glukuronit böbreklerle atılır.\",\"toxicityFlag\":\"non_toxic\",\"isTargetSite\":false},{\"id\":\"site_sulfation\",\"label\":\"4-O-Sülfasyon\",\"x\":260,\"y\":50,\"enzyme\":\"SULT1A1 (PAPS donörü)\",\"phase\":\"Phase II\",\"reactionType\":\"Sülfotransferaz Konjugasyonu\",\"metaboliteOutcome\":\"Sekonder güvenli yol (%35); yüksek afiniteli ancak düşük kapasiteli sülfat konjugatı idrarla atılır.\",\"toxicityFlag\":\"non_toxic\",\"isTargetSite\":false},{\"id\":\"site_cyp2e1_napqi\",\"label\":\"N-Oksidasyon / CYP2E1 (NAPQI)\",\"x\":190,\"y\":140,\"enzyme\":\"CYP2E1 / CYP1A2\",\"phase\":\"Phase I\",\"reactionType\":\"N-Hidroksilasyon ve Spontan Dehidrasyon\",\"metaboliteOutcome\":\"Son derece reaktif elektrofil N-asetil-p-benzokinonimin (NAPQI) üretir; glutatyon tükenince karaciğer nekrozu yapar.\",\"toxicityFlag\":\"toxic\",\"isTargetSite\":true},{\"id\":\"site_glutathione\",\"label\":\"Glutatyon (GSH) Detoksifikasyonu\",\"x\":330,\"y\":140,\"enzyme\":\"Glutatyon S-Transferaz (GST)\",\"phase\":\"Phase II\",\"reactionType\":\"Glutatyon Konjugasyonu -> Merkaptürik Asit\",\"metaboliteOutcome\":\"NAPQI elektrofilini tiyol (-SH) ile yakalar; merkaptürik asit türevi halinde idrarla zararsız atar.\",\"toxicityFlag\":\"non_toxic\",\"isTargetSite\":false}],\"source\":{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":35},\"explanation\":\"Terapötik dozda parasetamol %95 oranında UGT ve SULT ile temizlenir. %5'lik NAPQI ise glutatyon ile yakalanır. Aşırı dozda GSH tükenir ve serbest NAPQI hepatosit nekrozu başlatır.\"},\"widget\":{\"type\":\"MetabolismMap\",\"config\":{\"drugName\":\"Paracetamol (Asetaminofen)\",\"prompt\":\"Hepatotoksik kinonimin (NAPQI) oluşturan CYP2E1 biyoaktivasyon bölgesini seçin.\",\"moleculeSvgDescription\":\"Parasetamol p-asetamidofenol iskeleti, fenolik -OH ve asetamid azotu\",\"sites\":[{\"id\":\"site_glucuronidation\",\"label\":\"4-O-Glukuronidasyon\",\"x\":120,\"y\":50,\"enzyme\":\"UGT1A6 / UGT1A9\",\"phase\":\"Phase II\",\"reactionType\":\"O-Glukuroniltransferaz Konjugasyonu\",\"metaboliteOutcome\":\"Majör güvenli yol (%60); yüksek oranda polar, suda çözünen glukuronit böbreklerle atılır.\",\"toxicityFlag\":\"non_toxic\",\"isTargetSite\":false},{\"id\":\"site_sulfation\",\"label\":\"4-O-Sülfasyon\",\"x\":260,\"y\":50,\"enzyme\":\"SULT1A1 (PAPS donörü)\",\"phase\":\"Phase II\",\"reactionType\":\"Sülfotransferaz Konjugasyonu\",\"metaboliteOutcome\":\"Sekonder güvenli yol (%35); yüksek afiniteli ancak düşük kapasiteli sülfat konjugatı idrarla atılır.\",\"toxicityFlag\":\"non_toxic\",\"isTargetSite\":false},{\"id\":\"site_cyp2e1_napqi\",\"label\":\"N-Oksidasyon / CYP2E1 (NAPQI)\",\"x\":190,\"y\":140,\"enzyme\":\"CYP2E1 / CYP1A2\",\"phase\":\"Phase I\",\"reactionType\":\"N-Hidroksilasyon ve Spontan Dehidrasyon\",\"metaboliteOutcome\":\"Son derece reaktif elektrofil N-asetil-p-benzokinonimin (NAPQI) üretir; glutatyon tükenince karaciğer nekrozu yapar.\",\"toxicityFlag\":\"toxic\",\"isTargetSite\":true},{\"id\":\"site_glutathione\",\"label\":\"Glutatyon (GSH) Detoksifikasyonu\",\"x\":330,\"y\":140,\"enzyme\":\"Glutatyon S-Transferaz (GST)\",\"phase\":\"Phase II\",\"reactionType\":\"Glutatyon Konjugasyonu -> Merkaptürik Asit\",\"metaboliteOutcome\":\"NAPQI elektrofilini tiyol (-SH) ile yakalar; merkaptürik asit türevi halinde idrarla zararsız atar.\",\"toxicityFlag\":\"non_toxic\",\"isTargetSite\":false}],\"source\":{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":35},\"explanation\":\"Terapötik dozda parasetamol %95 oranında UGT ve SULT ile temizlenir. %5'lik NAPQI ise glutatyon ile yakalanır. Aşırı dozda GSH tükenir ve serbest NAPQI hepatosit nekrozu başlatır.\"}},\"technicalTerms\":[{\"term\":\"biyoaktivasyon toksisitesi\",\"arContext\":\"سمية التنشيط الحيوي\"},{\"term\":\"hepatosit nekrozu\",\"arContext\":\"تنخر الخلايا الكبدية\"}],\"hints\":[{\"tr\":\"Parasetamolün toksik metaboliti bir Faz I oksidasyon ürünüdür.\",\"ar\":\"المستقلب السام للباراسيتامول هو ناتج أكسدة من المرحلة الأولى.\",\"en\":\"The toxic metabolite of acetaminophen is produced by a Phase I oxidation.\"},{\"tr\":\"CYP2E1 enzimi asetamid azotunu N-hidroksiller ve su kaybederek kinonimin (NAPQI) oluşturur.\",\"ar\":\"يهدرل CYP2E1 نيتروجين الأسيتاميد لتتشكل وسائط الكينونيمين (NAPQI).\",\"en\":\"CYP2E1 hydroxylates the amide nitrogen to eliminate water, forging electrophilic NAPQI.\"},{\"tr\":\"Haritada kırmızı toksisite bayrağı taşıyan CYP2E1 bölgesi hedef metabolik alandır.\",\"ar\":\"موقع CYP2E1 الذي يحمل علامة السمية الحمراء هو الهدف المطلوب على الخريطة.\",\"en\":\"The CYP2E1 locus marked with the red toxicity flag is your target site.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":35}]},{\"id\":\"mc-mod5-les2-step-06\",\"stage\":\"guided_discovery\",\"stageIndex\":6,\"type\":\"guided_discovery\",\"title\":{\"tr\":\"Rehberli Keşif: Merkaptürik Asit Montaj Hattı\",\"ar\":\"استكشاف موجه: خط إنتاج حمض الميركابتوريك\",\"en\":\"Guided Discovery: The Mercapturic Acid Assembly Line\"},\"prompt\":{\"tr\":\"Toksik bir elektrofil glutatyon (GSH: Glu-Cys-Gly) ile yakalandığında 3 amino asitlik devasa bir konjugat oluşur. Vücut bu iri molekülü idrarla atmak için adım adım nasıl budar?\",\"ar\":\"عندما يقتنص الجلوتاثيون (GSH: Glu-Cys-Gly) جزيئاً ساماً، يتكون مركب ثلاثي الببتيد ضخم. كيف يقلم الجسم هذه الجزيئة خطوة بخطوة لطرحها بالبول؟\",\"en\":\"When a toxic electrophile is trapped by glutathione (GSH: Glu-Cys-Gly), a bulky tripeptide adduct forms. How does the body systematically trim this conjugate for safe urinary clearance?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-6a\",\"text\":{\"tr\":\"Önce glutamat (gGT) ardından glisin (dipeptidaz) koparılır; kalan sistein konjugatı NAT ile N-asetillenerek merkaptürik asit türevi halinde idrarla atılır.\",\"ar\":\"يُفصل الجلوتامات بـ gGT ثم الجليسين بإنزيم ببتيداز؛ ويُؤستل السيسيتين المتبقي بـ NAT ليُطرح كحمض ميركابتوريك في البول.\",\"en\":\"First glutamate is cleaved by gamma-GT, then glycine by a dipeptidase; the remaining cysteine adduct is N-acetylated by NAT into mercapturic acid for urine excretion.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harikulade biyokimyasal kavrayış! Slayt 36'daki merkaptürik asit yolu: 1. GST enzimi elektrofile GSH ekler. 2. Böbrek ve karaciğerde gama-glutamiltranspeptidaz (gGT) glutamatı koparır. 3. Dipeptidaz enzimi glisini koparır; geriye sistein-ilaç konjugatı kalır. 4. Mikrozomal NAT enzimi sistein aminini asetilleyerek N-asetilsistein (merkaptürik asit) türevine çevirir. Bu asidik ürün idrarla hızla temizlenir.\",\"ar\":\"إدراك بيوكيميائي باهر! مسار حمض الميركابتوريك (الشريحة 36): يربط GST الجلوتاثيون أولاً. يفصل إنزيم gGT الجلوتامات، ثم يقص الببتيداز الجليسين ليبقى مركب السيستئين. وأخيراً يؤستل إنزيم NAT أمين السيستئين لينتج حمض الميركابتوريك الذؤوب والمعد للإطراح البولي السريع.\",\"en\":\"Magnificent biochemical insight! Slide 36 assembly line: GST links GSH to the electrophile. Gamma-GT trims glutamate, and dipeptidase cleaves glycine, leaving a cysteine adduct. Finally, NAT N-acetylates the cysteine to forge mercapturic acid for rapid urinary clearance.\"}},{\"id\":\"opt-6b\",\"text\":{\"tr\":\"Üç amino asitlik intakt GSH konjugatı hiç parçalanmadan glomerüllerden doğrudan süzülür; tübüler peptidazlara ihtiyaç duyulmaz.\",\"ar\":\"يُرشح معقد GSH الثلاثي السليم بالكامل عبر الكبيبات الكلوية مباشرة دون الحاجة لأي إنزيمات ببتيداز نبيبية.\",\"en\":\"The intact tripeptide GSH conjugate is filtered directly across glomeruli into urine without requiring tubular peptidolysis.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Budadan doğrudan atılım yanılgısı: GSH konjugatı 500 Da'dan büyük hantal bir yapıdır; proksimal tübüllerde gama-glutamiltranspeptidaz ve dipeptidaz ile glutamat ve glisin koparılıp amino asitler geri kazanılmadan idrarla atılamaz.\",\"ar\":\"مغالطة الطرح المباشر: معقد GSH جزيء ضخم؛ تقوم إنزيمات gGT والديببتيداز النبيبية بنزع الجلوتامات والجليسين لإعادة تدويرهما قبل تكوين حمض الميركابتوريك.\",\"en\":\"Direct excretion fallacy: GSH conjugates are large tripeptides; proximal tubule gGT and dipeptidases sequentially cleave glutamate and glycine to salvage amino acids prior to mercapturic acid excretion.\"}},{\"id\":\"opt-6c\",\"text\":{\"tr\":\"Hücresel peptidazlar sistein kükürt-karbon (C-S) bağını kopararak ilacı intakt formda serbest bırakır ve ksenobiyotiği geri dönüştürür.\",\"ar\":\"تكسر ببتيدازات الخلية رابطة الكبريت-كربون (C-S) لتحرر الدواء سليماً في العصارة الخلوية وتعيد تدويره.\",\"en\":\"Intracellular peptidases cleave the cysteine-drug C-S bond, regenerating the parent xenobiotic intact for metabolic recycling.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"C-S klivajı yanılgısı: Ksenobiyotik ile sistein arasındaki C-S tiyoeter bağı son derece dayanıklıdır ve hidrolize uğramaz; molekül serbest ilaca dönüştürülmez, N-asetillenerek merkaptürik asit halinde elimine edilir.\",\"ar\":\"مغالطة فك رابطة C-S: رابطة الثيوايثر بين الدواء والسيستين شديدة الاستقرار؛ لا يتحرر الدواء بل تتم أسيتلة السيستين ليطرح كحمض ميركابتوريك.\",\"en\":\"C-S cleavage fallacy: The xenobiotic thioether bond is highly stable and not cleaved by peptidases; the cysteine conjugate is acetylated into mercapturic acid for terminal excretion.\"}}]},\"technicalTerms\":[{\"term\":\"merkaptürik asit yolu\",\"arContext\":\"مسار حمض الميركابتوريك (mercapturic acid pathway)\"},{\"term\":\"gama-glutamiltranspeptidaz (gGT)\",\"arContext\":\"إنزيم غاما-جلوتاميل ترانسببتيداز\"}],\"hints\":[{\"tr\":\"Glutatyon 3 amino asitten (Glutamat-Sistein-Glisin) oluşan bir tripeptittir.\",\"ar\":\"الجلوتاثيون ببتيد ثلاثي مكون من جلوتامات وسيسيتين وجليسين.\",\"en\":\"Glutathione is a tripeptide composed of Glutamate-Cysteine-Glycine.\"},{\"tr\":\"Uçlardaki glutamat ve glisin amino asitleri hidrolazlarla tek tek kesilir.\",\"ar\":\"تُقص الأحماض الأمينية الطرفية (الجلوتامات والجليسين) بالإنزيمات تباعاً.\",\"en\":\"Terminal glutamate and glycine residues are enzymatically clipped off.\"},{\"tr\":\"Kalan sistein konjugatı asetillenerek N-asetilsistein (merkaptürik asit) halinde idrara verilir.\",\"ar\":\"يُؤستل السيستئين المتبقي ليشكل حمض الميركابتوريك الذي يُطرح بالبول.\",\"en\":\"The residual cysteine adduct is N-acetylated into mercapturic acid for renal excretion.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":36}],\"config\":{\"options\":[{\"id\":\"opt-6a\",\"text\":\"Önce glutamat (gGT) ardından glisin (dipeptidaz) koparılır; kalan sistein konjugatı NAT ile N-asetillenerek merkaptürik asit türevi halinde idrarla atılır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harikulade biyokimyasal kavrayış! Slayt 36'daki merkaptürik asit yolu: 1. GST enzimi elektrofile GSH ekler. 2. Böbrek ve karaciğerde gama-glutamiltranspeptidaz (gGT) glutamatı koparır. 3. Dipeptidaz enzimi glisini koparır; geriye sistein-ilaç konjugatı kalır. 4. Mikrozomal NAT enzimi sistein aminini asetilleyerek N-asetilsistein (merkaptürik asit) türevine çevirir. Bu asidik ürün idrarla hızla temizlenir.\"},{\"id\":\"opt-6b\",\"text\":\"Üç amino asitlik intakt GSH konjugatı hiç parçalanmadan glomerüllerden doğrudan süzülür; tübüler peptidazlara ihtiyaç duyulmaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Budadan doğrudan atılım yanılgısı: GSH konjugatı 500 Da'dan büyük hantal bir yapıdır; proksimal tübüllerde gama-glutamiltranspeptidaz ve dipeptidaz ile glutamat ve glisin koparılıp amino asitler geri kazanılmadan idrarla atılamaz.\"},{\"id\":\"opt-6c\",\"text\":\"Hücresel peptidazlar sistein kükürt-karbon (C-S) bağını kopararak ilacı intakt formda serbest bırakır ve ksenobiyotiği geri dönüştürür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"C-S klivajı yanılgısı: Ksenobiyotik ile sistein arasındaki C-S tiyoeter bağı son derece dayanıklıdır ve hidrolize uğramaz; molekül serbest ilaca dönüştürülmez, N-asetillenerek merkaptürik asit halinde elimine edilir.\"}],\"revealedOutcome\":{\"tr\":\"Önce glutamat (gGT) ardından glisin (dipeptidaz) koparılır; kalan sistein konjugatı NAT ile N-asetillenerek merkaptürik asit türevi halinde idrarla atılır.\",\"ar\":\"يُفصل الجلوتامات بـ gGT ثم الجليسين بإنزيم ببتيداز؛ ويُؤستل السيسيتين المتبقي بـ NAT ليُطرح كحمض ميركابتوريك في البول.\",\"en\":\"First glutamate is cleaved by gamma-GT, then glycine by a dipeptidase; the remaining cysteine adduct is N-acetylated by NAT into mercapturic acid for urine excretion.\"},\"explanation\":{\"tr\":\"Harikulade biyokimyasal kavrayış! Slayt 36'daki merkaptürik asit yolu: 1. GST enzimi elektrofile GSH ekler. 2. Böbrek ve karaciğerde gama-glutamiltranspeptidaz (gGT) glutamatı koparır. 3. Dipeptidaz enzimi glisini koparır; geriye sistein-ilaç konjugatı kalır. 4. Mikrozomal NAT enzimi sistein aminini asetilleyerek N-asetilsistein (merkaptürik asit) türevine çevirir. Bu asidik ürün idrarla hızla temizlenir.\",\"ar\":\"إدراك بيوكيميائي باهر! مسار حمض الميركابتوريك (الشريحة 36): يربط GST الجلوتاثيون أولاً. يفصل إنزيم gGT الجلوتامات، ثم يقص الببتيداز الجليسين ليبقى مركب السيستئين. وأخيراً يؤستل إنزيم NAT أمين السيستئين لينتج حمض الميركابتوريك الذؤوب والمعد للإطراح البولي السريع.\",\"en\":\"Magnificent biochemical insight! Slide 36 assembly line: GST links GSH to the electrophile. Gamma-GT trims glutamate, and dipeptidase cleaves glycine, leaving a cysteine adduct. Finally, NAT N-acetylates the cysteine to forge mercapturic acid for rapid urinary clearance.\"}}},{\"id\":\"mc-mod5-les2-step-07\",\"stage\":\"formal_explanation\",\"stageIndex\":7,\"type\":\"formal_explanation\",\"title\":{\"tr\":\"NAT-2 Farmakogenetiği: Hızlı vs Yavaş Asetilatörler\",\"ar\":\"علم الوراثة الدوائي لـ NAT-2: المؤستلون السريعون مقابل البطيئين\",\"en\":\"NAT-2 Pharmacogenetics: Fast vs. Slow Acetylator Phenotypes\"},\"prompt\":{\"tr\":\"Tüberküloz ilacı izoniyazid kullanan hastaların %50-60'ında (yavaş asetilatörler) periferik nöropati riski tavan yaparken, hızlı asetilatörlerde tedavi başarısızlığı görülür. Bu genetik uçurumun nedeni nedir?\",\"ar\":\"ترتفع خطورة الاعتلال العصبي لدى 50-60% من مرضى السل المعالجين بالإيزونيازيد (المؤستلون البطيئون)، بينما يفشل العلاج لدى السريعين. ما سبب هذا التباين الوراثي؟\",\"en\":\"Among tuberculosis patients on isoniazid, 50-60% (slow acetylators) face severe peripheral neuropathy, whereas fast acetylators risk treatment failure. What biochemical mechanism drives this genetic divergence?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-7a\",\"text\":{\"tr\":\"NAT-2 enzim polimorfizmi: Yavaş asetilatörlerde enzim düzeyi düşüktür; serbest izoniyazid kanda birikerek piridoksin (B6) eksikliği ve periferik nöropati yapar.\",\"ar\":\"تباين جيني في NAT-2: يمتلك المؤستلون البطيئون إنزيماً قليل الكفاءة؛ فيتراكم الإيزونيازيد حراً ويستنزف فيتامين B6 مسبباً اعتلالاً عصبياً.\",\"en\":\"NAT-2 polymorphism: Slow acetylators have defective enzyme levels; parent isoniazid accumulates, depleting pyridoxine (B6) and triggering peripheral neuropathy.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz farmakogenetik analiz! Slayt 40 verisi: N-Asetiltransferaz-2 (NAT-2) geni polimorfiktir. Türk ve Avrupa toplumlarının %50-60'ı yavaş asetilatördür. İzoniyazid yavaş inaktive olduğunda kanda yükselir, B6 vitaminini bağlayarak nöropatiye yol açar (veya hidralazinde ilaca bağlı SLE tablosu gelişir). Japonlarda ise %90 hızlı asetilatördür; standart doz hızla yıkılarak yetersiz kalır.\",\"ar\":\"تحليل وراثي دوائي متقن! الشريحة 40: جين NAT-2 متباين وراثياً. 50-60% من مجتمعاتنا مؤستلون بطيئون، فيتراكم الإيزونيازيد ويستنزف فيتامين B6 مسبباً تلفاً عصبياً (أو ذئبة حمامية مع الهيدرالازين). أما لدى 90% من اليابانيين فالتخلص سريع جداً وقد يفشل العلاج.\",\"en\":\"Superb pharmacogenetic analysis! Slide 40: NAT-2 polymorphism splits populations. In slow acetylators (50-60% of Caucasians), parent isoniazid accumulates to deplete pyridoxine (B6), triggering neurotoxicity or hydralazine-induced lupus (SLE). In fast acetylators, rapid clearance risks subtherapeutic failure.\"}},{\"id\":\"opt-7b\",\"text\":{\"tr\":\"Hızlı asetilatörlerde intestinal P-glikoprotein (P-gp) aşırı eksprese edilmiştir; ilaç emilmeden feçesle dışarı atılır.\",\"ar\":\"يفرط التعبير عن مضخات P-glycoprotein في أمعاء المفرزين السريعين، مما يطرح الدواء في البراز دون امتصاصه.\",\"en\":\"Rapid acetylators overexpress intestinal P-glycoprotein (P-gp) efflux pumps, preventing drug absorption by expelling it directly into feces.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Efluks pompası yanılgısı: İzoniyazid emilimi hızlı ve tamdır; plazma konsantrasyonu farkı bağırsak taşınmasından değil, karaciğerdeki sitozolik NAT-2 enziminin genetik delesyon veya mutasyonlarından kaynaklanır.\",\"ar\":\"مغالطة مضخات الطرد: امتصاص الإيزونيازيد تام وسريع؛ الفروق البلازمية تعود لطفرات جينية في إنزيم NAT-2 الكبدي العصاري وليس لـ P-glycoprotein.\",\"en\":\"Efflux transporter fallacy: Isoniazid is rapidly and completely absorbed; phenotypic clearance divergence is strictly driven by allelic variants of hepatic cytosolic NAT-2.\"}},{\"id\":\"opt-7c\",\"text\":{\"tr\":\"Hızlı asetilatörlerde CYP2E1 enzimi aşırı aktiftir; izoniyazid asetillenmek yerine mikrozomal hidroksilasyonla parçalanır.\",\"ar\":\"يمتلك المفرزون السريعون نشاطاً مفرطاً لإنزيم CYP2E1؛ فيتفكك الإيزونيازيد بالأكسدة الميكروزومية بدلاً من الأسيتلة.\",\"en\":\"Rapid acetylators express hyperactive CYP2E1 monooxygenases that rapidly clear isoniazid via Phase I aliphatic hydroxylation rather than acetylation.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"CYP oksidasyonu yanılgısı: İzoniyazidin majör eliminasyon yolu Faz I oksidasyonu değil, Faz II N-asetilasyonudur (NAT-2). CYP aktivitesi fenotipik temizlenme hızını belirlemez.\",\"ar\":\"مغالطة أكسدة CYP: المسار الإقصائي الرئيسي للإيزونيازيد هو الأسيتلة بإنزيم NAT-2 وليس أكسدة CYP؛ نشاط CYP لا يحدد هذا التباين الظاهري.\",\"en\":\"CYP oxidation misconception: Isoniazid primary clearance is governed by NAT-2 acetylation of its hydrazine moiety, not microsomal CYP monooxygenation.\"}}]},\"technicalTerms\":[{\"term\":\"NAT-2 enzim polimorfizmi\",\"arContext\":\"التباين الوراثي لإنزيم NAT-2\"},{\"term\":\"ilaca bağlı lupus sendromu (SLE)\",\"arContext\":\"الذئبة الحمامية المحدثة بالأدوية\"}],\"hints\":[{\"tr\":\"İzoniyazid tüberküloz tedavisinde karaciğer NAT-2 enzimiyle inaktive edilir.\",\"ar\":\"يُعطل دواء الإيزونيازيد كبدياً بواسطة إنزيم NAT-2.\",\"en\":\"Isoniazid is inactivated in the liver by the polymorphic NAT-2 enzyme.\"},{\"tr\":\"Yavaş asetilatörlerde ilaç vücutta daha uzun süre kalır ve kanda birikir.\",\"ar\":\"لدى المؤستلين البطيئين يمكث الدواء طويلاً ويتراكم بتراكيز مرتفعة.\",\"en\":\"In slow acetylators, the parent drug is cleared slowly, accumulating to toxic levels.\"},{\"tr\":\"Biriken izoniyazid B6 vitaminini tüketerek periferik nöropatiye yol açar.\",\"ar\":\"يستنزف الدواء المتراكم فيتامين B6 مؤدياً إلى تلف الأعصاب المحيطية.\",\"en\":\"Accumulated isoniazid binds and depletes vitamin B6, triggering peripheral neuropathy.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":40}],\"config\":{\"options\":[{\"id\":\"opt-7a\",\"text\":\"NAT-2 enzim polimorfizmi: Yavaş asetilatörlerde enzim düzeyi düşüktür; serbest izoniyazid kanda birikerek piridoksin (B6) eksikliği ve periferik nöropati yapar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz farmakogenetik analiz! Slayt 40 verisi: N-Asetiltransferaz-2 (NAT-2) geni polimorfiktir. Türk ve Avrupa toplumlarının %50-60'ı yavaş asetilatördür. İzoniyazid yavaş inaktive olduğunda kanda yükselir, B6 vitaminini bağlayarak nöropatiye yol açar (veya hidralazinde ilaca bağlı SLE tablosu gelişir). Japonlarda ise %90 hızlı asetilatördür; standart doz hızla yıkılarak yetersiz kalır.\"},{\"id\":\"opt-7b\",\"text\":\"Hızlı asetilatörlerde intestinal P-glikoprotein (P-gp) aşırı eksprese edilmiştir; ilaç emilmeden feçesle dışarı atılır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Efluks pompası yanılgısı: İzoniyazid emilimi hızlı ve tamdır; plazma konsantrasyonu farkı bağırsak taşınmasından değil, karaciğerdeki sitozolik NAT-2 enziminin genetik delesyon veya mutasyonlarından kaynaklanır.\"},{\"id\":\"opt-7c\",\"text\":\"Hızlı asetilatörlerde CYP2E1 enzimi aşırı aktiftir; izoniyazid asetillenmek yerine mikrozomal hidroksilasyonla parçalanır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"CYP oksidasyonu yanılgısı: İzoniyazidin majör eliminasyon yolu Faz I oksidasyonu değil, Faz II N-asetilasyonudur (NAT-2). CYP aktivitesi fenotipik temizlenme hızını belirlemez.\"}],\"revealedOutcome\":{\"tr\":\"NAT-2 enzim polimorfizmi: Yavaş asetilatörlerde enzim düzeyi düşüktür; serbest izoniyazid kanda birikerek piridoksin (B6) eksikliği ve periferik nöropati yapar.\",\"ar\":\"تباين جيني في NAT-2: يمتلك المؤستلون البطيئون إنزيماً قليل الكفاءة؛ فيتراكم الإيزونيازيد حراً ويستنزف فيتامين B6 مسبباً اعتلالاً عصبياً.\",\"en\":\"NAT-2 polymorphism: Slow acetylators have defective enzyme levels; parent isoniazid accumulates, depleting pyridoxine (B6) and triggering peripheral neuropathy.\"},\"explanation\":{\"tr\":\"Kusursuz farmakogenetik analiz! Slayt 40 verisi: N-Asetiltransferaz-2 (NAT-2) geni polimorfiktir. Türk ve Avrupa toplumlarının %50-60'ı yavaş asetilatördür. İzoniyazid yavaş inaktive olduğunda kanda yükselir, B6 vitaminini bağlayarak nöropatiye yol açar (veya hidralazinde ilaca bağlı SLE tablosu gelişir). Japonlarda ise %90 hızlı asetilatördür; standart doz hızla yıkılarak yetersiz kalır.\",\"ar\":\"تحليل وراثي دوائي متقن! الشريحة 40: جين NAT-2 متباين وراثياً. 50-60% من مجتمعاتنا مؤستلون بطيئون، فيتراكم الإيزونيازيد ويستنزف فيتامين B6 مسبباً تلفاً عصبياً (أو ذئبة حمامية مع الهيدرالازين). أما لدى 90% من اليابانيين فالتخلص سريع جداً وقد يفشل العلاج.\",\"en\":\"Superb pharmacogenetic analysis! Slide 40: NAT-2 polymorphism splits populations. In slow acetylators (50-60% of Caucasians), parent isoniazid accumulates to deplete pyridoxine (B6), triggering neurotoxicity or hydralazine-induced lupus (SLE). In fast acetylators, rapid clearance risks subtherapeutic failure.\"}}},{\"id\":\"mc-mod5-les2-step-08\",\"stage\":\"concept_check\",\"stageIndex\":8,\"type\":\"concept_check\",\"title\":{\"tr\":\"Hücresel Yerleşim Tuzağı: Mikrozomal vs Sitozolik Enzimler\",\"ar\":\"فخ التموضع الخلوي: الإنزيمات الميكروزومية مقابل السيتوزولية\",\"en\":\"Cellular Localization Trap: Microsomal vs. Cytosolic Transferases\"},\"prompt\":{\"tr\":\"Bir öğrenci sınavda 'Tüm Faz II transferaz enzimleri sitozolde çözünmüş halde bulunur' demiştir. Bu iddiayı çürüten ve endoplazmik retikuluma gömülü olan majör Faz II enzimi hangisidir?\",\"ar\":\"ادعى طالب أن 'جميع إنزيمات المرحلة الثانية تسبح ذائبة في السيتوزول'. ما هو الإنزيم الرئيسي الذي يدحض هذا الادعاء لكونه مدمجاً في الشبكة الإندوبلازمية؟\",\"en\":\"A student claims that 'all Phase II conjugation enzymes are dissolved in the soluble cytosol.' Which vital transferase refutes this claim by being embedded in the endoplasmic reticulum membrane?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-8a\",\"text\":{\"tr\":\"UDP-Glukuroniltransferaz (UGT); endoplazmik retikulum membranına gömülü mikrozomal bir enzimdir (SULT, NAT ve GST ise sitozoliktir).\",\"ar\":\"إنزيم UGT (جلوكورونيل ترانسفيراز)؛ فهو إنزيم ميكروزومي مدمج في غشاء الشبكة الإندوبلازمية (بينما SULT و NAT و GST سيتوزولية).\",\"en\":\"UDP-Glucuronosyltransferase (UGT); it is an integral membrane-bound microsomal enzyme (whereas SULT, NAT, and GST are cytosolic).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika bir sınav tuzağı yakalandı! Slayt 33 ve 38'in kritik ayrımı: Faz II enzimlerinin çoğu (SULT, NAT, GST, COMT) sitozoliktir. Ancak en yüksek kapasiteli Faz II enzimi olan UGT, endoplazmik retikulum membranına gömülüdür (mikrozomal fraksiyonda yer alır). Aktif bölgesi ER lümenine bakar; bu yüzden UDPGA kofaktörü membran taşıyıcılarıyla içeri alınır.\",\"ar\":\"إمساك بارع بفخ امتحاني كلاسيكي! الشريحة 33 و 38: معظم إنزيمات الاقتران سيتوزولية، لكن إنزيم UGT صاحب السعة الكبرى ميكروزومي متغلغل في غشاء الشبكة الإندوبلازمية وموقعه التحفيزي يواجه جوف الشبكة.\",\"en\":\"Classic exam trap mastered! Slides 33 & 38: While most Phase II transferases (SULT, NAT, GST) reside in soluble cytosol, the high-capacity UGT is an integral ER transmembrane protein whose catalytic site faces the luminal compartment.\"}},{\"id\":\"opt-8b\",\"text\":{\"tr\":\"Sülfotransferaz (SULT); mitokondri iç zarında ATP sentaz ile kompleks halde bulunan mikrozomal bir enzimdir.\",\"ar\":\"سلفوترانسفيراز (SULT)؛ إنزيم ميكروزومي مرتبط بإنزيم تصنيع ATP على الغشاء الداخلي للميتوكوندريا.\",\"en\":\"Sulfotransferase (SULT); an integral membrane enzyme localized to the mitochondrial inner membrane alongside ATP synthase.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"SULT yerleşim yanılgısı: SULT enzimleri mitokondriyal veya membranöz değildir; hücre sitozolünde çözünmüş halde bulunurlar. Endoplazmik retikuluma gömülü tek majör Faz II enzimi UGT'dir.\",\"ar\":\"مغالطة توضع SULT: إنزيمات SULT ذائبة في العصارة الخلوية وليست ميتوكوندرية؛ UGT هو الإنزيم الميكروزومي الوحيد المنغرس بالشبكة الإندوبلازمية.\",\"en\":\"SULT localization misconception: SULT enzymes are soluble cytosolic proteins; UGT is the unique major Phase II transferase embedded in the endoplasmic reticulum.\"}},{\"id\":\"opt-8c\",\"text\":{\"tr\":\"Glutatyon S-transferaz (GST); nükleer por kompleksine ve çekirdek zarına kalıcı olarak gömülü bir enzimdir.\",\"ar\":\"جلوتاثيون إس ترانسفيراز (GST)؛ إنزيم منغرس بشكل دائم في الغلاف النووي ومعقد المسام النووية.\",\"en\":\"Glutathione S-transferase (GST); an integral membrane protein embedded within the outer nuclear envelope and pore complexes.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"GST hücresel yerleşim yanılgısı: GST'nin majör detoksifikasyon izoformları sitozolde serbestçe dağılmıştır (küçük bir mikrozomal alt tip hariç); ER lümeninde yerleşik olan ve yüksek kapasiteli Faz II konjugasyonunu yöneten enzim UGT'dir.\",\"ar\":\"مغالطة توضع GST: تتواجد نظائر GST بشكل أساسي حرة في العصارة الخلوية؛ بينما UGT هو الإنزيم الرئيسي المنغرس في تجويف الشبكة الإندوبلازمية.\",\"en\":\"GST compartmentalization fallacy: Canonical GST enzymes are soluble cytosolic transferases; UGT is the hallmark microsomal enzyme anchored in the ER membrane.\"}}]},\"technicalTerms\":[{\"term\":\"mikrozomal UGT enzimi\",\"arContext\":\"إنزيم UGT الميكروزومي\"},{\"term\":\"sitozolik transferazlar\",\"arContext\":\"إنزيمات التحويل السيتوزولية\"}],\"hints\":[{\"tr\":\"Hücre kırıldığında endoplazmik retikulum parçaları mikrozom keseciklerini oluşturur.\",\"ar\":\"عند تفتيت الخلية تشكل أجزاء الشبكة الإندوبلازمية حويصلات الميكروزوم.\",\"en\":\"Centrifugation pellets endoplasmic reticulum fragments into the microsomal fraction.\"},{\"tr\":\"CYP450 gibi endoplazmik retikulum zarına gömülü olan tek Faz II enzimi glukuronidasyonu yapandır.\",\"ar\":\"إنزيم المرحلة الثانية الوحيد المدمج في غشاء الشبكة الإندوبلازمية كـ CYP450 هو المسؤول عن الجلوكورونيد.\",\"en\":\"The only Phase II transferase co-localized with CYP450 in the ER membrane is UGT.\"},{\"tr\":\"Doğru yanıt mikrozomal UDP-Glukuroniltransferaz (UGT) enzimidir.\",\"ar\":\"الجواب الصحيح هو إنزيم UDP-Glucuronosyltransferase (UGT) الميكروزومي.\",\"en\":\"The correct answer is microsomal UDP-Glucuronosyltransferase (UGT).\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":33}],\"config\":{\"options\":[{\"id\":\"opt-8a\",\"text\":\"UDP-Glukuroniltransferaz (UGT); endoplazmik retikulum membranına gömülü mikrozomal bir enzimdir (SULT, NAT ve GST ise sitozoliktir).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika bir sınav tuzağı yakalandı! Slayt 33 ve 38'in kritik ayrımı: Faz II enzimlerinin çoğu (SULT, NAT, GST, COMT) sitozoliktir. Ancak en yüksek kapasiteli Faz II enzimi olan UGT, endoplazmik retikulum membranına gömülüdür (mikrozomal fraksiyonda yer alır). Aktif bölgesi ER lümenine bakar; bu yüzden UDPGA kofaktörü membran taşıyıcılarıyla içeri alınır.\"},{\"id\":\"opt-8b\",\"text\":\"Sülfotransferaz (SULT); mitokondri iç zarında ATP sentaz ile kompleks halde bulunan mikrozomal bir enzimdir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"SULT yerleşim yanılgısı: SULT enzimleri mitokondriyal veya membranöz değildir; hücre sitozolünde çözünmüş halde bulunurlar. Endoplazmik retikuluma gömülü tek majör Faz II enzimi UGT'dir.\"},{\"id\":\"opt-8c\",\"text\":\"Glutatyon S-transferaz (GST); nükleer por kompleksine ve çekirdek zarına kalıcı olarak gömülü bir enzimdir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"GST hücresel yerleşim yanılgısı: GST'nin majör detoksifikasyon izoformları sitozolde serbestçe dağılmıştır (küçük bir mikrozomal alt tip hariç); ER lümeninde yerleşik olan ve yüksek kapasiteli Faz II konjugasyonunu yöneten enzim UGT'dir.\"}],\"revealedOutcome\":{\"tr\":\"UDP-Glukuroniltransferaz (UGT); endoplazmik retikulum membranına gömülü mikrozomal bir enzimdir (SULT, NAT ve GST ise sitozoliktir).\",\"ar\":\"إنزيم UGT (جلوكورونيل ترانسفيراز)؛ فهو إنزيم ميكروزومي مدمج في غشاء الشبكة الإندوبلازمية (بينما SULT و NAT و GST سيتوزولية).\",\"en\":\"UDP-Glucuronosyltransferase (UGT); it is an integral membrane-bound microsomal enzyme (whereas SULT, NAT, and GST are cytosolic).\"},\"explanation\":{\"tr\":\"Harika bir sınav tuzağı yakalandı! Slayt 33 ve 38'in kritik ayrımı: Faz II enzimlerinin çoğu (SULT, NAT, GST, COMT) sitozoliktir. Ancak en yüksek kapasiteli Faz II enzimi olan UGT, endoplazmik retikulum membranına gömülüdür (mikrozomal fraksiyonda yer alır). Aktif bölgesi ER lümenine bakar; bu yüzden UDPGA kofaktörü membran taşıyıcılarıyla içeri alınır.\",\"ar\":\"إمساك بارع بفخ امتحاني كلاسيكي! الشريحة 33 و 38: معظم إنزيمات الاقتران سيتوزولية، لكن إنزيم UGT صاحب السعة الكبرى ميكروزومي متغلغل في غشاء الشبكة الإندوبلازمية وموقعه التحفيزي يواجه جوف الشبكة.\",\"en\":\"Classic exam trap mastered! Slides 33 & 38: While most Phase II transferases (SULT, NAT, GST) reside in soluble cytosol, the high-capacity UGT is an integral ER transmembrane protein whose catalytic site faces the luminal compartment.\"}}},{\"id\":\"mc-mod5-les2-step-09\",\"stage\":\"application\",\"stageIndex\":9,\"type\":\"clinical_vignette\",\"title\":{\"tr\":\"Klinik Vaka: N-Asetilsistein (NAC) ve Kritik Zaman Penceresi\",\"ar\":\"حالة سريرية: ترياق N-أسيتيل سيستئين والنافذة الزمنية الحرجة\",\"en\":\"Clinical Vignette: N-Acetylcysteine (NAC) & The Critical Antidote Window\"},\"prompt\":{\"tr\":\"Parasetamol zehirlenmesinde antidot olan N-Asetilsistein (NAC) ilk 8-10 saat içinde başlandığında karaciğeri %100 kurtarırken, 24 saatten sonra neden yetersiz kalır? Biyokimyasal kurtarma mekanizması nedir?\",\"ar\":\"ينقذ ترياق N-acetylcysteine (NAC) الكبد بنسبة 100% إذا أُعطي في الساعات 8-10 الأولى، لكن كفاءته تتلاشى بعد 24 ساعة. ما هي آلية الإنقاذ البيوكيميائية؟\",\"en\":\"N-Acetylcysteine (NAC) prevents fatal liver damage if initiated within 8-10 hours of paracetamol overdose, yet loses efficacy after 24 hours. What is the biochemical rescue mechanism?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-9a\",\"text\":{\"tr\":\"NAC serbest sistein sağlayarak tükenen glutatyon (GSH) sentezini hızla yeniler; ancak GSH >%70 tükendikten sonra NAPQI proteinlere kovalent bağlanıp geri dönüşsüz nekroz başlatmıştır.\",\"ar\":\"يوفر NAC السيستئين ليعيد بناء الجلوتاثيون (GSH) المنهار؛ ولكن بعد نفاد 70% من GSH، يكون NAPQI قد ارتبط ببروتينات الخلية وبدأ التنخر غير العكوس.\",\"en\":\"NAC supplies rate-limiting cysteine to rapidly replenish depleted glutathione (GSH); once GSH falls below 30%, NAPQI binds irreversibly to vital proteins, triggering irreversible necrosis.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz klinik toksikoloji! Slayt 36 verisi: Glutatyon sentezinde hız kısıtlayıcı amino asit L-sisteindir. NAC hücreye girerek sistein havuzunu doldurur ve GSH sentezini patlatır; ayrıca serbest tiyolüyle bizzat NAPQI'yi nötralize eder. Ancak ilk 8-10 saat aşılırsa NAPQI mitokondriyal proteinlere kovalent kilitlenir; artık GSH verilse dahi ölen hücreler diriltilemez.\",\"ar\":\"تحليل سمومي سريري متكامل! الشريحة 36: السيستئين هو الحمض الأميني المحدد لسرعة بناء الجلوتاثيون. يزود NAC الخلايا بالسيستئين فيتضاعف بناء GSH ويقضي على سم NAPQI. بعد 8-10 ساعات، يكون NAPQI قد ارتبط بالميتوكوندريا وأحدث موتاً خلوياً محتوماً.\",\"en\":\"Flawless clinical toxicology! Slide 36: Cysteine availability is the bottleneck for de novo glutathione synthesis. NAC recharges intracellular cysteine, driving rapid GSH restoration and directly scavenging NAPQI. Beyond the 8-10 hour window, irreversible covalent mitochondrial alkylation has already triggered cell death.\"}},{\"id\":\"opt-9b\",\"text\":{\"tr\":\"NAC doğrudan CYP2E1 enziminin aktif bölgesine bağlanarak enzimi yarışmalı olarak inhibe eder ve parasetamolün oksidasyonunu durdurur.\",\"ar\":\"يرتبط NAC مباشرة بالموقع الفعال لـ CYP2E1 ويثبطه تنافسياً ليوقف أكسدة الباراسيتامول تماماً.\",\"en\":\"NAC binds directly to the CYP2E1 heme catalytic pocket, acting as a competitive inhibitor to arrest paracetamol oxidation.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"CYP inhibisyonu yanılgısı: NAC bir CYP2E1 inhibitörü değildir; kofaktör öncülü (L-sistein donörü) olarak hücre içi glutatyon (GSH) havuzunu yeniler ve tiyol grubuyla serbest NAPQI'yi redükler.\",\"ar\":\"مغالطة تثبيط CYP: لا يثبط NAC إنزيم CYP2E1؛ بل يعمل كمانح للسيستين لتجديد مخزون الجلوتاثيون (GSH) واختزال NAPQI كيميائياً بمجموعة الثيول.\",\"en\":\"CYP inhibition misconception: NAC does not inhibit CYP2E1; it serves as a bioavailable L-cysteine precursor to replenish depleted glutathione (GSH) pools.\"}},{\"id\":\"opt-9c\",\"text\":{\"tr\":\"NAC gastrointestinal kanalda aktif kömür gibi davranarak parasetamol moleküllerini bağlar ve sistemik emilimi engeller.\",\"ar\":\"يعمل NAC في السبيل الهضمي كالفحم النشط مشلباً جزيئات الباراسيتامول لمنع امتصاصها الجهازي.\",\"en\":\"NAC functions as an intestinal chelating resin analogous to activated charcoal, binding paracetamol lumenally to prevent absorption.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"İntestinal şelasyon yanılgısı: NAC bir gastrointestinal bağlayıcı değildir; sistemik olarak emilip hepatosite girerek sistein sağlayan ve tükenen glutatyonu yeniden sentezleten metabolik bir antidottur.\",\"ar\":\"مغالطة الارتباط الهضمي: لا يعمل NAC كراتنج رابط في الأمعاء؛ بل يُمتص جهازياً ليدخل الكبد ويوفر السيستين اللازم لإعادة بناء الجلوتاثيون.\",\"en\":\"Intestinal binding fallacy: NAC is not an adsorbative resin; it is systemically absorbed and converted intracellularly into cysteine to rescue hepatic GSH.\"}}]},\"technicalTerms\":[{\"term\":\"N-asetilsistein (NAC) antidotu\",\"arContext\":\"ترياق N-أسيتيل سيستئين (NAC)\"},{\"term\":\"kovalent mitokondriyal hasar\",\"arContext\":\"الضرر التساهمي للميتوكوندريا\"}],\"hints\":[{\"tr\":\"Hücrede glutatyon (GSH) sentezinin hızını sınırlayan bileşen sistein amino asididir.\",\"ar\":\"العامل المحدد لسرعة تصنيع الجلوتاثيون هو وفرة حمض السيستئين الأميني.\",\"en\":\"Cysteine availability is the rate-limiting bottleneck in cellular glutathione synthesis.\"},{\"tr\":\"N-Asetilsistein (NAC) vücuda bol miktarda sistein sağlayarak GSH fabrikasını çalıştırır.\",\"ar\":\"يزود NAC الكبد بالسيستئين بوفرة ليعيد تشغيل مصنع الجلوتاثيون.\",\"en\":\"NAC delivers bioavailable cysteine to rapidly reboot glutathione synthesis.\"},{\"tr\":\"İlk 8-10 saat içinde verilirse NAPQI proteinlere bağlanamadan GSH tarafından temizlenir.\",\"ar\":\"إذا أُعطي خلال 8-10 ساعات، يقضي الجلوتاثيون على NAPQI قبل أن يربط بروتينات الكبد.\",\"en\":\"Given within 8-10 hours, replenished GSH captures NAPQI before it irreversibly alkylates proteins.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":36}],\"config\":{\"options\":[{\"id\":\"opt-9a\",\"text\":\"NAC serbest sistein sağlayarak tükenen glutatyon (GSH) sentezini hızla yeniler; ancak GSH >%70 tükendikten sonra NAPQI proteinlere kovalent bağlanıp geri dönüşsüz nekroz başlatmıştır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz klinik toksikoloji! Slayt 36 verisi: Glutatyon sentezinde hız kısıtlayıcı amino asit L-sisteindir. NAC hücreye girerek sistein havuzunu doldurur ve GSH sentezini patlatır; ayrıca serbest tiyolüyle bizzat NAPQI'yi nötralize eder. Ancak ilk 8-10 saat aşılırsa NAPQI mitokondriyal proteinlere kovalent kilitlenir; artık GSH verilse dahi ölen hücreler diriltilemez.\"},{\"id\":\"opt-9b\",\"text\":\"NAC doğrudan CYP2E1 enziminin aktif bölgesine bağlanarak enzimi yarışmalı olarak inhibe eder ve parasetamolün oksidasyonunu durdurur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"CYP inhibisyonu yanılgısı: NAC bir CYP2E1 inhibitörü değildir; kofaktör öncülü (L-sistein donörü) olarak hücre içi glutatyon (GSH) havuzunu yeniler ve tiyol grubuyla serbest NAPQI'yi redükler.\"},{\"id\":\"opt-9c\",\"text\":\"NAC gastrointestinal kanalda aktif kömür gibi davranarak parasetamol moleküllerini bağlar ve sistemik emilimi engeller.\",\"isCorrect\":false,\"misconceptionFeedback\":\"İntestinal şelasyon yanılgısı: NAC bir gastrointestinal bağlayıcı değildir; sistemik olarak emilip hepatosite girerek sistein sağlayan ve tükenen glutatyonu yeniden sentezleten metabolik bir antidottur.\"}],\"revealedOutcome\":{\"tr\":\"NAC serbest sistein sağlayarak tükenen glutatyon (GSH) sentezini hızla yeniler; ancak GSH >%70 tükendikten sonra NAPQI proteinlere kovalent bağlanıp geri dönüşsüz nekroz başlatmıştır.\",\"ar\":\"يوفر NAC السيستئين ليعيد بناء الجلوتاثيون (GSH) المنهار؛ ولكن بعد نفاد 70% من GSH، يكون NAPQI قد ارتبط ببروتينات الخلية وبدأ التنخر غير العكوس.\",\"en\":\"NAC supplies rate-limiting cysteine to rapidly replenish depleted glutathione (GSH); once GSH falls below 30%, NAPQI binds irreversibly to vital proteins, triggering irreversible necrosis.\"},\"explanation\":{\"tr\":\"Kusursuz klinik toksikoloji! Slayt 36 verisi: Glutatyon sentezinde hız kısıtlayıcı amino asit L-sisteindir. NAC hücreye girerek sistein havuzunu doldurur ve GSH sentezini patlatır; ayrıca serbest tiyolüyle bizzat NAPQI'yi nötralize eder. Ancak ilk 8-10 saat aşılırsa NAPQI mitokondriyal proteinlere kovalent kilitlenir; artık GSH verilse dahi ölen hücreler diriltilemez.\",\"ar\":\"تحليل سمومي سريري متكامل! الشريحة 36: السيستئين هو الحمض الأميني المحدد لسرعة بناء الجلوتاثيون. يزود NAC الخلايا بالسيستئين فيتضاعف بناء GSH ويقضي على سم NAPQI. بعد 8-10 ساعات، يكون NAPQI قد ارتبط بالميتوكوندريا وأحدث موتاً خلوياً محتوماً.\",\"en\":\"Flawless clinical toxicology! Slide 36: Cysteine availability is the bottleneck for de novo glutathione synthesis. NAC recharges intracellular cysteine, driving rapid GSH restoration and directly scavenging NAPQI. Beyond the 8-10 hour window, irreversible covalent mitochondrial alkylation has already triggered cell death.\"}}},{\"id\":\"mc-mod5-les2-step-10\",\"stage\":\"retrieval\",\"stageIndex\":10,\"type\":\"retrieval\",\"title\":{\"tr\":\"Aralıklı Hatırlama: Faz II Kofaktör Donörleri Eşleşmesi\",\"ar\":\"استرجاع تباعدي: مطابقة كواشف الاقتران في المرحلة الثانية\",\"en\":\"Spaced Retrieval: Matching Phase II Cofactor Donors\"},\"prompt\":{\"tr\":\"Faz II transferaz enzimlerinin substratlarına polar grup takabilmesi için aktif donör kofaktörlere ihtiyacı vardır. UGT, SULT ve NAT enzimlerinin aktif kofaktörleri sırasıyla hangileridir?\",\"ar\":\"تحتاج إنزيمات المرحلة الثانية إلى كواشف مانحة لتفعيل تفاعلات الاقتران. ما هي الكواشف النشطة لإنزيمات UGT و SULT و NAT على التوالي؟\",\"en\":\"Phase II transferases require high-energy donor cofactors to transfer functional groups. What are the active cofactor donors for UGT, SULT, and NAT, respectively?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-10a\",\"text\":{\"tr\":\"UGT: UDPGA (Üridin difosfat glukuronik asit); SULT: PAPS (Fosfoadenozin-fosfosülfat); NAT: Asetil-KoA.\",\"ar\":\"UGT: كاشف UDPGA؛ SULT: كاشف PAPS؛ NAT: كاشف أسيتيل-كوانزيم A (Acetyl-CoA).\",\"en\":\"UGT: UDPGA (Uridine diphosphate glucuronic acid); SULT: PAPS (Phosphoadenosine-phosphosulfate); NAT: Acetyl-CoA.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz hafıza! Slayt 38 karşılaştırma tablosu: 1. UGT enzimi UDPGA kofaktöründen glukuronik asit aktarır. 2. SULT enzimi PAPS kofaktöründen sülfat aktarır. 3. NAT enzimi Asetil-KoA'dan asetil grubu aktarır. Bu kofaktör üçlüsü farmasötik kimyanın altın standart bilgisidir.\",\"ar\":\"ذاكرة صيدلانية خارقة! جدول الشريحة 38: ينقل UGT الجلوكورونيد من UDPGA، وينقل SULT الكبريتات من PAPS، وينقل NAT الأسيتيل من Acetyl-CoA. هذه الثلاثية من أهم ركائز الكيمياء الصيدلانية.\",\"en\":\"Flawless retrieval! Slide 38 comparative master table: UGT transfers glucuronic acid from UDPGA; SULT transfers sulfate from PAPS; NAT transfers acetyl from Acetyl-CoA. This cofactor triad is the bedrock of drug conjugation.\"}},{\"id\":\"opt-10b\",\"text\":{\"tr\":\"UGT: NADPH; SULT: ATP; NAT: Koenzim Q10 (Ubikinon).\",\"ar\":\"UGT: NADPH؛ SULT: ATP؛ NAT: مرافق الإنزيم Q10.\",\"en\":\"UGT: NADPH; SULT: ATP; NAT: Coenzyme Q10 (Ubiquinone).\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Redoks ve biyoenerji kofaktörü yanılgısı: NADPH Faz I CYP enzimlerinin elektron donörüdür; ATP genel enerji molekülüdür. Faz II transferazları nükleotit bağlı aktif transfer kofaktörleri (UDPGA, PAPS, Asetil-KoA) kullanır.\",\"ar\":\"مغالطة مرافقات الأكسدة والإرجاع: NADPH مانح إلكترونات لـ CYP في المرحلة الأولى وATP طاقة عامة؛ إنزيمات المرحلة الثانية تتطلب مرافقات نقل مخصصة (UDPGA, PAPS, Asetil-KoA).\",\"en\":\"Redox cofactor confusion: NADPH supplies electrons for Phase I CYPs; Phase II transferases require specialized activated nucleotide donors (UDPGA, PAPS, Acetyl-CoA).\"}},{\"id\":\"opt-10c\",\"text\":{\"tr\":\"UGT: Glutatyon (GSH); SULT: S-Adenozilmetiyonin (SAM); NAT: Glisin.\",\"ar\":\"UGT: جلوتاثيون (GSH)؛ SULT: إس-أدينوزيل ميثيونين (SAM)؛ NAT: جليسين.\",\"en\":\"UGT: Glutathione (GSH); SULT: S-Adenosylmethionine (SAM); NAT: Glycine.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Transferaz kofaktör eşleşme yanılgısı: Glutatyon GST'nin, SAM metiltransferazların (COMT), glisin ise açiltransferazın kofaktörüdür; UGT UDPGA, SULT PAPS, NAT ise Asetil-KoA gerektirir.\",\"ar\":\"مغالطة خلط مرافقات النقل: الجلوتاثيون يخص GST، وSAM يخص COMT، والجليسين يخص ناقلات الأسيل؛ بينما تتطلب UGT/SULT/NAT كلاً من UDPGA وPAPS وأسيتيل-CoA.\",\"en\":\"Transferase mismatched donor error: GSH belongs to GST, SAM belongs to methyltransferases (COMT), and glycine belongs to amino acid transferases, not UGT/SULT/NAT.\"}}]},\"technicalTerms\":[{\"term\":\"UDPGA kofaktörü\",\"arContext\":\"كاشف UDPGA المنشط\"},{\"term\":\"PAPS aktif sülfat donörü\",\"arContext\":\"كاشف PAPS المانح للكبريتات\"}],\"hints\":[{\"tr\":\"Glukuronik asit aktarımı için nükleozit difosfat şeker türevi gerekir (UDP-glukuronik asit).\",\"ar\":\"يتطلب نقل الجلوكورونيد سكر نكليوتيدي ثنائي الفوسفات (UDP-glucuronic acid).\",\"en\":\"Glucuronidation utilizes an activated uridine nucleotide sugar derivative.\"},{\"tr\":\"Sülfasyon adenozin nükleotidinde sülfat taşıyan PAPS molekülünden beslenir.\",\"ar\":\"تتغذى الكبرتة من مركب PAPS المحتوي على نكليوتيد الأدينوزين الحامل للكبريتات.\",\"en\":\"Sulfation transfers sulfate from the 3'-phosphoadenosine-5'-phosphosulfate cofactor.\"},{\"tr\":\"Asetilasyon hücresel enerji metabolizmasının ana taşıyıcısı Asetil-KoA ile yürür.\",\"ar\":\"تعتمد الأستلة على الناقل الخلوي الشهير أسيتيل-كوانزيم A (Acetyl-CoA).\",\"en\":\"Acetylation relies on the central cellular carrier Acetyl-CoA.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":38}],\"config\":{\"options\":[{\"id\":\"opt-10a\",\"text\":\"UGT: UDPGA (Üridin difosfat glukuronik asit); SULT: PAPS (Fosfoadenozin-fosfosülfat); NAT: Asetil-KoA.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz hafıza! Slayt 38 karşılaştırma tablosu: 1. UGT enzimi UDPGA kofaktöründen glukuronik asit aktarır. 2. SULT enzimi PAPS kofaktöründen sülfat aktarır. 3. NAT enzimi Asetil-KoA'dan asetil grubu aktarır. Bu kofaktör üçlüsü farmasötik kimyanın altın standart bilgisidir.\"},{\"id\":\"opt-10b\",\"text\":\"UGT: NADPH; SULT: ATP; NAT: Koenzim Q10 (Ubikinon).\",\"isCorrect\":false,\"misconceptionFeedback\":\"Redoks ve biyoenerji kofaktörü yanılgısı: NADPH Faz I CYP enzimlerinin elektron donörüdür; ATP genel enerji molekülüdür. Faz II transferazları nükleotit bağlı aktif transfer kofaktörleri (UDPGA, PAPS, Asetil-KoA) kullanır.\"},{\"id\":\"opt-10c\",\"text\":\"UGT: Glutatyon (GSH); SULT: S-Adenozilmetiyonin (SAM); NAT: Glisin.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Transferaz kofaktör eşleşme yanılgısı: Glutatyon GST'nin, SAM metiltransferazların (COMT), glisin ise açiltransferazın kofaktörüdür; UGT UDPGA, SULT PAPS, NAT ise Asetil-KoA gerektirir.\"}],\"revealedOutcome\":{\"tr\":\"UGT: UDPGA (Üridin difosfat glukuronik asit); SULT: PAPS (Fosfoadenozin-fosfosülfat); NAT: Asetil-KoA.\",\"ar\":\"UGT: كاشف UDPGA؛ SULT: كاشف PAPS؛ NAT: كاشف أسيتيل-كوانزيم A (Acetyl-CoA).\",\"en\":\"UGT: UDPGA (Uridine diphosphate glucuronic acid); SULT: PAPS (Phosphoadenosine-phosphosulfate); NAT: Acetyl-CoA.\"},\"explanation\":{\"tr\":\"Kusursuz hafıza! Slayt 38 karşılaştırma tablosu: 1. UGT enzimi UDPGA kofaktöründen glukuronik asit aktarır. 2. SULT enzimi PAPS kofaktöründen sülfat aktarır. 3. NAT enzimi Asetil-KoA'dan asetil grubu aktarır. Bu kofaktör üçlüsü farmasötik kimyanın altın standart bilgisidir.\",\"ar\":\"ذاكرة صيدلانية خارقة! جدول الشريحة 38: ينقل UGT الجلوكورونيد من UDPGA، وينقل SULT الكبريتات من PAPS، وينقل NAT الأسيتيل من Acetyl-CoA. هذه الثلاثية من أهم ركائز الكيمياء الصيدلانية.\",\"en\":\"Flawless retrieval! Slide 38 comparative master table: UGT transfers glucuronic acid from UDPGA; SULT transfers sulfate from PAPS; NAT transfers acetyl from Acetyl-CoA. This cofactor triad is the bedrock of drug conjugation.\"}}},{\"id\":\"mc-mod5-les2-step-11\",\"stage\":\"connection\",\"stageIndex\":11,\"type\":\"connection\",\"title\":{\"tr\":\"Geniş Bağlantı: İdrarda Biyoaktive Olan Ön İlaç (Metenamin)\",\"ar\":\"آفاق متقدمة: طليعة دوائية تتنشط ذاتياً في البول (الميثينامين)\",\"en\":\"Broader Connection: Spontaneous Urinary Activation of Methenamine\"},\"prompt\":{\"tr\":\"Metenamin kanda ve pH 7.4'te tamamen inaktif bir kafes molekülüdür. Ancak idrar pH'ı 5.5'in altına düştüğünde hiçbir enzim olmadan neye parçalanır ve bakterileri nasıl yok eder?\",\"ar\":\"الميثينامين جزيء قفصي خامل تماماً في الدم عند pH 7.4. عندما يهبط باهاء البول تحت 5.5، إلى ماذا يتفكك ذاتياً دون إنزيمات ليبيد البكتيريا؟\",\"en\":\"Methenamine is an inert cage molecule circulating unchanged in blood at pH 7.4. When urine pH drops below 5.5, what does it non-enzymatically release to eliminate urinary pathogens?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-11a\",\"text\":{\"tr\":\"Asidik idrarda kendiliğinden hidroliz olarak 6 molekül formaldehit açığa çıkarır; formaldehit bakteriyel proteinleri denatüre eder ve direnç gelişemez.\",\"ar\":\"يتحلل تلقائياً في البول الحمضي محرراً 6 جزيئات فورمالدهيد؛ الذي يخثر بروتينات البكتيريا دون أي قدرة منها على تطوير مقاومة.\",\"en\":\"It undergoes spontaneous acid-catalyzed hydrolysis to release 6 molecules of formaldehyde, which denatures bacterial proteins with zero risk of resistance.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika bir ön-ilaç / metabonat örneği! Slayt 5 ve 44: Hekzametilentetramin (Metenamin) kanda kararlıdır ve toksik değildir. Böbreklerden süzüldükten sonra idrar asidikse (pH < 5.5), H+ iyonları kafes yapısını parçalar: 1 molekül metenaminden 6 formaldehit ve 4 amonyum oluşur. Formaldehit genel bir hücre zehiridir; bakteriler formaldehite karşı asla direnç geliştiremez (bu yüzden idrarı asitleştirmek için vitamin C veya metiyoninle kombine edilir).\",\"ar\":\"مثال دوائي عبقري على المستقلبات التلقائية (Metabonates)! الشريحة 5 و 44: الميثينامين آمن بالدم. عند وصوله للبول الحمضي (pH < 5.5)، تفصم البروتونات الهيكل القفصي محررة 6 جزيئات فورمالدهيد و4 أمونيوم. يقتل الفورمالدهيد البكتيريا بتخثير بروتيناتها وتستحيل مقاومته جينياً.\",\"en\":\"Brilliant prodrug / metabonate design! Slides 5 & 44: Hexamethylenetetramine (Methenamine) is non-toxic in systemic blood. At acidic urine pH (<5.5), ambient hydronium ions trigger non-enzymatic decomposition into 6 formaldehyde molecules and 4 ammonium ions. Formaldehyde cross-links bacterial proteins; bacteria cannot mutate resistance against formaldehyde.\"}},{\"id\":\"opt-11b\",\"text\":{\"tr\":\"Bakteriyel enzimler metenamin kafesini tanıyıp parçalayarak amonyak gazı üretir ve bakterileri aşırı alkali şokla yok eder.\",\"ar\":\"تتعرف الإنزيمات البكتيرية على قفص الميثينامين وتفككه مولدة غاز الأمونيا الذي يقضي على البكتيريا بصدمة قلوية.\",\"en\":\"Bacterial enzymes recognize and cleave the methenamine cage into ammonia gas, killing microorganisms via hyperalkaline osmotic shock.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Bakteriyel enzim parçalanması yanılgısı: Metenaminin aktivasyonu enzimatik değildir; asidik idrar ortamında (pH < 5.5) spontan kimyasal hidrolizle açığa çıkan formaldehit bakterileri denatüre eder.\",\"ar\":\"مغالطة التفكك بالإنزيمات البكتيرية: تنشيط الميثينامين غير إنزيمي إطلاقاً؛ بل يحدث بحلمهة كيميائية تلقائية في بول حمضي (pH < 5.5) محرراً الفورمالدهايد القاتل.\",\"en\":\"Bacterial enzymatic cleavage fallacy: Methenamine activation is strictly non-enzymatic; spontaneous chemical hydrolysis in acidic urine (pH < 5.5) generates bactericidal formaldehyde.\"}},{\"id\":\"opt-11c\",\"text\":{\"tr\":\"Alkali idrarda (pH > 8.0) metenamin hızla iyonize olur ve bakterilerin folik asit sentez pompalarını yarışmalı olarak kilitler.\",\"ar\":\"يتأين الميثينامين في البول القلوي (pH > 8.0) ويثبط مضخات تصنيع حمض الفوليك البكتيرية تنافسياً.\",\"en\":\"In alkaline urine (pH > 8.0), methenamine ionizes rapidly to competitively block bacterial folate synthesis uptake transporters.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Alkali ortam ve folat yanılgısı: Metenamin alkali idrarda tamamen kararlıdır ve formaldehit açığa çıkaramaz; aktivasyon için mutlaka asidik pH (< 5.5) şarttır ve etki mekanizması folat inhibisyonu değil formaldehit protein denatürasyonudur.\",\"ar\":\"مغالطة الوسط القلوي: الميثينامين خامل في البول القلوي؛ يتطلب تنشيطه وسطاً حمضياً (pH < 5.5) وآليته هي تمسخ البروتين بالفورمالدهايد لا تثبيط الفولات.\",\"en\":\"Alkaline activation misconception: Methenamine is chemically stable in alkaline urine and cannot release formaldehyde; it strictly requires an acidic pH (< 5.5).\"}}]},\"technicalTerms\":[{\"term\":\"metabonat (non-enzimatik dönüşüm)\",\"arContext\":\"المستقلب التلقائي اللاتحفيزي (metabonate)\"},{\"term\":\"üriner antiseptik biyoaktivasyonu\",\"arContext\":\"تنشيط المطهرات البولية\"}],\"hints\":[{\"tr\":\"Metenamin yapısında 4 azot atomu ve 6 adet metilen (-CH2-) köprüsü taşır.\",\"ar\":\"يتكون الميثينامين من 4 ذرات نيتروجين و 6 جسور ميثيلين (-CH2-).\",\"en\":\"Methenamine consists of 4 nitrogen atoms cross-linked by 6 methylene (-CH2-) bridges.\"},{\"tr\":\"Asidik ortamda (pH < 5.5) su ve protonlar metilen köprülerini aldehide çevirir.\",\"ar\":\"في الوسط الحمضي (pH < 5.5) تفكك البروتونات والماء جسور الميثيلين إلى ألدهيد.\",\"en\":\"Under acidic conditions (pH < 5.5), hydronium ions hydrolyze methylene bridges into aldehydes.\"},{\"tr\":\"Açığa çıkan formaldehit bakterilerin proteinlerini denatüre eden güçlü bir antiseptiktir.\",\"ar\":\"الفورمالدهيد الناتج مطهر فعال يخثر بروتينات البكتيريا دون حدوث مقاومة.\",\"en\":\"The liberated formaldehyde acts as a powerful non-specific antiseptic against urinary pathogens.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":44}],\"config\":{\"options\":[{\"id\":\"opt-11a\",\"text\":\"Asidik idrarda kendiliğinden hidroliz olarak 6 molekül formaldehit açığa çıkarır; formaldehit bakteriyel proteinleri denatüre eder ve direnç gelişemez.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika bir ön-ilaç / metabonat örneği! Slayt 5 ve 44: Hekzametilentetramin (Metenamin) kanda kararlıdır ve toksik değildir. Böbreklerden süzüldükten sonra idrar asidikse (pH < 5.5), H+ iyonları kafes yapısını parçalar: 1 molekül metenaminden 6 formaldehit ve 4 amonyum oluşur. Formaldehit genel bir hücre zehiridir; bakteriler formaldehite karşı asla direnç geliştiremez (bu yüzden idrarı asitleştirmek için vitamin C veya metiyoninle kombine edilir).\"},{\"id\":\"opt-11b\",\"text\":\"Bakteriyel enzimler metenamin kafesini tanıyıp parçalayarak amonyak gazı üretir ve bakterileri aşırı alkali şokla yok eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Bakteriyel enzim parçalanması yanılgısı: Metenaminin aktivasyonu enzimatik değildir; asidik idrar ortamında (pH < 5.5) spontan kimyasal hidrolizle açığa çıkan formaldehit bakterileri denatüre eder.\"},{\"id\":\"opt-11c\",\"text\":\"Alkali idrarda (pH > 8.0) metenamin hızla iyonize olur ve bakterilerin folik asit sentez pompalarını yarışmalı olarak kilitler.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Alkali ortam ve folat yanılgısı: Metenamin alkali idrarda tamamen kararlıdır ve formaldehit açığa çıkaramaz; aktivasyon için mutlaka asidik pH (< 5.5) şarttır ve etki mekanizması folat inhibisyonu değil formaldehit protein denatürasyonudur.\"}],\"revealedOutcome\":{\"tr\":\"Asidik idrarda kendiliğinden hidroliz olarak 6 molekül formaldehit açığa çıkarır; formaldehit bakteriyel proteinleri denatüre eder ve direnç gelişemez.\",\"ar\":\"يتحلل تلقائياً في البول الحمضي محرراً 6 جزيئات فورمالدهيد؛ الذي يخثر بروتينات البكتيريا دون أي قدرة منها على تطوير مقاومة.\",\"en\":\"It undergoes spontaneous acid-catalyzed hydrolysis to release 6 molecules of formaldehyde, which denatures bacterial proteins with zero risk of resistance.\"},\"explanation\":{\"tr\":\"Harika bir ön-ilaç / metabonat örneği! Slayt 5 ve 44: Hekzametilentetramin (Metenamin) kanda kararlıdır ve toksik değildir. Böbreklerden süzüldükten sonra idrar asidikse (pH < 5.5), H+ iyonları kafes yapısını parçalar: 1 molekül metenaminden 6 formaldehit ve 4 amonyum oluşur. Formaldehit genel bir hücre zehiridir; bakteriler formaldehite karşı asla direnç geliştiremez (bu yüzden idrarı asitleştirmek için vitamin C veya metiyoninle kombine edilir).\",\"ar\":\"مثال دوائي عبقري على المستقلبات التلقائية (Metabonates)! الشريحة 5 و 44: الميثينامين آمن بالدم. عند وصوله للبول الحمضي (pH < 5.5)، تفصم البروتونات الهيكل القفصي محررة 6 جزيئات فورمالدهيد و4 أمونيوم. يقتل الفورمالدهيد البكتيريا بتخثير بروتيناتها وتستحيل مقاومته جينياً.\",\"en\":\"Brilliant prodrug / metabonate design! Slides 5 & 44: Hexamethylenetetramine (Methenamine) is non-toxic in systemic blood. At acidic urine pH (<5.5), ambient hydronium ions trigger non-enzymatic decomposition into 6 formaldehyde molecules and 4 ammonium ions. Formaldehyde cross-links bacterial proteins; bacteria cannot mutate resistance against formaldehyde.\"}}},{\"id\":\"mc-mod5-les2-step-12\",\"stage\":\"mastery_check\",\"stageIndex\":12,\"type\":\"mastery_check\",\"title\":{\"tr\":\"Ustalık Sınavı: Parasetamol Toksisitesinin Stoikiometrik Dengesi\",\"ar\":\"اختبار التمكن: الميزان الحسابي لسمية الباراسيتامول\",\"en\":\"Mastery Check: Stoichiometric Balance of Paracetamol Hepatotoxicity\"},\"prompt\":{\"tr\":\"Bir hasta 10 g (66 mmol) parasetamol yutar. SULT 10 mmol'de, UGT 40 mmol'de doyar. Kalan 16 mmol CYP2E1 ile 16 mmol NAPQI üretir. Karaciğer GSH rezervi 10 mmol olduğuna göre klinik sonuç ne olur?\",\"ar\":\"تناول مريض 10 غرامات (66 مليمول) باراسيتامول. تشبع SULT عند 10، و UGT عند 40. حول CYP2E1 الباقي (16 مليمول) إلى NAPQI. إذا كان مخزون الكبد من GSH هو 10 مليمول، فما النتيجة؟\",\"en\":\"A patient takes 10 g (66 mmol) of paracetamol. SULT saturates at 10 mmol, UGT at 40 mmol. The excess 16 mmol forms 16 mmol NAPQI via CYP2E1. If hepatic GSH pool is 10 mmol, what is the clinical outcome?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-12a\",\"text\":{\"tr\":\"Glutatyon %100 tükenir; arta kalan 6 mmol serbest NAPQI hepatosit proteinlerine kovalent bağlanarak fulminan karaciğer nekrozunu tetikler.\",\"ar\":\"يستنفد الجلوتاثيون بنسبة 100%؛ ويرتبط الفائض (6 مليمول) من NAPQI ببروتينات الكبد تساهمياً مسبباً تنخراً كبدياً صاعقاً ومميتاً.\",\"en\":\"Glutathione is 100% exhausted; the remaining 6 mmol of free NAPQI binds covalently to hepatocyte vital proteins, triggering fulminant hepatic necrosis.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz stoikiometrik ustalık! Hesaplama: 66 mmol parasetamolün 50 mmol'ü güvenli Faz II yollarıyla (10 mmol SULT + 40 mmol UGT) bağlanır. Doyum fazlası 16 mmol parasetamol CYP2E1 ile 16 mmol elektrofilik NAPQI üretir. Karaciğerdeki mevcut 10 mmol GSH bu toksinin 10 mmol'ünü nötralize eder ve GSH tamamen sıfırlanır (%100 tükenme). Kalan 6 mmol reaktif NAPQI, hücredeki mitokondriyal proteinlere kovalent bağlanarak saatler içinde masif hepatosit ölümüne yol açar. Acil NAC verilmezse tablo ölümcüldür.\",\"ar\":\"تمكن كيميائي وحسابي باهر! الحساب: 50 مليمول تُعالج بـ UGT و SULT. الفائض (16 مليمول) يتحول إلى 16 مليمول من سم NAPQI. يستهلك هذا السم كامل رصيد الجلوتاثيون البالغ 10 مليمول (استنزاف 100%). الفائض المتبقي (6 مليمول) يهاجم بروتينات الميتوكوندريا تساهمياً ويحدث تنخراً كبدياً شاملاً يستوجب إعطاء NAC فوراً.\",\"en\":\"Flawless stoichiometric mastery! Clear balance: 50 mmol is cleared safely via UGT (40 mmol) and SULT (10 mmol). The 16 mmol overflow is shunted to CYP2E1, generating 16 mmol of NAPQI. This instantly exhausts the entire 10 mmol hepatic GSH reserve (100% depletion). The leftover 6 mmol of unquenched NAPQI irreversibly alkylates essential hepatocyte proteins, initiating fulminant hepatic failure.\"}},{\"id\":\"opt-12b\",\"text\":{\"tr\":\"16 mmol NAPQI hepatosit proteinlerine geri dönüşümlü bağlanır; CYP2E1 doyunca metabolit kendiliğinden kandan temizlenir ve nekroz önlenir.\",\"ar\":\"يرتبط 16 ميليمول NAPQI ببروتينات الكبد عكوساً؛ وعند تشبع CYP2E1 يُطرح المستقلب تلقائياً من الدم دون حدوث نخر.\",\"en\":\"The 16 mmol NAPQI binds hepatocyte proteins reversibly; once CYP2E1 saturates, excess metabolite clears spontaneously without causing necrosis.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Geri dönüşümlü bağlanma yanılgısı: NAPQI elektrofilik bir kinonimindir; proteinlerin nükleofilik sistein tiyollerine kovalent (geri dönüşsüz) bağlanarak mitokondriyi çökertir ve masif nekroz başlatır.\",\"ar\":\"مغالطة الارتباط العكوس: NAPQI مركب كينون إلكتروفيلي يرتبط تساهمياً (بشكل غير عكوس) مع مجموعات الثيول في بروتينات الكبد، مما يسبب تنخراً خلوياً شاملاً.\",\"en\":\"Reversible binding misconception: NAPQI is an electrophilic benzoquinoneimine that forms irreversible covalent bonds with mitochondrial protein thiols, driving fulminant hepatic necrosis.\"}},{\"id\":\"opt-12c\",\"text\":{\"tr\":\"10 mmol glutatyon katalitik bir enzim gibi çalışıp 16 mmol NAPQI'nin tamamını sıfırlar; GSH tükenmesi yaşanmaz ve karaciğer korunur.\",\"ar\":\"يعمل 10 ميليمول جلوتاثيون كإنزيم حفاز لإبطال مفعول كامل الـ 16 ميليمول NAPQI دون أي استنزاف لـ GSH.\",\"en\":\"The 10 mmol glutathione functions as a catalytic enzyme to neutralize all 16 mmol NAPQI repeatedly without undergoing consumable depletion.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Katalitik glutatyon yanılgısı: GSH bir enzim değildir; NAPQI ile bire bir (1:1 stoikiometrik) tüketilen feda edilebilir bir tripeptittir. 10 mmol GSH bittiğinde kalan 6 mmol NAPQI hücreyi yok eder.\",\"ar\":\"مغالطة الطبيعة الحفازة للجلوتاثيون: GSH ليس إنزيماً بل ركيزة ببتيدية تُستهلك بنسبة ستوكيومترية (1:1)؛ ونفاذ الـ 10 ميليمول يترك 6 ميليمول تدمر الخلايا.\",\"en\":\"Catalytic glutathione misconception: GSH is a consumable tripeptide co-substrate consumed stoichiometrically 1:1; once depleted, excess electrophilic NAPQI devastates hepatocyte proteins.\"}}]},\"technicalTerms\":[{\"term\":\"stoikiometrik toksisite dengesi\",\"arContext\":\"الميزان الحسابي للسمية\"},{\"term\":\"mitokondriyal protein arilasyonu\",\"arContext\":\"ألكلة بروتينات الميتوكوندريا\"}],\"hints\":[{\"tr\":\"66 mmol ilacın ne kadarının güvenli Faz II yollarıyla (SULT + UGT) temizlendiğini toplayın: 10 + 40 = 50 mmol.\",\"ar\":\"اجمع الكمية المعالجة بالمسارات الآمنة (SULT + UGT): 10 + 40 = 50 مليمول.\",\"en\":\"Sum the amount safely processed by SULT and UGT: 10 + 40 = 50 mmol.\"},{\"tr\":\"Geriye kalan miktar CYP2E1'e kayar: 66 - 50 = 16 mmol NAPQI.\",\"ar\":\"المقدار الفائض ينحرف نحو CYP2E1: 66 - 50 = 16 مليمول NAPQI.\",\"en\":\"The overflow shunts to CYP2E1: 66 - 50 = 16 mmol of reactive NAPQI.\"},{\"tr\":\"Karaciğerde 10 mmol GSH olduğuna göre 10 mmol NAPQI yakalanır; arta kalan 6 mmol serbest toksin karaciğeri yok eder.\",\"ar\":\"يمتلك الكبد 10 مليمول GSH، فيتبقى 6 مليمول من السم الحر ليدمر خلايا الكبد.\",\"en\":\"With only 10 mmol of GSH available, 6 mmol of unquenched NAPQI attacks cell proteins.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":35}],\"config\":{\"options\":[{\"id\":\"opt-12a\",\"text\":\"Glutatyon %100 tükenir; arta kalan 6 mmol serbest NAPQI hepatosit proteinlerine kovalent bağlanarak fulminan karaciğer nekrozunu tetikler.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz stoikiometrik ustalık! Hesaplama: 66 mmol parasetamolün 50 mmol'ü güvenli Faz II yollarıyla (10 mmol SULT + 40 mmol UGT) bağlanır. Doyum fazlası 16 mmol parasetamol CYP2E1 ile 16 mmol elektrofilik NAPQI üretir. Karaciğerdeki mevcut 10 mmol GSH bu toksinin 10 mmol'ünü nötralize eder ve GSH tamamen sıfırlanır (%100 tükenme). Kalan 6 mmol reaktif NAPQI, hücredeki mitokondriyal proteinlere kovalent bağlanarak saatler içinde masif hepatosit ölümüne yol açar. Acil NAC verilmezse tablo ölümcüldür.\"},{\"id\":\"opt-12b\",\"text\":\"16 mmol NAPQI hepatosit proteinlerine geri dönüşümlü bağlanır; CYP2E1 doyunca metabolit kendiliğinden kandan temizlenir ve nekroz önlenir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Geri dönüşümlü bağlanma yanılgısı: NAPQI elektrofilik bir kinonimindir; proteinlerin nükleofilik sistein tiyollerine kovalent (geri dönüşsüz) bağlanarak mitokondriyi çökertir ve masif nekroz başlatır.\"},{\"id\":\"opt-12c\",\"text\":\"10 mmol glutatyon katalitik bir enzim gibi çalışıp 16 mmol NAPQI'nin tamamını sıfırlar; GSH tükenmesi yaşanmaz ve karaciğer korunur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Katalitik glutatyon yanılgısı: GSH bir enzim değildir; NAPQI ile bire bir (1:1 stoikiometrik) tüketilen feda edilebilir bir tripeptittir. 10 mmol GSH bittiğinde kalan 6 mmol NAPQI hücreyi yok eder.\"}],\"revealedOutcome\":{\"tr\":\"Glutatyon %100 tükenir; arta kalan 6 mmol serbest NAPQI hepatosit proteinlerine kovalent bağlanarak fulminan karaciğer nekrozunu tetikler.\",\"ar\":\"يستنفد الجلوتاثيون بنسبة 100%؛ ويرتبط الفائض (6 مليمول) من NAPQI ببروتينات الكبد تساهمياً مسبباً تنخراً كبدياً صاعقاً ومميتاً.\",\"en\":\"Glutathione is 100% exhausted; the remaining 6 mmol of free NAPQI binds covalently to hepatocyte vital proteins, triggering fulminant hepatic necrosis.\"},\"explanation\":{\"tr\":\"Kusursuz stoikiometrik ustalık! Hesaplama: 66 mmol parasetamolün 50 mmol'ü güvenli Faz II yollarıyla (10 mmol SULT + 40 mmol UGT) bağlanır. Doyum fazlası 16 mmol parasetamol CYP2E1 ile 16 mmol elektrofilik NAPQI üretir. Karaciğerdeki mevcut 10 mmol GSH bu toksinin 10 mmol'ünü nötralize eder ve GSH tamamen sıfırlanır (%100 tükenme). Kalan 6 mmol reaktif NAPQI, hücredeki mitokondriyal proteinlere kovalent bağlanarak saatler içinde masif hepatosit ölümüne yol açar. Acil NAC verilmezse tablo ölümcüldür.\",\"ar\":\"تمكن كيميائي وحسابي باهر! الحساب: 50 مليمول تُعالج بـ UGT و SULT. الفائض (16 مليمول) يتحول إلى 16 مليمول من سم NAPQI. يستهلك هذا السم كامل رصيد الجلوتاثيون البالغ 10 مليمول (استنزاف 100%). الفائض المتبقي (6 مليمول) يهاجم بروتينات الميتوكوندريا تساهمياً ويحدث تنخراً كبدياً شاملاً يستوجب إعطاء NAC فوراً.\",\"en\":\"Flawless stoichiometric mastery! Clear balance: 50 mmol is cleared safely via UGT (40 mmol) and SULT (10 mmol). The 16 mmol overflow is shunted to CYP2E1, generating 16 mmol of NAPQI. This instantly exhausts the entire 10 mmol hepatic GSH reserve (100% depletion). The leftover 6 mmol of unquenched NAPQI irreversibly alkylates essential hepatocyte proteins, initiating fulminant hepatic failure.\"}}}]},\"pharm-mod1-les1\":{\"$schema\":\"../../../packages/platform/schema/lesson.schema.json\",\"id\":\"pharm-mod1-les1\",\"courseId\":\"pharmacology\",\"moduleId\":\"ph-mod-01\",\"title\":{\"tr\":\"Makromoleküler İlaç Hedefleri ve Kimyasal Bağlar\",\"ar\":\"أهداف الأدوية الجزيئية وطاقات الروابط الكيميائية\",\"en\":\"Macromolecular Drug Targets & Chemical Bond Energetics\"},\"order\":1,\"access\":\"free\",\"objective\":{\"tr\":\"İlaç-reseptör etkileşimlerini kimyasal bağ türlerine göre sınıflandırmak, bağ enerjilerini termodinamik açıdan hesaplamak ve etkinin tersinirliğini öngörmek.\",\"ar\":\"تصنيف تفاعلات الدواء والمستقبل وفق نوع الرابطة الكيميائية، وحساب طاقات الارتباط ديناميكياً حرارياً، والتنبؤ بعكوسية التأثير واستمراريته.\",\"en\":\"Classify drug-receptor interactions by chemical bond types, calculate binding stability from thermodynamic energies, and predict reversibility.\"},\"misconceptions\":[{\"tr\":\"Kovalent bağların vücut sıcaklığında (37°C) kendiliğinden koparak geri dönüşümlü etki gösterebileceği yanılgısı.\",\"ar\":\"الاعتقاد الخاطئ بأن الروابط التساهمية تتفكك تلقائياً بحرارة الجسم (37 مئوية) لتمنح تأثيراً عكوساً.\",\"en\":\"The misconception that covalent bonds break spontaneously at physiological temperature (37°C) allowing reversible action.\"},{\"tr\":\"Hidrofobik etkileşimin apolar atomlar arasındaki doğrudan bir manyetik çekim kuvveti olduğu yanılgısı (aslında su klatrat kafesinin yıkılmasıyla oluşan entropik itici güçtür).\",\"ar\":\"الظن الخاطئ بأن التأثر الكاره للماء هو تجاذب مغناطيسي مباشر بين الذرات اللابولارية (بل هو قوة دافعة إنتروبية ناشئة عن تحطم قفص الكلاثرات المائي).\",\"en\":\"The assumption that hydrophobic interaction is a direct magnetic-like attraction between nonpolar atoms (actually an entropic driving force from water cage collapse).\"},{\"tr\":\"EDTA şelatörünün kanda sadece yabancı ağır metalleri bağlayıp kalsiyuma dokunmayacağı yanılgısı (serbest EDTA fatal hipokalsemik tetani yapar).\",\"ar\":\"الاعتقاد الخاطئ بأن EDTA يخلب المعادن الثقيلة السامة فقط دون المساس بالكالسيوم (الحمض الحر يسبب كزاز نقص الكالسيوم القاتل).\",\"en\":\"The misconception that EDTA selectively binds foreign heavy metals without chelating endogenous calcium.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":5},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":7},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":9},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":10},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":11},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":12},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":14},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":15},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":24},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":25},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":32},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":33}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Goodman & Gilman's The Pharmacological Basis of Therapeutics\",\"edition\":\"14th ed.\",\"topic\":\"Drug-Receptor Interactions and Chemical Bonding\",\"chapter\":\"Chapter 3\",\"page\":\"45-68\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Katzung's Basic & Clinical Pharmacology\",\"edition\":\"15th ed.\",\"topic\":\"Receptors and Pharmacodynamics\",\"chapter\":\"Chapter 2\",\"page\":\"20-38\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"pharm-mod1-les1-card1\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Kimyasal Bağ Enerjisi Sıralaması\",\"prompt\":\"İlaç-reseptör etkileşiminde kimyasal bağ enerjilerini en güçlüden en zayıfa doğru sıralayınız.\",\"answer\":\"Kovalan (50-150 kcal/mol) > İyonik (5-10) > Hidrojen (2-7) > İyon-Dipol (1-5) > Hidrofobik (0.5-2) > Van der Waals (0.5-1).\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod1-les1-card2\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Kovalent İlaç Etki Mekanizmaları\",\"prompt\":\"Penisilin, organofosfat (sarin) ve azotlu hardalların hedef makromoleküle kovalent bağlanma türleri nelerdir?\",\"answer\":\"Penisilin transpeptidaz serinini açiller; organofosfat AChE serinini fosforiller; azotlu hardal DNA guanin N7 atomunu alkiller.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod1-les1-card3\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Hidrofobik Etkileşimin Termodinamik Gücü\",\"prompt\":\"Hidrofobik etkileşimi spontan ve kuvvetli kılan termodinamik itici güç nedir?\",\"answer\":\"Entropik itici güçtür (Delta S > 0); apolar gruplar bir araya geldiğinde su moleküllerinin klatrat kafesi yıkılarak serbest kalır.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod1-les1-card4\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"EDTA vs BAL Şelasyon Ayrımı\",\"prompt\":\"EDTA ile BAL (Dimerkaprol) şelatörlerinin dişlilik ve klinik antidot kullanım farkı nedir?\",\"answer\":\"EDTA 6-dişli (heksadentat) yapısıyla Pb2+ ve Ca2+ bağlar; BAL 2-dişli ditiyol yapısıyla As, Hg ve Au bağlayarak idrarla atar.\",\"box\":1,\"intervalDays\":1}],\"steps\":[{\"id\":\"pharm-mod1-les1-step-01\",\"stage\":\"hook\",\"stageIndex\":1,\"type\":\"predict_reveal\",\"predictThenReveal\":true,\"title\":{\"tr\":\"Sarin Felci Paradoksu: Neden Günlerce Sürer?\",\"ar\":\"مفارقة شلل غاز السارين: لماذا يستمر لأيام؟\",\"en\":\"The Sarin Paralysis Paradox: Why Does It Persist for Days?\"},\"prompt\":{\"tr\":\"Sarin gazı soluyan kurbanda felç zehir kandan temizlense bile günlerce sürerken, asetilkolin milisaniyede biter. İlacı reseptörde günlerce kilitli tutan kimyasal sır nedir?\",\"ar\":\"يستمر شلل غاز السارين لأيام حتى بعد تنظيفه من الدم، بينما ينتهي الأستيل كولين في ميلي ثانية. ما هو السر الكيميائي وراء إقفال الدواء على مستقبله لأيام؟\",\"en\":\"Sarin paralysis persists for days after blood clearance, while acetylcholine clears in milliseconds. What chemical secret locks a drug onto its target for days?\"},\"config\":{\"revealedOutcome\":{\"tr\":\"Sarin AChE aktif bölgesindeki Serin hidroksiline kovalent fosforilasyonla (50-150 kcal/mol) bağlanır. 37°C vücut sıcaklığında bu kovalent bağ kendiliğinden kopamaz; klinik etkinin sonlanması ancak vücudun sıfırdan yeni AChE enzimi sentezlemesiyle mümkündür!\",\"ar\":\"يرتبط السارين تساهمياً بفوسفورية هيدروكسيل السيرين (50-150 كيلو كالوري/مول) في جيب AChE. لا يمكن تفكيك هذا الرابط بحرارة الجسم 37 مئوية؛ يتطلب الشفاء تصنيع إنزيم جديد بالكامل!\",\"en\":\"Sarin covalently phosphorylates the active Serine of AChE (50-150 kcal/mol). At 37°C, this bond cannot break spontaneously; clinical recovery strictly requires de novo protein synthesis of new AChE!\"},\"explanation\":{\"tr\":\"Slayt 9 ve 12: Asetilkolin ester bağıyla bağlanıp saniyede 25.000 kez hidroliz edilirken, organofosfat kovalent fosforilasyon oluşturur. 50-150 kcal/mol enerjili kovalent bağlar biyolojik ortamda geri dönüşümsüzdür.\",\"ar\":\"شريحة 9 و 12: يتحلمه الأستيل كولين 25,000 مرة في الثانية بروابط إسترية عكوسة، بينما يشكل السارين فوسفرة تساهمية بطاقة 50-150 كيلو كالوري/مول غير عكوسة.\",\"en\":\"Slides 9 & 12: Acetylcholine hydrolyzes 25,000 times/sec, whereas Sarin forms a covalent phospho-serine adduct (50-150 kcal/mol) that is biologically irreversible.\"},\"options\":[{\"id\":\"opt-1a\",\"text\":\"Sarin aktif bölgedeki Serin amino asidini kovalent fosforiller (50-150 kcal/mol); bağ spontan kopamaz ve etki yeni enzim sentezini bekler.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz moleküler kavrayış! Slayt 9 ve 12: Kovalent bağlar (50-150 kcal/mol) atomlar arasında elektron ortaklaşmasıyla kurulur. Biyolojik vücut sıcaklığında (37°C) kendiliğinden kopması imkansızdır. Etkinin sonlanması için hücrenin yeni AChE enzimi sentezlemesi şarttır.\"},{\"id\":\"opt-1b\",\"text\":\"Sarin kanda hiç serbest kalmayıp akciğer alveollerine geri emilerek sürekli sinirleri kimyasal olarak uyarır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Alveoler geri emilim yanılgısı: Sarin dokulara hızla dağılır ve kandaki serbest seviyesi saatler içinde düşer; uzamış felcin nedeni ilacın kanda kalması değil, enzime kovalent kenetlenmesidir.\"},{\"id\":\"opt-1c\",\"text\":\"Sarin molekülleri asetilkolin gibi parçalanır fakat parçalanan fosfat tuzları kas hücrelerini mekanik olarak tıkar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Mekanik tıkaç yanılgısı: Sarin hidroliz edilerek zararsız tuzlara dönüşemez; AChE enziminin katalitik merkezini kovalent fosforilasyonla dondurarak asetilkolin birikimine yol açar.\"}]},\"conceptCheck\":{\"options\":[{\"id\":\"opt-1a\",\"text\":{\"tr\":\"Sarin aktif bölgedeki Serin amino asidini kovalent fosforiller (50-150 kcal/mol); bağ spontan kopamaz ve etki yeni enzim sentezini bekler.\",\"ar\":\"يقوم السارين بفَسفرة تساهمية لسيرين الموقع النشط (50-150 كيلو كالوري/مول)؛ الرابط لا ينفك تلقائياً والشفاء يتطلب تصنيع إنزيم جديد.\",\"en\":\"Sarin covalently phosphorylates the active-site Serine (50-150 kcal/mol); the bond cannot break spontaneously, requiring new enzyme synthesis.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz moleküler kavrayış! Slayt 9 ve 12: Kovalent bağlar (50-150 kcal/mol) atomlar arasında elektron ortaklaşmasıyla kurulur. Biyolojik vücut sıcaklığında (37°C) kendiliğinden kopması imkansızdır. Etkinin sonlanması için hücrenin yeni AChE enzimi sentezlemesi şarttır.\",\"ar\":\"فهم جزيئي دقيق! شريحة 9 و 12: الروابط التساهمية تنشأ بمشاركة الإلكترونات بطاقة هائلة تجعل تفككها مستحيلاً بحرارة 37 مئوية، فيرتهن زوال الأثر بتخليق إنزيم جديد.\",\"en\":\"Superb molecular deduction! Slides 9 & 12: Covalent bonds (50-150 kcal/mol) share electron pairs. At 37°C thermal energy cannot cleave them; recovery strictly requires de novo protein synthesis.\"}},{\"id\":\"opt-1b\",\"text\":{\"tr\":\"Sarin kanda hiç serbest kalmayıp akciğer alveollerine geri emilerek sürekli sinirleri kimyasal olarak uyarır.\",\"ar\":\"لا يتحرر السارين في الدم بل يعاد امتصاصه إلى الحويصلات الهوائية ليواصل تحفيز الأعصاب كيميائياً.\",\"en\":\"Sarin never circulates freely, recycling continuously into lung alveoli to stimulate nerves.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Alveoler geri emilim yanılgısı: Sarin dokulara hızla dağılır ve kandaki serbest seviyesi saatler içinde düşer; uzamış felcin nedeni ilacın kanda kalması değil, enzime kovalent kenetlenmesidir.\",\"ar\":\"مغالطة إعادة الامتصاص السنخي: يتوزع السارين بسرعة وينخفض تركيزه البلازمي خلال ساعات؛ سبب الشلل الممتد هو الرابط التساهمي الثابت مع الإنزيم.\",\"en\":\"Alveolar recycling fallacy: Sarin distributes rapidly and clears from blood within hours; persistent toxicity is driven entirely by irreversible target covalent adducts.\"}},{\"id\":\"opt-1c\",\"text\":{\"tr\":\"Sarin molekülleri asetilkolin gibi parçalanır fakat parçalanan fosfat tuzları kas hücrelerini mekanik olarak tıkar.\",\"ar\":\"يتفكك السارين كالأستيل كولين ولكن أملاح الفوسفات الناتجة تسد ألياف العضلات ميكانيكياً.\",\"en\":\"Sarin hydrolyzes normally, but precipitate phosphate crystals mechanically block neuromuscular fibers.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Mekanik tıkaç yanılgısı: Sarin hidroliz edilerek zararsız tuzlara dönüşemez; AChE enziminin katalitik merkezini kovalent fosforilasyonla dondurarak asetilkolin birikimine yol açar.\",\"ar\":\"مغالطة الانسداد الميكانيكي: لا يتحلمه السارين إلى أملاح بريئة، بل يجمد المركز التحفيزي لإنزيم AChE بالفَسفرة التساهمية الدائمة.\",\"en\":\"Mechanical plug fallacy: Sarin does not hydrolyze into benign salts; it covalently freezes the AChE catalytic machinery, producing massive acetylcholine accumulation.\"}}]},\"technicalTerms\":[{\"term\":\"kovalan bağ\",\"arContext\":\"الرابطة التساهمية\"},{\"term\":\"asetilkolinesteraz\",\"arContext\":\"إنزيم أستيل كولين إستراز (AChE)\"}],\"hints\":[{\"tr\":\"Asetilkolin ile sarinin enzim üzerindeki bağlanma doğasını karşılaştırın: Reversibilite kuralı.\",\"ar\":\"قارن بين طبيعة ارتباط الأستيل كولين العكوس وارتباط السارين مع الإنزيم.\",\"en\":\"Compare the reversibility of acetylcholine binding versus organophosphate binding.\"},{\"tr\":\"Enzimin aktif bölgesindeki serin amino asidinin -OH grubu kovalent olarak fosforillenir.\",\"ar\":\"تتعرض مجموعة الهيدروكسيل في سيرين الموقع النشط لفَسفرة تساهمية مستقرة.\",\"en\":\"The active-site serine hydroxyl undergoes covalent phosphorylation with 50-150 kcal/mol energy.\"},{\"tr\":\"50-150 kcal/mol enerjili kovalent bağlar vücut sıcaklığında kopamaz; yeni enzim sentezi şarttır.\",\"ar\":\"طاقة الرابطة التساهمية تمنع تفككها بحرارة الجسم؛ والحل الوحيد هو تخليق إنزيم جديد.\",\"en\":\"Covalent bonds cannot dissociate thermally; reversal strictly requires de novo protein synthesis.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":12}]},{\"id\":\"pharm-mod1-les1-step-02\",\"stage\":\"question\",\"stageIndex\":2,\"type\":\"question\",\"title\":{\"tr\":\"Termodinamik Bağ Enerjisi ve Tersinirlik Eşiği\",\"ar\":\"طاقة الرابطة الديناميكية الحرارية وعتبة العكوسية\",\"en\":\"Thermodynamic Bond Energy & Reversibility Threshold\"},\"prompt\":{\"tr\":\"İlaç-hedef etkileşimlerinde 50-150 kcal/mol gibi devasa bir termodinamik enerjiye sahip olan ve 37°C vücut sıcaklığında kendiliğinden kopması imkansız olan kimyasal bağ türü hangisidir?\",\"ar\":\"أي نوع من الروابط الكيميائية يمتلك طاقة هائلة تبلغ 50-150 كيلو كالوري/مول، مما يجعل تفككه التلقائي عند درجة حرارة الجسم 37 مئوية مستحيلاً؟\",\"en\":\"Which chemical bond type possesses an immense thermodynamic energy of 50-150 kcal/mol, making spontaneous thermal dissociation at 37°C completely impossible in biological systems?\"},\"conceptCheck\":{\"options\":[{\"id\":\"opt-2a\",\"text\":{\"tr\":\"Kovalan bağ (50-150 kcal/mol); elektron çiftlerinin ortaklaşa kullanılmasıyla oluşur ve vücut sıcaklığında spontan kopması imkansızdır.\",\"ar\":\"الرابطة التساهمية (50-150 كيلو كالوري/مول)؛ تنشأ بمشاركة الإلكترونات ومستحيلة التفكك بحرارة الجسم.\",\"en\":\"Covalent bond (50-150 kcal/mol); formed by electron pair sharing, impossible to dissociate thermally at 37°C.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Slayt 7 ve 9: Kovalan bağlar 50-150 kcal/mol serbest enerjiye sahiptir. Bu bariyeri aşmak için gereken aktivasyon enerjisi 37°C'deki ısıl enerjiden (kT) kat kat büyüktür; bu yüzden tersinmez (irreversible) kabul edilirler.\",\"ar\":\"صحيح! شريحة 7 و 9: الروابط التساهمية تمتلك طاقة 50-150 كيلو كالوري/مول؛ وهي أعلى بكثير من الطاقة الحرارية الحيوية فتعد غير عكوسة تماماً.\",\"en\":\"Correct! Slides 7 & 9: Covalent bonds boast 50-150 kcal/mol. The activation barrier far exceeds thermal energy at 37°C, rendering them biologically irreversible.\"}},{\"id\":\"opt-2b\",\"text\":{\"tr\":\"İyonik bağ (5-10 kcal/mol); zıt yükler arasındaki elektrostatik çekim biyolojik sıvılarda kalıcıdır ve asla kopmaz.\",\"ar\":\"الرابطة الأيونية (5-10 كيلو كالوري/مول)؛ التجاذب بين الشحنات المتعاكسة في السوائل الحيوية دائم ولا ينفك أبداً.\",\"en\":\"Ionic bond (5-10 kcal/mol); electrostatic attraction between opposite charges in biofluids is permanent and unbreakable.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"İyonik kalıcılık yanılgısı: Slayt 14: İyonik bağlar 5-10 kcal/mol gibi orta düzey enerji taşır ve suyun dielektrik sabiti (epsilon = 80) nedeniyle sulu ortamda dinamik olarak hızla ayrışıp tersinir dengeye girer.\",\"ar\":\"مغالطة ثبات الرابط الأيوني: شريحة 14: طاقة الرابط الأيوني 5-10 كيلو كالوري/مول؛ وثابت عزل الماء العالي (80) يتيح تفككه السريع بحركية عكوسة.\",\"en\":\"Ionic permanence fallacy: Slide 14: Ionic bonds possess 5-10 kcal/mol; high solvent dielectric constant (epsilon = 80) allows rapid, reversible thermal dissociation.\"}},{\"id\":\"opt-2c\",\"text\":{\"tr\":\"Hidrojen bağı (2-7 kcal/mol); su moleküllerinin sağladığı kalkan nedeniyle vücutta en zor kopan kovalent olmayan bağdır.\",\"ar\":\"الرابطة الهيدروجينية (2-7 كيلو كالوري/مول)؛ تشكل درعاً مائياً يجعلها أصعب الروابط غير التساهمية تفككاً بالجسم.\",\"en\":\"Hydrogen bond (2-7 kcal/mol); protected by water shielding, making it thermally unbreakable in tissues.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Hidrojen bağı yanılgısı: Slayt 15: Hidrojen bağları 2-7 kcal/mol enerjiye sahiptir. Bu enerji vücut sıcaklığındaki termal dalgalanmalarla kolayca kopabilir ve saniyede milyonlarca kez açılıp kapanır.\",\"ar\":\"مغالطة الرابطة الهيدروجينية: شريحة 15: طاقتها 2-7 كيلو كالوري/مول، وتنفتح وتنغلق ملايين المرات في الثانية بفعل الاضطراب الحراري.\",\"en\":\"Hydrogen bond fallacy: Slide 15: Hydrogen bonds carry 2-7 kcal/mol; thermal fluctuations rapidly break and reform them millions of times per second.\"}}]},\"technicalTerms\":[{\"term\":\"bağ enerjisi\",\"arContext\":\"طاقة الرابطة الكيميائية\"},{\"term\":\"tersinirlik\",\"arContext\":\"العكوسية الديناميكية\"}],\"hints\":[{\"tr\":\"Atomların elektronlarını ortaklaşa kullandığı en güçlü kimyasal bağı düşünün.\",\"ar\":\"فكر في الرابطة الأقوى التي تتشارك فيها الذرات أزواج الإلكترونات.\",\"en\":\"Think of the primary bond where atoms share valence electron pairs.\"},{\"tr\":\"Slayt 7 tablosuna bakın: 50-150 kcal/mol aralığında sadece tek bir bağ türü vardır.\",\"ar\":\"انظر جدول شريحة 7: يوجد نوع واحد فقط يقع في نطاق 50-150 كيلو كالوري/مول.\",\"en\":\"Review Slide 7: Only one bond type occupies the 50-150 kcal/mol range.\"},{\"tr\":\"Cevap kovalan bağdır; diğer tüm non-kovalent bağlar 0.5-10 kcal/mol aralığındadır.\",\"ar\":\"الجواب هو الرابطة التساهمية؛ بينما تتراوح باقي الروابط بين 0.5 إلى 10 كيلو كالوري/مول.\",\"en\":\"The answer is covalent bonding; all non-covalent forces span 0.5 to 10 kcal/mol.\"}],\"config\":{\"options\":[{\"id\":\"opt-2a\",\"text\":\"Kovalan bağ (50-150 kcal/mol); elektron çiftlerinin ortaklaşa kullanılmasıyla oluşur ve vücut sıcaklığında spontan kopması imkansızdır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Slayt 7 ve 9: Kovalan bağlar 50-150 kcal/mol serbest enerjiye sahiptir. Bu bariyeri aşmak için gereken aktivasyon enerjisi 37°C'deki ısıl enerjiden (kT) kat kat büyüktür; bu yüzden tersinmez (irreversible) kabul edilirler.\"},{\"id\":\"opt-2b\",\"text\":\"İyonik bağ (5-10 kcal/mol); zıt yükler arasındaki elektrostatik çekim biyolojik sıvılarda kalıcıdır ve asla kopmaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"İyonik kalıcılık yanılgısı: Slayt 14: İyonik bağlar 5-10 kcal/mol gibi orta düzey enerji taşır ve suyun dielektrik sabiti (epsilon = 80) nedeniyle sulu ortamda dinamik olarak hızla ayrışıp tersinir dengeye girer.\"},{\"id\":\"opt-2c\",\"text\":\"Hidrojen bağı (2-7 kcal/mol); su moleküllerinin sağladığı kalkan nedeniyle vücutta en zor kopan kovalent olmayan bağdır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Hidrojen bağı yanılgısı: Slayt 15: Hidrojen bağları 2-7 kcal/mol enerjiye sahiptir. Bu enerji vücut sıcaklığındaki termal dalgalanmalarla kolayca kopabilir ve saniyede milyonlarca kez açılıp kapanır.\"}]},\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":7},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":9}]},{\"id\":\"pharm-mod1-les1-step-03\",\"stage\":\"intuition\",\"stageIndex\":3,\"type\":\"intuition\",\"title\":{\"tr\":\"Zihinsel Model: Kaynak Dikişi vs Cırt-Cırt (Velcro)\",\"ar\":\"النموذج الذهني: اللحام الدائم في مقابل شريط الفيلكرو\",\"en\":\"Mental Model: Permanent Weld vs Multi-Hook Velcro\"},\"prompt\":{\"tr\":\"Kaynak dikişi ile cırt-cırt (Velcro) kumaşı hayal edin. Tek bir kaynak dikişi yapıyı kalıcı kilitlerken, binlerce küçük cırt-cırt lifi bir arada ne tür bir bağlanma davranışı sergiler?\",\"ar\":\"تخيل لحاماً حديدياً في مقابل شريط الفيلكرو. بينما يثبت اللحام الهيكل بشكل دائم، ما هو السلوك الذي تظهره آلاف ألياف الفيلكرو الدقيقة مجتمعة عند الارتباط؟\",\"en\":\"Imagine a permanent weld versus a Velcro strip. While a single weld locks a joint permanently, what binding behavior emerges when dozens of microscopic Velcro hooks engage simultaneously?\"},\"conceptCheck\":{\"options\":[{\"id\":\"opt-3a\",\"text\":{\"tr\":\"Tek tek lifler zayıftır fakat yüzlercesi birleşince sımsıkı tutar; istendiğinde çekilerek hiçbir yapı bozulmadan tersinir şekilde ayrılabilir.\",\"ar\":\"الألياف الفردية ضعيفة لكن تجمع المئات منها يمنح ثباتاً قوياً، ويمكن فصلها بعكوسية تامة دون إتلاف النسيج.\",\"en\":\"Individual hooks are weak, but dozens combined grip firmly; pulling separates them reversibly without structural damage.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika bir analoji! Slayt 8: İlaç molekülü reseptörle aynı anda 10-15 non-kovalent bağ kurduğunda toplam bağlanma serbest enerjisi Delta G = -10 ila -15 kcal/mol seviyesine çıkar. Bu güç mikromolar/nanomolar afinite sağlar; ancak kovalent kaynak gibi reseptörü tahrip etmez, ayrışma hız sabiti (koff) ile tersinir kalır.\",\"ar\":\"تشبيه عبقري! شريحة 8: تشكيل 10-15 رابط غير تساهمي يمنح طاقة إجمالية -10 إلى -15 كيلو كالوري/مول، مما يحقق ألفة عالية وعكوسية تامة دون تخريب المستقبل.\",\"en\":\"Superb analogy! Slide 8: 10-15 simultaneous non-covalent bonds sum to Delta G = -10 to -15 kcal/mol, providing high affinity and selectivity with complete reversibility.\"}},{\"id\":\"opt-3b\",\"text\":{\"tr\":\"Cırt-cırt lifleri kovalent bağdan daha güçlüdür; bu yüzden tersinir ilaçlar kovalent ilaçlardan daha uzun süre etki eder.\",\"ar\":\"ألياف الفيلكرو أقوى من اللحام؛ لذلك تدوم الأدوية العكوسة لفترة أطول من الأدوية التساهمية.\",\"en\":\"Velcro fibers are mechanically stronger than welds; hence reversible drugs act longer than covalent ones.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Afinite-kuvvet yanılgısı: Kovalent bağ (50-150 kcal/mol) non-kovalent bağlardan en az 10-20 kat daha güçlüdür; tersinir ilaçlar asla kovalent ilaçlardan daha kalıcı olamaz.\",\"ar\":\"مغالطة قوة الألفة: الروابط التساهمية أقوى بـ 10-20 ضعفاً من الروابط غير التساهمية، ولا يمكن للأدوية العكوسة أن تفوقها في بقاء الارتباط.\",\"en\":\"Affinity-strength confusion: Covalent bonds are 10-20 times stronger than individual non-covalent interactions; reversible drugs cannot exceed covalent persistence.\"}},{\"id\":\"opt-3c\",\"text\":{\"tr\":\"İlaç molekülü reseptör cebine bir bozuk para gibi mekanik olarak sıkışır; hiçbir elektrostatik çekim kuvveti rol oynamaz.\",\"ar\":\"ينحشر جزيء الدواء ميكانيكياً في جيب المستقبل كقطعة نقدية دون أي دور لقوى التجاذب الكهروستاتيكي.\",\"en\":\"The drug molecule mechanically wedges into the receptor pocket like a coin in a slot without requiring electrostatic attractions.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Mekanik sıkışma yanılgısı: Reseptör bağlanması makroskobik mekanik bir kilitlenme değildir; tamamlayıcı kimyasal grupların Coulomb, dipol, hidrojen ve van der Waals etkileşimlerinin elektrostatik dengesidir.\",\"ar\":\"مغالطة الانحشار الميكانيكي: الارتباط بالمستقبل ليس انحشاراً ميكانيكياً؛ بل هو توازن كهروستاتيكي دقيق لقوى كولوم والروابط الهيدروجينية وفان دير فالس.\",\"en\":\"Mechanical wedging fallacy: Receptor binding is not macro-mechanical entrapment; it requires precise electronic complementarity across ionic, hydrogen, and dispersion fields.\"}}]},\"technicalTerms\":[{\"term\":\"aditif serbest enerji\",\"arContext\":\"الطاقة الحرة التراكمية\"},{\"term\":\"koff ayrışma hızı\",\"arContext\":\"معدل التفكك الحركي (koff)\"}],\"hints\":[{\"tr\":\"Velcro kumaşındaki her bir minik plastik kanca tek başına ne kadar ağırlık taşır?\",\"ar\":\"كم من الوزن يستطيع خيط بلاستيكي فردي في شريط الفيلكرو أن يحمل بمفرده؟\",\"en\":\"How much weight can a single microscopic plastic hook support on its own?\"},{\"tr\":\"Bireysel olarak zayıf bağların toplanarak yüksek tutunma sağlamasını düşünün.\",\"ar\":\"فكر في اجتماع الروابط الضعيفة فردياً لتوليد قوة تماسك عالية إجمالاً.\",\"en\":\"Consider how individually weak forces sum up to generate strong collective adhesion.\"},{\"tr\":\"Cırt-cırt modeli çoklu zayıf bağların hem yüksek afinite hem tersinirlik sağlamasını temsil eder.\",\"ar\":\"يمثل الفيلكرو كيف يمنح تضافر الروابط الضعيفة ألفة عالية مع بقاء الارتباط عكوساً.\",\"en\":\"Velcro exemplifies multi-point binding: high collective affinity paired with effortless reversibility.\"}],\"config\":{\"options\":[{\"id\":\"opt-3a\",\"text\":\"Tek tek lifler zayıftır fakat yüzlercesi birleşince sımsıkı tutar; istendiğinde çekilerek hiçbir yapı bozulmadan tersinir şekilde ayrılabilir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika bir analoji! Slayt 8: İlaç molekülü reseptörle aynı anda 10-15 non-kovalent bağ kurduğunda toplam bağlanma serbest enerjisi Delta G = -10 ila -15 kcal/mol seviyesine çıkar. Bu güç mikromolar/nanomolar afinite sağlar; ancak kovalent kaynak gibi reseptörü tahrip etmez, ayrışma hız sabiti (koff) ile tersinir kalır.\"},{\"id\":\"opt-3b\",\"text\":\"Cırt-cırt lifleri kovalent bağdan daha güçlüdür; bu yüzden tersinir ilaçlar kovalent ilaçlardan daha uzun süre etki eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Afinite-kuvvet yanılgısı: Kovalent bağ (50-150 kcal/mol) non-kovalent bağlardan en az 10-20 kat daha güçlüdür; tersinir ilaçlar asla kovalent ilaçlardan daha kalıcı olamaz.\"},{\"id\":\"opt-3c\",\"text\":\"İlaç molekülü reseptör cebine bir bozuk para gibi mekanik olarak sıkışır; hiçbir elektrostatik çekim kuvveti rol oynamaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Mekanik sıkışma yanılgısı: Reseptör bağlanması makroskobik mekanik bir kilitlenme değildir; tamamlayıcı kimyasal grupların Coulomb, dipol, hidrojen ve van der Waals etkileşimlerinin elektrostatik dengesidir.\"}]},\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":9}]},{\"id\":\"pharm-mod1-les1-step-04\",\"stage\":\"visual_explanation\",\"stageIndex\":4,\"type\":\"visual_explanation\",\"title\":{\"tr\":\"4 Reseptör Süperailesi ve Yanıt Hızları\",\"ar\":\"عائلات المستقبِلات الأربع وسرعات الاستجابة\",\"en\":\"The 4 Receptor Superfamilies & Response Velocities\"},\"prompt\":{\"tr\":\"Hücredeki 4 reseptör süperailesi farklı yanıtlama hızlarına sahiptir. Milisaniyeler içinde en hızlı yanıt veren süperailenin etki mekanizması nedir?\",\"ar\":\"تمتلك عائلات المستقبِلات الأربع سرعات استجابة متباينة للغاية. ما هي آلية عمل العائلة الأسرع التي تستجيب في غضون أجزاء من الثانية؟\",\"en\":\"The four receptor superfamilies exhibit vastly different response velocities. What effector mechanism allows the fastest family to trigger cellular depolarization in milliseconds?\"},\"conceptCheck\":{\"options\":[{\"id\":\"opt-4a\",\"text\":{\"tr\":\"İyonotropik reseptörler (ligand kapılı kanallar); agonist bağlanınca doğrudan iyon kanalını açarak milisaniyede (ms) membran potansiyelini değiştirir.\",\"ar\":\"المستقبلات الأيونية (قنوات مبوبة بربيطة)؛ يفتح ارتباط المنبه القناة الأيونية مباشرة ليغير جهد الغشاء خلال ميلي ثانية.\",\"en\":\"Ionotropic receptors (ligand-gated channels); agonist binding directly gates the channel pore to alter potential within milliseconds.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel! Slayt 5 karşılaştırma tablosu: 1) İyonotropik (Nikotinik ACh, GABAA): milisaniyeler (aracı kaskad yok, doğrudan gözenek açılır), 2) GPCR (Muskarinik, Adrenerjik): saniyeler (ikincil haberciler cAMP/IP3), 3) Kinaz-kenetli (İnsülin): dakikalar/saatler (tirozin otofosforilasyonu), 4) Nükleer (Steroid): saatler/günler (DNA transkripsiyonu).\",\"ar\":\"ممتاز! شريحة 5: 1) أيونية (nAChR): أجزاء من الثانية، 2) مقترنة ببروتين G: ثوانٍ، 3) مرتبطة بكينيز: دقائق/ساعات، 4) نووية داخلية: ساعات/أيام بتعديل النسخ الجيني.\",\"en\":\"Outstanding! Slide 5: 1) Ionotropic (nAChR): milliseconds, 2) GPCR (Adrenergic): seconds, 3) Kinase-linked (Insulin): minutes/hours, 4) Nuclear (Steroids): hours/days via gene transcription.\"}},{\"id\":\"opt-4b\",\"text\":{\"tr\":\"Nükleer reseptörler; hücre çekirdeğinde DNA zincirini doğrudan çekerek milisaniyeler içinde mRNA patlaması yapar.\",\"ar\":\"المستقبلات النووية؛ تؤثر مباشرة على شريط DNA في النواة لتحدث تدفقاً فورياً للرنا المرسال في ميلي ثانية.\",\"en\":\"Nuclear receptors; binding inside chromatin triggers instantaneous mRNA transcription bursts within milliseconds.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Nükleer hız yanılgısı: Slayt 5: Nükleer reseptörler en yavaş süperailedir (saatler veya günler sürer); çünkü nükleer translokasyon, kromatin açılması ve de novo protein translasyonu zaman alır.\",\"ar\":\"مغالطة سرعة المستقبِلات النووية: شريحة 5: المستقبِلات النووية هي الأبطأ إطلاقاً (ساعات لأيام) لأنها تتطلب نسخ وترجمة بروتينات جديدة.\",\"en\":\"Nuclear speed fallacy: Slide 5: Nuclear receptors are the slowest family (hours to days) because chromatin remodeling and protein synthesis require significant lag time.\"}},{\"id\":\"opt-4c\",\"text\":{\"tr\":\"Tüm reseptör süperaileleri hücre zarının dış yüzeyindedir ve yanıt süreleri birbirinden farksızdır.\",\"ar\":\"تتوضع جميع عائلات المستقبِلات على السطح الخارجي للغشاء وتتطابق سرعات استجابتها بالكامل.\",\"en\":\"All four receptor superfamilies reside strictly on the plasma membrane and share identical activation latencies.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Konum yanılgısı: Slayt 5: Nükleer reseptörler hücre zarında değil sitoplazmada veya nükleustadır; efektör mekanizmalarına göre yanıt hızları 100.000 kat farklılık gösterir.\",\"ar\":\"مغالطة التوضع: شريحة 5: المستقبِلات النووية داخل السيتوبلازم أو النواة، وتختلف سرعات الاستجابة بما يصل إلى 100,000 ضعف.\",\"en\":\"Cellular location fallacy: Slide 5: Nuclear receptors reside in the cytosol/nucleus; response times differ across superfamilies by over 5 orders of magnitude.\"}}]},\"technicalTerms\":[{\"term\":\"iyonotropik reseptör\",\"arContext\":\"المستقبل الأيوني (Ionotropic receptor)\"},{\"term\":\"GPCR süperailesi\",\"arContext\":\"المستقبلات المقترنة ببروتين G\"}],\"hints\":[{\"tr\":\"Hücre zarına yerleşik iyon kanallarının doğrudan kapılanmasını hatırlayın.\",\"ar\":\"تذكر القنوات الأيونية الغشائية التي تفتح بواباتها مباشرة بتأثير الربيطة.\",\"en\":\"Recall membrane channels whose pore opens directly upon ligand binding.\"},{\"tr\":\"Araya ikincil haberci (cAMP) veya gen transkripsiyonu girmeyen doğrudan mekanizmayı arayın.\",\"ar\":\"ابحث عن الآلية المباشرة التي لا تحتاج لوسطاء كـ cAMP أو نسخ جيني.\",\"en\":\"Look for the direct pore-opening mechanism without intervening secondary messengers.\"},{\"tr\":\"Cevap İyonotropik reseptörlerdir (Nikotinik asetilkolin, GABA-A); yanıt milisaniyeler sürer.\",\"ar\":\"الجواب هو المستقبِلات الأيونية مثل مستقبل النيكوتين وغابا-أ بسرعة أجزاء من الثانية.\",\"en\":\"The answer is Ionotropic receptors (nicotinic AChR, GABA-A) operating in milliseconds.\"}],\"config\":{\"options\":[{\"id\":\"opt-4a\",\"text\":\"İyonotropik reseptörler (ligand kapılı kanallar); agonist bağlanınca doğrudan iyon kanalını açarak milisaniyede (ms) membran potansiyelini değiştirir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel! Slayt 5 karşılaştırma tablosu: 1) İyonotropik (Nikotinik ACh, GABAA): milisaniyeler (aracı kaskad yok, doğrudan gözenek açılır), 2) GPCR (Muskarinik, Adrenerjik): saniyeler (ikincil haberciler cAMP/IP3), 3) Kinaz-kenetli (İnsülin): dakikalar/saatler (tirozin otofosforilasyonu), 4) Nükleer (Steroid): saatler/günler (DNA transkripsiyonu).\"},{\"id\":\"opt-4b\",\"text\":\"Nükleer reseptörler; hücre çekirdeğinde DNA zincirini doğrudan çekerek milisaniyeler içinde mRNA patlaması yapar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Nükleer hız yanılgısı: Slayt 5: Nükleer reseptörler en yavaş süperailedir (saatler veya günler sürer); çünkü nükleer translokasyon, kromatin açılması ve de novo protein translasyonu zaman alır.\"},{\"id\":\"opt-4c\",\"text\":\"Tüm reseptör süperaileleri hücre zarının dış yüzeyindedir ve yanıt süreleri birbirinden farksızdır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Konum yanılgısı: Slayt 5: Nükleer reseptörler hücre zarında değil sitoplazmada veya nükleustadır; efektör mekanizmalarına göre yanıt hızları 100.000 kat farklılık gösterir.\"}]},\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":5}]},{\"id\":\"pharm-mod1-les1-step-05\",\"stage\":\"interactive_artifact\",\"stageIndex\":5,\"type\":\"receptor_ligand_matcher\",\"widgetType\":\"ReceptorLigandMatcher\",\"title\":{\"tr\":\"Etkileşimli Eşleştirme: Dibukain Reseptör Kenetlenmesi\",\"ar\":\"المطابقة التفاعلية: رسو مخدر الديبوكائين في جيب المستقبل\",\"en\":\"Interactive Matcher: Dibucaine Receptor Multi-Point Docking\"},\"prompt\":{\"tr\":\"Dibukain lokal anestezik molekülünün 4 farmakofor grubunu voltaj kapılı sodyum kanalı reseptör cebindeki tamamlayıcı amino asitlerle eşleştirin.\",\"ar\":\"طابق المجموعات الدوائية الأربع لمخدر الديبوكائين الموضعي مع الأحماض الأمينية التكميلية في جيب مستقبل قناة الصوديوم.\",\"en\":\"Match the four pharmacophoric groups of local anesthetic dibucaine with their complementary amino acid residues inside the sodium channel receptor pocket.\"},\"config\":{\"title\":\"Dibukain Çok Noktalı Reseptör Kenetlenmesi\",\"prompt\":\"Dibukain farmakoforlarını reseptörün tamamlayıcı cepleriyle eşleştirin.\",\"drugName\":\"Dibukain (Sinkokain)\",\"receptorName\":\"Voltaj Kapılı Sodyum Kanalı Reseptör Cebi\",\"pairs\":[{\"id\":\"pair_amine\",\"drugGroup\":\"Protonlanmış Dietilamino Azotu (-NH+(C2H5)2)\",\"correctResidueId\":\"res_asp113\",\"bondType\":\"ionic\",\"energyKcalMol\":\"-5 to -10 kcal/mol\",\"explanation\":\"Asp113 karboksilat anyonu (-COO-) ile güçlü bir Coulomb iyonik tuz köprüsü kurar.\"},{\"id\":\"pair_amide\",\"drugGroup\":\"Amit Karbonil Oksijeni (-CO-NH-)\",\"correctResidueId\":\"res_ser165\",\"bondType\":\"h_bond\",\"energyKcalMol\":\"-2 to -7 kcal/mol\",\"explanation\":\"Ser165 hidroksil grubu ile doğrusal 180 derecelik yönlü hidrojen bağı kurar.\"},{\"id\":\"pair_butoxy\",\"drugGroup\":\"Butoksi Alifatik Zinciri (-O-C4H9)\",\"correctResidueId\":\"res_leu275\",\"bondType\":\"van_der_waals\",\"energyKcalMol\":\"-0.5 to -2 kcal/mol\",\"explanation\":\"Leu275 apolar yan zincirleriyle hidrofobik temas kurar ve su kafesini yıkar.\"},{\"id\":\"pair_quinoline\",\"drugGroup\":\"Kinolin Aromatik Halkası\",\"correctResidueId\":\"res_phe290\",\"bondType\":\"pi_pi\",\"energyKcalMol\":\"-0.5 to -1 kcal/mol\",\"explanation\":\"Phe290 aromatik benzen halkası ile pi-pi istiflenmesi ve London dispersiyonu oluşturur.\"}],\"residues\":[{\"id\":\"res_asp113\",\"residueName\":\"Asp113 (Karboksilat Anyonu)\",\"description\":\"Negatif yüklü elektrostatik anyonik tuz köprüsü cebi\"},{\"id\":\"res_ser165\",\"residueName\":\"Ser165 (Hidroksil Yan Zinciri)\",\"description\":\"Polar H-bağı donörü ve akseptörü cebi\"},{\"id\":\"res_leu275\",\"residueName\":\"Leu275 (Apolar Alifatik Kalıntı)\",\"description\":\"Alifatik hidrofobik cep kalıntısı\"},{\"id\":\"res_phe290\",\"residueName\":\"Phe290 (Aromatik Fenilalanin)\",\"description\":\"Aromatik pi-pi istiflenme ve dispersiyon cebi\"},{\"id\":\"res_glu107\",\"residueName\":\"Glu107 (Dış Yüzey Kalıntısı)\",\"description\":\"Bağlanma cebinin dışında kalan çözücüye açık kalıntı\"}],\"source\":{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":33}},\"widget\":{\"type\":\"ReceptorLigandMatcher\",\"config\":{\"title\":\"Dibukain Çok Noktalı Reseptör Kenetlenmesi\",\"prompt\":\"Dibukain farmakoforlarını reseptörün tamamlayıcı cepleriyle eşleştirin.\",\"drugName\":\"Dibukain (Sinkokain)\",\"receptorName\":\"Voltaj Kapılı Sodyum Kanalı Reseptör Cebi\",\"pairs\":[{\"id\":\"pair_amine\",\"drugGroup\":\"Protonlanmış Dietilamino Azotu (-NH+(C2H5)2)\",\"correctResidueId\":\"res_asp113\",\"bondType\":\"ionic\",\"energyKcalMol\":\"-5 to -10 kcal/mol\",\"explanation\":\"Asp113 karboksilat anyonu (-COO-) ile güçlü bir Coulomb iyonik tuz köprüsü kurar.\"},{\"id\":\"pair_amide\",\"drugGroup\":\"Amit Karbonil Oksijeni (-CO-NH-)\",\"correctResidueId\":\"res_ser165\",\"bondType\":\"h_bond\",\"energyKcalMol\":\"-2 to -7 kcal/mol\",\"explanation\":\"Ser165 hidroksil grubu ile doğrusal 180 derecelik yönlü hidrojen bağı kurar.\"},{\"id\":\"pair_butoxy\",\"drugGroup\":\"Butoksi Alifatik Zinciri (-O-C4H9)\",\"correctResidueId\":\"res_leu275\",\"bondType\":\"van_der_waals\",\"energyKcalMol\":\"-0.5 to -2 kcal/mol\",\"explanation\":\"Leu275 apolar yan zincirleriyle hidrofobik temas kurar ve su kafesini yıkar.\"},{\"id\":\"pair_quinoline\",\"drugGroup\":\"Kinolin Aromatik Halkası\",\"correctResidueId\":\"res_phe290\",\"bondType\":\"pi_pi\",\"energyKcalMol\":\"-0.5 to -1 kcal/mol\",\"explanation\":\"Phe290 aromatik benzen halkası ile pi-pi istiflenmesi ve London dispersiyonu oluşturur.\"}],\"residues\":[{\"id\":\"res_asp113\",\"residueName\":\"Asp113 (Karboksilat Anyonu)\",\"description\":\"Negatif yüklü elektrostatik anyonik tuz köprüsü cebi\"},{\"id\":\"res_ser165\",\"residueName\":\"Ser165 (Hidroksil Yan Zinciri)\",\"description\":\"Polar H-bağı donörü ve akseptörü cebi\"},{\"id\":\"res_leu275\",\"residueName\":\"Leu275 (Apolar Alifatik Kalıntı)\",\"description\":\"Alifatik hidrofobik cep kalıntısı\"},{\"id\":\"res_phe290\",\"residueName\":\"Phe290 (Aromatik Fenilalanin)\",\"description\":\"Aromatik pi-pi istiflenme ve dispersiyon cebi\"},{\"id\":\"res_glu107\",\"residueName\":\"Glu107 (Dış Yüzey Kalıntısı)\",\"description\":\"Bağlanma cebinin dışında kalan çözücüye açık kalıntı\"}],\"source\":{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":33}}},\"technicalTerms\":[{\"term\":\"kenetlenme (docking)\",\"arContext\":\"الرسو الجزيئي (Docking)\"},{\"term\":\"tuz köprüsü\",\"arContext\":\"الجسر الملحي الأيوني\"}],\"hints\":[{\"tr\":\"Pozitif yüklü amonyum grubunu negatif yüklü aspartat karboksilatına bağlayın.\",\"ar\":\"صل مجموعة الأمونيوم موجبة الشحنة بجيب الأسبارتات سالب الشحنة.\",\"en\":\"Connect the cationic ammonium to the anionic aspartate carboxylate.\"},{\"tr\":\"Apolar butoksi zincirini apolar lösin cebine, kinolini ise aromatik fenilalanin cebine oturtun.\",\"ar\":\"ضع سلسلة البوتوكسي اللابولارية في جيب اللوسين، وحلقة الكينولين مع الفينيل ألانين.\",\"en\":\"Place nonpolar butoxy into leucine and the quinoline ring against phenylalanine.\"},{\"tr\":\"Amin -> Asp113, Amit -> Ser165, Butoksi -> Leu275, Kinolin -> Phe290 eşleşmesini tamamlayın.\",\"ar\":\"أكمل المطابقة: أمين مع Asp113، أميد مع Ser165، بوتوكسي مع Leu275، كينولين مع Phe290.\",\"en\":\"Complete pairs: Amine -> Asp113, Amide -> Ser165, Butoxy -> Leu275, Quinoline -> Phe290.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":33}]},{\"id\":\"pharm-mod1-les1-step-06\",\"stage\":\"guided_discovery\",\"stageIndex\":6,\"type\":\"guided_discovery\",\"title\":{\"tr\":\"Keşif: Çok Noktalı Zayıf Bağların Büyüsü\",\"ar\":\"الاستكشاف: أسرار الارتباط متعدد النقاط عبر الروابط الضعيفة\",\"en\":\"Guided Discovery: The Magic of Multi-Point Non-Covalent Binding\"},\"prompt\":{\"tr\":\"Dibukain molekülünde tek bir bağ zayıfken (0.5-10 kcal/mol), 4-5 non-kovalent bağın aynı anda kurulması moleküle nasıl hem yüksek afinite hem de geri dönüşümlülük kazandırır?\",\"ar\":\"إذا كانت كل رابطة منفردة ضعيفة (0.5-10 كيلو كالوري/مول)، كيف يمنح تشكل 4-5 روابط غير تساهمية معاً الدواء ألفة بيكومولية عالية مع الحفاظ على عكوسيته؟\",\"en\":\"If individual non-covalent bonds are weak (0.5-10 kcal/mol), how does the simultaneous formation of 4-5 bonds deliver high nanomolar affinity while preserving reversibility?\"},\"conceptCheck\":{\"options\":[{\"id\":\"opt-6a\",\"text\":{\"tr\":\"Aditif serbest enerji: Her bağın serbest enerjisi toplanarak Delta G = -10 ila -15 kcal/mol'e ulaşır; bu toplam afinite sağlar ancak kovalent tahribat yapmaz.\",\"ar\":\"الطاقة الحرة التراكمية: تجتمع طاقات الروابط لتبلغ Delta G = -10 إلى -15 كيلو كالوري/مول، مما يمنح ألفة عالية دون تخريب تساهمي للمستقبل.\",\"en\":\"Additive free energy: Summing discrete interactions achieves Delta G = -10 to -15 kcal/mol, providing high target affinity without irreversible damage.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel termodinamik çıkarım! Slayt 8 ve 33: Tek bir kovalent bağ ilacı kalıcı kilitler. Ancak 1 iyonik (-8), 1 H-bağı (-4), 1 hidrofobik (-2) ve 1 pi-pi (-1) toplandığında Delta G = -15 kcal/mol olur. İlacın ayrışması için bu 4 bağın aynı anda salise içinde kopması gerekir; bu da ilacı saatlerce reseptörde tutar fakat konsantrasyon düşünce tersinir ayrılmaya izin verir.\",\"ar\":\"استنتاج ترموديناميكي باهر! شريحة 8 و 33: رابط تساهمي واحد يقفل المستقبل للأبد. بينما اجتماع 4 روابط ضعيفة يحقق Delta G = -15 كيلو كالوري/مول، فيلزم انفصامها معاً للتفكك مما يمنح ألفة عالية وعكوسية تامة.\",\"en\":\"Brilliant thermodynamic deduction! Slides 8 & 33: A single covalent weld is permanent. Summing 4 non-covalent bonds reaches Delta G = -15 kcal/mol, requiring all 4 to unbind simultaneously, yielding high residence time with complete reversibility.\"}},{\"id\":\"opt-6b\",\"text\":{\"tr\":\"Sulu ortamdaki su kılıfı polar grupları tamamen bloke eder; birden fazla bağ kurulsa dahi net serbest enerji sıfıra yakın kalır.\",\"ar\":\"يحجب الغلاف المائي المحيط المجموعات القطبية تماماً؛ ومهما تعددت الروابط تظل الطاقة الحرة الكلية قريبة من الصفر.\",\"en\":\"Bulk water hydration shells shield polar groups entirely; even with multiple contacts, net binding free energy remains near zero.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Solvatasyon engeli yanılgısı: Desolvatasyon endotermik bir bedel gerektirse de, bağlanma cebinde suyun dışarı atılması (hidrofobik entropi artışı) ve tamamlayıcı bağlar bu bedeli fazlasıyla aşarak net Delta G°'ı negatif ve yüksek afiniteli yapar.\",\"ar\":\"مغالطة حاجز الإماهة: طرد جزيئات الماء من الجيب يولد كسباً إنتروبياً هائلاً يتجاوز كلفة نزع الماء، جاعلاً الطاقة الحرة سالبة ومحققة للألفة العالية.\",\"en\":\"Solvation barrier fallacy: Water displacement from the binding pocket provides favorable entropic gain that easily overcomes desolvation penalties, yielding high negative Delta G.\"}},{\"id\":\"opt-6c\",\"text\":{\"tr\":\"Aynı anda 5 non-kovalent bağ kurulduğunda ayrışma hızı (koff) sıfıra iner ve ilaç kovalent bir ajan gibi kalıcı kilitlenir.\",\"ar\":\"عند تشكل 5 روابط غير تساهمية معاً، تنعدم سرعة التفكك (koff) ويُقفل الدواء بصورة دائمة كأنه عامل تساهمي.\",\"en\":\"Simultaneous formation of five non-covalent bonds forces dissociation rate (koff) to zero, locking the drug irreversibly like a covalent alkylator.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kalıcı kilitlenme yanılgısı: Non-kovalent bağların enerjisi (-10 ila -15 kcal/mol) çok yüksek bir afinite ve uzun rezidans süresi sağlasa da termodinamik denge korunur; koff asla sıfır olamaz ve ilaç konsantrasyonu düşünce serbestleşir.\",\"ar\":\"مغالطة القفل الدائم: الطاقة غير التساهمية (-10 إلى -15) تمنح ألفة عالية لكن التوازن الحركي يبقى محفوظاً؛ koff لا تنعدم أبداً ويتفكك الدواء عند هبوط تركيزه.\",\"en\":\"Non-covalent permanence misconception: Multi-point non-covalent contacts yield nanomolar affinity but retain dynamic reversibility; koff remains non-zero, allowing clearance.\"}}]},\"technicalTerms\":[{\"term\":\"serbest bağlanma enerjisi\",\"arContext\":\"طاقة الارتباط الحرة (Delta G)\"},{\"term\":\"rezidans süresi\",\"arContext\":\"زمن مكوث الدواء (Residence time)\"}],\"hints\":[{\"tr\":\"Matematiksel olarak bağlanma enerjilerinin toplamsal (aditif) kuralını hatırlayın.\",\"ar\":\"تذكر رياضياً مبدأ تراكم طاقات الارتباط الحرة (قاعدة الجمع).\",\"en\":\"Recall the additive nature of binding free energies (Delta G = Delta G1 + Delta G2...).\"},{\"tr\":\"4 farklı temas noktası aynı anda koptuğunda ancak molekül reseptörden serbest kalabilir.\",\"ar\":\"لا يتحرر الدواء إلا عند انفصام نقاط التماس الأربع مجتمعة في نفس اللحظة.\",\"en\":\"A drug can dissociate only when all multi-point contact sites detach simultaneously.\"},{\"tr\":\"Cevap aditif serbest enerjidir; 4 zayıf bağ Delta G = -15 kcal/mol yaparak yüksek afinite ve tersinirlik sağlar.\",\"ar\":\"الجواب هو الطاقة الحرة التراكمية، حيث مجموع الروابط يمنح ألفة عالية مع بقاء الارتباط عكوساً.\",\"en\":\"The answer is additive free energy: 4 weak bonds combine to Delta G = -15 kcal/mol, preserving reversibility.\"}],\"config\":{\"options\":[{\"id\":\"opt-6a\",\"text\":\"Aditif serbest enerji: Her bağın serbest enerjisi toplanarak Delta G = -10 ila -15 kcal/mol'e ulaşır; bu toplam afinite sağlar ancak kovalent tahribat yapmaz.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel termodinamik çıkarım! Slayt 8 ve 33: Tek bir kovalent bağ ilacı kalıcı kilitler. Ancak 1 iyonik (-8), 1 H-bağı (-4), 1 hidrofobik (-2) ve 1 pi-pi (-1) toplandığında Delta G = -15 kcal/mol olur. İlacın ayrışması için bu 4 bağın aynı anda salise içinde kopması gerekir; bu da ilacı saatlerce reseptörde tutar fakat konsantrasyon düşünce tersinir ayrılmaya izin verir.\"},{\"id\":\"opt-6b\",\"text\":\"Sulu ortamdaki su kılıfı polar grupları tamamen bloke eder; birden fazla bağ kurulsa dahi net serbest enerji sıfıra yakın kalır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Solvatasyon engeli yanılgısı: Desolvatasyon endotermik bir bedel gerektirse de, bağlanma cebinde suyun dışarı atılması (hidrofobik entropi artışı) ve tamamlayıcı bağlar bu bedeli fazlasıyla aşarak net Delta G°'ı negatif ve yüksek afiniteli yapar.\"},{\"id\":\"opt-6c\",\"text\":\"Aynı anda 5 non-kovalent bağ kurulduğunda ayrışma hızı (koff) sıfıra iner ve ilaç kovalent bir ajan gibi kalıcı kilitlenir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kalıcı kilitlenme yanılgısı: Non-kovalent bağların enerjisi (-10 ila -15 kcal/mol) çok yüksek bir afinite ve uzun rezidans süresi sağlasa da termodinamik denge korunur; koff asla sıfır olamaz ve ilaç konsantrasyonu düşünce serbestleşir.\"}]},\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":7},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":33}]},{\"id\":\"pharm-mod1-les1-step-07\",\"stage\":\"formal_explanation\",\"stageIndex\":7,\"type\":\"formal_explanation\",\"title\":{\"tr\":\"Kovalent İlaçların 4 Kimyasal Mekanizması\",\"ar\":\"الآليات الكيميائية الأربع للأدوية التساهمية\",\"en\":\"The 4 Chemical Mechanisms of Covalent Drugs\"},\"prompt\":{\"tr\":\"Kovalent ilaçlar hedef protein veya DNA'yı kalıcı olarak kilitler. Penisilin, organofosfatlar ve azotlu hardalların kovalent bağlanma reaksiyon mekanizmaları sırasıyla hangileridir?\",\"ar\":\"تقفل الأدوية التساهمية أهدافها من البروتينات أو الأحماض النووية بشكل دائم. ما هي الآليات الكيميائية لارتباط البنسلين والمركبات العضوية الفوسفورية وخردل النيتروجين على التوالي؟\",\"en\":\"Covalent drugs lock their target enzyme or DNA permanently. What are the respective chemical reaction mechanisms for penicillin, organophosphates, and nitrogen mustards?\"},\"conceptCheck\":{\"options\":[{\"id\":\"opt-7a\",\"text\":{\"tr\":\"Penisilin transpeptidazı açiller (beta-laktam halka açılması); organofosfat AChE'yi fosforiller; azotlu hardal DNA guanin N7'sini alkiller (aziridinyum katyonu).\",\"ar\":\"البنسلين يؤصّل ترانسببتيداز (فتح حلقة بيتا لاكتام)، والمركبات الفوسفورية تفسفر AChE، وخردل النيتروجين يؤلكل N7 في جوانين DNA.\",\"en\":\"Penicillin acylates transpeptidase (beta-lactam ring opening); organophosphates phosphorylate AChE; nitrogen mustards alkylate DNA guanine N7 (aziridinium cation).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika bir sınav ustalığı! Slayt 10, 11 ve 12'nin tam mekanik özeti: 1) Penisilin 4 üyeli gergin laktam halkasıyla transpeptidaz aktif Serinini açiller (açilasyon), 2) Organofosfatlar AChE esteratik Serinini fosforiller (fosforilasyon), 3) Azotlu hardallar aziridinyum iyonu üzerinden DNA guanin N7 atomunu alkiller (çapraz alkilasyon). Üçü de kalıcı kovalent adükt oluşturur.\",\"ar\":\"إتقان امتحاني رفيع! شريحة 10 و 11 و 12: البنسلين يؤصّل سيرين الترانسببتيداز، والفوسفات العضوية تفسفر سيرين AChE، وخردل النيتروجين يؤلكل غوانين DNA، وجميعها روابط تساهمية دائمة.\",\"en\":\"Flawless mechanistic mastery! Slides 10, 11 & 12: Penicillin acylates transpeptidase Serine, organophosphates phosphorylate AChE Serine, and nitrogen mustards alkylate DNA guanine N7 via aziridinium ions.\"}},{\"id\":\"opt-7b\",\"text\":{\"tr\":\"Penisilin ve organofosfatlar reseptörlerine sadece zayıf van der Waals bağlarıyla tutunur ve dakikalar içinde ayrılır.\",\"ar\":\"يرتبط البنسلين والفوسفات العضوية بمستقبلاتهما بروابط فان دير فالس الضعيفة فقط وينفصلان خلال دقائق.\",\"en\":\"Penicillin and organophosphates bind solely via weak van der Waals forces and dissociate within minutes.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Reversibilite yanılgısı: Penisilin ve organofosfatlar zayıf bağlarla değil, 50-150 kcal/mol enerjili kalıcı kovalent bağlarla bağlanır; dakikalar içinde ayrılmaları kimyasal olarak imkansızdır.\",\"ar\":\"مغالطة العكوسية: يرتبط البنسلين والسارين بروابط تساهمية دائمة (50-150 كيلو كالوري/مول) ومستحيلة الانفصال في دقائق.\",\"en\":\"Reversibility misconception: Penicillin and organophosphates form covalent bonds (50-150 kcal/mol); dissociating in minutes is chemically impossible.\"}},{\"id\":\"opt-7c\",\"text\":{\"tr\":\"Azotlu hardallar DNA'ya dokunmaz, sadece plazma albüminindeki serbest sülfatları kovalent olarak bağlar.\",\"ar\":\"لا يمس خردل النيتروجين مادة DNA إطلاقاً، بل يرتبط تساهمياً بكبريتات ألبومين البلازما الحرة فقط.\",\"en\":\"Nitrogen mustards never react with DNA, binding exclusively to free sulfates on circulating plasma albumin.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Hedef yanılgısı: Slayt 10: Azotlu hardalların sitotoksik kemoterapötik hedefi doğrudan hücre çekirdeğindeki DNA guanin N7 pozisyonudur; iki koluyla DNA çift zincirini çapraz bağlayarak replikasyonu durdurur.\",\"ar\":\"مغالطة الهدف البيولوجي: شريحة 10: الهدف السريري لخردل النيتروجين هو N7 في غوانين DNA لتشكيل روابط تصالبية توقف تكاثر الخلايا السرطانية.\",\"en\":\"Target misconception: Slide 10: The primary therapeutic target of nitrogen mustards is DNA guanine N7; bifunctional cross-linking blocks DNA replication in cancer cells.\"}}]},\"technicalTerms\":[{\"term\":\"açilasyon\",\"arContext\":\"تفاعل الأَصْيَلَة (Acylation)\"},{\"term\":\"alkilasyon\",\"arContext\":\"تفاعل الأَلْكَلَة (Alkylation)\"},{\"term\":\"fosforilasyon\",\"arContext\":\"تفاعل الفَسْفَرَة (Phosphorylation)\"}],\"hints\":[{\"tr\":\"Beta-laktam halkasının açılmasıyla oluşan reaksiyonu ve organofosfatın fosfat aktarımını hatırlayın.\",\"ar\":\"تذكر التفاعل الناتج عن فتح حلقة بيتا لاكتام ونقل مجموعة الفوسفات في المركبات الفوسفورية.\",\"en\":\"Recall the reaction triggered by beta-lactam ring opening and phosphate transfer by organophosphates.\"},{\"tr\":\"Slayt 10-12: Penisilin açilleme yapar, sarin fosforilleme yapar, azotlu hardal aziridinyum ile alkilleme yapar.\",\"ar\":\"شريحة 10-12: البنسلين يؤصل، والسارين يفسفر، وخردل النيتروجين يؤلكل عبر شاردة الأليريدينيوم.\",\"en\":\"Slides 10-12: Penicillin acylates, Sarin phosphorylates, and nitrogen mustard alkylates.\"},{\"tr\":\"Doğru eşleşme: Penisilin (açilasyon), Organofosfat (fosforilasyon), Azotlu hardal (alkilasyon).\",\"ar\":\"الترتيب الصحيح: بنسلين (أصيلة)، فوسفات عضوية (فسفرة)، خردل نيتروجين (ألكلة).\",\"en\":\"The correct sequence: Penicillin (acylation), Organophosphate (phosphorylation), Nitrogen mustard (alkylation).\"}],\"config\":{\"options\":[{\"id\":\"opt-7a\",\"text\":\"Penisilin transpeptidazı açiller (beta-laktam halka açılması); organofosfat AChE'yi fosforiller; azotlu hardal DNA guanin N7'sini alkiller (aziridinyum katyonu).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika bir sınav ustalığı! Slayt 10, 11 ve 12'nin tam mekanik özeti: 1) Penisilin 4 üyeli gergin laktam halkasıyla transpeptidaz aktif Serinini açiller (açilasyon), 2) Organofosfatlar AChE esteratik Serinini fosforiller (fosforilasyon), 3) Azotlu hardallar aziridinyum iyonu üzerinden DNA guanin N7 atomunu alkiller (çapraz alkilasyon). Üçü de kalıcı kovalent adükt oluşturur.\"},{\"id\":\"opt-7b\",\"text\":\"Penisilin ve organofosfatlar reseptörlerine sadece zayıf van der Waals bağlarıyla tutunur ve dakikalar içinde ayrılır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Reversibilite yanılgısı: Penisilin ve organofosfatlar zayıf bağlarla değil, 50-150 kcal/mol enerjili kalıcı kovalent bağlarla bağlanır; dakikalar içinde ayrılmaları kimyasal olarak imkansızdır.\"},{\"id\":\"opt-7c\",\"text\":\"Azotlu hardallar DNA'ya dokunmaz, sadece plazma albüminindeki serbest sülfatları kovalent olarak bağlar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Hedef yanılgısı: Slayt 10: Azotlu hardalların sitotoksik kemoterapötik hedefi doğrudan hücre çekirdeğindeki DNA guanin N7 pozisyonudur; iki koluyla DNA çift zincirini çapraz bağlayarak replikasyonu durdurur.\"}]},\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":10},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":11},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":12}]},{\"id\":\"pharm-mod1-les1-step-08\",\"stage\":\"concept_check\",\"stageIndex\":8,\"type\":\"concept_check\",\"title\":{\"tr\":\"Kavram Kontrolü: Hidrojen Bağının Yönlülüğü ve Geometrisi\",\"ar\":\"التحقق من المفهوم: اتجاهية الرابطة الهيدروجينية وهندستها الفراغية\",\"en\":\"Concept Check: Hydrogen Bond Directionality & Geometry\"},\"prompt\":{\"tr\":\"Hidrojen bağının reseptör stereoseçiciliğindeki kritik rolü nedir ve bağ ekseninden 30 derecelik açısal bir sapma bağ enerjisini nasıl etkiler?\",\"ar\":\"ما هو الدور الجوهري للرابطة الهيدروجينية في الانتقائية الفراغية للمستقبل، وكيف يؤثر انحراف الزاوية بمقدار 30 درجة عن الخط المستقيم على طاقة الرابطة؟\",\"en\":\"What is the crucial role of hydrogen bonding in receptor stereoselectivity, and how does a 30-degree deviation from the optimal linear axis affect bond energy?\"},\"conceptCheck\":{\"options\":[{\"id\":\"opt-8a\",\"text\":{\"tr\":\"Hidrojen bağı son derece yönlüdür (optimum 180° doğrusal açı); 30° sapma bağ enerjisini %50'den fazla düşürerek reseptör stereoseçiciliğini belirler.\",\"ar\":\"الرابطة الهيدروجينية شديدة الاتجاهية (الزاوية المثلى 180 درجة خطية)؛ وانحراف 30 درجة يقلل طاقتها بأكثر من 50% محدداً الانتقائية الفراغية.\",\"en\":\"Hydrogen bonds are highly directional (optimal at 180° linear geometry); a 30° deflection slashes bond energy by >50%, dictating stereoselectivity.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel biyofiziksel analiz! Slayt 16 ve 17: Hidrojen bağları iyonik bağlar gibi küresel (izotropik) değildir; son derece yönlüdür. Maksimum enerji donör-H-akseptör atomları 180° doğrusal eksende olduğunda elde edilir. 30° açısal kayma bağ enerjisini yarıdan fazla yok eder; enantiyomerler arasındaki devasa afinite farklarının ana nedeni bu açısal hassasiyettir.\",\"ar\":\"تحليل فيزيائي حيوي ممتاز! شريحة 16 و 17: الروابط الهيدروجينية شديدة الاتجاهية وليست كروية كالروابط الأيونية. الزاوية 180 درجة تعطي أقصى طاقة، وانحراف 30 درجة يفقده أكثر من نصف قوته مفسراً الفارق بين المصاوغات.\",\"en\":\"Brilliant biophysical analysis! Slides 16 & 17: Unlike isotropic ionic fields, hydrogen bonds are strictly directional (optimum 180° linear). A 30° tilt destroys >50% of binding energy, explaining stereoselective eudismic ratios.\"}},{\"id\":\"opt-8b\",\"text\":{\"tr\":\"Hidrojen bağı küresel bir buluttur; hangi açıyla yaklaşırsa yaklaşsın bağ enerjisi daima tamamen sabittir.\",\"ar\":\"الرابطة الهيدروجينية سحابة كروية متناظرة، وطاقتها ثابتة بالكامل مهما كانت زاوية الاقتراب.\",\"en\":\"Hydrogen bonding generates a spherical electrostatic cloud with invariant energy regardless of approach angle.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"İzotropik yanılgı: Slayt 16: İyonik bağlar küreseldir fakat hidrojen bağları orbital örtüşmesi ve kısmi kovalent karakter taşıdığı için doğrusal eksende (180°) olmak zorundadır.\",\"ar\":\"مغالطة الخصائص الكروية: شريحة 16: الروابط الأيونية كروية التناظر، أما الروابط الهيدروجينية فتحمل طابعاً مدارياً يتطلب خطاً مستقيماً 180 درجة.\",\"en\":\"Isotropic misconception: Slide 16: Pure ionic charges are spherical, but hydrogen bonds involve directional orbital overlap requiring near-linear 180° geometry.\"}},{\"id\":\"opt-8c\",\"text\":{\"tr\":\"Hidrojen bağları sadece 90° dik açıyla kurulabilir; 180° doğrusal açıda bağ kendiliğinden kopar.\",\"ar\":\"لا تتشكل الروابط الهيدروجينية إلا بزاوية قائمة 90 درجة، وتتفكك تلقائياً عند الزاوية المستقيمة 180 درجة.\",\"en\":\"Hydrogen bonds form exclusively at 90° right angles; a 180° linear alignment causes immediate repulsion.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Dik açı yanılgısı: 90° açıda donör ve akseptör atomların elektron bulutları birbirini iter; bağ enerjisi çöker. Optimum kararlılık doğrusal 180° eksendedir.\",\"ar\":\"مغالطة الزاوية القائمة: عند 90 درجة يحدث تنافر إلكتروني وتنهار الطاقة؛ الاستقرار الأعظمي يكون حصراً على الخط المستقيم 180 درجة.\",\"en\":\"Right angle fallacy: At 90° heavy atom electron clouds clash sterically; optimal thermodynamic stability strictly requires collinear 180° alignment.\"}}]},\"technicalTerms\":[{\"term\":\"yönlülük (directionality)\",\"arContext\":\"الاتجاهية الهندسية (Directionality)\"},{\"term\":\"stereoseçicilik\",\"arContext\":\"الانتقائية الفراغية\"}],\"hints\":[{\"tr\":\"Donör, Hidrojen ve Akseptör atomlarının uzaydaki diziliş geometrisini düşünün.\",\"ar\":\"فكر في هندسة اصطفاف ذرات المانح والهيدروجين والمستقبل في الفراغ.\",\"en\":\"Consider the spatial alignment of Donor, Hydrogen, and Acceptor atoms.\"},{\"tr\":\"Slayt 16: En güçlü hidrojen bağı doğrusal (180 derece) eksende elde edilir.\",\"ar\":\"شريحة 16: تتحقق أقصى طاقة للرابطة الهيدروجينية على المحور الخطي 180 درجة.\",\"en\":\"Slide 16: Maximum hydrogen bonding energy requires collinear 180° orientation.\"},{\"tr\":\"Hidrojen bağı yönlüdür; 30 derecelik açısal kayma bağ enerjisini %50'den fazla düşürür.\",\"ar\":\"الرابطة الهيدروجينية موجهة؛ انحراف 30 درجة يقلل الطاقة بأكثر من 50%.\",\"en\":\"Hydrogen bonds are directional; a 30° deviation cuts bond strength by over 50%.\"}],\"config\":{\"options\":[{\"id\":\"opt-8a\",\"text\":\"Hidrojen bağı son derece yönlüdür (optimum 180° doğrusal açı); 30° sapma bağ enerjisini %50'den fazla düşürerek reseptör stereoseçiciliğini belirler.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel biyofiziksel analiz! Slayt 16 ve 17: Hidrojen bağları iyonik bağlar gibi küresel (izotropik) değildir; son derece yönlüdür. Maksimum enerji donör-H-akseptör atomları 180° doğrusal eksende olduğunda elde edilir. 30° açısal kayma bağ enerjisini yarıdan fazla yok eder; enantiyomerler arasındaki devasa afinite farklarının ana nedeni bu açısal hassasiyettir.\"},{\"id\":\"opt-8b\",\"text\":\"Hidrojen bağı küresel bir buluttur; hangi açıyla yaklaşırsa yaklaşsın bağ enerjisi daima tamamen sabittir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"İzotropik yanılgı: Slayt 16: İyonik bağlar küreseldir fakat hidrojen bağları orbital örtüşmesi ve kısmi kovalent karakter taşıdığı için doğrusal eksende (180°) olmak zorundadır.\"},{\"id\":\"opt-8c\",\"text\":\"Hidrojen bağları sadece 90° dik açıyla kurulabilir; 180° doğrusal açıda bağ kendiliğinden kopar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Dik açı yanılgısı: 90° açıda donör ve akseptör atomların elektron bulutları birbirini iter; bağ enerjisi çöker. Optimum kararlılık doğrusal 180° eksendedir.\"}]},\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":15}]},{\"id\":\"pharm-mod1-les1-step-09\",\"stage\":\"application\",\"stageIndex\":9,\"type\":\"clinical_vignette\",\"title\":{\"tr\":\"Klinik Vaka: Ağır Metal Zehirlenmesi ve Şelasyon Tedavisi\",\"ar\":\"حالة سريرية: التسمم بالمعادن الثقيلة والعلاج بالخلب\",\"en\":\"Clinical Vignette: Heavy Metal Toxicity & Chelation Therapy\"},\"prompt\":{\"tr\":\"Kurşun zehirlenmesinde EDTA, arsenik ve cıva zehirlenmesinde ise BAL (Dimerkaprol) kullanılır. Neden serbest EDTA yerine kalsiyum disodyum tuzu infüze edilir?\",\"ar\":\"يستخدم EDTA لتسمم الرصاص و BAL لتسمم الزرنيخ والزئبق. لماذا يُحقن EDTA كملح كالسيوم ثنائي الصوديوم بدلاً من الحمض الحر؟\",\"en\":\"EDTA treats lead poisoning, while BAL treats arsenic and mercury. Why must EDTA be infused as a calcium disodium salt rather than free EDTA?\"},\"conceptCheck\":{\"options\":[{\"id\":\"opt-9a\",\"text\":{\"tr\":\"Serbest EDTA kanda fizyolojik Ca2+'yi de çok güçlü şelatlar ve ölümcül hipokalsemik tetani yapar; CaNa2-EDTA kalsiyumunu kurşunla (Pb2+) yer değiştirerek verir.\",\"ar\":\"يخلب EDTA الحر كالسيوم الدم الفسيولوجي بقوة مسبباً كزاز نقص الكالسيوم القاتل، بينما يستبدل CaNa2-EDTA كالسيومه بالرصاص بأمان.\",\"en\":\"Free EDTA chelates endogenous Ca2+ triggering fatal hypocalcemic tetany; CaNa2-EDTA exchanges bound calcium for higher-affinity lead (Pb2+).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel bir klinik farmakoloji dersi! Slayt 32: EDTA heksadentat (6 dişli: 2 azot + 4 karboksilat) bir moleküldür ve Ca2+ iyonuna yüksek afinite gösterir. Serbest EDTA verilirse kandaki iyonize kalsiyumu sıfırlayarak dakikalar içinde kardiyak arrest ve tetaniye yol açar. CaNa2-EDTA tuzu verildiğinde ise kurşun (Pb2+) kalsiyumdan daha yüksek stabilite sabitine sahip olduğu için Ca ile yer değiştirir ve kurşun idrarla atılır.\",\"ar\":\"درس سريري بالغ الأهمية! شريحة 32: يمتلك EDTA بنية سداسية السن تأسر الكالسيوم بشدة. حقن الحمض الحر يسبب توقف القلب والكزاز بنقص الكالسيوم. لذا يعطى ملح الكالسيوم ليستبدله بالرصاص الأعلى ألفة ويطرحه كلوياً.\",\"en\":\"Critical clinical pharmacology lesson! Slide 32: Hexadentate EDTA (2 nitrogens + 4 carboxylates) binds Ca2+ avidly. Free EDTA causes lethal hypocalcemic tetany. CaNa2-EDTA safely transchelates: lead (Pb2+) displaces calcium due to a higher stability constant.\"}},{\"id\":\"opt-9b\",\"text\":{\"tr\":\"EDTA gastrointestinal kanalda bir reçine gibi davranıp metalleri çöktürür; kana geçmeden feçesle atılmalarını sağlar.\",\"ar\":\"يعمل EDTA في الجهاز الهضمي كراتنج يرسب المعادن لطرحها في البراز دون امتصاص إلى مجرى الدم.\",\"en\":\"EDTA acts strictly as a non-absorbable gastrointestinal exchange resin, precipitating ingested heavy metals for fecal elimination.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"İntestinal sekestrasyon yanılgısı: EDTA parenteral yolla (IV) kanda dolaşıma verilir; sistemik dokulardaki kurşun ve ağır metalleri heksadentat koordinasyon kompleksiyle sarıp idrarla atar.\",\"ar\":\"مغالطة الحصر المعوي: يُحقن EDTA وريدياً ليدور في الدم؛ فيشلب الرصاص والمعادن في النسج العميقة عبر معقدات سداسية الإحاطة لتطرح كلوياً.\",\"en\":\"Intestinal sequestration misconception: EDTA is administered intravenously to chelate systemic tissue and plasma lead into soluble hexadentate complexes for renal excretion.\"}},{\"id\":\"opt-9c\",\"text\":{\"tr\":\"Serbest EDTA kanda tamamen protonlanmış (nötr) haldedir; bu nedenle divalent katyonlarla kompleks kuramaz ve etkisiz kalır.\",\"ar\":\"يكون EDTA الحر مبرتناً بالكامل (متعادلاً) في الدم، مما يمنعه تماماً من تشكيل معقدات مع الكاتيونات ثنائية التكافؤ.\",\"en\":\"Free EDTA is fully protonated and neutral at pH 7.4, making it electronically incapable of coordinating divalent blood cations.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Protonlanma yanılgısı: Fizyolojik pH 7.4'te EDTA'nın karboksilat grupları iyonizedir (-COO-); serbest EDTA verildiğinde kandaki Ca2+ iyonlarını derhal şelatlar ve ölümcül hipokalsemik tetani tetikler.\",\"ar\":\"مغالطة البرتنة: عند باهاء الدم 7.4 تكون كربوكسيلات EDTA متأينة بشحنة سالبة، فتشلب فوراً Ca2+ مسببة كزازاً نقص كلسياً قاتلاً.\",\"en\":\"Protonation fallacy: At physiologic pH 7.4, EDTA carboxylates are largely ionized and chelate ambient Ca2+ with extreme avidity, inducing fatal hypocalcemic tetany.\"}}]},\"technicalTerms\":[{\"term\":\"şelasyon (chelation)\",\"arContext\":\"الخَلْب المعدني (Chelation)\"},{\"term\":\"heksadentat ligand\",\"arContext\":\"ربيطة سداسية السن (Hexadentate ligand)\"}],\"hints\":[{\"tr\":\"EDTA'nın kan tüplerinde pıhtılaşmayı önlemek için hangi iyonu bağladığını hatırlayın.\",\"ar\":\"تذكر الشاردة التي يخلبها EDTA في أنابيب الدم لمنع التخثر.\",\"en\":\"Recall which physiological ion EDTA binds in laboratory tubes to prevent clotting.\"},{\"tr\":\"Serbest EDTA kalsiyumu bağlarsa kanda serbest Ca2+ seviyesine ve kas spazmına ne olur?\",\"ar\":\"إذا خلب EDTA الحر كالسيوم المصل، ماذا يحدث لمستوى الكالسيوم والتشنج العضلي؟\",\"en\":\"What happens to serum ionized calcium and muscular excitability if free EDTA is infused?\"},{\"tr\":\"Serbest EDTA hipokalsemik tetani yapar; bu yüzden kalsiyum disodyum tuzu (CaNa2-EDTA) kullanılır.\",\"ar\":\"يسبب EDTA الحر كزاز نقص الكالسيوم؛ لذلك يُعطى ملح الكالسيوم ثنائي الصوديوم.\",\"en\":\"Free EDTA causes hypocalcemic tetany; hence calcium disodium EDTA is administered.\"}],\"config\":{\"options\":[{\"id\":\"opt-9a\",\"text\":\"Serbest EDTA kanda fizyolojik Ca2+'yi de çok güçlü şelatlar ve ölümcül hipokalsemik tetani yapar; CaNa2-EDTA kalsiyumunu kurşunla (Pb2+) yer değiştirerek verir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel bir klinik farmakoloji dersi! Slayt 32: EDTA heksadentat (6 dişli: 2 azot + 4 karboksilat) bir moleküldür ve Ca2+ iyonuna yüksek afinite gösterir. Serbest EDTA verilirse kandaki iyonize kalsiyumu sıfırlayarak dakikalar içinde kardiyak arrest ve tetaniye yol açar. CaNa2-EDTA tuzu verildiğinde ise kurşun (Pb2+) kalsiyumdan daha yüksek stabilite sabitine sahip olduğu için Ca ile yer değiştirir ve kurşun idrarla atılır.\"},{\"id\":\"opt-9b\",\"text\":\"EDTA gastrointestinal kanalda bir reçine gibi davranıp metalleri çöktürür; kana geçmeden feçesle atılmalarını sağlar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"İntestinal sekestrasyon yanılgısı: EDTA parenteral yolla (IV) kanda dolaşıma verilir; sistemik dokulardaki kurşun ve ağır metalleri heksadentat koordinasyon kompleksiyle sarıp idrarla atar.\"},{\"id\":\"opt-9c\",\"text\":\"Serbest EDTA kanda tamamen protonlanmış (nötr) haldedir; bu nedenle divalent katyonlarla kompleks kuramaz ve etkisiz kalır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Protonlanma yanılgısı: Fizyolojik pH 7.4'te EDTA'nın karboksilat grupları iyonizedir (-COO-); serbest EDTA verildiğinde kandaki Ca2+ iyonlarını derhal şelatlar ve ölümcül hipokalsemik tetani tetikler.\"}]},\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":32}]},{\"id\":\"pharm-mod1-les1-step-10\",\"stage\":\"retrieval\",\"stageIndex\":10,\"type\":\"retrieval\",\"title\":{\"tr\":\"Geri Çağırma: İlaçların 4 Makromoleküler Hedef Sınıfı\",\"ar\":\"الاسترجاع: الفئات الأربع الرئيسية للأهداف الجزيئية للأدوية\",\"en\":\"Retrieval: The 4 Macromolecular Drug Target Classes\"},\"prompt\":{\"tr\":\"Farmakolojide ilaçların etki gösterdiği 4 temel makromoleküler hedef sınıfı hangileridir?\",\"ar\":\"ما هي الفئات الأربع الرئيسية للأهداف الجزيئية الحيوية التي ترتبط بها الأدوية وتحدث تأثيراتها الدوائية؟\",\"en\":\"What are the four primary macromolecular biological target classes through which drugs exert their pharmacological effects?\"},\"conceptCheck\":{\"options\":[{\"id\":\"opt-10a\",\"text\":{\"tr\":\"Reseptörler, Enzimler, İyon Kanalları ve Taşıyıcı Moleküller (Transporterlar / Pompalar).\",\"ar\":\"المستقبلات، والإنزيمات، والقنوات الأيونية، والناقلات الجزيئية (المضخات النقلية).\",\"en\":\"Receptors, Enzymes, Ion Channels, and Transporter Carrier Proteins.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz hafıza! Slayt 3'ün temel 4'lüsü: 1) Reseptörler (hücre yüzeyi ve nükleer), 2) Enzimler (inhibitör veya intihar substratları), 3) İyon Kanalları (bloker veya açıcılar), 4) Taşıyıcılar (SERT, DAT, SGLT-2 gibi geri alım pompaları). İlaçların %95'i bu 4 protein ailesini hedefler.\",\"ar\":\"استرجاع مثالي! شريحة 3: 1) المستقبِلات، 2) الإنزيمات، 3) القنوات الأيونية، 4) النواقل الخلوية مثل ناقلات السيروتونين SGLT-2. 95% من الأدوية تستهدف هذه الفئات الأربع.\",\"en\":\"Perfect recall! Slide 3 target tetrad: 1) Receptors, 2) Enzymes, 3) Ion channels, and 4) Transporter carriers (SERT, NET, SGLT-2). Over 95% of pharmacotherapy targets these four proteins.\"}},{\"id\":\"opt-10b\",\"text\":{\"tr\":\"İlaçların tek makromoleküler hedefi hücre çekirdeğindeki ribozomlardır; enzim ve kanallara ilaç bağlanamaz.\",\"ar\":\"الهدف الجزيئي الوحيد للأدوية هو ريبوسومات النواة؛ ولا يمكن للأدوية الارتباط بالإنزيمات والقنوات.\",\"en\":\"The sole macromolecular targets are nuclear ribosomes; drugs cannot bind enzymes or ion channels.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Tek hedef yanılgısı: Ribozomlar bazı antibiyotiklerin hedefidir ancak insan farmakolojisinde ana hedefler membran reseptörleri, metabolik enzimler ve iyon kanallarıdır.\",\"ar\":\"مغالطة حصر الهدف: الريبوسومات هدف لبعض الصادات، لكن الأهداف البشرية الرئيسية هي مستقبِلات الأغشية والإنزيمات والقنوات.\",\"en\":\"Single target fallacy: While ribosomes are targeted by bacterial antibiotics, human pharmacology is dominated by membrane receptors, metabolic enzymes, and ion channels.\"}},{\"id\":\"opt-10c\",\"text\":{\"tr\":\"İlaçlar sadece membran lipit çift katmanında pasif olarak çözünür; spesifik protein makromoleküllerini hedeflemezler.\",\"ar\":\"تنحل الأدوية فقط بشكل غير فعال في طبقة الفوسفوليبيد الثنائية للغشاء دون استهداف جزيئات بروتينية نوعية.\",\"en\":\"Drugs exert effects solely by non-specifically partitioning into the membrane lipid bilayer without interacting with protein targets.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Lipit çözünme yanılgısı: Bazı genel anestezikler membran lipitlerini etkilese de, modern farmakolojide ilaçların %95'i spesifik 4 protein hedefini (reseptörler, enzimler, kanallar, taşıyıcılar) stereoseçici olarak bağlar.\",\"ar\":\"مغالطة الانحلال الدهني: تستهدف 95% من الأدوية 4 فئات بروتينية نوعية (مستقبلات، إنزيمات، قنوات، نواقل) عبر تطابق بنيوي فراغي دقيق.\",\"en\":\"Lipid partitioning misconception: While general anesthetics perturb membranes, 95% of therapeutic drugs stereoselectively engage specific protein targets.\"}}]},\"technicalTerms\":[{\"term\":\"makromoleküler hedef\",\"arContext\":\"الهدف الجزيئي الحيوي\"},{\"term\":\"taşıyıcı molekül (transporter)\",\"arContext\":\"الناقل البروتيني (Transporter)\"}],\"hints\":[{\"tr\":\"Hücre zarındaki sinyal alıcılarını, metabolik katalizörleri ve gözenekli geçitleri düşünün.\",\"ar\":\"فكر في لاقطات الإشارة الغشائية، والمحفزات الاستقلابية، وبوابات العبور الأيونية.\",\"en\":\"Think of membrane signal receivers, catalytic converters, and gated ion conduits.\"},{\"tr\":\"Slayt 3: Reseptörler, Enzimler, İyon Kanalları ve Taşıyıcılar.\",\"ar\":\"شريحة 3: المستقبِلات، الإنزيمات، القنوات الأيونية، والنواقل.\",\"en\":\"Slide 3: Receptors, Enzymes, Ion Channels, and Transporters.\"},{\"tr\":\"Dört sınıf: Reseptörler, Enzimler, İyon Kanalları, Taşıyıcı Transporterlar.\",\"ar\":\"الفئات الأربع: مستقبِلات، إنزيمات، قنوات أيونية، نواقل خلوية.\",\"en\":\"The four classes: Receptors, Enzymes, Ion Channels, and Transporters.\"}],\"config\":{\"options\":[{\"id\":\"opt-10a\",\"text\":\"Reseptörler, Enzimler, İyon Kanalları ve Taşıyıcı Moleküller (Transporterlar / Pompalar).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz hafıza! Slayt 3'ün temel 4'lüsü: 1) Reseptörler (hücre yüzeyi ve nükleer), 2) Enzimler (inhibitör veya intihar substratları), 3) İyon Kanalları (bloker veya açıcılar), 4) Taşıyıcılar (SERT, DAT, SGLT-2 gibi geri alım pompaları). İlaçların %95'i bu 4 protein ailesini hedefler.\"},{\"id\":\"opt-10b\",\"text\":\"İlaçların tek makromoleküler hedefi hücre çekirdeğindeki ribozomlardır; enzim ve kanallara ilaç bağlanamaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Tek hedef yanılgısı: Ribozomlar bazı antibiyotiklerin hedefidir ancak insan farmakolojisinde ana hedefler membran reseptörleri, metabolik enzimler ve iyon kanallarıdır.\"},{\"id\":\"opt-10c\",\"text\":\"İlaçlar sadece membran lipit çift katmanında pasif olarak çözünür; spesifik protein makromoleküllerini hedeflemezler.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Lipit çözünme yanılgısı: Bazı genel anestezikler membran lipitlerini etkilese de, modern farmakolojide ilaçların %95'i spesifik 4 protein hedefini (reseptörler, enzimler, kanallar, taşıyıcılar) stereoseçici olarak bağlar.\"}]},\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":5}]},{\"id\":\"pharm-mod1-les1-step-11\",\"stage\":\"connection\",\"stageIndex\":11,\"type\":\"connection\",\"title\":{\"tr\":\"Bağlantı: Coulomb İyonik Yönlendirmesi ve van der Waals Kilitlenmesi\",\"ar\":\"الربط: التوجيه الأيوني وفق كولوم والإقفال بقوى فان دير فالس\",\"en\":\"Connection: Coulombic Ionic Steering & van der Waals Docking\"},\"prompt\":{\"tr\":\"İlacın reseptör cebine yaklaşmasında uzun menzilli Coulomb iyonik kuvveti (1/r²) ile kısa menzilli van der Waals kuvvetleri (1/r⁶) arasında nasıl bir iş bölümü vardır?\",\"ar\":\"كيف تتكامل قوى كولوم الأيونية بعيدة المدى (1/r²) مع قوى فان دير فالس قصيرة المدى (1/r⁶) أثناء توجيه الدواء واستقراره في جيب المستقبل؟\",\"en\":\"How do long-range Coulombic ionic forces (1/r²) cooperate with short-range van der Waals forces (1/r⁶) during ligand steering and docking into the receptor cavity?\"},\"conceptCheck\":{\"options\":[{\"id\":\"opt-11a\",\"text\":{\"tr\":\"İyonik kuvvet en uzun menzillidir (1/r²); ilacı uzaktan algılayıp cebe yönlendirir (ionic steering), yakına gelince van der Waals (1/r⁶) ve H-bağları kilitlenmeyi tamamlar.\",\"ar\":\"القوة الأيونية هي الأطول مدى (1/r²) فتوجه الدواء نحو الجيب، وحين الاقتراب تتدخل قوى فان دير فالس (1/r⁶) والروابط الهيدروجينية لإتمام الإقفال.\",\"en\":\"Ionic attraction is longest-range (1/r²), guiding the ligand from afar (ionic steering); at close contact, van der Waals (1/r⁶) and H-bonds lock the complex.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel biyofiziksel entegrasyon! Slayt 14 ve 24: İyonik bağın menzili 1/r² ile azalır; bu sayede mikroskobik ölçekte en uzun menzilli çekimdir. İlaç bağlanma cebine yönlendirilirken iyonik tuz köprüsü ilacı doğru oryantasyonda çeker. İlaç temas mesafesine (van der Waals yarıçapı) ulaştığında ise 1/r⁶ ile mesafeye aşırı duyarlı van der Waals ve hidrofobik kuvvetler devreye girerek kenetlenmeyi tamamlar.\",\"ar\":\"تكامل فيزيائي بديع! شريحة 14 و 24: تتناقص القوة الأيونية مع 1/r² وهي الأطول مدى لجذب الدواء وتوجيهه نحو الجيب. وعند التماس التام تتدخل قوى فان دير فالس الحساسة لـ 1/r⁶ لإحكام الارتباط.\",\"en\":\"Brilliant biophysical synthesis! Slides 14 & 24: Ionic force scales with 1/r², acting as a long-range beacon. Once the drug enters the cavity, contact-dependent van der Waals forces (1/r⁶) snap the ligand into place.\"}},{\"id\":\"opt-11b\",\"text\":{\"tr\":\"Van der Waals kuvvetleri mesafeden bağımsızdır ve ilacı uzaktan çeker; iyonik bağ ise ancak atomlar birbirine doğrudan temas edince doğar.\",\"ar\":\"قوى فان دير فالس مستقلة عن المسافة وتجذب الدواء من بعيد؛ بينما لا تنشأ الرابطة الأيونية إلا عند التماس المباشر.\",\"en\":\"Van der Waals forces act over long distances to steer the ligand; ionic forces only arise upon direct van der Waals surface contact.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Menzil bağımlılığı yanılgısı: Tam tersi! İyonik Coulomb kuvvetleri 1/r² ile azalarak uzun menzilde yönlendirme (steering) yapar; van der Waals ise 1/r⁶ ile mesafeye aşırı duyarlıdır ve sadece atomlar birbirine dokunma mesafesine (3-4 Å) geldiğinde devreye girer.\",\"ar\":\"مغالطة التبعية للمسافة: العكس تماماً! قوى كولوم الأيونية تتناسب مع 1/r² لتوجه الدواء من مسافة بعيدة؛ بينما تتطلب فان دير فالس تماساً وثيقاً (1/r⁶).\",\"en\":\"Inverted distance dependence fallacy: Coulombic ionic fields scale as 1/r2 to steer ligands from afar; van der Waals forces scale sharply as 1/r6, operating only at close contact.\"}},{\"id\":\"opt-11c\",\"text\":{\"tr\":\"İyonik kuvvetler ilacı reseptörden uzaklaştırır; bağlanmayı sadece apolar hidrokarbonlar başlatır.\",\"ar\":\"تدفع القوى الأيونية الدواء بعيداً عن المستقبل؛ والارتباط يبدأ حصراً بالهيدروكربونات اللابولارية.\",\"en\":\"Ionic forces act as an electrostatic repulsor; initial binding is initiated exclusively by nonpolar carbons.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"İtme yanılgısı: Pozitif yüklü ilaç amino grubu ile negatif yüklü aspartat/glutamat karboksilatı arasında güçlü çekim kuvveti vardır; elektrostatik itme ancak aynı yükler arasında olur.\",\"ar\":\"مغالطة التنافر: التجاذب بين الأمين الموجب وكربوكسيلات الأسبارتات السالب قوي وموجه، والتنافر لا يحدث إلا بين الشحنات المتماثلة.\",\"en\":\"Repulsion fallacy: Oppositely charged groups (cationic amine and anionic aspartate) attract each other strongly; electrostatic repulsion occurs only between identical charges.\"}}]},\"technicalTerms\":[{\"term\":\"iyonik yönlendirme (ionic steering)\",\"arContext\":\"التوجيه الأيوني (Ionic steering)\"},{\"term\":\"van der Waals yarıçapı\",\"arContext\":\"نصف قطر فان دير فالس\"}],\"hints\":[{\"tr\":\"Mesafe bağımlılıklarını karşılaştırın: 1/r² (uzun menzil) vs 1/r⁶ (kısa temas menzili).\",\"ar\":\"قارن بين التبعية للمسافة: 1/r² (بعيدة المدى) في مقابل 1/r⁶ (قصيرة المدى عند التماس).\",\"en\":\"Compare distance dependencies: 1/r² (long-range) versus 1/r⁶ (short-range contact).\"},{\"tr\":\"İlacı cebe ilk çeken kuvvet ile cebe oturduğunda yapışmayı sağlayan kuvveti düşünün.\",\"ar\":\"فكر في القوة التي تجذب الدواء أولاً نحو الجيب، وتلك التي تحكم تثبيته عند الاستقرار فيه.\",\"en\":\"Think of the force that guides the drug towards the entrance versus the forces that cement docking.\"},{\"tr\":\"İyonik kuvvetler uzun menzilli yönlendiricidir; van der Waals ise temas mesafesinde kenetler.\",\"ar\":\"القوة الأيونية موجه بعيد المدى، بينما تؤمن قوى فان دير فالس التثبيت التماسي المحكم.\",\"en\":\"Ionic forces guide from afar (steering); van der Waals and hydrophobic forces lock at atomic contact.\"}],\"config\":{\"options\":[{\"id\":\"opt-11a\",\"text\":\"İyonik kuvvet en uzun menzillidir (1/r²); ilacı uzaktan algılayıp cebe yönlendirir (ionic steering), yakına gelince van der Waals (1/r⁶) ve H-bağları kilitlenmeyi tamamlar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel biyofiziksel entegrasyon! Slayt 14 ve 24: İyonik bağın menzili 1/r² ile azalır; bu sayede mikroskobik ölçekte en uzun menzilli çekimdir. İlaç bağlanma cebine yönlendirilirken iyonik tuz köprüsü ilacı doğru oryantasyonda çeker. İlaç temas mesafesine (van der Waals yarıçapı) ulaştığında ise 1/r⁶ ile mesafeye aşırı duyarlı van der Waals ve hidrofobik kuvvetler devreye girerek kenetlenmeyi tamamlar.\"},{\"id\":\"opt-11b\",\"text\":\"Van der Waals kuvvetleri mesafeden bağımsızdır ve ilacı uzaktan çeker; iyonik bağ ise ancak atomlar birbirine doğrudan temas edince doğar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Menzil bağımlılığı yanılgısı: Tam tersi! İyonik Coulomb kuvvetleri 1/r² ile azalarak uzun menzilde yönlendirme (steering) yapar; van der Waals ise 1/r⁶ ile mesafeye aşırı duyarlıdır ve sadece atomlar birbirine dokunma mesafesine (3-4 Å) geldiğinde devreye girer.\"},{\"id\":\"opt-11c\",\"text\":\"İyonik kuvvetler ilacı reseptörden uzaklaştırır; bağlanmayı sadece apolar hidrokarbonlar başlatır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"İtme yanılgısı: Pozitif yüklü ilaç amino grubu ile negatif yüklü aspartat/glutamat karboksilatı arasında güçlü çekim kuvveti vardır; elektrostatik itme ancak aynı yükler arasında olur.\"}]},\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":14},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":24},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":25}]},{\"id\":\"pharm-mod1-les1-step-12\",\"stage\":\"mastery_check\",\"stageIndex\":12,\"type\":\"mastery_check\",\"title\":{\"tr\":\"Ustalık Sınavı: Yeni Kinaz İnhibitörü 'Mol-X' Transfer Analizi\",\"ar\":\"اختبار الإتقان: التحليل الانتقالي لمثبط الكينيز الجديد Mol-X\",\"en\":\"Mastery Check: Unseen Kinase Inhibitor 'Mol-X' Transfer Problem\"},\"prompt\":{\"tr\":\"Yeni bir tirozin kinaz inhibitörü Mol-X; 1 iyonik tuz köprüsü, 2 hidrojen bağı ve 3 hidrofobik temasla bağlanıyor. İlacın bağlanma stabilitesi ve tersinirliği hakkında ne söylenebilir?\",\"ar\":\"يرتبط مثبط التيروزين كينيز الجديد Mol-X بجسر ملحي أيوني واحد، ورابطتين هيدروجينيتين، و 3 تماسات كارهة للماء. ماذا نستنتج حول ثبات الارتباط وعكوسيته؟\",\"en\":\"A novel kinase inhibitor Mol-X forms 1 ionic salt bridge, 2 hydrogen bonds, and 3 hydrophobic contacts in its active pocket. What can be deduced about its affinity and reversibility?\"},\"conceptCheck\":{\"options\":[{\"id\":\"opt-12a\",\"text\":{\"tr\":\"Toplam bağlanma serbest enerjisi ~ -19 kcal/mol ile sub-nanomolar afinite sağlar; ancak kovalent bağ içermediğinden etki reversibildir ve kandan temizlenince sona erer.\",\"ar\":\"توفر طاقة الارتباط التراكمية ~ -19 كيلو كالوري/مول ألفة تحت نانومولية عالية؛ ونظراً لغياب الروابط التساهمية فإن التأثير عكوس تماماً ويزول بزوال الدواء.\",\"en\":\"Combined free energy (~ -19 kcal/mol) confers sub-nanomolar affinity; lacking covalent bonds, inhibition remains completely reversible upon drug clearance.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz farmakolojik sentez ve ustalık! Enerji hesabı: 1 iyonik bağ (~ -8 kcal/mol) + 2 hidrojen bağı (2 x -4 = -8 kcal/mol) + 3 hidrofobik temas (3 x -1 = -3 kcal/mol) = Toplam Delta G° yaklaşık -19 kcal/mol! Bu muazzam enerji Kd = 10^-10 M (sub-nanomolar) seviyesinde sıkı bir bağlanma sağlar. Ancak hiçbir kovalent bağ (50-150 kcal/mol) bulunmadığından ilaç kalıcı adükt oluşturmaz; plazma konsantrasyonu düşünce koff ayrışma hızıyla reseptörden ayrılarak hedef kinazın aktivitesini yeniden serbest bırakır!\",\"ar\":\"قمة الإتقان والتركيب العلمي! الحساب: 1 أيوني (-8) + 2 هيدروجيني (-8) + 3 كاره للماء (-3) = المجموع ~ -19 كيلو كالوري/مول! يمنح هذا ألفة نانومولية فائقة (Kd = 10^-10 M)، ولكن لغياب الروابط التساهمية، ينفصل الدواء بحركية عكوسة بمجرد انخفاض تركيزه البلازمي.\",\"en\":\"Masterful pharmacological synthesis! Energetic summation: 1 ionic (-8 kcal/mol) + 2 H-bonds (-8 kcal/mol) + 3 hydrophobic contacts (-3 kcal/mol) = Delta G° ~ -19 kcal/mol! This confers sub-nanomolar affinity (Kd ~ 0.1 nM) while maintaining complete reversibility without irreversible covalent adduction.\"}},{\"id\":\"opt-12b\",\"text\":{\"tr\":\"Toplam enerji 150 kcal/mol'ü aştığı için molekül hedef kinazı kalıcı olarak eritip geri dönüşsüz felç yapar.\",\"ar\":\"بما أن مجموع الطاقات يتجاوز 150 كيلو كالوري/مول، فإن الجزيء يذيب الكينيز بشكل دائم ويحدث شللاً غير عكوس.\",\"en\":\"Because summed energies exceed 150 kcal/mol, the molecule permanently melts the kinase, causing irreversible inactivation.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kovalent aşım yanılgısı: Non-kovalent bağların enerjileri toplandığında asla bir kovalent bağın enerjisine (50-150 kcal/mol) ulaşamaz; -19 kcal/mol çok güçlü bir non-kovalent afinite seviyesidir fakat kovalent kalıcılık yaratamaz.\",\"ar\":\"مغالطة التخطي التساهمي: طاقات الروابط غير التساهمية لا تصل إطلاقاً إلى طاقة الرابط التساهمي (50-150 كيلو كالوري/مول)، وقيمة -19 تعني ألفة عكوسة وليست شللاً تساهمياً.\",\"en\":\"Covalent threshold fallacy: Summed non-covalent forces rarely exceed -20 to -25 kcal/mol; they never reach covalent single-bond strength (50-150 kcal/mol) and remain reversible.\"}},{\"id\":\"opt-12c\",\"text\":{\"tr\":\"Non-kovalent bağların enerjisi asla toplanamaz; molekülün net bağlanma enerjisi en zayıf bağ olan van der Waals'e (-1 kcal/mol) eşittir.\",\"ar\":\"لا يمكن جمع طاقات الروابط غير التساهمية إطلاقاً، وتقتصر طاقة الارتباط الصافية على أضعف رابطة (-1 كيلو كالوري/مول).\",\"en\":\"Non-covalent bond energies can never be summed; target binding is constrained to the weakest single contact (-1 kcal/mol).\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Minimallik yanılgısı: Termodinamikte serbest enerjiler durum fonksiyonudur ve cebirsel olarak toplanır (Delta G_toplam = Delta G1 + Delta G2...); molekülün reseptöre toplam tutunma gücü tüm temas noktalarının bileşkesidir.\",\"ar\":\"مغالطة أدنى طاقة: في الديناميكا الحرارية، الطاقة الحرة دالة حالة تجمع جبرياً (Delta G = G1 + G2)، وقوة التماسك هي محصلة كافة نقاط التماس مجتمعة.\",\"en\":\"Minimality fallacy: Free energy is a thermodynamic state function that sums algebraically (Delta G_total = Delta G1 + Delta G2...); collective affinity reflects all simultaneous contacts.\"}}]},\"technicalTerms\":[{\"term\":\"tirozin kinaz inhibitörü\",\"arContext\":\"مثبط التيروزين كينيز\"},{\"term\":\"termodinamik serbest enerji\",\"arContext\":\"طاقة غيبس الحرة الديناميكية\"}],\"hints\":[{\"tr\":\"İyonik (~ -8), H-bağı (2 x -4 = -8) ve hidrofobik (3 x -1 = -3) enerjilerini toplayın.\",\"ar\":\"اجمع طاقات الروابط: أيونية (-8) + هيدروجينية (-8) + كارهة للماء (-3).\",\"en\":\"Sum the interaction energies: ionic (~ -8), H-bonds (2 x -4 = -8), and hydrophobic (3 x -1 = -3).\"},{\"tr\":\"Toplam enerji ~ -19 kcal/mol eder. Yapıda kovalent bağ var mı?\",\"ar\":\"المجموع يقارب -19 كيلو كالوري/مول. هل توجد رابطة تساهمية في البنية؟\",\"en\":\"Total energy equals ~ -19 kcal/mol. Is any covalent alkylating/acylating warhead present?\"},{\"tr\":\"Kovalent bağ olmadığı için etki sub-nanomolar afiniteye rağmen tamamen geri dönüşümlüdür.\",\"ar\":\"لغياب الروابط التساهمية، فإن التثبيط عكوس تماماً رغم الألفة العالية تحت النانومولية.\",\"en\":\"Lacking a covalent warhead, inhibition remains sub-nanomolar yet completely reversible.\"}],\"config\":{\"options\":[{\"id\":\"opt-12a\",\"text\":\"Toplam bağlanma serbest enerjisi ~ -19 kcal/mol ile sub-nanomolar afinite sağlar; ancak kovalent bağ içermediğinden etki reversibildir ve kandan temizlenince sona erer.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz farmakolojik sentez ve ustalık! Enerji hesabı: 1 iyonik bağ (~ -8 kcal/mol) + 2 hidrojen bağı (2 x -4 = -8 kcal/mol) + 3 hidrofobik temas (3 x -1 = -3 kcal/mol) = Toplam Delta G° yaklaşık -19 kcal/mol! Bu muazzam enerji Kd = 10^-10 M (sub-nanomolar) seviyesinde sıkı bir bağlanma sağlar. Ancak hiçbir kovalent bağ (50-150 kcal/mol) bulunmadığından ilaç kalıcı adükt oluşturmaz; plazma konsantrasyonu düşünce koff ayrışma hızıyla reseptörden ayrılarak hedef kinazın aktivitesini yeniden serbest bırakır!\"},{\"id\":\"opt-12b\",\"text\":\"Toplam enerji 150 kcal/mol'ü aştığı için molekül hedef kinazı kalıcı olarak eritip geri dönüşsüz felç yapar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kovalent aşım yanılgısı: Non-kovalent bağların enerjileri toplandığında asla bir kovalent bağın enerjisine (50-150 kcal/mol) ulaşamaz; -19 kcal/mol çok güçlü bir non-kovalent afinite seviyesidir fakat kovalent kalıcılık yaratamaz.\"},{\"id\":\"opt-12c\",\"text\":\"Non-kovalent bağların enerjisi asla toplanamaz; molekülün net bağlanma enerjisi en zayıf bağ olan van der Waals'e (-1 kcal/mol) eşittir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Minimallik yanılgısı: Termodinamikte serbest enerjiler durum fonksiyonudur ve cebirsel olarak toplanır (Delta G_toplam = Delta G1 + Delta G2...); molekülün reseptöre toplam tutunma gücü tüm temas noktalarının bileşkesidir.\"}]},\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":33}]}]},\"pharm-mod1-les2\":{\"$schema\":\"../../../packages/platform/schema/lesson.schema.json\",\"id\":\"pharm-mod1-les2\",\"courseId\":\"pharmacology\",\"moduleId\":\"ph-mod-01\",\"title\":{\"tr\":\"Kütle Hareketi Kanunu, Kd ve Reseptör Doluluk Dengesi\",\"ar\":\"قانون فعل الكتلة وثابت Kd وتوازن إشغال المستقبِلات\",\"en\":\"Law of Mass Action, Kd & Receptor Occupancy Equilibrium\"},\"order\":2,\"access\":\"free\",\"objective\":{\"tr\":\"Kütle hareketi kanununu ve Hill-Langmuir fraksiyonel doluluk denklemini uygulayarak Kd ve afiniteyi hesaplamak, buprenorfin parsiyel agonist paradoksunu ve yedek reseptör rezervini açıklamak.\",\"ar\":\"تطبيق قانون فعل الكتلة ومعادلة إشغال المستقبِلات لحساب Kd والألفة الدوائية، وتفسير مفارقة البوبرينورفين وظاهرة المستقبِلات الاحتياطية.\",\"en\":\"Apply the law of mass action and fractional occupancy equation to calculate Kd and affinity, resolving the buprenorphine paradox and spare receptor reserves.\"},\"misconceptions\":[{\"tr\":\"Kd ayrışma sabiti sayısal olarak ne kadar büyükse ilacın reseptörüne o kadar güçlü bağlandığı yanılgısı (düşük Kd daha yüksek afiniteyi gösterir).\",\"ar\":\"الظن الخاطئ بأن زيادة قيمة ثابت التفكك Kd تعني ارتباطاً أقوى بالمستقبل (انخفاض Kd يدل على ألفة أعلى).\",\"en\":\"The misconception that a higher dissociation constant Kd indicates tighter receptor binding (lower Kd reflects higher affinity).\"},{\"tr\":\"Maksimum biyolojik etkinin (Emax) elde edilebilmesi için dokudaki reseptörlerin tamamının (%100) işgal edilmesinin zorunlu olduğu yanılgısı (Furchgott yedek reseptör rezervi).\",\"ar\":\"الاعتقاد الخاطئ بأن تحقيق أقصى استجابة حيوية (Emax) يتطلب حتماً إشغال 100% من المستقبِلات (ظاهرة الاحتياطي الوظيفي لـ Furchgott).\",\"en\":\"The belief that producing maximum biological effect (Emax) requires 100% receptor occupancy, neglecting spare receptor reserves.\"},{\"tr\":\"Yüksek afiniteli bir ilacın her zaman güçlü bir tam agonist olacağı düşüncesi (buprenorfin gibi yüksek afiniteli parsiyel agonistler tam agonistin etkisini antagonize eder).\",\"ar\":\"الظن الخاطئ بأن الدواء ذو الألفة الأعلى يكون دوماً منبهاً كاملاً أقوى، متجاهلاً أن المنبهات الجزئية عالية الألفة تنافس وتكبح المنبه الكامل.\",\"en\":\"The misconception that high affinity guarantees high efficacy, overlooking high-affinity partial agonists like buprenorphine that precipitate withdrawal.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":4},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":6}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Goodman & Gilman's The Pharmacological Basis of Therapeutics\",\"edition\":\"14th ed.\",\"topic\":\"Drug-Receptor Interactions and Quantitative Dynamics: Mass Action Kinetics & Receptor Occupancy\",\"chapter\":\"Chapter 3\",\"page\":\"52-70\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Katzung Basic & Clinical Pharmacology\",\"edition\":\"15th ed.\",\"topic\":\"Receptor-Effector Coupling & Spare Receptors: Signaling Mechanisms & Drug Action\",\"chapter\":\"Chapter 2\",\"page\":\"25-42\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"pharm-mod1-les2-card1\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Kd Ayrışma Sabiti Tanımı\",\"prompt\":\"Kd ayrışma sabiti biyofiziksel konsantrasyon cinsinden neyi ifade eder ve afinite ile nasıl ilişkilidir?\",\"answer\":\"Reseptörlerin tam olarak %50'sinin işgal edildiği serbest ilaç konsantrasyonudur (Kd = koff / kon). Kd ne kadar küçükse afinite (Ka = 1/Kd) o kadar yüksektir.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod1-les2-card2\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Hill-Langmuir Reseptör Doluluk Formülü\",\"prompt\":\"Fraksiyonel reseptör doluluğu (theta), serbest ilaç [D] ve Kd cinsinden nasıl formüle edilir?\",\"answer\":\"theta = [D] / ([D] + Kd). İlaç konsantrasyonu [D] = Kd olduğunda theta = 0.50 (%50 doluluk) elde edilir.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod1-les2-card3\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Furchgott Yedek Reseptör (Spare Receptors) Teorisi\",\"prompt\":\"Yedek reseptör rezervi olan bir dokuda agonist için EC50 ile Kd arasındaki ilişki nasıldır?\",\"answer\":\"EC50 değeri Kd değerinden çok daha düşüktür (EC50 < Kd); doku maksimum cevaba (Emax) reseptör havuzunun yalnızca küçük bir yüzdesi işgal edildiğinde ulaşır.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod1-les2-card4\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Buprenorfin Akut Yoksunluk Paradoksu\",\"prompt\":\"Morfin bağımlısı bir hastaya sublingual buprenorfin verildiğinde neden anında akut yoksunluk krizi (precipitated withdrawal) patlak verir?\",\"answer\":\"Buprenorfinin mu-opioid afinitesi çok yüksek (Kd ≈ 0.1 nM) olduğundan morfini (Kd ≈ 2 nM) kovar; fakat intrinsik aktivitesi düşük (alfa ≈ 0.35) olduğu için net reseptör uyarısı aniden %100'den %35'e düşer.\",\"box\":1,\"intervalDays\":1}],\"translations\":{\"tr\":{\"title\":\"Kütle Hareketi Kanunu, Kd ve Reseptör Doluluk Dengesi\"},\"ar\":{\"title\":\"قانون فعل الكتلة وثابت Kd وتوازن إشغال المستقبِلات\"}},\"steps\":[{\"id\":\"pharm-mod1-les2-step-01\",\"stage\":\"hook\",\"stageIndex\":1,\"type\":\"predict_reveal\",\"title\":{\"tr\":\"Klinik Paradoks: Buprenorfin ve Hızlı Yoksunluk Krizi\",\"ar\":\"مفارقة سريرية: البوبرينورفين ونوبة الانسحاب الحاد\",\"en\":\"Clinical Paradox: Buprenorphine Precipitated Withdrawal\"},\"prompt\":{\"tr\":\"Yüksek doz morfin kullanan bir hastaya, çok daha yüksek afiniteli bir opioid olan buprenorfin veriliyor. Hasta komaya girmek yerine dakikalar içinde şiddetli akut yoksunluk krizine giriyor. Neden?\",\"ar\":\"مريض يتناول جرعة عالية من المورفين، يُعطى بوبرينورفين ذو الألفة الفائقة. بدلاً من دخول غيبوبة أفيونية، يصاب بأعراض انسحاب حادة خلال دقائق! لماذا؟\",\"en\":\"A patient on high-dose morphine receives buprenorphine, an opioid with far higher affinity. Instead of deepening narcosis, acute opioid withdrawal explodes within minutes! Why?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-1a\",\"text\":{\"tr\":\"Buprenorfin çok yüksek afinitesiyle morfini reseptörden kovar; ancak kendisi düşük efikasiteli parsiyel agonist olduğundan net sinyali %100'den %35'e düşürür.\",\"ar\":\"يطرد البوبرينورفين المورفين بألفته العالية؛ لكنه كمنبه جزئي ضعيف الفاعلية يخفض إشارة التنبيه فوراً من 100% إلى 35%.\",\"en\":\"Buprenorphine's sub-nanomolar affinity displaces morphine, but its low partial agonist efficacy plunges signaling from 100% to 35%.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Buprenorfin yüksek afiniteye (Kd ≈ 0.1 nM) fakat düşük intrinsik aktiviteye (alfa ≈ 0.35) sahiptir. Morfini (Kd ≈ 2 nM, alfa = 1) kovar ve opioid uyarısını aniden çökertir (Slayt 34).\",\"ar\":\"صحيح! يملك البوبرينورفين ألفة فائقة (Kd ≈ 0.1 nM) لكن فاعليته الذاتية منخفضة (alfa ≈ 0.35). يزيح المورفين لتهبط الاستجابة فجأة.\",\"en\":\"Correct! Buprenorphine has sub-nanomolar affinity (Kd ≈ 0.1 nM) but low intrinsic efficacy (alpha ≈ 0.35). It displaces morphine, collapsing activation.\"}},{\"id\":\"opt-1b\",\"text\":{\"tr\":\"Buprenorfin morfin molekülünü kanda kovalent olarak parçalayarak idrarla atar.\",\"ar\":\"يقوم البوبرينورفين بتكسير جزيئات المورفين في الدم تساهمياً ليطرحها عبر البول.\",\"en\":\"Buprenorphine covalently degrades circulating morphine molecules, expelling them in urine.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kimyasal parçalama yanılgısı: Buprenorfin kimyasal bir enzim veya antikor değildir; mu-opioid reseptöründe yarışan farmakodinamik bir liganddır.\",\"ar\":\"خطأ التفكيك الكيميائي: ليس البوبرينورفين أنزيماً أو مضاداً كيميائياً، بل ربيط دوائي ينافس على المستقبل الأفيوني.\",\"en\":\"Degradation misconception: Buprenorphine is not a metabolic enzyme; it is a competitive pharmacological ligand at mu receptors.\"}},{\"id\":\"opt-1c\",\"text\":{\"tr\":\"Buprenorfin kanda morfinin proteine bağlanmasını %100 bloke ederek toksik serbest morfin dalgası yaratır.\",\"ar\":\"يعطل البوبرينورفين ارتباط المورفين ببروتينات الدم كلياً ليطلق موجة سامة من المورفين الحر.\",\"en\":\"Buprenorphine completely blocks morphine protein binding, generating a surge of free toxic morphine.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Plazma proteini yanılgısı: Serbest morfin dalgası oluşsaydı hasta yoksunluğa değil, solunum depresyonu ve komaya girerdi. Olay reseptör düzeyindeki kompetisyondur.\",\"ar\":\"خطأ إزاحة البروتين: لو تحرر المورفين لدخل المريض في غيبوبة أفيونية وتثبيط تنفسي بدلاً من أعراض الانسحاب الحادة.\",\"en\":\"Protein displacement misconception: Excess free morphine would cause coma and respiratory depression, not acute withdrawal.\"}}]},\"technicalTerms\":[{\"term\":\"parsiyel agonist\",\"arContext\":\"المنبه الجزئي (partial agonist)\"},{\"term\":\"akut tetiklenmiş yoksunluk\",\"arContext\":\"متلازمة الانسحاب الحاد المحفز\"}],\"hints\":[{\"tr\":\"Afinite (reseptöre tutunma gücü) ile efikasite (reseptörü aktive etme gücü) arasındaki farkı düşünün.\",\"ar\":\"فكر في الفارق الحاسم بين الألفة (قوة الالتصاق بالمستقبل) والفاعلية (القدرة على تشغيل المستقبل).\",\"en\":\"Distinguish between target affinity (binding tenacity) and intrinsic efficacy (activation strength).\"},{\"tr\":\"Buprenorfin reseptöre morfinden çok daha sıkı bağlanır ama reseptörü sadece kısmen uyarabilir.\",\"ar\":\"يرتبط البوبرينورفين بالمستقبل بإحكام يفوق المورفين، لكنه يشغله جزئياً فقط.\",\"en\":\"Buprenorphine binds much tighter than morphine, but stimulates the receptor only partially.\"},{\"tr\":\"Tam agonist morfini kovan bu zayıf uyarıcı, net opioid sinyalini anında düşürerek yoksunluk krizi patlatır.\",\"ar\":\"طرد المنبه الكامل واستبداله بمنبه جزئي يهبط بمستوى التنبيه فوراً مفجراً أعراض الانسحاب.\",\"en\":\"Displacing a full agonist with a partial agonist plunges net stimulation, precipitating immediate withdrawal.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":4}],\"config\":{\"options\":[{\"id\":\"opt-1a\",\"text\":\"Buprenorfin çok yüksek afinitesiyle morfini reseptörden kovar; ancak kendisi düşük efikasiteli parsiyel agonist olduğundan net sinyali %100'den %35'e düşürür.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Buprenorfin yüksek afiniteye (Kd ≈ 0.1 nM) fakat düşük intrinsik aktiviteye (alfa ≈ 0.35) sahiptir. Morfini (Kd ≈ 2 nM, alfa = 1) kovar ve opioid uyarısını aniden çökertir (Slayt 34).\"},{\"id\":\"opt-1b\",\"text\":\"Buprenorfin morfin molekülünü kanda kovalent olarak parçalayarak idrarla atar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kimyasal parçalama yanılgısı: Buprenorfin kimyasal bir enzim veya antikor değildir; mu-opioid reseptöründe yarışan farmakodinamik bir liganddır.\"},{\"id\":\"opt-1c\",\"text\":\"Buprenorfin kanda morfinin proteine bağlanmasını %100 bloke ederek toksik serbest morfin dalgası yaratır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Plazma proteini yanılgısı: Serbest morfin dalgası oluşsaydı hasta yoksunluğa değil, solunum depresyonu ve komaya girerdi. Olay reseptör düzeyindeki kompetisyondur.\"}],\"revealedOutcome\":{\"tr\":\"Buprenorfin yüksek afinitesiyle morfini kovar; ancak düşük intrinsik aktivitesi (alfa ≈ 0.35) nedeniyle net opioid uyarısı aniden düşer ve akut yoksunluk patlak verir.\",\"ar\":\"يطرد البوبرينورفين المورفين بألفته العالية؛ ولأن فاعليته الذاتية منخفضة، تهبط الاستجابة الأفيونية فوراً مسببة نوبة انسحاب حادة.\",\"en\":\"Buprenorphine's high affinity displaces morphine; its low intrinsic efficacy then plunges opioid stimulation, precipitating acute withdrawal.\"},\"explanation\":{\"tr\":\"Slayt 34'teki Ariëns teorisine göre: Bir ilacın reseptör işgali tek başına etkiyi garanti etmez. Yüksek afiniteli bir parsiyel agonist, tam agonist varlığında bir antagonist gibi davranır.\",\"ar\":\"وفق نظرية Ariëns في الشريحة 34: إشغال المستقبل وحده لا يضمن الاستجابة؛ المنبه الجزئي عالي الألفة يسلك سلوك المضاد بوجود منبه كامل.\",\"en\":\"Per Ariëns' intrinsic activity theory (Slide 34): high affinity alone does not dictate response magnitude. A high-affinity partial agonist acts as an antagonist against a full agonist.\"}}},{\"id\":\"pharm-mod1-les2-step-02\",\"stage\":\"question\",\"stageIndex\":2,\"type\":\"question\",\"title\":{\"tr\":\"Kütle Hareketi ve Kd: Yarı Doluluk Noktası\",\"ar\":\"فعل الكتلة وثابت Kd: نقطة نصف الإشغال\",\"en\":\"Mass Action & Kd: The Half-Saturation Threshold\"},\"prompt\":{\"tr\":\"Kütle Hareketi Kanununa göre, ortamdaki serbest ilaç konsantrasyonu ilacın Kd ayrışma sabitine eşit olduğunda ([D] = Kd), reseptörlerin yüzde kaçı işgal edilmiştir?\",\"ar\":\"وفق قانون فعل الكتلة، عندما يتساوى تركيز الدواء الحر في الوسط مع ثابت التفكك ([D] = Kd)، ما هي النسبة المئوية لإشغال المستقبِلات؟\",\"en\":\"According to the Law of Mass Action, when the free drug concentration equals the dissociation constant ([D] = Kd), what percentage of receptors is occupied?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-2a\",\"text\":{\"tr\":\"Tam olarak %50'si doludur; theta = [D] / ([D] + Kd) = Kd / (2Kd) = 0.50.\",\"ar\":\"50% منها تماماً؛ نسبة الإشغال theta = [D] / ([D] + Kd) = 0.50.\",\"en\":\"Exactly 50% are occupied; fractional occupancy theta = [D] / ([D] + Kd) = 0.50.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kesinlikle doğru! Kd'nin matematiksel ve biyofiziksel tanımı budur: Toplam reseptörlerin tam olarak yarısının (%50) bağlandığı serbest ilaç konsantrasyonudur (Slayt 34).\",\"ar\":\"صحيح تماماً! هذا هو التعريف الرياضي والفيزيائي لـ Kd: تركيز الدواء الحر الذي يشغل 50% تماماً من إجمالي المستقبِلات (شريحة 34).\",\"en\":\"Exactly correct! This is the precise definition of Kd: the free ligand concentration at which 50% of total receptors are bound.\"}},{\"id\":\"opt-2b\",\"text\":{\"tr\":\"%100'ü tamamen doludur; Kd tam doygunluğa ulaşılan eşik konsantrasyonudur.\",\"ar\":\"100% منها بالكامل؛ يمثل Kd تركيز العتبة للوصول إلى التشبع التام.\",\"en\":\"100% fully occupied; Kd is the threshold concentration required to saturate all receptors.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Tam doygunluk yanılgısı: [D] = Kd olduğunda reseptörlerin tamamı değil, sadece yarısı doludur. %99 doluluk için konsantrasyonun Kd'nin en az 100 katı olması gerekir.\",\"ar\":\"خطأ التشبع التام: عند [D] = Kd يمتلئ النصف فقط؛ ويتطلب الوصول إلى 99% إشغال تركيزاً يفوق Kd بمئة ضعف.\",\"en\":\"Saturation misconception: At [D] = Kd, only half the receptors are occupied. Reaching 99% occupancy requires [D] to be 100 times Kd.\"}},{\"id\":\"opt-2c\",\"text\":{\"tr\":\"%0'ı doludur; Kd ilacın reseptörden ayrılmaya başladığı alt konsantrasyondur.\",\"ar\":\"0% منها؛ يمثل Kd الحد الأدنى من التركيز الذي يبدأ عنده الدواء بالانفصال.\",\"en\":\"0% occupied; Kd is the minimum baseline concentration where drug begins dissociating.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Sıfır doluluk yanılgısı: Bağlanma dinamik bir dengedir; konsantrasyon arttıkça doluluk artar. [D] = Kd seviyesinde reseptörlerin tam %50'si komplekstir.\",\"ar\":\"خطأ انعدام الإشغال: الارتباط توازن ديناميكي؛ عند وصول التركيز إلى قيمة Kd تكون نصف المستقبِلات مشغولة بالمعقد.\",\"en\":\"Zero occupancy misconception: Binding is a dynamic equilibrium; at [D] = Kd, exactly half the receptor pool exists as drug-receptor complex.\"}}]},\"technicalTerms\":[{\"term\":\"ayrışma sabiti (Kd)\",\"arContext\":\"ثابت التفكك (Kd)\"},{\"term\":\"fraksiyonel doluluk (theta)\",\"arContext\":\"نسبة الإشغال الكسرية (theta)\"}],\"hints\":[{\"tr\":\"Hill-Langmuir denklemini hatırlayın: theta = [D] / ([D] + Kd).\",\"ar\":\"تذكر معادلة هيل-لانغموير: theta = [D] / ([D] + Kd).\",\"en\":\"Recall the Hill-Langmuir occupancy equation: theta = [D] / ([D] + Kd).\"},{\"tr\":\"[D] yerine Kd koyun: Kd / (Kd + Kd).\",\"ar\":\"عوض Kd مكان [D]: تصبح المعادلة Kd / (Kd + Kd).\",\"en\":\"Substitute Kd for [D]: the ratio simplifies to Kd / (Kd + Kd).\"},{\"tr\":\"Kd / 2Kd = 1/2 = 0.50, yani reseptörlerin tam olarak %50'si doludur.\",\"ar\":\"Kd / 2Kd = 1/2 = 0.50، أي أن 50% تماماً من المستقبِلات مشغولة.\",\"en\":\"Kd / 2Kd equals 0.50; exactly half the receptor population is occupied.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":4}],\"config\":{\"options\":[{\"id\":\"opt-2a\",\"text\":\"Tam olarak %50'si doludur; theta = [D] / ([D] + Kd) = Kd / (2Kd) = 0.50.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kesinlikle doğru! Kd'nin matematiksel ve biyofiziksel tanımı budur: Toplam reseptörlerin tam olarak yarısının (%50) bağlandığı serbest ilaç konsantrasyonudur (Slayt 34).\"},{\"id\":\"opt-2b\",\"text\":\"%100'ü tamamen doludur; Kd tam doygunluğa ulaşılan eşik konsantrasyonudur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Tam doygunluk yanılgısı: [D] = Kd olduğunda reseptörlerin tamamı değil, sadece yarısı doludur. %99 doluluk için konsantrasyonun Kd'nin en az 100 katı olması gerekir.\"},{\"id\":\"opt-2c\",\"text\":\"%0'ı doludur; Kd ilacın reseptörden ayrılmaya başladığı alt konsantrasyondur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Sıfır doluluk yanılgısı: Bağlanma dinamik bir dengedir; konsantrasyon arttıkça doluluk artar. [D] = Kd seviyesinde reseptörlerin tam %50'si komplekstir.\"}],\"revealedOutcome\":{\"tr\":\"[D] = Kd olduğunda fraksiyonel reseptör doluluğu theta = Kd / (Kd + Kd) = 0.50 (%50 doluluk) olur.\",\"ar\":\"عندما يكون [D] = Kd تصبح نسبة إشغال المستقبِلات theta = 0.50 (50% إشغال).\",\"en\":\"When [D] = Kd, fractional receptor occupancy theta = Kd / (Kd + Kd) = 0.50 (50% occupancy).\"},\"explanation\":{\"tr\":\"Kütle hareketi kanununa göre denge anında kon*[D]*[R] = koff*[DR] dir. Buradan türetilen Kd = koff / kon sabiti, reseptörlerin yarı yarıya doyduğu serbest ligand derişimidir (Slayt 34).\",\"ar\":\"وفق قانون فعل الكتلة عند التوازن: سرعة الارتباط تساوي سرعة التفكك. ثابت Kd = koff / kon يمثل تركيز الربيط الذي يضمن إشغال نصف المستقبِلات بالضبط (شريحة 34).\",\"en\":\"At equilibrium, kon*[D]*[R] = koff*[DR]. The equilibrium dissociation constant Kd = koff/kon is the concentration occupying 50% of available receptors.\"}}},{\"id\":\"pharm-mod1-les2-step-03\",\"stage\":\"intuition\",\"stageIndex\":3,\"type\":\"intuition\",\"title\":{\"tr\":\"Afinite Sezgisi: Ters Orantılı Kd Ölçeği\",\"ar\":\"حدس الألفة الدوائية: مقياس Kd العكسي\",\"en\":\"Affinity Intuition: The Inverse Kd Scale\"},\"prompt\":{\"tr\":\"İki ilaç düşünün: İlaç A'nın Kd değeri 0.1 nM, İlaç B'nin Kd değeri 100 nM'dir. Aynı hedef reseptör için hangisi daha yüksek bağlanma afinitesine sahiptir?\",\"ar\":\"تأمل دواءين: الدواء A يملك Kd = 0.1 nM، بينما الدواء B يملك Kd = 100 nM. أيهما يملك ألفة ارتباط أعلى بالمستقبل المستهدف؟\",\"en\":\"Consider two drugs: Drug A has Kd = 0.1 nM, while Drug B has Kd = 100 nM. Which drug possesses the higher binding affinity for the target receptor?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-3a\",\"text\":{\"tr\":\"İlaç A; Kd değeri ne kadar düşükse, reseptörlerin %50'sini doyurmak için gereken molekül sayısı o kadar azdır ve afinite 1000 kat daha yüksektir.\",\"ar\":\"الدواء A؛ كلما انخفضت قيمة Kd، قل التركيز اللازم لإشغال 50% من المستقبِلات، وكانت الألفة أعلى بألف ضعف.\",\"en\":\"Drug A; a lower Kd means far fewer molecules are needed to achieve 50% occupancy, reflecting 1000-fold higher affinity.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika! Afinite Ka = 1 / Kd bağıntısıyla tanımlanır. Kd küçüldükçe ilacın reseptöre ilgisi katlanarak artar; 0.1 nM'lik ilaç 100 nM'likten 1000 kat daha güçlü bağlanır (Slayt 34).\",\"ar\":\"رائع! تُعرف الألفة بالمعادلة Ka = 1 / Kd. كلما صغرت Kd زاد الارتباط إحكاماً؛ فالدواء ذو 0.1 nM يرتبط بقوة تفوق الآخر بألف مرة (شريحة 34).\",\"en\":\"Great! Affinity is the reciprocal of dissociation (Ka = 1/Kd). A Kd of 0.1 nM binds 1000 times more avidly than 100 nM.\"}},{\"id\":\"opt-3b\",\"text\":{\"tr\":\"İlaç B; Kd değeri ne kadar büyükse moleküller o kadar hızlı yapışır ve afinite artar.\",\"ar\":\"الدواء B؛ كلما زادت قيمة Kd، التصقت الجزيئات بالمستقبل أسرع وارتفعت الألفة.\",\"en\":\"Drug B; larger Kd values indicate faster binding association and therefore higher affinity.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Ayrışma vs bağlanma yanılgısı: Kd bağlanma değil ayrışma (dissociation) sabitidir. Yüksek Kd, ilacın reseptörden çok hızlı koptuğunu (koff yüksek) ve afinitenin düşük olduğunu gösterir.\",\"ar\":\"خطأ التفكك والارتباط: Kd هو ثابت التفكك؛ وارتفاع قيمته يعني سرعة انفصال الدواء (koff مرتفع) وضعف الألفة.\",\"en\":\"Dissociation misconception: Kd measures dissociation. A high Kd means rapid target departure (high koff) and weak affinity.\"}},{\"id\":\"opt-3c\",\"text\":{\"tr\":\"Her iki ilacın afinitesi aynıdır; Kd sadece ilacın molekül ağırlığını temsil eder.\",\"ar\":\"كلا الدواءين متطابقان في الألفة؛ إذ يمثل Kd مجرد الوزن الجزيئي للدواء.\",\"en\":\"Both drugs have identical affinity; Kd merely reflects molecular weight.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Molekül ağırlığı yanılgısı: Kd molekül ağırlığıyla değil, kimyasal bağlanma dengesi ve Gibbs serbest enerjisiyle (Delta G) doğrudan ilişkilidir.\",\"ar\":\"خطأ الوزن الجزيئي: لا يعبر Kd عن الوزن الجزيئي إطلاقاً، بل يرتبط مباشرة بطاقة غيبس الحرة للارتباط والتوازن الكيميائي.\",\"en\":\"Molecular weight misconception: Kd is thermodynamic binding free energy (Delta G), unrelated to molecular mass.\"}}]},\"technicalTerms\":[{\"term\":\"bağlanma afinitesi\",\"arContext\":\"ألفة الارتباط (binding affinity)\"},{\"term\":\"ayrışma hızı (koff)\",\"arContext\":\"معدل التفكك (koff)\"}],\"hints\":[{\"tr\":\"Kd bir 'ayrışma' sabitidir; ilacın reseptörü ne kadar kolay terk ettiğini gösterir.\",\"ar\":\"ثابت Kd هو ثابت 'تفكك'؛ يقيس مدى سهولة مغادرة الدواء للمستقبل.\",\"en\":\"Kd is a 'dissociation' constant reflecting how readily a drug leaves its target.\"},{\"tr\":\"Az miktarda molekülle bile reseptörü doldurabilen ilaç mı, yoksa çok miktarda molekül gerektiren mi daha isteklidir?\",\"ar\":\"هل الدواء الذي يملأ المستقبل بتركيز شحيح أشد رغبة في الارتباط، أم الذي يتطلب تركيزاً غفيراً؟\",\"en\":\"Does a drug needing few molecules to occupy targets have higher or lower affinity?\"},{\"tr\":\"Kd ne kadar küçükse afinite o kadar büyüktür: Ka = 1 / Kd. 0.1 nM olan İlaç A 1000 kat daha güçlü afiniteye sahiptir.\",\"ar\":\"كلما صغر Kd زادت الألفة: Ka = 1 / Kd. الدواء A ذو 0.1 nM أشد ألفة بألف ضعف.\",\"en\":\"Smaller Kd indicates higher affinity: Ka = 1/Kd. Drug A (0.1 nM) is 1000-fold more avid.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":6}],\"config\":{\"options\":[{\"id\":\"opt-3a\",\"text\":\"İlaç A; Kd değeri ne kadar düşükse, reseptörlerin %50'sini doyurmak için gereken molekül sayısı o kadar azdır ve afinite 1000 kat daha yüksektir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika! Afinite Ka = 1 / Kd bağıntısıyla tanımlanır. Kd küçüldükçe ilacın reseptöre ilgisi katlanarak artar; 0.1 nM'lik ilaç 100 nM'likten 1000 kat daha güçlü bağlanır (Slayt 34).\"},{\"id\":\"opt-3b\",\"text\":\"İlaç B; Kd değeri ne kadar büyükse moleküller o kadar hızlı yapışır ve afinite artar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Ayrışma vs bağlanma yanılgısı: Kd bağlanma değil ayrışma (dissociation) sabitidir. Yüksek Kd, ilacın reseptörden çok hızlı koptuğunu (koff yüksek) ve afinitenin düşük olduğunu gösterir.\"},{\"id\":\"opt-3c\",\"text\":\"Her iki ilacın afinitesi aynıdır; Kd sadece ilacın molekül ağırlığını temsil eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Molekül ağırlığı yanılgısı: Kd molekül ağırlığıyla değil, kimyasal bağlanma dengesi ve Gibbs serbest enerjisiyle (Delta G) doğrudan ilişkilidir.\"}],\"revealedOutcome\":{\"tr\":\"Afinite Kd ile ters orantılıdır (Ka = 1 / Kd). Kd = 0.1 nM olan İlaç A, Kd = 100 nM olan İlaç B'ye göre reseptöre 1000 kat daha yüksek afiniteyle bağlanır.\",\"ar\":\"تتناسب الألفة عكساً مع Kd (Ka = 1 / Kd). الدواء A ذو Kd = 0.1 nM يرتبط بألفة تفوق الدواء B بمئة ضعف.\",\"en\":\"Affinity is inversely proportional to Kd (Ka = 1/Kd). Drug A (Kd = 0.1 nM) binds with 1000-fold higher affinity than Drug B (100 nM).\"},\"explanation\":{\"tr\":\"Düşük Kd, ilacın çok düşük konsantrasyonlarda bile reseptörün yarısını işgal edebildiğini gösterir. Bu durum daha yüksek bağlanma gücü, daha düşük terapötik doz ve daha az hedef dışı toksisite anlamına gelir (Slayt 34).\",\"ar\":\"يعني انخفاض Kd قدرة الدواء على إشغال نصف المستقبِلات بتركيز ضئيل جداً، مما يترجم سريرياً إلى فاعلية بجرعات منخفضة وأمان أعلى (شريحة 34).\",\"en\":\"A lower Kd demonstrates target occupancy at trace concentrations, enabling lower therapeutic dosing and reduced off-target liabilities.\"}}},{\"id\":\"pharm-mod1-les2-step-04\",\"stage\":\"visual_explanation\",\"stageIndex\":4,\"type\":\"visual_explanation\",\"title\":{\"tr\":\"Görsel Matematik: Hiperbolden Sigmoidal Eğriye\",\"ar\":\"الرياضيات البصرية: من القطع الزائد إلى المنحنى السيني\",\"en\":\"Visual Math: From Hyperbola to Sigmoidal Curve\"},\"prompt\":{\"tr\":\"Doz-yanıt eğrisinin logaritmik eksenini inceleyin: Eksen lineerden logaritmaya çevrildiğinde hiperbolik eğri neden zarif bir S-biçimli (sigmoidal) eğriye dönüşür?\",\"ar\":\"تأمل المحور اللوغاريتمي لمنحنى الجرعة والاستجابة: لماذا يتحول المنحنى الزائدي إلى منحنى سيني أنيق (sigmoidal) عند تحويل المحور من الخطي إلى اللوغاريتمي؟\",\"en\":\"Examine the log dose-response curve: why does the rectangular hyperbola transform into a symmetric sigmoidal S-curve upon logarithmic transformation?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-4a\",\"text\":{\"tr\":\"Logaritmik skala, çok geniş bir konsantrasyon aralığını (4-5 logaritma basamağı) tek bir grafik üzerinde simetrik ve ölçülebilir hale getirir.\",\"ar\":\"المقياس اللوغاريتمي يضغط مجالاً واسعاً من التراكيز (4-5 مراتب عشرية) ليصبح متناظراً وقابلاً للقياس والمقارنة على رسم بياني واحد.\",\"en\":\"The logarithmic scale compresses vast concentration spans (4-5 orders of magnitude) into a symmetric, clinically measurable curve.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel! Lineer grafikte düşük dozlar sıfıra sıkışırken yüksek dozlar sonsuza uzanır. Logaritmik dönüşüm, EC50 noktasını eğrinin simetrik büküm noktası (inflection point) haline getirir (Slayt 34).\",\"ar\":\"ممتاز! في الرسم الخطي تتكدس الجرعات المنخفضة بينما يمتد المنحنى في اللانهاية. يحول اللوغاريتم نقطة EC50 إلى نقطة انقلاب متناظرة (شريحة 34).\",\"en\":\"Perfect! Linear plots compress low doses near zero. Logarithmic transformation turns EC50 into a symmetric inflection point.\"}},{\"id\":\"opt-4b\",\"text\":{\"tr\":\"Logaritmik eksen reseptörler arasında pozitif kooperativite yaratır ve Hill katsayısını 1'den 4'e yükseltir.\",\"ar\":\"يخلق المحور اللوغاريتمي تعاونية إيجابية بين المستقبِلات ويرفع معامل هيل من 1 إلى 4.\",\"en\":\"Logarithmic plotting induces positive cooperativity among binding sites, altering the intrinsic Hill coefficient from 1 to 4.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Matematiksel vs biyolojik yanılgı: Logaritma ekseni sadece bir veri ekseni dönüşümüdür; ilacın bağlanma mekanizmasını, kooperativitesini veya Hill katsayısını biyolojik olarak değiştiremez.\",\"ar\":\"مغالطة الخلط الرياضي الحيوي: التحويل اللوغاريتمي مجرد أداة بيانية لعرض البيانات ولا يغير الخصائص الحيوية للمستقبل أو معامل هيل.\",\"en\":\"Mathematical vs biological fallacy: Logarithmic axis scaling is purely a graphic display transformation; it cannot alter physical binding cooperativity or Hill coefficients.\"}},{\"id\":\"opt-4c\",\"text\":{\"tr\":\"Sigmoidal dönüşüm reseptörlerin tamamının aynı anda tek bir molekülle doymasını zorunlu kılar.\",\"ar\":\"يفرض التحول السيني امتلاء كافة المستقبِلات بجزيء دوائي واحد في الوقت ذاته.\",\"en\":\"Sigmoidal conversion forces all receptors to simultaneously saturate with a single ligand molecule.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Doygunluk yanılgısı: Sigmoidal eğri Hill-Langmuir kütle hareketi dengesini simetrik olarak gösterir; tek bir molekülle tüm reseptörlerin doyması fizikokimyasal olarak imkansızdır.\",\"ar\":\"خطأ التشبع المتزامن: يعكس المنحنى السيني توازن فعل الكتلة تدريجياً؛ ومستحيل فيزيائياً أن يملأ جزيء واحد كافة المستقبِلات.\",\"en\":\"Simultaneous saturation misconception: Sigmoidal curves depict graded mass-action equilibria; individual molecules cannot bind all receptors at once.\"}}]},\"technicalTerms\":[{\"term\":\"sigmoidal eğri\",\"arContext\":\"المنحنى السيني (sigmoidal curve)\"},{\"term\":\"infleksiyon noktası (EC50)\",\"arContext\":\"نقطة الانقلاب (EC50)\"}],\"hints\":[{\"tr\":\"İlaç konsantrasyonlarının 0.001 nM'den 10,000 nM'ye kadar uzandığını düşünün.\",\"ar\":\"فكر في مجال تراكيز الأدوية الممتد من 0.001 nM إلى 10,000 nM.\",\"en\":\"Consider concentration ranges spanning from 0.001 nM up to 10,000 nM.\"},{\"tr\":\"Lineer bir cetvelde 0.001 ile 10,000'i aynı anda okumak mümkün müdür?\",\"ar\":\"هل يمكن قراءة 0.001 و 10,000 بوضوح على مسطرة خطية واحدة؟\",\"en\":\"Can you distinguish 0.001 and 10,000 clearly on a single linear ruler?\"},{\"tr\":\"Logaritma skalası geniş aralıkları sıkıştırır; hiperbolü orta noktası EC50 olan simetrik S-eğrisine dönüştürür.\",\"ar\":\"يضغط المقياس اللوغاريتمي المجالات الشاسعة ليحول القطع الزائد إلى منحنى S متناظر مركزه EC50.\",\"en\":\"Log transformation compresses wide ranges, creating a symmetric S-curve centered at EC50.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":4}],\"config\":{\"options\":[{\"id\":\"opt-4a\",\"text\":\"Logaritmik skala, çok geniş bir konsantrasyon aralığını (4-5 logaritma basamağı) tek bir grafik üzerinde simetrik ve ölçülebilir hale getirir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel! Lineer grafikte düşük dozlar sıfıra sıkışırken yüksek dozlar sonsuza uzanır. Logaritmik dönüşüm, EC50 noktasını eğrinin simetrik büküm noktası (inflection point) haline getirir (Slayt 34).\"},{\"id\":\"opt-4b\",\"text\":\"Logaritmik eksen reseptörler arasında pozitif kooperativite yaratır ve Hill katsayısını 1'den 4'e yükseltir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Matematiksel vs biyolojik yanılgı: Logaritma ekseni sadece bir veri ekseni dönüşümüdür; ilacın bağlanma mekanizmasını, kooperativitesini veya Hill katsayısını biyolojik olarak değiştiremez.\"},{\"id\":\"opt-4c\",\"text\":\"Sigmoidal dönüşüm reseptörlerin tamamının aynı anda tek bir molekülle doymasını zorunlu kılar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Doygunluk yanılgısı: Sigmoidal eğri Hill-Langmuir kütle hareketi dengesini simetrik olarak gösterir; tek bir molekülle tüm reseptörlerin doyması fizikokimyasal olarak imkansızdır.\"}],\"revealedOutcome\":{\"tr\":\"Logaritma skalası konsantrasyonu log[D] olarak dönüştürerek hiperbolik eğriyi simetrik sigmoidal S-eğrisine çevirir. EC50 noktası büküm noktasında kolayca okunur.\",\"ar\":\"يحول المقياس اللوغاريتمي التركيز إلى log[D] ليتحول المنحنى إلى شكل S متناظر؛ وتُقرأ قيمة EC50 بسهولة عند نقطة الانقلاب.\",\"en\":\"Log-transforming concentration into log[D] converts hyperbolas into sigmoidal S-curves, allowing straightforward EC50 readout at the inflection point.\"},\"explanation\":{\"tr\":\"Hill-Langmuir denklemi lineer eksende asimptotik hiperbol verirken, log eksende lojistik fonksiyona dönüşür. Bu durum farmakolojide agonistlerin güçlerini (EC50) ve maksimum yanıtlarını (Emax) kıyaslamanın standart yoludur (Slayt 34).\",\"ar\":\"تتحول معادلة هيل-لانغموير إلى دالة لوجستية سينيّة على المحور اللوغاريتمي، مما يوفر الطريقة المعيارية للمقارنة بين فاعلية الأدوية (EC50) وأقصى استجابة (Emax) (شريحة 34).\",\"en\":\"Hill-Langmuir kinetics transform into a symmetrical logistic function on log axes, providing the pharmacology standard for comparing EC50 potency and Emax efficacy.\"}}},{\"id\":\"pharm-mod1-les2-step-05\",\"stage\":\"interactive_artifact\",\"stageIndex\":5,\"type\":\"dose_response_curve\",\"widgetType\":\"DoseResponseCurve\",\"title\":{\"tr\":\"İnteraktif Laboratuvar: Doz-Yanıt Dinamikleri\",\"ar\":\"مختبر تفاعلي: ديناميكا الجرعة والاستجابة\",\"en\":\"Interactive Lab: Dose-Response Dynamics\"},\"prompt\":{\"tr\":\"İnteraktif Doz-Yanıt laboratuvarında Agonist, Parsiyel Agonist ve Kompetitif Antagonist modlarını test ederek EC50 kaymasını ve Emax tavanını inceleyin.\",\"ar\":\"في مختبر الجرعة والاستجابة التفاعلي، اختبر أنماط المنبه والمنبه الجزئي والمضاد التنافسي لملاحظة إزاحة EC50 وتغير سقف الاستجابة Emax.\",\"en\":\"In the interactive Dose-Response lab, toggle Agonist, Partial Agonist, and Competitive Antagonist modes to inspect EC50 shifts and Emax ceilings.\"},\"predictThenReveal\":false,\"config\":{\"title\":\"Farmakolojik Doz-Yanıt ve Reseptör Doluluk Simülatörü\",\"prompt\":\"Agonist, parsiyel agonist ve antagonist modlarını karşılaştırarak eğrilerin kaymasını inceleyin.\",\"defaultEc50\":10,\"defaultEmax\":100,\"defaultHillSlope\":1,\"modes\":[\"agonist\",\"partial_agonist\",\"competitive_antagonist\",\"noncompetitive_antagonist\"],\"source\":{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":4},\"explanation\":\"Tam agonist Emax=%100 üretir. Parsiyel agonist (örn. buprenorfin) reseptörü %100 doldursa dahi submaksimal etki (Emax=%35) verir. Kompetitif antagonist eğriyi paralel sağa kaydırırken, nonkompetitif antagonist Emax tavanını ezer.\"},\"widget\":{\"type\":\"DoseResponseCurve\",\"config\":{\"title\":\"Farmakolojik Doz-Yanıt ve Reseptör Doluluk Simülatörü\",\"prompt\":\"Agonist, parsiyel agonist ve antagonist modlarını karşılaştırarak eğrilerin kaymasını inceleyin.\",\"defaultEc50\":10,\"defaultEmax\":100,\"defaultHillSlope\":1,\"modes\":[\"agonist\",\"partial_agonist\",\"competitive_antagonist\",\"noncompetitive_antagonist\"],\"source\":{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":4},\"explanation\":\"Tam agonist Emax=%100 üretir. Parsiyel agonist (örn. buprenorfin) reseptörü %100 doldursa dahi submaksimal etki (Emax=%35) verir. Kompetitif antagonist eğriyi paralel sağa kaydırırken, nonkompetitif antagonist Emax tavanını ezer.\"}},\"technicalTerms\":[{\"term\":\"Emax (maksimum etki)\",\"arContext\":\"أقصى استجابة حيوية (Emax)\"},{\"term\":\"EC50 (yarı maksimal konsantrasyon)\",\"arContext\":\"التركيز الفعال النصفي (EC50)\"}],\"hints\":[{\"tr\":\"Kompetitif antagonist moduna geçin: Emax değişmeden eğrinin nasıl sağa ötelendiğini görün.\",\"ar\":\"انتقل إلى نمط المضاد التنافسي: لاحظ كيف ينزاح المنحنى يميناً دون انخفاض Emax.\",\"en\":\"Switch to competitive antagonist mode: observe the parallel rightward shift with preserved Emax.\"},{\"tr\":\"Parsiyel agonist modunda tavanın (Emax) düşmesine dikkat edin: Ne kadar doz verirseniz verin %100'e ulaşamaz.\",\"ar\":\"انتبه لهبوط سقف الاستجابة في نمط المنبه الجزئي: مهما رفعت الجرعة لن تبلغ 100%.\",\"en\":\"Notice the depressed Emax ceiling in partial agonist mode: no dose escalation reaches 100%.\"},{\"tr\":\"Kompetitif antagonist sağa kaydırır (surmountable); nonkompetitif ise Emax'ı aşağı çeker (insurmountable).\",\"ar\":\"المضاد التنافسي يزيح لليمين؛ بينما غير التنافسي يهبط بسقف Emax قسراً.\",\"en\":\"Competitive blockers cause surmountable right shifts; noncompetitive blockers depress Emax.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":4},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":6}]},{\"id\":\"pharm-mod1-les2-step-06\",\"stage\":\"guided_discovery\",\"stageIndex\":6,\"type\":\"guided_discovery\",\"title\":{\"tr\":\"Kritik Ayrım: Afinite ve İntrinsik Aktivite (Ariëns)\",\"ar\":\"التمييز الحاسم: الألفة والفاعلية الذاتية (Ariëns)\",\"en\":\"Critical Distinction: Affinity vs Intrinsic Activity (Ariëns)\"},\"prompt\":{\"tr\":\"Stephenson ve Ariëns'e göre bir ilacın reseptörüne çok sıkı bağlanması (yüksek afinite), hücrede mutlaka maksimum bir biyolojik yanıt oluşturacağını garanti eder mi?\",\"ar\":\"وفقاً لـ Stephenson و Ariëns، هل يضمن الارتباط الشديد للمركب بمستقبله (الألفة العالية) حتماً إحداث أقصى استجابة حيوية في الخلية؟\",\"en\":\"According to Stephenson and Ariëns, does tight receptor binding (high affinity) guarantee maximal biological response in the target cell?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-6a\",\"text\":{\"tr\":\"Hayır; afinite sadece bağlanma gücünü (Kd) belirler, oysa yanıt oluşturabilmek için ilacın intrinsik aktiviteye (alfa / efikasite) sahip olması gerekir.\",\"ar\":\"كلا؛ تحدد الألفة قوة الارتباط فقط (Kd)، بينما يتطلب إحداث الاستجابة امتلاك الدواء فاعلية ذاتية (alfa / efficacy).\",\"en\":\"No; affinity solely governs binding occupancy (Kd), whereas biological activation strictly requires intrinsic activity (alpha / efficacy).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Ariëns (1954) afinite ile intrinsik aktiviteyi (alfa) ayırmıştır. Bir antagonist (örn. nalokson) pikomolar afiniteyle bağlanabilir ama alfa = 0 olduğu için sıfır sinyal üretir (Slayt 34).\",\"ar\":\"صحيح! فصل Ariëns عام 1954 بين الألفة والفاعلية الذاتية (alfa). يرتبط المضاد (كالنالوكسون) بألفة بيكومولية فائقة لكنه ينتج صفراً من الإشارة لأن alfa = 0.\",\"en\":\"Correct! Ariëns (1954) bifurcated affinity from intrinsic activity (alpha). Antagonists bind with picomolar tenacity yet yield zero activation (alpha = 0).\"}},{\"id\":\"opt-6b\",\"text\":{\"tr\":\"Evet; Clark teorisine göre işgal edilen her reseptör istisnasız %100 tam biyolojik sinyal üretmek zorundadır.\",\"ar\":\"نعم؛ وفق نظرية كلارك يُلزم كل مستقبل مشغول بإنتاج 100% من الإشارة الحيوية الكاملة دون استثناء.\",\"en\":\"Yes; according to Clark's theory, every occupied receptor is strictly required to generate a 100% maximal biological stimulus.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Klasik teori yanılgısı: Clark'ın işgal teorisi (1926) antagonistlerin varlığını açıklayamadığı için terk edilmiştir; Ariëns ve Stephenson intrinsik aktivite kavramını getirmiştir.\",\"ar\":\"خطأ النظرية الكلاسيكية: عجزت نظرية كلارك (1926) عن تفسير عمل المضادات فتم تعديلها؛ وأدخل Ariëns مفهوم الفاعلية الذاتية.\",\"en\":\"Clark theory limitation: Clark's 1926 model could not explain antagonists or partial agonists; Ariëns and Stephenson revised it.\"}},{\"id\":\"opt-6c\",\"text\":{\"tr\":\"Evet; yüksek afiniteli moleküller kovalent bağ kurarak reseptörü daima tam güçle aktive eder.\",\"ar\":\"نعم؛ لأن الجزيئات عالية الألفة تؤسس روابط تساهمية تشغل المستقبل بالطاقة القصوى دوماً.\",\"en\":\"Yes; high-affinity ligands form covalent bonds that always drive maximum receptor activation.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Afinite-kovalent karışıklığı: Yüksek afinite kovalent bağ demek değildir; reversible non-kovalent bağlarla da pikomolar afinite sağlanabilir ve bu aktivasyonu garanti etmez.\",\"ar\":\"خلط الألفة بالتساهمية: لا تعني الألفة العالية روابط تساهمية؛ بل يمكن تحقيقها بروابط عكوسة، ولا علاقة لها بحجم التنشيط الخلوي.\",\"en\":\"Covalent confusion: Picomolar affinity is achievable via reversible contacts and implies nothing about intrinsic activation.\"}}]},\"technicalTerms\":[{\"term\":\"intrinsik aktivite (alfa)\",\"arContext\":\"الفاعلية الذاتية (intrinsic activity)\"},{\"term\":\"efikasite\",\"arContext\":\"الفعالية القصوى (efficacy)\"}],\"hints\":[{\"tr\":\"Bir anahtarın kilide girmesi (afinite) ile kilidi çevirebilmesi (efikasite) arasındaki farkı hayal edin.\",\"ar\":\"تخيل الفارق بين دخول المفتاح في القفل (الألفة) وقدرته على إدارة القفل لفتحه (الفاعلية).\",\"en\":\"Envision the difference between a key fitting into a lock (affinity) and turning the cylinder (efficacy).\"},{\"tr\":\"Kusursuz oturan ama dönmeyen sahte bir anahtar kilidi kilitler: Bu bir antagonisttir.\",\"ar\":\"المفتاح الذي يطابق القفل تماماً لكنه لا يدور يعطل الباب: هذا هو المضاد التنافسي.\",\"en\":\"A key that fits perfectly but cannot turn jams the deadbolt: this is an antagonist.\"},{\"tr\":\"Afinite bağlanmayı belirler; reseptörü konformasyonel olarak aktive edip yanıt doğurmak ise intrinsik aktivite (alfa) gerektirir.\",\"ar\":\"الألفة تضمن الالتصاق؛ وتشغيل المستقبل يتطلب فاعلية ذاتية مستقلة (alfa).\",\"en\":\"Affinity governs docking; conformational activation requires independent intrinsic activity (alpha).\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":6}],\"config\":{\"options\":[{\"id\":\"opt-6a\",\"text\":\"Hayır; afinite sadece bağlanma gücünü (Kd) belirler, oysa yanıt oluşturabilmek için ilacın intrinsik aktiviteye (alfa / efikasite) sahip olması gerekir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Ariëns (1954) afinite ile intrinsik aktiviteyi (alfa) ayırmıştır. Bir antagonist (örn. nalokson) pikomolar afiniteyle bağlanabilir ama alfa = 0 olduğu için sıfır sinyal üretir (Slayt 34).\"},{\"id\":\"opt-6b\",\"text\":\"Evet; Clark teorisine göre işgal edilen her reseptör istisnasız %100 tam biyolojik sinyal üretmek zorundadır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Klasik teori yanılgısı: Clark'ın işgal teorisi (1926) antagonistlerin varlığını açıklayamadığı için terk edilmiştir; Ariëns ve Stephenson intrinsik aktivite kavramını getirmiştir.\"},{\"id\":\"opt-6c\",\"text\":\"Evet; yüksek afiniteli moleküller kovalent bağ kurarak reseptörü daima tam güçle aktive eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Afinite-kovalent karışıklığı: Yüksek afinite kovalent bağ demek değildir; reversible non-kovalent bağlarla da pikomolar afinite sağlanabilir ve bu aktivasyonu garanti etmez.\"}],\"revealedOutcome\":{\"tr\":\"Afinite (Kd) ile Efikasite (alfa) iki bağımsız parametredir. Antagonistlerin afinitesi çok yüksek olabilir (alfa = 0); parsiyel agonistler submaksimal etki üretir (0 < alfa < 1).\",\"ar\":\"الألفة (Kd) والفاعلية الذاتية (alfa) عاملان مستقلان؛ يملك المضاد ألفة عالية مع alfa = 0، والمنبه الجزئي يملك 0 < alfa < 1.\",\"en\":\"Affinity (Kd) and Intrinsic Efficacy (alpha) are orthogonal parameters. Antagonists possess high affinity with alpha = 0; partial agonists yield 0 < alpha < 1.\"},\"explanation\":{\"tr\":\"Ariëns teorisi farmakolojik yanıtı E / Emax = alfa * [DR] / [Rtotal] olarak formüle eder. Tam agonistte alfa = 1, parsiyel agonistte 0 < alfa < 1, kompetitif antagonistte ise alfa = 0'dır (Slayt 34).\",\"ar\":\"صاغ Ariëns الاستجابة بالمعادلة: E / Emax = alfa * [DR] / [Rtotal]. للمنبه الكامل alfa = 1، وللمنبه الجزئي 0 < alfa < 1، وللمضاد alfa = 0 (شريحة 34).\",\"en\":\"Ariëns formalized response as E / Emax = alpha * [DR] / [Rtotal]. Full agonists exhibit alpha = 1, partial agonists 0 < alpha < 1, and antagonists alpha = 0.\"}}},{\"id\":\"pharm-mod1-les2-step-07\",\"stage\":\"formal_explanation\",\"stageIndex\":7,\"type\":\"formal_explanation\",\"title\":{\"tr\":\"Furchgott Teorisi: Yedek Reseptörler (Receptor Reserve)\",\"ar\":\"نظرية Furchgott: المستقبِلات الاحتياطية وفائض الحساسية\",\"en\":\"Furchgott Theory: Spare Receptors & Receptor Reserve\"},\"prompt\":{\"tr\":\"Furchgott'un Yedek Reseptör (Receptor Reserve) Teorisine göre, kalp kasında adrenalinin maksimum kasılma yanıtı (Emax) oluşturması için reseptörlerin ne kadarı işgal edilmelidir?\",\"ar\":\"وفق نظرية المستقبِلات الاحتياطية لـ Furchgott، كم تبلغ نسبة إشغال المستقبِلات اللازمة لإحداث أقصى استجابة تقلصية قلبية (Emax) بالأدرينالين؟\",\"en\":\"According to Furchgott's Spare Receptor Theory, what fraction of myocardial beta-1 receptors must be occupied by adrenaline to elicit Emax?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-7a\",\"text\":{\"tr\":\"Reseptörlerin yalnızca %1-5'inin işgal edilmesi tam maksimum kasılma cevabını (Emax) tetiklemek için yeterlidir; geriye kalan %95 yedek rezervdir.\",\"ar\":\"يكفي إشغال 1-5% فقط من المستقبِلات لإطلاق أقصى تقلص قلبي (Emax)؛ والـ 95% الباقية تمثل احتياطياً وظيفياً.\",\"en\":\"Occupying merely 1-5% of receptors suffices to elicit Emax; the remaining 95% constitute a functional spare receptor reserve.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Tebrikler! Slayt 34'te belirtildiği gibi dokularda hücresel sinyal amplifikasyonu (G-proteini, adenilat siklaz, cAMP kaskadı) sayesinde maksimum etki için havuzun sadece %1-5'inin uyarılması yeterlidir.\",\"ar\":\"أحسنت! بفضل التضخيم الخلوي للإشارة (بروتينات G، شلال cAMP)، يكفي تنبيه 1-5% من المستقبِلات لبلوغ الاستجابة القصوى (شريحة 34).\",\"en\":\"Bravo! Intracellular signal cascades (Gs -> adenylate cyclase -> cAMP) amplify signaling so that 1-5% occupancy drives 100% tissue response.\"}},{\"id\":\"opt-7b\",\"text\":{\"tr\":\"Dokudaki reseptör havuzunun tam olarak %100'ünün agonist ile kilitlenmesi şarttır.\",\"ar\":\"يُشترط قفل 100% تماماً من حوض المستقبِلات بالمنبه للوصول للاستجابة القصوى.\",\"en\":\"Exactly 100% of the receptor pool must be saturated with agonist to achieve maximum response.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"İşgal teorisi yanılgısı: Bu varsayım Clark'ın 1926 modeline aittir; Furchgott yedek reseptörlerin varlığını kanıtlayarak %100 işgal gerekmediğini göstermiştir.\",\"ar\":\"خطأ نظرية الإشغال: ينتمي هذا الافتراض لنموذج كلارك القديم؛ وأثبت Furchgott تجريبياً عدم الحاجة لإشغال 100%.\",\"en\":\"Clark assumption error: Furchgott disproved the requirement for 100% occupancy by demonstrating spare receptor reserves.\"}},{\"id\":\"opt-7c\",\"text\":{\"tr\":\"Emax cevabı için reseptörlerin en az %50'sinin (Kd kadar) işgal edilmesi zorunludur.\",\"ar\":\"يتطلب Emax إشغال ما لا يقل عن 50% من المستقبِلات (بما يعادل تركيز Kd).\",\"en\":\"Achieving Emax strictly mandates occupying at least 50% of targets (equivalent to Kd).\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"EC50 ve Kd karışıklığı: Yedek reseptör olan dokularda EC50 << Kd'dir. Yani yarı maksimal yanıt (%50 etki) %1'den bile az dolulukta elde edilebilir (Slayt 34).\",\"ar\":\"خلط EC50 بـ Kd: بوجود احتياطي وظيفي تكون EC50 أصغر بكثير من Kd؛ ويتحقق نصف التأثير بإشغال أقل من 1%.\",\"en\":\"EC50 vs Kd confusion: In spare receptor tissues, EC50 << Kd. A 50% response occurs at <1% receptor occupancy.\"}}]},\"technicalTerms\":[{\"term\":\"yedek reseptör (spare receptor)\",\"arContext\":\"المستقبِل الاحتياطي (spare receptor)\"},{\"term\":\"sinyal amplifikasyonu\",\"arContext\":\"تضخيم الإشارة الخلوية\"}],\"hints\":[{\"tr\":\"Kalp kasındaki adrenerjik sinyal iletimindeki kaskad çarpanını düşünün (tek bir reseptör binlerce cAMP üretir).\",\"ar\":\"فكر في معامل التضخيم المتسلسل في القلب (مستقبل مفرد يولد آلاف جزيئات cAMP).\",\"en\":\"Consider intracellular cascade multipliers in myocardium (one receptor activates thousands of cAMPs).\"},{\"tr\":\"Maksimum kasılma gücüne ulaşmak için tüm reseptörleri doldurmak gerekir mi?\",\"ar\":\"هل يلزم ملء كافة المستقبِلات للوصول إلى أقصى قوة انقباضية؟\",\"en\":\"Is full target occupancy required to exhaust the contractile machinery?\"},{\"tr\":\"Sadece %1-5 reseptör doluluğu Emax oluşturur; kalan %95 reseptör dokunun duyarlılığını artıran yedek rezervdir.\",\"ar\":\"إشغال 1-5% فقط يحقق Emax، والـ 95% الباقية هي احتياطي يضمن حساسية الخلية وسرعة استجابتها.\",\"en\":\"Only 1-5% occupancy yields Emax; remaining 95% are spare receptors ensuring high tissue sensitivity.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":6}],\"config\":{\"options\":[{\"id\":\"opt-7a\",\"text\":\"Reseptörlerin yalnızca %1-5'inin işgal edilmesi tam maksimum kasılma cevabını (Emax) tetiklemek için yeterlidir; geriye kalan %95 yedek rezervdir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Tebrikler! Slayt 34'te belirtildiği gibi dokularda hücresel sinyal amplifikasyonu (G-proteini, adenilat siklaz, cAMP kaskadı) sayesinde maksimum etki için havuzun sadece %1-5'inin uyarılması yeterlidir.\"},{\"id\":\"opt-7b\",\"text\":\"Dokudaki reseptör havuzunun tam olarak %100'ünün agonist ile kilitlenmesi şarttır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"İşgal teorisi yanılgısı: Bu varsayım Clark'ın 1926 modeline aittir; Furchgott yedek reseptörlerin varlığını kanıtlayarak %100 işgal gerekmediğini göstermiştir.\"},{\"id\":\"opt-7c\",\"text\":\"Emax cevabı için reseptörlerin en az %50'sinin (Kd kadar) işgal edilmesi zorunludur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"EC50 ve Kd karışıklığı: Yedek reseptör olan dokularda EC50 << Kd'dir. Yani yarı maksimal yanıt (%50 etki) %1'den bile az dolulukta elde edilebilir (Slayt 34).\"}],\"revealedOutcome\":{\"tr\":\"Furchgott teorisi: Miyokardda maksimum yanıt (Emax) için beta-1 reseptörlerinin %1-5'inin işgali yeterlidir. Geri kalan %95 yedek reseptör rezervidir.\",\"ar\":\"نظرية Furchgott: يكفي إشغال 1-5% من مستقبلات بيتا-1 لتحقيق أقصى استجابة قلبية، والـ 95% الباقية هي احتياطي وظيفي.\",\"en\":\"Furchgott Theory: 1-5% occupancy of myocardial beta-1 receptors produces Emax; the remaining 95% represent receptor reserve.\"},\"explanation\":{\"tr\":\"Yedek reseptör varlığında agonist doz-yanıt eğrisi reseptör bağlama eğrisinin soluna kayar (EC50 < Kd). Bu biyolojik mekanizma dokunun düşük hormon/ilaç derişimlerine bile maksimum yanıt verebilmesini sağlar (Slayt 34).\",\"ar\":\"بوجود مستقبِلات احتياطية، ينزاح منحنى الاستجابة إلى يسار منحنى الارتباط (EC50 < Kd)، مما يمنح النسيج حساسية فائقة للهرمونات والأدوية (شريحة 34).\",\"en\":\"Spare receptors shift the functional response curve to the left of the binding curve (EC50 < Kd), conferring exquisite tissue sensitivity.\"}}},{\"id\":\"pharm-mod1-les2-step-08\",\"stage\":\"concept_check\",\"stageIndex\":8,\"type\":\"concept_check\",\"title\":{\"tr\":\"Kavram Kontrolü: Rezidans Süresi ve Ayrışma Kinetiği\",\"ar\":\"تحقق المفهوم: زمن المكوث وحركية التفكك\",\"en\":\"Concept Check: Residence Time & Dissociation Kinetics\"},\"prompt\":{\"tr\":\"Bir ilacın ayrışma hız sabiti (koff) saniyede 0.001 s^-1 ise, bu ilacın reseptör üzerindeki ortalama kalış süresi (rezidans süresi, tau = 1/koff) ne kadardır?\",\"ar\":\"إذا كان ثابت سرعة تفكك دواء (koff) يساوي 0.001 s^-1، فكم يبلغ متوسط زمن مكوثه على المستقبل (tau = 1/koff)؟\",\"en\":\"If a drug's dissociation rate constant (koff) is 0.001 s^-1, what is the mean drug-target residence time (tau = 1/koff)?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-8a\",\"text\":{\"tr\":\"1000 saniye (yaklaşık 16.6 dakika); yavaş ayrışma oranı uzun bir rezidans süresi ve sustained farmakolojik etki sağlar.\",\"ar\":\"1000 ثانية (قرابة 16.6 دقيقة)؛ يوفر معدل التفكك البطيء زمن مكوث مديد وتأثيراً دوائياً مستداماً.\",\"en\":\"1000 seconds (~16.6 minutes); a slow off-rate confers long residence time and sustained target coverage.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz hesaplama! Rezidans süresi tau = 1 / koff formülüyle hesaplanır: 1 / 0.001 s^-1 = 1000 saniye. Plazma konsantrasyonu düşse bile ilaç reseptörde kalarak etkiyi sürdürür (Slayt 34).\",\"ar\":\"حساب دقيق! يحسب زمن المكوث بالمعادلة: tau = 1 / koff = 1000 ثانية. يستمر التأثير حتى لو انخفض تركيز الدواء في البلازما.\",\"en\":\"Flawless computation! Residence time tau = 1/koff = 1000 seconds. Target inhibition persists even after plasma drug washout.\"}},{\"id\":\"opt-8b\",\"text\":{\"tr\":\"0.001 saniye (1 milisaniye); molekül reseptörden anında fırlar.\",\"ar\":\"0.001 ثانية (1 ميلي ثانية)؛ ينفلت الجزيء من المستقبل على الفور.\",\"en\":\"0.001 seconds (1 millisecond); the ligand instantly dissociates from the binding pocket.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Formül tersliği yanılgısı: Rezidans süresi koff'un kendisi değil, çarpmaya göre tersidir (tau = 1 / koff). 0.001 s^-1 ayrışma hızı çok yavaş bir ayrılmayı gösterir.\",\"ar\":\"خطأ مقلوب القانون: زمن المكوث هو مقلوب koff وليس قيمته المجردة؛ فمعدل 0.001 يعني تفككاً بطيئاً جداً.\",\"en\":\"Reciprocal error: Residence time is the reciprocal of off-rate (tau = 1/koff), representing a long 1000-second occupancy.\"}},{\"id\":\"opt-8c\",\"text\":{\"tr\":\"0.693 saniye; rezidans süresi ilacın reseptör yarı ömrüne (t1/2) eşittir ve formülü tau = ln(2) * koff şeklindedir.\",\"ar\":\"0.693 ثانية؛ متوسط زمن المكوث يطابق العمر النصفي (t1/2) وصيغته tau = ln(2) * koff.\",\"en\":\"0.693 seconds; residence time is identical to the dissociation half-life (t1/2) and is calculated as tau = ln(2) * koff.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yarı ömür ve tau karışıklığı: Rezidans süresi tau = 1 / koff'tur (1000 saniye); ayrışma yarı ömrü ise t1/2 = ln(2) / koff = 693 saniyedir. koff ile ln(2) çarpılmaz, bölünür.\",\"ar\":\"مغالطة الخلط بين tau والعمر النصفي: زمن المكوث هو tau = 1 / koff (1000 ثانية)؛ أما العمر النصفي فهو t1/2 = ln(2)/koff (693 ثانية).\",\"en\":\"Half-life vs tau confusion: Mean residence time tau = 1/koff (1000 s); dissociation half-life is t1/2 = ln(2)/koff (693 s).\"}}]},\"technicalTerms\":[{\"term\":\"rezidans süresi (tau)\",\"arContext\":\"زمن المكوث (residence time)\"},{\"term\":\"ayrışma kinetiği (koff)\",\"arContext\":\"حركية التفكك (koff)\"}],\"hints\":[{\"tr\":\"Rezidans süresi formülünü hatırlayın: tau = 1 / koff.\",\"ar\":\"تذكر معادلة زمن المكوث: tau = 1 / koff.\",\"en\":\"Recall the target residence time equation: tau = 1 / koff.\"},{\"tr\":\"1 sayısını 0.001'e bölün: 1 / 10^-3 = ?\",\"ar\":\"اقسم الرقم 1 على 0.001: 1 / (1/1000) = ؟\",\"en\":\"Divide 1 by 0.001: 1 / 10^-3 = ?\"},{\"tr\":\"Sonuç 1000 saniyedir (yaklaşık 16.6 dakika).\",\"ar\":\"النتيجة هي 1000 ثانية (ما يقارب 16.6 دقيقة).\",\"en\":\"The calculation yields 1000 seconds (~16.6 minutes).\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":4}],\"config\":{\"options\":[{\"id\":\"opt-8a\",\"text\":\"1000 saniye (yaklaşık 16.6 dakika); yavaş ayrışma oranı uzun bir rezidans süresi ve sustained farmakolojik etki sağlar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz hesaplama! Rezidans süresi tau = 1 / koff formülüyle hesaplanır: 1 / 0.001 s^-1 = 1000 saniye. Plazma konsantrasyonu düşse bile ilaç reseptörde kalarak etkiyi sürdürür (Slayt 34).\"},{\"id\":\"opt-8b\",\"text\":\"0.001 saniye (1 milisaniye); molekül reseptörden anında fırlar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Formül tersliği yanılgısı: Rezidans süresi koff'un kendisi değil, çarpmaya göre tersidir (tau = 1 / koff). 0.001 s^-1 ayrışma hızı çok yavaş bir ayrılmayı gösterir.\"},{\"id\":\"opt-8c\",\"text\":\"0.693 saniye; rezidans süresi ilacın reseptör yarı ömrüne (t1/2) eşittir ve formülü tau = ln(2) * koff şeklindedir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yarı ömür ve tau karışıklığı: Rezidans süresi tau = 1 / koff'tur (1000 saniye); ayrışma yarı ömrü ise t1/2 = ln(2) / koff = 693 saniyedir. koff ile ln(2) çarpılmaz, bölünür.\"}],\"revealedOutcome\":{\"tr\":\"Rezidans süresi tau = 1 / koff = 1 / 0.001 s^-1 = 1000 saniyedir (~16.6 dakika). Yavaş koff katsayısı ilacın hedefte uzun süre kalarak etki göstermesini sağlar.\",\"ar\":\"زمن المكوث tau = 1 / koff = 1000 ثانية (~16.6 دقيقة). يتيح معدل التفكك البطيء بقاء الدواء على الهدف واستمرار فاعليته.\",\"en\":\"Residence time tau = 1/koff = 1000 seconds (~16.6 minutes). Slow off-rates prolong target engagement independent of plasma half-life.\"},\"explanation\":{\"tr\":\"Modern ilaç keşfinde rezidans süresi (tau) afinite kadar kritik bir parametredir. Yavaş ayrışan ilaçlar (düşük koff), plazma yarı ömrü kısa olsa dahi reseptör üzerinde uzun süre kalarak günde tek doz kullanım konforu sağlar (Slayt 34).\",\"ar\":\"في علم الأدوية الحديث، يعتبر زمن المكوث (tau) معياراً حيوياً كالألفة؛ فالأدوية بطيئة التفكك تدوم فاعليتها على المستقبل طويلاً حتى بعد زوالها من البلازما (شريحة 34).\",\"en\":\"Modern drug discovery emphasizes residence time (tau = 1/koff). Drugs with slow off-rates sustain pharmacodynamic efficacy long after plasma clearance.\"}}},{\"id\":\"pharm-mod1-les2-step-09\",\"stage\":\"application\",\"stageIndex\":9,\"type\":\"clinical_vignette\",\"title\":{\"tr\":\"Klinik Protokol: Buprenorfin İndüksiyonu ve COWS Skoru\",\"ar\":\"بروتوكول سريري: بدء علاج البوبرينورفين ومقياس COWS\",\"en\":\"Clinical Protocol: Buprenorphine Induction & COWS Score\"},\"prompt\":{\"tr\":\"Metadon idamesindeki bir hastaya yoksunluk krizini tetiklemeden buprenorfin başlanmak isteniyor. Klinik farmakolojiye göre buprenorfin uygulaması ne zaman başlatılmalıdır?\",\"ar\":\"لمريض خاضع لعلاج الميثادون، يراد البدء بالبوبرينورفين دون تحفيز متلازمة انسحاب مفاجئة. متى يجب إعطاء الجرعة سريرياً؟\",\"en\":\"In a patient maintained on methadone, how should buprenorphine induction be timed to avoid precipitating acute opioid withdrawal?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-9a\",\"text\":{\"tr\":\"Hastada orta derecede objektif morfin/metadon yoksunluk belirtileri (COWS skoru > 12) başlayıp reseptör doluluğu doğal olarak düştükten sonra.\",\"ar\":\"بعد بدء ظهور أعراض انسحاب موضوعية معتدلة (مقياس COWS > 12) وهبوط إشغال المستقبِلات طبيعياً.\",\"en\":\"Only after objective opioid withdrawal appears (COWS score > 12), ensuring mu-receptor occupancy has naturally cleared.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Hayati bir klinik kural! Buprenorfin ancak reseptör havuzundaki tam agonist konsantrasyonu düşüp hasta hafif yoksunluğa girdiğinde verilir. Aksi halde morfini anında kovar ve feci bir kriz patlatır.\",\"ar\":\"قاعدة سريرية ذهبية! لا يُعطى البوبرينورفين إلا بعد تراجع إشغال المنبه الكامل وبدء الانسحاب؛ وإلا طرد المورفين مفجراً أزمة انسحابية عنيفة.\",\"en\":\"Vital clinical dogma! Buprenorphine must only be introduced when receptor occupancy has declined; giving it prematurely triggers severe precipitated withdrawal.\"}},{\"id\":\"opt-9b\",\"text\":{\"tr\":\"Hasta son metadon dozunu alır almaz, tam kanda metadon konsantrasyonu en yüksek zirvedeyken (Cmax).\",\"ar\":\"فور تناول المريض آخر جرعة ميثادون، في ذروة تركيزه بالبلازما (Cmax).\",\"en\":\"Immediately following the last methadone dose, precisely at peak plasma concentration (Cmax).\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Ölümcül klinik hata: Cmax anında reseptörler %100 metadon ile doludur. Buprenorfin verilirse metadonu kovar ve net sinyali anında %35'e düşürerek en şiddetli krizi başlatır.\",\"ar\":\"خطأ سريري فادح: عند ذروة Cmax تكون المستقبِلات ممتلئة بالميثادون؛ إعطاء البوبرينورفين يطرده فوراً ويفجر نوبة انسحاب مروعة.\",\"en\":\"Catastrophic error: At Cmax, receptors are saturated with full agonist. Buprenorphine will displace it, precipitating acute withdrawal.\"}},{\"id\":\"opt-9c\",\"text\":{\"tr\":\"Yüksek doz nalokson infüzyonuyla tüm reseptörler kovalent olarak yok edildikten 24 saat sonra.\",\"ar\":\"بعد مرور 24 ساعة على تدمير كافة المستقبِلات تساهمياً بجرعة عالية من النالوكسون.\",\"en\":\"24 hours after destroying all mu receptors covalently via high-dose intravenous naloxone.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Mekanizma saçmalığı: Nalokson kovalent değildir (reversibl kompetitif antagonisttir) ve elektif indüksiyonda böyle bir uygulama kontrendikedir.\",\"ar\":\"خطأ بيولوجي: النالوكسون مضاد عكوس وليس تساهمياً مدمراً؛ ومثل هذا الإجراء غير مقبول سريرياً.\",\"en\":\"Pharmacological absurdity: Naloxone is a reversible competitive antagonist, not a covalent receptor-destroying toxin.\"}}]},\"technicalTerms\":[{\"term\":\"COWS skoru (Klinik Opioid Yoksunluk Skalası)\",\"arContext\":\"مقياس COWS للانسحاب الأفيوني السريري\"},{\"term\":\"buprenorfin indüksiyonu\",\"arContext\":\"بدء المعالجة بالبوبرينورفين\"}],\"hints\":[{\"tr\":\"Buprenorfinin reseptördeki tam agonistleri (metadon/morfin) kovan yüksek afinitesini hatırlayın.\",\"ar\":\"تذكر ألفة البوبرينورفين الفائقة التي تطرد المنبهات الكاملة كالميثادون والمورفين.\",\"en\":\"Remember buprenorphine's fierce affinity displacing full agonists from mu receptors.\"},{\"tr\":\"Eğer reseptörler hala metadon ile doluysa, buprenorfin verilince ne olur?\",\"ar\":\"إذا كانت المستقبِلات ما تزال ممتلئة بالميثادون، ماذا يحدث فور دخول البوبرينورفين؟\",\"en\":\"If receptors remain fully occupied by methadone, what happens when buprenorphine enters?\"},{\"tr\":\"Metadonun reseptörden doğal olarak ayrışması ve hastanın hafif yoksunluğa girmesi (COWS > 12) beklenmelidir.\",\"ar\":\"يجب انتظار انفصال الميثادون طبيعياً ودخول المريض في انسحاب خفيف (COWS > 12).\",\"en\":\"Wait until methadone dissociates and objective withdrawal develops (COWS > 12).\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":6}],\"config\":{\"options\":[{\"id\":\"opt-9a\",\"text\":\"Hastada orta derecede objektif morfin/metadon yoksunluk belirtileri (COWS skoru > 12) başlayıp reseptör doluluğu doğal olarak düştükten sonra.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Hayati bir klinik kural! Buprenorfin ancak reseptör havuzundaki tam agonist konsantrasyonu düşüp hasta hafif yoksunluğa girdiğinde verilir. Aksi halde morfini anında kovar ve feci bir kriz patlatır.\"},{\"id\":\"opt-9b\",\"text\":\"Hasta son metadon dozunu alır almaz, tam kanda metadon konsantrasyonu en yüksek zirvedeyken (Cmax).\",\"isCorrect\":false,\"misconceptionFeedback\":\"Ölümcül klinik hata: Cmax anında reseptörler %100 metadon ile doludur. Buprenorfin verilirse metadonu kovar ve net sinyali anında %35'e düşürerek en şiddetli krizi başlatır.\"},{\"id\":\"opt-9c\",\"text\":\"Yüksek doz nalokson infüzyonuyla tüm reseptörler kovalent olarak yok edildikten 24 saat sonra.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Mekanizma saçmalığı: Nalokson kovalent değildir (reversibl kompetitif antagonisttir) ve elektif indüksiyonda böyle bir uygulama kontrendikedir.\"}],\"revealedOutcome\":{\"tr\":\"Buprenorfin indüksiyonu için altın kural: Hastanın hafif/orta yoksunlukta (COWS > 12) olması beklenir. Böylece reseptör doluluğu düşmüş olur ve buprenorfin agonist gibi davranarak hastayı rahatlatır.\",\"ar\":\"القاعدة الذهبية لبدء البوبرينورفين: انتظار دخول المريض في انسحاب معتدل (COWS > 12)؛ ليعمل البوبرينورفين كمنبه يريح المريض بدلاً من طرد الدواء السابق.\",\"en\":\"Golden induction rule: wait for mild-moderate withdrawal (COWS > 12). With low baseline occupancy, buprenorphine acts as an agonist, relieving symptoms.\"},\"explanation\":{\"tr\":\"Hasta tam agonist etkisi altındayken parsiyel agonist verilirse antagonizma oluşur. Hasta yoksunluktayken verilirse parsiyel agonizm net stimülasyonu sıfırdan %35'e çıkararak tedavi edici olur (Slayt 34).\",\"ar\":\"إعطاء المنبه الجزئي بوجود منبه كامل يولد مناهضة (انسحاب حاد). أما إعطاؤه أثناء الانسحاب فيرفع التنبيه من الصفر إلى 35% فيحقق الشفاء (شريحة 34).\",\"en\":\"Administering a partial agonist during full agonism causes functional antagonism. Giving it during withdrawal elevates activation from 0 to 35%, providing therapeutic relief.\"}}},{\"id\":\"pharm-mod1-les2-step-10\",\"stage\":\"retrieval\",\"stageIndex\":10,\"type\":\"retrieval\",\"title\":{\"tr\":\"Geri Çağırma: Kompetitif Antagonizma Eğri Kayması\",\"ar\":\"استرجاع: إزاحة منحنى المناهضة التنافسية\",\"en\":\"Active Recall: Competitive Antagonist Surmountable Shift\"},\"prompt\":{\"tr\":\"Kompetitif bir antagonist (örn. nalokson) sisteme eklendiğinde, agonist doz-yanıt eğrisinde nasıl bir değişim gözlenir?\",\"ar\":\"عند إضافة مضاد تنافسي (مثل نالوكسون) إلى النظام، ما التغير الملاحظ على منحنى الجرعة والاستجابة للمنبه؟\",\"en\":\"When a competitive antagonist (e.g., naloxone) is introduced, what distinct shift occurs in the agonist dose-response curve?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-10a\",\"text\":{\"tr\":\"Eğri Emax yüksekliği değişmeksizin paralel olarak sağa kayar; artan agonist konsantrasyonu antagonisti tamamen yenebilir (surmountable).\",\"ar\":\"ينزاح المنحنى يميناً بشكل موازٍ دون أي هبوط في Emax؛ ويمكن للجرعات العالية من المنبه التغلب على المضاد كلياً.\",\"en\":\"The curve shifts in parallel to the right with unchanged Emax; higher agonist concentrations fully surmount antagonism.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Kompetitif antagonist aynı bağlanma bölgesi için yarışır. Yeterince agonist verilirse antagonist reseptörden kovulur ve Emax korunur (surmountable antagonizma) (Slayt 34).\",\"ar\":\"صحيح! ينافس المضاد التنافسي على نفس الموقع؛ وبزيادة تركيز المنبه يُطرد المضاد ويبقى Emax ثابتاً (مناهضة يمكن التغلب عليها) (شريحة 34).\",\"en\":\"Correct! Competitive antagonists compete for the same pocket. Escalating agonist concentrations outcompete the blocker, fully restoring Emax.\"}},{\"id\":\"opt-10b\",\"text\":{\"tr\":\"Emax tavanı yarıya iner fakat EC50 değeri sola kayar.\",\"ar\":\"يهبط سقف Emax إلى النصف بينما ينزاح EC50 إلى اليسار.\",\"en\":\"The Emax ceiling is halved while the EC50 value shifts to the left.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Nonkompetitif ayrımı yanılgısı: Emax'ı düşüren nonkompetitif veya geri dönüşümsüz antagonistlerdir. Kompetitif antagonist Emax tavanını asla düşürmez.\",\"ar\":\"خطأ التمييز عن غير التنافسي: انخفاض Emax خاص بالمضادات غير التنافسية أو التساهمية؛ أما التنافسي فيحافظ على Emax.\",\"en\":\"Noncompetitive confusion: Emax depression is the hallmark of noncompetitive or irreversible antagonism; competitive blockers preserve Emax.\"}},{\"id\":\"opt-10c\",\"text\":{\"tr\":\"Eğri sola kayar çünkü antagonist agonistin afinitesini allosterik olarak 10 kat artırır.\",\"ar\":\"ينزاح المنحنى لليسار لأن المضاد يرفع ألفة المنبه بنحو عشرة أضعاف تباعدياً.\",\"en\":\"The curve shifts to the left because the antagonist allosterically enhances agonist affinity 10-fold.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yön yanılgısı: Antagonist yarışarak agonistin görünür potansını düşürür ve eğriyi sağa iter (daha yüksek agonist konsantrasyonu gerekir); sola kaydırma agonist veya PAM özelliğidir.\",\"ar\":\"خطأ اتجاه الإزاحة: ينافس المضاد المنبه فيخفض فاعليته الظاهرية ويدفعه يميناً، بينما الإزاحة لليسار تخص المنبهات أو المعدلات الإيجابية.\",\"en\":\"Direction error: Antagonists demand higher agonist concentrations to achieve effects, shifting curves rightward, never leftward.\"}}]},\"technicalTerms\":[{\"term\":\"kompetitif antagonizma\",\"arContext\":\"المناهضة التنافسية (competitive antagonism)\"},{\"term\":\"aşılabilir blokaj (surmountable)\",\"arContext\":\"حصار قابل للتغلب عليه\"}],\"hints\":[{\"tr\":\"İki ligand aynı reseptör cebi için yarışıyor; birinin miktarını devasa artırırsanız ne olur?\",\"ar\":\"يتنافس ربيطان على نفس جيب المستقبل؛ ماذا يحدث لو ضاعفت تركيز أحدهما لدرجة هائلة؟\",\"en\":\"Two ligands compete for the same pocket; what happens if you massively increase agonist concentration?\"},{\"tr\":\"Yüksek agonist konsantrasyonu kompetitif antagonisti kovar ve maksimum cevaba yine ulaşılır.\",\"ar\":\"يطرد التركيز العالي من المنبه المضاد التنافسي، ويمكن الوصول للاستجابة القصوى مجدداً.\",\"en\":\"High agonist concentrations displace competitive blockers, fully restoring maximal response.\"},{\"tr\":\"Emax değişmez, eğri paralel olarak sağa kayar (surmountable antagonizma).\",\"ar\":\"يبقى Emax ثابتاً، وينزاح المنحنى بشكل موازٍ إلى اليمين.\",\"en\":\"Emax remains unaltered while the curve shifts parallel to the right.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":4}],\"config\":{\"options\":[{\"id\":\"opt-10a\",\"text\":\"Eğri Emax yüksekliği değişmeksizin paralel olarak sağa kayar; artan agonist konsantrasyonu antagonisti tamamen yenebilir (surmountable).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Kompetitif antagonist aynı bağlanma bölgesi için yarışır. Yeterince agonist verilirse antagonist reseptörden kovulur ve Emax korunur (surmountable antagonizma) (Slayt 34).\"},{\"id\":\"opt-10b\",\"text\":\"Emax tavanı yarıya iner fakat EC50 değeri sola kayar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Nonkompetitif ayrımı yanılgısı: Emax'ı düşüren nonkompetitif veya geri dönüşümsüz antagonistlerdir. Kompetitif antagonist Emax tavanını asla düşürmez.\"},{\"id\":\"opt-10c\",\"text\":\"Eğri sola kayar çünkü antagonist agonistin afinitesini allosterik olarak 10 kat artırır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yön yanılgısı: Antagonist yarışarak agonistin görünür potansını düşürür ve eğriyi sağa iter (daha yüksek agonist konsantrasyonu gerekir); sola kaydırma agonist veya PAM özelliğidir.\"}],\"revealedOutcome\":{\"tr\":\"Kompetitif antagonistler agonist eğrisini paralel sağa kaydırır (EC50 artar); ancak Emax korunur çünkü aşırı agonist antagonisti yener (surmountable).\",\"ar\":\"تزيح المضادات التنافسية منحنى المنبه يميناً بشكل موازٍ (يزداد EC50) مع بقاء Emax ثابتاً لإمكانية التغلب على الحصار بالجرعات العالية.\",\"en\":\"Competitive antagonists cause a parallel rightward shift in the agonist curve (increased EC50) without depressing Emax (surmountable antagonism).\"},\"explanation\":{\"tr\":\"Schild analizi prensiplerine göre kompetitif antagonizmada agonist ve antagonist aynı reseptör bölgesi için yarışır. Ortamdaki serbest agonist arttıkça fraksiyonel işgal agoniste döner ve maksimum yanıt korunur (Slayt 34).\",\"ar\":\"وفق تحليل Schild، يتنافس المنبه والمضاد على الموقع ذاته؛ وبرفع تركيز المنبه يتحول إشغال المستقبِلات لصالحه ويُستعاد Emax بالكامل (شريحة 34).\",\"en\":\"Per Schild analysis, competitive ligands vie for identical binding sites. Elevating agonist concentration outcompetes the antagonist, preserving Emax.\"}}},{\"id\":\"pharm-mod1-les2-step-11\",\"stage\":\"connection\",\"stageIndex\":11,\"type\":\"connection\",\"title\":{\"tr\":\"Kavramsal Köprü: Kovalent Blokaj ve Yedek Reseptör Tükenişi\",\"ar\":\"جسر المفاهيم: الحصار التساهمي ونفاد الاحتياطي الوظيفي\",\"en\":\"Conceptual Bridge: Covalent Blockade & Spare Receptor Depletion\"},\"prompt\":{\"tr\":\"Fenoksibenzamin gibi geri dönüşümsüz (kovalent) bir alfa bloker dokuya uygulandığında, yedek reseptör rezervi tükenene kadar agonist eğrisinde ne gözlenir?\",\"ar\":\"عند تطبيق حاصر ألفا تساهمي غير عكوس (فينوكسي بنزامين)، ماذا يطرأ على منحنى المنبه حتى يستنفد الاحتياطي الوظيفي تماماً؟\",\"en\":\"When an irreversible covalent blocker (phenoxybenzamine) is applied, what happens to the agonist curve before the spare receptor reserve is exhausted?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-11a\",\"text\":{\"tr\":\"Emax düşmez, eğri başlangıçta paralel sağa kayar; ancak tüm yedek reseptörler kovalent bloke olunca Emax çökmeye başlar.\",\"ar\":\"لا ينخفض Emax وينزاح المنحنى يميناً في البداية؛ لكن بمجرد نفاد الاحتياطي الوظيفي يبدأ سقف Emax بالانهيار.\",\"en\":\"Emax is initially preserved and the curve shifts rightward; only when the receptor reserve is fully exhausted does Emax collapse.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika bir köprü! Furchgott'un klasik deneyinde fenoksibenzamin kademeli olarak reseptörleri kovalent yok eder. Yedek reseptörler tükenene kadar kalan serbest reseptörler %100 yanıt verebilir; rezerv bitince Emax düşer (Slayt 34).\",\"ar\":\"ربط رائع للمفاهيم! في تجارب Furchgott يُعطل الفينوكسي بنزامين المستقبِلات تساهمياً؛ وطالما وُجد احتياطي يتحقق Emax، حتى ينفد الاحتياطي فيهبط السقف (شريحة 34).\",\"en\":\"Brilliant bridge! In Furchgott's experiments, phenoxybenzamine alkylates alpha receptors. Emax holds until the spare reserve is exhausted; only then does efficacy drop.\"}},{\"id\":\"opt-11b\",\"text\":{\"tr\":\"İlk molekül bağlandığı anda Emax anında sıfırlanır ve agonist hiçbir kasılma oluşturamaz.\",\"ar\":\"فور ارتباط أول جزيء يهبط Emax للصفر مباشرة ويعجز المنبه عن إحداث أي استجابة.\",\"en\":\"Upon binding the first blocker molecule, Emax instantly drops to zero, abolishing all agonist contraction.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Rezerv yok sayma yanılgısı: Dokuda %90 yedek reseptör varsa, ilacın reseptörlerin %50'sini kovalent kitlemesi bile Emax'ı düşürmez; kalan %50 tam yanıt vermeye yeterlidir.\",\"ar\":\"خطأ إغفال الاحتياطي: بوجود 90% مستقبِلات احتياطية، فإن حجب 50% منها لن ينقص Emax لأن الـ 50% الباقية كافية للاستجابة القصوى.\",\"en\":\"Spare receptor denial: If a tissue has a 90% reserve, alkylating 50% of receptors leaves ample spare targets to still achieve 100% Emax.\"}},{\"id\":\"opt-11c\",\"text\":{\"tr\":\"Eğri sola kayar çünkü kovalent blokaj diğer reseptörlerin afinitesini 100 kat artırır.\",\"ar\":\"ينزاح المنحنى لليسار لأن الحصار التساهمي يرفع ألفة باقي المستقبِلات بمئة ضعف.\",\"en\":\"The curve shifts leftward because covalent blockade allosterically boosts affinity of remaining targets 100-fold.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Afinite artışı yanılgısı: Kovalent blokaj kalan reseptörlerin afinitesini artırmaz; sadece toplam işlevsel reseptör havuzunu eksiltir.\",\"ar\":\"خطأ زيادة الألفة: لا يرفع الحصار التساهمي ألفة باقي المستقبِلات، بل ينقص العدد الكلي للمستقبِلات العاملة فقط.\",\"en\":\"Affinity fantasy: Irreversible alkylation decreases functional target numbers; it never augments receptor affinity.\"}}]},\"technicalTerms\":[{\"term\":\"fenoksibenzamin\",\"arContext\":\"فينوكسي بنزامين\"},{\"term\":\"geri dönüşümsüz (non-surmountable) blokaj\",\"arContext\":\"حصار غير عكوس وغير قابل للتغلب عليه\"}],\"hints\":[{\"tr\":\"Dokuda %95 yedek reseptör olduğunu ve kovalent blokerin reseptörlerin %50'sini öldürdüğünü varsayın.\",\"ar\":\"افترض وجود 95% مستقبِلات احتياطية، وقام الحاصر التساهمي بتعطيل 50% منها.\",\"en\":\"Assume a 95% receptor reserve and an irreversible blocker disabling 50% of total targets.\"},{\"tr\":\"Geriye kalan %45'lik reseptör havuzu, tam etki için gereken %5'i karşılayabilir mi?\",\"ar\":\"هل يكفي الـ 45% المتبقي من المستقبِلات لتغطية الـ 5% اللازمة للاستجابة القصوى؟\",\"en\":\"Does the remaining 45% pool suffice to deliver the 5% needed for full Emax?\"},{\"tr\":\"Evet, karşılar! Emax korunur ve eğri sağa kayar; ancak blokaj rezervi aşınca Emax çöker.\",\"ar\":\"نعم تكفي وزيادة! يبقى Emax ثابتاً وينزاح المنحنى يميناً، حتى يتجاوز الحصار نسبة الاحتياطي فيهبط Emax.\",\"en\":\"Yes! Emax is preserved and shifts right until blockade exceeds the spare threshold, collapsing Emax.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":4},{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":6}],\"config\":{\"options\":[{\"id\":\"opt-11a\",\"text\":\"Emax düşmez, eğri başlangıçta paralel sağa kayar; ancak tüm yedek reseptörler kovalent bloke olunca Emax çökmeye başlar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika bir köprü! Furchgott'un klasik deneyinde fenoksibenzamin kademeli olarak reseptörleri kovalent yok eder. Yedek reseptörler tükenene kadar kalan serbest reseptörler %100 yanıt verebilir; rezerv bitince Emax düşer (Slayt 34).\"},{\"id\":\"opt-11b\",\"text\":\"İlk molekül bağlandığı anda Emax anında sıfırlanır ve agonist hiçbir kasılma oluşturamaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Rezerv yok sayma yanılgısı: Dokuda %90 yedek reseptör varsa, ilacın reseptörlerin %50'sini kovalent kitlemesi bile Emax'ı düşürmez; kalan %50 tam yanıt vermeye yeterlidir.\"},{\"id\":\"opt-11c\",\"text\":\"Eğri sola kayar çünkü kovalent blokaj diğer reseptörlerin afinitesini 100 kat artırır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Afinite artışı yanılgısı: Kovalent blokaj kalan reseptörlerin afinitesini artırmaz; sadece toplam işlevsel reseptör havuzunu eksiltir.\"}],\"revealedOutcome\":{\"tr\":\"Geri dönüşümsüz antagonistler yedek reseptör rezervi tükenene kadar Emax'ı düşürmeden eğriyi sağa kaydırır. Rezerv aşıldığında ise aşılmaz (insurmountable) Emax çöküşü başlar.\",\"ar\":\"تزيح المضادات غير العكوسة المنحنى يميناً دون إنقاص Emax طالما وُجد احتياطي وظيفي؛ وبمجرد استنفاد الاحتياطي يبدأ انهيار Emax الحتمي.\",\"en\":\"Irreversible antagonists initially shift agonist curves rightward with preserved Emax; once the spare reserve is exhausted, insurmountable Emax depression occurs.\"},\"explanation\":{\"tr\":\"Furchgott'un yedek reseptör teorisinin deneysel kanıtı fenoksibenzamin ile yapılmıştır. Kovalent alkilasyon reseptör sayısını azaltsa da, geriye kalan reseptörler doku amplifikasyonuyla tam yanıt oluşturmaya devam eder (Slayt 10, 34).\",\"ar\":\"أُثبتت نظرية Furchgott تجريبياً باستخدام الفينوكسي بنزامين؛ فرغم تناقص المستقبِلات بالألكلة التساهمية، تكفي البقية لتوليد استجابة تامة بفضل التضخيم الخلوي (شريحة 10، 34).\",\"en\":\"Furchgott validated spare receptor theory using phenoxybenzamine: covalent target alkylation reduces target pools, yet remaining receptors sustain 100% Emax via signal amplification.\"}}},{\"id\":\"pharm-mod1-les2-step-12\",\"stage\":\"mastery_check\",\"stageIndex\":12,\"type\":\"mastery_check\",\"title\":{\"tr\":\"Ustalık Sınavı: Parsiyel Agonistin Çift Yüzlü Doğası\",\"ar\":\"اختبار الإتقان: الطبيعة المزدوجة للمنبه الجزئي\",\"en\":\"Mastery Check: Dual Nature of Partial Agonists\"},\"prompt\":{\"tr\":\"Bir hastada kalp yetmezliği için parsiyel beta-1 agonisti xamoterol veriliyor. Dinlenim halinde nabzı artarken, egzersiz sırasında neden tam tersine taşikardiyi baskılar?\",\"ar\":\"مريض قصور قلب يُعطى xamoterol (منبه بيتا-1 جزئي). يرفع الدواء نبضه أثناء الراحة، لكنه أثناء الجهد العنيف يكبح تسرع القلب! لماذا؟\",\"en\":\"Heart failure patient receives xamoterol (partial beta-1 agonist). At rest, it modestly raises heart rate, but during heavy exercise it paradoxically suppresses tachycardia! Why?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-12a\",\"text\":{\"tr\":\"Dinlenimde düşük sempatik tonda agonist gibi davranarak nabzı artırır; egzersizde yoğun salınan tam agonist adrenalini yarışarak engellediği için antagonist gibi davranır.\",\"ar\":\"يعمل كمنبه أثناء الراحة لانخفاض النغمة الودية فيرفع النبض، بينما ينافس الأدرينالين الكامل المفرز بغزارة أثناء الجهد فيسلك سلوك المضاد.\",\"en\":\"Acts as an agonist at rest under low sympathetic tone, but competitively blocks abundant full agonist adrenaline during exercise, acting as an antagonist.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel bir farmakolojik ustalık! Parsiyel agonistler çift yönlü moleküllerdir: Endojen tonus düşükken net agonizma (%35) üretirler; endojen tam agonist yoğunlaştığında ise reseptörü işgal edip uyarımı %100'den %35'e frenlerler (Slayt 34).\",\"ar\":\"قمة الإتقان الدوائي! المنبه الجزئي سيف ذو حدين: بوجود نغمة منخفضة يرفع التنبيه لـ 35%، وبوجود منبه كامل عاصف يحجب المستقبل ليعمل كمضاد كابح (شريحة 34).\",\"en\":\"Peak pharmacological mastery! Partial agonists act conditionally: elevating activation from basal 0 to 35% at rest, while capping adrenergic surges from 100 down to 35%.\"}},{\"id\":\"opt-12b\",\"text\":{\"tr\":\"Egzersiz sırasında salınan yüksek adrenalin tüm beta reseptörlerini 10 saniyede endositozla hücre içine çeker ve kalbi duyarsızlaştırır.\",\"ar\":\"يقوم الأدرينالين المفرز بالجهد بإدخال جميع مستقبلات بيتا بالبلعمة إلى داخل الخلية خلال 10 ثوانٍ مما يعطل التنبيه.\",\"en\":\"Massive adrenaline release during exercise triggers complete receptor endocytosis within 10 seconds, leaving myocardium unresponsive.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Akut internalizasyon yanılgısı: Reseptör down-regülasyonu ve endositoz dakikalar-saatler alan bir regülasyon sürecidir; egzersizdeki ani taşikardi baskılanması, xamoterolün yüksek afiniteyle adrenalini yarışmalı olarak reseptörden kovmasından (parsiyel agonist antagonizması) doğar.\",\"ar\":\"مغالطة البلعمة الفورية: يستغرق سحب المستقبلات وقتاً طويلاً؛ كبح تسرع القلب المفاجئ بالجهد ينجم عن إزاحة xamoterol للأدرينالين تنافسياً.\",\"en\":\"Acute internalization misconception: Receptor endocytosis requires minutes to hours; acute exercise blunting is driven by xamoterol competitively displacing full agonist adrenaline.\"}},{\"id\":\"opt-12c\",\"text\":{\"tr\":\"Dinlenimde kalpteki beta reseptörlerini artırır, egzersizde ise tüm reseptörleri lizozomlarda yok eder.\",\"ar\":\"يرفع عدد مستقبلات بيتا بالراحة، ويدمر كافة المستقبِلات في الجسيمات الحالة بالجهد.\",\"en\":\"It upregulates beta receptors at rest, while selectively destroying all targets in lysosomes during exercise.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Reseptör regülasyonu yanılgısı: Up-regülasyon ve down-regülasyon günlerce sürer; dakikalar içinde değişen etki tamamen Ariëns parsiyel agonizma dengesidir.\",\"ar\":\"خطأ تنظيم المستقبلات: يستغرق تعديل عدد المستقبِلات أياماً؛ أما التأثير الفوري خلال دقائق فيعود لتوازن المنبه الجزئي لـ Ariëns.\",\"en\":\"Regulation fallacy: Receptor upregulation takes days; instantaneous exercise dynamics reflect Ariëns partial agonist competition.\"}}]},\"technicalTerms\":[{\"term\":\"koşullu antagonizma\",\"arContext\":\"المناهضة الشرطية (conditional antagonism)\"},{\"term\":\"endojen sempatik tonus\",\"arContext\":\"النغمة الودية الداخلية\"}],\"hints\":[{\"tr\":\"Parsiyel agonistin intrinsik aktivitesini (alfa ≈ 0.40) ve ortamdaki endojen adrenalin seviyesini düşünün.\",\"ar\":\"فكر في الفاعلية الذاتية للمنبه الجزئي (alfa ≈ 0.40) ومستوى الأدرينالين الداخلي المحيط.\",\"en\":\"Consider the partial agonist's intrinsic activity (alpha ≈ 0.40) relative to ambient adrenaline.\"},{\"tr\":\"Dinlenimde ortamda adrenalin azdır; ilaç reseptörü uyararak nabzı yükseltir.\",\"ar\":\"أثناء الراحة يقل الأدرينالين، فيشغل الدواء المستقبِلات ليرفع النبض إلى 40%.\",\"en\":\"At rest, adrenaline is sparse; the drug occupies targets and elevates tone toward 40%.\"},{\"tr\":\"Egzersizde adrenalin %100 güçle fırlar; ilaç ise araya girip sinyali %40'ta sınırlandırarak taşikardiyi önler.\",\"ar\":\"أثناء الجهد ينطلق الأدرينالين بطاقة 100%؛ فيحجز الدواء المستقبلات كابحاً التنبيه عند 40%.\",\"en\":\"During exercise, adrenaline spikes; xamoterol limits net activation to 40%, preventing tachycardia.\"}],\"sources\":[{\"file\":\"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf\",\"page\":6}],\"config\":{\"options\":[{\"id\":\"opt-12a\",\"text\":\"Dinlenimde düşük sempatik tonda agonist gibi davranarak nabzı artırır; egzersizde yoğun salınan tam agonist adrenalini yarışarak engellediği için antagonist gibi davranır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel bir farmakolojik ustalık! Parsiyel agonistler çift yönlü moleküllerdir: Endojen tonus düşükken net agonizma (%35) üretirler; endojen tam agonist yoğunlaştığında ise reseptörü işgal edip uyarımı %100'den %35'e frenlerler (Slayt 34).\"},{\"id\":\"opt-12b\",\"text\":\"Egzersiz sırasında salınan yüksek adrenalin tüm beta reseptörlerini 10 saniyede endositozla hücre içine çeker ve kalbi duyarsızlaştırır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Akut internalizasyon yanılgısı: Reseptör down-regülasyonu ve endositoz dakikalar-saatler alan bir regülasyon sürecidir; egzersizdeki ani taşikardi baskılanması, xamoterolün yüksek afiniteyle adrenalini yarışmalı olarak reseptörden kovmasından (parsiyel agonist antagonizması) doğar.\"},{\"id\":\"opt-12c\",\"text\":\"Dinlenimde kalpteki beta reseptörlerini artırır, egzersizde ise tüm reseptörleri lizozomlarda yok eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Reseptör regülasyonu yanılgısı: Up-regülasyon ve down-regülasyon günlerce sürer; dakikalar içinde değişen etki tamamen Ariëns parsiyel agonizma dengesidir.\"}],\"revealedOutcome\":{\"tr\":\"Parsiyel agonistler endojen ligand konsantrasyonuna göre çift yönlü çalışır: Bazal durumda agonist gibi davranırken, yüksek agonist varlığında antagonist gibi davranarak sistemi stabilize eder.\",\"ar\":\"تعمل المنبهات الجزئية بشكل مزدوج بحسب تركيز الربيط الداخلي: تسلك سلوك المنبه بالراحة وسلوك المضاد أثناء التدفق الأدريناليني، مما يثبت استجابة العضو.\",\"en\":\"Partial agonists function as bi-directional stabilizers: acting as agonists at baseline, but transitioning into functional antagonists during full agonist surges.\"},\"explanation\":{\"tr\":\"Ariëns ve Stephenson modellerinde parsiyel agonistler sabit bir intrinsik aktiviteye (0 < alfa < 1) sahiptir. Endojen sinyal seviyesi alfa değerinin altındayken uyarır, üzerindeyken ise reseptörleri işgal ederek uyarımı sınırlar (Slayt 34).\",\"ar\":\"في نماذج Ariëns و Stephenson، تملك المنبهات الجزئية فاعلية ثابتة (0 < alfa < 1)؛ فإذا كانت الإشارة الداخلية أقل من alfa فإنها تحفزها، وإذا كانت أعلى فإنها تكبحها (شريحة 34).\",\"en\":\"Under Ariëns-Stephenson models, partial agonists possess intermediate efficacy (0 < alpha < 1), elevating sub-threshold signaling while dampening excessive physiological surges.\"}}}]},\"pharm-mod2-les1\":{\"$schema\":\"../../../packages/platform/schema/lesson.schema.json\",\"id\":\"pharm-mod2-les1\",\"courseId\":\"pharmacology\",\"moduleId\":\"ph-mod-02\",\"title\":{\"tr\":\"Kademeli Doz-Yanıt Eğrileri ve İntrinsik Etkinlik\",\"ar\":\"منحنيات الجرعة والاستجابة التدرجية والفعالية الذاتية\",\"en\":\"Graded Dose-Response Curves & Intrinsic Efficacy\"},\"order\":1,\"access\":\"free\",\"objective\":{\"tr\":\"Potens (EC50) ve efikasite (Emax) ayrımını yapmak, Ariëns ve Stephenson modellerini uygulayarak parsiyel agonizm ve doku yedek reseptör rezervini analiz etmek.\",\"ar\":\"التمييز الدقيق بين القوة (EC50) والفعالية (Emax)، وتطبيق نموذجي Ariëns و Stephenson لتحليل التنبيه الجزئي والاحتياطي الوظيفي للمستقبِلات.\",\"en\":\"Differentiate potency (EC50) from efficacy (Emax), and apply Ariëns and Stephenson models to analyze partial agonism and tissue spare receptor reserves.\"},\"misconceptions\":[{\"tr\":\"Daha düşük dozda etki gösteren (potensi yüksek, düşük EC50) bir ilacın klinik olarak mutlaka daha yüksek bir maksimum etki (Emax) üreteceği yanılgısı.\",\"ar\":\"الظن الخاطئ بأن الدواء الأكثر قوة (EC50 أقل) يحقق حتماً استجابة حيوية أعظمية سريرية أكبر (Emax).\",\"en\":\"The misconception that a drug with higher potency (lower EC50) necessarily achieves greater maximal clinical efficacy (Emax).\"},{\"tr\":\"Parsiyel agonistlerin tüm dokularda ve her koşulda aynı oranda submaksimal etki göstereceği düşüncesi (efektör kenetlenmesi ve yedek reseptör rezervine göre tam agoniste dönüşebilir).\",\"ar\":\"الاعتقاد الخاطئ بأن المنبهات الجزئية تعطي نفس الاستجابة دون القصوى في كافة الأنسجة (قد تسلك سلوك المنبه الكامل بوجود احتياطي وظيفي ضخم).\",\"en\":\"The belief that partial agonist efficacy is immutable across tissues, overlooking that abundant spare receptor reserves can convert them into functional full agonists.\"},{\"tr\":\"Morfin bağımlısına verilen yüksek afiniteli bir parsiyel agonistin (buprenorfin) ağrıyı daha da derin keseceği varsayımı (aksine tam agonisti kovarak akut yoksunluk krizi patlatır).\",\"ar\":\"الافتراض الخاطئ بأن إعطاء منبه جزئي فائق الألفة (بوبرينورفين) لمريض معتمد على المورفين سيزيد التسكين (بل يطرد المورفين مفجراً نوبة انسحاب حادة).\",\"en\":\"The misconception that co-administering high-affinity buprenorphine with morphine deepens analgesia, rather than precipitating acute opioid withdrawal.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":4},{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":8},{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":12},{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":15},{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":19},{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":22}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Goodman & Gilman's The Pharmacological Basis of Therapeutics\",\"edition\":\"14th ed.\",\"topic\":\"Graded Dose-Response Relationships, Potency, Efficacy, and Spare Receptors\",\"chapter\":\"Chapter 3\",\"page\":\"55-75\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Katzung Basic & Clinical Pharmacology\",\"edition\":\"15th ed.\",\"topic\":\"Drug Receptors & Pharmacodynamics: Graded Dose-Response Curves & Partial Agonists\",\"chapter\":\"Chapter 2\",\"page\":\"22-38\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"pharm-mod2-les1-card1\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Potens (EC50) vs Efikasite (Emax)\",\"prompt\":\"Bir ilacın potansi ile efikasitesi (maksimum etkinliği) doz-yanıt eğrisinde hangi eksen parametreleriyle ifade edilir?\",\"answer\":\"Potens yatay eksendeki EC50 konumuyla (düşük EC50 = yüksek potens), efikasite ise dikey eksendeki Emax tavan yüksekliğiyle ifade edilir.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod2-les1-card2\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Ariëns İntrinsik Aktivite (alfa)\",\"prompt\":\"Ariëns modeline göre tam agonist, parsiyel agonist ve kompetitif antagonistin alfa değerleri nedir?\",\"answer\":\"Tam agonist alfa = 1, parsiyel agonist 0 < alfa < 1, kompetitif antagonist alfa = 0.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod2-les1-card3\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Pindolol ISA Mekanizması\",\"prompt\":\"Pindolol gibi ISA pozitif beta blokerlerin saf antagonist propranolole göre bradikardik hastalardaki üstünlüğü nedir?\",\"answer\":\"Parsiyel agonist etkisiyle kalpte bazal sempatik tonusu (%15-25) koruyarak aşırı bradikardiyi ve kardiyak duraklamayı önler.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod2-les1-card4\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Dokuya Özgü Parsiyel Agonizm (Receptor Reserve)\",\"prompt\":\"Orta derecede efikasiteye sahip bir ilaç neden sağlıklı dokuda tam agonist, yetmezlikli dokuda parsiyel agonist gibi davranır?\",\"answer\":\"Sağlıklı dokudaki geniş yedek reseptör rezervi düşük uyarımı tam yanıta amplifiye eder; yetmezlikte rezerv kaybolunca submaksimal tavan ortaya çıkar.\",\"box\":1,\"intervalDays\":1}],\"translations\":{\"tr\":{\"title\":\"Kademeli Doz-Yanıt Eğrileri ve İntrinsik Etkinlik\"},\"ar\":{\"title\":\"منحنيات الجرعة والاستجابة التدرجية والفعالية الذاتية\"}},\"steps\":[{\"id\":\"pharm-mod2-les1-step-01\",\"stage\":\"hook\",\"stageIndex\":1,\"type\":\"predict_reveal\",\"title\":{\"tr\":\"Klinik Paradoks: Buprenorfin ile Tetiklenen Kriz\",\"ar\":\"مفارقة سريرية: نوبة الانسحاب المحفزة بالبوبرينورفين\",\"en\":\"Clinical Paradox: Buprenorphine Precipitated Withdrawal\"},\"prompt\":{\"tr\":\"Morfin infüzyonundaki kanser hastasına şiddetli ağrı atağı için yüksek afiniteli buprenorfin ekleniyor. Hasta derin bir sedasyona girmek yerine 15 dakikada şiddetli terleme, kusma ve akut yoksunluk krizine giriyor. Neden?\",\"ar\":\"لمريض سرطان خاضع للمورفين، يُعطى بوبرينورفين فائق الألفة لألم حاد مفاجئ. بدلاً من تسكين عميق، يصاب خلال 15 دقيقة بتعرق شديد وإقياء ونوبة انسحاب حادة! لماذا؟\",\"en\":\"A cancer patient on continuous morphine receives high-affinity buprenorphine for breakthrough pain. Instead of deepening sedation, severe vomiting, diaphoresis, and acute opioid withdrawal erupt within 15 minutes! Why?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-1a\",\"text\":{\"tr\":\"Buprenorfin yüksek afinitesiyle morfini reseptörden kovar; ancak düşük intrinsik aktivitesi (alfa ≈ 0.35) nedeniyle net reseptör aktivasyonu aniden düşer.\",\"ar\":\"يطرد البوبرينورفين المورفين بألفته العالية؛ ولأن فاعليته الذاتية منخفضة (alfa ≈ 0.35)، تهبط الاستجابة الكلية فجأة وتفجر متلازمة الانسحاب.\",\"en\":\"Buprenorphine's sub-nanomolar affinity displaces morphine; its lower intrinsic efficacy (alpha ≈ 0.35) then abruptly plunges net opioid signaling.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Buprenorfin sub-nanomolar afiniteyle (Kd ≈ 0.1 nM) morfini (Kd ≈ 2 nM) kovar; ancak kendisi parsiyel agonist olduğu için uyarımı %100'den %35'e düşürerek yoksunluk patlatır.\",\"ar\":\"صحيح! يزيح البوبرينورفين المورفين بألفته الفائقة؛ ولكنه كمنبه جزئي يخفض التنبيه من 100% إلى 35% مما يحفز متلازمة انسحاب حادة فورية.\",\"en\":\"Correct! Buprenorphine's high affinity displaces morphine, but its partial agonist profile drops activation to 35%, precipitating withdrawal.\"}},{\"id\":\"opt-1b\",\"text\":{\"tr\":\"Buprenorfin karaciğerde CYP3A4 enzimini hızlandırarak kandaki tüm morfini saniyeler içinde metabolize eder.\",\"ar\":\"يقوم البوبرينورفين بتحفيز أنزيم CYP3A4 كبدياً ليفكك كامل المورفين في الدم خلال ثوانٍ.\",\"en\":\"Buprenorphine hyper-induces hepatic CYP3A4, clearing all circulating morphine from blood within seconds.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Metabolik yanılgı: Enzim indüksiyonu günler sürer; 15 dakikada gelişen kriz farmakokinetik klirens değil, reseptör düzeyindeki farmakodinamik yer değiştirmedir.\",\"ar\":\"خطأ الاستقلاب: يستغرق التحفيز الأنزيمي أياماً؛ والأزمة الصاعقة خلال دقائق تعود لتنافس دوائي مباشر على المستقبلات.\",\"en\":\"Metabolic misconception: Enzyme induction takes days; rapid 15-minute crisis is pharmacodynamic receptor displacement, not clearance.\"}},{\"id\":\"opt-1c\",\"text\":{\"tr\":\"Buprenorfin morfin moleküllerine kovalent olarak bağlanarak onları inaktif şelat adüktlerine dönüştürür.\",\"ar\":\"يرتبط البوبرينورفين تساهمياً بجزيئات المورفين ليحولها إلى معقدات تمخلب خاملة.\",\"en\":\"Buprenorphine binds covalently to morphine molecules, neutralizing them into inactive chelate adducts.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kimyasal antikor yanılgısı: İki opioid molekülü birbiriyle kovalent bağlanmaz; etki mu-reseptör aktif cebindeki kompetisyondan kaynaklanır.\",\"ar\":\"خطأ التمخلب الكيميائي: لا يتفاعل الأفيونان كيميائياً في الدم؛ بل يتنافسان على الجيب النشط للمستقبل الأفيوني mu.\",\"en\":\"Chemical neutralization misconception: Opioids do not react chemically with each other; antagonism occurs at the receptor level.\"}}]},\"technicalTerms\":[{\"term\":\"parsiyel agonist\",\"arContext\":\"المنبه الجزئي (partial agonist)\"},{\"term\":\"tetiklenmiş yoksunluk\",\"arContext\":\"الانسحاب المحفز (precipitated withdrawal)\"}],\"hints\":[{\"tr\":\"Afinite (bağlanma gücü) ile efikasite (etki gücü) arasındaki farkı hatırlayın.\",\"ar\":\"تذكر الفارق الحاسم بين الألفة (الارتباط) والفاعلية القصوى (التأثير).\",\"en\":\"Recall the distinction between target affinity and intrinsic efficacy.\"},{\"tr\":\"Buprenorfin reseptöre morfinden çok daha sıkı bağlanır fakat reseptörü sadece kısmen uyarabilir.\",\"ar\":\"يرتبط البوبرينورفين بألفة أشد من المورفين، لكنه ينشط المستقبل جزئياً فقط.\",\"en\":\"Buprenorphine binds much tighter than morphine, but only stimulates the receptor partially.\"},{\"tr\":\"Tam agonist morfini kovan parsiyel agonist, net opioid uyarısını anında %35'e düşürür.\",\"ar\":\"طرد المنبه الكامل واستبداله بمنبه جزئي يهبط بالتنبيه إلى 35% فجأة مسبباً الأزمة.\",\"en\":\"Displacing a full agonist with a partial agonist plunges stimulation from 100% to 35%.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":12}],\"config\":{\"options\":[{\"id\":\"opt-1a\",\"text\":\"Buprenorfin yüksek afinitesiyle morfini reseptörden kovar; ancak düşük intrinsik aktivitesi (alfa ≈ 0.35) nedeniyle net reseptör aktivasyonu aniden düşer.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Buprenorfin sub-nanomolar afiniteyle (Kd ≈ 0.1 nM) morfini (Kd ≈ 2 nM) kovar; ancak kendisi parsiyel agonist olduğu için uyarımı %100'den %35'e düşürerek yoksunluk patlatır.\"},{\"id\":\"opt-1b\",\"text\":\"Buprenorfin karaciğerde CYP3A4 enzimini hızlandırarak kandaki tüm morfini saniyeler içinde metabolize eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Metabolik yanılgı: Enzim indüksiyonu günler sürer; 15 dakikada gelişen kriz farmakokinetik klirens değil, reseptör düzeyindeki farmakodinamik yer değiştirmedir.\"},{\"id\":\"opt-1c\",\"text\":\"Buprenorfin morfin moleküllerine kovalent olarak bağlanarak onları inaktif şelat adüktlerine dönüştürür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kimyasal antikor yanılgısı: İki opioid molekülü birbiriyle kovalent bağlanmaz; etki mu-reseptör aktif cebindeki kompetisyondan kaynaklanır.\"}],\"revealedOutcome\":{\"tr\":\"Buprenorfin yüksek afinitesiyle morfini kovar; fakat intrinsik etkinliği düşük olduğu için net sinyali anında %100'den %35'e düşürerek akut yoksunluk krizi başlatır.\",\"ar\":\"يطرد البوبرينورفين المورفين بألفته الفائقة؛ ولأن فاعليته منخفضة، تهبط الاستجابة فجأة من 100% إلى 35% مفجرة نوبة انسحاب حادة.\",\"en\":\"Buprenorphine displaces morphine with high affinity; its low partial efficacy then plunges signaling from 100% to 35%, triggering acute withdrawal.\"},\"explanation\":{\"tr\":\"Doz-yanıt teorisinde parsiyel agonistler çift yönlüdür: Tek başlarınayken agonist, tam agonist varlığında ise kompetitif antagonist gibi davranırlar (Farmakodinami Slayt 12).\",\"ar\":\"في نظرية الجرعة والاستجابة، تسلك المنبهات الجزئية سلوكاً مزدوجاً: منبه بمفردها، ومضاد تنافسي بوجود منبه كامل.\",\"en\":\"In dose-response theory, partial agonists display dual behavior: agonists in isolation, but functional antagonists in the presence of full agonists.\"}}},{\"id\":\"pharm-mod2-les1-step-02\",\"stage\":\"question\",\"stageIndex\":2,\"type\":\"question\",\"title\":{\"tr\":\"Temel Ayrım: Potens (EC50) vs Efikasite (Emax)\",\"ar\":\"التمييز الجوهري: القوة (EC50) والفعالية (Emax)\",\"en\":\"Core Distinction: Potency (EC50) vs Efficacy (Emax)\"},\"prompt\":{\"tr\":\"İki analjezikten İlaç X'in EC50'si 1 mg, İlaç Y'nin EC50'si 50 mg'dır; ancak her ikisi de ağrıyı %100 kesebilmektedir. İlaç X için hangisi doğrudur?\",\"ar\":\"بين مسكنين، يملك الدواء X تركيز EC50 = 1 mg، والدواء Y يملك EC50 = 50 mg؛ لكن كلاهما يسكن الألم بنسبة 100%. ما الصحيح عن الدواء X؟\",\"en\":\"Between two analgesics, Drug X has EC50 = 1 mg, while Drug Y has EC50 = 50 mg; yet both completely abolish pain (Emax = 100%). What is true of Drug X?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-2a\",\"text\":{\"tr\":\"İlaç X, İlaç Y'den 50 kat daha potenttir (yüksek potens); fakat her ikisinin de maksimum efikasitesi (Emax) tamamen eşittir.\",\"ar\":\"الدواء X أكثر قوة (potency) بـ 50 مرة من الدواء Y؛ لكن الفعالية القصوى (Emax) متطابقة تماماً لكلا الدواءين.\",\"en\":\"Drug X is 50-fold more potent than Drug Y, yet their maximal efficacy (Emax) is perfectly identical.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika! Potens yatay eksendeki dozu (EC50) belirler; 1 mg 50 mg'dan 50 kat daha potenttir. Efikasite ise tavan yüksekliktir (Emax = %100) ve ikisinde de aynıdır.\",\"ar\":\"رائع! تعبر القوة عن موضع الجرعة أفقياً (EC50)؛ فـ 1 mg أكثر قوة بـ 50 مرة. أما الفعالية فهي سقف الاستجابة الشاقولي (Emax = 100%) وهي متساوية.\",\"en\":\"Great! Potency reflects horizontal curve placement (EC50); 1 mg is 50-fold more potent. Efficacy is the vertical ceiling (Emax = 100%), which is identical.\"}},{\"id\":\"opt-2b\",\"text\":{\"tr\":\"İlaç X'in efikasitesi İlaç Y'den 50 kat üstündür ve terminal kanser ağrılarında mutlaka daha üstün bir rahatlama sağlar.\",\"ar\":\"فعالية الدواء X تفوق الدواء Y بخمسين ضعفاً وسيحقق حتماً تسكيناً أفضل في آلام السرطان الشديدة.\",\"en\":\"Drug X's efficacy is 50-fold superior to Drug Y, guaranteeing superior relief in severe cancer pain.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Efikasite-potens karışıklığı: Potens sadece gereken miligram miktarını gösterir; her iki ilaç da yeterli dozda ağrıyı %100 keser, tavan etkinlikleri eşittir.\",\"ar\":\"خلط الفعالية بالقوة: تحدد القوة مقدار الميليغرامات فقط؛ وكلا الدواءين يسكنان الألم بنسبة 100% عند الجرعة الكافية بسقف متساوٍ.\",\"en\":\"Potency-efficacy confusion: Potency reflects required dose; both drugs reach 100% pain relief, meaning identical clinical efficacy ceilings.\"}},{\"id\":\"opt-2c\",\"text\":{\"tr\":\"İlaç X'in reseptöre bağlanması kovalenttir; bu yüzden 50 kat daha az dozla etki gösterebilmektedir.\",\"ar\":\"ارتباط الدواء X بالمستقبل تساهمي غير عكوس؛ ولذا يعمل بجرعة أقل بخمسين ضعفاً.\",\"en\":\"Drug X binds targets covalently, which is why it operates at 50-fold lower dosage.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kovalent bağ yanılgısı: Yüksek potens kovalent bağlanma demek değildir; non-kovalent bağların yüksek afinite sağlamasıyla da düşük EC50 elde edilir.\",\"ar\":\"خطأ الرابطة التساهمية: لا تعني القوة العالية روابط تساهمية؛ بل يمكن للألفة العالية غير التساهمية تحقيق EC50 منخفض جداً.\",\"en\":\"Covalent misconception: High potency does not imply covalent bonding; high-affinity reversible interactions readily achieve low EC50.\"}}]},\"technicalTerms\":[{\"term\":\"potens (EC50)\",\"arContext\":\"القوة الدوائية (potency)\"},{\"term\":\"efikasite (Emax)\",\"arContext\":\"الفعالية القصوى (efficacy)\"}],\"hints\":[{\"tr\":\"EC50 yatay eksende, Emax ise dikey eksendedir.\",\"ar\":\"يقع تركيز EC50 على المحور الأفقي، بينما يقع سقف Emax على المحور الشاقولي.\",\"en\":\"EC50 is plotted on the horizontal axis; Emax on the vertical axis.\"},{\"tr\":\"Daha az dozla aynı yanıtı veren ilaç daha 'potent'tir.\",\"ar\":\"الدواء الذي يحقق نفس الاستجابة بجرعة أقل يعتبر أكثر 'قوة'.\",\"en\":\"A drug producing identical effects at lower doses is more 'potent'.\"},{\"tr\":\"Her ikisi de ağrıyı %100 kestiği için efikasiteleri (Emax) tamamen eşittir.\",\"ar\":\"بما أن كلاهما يسكن الألم بنسبة 100%، فإن فعاليتهما القصوى متطابقة.\",\"en\":\"Since both abolish 100% of pain, their maximal efficacies are identical.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":8}],\"config\":{\"options\":[{\"id\":\"opt-2a\",\"text\":\"İlaç X, İlaç Y'den 50 kat daha potenttir (yüksek potens); fakat her ikisinin de maksimum efikasitesi (Emax) tamamen eşittir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika! Potens yatay eksendeki dozu (EC50) belirler; 1 mg 50 mg'dan 50 kat daha potenttir. Efikasite ise tavan yüksekliktir (Emax = %100) ve ikisinde de aynıdır.\"},{\"id\":\"opt-2b\",\"text\":\"İlaç X'in efikasitesi İlaç Y'den 50 kat üstündür ve terminal kanser ağrılarında mutlaka daha üstün bir rahatlama sağlar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Efikasite-potens karışıklığı: Potens sadece gereken miligram miktarını gösterir; her iki ilaç da yeterli dozda ağrıyı %100 keser, tavan etkinlikleri eşittir.\"},{\"id\":\"opt-2c\",\"text\":\"İlaç X'in reseptöre bağlanması kovalenttir; bu yüzden 50 kat daha az dozla etki gösterebilmektedir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kovalent bağ yanılgısı: Yüksek potens kovalent bağlanma demek değildir; non-kovalent bağların yüksek afinite sağlamasıyla da düşük EC50 elde edilir.\"}],\"revealedOutcome\":{\"tr\":\"İlaç X 50 kat daha potenttir (EC50=1 mg vs 50 mg). Ancak her iki ilacın klinik tavanı (%100 analjezi) eşittir, yani efikasiteleri aynıdır.\",\"ar\":\"الدواء X أكثر قوة بـ 50 مرة (EC50 = 1 mg مقابل 50 mg)؛ لكن السقف السريري متطابق (100% تسكين)، أي أن الفعالية القصوى متساوية.\",\"en\":\"Drug X is 50-fold more potent (EC50 = 1 mg vs 50 mg), but both share identical 100% analgesic efficacy ceilings.\"},\"explanation\":{\"tr\":\"Farmakolojide klinik başarıyı belirleyen asıl parametre efikasitedir (Emax). Potens (EC50) sadece tabletin kaç miligram olacağını belirlerken, efikasite ilacın hastayı ne kadar tedavi edebileceğini belirler (Slayt 8).\",\"ar\":\"في علم الأدوية، الفعالية (Emax) هي المحدد الحاسم للنجاح السريري. بينما تحدد القوة (EC50) حجم حبة الدواء بالميليغرامات فقط.\",\"en\":\"Maximal efficacy (Emax) dictates clinical ceiling. Potency (EC50) merely sets pill dosage weight, not ultimate therapeutic ceiling.\"}}},{\"id\":\"pharm-mod2-les1-step-03\",\"stage\":\"intuition\",\"stageIndex\":3,\"type\":\"intuition\",\"title\":{\"tr\":\"Klinik Sezgi: Pindolol ve İntrinsik Sempatomimetik Aktivite (ISA)\",\"ar\":\"الحدس السريري: بيندولول والنشاط الودي الداخلي (ISA)\",\"en\":\"Clinical Intuition: Pindolol & Intrinsic Sympathomimetic Activity\"},\"prompt\":{\"tr\":\"Astımlı bir hipertansiyon hastasında, tam antagonist propranolol bronkospazm yaparken; parsiyel agonist pindolol (ISA pozitif) neden bronş tonusunu tehlikeli biçimde düşürmez?\",\"ar\":\"لمريض ربو وضغط دم، يسبب بروبرانولول (مضاد كامل) تشنجاً قصبياً؛ بينما لا يسبب بيندولول (منبه جزئي ذو نشاط ودي داخلي) هذا التشنج الخطير! لماذا؟\",\"en\":\"In a hypertensive asthmatic, pure antagonist propranolol triggers bronchospasm, whereas partial agonist pindolol (with ISA) does not provoke severe airway constriction. Why?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-3a\",\"text\":{\"tr\":\"Pindolol beta-2 reseptörlerine bağlandığında bazal seviyede (%15-25) hafif bir agonistik uyarı (intrinsik sempatomimetik aktivite) sürdürerek bronşların tamamen kasılmasını engeller.\",\"ar\":\"يحافظ بيندولول على تنبيه قاعدي خفيف (15-25%) لمستقبلات بيتا-2 (نشاط ودي داخلي)، مانعاً التشنج القصبي التام.\",\"en\":\"Pindolol sustains low-level baseline beta-2 stimulation (15-25% ISA), preventing full, unopposed bronchoconstriction.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kesinlikle! Propranolol saf antagonisttir (alfa=0) ve sempatik tonusu sıfırlayarak bronkospazm yapar. Pindolol ise parsiyel agonisttir (alfa ≈ 0.20); dinlenimde hafif gevşeme sağlar.\",\"ar\":\"بالتأكيد! بروبرانولول مضاد نقي (alfa=0) يصفر النغمة الودية فيحدث تشنجاً. أما بيندولول فمنبه جزئي (alfa ≈ 0.20) يحافظ على ارتخاء قصبي طفيف.\",\"en\":\"Exactly! Propranolol is a pure antagonist (alpha=0), wiping out tone. Pindolol is a partial agonist (alpha ≈ 0.20), preserving basal dilation.\"}},{\"id\":\"opt-3b\",\"text\":{\"tr\":\"Pindolol bronşlardaki beta-2 reseptörlerini tamamen görmezden gelir ve yalnızca böbrek alfa reseptörlerine kilitlenir.\",\"ar\":\"يتجاهل بيندولول مستقبلات بيتا-2 القصبية كلياً وينقفل حصراً على مستقبلات ألفا الكلوية.\",\"en\":\"Pindolol completely ignores airway beta-2 targets, binding selectively to renal alpha receptors.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Seçicilik yanılgısı: Pindolol non-selektif bir beta blokerdir; beta-2 reseptörlerine bağlanır ancak onları kısmen uyardığı için koruyucudur.\",\"ar\":\"خطأ الانتقائية: بيندولول حاصر بيتا غير انتقائي؛ يرتبط بمستقبلات بيتا-2 القصبية لكنه يحميها بالتنبيه الجزئي.\",\"en\":\"Selectivity misconception: Pindolol is a non-selective beta ligand; safety stems from partial agonism, not receptor avoidance.\"}},{\"id\":\"opt-3c\",\"text\":{\"tr\":\"Pindolol adrenerjik reseptörleri bırakıp doğrudan parasempatik muskarinik M3 reseptörlerini bloke ederek antikolinerjik bronkodilatasyon yapar.\",\"ar\":\"يترك بيندولول المستقبلات الأدرينرجية ليحصر مباشرة مستقبلات M3 الموسكارينك محدثاً توسعاً قصبياً مضاداً للكولين.\",\"en\":\"Pindolol bypasses adrenergic receptors to directly block parasympathetic muscarinic M3 receptors, inducing anticholinergic bronchodilation.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Çapraz reseptör blokajı yanılgısı: Pindolol bir muskarinik M3 antagonisti değildir; bronş tonusunu korumasının nedeni beta-2 reseptörlerinde sürdürdüğü zayıf intrinsik sempatomimetik aktivitedir (alfa ≈ 0.20).\",\"ar\":\"مغالطة الحصار المتصالب: بيندولول ليس مضاداً لمستقبلات M3؛ حماية القصبات تنبع حصراً من نشاطه الودي الداخلي الخفيف على مستقبلات بيتا-2 (alfa ≈ 0.20).\",\"en\":\"Cross-receptor antagonism misconception: Pindolol does not block muscarinic M3 receptors; airway protection stems strictly from its weak intrinsic sympathomimetic activity at beta-2 receptors.\"}}]},\"technicalTerms\":[{\"term\":\"intrinsik sempatomimetik aktivite (ISA)\",\"arContext\":\"النشاط الودي الداخلي (ISA)\"},{\"term\":\"bazal tonus\",\"arContext\":\"النغمة القاعدية (basal tone)\"}],\"hints\":[{\"tr\":\"Propranolol ile pindolol arasındaki efikasite (alfa) farkını düşünün.\",\"ar\":\"قارن بين الفاعلية الذاتية (alpha) لبروبرانولول وبيندولول.\",\"en\":\"Contrast the intrinsic activity (alpha) of propranolol versus pindolol.\"},{\"tr\":\"Propranolol reseptörü tamamen susturur (alfa = 0); pindolol ise hafifçe uyarır (alfa ≈ 0.20).\",\"ar\":\"يخمد بروبرانولول المستقبل كلياً (alfa = 0)؛ بينما يشغله بيندولول جزئياً (alfa ≈ 0.20).\",\"en\":\"Propranolol silences targets (alpha = 0); pindolol maintains weak stimulation (alpha ≈ 0.20).\"},{\"tr\":\"Bu hafif bazal uyarı (ISA) bronşların aşırı kasılmasını engelleyen bir koruma kalkanı sunar.\",\"ar\":\"هذا التنبيه القاعدي الطفيف (ISA) يمنع التشنج القصبي المفرط.\",\"en\":\"This baseline stimulus (ISA) buffers against severe bronchoconstriction.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":15}],\"config\":{\"options\":[{\"id\":\"opt-3a\",\"text\":\"Pindolol beta-2 reseptörlerine bağlandığında bazal seviyede (%15-25) hafif bir agonistik uyarı (intrinsik sempatomimetik aktivite) sürdürerek bronşların tamamen kasılmasını engeller.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kesinlikle! Propranolol saf antagonisttir (alfa=0) ve sempatik tonusu sıfırlayarak bronkospazm yapar. Pindolol ise parsiyel agonisttir (alfa ≈ 0.20); dinlenimde hafif gevşeme sağlar.\"},{\"id\":\"opt-3b\",\"text\":\"Pindolol bronşlardaki beta-2 reseptörlerini tamamen görmezden gelir ve yalnızca böbrek alfa reseptörlerine kilitlenir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Seçicilik yanılgısı: Pindolol non-selektif bir beta blokerdir; beta-2 reseptörlerine bağlanır ancak onları kısmen uyardığı için koruyucudur.\"},{\"id\":\"opt-3c\",\"text\":\"Pindolol adrenerjik reseptörleri bırakıp doğrudan parasempatik muskarinik M3 reseptörlerini bloke ederek antikolinerjik bronkodilatasyon yapar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Çapraz reseptör blokajı yanılgısı: Pindolol bir muskarinik M3 antagonisti değildir; bronş tonusunu korumasının nedeni beta-2 reseptörlerinde sürdürdüğü zayıf intrinsik sempatomimetik aktivitedir (alfa ≈ 0.20).\"}],\"revealedOutcome\":{\"tr\":\"Pindolol parsiyel agonisttir (ISA pozitif). Saf antagonist propranolol gibi sempatik tonusu sıfırlamaz; %15-25 düzeyinde bazal beta-2 uyarısı sağlayarak bronkospazmı önler.\",\"ar\":\"بيندولول منبه جزئي (ISA إيجابي)؛ لا يخمد النغمة الودية كالبروبرانولول، بل يحافظ على تنبيه قاعدي بنسبة 15-25% يمنع التشنج القصبي.\",\"en\":\"Pindolol is a partial agonist (ISA-positive). Unlike pure antagonist propranolol, it preserves 15-25% basal beta-2 stimulation, preventing airway spasm.\"},\"explanation\":{\"tr\":\"İntrinsik sempatomimetik aktiviteye (ISA) sahip beta blokerler, endojen katekolamin seviyesi yüksekken antagonist, düşükken zayıf agonist davranırlar. Bu özellik bradikardi ve astım eğilimli hastalarda klinik avantaj sağlar (Slayt 15).\",\"ar\":\"حاصرات بيتا ذات النشاط الودي الداخلي (ISA) تسلك سلوك المضاد عند تدفق الكاتيكولامينات، والمنبه بالراحة؛ مما يفيد مرضى بطء القلب والربو.\",\"en\":\"ISA beta-blockers act as antagonists during catecholamine surges, but maintain weak agonism at rest, buffering against bradycardia and asthma exacerbations.\"}}},{\"id\":\"pharm-mod2-les1-step-04\",\"stage\":\"visual_explanation\",\"stageIndex\":4,\"type\":\"visual_explanation\",\"title\":{\"tr\":\"Görsel Model: Ariëns (alfa) vs Stephenson (e)\",\"ar\":\"النموذج البصري: Ariëns (alpha) مقابل Stephenson (e)\",\"en\":\"Visual Modeling: Ariëns (alpha) vs Stephenson (e)\"},\"prompt\":{\"tr\":\"Ariëns'in 'intrinsik aktivite' (alfa) modeli ile Stephenson'ın 'stimulus-efikasite' (e) modeli arasındaki temel fark doz-yanıt eğrisinde nasıl görselleşir?\",\"ar\":\"كيف يتمايز نموذج 'الفاعلية الذاتية' (alpha) لـ Ariëns عن نموذج 'الفعالية والتحفيز' (e) لـ Stephenson بصرياً على منحنى الجرعة والاستجابة؟\",\"en\":\"How is the fundamental difference between Ariëns' intrinsic activity (alpha) and Stephenson's stimulus-efficacy (e) visually captured on a dose-response plot?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-4a\",\"text\":{\"tr\":\"Ariëns yanıtı doğrudan reseptör doluluğuyla sınırlandırırken (alfa * theta); Stephenson doku rezervini açıklayarak düşük dolulukta bile maksimum yanıt üreten 'efikasite' (e) kavramını tanımlar.\",\"ar\":\"يقيد Ariëns الاستجابة بنسبة إشغال المستقبِلات (alpha * theta)؛ بينما يفسر Stephenson الاحتياطي الوظيفي بإمكانية بلوغ Emax بإشغال ضئيل عبر الفعالية (e).\",\"en\":\"Ariëns restricts response linearly to occupancy (alpha * theta); Stephenson accommodates spare reserves, showing high efficacy (e) triggers Emax at minimal occupancy.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz kavrayış! Ariëns modelinde %100 etki için %100 doluluk gerekirken; Stephenson stimulus (S = e * theta) kavramıyla non-lineer amplifikasyonu ve yedek reseptörleri açıklamıştır.\",\"ar\":\"فهم استثنائي! تطلب نموذج Ariëns إشغال 100% لبلوغ Emax؛ بينما أثبت Stephenson عبر التحفيز (S = e * theta) إمكانية بلوغ Emax بإشغال 1% فقط.\",\"en\":\"Flawless! Ariëns required 100% occupancy for 100% effect; Stephenson decoupled occupancy via stimulus (S = e * theta), predicting spare receptors.\"}},{\"id\":\"opt-4b\",\"text\":{\"tr\":\"Ariëns sadece antagonistleri, Stephenson ise yalnızca kovalent bağ kuran toksik molekülleri inceler.\",\"ar\":\"يدرس Ariëns المضادات فقط، بينما يدرس Stephenson الجزيئات السامة المرتبطة تساهمياً حصراً.\",\"en\":\"Ariëns solely evaluates antagonists, while Stephenson exclusively models toxic covalent alkylators.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kapsam yanılgısı: Her iki bilim insanı da agonist ve parsiyel agonistleri modellemiştir; Stephenson kovalent ajanları değil doku amplifikasyonunu formüle etmiştir.\",\"ar\":\"خطأ النطاق: قام كلاهما بنمذجة المنبهات والمنبهات الجزئية؛ ولم يقتصر Stephenson على المواد التساهمية بل صاغ التضخيم الخلوي.\",\"en\":\"Scope misconception: Both scientists modeled reversible agonists; Stephenson introduced stimulus-response coupling, not covalent toxins.\"}},{\"id\":\"opt-4c\",\"text\":{\"tr\":\"Stephenson modelinde EC50 değeri daima Kd değerinden 100 kat daha büyüktür.\",\"ar\":\"في نموذج Stephenson تكون قيمة EC50 دائماً أكبر بمئة ضعف من قيمة Kd.\",\"en\":\"Under Stephenson's model, the EC50 value is perpetually 100-fold greater than Kd.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yön yanılgısı: Stephenson ve Furchgott modellerinde yedek reseptör rezervi nedeniyle EC50 << Kd olur (eğri sola kayar), asla daha büyük olmaz.\",\"ar\":\"خطأ الاتجاه: بوجود احتياطي وظيفي في نموذج Stephenson يكون EC50 أصغر بكثير من Kd (ينزاح لليسار) وليس العكس.\",\"en\":\"Direction error: In Stephenson's spare receptor model, EC50 << Kd (curve shifts leftward), never rightward.\"}}]},\"technicalTerms\":[{\"term\":\"Stephenson efikasitesi (e)\",\"arContext\":\"فعالية Stephenson (e)\"},{\"term\":\"stimulus-yanıt kenetlenmesi\",\"arContext\":\"اقتران التحفيز بالاستجابة\"}],\"hints\":[{\"tr\":\"Ariëns: Yanıt = alfa * doluluk (lineer işgal).\",\"ar\":\"نموذج Ariëns: الاستجابة = alfa * نسبة الإشغال (اقتران خطي).\",\"en\":\"Ariëns: Response = alpha * occupancy (linear coupling).\"},{\"tr\":\"Stephenson: İlaç bir stimulus (S = e * theta) üretir, doku bunu non-lineer olarak cevaba çevirir.\",\"ar\":\"نموذج Stephenson: يولد الدواء تحفيزاً (S = e * theta) يحوله النسيج غير خطياً إلى استجابة.\",\"en\":\"Stephenson: Drug creates stimulus (S = e * theta); tissue converts it non-linearly.\"},{\"tr\":\"Stephenson sayesinde reseptörlerin yalnızca %1'i doluyken bile tam yanıt (%100) alınabileceği anlaşılmıştır.\",\"ar\":\"أثبت Stephenson إمكانية تحقيق استجابة 100% بإشغال 1% فقط من المستقبِلات بفضل الاحتياطي.\",\"en\":\"Stephenson proved that 1% occupancy can trigger 100% response when efficacy (e) is high.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":19}],\"config\":{\"options\":[{\"id\":\"opt-4a\",\"text\":\"Ariëns yanıtı doğrudan reseptör doluluğuyla sınırlandırırken (alfa * theta); Stephenson doku rezervini açıklayarak düşük dolulukta bile maksimum yanıt üreten 'efikasite' (e) kavramını tanımlar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz kavrayış! Ariëns modelinde %100 etki için %100 doluluk gerekirken; Stephenson stimulus (S = e * theta) kavramıyla non-lineer amplifikasyonu ve yedek reseptörleri açıklamıştır.\"},{\"id\":\"opt-4b\",\"text\":\"Ariëns sadece antagonistleri, Stephenson ise yalnızca kovalent bağ kuran toksik molekülleri inceler.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kapsam yanılgısı: Her iki bilim insanı da agonist ve parsiyel agonistleri modellemiştir; Stephenson kovalent ajanları değil doku amplifikasyonunu formüle etmiştir.\"},{\"id\":\"opt-4c\",\"text\":\"Stephenson modelinde EC50 değeri daima Kd değerinden 100 kat daha büyüktür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yön yanılgısı: Stephenson ve Furchgott modellerinde yedek reseptör rezervi nedeniyle EC50 << Kd olur (eğri sola kayar), asla daha büyük olmaz.\"}],\"revealedOutcome\":{\"tr\":\"Ariëns modeli yanıtı doğrudan dolulukla sınırlandırır. Stephenson efikasite (e) ve stimulus fonksiyonunu tanımlayarak minimal dolulukta tam yanıt oluşturan yedek reseptörleri açıklamıştır.\",\"ar\":\"قيد Ariëns الاستجابة بالإشغال المباشر؛ بينما فسر Stephenson عبر الفعالية (e) ودالة التحفيز ظاهرة المستقبِلات الاحتياطية وتضخيم الإشارة.\",\"en\":\"Ariëns capped response linearly to occupancy. Stephenson defined efficacy (e) and stimulus, predicting full responses at minimal occupancy.\"},\"explanation\":{\"tr\":\"Stephenson'ın 1956 uyarı teorisi: Yüksek efikasiteli bir tam agonist (yüksek e), reseptör havuzunun minik bir fraksiyonunu uyararak dokunun maksimum kasılma/iletim kapasitesini tüketir. Kalan reseptörler yedektir (Slayt 19).\",\"ar\":\"نظرية Stephenson للتحفيز (1956): يستطيع المنبه ذو الفعالية الفائقة استنفاد قدرة النسيج القصوى بإشغال نسبة ضئيلة من المستقبِلات، وما تبقى يعتبر احتياطياً.\",\"en\":\"Stephenson's 1956 stimulus theory: High-efficacy agonists (large e) saturate tissue response capacity at minimal occupancy, establishing receptor reserves.\"}}},{\"id\":\"pharm-mod2-les1-step-05\",\"stage\":\"interactive_artifact\",\"stageIndex\":5,\"type\":\"dose_response_curve\",\"widgetType\":\"DoseResponseCurve\",\"title\":{\"tr\":\"İnteraktif Laboratuvar: Doz-Yanıt ve Efikasite\",\"ar\":\"مختبر تفاعلي: منحنى الجرعة والاستجابة والفعالية\",\"en\":\"Interactive Lab: Dose-Response & Efficacy\"},\"prompt\":{\"tr\":\"Doz-Yanıt laboratuvarında Tam Agonist ve Parsiyel Agonist modlarını karşılaştırın; EC50 kaymasını ve Emax tavanındaki düşüşü canlı manipüle edin.\",\"ar\":\"في مختبر الجرعة والاستجابة، قارن بين المنبه الكامل والمنبه الجزئي؛ وتحكم حياً بإزاحة EC50 وانخفاض سقف الاستجابة Emax.\",\"en\":\"In the Dose-Response lab, compare Full Agonist and Partial Agonist modes; dynamically manipulate EC50 shifts and Emax efficacy ceilings.\"},\"predictThenReveal\":false,\"config\":{\"title\":\"Kademeli Doz-Yanıt ve Efikasite Simülatörü\",\"prompt\":\"Tam agonist ve parsiyel agonist eğrilerini inceleyerek Emax tavanını karşılaştırın.\",\"defaultEc50\":5,\"defaultEmax\":100,\"defaultHillSlope\":1,\"modes\":[\"agonist\",\"partial_agonist\",\"competitive_antagonist\",\"noncompetitive_antagonist\"],\"source\":{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":12},\"explanation\":\"Tam agonist (Emax=%100) sistemi tam kapasite aktive eder. Parsiyel agonist (Emax=%35) tüm reseptörleri doldursa da submaksimal yanıt verir; tam agonist varlığında kompetitif antagonist gibi davranır.\"},\"widget\":{\"type\":\"DoseResponseCurve\",\"config\":{\"title\":\"Kademeli Doz-Yanıt ve Efikasite Simülatörü\",\"prompt\":\"Tam agonist ve parsiyel agonist eğrilerini inceleyerek Emax tavanını karşılaştırın.\",\"defaultEc50\":5,\"defaultEmax\":100,\"defaultHillSlope\":1,\"modes\":[\"agonist\",\"partial_agonist\",\"competitive_antagonist\",\"noncompetitive_antagonist\"],\"source\":{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":12},\"explanation\":\"Tam agonist (Emax=%100) sistemi tam kapasite aktive eder. Parsiyel agonist (Emax=%35) tüm reseptörleri doldursa da submaksimal yanıt verir; tam agonist varlığında kompetitif antagonist gibi davranır.\"}},\"technicalTerms\":[{\"term\":\"submaksimal tavan (Emax)\",\"arContext\":\"السقف دون الأقصى (submaximal ceiling)\"},{\"term\":\"Hill katsayısı\",\"arContext\":\"معامل هيل (Hill coefficient)\"}],\"hints\":[{\"tr\":\"Parsiyel agonist moduna geçin ve Emax tavanının %35'e kilitlendiğini görün.\",\"ar\":\"انتقل لنمط المنبه الجزئي ولاحظ كيف ينقفل سقف Emax عند 35%.\",\"en\":\"Switch to partial agonist mode and observe the Emax ceiling capped at 35%.\"},{\"tr\":\"Dozu ne kadar artırırsanız artırın, parsiyel agonist asla tam agonistin %100 seviyesine çıkamaz.\",\"ar\":\"مهما ضاعفت الجرعة، لن يصل المنبه الجزئي إطلاقاً لسقف المنبه الكامل 100%.\",\"en\":\"No dose escalation allows the partial agonist to reach the 100% full agonist ceiling.\"},{\"tr\":\"Aynı ortamda tam agonist varken parsiyel agonist reseptörleri işgal ederek uyarımı %35'te sınırlar.\",\"ar\":\"بوجود منبه كامل، يحجز المنبه الجزئي المستقبِلات حابساً الاستجابة عند 35%.\",\"en\":\"In the presence of a full agonist, partial agonist occupancy caps net stimulation at 35%.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":12}]},{\"id\":\"pharm-mod2-les1-step-06\",\"stage\":\"guided_discovery\",\"stageIndex\":6,\"type\":\"guided_discovery\",\"title\":{\"tr\":\"Deneysel Vaka: CR-10 ve Dokuya Özgü Parsiyel Agonizm\",\"ar\":\"حالة تجريبية: CR-10 والتنبيه الجزئي المعتمد على النسيج\",\"en\":\"Experimental Case: CR-10 & Tissue-Dependent Partial Agonism\"},\"prompt\":{\"tr\":\"Deneysel inotropik ajan CR-10, sağlıklı köpek kalbinde güçlü bir tam agonistken (Emax=%100); yetmezlikli insan atriyumunda neden zayıf bir parsiyel agoniste (Emax=%20) dönüşür?\",\"ar\":\"المركب القلبي التجريبي CR-10 يعمل كمنبه كامل قوي (Emax=100%) في قلب كلب سليم؛ لكنه في أذينة بشرية مصابة بقصور يتحول لمنبه جزئي ضعيف (Emax=20%)! لماذا؟\",\"en\":\"Experimental inotrope CR-10 acts as a full agonist (Emax=100%) in healthy canine myocardium, yet becomes a weak partial agonist (Emax=20%) in failing human atrium! Why?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-6a\",\"text\":{\"tr\":\"Yetmezlikli insan kalbinde beta reseptörleri ve efektör kenetlenmesi azaldığı için (yedek reseptör kaybı), orta efikasiteli bir ligand artık maksimum yanıt üretemez.\",\"ar\":\"بسبب تراجع كثافة مستقبلات بيتا والاقتران الخلوي في القلب البشري المريض (فقدان الاحتياطي)، يعجز المركب متوسط الفعالية عن تحقيق Emax.\",\"en\":\"In failing human myocardium, downregulated beta receptors and uncoupled effectors (loss of spare reserve) prevent intermediate-efficacy ligands from reaching Emax.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Muhteşem bir keşif! Bir ilacın tam mı parsiyel mi agonist olacağı sadece moleküle değil, dokudaki reseptör yoğunluğuna ve yedek reseptör rezervine bağlıdır (Slayt 22).\",\"ar\":\"اكتشاف باهر! لا تتحدد صفة المنبه (كامل أم جزئي) ببنية الجزيء وحدها، بل بكثافة المستقبِلات والاحتياطي الوظيفي المتاح في النسيج (شريحة 22).\",\"en\":\"Magnificent discovery! Full vs partial agonism is not an intrinsic property of the drug alone, but a function of tissue receptor density and reserve.\"}},{\"id\":\"opt-6b\",\"text\":{\"tr\":\"İnsan atriyumu ilacın kimyasal yapısını anında hidroksilleyerek bir beta blokere dönüştürür.\",\"ar\":\"يقوم الأذين البشري بهدركسة بنية الدواء فوراً ليتحول إلى حاصر بيتا مثبط.\",\"en\":\"Human atrial tissue immediately hydroxylates the drug, converting it chemically into an antagonist.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Biyokimyasal yanılgı: Organ banyosunda molekül yapısı değişmez; fark dokudaki sinyal amplifikasyonu ve yedek reseptör kapasitesidir.\",\"ar\":\"خطأ كيميائي حيوي: لا تتغير بنية الجزيء في الحمام النسيجي؛ بل يعود الفارق لتضخيم الإشارة وسعة المستقبِلات الاحتياطية.\",\"en\":\"Biochemical misconception: Ligand structures do not mutate in organ baths; differences stem from receptor reserve density.\"}},{\"id\":\"opt-6c\",\"text\":{\"tr\":\"Köpek kalbinde beta reseptörleri kovalent, insan kalbinde ise sadece van der Waals bağları kurar.\",\"ar\":\"ترتبط مستقبلات قلب الكلب بروابط تساهمية، بينما قلب الإنسان بروابط فان دير فالس فقط.\",\"en\":\"Canine myocardial targets form covalent bonds, whereas human targets form only van der Waals contacts.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Bağ türü yanılgısı: CR-10 her iki türde de aynı tersinir non-kovalent bağlarla bağlanır; türler arası fark reseptör sayısı ve kenetlenme verimidir.\",\"ar\":\"خطأ نوع الرابطة: يرتبط CR-10 بنفس الروابط غير التساهمية العكوسة؛ ويكمن الفارق في عدد المستقبِلات وكفاءة الاقتران.\",\"en\":\"Bond type error: CR-10 forms identical non-covalent interactions in both species; the difference is receptor reserve magnitude.\"}}]},\"technicalTerms\":[{\"term\":\"dokuya özgü agonizm\",\"arContext\":\"التنبيه المعتمد على النسيج\"},{\"term\":\"reseptör down-regülasyonu\",\"arContext\":\"تنظيم المستقبلات نحو الهبوط\"}],\"hints\":[{\"tr\":\"Kronik kalp yetmezliğinde kardiyak beta-1 reseptörlerinin sayısına ne olduğunu düşünün.\",\"ar\":\"فكر في مصير عدد مستقبلات بيتا-1 القلبية في قصور القلب المزمن.\",\"en\":\"Consider what happens to beta-1 receptor numbers in chronic heart failure.\"},{\"tr\":\"Reseptörler down-regüle olur ve yedek reseptör rezervi tükenir.\",\"ar\":\"يحدث هبوط في تنظيم المستقبِلات وينفد الاحتياطي الوظيفي.\",\"en\":\"Receptors downregulate and spare receptor reserves vanish.\"},{\"tr\":\"Köpek kalbinde bol yedek reseptör CR-10'u tam agonist yaparken; insan yetmezliğinde rezerv olmadığı için Emax çöker.\",\"ar\":\"الاحتياطي الضخم في قلب الكلب يجعل CR-10 منبهاً كاملاً، بينما غياب الاحتياطي في الإنسان يسقط Emax لـ 20%.\",\"en\":\"Plentiful canine reserve yields full agonism; absent human reserve exposes partial agonist limitations.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":22}],\"config\":{\"options\":[{\"id\":\"opt-6a\",\"text\":\"Yetmezlikli insan kalbinde beta reseptörleri ve efektör kenetlenmesi azaldığı için (yedek reseptör kaybı), orta efikasiteli bir ligand artık maksimum yanıt üretemez.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Muhteşem bir keşif! Bir ilacın tam mı parsiyel mi agonist olacağı sadece moleküle değil, dokudaki reseptör yoğunluğuna ve yedek reseptör rezervine bağlıdır (Slayt 22).\"},{\"id\":\"opt-6b\",\"text\":\"İnsan atriyumu ilacın kimyasal yapısını anında hidroksilleyerek bir beta blokere dönüştürür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Biyokimyasal yanılgı: Organ banyosunda molekül yapısı değişmez; fark dokudaki sinyal amplifikasyonu ve yedek reseptör kapasitesidir.\"},{\"id\":\"opt-6c\",\"text\":\"Köpek kalbinde beta reseptörleri kovalent, insan kalbinde ise sadece van der Waals bağları kurar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Bağ türü yanılgısı: CR-10 her iki türde de aynı tersinir non-kovalent bağlarla bağlanır; türler arası fark reseptör sayısı ve kenetlenme verimidir.\"}],\"revealedOutcome\":{\"tr\":\"Agonist profili dokuya bağlıdır: CR-10 sağlıklı köpek kalbinde geniş yedek reseptör sayesinde tam agonisttir (Emax=%100). Yetmezlikli insan kalbinde reseptörler down-regüle olduğu için parsiyel agonisttir (Emax=%20).\",\"ar\":\"يعتمد التنبيه على النسيج: يعمل CR-10 كمنبه كامل في قلب الكلب لوجود احتياطي وظيفي ضخم (Emax=100%)، ويتحول لمنبه جزئي (Emax=20%) في القلب البشري المريض لنفاد الاحتياطي.\",\"en\":\"Agonism is tissue-dependent: CR-10 acts as a full agonist in canine tissue due to spare reserves, but collapses to a partial agonist in human heart failure due to receptor downregulation.\"},\"explanation\":{\"tr\":\"Kenbar ve Furchgott prensiplerine göre: Bir ilacın intrinsik efikasitesi (e) sabittir; fakat oluşturduğu biyolojik yanıt dokunun reseptör havuzu büyüklüğü ([Rt]) ile çarpılır. Doku rezervi azalınca tam agonistler parsiyel agoniste dönüşür (Slayt 22).\",\"ar\":\"وفق مبادئ Furchgott: فعالية الدواء الذاتية (e) ثابتة؛ لكن الاستجابة الحيوية تتضاعف بحجم حوض المستقبِلات ([Rt]). وعند تراجع الاحتياطي تتحول المنبهات الكاملة لمنبهات جزئية.\",\"en\":\"Per Furchgott: intrinsic efficacy (e) is constant, but tissue stimulus multiplies by target density ([Rt]). When reserves decline, former full agonists become partial agonists.\"}}},{\"id\":\"pharm-mod2-les1-step-07\",\"stage\":\"formal_explanation\",\"stageIndex\":7,\"type\":\"formal_explanation\",\"title\":{\"tr\":\"Formal Teori: Furchgott Yedek Reseptör Matematiği\",\"ar\":\"النظرية الصورية: رياضيات المستقبِلات الاحتياطية لـ Furchgott\",\"en\":\"Formal Theory: Furchgott Spare Receptor Mathematics\"},\"prompt\":{\"tr\":\"Furchgott'un matematiksel modeline göre, bir dokuda yüksek oranda yedek reseptör rezervi bulunduğunda agonist için EC50 ile Kd ilişkisi nasıldır?\",\"ar\":\"وفق نموذج Furchgott الرياضي، عندما يمتلك النسيج فائضاً كبيراً من المستقبِلات الاحتياطية، ما العلاقة بين EC50 و Kd للمنبه؟\",\"en\":\"According to Furchgott's mathematical formulation, when a tissue possesses a large spare receptor reserve, what is the precise relationship between agonist EC50 and Kd?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-7a\",\"text\":{\"tr\":\"EC50 değeri Kd'den çok daha düşüktür (EC50 << Kd); doku maksimum cevaba reseptörlerin yalnızca küçük bir fraksiyonu dolduğunda ulaşır.\",\"ar\":\"قيمة EC50 أصغر بكثير من Kd (أي EC50 << Kd)؛ ويصل النسيج لأقصى استجابة بإشغال نسبة ضئيلة جداً من المستقبِلات.\",\"en\":\"EC50 is substantially lower than Kd (EC50 << Kd); tissue reaches maximal response when only a small fraction of receptors is bound.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel matematiksel kavrayış! Doku %50 yanıta reseptörlerin yalnızca %1'i dolduğunda ulaşabildiği için EC50 eğrisi Kd bağlama eğrisinin çok soluna kayar (Slayt 19).\",\"ar\":\"إدراك رياضي متقن! يتحقق نصف التأثير بإشغال 1% فقط من المستقبِلات؛ ولذا ينزاح منحنى الاستجابة EC50 بعيداً إلى يسار منحنى الارتباط Kd.\",\"en\":\"Flawless mathematical grasp! 50% response occurs at ~1% occupancy; hence the functional EC50 curve lies far to the left of the Kd binding curve.\"}},{\"id\":\"opt-7b\",\"text\":{\"tr\":\"EC50 değeri mutlaka Kd değerine tam olarak eşit olmak zorundadır (EC50 = Kd).\",\"ar\":\"يجب أن تتساوى قيمة EC50 تماماً مع قيمة Kd (أي EC50 = Kd).\",\"en\":\"The EC50 value must be strictly identical to Kd (EC50 = Kd) under all conditions.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Klasik yanılgı: EC50 = Kd eşitliği sadece yedek reseptörün sıfır olduğu ve lineer kenetlenen sistemlerde görülür; yedek reseptör olan dokularda EC50 << Kd'dir.\",\"ar\":\"خطأ النموذج القديم: تتساوى EC50 مع Kd فقط في غياب المستقبِلات الاحتياطية؛ أما بوجود الاحتياطي فالاستجابة تسبق الارتباط (EC50 << Kd).\",\"en\":\"Classic misconception: EC50 = Kd only when spare receptors are absent; in reserve-rich tissues, EC50 is far below Kd.\"}},{\"id\":\"opt-7c\",\"text\":{\"tr\":\"EC50 değeri Kd'den 1000 kat daha büyüktür çünkü yedek reseptörler ilacı nötralize eder.\",\"ar\":\"قيمة EC50 أكبر بألف ضعف من Kd لأن المستقبِلات الاحتياطية تعطل الدواء.\",\"en\":\"EC50 is 1000-fold larger than Kd because spare receptors neutralize active drug.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yedek reseptör fonksiyonu yanılgısı: Yedek reseptörler ilacı nötralize etmez; dokunun duyarlılığını artırarak düşük dozlarda bile tam yanıt üretmesini sağlar.\",\"ar\":\"خطأ وظيفة الاحتياطي: لا تعطل المستقبِلات الاحتياطية الدواء؛ بل تمنح الخلية حساسية فائقة للاستجابة بجرعات ضئيلة جداً.\",\"en\":\"Neutralization misconception: Spare receptors do not destroy drugs; they amplify cellular sensitivity, shifting curves leftward.\"}}]},\"technicalTerms\":[{\"term\":\"yedek reseptör rezervi\",\"arContext\":\"الاحتياطي الوظيفي للمستقبِلات\"},{\"term\":\"EC50 << Kd sola kayma\",\"arContext\":\"إزاحة الاستجابة لليسار (EC50 << Kd)\"}],\"hints\":[{\"tr\":\"Maksimum yanıt için reseptörlerin yalnızca %2'sinin işgal edilmesinin yettiği bir dokuyu hayal edin.\",\"ar\":\"تخيل نسيجاً تكفيه نسبة 2% فقط من إشغال المستقبِلات لإعطاء أقصى استجابة.\",\"en\":\"Picture a tissue where occupying only 2% of targets produces full maximal effect.\"},{\"tr\":\"Yarı maksimal (%50) yanıt için gereken ilaç konsantrasyonu (EC50) çok düşük olacaktır.\",\"ar\":\"سيكون تركيز الدواء اللازم لإحداث نصف الاستجابة (EC50) ضئيلاً جداً.\",\"en\":\"The drug concentration producing half-maximal response (EC50) will be miniscule.\"},{\"tr\":\"Kd ise reseptörlerin %50'sini doldurmak için gereken konsantrasyondur; dolayısıyla EC50 << Kd olur.\",\"ar\":\"بينما يتطلب Kd إشغال 50% من المستقبِلات فعلياً؛ ولذا يكون EC50 << Kd حتماً.\",\"en\":\"Kd requires 50% physical occupancy; hence EC50 << Kd by orders of magnitude.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":19}],\"config\":{\"options\":[{\"id\":\"opt-7a\",\"text\":\"EC50 değeri Kd'den çok daha düşüktür (EC50 << Kd); doku maksimum cevaba reseptörlerin yalnızca küçük bir fraksiyonu dolduğunda ulaşır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel matematiksel kavrayış! Doku %50 yanıta reseptörlerin yalnızca %1'i dolduğunda ulaşabildiği için EC50 eğrisi Kd bağlama eğrisinin çok soluna kayar (Slayt 19).\"},{\"id\":\"opt-7b\",\"text\":\"EC50 değeri mutlaka Kd değerine tam olarak eşit olmak zorundadır (EC50 = Kd).\",\"isCorrect\":false,\"misconceptionFeedback\":\"Klasik yanılgı: EC50 = Kd eşitliği sadece yedek reseptörün sıfır olduğu ve lineer kenetlenen sistemlerde görülür; yedek reseptör olan dokularda EC50 << Kd'dir.\"},{\"id\":\"opt-7c\",\"text\":\"EC50 değeri Kd'den 1000 kat daha büyüktür çünkü yedek reseptörler ilacı nötralize eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yedek reseptör fonksiyonu yanılgısı: Yedek reseptörler ilacı nötralize etmez; dokunun duyarlılığını artırarak düşük dozlarda bile tam yanıt üretmesini sağlar.\"}],\"revealedOutcome\":{\"tr\":\"Yedek reseptör varlığında fonksiyonel yanıt eğrisi bağlama eğrisinin solundadır (EC50 << Kd). Doku, toplam reseptörlerin çok küçük bir yüzdesi işgal edildiğinde Emax üretir.\",\"ar\":\"بوجود مستقبِلات احتياطية يقع منحنى الاستجابة إلى يسار منحنى الارتباط (EC50 << Kd)؛ ويتحقق Emax بإشغال نسبة مئوية ضئيلة من المستقبِلات.\",\"en\":\"In spare receptor systems, functional response lies left of binding (EC50 << Kd). Tissues achieve Emax when only a tiny fraction of receptors is occupied.\"},\"explanation\":{\"tr\":\"Furchgott teorisine göre hücre içi kaskad amplifikasyonu (1 aktif GPCR -> 100 G-proteini -> 10,000 cAMP), hücrenin yanıt kapasitesini reseptör doygunluğundan çok önce tüketir. Bu sayede EC50 Kd'den onlarca kat küçük olur (Slayt 19).\",\"ar\":\"وفق نظرية Furchgott، يؤدي التضخيم الخلوي (مستقبل واحد ينشط 100 بروتين G وآلاف جزيئات cAMP) لاستنفاد قدرة الخلية قبل تشبع المستقبِلات بكثير (EC50 << Kd).\",\"en\":\"Intracellular enzymatic amplification cascades saturate downstream effector capacity well before receptors reach saturation, driving EC50 far below Kd.\"}}},{\"id\":\"pharm-mod2-les1-step-08\",\"stage\":\"concept_check\",\"stageIndex\":8,\"type\":\"concept_check\",\"title\":{\"tr\":\"Kavram Kontrolü: İntrinsik Aktivite (alfa) Hesaplaması\",\"ar\":\"تحقق المفهوم: حساب الفاعلية الذاتية (alpha)\",\"en\":\"Concept Check: Calculating Intrinsic Activity (alpha)\"},\"prompt\":{\"tr\":\"Bir organ banyosunda tam agonist asetilkolin 100 gram kasılma üretirken, eşit reseptör işgalinde İlaç Z 40 gram kasılma üretmektedir. İlaç Z'nin intrinsik aktivitesi (alfa) nedir?\",\"ar\":\"في حمام نسيجي، يولد أستيل كولين (منبه كامل) تقلصاً بقوة 100 غرام، بينما يولد الدواء Z بنفس نسبة الإشغال 40 غراماً. ما الفاعلية الذاتية (alpha) للدواء Z؟\",\"en\":\"In an isolated tissue bath, full agonist acetylcholine elicits 100 g contraction. At identical receptor occupancy, Drug Z elicits 40 g. What is Drug Z's intrinsic activity (alpha)?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-8a\",\"text\":{\"tr\":\"alfa = 0.40; İlaç Z submaksimal yanıt üreten bir parsiyel agonisttir.\",\"ar\":\"alfa = 0.40؛ الدواء Z منبه جزئي يحقق استجابة دون القصوى.\",\"en\":\"alpha = 0.40; Drug Z is a partial agonist producing submaximal contraction.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz! Ariëns formülü: alfa = E_ilaç / E_tam_agonist = 40 g / 100 g = 0.40. İlaç Z 0 < alfa < 1 aralığında klasik bir parsiyel agonisttir.\",\"ar\":\"حساب متقن! قانون Ariëns: الفاعلية alfa = استجابة الدواء / أقصى استجابة للمنبه الكامل = 40 / 100 = 0.40، وهو منبه جزئي كلاسيكي.\",\"en\":\"Flawless! Ariëns formula: alpha = E_drug / E_full_agonist = 40 g / 100 g = 0.40, placing Drug Z squarely as a partial agonist.\"}},{\"id\":\"opt-8b\",\"text\":{\"tr\":\"alfa = 1.0; çünkü reseptörün tamamını doldurabilmektedir.\",\"ar\":\"alfa = 1.0؛ لأنه قادر على إشغال كامل المستقبِلات في النسيج.\",\"en\":\"alpha = 1.0; because it is capable of occupying 100% of available receptors.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"İşgal-etkinlik ayrımı yanılgısı: Reseptörlerin tamamını doldurmak afinite ile ilgilidir; intrinsik aktivite (alfa) üretilen yanıtın tavan oranıdır (40/100 = 0.40).\",\"ar\":\"خطأ الخلط بين الإشغال والفاعلية: يتبع الامتلاء للألفة والجرعة؛ أما الفاعلية الذاتية (alpha) فهي نسبة الاستجابة الناتجة (40/100 = 0.40).\",\"en\":\"Occupancy vs efficacy confusion: Occupying all targets reflects concentration; intrinsic activity (alpha) is the fractional response ratio (40/100 = 0.40).\"}},{\"id\":\"opt-8c\",\"text\":{\"tr\":\"alfa = 0; çünkü 100 gramlık tam yanıta ulaşamamıştır.\",\"ar\":\"alfa = 0؛ لأنه عجز عن الوصول للاستجابة التامة 100 غرام.\",\"en\":\"alpha = 0; because it failed to achieve the full 100 g biological contraction.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Sıfır efikasite yanılgısı: alfa = 0 kompetitif antagonistler için geçerlidir; 40 gram kasılma oluşturan bir ajan sıfır değil, parsiyel agonisttir (alfa = 0.40).\",\"ar\":\"خطأ الفاعلية الصفرية: تخص alfa = 0 المضادات النقية العاجزة عن إحداث أي تقلص؛ أما هنا فالاستجابة 40 غراماً تمثل منبهاً جزئياً.\",\"en\":\"Zero efficacy fallacy: alpha = 0 is reserved for pure antagonists; generating 40 g demonstrates partial agonism (alpha = 0.40).\"}}]},\"technicalTerms\":[{\"term\":\"intrinsik aktivite katsayısı (alfa)\",\"arContext\":\"معامل الفاعلية الذاتية (alpha)\"},{\"term\":\"organ banyosu biyoanalizi\",\"arContext\":\"المقايسة الحيوية في الحمام النسيجي\"}],\"hints\":[{\"tr\":\"Ariëns intrinsik aktivite formülünü hatırlayın: alfa = Emax(test) / Emax(tam agonist).\",\"ar\":\"تذكر قانون Ariëns للفاعلية الذاتية: alfa = أقصى استجابة للدواء / أقصى استجابة للمنبه الكامل.\",\"en\":\"Recall Ariëns' intrinsic activity equation: alpha = Emax(test) / Emax(full agonist).\"},{\"tr\":\"Test ilacı 40 g, tam agonist 100 g üretmiştir.\",\"ar\":\"أنتج الدواء المختبر 40 غراماً، بينما المنبه الكامل 100 غرام.\",\"en\":\"Test drug produces 40 g; full agonist produces 100 g.\"},{\"tr\":\"40 / 100 = 0.40.\",\"ar\":\"40 مقسومة على 100 تساوي 0.40.\",\"en\":\"40 divided by 100 equals 0.40.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":12}],\"config\":{\"options\":[{\"id\":\"opt-8a\",\"text\":\"alfa = 0.40; İlaç Z submaksimal yanıt üreten bir parsiyel agonisttir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz! Ariëns formülü: alfa = E_ilaç / E_tam_agonist = 40 g / 100 g = 0.40. İlaç Z 0 < alfa < 1 aralığında klasik bir parsiyel agonisttir.\"},{\"id\":\"opt-8b\",\"text\":\"alfa = 1.0; çünkü reseptörün tamamını doldurabilmektedir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"İşgal-etkinlik ayrımı yanılgısı: Reseptörlerin tamamını doldurmak afinite ile ilgilidir; intrinsik aktivite (alfa) üretilen yanıtın tavan oranıdır (40/100 = 0.40).\"},{\"id\":\"opt-8c\",\"text\":\"alfa = 0; çünkü 100 gramlık tam yanıta ulaşamamıştır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Sıfır efikasite yanılgısı: alfa = 0 kompetitif antagonistler için geçerlidir; 40 gram kasılma oluşturan bir ajan sıfır değil, parsiyel agonisttir (alfa = 0.40).\"}],\"revealedOutcome\":{\"tr\":\"İlaç Z'nin intrinsik aktivitesi alfa = 40 g / 100 g = 0.40'tır. 0 < alfa < 1 aralığında olduğu için klasik bir parsiyel agonisttir.\",\"ar\":\"الفاعلية الذاتية للدواء Z هي alfa = 40 / 100 = 0.40؛ وبما أنها تقع بين 0 و 1 فهو منبه جزئي كلاسيكي.\",\"en\":\"Drug Z's intrinsic activity alpha = 40 g / 100 g = 0.40. Falling between 0 and 1, it is a classic partial agonist.\"},\"explanation\":{\"tr\":\"Ariëns modelinde alfa katsayısı ilacın reseptörü ne derece aktif konformasyona geçirebildiğini gösterir. alfa = 1 tam agonist, alfa = 0 antagonist, aradaki değerler parsiyel agonisttir (Slayt 12).\",\"ar\":\"يقيس معامل alfa قدرة الدواء على تثبيت المستقبل في الحالة النشطة. يمثل 1 منبهاً كاملاً، و0 مضاداً، والقيم البينية منبهاً جزئياً.\",\"en\":\"The alpha coefficient quantifies a ligand's ability to drive active receptor conformation: alpha = 1 (full), alpha = 0 (antagonist), intermediate values (partial).\"}}},{\"id\":\"pharm-mod2-les1-step-09\",\"stage\":\"application\",\"stageIndex\":9,\"type\":\"clinical_vignette\",\"title\":{\"tr\":\"Klinik Protokol: Buprenorfin Geçişinde Yoksunluk Yönetimi\",\"ar\":\"بروتوكول سريري: إدارة الانتقال إلى البوبرينورفين وتجنب الانسحاب\",\"en\":\"Clinical Protocol: Managing Buprenorphine Transition Without Withdrawal\"},\"prompt\":{\"tr\":\"Opioid kullanım bozukluğu tedavisinde tam agonist metadondan parsiyel agonist buprenorfine geçiş yapılırken hasta neden en az 24 saat yoksunlukta bekletilir?\",\"ar\":\"في علاج الإدمان الأفيوني، عند الانتقال من ميثادون (منبه كامل) إلى بوبرينورفين (منبه جزئي)، لماذا يُترك المريض 24 ساعة على الأقل في حالة انسحاب؟\",\"en\":\"In opioid use disorder treatment, when transitioning from full agonist methadone to partial agonist buprenorphine, why must patients endure at least 24 hours of active withdrawal?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-9a\",\"text\":{\"tr\":\"Metadon reseptörlerden doğal olarak ayrışıp reseptör doluluğu düşmeden buprenorfin verilirse, yüksek afinitesiyle metadonu kovarak feci bir yoksunluk krizi tetikler.\",\"ar\":\"إذا أُعطي البوبرينورفين قبل انفصال الميثادون وهبوط نسبة الإشغال طبيعياً، سيطرد الميثادون بألفته العالية مفجراً نوبة انسحاب حادة كارثية.\",\"en\":\"If buprenorphine is given before methadone naturally dissociates and occupancy drops, its superior affinity will displace methadone, precipitating severe withdrawal.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kesinlikle hayati bir kural! Buprenorfin tam agonist doluluğu varken verilirse antagonist gibi davranır. Reseptörler boşalınca verildiğinde ise agonist gibi davranarak hastayı rahatlatır.\",\"ar\":\"قاعدة سريرية جوهرية! بوجود إشغال كامل للميثادون يتصرف البوبرينورفين كمضاد كابح؛ أما عند فراغ المستقبِلات فيعمل كمنبه يريح المريض.\",\"en\":\"Critical clinical dogma! In the presence of full agonist occupancy, buprenorphine functions as an antagonist; given when targets clear, it acts as a soothing agonist.\"}},{\"id\":\"opt-9b\",\"text\":{\"tr\":\"Metadon kanda buprenorfini kovalent olarak yıkarak ilacın karaciğere ulaşmasını engeller.\",\"ar\":\"يقوم الميثادون بتكسير البوبرينورفين تساهمياً في الدم مانعاً وصوله إلى الكبد.\",\"en\":\"Methadone chemically degrades circulating buprenorphine, preventing it from reaching hepatic targets.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kimyasal parçalanma yanılgısı: Metadon buprenorfini parçalamaz; etkileşim tamamen hedef mu-opioid reseptörü üzerindeki farmakodinamik yarışmadır.\",\"ar\":\"خطأ التخريب الكيميائي: لا يكسر الميثادون جزيئات البوبرينورفين؛ بل يدور التفاعل بالكامل حول التنافس على مستقبلات mu الأفيونية.\",\"en\":\"Chemical destruction error: Methadone does not degrade buprenorphine; competition is purely pharmacodynamic at mu receptors.\"}},{\"id\":\"opt-9c\",\"text\":{\"tr\":\"24 saatlik süre karaciğerin buprenorfin için yeni reseptörler sentezlemesi için biyolojik olarak zorunludur.\",\"ar\":\"فترة الـ 24 ساعة ضرورية بيولوجياً لقيام الكبد بتصنيع مستقبلات جديدة للبوبرينورفين.\",\"en\":\"The 24-hour interval is biologically required for the liver to synthesize brand-new buprenorphine receptors.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Reseptör sentez yeri yanılgısı: Karaciğer opioid reseptörü üretmez, nöronlar üretir; 24 saatlik bekleme süresi yeni reseptör sentezi için değil, metadonun reseptörden temizlenmesi içindir.\",\"ar\":\"خطأ مكان تصنيع المستقبلات: لا يصنع الكبد مستقبلات أفيونية، بل الخلايا العصبية؛ والهدف من الانتظار هو إفراغ المستقبِلات من الميثادون.\",\"en\":\"Anatomical misconception: The liver does not produce opioid receptors; 24 hours allows methadone dissociation, not de novo protein synthesis.\"}}]},\"technicalTerms\":[{\"term\":\"buprenorfin indüksiyon aralığı\",\"arContext\":\"فترة التحريض بالبوبرينورفين\"},{\"term\":\"mu-opioid reseptör kompetisyonu\",\"arContext\":\"التنافس على مستقبلات mu الأفيونية\"}],\"hints\":[{\"tr\":\"Buprenorfinin yüksek afiniteli bir parsiyel agonist olduğunu unutmayın.\",\"ar\":\"تذكر أن البوبرينورفين منبه جزئي فائق الألفة.\",\"en\":\"Remember that buprenorphine is a high-affinity partial agonist.\"},{\"tr\":\"Reseptörler metadon ile doluyken girerse uyarımı %100'den %35'e düşürür.\",\"ar\":\"إذا دخل والمستقبلات ممتلئة بالميثادون، سيهبط بالتحفيز من 100% إلى 35%.\",\"en\":\"If it binds while receptors are saturated with methadone, it drops activation to 35%.\"},{\"tr\":\"Metadonun reseptörden ayrışması ve reseptör doluluğunun düşmesi beklenmelidir.\",\"ar\":\"يجب انتظار انفصال الميثادون وهبوط نسبة الإشغال في المستقبِلات.\",\"en\":\"One must wait for methadone dissociation and declining target occupancy.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":12}],\"config\":{\"options\":[{\"id\":\"opt-9a\",\"text\":\"Metadon reseptörlerden doğal olarak ayrışıp reseptör doluluğu düşmeden buprenorfin verilirse, yüksek afinitesiyle metadonu kovarak feci bir yoksunluk krizi tetikler.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kesinlikle hayati bir kural! Buprenorfin tam agonist doluluğu varken verilirse antagonist gibi davranır. Reseptörler boşalınca verildiğinde ise agonist gibi davranarak hastayı rahatlatır.\"},{\"id\":\"opt-9b\",\"text\":\"Metadon kanda buprenorfini kovalent olarak yıkarak ilacın karaciğere ulaşmasını engeller.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kimyasal parçalanma yanılgısı: Metadon buprenorfini parçalamaz; etkileşim tamamen hedef mu-opioid reseptörü üzerindeki farmakodinamik yarışmadır.\"},{\"id\":\"opt-9c\",\"text\":\"24 saatlik süre karaciğerin buprenorfin için yeni reseptörler sentezlemesi için biyolojik olarak zorunludur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Reseptör sentez yeri yanılgısı: Karaciğer opioid reseptörü üretmez, nöronlar üretir; 24 saatlik bekleme süresi yeni reseptör sentezi için değil, metadonun reseptörden temizlenmesi içindir.\"}],\"revealedOutcome\":{\"tr\":\"Buprenorfin indüksiyon protokolü: Hastada objektif hafif yoksunluk belirtileri beklenir. Metadon reseptörleri terk ettiğinde buprenorfin agonist gibi davranarak semptomları yatıştırır.\",\"ar\":\"بروتوكول البوبرينورفين: انتظار ظهور علامات انسحاب موضوعية؛ فبمجرد مغادرة الميثادون للمستقبِلات يعمل البوبرينورفين كمنبه يخفف الأعراض بأمان.\",\"en\":\"Buprenorphine protocol: induction requires mild-moderate objective withdrawal. Once methadone clears targets, buprenorphine acts as an agonist, relieving distress.\"},\"explanation\":{\"tr\":\"Parsiyel agonistler koşullu davranır: Endojen agonist sinyali yüksekken onu baskılarlar (antagonizma), sinyal yokken ise uyarırlar (agonizma). Bu ilke buprenorfin indüksiyonunun temelini oluşturur (Slayt 12).\",\"ar\":\"تعمل المنبهات الجزئية بشكل شرطي: تكبح الإشارة عند تدفق المنبه الكامل، وتنشطها عند غيابه. ويشكل هذا المبدأ أساس بروتوكول العلاج بالبوبرينورفين.\",\"en\":\"Partial agonists are conditional: damping high full-agonist signaling while elevating sub-basal tones. This governs safe buprenorphine induction timing.\"}}},{\"id\":\"pharm-mod2-les1-step-10\",\"stage\":\"retrieval\",\"stageIndex\":10,\"type\":\"retrieval\",\"title\":{\"tr\":\"Geri Çağırma: Agonist ve Antagonist Spektrumu\",\"ar\":\"استرجاع: طيف المنبهات والمضادات الحيوية\",\"en\":\"Active Recall: Agonist-Antagonist Spectrum\"},\"prompt\":{\"tr\":\"Bir doz-yanıt deneyinde test edilen üç ajandan hangisi reseptöre yüksek afiniteyle bağlanmasına rağmen alfa = 0 olduğu için hiçbir biyolojik stimulus üretemez?\",\"ar\":\"بين ثلاثة مركبات في تجربة الجرعة والاستجابة، أي مركب يرتبط بالمستقبل بألفة عالية لكنه لا يولد أي تحفيز حيوي لكون alfa = 0؟\",\"en\":\"Among three agents evaluated in a dose-response assay, which binds targets with high affinity yet generates zero biological stimulus because its intrinsic activity alpha = 0?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-10a\",\"text\":{\"tr\":\"Saf kompetitif antagonist (örn. nalokson); afinitesi vardır ancak intrinsik aktivitesi sıfırdır (alfa = 0).\",\"ar\":\"المضاد التنافسي النقي (مثل نالوكسون)؛ يملك ألفة ارتباط قوية لكن فاعليته الذاتية معدومة (alfa = 0).\",\"en\":\"Pure competitive antagonist (e.g., naloxone); possessing robust affinity yet zero intrinsic activity (alpha = 0).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Ariëns sınıflamasında alfa = 0 kompetitif antagonistleri tanımlar. Reseptöre bağlanırlar ancak aktif konformasyonu tetikleyemezler.\",\"ar\":\"صحيح! يعرف تصنيف Ariëns المضادات بـ alfa = 0؛ فهي ترسو بالجيب لكنها تعجز عن تحفيز البنية النشطة للمستقبل.\",\"en\":\"Correct! Ariëns classifies pure antagonists as alpha = 0. They occupy binding alcoves without stabilizing active conformations.\"}},{\"id\":\"opt-10b\",\"text\":{\"tr\":\"Tam agonist (örn. fentanil); en yüksek afiniteye sahip olduğu için daima alfa = 0 kabul edilir.\",\"ar\":\"المنبه الكامل (مثل فنتانيل)؛ لامتلاكه أعلى ألفة يعتبر دوماً ذو alfa = 0.\",\"en\":\"Full agonist (e.g., fentanyl); having the highest affinity, it is designated with alpha = 0.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Tam agonist katsayısı yanılgısı: Tam agonist maksimum stimulus üretir ve alfa = 1.0 olarak tanımlanır, alfa = 0 değil.\",\"ar\":\"خطأ معامل المنبه الكامل: يحقق المنبه الكامل أقصى تحفيز وتكون alfa = 1.0 لديه وليست صفراً.\",\"en\":\"Full agonist coefficient error: Full agonists produce maximum activation and have alpha = 1.0, not zero.\"}},{\"id\":\"opt-10c\",\"text\":{\"tr\":\"Ters agonist (örn. rimonabant); bazal konstitütif aktiviteyi sıfırladığı için afinitesi sıfırdır.\",\"ar\":\"المنبه العكسي (مثل ريمونابانت)؛ يملك ألفة معدومة لأنه يخمد النشاط التأسيسي القاعدي.\",\"en\":\"Inverse agonist (e.g., rimonabant); having zero affinity because it silences basal constitutive activity.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Ters agonist afinite yanılgısı: Ters agonistlerin yüksek afinitesi vardır; inaktif konformasyonu stabilize ederek bazal aktiviteyi sıfırın altına çekerler (alfa < 0).\",\"ar\":\"خطأ ألفة المنبه العكسي: يمتلك المنبه العكسي ألفة عالية جداً، ويخفض النشاط القاعدي لما دون الصفر (alfa < 0).\",\"en\":\"Inverse agonist affinity error: Inverse agonists possess high affinity; they stabilize inactive states below baseline (alpha < 0).\"}}]},\"technicalTerms\":[{\"term\":\"kompetitif antagonist (alfa = 0)\",\"arContext\":\"المضاد التنافسي (alfa = 0)\"},{\"term\":\"konstitütif aktivite\",\"arContext\":\"النشاط التأسيسي للمستقبل\"}],\"hints\":[{\"tr\":\"Afinite var (bağlanıyor) ama etki sıfır (uyarmıyor).\",\"ar\":\"الألفة موجودة (يرتبط) لكن التأثير معدوم (لا ينشط).\",\"en\":\"Affinity is present (it binds) but response is absent (no activation).\"},{\"tr\":\"Ariëns skalasında alfa = 0 değerini hatırlayın.\",\"ar\":\"تذكر القيمة alfa = 0 على مقياس Ariëns.\",\"en\":\"Recall the alpha = 0 value on Ariëns' scale.\"},{\"tr\":\"Bu ajan yarışmalı kompetitif antagonisttir (örn. nalokson).\",\"ar\":\"هذا المركب هو مضاد تنافسي (مثل النالوكسون).\",\"en\":\"This agent is a competitive antagonist (e.g., naloxone).\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":12}],\"config\":{\"options\":[{\"id\":\"opt-10a\",\"text\":\"Saf kompetitif antagonist (örn. nalokson); afinitesi vardır ancak intrinsik aktivitesi sıfırdır (alfa = 0).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Ariëns sınıflamasında alfa = 0 kompetitif antagonistleri tanımlar. Reseptöre bağlanırlar ancak aktif konformasyonu tetikleyemezler.\"},{\"id\":\"opt-10b\",\"text\":\"Tam agonist (örn. fentanil); en yüksek afiniteye sahip olduğu için daima alfa = 0 kabul edilir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Tam agonist katsayısı yanılgısı: Tam agonist maksimum stimulus üretir ve alfa = 1.0 olarak tanımlanır, alfa = 0 değil.\"},{\"id\":\"opt-10c\",\"text\":\"Ters agonist (örn. rimonabant); bazal konstitütif aktiviteyi sıfırladığı için afinitesi sıfırdır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Ters agonist afinite yanılgısı: Ters agonistlerin yüksek afinitesi vardır; inaktif konformasyonu stabilize ederek bazal aktiviteyi sıfırın altına çekerler (alfa < 0).\"}],\"revealedOutcome\":{\"tr\":\"Kompetitif antagonistler reseptöre yüksek afiniteyle bağlanır fakat intrinsik aktiviteleri sıfırdır (alfa = 0). Parsiyel agonistler 0 < alfa < 1, tam agonistler alfa = 1'dir.\",\"ar\":\"ترتبط المضادات التنافسية بألفة عالية لكن فاعليتها معدومة (alfa = 0)؛ المنبه الجزئي 0 < alfa < 1 والمنبه الكامل alfa = 1.\",\"en\":\"Competitive antagonists bind avidly with zero intrinsic efficacy (alpha = 0). Partial agonists have 0 < alpha < 1, full agonists alpha = 1.\"},\"explanation\":{\"tr\":\"Farmakolojik spektrum: Tam Agonist (alfa = 1) -> Parsiyel Agonist (0 < alfa < 1) -> Nötral Antagonist (alfa = 0) -> Ters Agonist (alfa < 0). Antagonist afiniteye sahiptir fakat biyolojik stimulus oluşturamaz (Slayt 12).\",\"ar\":\"الطيف الدوائي: منبه كامل (1) -> منبه جزئي (0 إلى 1) -> مضاد حيادي (0) -> منبه عكسي (أقل من 0). يملك المضاد ألفة خالية من أي تحفيز حيوي.\",\"en\":\"Pharmacological spectrum: Full Agonist (1) -> Partial (0-1) -> Neutral Antagonist (0) -> Inverse Agonist (<0). Antagonists bind without generating stimulus.\"}}},{\"id\":\"pharm-mod2-les1-step-11\",\"stage\":\"connection\",\"stageIndex\":11,\"type\":\"connection\",\"title\":{\"tr\":\"Kavramsal Köprü: Yaşlı Hastada Pindolol vs Propranolol\",\"ar\":\"جسر المفاهيم: بيندولول مقابل بروبرانولول في المسنين\",\"en\":\"Conceptual Bridge: Pindolol vs Propranolol in Geriatric Care\"},\"prompt\":{\"tr\":\"Dinlenim nabzı 52 olan yaşlı bir hipertansif hastada, propranolol yerine neden intrinsik sempatomimetik aktiviteye (ISA) sahip pindolol tercih edilir?\",\"ar\":\"لمريض مسن يعاني من ارتفاع ضغط ونبض منخفض بالراحة (52 نبضة/د)، لماذا يُفضل بيندولول ذو النشاط الودي الداخلي (ISA) على بروبرانولول؟\",\"en\":\"In an elderly hypertensive patient with resting bradycardia (52 bpm), why is pindolol (with intrinsic sympathomimetic activity) preferred over pure antagonist propranolol?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-11a\",\"text\":{\"tr\":\"Pindolol parsiyel agonisttir; dinlenimde kalpte bazal beta uyarımı sağlayarak aşırı bradikardi ve asistol riskini önlerken, egzersiz taşikardisini ve tansiyonu düşürür.\",\"ar\":\"بيندولول منبه جزئي؛ يحافظ على تنبيه بيتا قاعدي بالراحة لتجنب بطء القلب الشديد، بينما يكبح تسرع القلب الإجهادي ويروض الضغط.\",\"en\":\"Pindolol is a partial agonist; preserving baseline cardiac beta stimulation at rest to avert severe bradycardia, while suppressing exertional tachycardia and hypertension.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Klinik ustalık! Saf antagonist propranolol dinlenim nabzını 40'ın altına düşürerek kalp bloğu yapabilir. Pindolol parsiyel agonist profiliyle dinlenimde kalbi korur, eforda ise tansiyonu düşürür.\",\"ar\":\"إتقان سريري! قد يهبط بروبرانولول (المضاد النقي) بالنبض لما دون 40 مسبباً إحصاراً قلبياً؛ بينما يحمي بيندولول القلب بالراحة ويكبح الضغط بالجهد.\",\"en\":\"Clinical mastery! Pure antagonist propranolol drops resting pulse below 40 bpm (heart block). Pindolol buffers resting rate while controlling exertion pressure.\"}},{\"id\":\"opt-11b\",\"text\":{\"tr\":\"Pindolol kalsiyum kanallarını bloke ederek kalp atım hızını 120'ye sabitler.\",\"ar\":\"يقوم بيندولول بحصر قنوات الكالسيوم ليثبت ضربات القلب عند 120 نبضة/دقيقة.\",\"en\":\"Pindolol selectively blocks L-type calcium channels, fixing heart rate rigidly at 120 bpm.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"İlaç sınıfı yanılgısı: Pindolol bir kalsiyum bloker değildir, adrenerjik beta reseptör ligandıdır ve nabzı 120'ye çıkarmaz.\",\"ar\":\"خطأ فئة الدواء: ليس بيندولول حاصراً للكالسيوم بل ربيط لمستقبلات بيتا الأدرينالينية، ولا يرفع النبض إلى 120.\",\"en\":\"Drug class misconception: Pindolol is a beta-adrenergic partial agonist, not a calcium channel blocker; it does not force rate to 120.\"}},{\"id\":\"opt-11c\",\"text\":{\"tr\":\"Pindolol propranololden 100 kat daha güçlü bir tam agonist olup kalbi sürekli aşırı uyarır.\",\"ar\":\"بيندولول منبه كامل أقوى بمئة ضعف من بروبرانولول ويحفز القلب باستمرار مفرط.\",\"en\":\"Pindolol is a full agonist 100-fold more potent than propranolol, perpetually driving cardiac tachycardia.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Agonist derecesi yanılgısı: Pindolol tam agonist değil, zayıf bir parsiyel agonisttir (alfa ≈ 0.20); kalbi aşırı uyarmaz, sadece durmasını engeller.\",\"ar\":\"خطأ درجة التنبيه: بيندولول ليس منبهاً كاملاً بل منبه جزئي خفيف (alfa ≈ 0.20)؛ لا يجهد القلب بل يمنع توقفه فقط.\",\"en\":\"Agonist grade error: Pindolol is a weak partial agonist (alpha ≈ 0.20), not a hyper-stimulating full agonist.\"}}]},\"technicalTerms\":[{\"term\":\"dinlenim bradikardisi\",\"arContext\":\"بطء القلب أثناء الراحة\"},{\"term\":\"parsiyel agonistik tamponlama\",\"arContext\":\"التخفيف التوازني بالمنبه الجزئي\"}],\"hints\":[{\"tr\":\"Hastanın nabzının zaten 52 (bradikardik) olduğunu dikkate alın.\",\"ar\":\"انتبه إلى أن نبض المريض منخفض أصلاً (52 نبضة/دقيقة).\",\"en\":\"Note that the patient's baseline heart rate is already bradycardic (52 bpm).\"},{\"tr\":\"Saf bir antagonist (propranolol) nabzı tehlikeli seviyede (örn. 38) düşürebilir.\",\"ar\":\"المضاد النقي (بروبرانولول) قد يهبط بالنبض لمستويات حرجة (38 نبضة/د).\",\"en\":\"A pure antagonist (propranolol) can crash heart rate into dangerous territory (<40 bpm).\"},{\"tr\":\"Parsiyel agonist pindolol bazal tonusu koruyarak aşırı bradikardiden korur.\",\"ar\":\"المنبه الجزئي بيندولول يحافظ على النغمة القاعدية ويحمي من بطء القلب المفرط.\",\"en\":\"Partial agonist pindolol maintains basal tone, shielding against catastrophic bradycardia.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":15}],\"config\":{\"options\":[{\"id\":\"opt-11a\",\"text\":\"Pindolol parsiyel agonisttir; dinlenimde kalpte bazal beta uyarımı sağlayarak aşırı bradikardi ve asistol riskini önlerken, egzersiz taşikardisini ve tansiyonu düşürür.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Klinik ustalık! Saf antagonist propranolol dinlenim nabzını 40'ın altına düşürerek kalp bloğu yapabilir. Pindolol parsiyel agonist profiliyle dinlenimde kalbi korur, eforda ise tansiyonu düşürür.\"},{\"id\":\"opt-11b\",\"text\":\"Pindolol kalsiyum kanallarını bloke ederek kalp atım hızını 120'ye sabitler.\",\"isCorrect\":false,\"misconceptionFeedback\":\"İlaç sınıfı yanılgısı: Pindolol bir kalsiyum bloker değildir, adrenerjik beta reseptör ligandıdır ve nabzı 120'ye çıkarmaz.\"},{\"id\":\"opt-11c\",\"text\":\"Pindolol propranololden 100 kat daha güçlü bir tam agonist olup kalbi sürekli aşırı uyarır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Agonist derecesi yanılgısı: Pindolol tam agonist değil, zayıf bir parsiyel agonisttir (alfa ≈ 0.20); kalbi aşırı uyarmaz, sadece durmasını engeller.\"}],\"revealedOutcome\":{\"tr\":\"Pindolol (ISA+), dinlenimde bazal sempatik deşarjı (%15-25) koruyarak bradikardik hastaları kardiyak arrestten korur; egzersizde ise tansiyon ve taşikardiyi baskılar.\",\"ar\":\"يحافظ بيندولول (ISA+) على نغمة ودية قاعدية (15-25%) تقي مريض بطء القلب من توقف النبض، بينما يكبح الضغط وتسرع القلب أثناء الجهد.\",\"en\":\"Pindolol (ISA+) sustains 15-25% baseline sympathetic drive, protecting bradycardic patients from heart block while controlling exertional pressure.\"},\"explanation\":{\"tr\":\"Parsiyel agonist beta blokerler 'akıllı moleküller' gibi davranır: Vücudun kendi sempatik tonusu düşükken zayıf bir kardiyak destek sağlar, katekolamin fırtınasında ise reseptörleri kapatarak aşırı uyarımı önler (Slayt 15).\",\"ar\":\"تسلك حاصرات بيتا ذات التنبيه الجزئي سلوكاً ذكياً: توفر دعماً قلبياً طفيفاً عند خمول الجهاز الودي، وتغلق المستقبِلات لحماية القلب عند فوران الأدرينالين.\",\"en\":\"ISA beta-blockers provide stabilizing bidirectional control: offering mild inotropic support at baseline while blunting dangerous catecholaminergic surges.\"}}},{\"id\":\"pharm-mod2-les1-step-12\",\"stage\":\"mastery_check\",\"stageIndex\":12,\"type\":\"mastery_check\",\"title\":{\"tr\":\"Ustalık Sınavı: Farmakolojik Yanıtın İki Belirleyicisi\",\"ar\":\"اختبار الإتقان: محددا الاستجابة الدوائية\",\"en\":\"Mastery Check: Two Determinants of Pharmacological Response\"},\"prompt\":{\"tr\":\"Bir molekülün aynı reseptör havuzunda bazen tam agonist, bazen parsiyel agonist, bazen de antagonist davranabilmesi farmakolojide hangi iki faktörün dinamik etkileşimiyle belirlenir?\",\"ar\":\"قدرة جزيء ما على التصرف كمنبه كامل تارة، وكمنبه جزئي أو مضاد تارة أخرى لنفس المستقبل، تتحدد بأي عاملين ديناميكيين في علم الأدوية؟\",\"en\":\"A drug's ability to act as a full agonist, partial agonist, or antagonist at the same receptor is dictated by which two interacting determinants?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-12a\",\"text\":{\"tr\":\"İlacın sahip olduğu sabit intrinsik efikasite (e) ile hedef dokunun reseptör yoğunluğu ve sinyal amplifikasyon kapasitesi (yedek reseptör rezervi).\",\"ar\":\"الفعالية الذاتية الثابتة للدواء (e) وكثافة مستقبِلات النسيج وقدرته على تضخيم الإشارة (الاحتياطي الوظيفي).\",\"en\":\"The drug's invariant intrinsic efficacy (e) interacting with the target tissue's receptor density and coupling amplification (spare receptor reserve).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz ustalık! Stephenson ve Furchgott'un modern farmakolojiye en büyük katkısı budur: Efikasite ilaca, rezerv ise dokuya aittir. İkisinin çarpımı klinik yanıtı belirler (Slayt 19, 22).\",\"ar\":\"إتقان دوائي رفيع! هذه أعظم مساهمة لـ Stephenson و Furchgott: الفعالية ملك للدواء والاحتياطي ملك للنسيج، وحاصل تفاعلهما هو المحدد للاستجابة السريرية.\",\"en\":\"Flawless mastery! Stephenson and Furchgott's enduring insight: efficacy belongs to the drug, reserve belongs to the tissue; their interplay dictates clinical response.\"}},{\"id\":\"opt-12b\",\"text\":{\"tr\":\"İlacın molekül ağırlığı ile hastanın idrar pH'sının asitliği.\",\"ar\":\"الوزن الجزيئي للدواء ودرجة حموضة بول المريض (pH).\",\"en\":\"The drug's molecular weight interacting with the acidity of patient urinary pH.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Farmakokinetik yanılgısı: Molekül ağırlığı ve idrar pH'sı renal atılımı belirler; reseptör seviyesindeki agonizma/antagonizma dengesini asla belirleyemez.\",\"ar\":\"خطأ حركية الدواء: يؤثر الوزن وحموضة البول على الإطراح الكلوي، ولا علاقة لهما بآلية التنبيه والمناهضة على مستوى المستقبل.\",\"en\":\"Pharmacokinetic confusion: Molecular weight and urine pH govern elimination; they have zero bearing on target efficacy mechanisms.\"}},{\"id\":\"opt-12c\",\"text\":{\"tr\":\"Yalnızca ilacın plazma serbest konsantrasyonu ile böbrek glomerüler filtrasyon hızı (GFR).\",\"ar\":\"فقط تركيز الدواء الحر في البلازما ومعدل الرشح الكبيبي الكلوي (GFR).\",\"en\":\"Solely the free plasma drug concentration and the patient's glomerular filtration rate (GFR).\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Farmakokinetik indirgemecilik yanılgısı: Plazma konsantrasyonu ve GFR yalnızca ilacın hedefe ulaşma miktarını belirler; ilacın dokuda tam mı parsiyel mi davranacağı ilacın intrinsik efikasitesi (e) ile dokunun reseptör rezervinin (yedek reseptör) etkileşimiyle belirlenir.\",\"ar\":\"مغالطة الاختزال الحركي: يحدد التركيز والرشح وصول الدواء فقط؛ بينما يحدد سلوكه كمنبه كامل أو جزئي التفاعل بين الفعالية الذاتية (e) والاحتياطي الوظيفي للمستقبلات في النسيج.\",\"en\":\"Pharmacokinetic reductionism fallacy: Plasma levels and GFR determine drug exposure; whether an agent acts as a full or partial agonist is governed by intrinsic efficacy (e) interacting with tissue receptor reserve.\"}}]},\"technicalTerms\":[{\"term\":\"intrinsik efikasite (e)\",\"arContext\":\"الفعالية الذاتية (intrinsic efficacy)\"},{\"term\":\"doku reseptör rezervi\",\"arContext\":\"احتياطي مستقبِلات النسيج\"}],\"hints\":[{\"tr\":\"Biri ilacın kimyasal yapısına ait (efikasite), diğeri ise hastanın hedef dokusuna aittir (rezonans/rezerv).\",\"ar\":\"أحدهما يخص بنية الدواء الكيميائية (الفعالية)، والآخر يخص نسيج المريض المستهدف (الاحتياطي).\",\"en\":\"One factor belongs to the drug molecule (efficacy); the other belongs to the target tissue (reserve).\"},{\"tr\":\"CR-10 örneğini hatırlayın: İlaç aynıydı, ancak dokudaki yedek reseptör havuzu farklıydı.\",\"ar\":\"تذكر تجربة CR-10: الدواء هو ذاته، لكن حوض المستقبِلات الاحتياطية اختلف بين النسيجين.\",\"en\":\"Recall the CR-10 case: the drug was identical, but target tissue receptor reserves differed.\"},{\"tr\":\"İlacın intrinsik efikasitesi (e) ile dokunun reseptör rezervinin çarpımı yanıtı belirler.\",\"ar\":\"حاصل تفاعل فعالية الدواء الذاتية (e) مع الاحتياطي الوظيفي للنسيج هو من يحدد النتيجة.\",\"en\":\"The interaction between drug efficacy (e) and tissue receptor reserve governs output.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":19},{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":22}],\"config\":{\"options\":[{\"id\":\"opt-12a\",\"text\":\"İlacın sahip olduğu sabit intrinsik efikasite (e) ile hedef dokunun reseptör yoğunluğu ve sinyal amplifikasyon kapasitesi (yedek reseptör rezervi).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz ustalık! Stephenson ve Furchgott'un modern farmakolojiye en büyük katkısı budur: Efikasite ilaca, rezerv ise dokuya aittir. İkisinin çarpımı klinik yanıtı belirler (Slayt 19, 22).\"},{\"id\":\"opt-12b\",\"text\":\"İlacın molekül ağırlığı ile hastanın idrar pH'sının asitliği.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Farmakokinetik yanılgısı: Molekül ağırlığı ve idrar pH'sı renal atılımı belirler; reseptör seviyesindeki agonizma/antagonizma dengesini asla belirleyemez.\"},{\"id\":\"opt-12c\",\"text\":\"Yalnızca ilacın plazma serbest konsantrasyonu ile böbrek glomerüler filtrasyon hızı (GFR).\",\"isCorrect\":false,\"misconceptionFeedback\":\"Farmakokinetik indirgemecilik yanılgısı: Plazma konsantrasyonu ve GFR yalnızca ilacın hedefe ulaşma miktarını belirler; ilacın dokuda tam mı parsiyel mi davranacağı ilacın intrinsik efikasitesi (e) ile dokunun reseptör rezervinin (yedek reseptör) etkileşimiyle belirlenir.\"}],\"revealedOutcome\":{\"tr\":\"Farmakolojik yanıt, ilacın sahip olduğu intrinsik efikasite (e) ile dokunun reseptör rezervinin ortak ürünüdür. Bu dinamik ilişki bir ilacın farklı dokularda neden farklı yanıtlar verdiğini açıklar.\",\"ar\":\"الاستجابة الدوائية ثمرة مشتركة لفاعلية الدواء الذاتية (e) واحتياطي مستقبِلات النسيج؛ وتفسر هذه الديناميكية تباين استجابة الأنسجة لنفس الدواء.\",\"en\":\"Pharmacological response is the joint product of drug intrinsic efficacy (e) and tissue receptor reserve, explaining why a single ligand displays divergent tissue behaviors.\"},\"explanation\":{\"tr\":\"Modern reseptör teorisinin zirvesi: İlaç molekülü reseptöre 'efikasite' (e) kazandırır; doku ise bu uyarıyı 'yedek reseptör ve efektör kaskadı' ile büyütür. Bu iki bileşeni anlamak rasyonel farmakoterapiyi yönetmenin anahtarıdır (Slayt 19, 22).\",\"ar\":\"قمة نظرية المستقبلات الحديثة: يمنح الدواء المستقبل الفعالية (e)، بينما يضخم النسيج هذا التحفيز عبر الاحتياطي وشلال الإشارات الخلوية.\",\"en\":\"Pinnacle of modern pharmacodynamics: drugs contribute intrinsic efficacy (e); tissues contribute receptor reserve and cascade amplification to create therapeutic response.\"}}}]},\"pharm-mod2-les2\":{\"$schema\":\"../../../packages/platform/schema/lesson.schema.json\",\"id\":\"pharm-mod2-les2\",\"courseId\":\"pharmacology\",\"moduleId\":\"ph-mod-02\",\"title\":{\"tr\":\"Reseptör Antagonizmi: Yarışmalı ve Yarışmasız Blokaj\",\"ar\":\"مناهضة المستقبِلات: الحصار التنافسي وغير التنافسي\",\"en\":\"Receptor Antagonism: Competitive & Non-Competitive Blockade\"},\"order\":2,\"access\":\"free\",\"objective\":{\"tr\":\"Yarışmalı (kompetitif) ve yarışmasız (non-kompetitif) antagonizma mekanizmalarını ayırt etmek, Schild denklemini uygulayarak pA2 ve Kb afinitesini hesaplamak.\",\"ar\":\"التمييز بين آليات المناهضة التنافسية وغير التنافسية، وتطبيق معادلة Schild لحساب pA2 وثابت الألفة Kb بدقة.\",\"en\":\"Distinguish competitive from non-competitive antagonism mechanisms, and apply the Schild equation to calculate pA2 and Kb affinity constants.\"},\"misconceptions\":[{\"tr\":\"Yarışmasız (allosterik veya kovalent) antagonistlerin oluşturduğu biyolojik blokajın ortamdaki agonist konsantrasyonu sonsuza kadar artırılarak aşılabileceği yanılgısı.\",\"ar\":\"الاعتقاد الخاطئ بإمكانية التغلب على الحصار غير التنافسي (التباعدي أو التساهمي) بمجرد زيادة تركيز المنبه إلى ما لا نهاية.\",\"en\":\"The misconception that non-competitive or irreversible blockade can eventually be overcome by escalating agonist concentration indefinitely.\"},{\"tr\":\"pA2 değerinin antagonistin toksik veya ölümcül dozunu temsil ettiği yanılgısı (aslında doz oranını r=2 yapan afinite indeksidir: pA2 = -log Kb).\",\"ar\":\"الظن الخاطئ بأن قيمة pA2 تعبر عن الجرعة السامة أو القاتلة للمضاد (بينما هي مؤشر ألفة المضاد الذي يضاعف جرعة المنبه: pA2 = -log Kb).\",\"en\":\"The misconception that pA2 reflects an antagonist's toxicity or lethal dose, rather than its equilibrium affinity index where r = 2 (pA2 = -log Kb).\"},{\"tr\":\"Aşırı doz fentanil zehirlenmesinde tek bir ampul nalokson uygulamasının hastayı kalıcı olarak kurtaracağı varsayımı (naloksonun yarı ömrü fentanilden çok daha kısadır, etki geçince solunum arresti tekrarlar).\",\"ar\":\"الافتراض الخاطئ بأن جرعة وحيدة من النالوكسون كافية لعلاج التسمم بالفنتانيل بشكل نهائي (عمر النصف للنالوكسون أقصر بكثير، وسيعود التثبيط التنفسي).\",\"en\":\"The dangerous assumption that a single dose of naloxone permanently resolves fentanyl overdose, ignoring that naloxone's short half-life permits rebound respiratory arrest.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":24},{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":26},{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":28},{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":30},{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":33}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Goodman & Gilman's The Pharmacological Basis of Therapeutics\",\"edition\":\"14th ed.\",\"topic\":\"Receptor Antagonism: Competitive, Noncompetitive, and Schild Analysis\",\"chapter\":\"Chapter 3\",\"page\":\"60-80\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Katzung Basic & Clinical Pharmacology\",\"edition\":\"15th ed.\",\"topic\":\"Competitive & Irreversible Antagonists, Allosteric Modulators, and Quantitation\",\"chapter\":\"Chapter 2\",\"page\":\"28-44\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"pharm-mod2-les2-card1\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Kompetitif Antagonizma Eğri Belirtisi\",\"prompt\":\"Yarışmalı (kompetitif) bir antagonist agonist doz-yanıt eğrisinde ne tür bir değişim yaratır?\",\"answer\":\"Maksimum yanıtı (Emax) değiştirmeden eğriyi paralel olarak sağa kaydırır; artan agonist dozuyla blokaj tamamen aşılabilir (surmountable).\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod2-les2-card2\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Non-Kompetitif / İrreversibl Antagonizma\",\"prompt\":\"Non-kompetitif veya geri dönüşümsüz (kovalent) antagonistlerin eğrideki karakteristik imzası nedir?\",\"answer\":\"Yedek reseptör rezervi aşıldıktan sonra maksimum yanıt tavanını (Emax) aşılmaz biçimde aşağı bastırır (depresyon).\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod2-les2-card3\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Schild Eşitliği ve Eğim 1.0\",\"prompt\":\"Schild grafiğinde log(r-1) vs log[B] doğrusunun eğiminin tam 1.0 çıkması neyi kanıtlar?\",\"answer\":\"Antagonist ile agonistin tek bir reseptör cebi için 1:1 oranında yarışmalı (kompetitif) etkileştiğini kanıtlar.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod2-les2-card4\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"pA2 Değeri Tanımı ve Anlamı\",\"prompt\":\"Schild analizindeki pA2 değeri biyofiziksel olarak neyi ifade eder?\",\"answer\":\"Agonistin aynı yanıtı vermesi için dozunu 2 katına (doz oranı r = 2) çıkarmayı gerektiren antagonist derişiminin negatif logaritmasıdır (-log Kb).\",\"box\":1,\"intervalDays\":1}],\"translations\":{\"tr\":{\"title\":\"Reseptör Antagonizmi: Yarışmalı ve Yarışmasız Blokaj\"},\"ar\":{\"title\":\"مناهضة المستقبِلات: الحصار التنافسي وغير التنافسي\"}},\"steps\":[{\"id\":\"pharm-mod2-les2-step-01\",\"stage\":\"hook\",\"stageIndex\":1,\"type\":\"predict_reveal\",\"title\":{\"tr\":\"Klinik Paradoks: Aşılabilen ve Aşılamayan Blokaj\",\"ar\":\"مفارقة سريرية: الحصار القابل وغير القابل للتجاوز\",\"en\":\"Clinical Paradox: Surmountable vs Insurmountable Blockade\"},\"prompt\":{\"tr\":\"Organ banyosunda atropinle durdurulan bağırsak kasılması asetilkolin artırılarak tamamen kurtarılırken; feokromositomada fenoksibenzamin blokajı devasa adrenalin patlamalarıyla neden aşılamaz?\",\"ar\":\"بينما يُستعاد تقلص الأمعاء المحصور بالأتروبين بزيادة تركيز أستيل كولين، يعجز الأدرينالين المتدفق بغزارة في ورم القواتم عن كسر حصار فينوكسي بنزامين! لماذا؟\",\"en\":\"While intestinal spasm blocked by atropine is fully restored by adding acetylcholine, phenoxybenzamine blockade in pheochromocytoma resists even massive adrenaline surges. Why?\"},\"predictThenReveal\":true,\"conceptCheck\":{\"options\":[{\"id\":\"opt-1a\",\"text\":{\"tr\":\"Atropin tersinir yarışmalı (kompetitif) olup agonist artışıyla aşılabilir; fenoksibenzamin ise alfa reseptörleri kovalent alkilasyonla kalıcı kilitlediği için aşılamaz (insurmountable).\",\"ar\":\"الأتروبين مضاد تنافسي عكوس يمكن تجاوزه بزيادة المنبه؛ بينما يقفل فينوكسي بنزامين مستقبلات ألفا تساهمياً بشكل غير عكوس وغير قابل للتجاوز.\",\"en\":\"Atropine is a reversible competitive blocker surmounted by excess agonist; phenoxybenzamine locks alpha receptors irreversibly via covalent alkylation.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Kompetitif antagonistler dinamik dengededir ve aşırı agonist tarafından kovulabilir (surmountable). Kovalent veya non-kompetitif antagonistler ise reseptör sayısını eksilttiği için aşılamaz (insurmountable).\",\"ar\":\"صحيح! تخضع المضادات التنافسية لتوازن حركي ويمكن للمنبه طردها؛ بينما تنقص المواد التساهمية حوض المستقبِلات بشكل نهائي غير قابل للكسر.\",\"en\":\"Correct! Competitive blockers follow dynamic equilibria and can be outcompeted; covalent alkylators permanently diminish functional target pools.\"}},{\"id\":\"opt-1b\",\"text\":{\"tr\":\"Atropin kanda asetilkolini kovalent parçalar; fenoksibenzamin ise adrenalinin kalbe girmesini mekanik olarak perdeler.\",\"ar\":\"يقوم الأتروبين بتفكيك أستيل كولين تساهمياً، بينما يشكل فينوكسي بنزامين حاجزاً ميكانيكياً يمنع دخول الأدرينالين للقلب.\",\"en\":\"Atropine covalently cleaves acetylcholine in blood, whereas phenoxybenzamine forms a physical barrier around cardiac tissue.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kimyasal parçalama yanılgısı: Atropin muskarinik reseptör aktif cebinde yarışır; asetilkolini parçalamaz. İki antagonistin farkı kovalent vs non-kovalent doğalarıdır.\",\"ar\":\"خطأ التفكيك الكيميائي: ينافس الأتروبين على الجيب النشط للمستقبل المسكاريني؛ والفارق الجوهري يكمن في عكوسية الروابط مقابل الرابطة التساهمية.\",\"en\":\"Degradation error: Atropine competes at muscarinic receptor pockets; the divergence stems from reversible versus covalent chemical bonding.\"}},{\"id\":\"opt-1c\",\"text\":{\"tr\":\"Adrenalin fenoksibenzaminle temas ettiği anda tüm alfa reseptörlerini endositozla hücre içine çeker ve reseptör havuzunu yok eder.\",\"ar\":\"يقوم الأدرينالين فور ملامسة فينوكسي بنزامين ببلعمة جميع مستقبلات ألفا لداخل الخلية وتدمير مخزون المستقبلات.\",\"en\":\"Adrenaline instantly triggers complete endocytosis of all alpha receptors upon contact with phenoxybenzamine, destroying the surface receptor pool.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Ani internalizasyon yanılgısı: Reseptör endositozu ve down-regülasyonu dakikalar-saatler süren hücresel bir süreçtir; fenoksibenzamin blokajının aşılamamasının nedeni reseptörün aktif bölgesindeki kalıcı kovalent alkilasyondur.\",\"ar\":\"مغالطة البلعمة الفورية: سحب المستقبلات عملية خلوية بطيئة؛ عدم القدرة على تجاوز حصار فينوكسي بنزامين سببه الألكلة التساهمية الدائمة للموقع الفعال.\",\"en\":\"Instantaneous internalization misconception: Receptor downregulation requires minutes to hours; phenoxybenzamine insurmountable blockade is strictly caused by irreversible covalent alkylation.\"}}]},\"technicalTerms\":[{\"term\":\"aşılabilir (surmountable) blokaj\",\"arContext\":\"حصار قابل للتجاوز (surmountable)\"},{\"term\":\"aşılamaz (insurmountable) blokaj\",\"arContext\":\"حصار غير قابل للتجاوز (insurmountable)\"}],\"hints\":[{\"tr\":\"Ligandın reseptör cebinden ayrılıp ayrılamayacağını (reversibilite) düşünün.\",\"ar\":\"فكر في قدرة الربيط على الانفصال عن جيب المستقبل (العكوسية).\",\"en\":\"Consider whether the ligand can dissociate from the binding pocket (reversibility).\"},{\"tr\":\"Atropin tersinir non-kovalent bağlarla tutunur; asetilkolin artırılınca yarışmayı kazanır.\",\"ar\":\"يرتبط الأتروبين بروابط غير تساهمية عكوسة، فيطرده أستيل كولين بزيادة الجرعة.\",\"en\":\"Atropine binds reversibly via non-covalent forces; adding acetylcholine outcompetes it.\"},{\"tr\":\"Fenoksibenzamin kovalent alkilasyon yapar (50-150 kcal/mol); adrenalin ne kadar çok olursa olsun bağı koparamaz.\",\"ar\":\"يؤسس فينوكسي بنزامين ألكلة تساهمية؛ ومهما زاد الأدرينالين فلن يستطيع كسر الرابطة.\",\"en\":\"Phenoxybenzamine alkylates targets covalently; no amount of adrenaline can break that bond.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":24}],\"config\":{\"options\":[{\"id\":\"opt-1a\",\"text\":\"Atropin tersinir yarışmalı (kompetitif) olup agonist artışıyla aşılabilir; fenoksibenzamin ise alfa reseptörleri kovalent alkilasyonla kalıcı kilitlediği için aşılamaz (insurmountable).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Kompetitif antagonistler dinamik dengededir ve aşırı agonist tarafından kovulabilir (surmountable). Kovalent veya non-kompetitif antagonistler ise reseptör sayısını eksilttiği için aşılamaz (insurmountable).\"},{\"id\":\"opt-1b\",\"text\":\"Atropin kanda asetilkolini kovalent parçalar; fenoksibenzamin ise adrenalinin kalbe girmesini mekanik olarak perdeler.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kimyasal parçalama yanılgısı: Atropin muskarinik reseptör aktif cebinde yarışır; asetilkolini parçalamaz. İki antagonistin farkı kovalent vs non-kovalent doğalarıdır.\"},{\"id\":\"opt-1c\",\"text\":\"Adrenalin fenoksibenzaminle temas ettiği anda tüm alfa reseptörlerini endositozla hücre içine çeker ve reseptör havuzunu yok eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Ani internalizasyon yanılgısı: Reseptör endositozu ve down-regülasyonu dakikalar-saatler süren hücresel bir süreçtir; fenoksibenzamin blokajının aşılamamasının nedeni reseptörün aktif bölgesindeki kalıcı kovalent alkilasyondur.\"}],\"revealedOutcome\":{\"tr\":\"Atropin kompetitif antagonisttir: Agonist artırılarak blokaj tamamen aşılabilir (surmountable, Emax korunur). Fenoksibenzamin kovalent/irreversibl blokerdir: Agonist ne kadar artırılırsa artırılsın blokaj aşılamaz (insurmountable, Emax çöker).\",\"ar\":\"الأتروبين مضاد تنافسي: يمكن كسر حصاره بالكامل بزيادة المنبه (Emax ثابت). أما فينوكسي بنزامين فمضاد تساهمي غير عكوس: لا يمكن كسر حصاره أبداً (يهبط سقف Emax).\",\"en\":\"Atropine is competitive: blockade is fully surmountable by excess agonist (preserved Emax). Phenoxybenzamine is irreversible: blockade is insurmountable (depressed Emax).\"},\"explanation\":{\"tr\":\"Antagonizma sınıflamasında temel ayrım: Kompetitif antagonistler aynı ortosterik bölgeye tersinir bağlanarak eğriyi paralel sağa kaydırır (surmountable). Non-kompetitif veya kovalent antagonistler ise Emax tavanını aşılmaz biçimde ezer (Farmakodinami Slayt 24).\",\"ar\":\"التصنيف الجوهري للمناهضة: ترتبط المضادات التنافسية عكوسياً بنفس الموقع لتزيح المنحنى يميناً، بينما تهبط المضادات غير التنافسية أو التساهمية بسقف Emax قسراً.\",\"en\":\"Fundamental distinction: competitive blockers bind orthosteric sites reversibly (parallel right shift, surmountable); non-competitive/covalent blockers crush Emax.\"}}},{\"id\":\"pharm-mod2-les2-step-02\",\"stage\":\"question\",\"stageIndex\":2,\"type\":\"question\",\"title\":{\"tr\":\"Karakteristik İmza: Paralel Sağa Kayma\",\"ar\":\"البصمة المميزة: الانزياح الموازي نحو اليمين\",\"en\":\"Characteristic Signature: Parallel Rightward Shift\"},\"prompt\":{\"tr\":\"Konsantrasyon-yanıt eğrisinde kompetitif bir antagonistin varlığında eğrinin eğimi ve maksimum tavanı (Emax) değişmeden sağa paralel kayması neyi kanıtlar?\",\"ar\":\"على منحنى التركيز والاستجابة، ماذا يثبت انزياح المنحنى يميناً بشكل موازٍ مع بقاء الميل وأقصى استجابة (Emax) دون تغيير بوجود مضاد تنافسي؟\",\"en\":\"On a concentration-response plot, what does a parallel rightward shift with preserved slope and unchanged maximal response (Emax) prove regarding antagonism?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-2a\",\"text\":{\"tr\":\"Antagonist ve agonistin aynı ortosterik bağlanma bölgesi için yarıştığını ve yeterli agonist verildiğinde blokajın tamamen aşılabileceğini kanıtlar.\",\"ar\":\"يثبت تنافس المنبه والمضاد على نفس موقع الارتباط الأصيل (orthosteric)، وإمكانية التغلب على الحصار تماماً بزيادة المنبه.\",\"en\":\"It proves that agonist and antagonist compete for identical orthosteric sites, and that antagonism is fully surmountable by escalating agonist.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Eğim ve Emax değişmeksizin eğrinin sağa kayması (surmountable rightward shift) klasik kompetitif farmakolojik antagonizmanın altın standardıdır (Slayt 26).\",\"ar\":\"صحيح! انزياح المنحنى يميناً بشكل موازٍ مع ثبات الميل وEmax هو المعيار الذهبي لإثبات المناهضة التنافسية الدوائية الحقيقية.\",\"en\":\"Correct! A parallel rightward displacement with identical slope and unaltered Emax is the gold standard for competitive pharmacological antagonism.\"}},{\"id\":\"opt-2b\",\"text\":{\"tr\":\"Antagonistin reseptörü kalıcı olarak yıktığını ve yeni reseptör sentezlendiğini kanıtlar.\",\"ar\":\"يثبت أن المضاد قد خرب المستقبل نهائياً وتم تصنيع مستقبلات بديلة.\",\"en\":\"It proves that the antagonist permanently degraded the receptor, triggering de novo protein synthesis.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kalıcı hasar yanılgısı: Reseptör tahribatı Emax'ı çökerterek non-paralel depresyon yaratır; paralel sağa kayma dinamik ve tersinir yer değiştirmedir.\",\"ar\":\"خطأ التخريب الدائم: يؤدي تدمير المستقبِلات إلى هبوط سقف Emax؛ بينما يمثل الانزياح الموازي إزاحة حركية عكوسة نقية.\",\"en\":\"Destruction error: Target degradation depresses Emax; parallel rightward shifts represent reversible mass-action displacement.\"}},{\"id\":\"opt-2c\",\"text\":{\"tr\":\"Agonistin hücre içinde kovalent bağlar kurarak ilacın atılımını durdurduğunu kanıtlar.\",\"ar\":\"يثبت تشكيل المنبه روابط تساهمية داخل الخلية عطلت إطراح الدواء.\",\"en\":\"It proves that the agonist forms intracellular covalent bonds that halt drug clearance.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kinetik yanılgı: Doz-yanıt eğrileri reseptör işgalini gösterir; eliminasyon klirensi veya kovalent tutulma ile doğrudan ilişkili değildir.\",\"ar\":\"خطأ حركي: تقيس منحنيات الجرعة والاستجابة إشغال المستقبِلات؛ ولا علاقة لها بالإطراح أو الارتباط التساهمي الداخلي.\",\"en\":\"Kinetic confusion: In vitro dose-response measures receptor occupancy; it is unrelated to systemic clearance or covalent trapping.\"}}]},\"technicalTerms\":[{\"term\":\"paralel sağa kayma\",\"arContext\":\"الانزياح الموازي نحو اليمين\"},{\"term\":\"ortosterik bağlanma bölgesi\",\"arContext\":\"موقع الارتباط الأصيل (orthosteric site)\"}],\"hints\":[{\"tr\":\"Eğrinin eğimi değişmemiş ve tepe noktası (Emax) hala %100'e ulaşıyor.\",\"ar\":\"ميل المنحنى لم يتغير والقمة (Emax) ما تزال تبلغ 100%.\",\"en\":\"Curve slope is unchanged and the peak (Emax) still reaches 100%.\"},{\"tr\":\"Sadece aynı etkiyi almak için daha yüksek konsantrasyonda agonist gerekiyor.\",\"ar\":\"يتطلب الأمر فقط تركيزاً أعلى من المنبه للحصول على نفس الاستجابة.\",\"en\":\"Higher agonist concentrations are simply needed to match former response levels.\"},{\"tr\":\"Bu durum iki molekülün aynı cebe yarıştığını ve aşırı agonist ile antagonistin kovulabildiğini kanıtlar.\",\"ar\":\"يثبت هذا تنافس الجزيئين على نفس الجيب وإمكانية طرد المضاد بزيادة المنبه.\",\"en\":\"This proves both molecules vie for the same site, and excess agonist displaces the blocker.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":26}],\"config\":{\"options\":[{\"id\":\"opt-2a\",\"text\":\"Antagonist ve agonistin aynı ortosterik bağlanma bölgesi için yarıştığını ve yeterli agonist verildiğinde blokajın tamamen aşılabileceğini kanıtlar.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Eğim ve Emax değişmeksizin eğrinin sağa kayması (surmountable rightward shift) klasik kompetitif farmakolojik antagonizmanın altın standardıdır (Slayt 26).\"},{\"id\":\"opt-2b\",\"text\":\"Antagonistin reseptörü kalıcı olarak yıktığını ve yeni reseptör sentezlendiğini kanıtlar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kalıcı hasar yanılgısı: Reseptör tahribatı Emax'ı çökerterek non-paralel depresyon yaratır; paralel sağa kayma dinamik ve tersinir yer değiştirmedir.\"},{\"id\":\"opt-2c\",\"text\":\"Agonistin hücre içinde kovalent bağlar kurarak ilacın atılımını durdurduğunu kanıtlar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kinetik yanılgı: Doz-yanıt eğrileri reseptör işgalini gösterir; eliminasyon klirensi veya kovalent tutulma ile doğrudan ilişkili değildir.\"}],\"revealedOutcome\":{\"tr\":\"Paralel sağa kayma: Kompetitif antagonist ortamdayken Emax ve eğim korunur, yalnızca görünür EC50 artar (eğri sağa ötelenir). Bu durum yarışmalı ve aşılabilir blokajın kesin kanıtıdır.\",\"ar\":\"الانزياح الموازي: بوجود مضاد تنافسي يثبت Emax والميل ويزداد EC50 الظاهري فقط؛ وهو البرهان القاطع على المناهضة التنافسية القابلة للتجاوز.\",\"en\":\"Parallel rightward shift: In competitive antagonism, Emax and slope remain constant while apparent EC50 increases. This proves surmountable, orthosteric competition.\"},\"explanation\":{\"tr\":\"Gaddum denklemi: [DR] / [Rt] = [A] / ([A] + Ka * (1 + [B]/Kb)). Antagonist [B] arttıkça agonistin afinite paydası çarpanla büyür; bu durum eğriyi şeklini bozmadan sağa öteler (Slayt 26).\",\"ar\":\"معادلة Gaddum: وجود المضاد [B] يضاعف مقام الألفة بعامل تمدد دون المساس بسعة النسيج القصوى، فينزاح المنحنى يميناً بتناظر تام.\",\"en\":\"Gaddum equation demonstrates that antagonist concentration [B] scales apparent Kd by (1 + [B]/Kb), shifting curves horizontally without altering maximum capacity.\"}}},{\"id\":\"pharm-mod2-les2-step-03\",\"stage\":\"intuition\",\"stageIndex\":3,\"type\":\"intuition\",\"title\":{\"tr\":\"Schild Sezgisi: Doz Oranı (r) Nedir?\",\"ar\":\"حدس Schild: ما هي نسبة الجرعة (r)؟\",\"en\":\"Schild Intuition: What is Dose Ratio (r)?\"},\"prompt\":{\"tr\":\"Doz oranı (r = [A']/[A]), antagonist varlığında aynı biyolojik yanıtı elde etmek için gereken agonist katıdır. r = 10 ise bu durum ne anlama gelir?\",\"ar\":\"نسبة الجرعة (r = [A']/[A]) هي مضاعف المنبه اللازم لتحقيق نفس الاستجابة بوجود المضاد. إذا كانت r = 10، فماذا يعني ذلك حدسياً؟\",\"en\":\"The dose ratio (r = [A']/[A]) represents the fold-increase in agonist concentration needed to match control responses. What does r = 10 intuitively signify?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-3a\",\"text\":{\"tr\":\"Antagonist varlığında aynı biyolojik etkiyi (örneğin %50 kasılma) üretebilmek için agonist dozunu tam 10 kat artırmak gerekmektedir.\",\"ar\":\"يتطلب تحقيق نفس الاستجابة الحيوية (مثلاً 50% تقلص) بوجود المضاد مضاعفة جرعة المنبه 10 مرات تماماً.\",\"en\":\"To produce an identical biological effect (e.g. 50% contraction) in the presence of antagonist, agonist dose must be increased exactly 10-fold.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kesinlikle doğru! Doz oranı r, antagonistin yarattığı sağa kayma faktörüdür. r = 10 demek, ilacın aynı yanıtı vermesi için 10 kat daha yoğun verilmesi demektir (Slayt 28).\",\"ar\":\"صحيح تماماً! نسبة الجرعة r هي معامل الإزاحة لليمين؛ وتعني r = 10 مضاعفة الجرعة عشر مرات لمعادلة حجب المضاد.\",\"en\":\"Exactly right! Dose ratio r is the horizontal shift factor. r = 10 means 10-fold more agonist is required to match baseline activation.\"}},{\"id\":\"opt-3b\",\"text\":{\"tr\":\"Dokudaki reseptörlerin %90'ının kovalent olarak tahrip edildiği anlamına gelir.\",\"ar\":\"يعني أن 90% من مستقبلات النسيج قد دُمرت تساهمياً بشكل نهائي.\",\"en\":\"It means that 90% of tissue receptors have been covalently destroyed.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kovalent tahribat yanılgısı: Doz oranı kompetitif yarışmayı ifade eder; reseptörler sağlamdır ve agonist artırılarak hepsi geri kazanılabilir.\",\"ar\":\"خطأ التدمير التساهمي: تعبر نسبة الجرعة عن منافسة نقية؛ والمستقبلات سليمة تماماً ويمكن استعادتها بزيادة المنبه.\",\"en\":\"Covalent destruction error: Dose ratio reflects reversible competition; receptors remain functional and fully recoverable.\"}},{\"id\":\"opt-3c\",\"text\":{\"tr\":\"İlacın karaciğerdeki yarı ömrünün 10 dakikaya indiği anlamına gelir.\",\"ar\":\"يعني هبوط عمر النصف الحيوي للدواء في الكبد إلى 10 دقائق.\",\"en\":\"It means the drug's hepatic half-life has plummeted to 10 minutes.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Klirens yanılgısı: Doz oranı in vitro veya in vivo farmakodinamik reseptör afinite metriğidir; karaciğer yarı ömrüyle ilişkili değildir.\",\"ar\":\"خطأ التصفية الكبدية: نسبة الجرعة مقياس دوائي لديناميكا المستقبلات، ولا شأن لها بعمر النصف الاستقلابي.\",\"en\":\"Clearance error: Dose ratio measures target pharmacodynamics in tissue baths; it is unrelated to metabolic half-life.\"}}]},\"technicalTerms\":[{\"term\":\"doz oranı (dose ratio, r)\",\"arContext\":\"نسبة الجرعة (dose ratio, r)\"},{\"term\":\"Gaddum-Schild kayma faktörü\",\"arContext\":\"معامل إزاحة Gaddum-Schild\"}],\"hints\":[{\"tr\":\"r = [A'] / [A] formülünü inceleyin: Antagonistli doz bölü kontrol dozu.\",\"ar\":\"تأمل معادلة r = [A'] / [A]: تركيز المنبه بوجود المضاد مقسوماً على تركيز الشاهد.\",\"en\":\"Inspect r = [A'] / [A]: agonist concentration with antagonist divided by control.\"},{\"tr\":\"Eğer r = 10 ise, pay paydadan 10 kat daha büyüktür.\",\"ar\":\"إذا كانت r = 10، فالبسط أكبر من المقام بعشر مرات.\",\"en\":\"If r = 10, the numerator is 10 times larger than the denominator.\"},{\"tr\":\"Yani aynı etkiyi almak için 10 kat agonist dozu gerekir.\",\"ar\":\"أي أنك تحتاج لعشرة أضعاف الجرعة للحصول على نفس النتيجة.\",\"en\":\"Hence you need 10 times the agonist concentration to produce the same effect.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":28}],\"config\":{\"options\":[{\"id\":\"opt-3a\",\"text\":\"Antagonist varlığında aynı biyolojik etkiyi (örneğin %50 kasılma) üretebilmek için agonist dozunu tam 10 kat artırmak gerekmektedir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kesinlikle doğru! Doz oranı r, antagonistin yarattığı sağa kayma faktörüdür. r = 10 demek, ilacın aynı yanıtı vermesi için 10 kat daha yoğun verilmesi demektir (Slayt 28).\"},{\"id\":\"opt-3b\",\"text\":\"Dokudaki reseptörlerin %90'ının kovalent olarak tahrip edildiği anlamına gelir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kovalent tahribat yanılgısı: Doz oranı kompetitif yarışmayı ifade eder; reseptörler sağlamdır ve agonist artırılarak hepsi geri kazanılabilir.\"},{\"id\":\"opt-3c\",\"text\":\"İlacın karaciğerdeki yarı ömrünün 10 dakikaya indiği anlamına gelir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Klirens yanılgısı: Doz oranı in vitro veya in vivo farmakodinamik reseptör afinite metriğidir; karaciğer yarı ömrüyle ilişkili değildir.\"}],\"revealedOutcome\":{\"tr\":\"Doz oranı r = 10: Kompetitif antagonist varlığında eğri 10 kat sağa kaymıştır. Aynı kasılmayı oluşturmak için agonist derişimi tam 10 katına çıkarılmalıdır.\",\"ar\":\"نسبة الجرعة r = 10: انزاح المنحنى يميناً بمقدار 10 أضعاف؛ ويلزم رفع تركيز المنبه 10 مرات لإحداث نفس التأثير.\",\"en\":\"Dose ratio r = 10: The agonist curve shifts 10-fold rightward. Exactly 10 times more agonist is required to match baseline response.\"},\"explanation\":{\"tr\":\"Schild analizinin temeli doz oranına (r) dayanır: r - 1 = [B] / Kb. Doz oranı antagonist konsantrasyonuyla doğru orantılı olarak büyür (Slayt 28).\",\"ar\":\"يقوم تحليل Schild على نسبة الجرعة: r - 1 = [B] / Kb؛ حيث تتناسب الزيادة في نسبة الجرعة طرداً مع تركيز المضاد.\",\"en\":\"Schild analysis relies on dose ratio: r - 1 = [B] / Kb. As antagonist concentration [B] rises, the required agonist multiplier scales linearly.\"}}},{\"id\":\"pharm-mod2-les2-step-04\",\"stage\":\"visual_explanation\",\"stageIndex\":4,\"type\":\"visual_explanation\",\"title\":{\"tr\":\"Görsel Regresyon: Schild Grafiği ve pA2\",\"ar\":\"الانحدار البصري: مخطط Schild وقيمة pA2\",\"en\":\"Visual Regression: The Schild Plot & pA2\"},\"prompt\":{\"tr\":\"Schild regresyon grafiğinde log(r-1) değerine karşı log[B] çizildiğinde doğrunun eğiminin 1.0 çıkması ve x-ekseni kesişimi neyi ifade eder?\",\"ar\":\"في مخطط انحدار Schild، عند رسم log(r-1) مقابل log[B]، ماذا يعني ميل الخط البالغ 1.0 بالضبط ونقطة تقاطعه مع المحور السيني؟\",\"en\":\"In a Schild plot, when log(r-1) is plotted against log[B], what does a regression slope of exactly 1.0 and its x-intercept signify?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-4a\",\"text\":{\"tr\":\"Eğim 1.0 ise basit yarışmalı kompetitif antagonizmayı (1:1 bağlanma) doğrular; x-ekseni kesişimi ise antagonistin afinite sabiti olan pA2 (-log Kb) değerini verir.\",\"ar\":\"يثبت الميل 1.0 المناهضة التنافسية البسيطة (ارتباط 1:1)؛ ونقطة التقاطع مع المحور السيني تعطي قيمة pA2 (-log Kb) لألفة المضاد.\",\"en\":\"A slope of 1.0 confirms simple competitive antagonism (1:1 binding); the x-intercept yields the antagonist affinity index pA2 (-log Kb).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz! Schild denklemi: log(r-1) = log[B] - log(Kb). log(r-1)=0 (yani r=2) olduğunda log[B] = log(Kb) olur ve x-ekseni kesişimi doğrudan pA2 = -log(Kb)'yi verir (Slayt 28).\",\"ar\":\"إتقان تام! معادلة Schild: log(r-1) = log[B] - log(Kb). عند log(r-1)=0 (أي r=2) يصبح log[B] = log(Kb)، ونقطة التقاطع تعطي pA2 = -log(Kb).\",\"en\":\"Flawless! Schild equation: log(r-1) = log[B] - log(Kb). When log(r-1) = 0 (r=2), log[B] = log(Kb), and the intercept directly yields pA2.\"}},{\"id\":\"opt-4b\",\"text\":{\"tr\":\"Eğim 1.0 ise antagonistin reseptörü kovalent olarak parçaladığını doğrular; kesişim ise ilacın öldürücü dozunu (LD50) verir.\",\"ar\":\"يثبت الميل 1.0 أن المضاد فكك المستقبل تساهمياً، ونقطة التقاطع تعبر عن الجرعة القاتلة (LD50).\",\"en\":\"A slope of 1.0 proves covalent receptor degradation, while the intercept indicates the lethal median dose (LD50).\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kovalent yanılgısı: Kovalent ajanlarda Schild doğrusu kurulamaz (eğim 1 çıkmaz ve Emax düşer); Schild analizi saf tersinir kompetitif bağlanmanın kanıtıdır.\",\"ar\":\"خطأ التساهمية: تفشل معادلة Schild مع المواد التساهمية؛ فالميل 1.0 برهان حصري على التنافس العكوس النقي.\",\"en\":\"Covalent error: Covalent blockers distort Schild regressions; unity slope (1.0) strictly proves reversible orthosteric competition.\"}},{\"id\":\"opt-4c\",\"text\":{\"tr\":\"Eğim 1.0 ise agonist ile antagonistin kimyasal olarak nötralize olduğunu ve reseptörün devre dışı kaldığını gösterir.\",\"ar\":\"يدل الميل 1.0 على حدوث تعادل كيميائي بين المنبه والمضاد وخروج المستقبل من التفاعل.\",\"en\":\"A slope of 1.0 indicates that agonist and antagonist chemically neutralize each other, bypassing target receptors.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kimyasal nötralizasyon yanılgısı: Schild analizi reseptör düzeyindeki kompetisyonu inceler; moleküllerin birbirini kimyasal olarak yok etmesini değil.\",\"ar\":\"خطأ التعادل الكيميائي: يحلل مخطط Schild التنافس على جيب المستقبل الحيوي، وليس التفاعل الكيميائي المباشر في المحلول.\",\"en\":\"Neutralization error: Schild plots analyze receptor binding pocket equilibria, not direct solution chemistry neutralization.\"}}]},\"technicalTerms\":[{\"term\":\"Schild eşitliği\",\"arContext\":\"معادلة Schild\"},{\"term\":\"pA2 (-log Kb)\",\"arContext\":\"مؤشر pA2 (-log Kb)\"}],\"hints\":[{\"tr\":\"Schild doğrusunun formülü: y = m*x + c -> log(r-1) = 1.0 * log[B] - log(Kb).\",\"ar\":\"معادلة خط Schild: log(r-1) = 1.0 * log[B] - log(Kb).\",\"en\":\"Schild line equation: log(r-1) = 1.0 * log[B] - log(Kb).\"},{\"tr\":\"Eğim 1.0 çıktığında 1 agonist molekülüne karşı 1 antagonist molekülü yarışıyor demektir.\",\"ar\":\"عندما يكون الميل 1.0 فهذا يعني تنافس جزيء منبه واحد مع جزيء مضاد واحد.\",\"en\":\"Unity slope (1.0) confirms 1:1 equimolar competition at target binding pockets.\"},{\"tr\":\"Doğrunun y = 0 eksenini kestiği nokta pA2 (-log Kb) afinitesini verir.\",\"ar\":\"نقطة تقاطع الخط مع y = 0 تعطي قيمة pA2 مساوية لـ -log Kb.\",\"en\":\"The point intersecting y = 0 directly reveals antagonist affinity: pA2 = -log Kb.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":28}],\"config\":{\"options\":[{\"id\":\"opt-4a\",\"text\":\"Eğim 1.0 ise basit yarışmalı kompetitif antagonizmayı (1:1 bağlanma) doğrular; x-ekseni kesişimi ise antagonistin afinite sabiti olan pA2 (-log Kb) değerini verir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz! Schild denklemi: log(r-1) = log[B] - log(Kb). log(r-1)=0 (yani r=2) olduğunda log[B] = log(Kb) olur ve x-ekseni kesişimi doğrudan pA2 = -log(Kb)'yi verir (Slayt 28).\"},{\"id\":\"opt-4b\",\"text\":\"Eğim 1.0 ise antagonistin reseptörü kovalent olarak parçaladığını doğrular; kesişim ise ilacın öldürücü dozunu (LD50) verir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kovalent yanılgısı: Kovalent ajanlarda Schild doğrusu kurulamaz (eğim 1 çıkmaz ve Emax düşer); Schild analizi saf tersinir kompetitif bağlanmanın kanıtıdır.\"},{\"id\":\"opt-4c\",\"text\":\"Eğim 1.0 ise agonist ile antagonistin kimyasal olarak nötralize olduğunu ve reseptörün devre dışı kaldığını gösterir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kimyasal nötralizasyon yanılgısı: Schild analizi reseptör düzeyindeki kompetisyonu inceler; moleküllerin birbirini kimyasal olarak yok etmesini değil.\"}],\"revealedOutcome\":{\"tr\":\"Schild regresyonunda eğim = 1.0 ise bu basit kompetitif antagonizmanın kanıtıdır. Doğrunun yatay eksenle kesişim noktası antagonistin afinite ölçüsü olan pA2 (-log Kb) değeridir.\",\"ar\":\"في انحدار Schild، الميل = 1.0 يثبت المناهضة التنافسية النقية؛ ونقطة التقاطع مع المحور الأفقي تمثل قيمة pA2 (-log Kb) المعبرة عن ألفة المضاد.\",\"en\":\"In Schild regression, slope = 1.0 validates simple competitive antagonism. The x-axis intercept equals pA2 (-log Kb), quantifying antagonist affinity.\"},\"explanation\":{\"tr\":\"Schild analizi farmakolojide bir ilacın gerçek bir kompetitif antagonist olup olmadığını belirlemenin en titiz yöntemidir. Eğim 1.0'den istatistiksel olarak saparsa allosterik modülasyon veya non-spesifik bağlanma şüphe edilir (Slayt 28).\",\"ar\":\"يمثل تحليل Schild الطريقة الأكثر صرامة لإثبات المناهضة التنافسية؛ وأي انحراف للميل عن 1.0 يثير الشك بوجود تعديل تباعدي أو ارتباط غير نوعي.\",\"en\":\"Schild analysis is the definitive pharmacodynamic proof of competitive antagonism. Slopes deviating from 1.0 indicate allosteric effects or non-specific binding.\"}}},{\"id\":\"pharm-mod2-les2-step-05\",\"stage\":\"interactive_artifact\",\"stageIndex\":5,\"type\":\"dose_response_curve\",\"widgetType\":\"DoseResponseCurve\",\"title\":{\"tr\":\"İnteraktif Laboratuvar: Kompetitif vs Non-kompetitif Blokaj\",\"ar\":\"مختبر تفاعلي: الحصار التنافسي مقابل غير التنافسي\",\"en\":\"Interactive Lab: Competitive vs Non-Competitive Blockade\"},\"prompt\":{\"tr\":\"Doz-Yanıt laboratuvarında Kompetitif ve Non-kompetitif Antagonist modlarını test edin; artan antagonist dozlarında surmountable paralel kayma ile Emax çöküşünü karşılaştırın.\",\"ar\":\"في مختبر الجرعة والاستجابة، اختبر نمطي المضاد التنافسي وغير التنافسي؛ وقارن بين الإزاحة الموازية القابلة للتجاوز وانهيار سقف Emax عند زيادة الجرعة.\",\"en\":\"In the Dose-Response lab, toggle Competitive and Non-Competitive Antagonist modes; contrast surmountable parallel shifts against insurmountable Emax depression under escalating blocker concentrations.\"},\"predictThenReveal\":false,\"config\":{\"title\":\"Reseptör Antagonizma Simülatörü ve Schild Analizi\",\"prompt\":\"Kompetitif (paralel kayma) ve non-kompetitif (Emax depresyonu) modları karşılaştırın.\",\"defaultEc50\":10,\"defaultEmax\":100,\"defaultHillSlope\":1,\"modes\":[\"agonist\",\"competitive_antagonist\",\"noncompetitive_antagonist\",\"partial_agonist\"],\"source\":{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":28},\"explanation\":\"Kompetitif antagonistler aynı cebe reversibl bağlanarak eğriyi sağa kaydırır (Emax korunur). Nonkompetitif/kovalent antagonistler ise reseptörü kullanım dışı bırakarak Emax tavanını aşılmaz biçimde çökertir.\"},\"widget\":{\"type\":\"DoseResponseCurve\",\"config\":{\"title\":\"Reseptör Antagonizma Simülatörü ve Schild Analizi\",\"prompt\":\"Kompetitif (paralel kayma) ve non-kompetitif (Emax depresyonu) modları karşılaştırın.\",\"defaultEc50\":10,\"defaultEmax\":100,\"defaultHillSlope\":1,\"modes\":[\"agonist\",\"competitive_antagonist\",\"noncompetitive_antagonist\",\"partial_agonist\"],\"source\":{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":28},\"explanation\":\"Kompetitif antagonistler aynı cebe reversibl bağlanarak eğriyi sağa kaydırır (Emax korunur). Nonkompetitif/kovalent antagonistler ise reseptörü kullanım dışı bırakarak Emax tavanını aşılmaz biçimde çökertir.\"}},\"technicalTerms\":[{\"term\":\"Emax depresyonu (insurmountable)\",\"arContext\":\"هبوط سقف Emax غير القابل للتجاوز\"},{\"term\":\"Gaddum-Schild eğri ötelemesi\",\"arContext\":\"إزاحة المنحنى لـ Gaddum-Schild\"}],\"hints\":[{\"tr\":\"Kompetitif modda dozu artırın: Eğri sağa kayar ama tepe yüksekliği (%100) asla düşmez.\",\"ar\":\"في النمط التنافسي ارفع الجرعة: ينزاح المنحنى يميناً ويبقى سقف الاستجابة 100%.\",\"en\":\"In competitive mode, escalate blocker dose: curve shifts rightward, preserving 100% Emax.\"},{\"tr\":\"Non-kompetitif moda geçin: Doz arttıkça Emax tavanının %80, %50, %20'ye çöktüğünü görün.\",\"ar\":\"انتقل للنمط غير التنافسي: لاحظ كيف يهبط سقف Emax إلى 80%، 50%، 20%.\",\"en\":\"Switch to non-competitive mode: observe the Emax ceiling collapse to 80%, 50%, 20%.\"},{\"tr\":\"Kompetitif blokaj aşılabilir (surmountable); non-kompetitif blokaj ise aşılamazdır (insurmountable).\",\"ar\":\"الحصار التنافسي يمكن تجاوزه، بينما الحصار غير التنافسي مستحيل التجاوز.\",\"en\":\"Competitive blockade is surmountable; non-competitive blockade is insurmountable.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":28}]},{\"id\":\"pharm-mod2-les2-step-06\",\"stage\":\"guided_discovery\",\"stageIndex\":6,\"type\":\"guided_discovery\",\"title\":{\"tr\":\"Mekanizma Ayrımı: Allosterik Non-Kompetitif Antagonizma\",\"ar\":\"التمييز الآلي: المناهضة التباعدية غير التنافسية\",\"en\":\"Mechanistic Distinction: Allosteric Non-Competitive Antagonism\"},\"prompt\":{\"tr\":\"Bir antagonist agonist bağlanma cebi yerine reseptörün farklı bir allosterik bölgesine bağlandığında, yüksek agonist konsantrasyonu bu blokajı neden yenemez?\",\"ar\":\"عندما يرتبط مضاد بموقع تباعدي (allosteric) مختلف عن جيب المنبه، لماذا يعجز التركيز العالي جداً من المنبه عن تجاوز هذا الحصار؟\",\"en\":\"When an antagonist binds to an allosteric site rather than the agonist binding pocket, why can escalating agonist concentrations never surmount this blockade?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-6a\",\"text\":{\"tr\":\"Allosterik bağlanma reseptörün konformasyonunu bozarak aktif bölgenin sinyal iletmesini engeller; agonist kendi cebine bağlansa bile efektör aktive olamaz (aşılamaz Emax depresyonu).\",\"ar\":\"يشوه الارتباط التباعدي بنية المستقبل فيمنع نقل الإشارة؛ وحتى لو ارتبط المنبه بجيبه لا يتفعل المستجيب الخلوي (هبوط غير قابل للكسر في Emax).\",\"en\":\"Allosteric binding distorts receptor tertiary conformation, preventing signal transduction; even if agonist binds its pocket, downstream effectors cannot activate.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika keşif! Agonist ve allosterik antagonist farklı ceplere bağlandığı için birbirini kovamazlar. Agonist bağlansa dahi reseptör sinyali iletemez; bu yüzden Emax aşılmaz biçimde çöker (Slayt 30).\",\"ar\":\"اكتشاف رائع! لا يمكن للمنبه طرد المضاد التباعدي لاختلاف موقعيهما؛ ورغم ارتباط المنبه، يعجز المستقبل المشوه عن توليد الاستجابة، فيهبط Emax.\",\"en\":\"Great discovery! Agonist and allosteric antagonist dock at distinct pockets and cannot physically displace each other; signaling fails, depressing Emax.\"}},{\"id\":\"opt-6b\",\"text\":{\"tr\":\"Allosterik antagonist kanda agonisti arayıp bularak molekülü kovalent olarak yok eder.\",\"ar\":\"يقوم المضاد التباعدي بالبحث عن المنبه في الدم وتفكيكه تساهمياً.\",\"en\":\"The allosteric antagonist seeks out agonist molecules in circulating blood and covalently degrades them.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Moleküler imha yanılgısı: Allosterik modülatörler hedef reseptör proteinine bağlanır; plazmada ligand parçalamazlar.\",\"ar\":\"خطأ التدمير الجزيئي: ترتبط المعدلات التباعدية ببروتين المستقبل في الخلية، ولا شأن لها بتفكيك المنبه في البلازما.\",\"en\":\"Molecular destruction fallacy: Allosteric modulators bind the receptor macromolecule; they do not destroy ligands in plasma.\"}},{\"id\":\"opt-6c\",\"text\":{\"tr\":\"Allosterik antagonist iyon kanalının iç lümenine fiziksel bir tıkaç gibi oturarak ortosterik cebin açılmasını tamamen engeller.\",\"ar\":\"يستقر المضاد اللابؤري كمسدادة في لمعة قناة الأيونات مانعاً انفتاح الجيب الرئيسي فيزيائياً.\",\"en\":\"The allosteric antagonist acts as a physical plug inside the channel pore, sterically preventing ion flux regardless of orthosteric binding.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kanal tıkacı yanılgısı: Allosterik modülatörler kanalı fiziksel olarak tıkamaz; reseptörün dış/allosterik cebine bağlanıp protein konformasyonunu değiştirerek ortosterik sinyal iletimini bozar (negatif allosterik modülasyon).\",\"ar\":\"مغالطة السدادة الفيزيائية: لا تسد المعدلات اللابؤرية القناة فيزيائياً؛ بل تغير الشكل الفراغي للمستقبل عبر جيب خارجي لتعطيل نقل الإشارة.\",\"en\":\"Pore-plugging misconception: Allosteric antagonists do not physically occlude the pore; they bind distinct regulatory domains to induce conformational changes that disrupt efficacy.\"}}]},\"technicalTerms\":[{\"term\":\"allosterik modülasyon\",\"arContext\":\"التعديل التباعدي (allosteric modulation)\"},{\"term\":\"konformasyonel kenetlenme kaybı\",\"arContext\":\"فقدان الاقتران الشكلي\"}],\"hints\":[{\"tr\":\"Agonistin bağlandığı kapı ile antagonistin bağlandığı kapının farklı olduğunu düşünün.\",\"ar\":\"تخيل أن الباب الذي يدخل منه المنبه مختلف تماماً عن الباب الذي يدخل منه المضاد.\",\"en\":\"Picture two distinct doors: one for the agonist, another for the allosteric antagonist.\"},{\"tr\":\"Agonist kendi kapısından girse bile, diğer kapıdaki kilit mekanizmayı felç etmiştir.\",\"ar\":\"حتى لو دخل المنبه من بابه، فإن قفل الباب الآخر يشل حركة الآلية بالكامل.\",\"en\":\"Even if the agonist enters its door, the lock on the second door paralyzes the machinery.\"},{\"tr\":\"Agonisti ne kadar artırırsanız artırın, diğer cepteki antagonisti yerinden sökemez.\",\"ar\":\"مهما كدست المنبه، فلن يستطيع إزاحة المضاد المستقر في الجيب الآخر.\",\"en\":\"No amount of agonist can displace the antagonist residing in that independent pocket.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":30}],\"config\":{\"options\":[{\"id\":\"opt-6a\",\"text\":\"Allosterik bağlanma reseptörün konformasyonunu bozarak aktif bölgenin sinyal iletmesini engeller; agonist kendi cebine bağlansa bile efektör aktive olamaz (aşılamaz Emax depresyonu).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika keşif! Agonist ve allosterik antagonist farklı ceplere bağlandığı için birbirini kovamazlar. Agonist bağlansa dahi reseptör sinyali iletemez; bu yüzden Emax aşılmaz biçimde çöker (Slayt 30).\"},{\"id\":\"opt-6b\",\"text\":\"Allosterik antagonist kanda agonisti arayıp bularak molekülü kovalent olarak yok eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Moleküler imha yanılgısı: Allosterik modülatörler hedef reseptör proteinine bağlanır; plazmada ligand parçalamazlar.\"},{\"id\":\"opt-6c\",\"text\":\"Allosterik antagonist iyon kanalının iç lümenine fiziksel bir tıkaç gibi oturarak ortosterik cebin açılmasını tamamen engeller.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kanal tıkacı yanılgısı: Allosterik modülatörler kanalı fiziksel olarak tıkamaz; reseptörün dış/allosterik cebine bağlanıp protein konformasyonunu değiştirerek ortosterik sinyal iletimini bozar (negatif allosterik modülasyon).\"}],\"revealedOutcome\":{\"tr\":\"Allosterik non-kompetitif antagonizma: Antagonist farklı bir cebe bağlandığı için agonist konsantrasyonu artırılarak yerinden sökülemez. Reseptör sinyal üretemez ve Emax aşılmaz biçimde çöker.\",\"ar\":\"المناهضة التباعدية غير التنافسية: يرتبط المضاد بجيب مستقل ولا يمكن طرده بزيادة المنبه؛ فيعجز المستقبل عن نقل الإشارة ويهبط سقف Emax حتماً.\",\"en\":\"Allosteric non-competitive antagonism: Binding an independent allosteric pocket precludes competitive displacement. Transduction is compromised and Emax collapses.\"},\"explanation\":{\"tr\":\"Non-kompetitif antagonizmada agonist ve antagonist farklı bölgelere bağlanır. Bu durum reseptörün maksimum yanıt kapasitesini (Emax) düşürür; aşırı agonist eklenmesi bu depresyonu geri çeviremez (insurmountable, Slayt 30).\",\"ar\":\"في المناهضة غير التنافسية ترتبط الجزيئات بمواقع متباينة؛ مما ينقص قدرة النسيج القصوى (Emax) بحيث تعجز الجرعات العالية عن استعادتها.\",\"en\":\"In non-competitive antagonism, distinct binding topographies mean agonist titration cannot surmount target blockade, leading to insurmountable Emax depression.\"}}},{\"id\":\"pharm-mod2-les2-step-07\",\"stage\":\"formal_explanation\",\"stageIndex\":7,\"type\":\"formal_explanation\",\"title\":{\"tr\":\"Formal Teori: pA2 Tanımı ve Schild Eşitliği\",\"ar\":\"النظرية الصورية: تعريف pA2 ومعادلة Schild\",\"en\":\"Formal Theory: Definition of pA2 & Schild Equation\"},\"prompt\":{\"tr\":\"Schild eşitliğinde pA2 değeri farmakolojik olarak neyi ifade eder ve antagonistin afinitesi (Kb) ile formülasyonel ilişkisi nedir?\",\"ar\":\"في معادلة Schild، ماذا تعني قيمة pA2 دوائياً وما هي علاقتها الرياضية بثابت تفكك المضاد (Kb)؟\",\"en\":\"In Schild analysis, what does the pA2 value pharmacologically designate, and what is its mathematical relationship to the antagonist dissociation constant (Kb)?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-7a\",\"text\":{\"tr\":\"pA2, agonist dozunu 2 katına çıkarmayı (doz oranı r = 2) gerektiren antagonist derişiminin negatif logaritmasıdır (-log[B]); Schild eğimi 1.0 olduğunda pA2 = -log Kb olur.\",\"ar\":\"تمثل pA2 اللوغاريتم السالب لتركيز المضاد الذي يتطلب مضاعفة جرعة المنبه مرتين (r=2)؛ وعندما يكون ميل Schild مساوياً 1.0 فإن pA2 = -log Kb.\",\"en\":\"pA2 is the negative logarithm of antagonist concentration that requires doubling agonist dose (dose ratio r = 2); when Schild slope is 1.0, pA2 = -log Kb.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Tam isabet! Schild formülü: log(r-1) = log[B] - log Kb. r = 2 olduğunda log(2-1) = log(1) = 0 olur; buradan log[B] = log Kb, dolayısıyla -log[B] = -log Kb = pA2 elde edilir (Slayt 28).\",\"ar\":\"أصبت بدقة! معادلة Schild: log(r-1) = log[B] - log Kb. عندما r = 2، يصبح log(1) = 0، ومنها pA2 = -log[B] = -log Kb.\",\"en\":\"Bullseye! In the Schild equation, r = 2 yields log(2-1) = 0, meaning log[B] = log Kb, thus establishing pA2 = -log[B] = -log Kb.\"}},{\"id\":\"opt-7b\",\"text\":{\"tr\":\"pA2, antagonistin hastadaki toksik ölümcül dozunun (LD50) logaritmik katsayısıdır.\",\"ar\":\"تمثل pA2 المعامل اللوغاريتمي للجرعة القاتلة المميتة للمضاد (LD50).\",\"en\":\"pA2 represents the logarithmic transformation of the antagonist's median lethal toxic dose (LD50).\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Toksisite yanılgısı: pA2 bir toksisite dozu değildir; kompetitif antagonistin hedef reseptöre afinitesini belirten son derece zarif bir biyofiziksel indekstir.\",\"ar\":\"خطأ السمية: ليست pA2 معياراً للسمية؛ بل هي مؤشر فيزيائي حيوي راقٍ يحدد ألفة المضاد التنافسي للمستقبل.\",\"en\":\"Toxicity error: pA2 is not a lethal metric; it is an elegant biophysical index quantifying competitive target affinity.\"}},{\"id\":\"opt-7c\",\"text\":{\"tr\":\"pA2, ilacın plazma proteinlerine %50 bağlandığı andaki pH değerini temsil eder.\",\"ar\":\"تمثل pA2 درجة حموضة البلازما (pH) التي يرتبط عندها 50% من الدواء بالبروتينات.\",\"en\":\"pA2 represents the solution pH at which exactly 50% of the drug binds to plasma albumin.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Fizikokimya karışıklığı: pA2 çözelti pH'sı veya plazma proteini değildir; Heinz Otto Schild tarafından tanımlanan antagonist afinite değeridir.\",\"ar\":\"خلط فيزيائي: لا تعبر pA2 عن درجة الحموضة أو ارتباط البروتين؛ بل هي ثابت ألفة المضاد الذي صاغه Heinz Otto Schild.\",\"en\":\"Physicochemical confusion: pA2 is neither solution pH nor protein binding; it is Heinz Otto Schild's competitive affinity constant.\"}}]},\"technicalTerms\":[{\"term\":\"pA2 değeri\",\"arContext\":\"قيمة pA2 الدوائية\"},{\"term\":\"antagonist denge sabiti (Kb)\",\"arContext\":\"ثابت تفكك المضاد (Kb)\"}],\"hints\":[{\"tr\":\"Schild formülünde r yerine 2 koyun: log(r-1) = log(2-1) = log(1) = 0.\",\"ar\":\"عوض r = 2 في معادلة Schild: تصبح log(2-1) = log(1) = 0.\",\"en\":\"Substitute r = 2 into Schild's equation: log(r-1) = log(2-1) = log(1) = 0.\"},{\"tr\":\"0 = log[B] - log Kb -> log[B] = log Kb.\",\"ar\":\"0 = log[B] - log Kb، أي أن log[B] = log Kb.\",\"en\":\"0 = log[B] - log Kb implies log[B] = log Kb.\"},{\"tr\":\"pA2 = -log[B] = -log Kb'dir. Dozu 2 kat artıran antagonist konsantrasyonunun negatif logaritmasıdır.\",\"ar\":\"pA2 = -log[B] = -log Kb؛ وهو اللوغاريتم السالب لتركيز المضاد الذي يضاعف جرعة المنبه مرتين.\",\"en\":\"pA2 = -log[B] = -log Kb: the negative log of antagonist concentration doubling required agonist.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":28}],\"config\":{\"options\":[{\"id\":\"opt-7a\",\"text\":\"pA2, agonist dozunu 2 katına çıkarmayı (doz oranı r = 2) gerektiren antagonist derişiminin negatif logaritmasıdır (-log[B]); Schild eğimi 1.0 olduğunda pA2 = -log Kb olur.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Tam isabet! Schild formülü: log(r-1) = log[B] - log Kb. r = 2 olduğunda log(2-1) = log(1) = 0 olur; buradan log[B] = log Kb, dolayısıyla -log[B] = -log Kb = pA2 elde edilir (Slayt 28).\"},{\"id\":\"opt-7b\",\"text\":\"pA2, antagonistin hastadaki toksik ölümcül dozunun (LD50) logaritmik katsayısıdır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Toksisite yanılgısı: pA2 bir toksisite dozu değildir; kompetitif antagonistin hedef reseptöre afinitesini belirten son derece zarif bir biyofiziksel indekstir.\"},{\"id\":\"opt-7c\",\"text\":\"pA2, ilacın plazma proteinlerine %50 bağlandığı andaki pH değerini temsil eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Fizikokimya karışıklığı: pA2 çözelti pH'sı veya plazma proteini değildir; Heinz Otto Schild tarafından tanımlanan antagonist afinite değeridir.\"}],\"revealedOutcome\":{\"tr\":\"pA2 = -log Kb: Agonist dozunu tam 2 katına çıkarmayı (r=2) gerektiren antagonist derişiminin negatif logaritmasıdır. pA2 ne kadar büyükse, antagonist o kadar yüksek afiniteye sahiptir.\",\"ar\":\"pA2 = -log Kb: اللوغاريتم السالب لتركيز المضاد الذي يضاعف جرعة المنبه (r=2). كلما كبرت قيمة pA2، كانت ألفة المضاد للمستقبل أعلى.\",\"en\":\"pA2 = -log Kb: the negative log of antagonist concentration doubling required agonist (r=2). Larger pA2 values denote higher competitive affinity.\"},\"explanation\":{\"tr\":\"Schild analizi matematiksel zarafeti: Doz oranı r=2 olduğunda formül sadeleşir. Örneğin pA2 = 9 olan bir ilacın Kb değeri 10^-9 M (1 nM)'dir; yani pikomolar/nanomolar düzeyde olağanüstü güçlü bir antagonisttir (Slayt 28).\",\"ar\":\"أناقة تحليل Schild الرياضية: عند r=2 تتبسط المعادلة؛ فإذا كانت pA2 = 9 فإن Kb = 1 nM، مما يدل على مضاد فائق الألفة بتركيز نانومولي.\",\"en\":\"Mathematical beauty of Schild analysis: at r=2, the equation collapses cleanly. A pA2 of 9 means Kb = 1 nM, signifying high nanomolar potency.\"}}},{\"id\":\"pharm-mod2-les2-step-08\",\"stage\":\"concept_check\",\"stageIndex\":8,\"type\":\"concept_check\",\"title\":{\"tr\":\"Kavram Kontrolü: Schild pA2 Sayısal Analizi\",\"ar\":\"تحقق المفهوم: الحساب العددي لـ pA2 في تحليل Schild\",\"en\":\"Concept Check: Quantitative Schild pA2 Calculation\"},\"prompt\":{\"tr\":\"Kompetitif bir antagonistin Kb değeri 10^-8 M (10 nM) ise, bu antagonist için hesaplanan pA2 değeri kaçtır?\",\"ar\":\"إذا كان ثابت التفكك لمضاد تنافسي Kb = 10^-8 M (أي 10 nM)، فكم تبلغ قيمة pA2 المحسوبة لهذا المضاد؟\",\"en\":\"If a competitive antagonist exhibits an equilibrium dissociation constant Kb = 10^-8 M (10 nM), what is its calculated pA2 value?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-8a\",\"text\":{\"tr\":\"pA2 = 8; çünkü pA2 = -log(Kb) = -log(10^-8) = 8.\",\"ar\":\"pA2 = 8؛ لأن pA2 = -log(Kb) = -log(10^-8) = 8.\",\"en\":\"pA2 = 8; because pA2 = -log(Kb) = -log(10^-8) = 8.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz! pA2 doğrudan -log(Kb) formülünden hesaplanır: -log(10^-8) = -(-8) = 8. Bu ilacın 10 nM derişimi agonist dozunu 2 katına çıkarır (r = 2).\",\"ar\":\"حساب متقن! تطبق pA2 مباشرة من -log(Kb) = -(-8) = 8. تركيز 10 nM من هذا الدواء يضاعف جرعة المنبه مرتين (r = 2).\",\"en\":\"Flawless! pA2 is directly -log(Kb) = -(-8) = 8. A 10 nM concentration doubles the required agonist dose (r = 2).\"}},{\"id\":\"opt-8b\",\"text\":{\"tr\":\"pA2 = -8; logaritmik değerler farmakolojide daima negatif işaretli yazılmak zorundadır.\",\"ar\":\"pA2 = -8؛ يجب كتابة القيم اللوغاريتمية الدوائية بإشارة سالبة دوماً.\",\"en\":\"pA2 = -8; pharmacological log scales are strictly mandated to retain negative signs.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"İşaret yanılgısı: 'p' operatörü (pH veya pKa gibi) başında zaten eksi taşır (-log); -(-8) pozitif 8 yapar.\",\"ar\":\"خطأ الإشارة: يشير الرمز 'p' (كما في pH و pKa) إلى مقلوب اللوغاريتم السالب (-log)، فيتحول السالب إلى موجب (+8).\",\"en\":\"Sign convention error: The 'p' operator denotes -log; taking -(-8) yields a positive index of 8.\"}},{\"id\":\"opt-8c\",\"text\":{\"tr\":\"pA2 = 10; çünkü konsantrasyon 10 nM olarak verilmiştir.\",\"ar\":\"pA2 = 10؛ لأن التركيز معطى بالقيمة 10 nM.\",\"en\":\"pA2 = 10; because the concentration was given as 10 nM.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Birim yanılgısı: pA2 molar konsantrasyonun (M) negatif logaritmasıdır; 10 nM = 10^-8 M olduğundan logaritması 8'dir, 10 değil.\",\"ar\":\"خطأ الواحدات: يحسب pA2 بالتركيز المولي (M)؛ وبما أن 10 nM = 10^-8 M فإن الناتج هو 8 وليس 10.\",\"en\":\"Unit error: pA2 operates on molarity (M). Since 10 nM = 10^-8 M, the negative log is 8, not 10.\"}}]},\"technicalTerms\":[{\"term\":\"negatif logaritmik afinite indeksi\",\"arContext\":\"مؤشر الألفة اللوغاريتمي السالب\"},{\"term\":\"nanomolar disosiyasyon (nM)\",\"arContext\":\"التفكك النانومولي (nM)\"}],\"hints\":[{\"tr\":\"pA2 = -log(Kb) formülünü kullanın.\",\"ar\":\"طبق القانون: pA2 = -log(Kb).\",\"en\":\"Apply the governing equation: pA2 = -log(Kb).\"},{\"tr\":\"Kb = 10^-8 M derişiminin negatif logaritmasını alın: -log(10^-8).\",\"ar\":\"احسب اللوغاريتم السالب للقيمة 10^-8 M: -log(10^-8).\",\"en\":\"Take the negative log of 10^-8 M: -log(10^-8).\"},{\"tr\":\"-(-8) = +8.\",\"ar\":\"-(-8) = +8.\",\"en\":\"-(-8) = +8.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":28}],\"config\":{\"options\":[{\"id\":\"opt-8a\",\"text\":\"pA2 = 8; çünkü pA2 = -log(Kb) = -log(10^-8) = 8.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz! pA2 doğrudan -log(Kb) formülünden hesaplanır: -log(10^-8) = -(-8) = 8. Bu ilacın 10 nM derişimi agonist dozunu 2 katına çıkarır (r = 2).\"},{\"id\":\"opt-8b\",\"text\":\"pA2 = -8; logaritmik değerler farmakolojide daima negatif işaretli yazılmak zorundadır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"İşaret yanılgısı: 'p' operatörü (pH veya pKa gibi) başında zaten eksi taşır (-log); -(-8) pozitif 8 yapar.\"},{\"id\":\"opt-8c\",\"text\":\"pA2 = 10; çünkü konsantrasyon 10 nM olarak verilmiştir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Birim yanılgısı: pA2 molar konsantrasyonun (M) negatif logaritmasıdır; 10 nM = 10^-8 M olduğundan logaritması 8'dir, 10 değil.\"}],\"revealedOutcome\":{\"tr\":\"Kb = 10^-8 M (10 nM) için pA2 = -log(10^-8) = 8. Bu antagonist 10 nM derişimde agonist dozunu tam iki katına çıkarır (r = 2).\",\"ar\":\"من أجل Kb = 10^-8 M، فإن pA2 = 8. يضاعف هذا المضاد جرعة المنبه مرتين عند تركيز 10 nM.\",\"en\":\"For Kb = 10^-8 M (10 nM), pA2 = -log(10^-8) = 8. This antagonist doubles the required agonist concentration (r = 2) at 10 nM.\"},\"explanation\":{\"tr\":\"pA2 ölçeği tıpkı pH gibi logaritmiktir: pA2 değeri 1 birim artarsa (örn. 8'den 9'a), ilacın afinitesi 10 kat artmış demektir. Bu sayede antagonistlerin potensleri kolayca karşılaştırılır (Slayt 28).\",\"ar\":\"مقياس pA2 لوغاريتمي كالـ pH: زيادة وحدة واحدة في pA2 (من 8 إلى 9) تعني تضاعف الألفة 10 مرات، مما يسهل مقارنة فاعلية المضادات.\",\"en\":\"pA2 is logarithmic like pH: a 1-unit increase (e.g. 8 to 9) denotes a 10-fold gain in affinity, enabling clean cross-drug comparisons.\"}}},{\"id\":\"pharm-mod2-les2-step-09\",\"stage\":\"application\",\"stageIndex\":9,\"type\":\"clinical_vignette\",\"title\":{\"tr\":\"Klinik Vaka: Aşırı Doz Fentanil ve Nalokson Reboundu\",\"ar\":\"حالة سريرية: جرعة فنتانيل زائدة وانتكاسة النالوكسون\",\"en\":\"Clinical Case: Fentanyl Overdose & Naloxone Rebound\"},\"prompt\":{\"tr\":\"Aşırı doz fentanil ile solunumu duran bir hastaya nalokson uygulanıyor. Dakikalar içinde hasta uyanıyor fakat 45 dakika sonra yeniden solunum depresyonuna giriyor. Neden?\",\"ar\":\"لمريض بتثبيط تنفسي ناتج عن جرعة زائدة من الفنتانيل، يُعطى نالوكسون. يستيقظ المريض فوراً، لكن بعد 45 دقيقة يعود التثبيط التنفسي مجدداً! لماذا؟\",\"en\":\"A patient in respiratory arrest from fentanyl overdose receives naloxone, waking up promptly. Yet 45 minutes later, severe respiratory depression re-emerges. Why?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-9a\",\"text\":{\"tr\":\"Nalokson kompetitif ve tersinir bir antagonisttir; plazma yarı ömrü (30-60 dk) fentanilden çok daha kısa olduğu için vücuttan hızla temizlenir ve fentanil reseptörleri yeniden işgal eder.\",\"ar\":\"النالوكسون مضاد تنافسي عكوس؛ ولأن عمر نصفه (30-60 دقيقة) أقصر بكثير من الفنتانيل، يُطرح سريعاً ليعاود الفنتانيل شغل المستقبِلات.\",\"en\":\"Naloxone is a reversible competitive blocker; its short half-life (30-60 min) clears it rapidly, allowing longer-acting fentanyl to reoccupy targets.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Hayati bir acil tıp kuralı! Nalokson tersinir bir kompetitif antagonisttir. Fentanil lipofilik ve uzun ömürlüyken (3-7 saat), nalokson 45 dakikada temizlenir; kompetisyon fentanile döner ve solunum yeniden durur.\",\"ar\":\"قاعدة طوارئ منقذة للحياة! النالوكسون مضاد تنافسي عكوس؛ يزول خلال 45 دقيقة بينما يدوم الفنتانيل لساعات، فتعود الغيبوبة التنفسية.\",\"en\":\"Life-saving emergency pearl! Naloxone is competitive and reversible. Its rapid clearance (30-60 min) relative to fentanyl (hours) permits lethal rebound.\"}},{\"id\":\"opt-9b\",\"text\":{\"tr\":\"Fentanil nalokson moleküllerini kovalent olarak parçalayarak kendini korumaya almıştır.\",\"ar\":\"قام الفنتانيل بتكسير جزيئات النالوكسون تساهمياً لحماية نفسه.\",\"en\":\"Fentanyl chemically cleaves naloxone molecules, defending itself from competitive displacement.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kimyasal parçalanma yanılgısı: Fentanil naloksonu parçalayamaz; nalokson karaciğerde glukuronidasyonla fizyolojik olarak metabolize edilir.\",\"ar\":\"خطأ التخريب الكيميائي: لا يفكك الفنتانيل النالوكسون؛ بل يُستقلب النالوكسون طبيعياً بالاقتران الكبدي في البلازما.\",\"en\":\"Degradation error: Fentanyl cannot cleave naloxone; naloxone is cleared physiologically via hepatic glucuronidation.\"}},{\"id\":\"opt-9c\",\"text\":{\"tr\":\"Nalokson tek dozda reseptörleri kovalent bloke ettiği için fentanil allosterik reseptörlere kaçmıştır.\",\"ar\":\"حجب النالوكسون المستقبِلات تساهمياً بجرعة وحيدة، فهرب الفنتانيل نحو مستقبلات تباعدية.\",\"en\":\"Naloxone covalently blocked receptors, prompting fentanyl to migrate into allosteric pockets.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kovalent blokaj yanılgısı: Nalokson asla kovalent değildir, saf kompetitiftir; kovalent olsaydı hasta saatlerce uyanık kalırdı.\",\"ar\":\"خطأ الحصار التساهمي: النالوكسون مضاد عكوس نقي وليس تساهمياً؛ ولو كان تساهمياً لدام الاستيقاظ لساعات طويلة.\",\"en\":\"Covalent error: Naloxone is non-covalent and competitive; had it been irreversible, antagonism would persist for hours.\"}}]},\"technicalTerms\":[{\"term\":\"kompetitif tersinirlik\",\"arContext\":\"العكوسية التنافسية\"},{\"term\":\"rebound solunum depresyonu\",\"arContext\":\"الانتكاس التنفسي الارتدادي\"}],\"hints\":[{\"tr\":\"Naloksonun vücuttaki yarı ömrü (30-60 dakika) ile fentanilin yarı ömrünü (3-7 saat) kıyaslayın.\",\"ar\":\"قارن عمر نصف النالوكسون (30-60 دقيقة) بعمر نصف الفنتانيل (3-7 ساعات).\",\"en\":\"Contrast naloxone's short half-life (30-60 min) with fentanyl's duration (3-7 hours).\"},{\"tr\":\"Nalokson kandan temizlendiğinde geride kalan fentanile ne olur?\",\"ar\":\"عندما يزول النالوكسون من الدم، ماذا سيحدث للفنتانيل المتبقي؟\",\"en\":\"When naloxone clears from circulation, what happens to lingering fentanyl?\"},{\"tr\":\"Nalokson yarışmalı bir antagonist olduğu için konsantrasyonu düşünce fentanil reseptörleri yeniden ele geçirir.\",\"ar\":\"بما أنه مضاد تنافسي، فإن هبوط تركيزه يسمح للفنتانيل بإعادة احتلال المستقبِلات.\",\"en\":\"Being competitive, dropping naloxone levels permit fentanyl to reoccupy targets.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":26}],\"config\":{\"options\":[{\"id\":\"opt-9a\",\"text\":\"Nalokson kompetitif ve tersinir bir antagonisttir; plazma yarı ömrü (30-60 dk) fentanilden çok daha kısa olduğu için vücuttan hızla temizlenir ve fentanil reseptörleri yeniden işgal eder.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Hayati bir acil tıp kuralı! Nalokson tersinir bir kompetitif antagonisttir. Fentanil lipofilik ve uzun ömürlüyken (3-7 saat), nalokson 45 dakikada temizlenir; kompetisyon fentanile döner ve solunum yeniden durur.\"},{\"id\":\"opt-9b\",\"text\":\"Fentanil nalokson moleküllerini kovalent olarak parçalayarak kendini korumaya almıştır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kimyasal parçalanma yanılgısı: Fentanil naloksonu parçalayamaz; nalokson karaciğerde glukuronidasyonla fizyolojik olarak metabolize edilir.\"},{\"id\":\"opt-9c\",\"text\":\"Nalokson tek dozda reseptörleri kovalent bloke ettiği için fentanil allosterik reseptörlere kaçmıştır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kovalent blokaj yanılgısı: Nalokson asla kovalent değildir, saf kompetitiftir; kovalent olsaydı hasta saatlerce uyanık kalırdı.\"}],\"revealedOutcome\":{\"tr\":\"Nalokson tersinir kompetitif bir antagonisttir (t1/2 ≈ 30-60 dk). Fentanil kanda saatlerce kaldığı için nalokson temizlenince reseptörleri yeniden işgal eder; tekrarlayan doz veya IV infüzyon şarttır.\",\"ar\":\"النالوكسون مضاد تنافسي عكوس سريع الزوال (t1/2 ≈ 30-60 دقيقة). يدوم الفنتانيل لساعات ليعيد شغل المستقبِلات؛ ولذا يلزم تكرار الجرعات أو التسريب المستمر.\",\"en\":\"Naloxone is reversible and competitive (t1/2 ≈ 30-60 min). Long-acting fentanyl re-engages cleared targets; repeated dosing or continuous infusion is mandatory.\"},\"explanation\":{\"tr\":\"Farmakokinetik-farmakodinamik uyumsuzluk: Bir kompetitif antagonistin koruyuculuğu kanda yeterli konsantrasyonda ([B] > Kb) kaldığı sürece geçerlidir. Antagonist temizlendiğinde kütle hareketi dengesi agoniste geri döner (Slayt 26).\",\"ar\":\"عدم التطابق الحركي الدوائي: تستمر حماية المضاد التنافسي طالما بقي تركيزه كافياً ([B] > Kb)؛ وبزواله ينحاز التوازن مجدداً للمنبه المتبقي.\",\"en\":\"PK-PD mismatch: competitive protection lasts only while antagonist levels satisfy [B] > Kb. Once cleared, mass-action equilibria swing back to agonist.\"}}},{\"id\":\"pharm-mod2-les2-step-10\",\"stage\":\"retrieval\",\"stageIndex\":10,\"type\":\"retrieval\",\"title\":{\"tr\":\"Geri Çağırma: Antagonizma Türleri Hiyerarşisi\",\"ar\":\"استرجاع: تصنيف وتسلسل أنواع المناهضة\",\"en\":\"Active Recall: Taxonomy of Antagonism Types\"},\"prompt\":{\"tr\":\"Anafilaktik şokta salınan histaminin bronkokonstriktör etkisini, aynı reseptöre bağlanmadan beta-2 reseptörleri üzerinden bronkodilalasyon yaparak geri çeviren adrenalin hangi tür antagonizma örneğidir?\",\"ar\":\"في الصدمة التأقية، يعاكس الأدرينالين تشنج القصبات الناتج عن الهستامين عبر مستقبلات بيتا-2 المستقلة بدلاً من منافسة مستقبلات الهستامين. ما نوع هذه المناهضة؟\",\"en\":\"During anaphylaxis, adrenaline reverses histamine-induced bronchospasm via independent beta-2 receptors rather than histamine receptors. What class of antagonism does this represent?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-10a\",\"text\":{\"tr\":\"Fizyolojik (fonksiyonel) antagonizma; iki farklı agonist zıt reseptör sistemleri üzerinden birbirine zıt biyolojik yanıtlar oluşturur.\",\"ar\":\"مناهضة فيزيولوجية (وظيفية)؛ حيث يشغل ربيطان مستقبلين مختلفين لإنتاج استجابتين متعاكستين في النسيج.\",\"en\":\"Physiological (functional) antagonism; two independent agonists act on distinct receptor systems to produce opposing biological effects.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Histamin H1 reseptörünü (bronkokonstriksiyon), adrenalin ise beta-2 reseptörünü (bronkodilatasyon) uyarır. Reseptör için yarışmazlar; zıt hücresel yollarla birbirini dengelerler.\",\"ar\":\"صحيح! ينشط الهستامين مستقبلات H1 (تقبض)، وينشط الأدرينالين مستقبلات بيتا-2 (توسع)؛ لا يتنافسان على المستقبل بل يتعاكسان وظيفياً.\",\"en\":\"Correct! Histamine acts on H1 (constriction), adrenaline on beta-2 (dilation). They act through opposing physiological pathways without target competition.\"}},{\"id\":\"opt-10b\",\"text\":{\"tr\":\"Kimyasal antagonizma; adrenalin histamin molekülünü kanda kovalent bağlarla nötralize eder.\",\"ar\":\"مناهضة كيميائية؛ حيث يربط الأدرينالين جزيئات الهستامين تساهمياً في الدم ويبطلها.\",\"en\":\"Chemical antagonism; adrenaline covalently binds and neutralizes histamine directly in circulation.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kimyasal antagonizma yanılgısı: Kimyasal antagonizma iki ilacın doğrudan birbiriyle reaksiyona girmesidir (örn. protaminin heparini bağlaması); adrenalin histaminle reaksiyona girmez.\",\"ar\":\"خطأ المناهضة الكيميائية: تحدث المناهضة الكيميائية بتفاعل جزيئين مباشرة (كالبروتامين والهيبارين)؛ ولا يتفاعل الأدرينالين مع الهستامين كيميائياً.\",\"en\":\"Chemical antagonism error: Chemical antagonism is direct drug-drug binding (e.g. protamine-heparin); adrenaline does not react with histamine.\"}},{\"id\":\"opt-10c\",\"text\":{\"tr\":\"Kompetitif farmakolojik antagonizma; adrenalin doğrudan histamin H1 reseptör cebi için yarışır.\",\"ar\":\"مناهضة دوائية تنافسية؛ ينافس الأدرينالين الهستامين مباشرة على نفس الجيب النشط لمستقبل H1.\",\"en\":\"Competitive pharmacological antagonism; adrenaline directly competes for the histaminergic H1 receptor pocket.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Reseptör hedef yanılgısı: Adrenalin H1 reseptörüne bağlanamaz; adrenerjik beta-2 reseptörünün agonistidir.\",\"ar\":\"خطأ موقع المستقبل: لا يرتبط الأدرينالين بمستقبلات H1 إطلاقاً؛ بل هو منبه نوعي لمستقبلات بيتا-2 الأدرينالينية.\",\"en\":\"Target error: Adrenaline does not dock into H1 histaminergic pockets; it is a selective adrenergic beta-2 agonist.\"}}]},\"technicalTerms\":[{\"term\":\"fizyolojik (fonksiyonel) antagonizma\",\"arContext\":\"المناهضة الفيزيولوجية (الوظيفية)\"},{\"term\":\"kimyasal antagonizma\",\"arContext\":\"المناهضة الكيميائية\"}],\"hints\":[{\"tr\":\"Adrenalin ile histaminin aynı reseptöre mi, yoksa farklı reseptörlere mi bağlandığına bakın.\",\"ar\":\"هل يرتبط الأدرينالين والهستامين بنفس المستقبل أم بمستقبلين مختلفين؟\",\"en\":\"Consider whether adrenaline and histamine target the same receptor or distinct targets.\"},{\"tr\":\"Histamin H1 reseptöründen kasar, adrenalin beta-2 reseptöründen gevşetir.\",\"ar\":\"يقبض الهستامين عبر H1، ويرخي الأدرينالين عبر بيتا-2.\",\"en\":\"Histamine constricts via H1; adrenaline relaxes via beta-2.\"},{\"tr\":\"Farklı reseptörler üzerinden zıt etkiler oluşturulmasına 'fizyolojik (fonksiyonel) antagonizma' denir.\",\"ar\":\"توليد استجابتين متعاكستين عبر مستقبلين مختلفين يسمى 'مناهضة فيزيولوجية (وظيفية)'.\",\"en\":\"Opposing actions via independent receptor systems define 'physiological (functional) antagonism'.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":33}],\"config\":{\"options\":[{\"id\":\"opt-10a\",\"text\":\"Fizyolojik (fonksiyonel) antagonizma; iki farklı agonist zıt reseptör sistemleri üzerinden birbirine zıt biyolojik yanıtlar oluşturur.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Histamin H1 reseptörünü (bronkokonstriksiyon), adrenalin ise beta-2 reseptörünü (bronkodilatasyon) uyarır. Reseptör için yarışmazlar; zıt hücresel yollarla birbirini dengelerler.\"},{\"id\":\"opt-10b\",\"text\":\"Kimyasal antagonizma; adrenalin histamin molekülünü kanda kovalent bağlarla nötralize eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kimyasal antagonizma yanılgısı: Kimyasal antagonizma iki ilacın doğrudan birbiriyle reaksiyona girmesidir (örn. protaminin heparini bağlaması); adrenalin histaminle reaksiyona girmez.\"},{\"id\":\"opt-10c\",\"text\":\"Kompetitif farmakolojik antagonizma; adrenalin doğrudan histamin H1 reseptör cebi için yarışır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Reseptör hedef yanılgısı: Adrenalin H1 reseptörüne bağlanamaz; adrenerjik beta-2 reseptörünün agonistidir.\"}],\"revealedOutcome\":{\"tr\":\"Adrenalin ve histamin fizyolojik antagonisttir: Ayrı reseptör sistemleri (beta-2 vs H1) üzerinden birbirine zıt biyolojik etkiler oluşturarak organ düzeyinde denge sağlarlar.\",\"ar\":\"الأدرينالين والهستامين مناهضان فيزيولوجيان: يعملان عبر مستقبلين مستقلين (بيتا-2 مقابل H1) بآليات متعاكسة تروض التشنج على مستوى العضو.\",\"en\":\"Adrenaline and histamine represent physiological antagonism: distinct receptor systems (beta-2 vs H1) generating opposing functional outputs at the organ level.\"},\"explanation\":{\"tr\":\"Farmakolojide 4 antagonizma türü: 1) Farmakolojik (kompetitif/non-kompetitif), 2) Fizyolojik/fonksiyonel (zıt reseptörler), 3) Kimyasal (doğrudan moleküler şelasyon/nötralizasyon), 4) Farmakokinetik (indüksiyonla atılımı hızlandırma, Slayt 33).\",\"ar\":\"أنواع المناهضة الأربعة: 1) دوائية (تنافسية/غير تنافسية)، 2) فيزيولوجية وظيفية (مستقبلات متعاكسة)، 3) كيميائية (تعادل مباشر)، 4) حركية دوائية (تسريع الإطراح).\",\"en\":\"4 Antagonism types: 1) Pharmacological (orthosteric/allosteric), 2) Physiological (opposing pathways), 3) Chemical (direct neutralization), 4) Pharmacokinetic (clearance acceleration).\"}}},{\"id\":\"pharm-mod2-les2-step-11\",\"stage\":\"connection\",\"stageIndex\":11,\"type\":\"connection\",\"title\":{\"tr\":\"Kavramsal Köprü: Feokromositomada Kovalent Blokaj Güvencesi\",\"ar\":\"جسر المفاهيم: أمان الحصار التساهمي في ورم القواتم\",\"en\":\"Conceptual Bridge: Covalent Blockade Safety in Pheochromocytoma\"},\"prompt\":{\"tr\":\"Feokromositoma cerrahisinde tümör manipülasyonuyla kana devasa katekolamin fırtınası saçılır. Ameliyat öncesi hazırlıkta prazosin (kompetitif) yerine neden fenoksibenzamin (geri dönüşümsüz) tercih edilir?\",\"ar\":\"أثناء جراحة ورم القواتم، تنطلق عاصفة كاتيكولامينية هائلة بالدم. في التحضير الجراحي، لماذا يُفضل فينوكسي بنزامين (غير العكوس) على برازوسين (التنافسي)؟\",\"en\":\"During pheochromocytoma resection, tumor manipulation dumps massive catecholamine surges. Pre-operatively, why is irreversible phenoxybenzamine preferred over competitive prazosin?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-11a\",\"text\":{\"tr\":\"Masif katekolamin deşarjı yarışmalı prazosin blokajını kolayca aşarak ölümcül hipertansif krize yol açabilir; oysa fenoksibenzamin reseptörleri kovalent kilitlediği için blokaj aşılamaz.\",\"ar\":\"التدفق الكاتيكولاميني الهائل سيتجاوز بسهولة حصار برازوسين التنافسي مفجراً أزمة فرط ضغط مميتة؛ بينما حصار فينوكسي بنزامين التساهمي مستحيل التجاوز.\",\"en\":\"Massive catecholamine surges easily overcome competitive prazosin blockade, causing fatal hypertensive crises; phenoxybenzamine's covalent bond is insurmountable.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika klinik kavrayış! Cerrah tümöre dokunduğunda katekolaminler 100 kat fırlar. Bu fırtına kompetitif bir blokerin sağa kaymasını tamamen yener (surmount eder). Fenoksibenzamin ise kovalent alkilasyonla Emax'ı çökerterek damarları krizden korur.\",\"ar\":\"فهم سريري رائع! عند لمس الورم ترتفع الكاتيكولامينات بمئة ضعف فتكسر الحصار التنافسي للبرازوسين؛ أما فينوكسي بنزامين فيقفل المستقبِلات تساهمياً حامياً المريض.\",\"en\":\"Brilliant insight! Tumor manipulation triggers 100-fold catecholamine surges that easily surmount competitive prazosin; covalent phenoxybenzamine prevents catastrophic crisis.\"}},{\"id\":\"opt-11b\",\"text\":{\"tr\":\"Prazosin cerrahi sırasında refleks sempatik deşarjı tamamen durdurarak hastada derin refrakter kardiyak şoka yol açar.\",\"ar\":\"يوقف برازوسين التفريغ الودي الانعكاسي تماماً أثناء الجراحة مما يدخل المريض في صدمة قلبية معندة.\",\"en\":\"Prazosin completely abolishes reflex sympathetic tone during surgery, plunging the patient into profound refractory cardiogenic shock.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kardiyak şok yanılgısı: Prazosinin temel sorunu şok değil, tam aksine cerrah tümöre dokunduğunda salınan devasa katekolaminlerin yarışmalı prazosin blokajını kolayca aşarak ölümcül hipertansif krize yol açmasıdır.\",\"ar\":\"مغالطة الصدمة القلبية: الخطر الحقيقي ليس الصدمة، بل قدرة عاصفة الكاتيكولامينات الجراحية على إزاحة برازوسين التنافسي وإحداث نوبة فرط ضغط قاتلة.\",\"en\":\"Cardiogenic shock fallacy: The clinical hazard is not circulatory collapse, but the massive intraoperative catecholamine surge displacing competitive prazosin to trigger hypertensive crisis.\"}},{\"id\":\"opt-11c\",\"text\":{\"tr\":\"Fenoksibenzamin doğrudan adrenal medullaya girerek tirozin hidroksilaz enzimini inhibe eder ve katekolamin üretimini sıfırlar.\",\"ar\":\"يدخل فينوكسي بنزامين مباشرة إلى لب الكظر ويثبط إنزيم تيروزين هيدروكسيلاز ليوقف تصنيع الكاتيكولامينات.\",\"en\":\"Phenoxybenzamine enters adrenal chromaffin cells to directly inhibit tyrosine hydroxylase, halting catecholamine biosynthesis at the source.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Biyosentez inhibisyonu yanılgısı: Fenoksibenzamin bir katekolamin sentez inhibitörü (örn. metirozosin) değildir; periferik damarlardaki alfa-adrenerjik reseptörleri kovalent bloke ederek dolaşımdaki yüksek adrenalinin damarları kasmasını engeller.\",\"ar\":\"مغالطة تثبيط التصنيع: فينوكسي بنزامين ليس مثبطاً للإنزيمات؛ بل يحصر مستقبلات ألفا الوعائية تساهمياً ليمنع تضيق الأوعية بالعاصفة الكاتيكولامينية.\",\"en\":\"Biosynthesis inhibition fallacy: Phenoxybenzamine does not inhibit tyrosine hydroxylase (like metyrosine); it covalently locks vascular alpha-receptors against circulating catecholamines.\"}}]},\"technicalTerms\":[{\"term\":\"katekolamin fırtınası\",\"arContext\":\"عاصفة الكاتيكولامينات\"},{\"term\":\"kovalent kilitlenme güvencesi\",\"arContext\":\"أمان الحصار التساهمي غير العكوس\"}],\"hints\":[{\"tr\":\"Ameliyat esnasında kanda adrenalin miktarının 100 katına çıktığını düşünün.\",\"ar\":\"تخيل تضاعف الأدرينالين مئة مرة في الدم أثناء العملية.\",\"en\":\"Imagine circulating adrenaline spiking 100-fold during surgery.\"},{\"tr\":\"Kompetitif bir ilaç (prazosin) bu devasa agonist artışı karşısında ne yapar?\",\"ar\":\"ماذا سيحل بمضاد تنافسي (برازوسين) أمام هذا الطوفان من المنبه؟\",\"en\":\"What happens to a competitive blocker (prazosin) in the face of this massive surge?\"},{\"tr\":\"Yarışmayı kaybeder ve aşılır; oysa kovalent fenoksibenzamin asla aşılamaz.\",\"ar\":\"سيخسر المنافسة ويُكسر حصاره؛ بينما الحصار التساهمي لفينوكسي بنزامين لا يُكسر أبداً.\",\"en\":\"It is outcompeted and surmounted; covalent phenoxybenzamine remains insurmountable.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":24}],\"config\":{\"options\":[{\"id\":\"opt-11a\",\"text\":\"Masif katekolamin deşarjı yarışmalı prazosin blokajını kolayca aşarak ölümcül hipertansif krize yol açabilir; oysa fenoksibenzamin reseptörleri kovalent kilitlediği için blokaj aşılamaz.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika klinik kavrayış! Cerrah tümöre dokunduğunda katekolaminler 100 kat fırlar. Bu fırtına kompetitif bir blokerin sağa kaymasını tamamen yener (surmount eder). Fenoksibenzamin ise kovalent alkilasyonla Emax'ı çökerterek damarları krizden korur.\"},{\"id\":\"opt-11b\",\"text\":\"Prazosin cerrahi sırasında refleks sempatik deşarjı tamamen durdurarak hastada derin refrakter kardiyak şoka yol açar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kardiyak şok yanılgısı: Prazosinin temel sorunu şok değil, tam aksine cerrah tümöre dokunduğunda salınan devasa katekolaminlerin yarışmalı prazosin blokajını kolayca aşarak ölümcül hipertansif krize yol açmasıdır.\"},{\"id\":\"opt-11c\",\"text\":\"Fenoksibenzamin doğrudan adrenal medullaya girerek tirozin hidroksilaz enzimini inhibe eder ve katekolamin üretimini sıfırlar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Biyosentez inhibisyonu yanılgısı: Fenoksibenzamin bir katekolamin sentez inhibitörü (örn. metirozosin) değildir; periferik damarlardaki alfa-adrenerjik reseptörleri kovalent bloke ederek dolaşımdaki yüksek adrenalinin damarları kasmasını engeller.\"}],\"revealedOutcome\":{\"tr\":\"Feokromositoma hazırlığında kovalent blokaj: Masif katekolamin fırtınası yarışmalı prazosini kolayca aşabilir. Kovalent bağlı fenoksibenzamin ise reseptör sayısını eksilttiği için katekolamin fırtınası tarafından asla yenilemez (insurmountable).\",\"ar\":\"الحصار التساهمي في ورم القواتم: يستطيع طوفان الأدرينالين كسر حصار برازوسين التنافسي؛ بينما يعجز تماماً عن تجاوز حصار فينوكسي بنزامين التساهمي الدائم.\",\"en\":\"Covalent blockade in pheochromocytoma: massive catecholamine storms surmount competitive prazosin; irreversible phenoxybenzamine guarantees insurmountable vascular protection.\"},\"explanation\":{\"tr\":\"Kovalent antagonistler (fenoksibenzamin) reseptör havuzunu kovalent alkilasyonla inaktive eder. Bu sayede agonistin konsantrasyonu 1000 kat artsa bile kasılma tavanı (Emax) bastırılmış kalır ve ölümcül hipertansif krizler önlenir (Slayt 24).\",\"ar\":\"تعطل المضادات التساهمية حوض المستقبِلات نهائياً؛ فحتى لو تضاعف تركيز المنبه ألف مرة، يبقى سقف الاستجابة Emax مكبوحاً مانعاً السكتة وفرط الضغط القاتل.\",\"en\":\"Covalent blockers eliminate functional receptors via alkylation. Even with 1000-fold agonist spikes, tissue Emax remains firmly suppressed, preventing fatal stroke.\"}}},{\"id\":\"pharm-mod2-les2-step-12\",\"stage\":\"mastery_check\",\"stageIndex\":12,\"type\":\"mastery_check\",\"title\":{\"tr\":\"Ustalık Sınavı: NX-40 Serotonin Antagonisti ve Schild Analizi\",\"ar\":\"اختبار الإتقان: مضاد السيروتونين NX-40 وتحليل Schild\",\"en\":\"Mastery Check: Serotonin Antagonist NX-40 & Schild Analysis\"},\"prompt\":{\"tr\":\"Bir araştırmacı serotonin 5-HT2A reseptörüne bağlanan NX-40 molekülünü test ediyor. Schild eğimini 1.0, x-ekseni kesişimini -9.0 (pA2 = 9.0) buluyor. Bu deneyden hangi kesin farmakolojik sonuç çıkar?\",\"ar\":\"باحث يختبر المركب NX-40 على مستقبل السيروتونين 5-HT2A. وجد أن ميل Schild يساوي 1.0، وتقاطع المحور السيني عند -9.0 (pA2 = 9.0). ما النتيجة الدوائية القاطعة؟\",\"en\":\"Investigating agent NX-40 at 5-HT2A receptors, a researcher observes a Schild slope of 1.0 and an x-intercept of -9.0 (pA2 = 9.0). What definitive pharmacological conclusion is drawn?\"},\"predictThenReveal\":false,\"conceptCheck\":{\"options\":[{\"id\":\"opt-12a\",\"text\":{\"tr\":\"NX-40 basit, reversibl ve tam kompetitif bir antagonisttir; 5-HT2A reseptörüne Kd = 1 nM (10^-9 M) gibi nanomolar yüksek bir afiniteyle bağlanır.\",\"ar\":\"NX-40 مضاد تنافسي عكوس نقي وبسيط؛ يرتبط بمستقبل 5-HT2A بألفة نانومولية فائقة قدرها Kd = 1 nM (10^-9 M).\",\"en\":\"NX-40 is a simple, reversible competitive antagonist; binding 5-HT2A receptors with high nanomolar affinity (Kd = 1 nM / 10^-9 M).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz ustalık! Eğim 1.0 basit kompetisyonu kanıtlar. x kesişimi -9.0 ise pA2 = 9.0 demektir; Kb = 10^-9 M = 1 nM olarak hesaplanır. NX-40 nanomolar güçlü bir kompetitif antagonisttir (Slayt 28).\",\"ar\":\"قمة الإتقان الدوائي! الميل 1.0 يثبت التنافس العكوس النقي، والتقاطع عند -9.0 يعني pA2 = 9.0 وبالتالي Kb = 10^-9 M = 1 nM بألفة فائقة.\",\"en\":\"Peak pharmacological mastery! A slope of 1.0 proves simple competition. The -9.0 intercept reveals pA2 = 9.0, yielding Kb = 1 nM.\"}},{\"id\":\"opt-12b\",\"text\":{\"tr\":\"NX-40 reseptörü kovalent olarak yok eden bir alkilleyici ajandır; pA2 = 9.0 değeri aşırı hücre ölümünü gösterir.\",\"ar\":\"NX-40 مركب مؤلكل يدمر المستقبل تساهمياً؛ وقيمة pA2 = 9.0 تدل على موت خلوي واسع.\",\"en\":\"NX-40 is a covalent alkylator destroying receptors; pA2 = 9.0 denotes extensive cellular apoptosis.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Schild yorumlama yanılgısı: Kovalent ajanlarda Schild eğimi 1.0 çıkmaz; eğim 1.0 tersinir kompetitif bağlanmanın mutlak kanıtıdır.\",\"ar\":\"خطأ تفسير Schild: لا يمكن للمواد التساهمية إعطاء ميل Schild مساوياً 1.0؛ فالميل 1.0 هو البرهان الحصري على التنافس العكوس.\",\"en\":\"Schild misinterpretation: Irreversible agents distort regressions; a slope of exactly 1.0 strictly validates reversible orthosteric competition.\"}},{\"id\":\"opt-12c\",\"text\":{\"tr\":\"NX-40 bir tam agonisttir ve serotoninden 9 kat daha fazla hücre içi kalsiyum salıverir.\",\"ar\":\"NX-40 منبه كامل يحرر كالسيوم داخل خلوي يفوق السيروتونين بتسعة أضعاف.\",\"en\":\"NX-40 is a full agonist that mobilizes 9-fold more intracellular calcium than endogenous serotonin.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Agonist-antagonist karışıklığı: Schild analizi agonistler için değil, antagonistlerin afinitesini ölçmek için yapılır; pA2 = 9.0 güçlü bir blokeri tanımlar.\",\"ar\":\"خلط المنبه بالمضاد: يُجرى تحليل Schild حصراً لقياس ألفة المضادات؛ وقيمة pA2 = 9.0 تدل على حاصر فائق القوة وليس منبهاً.\",\"en\":\"Agonist-antagonist confusion: Schild analyses evaluate antagonists; pA2 = 9.0 designates an extraordinarily potent blocker, not an agonist.\"}}]},\"technicalTerms\":[{\"term\":\"5-HT2A reseptör antagonizmi\",\"arContext\":\"مناهضة مستقبلات 5-HT2A\"},{\"term\":\"nanomolar dissosiyasyon sabiti (Kb = 1 nM)\",\"arContext\":\"ثابت التفكك النانومولي (Kb = 1 nM)\"}],\"hints\":[{\"tr\":\"Schild doğrusunun eğiminin tam 1.0 olması ne anlama gelir? (Yarışmalı kompetitif).\",\"ar\":\"ماذا يعني أن ميل خط Schild يساوي 1.0 تماماً؟ (تنافسي عكوس).\",\"en\":\"What does a Schild slope of exactly 1.0 prove? (Competitive reversible).\"},{\"tr\":\"x-ekseni kesişimi -9.0 ise: log(Kb) = -9.0 -> Kb = 10^-9 M = 1 nM.\",\"ar\":\"إذا كان التقاطع عند -9.0: فإن log(Kb) = -9.0 وبالتالي Kb = 10^-9 M = 1 nM.\",\"en\":\"If x-intercept is -9.0: log(Kb) = -9.0 -> Kb = 10^-9 M = 1 nM.\"},{\"tr\":\"NX-40, 1 nM afiniteye sahip saf bir kompetitif antagonisttir.\",\"ar\":\"المركب NX-40 هو مضاد تنافسي نقي بألفة فائقة قدرها 1 nM.\",\"en\":\"NX-40 is a pure competitive antagonist with 1 nM affinity.\"}],\"sources\":[{\"file\":\"Farmakodinami-Doz Yanıt.pdf\",\"page\":28}],\"config\":{\"options\":[{\"id\":\"opt-12a\",\"text\":\"NX-40 basit, reversibl ve tam kompetitif bir antagonisttir; 5-HT2A reseptörüne Kd = 1 nM (10^-9 M) gibi nanomolar yüksek bir afiniteyle bağlanır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz ustalık! Eğim 1.0 basit kompetisyonu kanıtlar. x kesişimi -9.0 ise pA2 = 9.0 demektir; Kb = 10^-9 M = 1 nM olarak hesaplanır. NX-40 nanomolar güçlü bir kompetitif antagonisttir (Slayt 28).\"},{\"id\":\"opt-12b\",\"text\":\"NX-40 reseptörü kovalent olarak yok eden bir alkilleyici ajandır; pA2 = 9.0 değeri aşırı hücre ölümünü gösterir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Schild yorumlama yanılgısı: Kovalent ajanlarda Schild eğimi 1.0 çıkmaz; eğim 1.0 tersinir kompetitif bağlanmanın mutlak kanıtıdır.\"},{\"id\":\"opt-12c\",\"text\":\"NX-40 bir tam agonisttir ve serotoninden 9 kat daha fazla hücre içi kalsiyum salıverir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Agonist-antagonist karışıklığı: Schild analizi agonistler için değil, antagonistlerin afinitesini ölçmek için yapılır; pA2 = 9.0 güçlü bir blokeri tanımlar.\"}],\"revealedOutcome\":{\"tr\":\"NX-40 için Schild eğimi 1.0 ve pA2 = 9.0: İlaç 5-HT2A reseptöründe 1:1 yarışmalı, reversibl ve kompetitif bir antagonisttir. Bağlanma afinitesi Kb = 10^-9 M = 1 nM'dir.\",\"ar\":\"ميل Schild = 1.0 و pA2 = 9.0 للمركب NX-40: يثبت أنه مضاد تنافسي عكوس بنسبة 1:1 لمستقبل 5-HT2A بألفة نانومولية قدرها Kb = 1 nM.\",\"en\":\"For NX-40, Schild slope = 1.0 and pA2 = 9.0: proves simple, reversible 1:1 competitive antagonism at 5-HT2A receptors with Kb = 1 nM.\"},\"explanation\":{\"tr\":\"Schild analizinin gücü: İlacın konsantrasyon-etki eğrilerini farklı antagonist dozlarında kaydırarak elde edilen eğim 1.0 ise, molekülün saf bir kompetitif bloker olduğu ve pA2 değerinin doğrudan afiniteyi verdiği kesinleşir (Slayt 28).\",\"ar\":\"قوة تحليل Schild: عندما ينتج عن إزاحة المنحنيات ميل يساوي 1.0، نتأكد يقينياً أن الدواء مضاد تنافسي نقي وأن pA2 تعكس ألفته الحقيقية مباشرة.\",\"en\":\"The definitive power of Schild analysis: unity slope confirms pure orthosteric competition, ensuring pA2 directly reflects thermodynamic affinity.\"}}}]},\"pharm-mod3-les1\":{\"id\":\"pharm-mod3-les1\",\"courseId\":\"pharmacology\",\"moduleId\":\"ph-mod-03\",\"title\":{\"tr\":\"Tek Kompartmanlı Farmakokinetik: Klerens, Dağılım Hacmi ve Yarılanma Ömrü\",\"ar\":\"حركية الدواء في نموذج الحجيرة الواحدة: التصفية وحجم التوزع وعمر النصف\",\"en\":\"One-Compartment Pharmacokinetics: Clearance, Volume of Distribution & Half-Life\"},\"order\":1,\"access\":\"free\",\"objective\":{\"tr\":\"Tek kompartmanlı farmakokinetik modelde sanal dağılım hacmi (Vd), klerens (CL) ve eliminasyon yarılanma ömrü (t1/2) arasındaki matematiksel ilişkiyi yönetmek ve hemodiyaliz etkinliğini öngörmek.\",\"ar\":\"إتقان العلاقة الرياضية بين حجم التوزع الظاهري (Vd) والتصفية (CL) وعمر النصف الإطراحي (t1/2) والتنبؤ بجدوى الديال الدموي في نموذج الحجيرة الواحدة.\",\"en\":\"Master the mathematical relationships between apparent volume of distribution (Vd), clearance (CL), and elimination half-life (t1/2), and predict hemodialysis efficacy in a one-compartment model.\"},\"misconceptions\":[{\"tr\":\"İnfüzyon hızını iki katına çıkarmanın kararlı duruma (steady-state) ulaşma süresini yarıya indireceği yanılgısı (kararlı duruma ulaşma süresi yalnızca eliminasyon yarılanma ömrü t1/2 ile belirlenir).\",\"ar\":\"الظن الخاطئ بأن مضاعفة معدل التسريب الوريدي يقلل زمن الوصول إلى الحالة المستقرة إلى النصف (الزمن محكوم حصراً بعمر النصف الإطراحي t1/2).\",\"en\":\"The misconception that doubling the infusion rate halves the time to reach steady-state (time to steady-state depends solely on elimination half-life t1/2).\"},{\"tr\":\"Dağılım hacminin (Vd) gerçek bir anatomik sıvı hacmini temsil ettiği yanılgısı (Vd, plazma konsantrasyonu ile vücuttaki toplam ilaç miktarını birbirine bağlayan sanal bir orantı katsayısıdır).\",\"ar\":\"الاعتقاد بأن حجم التوزع (Vd) يمثل حيزاً مائياً تشريحياً حقيقياً (Vd مجرد ثابت تناسب ظاهري يربط كمية الدواء الكلية بتركيز البلازما).\",\"en\":\"The belief that volume of distribution (Vd) reflects a real anatomical fluid volume rather than an apparent proportionality constant.\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":2}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Katzung's Basic & Clinical Pharmacology\",\"edition\":\"15th ed.\",\"topic\":\"Pharmacokinetics: Volume of Distribution, Clearance, and Half-Life\",\"chapter\":\"Chapter 3: Pharmacokinetics & Pharmacodynamics: Rational Dosing & the Time Course of Drug Action\",\"page\":\"pp. 34-41\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Goodman & Gilman's The Pharmacological Basis of Therapeutics\",\"edition\":\"14th ed.\",\"topic\":\"Clinical Pharmacokinetics: Clearance, Volume of Distribution, and Half-Life\",\"chapter\":\"Chapter 2: Pharmacokinetics: The Dynamics of Drug Absorption, Distribution, Metabolism, and Elimination\",\"page\":\"pp. 21-30\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"pharm-mod3-les1-card1\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Sanal Dağılım Hacmi Formülü\",\"prompt\":\"Tek kompartmanlı modelde sanal dağılım hacmi (Vd) IV bolus doz ve ekstrapole sıfır anı konsantrasyonu (C0) ile nasıl hesaplanır?\",\"answer\":\"Vd = Doz / C0 (Vd, vücuttaki toplam ilaç miktarını plazma konsantrasyonuna oranlayan sanal hacimdir).\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod3-les1-card2\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Yarılanma Ömrü Bağımlı Parametresi\",\"prompt\":\"Eliminasyon yarılanma ömrü (t1/2) Vd ve CL cinsinden nasıl formüle edilir ve neden bağımlı bir parametredir?\",\"answer\":\"t1/2 = 0.693 x Vd / CL. Bağımsız fizyolojik parametreler Vd ve CL olup, t1/2 bunların oranından türeyen bağımlı hibrit parametredir.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod3-les1-card3\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Kararlı Durum Kuralı (Steady-State)\",\"prompt\":\"Sabit hızlı sürekli infüzyonda kararlı durum plazma düzeyinin (Css) %93.8'ine kaç yarılanma ömründe ulaşılır?\",\"answer\":\"Tam olarak 4 yarılanma ömründe (%93.75). 5 yarılanma ömründe ise %96.88'e ulaşılır; infüzyon hızından tamamen bağımsızdır.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod3-les1-card4\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Klerens ve EAA İlişkisi\",\"prompt\":\"Sistemik vücut klerensi (CL) IV bolus doz ve plazma konsantrasyon-zaman eğrisi altındaki alan (EAA) ile nasıl hesaplanır?\",\"answer\":\"CL = Doz / EAA (veya CL = ke x Vd). Vücudun birim zamanda kandan tamamen temizlediği sanal plazma hacmini ifade eder.\",\"box\":1,\"intervalDays\":1}],\"steps\":[{\"id\":\"pharm-mod3-les1-step1\",\"order\":1,\"stageIndex\":1,\"stage\":\"hook\",\"type\":\"hook\",\"predictThenReveal\":true,\"prompt\":{\"tr\":\"Klorokin ile aşırı doz alan hastada hemodiyaliz başlatıldı. Dört saat sonra kandaki klorokin düzeyi neredeyse hiç düşmedi. Hemodiyaliz neden tamamen başarısız oldu?\",\"ar\":\"بدأ غسيل الكلى لمريض تناول جرعة مفرطة من الكلوروكين. بعد أربع ساعات، لم ينخفض تركيزه بالدم. لماذا فشل الغسيل تماماً؟\",\"en\":\"Hemodialysis was started in a chloroquine overdose. After four hours, blood chloroquine levels barely dropped. Why did dialysis fail completely?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Klorokin gibi devasa dağılım hacmine sahip bir ilaçta hemodiyalizin klerense katkı sağlayamamasının temel nedeni nedir?\",\"ar\":\"ما السبب الأساسي لعدم قدرة الديال الدموي على تصفية دواء ذي حجم توزع هائل مثل الكلوروكين؟\",\"en\":\"What is the primary reason hemodialysis fails to clear a drug with a massive volume of distribution like chloroquine?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"Klorokin doku kompartmanlarına yoğun sekestre olur; toplam vücut yükünün %1'inden azı kanda bulunur.\",\"ar\":\"يحتجز الكلوروكين بكثافة داخل أنسجة الجسم؛ أقل من 1% من إجمالي الدواء موجود بالدم.\",\"en\":\"Chloroquine sequesters deeply into tissues; less than 1% of total body drug resides in blood.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel klinik teşhis! Vd ~15.000 L olan klorokinde ilacın %99'dan fazlası hücre içindedir; hemodiyaliz filtresi kanda bulunmayan ilacı temizleyemez.\",\"ar\":\"تشخيص سريري ممتاز! الكلوروكين بحجم توزع 15,000 لتر يحتجز بنسبة 99% في الأنسجة؛ وفلتر الديال لا ينقي دواءً غير موجود بالدم.\",\"en\":\"Superb clinical reasoning! With Vd ~15,000 L, over 99% of chloroquine is sequestered in tissues; dialysis cannot clear what is not in blood.\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"Hemodiyaliz membran porları klorokin molekülünün geçişine fiziksel olarak izin vermeyecek kadar küçüktür.\",\"ar\":\"مسام غشاء غسيل الكلى صغيرة جداً فيزيائياً بحيث تمنع عبور جزيء الكلوروكين.\",\"en\":\"Hemodialysis membrane pores are physically too small to permit passage of the chloroquine molecule.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Klorokinin molekül ağırlığı 320 Da'dur. Hemodiyaliz filtreleri 10.000 Da'a kadar molekülleri rahatça süzer; sorun por boyutu değil doku sekestrasyonudur.\",\"ar\":\"غير صحيح: الوزن الجزيئي للكلوروكين 320 دالتون. فلاتر الديال تمرر جزيئات حتى 10,000 دالتون؛ المشكلة احتجاز نسيجي وليست حجم المسام.\",\"en\":\"Incorrect: Chloroquine MW is 320 Da. Dialysis membranes easily filter up to 10,000 Da; failure is caused by tissue sequestration, not pore size.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"Klorokin fizyolojik pH'da pozitif yüklü olduğundan diyaliz sıvısına geçişi elektriksel olarak itilir.\",\"ar\":\"شحنة الكلوروكين الموجبة عند الباهاء الفسيولوجية تسبب تنافراً كهربائياً مع سائل الديال.\",\"en\":\"Chloroquine is positively charged at physiological pH, causing electrical repulsion from dialysis fluid.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Katyonik bazik ilaçlar konsantrasyon gradyentiyle diyalizata diffüze olabilir; elektrostatik itme hemodiyaliz yetersizliğini açıklamaz.\",\"ar\":\"غير صحيح: الأدوية القاعدية الكاتيونية تنتشر بحسب مدروج التركيز؛ التنافر الكهربائي ليس سبب فشل الديال الدموي.\",\"en\":\"Incorrect: Cationic basic drugs diffuse freely down concentration gradients; electrostatic repulsion is not the reason dialysis fails.\"}}]},\"technicalTerms\":[{\"term\":\"sanal dağılım hacmi\",\"arContext\":\"حجم التوزع الظاهري (apparent volume of distribution)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Hemodiyaliz membranı vücudun hangi sıvı kompartmanını doğrudan filtreleyebilir?\",\"ar\":\"ما هو الحيز السائل في الجسم الذي يفلتره غشاء غسيل الكلى مباشرة؟\",\"en\":\"Which anatomical fluid compartment does a hemodialysis machine directly filter?\"},{\"tier\":2,\"tr\":\"İlacın %99'u kas, karaciğer ve lizozomların içindeyse kanda ne kadarı kalır?\",\"ar\":\"إذا كان 99% من الدواء محتجزاً داخل العضلات والكبد والجسيمات الحالة، فكم يتبقى بالدم؟\",\"en\":\"If 99% of a drug is sequestered in muscle, liver, and lysosomes, how much remains in blood?\"},{\"tier\":3,\"tr\":\"Hemodiyaliz yalnızca kanda dolaşan serbest ilacı temizler; Vd çok büyükse diyaliz etkisizdir.\",\"ar\":\"غسيل الكلى ينقي فقط الدواء الحر في البلازما؛ وإذا كان Vd ضخماً جداً يصبح الغسيل غير مجدٍ.\",\"en\":\"Hemodialysis clears only free drug in plasma; if Vd is enormous, dialysis is completely ineffective.\"}],\"title\":{\"tr\":\"Klinik Paradoks: Klorokin Dozaşımı ve Diyaliz İflası\",\"ar\":\"مفارقة سريرية: جرعة الكلوروكين المفرطة وفشل الديال\",\"en\":\"Clinical Paradox: Chloroquine Overdose & Dialysis Failure\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"Klorokin doku kompartmanlarına yoğun sekestre olur; toplam vücut yükünün %1'inden azı kanda bulunur.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel klinik teşhis! Vd ~15.000 L olan klorokinde ilacın %99'dan fazlası hücre içindedir; hemodiyaliz filtresi kanda bulunmayan ilacı temizleyemez.\"},{\"id\":\"opt-2\",\"text\":\"Hemodiyaliz membran porları klorokin molekülünün geçişine fiziksel olarak izin vermeyecek kadar küçüktür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Klorokinin molekül ağırlığı 320 Da'dur. Hemodiyaliz filtreleri 10.000 Da'a kadar molekülleri rahatça süzer; sorun por boyutu değil doku sekestrasyonudur.\"},{\"id\":\"opt-3\",\"text\":\"Klorokin fizyolojik pH'da pozitif yüklü olduğundan diyaliz sıvısına geçişi elektriksel olarak itilir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Katyonik bazik ilaçlar konsantrasyon gradyentiyle diyalizata diffüze olabilir; elektrostatik itme hemodiyaliz yetersizliğini açıklamaz.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":2}]},{\"id\":\"pharm-mod3-les1-step2\",\"order\":2,\"stageIndex\":2,\"stage\":\"question\",\"type\":\"question\",\"prompt\":{\"tr\":\"Toplam vücut sıvısı 42 litre olan 70 kg'lık bir insanda, klorokinin dağılım hacmi nasıl 15.000 litre gibi devasa bir değer çıkabilir?\",\"ar\":\"في إنسان يزن 70 كغ ولديه 42 لتراً من سوائل الجسم الكلية، كيف يصل حجم توزع الكلوروكين إلى 15,000 لتر؟\",\"en\":\"In a 70 kg human with 42 liters of total body water, how can chloroquine have a distribution volume of 15,000 liters?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Dağılım hacminin (Vd) toplam vücut suyu hacmini (42 L) katbekat aşabilmesinin mantığı nedir?\",\"ar\":\"ما هو التفسير العلمي لتجاوز حجم التوزع (Vd) إجمالي ماء الجسم (42 لتر) بأضعاف مضاعفة؟\",\"en\":\"What is the scientific explanation for volume of distribution (Vd) greatly exceeding total body water (42 L)?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"Vd anatomik bir hacim değil, plazma derişiminin düşüklüğünü yansıtan matematiksel bir orantı katsayısıdır.\",\"ar\":\"حجم التوزع ليس حيزاً تشريحياً، بل ثابت تناسب رياضي يعكس شدة انخفاض تركيز البلازما.\",\"en\":\"Vd is not an anatomical space, but a mathematical proportionality constant reflecting low plasma concentration.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika! Vd = Doz / C0 formülünde, dokuya aşırı bağlanan ilaçların plazma derişimi (C0) sıfıra yakın olur; bu da yapay olarak devasa bir sanal hacim üretir.\",\"ar\":\"رائع! في معادلة Vd = الجرعة / C0، الأدوية شديدة الارتباط بالأنسجة ينخفض تركيزها بالبلازما بشدة، مما ينتج حجماً ظاهرياً هائلاً.\",\"en\":\"Brilliant! In Vd = Dose / C0, extensive tissue binding drives plasma concentration (C0) near zero, generating a massive apparent volume.\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"Klorokin böbreklerden atılamayıp lenfatik kanallarda biriktiği için ekstra lenf sıvısı üretir.\",\"ar\":\"الكلوروكين لا يطرح كلوياً بل يتراكم في القنوات اللمفاوية مما يحفز إنتاج سوائل إضافية.\",\"en\":\"Chloroquine accumulates in lymphatics rather than urine, stimulating generation of excess fluid.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: İlaçlar vücutta yeni sıvı yaratamaz. 15.000 L gerçek bir hacim değildir, doku sekestrasyonunun matematiksel sonucudur.\",\"ar\":\"غير صحيح: الأدوية لا تخلق سوائل جديدة في الجسم. 15,000 لتر ليست حجماً حقيقياً بل انعكاس رياضي للاحتجاز النسيجي.\",\"en\":\"Incorrect: Drugs do not create new fluid volumes. 15,000 L is a mathematical artifact of tissue sequestration, not real fluid.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"Vd değeri yalnızca plazma proteinlerine bağlanan ilaç miktarını gösterir; dokular hesaba katılmaz.\",\"ar\":\"قيمة Vd تعبر حصراً عن كمية الدواء المرتبطة ببروتينات البلازما، دون حساب الأنسجة.\",\"en\":\"The Vd value represents only drug bound to plasma proteins, ignoring tissue compartments.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Tam tersi! Plazma proteinlerine aşırı bağlanan ilaçların plazma derişimi yüksek kalır ve Vd'si küçüktür (örn. varfarin Vd ~7 L).\",\"ar\":\"العكس تماماً! الأدوية شديدة الارتباط ببروتينات البلازما يبقى تركيزها البلازمي مرتفعاً فيصغر Vd (كالوارفارين Vd ~7 لتر).\",\"en\":\"The exact opposite! Drugs heavily bound to plasma proteins remain in circulation and have small Vd (e.g. warfarin Vd ~7 L).\"}}]},\"technicalTerms\":[{\"term\":\"doku sekestrasyonu\",\"arContext\":\"الاحتجاز النسيجي (tissue sequestration)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Vd formülü nedir? Doz bölü plazma derişimi (C0).\",\"ar\":\"ما هو قانون Vd؟ الجرعة مقسومة على تركيز البلازما (C0).\",\"en\":\"What is the formula for Vd? Dose divided by plasma concentration (C0).\"},{\"tier\":2,\"tr\":\"Paydadaki plazma derişimi aşırı küçüldüğünde bölüm sonucu ne olur?\",\"ar\":\"عندما يصغر تركيز البلازما في المقام جداً، ماذا يحدث لناتج القسمة؟\",\"en\":\"When the denominator (plasma concentration) becomes very small, what happens to the result?\"},{\"tier\":3,\"tr\":\"Dokuya bağlanan ilaç plazmadan çekilir; düşük C0 değeri devasa bir sanal Vd üretir.\",\"ar\":\"الدواء المنجذب للأنسجة يغادر البلازما؛ انخفاض C0 ينتج رياضياً قيمة Vd هائلة.\",\"en\":\"Tissue-bound drug leaves plasma; a tiny C0 mathematically yields a massive apparent Vd.\"}],\"title\":{\"tr\":\"Kavramsal Soru: 15.000 Litrelik Sanal Okyanus\",\"ar\":\"سؤال مفاهيمي: محيط افتراضي سعة 15,000 لتر\",\"en\":\"Conceptual Question: The 15,000-Liter Apparent Ocean\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"Vd anatomik bir hacim değil, plazma derişiminin düşüklüğünü yansıtan matematiksel bir orantı katsayısıdır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika! Vd = Doz / C0 formülünde, dokuya aşırı bağlanan ilaçların plazma derişimi (C0) sıfıra yakın olur; bu da yapay olarak devasa bir sanal hacim üretir.\"},{\"id\":\"opt-2\",\"text\":\"Klorokin böbreklerden atılamayıp lenfatik kanallarda biriktiği için ekstra lenf sıvısı üretir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: İlaçlar vücutta yeni sıvı yaratamaz. 15.000 L gerçek bir hacim değildir, doku sekestrasyonunun matematiksel sonucudur.\"},{\"id\":\"opt-3\",\"text\":\"Vd değeri yalnızca plazma proteinlerine bağlanan ilaç miktarını gösterir; dokular hesaba katılmaz.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Tam tersi! Plazma proteinlerine aşırı bağlanan ilaçların plazma derişimi yüksek kalır ve Vd'si küçüktür (örn. varfarin Vd ~7 L).\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":2}]},{\"id\":\"pharm-mod3-les1-step3\",\"order\":3,\"stageIndex\":3,\"stage\":\"intuition\",\"type\":\"intuition\",\"prompt\":{\"tr\":\"Bir kova suya boya damlatıp içine kuru bir sünger atın. Sünger boyayı tamamen emerse, kovadaki serbest suyun rengi ve boya derişimi ne olur?\",\"ar\":\"ضع صبغة في دلو ماء ثم أسقط إسفنجة جافة. إذا امتصت الإسفنجة كل الصبغة، فماذا يحدث للون الماء المتبقي؟\",\"en\":\"Drop dye into a water bucket and add a dry sponge. If the sponge greedily absorbs the dye, what happens to the water's color?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Sünger analojisinde 'sünger' ve 'kova suyu' farmakokinetikte hangi kompartmanları temsil eder?\",\"ar\":\"في تشبيه الإسفنجة والدلو، ماذا تمثل 'الإسفنجة' وماذا يمثل 'ماء الدلو' في حركية الدواء؟\",\"en\":\"In the sponge analogy, what do the 'sponge' and the 'bucket water' represent in pharmacokinetics?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"Sünger derin dokuları (yağ, kas), kova suyu ise kan plazmasını temsil eder.\",\"ar\":\"الإسفنجة تمثل الأنسجة العميقة (الدهون والعضلات)، وماء الدلو يمثل بلازما الدم.\",\"en\":\"The sponge represents deep tissues (fat, muscle), while bucket water represents blood plasma.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru kavrayış! Doku süngeri ilacı emip hapsettiğinde plazma berrak kalır; örnek alan hekim ilacın devasa bir okyanusta çözündüğünü zanneder.\",\"ar\":\"فهم سليم! عندما تمتص إسفنجة الأنسجة الدواء، تصبح البلازما شبه خالية، فيتوهم المقيس أن الدواء تمدد في محيط مائي هائل.\",\"en\":\"Spot on! When tissue sponges absorb drug, plasma is depleted; an observer measuring plasma perceives an immense dilution volume.\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"Sünger böbrek glomerüllerini, kova suyu ise idrar kesesini temsil eder.\",\"ar\":\"الإسفنجة تمثل كبيبات الكلى، وماء الدلو يمثل المثانة البولية.\",\"en\":\"The sponge represents renal glomeruli, and bucket water represents the urinary bladder.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Glomerüller süzme yapar, depolama yapmaz. Sünger dağılımı ve doku sekestrasyonunu simgeler, eliminasyonu değil.\",\"ar\":\"غير صحيح: الكبيبات ترشح ولا تخزن. الإسفنجة ترمز لتوزع واحتجاز الدواء النسيجي وليس للإطراح.\",\"en\":\"Incorrect: Glomeruli filter, they do not store. The sponge symbolizes distribution and tissue sequestration, not elimination.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"Sünger albümin proteinlerini, kova suyu ise eritrositlerin içini temsil eder.\",\"ar\":\"الإسفنجة تمثل بروتينات الألبومين، وماء الدلو يمثل داخل كريات الدم الحمراء.\",\"en\":\"The sponge represents albumin proteins, and bucket water represents red blood cell interiors.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Albümin kanda dolaşır. Albümine yüksek bağlanan ilaç kanda kalır ve Vd'si küçüktür; sünger kan dışındaki dokulardır.\",\"ar\":\"غير صحيح: الألبومين يسبح في الدم. ارتباط الألبومين يبقي الدواء في البلازما فيصغر Vd؛ الإسفنجة هي الأنسجة خارج الدوران.\",\"en\":\"Incorrect: Albumin is in blood. High albumin binding keeps drug in plasma and reduces Vd; the sponge is extravascular tissue.\"}}]},\"technicalTerms\":[{\"term\":\"dağılım süngeri\",\"arContext\":\"إسفنجة التوزع (distribution sponge)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Sünger kovadaki boyayı emerse, sudan aldığınız örnekte boya miktarı nasıl görünür?\",\"ar\":\"إذا امتصت الإسفنجة الصبغة، فكيف سيبدو تركيز الصبغة في عينة الماء المأخوذة؟\",\"en\":\"If the sponge absorbs the dye, what does the dye concentration in a water sample look like?\"},{\"tier\":2,\"tr\":\"Plazmadan kan örneği aldığımızda dokuların içindeki ilacı doğrudan ölçebilir miyiz?\",\"ar\":\"عند أخذ عينة دم من البلازما، هل نقيس الدواء المحتجز داخل الأنسجة مباشرة؟\",\"en\":\"When taking a plasma sample, can we directly measure the drug trapped inside tissue cells?\"},{\"tier\":3,\"tr\":\"Doku süngeri ilacı çeker; kanda kalan azıcık ilaç, dağılım hacmini yapay olarak devasa gösterir.\",\"ar\":\"إسفنجة الأنسجة تسحب الدواء؛ قلة الدواء في البلازما تجعل حجم التوزع المحسوب يبدو عملاقاً.\",\"en\":\"Tissue sponges absorb drug; low plasma residue makes the calculated volume appear immense.\"}],\"title\":{\"tr\":\"Fiziksel Sezgi: Sünger ve Kova Analojisi\",\"ar\":\"الحدس الفيزيائي: تشبيه الإسفنجة والدلو\",\"en\":\"Physical Intuition: Sponge & Bucket Analogy\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"Sünger derin dokuları (yağ, kas), kova suyu ise kan plazmasını temsil eder.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru kavrayış! Doku süngeri ilacı emip hapsettiğinde plazma berrak kalır; örnek alan hekim ilacın devasa bir okyanusta çözündüğünü zanneder.\"},{\"id\":\"opt-2\",\"text\":\"Sünger böbrek glomerüllerini, kova suyu ise idrar kesesini temsil eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Glomerüller süzme yapar, depolama yapmaz. Sünger dağılımı ve doku sekestrasyonunu simgeler, eliminasyonu değil.\"},{\"id\":\"opt-3\",\"text\":\"Sünger albümin proteinlerini, kova suyu ise eritrositlerin içini temsil eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Albümin kanda dolaşır. Albümine yüksek bağlanan ilaç kanda kalır ve Vd'si küçüktür; sünger kan dışındaki dokulardır.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":2}]},{\"id\":\"pharm-mod3-les1-step4\",\"order\":4,\"stageIndex\":4,\"stage\":\"visual_explanation\",\"type\":\"visual_explanation\",\"prompt\":{\"tr\":\"Yarı-logaritmik konsantrasyon-zaman grafiğine bakın. Eliminasyon doğrusunu geriye sıfır anına uzattığımızda elde edilen C0 kesişimi, Vd'yi nasıl açığa çıkarır?\",\"ar\":\"انظر إلى الرسم البياني نصف اللوغاريتمي للتركيز مقابل الزمن. كيف يكشف تقاطع استقراء خط الإطراح مع الصفر (C0) عن قيمة Vd؟\",\"en\":\"Examine the semi-logarithmic concentration-time plot. How does extrapolating the elimination line back to zero time (C0) reveal Vd?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Tek kompartmanlı bir modelde IV bolus sonrası C0 değeri 2 katına çıkarsa, hesaplanan Vd değeri nasıl değişir?\",\"ar\":\"في نموذج الحجيرة الواحدة بعد حقنة IV، إذا تضاعف تركيز C0 المستقرأ مرتين لنفس الجرعة، فكيف يتغير Vd؟\",\"en\":\"In a one-compartment model after an IV bolus, if extrapolated C0 doubles for the same dose, how does calculated Vd change?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"Vd değeri yarıya iner çünkü Vd = Doz / C0 eşitliğinde C0 ile Vd ters orantılıdır.\",\"ar\":\"ينخفض Vd إلى النصف لأن Vd يتناسب عكساً مع C0 حسب المعادلة: Vd = الجرعة / C0.\",\"en\":\"Vd is halved because Vd is inversely proportional to C0 in Vd = Dose / C0.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kesinlikle doğru! Aynı doz verildiğinde kanda iki kat yüksek derişim ölçülmesi, ilacın dokulara daha az dağılıp kanda kaldığını ve Vd'nin yarıya indiğini gösterir.\",\"ar\":\"صحيح تماماً! قياس تركيز مضاعف في الدم لنفس الجرعة يعني أن الدواء لم يتوزع كثيراً في الأنسجة وبقي بالبلازما، فينخفض Vd للنصف.\",\"en\":\"Exactly right! A two-fold higher plasma concentration for the same dose proves less tissue uptake, meaning drug remains in blood and Vd halves.\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"Vd değeri iki katına çıkar çünkü yüksek başlangıç derişimi daha büyük dağılım gerektirir.\",\"ar\":\"يتضاعف Vd مرتين لأن التركيز الابتدائي المرتفع يتطلب حجماً أكبر للاستيعاب.\",\"en\":\"Vd doubles because a higher initial concentration requires a larger space to accommodate it.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: C0 paydadadır (Vd = Doz / C0). C0 artarsa Vd küçülür, büyümez.\",\"ar\":\"غير صحيح: C0 في المقام (Vd = الجرعة / C0). زيادة C0 تقلل Vd ولا تزيده.\",\"en\":\"Incorrect: C0 is in the denominator (Vd = Dose / C0). When C0 increases, Vd decreases.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"Vd değişmez çünkü dağılım hacmi doza ve plazma konsantrasyonuna tamamen duyarsızdır.\",\"ar\":\"لا يتغير Vd لأن حجم التوزع ثابت ومستقل تماماً عن الجرعة وتركيز البلازما.\",\"en\":\"Vd remains unchanged because volume of distribution is completely insensitive to concentration.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Kısmen yanıltıcı: Vd bir ilaç özelliği olsa da, hesaplama formülü Vd = Doz / C0'dır; C0 değişirse hesaplanan hacim değişir.\",\"ar\":\"مضلل: رغم أن Vd خاصية للدواء، إلا أن حسابه يعتمد على Vd = الجرعة / C0؛ وتغير C0 يغير الحجم المحسوب.\",\"en\":\"Misleading: While Vd is a pharmacokinetic property, its calculation is Vd = Dose / C0; altered C0 alters calculated Vd.\"}}]},\"technicalTerms\":[{\"term\":\"sıfır anı konsantrasyonu\",\"arContext\":\"التركيز الابتدائي المستقرأ (extrapolated C0)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Vd = Doz / C0 formülünde C0 paydada yer alır.\",\"ar\":\"في قانون Vd = الجرعة / C0، يقع C0 في المقام.\",\"en\":\"In the formula Vd = Dose / C0, C0 is in the denominator.\"},{\"tier\":2,\"tr\":\"Grafikte C0 ne kadar yüksekse, ilacın kanda toplanma oranı o kadar fazladır.\",\"ar\":\"كلما كان تقاطع C0 أعلى على الرسم البياني، كان احتباس الدواء في الدم أكبر.\",\"en\":\"A higher C0 intercept on the curve indicates greater drug confinement to the bloodstream.\"},{\"tier\":3,\"tr\":\"C0 iki katına çıkarsa Vd yarıya iner; kanda yüksek derişim küçük dağılım hacmi demektir.\",\"ar\":\"مضاعفة C0 تقلل Vd إلى النصف؛ التركيز الدموي العالي يعني حجم توزع صغير.\",\"en\":\"Doubling C0 halves Vd; high blood concentration reflects a small distribution volume.\"}],\"title\":{\"tr\":\"Görsel Açıklama: Yarı-Logaritmik Eğri ve C0 Ekstrapolasyonu\",\"ar\":\"الشرح البصري: المنحنى نصف اللوغاريتمي واستقراء C0\",\"en\":\"Visual Explanation: Semi-Log Plot & C0 Extrapolation\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"Vd değeri yarıya iner çünkü Vd = Doz / C0 eşitliğinde C0 ile Vd ters orantılıdır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kesinlikle doğru! Aynı doz verildiğinde kanda iki kat yüksek derişim ölçülmesi, ilacın dokulara daha az dağılıp kanda kaldığını ve Vd'nin yarıya indiğini gösterir.\"},{\"id\":\"opt-2\",\"text\":\"Vd değeri iki katına çıkar çünkü yüksek başlangıç derişimi daha büyük dağılım gerektirir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: C0 paydadadır (Vd = Doz / C0). C0 artarsa Vd küçülür, büyümez.\"},{\"id\":\"opt-3\",\"text\":\"Vd değişmez çünkü dağılım hacmi doza ve plazma konsantrasyonuna tamamen duyarsızdır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Kısmen yanıltıcı: Vd bir ilaç özelliği olsa da, hesaplama formülü Vd = Doz / C0'dır; C0 değişirse hesaplanan hacim değişir.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":3}]},{\"id\":\"pharm-mod3-les1-step5\",\"order\":5,\"stageIndex\":5,\"stage\":\"interactive_artifact\",\"type\":\"interactive_artifact\",\"prompt\":{\"tr\":\"Simülatörde Vd ve CL kaydırıcılarını değiştirin. Vd'yi artırmanın başlangıç konsantrasyonunu düşürürken eliminasyon eğrisini nasıl uzattığını gözlemleyin.\",\"ar\":\"حرك شريطي Vd و CL في المحاكي. لاحظ كيف يؤدي رفع Vd إلى خفض التركيز الابتدائي وإطالة منحنى الإطراح.\",\"en\":\"Adjust Vd and CL sliders in the simulator. Observe how increasing Vd lowers initial concentration while lengthening the elimination curve.\"},\"widgetType\":\"PkSimulator\",\"widget\":{\"type\":\"PkSimulator\",\"config\":{\"drugName\":\"Klorokin ve Teofilin PK Modeli\",\"prompt\":\"Vd ve CL parametrelerini ayarlayarak plazma konsantrasyonu ve eliminasyon yarılanma ömrünü simüle edin.\",\"defaultDoseMg\":500,\"defaultClearanceLHr\":3,\"defaultVdL\":50,\"defaultBioavailabilityF\":1,\"defaultKa\":1.5,\"therapeuticWindow\":[10,20],\"routes\":[\"iv_bolus\",\"oral\"],\"source\":{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":2},\"explanation\":\"Vd plazma tepe derişimini, CL ise birim zamandaki ilaç temizleme hızını belirler.\"}},\"config\":{\"drugName\":\"Klorokin ve Teofilin PK Modeli\",\"prompt\":\"Vd ve CL parametrelerini ayarlayarak plazma konsantrasyonu ve eliminasyon yarılanma ömrünü simüle edin.\",\"defaultDoseMg\":500,\"defaultClearanceLHr\":3,\"defaultVdL\":50,\"defaultBioavailabilityF\":1,\"defaultKa\":1.5,\"therapeuticWindow\":[10,20],\"routes\":[\"iv_bolus\",\"oral\"],\"source\":{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":2},\"explanation\":\"Vd plazma tepe derişimini, CL ise birim zamandaki ilaç temizleme hızını belirler.\"},\"technicalTerms\":[{\"term\":\"farmakokinetik simülasyon\",\"arContext\":\"المحاكاة الحركية الدوائية (pharmacokinetic simulation)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Vd kaydırıcısını en sağa çekin; başlangıç derişimi (C0) nasıl değişti?\",\"ar\":\"اسحب شريط Vd إلى أقصى اليمين؛ كيف تغير التركيز الابتدائي C0؟\",\"en\":\"Slide the Vd slider to maximum; how does the initial concentration (C0) respond?\"},{\"tier\":2,\"tr\":\"Vd büyüdüğünde klerens sabit kalsa bile ilacın vücuttan temizlenme süresi (t1/2) uzar mı?\",\"ar\":\"عندما يكبر Vd مع ثبات التصفية، هل يطول الوقت اللازم لتخلص الجسم من الدواء (t1/2)؟\",\"en\":\"When Vd expands while clearance stays constant, does drug persistence time (t1/2) lengthen?\"},{\"tier\":3,\"tr\":\"Büyük Vd, ilacı dokulara saklar; klerens sabit kalsa bile kanda az ilaç olduğundan eliminasyon gecikir.\",\"ar\":\"حجم Vd الكبير يخفي الدواء في الأنسجة؛ فتبطأ التصفية ويطول عمر النصف لقلة الدواء في الدم.\",\"en\":\"A large Vd hides drug in tissues; because little drug reaches the organs of clearance, half-life lengthens.\"}],\"title\":{\"tr\":\"İnteraktif Deney: Vd ve CL ile PK Simülasyonu\",\"ar\":\"تجربة تفاعلية: محاكاة الحركية الدوائية بتعديل Vd و CL\",\"en\":\"Interactive Experiment: PK Simulation of Vd & CL\"},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":2},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":3}]},{\"id\":\"pharm-mod3-les1-step6\",\"order\":6,\"stageIndex\":6,\"stage\":\"guided_discovery\",\"type\":\"guided_discovery\",\"prompt\":{\"tr\":\"Yaşlı bir hastada vücut yağ oranı artarak diazepamın Vd'sini iki katına çıkarmıştır. Karaciğer klerensi değişmediği halde diazepamın yarılanma ömrü neden iki katına çıkar?\",\"ar\":\"في مريض مسن ارتفعت نسبة الدهون فتضاعف حجم توزع الديازيبام مرتين. مع ثبات التصفية الكبدية، لماذا تضاعف عمر نصف الدواء؟\",\"en\":\"In an elderly patient, increased body fat doubles diazepam's Vd. With hepatic clearance unchanged, why does diazepam's half-life double?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Yarılanma ömrünün (t1/2) bağımsız bir fizyolojik parametre olmayıp 'hibrit' bir parametre olmasının klinik anlamı nedir?\",\"ar\":\"ما المعنى السريري لكون عمر النصف (t1/2) متغيراً هجيناً وتابعاً وليس ثابتاً فسيولوجياً مستقلاً؟\",\"en\":\"What is the clinical significance of half-life (t1/2) being a dependent hybrid parameter rather than an independent parameter?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"t1/2 hem dağılımın (Vd) hem eliminasyonun (CL) oranıdır; organ yetmezliği olmasa bile Vd artışı yarı ömrü uzatır.\",\"ar\":\"عمر النصف ناتج نسبة Vd إلى CL؛ وأي زيادة في التوزع تطيل عمر النصف حتى لو كانت وظائف الأعضاء سليمة.\",\"en\":\"t1/2 is the ratio of Vd to CL; expanding Vd prolongs half-life even when organ clearance is completely normal.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika kavrayış! t1/2 = 0.693 x Vd / CL. Karaciğer ve böbrekler mükemmel çalışsa bile, Vd genişlediğinde ilaç kandan saklandığı için yarı ömür uzar.\",\"ar\":\"فهم عبقري! t1/2 = 0.693 × Vd / CL. حتى مع كفاءة الكبد والكلية التامة، اتساع Vd يخفي الدواء عن التصفية فيطول عمر النصف.\",\"en\":\"Superb insight! t1/2 = 0.693 * Vd / CL. Even with perfect organ function, an expanded Vd sequesters drug away from clearance, prolonging t1/2.\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"Yarılanma ömrü yalnızca sitokrom P450 enzimlerinin ekspresyon hızına bağlıdır; vücut kompozisyonu etkisizdir.\",\"ar\":\"عمر النصف محكوم فقط بمعدل إنزيمات السيتوكروم P450، ولا يتأثر إطلاقاً بتكوين الجسم.\",\"en\":\"Half-life depends solely on CYP450 enzyme expression; body composition has no influence.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: CYP enzimleri klerensi (CL) etkiler; fakat yarı ömür Vd'ye de doğrudan bağlıdır. Yağ dokusu artışı lipofilik ilaçların yarı ömrünü uzatır.\",\"ar\":\"غير صحيح: إنزيمات CYP تحدد التصفية، لكن عمر النصف يتأثر طردياً بحجم التوزع Vd أيضاً.\",\"en\":\"Incorrect: CYP enzymes govern clearance (CL), but half-life is equally determined by Vd. Fat accumulation extends lipophilic drug half-life.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"Vd arttığında karaciğer kan akımı fizyolojik bir refleksle yarıya iner ve klerensi düşürür.\",\"ar\":\"عند زيادة Vd، يقل تدفق الدم إلى الكبد تلقائياً إلى النصف مما يخفض التصفية.\",\"en\":\"When Vd expands, hepatic blood flow reflexively drops by half to lower clearance.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Vd artışı karaciğer kan akımını düşürmez. Klerens sabit kalabilir; yarı ömrün uzaması tamamen matematiksel oran sonucudur.\",\"ar\":\"غير صحيح: زيادة Vd لا تقلل تدفق دم الكبد؛ بل ثبات CL مع زيادة Vd يطيل t1/2 حسابياً.\",\"en\":\"Incorrect: Vd does not alter liver blood flow. Clearance remains unchanged; half-life extension is a purely mathematical consequence of the ratio.\"}}]},\"technicalTerms\":[{\"term\":\"bağımlı hibrit parametre\",\"arContext\":\"المتغير الهجين التابع (dependent hybrid parameter)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Yarılanma ömrü formülü: t1/2 = 0.693 x Vd / CL.\",\"ar\":\"قانون عمر النصف: t1/2 = 0.693 × Vd / CL.\",\"en\":\"Half-life formula: t1/2 = 0.693 * Vd / CL.\"},{\"tier\":2,\"tr\":\"Paydaki Vd iki katına çıkar, paydadaki CL sabit kalırsa t1/2 ne olur?\",\"ar\":\"إذا تضاعف البسط Vd مرتين وبقي المقام CL ثابتاً، فماذا يحدث لـ t1/2؟\",\"en\":\"If numerator Vd doubles while denominator CL is unchanged, what happens to t1/2?\"},{\"tier\":3,\"tr\":\"Vd iki katına çıktığında t1/2 tam iki katına çıkar; karaciğer sağlam olsa bile hastada sedasyon uzar.\",\"ar\":\"مضاعفة Vd تضاعف t1/2 تماماً؛ فيطول التسكين لدى المسن رغم سلامة وظائف الكبد.\",\"en\":\"Doubling Vd exactly doubles t1/2; prolonged sedation occurs in the elderly despite intact hepatic clearance.\"}],\"title\":{\"tr\":\"Rehberli Keşif: Yaşlılıkta Diazepam Yarı Ömrü Paradoksu\",\"ar\":\"اكتشاف موجه: مفارقة عمر نصف الديازيبام لدى المسنين\",\"en\":\"Guided Discovery: Elderly Diazepam Half-Life Paradox\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"t1/2 hem dağılımın (Vd) hem eliminasyonun (CL) oranıdır; organ yetmezliği olmasa bile Vd artışı yarı ömrü uzatır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika kavrayış! t1/2 = 0.693 x Vd / CL. Karaciğer ve böbrekler mükemmel çalışsa bile, Vd genişlediğinde ilaç kandan saklandığı için yarı ömür uzar.\"},{\"id\":\"opt-2\",\"text\":\"Yarılanma ömrü yalnızca sitokrom P450 enzimlerinin ekspresyon hızına bağlıdır; vücut kompozisyonu etkisizdir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: CYP enzimleri klerensi (CL) etkiler; fakat yarı ömür Vd'ye de doğrudan bağlıdır. Yağ dokusu artışı lipofilik ilaçların yarı ömrünü uzatır.\"},{\"id\":\"opt-3\",\"text\":\"Vd arttığında karaciğer kan akımı fizyolojik bir refleksle yarıya iner ve klerensi düşürür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Vd artışı karaciğer kan akımını düşürmez. Klerens sabit kalabilir; yarı ömrün uzaması tamamen matematiksel oran sonucudur.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":6},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":20}]},{\"id\":\"pharm-mod3-les1-step7\",\"order\":7,\"stageIndex\":7,\"stage\":\"formal_explanation\",\"type\":\"formal_explanation\",\"prompt\":{\"tr\":\"Temel farmakokinetik eşitlikleri inceleyin: Klerens CL = ke x Vd = Doz / EAA ve eliminasyon yarı ömrü t1/2 = ln(2) / ke = 0.693 x Vd / CL.\",\"ar\":\"تأمل المعادلات الحركية الأساسية: التصفية CL = ke × Vd = الجرعة / AUC، وعمر النصف t1/2 = 0.693 × Vd / CL.\",\"en\":\"Review the fundamental equations: clearance CL = ke * Vd = Dose / AUC, and half-life t1/2 = ln(2) / ke = 0.693 * Vd / CL.\"},\"conceptCheck\":{\"question\":{\"tr\":\"Tek kompartmanlı bir modelde eliminasyon hız sabiti ke = 0.1 h^-1 ve dağılım hacmi Vd = 40 L ise klerens (CL) ve yarılanma ömrü (t1/2) nedir?\",\"ar\":\"في نموذج الحجيرة الواحدة، إذا كان ثابت الإطراح ke = 0.1 h^-1 وحجم التوزع Vd = 40 L، فما هي التصفية وعمر النصف؟\",\"en\":\"In a one-compartment model, if elimination rate constant ke = 0.1 hr^-1 and Vd = 40 L, what are clearance and half-life?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"CL = 4.0 L/saat ve t1/2 = 6.93 saat.\",\"ar\":\"التصفية CL = 4.0 L/h وعمر النصف t1/2 = 6.93 ساعات.\",\"en\":\"CL = 4.0 L/hr and t1/2 = 6.93 hours.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz hesaplama! CL = ke x Vd = 0.1 x 40 = 4.0 L/saat. t1/2 = 0.693 / ke = 0.693 / 0.1 = 6.93 saat.\",\"ar\":\"حساب دقيق! التصفية = 0.1 × 40 = 4.0 لتر/ساعة. عمر النصف = 0.693 / 0.1 = 6.93 ساعات.\",\"en\":\"Flawless calculation! CL = ke * Vd = 0.1 * 40 = 4.0 L/hr. t1/2 = 0.693 / 0.1 = 6.93 hours.\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"CL = 400 L/saat ve t1/2 = 10 saat.\",\"ar\":\"التصفية CL = 400 L/h وعمر النصف t1/2 = 10 ساعات.\",\"en\":\"CL = 400 L/hr and t1/2 = 10 hours.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Vd'yi ke'ye bölmüşsünüz (40 / 0.1 = 400). Doğru işlem çarpmadır: CL = ke x Vd = 4.0 L/saat.\",\"ar\":\"غير صحيح: قمت بقسمة Vd على ke بدلاً من ضربهما. الصحيح: CL = ke × Vd = 4.0 لتر/ساعة.\",\"en\":\"Incorrect: You divided Vd by ke instead of multiplying. The formula is CL = ke * Vd = 4.0 L/hr.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"CL = 0.4 L/saat ve t1/2 = 4.0 saat.\",\"ar\":\"التصفية CL = 0.4 L/h وعمر النصف t1/2 = 4.0 ساعات.\",\"en\":\"CL = 0.4 L/hr and t1/2 = 4.0 hours.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Basamak hatası (0.1 x 40 = 4.0'dır, 0.4 değil). Ayrıca t1/2 hesaplanırken ln(2) ~ 0.693 çarpanı kullanılmalıdır.\",\"ar\":\"غير صحيح: خطأ حسابي في الفواصل، كما تم إغفال المعامل 0.693 في حساب عمر النصف.\",\"en\":\"Incorrect: Arithmetic decimal error (0.1 * 40 = 4.0, not 0.4). Additionally, ln(2) ~ 0.693 must be used for t1/2.\"}}]},\"technicalTerms\":[{\"term\":\"eliminasyon hız sabiti\",\"arContext\":\"ثابت معدل الإطراح (elimination rate constant ke)\"}],\"hints\":[{\"tier\":1,\"tr\":\"CL = ke x Vd formülünü uygulayın.\",\"ar\":\"طبق معادلة: CL = ke × Vd.\",\"en\":\"Apply the formula: CL = ke * Vd.\"},{\"tier\":2,\"tr\":\"t1/2 = 0.693 / ke formülünü kullanın.\",\"ar\":\"استخدم قانون: t1/2 = 0.693 / ke.\",\"en\":\"Use the formula: t1/2 = 0.693 / ke.\"},{\"tier\":3,\"tr\":\"CL = 0.1 x 40 = 4 L/saat; t1/2 = 0.693 / 0.1 = 6.93 saattir.\",\"ar\":\"التصفية = 0.1 × 40 = 4 لتر/ساعة؛ وعمر النصف = 0.693 / 0.1 = 6.93 ساعات.\",\"en\":\"CL = 0.1 * 40 = 4 L/hr; t1/2 = 0.693 / 0.1 = 6.93 hours.\"}],\"title\":{\"tr\":\"Biçimsel Açıklama: Klerens, ke ve Yarı Ömür Formülleri\",\"ar\":\"الشرح المنهجي: معادلات التصفية وثابت ke وعمر النصف\",\"en\":\"Formal Explanation: Clearance, ke & Half-Life Formulas\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"CL = 4.0 L/saat ve t1/2 = 6.93 saat.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz hesaplama! CL = ke x Vd = 0.1 x 40 = 4.0 L/saat. t1/2 = 0.693 / ke = 0.693 / 0.1 = 6.93 saat.\"},{\"id\":\"opt-2\",\"text\":\"CL = 400 L/saat ve t1/2 = 10 saat.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Vd'yi ke'ye bölmüşsünüz (40 / 0.1 = 400). Doğru işlem çarpmadır: CL = ke x Vd = 4.0 L/saat.\"},{\"id\":\"opt-3\",\"text\":\"CL = 0.4 L/saat ve t1/2 = 4.0 saat.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Basamak hatası (0.1 x 40 = 4.0'dır, 0.4 değil). Ayrıca t1/2 hesaplanırken ln(2) ~ 0.693 çarpanı kullanılmalıdır.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":3}]},{\"id\":\"pharm-mod3-les1-step8\",\"order\":8,\"stageIndex\":8,\"stage\":\"concept_check\",\"type\":\"concept_check\",\"prompt\":{\"tr\":\"Bir hekim sürekli IV infüzyon hızını iki katına çıkarırsa, hastanın kararlı duruma (steady-state, Css) ulaşması için gereken süre nasıl değişir?\",\"ar\":\"إذا ضاعف الطبيب معدل التسريب الوريدي المستمر إلى الضعفين، فكيف يتغير الوقت اللازم لبلوغ الحالة المستقرة (Css)؟\",\"en\":\"If a physician doubles the continuous IV infusion rate, how does the time required to reach steady-state (Css) change?\"},\"conceptCheck\":{\"question\":{\"tr\":\"İnfüzyon hızı (R0) artırıldığında kararlı duruma (steady-state) ulaşma süresinin değişmeme sebebi nedir?\",\"ar\":\"ما السبب الحركي لعدم تغير زمن بلوغ الحالة المستقرة عند زيادة معدل التسريب (R0)؟\",\"en\":\"What pharmacokinetic principle explains why time to reach steady-state is independent of infusion rate (R0)?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"Kararlı duruma ulaşma süresi infüzyon hızına değil, yalnızca ilacın eliminasyon yarılanma ömrüne (4-5 x t1/2) bağlıdır.\",\"ar\":\"زمن الوصول للحالة المستقرة مستقل عن معدل التسريب، ويعتمد حصراً على عمر النصف الإطراحي (4-5 × t1/2).\",\"en\":\"Time to steady-state is independent of infusion rate and depends solely on elimination half-life (4-5 * t1/2).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika! İnfüzyon hızını iki katına çıkarmak ulaşılan kararlı durum derişimini (Css) iki katına çıkarır; ancak oraya varış süresi daima 4-5 yarı ömürdür.\",\"ar\":\"رائع! مضاعفة معدل التسريب تضاعف تركيز الحالة المستقرة (Css) فقط، لكن زمن الوصول يظل ثابتاً عند 4-5 أعمار نصف.\",\"en\":\"Spot on! Doubling the infusion rate doubles the plateau concentration (Css), but reaching that plateau always takes 4 to 5 half-lives.\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"Süre yarıya iner çünkü kompartmana birim zamanda iki kat daha fazla ilaç pompalanmaktadır.\",\"ar\":\"ينخفض الزمن إلى النصف لأن ضعف كمية الدواء تضخ إلى الحجيرة في وحدة الزمن.\",\"en\":\"The time is cut in half because twice as much drug is pumped into the compartment per hour.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Klasik öğrenci yanılgısı! Daha hızlı vermek konsantrasyonu yükseltir, ancak eliminasyon hızlandığı için platoya varış süresi değişmez.\",\"ar\":\"مغالطة شائعة! ضخ الدواء أسرع يرفع التركيز النهائي لكنه لا يسرع زمن الوصول لأن الإطراح يتسارع بالتوازي.\",\"en\":\"Classic misconception! Infusing faster raises concentration, but because elimination accelerates proportionally, time to plateau is unchanged.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"Süre iki katına çıkar çünkü artan konsantrasyon eliminasyon enzimlerini doygunluğa ulaştırır.\",\"ar\":\"يتضاعف الزمن مرتين لأن التركيز المرتفع يشبع إنزيمات الإطراح بالكامل.\",\"en\":\"The time doubles because elevated drug concentration fully saturates elimination enzymes.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Birinci derece kinetikte enzim doygunluğu olmaz. Eliminasyon hızı konsantrasyonla lineer artar.\",\"ar\":\"غير صحيح: في الحركية من الرتبة الأولى لا يحدث إشباع؛ بل يزداد معدل الإطراح طردياً مع التركيز.\",\"en\":\"Incorrect: First-order kinetics assumes linear capacity without saturation. Elimination rate rises proportionally with concentration.\"}}]},\"technicalTerms\":[{\"term\":\"kararlı durum konsantrasyonu\",\"arContext\":\"تركيز الحالة المستقرة (steady-state Css)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Kararlı duruma ulaşma kuralını hatırlayın: Platoya kaç yarılanma ömründe varılır?\",\"ar\":\"تذكر قاعدة الحالة المستقرة: كم عمر نصف يلزم لبلوغ الهضبة؟\",\"en\":\"Recall the steady-state rule: how many half-lives are required to reach the plateau?\"},{\"tier\":2,\"tr\":\"İnfüzyon hızı Css düzeyini yükseltir; fakat %95 doluluğa ulaşma süresi t1/2 fonksiyonudur.\",\"ar\":\"معدل التسريب يرفع مستوى Css، لكن الوصول إلى 95% منه محكوم بـ t1/2.\",\"en\":\"Infusion rate governs the plateau height, but time to 95% completion is a function of t1/2.\"},{\"tier\":3,\"tr\":\"İnfüzyon hızı ne olursa olsun kararlı duruma daima 4 ila 5 yarılanma ömründe ulaşılır.\",\"ar\":\"مهما كان معدل التسريب، يلزم دائماً 4 إلى 5 أعمار نصف لبلوغ الحالة المستقرة.\",\"en\":\"Regardless of infusion rate, steady-state is always reached in 4 to 5 half-lives.\"}],\"title\":{\"tr\":\"Kavram Kontrolü: İnfüzyon Hızı ve Kararlı Durum Yanılgısı\",\"ar\":\"اختبار المفهوم: مغالطة معدل التسريب والحالة المستقرة\",\"en\":\"Concept Check: Infusion Rate & Steady-State Fallacy\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"Kararlı duruma ulaşma süresi infüzyon hızına değil, yalnızca ilacın eliminasyon yarılanma ömrüne (4-5 x t1/2) bağlıdır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika! İnfüzyon hızını iki katına çıkarmak ulaşılan kararlı durum derişimini (Css) iki katına çıkarır; ancak oraya varış süresi daima 4-5 yarı ömürdür.\"},{\"id\":\"opt-2\",\"text\":\"Süre yarıya iner çünkü kompartmana birim zamanda iki kat daha fazla ilaç pompalanmaktadır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Klasik öğrenci yanılgısı! Daha hızlı vermek konsantrasyonu yükseltir, ancak eliminasyon hızlandığı için platoya varış süresi değişmez.\"},{\"id\":\"opt-3\",\"text\":\"Süre iki katına çıkar çünkü artan konsantrasyon eliminasyon enzimlerini doygunluğa ulaştırır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Birinci derece kinetikte enzim doygunluğu olmaz. Eliminasyon hızı konsantrasyonla lineer artar.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":3}]},{\"id\":\"pharm-mod3-les1-step9\",\"order\":9,\"stageIndex\":9,\"stage\":\"application\",\"type\":\"clinical_vignette\",\"prompt\":{\"tr\":\"Teofilin toksisitesi (Vd = 35 L, CL = 2.8 L/saat) geçiren hastaya hemodiyaliz (diyalizör klerensi = 7.0 L/saat) uygulanıyor. Diyaliz hastanın yarılanma ömrünü ne kadar kısaltır?\",\"ar\":\"مريض بتسمم التيوفيلين (Vd = 35 L, CL = 2.8 L/h) يخضع لغسيل الكلى (تصفية الفلتر = 7.0 L/h). كم يختصر الغسيل عمر النصف؟\",\"en\":\"A theophylline toxicity patient (Vd = 35 L, CL = 2.8 L/hr) undergoes hemodialysis (dialyzer clearance = 7.0 L/hr). How much does dialysis shorten t1/2?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Hemodiyaliz öncesi ve hemodiyaliz sırasındaki teofilin yarılanma ömürleri sırasıyla hangi seçenekte doğru verilmiştir?\",\"ar\":\"ما هو عمر نصف التيوفيلين قبل الغسيل وأثناء الغسيل على التوالي؟\",\"en\":\"What are the theophylline half-lives before and during hemodialysis, respectively?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"Diyaliz öncesi t1/2 = 8.66 saat; diyaliz sırasında toplam klerens 9.8 L/saat olup t1/2 = 2.47 saate iner.\",\"ar\":\"قبل الديال t1/2 = 8.66 ساعات؛ وأثناء الديال تصبح التصفية الكلية 9.8 L/h فيهبط t1/2 إلى 2.47 ساعة.\",\"en\":\"Before dialysis t1/2 = 8.66 hours; during dialysis total clearance is 9.8 L/hr, dropping t1/2 to 2.47 hours.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel klinik hesaplama! Teofilin Vd'si küçük (35 L) olduğu için kanda boldur. Diyaliz klerensi (7 L/saat) toplam klerensi 9.8 L/saate çıkarır ve yarı ömrü 8.7'den 2.5 saate düşürür.\",\"ar\":\"حساب سريري رائع! التيوفيلين حجم توزعه صغير (35 لتر) فهو متوافر بالدم. غسيل الكلى يرفع التصفية إلى 9.8 L/h فيقلص عمر النصف من 8.7 إلى 2.5 ساعة.\",\"en\":\"Outstanding clinical calculation! Theophylline has a small Vd (35 L), so drug resides mostly in plasma. Dialysis adds 7 L/hr, reducing t1/2 from 8.7 to 2.5 hours.\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"Diyaliz öncesi t1/2 = 12.5 saat; diyaliz sırasında t1/2 hiç değişmez çünkü diyalizör klerensi vücut klerensine eklenemez.\",\"ar\":\"قبل الديال t1/2 = 12.5 ساعة؛ وأثناء الديال لا يتغير لأن تصفية الفلتر لا تضاف لتصفية الجسم.\",\"en\":\"Before dialysis t1/2 = 12.5 hours; during dialysis t1/2 is unchanged because filter clearance cannot be added to body clearance.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Klerensler paralel organlar gibi doğrudan toplanır (CL_toplam = CL_vücut + CL_diyaliz).\",\"ar\":\"غير صحيح: معدلات التصفية تجمع طردياً كما في الأعضاء المتوازية (التصفية الكلية = تصفية الجسم + تصفية الديال).\",\"en\":\"Incorrect: Clearances are strictly additive (CL_total = CL_body + CL_dialysis).\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"Diyaliz öncesi t1/2 = 8.66 saat; diyaliz sırasında t1/2 sıfıra iner çünkü klerens sonsuz kabul edilir.\",\"ar\":\"قبل الديال t1/2 = 8.66 ساعات؛ وأثناء الديال يصبح صفر لأن التصفية تعتبر لانهائية.\",\"en\":\"Before dialysis t1/2 = 8.66 hours; during dialysis t1/2 drops to zero because clearance is infinite.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Diyalizör klerensi sonludur (7.0 L/saat). Dağılım hacmi nedeniyle yarı ömür sıfır olamaz.\",\"ar\":\"غير صحيح: تصفية الفلتر محدودة (7.0 L/h). وبسبب حجم التوزع لا يمكن لعمر النصف أن ينعدم.\",\"en\":\"Incorrect: Dialyzer clearance is finite (7.0 L/hr). Volume of distribution prevents half-life from dropping to zero.\"}}]},\"technicalTerms\":[{\"term\":\"diyalizör klerensi\",\"arContext\":\"تصفية الفلتر (dialyzer clearance)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Diyaliz öncesi t1/2 = 0.693 x 35 / 2.8 formülüyle hesaplanır.\",\"ar\":\"قبل الديال: t1/2 = 0.693 × 35 / 2.8.\",\"en\":\"Before dialysis: t1/2 = 0.693 * 35 / 2.8.\"},{\"tier\":2,\"tr\":\"Diyaliz sırasında toplam klerens: 2.8 + 7.0 = 9.8 L/saattir.\",\"ar\":\"أثناء الديال: التصفية الكلية = 2.8 + 7.0 = 9.8 L/h.\",\"en\":\"During dialysis: total clearance is 2.8 + 7.0 = 9.8 L/hr.\"},{\"tier\":3,\"tr\":\"Yeni t1/2 = 0.693 x 35 / 9.8 = 2.47 saattir; teofilin zehirlenmesinde diyaliz hayat kurtarıcıdır.\",\"ar\":\"عمر النصف الجديد = 0.693 × 35 / 9.8 = 2.47 ساعة؛ الديال ينقذ الحياة في تسمم التيوفيلين.\",\"en\":\"New t1/2 = 0.693 * 35 / 9.8 = 2.47 hours; dialysis is lifesaving in theophylline toxicity.\"}],\"title\":{\"tr\":\"Klinik Uygulama: Teofilin Zehirlenmesi ve Diyaliz Klerensi\",\"ar\":\"تطبيق سريري: تسمم التيوفيلين وتصفية غسيل الكلى\",\"en\":\"Clinical Vignette: Theophylline Poisoning & Dialysis\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"Diyaliz öncesi t1/2 = 8.66 saat; diyaliz sırasında toplam klerens 9.8 L/saat olup t1/2 = 2.47 saate iner.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel klinik hesaplama! Teofilin Vd'si küçük (35 L) olduğu için kanda boldur. Diyaliz klerensi (7 L/saat) toplam klerensi 9.8 L/saate çıkarır ve yarı ömrü 8.7'den 2.5 saate düşürür.\"},{\"id\":\"opt-2\",\"text\":\"Diyaliz öncesi t1/2 = 12.5 saat; diyaliz sırasında t1/2 hiç değişmez çünkü diyalizör klerensi vücut klerensine eklenemez.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Klerensler paralel organlar gibi doğrudan toplanır (CL_toplam = CL_vücut + CL_diyaliz).\"},{\"id\":\"opt-3\",\"text\":\"Diyaliz öncesi t1/2 = 8.66 saat; diyaliz sırasında t1/2 sıfıra iner çünkü klerens sonsuz kabul edilir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Diyalizör klerensi sonludur (7.0 L/saat). Dağılım hacmi nedeniyle yarı ömür sıfır olamaz.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":2}]},{\"id\":\"pharm-mod3-les1-step10\",\"order\":10,\"stageIndex\":10,\"stage\":\"retrieval\",\"type\":\"retrieval\",\"prompt\":{\"tr\":\"Tek bir intravenöz bolus dozun ardından, vücuttaki toplam ilaç miktarının %93'ünden fazlasının elenmesi için kaç yarılanma ömrü (t1/2) geçmesi gerekir?\",\"ar\":\"بعد جرعة وريدية واحدة، كم عمر نصف (t1/2) يلزم لإطراح أكثر من 93% من إجمالي الدواء من الجسم؟\",\"en\":\"Following a single intravenous bolus dose, how many half-lives (t1/2) must elapse to eliminate over 93% of the drug?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Eliminasyon yarılanma ömrü ile atılan ilaç fraksiyonu eşleştirmelerinden hangisi doğrudur?\",\"ar\":\"أي من الارتباطات التالية بين عمر النصف والنسبة المئوية للإطراح صحيحة دقيقة؟\",\"en\":\"Which mapping between elapsed half-lives and percentage of eliminated drug is accurate?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"4 yarılanma ömrü: %93.75 elenir (kalan %6.25); 5 yarılanma ömründe %96.88 elenir.\",\"ar\":\"4 أعمار نصف: يطرح 93.75% (يتبقى 6.25%)؛ وفي 5 أعمار نصف يطرح 96.88%.\",\"en\":\"4 half-lives: 93.75% eliminated (6.25% remains); in 5 half-lives 96.88% eliminated.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! 1. yarı ömürde %50 kalır, 2.'de %25, 3.'te %12.5, 4.'te %6.25 kalır (%93.75 elenir).\",\"ar\":\"صحيح! بعد عمر نصف واحد يتبقى 50%، ثم 25%، ثم 12.5%، وفي الرابع يتبقى 6.25% (أي تم إطراح 93.75%).\",\"en\":\"Correct! After 1 t1/2: 50% remains, after 2: 25%, after 3: 12.5%, after 4: 6.25% remains (93.75% eliminated).\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"2 yarılanma ömrü: İlaç miktarı doğrusal azalarak tamamı (%100) elenir.\",\"ar\":\"عمران نصف: يتناقص الدواء خطياً ليتم إطراح 100% منه تماماً.\",\"en\":\"2 half-lives: Drug quantity decreases linearly so that 100% is completely eliminated.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Klasik lineer yanılgı! İlaç doğrusal değil üstel azalır. 2 yarı ömürde ancak %75'i elenir, %25'i kalır.\",\"ar\":\"مغالطة خطية شائعة! تناقص الدواء أسي وليس خطياً. بعد عمرين نصف يطرح 75% فقط ويتبقى 25%.\",\"en\":\"Classic linear misconception! First-order elimination is exponential. After 2 half-lives, only 75% is cleared.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"7 yarılanma ömrü: %93'e ancak 7 yarı ömürde ulaşılır, öncesinde eliminasyon çok yavaştır.\",\"ar\":\"7 أعمار نصف: لا يتم بلوغ 93% إلا عند عمر النصف السابع لبطء الإطراح الأولي.\",\"en\":\"7 half-lives: 93% is only reached at 7 half-lives because initial clearance is slow.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: 7 yarı ömürde %99.2 elenmiş olur (klinik temizlenme kuralı). %93 için 4 yarılanma ömrü yeterlidir.\",\"ar\":\"غير صحيح: عند 7 أعمار نصف يطرح 99.2% من الدواء (قاعدة الغسيل التام). للوصول إلى 93% يكفي 4 أعمار نصف.\",\"en\":\"Incorrect: At 7 half-lives, 99.2% is eliminated (washout rule). 4 half-lives is sufficient to clear 93.75%.\"}}]},\"technicalTerms\":[{\"term\":\"üstel eliminasyon\",\"arContext\":\"الإطراح الأسي (exponential elimination)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Her yarı ömürde kalan ilaç miktarı yarıya iner: 100 -> 50 -> 25 -> ...\",\"ar\":\"في كل عمر نصف ينصف المتبقي: 100 -> 50 -> 25 -> ...\",\"en\":\"With each half-life remaining drug halves: 100 -> 50 -> 25 -> ...\"},{\"tier\":2,\"tr\":\"3 yarı ömürde %12.5 kalır (%87.5 atılır). Bir sonraki yarı ömürde ne kalır?\",\"ar\":\"بعد 3 أعمار نصف يتبقى 12.5% (يطرح 87.5%). كم يتبقى بعد عمر النصف التالي؟\",\"en\":\"After 3 half-lives 12.5% remains (87.5% cleared). What remains after the next half-life?\"},{\"tier\":3,\"tr\":\"4. yarı ömürde %6.25 kalır, yani %93.75'i vücuttan atılmış olur.\",\"ar\":\"في عمر النصف الرابع يتبقى 6.25%، أي تم التخلص من 93.75% من الدواء.\",\"en\":\"At the 4th half-life 6.25% remains, meaning 93.75% has been eliminated.\"}],\"title\":{\"tr\":\"Hafıza Yoklama: 4 Yarılanma Ömrü Kuralı\",\"ar\":\"استرجاع معرفي: قاعدة الأعمار النصفية الأربعة\",\"en\":\"Retrieval: The 4 Half-Lives Rule\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"4 yarılanma ömrü: %93.75 elenir (kalan %6.25); 5 yarılanma ömründe %96.88 elenir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! 1. yarı ömürde %50 kalır, 2.'de %25, 3.'te %12.5, 4.'te %6.25 kalır (%93.75 elenir).\"},{\"id\":\"opt-2\",\"text\":\"2 yarılanma ömrü: İlaç miktarı doğrusal azalarak tamamı (%100) elenir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Klasik lineer yanılgı! İlaç doğrusal değil üstel azalır. 2 yarı ömürde ancak %75'i elenir, %25'i kalır.\"},{\"id\":\"opt-3\",\"text\":\"7 yarılanma ömrü: %93'e ancak 7 yarı ömürde ulaşılır, öncesinde eliminasyon çok yavaştır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: 7 yarı ömürde %99.2 elenmiş olur (klinik temizlenme kuralı). %93 için 4 yarılanma ömrü yeterlidir.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":3}]},{\"id\":\"pharm-mod3-les1-step11\",\"order\":11,\"stageIndex\":11,\"stage\":\"connection\",\"type\":\"connection\",\"prompt\":{\"tr\":\"Plazma proteinlerine bağlanma (albümin) ile doku proteinlerine bağlanma arasındaki çekişme, bir ilacın Vd'sinin 5 L mi yoksa 15.000 L mi olacağını nasıl belirler?\",\"ar\":\"كيف يحدد التنافس بين الارتباط ببروتينات البلازما (الألبومين) وبروتينات الأنسجة ما إذا كان Vd يساوي 5 لترات أم 15,000 لتر؟\",\"en\":\"How does the tug-of-war between plasma protein binding (albumin) and tissue binding dictate whether Vd is 5 L or 15,000 L?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Fizyolojik dağılım hacmi eşitliği Vd = Vp + Vt x (fu / fu,t) gereğince, plazma serbest kesri (fu) doku serbest kesrinden (fu,t) çok daha büyükse ne olur?\",\"ar\":\"وفق معادلة Vd = Vp + Vt × (fu / fu,t)، إذا كان الكسر الحر في البلازما (fu) أكبر بكثير من الكسر الحر في الأنسجة (fu,t)، فما النتيجة؟\",\"en\":\"According to Vd = Vp + Vt * (fu / fu,t), if free fraction in plasma (fu) far exceeds free fraction in tissue (fu,t), what occurs?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"İlaç plazmadan kaçarak dokulara hücum eder; fu / fu,t oranı büyür ve Vd anatomik sınırları aşarak devasa boyutlara ulaşır.\",\"ar\":\"يهرب الدواء من البلازما إلى الأنسجة؛ ترتفع نسبة fu / fu,t ويتضخم Vd متجاوزاً الحيز التشريحي.\",\"en\":\"Drug flees plasma into tissues; the ratio fu / fu,t expands and Vd swells far beyond anatomical fluid limits.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika bağdaştırma! fu yüksek (plazmaya az bağlı) ve fu,t düşük (dokuya aşırı bağlı) olduğunda Vd binlerce litreye ulaşır (örn. trisiklik antidepresanlar, klorokin).\",\"ar\":\"ربط علمي ممتاز! عندما يكون fu كبيراً و fu,t صغيراً، يقفز Vd لآلاف اللترات كما في مضادات الاكتئاب ثلاثية الحلقات والكلوروكين.\",\"en\":\"Superb synthesis! When fu is high (low plasma binding) and fu,t is tiny (high tissue binding), Vd reaches thousands of liters (e.g. TCAs, chloroquine).\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"İlaç dokulara geçemez; plazmada hapsolarak Vd değerini plazma hacminin (3 L) altına düşürür.\",\"ar\":\"يعجز الدواء عن دخول الأنسجة، فينحصر في البلازما ويهبط Vd إلى أقل من حجم البلازما (3 لتر).\",\"en\":\"Drug cannot enter tissues; it becomes trapped in plasma, dropping Vd below plasma volume (3 L).\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Vd hiçbir zaman plazma hacminden (Vp ~3 L) küçük olamaz. Ayrıca fu'nun büyük olması ilacın dokuya geçmesini kolaylaştırır.\",\"ar\":\"غير صحيح: لا يمكن لـ Vd أن يقل عن حجم البلازما (3 لتر). كما أن كبر fu يسهل عبور الدواء للأنسجة.\",\"en\":\"Incorrect: Vd can never physically be less than plasma volume (~3 L). Furthermore, a high fu facilitates tissue entry.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"Plazma protein bağlanması Vd'yi etkilemez çünkü kılcal damar endoteli proteinleri de süzer.\",\"ar\":\"الارتباط ببروتينات البلازما لا يؤثر على Vd لأن بطانة الشعيرات ترشح البروتينات أيضاً.\",\"en\":\"Plasma protein binding has no effect on Vd because capillary endothelium filters proteins as well.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Albümin kapiller endoteli geçemez (MW ~66 kDa). Albümine bağlı ilaç damar yatağında hapsolur.\",\"ar\":\"غير صحيح: الألبومين لا يعبر بطانة الشعيرات لضخامة وزنه (66 كيلو دالتون)، فيحجز الدواء المرتبط داخل الأوعية.\",\"en\":\"Incorrect: Albumin cannot cross intact capillary endothelium (MW ~66 kDa). Albumin-bound drug is trapped within blood vessels.\"}}]},\"technicalTerms\":[{\"term\":\"serbest ilaç kesri\",\"arContext\":\"الكسر الدوائي الحر (fraction unbound fu)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Vd = Vp + Vt x (fu / fu,t) formülünü göz önüne alın.\",\"ar\":\"انظر إلى معادلة: Vd = Vp + Vt × (fu / fu,t).\",\"en\":\"Consider the equation: Vd = Vp + Vt * (fu / fu,t).\"},{\"tier\":2,\"tr\":\"Dokuya bağlanma aşırı güçlüyse dokudaki serbest kesir (fu,t) sıfıra yaklaşır.\",\"ar\":\"إذا كان الارتباط بالأنسجة شديداً، فإن الكسر الحر النسيجي fu,t يقترب من الصفر.\",\"en\":\"If tissue binding is extremely avid, free fraction in tissue (fu,t) approaches zero.\"},{\"tier\":3,\"tr\":\"Paydadaki fu,t küçüldükçe Vd katlanarak büyür; bu durum ilacı dokularda depolayarak Vd'yi devasa yapar.\",\"ar\":\"صغر fu,t في المقام يضخم Vd أضعافاً مضاعفة؛ مما يؤدي لتخزين الدواء بالأنسجة.\",\"en\":\"A tiny denominator fu,t causes Vd to multiply massively, sequestering drug into tissues.\"}],\"title\":{\"tr\":\"Bütünsel Bağlantı: Plazma Albümini vs Doku Bağlanması Dengesi\",\"ar\":\"الربط الشامل: توازن ارتباط ألبومين البلازما بالأنسجة\",\"en\":\"Holistic Connection: Plasma Albumin vs Tissue Binding Tug-of-War\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"İlaç plazmadan kaçarak dokulara hücum eder; fu / fu,t oranı büyür ve Vd anatomik sınırları aşarak devasa boyutlara ulaşır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika bağdaştırma! fu yüksek (plazmaya az bağlı) ve fu,t düşük (dokuya aşırı bağlı) olduğunda Vd binlerce litreye ulaşır (örn. trisiklik antidepresanlar, klorokin).\"},{\"id\":\"opt-2\",\"text\":\"İlaç dokulara geçemez; plazmada hapsolarak Vd değerini plazma hacminin (3 L) altına düşürür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Vd hiçbir zaman plazma hacminden (Vp ~3 L) küçük olamaz. Ayrıca fu'nun büyük olması ilacın dokuya geçmesini kolaylaştırır.\"},{\"id\":\"opt-3\",\"text\":\"Plazma protein bağlanması Vd'yi etkilemez çünkü kılcal damar endoteli proteinleri de süzer.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Albümin kapiller endoteli geçemez (MW ~66 kDa). Albümine bağlı ilaç damar yatağında hapsolur.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":2}]},{\"id\":\"pharm-mod3-les1-step12\",\"order\":12,\"stageIndex\":12,\"stage\":\"mastery_check\",\"type\":\"mastery_check\",\"prompt\":{\"tr\":\"Deneysel antifungal AF-90 (400 mg IV bolus) sonrasında C0 = 8.0 mg/L ve EAA = 80 mg·h/L bulunuyor. Vd, CL ve t1/2 değerlerini hesaplayıp hemodiyaliz uygulanabilirliğini değerlendirin.\",\"ar\":\"مضاد فطري تجريبي AF-90 (400 mg حقنة IV) سجل C0 = 8.0 mg/L و AUC = 80 mg·h/L. احسب Vd و CL و t1/2 وقيم جدوى غسيل الكلى.\",\"en\":\"Experimental antifungal AF-90 (400 mg IV bolus) yields C0 = 8.0 mg/L and AUC = 80 mg·hr/L. Calculate Vd, CL, and t1/2, and evaluate hemodialysis.\"},\"conceptCheck\":{\"question\":{\"tr\":\"AF-90'ın farmakokinetik parametreleri ve hemodiyaliz ile temizlenebilirlik durumu hangi seçenekte eksiksiz ve doğru verilmiştir?\",\"ar\":\"ما هي المعايير الحركية الصحيحة للدواء AF-90 ومدى قابليته للإزالة بغسيل الكلى؟\",\"en\":\"Which option completely and accurately states AF-90's pharmacokinetic parameters and hemodialysis feasibility?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"Vd = 50 L, CL = 5.0 L/saat, t1/2 = 6.93 saat; Vd vücut sıvısına yakın olduğundan hemodiyaliz zehirlenmede etkilidir.\",\"ar\":\"Vd = 50 L، والتصفية CL = 5.0 L/h، و t1/2 = 6.93 ساعات؛ وبما أن Vd مقارب لماء الجسم فإن الديال فعال.\",\"en\":\"Vd = 50 L, CL = 5.0 L/hr, t1/2 = 6.93 hours; moderate Vd close to total body water allows effective hemodialysis.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel ustalık! Vd = 400 / 8 = 50 L. CL = 400 / 80 = 5.0 L/saat. t1/2 = 0.693 x 50 / 5 = 6.93 saat. Vd küçük/orta olduğundan hemodiyaliz kanda bulunan ilacı etkin temizler.\",\"ar\":\"إتقان حركي باهر! Vd = 400 / 8 = 50 لتر. التصفية = 400 / 80 = 5 لتر/ساعة. عمر النصف = 0.693 × 50 / 5 = 6.93 ساعات. صغر Vd يجعل الغسيل فعالاً لوجود الدواء بالدم.\",\"en\":\"Mastery demonstrated! Vd = 400 / 8 = 50 L. CL = 400 / 80 = 5.0 L/hr. t1/2 = 0.693 * 50 / 5 = 6.93 hours. Because Vd is moderate (~total body water), hemodialysis is clinically effective.\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"Vd = 3200 L, CL = 0.2 L/saat, t1/2 = 110 saat; Vd çok büyük olduğundan hemodiyaliz tamamen başarısız olur.\",\"ar\":\"Vd = 3200 L، والتصفية CL = 0.2 L/h، و t1/2 = 110 ساعات؛ الحجم الهائل يمنع نجاح الديال.\",\"en\":\"Vd = 3200 L, CL = 0.2 L/hr, t1/2 = 110 hours; massive Vd causes hemodialysis to fail completely.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Formülleri ters çarpmışsınız (400 x 8 = 3200). Doğrusu Doz / C0 = 400 / 8 = 50 L'dir.\",\"ar\":\"غير صحيح: قمت بضرب الجرعة بالتركيز بدلاً من القسمة (400 × 8 = 3200). الصحيح: الجرعة / C0 = 50 لتراً.\",\"en\":\"Incorrect: You multiplied dose by concentration instead of dividing (400 * 8 = 3200). Correct: Dose / C0 = 50 L.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"Vd = 50 L, CL = 5.0 L/saat, t1/2 = 10.0 saat; hemodiyaliz membranında çökme yapacağı için kontrendikedir.\",\"ar\":\"Vd = 50 L، والتصفية CL = 5.0 L/h، و t1/2 = 10.0 ساعات؛ يمنع الديال لخطورة ترسب الدواء بالفلتر.\",\"en\":\"Vd = 50 L, CL = 5.0 L/hr, t1/2 = 10.0 hours; dialysis is contraindicated due to filter precipitation.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: t1/2 hesaplanırken ln(2) = 0.693 ihmal edilmiş (50 / 5 = 10 denmiş). Ayrıca hemodiyalizde ilaç çökmesi gibi bir kontrendikasyon yoktur.\",\"ar\":\"غير صحيح: تم إهمال المعامل 0.693 في حساب عمر النصف (50 / 5 = 10). كما لا يوجد موانع ترسب في الفلتر.\",\"en\":\"Incorrect: Failed to multiply by 0.693 (50 / 5 = 10). Furthermore, filter precipitation is an invented distractor.\"}}]},\"technicalTerms\":[{\"term\":\"toksikokinetik optimizasyon\",\"arContext\":\"التحسين السمومي الحركي (toxicokinetic optimization)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Vd = Doz / C0 ve CL = Doz / EAA eşitliklerini çözün.\",\"ar\":\"حل معادلتي: Vd = الجرعة / C0 و CL = الجرعة / AUC.\",\"en\":\"Solve Vd = Dose / C0 and CL = Dose / AUC.\"},{\"tier\":2,\"tr\":\"t1/2 = 0.693 x Vd / CL formülünde 50 L ve 5 L/saat değerlerini yerine koyun.\",\"ar\":\"عوض القيم في قانون: t1/2 = 0.693 × Vd / CL.\",\"en\":\"Substitute 50 L and 5 L/hr into t1/2 = 0.693 * Vd / CL.\"},{\"tier\":3,\"tr\":\"Vd = 50 L, CL = 5 L/saat, t1/2 = 6.93 saat. Vd < 1 L/kg (~70 L) olduğundan hemodiyaliz kanda bol ilaç bulur ve etkilidir.\",\"ar\":\"Vd = 50 L، والتصفية 5 L/h، و t1/2 = 6.93 ساعات. صغر Vd يجعل غسيل الكلى خياراً ممتازاً وفعالاً.\",\"en\":\"Vd = 50 L, CL = 5 L/hr, t1/2 = 6.93 hrs. Because Vd is moderate (< 1 L/kg), hemodialysis is clinically effective.\"}],\"title\":{\"tr\":\"Ustalık Sınavı: Antifungal AF-90 PK ve Diyaliz Analizi\",\"ar\":\"اختبار الإتقان: التحليل الحركي للدواء AF-90 وتقييم الديال\",\"en\":\"Mastery Check: Antifungal AF-90 PK & Dialysis Analysis\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"Vd = 50 L, CL = 5.0 L/saat, t1/2 = 6.93 saat; Vd vücut sıvısına yakın olduğundan hemodiyaliz zehirlenmede etkilidir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel ustalık! Vd = 400 / 8 = 50 L. CL = 400 / 80 = 5.0 L/saat. t1/2 = 0.693 x 50 / 5 = 6.93 saat. Vd küçük/orta olduğundan hemodiyaliz kanda bulunan ilacı etkin temizler.\"},{\"id\":\"opt-2\",\"text\":\"Vd = 3200 L, CL = 0.2 L/saat, t1/2 = 110 saat; Vd çok büyük olduğundan hemodiyaliz tamamen başarısız olur.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Formülleri ters çarpmışsınız (400 x 8 = 3200). Doğrusu Doz / C0 = 400 / 8 = 50 L'dir.\"},{\"id\":\"opt-3\",\"text\":\"Vd = 50 L, CL = 5.0 L/saat, t1/2 = 10.0 saat; hemodiyaliz membranında çökme yapacağı için kontrendikedir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: t1/2 hesaplanırken ln(2) = 0.693 ihmal edilmiş (50 / 5 = 10 denmiş). Ayrıca hemodiyalizde ilaç çökmesi gibi bir kontrendikasyon yoktur.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":3}]}]},\"pharm-mod3-les2\":{\"id\":\"pharm-mod3-les2\",\"courseId\":\"pharmacology\",\"moduleId\":\"ph-mod-03\",\"title\":{\"tr\":\"Biyoyararlanım, İlk Geçiş Eliminasyonu ve EAA Analizi\",\"ar\":\"التوافر الحيوي، تأثير المرور الأول وتحليل المساحة تحت المنحنى (AUC)\",\"en\":\"Bioavailability, First-Pass Elimination & AUC Analysis\"},\"order\":2,\"access\":\"free\",\"objective\":{\"tr\":\"Oral ve intravenöz eğriler altındaki alan (EAA) üzerinden mutlak biyoyararlanımı (F), hepatik ekstraksiyon oranını (EH) ve oral idame dozunu (MD) hesaplamak.\",\"ar\":\"حساب التوافر الحيوي المطلق (F) ومعدل الاستخلاص الكبدي (EH) وجرعة المداومة الفموية (MD) عبر تحليل المساحة تحت المنحنى (AUC) للحقن والفم.\",\"en\":\"Calculate absolute bioavailability (F), hepatic extraction ratio (EH), and oral maintenance dose (MD) through AUC analysis of oral and intravenous routes.\"},\"misconceptions\":[{\"tr\":\"Oral biyoyararlanım düşüklüğünün her zaman yetersiz gastrointestinal emilimden kaynaklandığı yanılgısı (karaciğer ilk geçiş ekstraksiyonu tam emilen ilaçları bile %80 oranında yok edebilir).\",\"ar\":\"الظن الخاطئ بأن تدني التوافر الحيوي الفموي ناتج دوماً عن سوء الامتصاص المعوي (الاستخلاص الكبدي بالمرور الأول قد يدمر 80% من دواء مكتمل الامتصاص).\",\"en\":\"The misconception that low oral bioavailability is always caused by poor gut absorption (hepatic first-pass extraction can eliminate 80% of completely absorbed drug).\"},{\"tr\":\"Karaciğer sirozunda portal şantların ilaç kan düzeylerini düşüreceği yanılgısı (karaciğeri baypas eden kan, yüksek ilk geçiş ekstraksiyonlu ilaçların biyoyararlanımını 4-6 kat artırarak ölümcül toksisiteye yol açar).\",\"ar\":\"الاعتقاد بأن تحويلات الدم البابية في تشمع الكبد تخفض تركيز الدواء (تجاوز الكبد يرفع توافر الأدوية عالية الاستخلاص بـ 4 إلى 6 أضعاف مسبباً سمية قاتلة).\",\"en\":\"The mistaken belief that portosystemic shunts in cirrhosis lower drug exposure (bypassing hepatic extraction multiplies oral bioavailability 4-6 fold, causing severe toxicity).\"}],\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":42}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Katzung's Basic & Clinical Pharmacology\",\"edition\":\"15th ed.\",\"topic\":\"Bioavailability, First-Pass Elimination, and AUC\",\"chapter\":\"Chapter 3: Pharmacokinetics & Pharmacodynamics: Rational Dosing & the Time Course of Drug Action\",\"page\":\"pp. 41-48\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Goodman & Gilman's The Pharmacological Basis of Therapeutics\",\"edition\":\"14th ed.\",\"topic\":\"Systemic Bioavailability and Hepatic First-Pass Metabolism\",\"chapter\":\"Chapter 2: Pharmacokinetics: The Dynamics of Drug Absorption, Distribution, Metabolism, and Elimination\",\"page\":\"pp. 25-33\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"pharm-mod3-les2-card1\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Mutlak Biyoyararlanım (F) Formülü\",\"prompt\":\"Oral ve IV bolus dozlar ile EAA değerleri kullanılarak mutlak biyoyararlanım (F) nasıl hesaplanır?\",\"answer\":\"F = (EAA_oral x Doz_IV) / (EAA_IV x Doz_oral). İlacın sistemik dolaşıma değişmeden ulaşan kesridir.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod3-les2-card2\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Hepatik İlk Geçiş Eşitliği\",\"prompt\":\"Gastrointestinal emilim tam (f = 1) olduğunda, biyoyararlanım (F) ile hepatik ekstraksiyon oranı (EH) arasındaki bağıntı nedir?\",\"answer\":\"F = 1 - EH (burada EH = CL_karaciğer / Q_karaciğer; portal kan akımı Q ~ 90 L/saat).\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod3-les2-card3\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Oral İdame Dozu Formülü\",\"prompt\":\"Hedef kararlı durum derişimi (Css), klerens (CL), doz aralığı (tau) ve biyoyararlanım (F) ile oral idame dozu (MD) nasıl hesaplanır?\",\"answer\":\"MD = (CL x Css x tau) / F. Biyoyararlanım düşükse gereken oral tablet dozu orantılı olarak büyür.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod3-les2-card4\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Sublingual Uygulama ve Karaciğer Baypası\",\"prompt\":\"Nitrogliserin neden yutulmayıp dilaltı (sublingual) verilir?\",\"answer\":\"Dilaltı venler doğrudan vena cava superior'a drene olarak karaciğer portal dolaşımını ve >%99'luk ilk geçiş metabolizmasını baypas eder.\",\"box\":1,\"intervalDays\":1}],\"steps\":[{\"id\":\"pharm-mod3-les2-step1\",\"order\":1,\"stageIndex\":1,\"stage\":\"hook\",\"type\":\"hook\",\"predictThenReveal\":true,\"prompt\":{\"tr\":\"Kardiyolog bir hastaya acilde 2 mg intravenöz propranolol uyguluyor; ancak taburcu ederken aynı etki için günde 80 mg oral tablet reçete ediyor. Oral doz neden 40 kat daha büyüktür?\",\"ar\":\"حقن طبيب قلب 2 mg بروبرانولول وريدياً؛ لكنه وصف عند التخريج 80 mg فموياً لتحقيق نفس الأثر. لماذا تزيد الجرعة الفموية بـ 40 ضعفاً؟\",\"en\":\"A cardiologist administers 2 mg propranolol IV, but prescribes 80 mg orally for the same effect. Why is the oral dose 40 times higher?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Oral propranololün damar içi doza kıyasla 40 kat yüksek verilmesini zorunlu kılan temel farmakokinetik engel nedir?\",\"ar\":\"ما الحاجز الحركي الدوائي الأساسي الذي يفرض رفع جرعة البروبرانولول الفموية 40 ضعفاً مقارنة بالحقن الوريدي؟\",\"en\":\"What primary pharmacokinetic obstacle necessitates giving a 40-fold higher dose of oral propranolol compared to IV?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"Bağırsaktan emilen ilacın yaklaşık %75'i portal ven yoluyla girdiği karaciğerde ilk geçişte metabolize edilerek yok edilir.\",\"ar\":\"يمتص الدواء معوياً بالكامل، لكن الكبد يستخلص ويستقلب نحو 75% منه بالمرور الأول عبر الوريد البابي.\",\"en\":\"The gut absorbs the drug completely, but the liver extracts and metabolizes ~75% during first-pass transit.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika klinik kavrayış! Propranolol bağırsaktan mükemmel emilir (f ~ 1); ancak karaciğer ilk geçiş ekstraksiyonu (EH ~ 0.75-0.80) sistemik dolaşıma ancak küçük bir fraksiyonun (F ~ %25) ulaşmasına izin verir.\",\"ar\":\"فهم سريري ممتاز! البروبرانولول يمتص جيداً، لكن كفاءة استخلاص الكبد العالية (EH ~ 0.75) تترك جزءاً ضئيلاً للدوران العام (F ~ 25%).\",\"en\":\"Superb clinical insight! Propranolol is fully absorbed, but high hepatic extraction (EH ~ 0.75-0.80) leaves only a small fraction reaching systemic blood.\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"Mide asidi propranolol moleküllerinin %97'sini parçalayarak bağırsak villuslarına ulaşmasını engeller.\",\"ar\":\"حمض المعدة يحلل 97% من جزيئات البروبرانولول قبل وصولها إلى زغابات الأمعاء الدقيقة.\",\"en\":\"Stomach acid hydrolyzes 97% of propranolol molecules before they can reach small intestinal villi.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Propranolol asitte oldukça kararlıdır; mide pH'sında yıkılmaz. Sorun gastrointestinal parçalanma değil, karaciğer ilk geçiş metabolizmasıdır.\",\"ar\":\"غير صحيح: البروبرانولول جزيء ثابت في الوسط الحمضي ولا يتخرب بالمعدة؛ المشكلة في الاستقلاب الكبدي البابي.\",\"en\":\"Incorrect: Propranolol is acid-stable and survives gastric pH intact. The barrier is hepatic portal extraction, not acid degradation.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"İntestinal P-glikoprotein pompaları propranololu enterosit içine girdiği anda lümene geri pompalar.\",\"ar\":\"مضخات P-glycoprotein المعوية تطرد البروبرانولول إلى لمعة الأمعاء فور دخوله الخلايا المعوية.\",\"en\":\"Intestinal P-glycoprotein pumps actively efflux propranolol back into the lumen as soon as it enters enterocytes.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Propranolol yüksek membran geçirgenliğine sahip lipofilik bir moleküldür ve P-gp'nin ana substratı değildir; emilim neredeyse eksiksizdir.\",\"ar\":\"غير صحيح: البروبرانولول دواء محب للدهون عالي النفوذية وليس ركيزة رئيسية لمضخة P-gp؛ الامتصاص المعوي مكتمل تقريباً.\",\"en\":\"Incorrect: Propranolol is highly lipophilic with excellent membrane permeability and is not heavily limited by P-gp efflux.\"}}]},\"technicalTerms\":[{\"term\":\"ilk geçiş eliminasyonu\",\"arContext\":\"تأثير المرور الأول (first-pass elimination)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Oral yoldan emilen ilaçların kalbe ulaşmadan önce uğradığı ilk filtre organı hangisidir?\",\"ar\":\"ما هو العضو المرشح الأول الذي تعبره الأدوية الممتصة فموياً قبل وصولها إلى القلب؟\",\"en\":\"What is the first filter organ that orally absorbed drugs must pass through before reaching the heart?\"},{\"tier\":2,\"tr\":\"Portal ven kanı doğrudan karaciğer sinüzoidlerine akar; karaciğer enzimleri burada ne yapar?\",\"ar\":\"يتدفق دم الوريد البابي مباشرة إلى أشباه الجيوب الكبدية؛ ماذا تفعل إنزيمات الكبد بالدواء هناك؟\",\"en\":\"Portal blood drains directly into hepatic sinusoids; what do hepatic enzymes do to the drug there?\"},{\"tier\":3,\"tr\":\"Karaciğer ilk geçişte ilacın büyük kısmını temizler; bu nedenle ağızdan verilen tablet dozu çok daha yüksek olmalıdır.\",\"ar\":\"الكبد يستخلص معظم الدواء في مروره الأول؛ لذا يجب رفع الجرعة الفموية لتعويض الفاقد الاستقلابي.\",\"en\":\"The liver eliminates most of the drug on its first pass; hence oral tablet doses must be much larger.\"}],\"title\":{\"tr\":\"Klinik Paradoks: Propranolol 2 mg IV vs 80 mg Oral\",\"ar\":\"مفارقة سريرية: بروبرانولول 2 mg وريدياً مقابل 80 mg فموياً\",\"en\":\"Clinical Paradox: Propranolol 2 mg IV vs 80 mg Oral\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"Bağırsaktan emilen ilacın yaklaşık %75'i portal ven yoluyla girdiği karaciğerde ilk geçişte metabolize edilerek yok edilir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika klinik kavrayış! Propranolol bağırsaktan mükemmel emilir (f ~ 1); ancak karaciğer ilk geçiş ekstraksiyonu (EH ~ 0.75-0.80) sistemik dolaşıma ancak küçük bir fraksiyonun (F ~ %25) ulaşmasına izin verir.\"},{\"id\":\"opt-2\",\"text\":\"Mide asidi propranolol moleküllerinin %97'sini parçalayarak bağırsak villuslarına ulaşmasını engeller.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Propranolol asitte oldukça kararlıdır; mide pH'sında yıkılmaz. Sorun gastrointestinal parçalanma değil, karaciğer ilk geçiş metabolizmasıdır.\"},{\"id\":\"opt-3\",\"text\":\"İntestinal P-glikoprotein pompaları propranololu enterosit içine girdiği anda lümene geri pompalar.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Propranolol yüksek membran geçirgenliğine sahip lipofilik bir moleküldür ve P-gp'nin ana substratı değildir; emilim neredeyse eksiksizdir.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":2},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":3}]},{\"id\":\"pharm-mod3-les2-step2\",\"order\":2,\"stageIndex\":2,\"stage\":\"question\",\"type\":\"question\",\"prompt\":{\"tr\":\"Ağızdan yutulan bir tablet ile kol venine enjekte edilen bir çözelti arasındaki yolculukta hangi anatomik ve fizyolojik bariyerler yer alır?\",\"ar\":\"بين حبة دواء يتم بلعها ومحلول يحقن في وريد الذراع، ما الحواجز التشريحية والفسيولوجية التي تعترض الدواء الفموي؟\",\"en\":\"Between a swallowed pill and an arm vein injection, what anatomical and physiological barriers intercept the oral drug?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Oral bir ilacın sistemik arteriyel kana ulaşması için sırasıyla hangi anatomik kompartmanları aşması zorunludur?\",\"ar\":\"ما الترتيب التشريحي الصحيح للحواجز التي يعبرها الدواء الفموي لبلوغ الشرايين الجهازية؟\",\"en\":\"What is the correct anatomical sequence of compartments an oral drug must traverse to enter systemic arterial blood?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"Bağırsak lümeni -> Enterosit membranı -> Portal ven -> Karaciğer sinüzoidleri -> Vena kava -> Sistemik dolaşım.\",\"ar\":\"لمعة الأمعاء -> غشاء الخلايا المعوية -> الوريد البابي -> أشباه جيوب الكبد -> الوريد الأجوف -> الدوران العام.\",\"en\":\"Gut lumen -> Enterocyte membrane -> Portal vein -> Hepatic sinusoids -> Vena cava -> Systemic circulation.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz anatomi! İlaç önce enterosit CYP/taşıyıcılarını, ardından portal dolaşımı ve karaciğer enzimlerini aşmak zorundadır.\",\"ar\":\"تسلسل تشريحي سليم! يعبر الدواء إنزيمات وناقلات الأمعاء أولاً، ثم الجريان البابي وإنزيمات الكبد ثانياً.\",\"en\":\"Flawless anatomical sequence! Drug must survive enterocyte enzymes/transporters, portal flow, and hepatic sinusoidal metabolism.\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"Mide mukozası -> Çölyak arter -> Aorta -> Karaciğer arteriyolleri -> Sağ atriyum.\",\"ar\":\"مخاطية المعدة -> الشريان الزلاقي -> الأبهر -> شرايين الكبد -> الأذين الأيمن.\",\"en\":\"Gastric mucosa -> Celiac artery -> Aorta -> Hepatic arterioles -> Right atrium.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Emilim venöz sisteme (portal ven) olur, arterlere değil. Çölyak arter kalpten organlara kan taşır.\",\"ar\":\"غير صحيح: الامتصاص يتم إلى الأوردة (الوريد البابي) وليس الشرايين. الشريان الزلاقي يحمل الدم من القلب للأحشاء.\",\"en\":\"Incorrect: Absorption drains into the venous system (portal vein), not arteries. Celiac artery carries blood away from heart.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"Bağırsak lümeni -> Lenfatik torasik kanal -> Portal ven -> Safra kanalı -> Böbrekler.\",\"ar\":\"لمعة الأمعاء -> القناة الصدرية اللمفاوية -> الوريد البابي -> القناة الصفراوية -> الكليتان.\",\"en\":\"Gut lumen -> Thoracic lymph duct -> Portal vein -> Bile duct -> Kidneys.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Çoğu ilaç portal kanla taşınır. Lenfatik yol yalnızca şilomikronlara bağlanan son derece lipofilik moleküller içindir.\",\"ar\":\"غير صحيح: الغالبية العظمى من الأدوية تسلك الوريد البابي. المسار اللمفاوي يقتصر على جزيئات فائقة الشحوم مع الكيلوميكرونات.\",\"en\":\"Incorrect: The vast majority of drugs travel via portal blood. Lymphatic transport is limited to extremely lipophilic drugs in chylomicrons.\"}}]},\"technicalTerms\":[{\"term\":\"portal dolaşım\",\"arContext\":\"الدوران البابي (portal circulation)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Bağırsak villuslarından kana geçen maddeler hangi büyük vene toplanır?\",\"ar\":\"ما هو الوريد الضخم الذي يستقبل المواد الممتصة من زغابات الأمعاء؟\",\"en\":\"What major vein collects substances absorbed from intestinal villi?\"},{\"tier\":2,\"tr\":\"Portal ven doğrudan nereye açılır? Karaciğer sinüzoidlerine.\",\"ar\":\"إلى أين يفرغ الوريد البابي دمه مباشرة؟ إلى أشباه الجيوب الكبدية.\",\"en\":\"Where does the portal vein drain directly? Into hepatic sinusoids.\"},{\"tier\":3,\"tr\":\"Sıralama: Lümen -> Enterosit -> Portal ven -> Karaciğer -> Hepatik ven -> Vena kava -> Sistemik arterler.\",\"ar\":\"المسار: اللمعة -> الخلية المعوية -> الوريد البابي -> الكبد -> الوريد الكبدي -> الوريد الأجوف -> الشرايين.\",\"en\":\"Sequence: Lumen -> Enterocyte -> Portal vein -> Liver -> Hepatic vein -> Vena cava -> Systemic arteries.\"}],\"title\":{\"tr\":\"Kavramsal Soru: Tabletin Sistemik Dolaşıma Yolculuğu\",\"ar\":\"سؤال مفاهيمي: رحلة القرص الفموي نحو الدوران الجهازي\",\"en\":\"Conceptual Question: The Journey from Pill to Systemic Arteries\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"Bağırsak lümeni -> Enterosit membranı -> Portal ven -> Karaciğer sinüzoidleri -> Vena kava -> Sistemik dolaşım.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz anatomi! İlaç önce enterosit CYP/taşıyıcılarını, ardından portal dolaşımı ve karaciğer enzimlerini aşmak zorundadır.\"},{\"id\":\"opt-2\",\"text\":\"Mide mukozası -> Çölyak arter -> Aorta -> Karaciğer arteriyolleri -> Sağ atriyum.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Emilim venöz sisteme (portal ven) olur, arterlere değil. Çölyak arter kalpten organlara kan taşır.\"},{\"id\":\"opt-3\",\"text\":\"Bağırsak lümeni -> Lenfatik torasik kanal -> Portal ven -> Safra kanalı -> Böbrekler.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Çoğu ilaç portal kanla taşınır. Lenfatik yol yalnızca şilomikronlara bağlanan son derece lipofilik moleküller içindir.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":3}]},{\"id\":\"pharm-mod3-les2-step3\",\"order\":3,\"stageIndex\":3,\"stage\":\"intuition\",\"type\":\"intuition\",\"prompt\":{\"tr\":\"Bir limandan çıkan tek otoyol üzerindeki gümrük kapısını düşünün. Muhafızlar gelen malların %80'ine el koyarsa, ülkenin serbest pazarına ne kadarı girebilir?\",\"ar\":\"تخيل نقطة تفتيش جمركية على الطريق السريع الوحيد الخارج من الميناء. إذا صادر الحراس 80% من البضائع، فكم يصل للسوق؟\",\"en\":\"Picture a border tollbooth on the single highway leaving a port. If guards confiscate 80% of goods, how much cargo enters the country?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Gümrük kapısı analojisinde 'liman', 'gümrük muhafızları' ve 'serbest pazar' vücutta neye karşılık gelir?\",\"ar\":\"في تشبيه نقطة التفتيش، ماذا يمثل 'الميناء' و'الحراس' و'السوق الحرة' في الجسم البشري؟\",\"en\":\"In the tollbooth analogy, what do the 'port', 'guards', and 'free market' correspond to in the human body?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"Liman bağırsak emilimini, gümrük karaciğer enzimlerini, serbest pazar ise sistemik dolaşımı temsil eder.\",\"ar\":\"الميناء يمثل الامتصاص المعوي، والحراس يمثلون إنزيمات الكبد، والسوق الحرة تمثل الدوران الجهازي.\",\"en\":\"The port represents gut absorption, guards represent liver enzymes, and free market represents systemic circulation.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel analoji! Karaciğer gümrüğü gelen ilacın %80'ini kırparsa (EH = 0.80), sistemik pazara ancak %20'si (F = 0.20) geçebilir.\",\"ar\":\"تشبيه بديع! إذا صادر جمرك الكبد 80% من الدواء (EH = 0.80)، فلن يدخل الدوران العام سوى 20% فقط (F = 0.20).\",\"en\":\"Spot-on analogy! If the liver checkpoint eliminates 80% of cargo (EH = 0.80), only 20% reaches the systemic market (F = 0.20).\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"Liman böbrek glomerüllerini, gümrük idrar kesesini, serbest pazar ise dışkıyı temsil eder.\",\"ar\":\"الميناء يمثل كبيبات الكلى، والحراس يمثلون المثانة، والسوق الحرة تمثل البراز.\",\"en\":\"The port represents kidney glomeruli, guards represent the bladder, and free market represents feces.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Glomerül ve idrar kesesi eliminasyon organlarıdır; oral biyoyararlanım ve ilk geçiş mekanizmasını açıklamaz.\",\"ar\":\"غير صحيح: الكلى والمثانة أعضاء إطراح بولي؛ التشبيه يخص الامتصاص الفموي والمرور الكبدي البابي.\",\"en\":\"Incorrect: Glomeruli and bladder are urinary elimination structures; they do not represent oral absorption and hepatic transit.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"Liman kan-beyin bariyerini, gümrük astrositleri, serbest pazar ise beyin omurilik sıvısını temsil eder.\",\"ar\":\"الميناء يمثل الحاجز الدموي الدماغي، والحراس يمثلون الخلايا النجمية، والسوق تمثل السائل الدماغي.\",\"en\":\"The port represents the blood-brain barrier, guards represent astrocytes, and free market represents CSF.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Kan-beyin bariyeri santral sinir sistemi dağılımını ilgilendirir; ilk geçiş metabolizması gastrointestinal ve hepatik bir olgudur.\",\"ar\":\"غير صحيح: الحاجز الدموي الدماغي يخص توزع الدواء بالمخ؛ بينما تأثير المرور الأول ظاهرة كبدية معوية.\",\"en\":\"Incorrect: The blood-brain barrier governs CNS drug distribution; first-pass elimination is a gastrointestinal-hepatic phenomenon.\"}}]},\"technicalTerms\":[{\"term\":\"hepatik ekstraksiyon oranı\",\"arContext\":\"نسبة الاستخلاص الكبدي (hepatic extraction ratio EH)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Malların %80'ine gümrükte el konursa geriye kaçta kaçı kalır?\",\"ar\":\"إذا تمت مصادرة 80% من البضائع في التفتيش، فما هي النسبة المتبقية؟\",\"en\":\"If 80% of goods are seized at the border, what fraction remains?\"},{\"tier\":2,\"tr\":\"100 birim maldan 80'i elenirse ülkeye 20 birim girer (%20 biyoyararlanım).\",\"ar\":\"من كل 100 وحدة، يصادر 80 وتصل 20 وحدة (20% توافر حيوي).\",\"en\":\"Out of 100 units, 80 are cleared and 20 enter circulation (20% bioavailability).\"},{\"tier\":3,\"tr\":\"Karaciğer enzimleri gümrük memurudur; EH yüksekse sistemik dolaşıma çok az ilaç sızabilir.\",\"ar\":\"إنزيمات الكبد هي حراس الجمارك؛ وكلما ارتفعت قيمة EH قل الدواء الواصل للدوران الجهازي.\",\"en\":\"Hepatic enzymes are border guards; if EH is high, very little drug penetrates systemic circulation.\"}],\"title\":{\"tr\":\"Fiziksel Sezgi: Liman ve Gümrük Kapısı Analojisi\",\"ar\":\"الحدس الفيزيائي: تشبيه الميناء وبوابة الجمارك\",\"en\":\"Physical Intuition: Port & Border Tollbooth Analogy\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"Liman bağırsak emilimini, gümrük karaciğer enzimlerini, serbest pazar ise sistemik dolaşımı temsil eder.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel analoji! Karaciğer gümrüğü gelen ilacın %80'ini kırparsa (EH = 0.80), sistemik pazara ancak %20'si (F = 0.20) geçebilir.\"},{\"id\":\"opt-2\",\"text\":\"Liman böbrek glomerüllerini, gümrük idrar kesesini, serbest pazar ise dışkıyı temsil eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Glomerül ve idrar kesesi eliminasyon organlarıdır; oral biyoyararlanım ve ilk geçiş mekanizmasını açıklamaz.\"},{\"id\":\"opt-3\",\"text\":\"Liman kan-beyin bariyerini, gümrük astrositleri, serbest pazar ise beyin omurilik sıvısını temsil eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Kan-beyin bariyeri santral sinir sistemi dağılımını ilgilendirir; ilk geçiş metabolizması gastrointestinal ve hepatik bir olgudur.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":3}]},{\"id\":\"pharm-mod3-les2-step4\",\"order\":4,\"stageIndex\":4,\"stage\":\"visual_explanation\",\"type\":\"visual_explanation\",\"prompt\":{\"tr\":\"İntravenöz bolus ve oral konsantrasyon-zaman eğrilerini karşılaştırın. Eğri altındaki alan (EAA / AUC) vücudun toplam ilaç maruziyetini nasıl ifade eder?\",\"ar\":\"قارن بين منحنَي التركيز والزمن للحقن الوريدي والجرعة الفموية. كيف تعبر المساحة تحت المنحنى (AUC) عن إجمالي التعرض الدوائي للجسم؟\",\"en\":\"Compare IV bolus and oral concentration-time curves. How does the area under the curve (AUC) express total systemic drug exposure?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Aynı hastada eşit dozda (100 mg) verilen bir ilacın oral EAA'sı 25 mg·h/L, IV EAA'sı ise 100 mg·h/L ölçülmüştür. Bu ilacın mutlak oral biyoyararlanımı (F) nedir?\",\"ar\":\"لنفس المريض وبجرعة متساوية (100 mg)، سجلت المساحة الفموية AUC = 25 mg·h/L والوريدية AUC = 100 mg·h/L. ما التوافر الحيوي المطلق (F)؟\",\"en\":\"In the same patient with equal doses (100 mg), oral AUC is 25 mg·hr/L and IV AUC is 100 mg·hr/L. What is the absolute oral bioavailability (F)?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"F = 0.25 (%25); oral EAA'nın IV EAA'ya oranı sistemik dolaşıma ulaşan net kesri verir.\",\"ar\":\"F = 0.25 (25%)؛ نسبة المساحة الفموية إلى المساحة الوريدية تمثل الكسر الواصل للدوران.\",\"en\":\"F = 0.25 (25%); the ratio of oral AUC to IV AUC directly yields the fraction reaching circulation.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika! Dozlar eşit olduğunda formül F = EAA_oral / EAA_IV halini alır: 25 / 100 = 0.25 (%25).\",\"ar\":\"إجابة صحيحة! عند تساوي الجرعات تصبح المعادلة F = AUC_oral / AUC_IV؛ أي 25 / 100 = 0.25 (25%).\",\"en\":\"Spot on! When doses are identical, F = AUC_oral / AUC_IV = 25 / 100 = 0.25 (25%).\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"F = 4.0 (%400); IV maruziyet oral maruziyetin dört katı olduğu için biyoyararlanım dörttür.\",\"ar\":\"F = 4.0 (400%)؛ لأن التعرض الوريدي يعادل أربعة أضعاف الفموي فالتوافر الحيوي أربعة.\",\"en\":\"F = 4.0 (400%); because IV exposure is four times oral, bioavailability is four.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Orantıyı ters kurmuşsunuz (100 / 25 = 4). Biyoyararlanım hiçbir zaman 1.0'ı (%100) aşamaz; paydada IV EAA bulunmalıdır.\",\"ar\":\"غير صحيح: عكست النسبة (100 / 25 = 4). التوافر الحيوي لا يتجاوز 100% أبداً؛ ويجب وضع AUC الوريدي في المقام.\",\"en\":\"Incorrect: Inverted ratio (100 / 25 = 4). Bioavailability can never exceed 1.0 (100%); IV AUC belongs in the denominator.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"F = 0.75 (%75); aradaki fark olan 75 birim sistemik dolaşıma geçen ilacı temsil eder.\",\"ar\":\"F = 0.75 (75%)؛ الفارق البالغ 75 وحدة يمثل الدواء الذي دخل الدوران الجهازي.\",\"en\":\"F = 0.75 (75%); the difference of 75 units represents drug entering systemic circulation.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: 0.75 kaybolan (elimine edilen) kesirdir, sistemik kana geçen kesir değil. Biyoyararlanım fark değil oran ile hesaplanır.\",\"ar\":\"غير صحيح: 0.75 هي نسبة الفاقد المستقلب وليس ما وصل للدوران. التوافر الحيوي نسبة وليس طرحاً.\",\"en\":\"Incorrect: 0.75 is the extracted fraction, not the bioavailable fraction. Bioavailability is a ratio, not a subtraction.\"}}]},\"technicalTerms\":[{\"term\":\"eğri altındaki alan\",\"arContext\":\"المساحة تحت المنحنى (area under the curve AUC)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Biyoyararlanım eşitliği: F = (EAA_oral x Doz_IV) / (EAA_IV x Doz_oral).\",\"ar\":\"قانون التوافر الحيوي: F = (AUC_oral × Dose_IV) / (AUC_IV × Dose_oral).\",\"en\":\"Bioavailability equation: F = (AUC_oral * Dose_IV) / (AUC_IV * Dose_oral).\"},{\"tier\":2,\"tr\":\"Dozlar birbirine eşit olduğundan formül doğrudan 25 / 100 oranına indirgenir.\",\"ar\":\"بما أن الجرعتين متساويتان، تختصر المعادلة مباشرة إلى حاصل قسمة 25 / 100.\",\"en\":\"Since doses are equal, the equation simplifies directly to 25 / 100.\"},{\"tier\":3,\"tr\":\"F = 25 / 100 = 0.25, yani ilacın %25'i sistemik kan dolaşımına sağlam ulaşmıştır.\",\"ar\":\"F = 25 / 100 = 0.25؛ أي أن 25% من الدواء فقط بلغ الدوران العام بنجاح.\",\"en\":\"F = 25 / 100 = 0.25, meaning 25% of the administered dose reaches systemic circulation.\"}],\"title\":{\"tr\":\"Görsel Açıklama: IV vs Oral EAA / AUC Karşılaştırması\",\"ar\":\"الشرح البصري: مقارنة المساحة تحت المنحنى (AUC) للوريد والفم\",\"en\":\"Visual Explanation: IV vs Oral AUC Comparison\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"F = 0.25 (%25); oral EAA'nın IV EAA'ya oranı sistemik dolaşıma ulaşan net kesri verir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika! Dozlar eşit olduğunda formül F = EAA_oral / EAA_IV halini alır: 25 / 100 = 0.25 (%25).\"},{\"id\":\"opt-2\",\"text\":\"F = 4.0 (%400); IV maruziyet oral maruziyetin dört katı olduğu için biyoyararlanım dörttür.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Orantıyı ters kurmuşsunuz (100 / 25 = 4). Biyoyararlanım hiçbir zaman 1.0'ı (%100) aşamaz; paydada IV EAA bulunmalıdır.\"},{\"id\":\"opt-3\",\"text\":\"F = 0.75 (%75); aradaki fark olan 75 birim sistemik dolaşıma geçen ilacı temsil eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: 0.75 kaybolan (elimine edilen) kesirdir, sistemik kana geçen kesir değil. Biyoyararlanım fark değil oran ile hesaplanır.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":3}]},{\"id\":\"pharm-mod3-les2-step5\",\"order\":5,\"stageIndex\":5,\"stage\":\"interactive_artifact\",\"type\":\"interactive_artifact\",\"prompt\":{\"tr\":\"Simülatörde oral ve IV uygulama yollarını karşılaştırın. Biyoyararlanım (F) ve absorpsiyon hız sabiti (ka) kaydırıcılarını değiştirerek oral eğrinin nasıl küçüldüğünü inceleyin.\",\"ar\":\"قارن بين مساري الإعطاء الفموي والوريدي في المحاكي. غير شريطي التوافر الحيوي (F) ومعدل الامتصاص (ka) ولاحظ انكماش المنحنى الفموي.\",\"en\":\"Compare oral and IV routes in the simulator. Adjust bioavailability (F) and absorption rate (ka) sliders to examine oral curve compression.\"},\"widgetType\":\"PkSimulator\",\"widget\":{\"type\":\"PkSimulator\",\"config\":{\"drugName\":\"Propranolol ve Nitrogliserin Modeli\",\"prompt\":\"Oral ve intravenöz eğrileri karşılaştırarak EAA ve ilk geçiş eliminasyonunun biyoyararlanıma etkisini simüle edin.\",\"defaultDoseMg\":80,\"defaultClearanceLHr\":60,\"defaultVdL\":280,\"defaultBioavailabilityF\":0.25,\"defaultKa\":1.2,\"therapeuticWindow\":[20,100],\"routes\":[\"iv_bolus\",\"oral\"],\"source\":{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":42},\"explanation\":\"İlk geçiş hepatik ekstraksiyonu oral EAA alanını küçülterek oral doz gereksinimini artırır.\"}},\"config\":{\"drugName\":\"Propranolol ve Nitrogliserin Modeli\",\"prompt\":\"Oral ve intravenöz eğrileri karşılaştırarak EAA ve ilk geçiş eliminasyonunun biyoyararlanıma etkisini simüle edin.\",\"defaultDoseMg\":80,\"defaultClearanceLHr\":60,\"defaultVdL\":280,\"defaultBioavailabilityF\":0.25,\"defaultKa\":1.2,\"therapeuticWindow\":[20,100],\"routes\":[\"iv_bolus\",\"oral\"],\"source\":{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":42},\"explanation\":\"İlk geçiş hepatik ekstraksiyonu oral EAA alanını küçülterek oral doz gereksinimini artırır.\"},\"technicalTerms\":[{\"term\":\"mutlak biyoyararlanım\",\"arContext\":\"التوافر الحيوي المطلق (absolute bioavailability F)\"}],\"hints\":[{\"tier\":1,\"tr\":\"F değerini 0.25'ten 1.0'a çıkarın; oral EAA eğrisindeki büyümeyi izleyin.\",\"ar\":\"ارفع قيمة F من 0.25 إلى 1.0؛ وراقب تضخم المساحة تحت المنحنى الفموي.\",\"en\":\"Increase F from 0.25 to 1.0; watch the oral AUC curve expand.\"},{\"tier\":2,\"tr\":\"F küçüldükçe oral eğrinin tepe noktası (Cmax) ve altındaki alan (EAA) doğru orantılı küçülür.\",\"ar\":\"كلما انخفضت F، تضاءلت ذروة Cmax والمساحة AUC بنسبة طردية مباشرة.\",\"en\":\"As F drops, the oral peak (Cmax) and total area (AUC) shrink proportionally.\"},{\"tier\":3,\"tr\":\"Karaciğer ilk geçişi F'yi düşürür; aynı plazma derişimine ulaşmak için oral doz kat kat artırılmalıdır.\",\"ar\":\"المرور الكبدي يخفض F؛ وللوصول لنفس التركيز يجب مضاعفة الجرعة الفموية أضعافاً.\",\"en\":\"Hepatic first-pass lowers F; to match target plasma levels, oral dose must be scaled up.\"}],\"title\":{\"tr\":\"İnteraktif Deney: Biyoyararlanım ve Emilim Hızı Simülatörü\",\"ar\":\"تجربة تفاعلية: محاكاة التوافر الحيوي ومعدل الامتصاص\",\"en\":\"Interactive Experiment: Bioavailability & Absorption Rate Simulator\"},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":2},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":3}]},{\"id\":\"pharm-mod3-les2-step6\",\"order\":6,\"stageIndex\":6,\"stage\":\"guided_discovery\",\"type\":\"guided_discovery\",\"prompt\":{\"tr\":\"Dilaltı nitrogliserin tablet alan anjin hastasının göğüs ağrısı 2 dakikada geçerken, aynı tablet yutulduğunda neden neredeyse sıfır etki gösterir?\",\"ar\":\"لماذا يزول ألم الذبحة الصدرية خلال دقيقتين بقرص نتروغليسرين تحت اللسان، بينما لا يعطي بلع نفس القرص أي مفعول سريري؟\",\"en\":\"Why does sublingual nitroglycerin relieve angina within 2 minutes, while swallowing the same tablet produces virtually zero effect?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Dilaltı (sublingual) uygulamanın yutmaya kıyasla dramatik üstünlük sağlamasının vasküler mekanizması nedir?\",\"ar\":\"ما الآلية الوعائية التي تمنح إعطاء الدواء تحت اللسان تفوقاً هائلاً على البلع الفموي؟\",\"en\":\"What vascular mechanism gives sublingual administration its dramatic advantage over oral swallowing?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"Dilaltı venöz drenaj doğrudan vena kava süperiora dökülerek karaciğer portal sistemini ve >%99'luk ilk geçiş yıkımını baypas eder.\",\"ar\":\"الأوردة تحت اللسان تصب مباشرة في الوريد الأجوف العلوي متجاوزة الوريد البابي واستقلاب الكبد المدمر (> 99%).\",\"en\":\"Sublingual venous drainage empties directly into superior vena cava, bypassing portal transit and >99% first-pass destruction.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Harika anatomik ve farmakolojik çıkarım! Yutulan nitrogliserin portal venle karaciğere gider ve %99'dan fazlası anında parçalanır; dilaltı yol ise doğrudan kalbe akar.\",\"ar\":\"استنتاج تشريحي وحركي رائع! النتروغليسرين المبتلع يمر بالوريد البابي فيتلف الكبد أكثر من 99% منه؛ بينما المسار تحت اللساني يذهب للقلب مباشرة.\",\"en\":\"Superb anatomical synthesis! Swallowed nitroglycerin enters portal blood where >99% is destroyed by hepatic enzymes; sublingual routes bypass the liver entirely.\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"Tükürükteki amilaz enzimleri nitrogliserini aktive eder, oysa mide pepsini ilacı tamamen inaktive eder.\",\"ar\":\"إنزيمات الأميلاز في اللعاب تنشط النتروغليسرين، بينما يبطل بيبسين المعدة مفعوله تماماً.\",\"en\":\"Salivary amylase activates nitroglycerin into its active state, whereas gastric pepsin completely inactivates it.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Nitrogliserin bir ön ilaç değildir ve tükürükle aktive olmaz. Mide enzimleri de nitrogliserini parçalamaz.\",\"ar\":\"غير صحيح: النتروغليسرين ليس دواءً أولياً ولا ينشطه اللعاب، كما أن إنزيمات المعدة لا تدمره.\",\"en\":\"Incorrect: Nitroglycerin is not a prodrug activated by saliva. Gastric enzymes also do not destroy it.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"Dilaltı mukoza nitrogliserini doğrudan koroner arterlere pompalayan özel lenfatik kanallara sahiptir.\",\"ar\":\"تحتوي مخاطية تحت اللسان على قنوات لمفاوية خاصة تضخ النتروغليسرين مباشرة إلى الشرايين التاجية.\",\"en\":\"Sublingual mucosa contains specialized lymphatic conduits that pump nitroglycerin directly into coronary arteries.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Böyle bir lenfatik bağlantı anatomik olarak mevcut değildir. İlaç sistemik venöz kana karışarak tüm vücuda yayılır.\",\"ar\":\"غير صحيح: لا يوجد تشريحياً أي مسار لمفاوي يصل تحت اللسان بالشرايين التاجية. الدواء يدخل الدوران الوريدي العام.\",\"en\":\"Incorrect: No such anatomical lymphatic shunt exists. Drug enters systemic venous circulation and distributes systemically.\"}}]},\"technicalTerms\":[{\"term\":\"karaciğer baypası\",\"arContext\":\"تجاوز الكبد (hepatic bypass)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Dilaltı venlerin kanı portal vene mi yoksa vena kava süperiora mı dökülür?\",\"ar\":\"هل تصب أوردة تحت اللسان في الوريد البابي أم في الوريد الأجوف العلوي؟\",\"en\":\"Do sublingual veins empty into the portal vein or into the superior vena cava?\"},{\"tier\":2,\"tr\":\"Vena kava süperior doğrudan sağ kalbe açılır; araya karaciğer filtresi girmez.\",\"ar\":\"الوريد الأجوف العلوي يصب مباشرة في القلب الأيمن دون المرور بفلتر الكبد.\",\"en\":\"The superior vena cava drains directly to the right heart without traversing the liver.\"},{\"tier\":3,\"tr\":\"Dilaltı yol portal sistemi baypas eder; bu sayede nitrogliserin karaciğerde parçalanmadan anında kalbe ulaşır.\",\"ar\":\"المسار تحت اللساني يتفادى الوريد البابي؛ فيصل النتروغليسرين للقلب دون أن يدمره الكبد.\",\"en\":\"The sublingual route bypasses portal flow; nitroglycerin reaches the heart intact without hepatic destruction.\"}],\"title\":{\"tr\":\"Rehberli Keşif: Sublingual Nitrogliserin ile Karaciğer Baypası\",\"ar\":\"اكتشاف موجه: تجاوز الكبد عبر النتروغليسرين تحت اللساني\",\"en\":\"Guided Discovery: Sublingual Nitroglycerin Hepatic Bypass\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"Dilaltı venöz drenaj doğrudan vena kava süperiora dökülerek karaciğer portal sistemini ve >%99'luk ilk geçiş yıkımını baypas eder.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Harika anatomik ve farmakolojik çıkarım! Yutulan nitrogliserin portal venle karaciğere gider ve %99'dan fazlası anında parçalanır; dilaltı yol ise doğrudan kalbe akar.\"},{\"id\":\"opt-2\",\"text\":\"Tükürükteki amilaz enzimleri nitrogliserini aktive eder, oysa mide pepsini ilacı tamamen inaktive eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Nitrogliserin bir ön ilaç değildir ve tükürükle aktive olmaz. Mide enzimleri de nitrogliserini parçalamaz.\"},{\"id\":\"opt-3\",\"text\":\"Dilaltı mukoza nitrogliserini doğrudan koroner arterlere pompalayan özel lenfatik kanallara sahiptir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Böyle bir lenfatik bağlantı anatomik olarak mevcut değildir. İlaç sistemik venöz kana karışarak tüm vücuda yayılır.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":3}]},{\"id\":\"pharm-mod3-les2-step7\",\"order\":7,\"stageIndex\":7,\"stage\":\"formal_explanation\",\"type\":\"formal_explanation\",\"prompt\":{\"tr\":\"Matematiksel bağıntıları inceleyin: Oral biyoyararlanım F = f x (1 - EH), hepatik ekstraksiyon EH = CL_karaciğer / Q_karaciğer ve mutlak F = (EAA_oral x Doz_IV) / (EAA_IV x Doz_oral).\",\"ar\":\"تأمل المعادلات الحركية: التوافر الحيوي F = f × (1 - EH)، والاستخلاص الكبدي EH = CL / Q، والتوافر المطلق F = (AUC_oral × Dose_IV) / (AUC_IV × Dose_oral).\",\"en\":\"Study the quantitative equations: oral bioavailability F = f * (1 - EH), extraction ratio EH = CL_liver / Q_liver, and absolute F = (AUC_oral * Dose_IV) / (AUC_IV * Dose_oral).\"},\"conceptCheck\":{\"question\":{\"tr\":\"Bağırsaktan emilimi tam olan (f = 1) ve hepatik klerensi CL = 63 L/saat olan bir ilacın karaciğer kan akımı Q = 90 L/saat ise oral biyoyararlanımı (F) kaçtır?\",\"ar\":\"دواء مكتمل الامتصاص (f = 1) وتصفيته الكبدية CL = 63 L/h مع تدفق دم كبدي Q = 90 L/h؛ كم يبلغ توافره الحيوي الفموي (F)؟\",\"en\":\"A completely absorbed drug (f = 1) has hepatic clearance CL = 63 L/hr and hepatic blood flow Q = 90 L/hr. What is its oral bioavailability (F)?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"EH = 0.70 (%70) ve F = 1 - 0.70 = 0.30 (%30).\",\"ar\":\"معدل الاستخلاص EH = 0.70 (70%) والتوافر الحيوي F = 1 - 0.70 = 0.30 (30%).\",\"en\":\"EH = 0.70 (70%) and F = 1 - 0.70 = 0.30 (30%).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz hesaplama! EH = 63 / 90 = 0.70. Karaciğer giren ilacın %70'ini temizlediğinden sistemik dolaşıma F = 1 - 0.70 = 0.30 (%30) geçer.\",\"ar\":\"حساب متقن! EH = 63 / 90 = 0.70. يستخلص الكبد 70% من الدواء فيصل للدوران الجهازي F = 1 - 0.70 = 0.30 (30%).\",\"en\":\"Flawless math! EH = 63 / 90 = 0.70. Because the liver clears 70% on first-pass, systemic bioavailability is F = 1 - 0.70 = 0.30 (30%).\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"EH = 0.30 (%30) ve F = 0.70 (%70).\",\"ar\":\"الاستخلاص EH = 0.30 (30%) والتوافر الحيوي F = 0.70 (70%).\",\"en\":\"EH = 0.30 (30%) and F = 0.70 (70%).\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Ekstraksiyon oranı ile biyoyararlanım yer değiştirmiş. EH = 63 / 90 = 0.70'dir, 0.30 değil.\",\"ar\":\"غير صحيح: عكست بين نسبة الاستخلاص والتوافر الحيوي. EH = 63 / 90 = 0.70 وليس 0.30.\",\"en\":\"Incorrect: You swapped extraction and bioavailability. EH = 63 / 90 = 0.70, not 0.30.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"EH = 1.43 (%143) ve F = 0 (%0).\",\"ar\":\"الاستخلاص EH = 1.43 (143%) والتوافر الحيوي F = 0 (0%).\",\"en\":\"EH = 1.43 (143%) and F = 0 (0%).\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Q'yu CL'ye bölmüşsünüz (90 / 63 = 1.43). Ekstraksiyon oranı 1.0'ı aşamaz; formül CL / Q'dur.\",\"ar\":\"غير صحيح: قسمت تدفق الدم على التصفية (90 / 63 = 1.43). نسبة الاستخلاص لا تتجاوز 1.0؛ المعادلة هي CL / Q.\",\"en\":\"Incorrect: You divided flow by clearance (90 / 63 = 1.43). Extraction ratio can never exceed 1.0; formula is CL / Q.\"}}]},\"technicalTerms\":[{\"term\":\"karaciğer kan akımı\",\"arContext\":\"تدفق الدم الكبدي (hepatic blood flow QH)\"}],\"hints\":[{\"tier\":1,\"tr\":\"EH = CL / Q formülüyle ekstraksiyon oranını hesaplayın.\",\"ar\":\"احسب نسبة الاستخلاص أولاً بالقانون: EH = CL / Q.\",\"en\":\"Calculate extraction ratio first: EH = CL / Q.\"},{\"tier\":2,\"tr\":\"EH = 63 / 90 = 0.70 çıkar.\",\"ar\":\"ناتج الاستخلاص: EH = 63 / 90 = 0.70.\",\"en\":\"EH = 63 / 90 = 0.70.\"},{\"tier\":3,\"tr\":\"F = 1 - EH = 1 - 0.70 = 0.30 (%30 biyoyararlanım).\",\"ar\":\"التوافر الحيوي: F = 1 - EH = 1 - 0.70 = 0.30 (أي 30%).\",\"en\":\"F = 1 - EH = 1 - 0.70 = 0.30 (30% bioavailability).\"}],\"title\":{\"tr\":\"Biçimsel Açıklama: Ekstraksiyon, Akım ve Biyoyararlanım Formülleri\",\"ar\":\"الشرح المنهجي: معادلات الاستخلاص وتدفق الدم والتوافر الحيوي\",\"en\":\"Formal Explanation: Extraction, Flow & Bioavailability Formulas\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"EH = 0.70 (%70) ve F = 1 - 0.70 = 0.30 (%30).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz hesaplama! EH = 63 / 90 = 0.70. Karaciğer giren ilacın %70'ini temizlediğinden sistemik dolaşıma F = 1 - 0.70 = 0.30 (%30) geçer.\"},{\"id\":\"opt-2\",\"text\":\"EH = 0.30 (%30) ve F = 0.70 (%70).\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Ekstraksiyon oranı ile biyoyararlanım yer değiştirmiş. EH = 63 / 90 = 0.70'dir, 0.30 değil.\"},{\"id\":\"opt-3\",\"text\":\"EH = 1.43 (%143) ve F = 0 (%0).\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Q'yu CL'ye bölmüşsünüz (90 / 63 = 1.43). Ekstraksiyon oranı 1.0'ı aşamaz; formül CL / Q'dur.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":3}]},{\"id\":\"pharm-mod3-les2-step8\",\"order\":8,\"stageIndex\":8,\"stage\":\"concept_check\",\"type\":\"concept_check\",\"prompt\":{\"tr\":\"İlerlemiş karaciğer sirozu ve portal hipertansiyonu olan hastada geniş porto-kaval şantlar gelişmiştir. Bu hastaya standart dozda oral verapamil verilirse ne olur?\",\"ar\":\"مريض بتشمع كبدي متقدم وارتفاع ضغط بابي طور تحويلات وريدية بابية أجوفية واسعة. ماذا يحدث إذا تناول فيراباميل فموياً بالجرعة المعتادة؟\",\"en\":\"A cirrhotic patient with portal hypertension develops extensive porto-caval shunts. If given standard oral verapamil, what clinical catastrophe occurs?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Karaciğer sirozundaki porto-kaval şantların verapamil gibi yüksek ekstraksiyonlu oral ilaçların farmakokinetiğine etkisi nedir?\",\"ar\":\"ما أثر التحويلات البابية الأجوفية في تشمع الكبد على حركية دواء عالي الاستخلاص مثل الفيراباميل؟\",\"en\":\"What effect do porto-caval shunts in cirrhosis have on the pharmacokinetics of high-extraction oral drugs like verapamil?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"Portal kan şantlarla karaciğeri baypas eder; ilk geçiş eliminasyonu çöker, oral biyoyararlanım katlanarak şiddetli hipotansiyon ve bradikardi yaratır.\",\"ar\":\"يتجاوز الدم الكبد عبر التحويلات فيهبط استقلاب المرور الأول ويقفز التوافر الحيوي مسبباً هبوط ضغط حاد وبطء قلب مميت.\",\"en\":\"Portal blood bypasses the liver through shunts; first-pass collapse multiplies bioavailability, precipitating profound hypotension and bradycardia.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel klinik kavrayış! Verapamilde normalde F ~%20'dir. Şantlar karaciğer ekstraksiyonunu baypas ettiğinde F %80'e fırlar (4 kat doz artışı gibi etki) ve kardiyak kollaps gelişir.\",\"ar\":\"تشخيص سريري عبقري! التوافر المعتاد للفيراباميل 20%؛ لكن تجاوزه للكبد يرفع توافره إلى 80% (أثر مضاعف 4 مرات) فينهار الجهاز القلبي الوعائي.\",\"en\":\"Superb clinical reasoning! Verapamil normally has F ~20%. Shunts bypass hepatic extraction, surging F to ~80% (a 4-fold overdose equivalent), causing cardiovascular collapse.\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"Plazma albümin düzeyi azaldığı için verapamil mezenterik venlerde kristalleşir ve sistemik dolaşıma hiç geçemez.\",\"ar\":\"بسبب هبوط الألبومين يترسب الفيراباميل في أوردة المساريقا ويعجز تماماً عن دخول الدوران الجهازي.\",\"en\":\"Decreased plasma albumin causes verapamil to precipitate in mesenteric veins, preventing systemic absorption entirely.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Sirozda ilaç kristalleşmesi olmaz. Hipoalbüminemi serbest ilaç kesrini (fu) artırır ve toksisiteyi daha da şiddetlendirir.\",\"ar\":\"غير صحيح: التليف لا يرسب الأدوية في الأوردة؛ نقص الألبومين يرفع الكسر الدوائي الحر فيزيد السمية تفاقماً.\",\"en\":\"Incorrect: Cirrhosis does not cause intravascular precipitation. Hypoalbuminemia increases free drug fraction, compounding toxicity.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"Sirozlu karaciğer aşırı miktarda sitokrom enzimi salgılayarak ilacı saniyeler içinde tamamen yok eder.\",\"ar\":\"الكبد المتليف يفرز كميات هائلة من إنزيمات السيتوكروم فيدمر الدواء خلال ثوانٍ معدودة.\",\"en\":\"The cirrhotic liver hyper-secretes cytochrome enzymes, completely metabolizing the drug within seconds.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Sirozda fonksiyonel hepatosit kitlesi ve CYP enzim kapasitesi azalır, asla artmaz.\",\"ar\":\"غير صحيح: في تشمع الكبد تتلف الخلايا الكبدية وتقل إنزيمات CYP بشدة ولا تزداد أبداً.\",\"en\":\"Incorrect: Cirrhosis destroys functional hepatocytes and depletes CYP capacity; it never induces hyper-clearance.\"}}]},\"technicalTerms\":[{\"term\":\"porto-kaval şant\",\"arContext\":\"التحويلة البابية الأجوفية (portosystemic shunt)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Portal kan karaciğere uğramadan doğrudan kalbe akarsa ilk geçiş eliminasyonuna ne olur?\",\"ar\":\"إذا عبر الدم البابي مباشرة إلى القلب دون المرور بالكبد، فماذا يحدث لاستقلاب المرور الأول؟\",\"en\":\"If portal blood flows directly to the heart without visiting the liver, what happens to first-pass elimination?\"},{\"tier\":2,\"tr\":\"İlk geçiş yıkımı ortadan kalktığında oral ilacın kana ulaşan fraksiyonu (F) ne yönde değişir?\",\"ar\":\"عند زوال تأثير المرور الأول، كيف تتغير نسبة الدواء الواصلة للدم (F)؟\",\"en\":\"When first-pass breakdown collapses, which way does systemic bioavailability (F) swing?\"},{\"tier\":3,\"tr\":\"F değeri %20'den %80'e fırlar; standart tablet sanki 4 kat yüksek doz verilmiş gibi ağır toksisite yapar.\",\"ar\":\"يقفز F من 20% إلى 80%؛ فتعمل الجرعة العادية عمل جرعة مفرطة بمقدار 4 أضعاف مسببة سمية مميتة.\",\"en\":\"F surges from 20% to ~80%; the standard pill acts like a 4-fold overdose, inducing acute toxicity.\"}],\"title\":{\"tr\":\"Kavram Kontrolü: Sirotik Porto-Kaval Şant ve Toksisite Krizi\",\"ar\":\"اختبار المفهوم: التحويلة البابية في التشمع وأزمة السمية\",\"en\":\"Concept Check: Cirrhotic Portosystemic Shunts & Toxicity Crisis\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"Portal kan şantlarla karaciğeri baypas eder; ilk geçiş eliminasyonu çöker, oral biyoyararlanım katlanarak şiddetli hipotansiyon ve bradikardi yaratır.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel klinik kavrayış! Verapamilde normalde F ~%20'dir. Şantlar karaciğer ekstraksiyonunu baypas ettiğinde F %80'e fırlar (4 kat doz artışı gibi etki) ve kardiyak kollaps gelişir.\"},{\"id\":\"opt-2\",\"text\":\"Plazma albümin düzeyi azaldığı için verapamil mezenterik venlerde kristalleşir ve sistemik dolaşıma hiç geçemez.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Sirozda ilaç kristalleşmesi olmaz. Hipoalbüminemi serbest ilaç kesrini (fu) artırır ve toksisiteyi daha da şiddetlendirir.\"},{\"id\":\"opt-3\",\"text\":\"Sirozlu karaciğer aşırı miktarda sitokrom enzimi salgılayarak ilacı saniyeler içinde tamamen yok eder.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Sirozda fonksiyonel hepatosit kitlesi ve CYP enzim kapasitesi azalır, asla artmaz.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":3}]},{\"id\":\"pharm-mod3-les2-step9\",\"order\":9,\"stageIndex\":9,\"stage\":\"application\",\"type\":\"clinical_vignette\",\"prompt\":{\"tr\":\"Hedef Css = 15 mg/L, klerens CL = 3 L/saat, doz aralığı tau = 8 saat ve oral biyoyararlanım F = 0.60 olan hastada gereken oral idame dozu (MD) nedir?\",\"ar\":\"مريض يحتاج تركيز Css = 15 mg/L، مع تصفية CL = 3 L/h، وفاصل 8 ساعات، وتوافر F = 0.60. ما هي جرعة المداومة الفموية المطلوبة؟\",\"en\":\"A patient requires Css = 15 mg/L with clearance CL = 3 L/hr, interval tau = 8 hr, and bioavailability F = 0.60. What oral maintenance dose (MD) is needed?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Oral idame dozu eşitliği MD = (CL x Css x tau) / F kullanılarak hesaplanan doğru dozaj miktarı nedir?\",\"ar\":\"باستخدام قانون جرعة المداومة الفموية MD = (CL × Css × tau) / F، ما هي الجرعة الحسابية الدقيقة؟\",\"en\":\"Using the oral maintenance dose formula MD = (CL * Css * tau) / F, what is the precise dosage?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"MD = 600 mg (her 8 saatte bir oral olarak alınmalıdır).\",\"ar\":\"جرعة المداومة = 600 mg (تؤخذ فموياً كل 8 ساعات).\",\"en\":\"MD = 600 mg (administered orally every 8 hours).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz doz hesabı! MD = (3 x 15 x 8) / 0.60 = 360 / 0.60 = 600 mg. Biyoyararlanım %60 olduğundan 600 mg oral doz kanda tam 360 mg sağlar.\",\"ar\":\"حساب سريري رائع! الجرعة = (3 × 15 × 8) / 0.60 = 360 / 0.60 = 600 ملغ. وبما أن التوافر 60%، فإن 600 ملغ فموياً توفر 360 ملغ جهازياً.\",\"en\":\"Flawless clinical calculation! MD = (3 * 15 * 8) / 0.60 = 360 / 0.60 = 600 mg. With 60% bioavailability, a 600 mg oral tablet delivers exactly 360 mg systemically.\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"MD = 216 mg (her 8 saatte bir oral olarak alınmalıdır).\",\"ar\":\"جرعة المداومة = 216 mg (تؤخذ فموياً كل 8 ساعات).\",\"en\":\"MD = 216 mg (administered orally every 8 hours).\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: F ile bölmek yerine çarpmışsınız (360 x 0.60 = 216). Biyoyararlanım azaldıkça oral doz büyütülmelidir, küçültülmemelidir!\",\"ar\":\"غير صحيح: ضربت بالمعامل F بدلاً من القسمة عليه (360 × 0.60 = 216). قلة التوافر تقتضي تكبير الجرعة الفموية وليس تصغيرها!\",\"en\":\"Incorrect: You multiplied by F instead of dividing (360 * 0.60 = 216). Lower bioavailability demands larger oral doses, not smaller!\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"MD = 360 mg (biyoyararlanım kayıpları hesaba katılmadan intravenöz eşdeğer doz).\",\"ar\":\"جرعة المداومة = 360 mg (الجرعة الوريدية المكافئة دون تعويض الفاقد الفموي).\",\"en\":\"MD = 360 mg (the IV equivalent dose without adjusting for oral bioavailability loss).\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: 360 mg intravenöz dozdur. Oral verildiğinde %40'ı ilk geçişte kaybolacağı için plazma derişimi hedefin altında (9 mg/L) kalır.\",\"ar\":\"غير صحيح: 360 ملغ هي الجرعة الوريدية؛ وإذا أعطيت فموياً سيفقد 40% منها ويهبط التركيز دون الهدف العلاجي.\",\"en\":\"Incorrect: 360 mg is the IV dose. Given orally, 40% is lost to first-pass extraction, leaving plasma levels subtherapeutic (9 mg/L).\"}}]},\"technicalTerms\":[{\"term\":\"oral idame dozu\",\"arContext\":\"جرعة المداومة الفموية (oral maintenance dose MD)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Birim zamandaki eliminasyon: CL x Css = 3 x 15 = 45 mg/saat.\",\"ar\":\"معدل الإطراح في الساعة: CL × Css = 3 × 15 = 45 mg/h.\",\"en\":\"Elimination rate per hour: CL * Css = 3 * 15 = 45 mg/hr.\"},{\"tier\":2,\"tr\":\"8 saatlik aralıkta vücudun temizlediği miktar: 45 x 8 = 360 mg.\",\"ar\":\"الكمية المزالة خلال 8 ساعات: 45 × 8 = 360 mg.\",\"en\":\"Drug quantity cleared over 8 hours: 45 * 8 = 360 mg.\"},{\"tier\":3,\"tr\":\"MD = 360 / 0.60 = 600 mg; oral tablet 600 mg olarak reçete edilmelidir.\",\"ar\":\"جرعة الفم = 360 / 0.60 = 600 mg لتعويض فاقد الامتصاص والكبد.\",\"en\":\"MD = 360 / 0.60 = 600 mg; the oral prescription must be 600 mg to compensate for first-pass loss.\"}],\"title\":{\"tr\":\"Klinik Uygulama: Oral İdame Dozu (MD) Reçeteleme\",\"ar\":\"تطبيق سريري: حساب جرعة المداومة الفموية (MD)\",\"en\":\"Clinical Vignette: Prescribing the Oral Maintenance Dose (MD)\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"MD = 600 mg (her 8 saatte bir oral olarak alınmalıdır).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz doz hesabı! MD = (3 x 15 x 8) / 0.60 = 360 / 0.60 = 600 mg. Biyoyararlanım %60 olduğundan 600 mg oral doz kanda tam 360 mg sağlar.\"},{\"id\":\"opt-2\",\"text\":\"MD = 216 mg (her 8 saatte bir oral olarak alınmalıdır).\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: F ile bölmek yerine çarpmışsınız (360 x 0.60 = 216). Biyoyararlanım azaldıkça oral doz büyütülmelidir, küçültülmemelidir!\"},{\"id\":\"opt-3\",\"text\":\"MD = 360 mg (biyoyararlanım kayıpları hesaba katılmadan intravenöz eşdeğer doz).\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: 360 mg intravenöz dozdur. Oral verildiğinde %40'ı ilk geçişte kaybolacağı için plazma derişimi hedefin altında (9 mg/L) kalır.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":3}]},{\"id\":\"pharm-mod3-les2-step10\",\"order\":10,\"stageIndex\":10,\"stage\":\"retrieval\",\"type\":\"retrieval\",\"prompt\":{\"tr\":\"Aşağıdaki uygulama yollarından hangisi karaciğerin ilk geçiş portal metabolizmasını doğrudan ve tamamen baypas eder?\",\"ar\":\"أي من طرق إعطاء الدواء التالية تتفادى استقلاب المرور الأول الكبدي البابي بشكل كامل ومباشر؟\",\"en\":\"Which of the following routes directly and completely bypasses the liver's first-pass portal metabolism?\"},\"conceptCheck\":{\"question\":{\"tr\":\"İlk geçiş hepatik ekstraksiyonunu baypas eden ve doğrudan sistemik venöz kana karışan yol hangisidir?\",\"ar\":\"ما المسار الذي يتفادى الاستخلاص الكبدي بالمرور الأول ويصب مباشرة في الوريد الأجوف؟\",\"en\":\"Which route bypasses first-pass hepatic extraction and enters systemic venous blood directly?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"Sublingual (dilaltı) ve intravenöz yollar (doğrudan vena kava dolaşımına katılır).\",\"ar\":\"طريق تحت اللسان والحقن الوريدي (يصبان مباشرة في الدوران الأجوف الجهازي).\",\"en\":\"Sublingual and intravenous routes (drain directly into vena cava circulation).\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Doğru! Dilaltı mukoza ve sistemik venler doğrudan vena kava sistemine akar; portal vene ve karaciğere uğramaz.\",\"ar\":\"صحيح! أوردة تحت اللسان والحقن الوريدي تفرغ في الوريد الأجوف مباشرة متفادية الوريد البابي والكبد.\",\"en\":\"Correct! Sublingual vessels and peripheral veins drain directly into the caval system, completely avoiding portal transit.\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"Oral tablet ve oral süspansiyon yolları (mide ve duodenum emilimi).\",\"ar\":\"الحبوب الفموية والمعلقات الفموية (الامتصاص المعدي والإثني عشري).\",\"en\":\"Oral tablets and oral suspensions (gastric and duodenal absorption).\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Mide ve ince bağırsaktan emilen tüm kan mezenterik venler üzerinden portal vene ve karaciğere dökülür.\",\"ar\":\"غير صحيح: كل الدم الوريدي الممتص من المعدة والأمعاء يصب حتماً في الوريد البابي نحو الكبد.\",\"en\":\"Incorrect: All venous blood from stomach and intestines drains via mesenteric veins into the portal vein.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"Jejunuma yerleştirilen enteral beslenme tüpü uygulaması.\",\"ar\":\"أنبوب التغذية المعوي المستقر في الصائم.\",\"en\":\"Enteral feeding tube infusion placed into the upper jejunum.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Jejunumdan emilim süperior mezenterik vene ve oradan portal vene gider; ilk geçiş ekstraksiyonu aynen devam eder.\",\"ar\":\"غير صحيح: امتصاص الصائم يمر بالوريد المساريقي العلوي فالوريد البابي؛ وتأثير المرور الأول يبقى قائماً.\",\"en\":\"Incorrect: Jejunal absorption drains directly into the superior mesenteric and portal veins, undergoing full first-pass transit.\"}}]},\"technicalTerms\":[{\"term\":\"sistemik venöz drenaj\",\"arContext\":\"التصريف الوريدي الجهازي (systemic venous drainage)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Gastrointestinal kanalın (mide, bağırsak) venleri nereye akar? Portal vene.\",\"ar\":\"أين تفرغ أوردة القناة الهضمية (المعدة والأمعاء) دمها؟ في الوريد البابي.\",\"en\":\"Where do veins from the GI tract (stomach, intestines) drain? Into the portal vein.\"},{\"tier\":2,\"tr\":\"Ağız mukozası (dilaltı) ve kol venleri portal sisteme dahil midir?\",\"ar\":\"هل تنتمي أوردة مخاطية الفم (تحت اللسان) وأوردة الذراع إلى الجهاز البابي؟\",\"en\":\"Do oral mucosal veins (sublingual) and arm veins belong to the portal system?\"},{\"tier\":3,\"tr\":\"Dilaltı venler superior vena kavaya dökülür; bu sayede portal dolaşım ve ilk geçiş tamamen baypas edilir.\",\"ar\":\"تصب الأوردة تحت اللسانية في الوريد الأجوف العلوي متجاوزة الكبد والوريد البابي كلياً.\",\"en\":\"Sublingual veins empty into the superior vena cava, completely bypassing portal flow and first-pass loss.\"}],\"title\":{\"tr\":\"Hafıza Yoklama: Portal İlk Geçişi Baypas Eden Yollar\",\"ar\":\"استرجاع معرفي: الطرق التي تتفادى المرور البابي الأول\",\"en\":\"Retrieval: Routes Bypassing First-Pass Portal Clearance\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"Sublingual (dilaltı) ve intravenöz yollar (doğrudan vena kava dolaşımına katılır).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Doğru! Dilaltı mukoza ve sistemik venler doğrudan vena kava sistemine akar; portal vene ve karaciğere uğramaz.\"},{\"id\":\"opt-2\",\"text\":\"Oral tablet ve oral süspansiyon yolları (mide ve duodenum emilimi).\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Mide ve ince bağırsaktan emilen tüm kan mezenterik venler üzerinden portal vene ve karaciğere dökülür.\"},{\"id\":\"opt-3\",\"text\":\"Jejunuma yerleştirilen enteral beslenme tüpü uygulaması.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Jejunumdan emilim süperior mezenterik vene ve oradan portal vene gider; ilk geçiş ekstraksiyonu aynen devam eder.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":3}]},{\"id\":\"pharm-mod3-les2-step11\",\"order\":11,\"stageIndex\":11,\"stage\":\"connection\",\"type\":\"connection\",\"prompt\":{\"tr\":\"İlk geçiş hepatik metabolizması farmakolojide nasıl hem bir avantaja (ön ilaç aktivasyonu) hem de ölümcül bir tehlikeye (hepatotoksik metabolitler) dönüşebilir?\",\"ar\":\"كيف يتحول استقلاب المرور الأول الكبدي إلى ميزة علاجية (تنشيط الأدوية الأولية) أو خطر مميت (تولد مستقلبات سامة)؟\",\"en\":\"How can hepatic first-pass metabolism represent both a therapeutic triumph (prodrug bioactivation) and a lethal danger (reactive toxic metabolites)?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Aşağıdaki ilaç eşleştirmelerinden hangisi karaciğer ilk geçiş metabolizmasının zıt sonuçlarını (ön ilaç aktivasyonu vs toksik ara ürün) tam yansıtır?\",\"ar\":\"أي من الثنائيات الدوائية التالية تعكس بوضوح النقيضين للاستقلاب الكبدي (تنشيط دواء أولي مقابل سمية كبدية)؟\",\"en\":\"Which drug pair accurately exemplifies the dual nature of first-pass metabolism: prodrug bioactivation vs toxic metabolite generation?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"Enalapril karaciğer esterazlarıyla aktif enalaprilata dönüşürken; parasetamol aşırı dozunda ilk geçişte reaktif toksik NAPQI üretilir.\",\"ar\":\"إينالابريل يتحول بإسترازات الكبد إلى إينالابريلات الفعال؛ بينما ينتج الباراسيتامول في الجرعات العالية وسيط NAPQI السام.\",\"en\":\"Enalapril is bioactivated by hepatic esterases to active enalaprilat, whereas acetaminophen overdose generates reactive toxic NAPQI.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Mükemmel farmakolojik bağlantı! Enalapril oral emilimi iyi olan inaktif bir esterdir ve karaciğerde aktif forma çevrilir. Parasetamol ise CYP2E1 ile reaktif hepatotoksik NAPQI'ye oksitlenir.\",\"ar\":\"ربط دوائي بديع! إينالابريل دواء أولي ينشطه الكبد لاستراته؛ بينما الباراسيتامول يتحول بواسطة CYP2E1 إلى NAPQI الذي يخرب خلايا الكبد.\",\"en\":\"Superb pharmacological connection! Enalapril is an inactive ethyl ester bioactivated by hepatic cleavage. Acetaminophen undergoes CYP2E1 oxidation to cytotoxic NAPQI.\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"Penisilin G karaciğerde sefalosporine dönüşürken; lityum karaciğerde metillenerek nörotoksik hale gelir.\",\"ar\":\"بنسلين G يتحول في الكبد إلى سيفالوسبورين؛ والليثيوم يمتخل في الكبد ليصبح ساماً للأعصاب.\",\"en\":\"Penicillin G is transformed into cephalosporin by the liver, whereas lithium is methylated into a neurotoxin.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Penisilin sefalosporine dönüşemez (farklı kimyasal sınıflardır). Lityum ise elementtir ve karaciğerde hiç metabolize edilmez; böbrekten atılır.\",\"ar\":\"غير صحيح: البنسلين لا يتحول لسيفالوسبورين. والليثيوم عنصر كيميائي لا يستقلب بالكبد إطلاقاً بل يطرح كلوياً.\",\"en\":\"Incorrect: Penicillin cannot convert to cephalosporins. Lithium is an elemental ion eliminated entirely unchanged by the kidneys.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"Gentamisin karaciğerde aktive olarak ribozoma bağlanırken; digoksin karaciğerde glikoza parçalanır.\",\"ar\":\"جنتاميسين يتنشط كبدياً ليرتبط بالريبوسوم؛ والديجوكسين يتحلل في الكبد إلى جلوكوز.\",\"en\":\"Gentamicin is activated by liver enzymes to bind ribosomes, whereas digoxin is broken down into glucose.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Gentamisin ön ilaç değildir ve karaciğerde metabolize olmaz (böbrekten değişmeden atılır). Digoksin glikoza dönüşmez.\",\"ar\":\"غير صحيح: الجنتاميسين يطرح كلوياً دون استقلاب. والديجوكسين لا يتحول إلى سكر جلوكوز.\",\"en\":\"Incorrect: Gentamicin is not a prodrug and is eliminated unchanged by renal filtration. Digoxin does not convert to glucose.\"}}]},\"technicalTerms\":[{\"term\":\"ön ilaç biyoaktivasyonu\",\"arContext\":\"التنشيط الحيوي للدواء الأولي (prodrug bioactivation)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Oral emilimi artırmak için tasarlanan ester ön ilaçları (örn. ACE inhibitörleri) düşünün.\",\"ar\":\"تذكر الأدوية الأولية الإسترية المصممة لتحسين الامتصاص كأدوية الضغط (مثبطات ACE).\",\"en\":\"Consider ester prodrugs designed to enhance oral absorption, such as ACE inhibitors.\"},{\"tier\":2,\"tr\":\"Karaciğer CYP enzimlerinin aşırı dozda glukuronidasyon kapasitesini aşıp toksik metabolit ürettiği analjezik hangisidir?\",\"ar\":\"ما المسكن الذي يشبع مسارات الاقتران عند الجرعة الزائدة لينتج وسيطاً كبدياً ساماً عبر CYP؟\",\"en\":\"Which analgesic saturates glucuronidation in overdose, shunting into CYP oxidation to form a toxic intermediate?\"},{\"tier\":3,\"tr\":\"Enalapril karaciğerde enalaprilata aktive olur; parasetamol aşırı dozda toksik NAPQI'ye dönüşür.\",\"ar\":\"إينالابريل يتنشط إلى إينالابريلات؛ والباراسيتامول في الجرعات العالية ينتج وسيط NAPQI السام للكبد.\",\"en\":\"Enalapril is bioactivated to enalaprilat; acetaminophen overdose generates hepatotoxic NAPQI.\"}],\"title\":{\"tr\":\"Bütünsel Bağlantı: Ön İlaç Biyoaktivasyonu vs Toksik Metabolitler\",\"ar\":\"الربط الشامل: تنشيط الأدوية الأولية مقابل تولد المستقلبات السامة\",\"en\":\"Holistic Connection: Prodrug Activation vs Toxic Metabolites\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"Enalapril karaciğer esterazlarıyla aktif enalaprilata dönüşürken; parasetamol aşırı dozunda ilk geçişte reaktif toksik NAPQI üretilir.\",\"isCorrect\":true,\"misconceptionFeedback\":\"Mükemmel farmakolojik bağlantı! Enalapril oral emilimi iyi olan inaktif bir esterdir ve karaciğerde aktif forma çevrilir. Parasetamol ise CYP2E1 ile reaktif hepatotoksik NAPQI'ye oksitlenir.\"},{\"id\":\"opt-2\",\"text\":\"Penisilin G karaciğerde sefalosporine dönüşürken; lityum karaciğerde metillenerek nörotoksik hale gelir.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Penisilin sefalosporine dönüşemez (farklı kimyasal sınıflardır). Lityum ise elementtir ve karaciğerde hiç metabolize edilmez; böbrekten atılır.\"},{\"id\":\"opt-3\",\"text\":\"Gentamisin karaciğerde aktive olarak ribozoma bağlanırken; digoksin karaciğerde glikoza parçalanır.\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Gentamisin ön ilaç değildir ve karaciğerde metabolize olmaz (böbrekten değişmeden atılır). Digoksin glikoza dönüşmez.\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":42},{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":44}]},{\"id\":\"pharm-mod3-les2-step12\",\"order\":12,\"stageIndex\":12,\"stage\":\"mastery_check\",\"type\":\"mastery_check\",\"prompt\":{\"tr\":\"Antiviral AV-12 için 100 mg IV doz EAA=50, 400 mg oral doz EAA=60 mg·h/L veriyor (f=1.0). F, EH ve Css=2.0 mg/L (tau=12 saat) için oral idame dozunu hesaplayın.\",\"ar\":\"للدواء AV-12: جرعة 100 mg وريدياً أعطت AUC=50، و400 mg فموياً أعطت AUC=60 mg·h/L مع f=1.0. احسب F و EH وجرعة المداومة لـ Css=2.0 mg/L كل 12 ساعة.\",\"en\":\"For AV-12, 100 mg IV yields AUC=50 and 400 mg oral yields AUC=60 mg·hr/L (f=1.0). Calculate F, EH, and oral maintenance dose for Css=2.0 mg/L (tau=12 hr).\"},\"conceptCheck\":{\"question\":{\"tr\":\"AV-12'nin mutlak biyoyararlanımı (F), hepatik ekstraksiyonu (EH), klerensi (CL) ve gereken oral idame dozu (MD) hangi seçenekte eksiksiz doğrudur?\",\"ar\":\"ما هي قيم التوافر الحيوي (F)، والاستخلاص الكبدي (EH)، والتصفية (CL)، وجرعة المداومة الفموية (MD) الصحيحة للدواء AV-12؟\",\"en\":\"Which option completely and correctly states AV-12's absolute bioavailability (F), extraction ratio (EH), clearance (CL), and oral maintenance dose (MD)?\"},\"options\":[{\"id\":\"opt-1\",\"text\":{\"tr\":\"F = 0.30 (%30), EH = 0.70, CL = 2.0 L/saat; oral idame dozu MD = 160 mg (her 12 saatte bir).\",\"ar\":\"F = 0.30 (30%)، و EH = 0.70، والتصفية CL = 2.0 L/h؛ وجرعة المداومة الفموية MD = 160 mg كل 12 ساعة.\",\"en\":\"F = 0.30 (30%), EH = 0.70, CL = 2.0 L/hr; oral maintenance dose MD = 160 mg every 12 hours.\"},\"isCorrect\":true,\"misconceptionFeedback\":{\"tr\":\"Kusursuz ustalık! 1) F = (60 x 100) / (50 x 400) = 6000 / 20000 = 0.30 (%30). 2) f = 1 olduğundan EH = 1 - F = 0.70. 3) CL = Doz_IV / EAA_IV = 100 / 50 = 2.0 L/saat. 4) Oral MD = (CL x Css x tau) / F = (2.0 x 2.0 x 12) / 0.30 = 48 / 0.30 = 160 mg.\",\"ar\":\"إتقان دوائي وحركي مذهل! 1) F = (60 × 100) / (50 × 400) = 0.30. 2) الاستخلاص EH = 1 - 0.30 = 0.70. 3) التصفية = 100 / 50 = 2.0 L/h. 4) الجرعة الفموية = (2.0 × 2.0 × 12) / 0.30 = 48 / 0.30 = 160 ملغ.\",\"en\":\"Complete pharmacokinetic mastery! 1) F = (60 * 100) / (50 * 400) = 0.30. 2) With f = 1, EH = 1 - F = 0.70. 3) CL = Dose_IV / AUC_IV = 100 / 50 = 2.0 L/hr. 4) Oral MD = (CL * Css * tau) / F = (2.0 * 2.0 * 12) / 0.30 = 48 / 0.30 = 160 mg.\"}},{\"id\":\"opt-2\",\"text\":{\"tr\":\"F = 0.83 (%83), EH = 0.17, CL = 0.5 L/saat; oral idame dozu MD = 40 mg (her 12 saatte bir).\",\"ar\":\"F = 0.83 (83%)، و EH = 0.17، والتصفية CL = 0.5 L/h؛ وجرعة المداومة الفموية MD = 40 mg كل 12 ساعة.\",\"en\":\"F = 0.83 (83%), EH = 0.17, CL = 0.5 L/hr; oral maintenance dose MD = 40 mg every 12 hours.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: Doz düzeltmesini yapmadan doğrudan EAA oranını almışsınız veya dozu ters çarpmışsınız. Mutlak F hesabında dozlar çapraz çarpılmalıdır.\",\"ar\":\"غير صحيح: قمت بقسمة المساحات دون تعديل الجرعات بشكل صحيح. حساب التوافر المطلق يتطلب ضرباً تقاطعياً مع الجرعات.\",\"en\":\"Incorrect: You calculated AUC ratio without proper dose normalization. Absolute F requires cross-multiplying normalized doses.\"}},{\"id\":\"opt-3\",\"text\":{\"tr\":\"F = 0.30 (%30), EH = 0.70, CL = 2.0 L/saat; oral idame dozu MD = 14.4 mg (her 12 saatte bir).\",\"ar\":\"F = 0.30 (30%)، و EH = 0.70، والتصفية CL = 2.0 L/h؛ وجرعة المداومة الفموية MD = 14.4 mg كل 12 ساعة.\",\"en\":\"F = 0.30 (30%), EH = 0.70, CL = 2.0 L/hr; oral maintenance dose MD = 14.4 mg every 12 hours.\"},\"isCorrect\":false,\"misconceptionFeedback\":{\"tr\":\"Yanlış: İdame dozu hesaplarken 48 mg'ı F'ye bölmek yerine F ile çarpmışsınız (48 x 0.30 = 14.4). Biyoyararlanım azaldıkça oral doz büyütülmelidir!\",\"ar\":\"غير صحيح: قمت بضرب 48 في 0.30 بدلاً من القسمة عليها (48 × 0.30 = 14.4). انخفاض التوافر يستلزم تكبير الجرعة الفموية!\",\"en\":\"Incorrect: You multiplied 48 mg by F instead of dividing by F (48 * 0.30 = 14.4). Incomplete bioavailability requires scaling up oral doses!\"}}]},\"technicalTerms\":[{\"term\":\"klinik rejim optimizasyonu\",\"arContext\":\"تحسين الجرعات السريرية (clinical dosing optimization)\"}],\"hints\":[{\"tier\":1,\"tr\":\"F = (EAA_oral x Doz_IV) / (EAA_IV x Doz_oral) formülünü uygulayın: (60 x 100) / (50 x 400).\",\"ar\":\"طبق قانون التوافر المطلق: F = (60 × 100) / (50 × 400).\",\"en\":\"Apply the absolute bioavailability formula: F = (60 * 100) / (50 * 400).\"},{\"tier\":2,\"tr\":\"F = 0.30 bulunur. f = 1 olduğundan EH = 1 - 0.30 = 0.70'dir. CL = 100 / 50 = 2 L/saattir.\",\"ar\":\"تجد F = 0.30، والاستخلاص EH = 1 - 0.30 = 0.70، والتصفية CL = 100 / 50 = 2 L/h.\",\"en\":\"F = 0.30 is obtained. With f = 1, EH = 1 - 0.30 = 0.70. CL = 100 / 50 = 2 L/hr.\"},{\"tier\":3,\"tr\":\"Oral MD = (CL x Css x tau) / F = (2 x 2 x 12) / 0.30 = 48 / 0.30 = 160 mg'dır.\",\"ar\":\"الجرعة الفموية: MD = (2 × 2 × 12) / 0.30 = 48 / 0.30 = 160 mg كل 12 ساعة.\",\"en\":\"Oral MD = (CL * Css * tau) / F = (2 * 2 * 12) / 0.30 = 48 / 0.30 = 160 mg every 12 hours.\"}],\"title\":{\"tr\":\"Ustalık Sınavı: Antiviral AV-12 PK ve Oral Rejim Optimizasyonu\",\"ar\":\"اختبار الإتقان: التحليل الحركي للدواء AV-12 وتحسين الجرعة الفموية\",\"en\":\"Mastery Check: Antiviral AV-12 PK & Oral Regimen Optimization\"},\"config\":{\"options\":[{\"id\":\"opt-1\",\"text\":\"F = 0.30 (%30), EH = 0.70, CL = 2.0 L/saat; oral idame dozu MD = 160 mg (her 12 saatte bir).\",\"isCorrect\":true,\"misconceptionFeedback\":\"Kusursuz ustalık! 1) F = (60 x 100) / (50 x 400) = 6000 / 20000 = 0.30 (%30). 2) f = 1 olduğundan EH = 1 - F = 0.70. 3) CL = Doz_IV / EAA_IV = 100 / 50 = 2.0 L/saat. 4) Oral MD = (CL x Css x tau) / F = (2.0 x 2.0 x 12) / 0.30 = 48 / 0.30 = 160 mg.\"},{\"id\":\"opt-2\",\"text\":\"F = 0.83 (%83), EH = 0.17, CL = 0.5 L/saat; oral idame dozu MD = 40 mg (her 12 saatte bir).\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: Doz düzeltmesini yapmadan doğrudan EAA oranını almışsınız veya dozu ters çarpmışsınız. Mutlak F hesabında dozlar çapraz çarpılmalıdır.\"},{\"id\":\"opt-3\",\"text\":\"F = 0.30 (%30), EH = 0.70, CL = 2.0 L/saat; oral idame dozu MD = 14.4 mg (her 12 saatte bir).\",\"isCorrect\":false,\"misconceptionFeedback\":\"Yanlış: İdame dozu hesaplarken 48 mg'ı F'ye bölmek yerine F ile çarpmışsınız (48 x 0.30 = 14.4). Biyoyararlanım azaldıkça oral doz büyütülmelidir!\"}]},\"sources\":[{\"file\":\"İlaç metabolizması-2026.pdf\",\"page\":3}]}]},\"pharm-mod4-les1\":{\"id\":\"pharm-mod4-les1\",\"courseId\":\"pharmacology\",\"moduleId\":\"ph-mod-04\",\"title\":{\"tr\":\"Otonom Sinir Sistemi: Adrenerjik Nörotransmisyon ve Reseptör Alt Tipleri\",\"ar\":\"الجهاز العصبي الذاتي: النقل العصبي الأدريناليني والأنماط الفرعية للمستقبلات\",\"en\":\"Autonomic Nervous System: Adrenergic Neurotransmission & Receptor Subtypes\"},\"order\":1,\"access\":\"free\",\"objective\":{\"tr\":\"Adrenerjik alfa-1, alfa-2, beta-1 ve beta-2 reseptörlerinin sinyal iletim yolaklarını, Dale vazomotor tersinme fenomenini ve feokromositoma kriz yönetimini yönetmek.\",\"ar\":\"إتقان مسارات تأشير المستقبلات الأدرينالينية alpha-1 و alpha-2 و beta-1 و beta-2، وظاهرة انعكاس ديل الوعائي، والتدبير العلاجي لأزمة ورم القواتم.\",\"en\":\"Master adrenergic alpha-1, alpha-2, beta-1, and beta-2 receptor signaling cascades, Dale's vasomotor reversal phenomenon, and pheochromocytoma crisis management.\"},\"misconceptions\":[{\"tr\":\"Tüm sempatik reseptörlerin aynı hücresel sinyali (cAMP artışı) ürettiği yanılgısı (alfa-1 Gq ile IP3/DAG/Ca2+ üretirken, alfa-2 Gi ile cAMP'yi düşürür, beta reseptörleri Gs ile cAMP'yi artırır).\",\"ar\":\"الظن الخاطئ بأن جميع المستقبلات الودية تنتج نفس الإشارة الخلوية (alpha-1 تعمل عبر Gq و IP3/Ca2+، و alpha-2 عبر Gi لخفض cAMP، بينما مستقبلات بيتا تعمل عبر Gs لرفع cAMP).\",\"en\":\"The misconception that all adrenergic receptors elicit uniform cellular signals (alpha-1 couples to Gq/IP3/Ca2+, alpha-2 couples to Gi/lowering cAMP, and beta receptors couple to Gs/cAMP).\"},{\"tr\":\"Feokromositoma krizinde taşikardiyi önlemek için önce beta-bloker verilmesi gerektiği yanılgısı (önce beta-bloker verilirse vazodilatör beta-2 bloke olur, devasa katekolamin yükü alfa-1'i tek başına uyararak ölümcül hipertansif krize yol açar).\",\"ar\":\"الاعتقاد الخاطئ بإمكانية إعطاء حاصرات بيتا قبل حاصرات ألفا في ورم القواتم (حصر بيتا أولاً يلغي التوسع الوعائي عبر beta-2، فيتفرد التحفيز الألفاوي مسبباً نوبة فرط ضغط قاتلة).\",\"en\":\"The fatal belief that beta-blockers should precede alpha-blockers in pheochromocytoma (blocking beta-2 first leaves massive alpha-1 vasoconstriction unopposed, precipitating lethal hypertensive crisis).\"}],\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":14}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Katzung's Basic & Clinical Pharmacology\",\"edition\":\"15th ed.\",\"topic\":\"Adrenoceptor Agonists & Sympathomimetic Drugs\",\"chapter\":\"Chapter 9: Adrenoceptor Agonists & Sympathomimetic Drugs\",\"page\":\"pp. 130-148\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Goodman & Gilman's The Pharmacological Basis of Therapeutics\",\"edition\":\"14th ed.\",\"topic\":\"Adrenergic Agonists and Antagonists\",\"chapter\":\"Chapter 8: Adrenergic Agonists and Antagonists\",\"page\":\"pp. 160-185\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"pharm-mod4-les1-card1\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Alfa-1 Reseptör Sinyali ve Damar Yanıtı\",\"prompt\":\"Alfa-1 adrenerjik reseptör hangi G-proteini ile kenetlidir ve damar düz kasında hangi ikinci ulak yolağını aktive eder?\",\"answer\":\"Gq proteini ile kenetlidir; Fosfolipaz C (PLC) aktivasyonu ile IP3 ve DAG üreterek hücre içi serbest Ca2+ derişimini artırır ve vazokonstriksiyon yapar.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod4-les1-card2\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Dale Vazomotor Adrenalin Tersinmesi\",\"prompt\":\"Alfa-bloker (fentolamin) verildikten sonra adrenalin enjekte edildiğinde kan basıncı neden yükselmek yerine düşer?\",\"answer\":\"Fentolamin presör alfa-1 vazokonstriksiyonunu felç eder; adrenalinin damar düz kasındaki beta-2 reseptörlerini uyarması vazodilatasyona ve tansiyon düşüşüne yol açar.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod4-les1-card3\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Presinaptik Alfa-2 Otoreseptörü\",\"prompt\":\"Presinaptik adrenerjik sinir ucundaki alfa-2 otoreseptörünün fizyolojik görevi ve kenetli olduğu G-proteini nedir?\",\"answer\":\"Gi proteini ile kenetlidir; adenilat siklazı inhibe ederek ve kalsiyum girişini kapatarak veziküler noradrenalin salıverilmesini otoregülatuvar olarak durdurur.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod4-les1-card4\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Feokromositomada Blokaj Sırası Kuralı\",\"prompt\":\"Feokromositomalı bir hastada neden ASLA alfa-blokerden önce tek başına beta-bloker verilmez?\",\"answer\":\"Beta-2 vazodilatasyonu bloke edildiğinde, dolaşımdaki devasa katekolaminler damar alfa-1 reseptörlerini engelsiz uyarır ve ölümcül hipertansif krize neden olur.\",\"box\":1,\"intervalDays\":1}],\"steps\":[{\"id\":\"pharm-mod4-les1-step1\",\"order\":1,\"stageIndex\":1,\"stage\":\"hook\",\"type\":\"predict_reveal\",\"title\":{\"tr\":\"Klinik Paradoks: Dale'in Vazomotor Epinefrin Tersinmesi\",\"ar\":\"المفارقة السريرية: انعكاس ديل الحركي الوعائي للإبينفرين\",\"en\":\"Clinical Paradox: Dale's Vasomotor Epinephrine Reversal\"},\"predictThenReveal\":true,\"prompt\":{\"tr\":\"Epinefrin normalde tansiyonu yükseltir. Ancak alfa-bloker fentolamin ile önceden tedavi edilen bir hayvanda, epinefrin neden kan basıncında ani bir DÜŞÜŞE yol açar?\",\"ar\":\"يرفع الإبينفرين عادة ضغط الدم. ولكن في حيوان عولج مسبقاً بحاصر ألفا فينتولامين، لماذا يسبب الإبينفرين هبوطاً حاداً في ضغط الدم؟\",\"en\":\"Epinephrine normally elevates blood pressure. But in an animal pretreated with the alpha-blocker phentolamine, why does epinephrine trigger a precipitous blood pressure DROP?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Epinefrin fentolamin varlığında neden vazodilatasyon ve hipotansiyon yapar?\",\"ar\":\"لماذا يحدث الإبينفرين توسعاً وعائياً وهبوطاً في الضغط بوجود الفينتولامين؟\",\"en\":\"Why does epinephrine trigger vasodilation and hypotension in the presence of phentolamine?\"},\"options\":[{\"id\":\"opt-l7-s1-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Alfa-1 vazokonstriksiyonu bloke edilir; iskelet kası damarlarındaki engellenmemiş beta-2 aktivasyonu belirgin vazodilatasyon ve hipotansiyon oluşturur.\",\"ar\":\"تُحصر مستقبلات ألفا-1 المضيقة للأوعية، فيؤدي تفعيل بيتا-2 دون معارضة في الأوعية العضلية إلى توسع وعائي شديد وهبوط ضغط.\",\"en\":\"Alpha-1 vasoconstriction is blocked; unopposed beta-2 receptor activation in skeletal muscle vascular beds produces pronounced vasodilation and hypotension.\"},\"feedback\":{\"tr\":\"Doğru. Dale vazomotor tersinmesi, alfa-blokajın beta-2 vazodilatasyonunu açığa çıkarmasıyla oluşur.\",\"ar\":\"صحيح. يحدث انعكاس ديل الوعائي لأن حصر ألفا يكشف التوسع الوعائي المتواسط بـ بيتا-2.\",\"en\":\"Correct. Dale's vasomotor reversal occurs because alpha-blockade unmasks potent beta-2 mediated arteriolar dilation.\"}},{\"id\":\"opt-l7-s1-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Fentolamin vagal refleks yaylarını uyararak epinefrinin kardiyak etkisini şiddetli bradikardiye ve vasküler kollapsa dönüştürür.\",\"ar\":\"يحفز الفينتولامين المنعكس المبهمي، محولاً تأثير الإبينفرين القلبي إلى تباطؤ نبض شديد وانهيار وعائي.\",\"en\":\"Phentolamine stimulates vagal reflex arcs, converting epinephrine's cardiac action into profound bradycardia and vascular collapse.\"},\"feedback\":{\"tr\":\"Yanlış. Fentolamin vagal bradikardi yapmaz; kardiyak beta-1 uyarımı devam eder ancak toplam periferik direnç beta-2 ile çöker.\",\"ar\":\"غير صحيح. لا يسبب الفينتولامين بطء قلب مبهمياً؛ يبقى تنبيه بيتا-1 القلبي قائماً بينما تنهار المقاومة بـ بيتا-2.\",\"en\":\"Incorrect. Phentolamine does not cause vagal bradycardia; cardiac beta-1 stimulation remains intact, but peripheral resistance plummets via beta-2 dilation.\"}},{\"id\":\"opt-l7-s1-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Fentolamin beta-1 reseptörlerine geçerek kardiyak debiyi yarışmalı şekilde bloke eder ve sistolik arteriyel basıncı sıfırlar.\",\"ar\":\"يعبر الفينتولامين لمستقبلات بيتا-1 ويحصر النتاج القلبي تنافسياً، ملغياً الضغط الشرياني الانقباضي.\",\"en\":\"Phentolamine crosses to beta-1 receptors and competitively blocks cardiac output, eliminating systolic arterial pressure.\"},\"feedback\":{\"tr\":\"Yanlış. Fentolamin alfa reseptörlerine selektiftir; kardiyak beta-1 reseptörlerine ihmal edilebilir afinite gösterir.\",\"ar\":\"غير صحيح. الفينتولامين انتقائي لمستقبلات ألفا وله ألفة ضئيلة جداً تجاه مستقبلات بيتا-1 القلبية.\",\"en\":\"Incorrect. Phentolamine is selective for alpha adrenoceptors and has negligible affinity for cardiac beta-1 receptors.\"}}]},\"technicalTerms\":[{\"term\":\"Dale Vazomotor Tersinmesi\",\"arContext\":\"انعكاس ديل الوعائي (Dale's Vasomotor Reversal)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Epinefrinin aynı anda bağlandığı iki zıt vasküler adrenerjik reseptör alt tipini düşünün.\",\"ar\":\"فكر في النمطين الفرعيين المتعاكسين لمستقبلات الأوعية اللذين يرتبط بهما الإبينفرين في وقت واحد.\",\"en\":\"Think about the two opposing vascular adrenoceptor subtypes epinephrine binds simultaneously.\"},{\"tier\":2,\"tr\":\"Alfa-1 arteriyol büzülmesini, beta-2 ise arteriyol gevşemesini yönetir. Fentolaminden sonra hangi alt tip açıkta kalır?\",\"ar\":\"يتوسط ألفا-1 التضيق الوعائي بينما يتوسط بيتا-2 الارتخاء. أي نمط فرعي يبقى غير محصور بعد الفينتولامين؟\",\"en\":\"Alpha-1 mediates arteriolar constriction, while beta-2 mediates arteriolar relaxation. Which subtype remains unblocked?\"},{\"tier\":3,\"tr\":\"Fentolamin alfa-1 reseptörlerini bloke eder; epinefrinin iskelet kası damarlarındaki beta-2 etkisi engelsiz vazodilatasyon ve hipotansiyon yapar.\",\"ar\":\"يحصر الفينتولامين مستقبلات ألفا-1؛ فيؤدي تأثير الإبينفرين غير المقيد على مستقبلات بيتا-2 العضلية إلى توسع وعائي وهبوط ضغط.\",\"en\":\"Phentolamine blocks vasoconstrictor alpha-1 receptors; unopposed beta-2 receptor activation in skeletal muscle vascular beds produces pronounced vasodilation and hypotension.\"}],\"config\":{\"options\":[{\"id\":\"opt-l7-s1-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Alfa-1 vazokonstriksiyonu bloke edilir; iskelet kası damarlarındaki engellenmemiş beta-2 aktivasyonu belirgin vazodilatasyon ve hipotansiyon oluşturur.\",\"ar\":\"تُحصر مستقبلات ألفا-1 المضيقة للأوعية، فيؤدي تفعيل بيتا-2 دون معارضة في الأوعية العضلية إلى توسع وعائي شديد وهبوط ضغط.\",\"en\":\"Alpha-1 vasoconstriction is blocked; unopposed beta-2 receptor activation in skeletal muscle vascular beds produces pronounced vasodilation and hypotension.\"},\"feedback\":{\"tr\":\"Doğru. Dale vazomotor tersinmesi, alfa-blokajın beta-2 vazodilatasyonunu açığa çıkarmasıyla oluşur.\",\"ar\":\"صحيح. يحدث انعكاس ديل الوعائي لأن حصر ألفا يكشف التوسع الوعائي المتواسط بـ بيتا-2.\",\"en\":\"Correct. Dale's vasomotor reversal occurs because alpha-blockade unmasks potent beta-2 mediated arteriolar dilation.\"}},{\"id\":\"opt-l7-s1-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Fentolamin vagal refleks yaylarını uyararak epinefrinin kardiyak etkisini şiddetli bradikardiye ve vasküler kollapsa dönüştürür.\",\"ar\":\"يحفز الفينتولامين المنعكس المبهمي، محولاً تأثير الإبينفرين القلبي إلى تباطؤ نبض شديد وانهيار وعائي.\",\"en\":\"Phentolamine stimulates vagal reflex arcs, converting epinephrine's cardiac action into profound bradycardia and vascular collapse.\"},\"feedback\":{\"tr\":\"Yanlış. Fentolamin vagal bradikardi yapmaz; kardiyak beta-1 uyarımı devam eder ancak toplam periferik direnç beta-2 ile çöker.\",\"ar\":\"غير صحيح. لا يسبب الفينتولامين بطء قلب مبهمياً؛ يبقى تنبيه بيتا-1 القلبي قائماً بينما تنهار المقاومة بـ بيتا-2.\",\"en\":\"Incorrect. Phentolamine does not cause vagal bradycardia; cardiac beta-1 stimulation remains intact, but peripheral resistance plummets via beta-2 dilation.\"}},{\"id\":\"opt-l7-s1-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Fentolamin beta-1 reseptörlerine geçerek kardiyak debiyi yarışmalı şekilde bloke eder ve sistolik arteriyel basıncı sıfırlar.\",\"ar\":\"يعبر الفينتولامين لمستقبلات بيتا-1 ويحصر النتاج القلبي تنافسياً، ملغياً الضغط الشرياني الانقباضي.\",\"en\":\"Phentolamine crosses to beta-1 receptors and competitively blocks cardiac output, eliminating systolic arterial pressure.\"},\"feedback\":{\"tr\":\"Yanlış. Fentolamin alfa reseptörlerine selektiftir; kardiyak beta-1 reseptörlerine ihmal edilebilir afinite gösterir.\",\"ar\":\"غير صحيح. الفينتولامين انتقائي لمستقبلات ألفا وله ألفة ضئيلة جداً تجاه مستقبلات بيتا-1 القلبية.\",\"en\":\"Incorrect. Phentolamine is selective for alpha adrenoceptors and has negligible affinity for cardiac beta-1 receptors.\"}}],\"prompt\":{\"tr\":\"Epinefrin normalde tansiyonu yükseltir. Ancak alfa-bloker fentolamin ile önceden tedavi edilen bir hayvanda, epinefrin neden kan basıncında ani bir DÜŞÜŞE yol açar?\",\"ar\":\"يرفع الإبينفرين عادة ضغط الدم. ولكن في حيوان عولج مسبقاً بحاصر ألفا فينتولامين، لماذا يسبب الإبينفرين هبوطاً حاداً في ضغط الدم؟\",\"en\":\"Epinephrine normally elevates blood pressure. But in an animal pretreated with the alpha-blocker phentolamine, why does epinephrine trigger a precipitous blood pressure DROP?\"},\"title\":{\"tr\":\"Klinik Paradoks: Dale'in Vazomotor Epinefrin Tersinmesi\",\"ar\":\"المفارقة السريرية: انعكاس ديل الحركي الوعائي للإبينفرين\",\"en\":\"Clinical Paradox: Dale's Vasomotor Epinephrine Reversal\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":9}]},{\"id\":\"pharm-mod4-les1-step2\",\"order\":2,\"stageIndex\":2,\"stage\":\"question\",\"type\":\"question\",\"title\":{\"tr\":\"Kavramsal Soru: Zıt Yanıtların Kökeni\",\"ar\":\"سؤال مفاهيمي: أصل الاستجابات المتعاكسة\",\"en\":\"Conceptual Question: The Origin of Opposing Responses\"},\"prompt\":{\"tr\":\"Aynı epinefrin molekülü, cilt arteriyollerinde yoğun kasılmaya yol açarken iskelet kası damarlarında ve hava yollarında nasıl belirgin gevşeme sağlar?\",\"ar\":\"كيف يمكن لجزيء الإبينفرين نفسه أن يحدث تضيقاً شديداً في شريانات الجلد بينما يسبب ارتخاءً عميقاً في شريانات العضلات والشعب الهوائية؟\",\"en\":\"How can the exact same epinephrine molecule trigger intense constriction in skin arterioles while causing profound relaxation in muscle arterioles and airways?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Aynı epinefrin molekülü farklı dokularda zıt etkilere nasıl yol açar?\",\"ar\":\"كيف يسبب جزيء الإبينفرين نفسه تأثيرات متعاكسة في أنسجة مختلفة؟\",\"en\":\"How does the exact same epinephrine molecule mediate opposing effects across different tissues?\"},\"options\":[{\"id\":\"opt-l7-s2-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Cilt arteriyolleri ağırlıklı olarak alfa-1 (Gq kenetli) ifade ederken, kas arteriyolleri ve bronşiyoller beta-2 (Gs kenetli) reseptörler taşır.\",\"ar\":\"تعبر شريانات الجلد غالباً عن مستقبلات ألفا-1 (المقترنة بـ Gq)، بينما تعبر شريانات العضلات والشعب عن بيتا-2 (المقترنة بـ Gs).\",\"en\":\"Skin arterioles express predominantly alpha-1 receptors (Gq-coupled), whereas skeletal muscle arterioles and bronchioles express beta-2 receptors (Gs-coupled).\"},\"feedback\":{\"tr\":\"Doğru. Dokuya özgü reseptör dağılımı yanıtı belirler: alfa-1 kasılma, beta-2 gevşeme oluşturur.\",\"ar\":\"صحيح. يحدد التوزع النسيجي للمستقبلات نوع الاستجابة: ألفا-1 يسبب التضيق، وبيتا-2 يسبب الارتخاء.\",\"en\":\"Correct. Tissue-specific receptor distribution dictates the response: alpha-1 causes constriction, while beta-2 induces relaxation.\"}},{\"id\":\"opt-l7-s2-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Kutanöz monoamin oksidaz epinefrini uyarıcı bir metabolite yıkarken, kas COMT enzimi onu gevşetici bir metabolite dönüştürür.\",\"ar\":\"يستقلب أوكسيداز أحادي الأمين الجلدي الإبينفرين لمستقلب منبه، بينما يحوله COMT في العضلات لمستقلب مرخٍ.\",\"en\":\"Cutaneous monoamine oxidase metabolizes epinephrine into an excitatory metabolite, while muscle COMT converts it into an inhibitory one.\"},\"feedback\":{\"tr\":\"Yanlış. Epinefrin yüzey reseptörlerine intakt etki eder; MAO veya COMT metabolitleri agonist etki göstermez.\",\"ar\":\"غير صحيح. يؤثر الإبينفرين سليماً على المستقبلات السطحية؛ ولا تمتلك نواتج MAO أو COMT فعالية تنبيهية.\",\"en\":\"Incorrect. Epinephrine acts intact on cell-surface receptors; neither MAO nor COMT metabolites possess significant adrenoceptor agonist activity.\"}},{\"id\":\"opt-l7-s2-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Cilt, iskelet kasından daha yüksek arteryel epinefrin konsantrasyonu alarak vazokonstriktör eşiği aşar.\",\"ar\":\"يصل إلى الجلد تركيز شرياني من الإبينفرين أعلى من العضلات، متجاوزاً عتبة التضيق الوعائي.\",\"en\":\"Skin receives higher arterial epinephrine concentrations than skeletal muscle, overwhelming vasoconstrictor thresholds.\"},\"feedback\":{\"tr\":\"Yanlış. Her iki doku da eşit arteryel ilaç konsantrasyonu alır; fark reseptör alt tip yoğunluğundan kaynaklanır.\",\"ar\":\"غير صحيح. يتلقى كلا النسيجين تركيزاً شريانياً متطابقاً؛ ويعود الفارق حصراً لكثافة الأنماط الفرعية للمستقبلات.\",\"en\":\"Incorrect. Both tissues receive identical arterial drug concentrations; the divergence stems entirely from receptor subtype density.\"}}]},\"technicalTerms\":[{\"term\":\"Reseptör Heterojenitesi\",\"arContext\":\"تغاير المستقبلات (Receptor Heterogeneity)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Dolaşımdaki ligand aynıdır. Hedef doku membranlarında ne farklıdır?\",\"ar\":\"الربيطة الجائلة متطابقة. ما الذي يختلف بين أغشية الأنسجة المستهدفة؟\",\"en\":\"The circulating ligand is identical. What differs between the target tissue membranes?\"},{\"tier\":2,\"tr\":\"Kutanöz ve iskelet kası damar yataklarında hangi reseptör alt tipleri ve G-protein yolakları baskındır?\",\"ar\":\"ما هي الأنماط الفرعية للمستقبلات ومسارات بروتين G السائدة في الأوعية الجلدية مقابل العضلية؟\",\"en\":\"Consider which adrenoceptor subtypes and G-protein pathways predominate in cutaneous versus skeletal muscle beds.\"},{\"tier\":3,\"tr\":\"Cilt damarları alfa-1 (Gq) ifade ederken, kas damarları ve bronşlar beta-2 (Gs) reseptörleri taşır; bu da zıt yanıtlara yol açar.\",\"ar\":\"تعبر أوعية الجلد عن ألفا-1 (Gq)، بينما تحمل أوعية العضلات والشعب مستقبلات بيتا-2 (Gs)، مما يولد استجابات متعاكسة.\",\"en\":\"Cutaneous vessels express predominantly alpha-1 (Gq-coupled), whereas skeletal muscle vessels and airways express beta-2 (Gs-coupled) receptors.\"}],\"config\":{\"options\":[{\"id\":\"opt-l7-s2-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Cilt arteriyolleri ağırlıklı olarak alfa-1 (Gq kenetli) ifade ederken, kas arteriyolleri ve bronşiyoller beta-2 (Gs kenetli) reseptörler taşır.\",\"ar\":\"تعبر شريانات الجلد غالباً عن مستقبلات ألفا-1 (المقترنة بـ Gq)، بينما تعبر شريانات العضلات والشعب عن بيتا-2 (المقترنة بـ Gs).\",\"en\":\"Skin arterioles express predominantly alpha-1 receptors (Gq-coupled), whereas skeletal muscle arterioles and bronchioles express beta-2 receptors (Gs-coupled).\"},\"feedback\":{\"tr\":\"Doğru. Dokuya özgü reseptör dağılımı yanıtı belirler: alfa-1 kasılma, beta-2 gevşeme oluşturur.\",\"ar\":\"صحيح. يحدد التوزع النسيجي للمستقبلات نوع الاستجابة: ألفا-1 يسبب التضيق، وبيتا-2 يسبب الارتخاء.\",\"en\":\"Correct. Tissue-specific receptor distribution dictates the response: alpha-1 causes constriction, while beta-2 induces relaxation.\"}},{\"id\":\"opt-l7-s2-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Kutanöz monoamin oksidaz epinefrini uyarıcı bir metabolite yıkarken, kas COMT enzimi onu gevşetici bir metabolite dönüştürür.\",\"ar\":\"يستقلب أوكسيداز أحادي الأمين الجلدي الإبينفرين لمستقلب منبه، بينما يحوله COMT في العضلات لمستقلب مرخٍ.\",\"en\":\"Cutaneous monoamine oxidase metabolizes epinephrine into an excitatory metabolite, while muscle COMT converts it into an inhibitory one.\"},\"feedback\":{\"tr\":\"Yanlış. Epinefrin yüzey reseptörlerine intakt etki eder; MAO veya COMT metabolitleri agonist etki göstermez.\",\"ar\":\"غير صحيح. يؤثر الإبينفرين سليماً على المستقبلات السطحية؛ ولا تمتلك نواتج MAO أو COMT فعالية تنبيهية.\",\"en\":\"Incorrect. Epinephrine acts intact on cell-surface receptors; neither MAO nor COMT metabolites possess significant adrenoceptor agonist activity.\"}},{\"id\":\"opt-l7-s2-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Cilt, iskelet kasından daha yüksek arteryel epinefrin konsantrasyonu alarak vazokonstriktör eşiği aşar.\",\"ar\":\"يصل إلى الجلد تركيز شرياني من الإبينفرين أعلى من العضلات، متجاوزاً عتبة التضيق الوعائي.\",\"en\":\"Skin receives higher arterial epinephrine concentrations than skeletal muscle, overwhelming vasoconstrictor thresholds.\"},\"feedback\":{\"tr\":\"Yanlış. Her iki doku da eşit arteryel ilaç konsantrasyonu alır; fark reseptör alt tip yoğunluğundan kaynaklanır.\",\"ar\":\"غير صحيح. يتلقى كلا النسيجين تركيزاً شريانياً متطابقاً؛ ويعود الفارق حصراً لكثافة الأنماط الفرعية للمستقبلات.\",\"en\":\"Incorrect. Both tissues receive identical arterial drug concentrations; the divergence stems entirely from receptor subtype density.\"}}],\"prompt\":{\"tr\":\"Aynı epinefrin molekülü, cilt arteriyollerinde yoğun kasılmaya yol açarken iskelet kası damarlarında ve hava yollarında nasıl belirgin gevşeme sağlar?\",\"ar\":\"كيف يمكن لجزيء الإبينفرين نفسه أن يحدث تضيقاً شديداً في شريانات الجلد بينما يسبب ارتخاءً عميقاً في شريانات العضلات والشعب الهوائية؟\",\"en\":\"How can the exact same epinephrine molecule trigger intense constriction in skin arterioles while causing profound relaxation in muscle arterioles and airways?\"},\"title\":{\"tr\":\"Kavramsal Soru: Zıt Yanıtların Kökeni\",\"ar\":\"سؤال مفاهيمي: أصل الاستجابات المتعاكسة\",\"en\":\"Conceptual Question: The Origin of Opposing Responses\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":10}]},{\"id\":\"pharm-mod4-les1-step3\",\"order\":3,\"stageIndex\":3,\"stage\":\"intuition\",\"type\":\"intuition\",\"title\":{\"tr\":\"Fiziksel Sezgi: Savaş ya da Kaç Güç Dağıtıcısı\",\"ar\":\"الحدس الفيزيائي: موجه طاقة الكر والفر\",\"en\":\"Physical Intuition: The Fight-or-Flight Power Router\"},\"prompt\":{\"tr\":\"Akut savaş-ya-da-kaç sempatik deşarjında, farklı adrenerjik reseptör aktivasyonları kan akışını hayati organlara nasıl optimize eder?\",\"ar\":\"أثناء التنبيه الودي الحاد (الكر أو الفر)، كيف يحسن التفعيل المتمايز للمستقبلات الأدرينالينية تدفق الدم للأعضاء الحيوية؟\",\"en\":\"During acute fight-or-flight sympathetic discharge, how does differential adrenoceptor activation optimize blood delivery to vital organs?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Sempatik deşarj sırasında kan akışı vücutta nasıl yeniden dağıtılır?\",\"ar\":\"كيف يُعاد توزيع تدفق الدم في الجسم أثناء التنبيه الودي الحاد؟\",\"en\":\"How is blood flow redistributed during acute sympathetic fight-or-flight activation?\"},\"options\":[{\"id\":\"opt-l7-s3-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Alfa-1 visseral ve mukozal damarları daraltır; debiyi beta-2 ile genişleyen iskelet kası damarlarına ve beta-1 ile uyarılan miyokarda yönlendirir.\",\"ar\":\"يضيق ألفا-1 أوعية الأحشاء والغشاء المخاطي، موجهاً النتاج القلبي نحو عضلات هيكلية موسعة بـ بيتا-2 وميوكارديوم منشط بـ بيتا-1.\",\"en\":\"Alpha-1 vasoconstricts splanchnic and mucosal vessels, shunting cardiac output toward beta-2 dilated skeletal muscle beds and beta-1 stimulated myocardium.\"},\"feedback\":{\"tr\":\"Doğru. Alfa-1 acil olmayan yatakları daraltırken, beta-2 çalışan iskelet kası damarlarını genişletir.\",\"ar\":\"صحيح. يضيق ألفا-1 الأوعية غير الحيوية، بينما يوسع بيتا-2 أوعية العضلات الهيكلية النشطة.\",\"en\":\"Correct. Alpha-1 clamps non-essential vascular beds while beta-2 dilates exercising skeletal muscle beds.\"}},{\"id\":\"opt-l7-s3-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Alfa-1 koroner ve serebral dolaşımı daraltarak toplam kan hacmini yalnızca periferik iskelet kasına yönlendirir.\",\"ar\":\"يضيق ألفا-1 الدوران التاجي والمخي، معيداً توجيه كامل حجم الدم حصرياً نحو العضلات الهيكلية المحيطية.\",\"en\":\"Alpha-1 vasoconstricts coronary and cerebral circulation, redirecting total blood volume exclusively toward peripheral skeletal muscle.\"},\"feedback\":{\"tr\":\"Yanlış. Koroner ve serebral damarlar vazokonstriksiyondan korunur; lokal otoregülasyon ve beta-2 ile genişler.\",\"ar\":\"غير صحيح. يُحمى الدوران التاجي والدماغي من التضيق؛ حيث يتوسعان بالتنظيم الذاتي الموضعي و بيتا-2.\",\"en\":\"Incorrect. Coronary and cerebral vessels are preserved from vasoconstriction; local autoregulation and beta-2 maintain perfusion.\"}},{\"id\":\"opt-l7-s3-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Sempatik uyarım, sistemik arteriyel direnci maksimize etmek için tüm vücuttaki damar yataklarını homojen biçimde büzer.\",\"ar\":\"يسبب التنبيه الودي تضيقاً متجانساً في جميع الأوعية عبر كامل الجسم لتعظيم المقاومة الشريانية الجهازية.\",\"en\":\"Sympathetic stimulation uniformly constricts all vascular beds across the entire body to maximize systemic arterial resistance.\"},\"feedback\":{\"tr\":\"Yanlış. Homojen büzülme kas iskemisine yol açar; sempatik sistem reseptör dağılımı sayesinde kanı seçici olarak yönlendirir.\",\"ar\":\"غير صحيح. التضيق المتجانس يسبب إقفاراً عضلياً؛ يعيد الجهاز الودي توجيه الدم انتقائياً بفضل تباين المستقبلات.\",\"en\":\"Incorrect. Uniform constriction would cause muscle ischemia; sympathetic outflow selectively redistributes blood flow.\"}}]},\"technicalTerms\":[{\"term\":\"Savaş ya da Kaç Yanıtı\",\"arContext\":\"استجابة الكر والفر (Fight-or-Flight Response)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Yoğun efor sırasında kanın nereye acil aktarılması gerektiğini ve nerede feda edilebileceğini düşünün.\",\"ar\":\"فكر في الأعضاء التي تتطلب دماً عاجلاً أثناء الجهد العنيف وتلك التي يمكن الاستغناء عنها مؤقتاً.\",\"en\":\"Think about where blood is desperately needed during high-stress exertion versus where it can be spared.\"},{\"tier\":2,\"tr\":\"Sindirim ve cilt kanlanması kısıtlanabilir; çalışan iskelet kasları ve kalp ise yüksek oksijene ihtiyaç duyar.\",\"ar\":\"يمكن تقليص التروية الجلدية والهضمية؛ بينما تتطلب العضلات الهيكلية العاملة والقلب تدفقاً هائلاً.\",\"en\":\"Digestion and skin perfusion can be temporarily sacrificed; skeletal muscles and the heart demand immense oxygen delivery.\"},{\"tier\":3,\"tr\":\"Alfa-1 viseral damarları büzerek kanı azaltır; beta-2 ise kas damarlarını genişleterek kanı çalışan kaslara yönlendirir.\",\"ar\":\"يضيق ألفا-1 أوعية الأحشاء حابساً الدم؛ بينما يوسع بيتا-2 أوعية العضلات موجهاً التدفق للأعضاء الحيوية.\",\"en\":\"Alpha-1 clamps visceral and cutaneous vessels, shunting perfusion to beta-2 dilated skeletal muscle beds and beta-1 myocardium.\"}],\"config\":{\"options\":[{\"id\":\"opt-l7-s3-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Alfa-1 visseral ve mukozal damarları daraltır; debiyi beta-2 ile genişleyen iskelet kası damarlarına ve beta-1 ile uyarılan miyokarda yönlendirir.\",\"ar\":\"يضيق ألفا-1 أوعية الأحشاء والغشاء المخاطي، موجهاً النتاج القلبي نحو عضلات هيكلية موسعة بـ بيتا-2 وميوكارديوم منشط بـ بيتا-1.\",\"en\":\"Alpha-1 vasoconstricts splanchnic and mucosal vessels, shunting cardiac output toward beta-2 dilated skeletal muscle beds and beta-1 stimulated myocardium.\"},\"feedback\":{\"tr\":\"Doğru. Alfa-1 acil olmayan yatakları daraltırken, beta-2 çalışan iskelet kası damarlarını genişletir.\",\"ar\":\"صحيح. يضيق ألفا-1 الأوعية غير الحيوية، بينما يوسع بيتا-2 أوعية العضلات الهيكلية النشطة.\",\"en\":\"Correct. Alpha-1 clamps non-essential vascular beds while beta-2 dilates exercising skeletal muscle beds.\"}},{\"id\":\"opt-l7-s3-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Alfa-1 koroner ve serebral dolaşımı daraltarak toplam kan hacmini yalnızca periferik iskelet kasına yönlendirir.\",\"ar\":\"يضيق ألفا-1 الدوران التاجي والمخي، معيداً توجيه كامل حجم الدم حصرياً نحو العضلات الهيكلية المحيطية.\",\"en\":\"Alpha-1 vasoconstricts coronary and cerebral circulation, redirecting total blood volume exclusively toward peripheral skeletal muscle.\"},\"feedback\":{\"tr\":\"Yanlış. Koroner ve serebral damarlar vazokonstriksiyondan korunur; lokal otoregülasyon ve beta-2 ile genişler.\",\"ar\":\"غير صحيح. يُحمى الدوران التاجي والدماغي من التضيق؛ حيث يتوسعان بالتنظيم الذاتي الموضعي و بيتا-2.\",\"en\":\"Incorrect. Coronary and cerebral vessels are preserved from vasoconstriction; local autoregulation and beta-2 maintain perfusion.\"}},{\"id\":\"opt-l7-s3-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Sempatik uyarım, sistemik arteriyel direnci maksimize etmek için tüm vücuttaki damar yataklarını homojen biçimde büzer.\",\"ar\":\"يسبب التنبيه الودي تضيقاً متجانساً في جميع الأوعية عبر كامل الجسم لتعظيم المقاومة الشريانية الجهازية.\",\"en\":\"Sympathetic stimulation uniformly constricts all vascular beds across the entire body to maximize systemic arterial resistance.\"},\"feedback\":{\"tr\":\"Yanlış. Homojen büzülme kas iskemisine yol açar; sempatik sistem reseptör dağılımı sayesinde kanı seçici olarak yönlendirir.\",\"ar\":\"غير صحيح. التضيق المتجانس يسبب إقفاراً عضلياً؛ يعيد الجهاز الودي توجيه الدم انتقائياً بفضل تباين المستقبلات.\",\"en\":\"Incorrect. Uniform constriction would cause muscle ischemia; sympathetic outflow selectively redistributes blood flow.\"}}],\"prompt\":{\"tr\":\"Akut savaş-ya-da-kaç sempatik deşarjında, farklı adrenerjik reseptör aktivasyonları kan akışını hayati organlara nasıl optimize eder?\",\"ar\":\"أثناء التنبيه الودي الحاد (الكر أو الفر)، كيف يحسن التفعيل المتمايز للمستقبلات الأدرينالينية تدفق الدم للأعضاء الحيوية؟\",\"en\":\"During acute fight-or-flight sympathetic discharge, how does differential adrenoceptor activation optimize blood delivery to vital organs?\"},\"title\":{\"tr\":\"Fiziksel Sezgi: Savaş ya da Kaç Güç Dağıtıcısı\",\"ar\":\"الحدس الفيزيائي: موجه طاقة الكر والفر\",\"en\":\"Physical Intuition: The Fight-or-Flight Power Router\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":11}]},{\"id\":\"pharm-mod4-les1-step4\",\"order\":4,\"stageIndex\":4,\"stage\":\"visual_explanation\",\"type\":\"visual_explanation\",\"title\":{\"tr\":\"Görsel Açıklama: Gq ve Gs İkinci Haberci Çatallanması\",\"ar\":\"شرح مرئي: تشعب المرسال الثاني بين Gq و Gs\",\"en\":\"Visual Explanation: Gq vs Gs Second Messenger Bifurcation\"},\"prompt\":{\"tr\":\"İkinci haberci haritasını inceleyin: Alfa-1 Gq'ya, Beta-1 ve Beta-2 ise Gs'ye kenetlenir. PKA miyokard ve düz kasta nasıl zıt mekanik etkiler üretir?\",\"ar\":\"افحص خريطة المرسال الثاني: يقترن ألفا-1 بـ Gq، بينما يقترن بيتا-1 وبيتا-2 بـ Gs. كيف ينتج PKA تأثيرات ميكانيكية متعاكسة في العضلة القلبية والملساء؟\",\"en\":\"Examine the second messenger map: Alpha-1 couples to Gq, whereas Beta-1 and Beta-2 couple to Gs. How does PKA produce opposite mechanical effects in myocardium versus smooth muscle?\"},\"conceptCheck\":{\"question\":{\"tr\":\"PKA miyokard ve damar düz kasında neden zıt mekanik yanıtlara yol açar?\",\"ar\":\"لماذا يسبب PKA استجابات ميكانيكية متعاكسة بين العضلة القلبية والملساء؟\",\"en\":\"Why does PKA mediate opposite mechanical responses in myocardium versus smooth muscle?\"},\"options\":[{\"id\":\"opt-l7-s4-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Kardiyak miyositlerde PKA L-tipi Ca2+ kanallarını fosforiller (kasılmayı artırır); düz kasta ise MLCK'yi fosforilleyip inhibe ederek gevşeme sağlar.\",\"ar\":\"في الخلايا القلبية، يفسفر PKA قنوات الكالسيوم L (معززاً الانقباض)؛ وفي العضلة الملساء، يفسفر ويثبط MLCK (محدثاً الارتخاء).\",\"en\":\"In cardiac myocytes, PKA phosphorylates L-type Ca2+ channels (enhancing contraction); in smooth muscle, PKA phosphorylates and inhibits MLCK (producing relaxation).\"},\"feedback\":{\"tr\":\"Doğru. PKA dokuya özgü substratları hedefler: kalpte kalsiyum girişini artırır, düz kasta MLCK'yi inaktive eder.\",\"ar\":\"صحيح. يستهدف PKA ركائز نسيجية نوعية: يزيد دخول الكالسيوم في القلب، ويثبط MLCK في العضلة الملساء.\",\"en\":\"Correct. PKA phosphorylation has tissue-specific substrates: activates cardiac calcium entry, but inactivates smooth muscle MLCK.\"}},{\"id\":\"opt-l7-s4-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Hem kardiyak hem düz kasta PKA, aktini doğrudan fosforilleyerek filamentleri çapraz bağlar ve aktif kasılmaya zorlar.\",\"ar\":\"في كل من العضلة القلبية والملساء، يفسفر PKA الأكتين مباشرة لربط الخيوط وفرض انقباض نشط.\",\"en\":\"In both cardiac and smooth muscle, PKA directly phosphorylates actin to cross-link filaments and force active contraction.\"},\"feedback\":{\"tr\":\"Yanlış. Düz kas kasılması kalsiyum-kalmodulin ile MLCK aktivasyonuna bakar; PKA MLCK'yi inhibe ederek gevşetir.\",\"ar\":\"غير صحيح. يتطلب انقباض العضلة الملساء تفعيل MLCK عبر الكالسيوم؛ وفسفرة PKA تثبط MLCK مسببة الارتخاء.\",\"en\":\"Incorrect. Smooth muscle contraction requires MLCK activation by calcium-calmodulin; PKA phosphorylation inhibits MLCK, causing relaxation.\"}},{\"id\":\"opt-l7-s4-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Kardiyak hücrelerde Gs troponini doğrudan aktive eder; damar düz kasında ise Gs voltaj kapılı sodyum kanallarını doğrudan açar.\",\"ar\":\"في الخلايا القلبية، ينشط Gs التروponin مباشرة؛ وفي العضلة الملساء الوعائية، يفتح Gs قنوات الصوديوم المبوبة بالجهد مباشرة.\",\"en\":\"In cardiac cells, Gs activates troponin directly; in vascular smooth muscle, Gs directly opens voltage-gated sodium channels.\"},\"feedback\":{\"tr\":\"Yanlış. Gs adenilat siklaz ve cAMP/PKA üzerinden etki eder; troponin veya sodyum kanallarına doğrudan bağlanmaz.\",\"ar\":\"غير صحيح. يعمل Gs عبر محلقة الأدينيلات و cAMP/PKA؛ ولا يرتبط مباشرة بالتروبونين أو قنوات الصوديوم.\",\"en\":\"Incorrect. Gs acts through adenylyl cyclase and cAMP/PKA; it does not directly bind troponin or sodium channels.\"}}]},\"technicalTerms\":[{\"term\":\"Miyozin Hafif Zincir Kinazı\",\"arContext\":\"كيناز سلسلة الميوزين الخفيفة (Myosin Light-Chain Kinase (MLCK))\"}],\"hints\":[{\"tier\":1,\"tr\":\"Her iki dokuda da cAMP artar ve PKA aktive olur. PKA her birinde hangi aşağı akış molekülünü fosforiller?\",\"ar\":\"في كلا النسيجين يرتفع cAMP ويتفعل PKA. ما هو الجزيء المستهدف الذي يفسفره PKA في كل منهما؟\",\"en\":\"Both tissues experience rising cAMP and active PKA. What downstream substrate does PKA phosphorylate in each?\"},{\"tier\":2,\"tr\":\"Kalp kasılması kalsiyum girişine bağlıdır; düz kas tonusu ise Miyozin Hafif Zincir Kinazına (MLCK) bağlıdır.\",\"ar\":\"يعتمد انقباض القلب على دخول الكالسيوم؛ بينما تعتمد مقوية العضلة الملساء على كيناز سلاسل الميوزين الخفيفة (MLCK).\",\"en\":\"Look at the contractile machinery: myocardium requires calcium influx, whereas smooth muscle tone depends on MLCK.\"},{\"tier\":3,\"tr\":\"PKA miyositlerde L-tipi Ca2+ kanallarını fosforilleyerek kasılmayı artırır; düz kasta ise MLCK'yi inaktive ederek gevşeme sağlar.\",\"ar\":\"يفسفر PKA قنوات الكالسيوم L في القلب معززاً الانقباض، لكنه يفسفر ويثبط MLCK في العضلات الملساء محدثاً الارتخاء.\",\"en\":\"PKA enhances L-type Ca2+ channel opening in cardiomyocytes, but phosphorylates and inhibits MLCK in smooth muscle, causing relaxation.\"}],\"config\":{\"options\":[{\"id\":\"opt-l7-s4-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Kardiyak miyositlerde PKA L-tipi Ca2+ kanallarını fosforiller (kasılmayı artırır); düz kasta ise MLCK'yi fosforilleyip inhibe ederek gevşeme sağlar.\",\"ar\":\"في الخلايا القلبية، يفسفر PKA قنوات الكالسيوم L (معززاً الانقباض)؛ وفي العضلة الملساء، يفسفر ويثبط MLCK (محدثاً الارتخاء).\",\"en\":\"In cardiac myocytes, PKA phosphorylates L-type Ca2+ channels (enhancing contraction); in smooth muscle, PKA phosphorylates and inhibits MLCK (producing relaxation).\"},\"feedback\":{\"tr\":\"Doğru. PKA dokuya özgü substratları hedefler: kalpte kalsiyum girişini artırır, düz kasta MLCK'yi inaktive eder.\",\"ar\":\"صحيح. يستهدف PKA ركائز نسيجية نوعية: يزيد دخول الكالسيوم في القلب، ويثبط MLCK في العضلة الملساء.\",\"en\":\"Correct. PKA phosphorylation has tissue-specific substrates: activates cardiac calcium entry, but inactivates smooth muscle MLCK.\"}},{\"id\":\"opt-l7-s4-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Hem kardiyak hem düz kasta PKA, aktini doğrudan fosforilleyerek filamentleri çapraz bağlar ve aktif kasılmaya zorlar.\",\"ar\":\"في كل من العضلة القلبية والملساء، يفسفر PKA الأكتين مباشرة لربط الخيوط وفرض انقباض نشط.\",\"en\":\"In both cardiac and smooth muscle, PKA directly phosphorylates actin to cross-link filaments and force active contraction.\"},\"feedback\":{\"tr\":\"Yanlış. Düz kas kasılması kalsiyum-kalmodulin ile MLCK aktivasyonuna bakar; PKA MLCK'yi inhibe ederek gevşetir.\",\"ar\":\"غير صحيح. يتطلب انقباض العضلة الملساء تفعيل MLCK عبر الكالسيوم؛ وفسفرة PKA تثبط MLCK مسببة الارتخاء.\",\"en\":\"Incorrect. Smooth muscle contraction requires MLCK activation by calcium-calmodulin; PKA phosphorylation inhibits MLCK, causing relaxation.\"}},{\"id\":\"opt-l7-s4-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Kardiyak hücrelerde Gs troponini doğrudan aktive eder; damar düz kasında ise Gs voltaj kapılı sodyum kanallarını doğrudan açar.\",\"ar\":\"في الخلايا القلبية، ينشط Gs التروponin مباشرة؛ وفي العضلة الملساء الوعائية، يفتح Gs قنوات الصوديوم المبوبة بالجهد مباشرة.\",\"en\":\"In cardiac cells, Gs activates troponin directly; in vascular smooth muscle, Gs directly opens voltage-gated sodium channels.\"},\"feedback\":{\"tr\":\"Yanlış. Gs adenilat siklaz ve cAMP/PKA üzerinden etki eder; troponin veya sodyum kanallarına doğrudan bağlanmaz.\",\"ar\":\"غير صحيح. يعمل Gs عبر محلقة الأدينيلات و cAMP/PKA؛ ولا يرتبط مباشرة بالتروبونين أو قنوات الصوديوم.\",\"en\":\"Incorrect. Gs acts through adenylyl cyclase and cAMP/PKA; it does not directly bind troponin or sodium channels.\"}}],\"prompt\":{\"tr\":\"İkinci haberci haritasını inceleyin: Alfa-1 Gq'ya, Beta-1 ve Beta-2 ise Gs'ye kenetlenir. PKA miyokard ve düz kasta nasıl zıt mekanik etkiler üretir?\",\"ar\":\"افحص خريطة المرسال الثاني: يقترن ألفا-1 بـ Gq، بينما يقترن بيتا-1 وبيتا-2 بـ Gs. كيف ينتج PKA تأثيرات ميكانيكية متعاكسة في العضلة القلبية والملساء؟\",\"en\":\"Examine the second messenger map: Alpha-1 couples to Gq, whereas Beta-1 and Beta-2 couple to Gs. How does PKA produce opposite mechanical effects in myocardium versus smooth muscle?\"},\"title\":{\"tr\":\"Görsel Açıklama: Gq ve Gs İkinci Haberci Çatallanması\",\"ar\":\"شرح مرئي: تشعب المرسال الثاني بين Gq و Gs\",\"en\":\"Visual Explanation: Gq vs Gs Second Messenger Bifurcation\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":12}]},{\"id\":\"pharm-mod4-les1-step5\",\"order\":5,\"stageIndex\":5,\"stage\":\"interactive_artifact\",\"type\":\"interactive_artifact\",\"title\":{\"tr\":\"İnteraktif Deney: Adrenalin-Beta Reseptör Kenetlenmesi\",\"ar\":\"تجربة تفاعلية: تطابق الأدرينالين مع جيب مستقبل بيتا\",\"en\":\"Interactive Experiment: Epinephrine-Beta Receptor Docking\"},\"prompt\":{\"tr\":\"Adrenalinin amin, katekol ve beta-hidroksil gruplarını beta-adrenerjik reseptör aktif cebindeki Asp113, Ser204, Phe290 ve Asn293 kalıntılarıyla eşleştirin.\",\"ar\":\"طابق مجموعات الأمين والكاتيكول وهيدروكسيل بيتا للأدرينالين مع ثمالات Asp113 و Ser204 و Phe290 و Asn293 في جيب مستقبل بيتا.\",\"en\":\"Dock epinephrine into the beta-adrenergic pocket by matching its amine, catechol, and beta-OH to Asp113, Ser204, Phe290, and Asn293 residues.\"},\"widgetType\":\"ReceptorLigandMatcher\",\"widget\":{\"type\":\"ReceptorLigandMatcher\",\"config\":{\"title\":\"Adrenalin - Beta-2 Adrenerjik Reseptör Kenetlenmesi\",\"prompt\":\"Adrenalinin fonksiyonel gruplarını beta-2 reseptör cebindeki tamamlayıcı amino asitlerle eşleştirin.\",\"drugName\":\"Adrenalin (Epinephrine)\",\"receptorName\":\"Beta-2 Adrenerjik GPCR\",\"pairs\":[{\"id\":\"pair-1\",\"drugGroup\":\"Protonlanmış Sekonder Amin (-NH2+CH3)\",\"correctResidueId\":\"res-asp113\",\"bondType\":\"ionic\",\"energyKcalMol\":\"-8 to -12 kcal/mol\",\"explanation\":\"Protonlanmış katyonik amin, TM3 heliksindeki Asp113 karboksilat anyonu ile zorunlu elektrostatik tuz köprüsü kurar.\"},{\"id\":\"pair-2\",\"drugGroup\":\"Katekol Fenolik Hidroksilleri (meta & para -OH)\",\"correctResidueId\":\"res-ser204\",\"bondType\":\"h_bond\",\"energyKcalMol\":\"-4 to -7 kcal/mol\",\"explanation\":\"Katekol hidroksilleri TM5 heliksindeki Ser204 ve Ser207 kalıntılarıyla kilit hidrojen bağları oluşturarak reseptörü aktive eder.\"},{\"id\":\"pair-3\",\"drugGroup\":\"Katekol Aromatik Benzen Halkası\",\"correctResidueId\":\"res-phe290\",\"bondType\":\"pi_pi\",\"energyKcalMol\":\"-2 to -4 kcal/mol\",\"explanation\":\"Katekol benzen halkası TM6'daki Phe290 aromatik yan zinciriyle pi-pi istiflenme etkileşimi kurar.\"},{\"id\":\"pair-4\",\"drugGroup\":\"Kiral (R)-Beta-Hidroksil Grubu\",\"correctResidueId\":\"res-asn293\",\"bondType\":\"h_bond\",\"energyKcalMol\":\"-3 to -5 kcal/mol\",\"explanation\":\"Easson-Stedman hipotezine göre kiral beta-OH grubu TM6'daki Asn293 ile spesifik hidrojen bağı kurarak yüksek afinite sağlar.\"}],\"residues\":[{\"id\":\"res-asp113\",\"residueName\":\"Asp113 (TM3)\",\"description\":\"Negatif yüklü aspartat karboksilat grubu; adrenerjik ligantların protonlanmış aminiyle tuz köprüsü oluşturur.\"},{\"id\":\"res-ser204\",\"residueName\":\"Ser204 / Ser207 (TM5)\",\"description\":\"Polar serin hidroksil kalıntıları; katekol halkasının hidroksil gruplarıyla hidrojen bağı yapar.\"},{\"id\":\"res-phe290\",\"residueName\":\"Phe290 (TM6)\",\"description\":\"Hidrofobik fenilalanin aromatik halkası; katekol benzen halkasıyla pi-pi istiflenme temasındadır.\"},{\"id\":\"res-asn293\",\"residueName\":\"Asn293 (TM6)\",\"description\":\"Polar asparajin yan zinciri; kiral R-(-) enantiomerinin beta-OH grubuyla hidrojen bağı kurar.\"},{\"id\":\"res-val114\",\"residueName\":\"Val114 (TM3)\",\"description\":\"Alifatik apolar valin kalıntısı; ligandın alkil yan zinciriyle temas eden hidrofobik çevre.\"}],\"source\":{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":14}}},\"config\":{\"title\":\"Adrenalin - Beta-2 Adrenerjik Reseptör Kenetlenmesi\",\"prompt\":\"Adrenalinin fonksiyonel gruplarını beta-2 reseptör cebindeki tamamlayıcı amino asitlerle eşleştirin.\",\"drugName\":\"Adrenalin (Epinephrine)\",\"receptorName\":\"Beta-2 Adrenerjik GPCR\",\"pairs\":[{\"id\":\"pair-1\",\"drugGroup\":\"Protonlanmış Sekonder Amin (-NH2+CH3)\",\"correctResidueId\":\"res-asp113\",\"bondType\":\"ionic\",\"energyKcalMol\":\"-8 to -12 kcal/mol\",\"explanation\":\"Protonlanmış katyonik amin, TM3 heliksindeki Asp113 karboksilat anyonu ile zorunlu elektrostatik tuz köprüsü kurar.\"},{\"id\":\"pair-2\",\"drugGroup\":\"Katekol Fenolik Hidroksilleri (meta & para -OH)\",\"correctResidueId\":\"res-ser204\",\"bondType\":\"h_bond\",\"energyKcalMol\":\"-4 to -7 kcal/mol\",\"explanation\":\"Katekol hidroksilleri TM5 heliksindeki Ser204 ve Ser207 kalıntılarıyla kilit hidrojen bağları oluşturarak reseptörü aktive eder.\"},{\"id\":\"pair-3\",\"drugGroup\":\"Katekol Aromatik Benzen Halkası\",\"correctResidueId\":\"res-phe290\",\"bondType\":\"pi_pi\",\"energyKcalMol\":\"-2 to -4 kcal/mol\",\"explanation\":\"Katekol benzen halkası TM6'daki Phe290 aromatik yan zinciriyle pi-pi istiflenme etkileşimi kurar.\"},{\"id\":\"pair-4\",\"drugGroup\":\"Kiral (R)-Beta-Hidroksil Grubu\",\"correctResidueId\":\"res-asn293\",\"bondType\":\"h_bond\",\"energyKcalMol\":\"-3 to -5 kcal/mol\",\"explanation\":\"Easson-Stedman hipotezine göre kiral beta-OH grubu TM6'daki Asn293 ile spesifik hidrojen bağı kurarak yüksek afinite sağlar.\"}],\"residues\":[{\"id\":\"res-asp113\",\"residueName\":\"Asp113 (TM3)\",\"description\":\"Negatif yüklü aspartat karboksilat grubu; adrenerjik ligantların protonlanmış aminiyle tuz köprüsü oluşturur.\"},{\"id\":\"res-ser204\",\"residueName\":\"Ser204 / Ser207 (TM5)\",\"description\":\"Polar serin hidroksil kalıntıları; katekol halkasının hidroksil gruplarıyla hidrojen bağı yapar.\"},{\"id\":\"res-phe290\",\"residueName\":\"Phe290 (TM6)\",\"description\":\"Hidrofobik fenilalanin aromatik halkası; katekol benzen halkasıyla pi-pi istiflenme temasındadır.\"},{\"id\":\"res-asn293\",\"residueName\":\"Asn293 (TM6)\",\"description\":\"Polar asparajin yan zinciri; kiral R-(-) enantiomerinin beta-OH grubuyla hidrojen bağı kurar.\"},{\"id\":\"res-val114\",\"residueName\":\"Val114 (TM3)\",\"description\":\"Alifatik apolar valin kalıntısı; ligandın alkil yan zinciriyle temas eden hidrofobik çevre.\"}],\"source\":{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":14}},\"technicalTerms\":[{\"term\":\"Easson-Stedman Hipotezi\",\"arContext\":\"فرضية إيسون-ستيدمان (Easson-Stedman Hypothesis)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Epinefrinin pozitif yüklü amin grubunu, katekol halkasını ve kiral hidroksilini inceleyin.\",\"ar\":\"افحص مجموعة الأمين الموجبة وحلقة الكاتيكول والهيدروكسيل الفراغي في الإبينفرين.\",\"en\":\"Examine epinephrine's positively charged amine, catechol ring, and chiral beta-hydroxyl group.\"},{\"tier\":2,\"tr\":\"Asp113 iyonik bağ için negatif karboksilat sağlar; Ser204 katekol ile H-bağı yapar; Phe290 aromatik istiflenme kurar.\",\"ar\":\"يوفر Asp113 كربوكسيلات سالبة للرابط الأيوني؛ ويشكل Ser204 رابطاً هيدروجينياً؛ بينما يتيح Phe290 تكدساً عطرياً.\",\"en\":\"Asp113 provides a carboxylate for ionic bonding; Ser204 H-bonds with catechol; Phe290 forms pi-stacking.\"},{\"tier\":3,\"tr\":\"Protonlanmış amini Asp113'e (iyonik), katekol OH'yi Ser204'e (H-bağı), aromatik halkayı Phe290'a (pi-pi) ve beta-OH'yi Asn293'e (H-bağı) kenetleyin.\",\"ar\":\"اربط الأمين البروتوني بـ Asp113 (أيوني)، وهيدروكسيل الكاتيكول بـ Ser204 (هيدروجيني)، والحلقة بـ Phe290 (باي-باي)، وبيتا-OH بـ Asn293.\",\"en\":\"Match protonated amine to Asp113 (ionic), catechol meta-OH to Ser204 (H-bond), aromatic ring to Phe290 (pi-pi), and beta-OH to Asn293 (H-bond).\"}],\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":13}]},{\"id\":\"pharm-mod4-les1-step6\",\"order\":6,\"stageIndex\":6,\"stage\":\"guided_discovery\",\"type\":\"guided_discovery\",\"title\":{\"tr\":\"Rehberli Keşif: Presinaptik Alfa-2 Otoreseptör Freni\",\"ar\":\"استكشاف موجه: كابح مستقبل ألفا-2 الذاتي قبل المشبكي\",\"en\":\"Guided Discovery: Presynaptic Alpha-2 Autoreceptor Brake\"},\"prompt\":{\"tr\":\"Sempatik sinaptik aralıkta biriken noradrenalin, hangi fizyolojik otoreseptör mekanizmasıyla aşırı nörotransmiter salınımını durdurur?\",\"ar\":\"عندما يتراكم النورإبينفرين في الشق المشبكي الودي، ما هي آلية المستقبل الذاتي الفسيولوجية التي توقف التحرر المفرط للناقل؟\",\"en\":\"When exocytosed norepinephrine accumulates in the sympathetic synaptic cleft, what physiological autoreceptor mechanism halts excessive neurotransmitter release?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Presinaptik alfa-2 otoreseptörleri noradrenalin salınımını nasıl inhibe eder?\",\"ar\":\"كيف تثبط مستقبلات ألفا-2 الذاتية قبل المشبكية تحرر النورإبينفرين؟\",\"en\":\"How do presynaptic alpha-2 autoreceptors inhibit further norepinephrine release?\"},\"options\":[{\"id\":\"opt-l7-s6-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Presinaptik alfa-2 reseptörleri Gi'ye kenetlenir, adenilat siklazı inhibe eder ve N-tipi Ca2+ kanallarını kapatarak vezikül ekzositozunu durdurur.\",\"ar\":\"تقترن مستقبلات ألفا-2 قبل المشبكية بـ Gi، مثبطة محلقة الأدينيلات ومغلقة قنوات الكالسيوم N لوقف اندماج الحويصلات.\",\"en\":\"Presynaptic alpha-2 receptors couple to Gi, inhibiting adenylyl cyclase and closing N-type Ca2+ channels to block vesicle exocytosis.\"},\"feedback\":{\"tr\":\"Doğru. Presinaptik alfa-2 reseptörleri fizyolojik bir negatif geri bildirim frenidir: Gi kalsiyum girişini keserek ekzositozu bitirir.\",\"ar\":\"صحيح. تعمل مستقبلات ألفا-2 قبل المشبكية ككابح تلقيم راجع سلبي: يقطع Gi دخول الكالسيوم منهياً الإفراز الحويصلي.\",\"en\":\"Correct. Presynaptic alpha-2 receptors act as a physiological negative feedback brake: Gi lowers cAMP and halts Ca2+ influx.\"}},{\"id\":\"opt-l7-s6-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Postsinaptik alfa-2 reseptörleri beta-arrestini çağırarak tüm postsinaptik adrenerjik reseptörleri hücre içine alır ve yanıtı sonlandırır.\",\"ar\":\"تستدعي مستقبلات ألفا-2 بعد المشبكية بيتا-أريستين لبلعمة جميع المستقبلات بعد المشبكية، منهية الاستجابة.\",\"en\":\"Postsynaptic alpha-2 receptors recruit beta-arrestin to internalize all postsynaptic adrenoceptors, ending the response.\"},\"feedback\":{\"tr\":\"Yanlış. Salınımın negatif geri bildirim kontrolü postsinaptik reseptör internalizasyonuyla değil, presinaptik otoreseptörlerle sağlanır.\",\"ar\":\"غير صحيح. يحدث التلقيم الراجع السلبي المانع للتحرر على النهاية قبل المشبكية عبر مستقبلات ذاتية لا عبر البلعمة بعد المشبكية.\",\"en\":\"Incorrect. Negative feedback regulation of release occurs on the presynaptic terminal via autoreceptors, not via postsynaptic internalization.\"}},{\"id\":\"opt-l7-s6-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Alfa-2 presinaptik kalsiyum kanallarını etkilemeksizin, geri alımı hızlandırmak için noradrenalin taşıyıcısını (NET) uyarır.\",\"ar\":\"يحفز ألفا-2 ناقل النورإبينفرين (NET) لتسريع إعادة الالتقاط، دون التأثير على قنوات الكالسيوم قبل المشبكية.\",\"en\":\"Alpha-2 stimulates the norepinephrine transporter (NET) to accelerate reuptake, without affecting presynaptic calcium channels.\"},\"feedback\":{\"tr\":\"Yanlış. NET sodyum bağımlı bir taşıyıcıdır; alfa-2 ise spesifik olarak voltaj kapılı kalsiyum kanallarını kapatarak ekzositozu durdurur.\",\"ar\":\"غير صحيح. ناقل NET يعتمد على الصوديوم مستقلاً عن تأشير Gi؛ يغلق ألفا-2 قنوات الكالسيوم المعتمدة على الفولتية ليوقف الإفراز.\",\"en\":\"Incorrect. NET is a secondary active sodium-dependent symporter; alpha-2 specifically closes voltage-gated calcium channels.\"}}]},\"technicalTerms\":[{\"term\":\"Presinaptik Otoreseptör\",\"arContext\":\"المستقبل الذاتي قبل المشبكي (Presynaptic Autoreceptor)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Hedef dokuda değil, presinaptik sinir ucunda bulunan adrenerjik reseptör alt tipini düşünün.\",\"ar\":\"فكر في النمط الفرعي للمستقبلات الأدرينالينية الموجود على النهاية العصبية قبل المشبكية لا النسيج الهدف.\",\"en\":\"Think about which adrenoceptor subtype is located on the presynaptic nerve ending rather than the target tissue.\"},{\"tier\":2,\"tr\":\"Bu reseptör inhibitör G-proteinine (Gi) kenetlenir. Vezikül füzyonu için hangi iyon girişi şarttır?\",\"ar\":\"يقترن هذا المستقبل ببروتين G التثبيطي (Gi). ما هو التدفق الأيوني الإلزامي لاندماج الحويصلات؟\",\"en\":\"This receptor couples to an inhibitory G-protein (Gi). What ion influx is mandatory for vesicle fusion?\"},{\"tier\":3,\"tr\":\"Presinaptik alfa-2 reseptörleri Gi'ye kenetlenir, cAMP'yi düşürür ve N-tipi kalsiyum kanallarını kapatarak ekzositozu durdurur.\",\"ar\":\"تقترن مستقبلات ألفا-2 قبل المشبكية بـ Gi، خافضة cAMP ومغلقة قنوات الكالسيوم N لوقف اندماج الحويصلات وإفرازها.\",\"en\":\"Presynaptic alpha-2 receptors couple to Gi, reducing cAMP and blocking N-type calcium channels to halt exocytosis.\"}],\"config\":{\"options\":[{\"id\":\"opt-l7-s6-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Presinaptik alfa-2 reseptörleri Gi'ye kenetlenir, adenilat siklazı inhibe eder ve N-tipi Ca2+ kanallarını kapatarak vezikül ekzositozunu durdurur.\",\"ar\":\"تقترن مستقبلات ألفا-2 قبل المشبكية بـ Gi، مثبطة محلقة الأدينيلات ومغلقة قنوات الكالسيوم N لوقف اندماج الحويصلات.\",\"en\":\"Presynaptic alpha-2 receptors couple to Gi, inhibiting adenylyl cyclase and closing N-type Ca2+ channels to block vesicle exocytosis.\"},\"feedback\":{\"tr\":\"Doğru. Presinaptik alfa-2 reseptörleri fizyolojik bir negatif geri bildirim frenidir: Gi kalsiyum girişini keserek ekzositozu bitirir.\",\"ar\":\"صحيح. تعمل مستقبلات ألفا-2 قبل المشبكية ككابح تلقيم راجع سلبي: يقطع Gi دخول الكالسيوم منهياً الإفراز الحويصلي.\",\"en\":\"Correct. Presynaptic alpha-2 receptors act as a physiological negative feedback brake: Gi lowers cAMP and halts Ca2+ influx.\"}},{\"id\":\"opt-l7-s6-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Postsinaptik alfa-2 reseptörleri beta-arrestini çağırarak tüm postsinaptik adrenerjik reseptörleri hücre içine alır ve yanıtı sonlandırır.\",\"ar\":\"تستدعي مستقبلات ألفا-2 بعد المشبكية بيتا-أريستين لبلعمة جميع المستقبلات بعد المشبكية، منهية الاستجابة.\",\"en\":\"Postsynaptic alpha-2 receptors recruit beta-arrestin to internalize all postsynaptic adrenoceptors, ending the response.\"},\"feedback\":{\"tr\":\"Yanlış. Salınımın negatif geri bildirim kontrolü postsinaptik reseptör internalizasyonuyla değil, presinaptik otoreseptörlerle sağlanır.\",\"ar\":\"غير صحيح. يحدث التلقيم الراجع السلبي المانع للتحرر على النهاية قبل المشبكية عبر مستقبلات ذاتية لا عبر البلعمة بعد المشبكية.\",\"en\":\"Incorrect. Negative feedback regulation of release occurs on the presynaptic terminal via autoreceptors, not via postsynaptic internalization.\"}},{\"id\":\"opt-l7-s6-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Alfa-2 presinaptik kalsiyum kanallarını etkilemeksizin, geri alımı hızlandırmak için noradrenalin taşıyıcısını (NET) uyarır.\",\"ar\":\"يحفز ألفا-2 ناقل النورإبينفرين (NET) لتسريع إعادة الالتقاط، دون التأثير على قنوات الكالسيوم قبل المشبكية.\",\"en\":\"Alpha-2 stimulates the norepinephrine transporter (NET) to accelerate reuptake, without affecting presynaptic calcium channels.\"},\"feedback\":{\"tr\":\"Yanlış. NET sodyum bağımlı bir taşıyıcıdır; alfa-2 ise spesifik olarak voltaj kapılı kalsiyum kanallarını kapatarak ekzositozu durdurur.\",\"ar\":\"غير صحيح. ناقل NET يعتمد على الصوديوم مستقلاً عن تأشير Gi؛ يغلق ألفا-2 قنوات الكالسيوم المعتمدة على الفولتية ليوقف الإفراز.\",\"en\":\"Incorrect. NET is a secondary active sodium-dependent symporter; alpha-2 specifically closes voltage-gated calcium channels.\"}}],\"prompt\":{\"tr\":\"Sempatik sinaptik aralıkta biriken noradrenalin, hangi fizyolojik otoreseptör mekanizmasıyla aşırı nörotransmiter salınımını durdurur?\",\"ar\":\"عندما يتراكم النورإبينفرين في الشق المشبكي الودي، ما هي آلية المستقبل الذاتي الفسيولوجية التي توقف التحرر المفرط للناقل؟\",\"en\":\"When exocytosed norepinephrine accumulates in the sympathetic synaptic cleft, what physiological autoreceptor mechanism halts excessive neurotransmitter release?\"},\"title\":{\"tr\":\"Rehberli Keşif: Presinaptik Alfa-2 Otoreseptör Freni\",\"ar\":\"استكشاف موجه: كابح مستقبل ألفا-2 الذاتي قبل المشبكي\",\"en\":\"Guided Discovery: Presynaptic Alpha-2 Autoreceptor Brake\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":14}]},{\"id\":\"pharm-mod4-les1-step7\",\"order\":7,\"stageIndex\":7,\"stage\":\"formal_explanation\",\"type\":\"formal_explanation\",\"title\":{\"tr\":\"Biçimsel Açıklama: Kanonik Adrenerjik Reseptör Sınıflandırması\",\"ar\":\"شرح رسمي: التصنيف المعياري للمستقبلات الأدرينالينية\",\"en\":\"Formal Explanation: Canonical Adrenoceptor Classification\"},\"prompt\":{\"tr\":\"Kanonik adrenerjik reseptör tablosunu inceleyin. Hangi eşleştirme bir reseptör alt tipini, primer G-proteinini ve klinik fizyolojik etkisini doğru gösterir?\",\"ar\":\"راجع جدول المستقبلات الأدرينالينية. أي اقتران يربط بدقة بين نمط المستقبل، وبروتينه المقترن G، وتأثيره الفسيولوجي السريري؟\",\"en\":\"Review the canonical adrenoceptor table. Which pairing correctly maps an adrenoceptor subtype to its primary G-protein transducer and clinical physiological action?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Hangi adrenerjik reseptör eşleştirmesi G-proteini ve fizyolojik etkisiyle tamamen doğrudur?\",\"ar\":\"أي اقتران للمستقبلات الأدرينالينية صحيح تماماً مع بروتين G وتأثيره الفسيولوجي؟\",\"en\":\"Which adrenoceptor pairing is fully accurate regarding its G-protein and physiological response?\"},\"options\":[{\"id\":\"opt-l7-s7-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Beta-1 (Gs): Kardiyak inotropi/kronotropiyi artırır ve renal jukstaglomerüler hücrelerden renin salınımını tetikler.\",\"ar\":\"بيتا-1 (Gs): يزيد قلوصية وسرعة القلب ويحفز تحرر الرينين من الخلايا المجاورة للكبيبات الكلوية.\",\"en\":\"Beta-1 (Gs): Increases cardiac inotropy/chronotropy and triggers renin release from renal juxtaglomerular cells.\"},\"feedback\":{\"tr\":\"Doğru. Beta-1 miyokard ve böbrek jukstaglomerüler aparatında Gs ile cAMP'yi artırarak kasılmayı ve renin salgısını uyarır.\",\"ar\":\"صحيح. يقترن بيتا-1 بـ Gs في القلب والكلى لزيادة cAMP وتحفيز القلوصية وإفراز الرينين.\",\"en\":\"Correct. Beta-1 couples to Gs in myocardium and juxtaglomerular apparatus, elevating cAMP to boost contractility and renin release.\"}},{\"id\":\"opt-l7-s7-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Alfa-1 (Gi): Damar tonusunu inhibe ederek bronş dilatasyonuna ve sistemik postural hipotansiyona yol açar.\",\"ar\":\"ألفا-1 (Gi): يثبط المقوية الوعائية، مسبباً توسعاً شُعبياً وهبوط ضغط انتصابي جهازي.\",\"en\":\"Alpha-1 (Gi): Inhibits vascular tone, causing bronchial dilation and systemic postural hypotension.\"},\"feedback\":{\"tr\":\"Yanlış. Alfa-1 Gi'ye değil Gq'ya kenetlenir ve damar düz kasını kuvvetle kasarak tansiyonu yükseltir.\",\"ar\":\"غير صحيح. يقترن ألفا-1 بـ Gq (وليس Gi) ويسبب تضيقاً وعائياً عاتياً رافعاً ضغط الدم.\",\"en\":\"Incorrect. Alpha-1 couples to Gq (not Gi) and causes intense vascular smooth muscle constriction, raising blood pressure.\"}},{\"id\":\"opt-l7-s7-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Beta-2 (Gq): Fosfolipaz C'yi aktive ederek hava yolu düz kas kasılmasına ve astım krizine yol açar.\",\"ar\":\"بيتا-2 (Gq): ينشط فوسفوليباز C ليحفز انقباض العضلات الملساء في المسالك التنفسية وتفاقم الربو.\",\"en\":\"Beta-2 (Gq): Activates phospholipase C to trigger airway smooth muscle contraction and asthma exacerbation.\"},\"feedback\":{\"tr\":\"Yanlış. Beta-2 Gs'ye kenetlenir ve cAMP'yi artırarak bronş düz kasını gevşetir; bu nedenle beta-2 agonistleri astımda kullanılır.\",\"ar\":\"غير صحيح. يقترن بيتا-2 بـ Gs رافعاً cAMP ليرخي عضلات الشعب الملساء، ولهذا تستخدم منبهات بيتا-2 لعلاج الربو.\",\"en\":\"Incorrect. Beta-2 couples to Gs (not Gq); it increases cAMP to relax airway smooth muscle, which is why agonists treat asthma.\"}}]},\"technicalTerms\":[{\"term\":\"Pozitif İnotropi\",\"arContext\":\"تعزيز التقلص العضلي القلبي (Positive Inotropy)\"}],\"hints\":[{\"tier\":1,\"tr\":\"G-protein eşleşme kuralını hatırlayın: alfa-1 (Gq), alfa-2 (Gi), beta-1/2/3 (Gs).\",\"ar\":\"تذكر قاعدة اقتران بروتينات G: ألفا-1 (Gq)، ألفا-2 (Gi)، وبيتا-1/2/3 (Gs).\",\"en\":\"Remember the G-protein pairing mnemonic: alpha-1 (Gq), alpha-2 (Gi), beta-1/2/3 (Gs).\"},{\"tier\":2,\"tr\":\"Beta-1 reseptörleri kalpte ve böbrekte bulunur; Gs üzerinden cAMP artışı yaratır.\",\"ar\":\"توجد مستقبلات بيتا-1 في القلب والكلية؛ وتحدث زيادة في cAMP عبر بروتين Gs.\",\"en\":\"Beta-1 receptors reside in the heart and kidneys; they elevate cAMP via Gs.\"},{\"tier\":3,\"tr\":\"Beta-1 Gs'ye kenetlenir; miyokardiyal inotropi/kronotropiyi artırır ve jukstaglomerüler hücrelerden renin salınımını uyarır.\",\"ar\":\"يقترن بيتا-1 بـ Gs؛ معززاً قلوصية وسرعة القلب ومحفزاً تحرر الرينين من الخلايا المجاورة للكبيبات الكلوية.\",\"en\":\"Beta-1 (Gs): Increases cardiac inotropy/chronotropy and triggers renin release from renal juxtaglomerular cells.\"}],\"config\":{\"options\":[{\"id\":\"opt-l7-s7-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Beta-1 (Gs): Kardiyak inotropi/kronotropiyi artırır ve renal jukstaglomerüler hücrelerden renin salınımını tetikler.\",\"ar\":\"بيتا-1 (Gs): يزيد قلوصية وسرعة القلب ويحفز تحرر الرينين من الخلايا المجاورة للكبيبات الكلوية.\",\"en\":\"Beta-1 (Gs): Increases cardiac inotropy/chronotropy and triggers renin release from renal juxtaglomerular cells.\"},\"feedback\":{\"tr\":\"Doğru. Beta-1 miyokard ve böbrek jukstaglomerüler aparatında Gs ile cAMP'yi artırarak kasılmayı ve renin salgısını uyarır.\",\"ar\":\"صحيح. يقترن بيتا-1 بـ Gs في القلب والكلى لزيادة cAMP وتحفيز القلوصية وإفراز الرينين.\",\"en\":\"Correct. Beta-1 couples to Gs in myocardium and juxtaglomerular apparatus, elevating cAMP to boost contractility and renin release.\"}},{\"id\":\"opt-l7-s7-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Alfa-1 (Gi): Damar tonusunu inhibe ederek bronş dilatasyonuna ve sistemik postural hipotansiyona yol açar.\",\"ar\":\"ألفا-1 (Gi): يثبط المقوية الوعائية، مسبباً توسعاً شُعبياً وهبوط ضغط انتصابي جهازي.\",\"en\":\"Alpha-1 (Gi): Inhibits vascular tone, causing bronchial dilation and systemic postural hypotension.\"},\"feedback\":{\"tr\":\"Yanlış. Alfa-1 Gi'ye değil Gq'ya kenetlenir ve damar düz kasını kuvvetle kasarak tansiyonu yükseltir.\",\"ar\":\"غير صحيح. يقترن ألفا-1 بـ Gq (وليس Gi) ويسبب تضيقاً وعائياً عاتياً رافعاً ضغط الدم.\",\"en\":\"Incorrect. Alpha-1 couples to Gq (not Gi) and causes intense vascular smooth muscle constriction, raising blood pressure.\"}},{\"id\":\"opt-l7-s7-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Beta-2 (Gq): Fosfolipaz C'yi aktive ederek hava yolu düz kas kasılmasına ve astım krizine yol açar.\",\"ar\":\"بيتا-2 (Gq): ينشط فوسفوليباز C ليحفز انقباض العضلات الملساء في المسالك التنفسية وتفاقم الربو.\",\"en\":\"Beta-2 (Gq): Activates phospholipase C to trigger airway smooth muscle contraction and asthma exacerbation.\"},\"feedback\":{\"tr\":\"Yanlış. Beta-2 Gs'ye kenetlenir ve cAMP'yi artırarak bronş düz kasını gevşetir; bu nedenle beta-2 agonistleri astımda kullanılır.\",\"ar\":\"غير صحيح. يقترن بيتا-2 بـ Gs رافعاً cAMP ليرخي عضلات الشعب الملساء، ولهذا تستخدم منبهات بيتا-2 لعلاج الربو.\",\"en\":\"Incorrect. Beta-2 couples to Gs (not Gq); it increases cAMP to relax airway smooth muscle, which is why agonists treat asthma.\"}}],\"prompt\":{\"tr\":\"Kanonik adrenerjik reseptör tablosunu inceleyin. Hangi eşleştirme bir reseptör alt tipini, primer G-proteinini ve klinik fizyolojik etkisini doğru gösterir?\",\"ar\":\"راجع جدول المستقبلات الأدرينالينية. أي اقتران يربط بدقة بين نمط المستقبل، وبروتينه المقترن G، وتأثيره الفسيولوجي السريري؟\",\"en\":\"Review the canonical adrenoceptor table. Which pairing correctly maps an adrenoceptor subtype to its primary G-protein transducer and clinical physiological action?\"},\"title\":{\"tr\":\"Biçimsel Açıklama: Kanonik Adrenerjik Reseptör Sınıflandırması\",\"ar\":\"شرح رسمي: التصنيف المعياري للمستقبلات الأدرينالينية\",\"en\":\"Formal Explanation: Canonical Adrenoceptor Classification\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":15}]},{\"id\":\"pharm-mod4-les1-step8\",\"order\":8,\"stageIndex\":8,\"stage\":\"concept_check\",\"type\":\"concept_check\",\"title\":{\"tr\":\"Kavram Kontrolü: Astımlı Hastalarda Propranolol Tehlikesi\",\"ar\":\"تحقق مفاهيمي: خطر البروبرانولول على مرضى الربو\",\"en\":\"Concept Check: Propranolol Hazard in Asthmatic Patients\"},\"prompt\":{\"tr\":\"Bir astım hastasına non-selektif beta-bloker propranolol verilirse, hangi moleküler olay yaşamı tehdit eden bronkospazmı tetikler?\",\"ar\":\"إذا تلقى مريض ربو حاصر بيتا غير الانتقائي بروبرانولول، ما هو الحدث الجزيئي الدقيق الذي يثير تشنجاً قصبياً مهدداً للحياة؟\",\"en\":\"If an asthmatic patient receives the non-selective beta-blocker propranolol, what precise molecular event precipitates life-threatening bronchospasm?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Propranolol astım hastalarında neden ölümcül bronkospazma yol açabilir?\",\"ar\":\"لماذا يمكن أن يسبب البروبرانولول تشنجاً قصبياً قاتلاً لدى مرضى الربو؟\",\"en\":\"Why can propranolol trigger fatal bronchospasm in patients with asthma?\"},\"options\":[{\"id\":\"opt-l7-s8-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Propranolol hava yolu beta-2 reseptörlerini yarışmalı bloke eder, bazal cAMP'yi düşürür ve koruyucu bronkodilatör tonusu ortadan kaldırır.\",\"ar\":\"يحصر البروبرانولول تنافسياً مستقبلات بيتا-2 الشعبية، خافضاً cAMP القاعدي ومزيلاً مقوية التوسع القصبي الحامية.\",\"en\":\"Propranolol competitively blocks airway beta-2 receptors, decreasing basal cAMP and removing the protective bronchodilatory tone.\"},\"feedback\":{\"tr\":\"Doğru. Non-selektif beta-blokerler hava yolundaki beta-2 reseptörlerini bloke ederek sempatik bronkodilatasyon güvencesini yıkar.\",\"ar\":\"صحيح. تحصر حاصرات بيتا غير الانتقائية مستقبلات بيتا-2 التنفسية، مدمرة صمام الأمان الموسع للشعب.\",\"en\":\"Correct. Non-selective beta-blockers block airway beta-2 receptors, abolishing bronchodilatory tone.\"}},{\"id\":\"opt-l7-s8-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Propranolol bronş bezlerindeki muskarinik M3 reseptörlerinde doğrudan agonist gibi davranarak aşırı mukus salgısını tetikler.\",\"ar\":\"يعمل البروبرانولول كمنبه مباشر لمستقبلات M3 الموسكارينية في الغدد الشعبية، محفزاً فرط الإفراز المخاطي.\",\"en\":\"Propranolol acts as a direct agonist at muscarinic M3 receptors on bronchial glands, stimulating mucus hypersecretion.\"},\"feedback\":{\"tr\":\"Yanlış. Propranololün muskarinik reseptörlerde agonist afinitesi yoktur; spazm beta-2 gevşeme tonusunun kaybından doğar.\",\"ar\":\"غير صحيح. ليس للبروبرانولول ألفة تنبيهية للمستقبلات الموسكارينية؛ ينجم التشنج عن فقدان مقوية الارتخاء بـ بيتا-2.\",\"en\":\"Incorrect. Propranolol has no agonist affinity for muscarinic receptors; bronchospasm is caused by loss of beta-2 mediated dilation.\"}},{\"id\":\"opt-l7-s8-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Propranolol, normalde hava yolunda histamin salınımını baskılayan bronşiyal beta-1 reseptörlerini selektif olarak bloke eder.\",\"ar\":\"يحصر البروبرانولول انتقائياً مستقبلات بيتا-1 الشعبية التي تثبط عادة تحرر الهيستامين في القصبات.\",\"en\":\"Propranolol selectively blocks bronchial beta-1 receptors, which normally suppress airway histamine release.\"},\"feedback\":{\"tr\":\"Yanlış. Hava yolu düz kası esas olarak beta-2 ifade eder, beta-1 değil. Bu nedenle kardiyoselektif beta-1 blokerler tercih edilir.\",\"ar\":\"غير صحيح. تعبر العضلات الملساء التنفسية غالباً عن بيتا-2 وليس بيتا-1؛ ولهذا تفضل حاصرات بيتا-1 القلبية النوعية.\",\"en\":\"Incorrect. Airway smooth muscle predominantly expresses beta-2, not beta-1. Cardioselective beta-1 blockers are preferred to spare airways.\"}}]},\"technicalTerms\":[{\"term\":\"Bronkokonstriksiyon\",\"arContext\":\"تشنج القصبات (Bronchoconstriction)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Propranolol non-selektif bir antagonisttir. İnsan hava yolu düz kasında hangi beta alt tipi baskındır?\",\"ar\":\"البروبرانولول حاصر غير انتقائي. أي نمط فرعي لبيتا يسود في العضلات الملساء للمسالك التنفسية؟\",\"en\":\"Propranolol is a non-selective antagonist. Which beta subtype dominates in human airway smooth muscle?\"},{\"tier\":2,\"tr\":\"Hava yolu düz kası, bazal kolinerjik tonusa karşı gevşek kalabilmek için beta-2 (Gs/cAMP) sinyaline güvenir.\",\"ar\":\"تعتمد العضلات الملساء التنفسية على تأشير بيتا-2 (Gs/cAMP) لتبقى مرتخية في وجه المقوية الكولينية.\",\"en\":\"Airway smooth muscle depends on beta-2 signaling (via Gs and cAMP) to stay relaxed against baseline cholinergic tone.\"},{\"tier\":3,\"tr\":\"Bronşiyal beta-2 reseptörlerinin bloke edilmesi hücre içi cAMP'yi düşürür, PKA'yı kapatır ve engelsiz bronkokonstriksiyona yol açar.\",\"ar\":\"يحصر البروبرانولول مستقبلات بيتا-2 الشعبية، خافضاً cAMP ومثبطاً PKA، مما يسمح بحدوث تضيق قصبي غير معارض.\",\"en\":\"Blocking bronchial beta-2 receptors drops intracellular cAMP, inactivates PKA, and permits unopposed bronchoconstriction.\"}],\"config\":{\"options\":[{\"id\":\"opt-l7-s8-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Propranolol hava yolu beta-2 reseptörlerini yarışmalı bloke eder, bazal cAMP'yi düşürür ve koruyucu bronkodilatör tonusu ortadan kaldırır.\",\"ar\":\"يحصر البروبرانولول تنافسياً مستقبلات بيتا-2 الشعبية، خافضاً cAMP القاعدي ومزيلاً مقوية التوسع القصبي الحامية.\",\"en\":\"Propranolol competitively blocks airway beta-2 receptors, decreasing basal cAMP and removing the protective bronchodilatory tone.\"},\"feedback\":{\"tr\":\"Doğru. Non-selektif beta-blokerler hava yolundaki beta-2 reseptörlerini bloke ederek sempatik bronkodilatasyon güvencesini yıkar.\",\"ar\":\"صحيح. تحصر حاصرات بيتا غير الانتقائية مستقبلات بيتا-2 التنفسية، مدمرة صمام الأمان الموسع للشعب.\",\"en\":\"Correct. Non-selective beta-blockers block airway beta-2 receptors, abolishing bronchodilatory tone.\"}},{\"id\":\"opt-l7-s8-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Propranolol bronş bezlerindeki muskarinik M3 reseptörlerinde doğrudan agonist gibi davranarak aşırı mukus salgısını tetikler.\",\"ar\":\"يعمل البروبرانولول كمنبه مباشر لمستقبلات M3 الموسكارينية في الغدد الشعبية، محفزاً فرط الإفراز المخاطي.\",\"en\":\"Propranolol acts as a direct agonist at muscarinic M3 receptors on bronchial glands, stimulating mucus hypersecretion.\"},\"feedback\":{\"tr\":\"Yanlış. Propranololün muskarinik reseptörlerde agonist afinitesi yoktur; spazm beta-2 gevşeme tonusunun kaybından doğar.\",\"ar\":\"غير صحيح. ليس للبروبرانولول ألفة تنبيهية للمستقبلات الموسكارينية؛ ينجم التشنج عن فقدان مقوية الارتخاء بـ بيتا-2.\",\"en\":\"Incorrect. Propranolol has no agonist affinity for muscarinic receptors; bronchospasm is caused by loss of beta-2 mediated dilation.\"}},{\"id\":\"opt-l7-s8-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Propranolol, normalde hava yolunda histamin salınımını baskılayan bronşiyal beta-1 reseptörlerini selektif olarak bloke eder.\",\"ar\":\"يحصر البروبرانولول انتقائياً مستقبلات بيتا-1 الشعبية التي تثبط عادة تحرر الهيستامين في القصبات.\",\"en\":\"Propranolol selectively blocks bronchial beta-1 receptors, which normally suppress airway histamine release.\"},\"feedback\":{\"tr\":\"Yanlış. Hava yolu düz kası esas olarak beta-2 ifade eder, beta-1 değil. Bu nedenle kardiyoselektif beta-1 blokerler tercih edilir.\",\"ar\":\"غير صحيح. تعبر العضلات الملساء التنفسية غالباً عن بيتا-2 وليس بيتا-1؛ ولهذا تفضل حاصرات بيتا-1 القلبية النوعية.\",\"en\":\"Incorrect. Airway smooth muscle predominantly expresses beta-2, not beta-1. Cardioselective beta-1 blockers are preferred to spare airways.\"}}],\"prompt\":{\"tr\":\"Bir astım hastasına non-selektif beta-bloker propranolol verilirse, hangi moleküler olay yaşamı tehdit eden bronkospazmı tetikler?\",\"ar\":\"إذا تلقى مريض ربو حاصر بيتا غير الانتقائي بروبرانولول، ما هو الحدث الجزيئي الدقيق الذي يثير تشنجاً قصبياً مهدداً للحياة؟\",\"en\":\"If an asthmatic patient receives the non-selective beta-blocker propranolol, what precise molecular event precipitates life-threatening bronchospasm?\"},\"title\":{\"tr\":\"Kavram Kontrolü: Astımlı Hastalarda Propranolol Tehlikesi\",\"ar\":\"تحقق مفاهيمي: خطر البروبرانولول على مرضى الربو\",\"en\":\"Concept Check: Propranolol Hazard in Asthmatic Patients\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":16}]},{\"id\":\"pharm-mod4-les1-step9\",\"order\":9,\"stageIndex\":9,\"stage\":\"application\",\"type\":\"clinical_vignette\",\"title\":{\"tr\":\"Klinik Vaka: Feokromositomada Blokaj Sıralaması\",\"ar\":\"حالة سريرية: تسلسل الحصر في ورم القواتم\",\"en\":\"Clinical Vignette: Sequencing Blockade in Pheochromocytoma\"},\"prompt\":{\"tr\":\"Feokromositoma hastasında sinüs taşikardisi gelişir. Bir asistan alfa-blokaj sağlamadan ÖNCE IV propranolol uygular. Tansiyon neden aniden 260/150 mmHg'ye fırlar?\",\"ar\":\"مريض ورم القواتم أصيب بتسرع قلب جيبي. أعطى الطبيب بروبرانولول وريدياً قبل تثبيت حصر ألفا. لماذا قفز ضغط الدم فجأة إلى 260/150 مم زئبق؟\",\"en\":\"A pheochromocytoma patient develops sinus tachycardia. A resident administers IV propranolol BEFORE establishing alpha-blockade. Why does BP surge to 260/150 mmHg?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Feokromositomada alfa-blokaj öncesi beta-bloker verilmesi neden hipertansif krize yol açar?\",\"ar\":\"لماذا يؤدي إعطاء حاصر بيتا قبل حصر ألفا في ورم القواتم إلى أزمة فرط ضغط دموي؟\",\"en\":\"Why does administering a beta-blocker prior to alpha-blockade precipitate a hypertensive crisis in pheochromocytoma?\"},\"options\":[{\"id\":\"opt-l7-s9-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Beta-2 vazodilatasyonunun bloke edilmesi, dolaşımdaki katekolaminlerin damar alfa-1 reseptörlerini tamamen engelsiz uyarmasına yol açarak feci vazokonstriksiyonu tetikler.\",\"ar\":\"إلغاء توسع بيتا-2 يترك الكاتيكولامينات الجائلة تنبه مستقبلات ألفا-1 الوعائية دون أي معارضة، مسببة تضيقاً وعائياً كارثياً.\",\"en\":\"Blocking beta-2 vasodilation leaves circulating catecholamines to stimulate vascular alpha-1 receptors completely unopposed, triggering catastrophic vasoconstriction.\"},\"feedback\":{\"tr\":\"Doğru. Ölümcül feokromositoma tuzağı: beta bloker beta-2 gevşemesini siler ve devasa tümör katekolaminleri alfa-1'i tek başına kasarak krize sokar.\",\"ar\":\"صحيح. فخ ورم القواتم القاتل: يزيل حاصر بيتا صمام أمان التوسع الوعائي، مما يتيح لكوكبة الكاتيكولامينات إحداث تضيق وعائي ألفا-1 عاتٍ دون معارضة.\",\"en\":\"Correct. The lethal pheochromocytoma trap: beta-blockers remove the beta-2 vasodilatory buffer, allowing catecholamines to drive unmitigated alpha-1 vasoconstriction.\"}},{\"id\":\"opt-l7-s9-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Propranolol tümör membranını geçerek tirozin hidroksilazı doğrudan uyarır ve saniyeler içinde katekolamin sentezini iki katına çıkarır.\",\"ar\":\"يعبر البروبرانولول غشاء الورم ليحفز تيروزين هيدروكسيلاز مباشرة، مضاعفاً اصطناع الكاتيكولامينات خلال ثوانٍ.\",\"en\":\"Propranolol crosses the tumor membrane to directly stimulate tyrosine hydroxylase, doubling catecholamine synthesis within seconds.\"},\"feedback\":{\"tr\":\"Yanlış. Propranolol tirozin hidroksilazı uyarmaz; kriz tamamen hemodinamiktir ve beta-2 tamponunun kaybından kaynaklanır.\",\"ar\":\"غير صحيح. لا يحفز البروبرانولول اصطناع الكاتيكولامينات؛ بل الأزمة ديناميكية دموية بحتة ناجمة عن حصر توسع بيتا-2.\",\"en\":\"Incorrect. Propranolol does not stimulate tyrosine hydroxylase; the surge is purely hemodynamic due to unmasked vascular alpha-1 constriction.\"}},{\"id\":\"opt-l7-s9-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Propranolol kaynaklı bradikardi, sempatik sinirleri aşırı seviyede ateşleyen şiddetli bir baroreseptör refleksini tetikler.\",\"ar\":\"يؤدي بطء القلب الناجم عن البروبرانولول إلى إطلاق منعكس مستقبِلات الضغط الشديد الذي ينشط الأعصاب الودية إلى أقصى حد.\",\"en\":\"Propranolol-induced bradycardia triggers an intense baroreceptor reflex that fires sympathetic nerves to extreme levels.\"},\"feedback\":{\"tr\":\"Yanlış. Baroreseptör refleksi tansiyon düşüşünde ateşlenir; burada dolaşımdaki katekolaminler zaten doymuştur ve beta-2 tamponu yok olmuştur.\",\"ar\":\"غير صحيح. يستجيب منعكس الضغط لتغيرات الضغط الشرياني وليس معدل النبض؛ والأزمة ناتجة عن فقدان التوسع الوعائي بـ بيتا-2.\",\"en\":\"Incorrect. The baroreceptor reflex responds to arterial pressure drops; the crisis stems entirely from losing beta-2 vasodilation.\"}}]},\"technicalTerms\":[{\"term\":\"Karşılanmamış Alfa Uyarımı\",\"arContext\":\"تحفيز ألفا غير المعارض (Unopposed Alpha Stimulation)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Feokromositoma tedavisinin temel kuralını hatırlayın: Alfa blokaj daima Beta blokajdan ÖNCE gelmelidir ('Önce A, Sonra B').\",\"ar\":\"تذكر القاعدة الذهبية في علاج ورم القواتم: يجب أن يسبق حصر ألفا دائماً حصر بيتا ('A قبل B').\",\"en\":\"Remember the cardinal rule of pheochromocytoma management: Alpha blockade MUST always precede Beta blockade ('A before B').\"},{\"tier\":2,\"tr\":\"Dolaşımdaki epinefrin hem alfa-1 (büzücü) hem beta-2 (genişletici) uyarır. Yalnızca beta-2'yi silerseniz ne olur?\",\"ar\":\"ينبه الإبينفرين كلاً من ألفا-1 (مضيق) وبيتا-2 (موسع). ماذا يحدث للمقاومة عندما تلغي مكون بيتا-2 فقط؟\",\"en\":\"Epinephrine stimulates both alpha-1 (vasoconstriction) and beta-2 (vasodilation). What happens when you remove only the beta-2 component?\"},{\"tier\":3,\"tr\":\"Beta-2 vazodilatasyonunun ortadan kalkması, aşırı dolaşan katekolaminlerin damar alfa-1 reseptörlerini tamamen engelsiz uyarmasına yol açar.\",\"ar\":\"إلغاء توسع بيتا-2 الوعائي يترك فيض الكاتيكولامينات الجائلة ينبه مستقبلات ألفا-1 الوعائية دون معارضة، مسبباً أزمة فرط ضغط عاتية.\",\"en\":\"Eliminating beta-2 vasodilation unmasks massive, unopposed alpha-1 vascular constriction from circulating catecholamines, triggering a hypertensive emergency.\"}],\"config\":{\"options\":[{\"id\":\"opt-l7-s9-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Beta-2 vazodilatasyonunun bloke edilmesi, dolaşımdaki katekolaminlerin damar alfa-1 reseptörlerini tamamen engelsiz uyarmasına yol açarak feci vazokonstriksiyonu tetikler.\",\"ar\":\"إلغاء توسع بيتا-2 يترك الكاتيكولامينات الجائلة تنبه مستقبلات ألفا-1 الوعائية دون أي معارضة، مسببة تضيقاً وعائياً كارثياً.\",\"en\":\"Blocking beta-2 vasodilation leaves circulating catecholamines to stimulate vascular alpha-1 receptors completely unopposed, triggering catastrophic vasoconstriction.\"},\"feedback\":{\"tr\":\"Doğru. Ölümcül feokromositoma tuzağı: beta bloker beta-2 gevşemesini siler ve devasa tümör katekolaminleri alfa-1'i tek başına kasarak krize sokar.\",\"ar\":\"صحيح. فخ ورم القواتم القاتل: يزيل حاصر بيتا صمام أمان التوسع الوعائي، مما يتيح لكوكبة الكاتيكولامينات إحداث تضيق وعائي ألفا-1 عاتٍ دون معارضة.\",\"en\":\"Correct. The lethal pheochromocytoma trap: beta-blockers remove the beta-2 vasodilatory buffer, allowing catecholamines to drive unmitigated alpha-1 vasoconstriction.\"}},{\"id\":\"opt-l7-s9-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Propranolol tümör membranını geçerek tirozin hidroksilazı doğrudan uyarır ve saniyeler içinde katekolamin sentezini iki katına çıkarır.\",\"ar\":\"يعبر البروبرانولول غشاء الورم ليحفز تيروزين هيدروكسيلاز مباشرة، مضاعفاً اصطناع الكاتيكولامينات خلال ثوانٍ.\",\"en\":\"Propranolol crosses the tumor membrane to directly stimulate tyrosine hydroxylase, doubling catecholamine synthesis within seconds.\"},\"feedback\":{\"tr\":\"Yanlış. Propranolol tirozin hidroksilazı uyarmaz; kriz tamamen hemodinamiktir ve beta-2 tamponunun kaybından kaynaklanır.\",\"ar\":\"غير صحيح. لا يحفز البروبرانولول اصطناع الكاتيكولامينات؛ بل الأزمة ديناميكية دموية بحتة ناجمة عن حصر توسع بيتا-2.\",\"en\":\"Incorrect. Propranolol does not stimulate tyrosine hydroxylase; the surge is purely hemodynamic due to unmasked vascular alpha-1 constriction.\"}},{\"id\":\"opt-l7-s9-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Propranolol kaynaklı bradikardi, sempatik sinirleri aşırı seviyede ateşleyen şiddetli bir baroreseptör refleksini tetikler.\",\"ar\":\"يؤدي بطء القلب الناجم عن البروبرانولول إلى إطلاق منعكس مستقبِلات الضغط الشديد الذي ينشط الأعصاب الودية إلى أقصى حد.\",\"en\":\"Propranolol-induced bradycardia triggers an intense baroreceptor reflex that fires sympathetic nerves to extreme levels.\"},\"feedback\":{\"tr\":\"Yanlış. Baroreseptör refleksi tansiyon düşüşünde ateşlenir; burada dolaşımdaki katekolaminler zaten doymuştur ve beta-2 tamponu yok olmuştur.\",\"ar\":\"غير صحيح. يستجيب منعكس الضغط لتغيرات الضغط الشرياني وليس معدل النبض؛ والأزمة ناتجة عن فقدان التوسع الوعائي بـ بيتا-2.\",\"en\":\"Incorrect. The baroreceptor reflex responds to arterial pressure drops; the crisis stems entirely from losing beta-2 vasodilation.\"}}],\"prompt\":{\"tr\":\"Feokromositoma hastasında sinüs taşikardisi gelişir. Bir asistan alfa-blokaj sağlamadan ÖNCE IV propranolol uygular. Tansiyon neden aniden 260/150 mmHg'ye fırlar?\",\"ar\":\"مريض ورم القواتم أصيب بتسرع قلب جيبي. أعطى الطبيب بروبرانولول وريدياً قبل تثبيت حصر ألفا. لماذا قفز ضغط الدم فجأة إلى 260/150 مم زئبق؟\",\"en\":\"A pheochromocytoma patient develops sinus tachycardia. A resident administers IV propranolol BEFORE establishing alpha-blockade. Why does BP surge to 260/150 mmHg?\"},\"title\":{\"tr\":\"Klinik Vaka: Feokromositomada Blokaj Sıralaması\",\"ar\":\"حالة سريرية: تسلسل الحصر في ورم القواتم\",\"en\":\"Clinical Vignette: Sequencing Blockade in Pheochromocytoma\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":17}]},{\"id\":\"pharm-mod4-les1-step10\",\"order\":10,\"stageIndex\":10,\"stage\":\"retrieval\",\"type\":\"retrieval\",\"title\":{\"tr\":\"Geri Çağırma: Alfa-1 Sinyal Kaskadı\",\"ar\":\"استرجاع: شلال تأشير ألفا-1\",\"en\":\"Retrieval: Alpha-1 Signaling Cascade\"},\"prompt\":{\"tr\":\"Hangi ikinci haberci dizisi, alfa-1 adrenerjik reseptör aktivasyonunu takiben vazokonstriksiyonu tetikleyen moleküler kaskadı doğru sıralar?\",\"ar\":\"أي تسلسل للمرسال الثاني يوضح بدقة الشلال الجزيئي المحفز للتضيق الوعائي عقب تفعيل مستقبل ألفا-1 الأدريناليني؟\",\"en\":\"Which second messenger sequence correctly outlines the molecular cascade triggering vasoconstriction following alpha-1 adrenergic receptor activation?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Alfa-1 vazokonstriksiyonunun hücre içi iletim basamakları hangisidir?\",\"ar\":\"ما هي المراحل الخلوية لتأشير التضيق الوعائي عبر مستقبلات ألفا-1؟\",\"en\":\"What is the intracellular signaling sequence mediating alpha-1 vasoconstriction?\"},\"options\":[{\"id\":\"opt-l7-s10-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Gq aktivasyonu -> Fosfolipaz C (PLC) -> IP3 ve DAG -> IP3 kapılı ER Ca2+ salınımı -> Ca2+-kalmodulin MLCK'yi aktive eder -> Kasılma.\",\"ar\":\"تفعيل Gq -> فوسفوليباز C -> تشكل IP3 وDAG -> تحرر Ca2+ من الشبكة الإندوبلازمية عبر IP3 -> كالمديولين ينشط MLCK -> انقباض.\",\"en\":\"Gq activation -> Phospholipase C (PLC) -> IP3 and DAG -> IP3-gated ER Ca2+ release -> Ca2+-calmodulin activates MLCK -> Contraction.\"},\"feedback\":{\"tr\":\"Doğru. Alfa-1 Gq ile PLC-beta'yı aktive eder, açığa çıkan IP3 kalsiyumu salarak kalmodulin ve MLCK ile kasılmayı başlatır.\",\"ar\":\"صحيح. يقترن ألفا-1 بـ Gq لتنشيط PLC-بيتا، حيث يحرر IP3 الكالسيوم ليفعل الكالموديولين و MLCK مسبباً الانقباض.\",\"en\":\"Correct. Alpha-1 couples to Gq to activate PLC-beta, generating IP3 to release calcium and stimulate MLCK via calmodulin.\"}},{\"id\":\"opt-l7-s10-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Gs aktivasyonu -> Adenilat siklaz -> cAMP artışı -> Protein Kinaz A aktivasyonu -> Troponin fosforilasyonu -> Kasılma.\",\"ar\":\"تفعيل Gs -> محلقة الأدينيلات -> ارتفاع cAMP -> تنشيط بروتين كيناز A -> فسفرة التروponin -> انقباض.\",\"en\":\"Gs activation -> Adenylyl cyclase -> cAMP elevation -> Protein Kinase A activation -> Phosphorylation of troponin -> Contraction.\"},\"feedback\":{\"tr\":\"Yanlış. Gs/cAMP/PKA düz kasta kasılma değil gevşeme yapar; ayrıca damar düz kasında troponin bulunmaz, kalmodulin bulunur.\",\"ar\":\"غير صحيح. مسار Gs/cAMP/PKA يسبب الارتخاء في العضلة الملساء وليس الانقباض؛ كما تفتقر العضلة الملساء للتروبونين.\",\"en\":\"Incorrect. Gs/cAMP/PKA produces smooth muscle relaxation (by inhibiting MLCK); smooth muscle lacks troponin, utilizing calmodulin instead.\"}},{\"id\":\"opt-l7-s10-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Gi aktivasyonu -> Çözünür guanilat siklaz -> cGMP artışı -> Protein Kinaz G -> Miyozin defosforilasyonu -> Vazokonstriksiyon.\",\"ar\":\"تفعيل Gi -> محلقة الغوانيلات الذوابة -> تدفق cGMP -> بروتين كيناز G -> نزع فسفرة الميوزين -> تضيق وعائي.\",\"en\":\"Gi activation -> Soluble guanylyl cyclase -> cGMP surge -> Protein Kinase G -> Dephosphorylation of myosin -> Vasoconstriction.\"},\"feedback\":{\"tr\":\"Yanlış. cGMP/PKG yolağı (NO ile uyarılır) vazokonstriksiyon değil vazodilatasyon yapar.\",\"ar\":\"غير صحيح. يسبب مسار cGMP/PKG (المحفز بأكسيد النيتريك) توسعاً وعائياً وليس تضيقاً.\",\"en\":\"Incorrect. The cGMP/PKG pathway causes vasodilation, not vasoconstriction. Alpha-1 signals through Gq and IP3/Ca2+.\"}}]},\"technicalTerms\":[{\"term\":\"Fosfolipaz C\",\"arContext\":\"فوسفوليباز C (Phospholipase C (PLC))\"}],\"hints\":[{\"tier\":1,\"tr\":\"Alfa-1 reseptörleri heterotrimerik Gq proteinine kenetlenir.\",\"ar\":\"تقترن مستقبلات ألفا-1 ببروتين Gq ثلاثي الوحدات المغايرة.\",\"en\":\"Alpha-1 receptors couple to the Gq heterotrimeric G-protein.\"},{\"tier\":2,\"tr\":\"Gq proteini membrana bağlı hangi enzimi uyararak PIP2'yi iki haberciye (IP3 ve DAG) böler?\",\"ar\":\"ما هو الإنزيم الغشائي الذي ينشطه Gq ليشطر PIP2 إلى مرسالين (IP3 و DAG)؟\",\"en\":\"What membrane-bound enzyme does Gq stimulate to cleave PIP2 into IP3 and DAG?\"},{\"tier\":3,\"tr\":\"Gq Fosfolipaz C'yi (PLC) aktive eder, IP3 endoplazmik retikulumdan Ca2+ salar, Ca2+-kalmodulin MLCK'yi aktive ederek kasılma yapar.\",\"ar\":\"ينشط Gq إنزيم فوسفوليباز C مشكلاً IP3 الذي يحرر الكالسيوم؛ وينشط مركب الكالسيوم-كالموديولين إنزيم MLCK ليحدث الانقباض.\",\"en\":\"Gq activates Phospholipase C (PLC), producing IP3 (mobilizing ER Ca2+) and DAG; calcium-calmodulin activates MLCK to contract smooth muscle.\"}],\"config\":{\"options\":[{\"id\":\"opt-l7-s10-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Gq aktivasyonu -> Fosfolipaz C (PLC) -> IP3 ve DAG -> IP3 kapılı ER Ca2+ salınımı -> Ca2+-kalmodulin MLCK'yi aktive eder -> Kasılma.\",\"ar\":\"تفعيل Gq -> فوسفوليباز C -> تشكل IP3 وDAG -> تحرر Ca2+ من الشبكة الإندوبلازمية عبر IP3 -> كالمديولين ينشط MLCK -> انقباض.\",\"en\":\"Gq activation -> Phospholipase C (PLC) -> IP3 and DAG -> IP3-gated ER Ca2+ release -> Ca2+-calmodulin activates MLCK -> Contraction.\"},\"feedback\":{\"tr\":\"Doğru. Alfa-1 Gq ile PLC-beta'yı aktive eder, açığa çıkan IP3 kalsiyumu salarak kalmodulin ve MLCK ile kasılmayı başlatır.\",\"ar\":\"صحيح. يقترن ألفا-1 بـ Gq لتنشيط PLC-بيتا، حيث يحرر IP3 الكالسيوم ليفعل الكالموديولين و MLCK مسبباً الانقباض.\",\"en\":\"Correct. Alpha-1 couples to Gq to activate PLC-beta, generating IP3 to release calcium and stimulate MLCK via calmodulin.\"}},{\"id\":\"opt-l7-s10-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Gs aktivasyonu -> Adenilat siklaz -> cAMP artışı -> Protein Kinaz A aktivasyonu -> Troponin fosforilasyonu -> Kasılma.\",\"ar\":\"تفعيل Gs -> محلقة الأدينيلات -> ارتفاع cAMP -> تنشيط بروتين كيناز A -> فسفرة التروponin -> انقباض.\",\"en\":\"Gs activation -> Adenylyl cyclase -> cAMP elevation -> Protein Kinase A activation -> Phosphorylation of troponin -> Contraction.\"},\"feedback\":{\"tr\":\"Yanlış. Gs/cAMP/PKA düz kasta kasılma değil gevşeme yapar; ayrıca damar düz kasında troponin bulunmaz, kalmodulin bulunur.\",\"ar\":\"غير صحيح. مسار Gs/cAMP/PKA يسبب الارتخاء في العضلة الملساء وليس الانقباض؛ كما تفتقر العضلة الملساء للتروبونين.\",\"en\":\"Incorrect. Gs/cAMP/PKA produces smooth muscle relaxation (by inhibiting MLCK); smooth muscle lacks troponin, utilizing calmodulin instead.\"}},{\"id\":\"opt-l7-s10-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Gi aktivasyonu -> Çözünür guanilat siklaz -> cGMP artışı -> Protein Kinaz G -> Miyozin defosforilasyonu -> Vazokonstriksiyon.\",\"ar\":\"تفعيل Gi -> محلقة الغوانيلات الذوابة -> تدفق cGMP -> بروتين كيناز G -> نزع فسفرة الميوزين -> تضيق وعائي.\",\"en\":\"Gi activation -> Soluble guanylyl cyclase -> cGMP surge -> Protein Kinase G -> Dephosphorylation of myosin -> Vasoconstriction.\"},\"feedback\":{\"tr\":\"Yanlış. cGMP/PKG yolağı (NO ile uyarılır) vazokonstriksiyon değil vazodilatasyon yapar.\",\"ar\":\"غير صحيح. يسبب مسار cGMP/PKG (المحفز بأكسيد النيتريك) توسعاً وعائياً وليس تضيقاً.\",\"en\":\"Incorrect. The cGMP/PKG pathway causes vasodilation, not vasoconstriction. Alpha-1 signals through Gq and IP3/Ca2+.\"}}],\"prompt\":{\"tr\":\"Hangi ikinci haberci dizisi, alfa-1 adrenerjik reseptör aktivasyonunu takiben vazokonstriksiyonu tetikleyen moleküler kaskadı doğru sıralar?\",\"ar\":\"أي تسلسل للمرسال الثاني يوضح بدقة الشلال الجزيئي المحفز للتضيق الوعائي عقب تفعيل مستقبل ألفا-1 الأدريناليني؟\",\"en\":\"Which second messenger sequence correctly outlines the molecular cascade triggering vasoconstriction following alpha-1 adrenergic receptor activation?\"},\"title\":{\"tr\":\"Geri Çağırma: Alfa-1 Sinyal Kaskadı\",\"ar\":\"استرجاع: شلال تأشير ألفا-1\",\"en\":\"Retrieval: Alpha-1 Signaling Cascade\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":18}]},{\"id\":\"pharm-mod4-les1-step11\",\"order\":11,\"stageIndex\":11,\"stage\":\"connection\",\"type\":\"connection\",\"title\":{\"tr\":\"Bütünsel Bağlantı: Renal Beta-1 ve RAAS Entegrasyonu\",\"ar\":\"ترابط شمولي: تكامل بيتا-1 الكلوي مع نظام RAAS\",\"en\":\"Holistic Connection: Renal Beta-1 & RAAS Integration\"},\"prompt\":{\"tr\":\"Böbrek beta-1 adrenerjik reseptörleri, akut sempatik aktivasyonu kan basıncının uzun vadeli endokrin kontrolüne doğrudan nasıl bağlar?\",\"ar\":\"كيف تربط مستقبلات بيتا-1 الأدرينالينية الكلوية مباشرة بين التنشيط الودي الحاد والتنظيم الصماوي طويل الأمد لضغط الدم؟\",\"en\":\"How do renal beta-1 adrenoceptors directly link acute sympathetic nervous activation to long-term endocrine regulation of blood pressure?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Renal beta-1 reseptörleri sempatik sistemi RAAS yolağına nasıl entegre eder?\",\"ar\":\"كيف تدمج مستقبلات بيتا-1 الكلوية الجهاز الودي بشلال RAAS؟\",\"en\":\"How do renal beta-1 receptors integrate sympathetic activation into the RAAS cascade?\"},\"options\":[{\"id\":\"opt-l7-s11-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Jukstaglomerüler hücrelerdeki beta-1 uyarımı renin salınımını tetikler; RAAS kaskadı anjiyotensin II ve aldosteron üreterek basıncı artırır.\",\"ar\":\"يحفز تنبيه بيتا-1 في الخلايا المجاورة للكبيبات تحرر الرينين، منشطاً شلال RAAS لإنتاج أنجيوتنسين II والألدوستيرون.\",\"en\":\"Beta-1 stimulation on juxtaglomerular cells triggers renin release, driving the RAAS cascade to produce angiotensin II and aldosterone.\"},\"feedback\":{\"tr\":\"Doğru. Renal jukstaglomerüler hücreler beta-1 taşır; sempatik uyarım cAMP'yi artırıp renin salarak RAAS eksenini devreye sokar.\",\"ar\":\"صحيح. تحمل الخلايا المجاورة للكبيبات مستقبلات بيتا-1؛ ينشط التنبيه الودي cAMP مفرزاً الرينين ومفعلاً محور RAAS.\",\"en\":\"Correct. Renal juxtaglomerular cells express beta-1 receptors; sympathetic stimulation increases cAMP, releasing renin and activating RAAS.\"}},{\"id\":\"opt-l7-s11-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Böbrek beta-1 reseptörleri, hormonal kaskadlardan bağımsız olarak proksimal tübül sodyum kanallarını doğrudan açar ve sodyumu geri emer.\",\"ar\":\"تفتح مستقبلات بيتا-1 الكلوية قنوات الصوديوم في الأنابيب القريبة مباشرة، معيدة امتصاص الصوديوم بمعزل عن الهرمونات.\",\"en\":\"Renal beta-1 receptors directly open proximal tubular sodium channels, reabsorbing sodium independently of hormonal cascades.\"},\"feedback\":{\"tr\":\"Yanlış. Beta-1 reseptörleri tübüler iyon kanallarını doğrudan açmaz; aldosteron üretimini tetikleyen enzimatik renin salınımını yönetir.\",\"ar\":\"غير صحيح. لا تفتح مستقبلات بيتا-1 قنوات الأنابيب مباشرة؛ بل تتحكم بإفراز الرينين الذي يحفز الألدوستيرون لاحقاً.\",\"en\":\"Incorrect. Beta-1 receptors on juxtaglomerular cells control the enzymatic release of renin, which hormonally drives aldosterone downstream.\"}},{\"id\":\"opt-l7-s11-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Böbrek beta-1 reseptörleri afferent arteriyolleri kasarak GFR'yi sıfırlar ve idrar üretimini tamamen durdurur.\",\"ar\":\"تضيق مستقبلات بيتا-1 الكلوية الشريانات الواردة لإيقاف الترشيح الكبيبي وإلغاء إنتاج البول كلياً.\",\"en\":\"Renal beta-1 receptors vasoconstrict afferent arterioles to shut down GFR and eliminate urine production entirely.\"},\"feedback\":{\"tr\":\"Yanlış. Afferent arteriyol büzülmesi vasküler alfa-1 reseptörleri (Gq) ile olur, beta-1 ile değil.\",\"ar\":\"غير صحيح. يتوسط التضيق الشرياني الوارد مستقبلات ألفا-1 الوعائية (Gq) وليس بيتا-1.\",\"en\":\"Incorrect. Renal afferent arteriolar vasoconstriction is mediated by vascular alpha-1 receptors (Gq), not beta-1.\"}}]},\"technicalTerms\":[{\"term\":\"Renin-Anjiyotensin Sistemi\",\"arContext\":\"نظام الرينين-أنجيوتنسين (Renin-Angiotensin-Aldosterone System (RAAS))\"}],\"hints\":[{\"tier\":1,\"tr\":\"Renal glomerülün afferent arteriyol duvarında bulunan özelleşmiş hücreleri düşünün.\",\"ar\":\"فكر في الخلايا المتخصصة الموجودة في جدار الشريان الوارد للكبيبة الكلوية.\",\"en\":\"Think about the specialized sensory cells situated in the afferent arteriolar wall of the renal glomerulus.\"},{\"tier\":2,\"tr\":\"Bu jukstaglomerüler hücreler, anjiyotensinojen kaskadını başlatan proteolitik bir enzimi (renin) sentezler ve depolar.\",\"ar\":\"تصنع وتخزن هذه الخلايا المجاورة للكبيبات إنزيماً حالاً للبروتين (الرينين) يطلق شلال الأنجيوتنسينوجين.\",\"en\":\"These juxtaglomerular cells store and secrete an aspartic protease enzyme (renin) that initiates the angiotensinogen cascade.\"},{\"tier\":3,\"tr\":\"Jukstaglomerüler beta-1 reseptörleri Gs/cAMP sinyaliyle kana renin salınmasını sağlar; renin RAAS yolağını aktive ederek tansiyonu yükseltir.\",\"ar\":\"تحفز مستقبلات بيتا-1 المجاورة للكبيبات عبر Gs/cAMP إفراز الرينين في الدم؛ مما ينشط محور RAAS لرفع الضغط وحبس الحجم.\",\"en\":\"Juxtaglomerular beta-1 receptors activate Gs/cAMP signaling, triggering the secretion of renin to drive the RAAS pathway.\"}],\"config\":{\"options\":[{\"id\":\"opt-l7-s11-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Jukstaglomerüler hücrelerdeki beta-1 uyarımı renin salınımını tetikler; RAAS kaskadı anjiyotensin II ve aldosteron üreterek basıncı artırır.\",\"ar\":\"يحفز تنبيه بيتا-1 في الخلايا المجاورة للكبيبات تحرر الرينين، منشطاً شلال RAAS لإنتاج أنجيوتنسين II والألدوستيرون.\",\"en\":\"Beta-1 stimulation on juxtaglomerular cells triggers renin release, driving the RAAS cascade to produce angiotensin II and aldosterone.\"},\"feedback\":{\"tr\":\"Doğru. Renal jukstaglomerüler hücreler beta-1 taşır; sempatik uyarım cAMP'yi artırıp renin salarak RAAS eksenini devreye sokar.\",\"ar\":\"صحيح. تحمل الخلايا المجاورة للكبيبات مستقبلات بيتا-1؛ ينشط التنبيه الودي cAMP مفرزاً الرينين ومفعلاً محور RAAS.\",\"en\":\"Correct. Renal juxtaglomerular cells express beta-1 receptors; sympathetic stimulation increases cAMP, releasing renin and activating RAAS.\"}},{\"id\":\"opt-l7-s11-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Böbrek beta-1 reseptörleri, hormonal kaskadlardan bağımsız olarak proksimal tübül sodyum kanallarını doğrudan açar ve sodyumu geri emer.\",\"ar\":\"تفتح مستقبلات بيتا-1 الكلوية قنوات الصوديوم في الأنابيب القريبة مباشرة، معيدة امتصاص الصوديوم بمعزل عن الهرمونات.\",\"en\":\"Renal beta-1 receptors directly open proximal tubular sodium channels, reabsorbing sodium independently of hormonal cascades.\"},\"feedback\":{\"tr\":\"Yanlış. Beta-1 reseptörleri tübüler iyon kanallarını doğrudan açmaz; aldosteron üretimini tetikleyen enzimatik renin salınımını yönetir.\",\"ar\":\"غير صحيح. لا تفتح مستقبلات بيتا-1 قنوات الأنابيب مباشرة؛ بل تتحكم بإفراز الرينين الذي يحفز الألدوستيرون لاحقاً.\",\"en\":\"Incorrect. Beta-1 receptors on juxtaglomerular cells control the enzymatic release of renin, which hormonally drives aldosterone downstream.\"}},{\"id\":\"opt-l7-s11-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Böbrek beta-1 reseptörleri afferent arteriyolleri kasarak GFR'yi sıfırlar ve idrar üretimini tamamen durdurur.\",\"ar\":\"تضيق مستقبلات بيتا-1 الكلوية الشريانات الواردة لإيقاف الترشيح الكبيبي وإلغاء إنتاج البول كلياً.\",\"en\":\"Renal beta-1 receptors vasoconstrict afferent arterioles to shut down GFR and eliminate urine production entirely.\"},\"feedback\":{\"tr\":\"Yanlış. Afferent arteriyol büzülmesi vasküler alfa-1 reseptörleri (Gq) ile olur, beta-1 ile değil.\",\"ar\":\"غير صحيح. يتوسط التضيق الشرياني الوارد مستقبلات ألفا-1 الوعائية (Gq) وليس بيتا-1.\",\"en\":\"Incorrect. Renal afferent arteriolar vasoconstriction is mediated by vascular alpha-1 receptors (Gq), not beta-1.\"}}],\"prompt\":{\"tr\":\"Böbrek beta-1 adrenerjik reseptörleri, akut sempatik aktivasyonu kan basıncının uzun vadeli endokrin kontrolüne doğrudan nasıl bağlar?\",\"ar\":\"كيف تربط مستقبلات بيتا-1 الأدرينالينية الكلوية مباشرة بين التنشيط الودي الحاد والتنظيم الصماوي طويل الأمد لضغط الدم؟\",\"en\":\"How do renal beta-1 adrenoceptors directly link acute sympathetic nervous activation to long-term endocrine regulation of blood pressure?\"},\"title\":{\"tr\":\"Bütünsel Bağlantı: Renal Beta-1 ve RAAS Entegrasyonu\",\"ar\":\"ترابط شمولي: تكامل بيتا-1 الكلوي مع نظام RAAS\",\"en\":\"Holistic Connection: Renal Beta-1 & RAAS Integration\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":19}]},{\"id\":\"pharm-mod4-les1-step12\",\"order\":12,\"stageIndex\":12,\"stage\":\"mastery_check\",\"type\":\"mastery_check\",\"title\":{\"tr\":\"Ustalık Sınavı: Katekolamin İlaç Profilleme\",\"ar\":\"اختبار الإتقان: التنميط الدوائي للكاتيكولامينات\",\"en\":\"Mastery Check: Catecholamine Drug Profiling\"},\"prompt\":{\"tr\":\"Üç bilinmeyen adrenerjik agonist değerlendiriliyor: A maddesi refleks bradikardiyle saf vazokonstriksiyon yapar; B maddesi minimal vasküler etkiyle inotropiyi artırır; C maddesi bronkodilatasyon ve taşikardi yapar. Reseptör profillerini belirleyin.\",\"ar\":\"ثلاثة منبهات أدرينالينية مجهولة: المادة A تسبب تضيقاً وعائياً صرفاً مع بطء قلب انعكاسي؛ المادة B تزيد القلوصية دون تغير وعائي؛ المادة C تحدث توسعاً قصبياً وتسرع قلب. حدد انتقائيتها.\",\"en\":\"Three unknown adrenergic agonists are evaluated: Agent A causes pure vasoconstriction with reflex bradycardia; Agent B increases inotropy with minimal vascular change; Agent C induces bronchodilation and tachycardia. Identify their receptor selectivity profiles.\"},\"conceptCheck\":{\"question\":{\"tr\":\"A, B ve C maddelerinin adrenerjik reseptör seçicilik profilleri hangisinde doğru verilmiştir?\",\"ar\":\"ما هي الملامح الصحيحة لانتقائية المستقبلات الأدرينالينية للمواد A و B و C؟\",\"en\":\"Which mapping accurately describes the receptor selectivity profiles of Agents A, B, and C?\"},\"options\":[{\"id\":\"opt-l7-s12-1\",\"isCorrect\":true,\"text\":{\"tr\":\"A Maddesi: Selektif Alfa-1 agonisti (Fenilefrin); B Maddesi: Selektif Beta-1 agonisti (Dobutamin); C Maddesi: Non-selektif Beta-1/Beta-2 agonisti (İzoproterenol).\",\"ar\":\"المادة A: منبه ألفا-1 انتقائي (فينيل إفرين)؛ المادة B: منبه بيتا-1 انتقائي (دوبوتامين)؛ المادة C: منبه بيتا-1/بيتا-2 غير انتقائي (إيزوبروتيرينول).\",\"en\":\"Agent A: Selective Alpha-1 agonist (e.g., Phenylephrine); Agent B: Selective Beta-1 agonist (e.g., Dobutamine); Agent C: Non-selective Beta-1/Beta-2 agonist (e.g., Isoproterenol).\"},\"feedback\":{\"tr\":\"Doğru! Fenilefrin alfa-1 ile vazokonstriksiyon ve barorefleks bradikardi yapar; Dobutamin kardiyak beta-1'i seçer; İzoproterenol hem beta-1 hem beta-2'yi uyarır.\",\"ar\":\"صحيح! فينيل إفرين يحدث تضيقاً وعائياً وبطء قلب انعكاسياً؛ دوبوتامين ينتقي بيتا-1 القلبي؛ إيزوبروتيرينول ينبه كلاً من بيتا-1 وبيتا-2.\",\"en\":\"Correct! Agent A triggers alpha-1 vasoconstriction (reflex bradycardia); Agent B stimulates myocardial beta-1; Agent C stimulates both beta-2 and beta-1.\"}},{\"id\":\"opt-l7-s12-2\",\"isCorrect\":false,\"text\":{\"tr\":\"A Maddesi: Alfa-2 agonisti (Klonidin); B Maddesi: Beta-2 agonisti (Albuterol); C Maddesi: Non-selektif Alfa/Beta agonisti (Epinefrin).\",\"ar\":\"المادة A: منبه ألفا-2 (كلونيدين)؛ المادة B: منبه بيتا-2 (ألبوتيرول)؛ المادة C: منبه ألفا/بيتا غير انتقائي (إبينفرين).\",\"en\":\"Agent A: Alpha-2 agonist (Clonidine); Agent B: Beta-2 agonist (Albuterol); Agent C: Non-selective Alpha/Beta agonist (Epinephrine).\"},\"feedback\":{\"tr\":\"Yanlış. Klonidin santral sempatolitik etkiyle tansiyonu düşürür, akut periferik vazokonstriksiyon yapmaz. Albuterol ise beta-2 selektiftir.\",\"ar\":\"غير صحيح. يخفض الكلونيدين الضغط بتثبيط التنبيه الودي المركزي ولا يسبب تضيقاً محيطياً حاداً. ألبوتيرول انتقائي لـ بيتا-2.\",\"en\":\"Incorrect. Clonidine lowers pressure via central sympathetic outflow reduction. Albuterol is beta-2 selective and relaxes smooth muscle rather than augmenting inotropy.\"}},{\"id\":\"opt-l7-s12-3\",\"isCorrect\":false,\"text\":{\"tr\":\"A Maddesi: Selektif Beta-2 agonisti; B Maddesi: Non-selektif Alfa-bloker; C Maddesi: Selektif Alfa-1 agonisti.\",\"ar\":\"المادة A: منبه بيتا-2 انتقائي؛ المادة B: حاصر ألفا غير انتقائي؛ المادة C: منبه ألفا-1 انتقائي.\",\"en\":\"Agent A: Selective Beta-2 agonist; Agent B: Non-selective Alpha-blocker; Agent C: Selective Alpha-1 agonist.\"},\"feedback\":{\"tr\":\"Yanlış. Beta-2 agonisti vazokonstriksiyon değil vazodilatasyon ve hipotansiyon yapar. Fenilefrin alfa-1 ile basıncı artırıp vagal deşarjı tetikler.\",\"ar\":\"غير صحيح. يحدث منبه بيتا-2 توسعاً وعائياً وهبوط ضغط وليس تضيقاً وعائياً. الفينيل إفرين يرفع الضغط محفزاً تفريغ المبهم الانعكاسي.\",\"en\":\"Incorrect. A beta-2 agonist produces vasodilation and hypotension, not vasoconstriction with reflex bradycardia.\"}}]},\"technicalTerms\":[{\"term\":\"Selektif Adrenerjik Profil\",\"arContext\":\"التوصيف الأدريناليني الانتقائي (Selective Adrenergic Profile)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Hemodinamiği analiz edin: yoğun vazokonstriksiyon kan basıncını yükseltir ve karotis sinüsü baroreseptörlerini uyarır.\",\"ar\":\"حلل الديناميكا الدموية: التضيق الوعائي العاتي يرفع الضغط الشرياني الوسطي، مما ينشط مستقبِلات الضغط السباتية.\",\"en\":\"Analyze the hemodynamics: intense vasoconstriction raises mean arterial pressure, firing carotid sinus baroreceptors.\"},{\"tier\":2,\"tr\":\"A maddesi Gq vasküler reseptörlerini (alfa-1); B maddesi miyokardiyal Gs reseptörlerini (beta-1); C maddesi ise hava yolu ve kalp Gs reseptörlerini uyarır.\",\"ar\":\"تنبه المادة A مستقبلات Gq الوعائية (ألفا-1)؛ والمادة B مستقبلات Gs القلبية (بيتا-1)؛ والمادة C مستقبلات Gs في الشعب والقلب.\",\"en\":\"Agent A stimulates Gq vascular receptors (alpha-1); Agent B stimulates myocardial Gs receptors (beta-1); Agent C stimulates both airway and cardiac Gs receptors.\"},{\"tier\":3,\"tr\":\"Fenilefrin (Alfa-1) saf vazokonstriksiyon ve refleks bradikardi yapar; Dobutamin (Beta-1) kasılmayı artırır; İzoproterenol (Beta-1+Beta-2) bronkodilatasyon ve taşikardi yapar.\",\"ar\":\"فينيل إفرين (ألفا-1) يسبب تضيقاً وعائياً مع بطء قلب انعكاسي؛ دوبوتامين (بيتا-1) يعزز القلوصية؛ إيزوبروتيرينول (بيتا-1 + بيتا-2) يوسع الشعب ويسرع القلب.\",\"en\":\"Agent A: Alpha-1 selective (Phenylephrine); Agent B: Beta-1 selective (Dobutamine); Agent C: Non-selective Beta-1/Beta-2 agonist (Isoproterenol).\"}],\"config\":{\"options\":[{\"id\":\"opt-l7-s12-1\",\"isCorrect\":true,\"text\":{\"tr\":\"A Maddesi: Selektif Alfa-1 agonisti (Fenilefrin); B Maddesi: Selektif Beta-1 agonisti (Dobutamin); C Maddesi: Non-selektif Beta-1/Beta-2 agonisti (İzoproterenol).\",\"ar\":\"المادة A: منبه ألفا-1 انتقائي (فينيل إفرين)؛ المادة B: منبه بيتا-1 انتقائي (دوبوتامين)؛ المادة C: منبه بيتا-1/بيتا-2 غير انتقائي (إيزوبروتيرينول).\",\"en\":\"Agent A: Selective Alpha-1 agonist (e.g., Phenylephrine); Agent B: Selective Beta-1 agonist (e.g., Dobutamine); Agent C: Non-selective Beta-1/Beta-2 agonist (e.g., Isoproterenol).\"},\"feedback\":{\"tr\":\"Doğru! Fenilefrin alfa-1 ile vazokonstriksiyon ve barorefleks bradikardi yapar; Dobutamin kardiyak beta-1'i seçer; İzoproterenol hem beta-1 hem beta-2'yi uyarır.\",\"ar\":\"صحيح! فينيل إفرين يحدث تضيقاً وعائياً وبطء قلب انعكاسياً؛ دوبوتامين ينتقي بيتا-1 القلبي؛ إيزوبروتيرينول ينبه كلاً من بيتا-1 وبيتا-2.\",\"en\":\"Correct! Agent A triggers alpha-1 vasoconstriction (reflex bradycardia); Agent B stimulates myocardial beta-1; Agent C stimulates both beta-2 and beta-1.\"}},{\"id\":\"opt-l7-s12-2\",\"isCorrect\":false,\"text\":{\"tr\":\"A Maddesi: Alfa-2 agonisti (Klonidin); B Maddesi: Beta-2 agonisti (Albuterol); C Maddesi: Non-selektif Alfa/Beta agonisti (Epinefrin).\",\"ar\":\"المادة A: منبه ألفا-2 (كلونيدين)؛ المادة B: منبه بيتا-2 (ألبوتيرول)؛ المادة C: منبه ألفا/بيتا غير انتقائي (إبينفرين).\",\"en\":\"Agent A: Alpha-2 agonist (Clonidine); Agent B: Beta-2 agonist (Albuterol); Agent C: Non-selective Alpha/Beta agonist (Epinephrine).\"},\"feedback\":{\"tr\":\"Yanlış. Klonidin santral sempatolitik etkiyle tansiyonu düşürür, akut periferik vazokonstriksiyon yapmaz. Albuterol ise beta-2 selektiftir.\",\"ar\":\"غير صحيح. يخفض الكلونيدين الضغط بتثبيط التنبيه الودي المركزي ولا يسبب تضيقاً محيطياً حاداً. ألبوتيرول انتقائي لـ بيتا-2.\",\"en\":\"Incorrect. Clonidine lowers pressure via central sympathetic outflow reduction. Albuterol is beta-2 selective and relaxes smooth muscle rather than augmenting inotropy.\"}},{\"id\":\"opt-l7-s12-3\",\"isCorrect\":false,\"text\":{\"tr\":\"A Maddesi: Selektif Beta-2 agonisti; B Maddesi: Non-selektif Alfa-bloker; C Maddesi: Selektif Alfa-1 agonisti.\",\"ar\":\"المادة A: منبه بيتا-2 انتقائي؛ المادة B: حاصر ألفا غير انتقائي؛ المادة C: منبه ألفا-1 انتقائي.\",\"en\":\"Agent A: Selective Beta-2 agonist; Agent B: Non-selective Alpha-blocker; Agent C: Selective Alpha-1 agonist.\"},\"feedback\":{\"tr\":\"Yanlış. Beta-2 agonisti vazokonstriksiyon değil vazodilatasyon ve hipotansiyon yapar. Fenilefrin alfa-1 ile basıncı artırıp vagal deşarjı tetikler.\",\"ar\":\"غير صحيح. يحدث منبه بيتا-2 توسعاً وعائياً وهبوط ضغط وليس تضيقاً وعائياً. الفينيل إفرين يرفع الضغط محفزاً تفريغ المبهم الانعكاسي.\",\"en\":\"Incorrect. A beta-2 agonist produces vasodilation and hypotension, not vasoconstriction with reflex bradycardia.\"}}],\"prompt\":{\"tr\":\"Üç bilinmeyen adrenerjik agonist değerlendiriliyor: A maddesi refleks bradikardiyle saf vazokonstriksiyon yapar; B maddesi minimal vasküler etkiyle inotropiyi artırır; C maddesi bronkodilatasyon ve taşikardi yapar. Reseptör profillerini belirleyin.\",\"ar\":\"ثلاثة منبهات أدرينالينية مجهولة: المادة A تسبب تضيقاً وعائياً صرفاً مع بطء قلب انعكاسي؛ المادة B تزيد القلوصية دون تغير وعائي؛ المادة C تحدث توسعاً قصبياً وتسرع قلب. حدد انتقائيتها.\",\"en\":\"Three unknown adrenergic agonists are evaluated: Agent A causes pure vasoconstriction with reflex bradycardia; Agent B increases inotropy with minimal vascular change; Agent C induces bronchodilation and tachycardia. Identify their receptor selectivity profiles.\"},\"title\":{\"tr\":\"Ustalık Sınavı: Katekolamin İlaç Profilleme\",\"ar\":\"اختبار الإتقان: التنميط الدوائي للكاتيكولامينات\",\"en\":\"Mastery Check: Catecholamine Drug Profiling\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":20}]}]},\"pharm-mod4-les2\":{\"id\":\"pharm-mod4-les2\",\"courseId\":\"pharmacology\",\"moduleId\":\"ph-mod-04\",\"title\":{\"tr\":\"Kolinerjik Transmisyon ve Muskarinik Reseptör Modülasyonu\",\"ar\":\"النقل العصبي الكوليني وتعديل المستقبِلات الموسكارينية\",\"en\":\"Cholinergic Neurotransmission & Muscarinic Receptor Modulation\"},\"order\":2,\"access\":\"free\",\"objective\":{\"tr\":\"Asetilkolin sentez ve yıkım döngüsünü, muskarinik (M1-M5) ve nikotinik (Nn, Nm) reseptör alt tiplerini, organofosfat toksidromunu ve Tensilon testini yönetmek.\",\"ar\":\"إتقان دورة اصطناع وحلمهة الأسيتيل كولين، والأنماط الموسكارينية (M1-M5) والنيكوتينية (Nn, Nm)، ومتلازمة التسمم بالفوسفور العضوي واختبار تينسيلون.\",\"en\":\"Master acetylcholine synthesis and hydrolysis, muscarinic (M1-M5) and nicotinic (Nn, Nm) receptor subtypes, organophosphate toxidrome, and Tensilon testing.\"},\"misconceptions\":[{\"tr\":\"Atropinin tüm kolinerjik reseptörleri bloke eden evrensel bir panzehir olduğu yanılgısı (atropin yalnızca muskarinik M1-M5 reseptörlerini bloke eder; çizgili kas nikotinik Nm reseptörlerine sıfır afinitesi vardır).\",\"ar\":\"الظن الخاطئ بأن الأتروبين ترياق شامل يعطل كل المستقبلات الكولينية (الأتروبين يحصر المستقبلات الموسكارينية فقط، ولا يملك أي ألفة لمستقبلات Nm العضلية الهيكلية).\",\"en\":\"The misconception that atropine is a universal cholinergic antagonist (atropine selectively blocks muscarinic M1-M5 receptors with zero activity at nicotinic Nm endplates).\"},{\"tr\":\"Miyasteni krizinde zayıflık hisseden hastaya körlemesine kolinesteraz inhibitörü verilmesi yanılgısı (hastalık miyastenik kriz değil aşırı doz kolinerjik kriz ise, ilaç depolarizan felci şiddetlendirip hastayı boğabilir).\",\"ar\":\"الاعتقاد الخاطئ بإمكانية إعطاء مثبطات الكولينستراز عميانياً عند تفاقم الوهن العضلي (إذا كانت النوبة كولينية ناتجة عن فرط الجرعة، فإن الدواء يعمق الشلل الاستقطابي ويفضي للوفاة).\",\"en\":\"The dangerous practice of blindly giving AChE inhibitors in myasthenic weakness (if the event is an overtreatment cholinergic crisis, adding drug deepens depolarizing paralysis into fatal asphyxiation).\"}],\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":22}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Katzung's Basic & Clinical Pharmacology\",\"edition\":\"15th ed.\",\"topic\":\"Cholinoceptor-Activating & Cholinesterase-Inhibiting Drugs\",\"chapter\":\"Chapter 7: Cholinoceptor-Activating & Cholinesterase-Inhibiting Drugs\",\"page\":\"pp. 105-125\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Goodman & Gilman's The Pharmacological Basis of Therapeutics\",\"edition\":\"14th ed.\",\"topic\":\"Muscarinic Receptor Agonists and Antagonists\",\"chapter\":\"Chapter 7: Muscarinic Receptor Agonists and Antagonists\",\"page\":\"pp. 135-155\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"pharm-mod4-les2-card1\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Atropin Paradoksu ve Nikotinik Felç\",\"prompt\":\"Organofosfat zehirlenmesinde yüksek doz atropin sekresyonları durdurduğu halde diyafram kas felcini neden önleyemez?\",\"answer\":\"Atropin yalnızca muskarinik (M1-M5) reseptörleri bloke eder; nöromusküler kavşaktaki nikotinik (Nm) reseptörleri bloke edemez. Pralidoksim (2-PAM) gereklidir.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod4-les2-card2\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Endotelyal M3 Paradoksu\",\"prompt\":\"Damar düz kasında parasempatik innervasyon olmadığı halde intravenöz asetilkolin neden güçlü vazodilatasyon yapar?\",\"answer\":\"Endotel hücrelerindeki M3 reseptörleri Gq/Ca2+ ile endotelyal nitrik oksit sentazı (eNOS) aktive eder; salınan NO düz kasa diffüze olup cGMP ile gevşeme sağlar.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod4-les2-card3\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Tensilon Testi Ayırıcı Tanısı\",\"prompt\":\"Miyastenia Gravis krizinde ultra kısa etkili edrofonyum (Tensilon) verildiğinde klinik yanıt nasıl yorumlanır?\",\"answer\":\"Kas gücü anında düzelirse Miyastenik Krizdir (yetersiz ACh); kas felci daha da kötüleşir ve fasikülasyon artarsa Kolinerjik Krizdir (aşırı ACh / depolarizasyon bloku).\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod4-les2-card4\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Pralidoksim ve Yaşlanma (Aging)\",\"prompt\":\"Organofosfat zehirlenmesinde pralidoksim (2-PAM) neden ilk saatlerde hızla uygulanmalıdır?\",\"answer\":\"Organofosfat-AChE kompleksi alkil grubunu kaybedip 'yaşlanma' (aging) sürecine girdiğinde kovalent bağ kalıcılaşır ve enzim artık reaktive edilemez.\",\"box\":1,\"intervalDays\":1}],\"steps\":[{\"id\":\"pharm-mod4-les2-step1\",\"order\":1,\"stageIndex\":1,\"stage\":\"hook\",\"type\":\"predict_reveal\",\"title\":{\"tr\":\"Klinik Paradoks: Organofosfat Zehirlenmesinde Atropin Çıkmazı\",\"ar\":\"المفارقة السريرية: مأزق الأتروبين في التسمم بالفوسفات العضوي\",\"en\":\"Clinical Paradox: Organophosphate Poisoning & The Atropine Dilemma\"},\"predictThenReveal\":true,\"prompt\":{\"tr\":\"Şiddetli organofosfat zehirlenmesi yaşayan tarım işçisine yüksek doz IV atropin veriliyor. Bradikardi ve tükürük salgısı düzeliyor ancak solunum kası güçsüzlüğü ve fasikülasyonlar kötüleşiyor. Atropin çizgili kas felcini neden düzeltemez?\",\"ar\":\"تلقى مزارع مصاب بتسمم فوسفوري عضوي حاد جرعة عالية من الأتروبين وريدياً. تراجع بطء القلب واللعاب، لكن ضعف الحجاب الحاجز والنفضان العضلي تفاقما. لماذا يفشل الأتروبين في إنقاذ الشلل العضلي الهيكلي؟\",\"en\":\"An agricultural worker with severe organophosphate poisoning receives high-dose IV atropine. Bradycardia and salivation resolve, but diaphragmatic weakness and muscle fasciculations worsen. Why does atropine fail to rescue skeletal muscle paralysis?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Atropin organofosfat zehirlenmesinde çizgili kas güçsüzlüğünü ve diyafram felcini neden düzeltemez?\",\"ar\":\"لماذا يفشل الأتروبين في عكس الضعف العضلي وشلل الحجاب الحاجز في التسمم بالفوسفات العضوي؟\",\"en\":\"Why does atropine fail to reverse skeletal muscle weakness and diaphragmatic paralysis in organophosphate toxicity?\"},\"options\":[{\"id\":\"opt-l8-s1-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Atropin yarışmalı bir muskarinik antagonisttir; nöromusküler kavşaktaki nikotinik (Nm) reseptörlere afinitesi yoktur ve aşırı ACh depolarizan blok yapmaya devam eder.\",\"ar\":\"الأتروبين مضاد مسكاريني تنافسي ليس له أي ألفة لمستقبلات النيكوتين (Nm) في الوصل العصبي العضلي، فيستمر فائض الأسيتيل كولين بإحداث شلل إزالة الاستقطاب.\",\"en\":\"Atropine is a competitive muscarinic antagonist with zero affinity for nicotinic (Nm) receptors at the neuromuscular junction; excess ACh continues to cause depolarizing neuromuscular block.\"},\"feedback\":{\"tr\":\"Doğru. Atropin paradoksu: atropin muskarinik organları (SLUDGE) kurtarır ancak nikotinik kavşağa bağlanamaz; çizgili kas için oksim (Pralidoksim/2-PAM) gerekir.\",\"ar\":\"صحيح. مفارقة الأتروبين: ينقذ الأعضاء الموسكارينية ولكنه لا يرتبط بالوصل النيكوتيني؛ يتطلب شلل العضلات مضاداً نوعياً مثل البراليدوكسيم (2-PAM).\",\"en\":\"Correct. The atropine paradox: atropine rescues muscarinic organs, but has zero affinity for nicotinic Nm endplates, requiring Pralidoxime (2-PAM) for muscle recovery.\"}},{\"id\":\"opt-l8-s1-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Çizgili kas nikotinik reseptörleri atropine 1000 kat daha düşük afinite gösterir ve intravenöz dozun iki katına çıkarılmasını gerektirir.\",\"ar\":\"تمتلك مستقبلات النيكوتين العضلية ألفة أقل بألف ضعف للأتروبين، مما يتطلب مضاعفة الجرعة الوريدية بشكل هائل.\",\"en\":\"Skeletal muscle nicotinic receptors possess 1,000-fold lower affinity for atropine, requiring a massive doubling of the intravenous dose.\"},\"feedback\":{\"tr\":\"Yanlış. Atropin muskarinik GPCR'lara (M1-M5) kimyasal olarak selektiftir; hiçbir klinik dozda nikotinik katyon kanallarını antagonize etmez.\",\"ar\":\"غير صحيح. الأتروبين انتقائي بنيوياً للمستقبلات الموسكارينية؛ ولا يحصر قنوات النيكوتين الكاتيونية بأي جرعة سريرية.\",\"en\":\"Incorrect. Atropine is chemically selective for muscarinic GPCRs (M1-M5) and does not antagonize nicotinic cation channels at any clinical dose.\"}},{\"id\":\"opt-l8-s1-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Organofosfatlar doğrudan nikotinik reseptör iyon kanallarına bağlanarak onları geri dönüşsüz denatüre eder ve farmakolojik geri çevirmeyi imkansız kılar.\",\"ar\":\"ترتبط الفوسفات العضوية مباشرة بقنوات مستقبلات النيكوتين الأيونية وتخربها نهائياً، مما يجعل أي عكس دوائي مستحيلاً.\",\"en\":\"Organophosphates directly bind and irreversibly denature nicotinic receptor ion channels, rendering any pharmacological reversal impossible.\"},\"feedback\":{\"tr\":\"Yanlış. Organofosfatlar asetilkolinesterazı inhibe eder; nöromusküler blok aşırı ACh birikimine bağlı sekonder bir depolarizan bloktur ve oksimlerle geri çevrilebilir.\",\"ar\":\"غير صحيح. تثبط الفوسفات العضوية كولينستراز الأسيتيل مسببة تراكمه؛ والشلل العضلي إحصار ثانوي ناجم عن فرط الاستقطاب يمكن عكسه بالأوكسيمات.\",\"en\":\"Incorrect. Organophosphates inhibit acetylcholinesterase; muscle paralysis is a secondary depolarizing block reversible by oximes before aging.\"}}]},\"technicalTerms\":[{\"term\":\"Muskarinik Selektivite\",\"arContext\":\"الانتقائية الموسكارينية (Muscarinic Selectivity)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Otonom uç organlar ile somatik nöromusküler kavşağı yöneten reseptör sınıflarını kıyaslayın.\",\"ar\":\"قارن بين فئات المستقبلات المنظمة للأعضاء الذاتية وتلك المنظمة للوصل العصبي العضلي الجسدي.\",\"en\":\"Which receptor class mediates autonomic end-organs versus somatic neuromuscular junctions?\"},{\"tier\":2,\"tr\":\"Atropin katı biçimde muskarinik antagonisttir. Ligand kapılı nikotinik (Nm) reseptörlerine afinitesi var mıdır?\",\"ar\":\"الأتروبين مضاد مسكاريني بحت. هل يمتلك ألفة تجاه مستقبلات النيكوتين (Nm) المبوبة بالربيطة؟\",\"en\":\"Atropine is classified strictly as a muscarinic antagonist. Does it have affinity for ligand-gated nicotinic (Nm) receptors?\"},{\"tier\":3,\"tr\":\"Atropin muskarinik GPCR'ları (M1-M5) bloke ederek SLUDGE'ı ve bradikardiyi çözer; ancak nikotinik Nm reseptörlerine bağlanamaz ve depolarizan çizgili kas felcini durduramaz.\",\"ar\":\"يحصر الأتروبين مستقبلات GPCR الموسكارينية (M1-M5) عاكساً أعراض SLUDGE؛ لكنه لا يرتبط بمستقبلات النيكوتين Nm، فيستمر شلل العضلات الهيكلية.\",\"en\":\"Atropine selectively blocks muscarinic GPCRs (M1-M5), reversing SLUDGE and bradycardia, but cannot block nicotinic Nm receptors where ACh sustains depolarizing paralysis.\"}],\"config\":{\"options\":[{\"id\":\"opt-l8-s1-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Atropin yarışmalı bir muskarinik antagonisttir; nöromusküler kavşaktaki nikotinik (Nm) reseptörlere afinitesi yoktur ve aşırı ACh depolarizan blok yapmaya devam eder.\",\"ar\":\"الأتروبين مضاد مسكاريني تنافسي ليس له أي ألفة لمستقبلات النيكوتين (Nm) في الوصل العصبي العضلي، فيستمر فائض الأسيتيل كولين بإحداث شلل إزالة الاستقطاب.\",\"en\":\"Atropine is a competitive muscarinic antagonist with zero affinity for nicotinic (Nm) receptors at the neuromuscular junction; excess ACh continues to cause depolarizing neuromuscular block.\"},\"feedback\":{\"tr\":\"Doğru. Atropin paradoksu: atropin muskarinik organları (SLUDGE) kurtarır ancak nikotinik kavşağa bağlanamaz; çizgili kas için oksim (Pralidoksim/2-PAM) gerekir.\",\"ar\":\"صحيح. مفارقة الأتروبين: ينقذ الأعضاء الموسكارينية ولكنه لا يرتبط بالوصل النيكوتيني؛ يتطلب شلل العضلات مضاداً نوعياً مثل البراليدوكسيم (2-PAM).\",\"en\":\"Correct. The atropine paradox: atropine rescues muscarinic organs, but has zero affinity for nicotinic Nm endplates, requiring Pralidoxime (2-PAM) for muscle recovery.\"}},{\"id\":\"opt-l8-s1-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Çizgili kas nikotinik reseptörleri atropine 1000 kat daha düşük afinite gösterir ve intravenöz dozun iki katına çıkarılmasını gerektirir.\",\"ar\":\"تمتلك مستقبلات النيكوتين العضلية ألفة أقل بألف ضعف للأتروبين، مما يتطلب مضاعفة الجرعة الوريدية بشكل هائل.\",\"en\":\"Skeletal muscle nicotinic receptors possess 1,000-fold lower affinity for atropine, requiring a massive doubling of the intravenous dose.\"},\"feedback\":{\"tr\":\"Yanlış. Atropin muskarinik GPCR'lara (M1-M5) kimyasal olarak selektiftir; hiçbir klinik dozda nikotinik katyon kanallarını antagonize etmez.\",\"ar\":\"غير صحيح. الأتروبين انتقائي بنيوياً للمستقبلات الموسكارينية؛ ولا يحصر قنوات النيكوتين الكاتيونية بأي جرعة سريرية.\",\"en\":\"Incorrect. Atropine is chemically selective for muscarinic GPCRs (M1-M5) and does not antagonize nicotinic cation channels at any clinical dose.\"}},{\"id\":\"opt-l8-s1-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Organofosfatlar doğrudan nikotinik reseptör iyon kanallarına bağlanarak onları geri dönüşsüz denatüre eder ve farmakolojik geri çevirmeyi imkansız kılar.\",\"ar\":\"ترتبط الفوسفات العضوية مباشرة بقنوات مستقبلات النيكوتين الأيونية وتخربها نهائياً، مما يجعل أي عكس دوائي مستحيلاً.\",\"en\":\"Organophosphates directly bind and irreversibly denature nicotinic receptor ion channels, rendering any pharmacological reversal impossible.\"},\"feedback\":{\"tr\":\"Yanlış. Organofosfatlar asetilkolinesterazı inhibe eder; nöromusküler blok aşırı ACh birikimine bağlı sekonder bir depolarizan bloktur ve oksimlerle geri çevrilebilir.\",\"ar\":\"غير صحيح. تثبط الفوسفات العضوية كولينستراز الأسيتيل مسببة تراكمه؛ والشلل العضلي إحصار ثانوي ناجم عن فرط الاستقطاب يمكن عكسه بالأوكسيمات.\",\"en\":\"Incorrect. Organophosphates inhibit acetylcholinesterase; muscle paralysis is a secondary depolarizing block reversible by oximes before aging.\"}}],\"prompt\":{\"tr\":\"Şiddetli organofosfat zehirlenmesi yaşayan tarım işçisine yüksek doz IV atropin veriliyor. Bradikardi ve tükürük salgısı düzeliyor ancak solunum kası güçsüzlüğü ve fasikülasyonlar kötüleşiyor. Atropin çizgili kas felcini neden düzeltemez?\",\"ar\":\"تلقى مزارع مصاب بتسمم فوسفوري عضوي حاد جرعة عالية من الأتروبين وريدياً. تراجع بطء القلب واللعاب، لكن ضعف الحجاب الحاجز والنفضان العضلي تفاقما. لماذا يفشل الأتروبين في إنقاذ الشلل العضلي الهيكلي؟\",\"en\":\"An agricultural worker with severe organophosphate poisoning receives high-dose IV atropine. Bradycardia and salivation resolve, but diaphragmatic weakness and muscle fasciculations worsen. Why does atropine fail to rescue skeletal muscle paralysis?\"},\"title\":{\"tr\":\"Klinik Paradoks: Organofosfat Zehirlenmesinde Atropin Çıkmazı\",\"ar\":\"المفارقة السريرية: مأزق الأتروبين في التسمم بالفوسفات العضوي\",\"en\":\"Clinical Paradox: Organophosphate Poisoning & The Atropine Dilemma\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":17}]},{\"id\":\"pharm-mod4-les2-step2\",\"order\":2,\"stageIndex\":2,\"stage\":\"question\",\"type\":\"question\",\"title\":{\"tr\":\"Kavramsal Soru: Hızlı İyon Kanalları ve Yavaş GPCR'lar\",\"ar\":\"سؤال مفاهيمي: قنوات الأيونات السريعة مقابل GPCR البطيئة\",\"en\":\"Conceptual Question: Fast Ion Channels vs Slow GPCRs\"},\"prompt\":{\"tr\":\"Aynı asetilkolin molekülü, iskelet kasında milisaniyeler içinde hızlı depolarizasyonu tetiklerken kardiyak pacemaker'da nasıl uzun süreli hiperpolarizasyon ve bradikardiye yol açar?\",\"ar\":\"كيف يمكن لجزيء الأسيتيل كولين نفسه أن يحفز إزالة استقطاب سريعة بالميلي ثانية في العضلة الهيكلية، بينما يثير فرط استقطاب مديداً وبطء قلب في الناظمة القلبية؟\",\"en\":\"How can the exact same acetylcholine molecule trigger millisecond-fast depolarization in skeletal muscle, while evoking prolonged hyperpolarization and sustained bradycardia in the cardiac pacemaker?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Asetilkolin iskelet kası ve kalp düğüm dokusunda neden tamamen farklı hız ve yönde elektriksel yanıtlar oluşturur?\",\"ar\":\"لماذا يولد الأسيتيل كولين استجابات كهربائية متباينة السرعة والاتجاه بين العضلات الهيكلية والعقد القلبية؟\",\"en\":\"Why does acetylcholine mediate divergent speeds and directions of electrical response between skeletal muscle and cardiac pacemaker?\"},\"options\":[{\"id\":\"opt-l8-s2-1\",\"isCorrect\":true,\"text\":{\"tr\":\"İskelet kası nikotinik Nm ligand kapılı katyon kanalları taşır (anlık iyon akışı); kardiyak pacemaker ise Gi/beta-gama ile GIRK K+ kanallarına kenetli muskarinik M2 GPCR'lar taşır (yavaş kaskad).\",\"ar\":\"تعبر العضلة الهيكلية عن قنوات Nm النيكوتينية المبوبة بالربيطة (تدفق أيوني فوري)؛ وتعبر الناظمة القلبية عن مستقبلات M2 المقترنة بـ Gi/بيتا-غاما بقنوات GIRK للبوتاسيوم (شلال أبطأ).\",\"en\":\"Skeletal muscle expresses nicotinic Nm ligand-gated cation channels (immediate ion flux); cardiac pacemaker expresses muscarinic M2 GPCRs coupled via Gi/beta-gamma to GIRK K+ channels (slower cascade).\"},\"feedback\":{\"tr\":\"Doğru. Nikotinik reseptörler doğrudan sodyum/kalsiyum geçiren iyon kanallarıdır (iyonotropik); muskarinik M2 ise Gi aracılığıyla GIRK K+ kanallarını açan metabotropik bir GPCR'dır.\",\"ar\":\"صحيح. مستقبلات النيكوتين قنوات كاتيونية أيونية؛ بينما M2 مستقبل أيضي مقترن بـ Gi يفتح قنوات البوتاسيوم GIRK مسبباً فرط الاستقطاب.\",\"en\":\"Correct. Nicotinic receptors are ionotropic cation channels conducting sub-millisecond flux, whereas muscarinic M2 is a metabotropic GPCR coupled to GIRK K+ channels.\"}},{\"id\":\"opt-l8-s2-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Kardiyak asetilkolin, iskelet kasındaki L-konformerine göre 100 kat daha yavaş hidroliz olan stereoizomerik bir D-konformasyonunda bulunur.\",\"ar\":\"يوجد الأسيتيل كولين القلبي في متماكب فراغي D يتحلمه أبطأ بمئة مرة من متماكب L في العضلات الهيكلية.\",\"en\":\"Cardiac acetylcholine exists in a stereoisomeric D-conformation that hydrolyzes 100 times slower than the skeletal muscle L-conformer.\"},\"feedback\":{\"tr\":\"Yanlış. Asetilkolin kiral merkez içermez, optik izomeri yoktur; kinetik fark reseptör mimarisinden (iyonotropik vs GPCR) kaynaklanır.\",\"ar\":\"غير صحيح. الأسيتيل كولين جزيء لا كيرالي ليس له متماكبات ضوئية؛ ويعود الفارق الحركي كلياً لبنية المستقبل (أيوني مقابل GPCR).\",\"en\":\"Incorrect. Acetylcholine is an achiral molecule with no stereoisomers; receptor architecture alone dictates kinetic response speed.\"}},{\"id\":\"opt-l8-s2-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Kardiyak dokuda asetilkolinesteraz tamamen bulunmaz ve nöromusküler kavşağın aksine asetilkolinin dakikalarca kalmasına izin verir.\",\"ar\":\"يفتقر النسيج القلبي تماماً لإنزيم كولينستراز الأسيتيل، مما يسمح للأسيتيل كولين بالبقاء لدقائق بخلاف الوصل العصبي العضلي.\",\"en\":\"Cardiac tissue completely lacks acetylcholinesterase, allowing acetylcholine to persist for minutes, unlike the neuromuscular junction.\"},\"feedback\":{\"tr\":\"Yanlış. Kalp dokusunda bol miktarda asetilkolinesteraz bulunur. Yanıt süresini belirleyen şey doğrudan iyon poru açılmasına karşı GPCR sinyal iletimidir.\",\"ar\":\"غير صحيح. يحتوي القلب على كولينستراز بوفرة. يحدد الفارق الزمني طبيعة المستقبل (فتح قناة مباشر مقابل شلال GPCR).\",\"en\":\"Incorrect. Heart tissue contains abundant acetylcholinesterase. Kinetic divergence is governed by direct ion channel gating versus GPCR intracellular signaling.\"}}]},\"technicalTerms\":[{\"term\":\"Ligand Kapılı İyon Kanalı\",\"arContext\":\"القناة الأيونية المبوبة بالربيط (Ligand-Gated Ion Channel)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Reseptör süper ailelerini karşılaştırın: iyonotropik ligand kapılı kanallar ile metabotropik G-protein kenetli reseptörler.\",\"ar\":\"قارن بين العائلات الكبرى للمستقبلات: القنوات الأيونية المبوبة بالربيطة مقابل مستقبلات GPCR الاستقلابية.\",\"en\":\"Compare the receptor superfamilies: ionotropic ligand-gated channels versus metabotropic GPCRs.\"},{\"tier\":2,\"tr\":\"Nikotinik Nm kanalları ligand bağlanınca anında açılır. Muskarinik M2 reseptörleri ise GIRK K+ kanallarını açmak için heterotrimerik Gi proteinini aktive etmek zorundadır.\",\"ar\":\"تفتح قنوات Nm النيكوتينية فور ارتباط الربيطة. بينما يجب أن تفعل مستقبلات M2 الموسكارينية بروتين Gi لفتح قنوات البوتاسيوم GIRK.\",\"en\":\"Nicotinic Nm channels open directly upon binding. Muscarinic M2 receptors must activate a heterotrimeric Gi protein to open GIRK K+ channels.\"},{\"tier\":3,\"tr\":\"Nikotinik Nm kanallarında doğrudan iyon geçişi milisaniyede depolarizasyon yapar; M2 reseptöründe ise Gi beta-gama alt birimlerinin potasyum kanallarını açması daha yavaş ve uzundur.\",\"ar\":\"يحدث الفتح المباشر لقناة Nm النيكوتينية إزالة استقطاب بالميلي ثانية؛ بينما يفتح تأشير M2 عبر وحدات Gi بيتا-غاما قنوات البوتاسيوم ببطء واستدامة أكبر.\",\"en\":\"Direct ion channel gating at nicotinic Nm endplates produces sub-millisecond depolarization, while M2 GPCR signaling through Gi beta-gamma opens potassium channels more slowly.\"}],\"config\":{\"options\":[{\"id\":\"opt-l8-s2-1\",\"isCorrect\":true,\"text\":{\"tr\":\"İskelet kası nikotinik Nm ligand kapılı katyon kanalları taşır (anlık iyon akışı); kardiyak pacemaker ise Gi/beta-gama ile GIRK K+ kanallarına kenetli muskarinik M2 GPCR'lar taşır (yavaş kaskad).\",\"ar\":\"تعبر العضلة الهيكلية عن قنوات Nm النيكوتينية المبوبة بالربيطة (تدفق أيوني فوري)؛ وتعبر الناظمة القلبية عن مستقبلات M2 المقترنة بـ Gi/بيتا-غاما بقنوات GIRK للبوتاسيوم (شلال أبطأ).\",\"en\":\"Skeletal muscle expresses nicotinic Nm ligand-gated cation channels (immediate ion flux); cardiac pacemaker expresses muscarinic M2 GPCRs coupled via Gi/beta-gamma to GIRK K+ channels (slower cascade).\"},\"feedback\":{\"tr\":\"Doğru. Nikotinik reseptörler doğrudan sodyum/kalsiyum geçiren iyon kanallarıdır (iyonotropik); muskarinik M2 ise Gi aracılığıyla GIRK K+ kanallarını açan metabotropik bir GPCR'dır.\",\"ar\":\"صحيح. مستقبلات النيكوتين قنوات كاتيونية أيونية؛ بينما M2 مستقبل أيضي مقترن بـ Gi يفتح قنوات البوتاسيوم GIRK مسبباً فرط الاستقطاب.\",\"en\":\"Correct. Nicotinic receptors are ionotropic cation channels conducting sub-millisecond flux, whereas muscarinic M2 is a metabotropic GPCR coupled to GIRK K+ channels.\"}},{\"id\":\"opt-l8-s2-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Kardiyak asetilkolin, iskelet kasındaki L-konformerine göre 100 kat daha yavaş hidroliz olan stereoizomerik bir D-konformasyonunda bulunur.\",\"ar\":\"يوجد الأسيتيل كولين القلبي في متماكب فراغي D يتحلمه أبطأ بمئة مرة من متماكب L في العضلات الهيكلية.\",\"en\":\"Cardiac acetylcholine exists in a stereoisomeric D-conformation that hydrolyzes 100 times slower than the skeletal muscle L-conformer.\"},\"feedback\":{\"tr\":\"Yanlış. Asetilkolin kiral merkez içermez, optik izomeri yoktur; kinetik fark reseptör mimarisinden (iyonotropik vs GPCR) kaynaklanır.\",\"ar\":\"غير صحيح. الأسيتيل كولين جزيء لا كيرالي ليس له متماكبات ضوئية؛ ويعود الفارق الحركي كلياً لبنية المستقبل (أيوني مقابل GPCR).\",\"en\":\"Incorrect. Acetylcholine is an achiral molecule with no stereoisomers; receptor architecture alone dictates kinetic response speed.\"}},{\"id\":\"opt-l8-s2-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Kardiyak dokuda asetilkolinesteraz tamamen bulunmaz ve nöromusküler kavşağın aksine asetilkolinin dakikalarca kalmasına izin verir.\",\"ar\":\"يفتقر النسيج القلبي تماماً لإنزيم كولينستراز الأسيتيل، مما يسمح للأسيتيل كولين بالبقاء لدقائق بخلاف الوصل العصبي العضلي.\",\"en\":\"Cardiac tissue completely lacks acetylcholinesterase, allowing acetylcholine to persist for minutes, unlike the neuromuscular junction.\"},\"feedback\":{\"tr\":\"Yanlış. Kalp dokusunda bol miktarda asetilkolinesteraz bulunur. Yanıt süresini belirleyen şey doğrudan iyon poru açılmasına karşı GPCR sinyal iletimidir.\",\"ar\":\"غير صحيح. يحتوي القلب على كولينستراز بوفرة. يحدد الفارق الزمني طبيعة المستقبل (فتح قناة مباشر مقابل شلال GPCR).\",\"en\":\"Incorrect. Heart tissue contains abundant acetylcholinesterase. Kinetic divergence is governed by direct ion channel gating versus GPCR intracellular signaling.\"}}],\"prompt\":{\"tr\":\"Aynı asetilkolin molekülü, iskelet kasında milisaniyeler içinde hızlı depolarizasyonu tetiklerken kardiyak pacemaker'da nasıl uzun süreli hiperpolarizasyon ve bradikardiye yol açar?\",\"ar\":\"كيف يمكن لجزيء الأسيتيل كولين نفسه أن يحفز إزالة استقطاب سريعة بالميلي ثانية في العضلة الهيكلية، بينما يثير فرط استقطاب مديداً وبطء قلب في الناظمة القلبية؟\",\"en\":\"How can the exact same acetylcholine molecule trigger millisecond-fast depolarization in skeletal muscle, while evoking prolonged hyperpolarization and sustained bradycardia in the cardiac pacemaker?\"},\"title\":{\"tr\":\"Kavramsal Soru: Hızlı İyon Kanalları ve Yavaş GPCR'lar\",\"ar\":\"سؤال مفاهيمي: قنوات الأيونات السريعة مقابل GPCR البطيئة\",\"en\":\"Conceptual Question: Fast Ion Channels vs Slow GPCRs\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":18}]},{\"id\":\"pharm-mod4-les1-step3\",\"order\":3,\"stageIndex\":3,\"stage\":\"intuition\",\"type\":\"intuition\",\"title\":{\"tr\":\"Fiziksel Sezgi: Asma Köprü Kolu ve Belediye Ulağı\",\"ar\":\"الحدس الفيزيائي: رافعة الجسر مقابل رسول البلدية\",\"en\":\"Physical Intuition: The Drawbridge vs The City Hall Messenger\"},\"prompt\":{\"tr\":\"Bir kalenin asma köprüsünü doğrudan bir kol çekerek açmakla, koridorlardan ulak gönderip kapının açılmasını talep etmeyi kıyaslayın. Bu kolinerjik iletimi nasıl modeller?\",\"ar\":\"قارن بين فتح جسر قلعة بسحب رافعة مباشرة وبين إرسال رسول عبر الأروقة لطلب فتح البوابة. كيف يمثل ذلك النقل الكوليني؟\",\"en\":\"Compare opening a castle drawbridge by pulling a direct lever versus dispatching a messenger through corridors to request gate opening. How does this model cholinergic transmission?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Asma köprü kolu ve belediye ulağı benzetmesi kolinerjik iletimde neyi temsil eder?\",\"ar\":\"ماذا يمثل تشبيه رافعة الجسر ورسول البلدية في النقل الكوليني؟\",\"en\":\"What do the direct lever and city hall messenger analogies represent in cholinergic neurotransmission?\"},\"options\":[{\"id\":\"opt-l8-s3-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Doğrudan kol, ligand kapılı nikotinik iyon kanallarını modeller (anlık por açılması); ulak ise muskarinik GPCR'ları modeller (çok basamaklı biyokimyasal kaskad).\",\"ar\":\"تمثل الرافعة قنوات النيكوتين الأيونية (فتح فوري للمسام)؛ بينما يمثل الرسول مستقبلات GPCR الموسكارينية (شلال كيميائي حيوي متعدد المراحل).\",\"en\":\"The lever represents ligand-gated nicotinic ion channels (direct intrinsic pore opening); the messenger represents muscarinic GPCRs (multi-step intracellular biochemical cascade).\"},\"feedback\":{\"tr\":\"Doğru. İyonotropik nikotinik kanallar reseptör ve poru tek bir komplekste birleştirir (anlık kol). Muskarinik GPCR'lar ise G-proteini ve ikinci haberciler gerektirir (ulak).\",\"ar\":\"صحيح. تدمج قنوات النيكوتين المستقبل والمسام في معقد واحد (رافعة فورية)؛ بينما تتطلب GPCR الموسكارينية بروتينات G ومراسيل ثانوية (رسول).\",\"en\":\"Correct. Ionotropic nicotinic channels combine receptor and pore in one protein complex (instant lever). Metabotropic GPCRs require G-protein relays (messenger).\"}},{\"id\":\"opt-l8-s3-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Doğrudan kol yavaş muskarinik GPCR transkripsiyonunu modeller; ulak ise lipid çift tabakasından hızlı veziküler ekzositozu modeller.\",\"ar\":\"تمثل الرافعة استنساخ GPCR الموسكاريني البطيء؛ ويمثل الرسول الإخراج الخلوي الحويصلي السريع عبر طبقة الليبيد.\",\"en\":\"The lever represents slow muscarinic GPCR transcription; the messenger represents fast vesicular exocytosis through the lipid bilayer.\"},\"feedback\":{\"tr\":\"Yanlış. Kol benzetmesi agonist bağlanınca iyon kanalının doğrudan açılmasını modeller; nükleer transkripsiyonla ilgisi yoktur.\",\"ar\":\"غير صحيح. يمثل تشبيه الرافعة الفتح المباشر لمسام القناة الأيونية عند ارتباط المنبه، ولا علاقة له بالاستنساخ النووي.\",\"en\":\"Incorrect. The lever models the mechanical opening of the ionotropic channel pore upon agonist binding, not nuclear transcription.\"}},{\"id\":\"opt-l8-s3-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Doğrudan kol asetilkolinesterazın kolini hidroliz etmesini modeller; ulak ise asetatın mitokondriye geri difüzyonunu modeller.\",\"ar\":\"تمثل الرافعة حلمهة الكولين بإنزيم كولينستراز؛ ويمثل الرسول انتشار الأسيتات عائداً إلى الميتوكوندريا.\",\"en\":\"The lever represents acetylcholinesterase hydrolysis of choline; the messenger represents acetate diffusion back into mitochondria.\"},\"feedback\":{\"tr\":\"Yanlış. Her iki analoji de post-sinaptik sinyal iletim mekanizmalarını karşılaştırmak içindir, enzimatik yıkım için değil.\",\"ar\":\"غير صحيح. يصف كلا التشبيهين آليات تحويل الإشارة بعد المشبكية، مقارنين بين فتح القنوات المباشر وشلالات GPCR.\",\"en\":\"Incorrect. Both analogies describe post-synaptic transduction mechanisms, contrasting direct channel opening with GPCR second messenger cascades.\"}}]},\"technicalTerms\":[{\"term\":\"İyonotropik vs Metabotropik\",\"arContext\":\"أيوني مقابل أيضي (Ionotropic vs Metabotropic)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Mekanizma hızını düşünün: hangi süreç tek parça mekanik bir eylemdir, hangisi ikincil adımların zinciridir?\",\"ar\":\"فكر في سرعة الآلية: أي عملية هي فعل ميكانيكي من خطوة واحدة، وأيها سلسلة من خطوات الترحيل؟\",\"en\":\"Think about the speed and machinery: which process is an all-in-one mechanical action versus a relay of secondary steps?\"},{\"tier\":2,\"tr\":\"Nikotinik reseptörün poru bağlanma bölgesiyle aynı protein üzerindedir. Muskarinik reseptör ise sinyali G-proteinleri üzerinden iletmelidir.\",\"ar\":\"تحتوي مستقبلات النيكوتين على المسام مدمجاً مع موقع الارتباط. بينما يجب أن ترحل المستقبلات الموسكارينية الإشارة عبر بروتينات G.\",\"en\":\"Nicotinic receptors have the channel built into the binding site. Muscarinic receptors must relay the signal through G-proteins.\"},{\"tier\":3,\"tr\":\"Doğrudan kol ligand kapılı nikotinik iyon kanalını (anlık por açılması); ulak ise muskarinik GPCR ikinci haberci kaskadını modeller.\",\"ar\":\"تمثل الرافعة قنوات النيكوتين الأيونية (فتح ميكانيكي مباشر للمسام)؛ ويمثل الرسول شلال المستقبلات الموسكارينية المقترنة بـ GPCR.\",\"en\":\"The lever directly opens the channel pore (ionotropic nicotinic receptor). The messenger navigates biochemical pathways to activate effectors (metabotropic GPCR).\"}],\"config\":{\"options\":[{\"id\":\"opt-l8-s3-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Doğrudan kol, ligand kapılı nikotinik iyon kanallarını modeller (anlık por açılması); ulak ise muskarinik GPCR'ları modeller (çok basamaklı biyokimyasal kaskad).\",\"ar\":\"تمثل الرافعة قنوات النيكوتين الأيونية (فتح فوري للمسام)؛ بينما يمثل الرسول مستقبلات GPCR الموسكارينية (شلال كيميائي حيوي متعدد المراحل).\",\"en\":\"The lever represents ligand-gated nicotinic ion channels (direct intrinsic pore opening); the messenger represents muscarinic GPCRs (multi-step intracellular biochemical cascade).\"},\"feedback\":{\"tr\":\"Doğru. İyonotropik nikotinik kanallar reseptör ve poru tek bir komplekste birleştirir (anlık kol). Muskarinik GPCR'lar ise G-proteini ve ikinci haberciler gerektirir (ulak).\",\"ar\":\"صحيح. تدمج قنوات النيكوتين المستقبل والمسام في معقد واحد (رافعة فورية)؛ بينما تتطلب GPCR الموسكارينية بروتينات G ومراسيل ثانوية (رسول).\",\"en\":\"Correct. Ionotropic nicotinic channels combine receptor and pore in one protein complex (instant lever). Metabotropic GPCRs require G-protein relays (messenger).\"}},{\"id\":\"opt-l8-s3-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Doğrudan kol yavaş muskarinik GPCR transkripsiyonunu modeller; ulak ise lipid çift tabakasından hızlı veziküler ekzositozu modeller.\",\"ar\":\"تمثل الرافعة استنساخ GPCR الموسكاريني البطيء؛ ويمثل الرسول الإخراج الخلوي الحويصلي السريع عبر طبقة الليبيد.\",\"en\":\"The lever represents slow muscarinic GPCR transcription; the messenger represents fast vesicular exocytosis through the lipid bilayer.\"},\"feedback\":{\"tr\":\"Yanlış. Kol benzetmesi agonist bağlanınca iyon kanalının doğrudan açılmasını modeller; nükleer transkripsiyonla ilgisi yoktur.\",\"ar\":\"غير صحيح. يمثل تشبيه الرافعة الفتح المباشر لمسام القناة الأيونية عند ارتباط المنبه، ولا علاقة له بالاستنساخ النووي.\",\"en\":\"Incorrect. The lever models the mechanical opening of the ionotropic channel pore upon agonist binding, not nuclear transcription.\"}},{\"id\":\"opt-l8-s3-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Doğrudan kol asetilkolinesterazın kolini hidroliz etmesini modeller; ulak ise asetatın mitokondriye geri difüzyonunu modeller.\",\"ar\":\"تمثل الرافعة حلمهة الكولين بإنزيم كولينستراز؛ ويمثل الرسول انتشار الأسيتات عائداً إلى الميتوكوندريا.\",\"en\":\"The lever represents acetylcholinesterase hydrolysis of choline; the messenger represents acetate diffusion back into mitochondria.\"},\"feedback\":{\"tr\":\"Yanlış. Her iki analoji de post-sinaptik sinyal iletim mekanizmalarını karşılaştırmak içindir, enzimatik yıkım için değil.\",\"ar\":\"غير صحيح. يصف كلا التشبيهين آليات تحويل الإشارة بعد المشبكية، مقارنين بين فتح القنوات المباشر وشلالات GPCR.\",\"en\":\"Incorrect. Both analogies describe post-synaptic transduction mechanisms, contrasting direct channel opening with GPCR second messenger cascades.\"}}],\"prompt\":{\"tr\":\"Bir kalenin asma köprüsünü doğrudan bir kol çekerek açmakla, koridorlardan ulak gönderip kapının açılmasını talep etmeyi kıyaslayın. Bu kolinerjik iletimi nasıl modeller?\",\"ar\":\"قارن بين فتح جسر قلعة بسحب رافعة مباشرة وبين إرسال رسول عبر الأروقة لطلب فتح البوابة. كيف يمثل ذلك النقل الكوليني؟\",\"en\":\"Compare opening a castle drawbridge by pulling a direct lever versus dispatching a messenger through corridors to request gate opening. How does this model cholinergic transmission?\"},\"title\":{\"tr\":\"Fiziksel Sezgi: Asma Köprü Kolu ve Belediye Ulağı\",\"ar\":\"الحدس الفيزيائي: رافعة الجسر مقابل رسول البلدية\",\"en\":\"Physical Intuition: The Drawbridge vs The City Hall Messenger\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":19}]},{\"id\":\"pharm-mod4-les2-step4\",\"order\":4,\"stageIndex\":4,\"stage\":\"visual_explanation\",\"type\":\"visual_explanation\",\"title\":{\"tr\":\"Görsel Açıklama: Asetilkolin Sinaptik Yaşam Döngüsü\",\"ar\":\"شرح مرئي: دورة حياة الأسيتيل كولين المشبكية\",\"en\":\"Visual Explanation: Acetylcholine Synaptic Life Cycle\"},\"prompt\":{\"tr\":\"Kolinerjik sinaps yaşam döngüsünü inceleyin: Asetilkolin sentezindeki birincil hız kısıtlayıcı basamak nedir ve botulinum nörotoksini tam olarak hangi noktada müdahale eder?\",\"ar\":\"راجع دورة حياة المشبك الكوليني: ما هي الخطوة المحددة للسرعة في اصطناع الأسيتيل كولين، وأين يتدخل ذيفان البوتولينوم بالتحديد؟\",\"en\":\"Review the cholinergic synapse life cycle: What constitutes the primary rate-limiting step in acetylcholine synthesis, and at what specific point does botulinum neurotoxin intervene?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Asetilkolin sentezinde hız kısıtlayıcı basamak hangisidir ve botulinum toksini nereyi vurur?\",\"ar\":\"ما هي الخطوة المحددة للسرعة في اصطناع الأسيتيل كولين وأين يؤثر ذيفان البوتولينوم؟\",\"en\":\"What is the rate-limiting step in acetylcholine synthesis and where does botulinum toxin act?\"},\"options\":[{\"id\":\"opt-l8-s4-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Hız kısıtlayıcı basamak sodyum bağımlı yüksek afiniteli kolin geri alımıdır (CHT1); Botulinum nörotoksini presinaptik SNARE proteinlerini keserek veziküler ekzositozu engeller.\",\"ar\":\"الخطوة المحددة للسرعة هي إعادة التقاط الكولين عالية الألفة المعتمدة على الصوديوم (CHT1)؛ ويقطع ذيفان البوتولينوم بروتينات SNARE مانعاً تحرر الأسيتيل كولين.\",\"en\":\"Rate-limiting step is high-affinity sodium-dependent choline reuptake (CHT1); Botulinum neurotoxin cleaves presynaptic SNARE proteins, blocking vesicular acetylcholine exocytosis.\"},\"feedback\":{\"tr\":\"Doğru. Yüksek afiniteli kolin alımı (CHT1) hız kısıtlayıcıdır (hemikolinyum ile bloke edilir). Botulinum toksini SNARE kompleksini (SNAP-25 vb.) keserek ekzositozu durdurur.\",\"ar\":\"صحيح. التقاط الكولين عالي الألفة (CHT1) هو المحدد للسرعة (يحصر بـ هيميكولينيوم). ويقطع ذيفان البوتولينوم بروتينات SNARE موقفاً الإخراج الخلوي.\",\"en\":\"Correct. High-affinity choline uptake (CHT1) is the rate-limiting step. Botulinum toxin cleaves SNARE complex proteins (SNAP-25, syntaxin, synaptobrevin), arresting exocytosis.\"}},{\"id\":\"opt-l8-s4-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Hız kısıtlayıcı basamak kolin asetiltransferaz (ChAT) hızıdır; Botulinum nörotoksini asetilkolini tüketmek için sinaptik asetilkolinesterazı aşırı aktive eder.\",\"ar\":\"الخطوة المحددة هي سرعة إنزيم ChAT؛ وينشط ذيفان البوتولينوم كولينستراز الأسيتيل المشبكي بشدة لاستنزاف الأسيتيل كولين.\",\"en\":\"Rate-limiting step is choline acetyltransferase (ChAT) velocity; Botulinum neurotoxin hyper-activates synaptic acetylcholinesterase to deplete acetylcholine.\"},\"feedback\":{\"tr\":\"Yanlış. ChAT enzimi aşırı kapasiteyle çalışır, hız kısıtlayıcı değildir. Botulinum toksini AChE'yi değil, SNARE proteinlerini keser.\",\"ar\":\"غير صحيح. يعمل إنزيم ChAT بفائض قدرة ولا يحدد السرعة. ويقطع ذيفان البوتولينوم بروتينات SNARE وليس إنزيم AChE.\",\"en\":\"Incorrect. ChAT is not rate-limiting (operates with excess capacity); choline uptake is rate-limiting. Botulinum toxin cleaves SNARE fusion proteins, not AChE.\"}},{\"id\":\"opt-l8-s4-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Hız kısıtlayıcı basamak VAChT ile veziküler depolamadır; Botulinum nörotoksini sodyum-kolin kotransporterı CHT1'i yarışmalı olarak inhibe eder.\",\"ar\":\"الخطوة المحددة هي التخزين الحويصلي عبر VAChT؛ ويثبط ذيفان البوتولينوم تنافسياً ناقل الصوديوم والكولين CHT1.\",\"en\":\"Rate-limiting step is vesicular storage via VAChT; Botulinum neurotoxin competitively inhibits the sodium-choline cotransporter CHT1.\"},\"feedback\":{\"tr\":\"Yanlış. Hemikolinyum-3 CHT1'i bloke eder; vezamikol VAChT'yi bloke eder. Botulinum toksini ise çinko-endopeptidaz olarak SNARE'i parçalar.\",\"ar\":\"غير صحيح. يحصر هيميكولينيوم-3 ناقل CHT1؛ ويحصر فيزاميكول ناقل VAChT. بينما يعمل ذيفان البوتولينوم كإندوببتيداز زنك يشطر SNARE.\",\"en\":\"Incorrect. Hemicholinium-3 blocks CHT1; vesamicol blocks VAChT. Botulinum toxin is a zinc-endopeptidase that proteolytically cleaves SNARE proteins.\"}}]},\"technicalTerms\":[{\"term\":\"SNARE Kompleksi\",\"arContext\":\"معقد بروتينات SNARE (SNARE Complex)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Kolin substratının nereden geldiğini ve presinaptik terminale nasıl girdiğini düşünün.\",\"ar\":\"فكر في مصدر ركيزة الكولين وكيفية دخولها إلى النهاية العصبية قبل المشبكية.\",\"en\":\"Where does the raw choline substrate originate and how does it enter the presynaptic nerve terminal?\"},{\"tier\":2,\"tr\":\"Yüksek afiniteli CHT1 taşıyıcısı ile kolin geri alımı toplam sentez hızını sınırlar. Botulinum ise vezikül füzyon mekanizmasını hedefler.\",\"ar\":\"يحدد التقاط الكولين عبر ناقل CHT1 عالي الألفة سرعة الاصطناع الكلية. بينما يستهدف البوتولينوم آليات اندماج الحويصلات.\",\"en\":\"The uptake of choline through the high-affinity CHT1 transporter limits overall synthesis rate. Botulinum targets the fusion machinery.\"},{\"tier\":3,\"tr\":\"Sodyum bağımlı yüksek afiniteli kolin geri alımı (CHT1) hız kısıtlayıcıdır; Botulinum nörotoksini SNARE kompleksini keserek vezikül ekzositozunu bloke eder.\",\"ar\":\"التقاط الكولين عالي الألفة المعتمد على الصوديوم (CHT1) هو الخطوة المحددة للسرعة؛ ويقطع ذيفان البوتولينوم معقد SNARE مانعاً إفراز الحويصلات.\",\"en\":\"High-affinity Na+-dependent choline reuptake (CHT1) is rate-limiting. Botulinum neurotoxin cleaves the SNARE complex, preventing vesicle fusion and transmitter release.\"}],\"config\":{\"options\":[{\"id\":\"opt-l8-s4-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Hız kısıtlayıcı basamak sodyum bağımlı yüksek afiniteli kolin geri alımıdır (CHT1); Botulinum nörotoksini presinaptik SNARE proteinlerini keserek veziküler ekzositozu engeller.\",\"ar\":\"الخطوة المحددة للسرعة هي إعادة التقاط الكولين عالية الألفة المعتمدة على الصوديوم (CHT1)؛ ويقطع ذيفان البوتولينوم بروتينات SNARE مانعاً تحرر الأسيتيل كولين.\",\"en\":\"Rate-limiting step is high-affinity sodium-dependent choline reuptake (CHT1); Botulinum neurotoxin cleaves presynaptic SNARE proteins, blocking vesicular acetylcholine exocytosis.\"},\"feedback\":{\"tr\":\"Doğru. Yüksek afiniteli kolin alımı (CHT1) hız kısıtlayıcıdır (hemikolinyum ile bloke edilir). Botulinum toksini SNARE kompleksini (SNAP-25 vb.) keserek ekzositozu durdurur.\",\"ar\":\"صحيح. التقاط الكولين عالي الألفة (CHT1) هو المحدد للسرعة (يحصر بـ هيميكولينيوم). ويقطع ذيفان البوتولينوم بروتينات SNARE موقفاً الإخراج الخلوي.\",\"en\":\"Correct. High-affinity choline uptake (CHT1) is the rate-limiting step. Botulinum toxin cleaves SNARE complex proteins (SNAP-25, syntaxin, synaptobrevin), arresting exocytosis.\"}},{\"id\":\"opt-l8-s4-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Hız kısıtlayıcı basamak kolin asetiltransferaz (ChAT) hızıdır; Botulinum nörotoksini asetilkolini tüketmek için sinaptik asetilkolinesterazı aşırı aktive eder.\",\"ar\":\"الخطوة المحددة هي سرعة إنزيم ChAT؛ وينشط ذيفان البوتولينوم كولينستراز الأسيتيل المشبكي بشدة لاستنزاف الأسيتيل كولين.\",\"en\":\"Rate-limiting step is choline acetyltransferase (ChAT) velocity; Botulinum neurotoxin hyper-activates synaptic acetylcholinesterase to deplete acetylcholine.\"},\"feedback\":{\"tr\":\"Yanlış. ChAT enzimi aşırı kapasiteyle çalışır, hız kısıtlayıcı değildir. Botulinum toksini AChE'yi değil, SNARE proteinlerini keser.\",\"ar\":\"غير صحيح. يعمل إنزيم ChAT بفائض قدرة ولا يحدد السرعة. ويقطع ذيفان البوتولينوم بروتينات SNARE وليس إنزيم AChE.\",\"en\":\"Incorrect. ChAT is not rate-limiting (operates with excess capacity); choline uptake is rate-limiting. Botulinum toxin cleaves SNARE fusion proteins, not AChE.\"}},{\"id\":\"opt-l8-s4-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Hız kısıtlayıcı basamak VAChT ile veziküler depolamadır; Botulinum nörotoksini sodyum-kolin kotransporterı CHT1'i yarışmalı olarak inhibe eder.\",\"ar\":\"الخطوة المحددة هي التخزين الحويصلي عبر VAChT؛ ويثبط ذيفان البوتولينوم تنافسياً ناقل الصوديوم والكولين CHT1.\",\"en\":\"Rate-limiting step is vesicular storage via VAChT; Botulinum neurotoxin competitively inhibits the sodium-choline cotransporter CHT1.\"},\"feedback\":{\"tr\":\"Yanlış. Hemikolinyum-3 CHT1'i bloke eder; vezamikol VAChT'yi bloke eder. Botulinum toksini ise çinko-endopeptidaz olarak SNARE'i parçalar.\",\"ar\":\"غير صحيح. يحصر هيميكولينيوم-3 ناقل CHT1؛ ويحصر فيزاميكول ناقل VAChT. بينما يعمل ذيفان البوتولينوم كإندوببتيداز زنك يشطر SNARE.\",\"en\":\"Incorrect. Hemicholinium-3 blocks CHT1; vesamicol blocks VAChT. Botulinum toxin is a zinc-endopeptidase that proteolytically cleaves SNARE proteins.\"}}],\"prompt\":{\"tr\":\"Kolinerjik sinaps yaşam döngüsünü inceleyin: Asetilkolin sentezindeki birincil hız kısıtlayıcı basamak nedir ve botulinum nörotoksini tam olarak hangi noktada müdahale eder?\",\"ar\":\"راجع دورة حياة المشبك الكوليني: ما هي الخطوة المحددة للسرعة في اصطناع الأسيتيل كولين، وأين يتدخل ذيفان البوتولينوم بالتحديد؟\",\"en\":\"Review the cholinergic synapse life cycle: What constitutes the primary rate-limiting step in acetylcholine synthesis, and at what specific point does botulinum neurotoxin intervene?\"},\"title\":{\"tr\":\"Görsel Açıklama: Asetilkolin Sinaptik Yaşam Döngüsü\",\"ar\":\"شرح مرئي: دورة حياة الأسيتيل كولين المشبكية\",\"en\":\"Visual Explanation: Acetylcholine Synaptic Life Cycle\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":20}]},{\"id\":\"pharm-mod4-les2-step5\",\"order\":5,\"stageIndex\":5,\"stage\":\"interactive_artifact\",\"type\":\"interactive_artifact\",\"title\":{\"tr\":\"İnteraktif Deney: Asetilkolin-M3 Reseptör Kenetlenmesi\",\"ar\":\"تجربة تفاعلية: تطابق الأسيتيل كولين مع مستقبل M3\",\"en\":\"Interactive Experiment: Acetylcholine-M3 Receptor Docking\"},\"prompt\":{\"tr\":\"Asetilkolinin kuaterner amonyum, ester karbonil ve etilen gruplarını M3 muskarinik reseptör aktif cebindeki Asp147, Tyr506, Asn507 ve Trp199 kalıntılarıyla eşleştirin.\",\"ar\":\"طابق مجموعات الأمونيوم الرباعي وإستر الكربونيل والإيثيلين للأسيتيل كولين مع ثمالات Asp147 و Tyr506 و Asn507 و Trp199 في جيب مستقبل M3.\",\"en\":\"Dock acetylcholine into the M3 muscarinic pocket by matching its quaternary ammonium, ester carbonyl, and ethylene spacer to Asp147, Tyr506, Asn507, and Trp199.\"},\"widgetType\":\"ReceptorLigandMatcher\",\"widget\":{\"type\":\"ReceptorLigandMatcher\",\"config\":{\"title\":\"Asetilkolin - M3 Muskarinik Reseptör Kenetlenmesi\",\"prompt\":\"Asetilkolin molekülünün yapısal kısımlarını M3 reseptör cebindeki amino asit kalıntılarıyla eşleştirin.\",\"drugName\":\"Asetilkolin (Acetylcholine)\",\"receptorName\":\"M3 Muskarinik GPCR\",\"pairs\":[{\"id\":\"pair-1\",\"drugGroup\":\"Kuaterner Amonyum Katyonu (-N+(CH3)3)\",\"correctResidueId\":\"res-asp147\",\"bondType\":\"ionic\",\"energyKcalMol\":\"-6 to -10 kcal/mol\",\"explanation\":\"Pozitif yüklü kuaterner amonyum başı, TM3 heliksindeki Asp147 karboksilat anyonu ile zorunlu elektrostatik tuz köprüsü kurar.\"},{\"id\":\"pair-2\",\"drugGroup\":\"Kuaterner Amonyum Metil Grupları\",\"correctResidueId\":\"res-tyr506\",\"bondType\":\"pi_pi\",\"energyKcalMol\":\"-3 to -6 kcal/mol\",\"explanation\":\"Kuaterner amonyumun pozitif yükü, TM6 heliksindeki Tyr506 aromatik halkasının pi elektron bulutuyla katyon-pi etkileşimi yapar.\"},{\"id\":\"pair-3\",\"drugGroup\":\"Ester Karbonil Oksijeni (C=O)\",\"correctResidueId\":\"res-asn507\",\"bondType\":\"h_bond\",\"energyKcalMol\":\"-3 to -6 kcal/mol\",\"explanation\":\"Ester karbonil oksijeni, TM6'daki Asn507 yan zincir amidi ile spesifik dipol-dipol hidrojen bağı kurar.\"},{\"id\":\"pair-4\",\"drugGroup\":\"Etilen Köprüsü (-CH2-CH2-)\",\"correctResidueId\":\"res-trp199\",\"bondType\":\"van_der_waals\",\"energyKcalMol\":\"-1.5 to -3 kcal/mol\",\"explanation\":\"İki karbonlu etilen köprüsü, TM5 heliksindeki Trp199 indol halkasıyla hidrofobik van der Waals teması kurar.\"}],\"residues\":[{\"id\":\"res-asp147\",\"residueName\":\"Asp147 (TM3)\",\"description\":\"Negatif yüklü aspartat kalıntısı; asetilkolinin kuaterner amonyum katyonunu tuz köprüsüyle bağlar.\"},{\"id\":\"res-tyr506\",\"residueName\":\"Tyr506 (TM6)\",\"description\":\"Aromatik tirozin halkası; kuaterner amonyum ile katyon-pi etkileşimi oluşturur.\"},{\"id\":\"res-asn507\",\"residueName\":\"Asn507 (TM6)\",\"description\":\"Polar asparajin kalıntısı; ester karbonil grubuyla hidrojen bağı akseptörü/donörü olarak etkileşir.\"},{\"id\":\"res-trp199\",\"residueName\":\"Trp199 (TM5)\",\"description\":\"Büyük aromatik triptofan kalıntısı; etilen köprüsünü van der Waals temaslarıyla destekler.\"},{\"id\":\"res-leu225\",\"residueName\":\"Leu225 (TM5)\",\"description\":\"Hidrofobik lösin yan zinciri; terminal asetil metil grubunu çevreleyen apolar cep.\"}],\"source\":{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":22}}},\"config\":{\"title\":\"Asetilkolin - M3 Muskarinik Reseptör Kenetlenmesi\",\"prompt\":\"Asetilkolin molekülünün yapısal kısımlarını M3 reseptör cebindeki amino asit kalıntılarıyla eşleştirin.\",\"drugName\":\"Asetilkolin (Acetylcholine)\",\"receptorName\":\"M3 Muskarinik GPCR\",\"pairs\":[{\"id\":\"pair-1\",\"drugGroup\":\"Kuaterner Amonyum Katyonu (-N+(CH3)3)\",\"correctResidueId\":\"res-asp147\",\"bondType\":\"ionic\",\"energyKcalMol\":\"-6 to -10 kcal/mol\",\"explanation\":\"Pozitif yüklü kuaterner amonyum başı, TM3 heliksindeki Asp147 karboksilat anyonu ile zorunlu elektrostatik tuz köprüsü kurar.\"},{\"id\":\"pair-2\",\"drugGroup\":\"Kuaterner Amonyum Metil Grupları\",\"correctResidueId\":\"res-tyr506\",\"bondType\":\"pi_pi\",\"energyKcalMol\":\"-3 to -6 kcal/mol\",\"explanation\":\"Kuaterner amonyumun pozitif yükü, TM6 heliksindeki Tyr506 aromatik halkasının pi elektron bulutuyla katyon-pi etkileşimi yapar.\"},{\"id\":\"pair-3\",\"drugGroup\":\"Ester Karbonil Oksijeni (C=O)\",\"correctResidueId\":\"res-asn507\",\"bondType\":\"h_bond\",\"energyKcalMol\":\"-3 to -6 kcal/mol\",\"explanation\":\"Ester karbonil oksijeni, TM6'daki Asn507 yan zincir amidi ile spesifik dipol-dipol hidrojen bağı kurar.\"},{\"id\":\"pair-4\",\"drugGroup\":\"Etilen Köprüsü (-CH2-CH2-)\",\"correctResidueId\":\"res-trp199\",\"bondType\":\"van_der_waals\",\"energyKcalMol\":\"-1.5 to -3 kcal/mol\",\"explanation\":\"İki karbonlu etilen köprüsü, TM5 heliksindeki Trp199 indol halkasıyla hidrofobik van der Waals teması kurar.\"}],\"residues\":[{\"id\":\"res-asp147\",\"residueName\":\"Asp147 (TM3)\",\"description\":\"Negatif yüklü aspartat kalıntısı; asetilkolinin kuaterner amonyum katyonunu tuz köprüsüyle bağlar.\"},{\"id\":\"res-tyr506\",\"residueName\":\"Tyr506 (TM6)\",\"description\":\"Aromatik tirozin halkası; kuaterner amonyum ile katyon-pi etkileşimi oluşturur.\"},{\"id\":\"res-asn507\",\"residueName\":\"Asn507 (TM6)\",\"description\":\"Polar asparajin kalıntısı; ester karbonil grubuyla hidrojen bağı akseptörü/donörü olarak etkileşir.\"},{\"id\":\"res-trp199\",\"residueName\":\"Trp199 (TM5)\",\"description\":\"Büyük aromatik triptofan kalıntısı; etilen köprüsünü van der Waals temaslarıyla destekler.\"},{\"id\":\"res-leu225\",\"residueName\":\"Leu225 (TM5)\",\"description\":\"Hidrofobik lösin yan zinciri; terminal asetil metil grubunu çevreleyen apolar cep.\"}],\"source\":{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":22}},\"technicalTerms\":[{\"term\":\"Katyon-Pi Etkileşimi\",\"arContext\":\"تأثر الكاتيون بحلقة باي (Cation-Pi Interaction)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Asetilkolinin pozitif yüklü kuaterner amonyumunu, ester karbonilini ve etilen zincirini inceleyin.\",\"ar\":\"افحص الأمونيوم الرابعي الموجب وإستر الكربونيل وجسر الإيثيلين في الأسيتيل كولين.\",\"en\":\"Examine acetylcholine's positively charged quaternary ammonium, ester carbonyl, and ethylene spacer.\"},{\"tier\":2,\"tr\":\"Asp147 kuaterner amonyum ile iyonik bağ kurar; Tyr506 katyon-pi kafesi oluşturur; Asn507 ester oksijeniyle H-bağı yapar.\",\"ar\":\"يشكل Asp147 رابطاً أيونياً مع الأمونيوم؛ ويوفر Tyr506 قفصاً عطرياً (كاتيون-باي)؛ ويصنع Asn507 رابطاً هيدروجينياً مع الإستر.\",\"en\":\"Asp147 provides an ionic anchor for quaternary ammonium; Tyr506 creates a cation-pi cage; Asn507 H-bonds with carbonyl.\"},{\"tier\":3,\"tr\":\"Kuaterner azotu Asp147'ye (iyonik), kolin metillerini Tyr506'ya (pi-pi), karbonil oksijenini Asn507'ye (H-bağı) ve etilen omurgasını Trp199'a (van der Waals) yerleştirin.\",\"ar\":\"اربط الأمونيوم الرابعي بـ Asp147 (أيوني)، والميثيل بـ Tyr506 (كاتيون-باي)، وأكسجين الكربونيل بـ Asn507 (هيدروجيني)، والإيثيلين بـ Trp199.\",\"en\":\"Dock quaternary ammonium into Asp147 (ionic), methyl groups into Tyr506 (cation-pi), ester carbonyl into Asn507 (H-bond), and ethylene into Trp199 (van der Waals).\"}],\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":21}]},{\"id\":\"pharm-mod4-les2-step6\",\"order\":6,\"stageIndex\":6,\"stage\":\"guided_discovery\",\"type\":\"guided_discovery\",\"title\":{\"tr\":\"Rehberli Keşif: Endotelyal M3 Vazodilatasyon Paradoksu\",\"ar\":\"استكشاف موجه: مفارقة التوسع الوعائي البطاني بـ M3\",\"en\":\"Guided Discovery: Endothelial M3 Vasodilatation Paradox\"},\"prompt\":{\"tr\":\"Damar düz kasında doğrudan parasempatik innervasyon yoktur. Sağlam vasküler endoteli olan bir bireyde intravenöz asetilkolin uygulaması nasıl sistemik vazodilatasyon ve hipotansiyona yol açar?\",\"ar\":\"تفتقر العضلات الملساء الوعائية للتعصيب نظير الودي المباشر. كيف يحدث إعطاء الأسيتيل كولين وريدياً توسعاً وعائياً وهبوط ضغط لدى شخص ببطانة وعائية سليمة؟\",\"en\":\"Vascular smooth muscle lacks direct parasympathetic innervation. How does intravenous acetylcholine administration provoke systemic vasodilation and hypotension in an individual with intact vascular endothelium?\"},\"conceptCheck\":{\"question\":{\"tr\":\"İntakt endoteli olan damarlarda intravenöz asetilkolin vazodilatasyonu nasıl tetikler?\",\"ar\":\"كيف يحفز الأسيتيل كولين وريدياً التوسع الوعائي في الأوعية ذات البطانة السليمة؟\",\"en\":\"How does intravenous acetylcholine trigger vasodilation in vessels with an intact endothelial layer?\"},\"options\":[{\"id\":\"opt-l8-s6-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Endotelyal M3 reseptörleri Gq ile Ca2+ salarak eNOS'u aktive eder ve Nitrik Oksit (NO) üretir; NO düz kasa difüze olup guanilat siklazı uyararak cGMP sentezler.\",\"ar\":\"تحفز مستقبلات M3 البطانية تحرر الكالسيوم عبر Gq، منشطة eNOS لإنتاج أكسيد النيتريك (NO)؛ ينتشر NO للعضلات الملساء منشطاً محلقة الغوانيلات لإنتاج cGMP.\",\"en\":\"Endothelial M3 receptors trigger Gq-mediated Ca2+ release, activating eNOS to produce Nitric Oxide (NO); NO diffuses into smooth muscle, activating guanylyl cyclase to generate cGMP.\"},\"feedback\":{\"tr\":\"Doğru. Furchgott'un EDRF keşfi: endotelyal M3 NO salar, düz kasta cGMP artışı gevşeme yapar. Endotel hasarlıysa asetilkolin doğrudan düz kası büzerek vazokonstriksiyon yapar.\",\"ar\":\"صحيح. اكتشاف فورشغوت لـ EDRF: يحرر M3 البطاني أكسيد النيتريك رافعاً cGMP ومحدثاً الارتخاء. في حال غياب البطانة، يضيق الأسيتيل كولين العضلة الملساء مباشرة.\",\"en\":\"Correct. Furchgott's EDRF discovery: endothelial M3 activation releases nitric oxide (NO), stimulating guanylyl cyclase in smooth muscle to induce cGMP-mediated relaxation.\"}},{\"id\":\"opt-l8-s6-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Asetilkolin damar düz kası beta-2 adrenerjik reseptörlerine bağlanarak adenilat siklazı aktive eder ve gevşetici cAMP üretir.\",\"ar\":\"يرتبط الأسيتيل كولين بمستقبلات بيتا-2 الأدرينالينية في العضلات الملساء، منشطاً محلقة الأدينيلات لإنتاج cAMP المرخي.\",\"en\":\"Acetylcholine binds vascular smooth muscle beta-2 adrenergic receptors, activating adenylyl cyclase and generating relaxing cAMP.\"},\"feedback\":{\"tr\":\"Yanlış. Asetilkolin adrenerjik beta-2 reseptörlerine bağlanmaz; vazodilatasyon endotelyal muskarinik M3 / NO / cGMP kaskadıyla yönetilir.\",\"ar\":\"غير صحيح. لا يرتبط الأسيتيل كولين بمستقبلات بيتا-2؛ ويتوسط التوسع الوعائي مستقبلات M3 البطانية عبر شلال أكسيد النيتريك/cGMP.\",\"en\":\"Incorrect. Acetylcholine does not bind adrenergic beta-2 receptors; vasodilation is mediated by endothelial muscarinic M3 receptors via the NO/cGMP cascade.\"}},{\"id\":\"opt-l8-s6-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Damar düz kası, endotel katılımı olmaksızın potasyum kanallarını doğrudan açan bol miktarda inhibitör M2 reseptörü ifade eder.\",\"ar\":\"تعبر العضلات الملساء الوعائية عن مستقبلات M2 تثبيطية وفيرة تفتح قنوات البوتاسيوم مباشرة دون تدخل البطانة.\",\"en\":\"Vascular smooth muscle expresses abundant inhibitory M2 receptors that directly open potassium channels without endothelial involvement.\"},\"feedback\":{\"tr\":\"Yanlış. Endotelin kazınması vazodilatasyonu tamamen yok eder ve paradoksal vazokonstriksiyonu açığa çıkarır; bu da endotel zorunluluğunu kanıtlar.\",\"ar\":\"غير صحيح. يؤدي كشط البطانة إلى إلغاء التوسع الوعائي كلياً وكشف تضيق وعائي متناقض، مما يثبت الاعتماد المطلق على البطانة.\",\"en\":\"Incorrect. Endothelial denudation completely abolishes acetylcholine-induced vasodilation and unmasks vasoconstriction, proving obligatory endothelial mediation.\"}}]},\"technicalTerms\":[{\"term\":\"Endotelyal Nitrik Oksit Sentaz\",\"arContext\":\"إنزيم سينثاز أكسيد النيتريك البطاني (Endothelial Nitric Oxide Synthase (eNOS))\"}],\"hints\":[{\"tier\":1,\"tr\":\"Robert Furchgott'un Nobel ödüllü deneyini hatırlayın: endotel tabakası kazınırsa asetilkolinin etkisi tamamen tersine döner.\",\"ar\":\"تذكر تجربة روبرت فورشغوت الحائزة على نوبل: إذا كُشطت البطانة، ينعكس تأثير الأسيتيل كولين تماماً.\",\"en\":\"Remember Robert Furchgott's Nobel-winning experiment: the response to acetylcholine flips completely if the endothelial lining is removed.\"},{\"tier\":2,\"tr\":\"Endotel hücreleri, gaz halinde bir vazodilatatör haberci (Nitrik Oksit) sentezleyen bir enzime kenetli M3 reseptörleri taşır.\",\"ar\":\"تحمل الخلايا البطانية مستقبلات M3 المقترنة بإنزيم يصنع مرسالاً موسعاً غازياً (أكسيد النيتريك).\",\"en\":\"Endothelial cells express M3 receptors coupled to an enzyme that synthesizes a gaseous vasodilator messenger (Nitric Oxide).\"},{\"tier\":3,\"tr\":\"Endotelyal M3 uyarımı eNOS aracılığıyla Nitrik Oksit (NO) salar; NO düz kasa difüze olup cGMP'yi yükseltir ve gevşeme yaptırır.\",\"ar\":\"يحفز تنبيه M3 البطاني إطلاق أكسيد النيتريك (NO) عبر eNOS؛ ينتشر NO للعضلات الملساء رافعاً cGMP ومحدثاً الارتخاء.\",\"en\":\"Endothelial M3 stimulation releases Nitric Oxide (NO) via eNOS; NO diffuses into vascular smooth muscle, raising cGMP and driving relaxation.\"}],\"config\":{\"options\":[{\"id\":\"opt-l8-s6-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Endotelyal M3 reseptörleri Gq ile Ca2+ salarak eNOS'u aktive eder ve Nitrik Oksit (NO) üretir; NO düz kasa difüze olup guanilat siklazı uyararak cGMP sentezler.\",\"ar\":\"تحفز مستقبلات M3 البطانية تحرر الكالسيوم عبر Gq، منشطة eNOS لإنتاج أكسيد النيتريك (NO)؛ ينتشر NO للعضلات الملساء منشطاً محلقة الغوانيلات لإنتاج cGMP.\",\"en\":\"Endothelial M3 receptors trigger Gq-mediated Ca2+ release, activating eNOS to produce Nitric Oxide (NO); NO diffuses into smooth muscle, activating guanylyl cyclase to generate cGMP.\"},\"feedback\":{\"tr\":\"Doğru. Furchgott'un EDRF keşfi: endotelyal M3 NO salar, düz kasta cGMP artışı gevşeme yapar. Endotel hasarlıysa asetilkolin doğrudan düz kası büzerek vazokonstriksiyon yapar.\",\"ar\":\"صحيح. اكتشاف فورشغوت لـ EDRF: يحرر M3 البطاني أكسيد النيتريك رافعاً cGMP ومحدثاً الارتخاء. في حال غياب البطانة، يضيق الأسيتيل كولين العضلة الملساء مباشرة.\",\"en\":\"Correct. Furchgott's EDRF discovery: endothelial M3 activation releases nitric oxide (NO), stimulating guanylyl cyclase in smooth muscle to induce cGMP-mediated relaxation.\"}},{\"id\":\"opt-l8-s6-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Asetilkolin damar düz kası beta-2 adrenerjik reseptörlerine bağlanarak adenilat siklazı aktive eder ve gevşetici cAMP üretir.\",\"ar\":\"يرتبط الأسيتيل كولين بمستقبلات بيتا-2 الأدرينالينية في العضلات الملساء، منشطاً محلقة الأدينيلات لإنتاج cAMP المرخي.\",\"en\":\"Acetylcholine binds vascular smooth muscle beta-2 adrenergic receptors, activating adenylyl cyclase and generating relaxing cAMP.\"},\"feedback\":{\"tr\":\"Yanlış. Asetilkolin adrenerjik beta-2 reseptörlerine bağlanmaz; vazodilatasyon endotelyal muskarinik M3 / NO / cGMP kaskadıyla yönetilir.\",\"ar\":\"غير صحيح. لا يرتبط الأسيتيل كولين بمستقبلات بيتا-2؛ ويتوسط التوسع الوعائي مستقبلات M3 البطانية عبر شلال أكسيد النيتريك/cGMP.\",\"en\":\"Incorrect. Acetylcholine does not bind adrenergic beta-2 receptors; vasodilation is mediated by endothelial muscarinic M3 receptors via the NO/cGMP cascade.\"}},{\"id\":\"opt-l8-s6-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Damar düz kası, endotel katılımı olmaksızın potasyum kanallarını doğrudan açan bol miktarda inhibitör M2 reseptörü ifade eder.\",\"ar\":\"تعبر العضلات الملساء الوعائية عن مستقبلات M2 تثبيطية وفيرة تفتح قنوات البوتاسيوم مباشرة دون تدخل البطانة.\",\"en\":\"Vascular smooth muscle expresses abundant inhibitory M2 receptors that directly open potassium channels without endothelial involvement.\"},\"feedback\":{\"tr\":\"Yanlış. Endotelin kazınması vazodilatasyonu tamamen yok eder ve paradoksal vazokonstriksiyonu açığa çıkarır; bu da endotel zorunluluğunu kanıtlar.\",\"ar\":\"غير صحيح. يؤدي كشط البطانة إلى إلغاء التوسع الوعائي كلياً وكشف تضيق وعائي متناقض، مما يثبت الاعتماد المطلق على البطانة.\",\"en\":\"Incorrect. Endothelial denudation completely abolishes acetylcholine-induced vasodilation and unmasks vasoconstriction, proving obligatory endothelial mediation.\"}}],\"prompt\":{\"tr\":\"Damar düz kasında doğrudan parasempatik innervasyon yoktur. Sağlam vasküler endoteli olan bir bireyde intravenöz asetilkolin uygulaması nasıl sistemik vazodilatasyon ve hipotansiyona yol açar?\",\"ar\":\"تفتقر العضلات الملساء الوعائية للتعصيب نظير الودي المباشر. كيف يحدث إعطاء الأسيتيل كولين وريدياً توسعاً وعائياً وهبوط ضغط لدى شخص ببطانة وعائية سليمة؟\",\"en\":\"Vascular smooth muscle lacks direct parasympathetic innervation. How does intravenous acetylcholine administration provoke systemic vasodilation and hypotension in an individual with intact vascular endothelium?\"},\"title\":{\"tr\":\"Rehberli Keşif: Endotelyal M3 Vazodilatasyon Paradoksu\",\"ar\":\"استكشاف موجه: مفارقة التوسع الوعائي البطاني بـ M3\",\"en\":\"Guided Discovery: Endothelial M3 Vasodilatation Paradox\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":22}]},{\"id\":\"pharm-mod4-les2-step7\",\"order\":7,\"stageIndex\":7,\"stage\":\"formal_explanation\",\"type\":\"formal_explanation\",\"title\":{\"tr\":\"Biçimsel Açıklama: Kanonik Kolinoseptör Mimarisi\",\"ar\":\"شرح رسمي: البنية المعيارية للمستقبلات الكولينية\",\"en\":\"Formal Explanation: Canonical Cholinoceptor Architecture\"},\"prompt\":{\"tr\":\"Kanonik kolinerjik reseptör sınıflandırma tablosunu inceleyin. Hangi ifade bir kolinoseptör alt tipini, moleküler iletecini ve birincil fizyolojik yanıtını doğru eşleştirir?\",\"ar\":\"راجع جدول تصنيف المستقبلات الكولينية. أي عبارة تقرن بدقة بين نمط المستقبل الكوليني وموصله الجزيئي واستجابته الفسيولوجية الأساسية؟\",\"en\":\"Review the canonical cholinoceptor classification table. Which statement accurately pairs a cholinoceptor subtype with its molecular transducer and primary physiological response?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Hangi kolinerjik reseptör alt tipi, G-proteini ve fizyolojik yanıtıyla doğru eşleştirilmiştir?\",\"ar\":\"أي نمط فرعي للمستقبلات الكولينية مقترن بدقة ببروتين G واستجابته الفسيولوجية؟\",\"en\":\"Which cholinoceptor subtype is accurately matched with its G-protein and physiological response?\"},\"options\":[{\"id\":\"opt-l8-s7-1\",\"isCorrect\":true,\"text\":{\"tr\":\"M2 (Gi): Adenilat siklaz aktivitesini azaltır ve kardiyak pacemaker'da GIRK K+ kanallarını açarak kalp hızını yavaşlatır.\",\"ar\":\"M2 (Gi): يقلل نشاط محلقة الأدينيلات ويفتح قنوات البوتاسيوم GIRK في الناظمة القلبية، مبطئاً معدل ضربات القلب.\",\"en\":\"M2 (Gi): Decreases adenylyl cyclase activity and opens GIRK K+ channels in cardiac pacemaker, slowing heart rate.\"},\"feedback\":{\"tr\":\"Doğru. Muskarinik M2 reseptörleri Gi ile cAMP'yi düşürür ve G beta-gama ile içe doğrultucu GIRK K+ kanallarını açarak kalbi yavaşlatır.\",\"ar\":\"صحيح. تقترن مستقبلات M2 بـ Gi لخفض cAMP وفتح قنوات البوتاسيوم GIRK عبر بيتا-غاما مفرطة استقطاب العقد القلبية.\",\"en\":\"Correct. Muscarinic M2 receptors couple to Gi, inhibiting cAMP and directly opening GIRK K+ channels via G beta-gamma to slow heart rate.\"}},{\"id\":\"opt-l8-s7-2\",\"isCorrect\":false,\"text\":{\"tr\":\"M3 (Gi): Ekzokrin bezlerde fosfolipaz C'yi inhibe ederek tükürük ve gözyaşı salgılarını belirgin şekilde azaltır.\",\"ar\":\"M3 (Gi): يثبط فوسفوليباز C في الغدد خارجية الإفراز، مخفضاً الإفراز اللعابي والدمعي بشكل ملحوظ.\",\"en\":\"M3 (Gi): Inhibits phospholipase C in exocrine glands, dramatically reducing salivary and lacrimal secretions.\"},\"feedback\":{\"tr\":\"Yanlış. M3 Gi'ye değil Gq'ya kenetlenir ve PLC'yi aktive ederek hücre içi kalsiyumu artırır; ekzokrin salgıları güçlü şekilde uyarır.\",\"ar\":\"غير صحيح. يقترن M3 بـ Gq (وليس Gi) وينشط PLC لرفع الكالسيوم الداخلي، محفزاً الإفرازات الغدية بقوة.\",\"en\":\"Incorrect. M3 couples to Gq (not Gi) and activates PLC to increase intracellular calcium, powerfully stimulating secretions.\"}},{\"id\":\"opt-l8-s7-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Nm (Gs): Nöromusküler kavşakta adenilat siklazı aktive eder ve istemli tetanik kas kasılmasını sürdürmek için cAMP üretir.\",\"ar\":\"Nm (Gs): ينشط محلقة الأدينيلات في الوصل العصبي العضلي، مولداً cAMP لاستدامة الانقباض الكزازي الإرادي.\",\"en\":\"Nm (Gs): Activates adenylyl cyclase in neuromuscular junctions, generating cAMP to sustain voluntary tetanic muscle contraction.\"},\"feedback\":{\"tr\":\"Yanlış. Nikotinik reseptörler GPCR değildir; pentamerik iyonotropik kanallardır ve sodyum/kalsiyum girişiyle motor son plağı doğrudan depolarize eder.\",\"ar\":\"غير صحيح. مستقبلات النيكوتين قنوات أيونية وليست GPCR؛ تزيل استقطاب الصفيحة المحركة مباشرة بتدفق الصوديوم والكالسيوم.\",\"en\":\"Incorrect. Nicotinic receptors are ionotropic ligand-gated cation channels, not GPCRs; they depolarize the motor endplate directly.\"}}]},\"technicalTerms\":[{\"term\":\"GIRK Potasyum Kanalı\",\"arContext\":\"قنوات البوتاسيوم المقومة للداخل (GIRK) (GIRK Potassium Channel)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Kuralı hatırlayın: tek sayılı muskarinikler (M1, M3, M5) Gq'ya; çift sayılı olanlar (M2, M4) Gi'ye kenetlenir.\",\"ar\":\"تذكر القاعدة: تقترن الموسكارينية الفردية (M1, M3, M5) بـ Gq؛ بينما تقترن الزوجية (M2, M4) بـ Gi.\",\"en\":\"Remember the rule: odd-numbered muscarinics (M1, M3, M5) couple to Gq; even-numbered (M2, M4) couple to Gi.\"},{\"tier\":2,\"tr\":\"Nikotinik reseptörler (Nm, Nn) GPCR değildir; doğrudan ligand kapılı iyon kanallarıdır.\",\"ar\":\"المستقبلات النيكوتينية (Nm, Nn) ليست من نمط GPCR؛ بل هي قنوات أيونية مبوبة بالربيطة مباشرة.\",\"en\":\"Nicotinic receptors (Nm, Nn) are not GPCRs at all; they are pentameric ligand-gated ion channels.\"},{\"tier\":3,\"tr\":\"M2 reseptörleri kalpte Gi'ye kenetlenir, potasyum kanallarını açarak pacemaker'ı hiperpolarize eder ve kalp hızını yavaşlatır.\",\"ar\":\"تقترن مستقبلات M2 بـ Gi في النسيج العقدي القلبي، فاتحة قنوات البوتاسيوم لفرط استقطاب الناظمة وإبطاء القلب.\",\"en\":\"M2 (Gi): Decreases adenylyl cyclase activity and opens GIRK K+ channels in cardiac pacemaker, slowing heart rate.\"}],\"config\":{\"options\":[{\"id\":\"opt-l8-s7-1\",\"isCorrect\":true,\"text\":{\"tr\":\"M2 (Gi): Adenilat siklaz aktivitesini azaltır ve kardiyak pacemaker'da GIRK K+ kanallarını açarak kalp hızını yavaşlatır.\",\"ar\":\"M2 (Gi): يقلل نشاط محلقة الأدينيلات ويفتح قنوات البوتاسيوم GIRK في الناظمة القلبية، مبطئاً معدل ضربات القلب.\",\"en\":\"M2 (Gi): Decreases adenylyl cyclase activity and opens GIRK K+ channels in cardiac pacemaker, slowing heart rate.\"},\"feedback\":{\"tr\":\"Doğru. Muskarinik M2 reseptörleri Gi ile cAMP'yi düşürür ve G beta-gama ile içe doğrultucu GIRK K+ kanallarını açarak kalbi yavaşlatır.\",\"ar\":\"صحيح. تقترن مستقبلات M2 بـ Gi لخفض cAMP وفتح قنوات البوتاسيوم GIRK عبر بيتا-غاما مفرطة استقطاب العقد القلبية.\",\"en\":\"Correct. Muscarinic M2 receptors couple to Gi, inhibiting cAMP and directly opening GIRK K+ channels via G beta-gamma to slow heart rate.\"}},{\"id\":\"opt-l8-s7-2\",\"isCorrect\":false,\"text\":{\"tr\":\"M3 (Gi): Ekzokrin bezlerde fosfolipaz C'yi inhibe ederek tükürük ve gözyaşı salgılarını belirgin şekilde azaltır.\",\"ar\":\"M3 (Gi): يثبط فوسفوليباز C في الغدد خارجية الإفراز، مخفضاً الإفراز اللعابي والدمعي بشكل ملحوظ.\",\"en\":\"M3 (Gi): Inhibits phospholipase C in exocrine glands, dramatically reducing salivary and lacrimal secretions.\"},\"feedback\":{\"tr\":\"Yanlış. M3 Gi'ye değil Gq'ya kenetlenir ve PLC'yi aktive ederek hücre içi kalsiyumu artırır; ekzokrin salgıları güçlü şekilde uyarır.\",\"ar\":\"غير صحيح. يقترن M3 بـ Gq (وليس Gi) وينشط PLC لرفع الكالسيوم الداخلي، محفزاً الإفرازات الغدية بقوة.\",\"en\":\"Incorrect. M3 couples to Gq (not Gi) and activates PLC to increase intracellular calcium, powerfully stimulating secretions.\"}},{\"id\":\"opt-l8-s7-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Nm (Gs): Nöromusküler kavşakta adenilat siklazı aktive eder ve istemli tetanik kas kasılmasını sürdürmek için cAMP üretir.\",\"ar\":\"Nm (Gs): ينشط محلقة الأدينيلات في الوصل العصبي العضلي، مولداً cAMP لاستدامة الانقباض الكزازي الإرادي.\",\"en\":\"Nm (Gs): Activates adenylyl cyclase in neuromuscular junctions, generating cAMP to sustain voluntary tetanic muscle contraction.\"},\"feedback\":{\"tr\":\"Yanlış. Nikotinik reseptörler GPCR değildir; pentamerik iyonotropik kanallardır ve sodyum/kalsiyum girişiyle motor son plağı doğrudan depolarize eder.\",\"ar\":\"غير صحيح. مستقبلات النيكوتين قنوات أيونية وليست GPCR؛ تزيل استقطاب الصفيحة المحركة مباشرة بتدفق الصوديوم والكالسيوم.\",\"en\":\"Incorrect. Nicotinic receptors are ionotropic ligand-gated cation channels, not GPCRs; they depolarize the motor endplate directly.\"}}],\"prompt\":{\"tr\":\"Kanonik kolinerjik reseptör sınıflandırma tablosunu inceleyin. Hangi ifade bir kolinoseptör alt tipini, moleküler iletecini ve birincil fizyolojik yanıtını doğru eşleştirir?\",\"ar\":\"راجع جدول تصنيف المستقبلات الكولينية. أي عبارة تقرن بدقة بين نمط المستقبل الكوليني وموصله الجزيئي واستجابته الفسيولوجية الأساسية؟\",\"en\":\"Review the canonical cholinoceptor classification table. Which statement accurately pairs a cholinoceptor subtype with its molecular transducer and primary physiological response?\"},\"title\":{\"tr\":\"Biçimsel Açıklama: Kanonik Kolinoseptör Mimarisi\",\"ar\":\"شرح رسمي: البنية المعيارية للمستقبلات الكولينية\",\"en\":\"Formal Explanation: Canonical Cholinoceptor Architecture\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":23}]},{\"id\":\"pharm-mod4-les2-step8\",\"order\":8,\"stageIndex\":8,\"stage\":\"concept_check\",\"type\":\"concept_check\",\"title\":{\"tr\":\"Kavram Kontrolü: Tropikamid ile Göz Dibi Muayenesi\",\"ar\":\"تحقق مفاهيمي: فحص قاع العين بالتروبيكاميد\",\"en\":\"Concept Check: Tropicamide Fundus Examination\"},\"prompt\":{\"tr\":\"Bir göz hekimi fundus muayenesinden önce muskarinik antagonist tropikamid damlatır. Hastada aynı anda hangi iki farklı farmakolojik oküler değişiklik meydana gelir?\",\"ar\":\"يقطر طبيب العيون مضاد الموسكارين تروبيكاميد قبل فحص قاع العين. ما التغيران الدوائيان البصريان المتزامنان اللذان يحدثان لدى المريض؟\",\"en\":\"An ophthalmologist instills the muscarinic antagonist tropicamide before examining the ocular fundus. Which two distinct pharmacological ocular changes occur simultaneously in the patient?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Tropikamid göze damlatıldığında hangi iki etki aynı anda ortaya çıkar?\",\"ar\":\"ما التأثيران المتزامنان اللذان يظهران عند تقطير التروبيكاميد في العين؟\",\"en\":\"Which two effects occur simultaneously following ocular tropicamide instillation?\"},\"options\":[{\"id\":\"opt-l8-s8-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Midriyazis (sfinkter pupilla felciyle pupil dilatasyonu) ve siklopleji (silier kas felciyle yakın akomodasyon kaybı).\",\"ar\":\"توسع الحدقة (شلل العضلة العاصرة الحدقية) وشلل المطابقة (شلل العضلة الهدبية وفقدان المطابقة للرؤية القريبة).\",\"en\":\"Mydriasis (pupillary dilation via circular sphincter paralysis) and cycloplegia (loss of near accommodation via ciliary muscle paralysis).\"},\"feedback\":{\"tr\":\"Doğru. Tropikamid sfinkter pupilladaki M3'ü bloke ederek midriyazis, silier kastaki M3'ü bloke ederek siklopleji yapar.\",\"ar\":\"صحيح. يحصر التروبيكاميد مستقبلات M3 في العاصرة مسبباً توسع الحدقة، وفي العضلة الهدبية مسبباً شلل المطابقة.\",\"en\":\"Correct. Tropicamide blocks M3 receptors on both the circular sphincter (causing mydriasis) and ciliary muscle (causing cycloplegia).\"}},{\"id\":\"opt-l8-s8-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Miyozis (radyal kas aktivasyonuyla pupil daralması) ve uzak görme keskinliğinde kalıcı felç.\",\"ar\":\"تضيق الحدقة (تنشيط العضلة الشعاعية) وشلل دائم في حدة الرؤية البعيدة.\",\"en\":\"Miosis (pupillary constriction via radial muscle activation) and permanent paralysis of distant visual acuity.\"},\"feedback\":{\"tr\":\"Yanlış. Muskarinik antagonistler miyozis değil midriyazis yapar. Radyal dilatör kas alfa-1 adrenerjik kontrol altındadır.\",\"ar\":\"غير صحيح. تسبب مضادات الموسكارين توسع الحدقة لا تضيقها؛ وتخضع العضلة الشعاعية لسيطرة مستقبلات ألفا-1 الودية.\",\"en\":\"Incorrect. Muscarinic antagonists cause mydriasis, not miosis. The radial dilator muscle is controlled by alpha-1 adrenoceptors.\"}},{\"id\":\"opt-l8-s8-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Trabeküler ağdan aköz drenajın artmasıyla birlikte pupil dilatasyonu ve göz içi basıncında belirgin düşüş.\",\"ar\":\"توسع الحدقة مترافقاً بتصريف متزايد للخلط المائي عبر الشبكة التربيقية، خافضاً ضغط العين بشدة.\",\"en\":\"Pupillary dilation accompanied by enhanced trabecular meshwork aqueous drainage, dramatically reducing intraocular pressure.\"},\"feedback\":{\"tr\":\"Yanlış. Antimuskarinik midriyazis iridokorneal açıyı daraltarak aköz drenajını tıkar ve göz içi basıncını yükseltebilir.\",\"ar\":\"غير صحيح. يؤدي توسع الحدقة بمضادات الموسكارين لتضيق زاوية العين وإعاقة تصريف الخلط المائي، مما قد يرفع ضغط العين.\",\"en\":\"Incorrect. Antimuscarinic mydriasis crowds the iridocorneal angle, obstructing aqueous drainage and risking intraocular pressure spikes.\"}}]},\"technicalTerms\":[{\"term\":\"Siklopleji\",\"arContext\":\"شلل المطابقة البصرية (Cycloplegia)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Muskarinik M3 reseptörleri iki farklı oküler kası kasar: sfinkter pupilla ve silier kas.\",\"ar\":\"تقبض مستقبلات M3 الموسكارينية عضلتين عينيتين متميزتين: العضلة العاصرة للحدقة والعضلة الهدبية.\",\"en\":\"Muscarinic M3 receptors contract two distinct ocular muscles: the pupillary sphincter and the ciliary muscle.\"},{\"tier\":2,\"tr\":\"Sfinkterin felç olması gözbebeğinin daralmasını engeller; silier kasın felç olması merceği yassılaştırarak yakın görme uyumunu bozar.\",\"ar\":\"شلل العاصرة يمنع تضيق الحدقة؛ بينما شلل العضلة الهدبية يسطح العدسة ملغياً المطابقة للرؤية القريبة.\",\"en\":\"Paralyzing the sphincter prevents pupillary constriction; paralyzing the ciliary muscle flattens the lens, abolishing near accommodation.\"},{\"tier\":3,\"tr\":\"M3 blokajı sfinkter felciyle midriyazis (bebek genişlemesi), silier kas felciyle ise siklopleji (yakın görme uyumu kaybı) yapar.\",\"ar\":\"يحدث حصر M3 توسعاً للحدقة (شلل العاصرة) وشللاً للمطابقة (شلل العضلة الهدبية وفقدان التركيز القريب).\",\"en\":\"Blocking M3 produces mydriasis (pupillary dilation via sphincter paralysis) and cycloplegia (loss of near accommodation via ciliary paralysis).\"}],\"config\":{\"options\":[{\"id\":\"opt-l8-s8-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Midriyazis (sfinkter pupilla felciyle pupil dilatasyonu) ve siklopleji (silier kas felciyle yakın akomodasyon kaybı).\",\"ar\":\"توسع الحدقة (شلل العضلة العاصرة الحدقية) وشلل المطابقة (شلل العضلة الهدبية وفقدان المطابقة للرؤية القريبة).\",\"en\":\"Mydriasis (pupillary dilation via circular sphincter paralysis) and cycloplegia (loss of near accommodation via ciliary muscle paralysis).\"},\"feedback\":{\"tr\":\"Doğru. Tropikamid sfinkter pupilladaki M3'ü bloke ederek midriyazis, silier kastaki M3'ü bloke ederek siklopleji yapar.\",\"ar\":\"صحيح. يحصر التروبيكاميد مستقبلات M3 في العاصرة مسبباً توسع الحدقة، وفي العضلة الهدبية مسبباً شلل المطابقة.\",\"en\":\"Correct. Tropicamide blocks M3 receptors on both the circular sphincter (causing mydriasis) and ciliary muscle (causing cycloplegia).\"}},{\"id\":\"opt-l8-s8-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Miyozis (radyal kas aktivasyonuyla pupil daralması) ve uzak görme keskinliğinde kalıcı felç.\",\"ar\":\"تضيق الحدقة (تنشيط العضلة الشعاعية) وشلل دائم في حدة الرؤية البعيدة.\",\"en\":\"Miosis (pupillary constriction via radial muscle activation) and permanent paralysis of distant visual acuity.\"},\"feedback\":{\"tr\":\"Yanlış. Muskarinik antagonistler miyozis değil midriyazis yapar. Radyal dilatör kas alfa-1 adrenerjik kontrol altındadır.\",\"ar\":\"غير صحيح. تسبب مضادات الموسكارين توسع الحدقة لا تضيقها؛ وتخضع العضلة الشعاعية لسيطرة مستقبلات ألفا-1 الودية.\",\"en\":\"Incorrect. Muscarinic antagonists cause mydriasis, not miosis. The radial dilator muscle is controlled by alpha-1 adrenoceptors.\"}},{\"id\":\"opt-l8-s8-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Trabeküler ağdan aköz drenajın artmasıyla birlikte pupil dilatasyonu ve göz içi basıncında belirgin düşüş.\",\"ar\":\"توسع الحدقة مترافقاً بتصريف متزايد للخلط المائي عبر الشبكة التربيقية، خافضاً ضغط العين بشدة.\",\"en\":\"Pupillary dilation accompanied by enhanced trabecular meshwork aqueous drainage, dramatically reducing intraocular pressure.\"},\"feedback\":{\"tr\":\"Yanlış. Antimuskarinik midriyazis iridokorneal açıyı daraltarak aköz drenajını tıkar ve göz içi basıncını yükseltebilir.\",\"ar\":\"غير صحيح. يؤدي توسع الحدقة بمضادات الموسكارين لتضيق زاوية العين وإعاقة تصريف الخلط المائي، مما قد يرفع ضغط العين.\",\"en\":\"Incorrect. Antimuscarinic mydriasis crowds the iridocorneal angle, obstructing aqueous drainage and risking intraocular pressure spikes.\"}}],\"prompt\":{\"tr\":\"Bir göz hekimi fundus muayenesinden önce muskarinik antagonist tropikamid damlatır. Hastada aynı anda hangi iki farklı farmakolojik oküler değişiklik meydana gelir?\",\"ar\":\"يقطر طبيب العيون مضاد الموسكارين تروبيكاميد قبل فحص قاع العين. ما التغيران الدوائيان البصريان المتزامنان اللذان يحدثان لدى المريض؟\",\"en\":\"An ophthalmologist instills the muscarinic antagonist tropicamide before examining the ocular fundus. Which two distinct pharmacological ocular changes occur simultaneously in the patient?\"},\"title\":{\"tr\":\"Kavram Kontrolü: Tropikamid ile Göz Dibi Muayenesi\",\"ar\":\"تحقق مفاهيمي: فحص قاع العين بالتروبيكاميد\",\"en\":\"Concept Check: Tropicamide Fundus Examination\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":24}]},{\"id\":\"pharm-mod4-les2-step9\",\"order\":9,\"stageIndex\":9,\"stage\":\"application\",\"type\":\"clinical_vignette\",\"title\":{\"tr\":\"Klinik Vaka: Tensilon Testi ile Kriz Ayrımı\",\"ar\":\"حالة سريرية: تفريق الأزمة باختبار تينسيلون\",\"en\":\"Clinical Vignette: Tensilon Test Crisis Differentiation\"},\"prompt\":{\"tr\":\"Piridostigmin kullanan Miyastenia Gravis hastasında akut gevşek solunum güçsüzlüğü gelişir. Nörolog IV edrofonyum uygular (Tensilon testi). Tanısal yanıt nasıl yorumlanır?\",\"ar\":\"مريض وهن عضلي وخيم يعالج ببيريدوستيغمين أصيب بضعف تنفسي رخو حاد. حقن طبيب الأعصاب إدروفونيوم وريدياً (اختبار تينسيلون). كيف تفسر الاستجابة التشخيصية؟\",\"en\":\"A Myasthenia Gravis patient on pyridostigmine develops acute flaccid respiratory weakness. The neurologist administers IV edrophonium (Tensilon test). How is the diagnostic response interpreted?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Edrofonyum (Tensilon) testi ile miyastenik kriz ve kolinerjik kriz nasıl ayırt edilir?\",\"ar\":\"كيف يفرق اختبار الإدروفونيوم (تينسيلون) بين الأزمة الوهنية والأزمة الكولينية؟\",\"en\":\"How does the edrophonium (Tensilon) test distinguish between myasthenic crisis and cholinergic crisis?\"},\"options\":[{\"id\":\"opt-l8-s9-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Kas gücünde ani düzelme yetersiz tedaviyi (Miyastenik Kriz); fasikülasyonlarla artan güçsüzlük ise aşırı tedaviyi (Kolinerjik Kriz) gösterir.\",\"ar\":\"التحسن الفوري في قوة العضلات يشير لنقص العلاج (أزمة وهنية)؛ وتفاقم الضعف مع نفضان عضلي يشير لفرط العلاج (أزمة كولينية).\",\"en\":\"Immediate improvement in muscle strength indicates undertreatment (Myasthenic Crisis); worsening weakness with fasciculations indicates overtreatment (Cholinergic Crisis).\"},\"feedback\":{\"tr\":\"Doğru. Edrofonyum ultra kısa etkili bir AChE inhibitörüdür. Miyastenik krizde ACh artışı gücü toparlar; kolinerjik krizde ise depolarizan bloğu derinleştirip felci ağırlaştırır.\",\"ar\":\"صحيح. الإدروفونيوم مثبط فائق قصر الأمد للـ AChE. في الأزمة الوهنية يعيد الأسيتيل كولين القوة؛ وفي الأزمة الكولينية يعمق الشلل الاستقطابي.\",\"en\":\"Correct. Edrophonium is an ultra-short acting reversible AChE inhibitor. In myasthenic crisis, more ACh restores strength; in cholinergic crisis, more ACh deepens depolarizing block.\"}},{\"id\":\"opt-l8-s9-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Edrofonyum, çizgili kasta voltaj kapılı kalsiyum kanallarını doğrudan açarak her iki krizde de tam kas gücünü geri kazandırır.\",\"ar\":\"يعيد الإدروفونيوم كامل القوة العضلية في كلتا الأزمتين عن طريق فتح قنوات الكالسيوم في العضلات الهيكلية مباشرة.\",\"en\":\"Edrophonium restores full muscle power in both crises by directly opening voltage-gated calcium channels in skeletal muscle.\"},\"feedback\":{\"tr\":\"Yanlış. Kolinerjik krizde motor son plaklar zaten aşırı ACh ile depolarize ve inaktiftir; edrofonyum eklemek solunum durmasına yol açabilir.\",\"ar\":\"غير صحيح. في الأزمة الكولينية، تكون الصفائح مزالة الاستقطاب ومثبطة؛ وإضافة الإدروفونيوم تعمق الشلل وقد توقف التنفس.\",\"en\":\"Incorrect. In a cholinergic crisis, motor endplates are already depolarized and desensitized; adding edrophonium worsens the block and risks respiratory arrest.\"}},{\"id\":\"opt-l8-s9-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Düzelme edrofonyumun dolaşımdaki nikotinik otoantikorları nötralize ettiğini; başarısızlık ise geri dönüşsüz motor nöron ölümünü kanıtlar.\",\"ar\":\"يثبت التحسن أن الإدروفونيوم عادل الأجسام المضادة لمستقبلات النيكوتين، بينما يشير الفشل إلى موت عصبوني حركي غير عكوس.\",\"en\":\"Improvement proves edrophonium neutralized circulating nicotinic receptor autoantibodies, while failure indicates irreversible motor neuron death.\"},\"feedback\":{\"tr\":\"Yanlış. Edrofonyum antikorları bağlamaz veya nötralize etmez; yalnızca asetilkolinesterazı geçici olarak durdurarak ACh konsantrasyonunu artırır.\",\"ar\":\"غير صحيح. لا يعادل الإدروفونيوم الأجسام المضادة؛ بل يثبط الكولينستراز مؤقتاً لرفع تركيز الأسيتيل كولين لمنافسة الأضداد.\",\"en\":\"Incorrect. Edrophonium does not neutralize antibodies; it transiently inhibits acetylcholinesterase, elevating acetylcholine to compete with antibodies.\"}}]},\"technicalTerms\":[{\"term\":\"Tensilon Testi\",\"arContext\":\"اختبار تينسيلون (Tensilon Test)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Hem miyastenik kriz (yetersiz tedavi) hem kolinerjik kriz (aşırı tedavi) aynı gevşek kas güçsüzlüğüyle gelir.\",\"ar\":\"تتظاهر كل من الأزمة الوهنية (نقص العلاج) والأزمة الكولينية (فرط العلاج) بذات الضعف الرخو.\",\"en\":\"Both myasthenic crisis (undertreatment) and cholinergic crisis (overtreatment) present with identical flaccid weakness.\"},{\"tier\":2,\"tr\":\"Edrofonyum sinaptik asetilkolini 5-10 dakika geçici olarak yükseltir. Zaten depolarize ve duyarsızlaşmış bir plakaya daha fazla ACh eklenirse ne olur?\",\"ar\":\"يرفع الإدروفونيوم الأسيتيل كولين مؤقتاً لـ 5-10 دقائق. ماذا يحدث لصفيحة محركة مزالة الاستقطاب ومفرطة الإشباع إذا أضفت مزيداً من الأسيتيل كولين؟\",\"en\":\"Edrophonium transiently increases synaptic ACh for 5-10 minutes. What happens if you add more ACh to an already depolarized, desensitized motor endplate?\"},{\"tier\":3,\"tr\":\"Güçsüzlük ACh azlığından kaynaklanıyorsa kas gücü artar (Miyastenik Kriz); aşırı ACh'nin depolarizan bloğundan kaynaklanıyorsa güçsüzlük kötüleşir (Kolinerjik Kriz).\",\"ar\":\"إذا كان الضعف بسبب نقص الأسيتيل كولين تتحسن القوة (أزمة وهنية)؛ أما إذا كان بسبب فائض الأسيتيل كولين يتفاقم الشلل مع نفضان (أزمة كولينية).\",\"en\":\"If weakness was due to lack of ACh (myasthenic crisis), strength improves. If due to excess ACh causing depolarizing block (cholinergic crisis), paralysis worsens.\"}],\"config\":{\"options\":[{\"id\":\"opt-l8-s9-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Kas gücünde ani düzelme yetersiz tedaviyi (Miyastenik Kriz); fasikülasyonlarla artan güçsüzlük ise aşırı tedaviyi (Kolinerjik Kriz) gösterir.\",\"ar\":\"التحسن الفوري في قوة العضلات يشير لنقص العلاج (أزمة وهنية)؛ وتفاقم الضعف مع نفضان عضلي يشير لفرط العلاج (أزمة كولينية).\",\"en\":\"Immediate improvement in muscle strength indicates undertreatment (Myasthenic Crisis); worsening weakness with fasciculations indicates overtreatment (Cholinergic Crisis).\"},\"feedback\":{\"tr\":\"Doğru. Edrofonyum ultra kısa etkili bir AChE inhibitörüdür. Miyastenik krizde ACh artışı gücü toparlar; kolinerjik krizde ise depolarizan bloğu derinleştirip felci ağırlaştırır.\",\"ar\":\"صحيح. الإدروفونيوم مثبط فائق قصر الأمد للـ AChE. في الأزمة الوهنية يعيد الأسيتيل كولين القوة؛ وفي الأزمة الكولينية يعمق الشلل الاستقطابي.\",\"en\":\"Correct. Edrophonium is an ultra-short acting reversible AChE inhibitor. In myasthenic crisis, more ACh restores strength; in cholinergic crisis, more ACh deepens depolarizing block.\"}},{\"id\":\"opt-l8-s9-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Edrofonyum, çizgili kasta voltaj kapılı kalsiyum kanallarını doğrudan açarak her iki krizde de tam kas gücünü geri kazandırır.\",\"ar\":\"يعيد الإدروفونيوم كامل القوة العضلية في كلتا الأزمتين عن طريق فتح قنوات الكالسيوم في العضلات الهيكلية مباشرة.\",\"en\":\"Edrophonium restores full muscle power in both crises by directly opening voltage-gated calcium channels in skeletal muscle.\"},\"feedback\":{\"tr\":\"Yanlış. Kolinerjik krizde motor son plaklar zaten aşırı ACh ile depolarize ve inaktiftir; edrofonyum eklemek solunum durmasına yol açabilir.\",\"ar\":\"غير صحيح. في الأزمة الكولينية، تكون الصفائح مزالة الاستقطاب ومثبطة؛ وإضافة الإدروفونيوم تعمق الشلل وقد توقف التنفس.\",\"en\":\"Incorrect. In a cholinergic crisis, motor endplates are already depolarized and desensitized; adding edrophonium worsens the block and risks respiratory arrest.\"}},{\"id\":\"opt-l8-s9-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Düzelme edrofonyumun dolaşımdaki nikotinik otoantikorları nötralize ettiğini; başarısızlık ise geri dönüşsüz motor nöron ölümünü kanıtlar.\",\"ar\":\"يثبت التحسن أن الإدروفونيوم عادل الأجسام المضادة لمستقبلات النيكوتين، بينما يشير الفشل إلى موت عصبوني حركي غير عكوس.\",\"en\":\"Improvement proves edrophonium neutralized circulating nicotinic receptor autoantibodies, while failure indicates irreversible motor neuron death.\"},\"feedback\":{\"tr\":\"Yanlış. Edrofonyum antikorları bağlamaz veya nötralize etmez; yalnızca asetilkolinesterazı geçici olarak durdurarak ACh konsantrasyonunu artırır.\",\"ar\":\"غير صحيح. لا يعادل الإدروفونيوم الأجسام المضادة؛ بل يثبط الكولينستراز مؤقتاً لرفع تركيز الأسيتيل كولين لمنافسة الأضداد.\",\"en\":\"Incorrect. Edrophonium does not neutralize antibodies; it transiently inhibits acetylcholinesterase, elevating acetylcholine to compete with antibodies.\"}}],\"prompt\":{\"tr\":\"Piridostigmin kullanan Miyastenia Gravis hastasında akut gevşek solunum güçsüzlüğü gelişir. Nörolog IV edrofonyum uygular (Tensilon testi). Tanısal yanıt nasıl yorumlanır?\",\"ar\":\"مريض وهن عضلي وخيم يعالج ببيريدوستيغمين أصيب بضعف تنفسي رخو حاد. حقن طبيب الأعصاب إدروفونيوم وريدياً (اختبار تينسيلون). كيف تفسر الاستجابة التشخيصية؟\",\"en\":\"A Myasthenia Gravis patient on pyridostigmine develops acute flaccid respiratory weakness. The neurologist administers IV edrophonium (Tensilon test). How is the diagnostic response interpreted?\"},\"title\":{\"tr\":\"Klinik Vaka: Tensilon Testi ile Kriz Ayrımı\",\"ar\":\"حالة سريرية: تفريق الأزمة باختبار تينسيلون\",\"en\":\"Clinical Vignette: Tensilon Test Crisis Differentiation\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":25}]},{\"id\":\"pharm-mod4-les2-step10\",\"order\":10,\"stageIndex\":10,\"stage\":\"retrieval\",\"type\":\"retrieval\",\"title\":{\"tr\":\"Geri Çağırma: Kolinesteraz Reaktivatörü Panzehir\",\"ar\":\"استرجاع: الترياق المنشط للكولينستراز\",\"en\":\"Retrieval: Cholinesterase Reactivator Antidote\"},\"prompt\":{\"tr\":\"Hangi özgül farmakolojik panzehir organofosfatla fosforillenmiş asetilkolinesterazı yeniden aktifleştirebilir ve hangi kritik biyokimyasal reaksiyondan önce uygulanmalıdır?\",\"ar\":\"ما هو الترياق الدوائي النوعي القادر على إعادة تنشيط إنزيم كولينستراز الأسيتيل المفسفر بالفوسفات العضوي، وما التفاعل الكيميائي الحاسم الذي يجب أن يسبقه؟\",\"en\":\"Which specific pharmacological antidote can reactivate organophosphate-phosphorylated acetylcholinesterase, and what critical biochemical reaction must it precede?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Organofosfatla kilitlenmiş asetilkolinesterazı hangi ilaç reaktive eder ve hangi sınırlamaya tabidir?\",\"ar\":\"ما هو الدواء الذي يعيد تنشيط إنزيم كولينستراز المثبط بالفوسفات العضوي وما محدداته؟\",\"en\":\"Which drug reactivates organophosphate-inhibited acetylcholinesterase and what critical limitation applies?\"},\"options\":[{\"id\":\"opt-l8-s10-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Pralidoksim (2-PAM); nükleofilik oksim saldırısı serbest enzimi rejenere eder ancak kovalent 'yaşlanma' (aging) gerçekleşmeden önce verilmelidir.\",\"ar\":\"براليدوكسيم (2-PAM)؛ حيث يحرر الهجوم النكليوفيلي للأوكسيم الإنزيم، ولكن يجب إعطاؤه قبل حدوث 'تعمير' الإنزيم الكوفالنتي (aging).\",\"en\":\"Pralidoxime (2-PAM); nucleophilic oxime attack regenerates free enzyme, but it must be given before covalent enzyme 'aging' occurs.\"},\"feedback\":{\"tr\":\"Doğru. Pralidoksim oksim grubuyla fosforil-serin bağını koparır. Ancak enzim dealkilasyona ('yaşlanma') uğrarsa kimyasal reaktivasyon imkansızlaşır.\",\"ar\":\"صحيح. يكسر البراليدوكسيم الرابطة بهجوم نكليوفيلي. ولكن إذا حدث التعمير (فقدان ألكيل) يصبح الإنزيم عصياً على أي تنشيط كيميائي.\",\"en\":\"Correct. Pralidoxime uses an oxime nucleophile to regenerate the active serine. Once covalent 'aging' (dealkylation) occurs, reactivation is impossible.\"}},{\"id\":\"opt-l8-s10-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Atropin; tersiyer amini kovalent fosfat-ester bağını keserek katalitik triadın kendiliğinden dekarboksilasyonunu engeller.\",\"ar\":\"الأتروبين؛ حيث يقطع أمينه الثالثي الرابطة الفوسفاتية الكوفالنتية، مانعاً نزع الكربوكسيل التلقائي من الثالوث التحفيزي.\",\"en\":\"Atropine; its tertiary amine cleaves the covalent phosphate-ester bond, preventing spontaneous decarboxylation of the catalytic triad.\"},\"feedback\":{\"tr\":\"Yanlış. Atropin bir muskarinik reseptör antagonistidir; asetilkolinesterazı yeniden aktifleştiremez veya organofosfatı yerinden sökemez.\",\"ar\":\"غير صحيح. الأتروبين مضاد للمستقبلات الموسكارينية؛ وليس له أي خواص لإعادة تنشيط الإنزيم أو فك ارتباط الفوسفات العضوي.\",\"en\":\"Incorrect. Atropine is a muscarinic receptor antagonist; it has zero enzymatic reactivating properties and cannot displace organophosphates from AChE.\"}},{\"id\":\"opt-l8-s10-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Fizostigmin; geri dönüşümlü bir karbamat inhibitörü olarak aktif bölgeden organofosfatları kovar ve dakikalar içinde hidroliz olur.\",\"ar\":\"فيزوستيغمين؛ كونه مثبط كربامات عكوس، فإنه يزيح الفوسفات العضوي من الموقع النشط ويتحلمه خلال دقائق.\",\"en\":\"Physostigmine; as a reversible carbamate inhibitor, it displaces organophosphates from the active site and hydrolyzes within minutes.\"},\"feedback\":{\"tr\":\"Yanlış. Aktif organofosfat zehirlenmesinde fizostigmin verilmesi kolinesteraz inhibisyonunu daha da artırarak toksisiteyi ve ölümü hızlandırır.\",\"ar\":\"غير صحيح. يؤدي إعطاء فيزوستيغمين أثناء التسمم بالفوسفات العضوي إلى مضاعفة تثبيط الكولينستراز وتسريع الوفاة.\",\"en\":\"Incorrect. Giving an AChE inhibitor like physostigmine during organophosphate toxicity compounds enzyme inhibition, worsening lethal cholinergic crisis.\"}}]},\"technicalTerms\":[{\"term\":\"Kolinesteraz Reaktivatörü\",\"arContext\":\"منشط الكولينستراز (Cholinesterase Reactivator)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Semptomları maskeleyen bir reseptör blokeri ile enzimi kimyasal olarak kurtaran bir reaktivatörü ayırt edin.\",\"ar\":\"ميز بين حاصر المستقبلات الذي يخفي الأعراض وبين المنشط الذي ينقذ الإنزيم كيميائياً.\",\"en\":\"Distinguish between a receptor antagonist that masks symptoms versus a biochemical reactivator that restores the enzyme.\"},{\"tier\":2,\"tr\":\"Bu panzehir, organofosfatın fosfor atomuna nükleofilik saldırı yapabilen bir oksim (=N-OH) grubuna sahiptir.\",\"ar\":\"يمتلك هذا الترياق زمرة أوكسيم (=N-OH) قادرة على شن هجوم نكليوفيلي على ذرة الفوسفور.\",\"en\":\"This antidote possesses an oxime group capable of launching a nucleophilic attack on the organophosphorus atom.\"},{\"tier\":3,\"tr\":\"Pralidoksim (2-PAM) serbest enzimi rejenere etmek için nükleofilik oksim saldırısı yapar; ancak geri dönüşsüz 'yaşlanma' (aging) öncesinde verilmelidir.\",\"ar\":\"براليدوكسيم (2-PAM)؛ حيث يحرر الهجوم النكليوفيلي الإنزيم، لكن يجب إعطاؤه قبل حدوث 'تعمير' الإنزيم الكوفالنتي غير العكوس (aging).\",\"en\":\"Pralidoxime (2-PAM) acts as a nucleophile to displace the organophosphate from catalytic serine, but must be given before irreversible dealkylation ('aging').\"}],\"config\":{\"options\":[{\"id\":\"opt-l8-s10-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Pralidoksim (2-PAM); nükleofilik oksim saldırısı serbest enzimi rejenere eder ancak kovalent 'yaşlanma' (aging) gerçekleşmeden önce verilmelidir.\",\"ar\":\"براليدوكسيم (2-PAM)؛ حيث يحرر الهجوم النكليوفيلي للأوكسيم الإنزيم، ولكن يجب إعطاؤه قبل حدوث 'تعمير' الإنزيم الكوفالنتي (aging).\",\"en\":\"Pralidoxime (2-PAM); nucleophilic oxime attack regenerates free enzyme, but it must be given before covalent enzyme 'aging' occurs.\"},\"feedback\":{\"tr\":\"Doğru. Pralidoksim oksim grubuyla fosforil-serin bağını koparır. Ancak enzim dealkilasyona ('yaşlanma') uğrarsa kimyasal reaktivasyon imkansızlaşır.\",\"ar\":\"صحيح. يكسر البراليدوكسيم الرابطة بهجوم نكليوفيلي. ولكن إذا حدث التعمير (فقدان ألكيل) يصبح الإنزيم عصياً على أي تنشيط كيميائي.\",\"en\":\"Correct. Pralidoxime uses an oxime nucleophile to regenerate the active serine. Once covalent 'aging' (dealkylation) occurs, reactivation is impossible.\"}},{\"id\":\"opt-l8-s10-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Atropin; tersiyer amini kovalent fosfat-ester bağını keserek katalitik triadın kendiliğinden dekarboksilasyonunu engeller.\",\"ar\":\"الأتروبين؛ حيث يقطع أمينه الثالثي الرابطة الفوسفاتية الكوفالنتية، مانعاً نزع الكربوكسيل التلقائي من الثالوث التحفيزي.\",\"en\":\"Atropine; its tertiary amine cleaves the covalent phosphate-ester bond, preventing spontaneous decarboxylation of the catalytic triad.\"},\"feedback\":{\"tr\":\"Yanlış. Atropin bir muskarinik reseptör antagonistidir; asetilkolinesterazı yeniden aktifleştiremez veya organofosfatı yerinden sökemez.\",\"ar\":\"غير صحيح. الأتروبين مضاد للمستقبلات الموسكارينية؛ وليس له أي خواص لإعادة تنشيط الإنزيم أو فك ارتباط الفوسفات العضوي.\",\"en\":\"Incorrect. Atropine is a muscarinic receptor antagonist; it has zero enzymatic reactivating properties and cannot displace organophosphates from AChE.\"}},{\"id\":\"opt-l8-s10-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Fizostigmin; geri dönüşümlü bir karbamat inhibitörü olarak aktif bölgeden organofosfatları kovar ve dakikalar içinde hidroliz olur.\",\"ar\":\"فيزوستيغمين؛ كونه مثبط كربامات عكوس، فإنه يزيح الفوسفات العضوي من الموقع النشط ويتحلمه خلال دقائق.\",\"en\":\"Physostigmine; as a reversible carbamate inhibitor, it displaces organophosphates from the active site and hydrolyzes within minutes.\"},\"feedback\":{\"tr\":\"Yanlış. Aktif organofosfat zehirlenmesinde fizostigmin verilmesi kolinesteraz inhibisyonunu daha da artırarak toksisiteyi ve ölümü hızlandırır.\",\"ar\":\"غير صحيح. يؤدي إعطاء فيزوستيغمين أثناء التسمم بالفوسفات العضوي إلى مضاعفة تثبيط الكولينستراز وتسريع الوفاة.\",\"en\":\"Incorrect. Giving an AChE inhibitor like physostigmine during organophosphate toxicity compounds enzyme inhibition, worsening lethal cholinergic crisis.\"}}],\"prompt\":{\"tr\":\"Hangi özgül farmakolojik panzehir organofosfatla fosforillenmiş asetilkolinesterazı yeniden aktifleştirebilir ve hangi kritik biyokimyasal reaksiyondan önce uygulanmalıdır?\",\"ar\":\"ما هو الترياق الدوائي النوعي القادر على إعادة تنشيط إنزيم كولينستراز الأسيتيل المفسفر بالفوسفات العضوي، وما التفاعل الكيميائي الحاسم الذي يجب أن يسبقه؟\",\"en\":\"Which specific pharmacological antidote can reactivate organophosphate-phosphorylated acetylcholinesterase, and what critical biochemical reaction must it precede?\"},\"title\":{\"tr\":\"Geri Çağırma: Kolinesteraz Reaktivatörü Panzehir\",\"ar\":\"استرجاع: الترياق المنشط للكولينستراز\",\"en\":\"Retrieval: Cholinesterase Reactivator Antidote\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":26}]},{\"id\":\"pharm-mod4-les2-step11\",\"order\":11,\"stageIndex\":11,\"stage\":\"connection\",\"type\":\"connection\",\"title\":{\"tr\":\"Bütünsel Bağlantı: Botulinum ve Tetanoz Nörotoksinleri\",\"ar\":\"ترابط شمولي: ذيفانا البوتولينوم والكزاز\",\"en\":\"Holistic Connection: Botulinum vs Tetanus Neurotoxins\"},\"prompt\":{\"tr\":\"Hem Botulinum hem Tetanoz nörotoksinleri SNARE proteinlerini kesen çinko endopeptidazlardır. Neden Botulinum gevşek felç yaparken Tetanoz şiddetli spastik kasılmalara yol açar?\",\"ar\":\"كلا ذيفاني البوتولينوم والكزاز من إندوببتيدازات الزنك التي تقطع بروتينات SNARE. لماذا يحدث البوتولينوم شللاً رخواً، بينما يثير الكزاز تشنجات كزازية عاتية؟\",\"en\":\"Both Botulinum and Tetanus neurotoxins are zinc-endopeptidases that cleave SNARE proteins. Why does Botulinum produce flaccid paralysis, whereas Tetanus provokes violent spastic convulsions?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Botulinum ve Tetanoz toksinleri aynı enzimatik etkiye sahipken neden zıt felç tabloları oluşturur?\",\"ar\":\"لماذا يولد ذيفانا البوتولينوم والكزاز شللين متناقضين رغم امتلاكهما الفعالية الإنزيمية ذاتها؟\",\"en\":\"Why do Botulinum and Tetanus toxins produce opposing paralytic states despite sharing enzymatic SNARE cleavage?\"},\"options\":[{\"id\":\"opt-l8-s11-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Botulinum periferik kolinerjik nöromusküler kavşakta lokal etki gösterir (ACh'yi engeller); Tetanoz ise retrograd taşınarak spinal inhibitör internöronlara ulaşır (GABA/glisini engeller).\",\"ar\":\"يعمل البوتولينوم موضعياً في الوصل العصبي العضلي الكوليني (حاجباً الأسيتيل كولين)؛ بينما ينتقل الكزاز رجوعياً لعصبونات النخاع التثبيطية (حاجباً الغابا والغليسين).\",\"en\":\"Botulinum acts locally at peripheral cholinergic neuromuscular junctions (blocking ACh release); Tetanus undergoes retrograde axonal transport to spinal inhibitory interneurons (blocking GABA/glycine release).\"},\"feedback\":{\"tr\":\"Doğru. Anatomik hedef tabloyu belirler: Botulinum kavşakta ACh'yi keserek gevşek felç yapar; Tetanoz ise spinal Renshaw hücrelerinde inhibitör GABA/glisini keserek spastik felç yapar.\",\"ar\":\"صحيح. الموقع التشريحي يحدد المرضية: يحجب البوتولينوم الأسيتيل كولين محيطياً (شلل رخو)، بينما يهاجر الكزاز للنخاع قاطعاً تثبيط الغابا والغليسين (تشنج كزازي).\",\"en\":\"Correct. Site of action dictates pathology: Botulinum blocks peripheral ACh release (flaccid). Tetanus undergoes retrograde transport to silence spinal inhibitory interneurons (spastic).\"}},{\"id\":\"opt-l8-s11-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Botulinum asetilkolin ekzositozunu bloke ederken, Tetanoz nikotinik Nm reseptörlerinde doğrudan süper-agonist gibi davranarak sürekli kasılmaya zorlar.\",\"ar\":\"يحجب البوتولينوم إخراج الأسيتيل كولين، بينما يعمل الكزاز كمنبه فائق مباشر لمستقبلات Nm، فارضاً انقباضاً مستمراً.\",\"en\":\"Botulinum blocks acetylcholine exocytosis, while Tetanus acts as a direct super-agonist on nicotinic Nm receptors, forcing continuous contraction.\"},\"feedback\":{\"tr\":\"Yanlış. Tetanoz toksininin nikotinik reseptörlerde agonist etkisi yoktur; spastisite spinal internöronların disinhibisyonundan kaynaklanır.\",\"ar\":\"غير صحيح. ليس لذيفان الكزاز فعالية تنبيهية على مستقبلات النيكوتين؛ تنجم التشنجات عن فقدان التثبيط المركزي في النخاع.\",\"en\":\"Incorrect. Tetanus toxin has no agonist activity at nicotinic receptors; spasticity arises from disinhibition of spinal motor neurons.\"}},{\"id\":\"opt-l8-s11-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Her iki toksin de sadece nöromusküler kavşakta kalır; Botulinum SNAP-25'i keserken Tetanoz kas kasılma miyozin zincirlerini keser.\",\"ar\":\"يبقى كلا الذيفانين حصرياً في الوصل العصبي العضلي؛ يقطع البوتولينوم SNAP-25، بينما يقطع الكزاز سلاسل الميوزين الانقباضية.\",\"en\":\"Both toxins remain strictly at the neuromuscular junction; Botulinum cleaves SNAP-25, whereas Tetanus cleaves muscle contractile myosin chains.\"},\"feedback\":{\"tr\":\"Yanlış. Tetanoz toksini miyozini parçalamaz; karakteristik spastisitesi motor nöron boyu retrograd aksonal taşınarak merkezi sinir sistemine ulaşmasını gerektirir.\",\"ar\":\"غير صحيح. لا يخرب الكزاز الميوزين؛ بل تتطلب تشنجاته المميزة انتقالاً رجوعياً عبر المحوار للوصول للجهاز العصبي المركزي.\",\"en\":\"Incorrect. Tetanus toxin does not degrade myosin; its spasticity requires retrograde axonal transport to spinal inhibitory interneurons.\"}}]},\"technicalTerms\":[{\"term\":\"Retrograd Aksonal Taşınma\",\"arContext\":\"النقل المحواري الرجوعي (Retrograde Axonal Transport)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Her iki toksin de aynı moleküler mekanizmayı (SNARE kesimi) kullanır, ancak etki gösterdikleri anatomik bölgeler tamamen farklıdır.\",\"ar\":\"يستخدم كلا الذيفانين الآلية الجزيئية ذاتها (شطر SNARE)، ولكن مواقعهما التشريحية للعمل مختلفة تماماً.\",\"en\":\"Both toxins share the same molecular mechanism (SNARE cleavage), but their anatomical sites of action are completely different.\"},{\"tier\":2,\"tr\":\"Toksinler motor sinir ucuna girdikten sonra nereye gider? Spinal korddaki inhibitör internöronlara retrograd taşınmayı düşünün.\",\"ar\":\"أين ينتقل كل ذيفان بعد دخول النهاية المحركة؟ فكر في النقل المحواري الرجوعي إلى العصبونات التثبيطية في النخاع الشوكي.\",\"en\":\"Where does each toxin travel after entering the nerve terminal? Consider retrograde axonal transport to spinal inhibitory interneurons.\"},{\"tier\":3,\"tr\":\"Botulinum nöromusküler kavşakta lokal kalarak ACh'yi engeller (gevşek felç); Tetanoz ise spinal korddaki Renshaw hücrelerine taşınarak GABA ve glisin salınımını engeller (spastik felç).\",\"ar\":\"يعمل البوتولينوم موضعياً في الوصل العصبي العضلي مانعاً الأسيتيل كولين (شلل رخو)؛ بينما يهاجر الكزاز رجوعياً للنخاع مانعاً تحرر الغابا والغليسين (تشنج كزازي).\",\"en\":\"Botulinum acts locally at peripheral neuromuscular junctions to block ACh (flaccid). Tetanus migrates retrogradely to spinal inhibitory interneurons to block GABA/glycine (spastic).\"}],\"config\":{\"options\":[{\"id\":\"opt-l8-s11-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Botulinum periferik kolinerjik nöromusküler kavşakta lokal etki gösterir (ACh'yi engeller); Tetanoz ise retrograd taşınarak spinal inhibitör internöronlara ulaşır (GABA/glisini engeller).\",\"ar\":\"يعمل البوتولينوم موضعياً في الوصل العصبي العضلي الكوليني (حاجباً الأسيتيل كولين)؛ بينما ينتقل الكزاز رجوعياً لعصبونات النخاع التثبيطية (حاجباً الغابا والغليسين).\",\"en\":\"Botulinum acts locally at peripheral cholinergic neuromuscular junctions (blocking ACh release); Tetanus undergoes retrograde axonal transport to spinal inhibitory interneurons (blocking GABA/glycine release).\"},\"feedback\":{\"tr\":\"Doğru. Anatomik hedef tabloyu belirler: Botulinum kavşakta ACh'yi keserek gevşek felç yapar; Tetanoz ise spinal Renshaw hücrelerinde inhibitör GABA/glisini keserek spastik felç yapar.\",\"ar\":\"صحيح. الموقع التشريحي يحدد المرضية: يحجب البوتولينوم الأسيتيل كولين محيطياً (شلل رخو)، بينما يهاجر الكزاز للنخاع قاطعاً تثبيط الغابا والغليسين (تشنج كزازي).\",\"en\":\"Correct. Site of action dictates pathology: Botulinum blocks peripheral ACh release (flaccid). Tetanus undergoes retrograde transport to silence spinal inhibitory interneurons (spastic).\"}},{\"id\":\"opt-l8-s11-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Botulinum asetilkolin ekzositozunu bloke ederken, Tetanoz nikotinik Nm reseptörlerinde doğrudan süper-agonist gibi davranarak sürekli kasılmaya zorlar.\",\"ar\":\"يحجب البوتولينوم إخراج الأسيتيل كولين، بينما يعمل الكزاز كمنبه فائق مباشر لمستقبلات Nm، فارضاً انقباضاً مستمراً.\",\"en\":\"Botulinum blocks acetylcholine exocytosis, while Tetanus acts as a direct super-agonist on nicotinic Nm receptors, forcing continuous contraction.\"},\"feedback\":{\"tr\":\"Yanlış. Tetanoz toksininin nikotinik reseptörlerde agonist etkisi yoktur; spastisite spinal internöronların disinhibisyonundan kaynaklanır.\",\"ar\":\"غير صحيح. ليس لذيفان الكزاز فعالية تنبيهية على مستقبلات النيكوتين؛ تنجم التشنجات عن فقدان التثبيط المركزي في النخاع.\",\"en\":\"Incorrect. Tetanus toxin has no agonist activity at nicotinic receptors; spasticity arises from disinhibition of spinal motor neurons.\"}},{\"id\":\"opt-l8-s11-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Her iki toksin de sadece nöromusküler kavşakta kalır; Botulinum SNAP-25'i keserken Tetanoz kas kasılma miyozin zincirlerini keser.\",\"ar\":\"يبقى كلا الذيفانين حصرياً في الوصل العصبي العضلي؛ يقطع البوتولينوم SNAP-25، بينما يقطع الكزاز سلاسل الميوزين الانقباضية.\",\"en\":\"Both toxins remain strictly at the neuromuscular junction; Botulinum cleaves SNAP-25, whereas Tetanus cleaves muscle contractile myosin chains.\"},\"feedback\":{\"tr\":\"Yanlış. Tetanoz toksini miyozini parçalamaz; karakteristik spastisitesi motor nöron boyu retrograd aksonal taşınarak merkezi sinir sistemine ulaşmasını gerektirir.\",\"ar\":\"غير صحيح. لا يخرب الكزاز الميوزين؛ بل تتطلب تشنجاته المميزة انتقالاً رجوعياً عبر المحوار للوصول للجهاز العصبي المركزي.\",\"en\":\"Incorrect. Tetanus toxin does not degrade myosin; its spasticity requires retrograde axonal transport to spinal inhibitory interneurons.\"}}],\"prompt\":{\"tr\":\"Hem Botulinum hem Tetanoz nörotoksinleri SNARE proteinlerini kesen çinko endopeptidazlardır. Neden Botulinum gevşek felç yaparken Tetanoz şiddetli spastik kasılmalara yol açar?\",\"ar\":\"كلا ذيفاني البوتولينوم والكزاز من إندوببتيدازات الزنك التي تقطع بروتينات SNARE. لماذا يحدث البوتولينوم شللاً رخواً، بينما يثير الكزاز تشنجات كزازية عاتية؟\",\"en\":\"Both Botulinum and Tetanus neurotoxins are zinc-endopeptidases that cleave SNARE proteins. Why does Botulinum produce flaccid paralysis, whereas Tetanus provokes violent spastic convulsions?\"},\"title\":{\"tr\":\"Bütünsel Bağlantı: Botulinum ve Tetanoz Nörotoksinleri\",\"ar\":\"ترابط شمولي: ذيفانا البوتولينوم والكزاز\",\"en\":\"Holistic Connection: Botulinum vs Tetanus Neurotoxins\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":27}]},{\"id\":\"pharm-mod4-les2-step12\",\"order\":12,\"stageIndex\":12,\"stage\":\"mastery_check\",\"type\":\"mastery_check\",\"title\":{\"tr\":\"Ustalık Sınavı: Antikolinerjik Toksidrom ve Fizostigmin Kurtarması\",\"ar\":\"اختبار الإتقان: المتلازمة المضادة للكولين والإنقاذ بفيزوستيغمين\",\"en\":\"Mastery Check: Anticholinergic Toxidrome & Physostigmine Rescue\"},\"prompt\":{\"tr\":\"Bir hasta hipertermi (40°C), kuru kızarık cilt, aşırı ağız kuruluğu, fiks dilate pupiller, deliryum ve idrar retansiyonuyla geliyor. Toksidromu, mekanizmayı ve kan-beyin bariyerini geçen uygun panzehiri belirleyin.\",\"ar\":\"وصل مريض بارتفاع حرارة (40°C)، جلد أحمر جاف، جفاف فم شديد، حدقات متسعة ثابتة، هذيان واحتباس بول. حدد المتلازمة والآلية والترياق المناسب العابر للحاجز الدماغي.\",\"en\":\"A patient presents with hyperthermia (40°C), flushed anhidrotic skin, extreme xerostomia, fixed dilated pupils, delirium, and urinary retention. Identify the toxidrome, mechanism, and the pharmacologically appropriate blood-brain barrier-penetrating antidote.\"},\"conceptCheck\":{\"question\":{\"tr\":\"Tablodaki zehirlenmenin toksidromu, reseptör mekanizması ve santral etkili panzehiri hangisidir?\",\"ar\":\"ما هي المتلازمة والآلية والترياق المركزي المناسب للحالة المذكورة؟\",\"en\":\"What is the toxidrome, receptor mechanism, and central-acting antidote for this poisoning presentation?\"},\"options\":[{\"id\":\"opt-l8-s12-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Muskarinik blokaj kaynaklı Antikolinerjik toksidrom; santral deliryumu düzeltmek için kan-beyin bariyerini geçen tersiyer amin Fizostigmin ile tedavi edilir.\",\"ar\":\"متلازمة مضادة للكولين عبر حصر المستقبلات الموسكارينية؛ تعالج بـ فيزوستيغمين (أمين ثالثي يعبر الحاجز الدماغي لعكس الهذيان المركزي).\",\"en\":\"Anticholinergic toxidrome via muscarinic receptor blockade; treat with Physostigmine (a tertiary amine that crosses the blood-brain barrier to reverse central delirium).\"},\"feedback\":{\"tr\":\"Doğru! Klasik antikolinerjik toksidrom. Cildin tamamen kuru olması (anhidroz) onu terli sempatomimetik toksisiteden ayırır. Fizostigmin tersiyer amin yapısıyla KBB'yi geçer.\",\"ar\":\"صحيح! المتلازمة الكلاسيكية لمضادات الموسكارين. يميز جفاف الجلد (اللاحرق) هذه الحالة عن التسمم الودي (التعرق الغزير). ويعبر فيزوستيغمين الحاجز الدماغي كونه أميناً ثالثياً.\",\"en\":\"Correct! Classical anticholinergic toxidrome. Anhidrosis (dry skin) differentiates it from sympathomimetic toxicity (sweaty). Physostigmine is a tertiary amine crossing the BBB.\"}},{\"id\":\"opt-l8-s12-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Alfa-1/beta-1 hiperstimülasyonu kaynaklı Sempatomimetik toksidrom; intravenöz yüksek doz beta-bloker Esmolol ile tedavi edilir.\",\"ar\":\"متلازمة شبيهة بالودي عبر فرط تنبيه مستقبلات ألفا-1/بيتا-1؛ تعالج بجرعة عالية من حاصر بيتا إسمولول وريدياً.\",\"en\":\"Sympathomimetic toxidrome via alpha-1/beta-1 adrenoceptor hyperstimulation; treat with intravenous high-dose beta-blocker Esmolol.\"},\"feedback\":{\"tr\":\"Yanlış. Sempatomimetik toksisitede (kokain/amfetamin) taşikardi ve hipertermiye rağmen şiddetli terleme (diaforez) görülür. Antikolinerjikte ise cilt tamamen kurudur.\",\"ar\":\"غير صحيح. تترافق المتلازمة الودية (كوكايين/أمفيتامين) بتعرق غزير رغم الحرارة المرتفعة؛ بينما يكون الجلد جافاً تماماً في التسمم بمضادات الكولين.\",\"en\":\"Incorrect. Sympathomimetic toxicity presents with profuse diaphoresis (sweating). Anticholinergic toxicity produces dry (anhidrotic) skin.\"}},{\"id\":\"opt-l8-s12-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Antikolinerjik toksidrom; bilinci kurtarmak amacıyla merkezi sinir sistemine selektif geçen kuaterner amin Neostigmin ile tedavi edilir.\",\"ar\":\"متلازمة مضادة للكولين؛ تعالج بـ نيوستيغمين (أمين رابعي ينفذ انتقائياً للجهاز العصبي المركزي لإنقاذ الوعي).\",\"en\":\"Anticholinergic toxidrome; treat with Neostigmine (a quaternary amine that selectively penetrates the central nervous system to rescue consciousness).\"},\"feedback\":{\"tr\":\"Yanlış. Neostigmin kalıcı yüklü kuaterner amonyum taşır ve kan-beyin bariyerini ASLA GEÇEMEZ; santral deliryumu düzeltemez. Yalnızca tersiyer amin Fizostigmin beyne geçer.\",\"ar\":\"غير صحيح. يحمل النيوستيغمين أميناً رابعياً مشحوناً دائماً ولا يعبر إطلاقاً الحاجز الدماغي؛ فلا يعكس الهذيان المركزي. وحده فيزوستيغمين يعبر للدماغ.\",\"en\":\"Incorrect. Neostigmine possesses a permanently charged quaternary nitrogen that CANNOT cross the blood-brain barrier; only tertiary amines like physostigmine enter the CNS.\"}}]},\"technicalTerms\":[{\"term\":\"Antikolinerjik Toksidrom\",\"arContext\":\"متلازمة مضادات الكولين السمومية (Anticholinergic Toxidrome)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Klinik anımsatıcıyı hatırlayın: 'Pancar gibi kırmızı, kemik gibi kuru, yarasa gibi kör, tavşan gibi sıcak, şapkacı gibi deli.' Cilt nemine dikkat edin!\",\"ar\":\"تذكر العبارة السريرية الشهيرة: 'أحمر كالشمندر، جاف كالعظم، أعمى كالوطواط، ساخن كالأرنب، مجنون كصانع القبعات'. انتبه لرطوبة الجلد!\",\"en\":\"Mnemonic: 'Red as a beet, dry as a bone, blind as a bat, hot as a hare, mad as a hatter.' Pay close attention to skin moisture and central delirium.\"},{\"tier\":2,\"tr\":\"Muskarinik blokaj terlemeyi durdurur (anhidroz) ve santral deliryum yapar. Panzehirin santral semptomları düzeltmesi için kan-beyin bariyerini geçmesi şarttır.\",\"ar\":\"يوقف الحصر الموسكاريني التعرق (جفاف تام) ويحدث هذياناً مركزياً. يجب أن يعبر الترياق الحاجز الدماغي لإنقاذ الوعي.\",\"en\":\"Muscarinic blockade halts eccrine sweating (anhidrosis) and blocks central M1 receptors (delirium). The antidote must cross the blood-brain barrier.\"},{\"tier\":3,\"tr\":\"Bu bir antikolinerjik toksidromdur; yük taşımayan tersiyer amin yapısıyla kan-beyin bariyerini geçebilen Fizostigmin ile tedavi edilir.\",\"ar\":\"هذه متلازمة مضادة للكولين؛ تعالج بـ فيزوستيغمين كونه أميناً ثالثياً غير مشحون قادراً على عبور الحاجز الدماغي لعكس الهذيان.\",\"en\":\"Anticholinergic toxidrome; treat with Physostigmine, an uncharged tertiary amine that crosses the blood-brain barrier to reverse central delirium.\"}],\"config\":{\"options\":[{\"id\":\"opt-l8-s12-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Muskarinik blokaj kaynaklı Antikolinerjik toksidrom; santral deliryumu düzeltmek için kan-beyin bariyerini geçen tersiyer amin Fizostigmin ile tedavi edilir.\",\"ar\":\"متلازمة مضادة للكولين عبر حصر المستقبلات الموسكارينية؛ تعالج بـ فيزوستيغمين (أمين ثالثي يعبر الحاجز الدماغي لعكس الهذيان المركزي).\",\"en\":\"Anticholinergic toxidrome via muscarinic receptor blockade; treat with Physostigmine (a tertiary amine that crosses the blood-brain barrier to reverse central delirium).\"},\"feedback\":{\"tr\":\"Doğru! Klasik antikolinerjik toksidrom. Cildin tamamen kuru olması (anhidroz) onu terli sempatomimetik toksisiteden ayırır. Fizostigmin tersiyer amin yapısıyla KBB'yi geçer.\",\"ar\":\"صحيح! المتلازمة الكلاسيكية لمضادات الموسكارين. يميز جفاف الجلد (اللاحرق) هذه الحالة عن التسمم الودي (التعرق الغزير). ويعبر فيزوستيغمين الحاجز الدماغي كونه أميناً ثالثياً.\",\"en\":\"Correct! Classical anticholinergic toxidrome. Anhidrosis (dry skin) differentiates it from sympathomimetic toxicity (sweaty). Physostigmine is a tertiary amine crossing the BBB.\"}},{\"id\":\"opt-l8-s12-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Alfa-1/beta-1 hiperstimülasyonu kaynaklı Sempatomimetik toksidrom; intravenöz yüksek doz beta-bloker Esmolol ile tedavi edilir.\",\"ar\":\"متلازمة شبيهة بالودي عبر فرط تنبيه مستقبلات ألفا-1/بيتا-1؛ تعالج بجرعة عالية من حاصر بيتا إسمولول وريدياً.\",\"en\":\"Sympathomimetic toxidrome via alpha-1/beta-1 adrenoceptor hyperstimulation; treat with intravenous high-dose beta-blocker Esmolol.\"},\"feedback\":{\"tr\":\"Yanlış. Sempatomimetik toksisitede (kokain/amfetamin) taşikardi ve hipertermiye rağmen şiddetli terleme (diaforez) görülür. Antikolinerjikte ise cilt tamamen kurudur.\",\"ar\":\"غير صحيح. تترافق المتلازمة الودية (كوكايين/أمفيتامين) بتعرق غزير رغم الحرارة المرتفعة؛ بينما يكون الجلد جافاً تماماً في التسمم بمضادات الكولين.\",\"en\":\"Incorrect. Sympathomimetic toxicity presents with profuse diaphoresis (sweating). Anticholinergic toxicity produces dry (anhidrotic) skin.\"}},{\"id\":\"opt-l8-s12-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Antikolinerjik toksidrom; bilinci kurtarmak amacıyla merkezi sinir sistemine selektif geçen kuaterner amin Neostigmin ile tedavi edilir.\",\"ar\":\"متلازمة مضادة للكولين؛ تعالج بـ نيوستيغمين (أمين رابعي ينفذ انتقائياً للجهاز العصبي المركزي لإنقاذ الوعي).\",\"en\":\"Anticholinergic toxidrome; treat with Neostigmine (a quaternary amine that selectively penetrates the central nervous system to rescue consciousness).\"},\"feedback\":{\"tr\":\"Yanlış. Neostigmin kalıcı yüklü kuaterner amonyum taşır ve kan-beyin bariyerini ASLA GEÇEMEZ; santral deliryumu düzeltemez. Yalnızca tersiyer amin Fizostigmin beyne geçer.\",\"ar\":\"غير صحيح. يحمل النيوستيغمين أميناً رابعياً مشحوناً دائماً ولا يعبر إطلاقاً الحاجز الدماغي؛ فلا يعكس الهذيان المركزي. وحده فيزوستيغمين يعبر للدماغ.\",\"en\":\"Incorrect. Neostigmine possesses a permanently charged quaternary nitrogen that CANNOT cross the blood-brain barrier; only tertiary amines like physostigmine enter the CNS.\"}}],\"prompt\":{\"tr\":\"Bir hasta hipertermi (40°C), kuru kızarık cilt, aşırı ağız kuruluğu, fiks dilate pupiller, deliryum ve idrar retansiyonuyla geliyor. Toksidromu, mekanizmayı ve kan-beyin bariyerini geçen uygun panzehiri belirleyin.\",\"ar\":\"وصل مريض بارتفاع حرارة (40°C)، جلد أحمر جاف، جفاف فم شديد، حدقات متسعة ثابتة، هذيان واحتباس بول. حدد المتلازمة والآلية والترياق المناسب العابر للحاجز الدماغي.\",\"en\":\"A patient presents with hyperthermia (40°C), flushed anhidrotic skin, extreme xerostomia, fixed dilated pupils, delirium, and urinary retention. Identify the toxidrome, mechanism, and the pharmacologically appropriate blood-brain barrier-penetrating antidote.\"},\"title\":{\"tr\":\"Ustalık Sınavı: Antikolinerjik Toksidrom ve Fizostigmin Kurtarması\",\"ar\":\"اختبار الإتقان: المتلازمة المضادة للكولين والإنقاذ بفيزوستيغمين\",\"en\":\"Mastery Check: Anticholinergic Toxidrome & Physostigmine Rescue\"}},\"sources\":[{\"file\":\"Otonom Sinir Sistemi.pdf\",\"page\":28}]}]},\"pharm-mod5-les1\":{\"id\":\"pharm-mod5-les1\",\"courseId\":\"pharmacology\",\"moduleId\":\"ph-mod-05\",\"title\":{\"tr\":\"Renin-Anjiyotensin-Aldosteron Sistemi (RAAS) İnhibisyonu\",\"ar\":\"تثبيط مسار الرينين-أنجيوتنسين-ألدوستيرون (RAAS)\",\"en\":\"Renin-Angiotensin-Aldosterone System (RAAS) Inhibition\"},\"order\":1,\"access\":\"free\",\"objective\":{\"tr\":\"ADE inhibitörleri, ARB'ler ve ARNI'lerin etki mekanizmalarını, efferent arteriyoler hemodinamik etkilerini ve bradikinin kaynaklı anjiyoödem riskini analiz etmek.\",\"ar\":\"تحليل آليات عمل مثبطات ACE وحاصرات ARB ومركبات ARNI، وتأثيراتها الديناميكية على الشريين الصادر، وخطر الوذمة الوعائية المعتمدة على البراديكينين.\",\"en\":\"Analyze mechanisms of action of ACE inhibitors, ARBs, and ARNIs, their efferent arteriolar hemodynamic effects, and bradykinin-mediated angioedema risk.\"},\"misconceptions\":[{\"tr\":\"ARB'lerin de ADE inhibitörleri gibi kuru öksürük ve yüksek bradikinin birikimi yaptığı yanılgısı (öksürük bradikinin ve P maddesi birikiminden kaynaklanır; ADE kininaz II'dir, ARB'ler ise doğrudan AT1 reseptörünü bloke ederek bradikinin yıkımına dokunmaz).\",\"ar\":\"الاعتقاد الخاطئ بأن حاصرات ARB تسبب السعال الجاف وتراكم البراديكينين مثل مثبطات ACE (السعال ينجم عن تراكم البراديكينين؛ إنزيم ACE هو kininase II بينما تحصر ARB مستقبلات AT1 دون المساس بتحلل البراديكينين).\",\"en\":\"The misconception that ARBs cause the same persistent dry cough and bradykinin accumulation as ACE inhibitors (cough stems from bradykinin/substance P buildup; ACE is kininase II, whereas ARBs selectively block AT1 without altering kinin degradation).\"},{\"tr\":\"Bilateral renal arter darlığında glomerüler filtrasyonu korumak için ADE inhibitörü veya ARB verilmesi yanılgısı (intramezangial GFH'yi koruyan efferent vazokonstriksiyondur; AT1 blokajı efferenti genişleterek glomerüler filtrasyon basıncını sıfırlar ve akut böbrek yetmezliği yapar).\",\"ar\":\"الظن الخاطئ بإمكانية إعطاء مثبطات ACE أو ARB لحماية الكلية في تضيق الشريان الكلوي ثنائي الجانب (الحفاظ على GFR يعتمد كلياً على تقبض الشريين الصادر بوساطة Ang II؛ وحصاره يرخي الصادر مسقطاً ضغط الترشيح إلى فشل كلوي حاد).\",\"en\":\"The dangerous belief that ACE inhibitors or ARBs preserve renal function in bilateral renal artery stenosis (adequate GFR relies entirely on Ang II-mediated efferent vasoconstriction; blocking it dilates the efferent arteriole, collapsing GFR into acute anuric renal failure).\"},{\"tr\":\"ADE inhibitörleri ile ARNI (sakubitril/valsartan) kombinasyonunun güvenli olduğu yanılgısı (her ikisi de bradikinin yıkımını çift koldan bloke ederek ölümcül laringeal anjiyoödeme yol açar; aralarında en az 36 saatlik arınma süresi zorunludur).\",\"ar\":\"الاعتقاد الخاطئ بأمان الجمع المباشر بين مثبطات ACE ودواء ARNI (كلاهما يمنع تحلل البراديكينين فيحدث وذمة وعائية حنجرية قاتلة؛ لذا يشترط فترة غسيل دوائي فاصلة لا تقل عن 36 ساعة).\",\"en\":\"The fatal assumption that ACE inhibitors and ARNIs (sacubitril/valsartan) can be co-administered or switched without washout (both block bradykinin degradation via separate pathways, triggering life-threatening angioedema; a 36-hour washout is mandatory).\"}],\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":8}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Katzung's Basic & Clinical Pharmacology\",\"edition\":\"15th ed.\",\"topic\":\"Antihypertensive Agents: Drugs That Inhibit the Renin-Angiotensin System\",\"chapter\":\"Chapter 11: Antihypertensive Agents\",\"page\":\"pp. 180-205\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Goodman & Gilman's The Pharmacological Basis of Therapeutics\",\"edition\":\"14th ed.\",\"topic\":\"Renin and Angiotensin\",\"chapter\":\"Chapter 26: Renin and Angiotensin\",\"page\":\"pp. 471-496\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"pharm-mod5-les1-card1\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Kininaz II ve Kuru Öksürük / Anjiyoödem\",\"prompt\":\"ADE inhibitörlerinin en yaygın kesilme nedeni olan kuru öksürük ve en tehlikeli yan etkisi olan anjiyoödemin biyokimyasal mekanizması nedir?\",\"answer\":\"ADE enzimi aynı zamanda kininaz II'dir; inhibisyonu akciğer ve havayollarında bradikinin ve P maddesi birikimine yol açarak öksürük ve vazodilatasyona bağlı anjiyoödem yapar.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod5-les1-card2\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"ARB Üstünlüğü ve Reseptör Seçiciliği\",\"prompt\":\"Losartan ve valsartan gibi ARB'ler neden kuru öksürüğe yol açmaz?\",\"answer\":\"Doğrudan AT1 reseptörünü bloke ederler; ADE (kininaz II) enzim aktivitesine ve bradikinin yıkım yolağına dokunmazlar.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod5-les1-card3\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Efferent Arteriyol ve Renal Kriz\",\"prompt\":\"Bilateral renal arter darlığında kaptopril veya enalapril verilmesi neden aniden akut böbrek yetmezliğini tetikler?\",\"answer\":\"Böbrek perfüzyonu düştüğünde GFH'yi koruyan tek mekanizma Ang II'nin efferent arteriyolü kasmasıdır; ADEi efferenti genişleterek intraglomerüler filtrasyon basıncını çökertir.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod5-les1-card4\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"ARNI ve 36 Saatlik Arınma Kuralı\",\"prompt\":\"ADE inhibitöründen Sakubitril/Valsartan (ARNI) tedavisine geçerken neden en az 36 saat beklenmelidir?\",\"answer\":\"ADE ve neprilisin enzimlerinin eşzamanlı inhibisyonu masif bradikinin birikimi oluşturarak ölümcül laringeal anjiyoödeme neden olur; 36 saatlik arınma (washout) şarttır.\",\"box\":1,\"intervalDays\":1}],\"steps\":[{\"id\":\"pharm-mod5-les1-step1\",\"order\":1,\"stageIndex\":1,\"stage\":\"hook\",\"type\":\"question\",\"title\":{\"tr\":\"Klinik Paradoks: ACEi Kuru Öksürük ve Anjioödem Paradoksu\",\"ar\":\"المفارقة السريرية: لغز السعال الجاف والوذمة الوعائية بـ ACEi\",\"en\":\"Clinical Paradox: The ACEi Dry Cough & Angioedema Dilemma\"},\"predictThenReveal\":true,\"prompt\":{\"tr\":\"Lisinopril kullanan hipertansiyon hastasında inatçı, kuru bir gece öksürüğü ve ani dil şişmesi gelişir. Losartana geçildiğinde öksürük tamamen kaybolur. Bu tabloyu hangi biyokimyasal mekanizma açıklar?\",\"ar\":\"أصيب مريض ضغط يعالج بليزينوبريل بسعال جاف ليلي عنيد ووذمة مفاجئة في اللسان. أدى التحول إلى لوسارتان لزوال السعال تماماً. ما الآلية الكيميائية الحيوية المفسرة؟\",\"en\":\"An elderly hypertensive patient on lisinopril develops a relentless, dry hacking nocturnal cough and sudden tongue swelling. Switching to losartan completely abolishes the cough. What biochemical mechanism explains this?\"},\"conceptCheck\":{\"question\":{\"tr\":\"ACE inhibitörleri neden kuru öksürük ve anjioödeme yol açarken ARB'ler bu yan etkiyi göstermez?\",\"ar\":\"لماذا تسبب مثبطات ACE سعالاً جافاً ووذمة وعائية بينما تخلو ARBs من هذا الأثر الجانبي؟\",\"en\":\"Why do ACE inhibitors trigger dry cough and angioedema while ARBs lack this adverse effect?\"},\"options\":[{\"id\":\"opt-l9-s1-1\",\"isCorrect\":true,\"text\":{\"tr\":\"ACE (kininaz II) normalde bradikinini ve P maddesini yıkar; ACE inhibisyonu hava yolunda birikimlerine yol açarak bronkokonstriksiyon ve vasküler geçirgenlik yapar.\",\"ar\":\"يفكك إنزيم ACE (كينيناز II) عادة البراديكينين والمادة P؛ يؤدي تثبيطه لتراكمهما مسبباً تشنجاً قصبياً وزيادة في النفوذية الوعائية.\",\"en\":\"ACE (kininase II) normally degrades bradykinin and substance P; ACE inhibition causes their airway and submucosal accumulation, provoking bronchoconstriction and vascular permeability.\"},\"feedback\":{\"tr\":\"Doğru. ACE, bradikinini yıkan kininaz II ile aynı enzimdir. Biriken bradikinin duyusal C-liflerini uyararak öksürük ve anjioödem yapar; ARB'ler kinin metabolizmasına dokunmaz.\",\"ar\":\"صحيح. إنزيم ACE مطابق لـ كينيناز II مفكك البراديكينين. يثير تراكمه ألياف C الحسية محدثاً السعال والوذمة الوعائية، بينما لا تمس ARBs استقلاب الكينين.\",\"en\":\"Correct. ACE is identical to kininase II, degrading bradykinin and substance P. ACEi lead to kinin accumulation; ARBs block AT1 without altering kinin degradation.\"}},{\"id\":\"opt-l9-s1-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Lisinopril akciğer mast hücrelerine doğrudan bağlanıp degranüle ederek böbreklerce temizlenemeyen devasa histamin salınımına yol açar.\",\"ar\":\"يرتبط ليزينوبريل بالخلايا البدينة الرئوية مفجراً إياها، ومحرراً مخازن هيستامين هائلة تعجز الكلى عن تصريفها.\",\"en\":\"Lisinopril directly binds and degranulates pulmonary mast cells, releasing massive histamine stores that cannot be cleared by renal filtration.\"},\"feedback\":{\"tr\":\"Yanlış. ACEi anjioödemi histamin aracılı değildir; bradikinin kaynaklıdır. Bu yüzden antihistaminikler ve kortikosteroidler bu anjioödemi tedavi edemez.\",\"ar\":\"غير صحيح. لا تتواسط الوذمة الوعائية بالهيستامين؛ بل بالبراديكينين، ولهذا تفشل مضادات الهيستامين والكورتيكوستيرويدات في علاجها.\",\"en\":\"Incorrect. ACEi angioedema is non-histaminergic; it is mediated entirely by bradykinin, which is why antihistamines and steroids fail.\"}},{\"id\":\"opt-l9-s1-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Düşük sistemik Anjiyotensin II, bronş düz kasını dinlenim tonusundan mahrum bırakarak refleks spazmları ve mukozal şişmeyi tetikler.\",\"ar\":\"يؤدي نقص أنجيوتنسين II الجهازي لحرمان العضلات التنفسية من مقويتها، مما يثير تشنجات انعكاسية ووذمة مخاطية.\",\"en\":\"Low systemic Angiotensin II deprives bronchial smooth muscle of resting tone, triggering reflex spasms and mucosal swelling.\"},\"feedback\":{\"tr\":\"Yanlış. Anjiyotensin II'nin bronşlarda koruyucu bir tonus etkisi yoktur. Öksürük ve ödem tamamen kininlerin yıkılamamasından kaynaklanır.\",\"ar\":\"غير صحيح. ليس للأنجيوتنسين II دور حامٍ للمقوية الشعبية. ينجم السعال كلياً عن عجز تصريف ببتيدات الكينين.\",\"en\":\"Incorrect. Angiotensin II has no protective role against cough reflexes; symptoms arise purely from impaired clearance of kinins.\"}}]},\"technicalTerms\":[{\"term\":\"ADE inhibitörü\",\"arContext\":\"مثبط الإنزيم المحول للأنجيوتنسين (ACE inhibitor)\"}],\"hints\":[{\"tier\":1,\"tr\":\"ACE enzimi tarihsel olarak başka bir isimle de bilinir: kininaz II.\",\"ar\":\"يُعرف إنزيم ACE تاريخياً باسم إنزيمي آخر: كينيناز II.\",\"en\":\"ACE is also known by another historical enzymatic name: kininase II.\"},{\"tier\":2,\"tr\":\"Kininaz II pulmoner dolaşımda anjiyotensin dışındaki hangi peptitleri yıkar?\",\"ar\":\"ما هي الببتيدات غير الأنجيوتنسين التي يفككها كينيناز II في الدوران الرئوي؟\",\"en\":\"What non-angiotensin peptide does kininase II degrade in the pulmonary circulation?\"},{\"tier\":3,\"tr\":\"ACE inhibitörleri bradikinini ve P maddesini yıkan kininaz II'yi bloke eder; biriken kininler öksürük yapar. ARB'ler kininaz II'yi etkilemez.\",\"ar\":\"تحجب مثبطات ACE إنزيم كينيناز II مفكك البراديكينين؛ وتراكم الكينينات يسبب السعال. لا تؤثر ARBs على كينيناز II.\",\"en\":\"ACE inhibitors block bradykinin and substance P degradation via kininase II; ARBs selectively block AT1 without altering kinin breakdown.\"}],\"widgetType\":\"MultipleChoice\",\"config\":{\"options\":[{\"id\":\"opt-l9-s1-1\",\"isCorrect\":true,\"text\":{\"tr\":\"ACE (kininaz II) normalde bradikinini ve P maddesini yıkar; ACE inhibisyonu hava yolunda birikimlerine yol açarak bronkokonstriksiyon ve vasküler geçirgenlik yapar.\",\"ar\":\"يفكك إنزيم ACE (كينيناز II) عادة البراديكينين والمادة P؛ يؤدي تثبيطه لتراكمهما مسبباً تشنجاً قصبياً وزيادة في النفوذية الوعائية.\",\"en\":\"ACE (kininase II) normally degrades bradykinin and substance P; ACE inhibition causes their airway and submucosal accumulation, provoking bronchoconstriction and vascular permeability.\"},\"feedback\":{\"tr\":\"Doğru. ACE, bradikinini yıkan kininaz II ile aynı enzimdir. Biriken bradikinin duyusal C-liflerini uyararak öksürük ve anjioödem yapar; ARB'ler kinin metabolizmasına dokunmaz.\",\"ar\":\"صحيح. إنزيم ACE مطابق لـ كينيناز II مفكك البراديكينين. يثير تراكمه ألياف C الحسية محدثاً السعال والوذمة الوعائية، بينما لا تمس ARBs استقلاب الكينين.\",\"en\":\"Correct. ACE is identical to kininase II, degrading bradykinin and substance P. ACEi lead to kinin accumulation; ARBs block AT1 without altering kinin degradation.\"}},{\"id\":\"opt-l9-s1-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Lisinopril akciğer mast hücrelerine doğrudan bağlanıp degranüle ederek böbreklerce temizlenemeyen devasa histamin salınımına yol açar.\",\"ar\":\"يرتبط ليزينوبريل بالخلايا البدينة الرئوية مفجراً إياها، ومحرراً مخازن هيستامين هائلة تعجز الكلى عن تصريفها.\",\"en\":\"Lisinopril directly binds and degranulates pulmonary mast cells, releasing massive histamine stores that cannot be cleared by renal filtration.\"},\"feedback\":{\"tr\":\"Yanlış. ACEi anjioödemi histamin aracılı değildir; bradikinin kaynaklıdır. Bu yüzden antihistaminikler ve kortikosteroidler bu anjioödemi tedavi edemez.\",\"ar\":\"غير صحيح. لا تتواسط الوذمة الوعائية بالهيستامين؛ بل بالبراديكينين، ولهذا تفشل مضادات الهيستامين والكورتيكوستيرويدات في علاجها.\",\"en\":\"Incorrect. ACEi angioedema is non-histaminergic; it is mediated entirely by bradykinin, which is why antihistamines and steroids fail.\"}},{\"id\":\"opt-l9-s1-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Düşük sistemik Anjiyotensin II, bronş düz kasını dinlenim tonusundan mahrum bırakarak refleks spazmları ve mukozal şişmeyi tetikler.\",\"ar\":\"يؤدي نقص أنجيوتنسين II الجهازي لحرمان العضلات التنفسية من مقويتها، مما يثير تشنجات انعكاسية ووذمة مخاطية.\",\"en\":\"Low systemic Angiotensin II deprives bronchial smooth muscle of resting tone, triggering reflex spasms and mucosal swelling.\"},\"feedback\":{\"tr\":\"Yanlış. Anjiyotensin II'nin bronşlarda koruyucu bir tonus etkisi yoktur. Öksürük ve ödem tamamen kininlerin yıkılamamasından kaynaklanır.\",\"ar\":\"غير صحيح. ليس للأنجيوتنسين II دور حامٍ للمقوية الشعبية. ينجم السعال كلياً عن عجز تصريف ببتيدات الكينين.\",\"en\":\"Incorrect. Angiotensin II has no protective role against cough reflexes; symptoms arise purely from impaired clearance of kinins.\"}}],\"prompt\":{\"tr\":\"Lisinopril kullanan hipertansiyon hastasında inatçı, kuru bir gece öksürüğü ve ani dil şişmesi gelişir. Losartana geçildiğinde öksürük tamamen kaybolur. Bu tabloyu hangi biyokimyasal mekanizma açıklar?\",\"ar\":\"أصيب مريض ضغط يعالج بليزينوبريل بسعال جاف ليلي عنيد ووذمة مفاجئة في اللسان. أدى التحول إلى لوسارتان لزوال السعال تماماً. ما الآلية الكيميائية الحيوية المفسرة؟\",\"en\":\"An elderly hypertensive patient on lisinopril develops a relentless, dry hacking nocturnal cough and sudden tongue swelling. Switching to losartan completely abolishes the cough. What biochemical mechanism explains this?\"},\"title\":{\"tr\":\"Klinik Paradoks: ACEi Kuru Öksürük ve Anjioödem Paradoksu\",\"ar\":\"المفارقة السريرية: لغز السعال الجاف والوذمة الوعائية بـ ACEi\",\"en\":\"Clinical Paradox: The ACEi Dry Cough & Angioedema Dilemma\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":3}]},{\"id\":\"pharm-mod5-les1-step2\",\"order\":2,\"stageIndex\":2,\"stage\":\"question\",\"type\":\"question\",\"title\":{\"tr\":\"Kavramsal Soru: AT1 ve AT2 Reseptörlerinin Ayrışan Rolleri\",\"ar\":\"سؤال مفاهيمي: الأدوار المتباينة لمستقبلات AT1 و AT2\",\"en\":\"Conceptual Question: AT1 vs AT2 Divergent Receptors\"},\"predictThenReveal\":true,\"prompt\":{\"tr\":\"İlaç kimyagerleri neden hem AT1 hem AT2 reseptörlerini aynı anda bloke eden ilaçlar geliştirmek yerine yalnızca AT1 reseptörlerini bloke eden ARB'leri tasarladılar?\",\"ar\":\"لماذا صمم علماء الأدوية حاصرات مستقبلات الأنجيوتنسين (ARBs) لحصر مستقبلات AT1 فقط بدلاً من حصر AT1 و AT2 معاً؟\",\"en\":\"Why did pharmaceutical chemists design ARBs to block AT1 receptors rather than creating drugs that simultaneously block both AT1 and AT2 receptors?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Neden çift AT1/AT2 blokajı yerine selektif AT1 blokajı (ARB) tercih edilir?\",\"ar\":\"لماذا يفضل الحصر الانتقائي لـ AT1 (عبر ARBs) على الحصر المزدوج لـ AT1 و AT2؟\",\"en\":\"Why is selective AT1 blockade preferred over non-selective dual AT1/AT2 blockade?\"},\"options\":[{\"id\":\"opt-l9-s2-1\",\"isCorrect\":true,\"text\":{\"tr\":\"AT1 vazokonstriksiyon, aldosteron salınımı ve fibrozisi yönetir; bloke edilmeyen AT2 ise karşıt-düzenleyici vazodilatasyon, antiproliferasyon ve NO salınımı sağlar.\",\"ar\":\"يتوسط AT1 التضيق الوعائي وإفراز الألدوستيرون والتليف؛ بينما يتوسط AT2 غير المحصور توسعاً وعائياً معاكساً، وتثبيطاً للتكاثر، وتحرراً لأكسيد النيتريك.\",\"en\":\"AT1 mediates vasoconstriction, aldosterone release, and fibrosis; unblocked AT2 mediates counter-regulatory vasodilation, antiproliferation, and endothelial nitric oxide release.\"},\"feedback\":{\"tr\":\"Doğru. Selektif AT1 blokajı, biriken Ang II'yi açıkta kalan AT2 reseptörlerine yönlendirerek kardiyoprotektif, vazodilatatör ve anti-fibrotik etkiler kazandırır.\",\"ar\":\"صحيح. يوجه حصر AT1 الانتقائي فائض الأنجيوتنسين نحو مستقبلات AT2 غير المحصورة، مما يمنح حماية قلبية وتوسعاً وعائياً وتثبيطاً للتليف.\",\"en\":\"Correct. Selective AT1 blockade shunts accumulating Ang II to unblocked AT2 receptors, conferring cardioprotective and vasodilatory signaling.\"}},{\"id\":\"opt-l9-s2-2\",\"isCorrect\":false,\"text\":{\"tr\":\"AT2 reseptörleri, erişkin kardiyovasküler dokuda hiçbir aşağı akış sinyalleme yeteneği olmayan işlevsiz yalancı genlerdir.\",\"ar\":\"مستقبلات AT2 جينات كاذبة غير وظيفية تفتقر لأي قدرة على التأشير في النسيج القلبي الوعائي للبالغين.\",\"en\":\"AT2 receptors are non-functional pseudogenes with no downstream signaling capability in adult cardiovascular tissue.\"},\"feedback\":{\"tr\":\"Yanlış. AT2 reseptörleri Gi ve fosfatazlara kenetli aktif GPCR'lardır; bradikinin, NO ve cGMP yolaklarını uyararak AT1'e karşı durur.\",\"ar\":\"غير صحيح. مستقبلات AT2 بروتينات GPCR وظيفية مقترنة بـ Gi والفوسفاتاز؛ تعاكس تأشير AT1 بتعزيز مسارات NO و cGMP.\",\"en\":\"Incorrect. AT2 receptors are active GPCRs coupled to Gi and phosphatases; they promote NO and cGMP to counteract AT1 signaling.\"}},{\"id\":\"opt-l9-s2-3\",\"isCorrect\":false,\"text\":{\"tr\":\"AT2 reseptörleri proksimal tübül sodyum pompalarını uyarır; bloke edilmeleri feci bir natriürez ve dolaşım şokuna yol açar.\",\"ar\":\"تحفز مستقبلات AT2 مضخات الصوديوم الأنبوبية القريبة؛ ويؤدي حصرها لطرح كارثي للصوديوم وصدمة دورانية.\",\"en\":\"AT2 receptors stimulate proximal tubular sodium pumps; blocking them would cause catastrophic natriuresis and circulatory shock.\"},\"feedback\":{\"tr\":\"Yanlış. Proksimal sodyum tutulumunu uyaran AT1'dir; AT2 aktivasyonu aksine renal vazodilatasyon ve natriürezi destekler.\",\"ar\":\"غير صحيح. مستقبل AT1 هو من يحفز امتصاص الصوديوم الأنبوبي؛ بينما يدعم تفعيل AT2 التوسع الوعائي وطرح الصوديوم.\",\"en\":\"Incorrect. AT1 stimulates tubular Na+ reabsorption. AT2 activation actually promotes renal vasodilation and natriuresis.\"}}]},\"technicalTerms\":[{\"term\":\"bradikinin\",\"arContext\":\"براديكينين (bradykinin)\"}],\"hints\":[{\"tier\":1,\"tr\":\"AT1 ve AT2 reseptörleri arasındaki zıt fizyolojik dengeyi düşünün.\",\"ar\":\"فكر في التوازن الفسيولوجي المتعاكس بين مستقبلي AT1 و AT2.\",\"en\":\"Consider the opposing physiological balance between AT1 and AT2 receptors.\"},{\"tier\":2,\"tr\":\"AT1 patolojik yeniden şekillenme ve damar büzülmesi yapar. Serbest kalan AT2 uyarılırsa ne olur?\",\"ar\":\"يتوسط AT1 إعادة التشكيل المرضي والتضيق. ماذا يحدث لو بقي AT2 حراً ليرتبط به الأنجيوتنسين؟\",\"en\":\"AT1 mediates vasoconstriction and remodeling. What happens when unblocked AT2 is stimulated?\"},{\"tier\":3,\"tr\":\"Selektif AT1 blokajı, dolaşımdaki Ang II'yi vazodilatatör, antiproliferatif ve NO salıcı faydalı AT2 reseptörlerine yönlendirir.\",\"ar\":\"يوجه الحصر الانتقائي لـ AT1 الأنجيوتنسين المتراكم نحو مستقبلات AT2 المفيدة التي تسبب التوسع الوعائي وتثبيط التليف.\",\"en\":\"Selective AT1 blockade permits unopposed activation of beneficial AT2 receptors, inducing vasodilation, NO generation, and anti-fibrotic protection.\"}],\"widgetType\":\"MultipleChoice\",\"config\":{\"options\":[{\"id\":\"opt-l9-s2-1\",\"isCorrect\":true,\"text\":{\"tr\":\"AT1 vazokonstriksiyon, aldosteron salınımı ve fibrozisi yönetir; bloke edilmeyen AT2 ise karşıt-düzenleyici vazodilatasyon, antiproliferasyon ve NO salınımı sağlar.\",\"ar\":\"يتوسط AT1 التضيق الوعائي وإفراز الألدوستيرون والتليف؛ بينما يتوسط AT2 غير المحصور توسعاً وعائياً معاكساً، وتثبيطاً للتكاثر، وتحرراً لأكسيد النيتريك.\",\"en\":\"AT1 mediates vasoconstriction, aldosterone release, and fibrosis; unblocked AT2 mediates counter-regulatory vasodilation, antiproliferation, and endothelial nitric oxide release.\"},\"feedback\":{\"tr\":\"Doğru. Selektif AT1 blokajı, biriken Ang II'yi açıkta kalan AT2 reseptörlerine yönlendirerek kardiyoprotektif, vazodilatatör ve anti-fibrotik etkiler kazandırır.\",\"ar\":\"صحيح. يوجه حصر AT1 الانتقائي فائض الأنجيوتنسين نحو مستقبلات AT2 غير المحصورة، مما يمنح حماية قلبية وتوسعاً وعائياً وتثبيطاً للتليف.\",\"en\":\"Correct. Selective AT1 blockade shunts accumulating Ang II to unblocked AT2 receptors, conferring cardioprotective and vasodilatory signaling.\"}},{\"id\":\"opt-l9-s2-2\",\"isCorrect\":false,\"text\":{\"tr\":\"AT2 reseptörleri, erişkin kardiyovasküler dokuda hiçbir aşağı akış sinyalleme yeteneği olmayan işlevsiz yalancı genlerdir.\",\"ar\":\"مستقبلات AT2 جينات كاذبة غير وظيفية تفتقر لأي قدرة على التأشير في النسيج القلبي الوعائي للبالغين.\",\"en\":\"AT2 receptors are non-functional pseudogenes with no downstream signaling capability in adult cardiovascular tissue.\"},\"feedback\":{\"tr\":\"Yanlış. AT2 reseptörleri Gi ve fosfatazlara kenetli aktif GPCR'lardır; bradikinin, NO ve cGMP yolaklarını uyararak AT1'e karşı durur.\",\"ar\":\"غير صحيح. مستقبلات AT2 بروتينات GPCR وظيفية مقترنة بـ Gi والفوسفاتاز؛ تعاكس تأشير AT1 بتعزيز مسارات NO و cGMP.\",\"en\":\"Incorrect. AT2 receptors are active GPCRs coupled to Gi and phosphatases; they promote NO and cGMP to counteract AT1 signaling.\"}},{\"id\":\"opt-l9-s2-3\",\"isCorrect\":false,\"text\":{\"tr\":\"AT2 reseptörleri proksimal tübül sodyum pompalarını uyarır; bloke edilmeleri feci bir natriürez ve dolaşım şokuna yol açar.\",\"ar\":\"تحفز مستقبلات AT2 مضخات الصوديوم الأنبوبية القريبة؛ ويؤدي حصرها لطرح كارثي للصوديوم وصدمة دورانية.\",\"en\":\"AT2 receptors stimulate proximal tubular sodium pumps; blocking them would cause catastrophic natriuresis and circulatory shock.\"},\"feedback\":{\"tr\":\"Yanlış. Proksimal sodyum tutulumunu uyaran AT1'dir; AT2 aktivasyonu aksine renal vazodilatasyon ve natriürezi destekler.\",\"ar\":\"غير صحيح. مستقبل AT1 هو من يحفز امتصاص الصوديوم الأنبوبي؛ بينما يدعم تفعيل AT2 التوسع الوعائي وطرح الصوديوم.\",\"en\":\"Incorrect. AT1 stimulates tubular Na+ reabsorption. AT2 activation actually promotes renal vasodilation and natriuresis.\"}}],\"prompt\":{\"tr\":\"İlaç kimyagerleri neden hem AT1 hem AT2 reseptörlerini aynı anda bloke eden ilaçlar geliştirmek yerine yalnızca AT1 reseptörlerini bloke eden ARB'leri tasarladılar?\",\"ar\":\"لماذا صمم علماء الأدوية حاصرات مستقبلات الأنجيوتنسين (ARBs) لحصر مستقبلات AT1 فقط بدلاً من حصر AT1 و AT2 معاً؟\",\"en\":\"Why did pharmaceutical chemists design ARBs to block AT1 receptors rather than creating drugs that simultaneously block both AT1 and AT2 receptors?\"},\"title\":{\"tr\":\"Kavramsal Soru: AT1 ve AT2 Reseptörlerinin Ayrışan Rolleri\",\"ar\":\"سؤال مفاهيمي: الأدوار المتباينة لمستقبلات AT1 و AT2\",\"en\":\"Conceptual Question: AT1 vs AT2 Divergent Receptors\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":4}]},{\"id\":\"pharm-mod5-les1-step3\",\"order\":3,\"stageIndex\":3,\"stage\":\"intuition\",\"type\":\"question\",\"title\":{\"tr\":\"Fiziksel Sezgi: Efferent Arteriyoler Çıkış Kıskacı\",\"ar\":\"الحدس الفيزيائي: ملقط الشريان الصادر الكلوي\",\"en\":\"Physical Intuition: The Efferent Arteriolar Clamp\"},\"prompt\":{\"tr\":\"Glomerüler filtrasyonu bahçe hortumunun ucundaki ayarlı nozuldan su fışkırtmaya benzetin. Anjiyotensin II efferent çıkışı sıkıştırıyorsa, bir ACE inhibitörü o kıskacı gevşettiğinde intraglomerüler basınca ne olur?\",\"ar\":\"تخيل الترشيح الكبيبي كضغط ماء عبر فوهة خرطوم. إذا كان أنجيوتنسين II يضيق المخرج الصادر، فماذا يحدث للضغط داخل الكبيبة حين يرخي مثبط ACE هذا الملقط؟\",\"en\":\"Think of glomerular filtration as water forced through a garden hose nozzle. If Angiotensin II constricts the efferent outlet, what happens to glomerular pressure when an ACEi opens that outlet clamp?\"},\"technicalTerms\":[{\"term\":\"kininaz II\",\"arContext\":\"كينينيز 2 (kininase II)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Afferent giriş (prostaglandinler) ile efferent çıkış (Ang II) ayrımını hatırlayın.\",\"ar\":\"ميز بين المدخل الوارد (تنظمه البروستاغلاندينات) والمخرج الصادر (ينظمه أنجيوتنسين II).\",\"en\":\"Distinguish between the afferent inlet (prostaglandins) and efferent outlet (Angiotensin II).\"},{\"tier\":2,\"tr\":\"Bir borunun çıkışındaki vana açılırsa, gerideki iç hidrostatik basınç artar mı azalır mı?\",\"ar\":\"إذا فتحت صمام المخرج في أنبوب، هل يرتفع الضغط الداخلي قبله أم ينخفض؟\",\"en\":\"When you open an exit valve on a pipe, does the upstream hydrostatic pressure increase or decrease?\"},{\"tier\":3,\"tr\":\"Ang II efferent arteriyolü kasarak GFR'yi korur. ACEi bu çıkışı gevşetince intraglomerüler hidrostatik basınç ve GFR düşer.\",\"ar\":\"يقبض Ang II الشريان الصادر لصيانة الرشح. يؤدي إرخاؤه بمثبطات ACE لهبوط الضغط داخل الكبيبة وانخفاض GFR.\",\"en\":\"Ang II constricts the efferent arteriole to maintain filtration pressure. Blocking it dilates the outlet, dropping intraglomerular pressure and GFR.\"}],\"widgetType\":\"MultipleChoice\",\"conceptCheck\":{\"question\":{\"tr\":\"ACE inhibitörleri efferent arteriyolü genişlettiğinde glomerüler filtrasyona ne olur?\",\"ar\":\"ماذا يحدث للترشيح الكبيبي عندما توسع مثبطات ACE الشريان الصادر؟\",\"en\":\"What happens to glomerular hemodynamics when ACE inhibitors dilate the efferent arteriole?\"},\"options\":[{\"id\":\"opt-l9-s3-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Efferent arteriyol dilatasyonu intraglomerüler hidrostatik basıncı düşürür; filtrasyon stresini azaltır ancak GFR'de akut bir düşüşe neden olabilir.\",\"ar\":\"يؤدي توسع الشريان الصادر لانخفاض الضغط الهيدروستاتيكي داخل الكبيبة، مقللاً إجهاد الترشيح لكنه قد يخفض معدل الرشح الكبيبي (GFR) حاداً.\",\"en\":\"Efferent arteriolar dilation drops intraglomerular capillary hydrostatic pressure, reducing filtration stress but potentially causing an acute decline in GFR.\"},\"feedback\":{\"tr\":\"Doğru. Ang II efferent çıkışı büzerek filtrasyon basıncını yüksek tutar. ACEi çıkışı gevşetir; uzun vadede böbreği korur ancak akut evrede GFR'de geçici düşüş yapabilir.\",\"ar\":\"صحيح. يضيق Ang II الشريان الصادر لصيانة GFR. ترخي مثبطات ACE هذا المخرج، مما يحمي الكلية مستقبلاً لكنه قد يخفض GFR حاداً ومؤقتاً.\",\"en\":\"Correct. Ang II constricts efferent arterioles to sustain GFR. ACE inhibitors dilate the efferent outlet, reducing intraglomerular pressure.\"}},{\"id\":\"opt-l9-s3-2\",\"isCorrect\":false,\"text\":{\"tr\":\"ACE inhibitörleri afferent arteriyolleri selektif olarak kasarak glomerüler yumağı tüm arteryel perfüzyondan mahrum bırakır.\",\"ar\":\"تقبض مثبطات ACE الشريانات الواردة انتقائياً، حارمة الكبيبة الكلوية من أي تروية شريانية.\",\"en\":\"ACE inhibitors selectively vasoconstrict afferent arterioles, starving the glomerular tuft of all arterial perfusion.\"},\"feedback\":{\"tr\":\"Yanlış. Afferent arteriyolü büzen NSAİİ'lerdir (prostaglandinleri baskılayarak). ACE inhibitörleri ise efferent arteriyolü gevşetir.\",\"ar\":\"غير صحيح. المسكنات (NSAIDs) هي من تقبض الشريان الوارد بتثبيط البروستاغلاندين؛ بينما ترخي مثبطات ACE الشريان الصادر.\",\"en\":\"Incorrect. Afferent arterioles are constricted by NSAIDs via prostaglandin inhibition; ACE inhibitors selectively dilate efferent arterioles.\"}},{\"id\":\"opt-l9-s3-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Efferent çıkışın açılması retrograd geri basınç yaratarak glomerüler filtrasyon basıncını ikiye katlar ve hematüriye yol açar.\",\"ar\":\"يولد فتح المخرج الصادر ضغطاً رجوعياً يضاعف ضغط الترشيح الكبيبي ويؤدي لبيلة دموية.\",\"en\":\"Opening the efferent outlet creates retrograde backpressure, doubling intraglomerular filtration pressure and precipitating hematuria.\"},\"feedback\":{\"tr\":\"Yanlış. Çıkış vanasının açılması geri basınç yapmaz; aksine kılcal damarlardaki hidrostatik basıncı hızla deşarj eder.\",\"ar\":\"غير صحيح. لا يولد فتح الصمام الصادر ضغطاً رجوعياً، بل يفرغ الضغط الهيدروستاتيكي في الشعيرات الكبيبية.\",\"en\":\"Incorrect. Opening an outlet reduces upstream pressure; efferent vasodilation unloads intraglomerular capillary hydrostatic pressure.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-l9-s3-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Efferent arteriyol dilatasyonu intraglomerüler hidrostatik basıncı düşürür; filtrasyon stresini azaltır ancak GFR'de akut bir düşüşe neden olabilir.\",\"ar\":\"يؤدي توسع الشريان الصادر لانخفاض الضغط الهيدروستاتيكي داخل الكبيبة، مقللاً إجهاد الترشيح لكنه قد يخفض معدل الرشح الكبيبي (GFR) حاداً.\",\"en\":\"Efferent arteriolar dilation drops intraglomerular capillary hydrostatic pressure, reducing filtration stress but potentially causing an acute decline in GFR.\"},\"feedback\":{\"tr\":\"Doğru. Ang II efferent çıkışı büzerek filtrasyon basıncını yüksek tutar. ACEi çıkışı gevşetir; uzun vadede böbreği korur ancak akut evrede GFR'de geçici düşüş yapabilir.\",\"ar\":\"صحيح. يضيق Ang II الشريان الصادر لصيانة GFR. ترخي مثبطات ACE هذا المخرج، مما يحمي الكلية مستقبلاً لكنه قد يخفض GFR حاداً ومؤقتاً.\",\"en\":\"Correct. Ang II constricts efferent arterioles to sustain GFR. ACE inhibitors dilate the efferent outlet, reducing intraglomerular pressure.\"}},{\"id\":\"opt-l9-s3-2\",\"isCorrect\":false,\"text\":{\"tr\":\"ACE inhibitörleri afferent arteriyolleri selektif olarak kasarak glomerüler yumağı tüm arteryel perfüzyondan mahrum bırakır.\",\"ar\":\"تقبض مثبطات ACE الشريانات الواردة انتقائياً، حارمة الكبيبة الكلوية من أي تروية شريانية.\",\"en\":\"ACE inhibitors selectively vasoconstrict afferent arterioles, starving the glomerular tuft of all arterial perfusion.\"},\"feedback\":{\"tr\":\"Yanlış. Afferent arteriyolü büzen NSAİİ'lerdir (prostaglandinleri baskılayarak). ACE inhibitörleri ise efferent arteriyolü gevşetir.\",\"ar\":\"غير صحيح. المسكنات (NSAIDs) هي من تقبض الشريان الوارد بتثبيط البروستاغلاندين؛ بينما ترخي مثبطات ACE الشريان الصادر.\",\"en\":\"Incorrect. Afferent arterioles are constricted by NSAIDs via prostaglandin inhibition; ACE inhibitors selectively dilate efferent arterioles.\"}},{\"id\":\"opt-l9-s3-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Efferent çıkışın açılması retrograd geri basınç yaratarak glomerüler filtrasyon basıncını ikiye katlar ve hematüriye yol açar.\",\"ar\":\"يولد فتح المخرج الصادر ضغطاً رجوعياً يضاعف ضغط الترشيح الكبيبي ويؤدي لبيلة دموية.\",\"en\":\"Opening the efferent outlet creates retrograde backpressure, doubling intraglomerular filtration pressure and precipitating hematuria.\"},\"feedback\":{\"tr\":\"Yanlış. Çıkış vanasının açılması geri basınç yapmaz; aksine kılcal damarlardaki hidrostatik basıncı hızla deşarj eder.\",\"ar\":\"غير صحيح. لا يولد فتح الصمام الصادر ضغطاً رجوعياً، بل يفرغ الضغط الهيدروستاتيكي في الشعيرات الكبيبية.\",\"en\":\"Incorrect. Opening an outlet reduces upstream pressure; efferent vasodilation unloads intraglomerular capillary hydrostatic pressure.\"}}],\"prompt\":{\"tr\":\"Glomerüler filtrasyonu bahçe hortumunun ucundaki ayarlı nozuldan su fışkırtmaya benzetin. Anjiyotensin II efferent çıkışı sıkıştırıyorsa, bir ACE inhibitörü o kıskacı gevşettiğinde intraglomerüler basınca ne olur?\",\"ar\":\"تخيل الترشيح الكبيبي كضغط ماء عبر فوهة خرطوم. إذا كان أنجيوتنسين II يضيق المخرج الصادر، فماذا يحدث للضغط داخل الكبيبة حين يرخي مثبط ACE هذا الملقط؟\",\"en\":\"Think of glomerular filtration as water forced through a garden hose nozzle. If Angiotensin II constricts the efferent outlet, what happens to glomerular pressure when an ACEi opens that outlet clamp?\"},\"title\":{\"tr\":\"Fiziksel Sezgi: Efferent Arteriyoler Çıkış Kıskacı\",\"ar\":\"الحدس الفيزيائي: ملقط الشريان الصادر الكلوي\",\"en\":\"Physical Intuition: The Efferent Arteriolar Clamp\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":5}]},{\"id\":\"pharm-mod5-les1-step4\",\"order\":4,\"stageIndex\":4,\"stage\":\"visual_explanation\",\"type\":\"question\",\"title\":{\"tr\":\"Görsel Açıklama: RAAS Biyokimyasal Kaskat Haritası\",\"ar\":\"شرح مرئي: خريطة الشلال الكيميائي الحيوي لـ RAAS\",\"en\":\"Visual Explanation: RAAS Biochemical Cascade Map\"},\"prompt\":{\"tr\":\"Enzimatik kaskadı takip edin: Jukstaglomerüler renin karaciğer kaynaklı anjiyotensinojeni Ang I'e; pulmoner ACE ise Ang I'i Ang II'ye dönüştürür. ACE'yi tanımlayan benzersiz katalitik özellik nedir?\",\"ar\":\"تتبع شلال الإنزيمات: يشطر رينين الكبيبات أنجيوتنسينوجين الكبدي إلى Ang I؛ ويشطر ACE الرئوي Ang I إلى Ang II. ما الخاصية التحفيزية المميزة لـ ACE؟\",\"en\":\"Trace the enzymatic cascade: Juxtaglomerular renin cleaves liver angiotensinogen to Ang I; pulmonary ACE cleaves Ang I to Ang II. What unique catalytic property defines ACE?\"},\"technicalTerms\":[{\"term\":\"anjiyotensin II\",\"arContext\":\"أنجيوتنسين 2 (angiotensin II)\"},{\"term\":\"AT1 reseptörü\",\"arContext\":\"مستقبل AT1 (AT1 receptor)\"}],\"hints\":[{\"tier\":1,\"tr\":\"ACE enzimi 10 amino asitlik dekapeptit Ang I'in karboksil ucunu hedefler.\",\"ar\":\"يستهدف إنزيم ACE النهاية الكربوكسيلية لببتيد Ang I المكون من 10 أحماض أمينية.\",\"en\":\"ACE targets the carboxyl end of the 10-amino acid peptide Angiotensin I.\"},{\"tier\":2,\"tr\":\"Katalitik kofaktöre dikkat edin: ACE aktif bölgesinde iki değerlikli çinko katyonuna (Zn2+) ihtiyaç duyar.\",\"ar\":\"انتبه للمرافق التحفيزي: يتطلب ACE كاتيون زنك ثنائي التكافؤ (Zn2+) في موقعه النشط.\",\"en\":\"Notice the catalytic co-factor: ACE requires a divalent zinc cation (Zn2+) in its active pocket.\"},{\"tier\":3,\"tr\":\"ACE bir dipeptidil karboksipeptidazdır; Ang I'in C-ucundan iki amino asit (His-Leu) keserek güçlü oktapeptit Ang II'yi üretir.\",\"ar\":\"يعمل ACE كـ ثنائي ببتيديل كربوكسي ببتيداز؛ يشطر حمضي His-Leu من نهاية Ang I ليشكل Ang II النشط ثماني الببتيد.\",\"en\":\"ACE functions as a dipeptidyl carboxypeptidase, clipping the C-terminal His-Leu from Ang I to yield active octapeptide Ang II.\"}],\"widgetType\":\"MultipleChoice\",\"conceptCheck\":{\"question\":{\"tr\":\"ACE enziminin moleküler yapısı ve katalitik kesim mekanizması nasıldır?\",\"ar\":\"ما هي البنية الجزيئية وآلية الشطر التحفيزية لإنزيم ACE؟\",\"en\":\"What is the molecular class and catalytic cleavage mechanism of ACE?\"},\"options\":[{\"id\":\"opt-l9-s4-1\",\"isCorrect\":true,\"text\":{\"tr\":\"ACE, dekapeptit Ang I'in C-ucundan dipeptit (His-Leu) kopararak oktapeptit Ang II oluşturan bir çinko-metallopeptidazdır (dipeptidil karboksipeptidaz).\",\"ar\":\"إنزيم ACE هو ميتالوببتيداز زنك (ثنائي ببتيديل كربوكسي ببتيداز) يشطر ثنائي الببتيد (His-Leu) من Ang I ليشكل Ang II ثماني الببتيد.\",\"en\":\"ACE is a zinc-metallopeptidase (dipeptidyl carboxypeptidase) that cleaves the C-terminal dipeptide (His-Leu) from decapeptide Ang I to form octapeptide Ang II.\"},\"feedback\":{\"tr\":\"Doğru. ACE zara bağlı bir çinko metaloenzimidir; Ang I'in C-terminalinden iki amino asit kopararak Ang II üretir ve bradikinini inaktive eder.\",\"ar\":\"صحيح. إنزيم ACE ميتالوانزيم زنك مرتبط بالغشاء؛ يزيل ثنائي ببتيد من نهاية Ang I مشكلاً Ang II، كما يثبط البراديكينين.\",\"en\":\"Correct. ACE is a zinc metalloenzyme that removes a C-terminal dipeptide from Ang I to generate active Ang II, while also inactivating bradykinin.\"}},{\"id\":\"opt-l9-s4-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Renin, dolaşımdaki kolesterol esterlerinden aldosteronu doğrudan sentezleyen bir çinko metallopeptidazdır.\",\"ar\":\"الرينين ميتالوببتيداز زنك يصنع الألدوستيرون مباشرة من إسترات الكوليسترول الجائلة.\",\"en\":\"Renin is a zinc metallopeptidase that directly synthesizes aldosterone from circulating cholesterol esters.\"},\"feedback\":{\"tr\":\"Yanlış. Renin aspartik proteazdır ve anjiyotensinojeni Ang I'e yıkar; steroid sentezlemez.\",\"ar\":\"غير صحيح. الرينين إندوببتيداز أسبارتيك يشطر أنجيوتنسينوجين إلى Ang I؛ ولا يصنع الستيرويدات.\",\"en\":\"Incorrect. Renin is an aspartic endopeptidase cleaving angiotensinogen to Ang I; it does not synthesize steroid hormones.\"}},{\"id\":\"opt-l9-s4-3\",\"isCorrect\":false,\"text\":{\"tr\":\"ACE, peptitleri N-terminal aspartat ucundan başlayarak sırayla parçalayan bir aminopeptidazdır.\",\"ar\":\"إنزيم ACE هو أمينوببتيداز يفكك الببتيدات تدريجياً بدءاً من نهاية حمض الأسبارتيك النيتروجينية.\",\"en\":\"ACE is an aminopeptidase that progressively degrades peptides starting from their N-terminal aspartate residue.\"},\"feedback\":{\"tr\":\"Yanlış. ACE bir aminopeptidaz değil, karboksipeptidazdır; peptidin C-ucundan iki amino asit keser.\",\"ar\":\"غير صحيح. إنزيم ACE كربوكسي ببتيداز وليس أمينوببتيداز؛ حيث يقطع ثنائي ببتيد من النهاية الكربوكسيلية.\",\"en\":\"Incorrect. ACE is a carboxypeptidase; it requires a free carboxy-terminus and cleaves two amino acids from the C-terminus.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-l9-s4-1\",\"isCorrect\":true,\"text\":{\"tr\":\"ACE, dekapeptit Ang I'in C-ucundan dipeptit (His-Leu) kopararak oktapeptit Ang II oluşturan bir çinko-metallopeptidazdır (dipeptidil karboksipeptidaz).\",\"ar\":\"إنزيم ACE هو ميتالوببتيداز زنك (ثنائي ببتيديل كربوكسي ببتيداز) يشطر ثنائي الببتيد (His-Leu) من Ang I ليشكل Ang II ثماني الببتيد.\",\"en\":\"ACE is a zinc-metallopeptidase (dipeptidyl carboxypeptidase) that cleaves the C-terminal dipeptide (His-Leu) from decapeptide Ang I to form octapeptide Ang II.\"},\"feedback\":{\"tr\":\"Doğru. ACE zara bağlı bir çinko metaloenzimidir; Ang I'in C-terminalinden iki amino asit kopararak Ang II üretir ve bradikinini inaktive eder.\",\"ar\":\"صحيح. إنزيم ACE ميتالوانزيم زنك مرتبط بالغشاء؛ يزيل ثنائي ببتيد من نهاية Ang I مشكلاً Ang II، كما يثبط البراديكينين.\",\"en\":\"Correct. ACE is a zinc metalloenzyme that removes a C-terminal dipeptide from Ang I to generate active Ang II, while also inactivating bradykinin.\"}},{\"id\":\"opt-l9-s4-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Renin, dolaşımdaki kolesterol esterlerinden aldosteronu doğrudan sentezleyen bir çinko metallopeptidazdır.\",\"ar\":\"الرينين ميتالوببتيداز زنك يصنع الألدوستيرون مباشرة من إسترات الكوليسترول الجائلة.\",\"en\":\"Renin is a zinc metallopeptidase that directly synthesizes aldosterone from circulating cholesterol esters.\"},\"feedback\":{\"tr\":\"Yanlış. Renin aspartik proteazdır ve anjiyotensinojeni Ang I'e yıkar; steroid sentezlemez.\",\"ar\":\"غير صحيح. الرينين إندوببتيداز أسبارتيك يشطر أنجيوتنسينوجين إلى Ang I؛ ولا يصنع الستيرويدات.\",\"en\":\"Incorrect. Renin is an aspartic endopeptidase cleaving angiotensinogen to Ang I; it does not synthesize steroid hormones.\"}},{\"id\":\"opt-l9-s4-3\",\"isCorrect\":false,\"text\":{\"tr\":\"ACE, peptitleri N-terminal aspartat ucundan başlayarak sırayla parçalayan bir aminopeptidazdır.\",\"ar\":\"إنزيم ACE هو أمينوببتيداز يفكك الببتيدات تدريجياً بدءاً من نهاية حمض الأسبارتيك النيتروجينية.\",\"en\":\"ACE is an aminopeptidase that progressively degrades peptides starting from their N-terminal aspartate residue.\"},\"feedback\":{\"tr\":\"Yanlış. ACE bir aminopeptidaz değil, karboksipeptidazdır; peptidin C-ucundan iki amino asit keser.\",\"ar\":\"غير صحيح. إنزيم ACE كربوكسي ببتيداز وليس أمينوببتيداز؛ حيث يقطع ثنائي ببتيد من النهاية الكربوكسيلية.\",\"en\":\"Incorrect. ACE is a carboxypeptidase; it requires a free carboxy-terminus and cleaves two amino acids from the C-terminus.\"}}],\"prompt\":{\"tr\":\"Enzimatik kaskadı takip edin: Jukstaglomerüler renin karaciğer kaynaklı anjiyotensinojeni Ang I'e; pulmoner ACE ise Ang I'i Ang II'ye dönüştürür. ACE'yi tanımlayan benzersiz katalitik özellik nedir?\",\"ar\":\"تتبع شلال الإنزيمات: يشطر رينين الكبيبات أنجيوتنسينوجين الكبدي إلى Ang I؛ ويشطر ACE الرئوي Ang I إلى Ang II. ما الخاصية التحفيزية المميزة لـ ACE؟\",\"en\":\"Trace the enzymatic cascade: Juxtaglomerular renin cleaves liver angiotensinogen to Ang I; pulmonary ACE cleaves Ang I to Ang II. What unique catalytic property defines ACE?\"},\"title\":{\"tr\":\"Görsel Açıklama: RAAS Biyokimyasal Kaskat Haritası\",\"ar\":\"شرح مرئي: خريطة الشلال الكيميائي الحيوي لـ RAAS\",\"en\":\"Visual Explanation: RAAS Biochemical Cascade Map\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":6}]},{\"id\":\"pharm-mod5-les1-step5\",\"order\":5,\"stageIndex\":5,\"stage\":\"interactive_artifact\",\"type\":\"interactive_artifact\",\"title\":{\"tr\":\"Doz-Yanıt Eğrisi: Anjiyotensin II ve AT1 Antagonizmi\",\"ar\":\"منحنى الجرعة والاستجابة: الأنجيوتنسين 2 وحصار AT1\",\"en\":\"Dose-Response Modulator: Angiotensin II & AT1 Antagonism\"},\"prompt\":{\"tr\":\"Simülatörde Anjiyotensin II konsantrasyonunu artırarak vazokonstriksiyon eğrisini izleyin. Yarışmalı AT1 blokeri losartan ekleyerek eğrinin sağa kaymasını, aşılamaz kandesartan ile maksimum yanıtın düşüşünü keşfedin.\",\"ar\":\"زد تركيز Ang II في المحاكي وراقب منحنى تقبض الأوعية. أضف Losartan التنافسي لتشهد إزاحة المنحنى يميناً، أو Candesartan غير القابل للتجاوز لتشهد هبوط Emax.\",\"en\":\"Increase Angiotensin II concentration to generate vasoconstriction. Introduce competitive losartan to observe parallel rightward shifts, or candesartan to see insurmountable depression of Emax.\"},\"predictThenReveal\":false,\"widgetType\":\"DoseResponseCurve\",\"widget\":{\"type\":\"DoseResponseCurve\",\"config\":{\"title\":\"Anjiyotensin II Doz-Yanıt ve AT1 Blokajı\",\"prompt\":\"Anjiyotensin II konsantrasyonunu artırın; losartan ve kandesartan ile AT1 reseptör eğrisindeki değişimi izleyin.\",\"defaultEc50\":1,\"defaultEmax\":100,\"defaultHillSlope\":1,\"modes\":[\"agonist\",\"competitive_antagonist\",\"noncompetitive_antagonist\"],\"source\":{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":8},\"explanation\":\"Losartan kompetitif antagonist olarak eğriyi sağa paralel kaydırırken (EC50 artar), kandesartan reseptörden çok yavaş ayrılarak aşılamaz (non-kompetitif benzeri) blokajla Emax değerini baskılar.\"}},\"config\":{\"title\":\"Anjiyotensin II Doz-Yanıt ve AT1 Blokajı\",\"prompt\":\"Anjiyotensin II konsantrasyonunu artırın; losartan ve kandesartan ile AT1 reseptör eğrisindeki değişimi izleyin.\",\"defaultEc50\":1,\"defaultEmax\":100,\"defaultHillSlope\":1,\"modes\":[\"agonist\",\"competitive_antagonist\",\"noncompetitive_antagonist\"],\"source\":{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":8},\"explanation\":\"Losartan kompetitif antagonist olarak eğriyi sağa paralel kaydırırken (EC50 artar), kandesartan reseptörden çok yavaş ayrılarak aşılamaz (non-kompetitif benzeri) blokajla Emax değerini baskılar.\"},\"technicalTerms\":[{\"term\":\"kompetitif antagonizm\",\"arContext\":\"المناهضة التنافسية (competitive antagonism)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Kompetitif antagonistler EC50'yi artırır ancak maksimum tavan yanıtı (Emax) düşürmez.\",\"ar\":\"تزيد المضادات التنافسية قيمة EC50 دون خفض الاستجابة القصوى (Emax).\",\"en\":\"Competitive antagonists increase EC50 without decreasing the maximal ceiling response (Emax).\"},{\"tier\":2,\"tr\":\"Reseptörden çok yavaş ayrılan aşılamaz antagonistler erişilebilir reseptör havuzunu tüketerek Emax'ı baskılar.\",\"ar\":\"تستنفد المضادات غير القابلة للتجاوز حوض المستقبلات المتاحة فتخفض Emax.\",\"en\":\"Insurmountable (slowly dissociating) antagonists reduce the pool of accessible receptors, depressing Emax.\"},{\"tier\":3,\"tr\":\"Losartan kompetitif olarak Ang II eğrisini sağa kaydırırken (EC50 artar), kandesartan reseptörden çok yavaş ayrılarak Emax'ı baskılar.\",\"ar\":\"يزيح لوسارتان منحنى Ang II يميناً تنافسياً (زيادة EC50)، بينما ينفصل كانيديسارتان ببطء شديد كابحاً Emax.\",\"en\":\"Losartan competitively shifts the Ang II curve rightward (higher EC50), whereas candesartan dissociates extremely slowly to suppress Emax.\"}],\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":7}]},{\"id\":\"pharm-mod5-les1-step6\",\"order\":6,\"stageIndex\":6,\"stage\":\"guided_discovery\",\"type\":\"question\",\"title\":{\"tr\":\"Rehberli Keşif: Aldosteron Baskılanması ve Potasyum Tutulumu\",\"ar\":\"استكشاف موجه: تثبيط الألدوستيرون واحتباس البوتاسيوم\",\"en\":\"Guided Discovery: Aldosterone Suppression & Potassium Balance\"},\"prompt\":{\"tr\":\"Anjiyotensin II, adrenal zona glomerulosa hücrelerini aldosteron salgılaması için uyarır. Bir ACEi veya ARB bu uyarıyı kestiğinde serum potasyumu neden yükselir?\",\"ar\":\"يحفز أنجيوتنسين II قشر الكظر لإفراز الألدوستيرون. حين يقطع مثبط ACE أو ARB هذا التنبيه، لماذا يرتفع بوتاسيوم المصل؟\",\"en\":\"Angiotensin II stimulates adrenal cortical zona glomerulosa cells to secrete aldosterone. When an ACEi or ARB shuts down this stimulus, why does serum potassium rise?\"},\"technicalTerms\":[{\"term\":\"negatif geri bildirim\",\"arContext\":\"التغذية الراجعة السلبية (negative feedback)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Aldosteronun geç distal tübül ve kortikal toplayıcı kanallardaki ana hücrelerde (principal cells) ne yaptığını düşünün.\",\"ar\":\"فكر فيما يفعله الألدوستيرون في الخلايا الرئيسية بالأنابيب الجامعة القشرية.\",\"en\":\"Consider where aldosterone acts in the cortical collecting duct principal cells.\"},{\"tier\":2,\"tr\":\"Aldosteron sodyum geri emilimini potasyum ve proton atılımı karşılığında yönetir.\",\"ar\":\"ينظم الألدوستيرون امتصاص الصوديوم لقاء إطراح البوتاسيوم والبروتونات.\",\"en\":\"Aldosterone controls sodium reabsorption in exchange for potassium and proton secretion.\"},{\"tier\":3,\"tr\":\"Aldosteronun baskılanması ENaC sodyum girişini ve ROMK potasyum salgısını azaltarak potasyumu tutar ve hiperkalemiye yol açar.\",\"ar\":\"يقلل تثبيط الألدوستيرون دخول الصوديوم عبر ENaC وإفراز البوتاسيوم عبر ROMK، حابساً البوتاسيوم ومسبباً فرط البوتاسيوم.\",\"en\":\"Suppressing aldosterone reduces ENaC sodium entry and ROMK potassium secretion in principal cells, causing hyperkalemia.\"}],\"widgetType\":\"MultipleChoice\",\"conceptCheck\":{\"question\":{\"tr\":\"RAAS blokerleri aldosteron salgısını baskıladığında hiperkalemi mekanizması nasıl işler?\",\"ar\":\"كيف تحدث آلية فرط البوتاسيوم عند تثبيط إفراز الألدوستيرون بحاصرات RAAS؟\",\"en\":\"What is the molecular mechanism of hyperkalemia resulting from RAAS inhibitor-mediated aldosterone suppression?\"},\"options\":[{\"id\":\"opt-l9-s6-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Aldosteron normalde toplayıcı kanallarda bazolateral Na+/K+-ATPazı, apikal ENaC ve ROMK'yi artırır; aldosteron kaybı potasyum atılımını bozar.\",\"ar\":\"ينشط الألدوستيرون عادة مضخة Na+/K+ وقنوات ENaC و ROMK في الأنابيب الجامعة؛ ويؤدي فقده لتعطيل إطراح البوتاسيوم.\",\"en\":\"Aldosterone normally upregulates basolateral Na+/K+-ATPase and apical ENaC and ROMK in cortical collecting ducts; losing aldosterone impairs potassium excretion.\"},\"feedback\":{\"tr\":\"Doğru. Aldosteron esas hücrelerde ENaC ve ROMK ile sodyumu tutup potasyumu attırır. Aldosteron düşünce potasyum atılamaz ve hiperkalemi riski doğar.\",\"ar\":\"صحيح. يقود الألدوستيرون امتصاص الصوديوم وإطراح البوتاسيوم عبر ENaC و ROMK. يؤدي تثبيطه لتقليص إفراز البوتاسيوم وخطر فرط البوتاسيوم.\",\"en\":\"Correct. Aldosterone drives principal cell sodium reabsorption and potassium excretion. Suppressing it impairs kaliuresis, predisposing to hyperkalemia.\"}},{\"id\":\"opt-l9-s6-2\",\"isCorrect\":false,\"text\":{\"tr\":\"ACE inhibitörleri proksimal tübüler potasyum simportörlerini doğrudan aktive ederek filtrelenen potasyumun %100'ünü geri emer.\",\"ar\":\"تنشط مثبطات ACE نواقل البوتاسيوم في الأنابيب القريبة مباشرة، معيدة امتصاص 100% من البوتاسيوم للدم.\",\"en\":\"ACE inhibitors directly activate proximal tubular potassium symporters, forcing 100% of filtered potassium back into systemic circulation.\"},\"feedback\":{\"tr\":\"Yanlış. ACE inhibitörleri tübüler taşıyıcıları doğrudan uyarmaz; hiperkalemi aldosteron eksikliğine bağlı endokrin bir sonuçtur.\",\"ar\":\"غير صحيح. لا تنشط مثبطات ACE نواقل الأنابيب مباشرة؛ بل فرط البوتاسيوم نتيجة صماوية لنقص الألدوستيرون.\",\"en\":\"Incorrect. ACE inhibitors have no direct transport-activating properties in tubules; hyperkalemia is an endocrine consequence of aldosterone suppression.\"}},{\"id\":\"opt-l9-s6-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Ang II'nin bloke edilmesi sistemik asidoza yol açarak alyuvarların hücre içi potasyumunu plazmaya boşaltmasına neden olur.\",\"ar\":\"يؤدي حصر Ang II لحماض جهازي يجبر كريات الدم الحمراء على ضخ البوتاسيوم الداخلي إلى البلازما.\",\"en\":\"Blocking Ang II causes systemic acidosis, which forces red blood cells to dump intracellular potassium into plasma.\"},\"feedback\":{\"tr\":\"Yanlış. Hiperkalemi transselüler kaymadan değil, toplayıcı kanallarda aldosteron eksikliğine bağlı böbrek atılım yetersizliğinden kaynaklanır.\",\"ar\":\"غير صحيح. لا ينجم فرط البوتاسيوم عن انزياح عبر الخلايا، بل عن نقص الإطراح الكلوي في الأنابيب الجامعة بسبب عوز الألدوستيرون.\",\"en\":\"Incorrect. Hyperkalemia is driven by reduced renal excretion in collecting ducts via aldosterone deficiency, not transcellular shifting.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-l9-s6-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Aldosteron normalde toplayıcı kanallarda bazolateral Na+/K+-ATPazı, apikal ENaC ve ROMK'yi artırır; aldosteron kaybı potasyum atılımını bozar.\",\"ar\":\"ينشط الألدوستيرون عادة مضخة Na+/K+ وقنوات ENaC و ROMK في الأنابيب الجامعة؛ ويؤدي فقده لتعطيل إطراح البوتاسيوم.\",\"en\":\"Aldosterone normally upregulates basolateral Na+/K+-ATPase and apical ENaC and ROMK in cortical collecting ducts; losing aldosterone impairs potassium excretion.\"},\"feedback\":{\"tr\":\"Doğru. Aldosteron esas hücrelerde ENaC ve ROMK ile sodyumu tutup potasyumu attırır. Aldosteron düşünce potasyum atılamaz ve hiperkalemi riski doğar.\",\"ar\":\"صحيح. يقود الألدوستيرون امتصاص الصوديوم وإطراح البوتاسيوم عبر ENaC و ROMK. يؤدي تثبيطه لتقليص إفراز البوتاسيوم وخطر فرط البوتاسيوم.\",\"en\":\"Correct. Aldosterone drives principal cell sodium reabsorption and potassium excretion. Suppressing it impairs kaliuresis, predisposing to hyperkalemia.\"}},{\"id\":\"opt-l9-s6-2\",\"isCorrect\":false,\"text\":{\"tr\":\"ACE inhibitörleri proksimal tübüler potasyum simportörlerini doğrudan aktive ederek filtrelenen potasyumun %100'ünü geri emer.\",\"ar\":\"تنشط مثبطات ACE نواقل البوتاسيوم في الأنابيب القريبة مباشرة، معيدة امتصاص 100% من البوتاسيوم للدم.\",\"en\":\"ACE inhibitors directly activate proximal tubular potassium symporters, forcing 100% of filtered potassium back into systemic circulation.\"},\"feedback\":{\"tr\":\"Yanlış. ACE inhibitörleri tübüler taşıyıcıları doğrudan uyarmaz; hiperkalemi aldosteron eksikliğine bağlı endokrin bir sonuçtur.\",\"ar\":\"غير صحيح. لا تنشط مثبطات ACE نواقل الأنابيب مباشرة؛ بل فرط البوتاسيوم نتيجة صماوية لنقص الألدوستيرون.\",\"en\":\"Incorrect. ACE inhibitors have no direct transport-activating properties in tubules; hyperkalemia is an endocrine consequence of aldosterone suppression.\"}},{\"id\":\"opt-l9-s6-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Ang II'nin bloke edilmesi sistemik asidoza yol açarak alyuvarların hücre içi potasyumunu plazmaya boşaltmasına neden olur.\",\"ar\":\"يؤدي حصر Ang II لحماض جهازي يجبر كريات الدم الحمراء على ضخ البوتاسيوم الداخلي إلى البلازما.\",\"en\":\"Blocking Ang II causes systemic acidosis, which forces red blood cells to dump intracellular potassium into plasma.\"},\"feedback\":{\"tr\":\"Yanlış. Hiperkalemi transselüler kaymadan değil, toplayıcı kanallarda aldosteron eksikliğine bağlı böbrek atılım yetersizliğinden kaynaklanır.\",\"ar\":\"غير صحيح. لا ينجم فرط البوتاسيوم عن انزياح عبر الخلايا، بل عن نقص الإطراح الكلوي في الأنابيب الجامعة بسبب عوز الألدوستيرون.\",\"en\":\"Incorrect. Hyperkalemia is driven by reduced renal excretion in collecting ducts via aldosterone deficiency, not transcellular shifting.\"}}],\"prompt\":{\"tr\":\"Anjiyotensin II, adrenal zona glomerulosa hücrelerini aldosteron salgılaması için uyarır. Bir ACEi veya ARB bu uyarıyı kestiğinde serum potasyumu neden yükselir?\",\"ar\":\"يحفز أنجيوتنسين II قشر الكظر لإفراز الألدوستيرون. حين يقطع مثبط ACE أو ARB هذا التنبيه، لماذا يرتفع بوتاسيوم المصل؟\",\"en\":\"Angiotensin II stimulates adrenal cortical zona glomerulosa cells to secrete aldosterone. When an ACEi or ARB shuts down this stimulus, why does serum potassium rise?\"},\"title\":{\"tr\":\"Rehberli Keşif: Aldosteron Baskılanması ve Potasyum Tutulumu\",\"ar\":\"استكشاف موجه: تثبيط الألدوستيرون واحتباس البوتاسيوم\",\"en\":\"Guided Discovery: Aldosterone Suppression & Potassium Balance\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":8}]},{\"id\":\"pharm-mod5-les1-step7\",\"order\":7,\"stageIndex\":7,\"stage\":\"formal_explanation\",\"type\":\"question\",\"title\":{\"tr\":\"Biçimsel Açıklama: RAAS İnhibitörlerinin Sınıflandırılması ve Farmakokinetiği\",\"ar\":\"شرح رسمي: تصنيف مثبطات RAAS وحركيتها الدوائية\",\"en\":\"Formal Explanation: Classification & Pharmacokinetics of RAAS Inhibitors\"},\"prompt\":{\"tr\":\"Çoğu ACE inhibitörü (enalapril, ramipril) ester ön-ilaç iken, kaptopril ve lisinopril aktif ana moleküllerdir. Lisinoprili diğerlerinden ayıran farmakokinetik özellik nedir?\",\"ar\":\"معظم مثبطات ACE (إنالابريل، رام Pres pril) طلائع أدوية إسترية، بينما ليزينوبريل وكابتوبريل نشطان بذاتهما. ما الخاصية الحركية المميزة لـ ليزينوبريل؟\",\"en\":\"Most ACE inhibitors (enalapril, ramipril, fosinopril) are ester prodrugs, whereas captopril and lisinopril are active parent drugs. What pharmacokinetic property differentiates lisinopril?\"},\"technicalTerms\":[{\"term\":\"efferent arteriyol\",\"arContext\":\"الشريين الصادر (efferent arteriole)\"},{\"term\":\"glomerüler filtrasyon hızı\",\"arContext\":\"معدل الترشيح الكبيبي (glomerular filtration rate - GFR)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Ön-ilaçlar (enalaprilden enalaprilata) ile doğrudan aktif suda çözünür ilaçları kıyaslayın.\",\"ar\":\"قارن بين طلائع الأدوية الإسترية وتلك النشطة بذاتها الذوابة في الماء.\",\"en\":\"Compare ester prodrugs with water-soluble active drugs.\"},{\"tier\":2,\"tr\":\"Kimyasal adına dikkat edin: 'lisinopril' lizin amino asidi taşır ve hidrofiliktir.\",\"ar\":\"انتبه للاسم الكيميائي: يحتوي 'ليزينوبريل' على الحمض الأميني ليسين وهو محب للماء.\",\"en\":\"Notice the chemical name: 'lisinopril' incorporates the amino acid lysine.\"},{\"tier\":3,\"tr\":\"Lisinopril aktiftir, karaciğerde esteraz yıkımına ihtiyaç duymaz ve böbrek filtrasyonu ile değişmeden atılır.\",\"ar\":\"ليزينوبريل نشط كما هو، لا يحتاج شطراً إسترياً كبدياً، ويطرح دون تغيير بالترشيح الكلوي.\",\"en\":\"Lisinopril is active as administered, hydrophilic, requires no hepatic esterase bioactivation, and is eliminated unchanged by the kidneys.\"}],\"widgetType\":\"MultipleChoice\",\"conceptCheck\":{\"question\":{\"tr\":\"Lisinoprilin farmakokinetik ve metabolik profili diğer ACE inhibitörlerinden nasıl ayrılır?\",\"ar\":\"كيف يتميز المظهر الحركي والاستقلابي لـ ليزينوبريل عن بقية مثبطات ACE؟\",\"en\":\"How does lisinopril's pharmacokinetic profile diverge from most other ACE inhibitors?\"},\"options\":[{\"id\":\"opt-l9-s7-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Lisinopril sentetik bir lizin analoğudur; hidrofiliktir, karaciğerde biyoaktivasyona ihtiyaç duymaz ve böbreklerden değişmeden atılır.\",\"ar\":\"ليزينوبريل نظير مصنع لليسين؛ وهو محب للماء، ويطرح دون تغيير كلياً عبر الكلى دون حاجة لتنشيط كبدي.\",\"en\":\"Lisinopril is a synthetic lysine analogue; it is hydrophilic, excreted entirely unchanged by the kidneys, and requires no hepatic bioactivation.\"},\"feedback\":{\"tr\":\"Doğru. Lisinopril bazik bir lizin grubu taşır; ester hidrolizi olmadan doğrudan aktiftir ve karaciğer metabolizmasına uğramadan böbreklerle atılır.\",\"ar\":\"صحيح. يحتوي ليزينوبريل على ليسين قاعدي؛ وهو نشط دون حلمهة إسترية ويطرح كلوياً دون استقلاب كبدي.\",\"en\":\"Correct. Lisinopril contains a lysine moiety that allows active binding without ester hydrolysis; it is eliminated unchanged by renal excretion.\"}},{\"id\":\"opt-l9-s7-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Lisinopril, aktif dikarboksilik asit metabolitini oluşturmak için karaciğer CYP3A4 ile kapsamlı faz I oksidasyonuna ihtiyaç duyar.\",\"ar\":\"يتطلب ليزينوبريل أكسدة واسعة عبر CYP3A4 الكبدي لتوليد مستقلب حمض ثنائي الكربوكسيل النشط.\",\"en\":\"Lisinopril requires extensive phase I oxidation by hepatic CYP3A4 to generate its active dicarboxylic acid metabolite.\"},\"feedback\":{\"tr\":\"Yanlış. Lisinopril ön-ilaç değildir ve karaciğerde CYP metabolizmasına uğramaz; doğrudan aktif ana ilaçtır.\",\"ar\":\"غير صحيح. ليزينوبريل ليس طليعة دواء ولا يخضع لأي استقلاب كبدي بإنزيمات CYP؛ بل هو دواء نشط بذاته.\",\"en\":\"Incorrect. Lisinopril is not a prodrug and undergoes no hepatic CYP metabolism; it is active as parent drug.\"}},{\"id\":\"opt-l9-s7-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Kaptopril ve lisinopril %100 biliyer yolla atılır, bu da onları böbrek yetmezliğinde birikmeye karşı tamamen korur.\",\"ar\":\"يطرح كابتوبريل وليزينوبريل بنسبة 100% عبر الصفراء، مما يمنع تراكمهما تماماً في الفشل الكلوي.\",\"en\":\"Captopril and lisinopril undergo 100% biliary excretion, making them completely immune to renal failure accumulation.\"},\"feedback\":{\"tr\":\"Yanlış. Lisinopril ve kaptopril renal yolla atılır; böbrek yetmezliğinde birikmeyi önlemek için dozları azaltılmalıdır.\",\"ar\":\"غير صحيح. يعتمد ليزينوبريل وكابتوبريل على الإطراح الكلوي؛ ويجب خفض جرعتهما في القصور الكلوي تجنباً للتراكم.\",\"en\":\"Incorrect. Lisinopril and captopril rely heavily on renal elimination; doses must be adjusted downward in kidney disease.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-l9-s7-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Lisinopril sentetik bir lizin analoğudur; hidrofiliktir, karaciğerde biyoaktivasyona ihtiyaç duymaz ve böbreklerden değişmeden atılır.\",\"ar\":\"ليزينوبريل نظير مصنع لليسين؛ وهو محب للماء، ويطرح دون تغيير كلياً عبر الكلى دون حاجة لتنشيط كبدي.\",\"en\":\"Lisinopril is a synthetic lysine analogue; it is hydrophilic, excreted entirely unchanged by the kidneys, and requires no hepatic bioactivation.\"},\"feedback\":{\"tr\":\"Doğru. Lisinopril bazik bir lizin grubu taşır; ester hidrolizi olmadan doğrudan aktiftir ve karaciğer metabolizmasına uğramadan böbreklerle atılır.\",\"ar\":\"صحيح. يحتوي ليزينوبريل على ليسين قاعدي؛ وهو نشط دون حلمهة إسترية ويطرح كلوياً دون استقلاب كبدي.\",\"en\":\"Correct. Lisinopril contains a lysine moiety that allows active binding without ester hydrolysis; it is eliminated unchanged by renal excretion.\"}},{\"id\":\"opt-l9-s7-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Lisinopril, aktif dikarboksilik asit metabolitini oluşturmak için karaciğer CYP3A4 ile kapsamlı faz I oksidasyonuna ihtiyaç duyar.\",\"ar\":\"يتطلب ليزينوبريل أكسدة واسعة عبر CYP3A4 الكبدي لتوليد مستقلب حمض ثنائي الكربوكسيل النشط.\",\"en\":\"Lisinopril requires extensive phase I oxidation by hepatic CYP3A4 to generate its active dicarboxylic acid metabolite.\"},\"feedback\":{\"tr\":\"Yanlış. Lisinopril ön-ilaç değildir ve karaciğerde CYP metabolizmasına uğramaz; doğrudan aktif ana ilaçtır.\",\"ar\":\"غير صحيح. ليزينوبريل ليس طليعة دواء ولا يخضع لأي استقلاب كبدي بإنزيمات CYP؛ بل هو دواء نشط بذاته.\",\"en\":\"Incorrect. Lisinopril is not a prodrug and undergoes no hepatic CYP metabolism; it is active as parent drug.\"}},{\"id\":\"opt-l9-s7-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Kaptopril ve lisinopril %100 biliyer yolla atılır, bu da onları böbrek yetmezliğinde birikmeye karşı tamamen korur.\",\"ar\":\"يطرح كابتوبريل وليزينوبريل بنسبة 100% عبر الصفراء، مما يمنع تراكمهما تماماً في الفشل الكلوي.\",\"en\":\"Captopril and lisinopril undergo 100% biliary excretion, making them completely immune to renal failure accumulation.\"},\"feedback\":{\"tr\":\"Yanlış. Lisinopril ve kaptopril renal yolla atılır; böbrek yetmezliğinde birikmeyi önlemek için dozları azaltılmalıdır.\",\"ar\":\"غير صحيح. يعتمد ليزينوبريل وكابتوبريل على الإطراح الكلوي؛ ويجب خفض جرعتهما في القصور الكلوي تجنباً للتراكم.\",\"en\":\"Incorrect. Lisinopril and captopril rely heavily on renal elimination; doses must be adjusted downward in kidney disease.\"}}],\"prompt\":{\"tr\":\"Çoğu ACE inhibitörü (enalapril, ramipril) ester ön-ilaç iken, kaptopril ve lisinopril aktif ana moleküllerdir. Lisinoprili diğerlerinden ayıran farmakokinetik özellik nedir?\",\"ar\":\"معظم مثبطات ACE (إنالابريل، رام Pres pril) طلائع أدوية إسترية، بينما ليزينوبريل وكابتوبريل نشطان بذاتهما. ما الخاصية الحركية المميزة لـ ليزينوبريل؟\",\"en\":\"Most ACE inhibitors (enalapril, ramipril, fosinopril) are ester prodrugs, whereas captopril and lisinopril are active parent drugs. What pharmacokinetic property differentiates lisinopril?\"},\"title\":{\"tr\":\"Biçimsel Açıklama: RAAS İnhibitörlerinin Sınıflandırılması ve Farmakokinetiği\",\"ar\":\"شرح رسمي: تصنيف مثبطات RAAS وحركيتها الدوائية\",\"en\":\"Formal Explanation: Classification & Pharmacokinetics of RAAS Inhibitors\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":9}]},{\"id\":\"pharm-mod5-les1-step8\",\"order\":8,\"stageIndex\":8,\"stage\":\"concept_check\",\"type\":\"question\",\"title\":{\"tr\":\"Kavram Kontrolü: Bilateral Renal Arter Stenozunda Akut Yetmezlik\",\"ar\":\"تحقق مفاهيمي: الفشل الحاد في تضيق الشريان الكلوي ثنائي الجانب\",\"en\":\"Concept Check: Bilateral Renal Artery Stenosis Disaster\"},\"prompt\":{\"tr\":\"Şiddetli bilateral renal arter stenozu olan hastaya lisinopril başlanıyor. 48 saat içinde serum kreatinini 1.1'den 4.2 mg/dL'ye fırlıyor. Akut böbrek yetmezliğine hangi hemodinamik mekanizma yol açtı?\",\"ar\":\"بدأ مريض بتضيق شريان كلوي ثنائي الجانب ليزينوبريل. وخلال 48 ساعة، قفز الكرياتينين من 1.1 إلى 4.2 ملغ/دل. ما الآلية الديناميكية الدموية المسببة للفشل؟\",\"en\":\"A patient with severe bilateral renal artery stenosis is started on lisinopril. Within 48 hours, serum creatinine spikes from 1.1 to 4.2 mg/dL. What hemodynamic mechanism caused acute renal failure?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Bilateral renal arter stenozunda ACE inhibitörleri neden akut böbrek yetmezliği yapar?\",\"ar\":\"لماذا تسبب مثبطات ACE فشلاً كلوياً حاداً في تضيق الشريان الكلوي ثنائي الجانب؟\",\"en\":\"Why do ACE inhibitors precipitate acute renal failure in bilateral renal artery stenosis?\"},\"options\":[{\"id\":\"opt-l9-s8-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Stenoz afferent perfüzyon basıncını düşürür; GFR tamamen Ang II bağımlı efferent vazokonstriksiyonla korunuyordu. ACEi efferent direnci sıfırlayarak glomerüler filtrasyonu çökertti.\",\"ar\":\"يخفض التضيق ضغط التروية الوارد؛ وكان GFR يعتمد كلياً على تضيق الشريان الصادر بـ Ang II. أدى حصر ACE لإلغاء المقاومة الصادرة وانهيار الرشح.\",\"en\":\"Stenosis lowers afferent perfusion pressure; GFR was maintained entirely by Ang II-mediated efferent vasoconstriction. ACE inhibition abolishes efferent resistance, collapsing glomerular filtration.\"},\"feedback\":{\"tr\":\"Doğru. Stenozda intraglomerüler basınç yalnızca Ang II'nin efferent arteriyolü kasmasıyla korunur. ACEi bu tonusu silince intraglomerüler basınç çöker ve GFR sıfırlanır.\",\"ar\":\"صحيح. يصان الضغط داخل الكبيبة في التضيق حصراً بانقباض الشريان الصادر بـ Ang II. إلغاء هذه المقاومة بمثبطات ACE يسقط الضغط الهيدروستاتيكي ويوقف الرشح.\",\"en\":\"Correct. In bilateral stenosis, GFR is critically dependent on Ang II-mediated efferent tone. Blocking Ang II collapses glomerular hydrostatic pressure and GFR.\"}},{\"id\":\"opt-l9-s8-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Lisinopril proksimal tübülde çözünmeyen kalsiyum fosfat kristalleri halinde çökerek mekanik obstrüktif üropatiye yol açar.\",\"ar\":\"يترسب ليزينوبريل كبلورات فوسفات كالسيوم غير ذوابة في الأنابيب القريبة، مسبباً اعتلالاً بولياً انسدادياً ميكانيكياً.\",\"en\":\"Lisinopril precipitates as insoluble calcium phosphate crystals within the proximal tubule, causing mechanical obstructive uropathy.\"},\"feedback\":{\"tr\":\"Yanlış. Kreatinin artışı kristal nefropatisinden değil, tamamen fonksiyonel hemodinamik filtrasyon çöküşünden kaynaklanır.\",\"ar\":\"غير صحيح. ارتفاع الكرياتينين وظيفي ديناميكي دموي وليس اعتلالاً بلورياً؛ وسحب الدواء يعيد المقوية الصادرة والرشح.\",\"en\":\"Incorrect. The acute creatinine jump is functional and hemodynamic (pre-renal), not crystal nephropathy.\"}},{\"id\":\"opt-l9-s8-3\",\"isCorrect\":false,\"text\":{\"tr\":\"İlaç, böbrek podositlerinin %90'ını hızla yok eden akut bir immün kompleks glomerülonefritini tetikler.\",\"ar\":\"يحفز الدواء التهاب كبيبات مناعياً معقداً حاداً يدمر 90% من الخلايا الرجلاء الكلوية بسرعة.\",\"en\":\"The drug triggers an acute immune-complex glomerulonephritis that rapidly destroys 90% of renal podocytes.\"},\"feedback\":{\"tr\":\"Yanlış. İmmün kompleks yıkımı yoktur; yetmezlik efferent arteriyol gevşemesine bağlı intraglomerüler basınç kaybıdır.\",\"ar\":\"غير صحيح. لا يوجد تخريب مناعي معقد؛ بل الفشل ناجم حصراً عن فقدان الضغط الهيدروستاتيكي بتوسع الشريان الصادر.\",\"en\":\"Incorrect. There is no immune-complex pathology. The failure is entirely hemodynamic due to loss of efferent arteriolar vasoconstriction.\"}}]},\"technicalTerms\":[{\"term\":\"renal arter stenozu\",\"arContext\":\"تضيق الشريان الكلوي (renal artery stenosis)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Renal mikrovasküler otoregülasyonu hatırlayın: afferent giriş ve efferent çıkış dengesi.\",\"ar\":\"تذكر التنظيم الذاتي الوعائي الكلوي: توازن المدخل الوارد والمخرج الصادر.\",\"en\":\"Recall renal microvascular autoregulation: afferent inlet versus efferent outlet balance.\"},{\"tier\":2,\"tr\":\"Renal arter stenozu giriş basıncını düşürdüğünde, böbrek GFR'yi korumak için hangi damarı kısmıştı?\",\"ar\":\"حين يخفض تضيق الشريان ضغط الدخول، أي وعاء كان مقبوضاً لصيانة الرشح قبل الدواء؟\",\"en\":\"When stenosis drops inlet pressure, which vessel was constricted by Ang II to sustain GFR?\"},{\"tier\":3,\"tr\":\"Böbrek GFR'yi Ang II bağımlı efferent vazokonstriksiyonla sürdürüyordu. ACEi efferent çıkışı gevşetince intraglomerüler hidrostatik basınç ve filtrasyon çöker.\",\"ar\":\"كان الرشح يعتمد كلياً على تضيق الشريان الصادر بـ Ang II. أدى حصر ACE لإرخاء المخرج وانهيار الضغط والرشح.\",\"en\":\"Filtration was sustained solely by Ang II-mediated efferent constriction. ACEi dilates the efferent arteriole, collapsing intraglomerular pressure and GFR.\"}],\"widgetType\":\"MultipleChoice\",\"config\":{\"options\":[{\"id\":\"opt-l9-s8-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Stenoz afferent perfüzyon basıncını düşürür; GFR tamamen Ang II bağımlı efferent vazokonstriksiyonla korunuyordu. ACEi efferent direnci sıfırlayarak glomerüler filtrasyonu çökertti.\",\"ar\":\"يخفض التضيق ضغط التروية الوارد؛ وكان GFR يعتمد كلياً على تضيق الشريان الصادر بـ Ang II. أدى حصر ACE لإلغاء المقاومة الصادرة وانهيار الرشح.\",\"en\":\"Stenosis lowers afferent perfusion pressure; GFR was maintained entirely by Ang II-mediated efferent vasoconstriction. ACE inhibition abolishes efferent resistance, collapsing glomerular filtration.\"},\"feedback\":{\"tr\":\"Doğru. Stenozda intraglomerüler basınç yalnızca Ang II'nin efferent arteriyolü kasmasıyla korunur. ACEi bu tonusu silince intraglomerüler basınç çöker ve GFR sıfırlanır.\",\"ar\":\"صحيح. يصان الضغط داخل الكبيبة في التضيق حصراً بانقباض الشريان الصادر بـ Ang II. إلغاء هذه المقاومة بمثبطات ACE يسقط الضغط الهيدروستاتيكي ويوقف الرشح.\",\"en\":\"Correct. In bilateral stenosis, GFR is critically dependent on Ang II-mediated efferent tone. Blocking Ang II collapses glomerular hydrostatic pressure and GFR.\"}},{\"id\":\"opt-l9-s8-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Lisinopril proksimal tübülde çözünmeyen kalsiyum fosfat kristalleri halinde çökerek mekanik obstrüktif üropatiye yol açar.\",\"ar\":\"يترسب ليزينوبريل كبلورات فوسفات كالسيوم غير ذوابة في الأنابيب القريبة، مسبباً اعتلالاً بولياً انسدادياً ميكانيكياً.\",\"en\":\"Lisinopril precipitates as insoluble calcium phosphate crystals within the proximal tubule, causing mechanical obstructive uropathy.\"},\"feedback\":{\"tr\":\"Yanlış. Kreatinin artışı kristal nefropatisinden değil, tamamen fonksiyonel hemodinamik filtrasyon çöküşünden kaynaklanır.\",\"ar\":\"غير صحيح. ارتفاع الكرياتينين وظيفي ديناميكي دموي وليس اعتلالاً بلورياً؛ وسحب الدواء يعيد المقوية الصادرة والرشح.\",\"en\":\"Incorrect. The acute creatinine jump is functional and hemodynamic (pre-renal), not crystal nephropathy.\"}},{\"id\":\"opt-l9-s8-3\",\"isCorrect\":false,\"text\":{\"tr\":\"İlaç, böbrek podositlerinin %90'ını hızla yok eden akut bir immün kompleks glomerülonefritini tetikler.\",\"ar\":\"يحفز الدواء التهاب كبيبات مناعياً معقداً حاداً يدمر 90% من الخلايا الرجلاء الكلوية بسرعة.\",\"en\":\"The drug triggers an acute immune-complex glomerulonephritis that rapidly destroys 90% of renal podocytes.\"},\"feedback\":{\"tr\":\"Yanlış. İmmün kompleks yıkımı yoktur; yetmezlik efferent arteriyol gevşemesine bağlı intraglomerüler basınç kaybıdır.\",\"ar\":\"غير صحيح. لا يوجد تخريب مناعي معقد؛ بل الفشل ناجم حصراً عن فقدان الضغط الهيدروستاتيكي بتوسع الشريان الصادر.\",\"en\":\"Incorrect. There is no immune-complex pathology. The failure is entirely hemodynamic due to loss of efferent arteriolar vasoconstriction.\"}}],\"prompt\":{\"tr\":\"Şiddetli bilateral renal arter stenozu olan hastaya lisinopril başlanıyor. 48 saat içinde serum kreatinini 1.1'den 4.2 mg/dL'ye fırlıyor. Akut böbrek yetmezliğine hangi hemodinamik mekanizma yol açtı?\",\"ar\":\"بدأ مريض بتضيق شريان كلوي ثنائي الجانب ليزينوبريل. وخلال 48 ساعة، قفز الكرياتينين من 1.1 إلى 4.2 ملغ/دل. ما الآلية الديناميكية الدموية المسببة للفشل؟\",\"en\":\"A patient with severe bilateral renal artery stenosis is started on lisinopril. Within 48 hours, serum creatinine spikes from 1.1 to 4.2 mg/dL. What hemodynamic mechanism caused acute renal failure?\"},\"title\":{\"tr\":\"Kavram Kontrolü: Bilateral Renal Arter Stenozunda Akut Yetmezlik\",\"ar\":\"تحقق مفاهيمي: الفشل الحاد في تضيق الشريان الكلوي ثنائي الجانب\",\"en\":\"Concept Check: Bilateral Renal Artery Stenosis Disaster\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":10}]},{\"id\":\"pharm-mod5-les1-step9\",\"order\":9,\"stageIndex\":9,\"stage\":\"application\",\"type\":\"question\",\"title\":{\"tr\":\"Klinik Vaka: ARNI Sakubitril/Valsartan 36 Saatlik Arınma Kuralı\",\"ar\":\"حالة سريرية: قاعدة غسيل 36 ساعة لـ ARNI ساكوبيتريل/فالسارتان\",\"en\":\"Clinical Vignette: ARNI Sacubitril/Valsartan 36-Hour Washout Trap\"},\"prompt\":{\"tr\":\"Enalapril kullanan bir kalp yetmezliği hastası sakubitril/valsartana (ARNI) geçiriliyor. İlk ARNI dozundan önce neden kesin olarak 36 saatlik bir arınma (washout) süresi zorunludur?\",\"ar\":\"مريض قصور قلب يعالج بإنالابريل تقرر تحويله إلى ساكوبيتريل/فالسارتان (ARNI). لماذا يعد فاصل الغسيل الدوائي الإلزامي لمدة 36 ساعة حاسماً قبل أول جرعة؟\",\"en\":\"A heart failure patient receiving enalapril is transitioned to sacubitril/valsartan (ARNI). Why is a strict 36-hour washout mandatory before taking the first ARNI dose?\"},\"conceptCheck\":{\"question\":{\"tr\":\"ACE inhibitöründen ARNI'ye geçerken 36 saatlik bekleme süresine uyulmazsa hangi ölümcül risk doğar?\",\"ar\":\"ما الخطر المميت الناجم عن عدم الالتزام بفاصل 36 ساعة عند التحول من ACEi إلى ARNI؟\",\"en\":\"What fatal risk emerges if the 36-hour washout period is violated when switching from an ACEi to an ARNI?\"},\"options\":[{\"id\":\"opt-l9-s9-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Hem neprilisin hem ACE bradikinini parçalar; eş zamanlı inhibisyon sinerjistik bradikinin birikimine yol açarak ölümcül anjioödem riskini katlar.\",\"ar\":\"يفكك كل من النبريلايسين و ACE البراديكينين؛ ويؤدي تثبيطهما المتزامن لتراكم تآزري هائل للبراديكينين مسبباً خطراً مميتاً للوذمة الوعائية.\",\"en\":\"Neprilysin and ACE both degrade bradykinin; concurrent inhibition causes synergistic bradykinin accumulation, massively escalating the risk of fatal angioedema.\"},\"feedback\":{\"tr\":\"Doğru. Hem ACE hem neprilisin bradikinini yıkar. İkisi aynı anda kilitlenirse bradikinin katlanarak birikir ve asfiksiye yol açan laringeal anjioödem gelişir.\",\"ar\":\"صحيح. يفكك كل من ACE والنبريلايسين البراديكينين. حصر كلاهما في آن واحد يراكم البراديكينين بشكل تآزري مفجراً وذمة حنجرية خانقة.\",\"en\":\"Correct. Both ACE and neprilysin degrade bradykinin. Concurrent dual blockade leads to massive bradykinin accumulation and life-threatening laryngeal angioedema.\"}},{\"id\":\"opt-l9-s9-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Valsartan enalaprili albümin bağlanma bölgelerinden kovarak serbest enalaprili 50 kat artırır ve şiddetli postural hipotansiyon yapar.\",\"ar\":\"يزيح فالسارتان إنالابريل من مواقع الارتباط بالألبومين، رافعاً شكله الحر 50 ضعفاً ومسبباً هبوط ضغط انتصابي شديد.\",\"en\":\"Valsartan displaces enalapril from albumin binding sites, increasing free enalapril 50-fold and causing severe postural hypotension.\"},\"feedback\":{\"tr\":\"Yanlış. Tehlike albüminden kovulma değildir; iki büyük bradikinin yıkım yolunun aynı anda durdurulmasıyla gelişen ölümcül anjioödemdir.\",\"ar\":\"غير صحيح. ليس الخطر إزاحة من الألبومين؛ بل التآزر الإنزيمي الكارثي بحصر مساري تفكيك البراديكينين معاً.\",\"en\":\"Incorrect. The danger is not protein displacement; it is the catastrophic enzymatic synergy of blocking two major bradykinin clearance pathways.\"}},{\"id\":\"opt-l9-s9-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Sakubitril proksimal tübüler OAT taşıyıcılarını inhibe ederek enalapril atılımını engeller ve ölümcül laktik asidozu tetikler.\",\"ar\":\"يثبط ساكوبيتريل نواقل OAT الأنبوبية القريبة، مانعاً تصريف إنالابريل ومثيراً حماضاً لبنياً مميتاً.\",\"en\":\"Sacubitril inhibits proximal tubular OAT transporters, preventing enalapril clearance and triggering fatal lactic acidosis.\"},\"feedback\":{\"tr\":\"Yanlış. 36 saatlik kuralın tek varlık sebebi bradikinin yıkımının çift taraflı durması ve anjioödem patlamasıdır.\",\"ar\":\"غير صحيح. قاعدة الـ 36 ساعة وُجدت حصراً لتجنب التثبيط المزدوج لتفكيك البراديكينين وانفجار الوذمة الوعائية.\",\"en\":\"Incorrect. The 36-hour washout exists solely due to dual enzymatic inhibition of bradykinin breakdown resulting in fatal angioedema.\"}}]},\"technicalTerms\":[{\"term\":\"anjiyoödem\",\"arContext\":\"الوذمة الوعائية (angioedema)\"},{\"term\":\"neprilisin inhibitörü\",\"arContext\":\"مثبط النبريلايسين (neprilysin inhibitor)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Hem ACE hem de neprilisin enzimleri tarafından parçalanan ortak endojen vazodilatatör peptidi düşünün.\",\"ar\":\"فكر في الببتيد الموسع للأوعية الذي يفككه إنزيما ACE والنبريلايسين معاً.\",\"en\":\"Consider what endogenous vasodilator peptide is metabolized by both ACE and neprilysin.\"},{\"tier\":2,\"tr\":\"Bradikinini yıkan iki ana enzimatik yolak aynı anda bloke edilirse ne olur?\",\"ar\":\"ماذا يحدث إذا حصر كلا المسارين الإنزيميين الرئيسيين لتفكيك البراديكينين في آن واحد؟\",\"en\":\"What happens when both major enzymatic pathways for degrading bradykinin are blocked simultaneously?\"},{\"tier\":3,\"tr\":\"Hem ACE hem neprilisin bradikinini yıkar. Eş zamanlı inhibisyon feci bir bradikinin patlaması ve ölümcül laringeal anjioödem yaratır; 36 saatlik arınma şarttır.\",\"ar\":\"يفكك كلاهما البراديكينين. يسبب التثبيط المتزامن انفجاراً في مستويات البراديكينين ووذمة وعائية حنجرية قاتلة؛ لذا يلزم فاصل 36 ساعة.\",\"en\":\"Both ACE and neprilysin degrade bradykinin. Simultaneous inhibition causes explosive bradykinin accumulation and fatal angioedema; a 36-hour washout is mandatory.\"}],\"widgetType\":\"MultipleChoice\",\"config\":{\"options\":[{\"id\":\"opt-l9-s9-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Hem neprilisin hem ACE bradikinini parçalar; eş zamanlı inhibisyon sinerjistik bradikinin birikimine yol açarak ölümcül anjioödem riskini katlar.\",\"ar\":\"يفكك كل من النبريلايسين و ACE البراديكينين؛ ويؤدي تثبيطهما المتزامن لتراكم تآزري هائل للبراديكينين مسبباً خطراً مميتاً للوذمة الوعائية.\",\"en\":\"Neprilysin and ACE both degrade bradykinin; concurrent inhibition causes synergistic bradykinin accumulation, massively escalating the risk of fatal angioedema.\"},\"feedback\":{\"tr\":\"Doğru. Hem ACE hem neprilisin bradikinini yıkar. İkisi aynı anda kilitlenirse bradikinin katlanarak birikir ve asfiksiye yol açan laringeal anjioödem gelişir.\",\"ar\":\"صحيح. يفكك كل من ACE والنبريلايسين البراديكينين. حصر كلاهما في آن واحد يراكم البراديكينين بشكل تآزري مفجراً وذمة حنجرية خانقة.\",\"en\":\"Correct. Both ACE and neprilysin degrade bradykinin. Concurrent dual blockade leads to massive bradykinin accumulation and life-threatening laryngeal angioedema.\"}},{\"id\":\"opt-l9-s9-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Valsartan enalaprili albümin bağlanma bölgelerinden kovarak serbest enalaprili 50 kat artırır ve şiddetli postural hipotansiyon yapar.\",\"ar\":\"يزيح فالسارتان إنالابريل من مواقع الارتباط بالألبومين، رافعاً شكله الحر 50 ضعفاً ومسبباً هبوط ضغط انتصابي شديد.\",\"en\":\"Valsartan displaces enalapril from albumin binding sites, increasing free enalapril 50-fold and causing severe postural hypotension.\"},\"feedback\":{\"tr\":\"Yanlış. Tehlike albüminden kovulma değildir; iki büyük bradikinin yıkım yolunun aynı anda durdurulmasıyla gelişen ölümcül anjioödemdir.\",\"ar\":\"غير صحيح. ليس الخطر إزاحة من الألبومين؛ بل التآزر الإنزيمي الكارثي بحصر مساري تفكيك البراديكينين معاً.\",\"en\":\"Incorrect. The danger is not protein displacement; it is the catastrophic enzymatic synergy of blocking two major bradykinin clearance pathways.\"}},{\"id\":\"opt-l9-s9-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Sakubitril proksimal tübüler OAT taşıyıcılarını inhibe ederek enalapril atılımını engeller ve ölümcül laktik asidozu tetikler.\",\"ar\":\"يثبط ساكوبيتريل نواقل OAT الأنبوبية القريبة، مانعاً تصريف إنالابريل ومثيراً حماضاً لبنياً مميتاً.\",\"en\":\"Sacubitril inhibits proximal tubular OAT transporters, preventing enalapril clearance and triggering fatal lactic acidosis.\"},\"feedback\":{\"tr\":\"Yanlış. 36 saatlik kuralın tek varlık sebebi bradikinin yıkımının çift taraflı durması ve anjioödem patlamasıdır.\",\"ar\":\"غير صحيح. قاعدة الـ 36 ساعة وُجدت حصراً لتجنب التثبيط المزدوج لتفكيك البراديكينين وانفجار الوذمة الوعائية.\",\"en\":\"Incorrect. The 36-hour washout exists solely due to dual enzymatic inhibition of bradykinin breakdown resulting in fatal angioedema.\"}}],\"prompt\":{\"tr\":\"Enalapril kullanan bir kalp yetmezliği hastası sakubitril/valsartana (ARNI) geçiriliyor. İlk ARNI dozundan önce neden kesin olarak 36 saatlik bir arınma (washout) süresi zorunludur?\",\"ar\":\"مريض قصور قلب يعالج بإنالابريل تقرر تحويله إلى ساكوبيتريل/فالسارتان (ARNI). لماذا يعد فاصل الغسيل الدوائي الإلزامي لمدة 36 ساعة حاسماً قبل أول جرعة؟\",\"en\":\"A heart failure patient receiving enalapril is transitioned to sacubitril/valsartan (ARNI). Why is a strict 36-hour washout mandatory before taking the first ARNI dose?\"},\"title\":{\"tr\":\"Klinik Vaka: ARNI Sakubitril/Valsartan 36 Saatlik Arınma Kuralı\",\"ar\":\"حالة سريرية: قاعدة غسيل 36 ساعة لـ ARNI ساكوبيتريل/فالسارتان\",\"en\":\"Clinical Vignette: ARNI Sacubitril/Valsartan 36-Hour Washout Trap\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":11}]},{\"id\":\"pharm-mod5-les1-step10\",\"order\":10,\"stageIndex\":10,\"stage\":\"retrieval\",\"type\":\"question\",\"title\":{\"tr\":\"Geri Çağırma: Gebelikte Teratojenite ve Fötal Renal Disgenez\",\"ar\":\"استرجاع: ماسخية الحمل وخلل تكون الكلى الجنيني\",\"en\":\"Retrieval: Teratogenicity & Fetal Renal Hemodynamics\"},\"prompt\":{\"tr\":\"ACE inhibitörleri ve ARB'ler gebeliğin ikinci ve üçüncü trimesterlerinde neden kesinlikle kontrendikedir? Fötusta hangi spesifik gelişimsel anomaliler ortaya çıkar?\",\"ar\":\"لماذا تمنع مثبطات ACE و ARBs منعاً باتاً خلال الثلثين الثاني والثالث من الحمل؟ ما هي التشوهات الجنينية التطورية النوعية التي تحدث؟\",\"en\":\"Why are ACE inhibitors and ARBs categorically contraindicated across the second and third trimesters of pregnancy? What specific fetal developmental abnormalities occur?\"},\"technicalTerms\":[{\"term\":\"teratojenisite\",\"arContext\":\"التشوه الجنيني (teratogenicity)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Gebeliğin son evrelerinde amniyotik sıvının ana kaynağının fötal idrar olduğunu hatırlayın.\",\"ar\":\"تذكر أن البول الجنيني هو المكون الأساسي للسائل السلوي في الثلثين الأخيرين من الحمل.\",\"en\":\"Recall that fetal urine is the primary constituent of amniotic fluid in late pregnancy.\"},{\"tier\":2,\"tr\":\"Fötal böbrekler GFR'yi sürdürmek için Ang II'ye bağımlıdır. Fötus idrar üretemezse ne olur?\",\"ar\":\"تعتمد كلى الجنين على Ang II لصيانة GFR. ماذا يحدث إذا عجز الجنين عن إنتاج البول؟\",\"en\":\"Fetal kidneys depend on Ang II to maintain GFR. What happens if the fetus cannot produce urine?\"},{\"tier\":3,\"tr\":\"Fötal Ang II'nin bloke edilmesi renal disgenez ve anüri yapar; oligohidramniyos, hipoplastik akciğerler (Potter dizisi) ve kafa kemikleşme defektleri gelişir.\",\"ar\":\"يسبب حصر Ang II للجنين خلل تكون كلوي وانقطاع بول؛ مما يؤدي لقلة السلى، ونقص تنسج الرئة (متتالية بوتر)، وعيوب تعظم الجمجمة.\",\"en\":\"Blocking fetal Ang II causes renal dysgenesis and anuria, resulting in oligohydramnios, hypoplastic lungs (Potter sequence), and calvarial skull defects.\"}],\"widgetType\":\"MultipleChoice\",\"conceptCheck\":{\"question\":{\"tr\":\"Gebelikte ACEi/ARB maruziyeti fötusta hangi patolojik sendromu ve anomalileri tetikler?\",\"ar\":\"ما المتلازمة المرضية والتشوهات التي يثيرها تعرض الجنين لـ ACEi/ARB أثناء الحمل؟\",\"en\":\"What pathological sequence and fetal malformations are triggered by in utero ACEi/ARB exposure?\"},\"options\":[{\"id\":\"opt-l9-s10-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Fötal böbrekler perfüzyon ve organogenez için Ang II'ye muhtaçtır; blokaj fötal renal disgenez, oligohidramniyos, pulmoner hipoplazi ve kafa kemikleşme defektleri yapar.\",\"ar\":\"تتطلب كلى الجنين Ang II للتروية والتشكل؛ ويؤدي الحصر لخلل تكون كلوي، وقلة السائل السلوي، ونقص تنسج رئوي، وعيوب تعظم الجمجمة.\",\"en\":\"Fetal kidneys require Ang II for renal perfusion and organogenesis; blockade produces fetal renal dysgenesis, oligohydramnios, pulmonary hypoplasia, and skull ossification defects.\"},\"feedback\":{\"tr\":\"Doğru. Fötal Ang II böbrek perfüzyonu ve GFR için şarttır. Baskılanması anüri ve oligohidramniyos yapar; bu da Potter dizisine (akciğer hipoplazisi, yüz anomalileri) ve kafa hipokalsifikasyonuna yol açar.\",\"ar\":\"صحيح. Ang II حاسم لتروية كلى الجنين ورشحها. يسبب حصره انقطاع البول وقلة السلى، مما يطلق متتالية بوتر (نقص تنسج الرئة) وعيوب تعظم الجمجمة.\",\"en\":\"Correct. Fetal Ang II is essential for renal hemodynamics in utero. Blockade causes anuria, oligohydramnios (Potter sequence: pulmonary hypoplasia), and calvarial skull defects.\"}},{\"id\":\"opt-l9-s10-2\",\"isCorrect\":false,\"text\":{\"tr\":\"ACE inhibitörleri dihidrofolat redüktazı doğrudan inhibe ederek folat depolarını tüketir ve açık nöral tüp defektlerine yol açar.\",\"ar\":\"تثبط مثبطات ACE إنزيم اختزال ثنائي الهيدروفولات مباشرة، مستنزفة مخازن الفولات ومسببة عيوب الأنبوب العصبي المفتوحة.\",\"en\":\"ACE inhibitors directly inhibit dihydrofolate reductase, depleting folate stores and precipitating open neural tube defects.\"},\"feedback\":{\"tr\":\"Yanlış. ACEi folat antagonisti değildir. Teratojeniteleri 1. trimester nöral tüp hasarından değil, 2./3. trimester fötal böbrek hemodinamik çöküşünden doğar.\",\"ar\":\"غير صحيح. ليست مثبطات ACE مضادات للفولات؛ ماسخيتها سمية جنينية في الثلثين 2 و 3 ناجمة عن فشل كلى الجنين وليست عيوب أنبوب عصبي.\",\"en\":\"Incorrect. ACEi are not antifolates. Their teratogenicity is fetotoxic (2nd/3rd trimester renal failure), not 1st-trimester neural tube closure defects.\"}},{\"id\":\"opt-l9-s10-3\",\"isCorrect\":false,\"text\":{\"tr\":\"İlaçlar sereblona bağlanarak ekstremite tomurcuğu anjiyogenezini durdurur ve talidomid benzeri fokomeli oluşturur.\",\"ar\":\"ترتبط الأدوية بالثيريبلون لتثبيط التوعية الدموية لبراعم الأطراف، مسببة فقمية الأطراف المشابهة للثاليدومايد.\",\"en\":\"The drugs bind cereblon to arrest limb bud angiogenesis, producing thalidomide-like phocomelia and amelia.\"},\"feedback\":{\"tr\":\"Yanlış. Sereblon talidomidin hedefidir. ACEi'lerin karakteristik etkisi ekstremite kaybı değil, fötal böbrek disgenezisidir.\",\"ar\":\"غير صحيح. الثيريبلون هدف الثاليدومايد. الأثر المميز لـ ACEi هو خلل تكون الكلى الجنيني وليس بتر الأطراف.\",\"en\":\"Incorrect. Cereblon is the target of thalidomide. ACEi toxicity is characterized by fetal renal dysgenesis and oligohydramnios.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-l9-s10-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Fötal böbrekler perfüzyon ve organogenez için Ang II'ye muhtaçtır; blokaj fötal renal disgenez, oligohidramniyos, pulmoner hipoplazi ve kafa kemikleşme defektleri yapar.\",\"ar\":\"تتطلب كلى الجنين Ang II للتروية والتشكل؛ ويؤدي الحصر لخلل تكون كلوي، وقلة السائل السلوي، ونقص تنسج رئوي، وعيوب تعظم الجمجمة.\",\"en\":\"Fetal kidneys require Ang II for renal perfusion and organogenesis; blockade produces fetal renal dysgenesis, oligohydramnios, pulmonary hypoplasia, and skull ossification defects.\"},\"feedback\":{\"tr\":\"Doğru. Fötal Ang II böbrek perfüzyonu ve GFR için şarttır. Baskılanması anüri ve oligohidramniyos yapar; bu da Potter dizisine (akciğer hipoplazisi, yüz anomalileri) ve kafa hipokalsifikasyonuna yol açar.\",\"ar\":\"صحيح. Ang II حاسم لتروية كلى الجنين ورشحها. يسبب حصره انقطاع البول وقلة السلى، مما يطلق متتالية بوتر (نقص تنسج الرئة) وعيوب تعظم الجمجمة.\",\"en\":\"Correct. Fetal Ang II is essential for renal hemodynamics in utero. Blockade causes anuria, oligohydramnios (Potter sequence: pulmonary hypoplasia), and calvarial skull defects.\"}},{\"id\":\"opt-l9-s10-2\",\"isCorrect\":false,\"text\":{\"tr\":\"ACE inhibitörleri dihidrofolat redüktazı doğrudan inhibe ederek folat depolarını tüketir ve açık nöral tüp defektlerine yol açar.\",\"ar\":\"تثبط مثبطات ACE إنزيم اختزال ثنائي الهيدروفولات مباشرة، مستنزفة مخازن الفولات ومسببة عيوب الأنبوب العصبي المفتوحة.\",\"en\":\"ACE inhibitors directly inhibit dihydrofolate reductase, depleting folate stores and precipitating open neural tube defects.\"},\"feedback\":{\"tr\":\"Yanlış. ACEi folat antagonisti değildir. Teratojeniteleri 1. trimester nöral tüp hasarından değil, 2./3. trimester fötal böbrek hemodinamik çöküşünden doğar.\",\"ar\":\"غير صحيح. ليست مثبطات ACE مضادات للفولات؛ ماسخيتها سمية جنينية في الثلثين 2 و 3 ناجمة عن فشل كلى الجنين وليست عيوب أنبوب عصبي.\",\"en\":\"Incorrect. ACEi are not antifolates. Their teratogenicity is fetotoxic (2nd/3rd trimester renal failure), not 1st-trimester neural tube closure defects.\"}},{\"id\":\"opt-l9-s10-3\",\"isCorrect\":false,\"text\":{\"tr\":\"İlaçlar sereblona bağlanarak ekstremite tomurcuğu anjiyogenezini durdurur ve talidomid benzeri fokomeli oluşturur.\",\"ar\":\"ترتبط الأدوية بالثيريبلون لتثبيط التوعية الدموية لبراعم الأطراف، مسببة فقمية الأطراف المشابهة للثاليدومايد.\",\"en\":\"The drugs bind cereblon to arrest limb bud angiogenesis, producing thalidomide-like phocomelia and amelia.\"},\"feedback\":{\"tr\":\"Yanlış. Sereblon talidomidin hedefidir. ACEi'lerin karakteristik etkisi ekstremite kaybı değil, fötal böbrek disgenezisidir.\",\"ar\":\"غير صحيح. الثيريبلون هدف الثاليدومايد. الأثر المميز لـ ACEi هو خلل تكون الكلى الجنيني وليس بتر الأطراف.\",\"en\":\"Incorrect. Cereblon is the target of thalidomide. ACEi toxicity is characterized by fetal renal dysgenesis and oligohydramnios.\"}}],\"prompt\":{\"tr\":\"ACE inhibitörleri ve ARB'ler gebeliğin ikinci ve üçüncü trimesterlerinde neden kesinlikle kontrendikedir? Fötusta hangi spesifik gelişimsel anomaliler ortaya çıkar?\",\"ar\":\"لماذا تمنع مثبطات ACE و ARBs منعاً باتاً خلال الثلثين الثاني والثالث من الحمل؟ ما هي التشوهات الجنينية التطورية النوعية التي تحدث؟\",\"en\":\"Why are ACE inhibitors and ARBs categorically contraindicated across the second and third trimesters of pregnancy? What specific fetal developmental abnormalities occur?\"},\"title\":{\"tr\":\"Geri Çağırma: Gebelikte Teratojenite ve Fötal Renal Disgenez\",\"ar\":\"استرجاع: ماسخية الحمل وخلل تكون الكلى الجنيني\",\"en\":\"Retrieval: Teratogenicity & Fetal Renal Hemodynamics\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":12}]},{\"id\":\"pharm-mod5-les1-step11\",\"order\":11,\"stageIndex\":11,\"stage\":\"connection\",\"type\":\"question\",\"title\":{\"tr\":\"Bütünsel Bağlantı: Direkt Renin İnhibitörleri ve Geri Bildirim Döngüleri\",\"ar\":\"ترابط شمولي: مثبطات الرينين المباشرة وحلقات التلقيم الراجع\",\"en\":\"Holistic Connection: Direct Renin Inhibitors & RAAS Feedback Loops\"},\"prompt\":{\"tr\":\"Direkt renin inhibitörü aliskirenin farmakolojik profili, Plazma Renin Aktivitesi (PRA) ve Plazma Renin Konsantrasyonu (PRC) açısından ACE inhibitörleri ve ARB'lerden nasıl ayrılır?\",\"ar\":\"كيف يختلف المظهر الدوائي لمثبط الرينين المباشر أليسكيرين عن مثبطات ACE و ARBs فيما يخص نشاط الرينين في البلازما (PRA) مقابل تركيز الرينين (PRC)؟\",\"en\":\"How does the pharmacological profile of the direct renin inhibitor aliskiren differ from ACE inhibitors and ARBs regarding Plasma Renin Activity (PRA) versus Plasma Renin Concentration (PRC)?\"},\"technicalTerms\":[{\"term\":\"aldosteron\",\"arContext\":\"ألدوستيرون (aldosterone)\"},{\"term\":\"hiperkalemi\",\"arContext\":\"فرط بوتاسيوم الدم (hyperkalemia)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Dolaşımdaki renin molekülü miktarı (PRC) ile substratı kesme enzimatik gücü (PRA) arasındaki farkı düşünün.\",\"ar\":\"ميز بين كمية جزيئات الرينين (PRC) وقدرتها الإنزيمية على شطر الركيزة (PRA).\",\"en\":\"Distinguish between enzyme molecule quantity (PRC) versus substrate cleavage activity (PRA).\"},{\"tier\":2,\"tr\":\"Ang II düzeyleri düştüğünde jukstaglomerüler hücreler negatif geri bildirimi kaybeder ve kana daha çok renin proteini salar.\",\"ar\":\"حين يهبط Ang II تفقد الخلايا المجاورة للكبيبات التلقيم الراجع فتفرز مزيداً من بروتين الرينين.\",\"en\":\"When Ang II falls, juxtaglomerular cells lose negative feedback, secreting more renin protein into circulation.\"},{\"tier\":3,\"tr\":\"Tüm RAAS blokerleri PRC'yi artırır. Ancak Aliskiren reninin aktif bölgesini bağlayarak enzimatik aktiviteyi (PRA) düşürür; ACEi ve ARB'lerde ise PRA artar.\",\"ar\":\"ترفع جميع حاصرات RAAS تركيز PRC. لكن أليسكيرين يحصر الموقع النشط للرينين فيسقط نشاطه (PRA)، بينما يرتفع PRA مع ACEi و ARBs.\",\"en\":\"All RAAS blockers elevate PRC due to lost feedback. But Aliskiren blocks renin's active site, dropping PRA, whereas ACEi/ARBs increase PRA.\"}],\"widgetType\":\"MultipleChoice\",\"conceptCheck\":{\"question\":{\"tr\":\"Aliskirenin PRA ve PRC üzerindeki etkisi ACEi ve ARB'lerden nasıl farklılaşır?\",\"ar\":\"كيف يختلف تأثير أليسكيرين على PRA و PRC مقارنة بمثبطات ACE و ARBs؟\",\"en\":\"How does aliskiren's effect on PRA and PRC diverge from ACE inhibitors and ARBs?\"},\"options\":[{\"id\":\"opt-l9-s11-1\",\"isCorrect\":true,\"text\":{\"tr\":\"ACEi ve ARB'ler negatif geri bildirimin kaybıyla hem PRA'yı hem PRC'yi artırır; Aliskiren ise enzimi doğrudan inhibe ederek PRA'yı düşürürken PRC'yi artırır.\",\"ar\":\"ترفع مثبطات ACE و ARBs كلاً من PRA و PRC بفقدان التلقيم الراجع؛ بينما يثبط أليسكيرين نشاط الرينين الإنزيمي خافضاً PRA ورافعاً PRC انعكاسياً.\",\"en\":\"ACEi and ARBs increase both PRA and PRC via loss of negative feedback; Aliskiren directly inhibits renin enzymatic activity, suppressing PRA while reflexively increasing PRC.\"},\"feedback\":{\"tr\":\"Doğru. Ang II azaldığında jukstaglomerüler negatif geri bildirim kalkar ve renin proteini (PRC) tüm sınıflarda artar. Aliskiren renini aktif yerinden kilitlediği için aktivite (PRA) çöker.\",\"ar\":\"صحيح. عند هبوط Ang II يزول التلقيم الراجع ويرتفع بروتين الرينين (PRC) في الجميع. لكن أليسكيرين يقفل الموقع النشط فينهار نشاطه التحفيزي (PRA).\",\"en\":\"Correct. Removing Ang II negative feedback increases renin release (PRC rises in all classes). But aliskiren blocks the catalytic cleft, so enzymatic activity (PRA) falls.\"}},{\"id\":\"opt-l9-s11-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Aliskiren böbrek promotörüne bağlanarak renin mRNA sentezini tamamen durdurur ve hem PRA hem PRC'yi sıfıra indirir.\",\"ar\":\"يرتبط أليسكيرين بالمحفز الكلوي ليوقف اصطناع mRNA للرينين كلياً، خافضاً كلاً من PRA و PRC إلى الصفر.\",\"en\":\"Aliskiren binds the renal promoter to completely shut down renin mRNA synthesis, reducing both PRA and PRC to zero.\"},\"feedback\":{\"tr\":\"Yanlış. Aliskiren bir enzim inhibitörüdür, transkripsiyon baskılayıcı değildir. Geri bildirim kalktığı için jukstaglomerüler hücreler PRC'yi artırır.\",\"ar\":\"غير صحيح. أليسكيرين مثبط إنزيمي وليس كابحاً للاستنساخ؛ تفرز الخلايا المجاورة للكبيبات مزيداً من بروتين الرينين (يرتفع PRC) لفقدان التلقيم الراجع.\",\"en\":\"Incorrect. Aliskiren is an active-site enzyme inhibitor, not a transcription repressor; PRC surges due to lost negative feedback.\"}},{\"id\":\"opt-l9-s11-3\",\"isCorrect\":false,\"text\":{\"tr\":\"ACE inhibitörleri jukstaglomerüler hücreleri inhibe etmek için renal AT2 reseptörlerini uyararak hem PRA hem PRC'yi baskılar.\",\"ar\":\"تثبط مثبطات ACE كلاً من PRA و PRC عبر تنبيه مستقبلات AT2 الكلوية لتثبيط الخلايا المجاورة للكبيبات.\",\"en\":\"ACE inhibitors suppress both PRA and PRC by directly stimulating renal AT2 receptors to inhibit juxtaglomerular cells.\"},\"feedback\":{\"tr\":\"Yanlış. Ang II baskılandığında jukstaglomerüler AT1 üzerindeki fren kalkar; renin salınımı (hem PRA hem PRC) belirgin şekilde artar.\",\"ar\":\"غير صحيح. عند تثبيط Ang II يزول الكبح عن مستقبلات AT1 الكبيبية؛ مما يرفع تحرر الرينين (كلا PRA و PRC) تعويضياً.\",\"en\":\"Incorrect. Suppressing Ang II relieves negative feedback on juxtaglomerular AT1 receptors, provoking a compensatory surge in both PRA and PRC.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-l9-s11-1\",\"isCorrect\":true,\"text\":{\"tr\":\"ACEi ve ARB'ler negatif geri bildirimin kaybıyla hem PRA'yı hem PRC'yi artırır; Aliskiren ise enzimi doğrudan inhibe ederek PRA'yı düşürürken PRC'yi artırır.\",\"ar\":\"ترفع مثبطات ACE و ARBs كلاً من PRA و PRC بفقدان التلقيم الراجع؛ بينما يثبط أليسكيرين نشاط الرينين الإنزيمي خافضاً PRA ورافعاً PRC انعكاسياً.\",\"en\":\"ACEi and ARBs increase both PRA and PRC via loss of negative feedback; Aliskiren directly inhibits renin enzymatic activity, suppressing PRA while reflexively increasing PRC.\"},\"feedback\":{\"tr\":\"Doğru. Ang II azaldığında jukstaglomerüler negatif geri bildirim kalkar ve renin proteini (PRC) tüm sınıflarda artar. Aliskiren renini aktif yerinden kilitlediği için aktivite (PRA) çöker.\",\"ar\":\"صحيح. عند هبوط Ang II يزول التلقيم الراجع ويرتفع بروتين الرينين (PRC) في الجميع. لكن أليسكيرين يقفل الموقع النشط فينهار نشاطه التحفيزي (PRA).\",\"en\":\"Correct. Removing Ang II negative feedback increases renin release (PRC rises in all classes). But aliskiren blocks the catalytic cleft, so enzymatic activity (PRA) falls.\"}},{\"id\":\"opt-l9-s11-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Aliskiren böbrek promotörüne bağlanarak renin mRNA sentezini tamamen durdurur ve hem PRA hem PRC'yi sıfıra indirir.\",\"ar\":\"يرتبط أليسكيرين بالمحفز الكلوي ليوقف اصطناع mRNA للرينين كلياً، خافضاً كلاً من PRA و PRC إلى الصفر.\",\"en\":\"Aliskiren binds the renal promoter to completely shut down renin mRNA synthesis, reducing both PRA and PRC to zero.\"},\"feedback\":{\"tr\":\"Yanlış. Aliskiren bir enzim inhibitörüdür, transkripsiyon baskılayıcı değildir. Geri bildirim kalktığı için jukstaglomerüler hücreler PRC'yi artırır.\",\"ar\":\"غير صحيح. أليسكيرين مثبط إنزيمي وليس كابحاً للاستنساخ؛ تفرز الخلايا المجاورة للكبيبات مزيداً من بروتين الرينين (يرتفع PRC) لفقدان التلقيم الراجع.\",\"en\":\"Incorrect. Aliskiren is an active-site enzyme inhibitor, not a transcription repressor; PRC surges due to lost negative feedback.\"}},{\"id\":\"opt-l9-s11-3\",\"isCorrect\":false,\"text\":{\"tr\":\"ACE inhibitörleri jukstaglomerüler hücreleri inhibe etmek için renal AT2 reseptörlerini uyararak hem PRA hem PRC'yi baskılar.\",\"ar\":\"تثبط مثبطات ACE كلاً من PRA و PRC عبر تنبيه مستقبلات AT2 الكلوية لتثبيط الخلايا المجاورة للكبيبات.\",\"en\":\"ACE inhibitors suppress both PRA and PRC by directly stimulating renal AT2 receptors to inhibit juxtaglomerular cells.\"},\"feedback\":{\"tr\":\"Yanlış. Ang II baskılandığında jukstaglomerüler AT1 üzerindeki fren kalkar; renin salınımı (hem PRA hem PRC) belirgin şekilde artar.\",\"ar\":\"غير صحيح. عند تثبيط Ang II يزول الكبح عن مستقبلات AT1 الكبيبية؛ مما يرفع تحرر الرينين (كلا PRA و PRC) تعويضياً.\",\"en\":\"Incorrect. Suppressing Ang II relieves negative feedback on juxtaglomerular AT1 receptors, provoking a compensatory surge in both PRA and PRC.\"}}],\"prompt\":{\"tr\":\"Direkt renin inhibitörü aliskirenin farmakolojik profili, Plazma Renin Aktivitesi (PRA) ve Plazma Renin Konsantrasyonu (PRC) açısından ACE inhibitörleri ve ARB'lerden nasıl ayrılır?\",\"ar\":\"كيف يختلف المظهر الدوائي لمثبط الرينين المباشر أليسكيرين عن مثبطات ACE و ARBs فيما يخص نشاط الرينين في البلازما (PRA) مقابل تركيز الرينين (PRC)؟\",\"en\":\"How does the pharmacological profile of the direct renin inhibitor aliskiren differ from ACE inhibitors and ARBs regarding Plasma Renin Activity (PRA) versus Plasma Renin Concentration (PRC)?\"},\"title\":{\"tr\":\"Bütünsel Bağlantı: Direkt Renin İnhibitörleri ve Geri Bildirim Döngüleri\",\"ar\":\"ترابط شمولي: مثبطات الرينين المباشرة وحلقات التلقيم الراجع\",\"en\":\"Holistic Connection: Direct Renin Inhibitors & RAAS Feedback Loops\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":13}]},{\"id\":\"pharm-mod5-les1-step12\",\"order\":12,\"stageIndex\":12,\"stage\":\"mastery_check\",\"type\":\"question\",\"title\":{\"tr\":\"Ustalık Sınavı: Biyobelirteç Paneli ve İlaç Tanımlaması\",\"ar\":\"اختبار الإتقان: لوحة المؤشرات الحيوية وتشخيص الدواء\",\"en\":\"Mastery Check: Biochemical Panel Diagnosis & Drug Identification\"},\"prompt\":{\"tr\":\"Hipertansif bir hastanın laboratuvar panelinde: Yüksek PRA, yüksek Anjiyotensin I, belirgin baskılanmış Anjiyotensin II, yüksek bradikinin ve hafif hiperkalemi saptanıyor. Bu biyobelirteç tablosunu hangi ilaç açıklar?\",\"ar\":\"أظهرت تحاليل مريض ضغط: ارتفاع PRA، ارتفاع Ang I، هبوط شديد في Ang II، ارتفاع البراديكينين، وفرط بوتاسيوم خفيف. أي دواء يفسر هذه البصمة الحيوية بدقة؟\",\"en\":\"A hypertensive patient's diagnostic panel reveals: Elevated PRA, elevated Angiotensin I, markedly suppressed Angiotensin II, elevated bradykinin, and mild hyperkalemia. Which specific drug accounts for this biomarker signature?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Belirtilen hormon ve peptit profili hangi farmakolojik ajanın kullanımını kanıtlar?\",\"ar\":\"أي عامل دوائي تؤكده هذه اللوحة الهرمونية والببتيدية بدقة؟\",\"en\":\"Which pharmacological agent is definitively identified by this hormonal and peptide panel?\"},\"options\":[{\"id\":\"opt-l9-s12-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Kaptopril (ACE İnhibitörü); kilitlenen ACE Ang I'in Ang II'ye dönüşümünü durdurur (Ang I artar, Ang II düşer) ve bradikinin yıkımını engeller.\",\"ar\":\"كابتوبريل (مثبط ACE)؛ يؤدي حصر ACE لوقف تحول Ang I إلى Ang II (ارتفاع Ang I وهبوط Ang II) مع منع تفكيك البراديكينين.\",\"en\":\"Captopril (ACE Inhibitor); blocked ACE halts Ang I to Ang II conversion (elevating Ang I, suppressing Ang II) while preventing bradykinin degradation.\"},\"feedback\":{\"tr\":\"Doğru! ACE inhibitörleri Ang I'in Ang II'ye dönüşümünü keserek Ang I biriktirir ve Ang II'yi düşürür. Kininaz II bloke olduğu için bradikinin artar.\",\"ar\":\"صحيح! تحجب مثبطات ACE تحول Ang I إلى Ang II مما يراكم Ang I ويخفض Ang II، ويرفع البراديكينين لحصر كينيناز II.\",\"en\":\"Correct! ACE inhibitors block conversion of Ang I to Ang II, accumulating Ang I and depleting Ang II. Blocked kininase II accumulates bradykinin.\"}},{\"id\":\"opt-l9-s12-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Losartan (ARB); çünkü reseptörün bloke edilmesi plazma Ang II düzeyini düşürür ve dolaşımda bradikinin biriktirir.\",\"ar\":\"لوسارتان (ARB)؛ لأن حصر المستقبل يخفض بالتزامن تركيز Ang II في البلازما ويراكم البراديكينين الجائل.\",\"en\":\"Losartan (ARB); because blocking the receptor simultaneously reduces plasma Ang II concentration and accumulates circulating bradykinin.\"},\"feedback\":{\"tr\":\"Yanlış. ARB'ler AT1 reseptörünü bloke eder; negatif geri bildirim kalktığı için plazma Ang II seviyesi artar, bradikinin ise değişmez.\",\"ar\":\"غير صحيح. تحصر ARBs مستقبلات AT1 فيرتفع Ang II لزوال التلقيم الراجع، ولا تؤثر على كينيناز II فيبقى البراديكينين طبيعياً.\",\"en\":\"Incorrect. ARBs block AT1, increasing plasma Ang II via loss of negative feedback; they do not alter kininase II, so bradykinin is normal.\"}},{\"id\":\"opt-l9-s12-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Aliskiren (Direkt Renin İnhibitörü); çünkü yukarı akıştaki reninin bloke edilmesi Ang I'in Ang II'ye dönüşümünü hızlandırır.\",\"ar\":\"أليسكيرين (مثبط الرينين المباشر)؛ لأن حصر الرينين في البداية يسرع تحول Ang I إلى Ang II.\",\"en\":\"Aliskiren (Direct Renin Inhibitor); because blocking upstream renin accelerates conversion of Ang I into Ang II.\"},\"feedback\":{\"tr\":\"Yanlış. Aliskiren anjiyotensinojenin Ang I'e dönüşümünü engeller; hem Ang I hem Ang II düşer, PRA çöker ve bradikinin etkilenmez.\",\"ar\":\"غير صحيح. يثبط أليسكيرين تحول أنجيوتنسينوجين إلى Ang I؛ فيهبط كل من Ang I و Ang II وينهار PRA ولا يتغير البراديكينين.\",\"en\":\"Incorrect. Aliskiren inhibits angiotensinogen conversion to Ang I; both Ang I and Ang II fall, PRA plummets, and bradykinin is unaffected.\"}}]},\"technicalTerms\":[{\"term\":\"plazma renin aktivitesi\",\"arContext\":\"فعالية رينين البلازما (plasma renin activity - PRA)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Enzimatik darboğazı takip edin: Anjiyotensin I ile Anjiyotensin II arasında tam olarak hangi enzim bulunur?\",\"ar\":\"تتبع عنق الزجاجة الإنزيمي: ما هو الإنزيم الواقع تحديداً بين أنجيوتنسين I وأنجيوتنسين II؟\",\"en\":\"Follow the enzymatic bottleneck: Which enzyme sits directly between Angiotensin I and Angiotensin II?\"},{\"tier\":2,\"tr\":\"Bradikininin yüksek olduğuna dikkat edin. Hangi ilaç sınıfı bradikinin yıkımını selektif olarak durdurur?\",\"ar\":\"انتبه لارتفاع البراديكينين. أي صنف دوائي يثبط تفكيك البراديكينين نوعياً؟\",\"en\":\"Notice that bradykinin is elevated. Which drug class uniquely inhibits the breakdown of bradykinin?\"},{\"tier\":3,\"tr\":\"ACE (kininaz II) inhibisyonu Ang I'i biriktirir, Ang II'yi düşürür ve bradikinin yıkımını durdurur. Bu profil kaptopril (ACE inhibitörü) ile uyumludur.\",\"ar\":\"يؤدي تثبيط ACE (كينيناز II) لتراكم Ang I وهبوط Ang II ووقف تفكيك البراديكينين، وهو ما يطابق مثبطات ACE مثل كابتوبريل.\",\"en\":\"Inhibiting ACE traps Ang I, shuts down Ang II production, and halts bradykinin degradation. This matches an ACE inhibitor like captopril.\"}],\"widgetType\":\"MultipleChoice\",\"config\":{\"options\":[{\"id\":\"opt-l9-s12-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Kaptopril (ACE İnhibitörü); kilitlenen ACE Ang I'in Ang II'ye dönüşümünü durdurur (Ang I artar, Ang II düşer) ve bradikinin yıkımını engeller.\",\"ar\":\"كابتوبريل (مثبط ACE)؛ يؤدي حصر ACE لوقف تحول Ang I إلى Ang II (ارتفاع Ang I وهبوط Ang II) مع منع تفكيك البراديكينين.\",\"en\":\"Captopril (ACE Inhibitor); blocked ACE halts Ang I to Ang II conversion (elevating Ang I, suppressing Ang II) while preventing bradykinin degradation.\"},\"feedback\":{\"tr\":\"Doğru! ACE inhibitörleri Ang I'in Ang II'ye dönüşümünü keserek Ang I biriktirir ve Ang II'yi düşürür. Kininaz II bloke olduğu için bradikinin artar.\",\"ar\":\"صحيح! تحجب مثبطات ACE تحول Ang I إلى Ang II مما يراكم Ang I ويخفض Ang II، ويرفع البراديكينين لحصر كينيناز II.\",\"en\":\"Correct! ACE inhibitors block conversion of Ang I to Ang II, accumulating Ang I and depleting Ang II. Blocked kininase II accumulates bradykinin.\"}},{\"id\":\"opt-l9-s12-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Losartan (ARB); çünkü reseptörün bloke edilmesi plazma Ang II düzeyini düşürür ve dolaşımda bradikinin biriktirir.\",\"ar\":\"لوسارتان (ARB)؛ لأن حصر المستقبل يخفض بالتزامن تركيز Ang II في البلازما ويراكم البراديكينين الجائل.\",\"en\":\"Losartan (ARB); because blocking the receptor simultaneously reduces plasma Ang II concentration and accumulates circulating bradykinin.\"},\"feedback\":{\"tr\":\"Yanlış. ARB'ler AT1 reseptörünü bloke eder; negatif geri bildirim kalktığı için plazma Ang II seviyesi artar, bradikinin ise değişmez.\",\"ar\":\"غير صحيح. تحصر ARBs مستقبلات AT1 فيرتفع Ang II لزوال التلقيم الراجع، ولا تؤثر على كينيناز II فيبقى البراديكينين طبيعياً.\",\"en\":\"Incorrect. ARBs block AT1, increasing plasma Ang II via loss of negative feedback; they do not alter kininase II, so bradykinin is normal.\"}},{\"id\":\"opt-l9-s12-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Aliskiren (Direkt Renin İnhibitörü); çünkü yukarı akıştaki reninin bloke edilmesi Ang I'in Ang II'ye dönüşümünü hızlandırır.\",\"ar\":\"أليسكيرين (مثبط الرينين المباشر)؛ لأن حصر الرينين في البداية يسرع تحول Ang I إلى Ang II.\",\"en\":\"Aliskiren (Direct Renin Inhibitor); because blocking upstream renin accelerates conversion of Ang I into Ang II.\"},\"feedback\":{\"tr\":\"Yanlış. Aliskiren anjiyotensinojenin Ang I'e dönüşümünü engeller; hem Ang I hem Ang II düşer, PRA çöker ve bradikinin etkilenmez.\",\"ar\":\"غير صحيح. يثبط أليسكيرين تحول أنجيوتنسينوجين إلى Ang I؛ فيهبط كل من Ang I و Ang II وينهار PRA ولا يتغير البراديكينين.\",\"en\":\"Incorrect. Aliskiren inhibits angiotensinogen conversion to Ang I; both Ang I and Ang II fall, PRA plummets, and bradykinin is unaffected.\"}}],\"prompt\":{\"tr\":\"Hipertansif bir hastanın laboratuvar panelinde: Yüksek PRA, yüksek Anjiyotensin I, belirgin baskılanmış Anjiyotensin II, yüksek bradikinin ve hafif hiperkalemi saptanıyor. Bu biyobelirteç tablosunu hangi ilaç açıklar?\",\"ar\":\"أظهرت تحاليل مريض ضغط: ارتفاع PRA، ارتفاع Ang I، هبوط شديد في Ang II، ارتفاع البراديكينين، وفرط بوتاسيوم خفيف. أي دواء يفسر هذه البصمة الحيوية بدقة؟\",\"en\":\"A hypertensive patient's diagnostic panel reveals: Elevated PRA, elevated Angiotensin I, markedly suppressed Angiotensin II, elevated bradykinin, and mild hyperkalemia. Which specific drug accounts for this biomarker signature?\"},\"title\":{\"tr\":\"Ustalık Sınavı: Biyobelirteç Paneli ve İlaç Tanımlaması\",\"ar\":\"اختبار الإتقان: لوحة المؤشرات الحيوية وتشخيص الدواء\",\"en\":\"Mastery Check: Biochemical Panel Diagnosis & Drug Identification\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":14}]}]},\"pharm-mod5-les2\":{\"id\":\"pharm-mod5-les2\",\"courseId\":\"pharmacology\",\"moduleId\":\"ph-mod-05\",\"title\":{\"tr\":\"Diüretik Mekanizmaları ve Tübüler Elektrolit Taşınması\",\"ar\":\"آليات مدرات البول ونقل الشوارد في النبيبات الكلوية\",\"en\":\"Diuretic Mechanisms & Tubular Electrolyte Transport\"},\"order\":2,\"access\":\"free\",\"objective\":{\"tr\":\"Kıvrım, tiyazid ve potasyum tutucu diüretiklerin nefron taşıyıcıları (NKCC2, NCC, ENaC, MR) üzerindeki moleküler mekanizmalarını, elektrolit profillerini ve iyon tuzağı dinamiklerini yönetmek.\",\"ar\":\"إتقان الآليات الجزيئية لمدرات البول العروية والثيازيدية والحافظة للبوتاسيوم على نواقل الكليون (NKCC2, NCC, ENaC, MR) ومظهر الشوارد وديناميكا فخ التأين.\",\"en\":\"Master molecular mechanisms of loop, thiazide, and potassium-sparing diuretics across nephron transporters (NKCC2, NCC, ENaC, MR), electrolyte clearance profiles, and luminal ion trapping.\"},\"misconceptions\":[{\"tr\":\"Tüm diüretiklerin potasyum kaybettirdiği ve hipokalemi yaptığı yanılgısı (spironolakton, eplerenon, amilorid ve triamteren toplayıcı kanallarda potasyum atılımını engelleyen potasyum tutucu diüretiklerdir; özellikle ACEi/ARB ile kombine edildiklerinde ölümcül hiperkalemiye yol açabilirler).\",\"ar\":\"الظن الخاطئ بأن جميع مدرات البول تطرح البوتاسيوم وتسبب نقصانه (سبيرونولاكتون وأميلوريد وغيرها مدرات حافظة للبوتاسيوم في القنوات الجامعة، والجمع بينها وبين مثبطات ACE قد يسبب فرط بوتاسيوم مميتاً).\",\"en\":\"The dangerous misconception that all diuretics induce potassium wasting and hypokalemia (spironolactone, eplerenone, and amiloride are potassium-sparing agents acting at collecting ducts; co-administration with ACEi/ARBs risks lethal hyperkalemia).\"},{\"tr\":\"Kıvrım diüretikleri ile tiyazidlerin kalsiyum atılımını aynı şekilde etkilediği yanılgısı ('Kıvrım Kalsiyumu Kaybettirir': furosemid NKCC2'yi bloke edip lüminal pozitif potansiyeli silerek Ca2+ ve Mg2+ atılımını artırır; tiyazidler ise distal tübülde Ca2+ geri emilimini artırır).\",\"ar\":\"الاعتقاد الخاطئ بتطابق تأثير مدرات البول العروية والثيازيدية على الكالسيوم ('مدرات العروة تطرح الكالسيوم': فوروسيميد يحصر NKCC2 فيزيل الجهد الإيجابي طارحاً الكالسيوم، بينما تعزز الثيازيدات امتصاصه).\",\"en\":\"The confusion that loop and thiazide diuretics affect calcium identically ('Loops Lose Calcium': furosemide inhibits NKCC2, abolishing the lumen-positive potential and wasting calcium; thiazides enhance distal calcium reabsorption).\"},{\"tr\":\"Diüretiklerin kandan doğrudan bazolateral taraftan nefrona etki ettiği yanılgısı (furosemid ve tiyazidler plazma proteinlerine %95-98 bağlı zayıf organik asitlerdir; glomerülden süzülemezler, proksimal tübüler OAT taşıyıcılarıyla lümene salgılanıp lümen içi hedef bölgelerine taşınmalıdırlar).\",\"ar\":\"الاعتقاد الخاطئ بأن مدرات البول تؤثر على الكليون مباشرة من الدم جانبياً (ترتبط بالبروتينات بنسبة 98% وتعجز عن العبور الكبيبي؛ لذا تفرز بنواقل OAT في النبيبات القريبة لتصل إلى أهدافها في التجويف الأنبوبي).\",\"en\":\"The assumption that diuretics act directly from peritubular capillaries (furosemide and thiazides are 95-98% protein-bound weak organic acids that barely filter; they must be actively secreted via proximal OAT to reach luminal binding sites).\"}],\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":24}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Katzung's Basic & Clinical Pharmacology\",\"edition\":\"15th ed.\",\"topic\":\"Diuretic Agents: Loop Diuretics, Thiazides, Potassium-Sparing Agents\",\"chapter\":\"Chapter 15: Diuretic Agents\",\"page\":\"pp. 255-278\",\"status\":\"verified\"},{\"id\":\"cit-ref-02\",\"book\":\"Goodman & Gilman's The Pharmacological Basis of Therapeutics\",\"edition\":\"14th ed.\",\"topic\":\"Diuretics and Other Agents Employed in the Mobilization of Renal Fluid\",\"chapter\":\"Chapter 25: Diuretics\",\"page\":\"pp. 445-470\",\"status\":\"verified\"}],\"spacedReviewCards\":[{\"cardId\":\"pharm-mod5-les2-card1\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Kıvrım Diüretikleri Hedefi ve Pozitif Potansiyel\",\"prompt\":\"Furosemid Henle kulpunda hangi kotransportörü bloke eder ve kalsiyum ile magnezyum atılımını nasıl artırır?\",\"answer\":\"NKCC2 (Na+/K+/2Cl-) kotransportörünü bloke eder. K+ geri sızıntısının oluşturduğu +8 mV'lik lümen-pozitif transepitelyal potansiyeli silerek Ca2+ ve Mg2+'nin paraselüler emilimini durdurur (Loops Lose Calcium).\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod5-les2-card2\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Tiyazid Hedefi ve Kalsiyum Tutulması\",\"prompt\":\"Hidroklorotiyazid hangi segmentte hangi taşıyıcıyı bloke eder ve böbrek taşı oluşumunu neden önler?\",\"answer\":\"Distal kıvrımlı tübülde NCC (Na+/Cl-) kotransportörünü bloke eder. İntraselüler Na+ azalınca bazolateral Na+/Ca2+ değiştiricisi hızlanır; Ca2+ geri emilimi artar ve idrarda kalsiyum azaldığı için taş önlenir.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod5-les2-card3\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Diüretiklerin OAT Salgısı ve İyon Tuzağı\",\"prompt\":\"Furosemid ve tiyazidler glomerüler filtrasyonla mı yoksa proksimal tübüler salgıyla mı tübüler lümene ulaşır?\",\"answer\":\"Her ikisi de plazma albüminine yüksek oranda bağlıdır (>%95) ve süzülemez; proksimal tübüldeki Organik Anyon Taşıyıcıları (OAT) ile lümene aktif salgılanıp iyonize tuzaklanarak hedef bölgelerine akar.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod5-les2-card4\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Potasyum Tutucu Diüretik Çeşitleri\",\"prompt\":\"Spironolakton ile amiloridin toplayıcı kanaldaki moleküler etki mekanizması farkı nedir?\",\"answer\":\"Spironolakton intraselüler mineralokortikoid (aldosteron) reseptör antagonistidir; amilorid ise lüminal ENaC sodyum kanallarını doğrudan bloke eden direkt kanal engelleyicisidir.\",\"box\":1,\"intervalDays\":1}],\"steps\":[{\"id\":\"pharm-mod5-les2-step1\",\"order\":1,\"stageIndex\":1,\"stage\":\"hook\",\"type\":\"question\",\"title\":{\"tr\":\"Klinik Paradoks: Akut Akciğer Ödeminde Furosemidin İdrar Öncesi Etkisi\",\"ar\":\"المفارقة السريرية: تأثير فوروسيميد قبل الإدرار في وذمة الرئة\",\"en\":\"Clinical Paradox: IV Furosemide in Acute Pulmonary Edema\"},\"predictThenReveal\":true,\"prompt\":{\"tr\":\"Akut akciğer ödemi hastasına IV furosemid veriliyor. Boğucu nefes darlığı, mesanede tek damla idrar oluşmadan önce, 5 dakikada mucizevi şekilde düzeliyor! Bu durumu hangi akut hemodinamik mekanizma açıklar?\",\"ar\":\"تلقى مريض وذمة رئة حادة فوروسيميد وريدياً. تحسن ضيق التنفس الخانق خلال 5 دقائق وقبل أن تنتج المثانة قطرة بول واحدة! ما الآلية الديناميكية الدموية السريعة المفسرة؟\",\"en\":\"An acute pulmonary edema patient receives IV furosemide. Suffocating dyspnea resolves dramatically within 5 minutes—long before the bladder produces a single drop of urine! What acute hemodynamic mechanism explains this?\"},\"conceptCheck\":{\"question\":{\"tr\":\"IV furosemid akciğer ödemini diürez başlamadan dakikalar önce nasıl rahatlatır?\",\"ar\":\"كيف يريح فوروسيميد وريدياً وذمة الرئة خلال دقائق وقبل بدء الإدرار الفعلي؟\",\"en\":\"How does IV furosemide relieve acute pulmonary edema minutes before diuresis begins?\"},\"options\":[{\"id\":\"opt-l10-s1-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Furosemid hızla renal prostaglandin (PGE2) salınımını tetikler; sistemik venodilatasyon yaparak venöz kanı göller ve kardiyak önyükü belirgin şekilde düşürür.\",\"ar\":\"يحفز الفوروسيميد تحرراً كلوياً سريعاً للبروستاغلاندين (PGE2)، مسبباً توسعاً وريدياً جهازياً يجمع الدم ويخفض الحمل القبلي للقلب بشدة.\",\"en\":\"Furosemide triggers rapid renal prostaglandin (PGE2) release, provoking systemic venodilation that pools venous blood and dramatically reduces cardiac preload.\"},\"feedback\":{\"tr\":\"Doğru. Furosemid diürezden önce hızla renal prostaglandin (PGE2) salarak venöz kapasitansı artırır, önyükü düşürür ve akciğer kılcal basıncını düşürür.\",\"ar\":\"صحيح. يمتلك فوروسيميد تأثيراً وعائياً سريعاً عبر PGE2؛ يوسع الأوردة ويخفض الحمل القبلي محولاً الدم عن الرئتين قبل بدء إدرار البول.\",\"en\":\"Correct. Furosemide has a rapid vascular action mediated by renal PGE2: it induces systemic venodilation, pooling blood and reducing preload before diuresis.\"}},{\"id\":\"opt-l10-s1-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Furosemid hava yolu beta-2 adrenerjik reseptörlerini uyararak bronş düz kasını doğrudan gevşetir ve alveolar sıvıyı temizler.\",\"ar\":\"ينبه الفوروسيميد مستقبلات بيتا-2 الشعبية مباشرة، مرخياً العضلات الملساء التنفسية ومصرّفاً السائل السنخي.\",\"en\":\"Furosemide stimulates airway beta-2 adrenergic receptors, directly relaxing bronchial smooth muscle and clearing alveolar transudate.\"},\"feedback\":{\"tr\":\"Yanlış. Furosemidin adrenerjik reseptör afinitesi yoktur; rahatlama prostaglandin aracılı venöz önyük düşüşünden kaynaklanır.\",\"ar\":\"غير صحيح. ليس للفوروسيميد أي ألفة للمستقبلات الأدرينالينية؛ وينجم التحسن عن تخفيف الحمل القبلي بتوسع الأوردة عبر البروستاغلاندين.\",\"en\":\"Incorrect. Furosemide has zero adrenergic affinity. The relief is hemodynamic preload reduction via prostaglandin-mediated venodilation.\"}},{\"id\":\"opt-l10-s1-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Furosemid lenfatik kapakçıkları doğrudan açarak dakikalar içinde 2 litre alveolar sıvıyı duktus torasikusa pompalar.\",\"ar\":\"يفتح الفوروسيميد الصمامات اللمفاوية مباشرة، ضاخاً لترين من السائل السنخي إلى القناة الصدرية خلال دقائق.\",\"en\":\"Furosemide directly opens lymphatic valve pores, pumping 2 liters of alveolar fluid into thoracic ducts within minutes.\"},\"feedback\":{\"tr\":\"Yanlış. Lenfatik sistem sıvıyı bu hızda boşaltamaz. Sol ventrikül dolum basıncı düşünce kapillerler sıvıyı kendiliğinden geri çeker.\",\"ar\":\"غير صحيح. لا يمكن للجهاز اللمفاوي تصريف السوائل بهذه السرعة؛ يسمح انخفاض ضغط الأذين الأيسر للشعيرات بإعادة امتصاص السائل تلقائياً.\",\"en\":\"Incorrect. Fluid cannot be cleared lymphatically that fast; reducing left ventricular filling pressure allows pulmonary capillaries to reabsorb transudate.\"}}]},\"technicalTerms\":[{\"term\":\"kıvrım diüretiği\",\"arContext\":\"مدر البول العروي (loop diuretic)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Zamanlamaya dikkat edin: 5 dakika tübüler sıvı akışı veya idrar oluşumu için çok erkendir.\",\"ar\":\"انتبه للتوقيت: 5 دقائق أسرع بكثير من تدفق البول وامتلاء المثانة.\",\"en\":\"Notice the timing: 5 minutes is too fast for renal tubular fluid flow or bladder filling.\"},{\"tier\":2,\"tr\":\"Venöz kapasitansı düşünün: Kalbin ön-yükünü (preload) anında boşaltmak için venöz kan nerede göllenebilir?\",\"ar\":\"فكر في السعة الوريدية: أين يمكن تجميع الدم لتخفيف الحمل القبلي للقلب على الفور؟\",\"en\":\"Think about vascular capacitance: where can blood be pooled to immediately unload the failing heart?\"},{\"tier\":3,\"tr\":\"Furosemid hızla renal PGE2 sentezini uyararak sistemik venodilatasyon yapar. Bu etki venöz dönüşü azaltıp akciğer konjesyonunu idrar başlamadan rahatlatır.\",\"ar\":\"يحفز فوروسيميد تحرر PGE2 الكلوي مسبباً توسعاً وريدياً فورياً يخفض العود الوريدي ويريح وذمة الرئة قبل الإدرار.\",\"en\":\"Furosemide stimulates renal PGE2 synthesis, causing rapid systemic venodilation that reduces venous return and relieves congestion prior to diuresis.\"}],\"widgetType\":\"MultipleChoice\",\"config\":{\"options\":[{\"id\":\"opt-l10-s1-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Furosemid hızla renal prostaglandin (PGE2) salınımını tetikler; sistemik venodilatasyon yaparak venöz kanı göller ve kardiyak önyükü belirgin şekilde düşürür.\",\"ar\":\"يحفز الفوروسيميد تحرراً كلوياً سريعاً للبروستاغلاندين (PGE2)، مسبباً توسعاً وريدياً جهازياً يجمع الدم ويخفض الحمل القبلي للقلب بشدة.\",\"en\":\"Furosemide triggers rapid renal prostaglandin (PGE2) release, provoking systemic venodilation that pools venous blood and dramatically reduces cardiac preload.\"},\"feedback\":{\"tr\":\"Doğru. Furosemid diürezden önce hızla renal prostaglandin (PGE2) salarak venöz kapasitansı artırır, önyükü düşürür ve akciğer kılcal basıncını düşürür.\",\"ar\":\"صحيح. يمتلك فوروسيميد تأثيراً وعائياً سريعاً عبر PGE2؛ يوسع الأوردة ويخفض الحمل القبلي محولاً الدم عن الرئتين قبل بدء إدرار البول.\",\"en\":\"Correct. Furosemide has a rapid vascular action mediated by renal PGE2: it induces systemic venodilation, pooling blood and reducing preload before diuresis.\"}},{\"id\":\"opt-l10-s1-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Furosemid hava yolu beta-2 adrenerjik reseptörlerini uyararak bronş düz kasını doğrudan gevşetir ve alveolar sıvıyı temizler.\",\"ar\":\"ينبه الفوروسيميد مستقبلات بيتا-2 الشعبية مباشرة، مرخياً العضلات الملساء التنفسية ومصرّفاً السائل السنخي.\",\"en\":\"Furosemide stimulates airway beta-2 adrenergic receptors, directly relaxing bronchial smooth muscle and clearing alveolar transudate.\"},\"feedback\":{\"tr\":\"Yanlış. Furosemidin adrenerjik reseptör afinitesi yoktur; rahatlama prostaglandin aracılı venöz önyük düşüşünden kaynaklanır.\",\"ar\":\"غير صحيح. ليس للفوروسيميد أي ألفة للمستقبلات الأدرينالينية؛ وينجم التحسن عن تخفيف الحمل القبلي بتوسع الأوردة عبر البروستاغلاندين.\",\"en\":\"Incorrect. Furosemide has zero adrenergic affinity. The relief is hemodynamic preload reduction via prostaglandin-mediated venodilation.\"}},{\"id\":\"opt-l10-s1-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Furosemid lenfatik kapakçıkları doğrudan açarak dakikalar içinde 2 litre alveolar sıvıyı duktus torasikusa pompalar.\",\"ar\":\"يفتح الفوروسيميد الصمامات اللمفاوية مباشرة، ضاخاً لترين من السائل السنخي إلى القناة الصدرية خلال دقائق.\",\"en\":\"Furosemide directly opens lymphatic valve pores, pumping 2 liters of alveolar fluid into thoracic ducts within minutes.\"},\"feedback\":{\"tr\":\"Yanlış. Lenfatik sistem sıvıyı bu hızda boşaltamaz. Sol ventrikül dolum basıncı düşünce kapillerler sıvıyı kendiliğinden geri çeker.\",\"ar\":\"غير صحيح. لا يمكن للجهاز اللمفاوي تصريف السوائل بهذه السرعة؛ يسمح انخفاض ضغط الأذين الأيسر للشعيرات بإعادة امتصاص السائل تلقائياً.\",\"en\":\"Incorrect. Fluid cannot be cleared lymphatically that fast; reducing left ventricular filling pressure allows pulmonary capillaries to reabsorb transudate.\"}}],\"prompt\":{\"tr\":\"Akut akciğer ödemi hastasına IV furosemid veriliyor. Boğucu nefes darlığı, mesanede tek damla idrar oluşmadan önce, 5 dakikada mucizevi şekilde düzeliyor! Bu durumu hangi akut hemodinamik mekanizma açıklar?\",\"ar\":\"تلقى مريض وذمة رئة حادة فوروسيميد وريدياً. تحسن ضيق التنفس الخانق خلال 5 دقائق وقبل أن تنتج المثانة قطرة بول واحدة! ما الآلية الديناميكية الدموية السريعة المفسرة؟\",\"en\":\"An acute pulmonary edema patient receives IV furosemide. Suffocating dyspnea resolves dramatically within 5 minutes—long before the bladder produces a single drop of urine! What acute hemodynamic mechanism explains this?\"},\"title\":{\"tr\":\"Klinik Paradoks: Akut Akciğer Ödeminde Furosemidin İdrar Öncesi Etkisi\",\"ar\":\"المفارقة السريرية: تأثير فوروسيميد قبل الإدرار في وذمة الرئة\",\"en\":\"Clinical Paradox: IV Furosemide in Acute Pulmonary Edema\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":19}]},{\"id\":\"pharm-mod5-les2-step2\",\"order\":2,\"stageIndex\":2,\"stage\":\"question\",\"type\":\"question\",\"title\":{\"tr\":\"Kavramsal Soru: Kıvrım Diüretikleri Kalsiyumu Atar, Tiyazidler Tutar\",\"ar\":\"سؤال مفاهيمي: مدرات العروة تطرح الكالسيوم والثيازيد تحبسه\",\"en\":\"Conceptual Question: Loops Lose Calcium vs Thiazides Take In Calcium\"},\"predictThenReveal\":true,\"prompt\":{\"tr\":\"Hipertansif bir hasta tekrarlayan kalsiyum oksalat böbrek taşlarından muzdariptir. Furosemid neden taş oluşumunu artırırken hidroklorotiyazid taşları tamamen durdurur? Kalsiyum yönetimi neden zıttır?\",\"ar\":\"يعاني مريض ضغط من حصيات كلوية كلسية ناكسة. لماذا يفاقم الفوروسيميد تكون الحصيات بينما يوقفه هيدروكلوروثيازيد تماماً؟ كيف يتناقض تعاملهما الكلوي مع الكالسيوم؟\",\"en\":\"A hypertensive patient suffers recurrent calcium oxalate kidney stones. Why does furosemide exacerbate nephrolithiasis, while hydrochlorothiazide halts stone recurrence entirely? How do their renal calcium handlings diverge?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Furosemid ve hidroklorotiyazidin böbrekte kalsiyum taşınması üzerindeki zıt etkilerinin temeli nedir?\",\"ar\":\"ما هو الأساس الفسيولوجي للتأثيرات المتعاكسة للفوروسيميد وهيدروكلوروثيازيد على نقل الكالسيوم الكلوي؟\",\"en\":\"What is the physiological basis of opposing renal calcium handling by furosemide versus hydrochlorothiazide?\"},\"options\":[{\"id\":\"opt-l10-s2-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Furosemid TAL'de NKCC2'yi bloke edip lümen-pozitif potansiyeli yıkarak kalsiyumu idrara döker; tiyazidler ise DCT'de NCC'yi bloke ederek kalsiyumun kana geri emilimini artırır.\",\"ar\":\"يحصر الفوروسيميد NKCC2 لاغياً الجهد الإيجابي وطارحاً الكالسيوم بالبول؛ بينما يحصر الثيازيد NCC خافضاً الصوديوم ومعززاً ارتشاف الكالسيوم للدم.\",\"en\":\"Furosemide blocks TAL NKCC2, abolishing the lumen-positive potential and wasting calcium into urine; thiazides block DCT NCC, lowering intracellular Na+ and enhancing basolateral Na+/Ca2+ reabsorption.\"},\"feedback\":{\"tr\":\"Doğru. Furosemid TAL'de ROMK kaynaklı +8 mV'lik paraselüler itici gücü sıfırlar (hiperkalsiyüri). Tiyazidler ise DCT'de hücre içi Na'yı düşürerek NCX1 ile kalsiyumu kana çeker (hipokalsiyüri).\",\"ar\":\"صحيح. يلغي فوروسيميد القوة الدافعة +8 mV في TAL طارحاً الكالسيوم (حصيات). بينما يخفض الثيازيد صوديوم DCT منشطاً NCX1 لإعادة الكالسيوم للدم (مانع للحصيات).\",\"en\":\"Correct. Furosemide dismantles the +8 mV lumen-positive driving force for paracellular Ca2+ in TAL. Thiazides lower DCT cellular Na+, driving basolateral NCX1 to reabsorb calcium.\"}},{\"id\":\"opt-l10-s2-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Tiyazidler tiroidden kalsitonin salınımını uyararak dolaşımdaki kalsiyumu kemiklere sokar ve kalsiyumun glomerüle ulaşmasını tamamen engeller.\",\"ar\":\"يحفز الثيازيد تحرر الكالسيتونين لترسيب الكالسيوم في العظام، ملغياً وصوله إلى الكبيبة كلياً.\",\"en\":\"Thiazides stimulate thyroid calcitonin release to drive circulating calcium into bones, eliminating calcium from the glomerulus entirely.\"},\"feedback\":{\"tr\":\"Yanlış. Tiyazidler tiroid veya kemiğe etki etmez; hipokalsiyürik etki tamamen DCT'deki NCC blokajı ve bazolateral NCX1 aktivasyonundan kaynaklanır.\",\"ar\":\"غير صحيح. لا يؤثر الثيازيد على الغدة الدرقية أو العظام؛ بل ينجم حصر طرح الكالسيوم حصراً عن تثبيط NCC وتنشيط NCX1 في الأنبوب البعيد.\",\"en\":\"Incorrect. Thiazides do not act on thyroid or bone; hypocalciuric actions occur strictly in the DCT via NCC inhibition and NCX1 exchange.\"}},{\"id\":\"opt-l10-s2-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Furosemid tüm toplayıcı sistemde epitelyal kalsiyum kanallarını (TRPV5) doğrudan bloke ederek aktif transselüler kalsiyum alımını felç eder.\",\"ar\":\"يحصر الفوروسيميد قنوات الكالسيوم الظهارية (TRPV5) مباشرة، معطلاً الامتصاص النشط للكالسيوم عبر الخلايا.\",\"en\":\"Furosemide directly blocks epithelial calcium channels (TRPV5) throughout the entire collecting system, paralyzing active transcellular calcium uptake.\"},\"feedback\":{\"tr\":\"Yanlış. TAL'de kalsiyum emilimi ağırlıklı olarak paraselülerdir ve lümen-pozitif potansiyelle itilir; furosemid TRPV5'i doğrudan bloke etmez.\",\"ar\":\"غير صحيح. ارتشاف الكالسيوم في TAL نظير خلوي تدفعه الشحنة الموجبة باللمعة؛ ولا يحصر فوروسيميد قنوات TRPV5 مباشرة.\",\"en\":\"Incorrect. TAL calcium reabsorption is paracellular, driven by the lumen-positive transepithelial voltage rather than direct TRPV5 blockade.\"}}]},\"technicalTerms\":[{\"term\":\"kalsiüri\",\"arContext\":\"بيلة الكالسيوم (calciuria)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Klinik kural: 'Loops Lose calcium, Thiazides Take in calcium' (Kıvrım kalsiyumu döker, Tiyazid tutar).\",\"ar\":\"القاعدة السريرية: 'مدرات العروة تطرح الكالسيوم (Loops Lose)، ومدرات الثيازيد تحبس الكالسيوم (Thiazides Take)'.\",\"en\":\"Mnemonic: 'Loops Lose calcium, Thiazides Take in calcium.'\"},{\"tier\":2,\"tr\":\"Henle çıkan kolunda paraselüler Ca2+ emilimi lümen-pozitif (+8 mV) potansiyele bakar. Distal tübülde ise Ca2+ emilimi hücre içi Na+ seviyesine bağlıdır.\",\"ar\":\"يعتمد ارتشاف الكالسيوم في العروة على الجهد الإيجابي باللمعة (+8 mV). وفي الأنبوب البعيد يقترن بخروج الصوديوم.\",\"en\":\"In the TAL, Ca2+ reabsorption depends on a lumen-positive potential (+8 mV). In DCT, Ca2+ reabsorption couples to Na+ exit.\"},{\"tier\":3,\"tr\":\"Furosemid TAL'de NKCC2'yi durdurup lümen-pozitif potansiyeli yıkar (kalsiyüri). Tiyazidler ise DCT'de hücre içi sodyumu düşürüp bazolateral 3Na+/Ca2+ değiştiricisini hızlandırır (kalsiyum tutulur).\",\"ar\":\"يلغي فوروسيميد الجهد الإيجابي طارحاً الكالسيوم بالبول؛ بينما يخفض الثيازيد الصوديوم بالخلية معززاً مبادل 3Na+/Ca2+ لارتشاف الكالسيوم للدم.\",\"en\":\"Furosemide abolishes the lumen-positive potential in TAL, wasting Ca2+. Thiazides lower cellular Na+ in DCT, driving basolateral 3Na+/Ca2+ exchange to retain calcium.\"}],\"widgetType\":\"MultipleChoice\",\"config\":{\"options\":[{\"id\":\"opt-l10-s2-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Furosemid TAL'de NKCC2'yi bloke edip lümen-pozitif potansiyeli yıkarak kalsiyumu idrara döker; tiyazidler ise DCT'de NCC'yi bloke ederek kalsiyumun kana geri emilimini artırır.\",\"ar\":\"يحصر الفوروسيميد NKCC2 لاغياً الجهد الإيجابي وطارحاً الكالسيوم بالبول؛ بينما يحصر الثيازيد NCC خافضاً الصوديوم ومعززاً ارتشاف الكالسيوم للدم.\",\"en\":\"Furosemide blocks TAL NKCC2, abolishing the lumen-positive potential and wasting calcium into urine; thiazides block DCT NCC, lowering intracellular Na+ and enhancing basolateral Na+/Ca2+ reabsorption.\"},\"feedback\":{\"tr\":\"Doğru. Furosemid TAL'de ROMK kaynaklı +8 mV'lik paraselüler itici gücü sıfırlar (hiperkalsiyüri). Tiyazidler ise DCT'de hücre içi Na'yı düşürerek NCX1 ile kalsiyumu kana çeker (hipokalsiyüri).\",\"ar\":\"صحيح. يلغي فوروسيميد القوة الدافعة +8 mV في TAL طارحاً الكالسيوم (حصيات). بينما يخفض الثيازيد صوديوم DCT منشطاً NCX1 لإعادة الكالسيوم للدم (مانع للحصيات).\",\"en\":\"Correct. Furosemide dismantles the +8 mV lumen-positive driving force for paracellular Ca2+ in TAL. Thiazides lower DCT cellular Na+, driving basolateral NCX1 to reabsorb calcium.\"}},{\"id\":\"opt-l10-s2-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Tiyazidler tiroidden kalsitonin salınımını uyararak dolaşımdaki kalsiyumu kemiklere sokar ve kalsiyumun glomerüle ulaşmasını tamamen engeller.\",\"ar\":\"يحفز الثيازيد تحرر الكالسيتونين لترسيب الكالسيوم في العظام، ملغياً وصوله إلى الكبيبة كلياً.\",\"en\":\"Thiazides stimulate thyroid calcitonin release to drive circulating calcium into bones, eliminating calcium from the glomerulus entirely.\"},\"feedback\":{\"tr\":\"Yanlış. Tiyazidler tiroid veya kemiğe etki etmez; hipokalsiyürik etki tamamen DCT'deki NCC blokajı ve bazolateral NCX1 aktivasyonundan kaynaklanır.\",\"ar\":\"غير صحيح. لا يؤثر الثيازيد على الغدة الدرقية أو العظام؛ بل ينجم حصر طرح الكالسيوم حصراً عن تثبيط NCC وتنشيط NCX1 في الأنبوب البعيد.\",\"en\":\"Incorrect. Thiazides do not act on thyroid or bone; hypocalciuric actions occur strictly in the DCT via NCC inhibition and NCX1 exchange.\"}},{\"id\":\"opt-l10-s2-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Furosemid tüm toplayıcı sistemde epitelyal kalsiyum kanallarını (TRPV5) doğrudan bloke ederek aktif transselüler kalsiyum alımını felç eder.\",\"ar\":\"يحصر الفوروسيميد قنوات الكالسيوم الظهارية (TRPV5) مباشرة، معطلاً الامتصاص النشط للكالسيوم عبر الخلايا.\",\"en\":\"Furosemide directly blocks epithelial calcium channels (TRPV5) throughout the entire collecting system, paralyzing active transcellular calcium uptake.\"},\"feedback\":{\"tr\":\"Yanlış. TAL'de kalsiyum emilimi ağırlıklı olarak paraselülerdir ve lümen-pozitif potansiyelle itilir; furosemid TRPV5'i doğrudan bloke etmez.\",\"ar\":\"غير صحيح. ارتشاف الكالسيوم في TAL نظير خلوي تدفعه الشحنة الموجبة باللمعة؛ ولا يحصر فوروسيميد قنوات TRPV5 مباشرة.\",\"en\":\"Incorrect. TAL calcium reabsorption is paracellular, driven by the lumen-positive transepithelial voltage rather than direct TRPV5 blockade.\"}}],\"prompt\":{\"tr\":\"Hipertansif bir hasta tekrarlayan kalsiyum oksalat böbrek taşlarından muzdariptir. Furosemid neden taş oluşumunu artırırken hidroklorotiyazid taşları tamamen durdurur? Kalsiyum yönetimi neden zıttır?\",\"ar\":\"يعاني مريض ضغط من حصيات كلوية كلسية ناكسة. لماذا يفاقم الفوروسيميد تكون الحصيات بينما يوقفه هيدروكلوروثيازيد تماماً؟ كيف يتناقض تعاملهما الكلوي مع الكالسيوم؟\",\"en\":\"A hypertensive patient suffers recurrent calcium oxalate kidney stones. Why does furosemide exacerbate nephrolithiasis, while hydrochlorothiazide halts stone recurrence entirely? How do their renal calcium handlings diverge?\"},\"title\":{\"tr\":\"Kavramsal Soru: Kıvrım Diüretikleri Kalsiyumu Atar, Tiyazidler Tutar\",\"ar\":\"سؤال مفاهيمي: مدرات العروة تطرح الكالسيوم والثيازيد تحبسه\",\"en\":\"Conceptual Question: Loops Lose Calcium vs Thiazides Take In Calcium\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":20}]},{\"id\":\"pharm-mod5-les2-step3\",\"order\":3,\"stageIndex\":3,\"stage\":\"intuition\",\"type\":\"question\",\"title\":{\"tr\":\"Fiziksel Sezgi: Kademeli Barajlar Nehri Olarak Nefron\",\"ar\":\"الحدس الفيزيائي: النفرون كنهرب سدود متتالية\",\"en\":\"Physical Intuition: The Nephron as a Cascading Dam River\"},\"prompt\":{\"tr\":\"Nefronu kademeli barajları olan bir nehir gibi hayal edin. Henle kulpu filtrelenen sodyumun %25'ini tutan devasa bir barajdır. Bu barajı dinamitlemek aşağıdaki setleri taşırır. Distal setler buna nasıl yanıt verir?\",\"ar\":\"تخيل النفرون كنهرب سدود متتالية. عروة هنلي سد هائل يحجز 25% من الصوديوم. تفجير هذا السد يغمر الحواجز السفلية. كيف تستجيب الحواجز البعيدة؟\",\"en\":\"Imagine the nephron as a river with cascading floodgates. The loop of Henle is a massive dam holding 25% of sodium. Dynamiting this dam overwhelms downstream levees. How do distal levees respond?\"},\"technicalTerms\":[{\"term\":\"Henle kulpu\",\"arContext\":\"عروة هنلي (loop of Henle)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Distal tübül ve toplayıcı kanallara ulaşan devasa sodyum ve sıvı akışını düşünün.\",\"ar\":\"فكر في التدفق الهائل للصوديوم والسوائل الواصل للأنابيب البعيدة والجامعة.\",\"en\":\"Consider the massive sodium and fluid delivery reaching the late distal tubule and collecting duct.\"},{\"tier\":2,\"tr\":\"Toplayıcı kanal ana hücreleri ENaC ile sodyumu çekerken elektriksel denge için idrara hangi katyonları feda eder?\",\"ar\":\"حين تستعيد خلايا الأنابيب الجامعة الصوديوم عبر ENaC، ما هي الكاتيونات التي تضحي بها في البول لمعادلة الشحنة؟\",\"en\":\"When principal cells take up sodium through ENaC, what cations must be dumped into urine for electrical balance?\"},{\"tier\":3,\"tr\":\"Aşırı distal sodyum akışı elektrejenik ENaC emilimini zorlar; lümene potasyum (ROMK) ve proton atılarak hipokalemik metabolik alkaloz gelişir.\",\"ar\":\"يدفع تدفق الصوديوم امتصاص ENaC الكهربائي، مولداً شحنة سالبة تجبر الكلية على طرح K+ و H+ مسببة قلاءً بنقص البوتاسيوم.\",\"en\":\"High distal sodium delivery drives electrogenic ENaC reabsorption, creating a lumen-negative charge that dumps K+ (ROMK) and H+ into urine.\"}],\"widgetType\":\"MultipleChoice\",\"conceptCheck\":{\"question\":{\"tr\":\"Kıvrım diüretikleri Henle barajını yıktığında toplayıcı kanallardaki elektrolit dengesi nasıl bozulur?\",\"ar\":\"كيف يختل توازن الشوارد في الأنابيب الجامعة حين تفجر مدرات العروة سد هنلي؟\",\"en\":\"How is collecting duct electrolyte transport altered when loop diuretics disable the Henle dam?\"},\"options\":[{\"id\":\"opt-l10-s2-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Aşırı sodyumla taşan toplayıcı kanallar, ENaC ve ROMK üzerinden sodyumu yakalamak için umutsuzca potasyum ve proton feda eder; hipokalemik metabolik alkaloz gelişir.\",\"ar\":\"تضحي الأنابيب الجامعة المغمورة بالصوديوم بالبوتاسيوم والبروتونات لاستعادة الصوديوم عبر ENaC و ROMK، محدثة قلاءً استقلابياً بنقص البوتاسيوم.\",\"en\":\"Flooded downstream collecting ducts frantically exchange surging sodium for potassium and protons via ENaC and ROMK, triggering severe hypokalemic metabolic alkalosis.\"},\"feedback\":{\"tr\":\"Doğru. Henle kulpu bloke edildiğinde distal segmentlere devasa sodyum ulaşır. Esas hücreler ENaC ile sodyumu çekerken potasyum ve protonları idrara atarak alkaloz ve hipokalemi yapar.\",\"ar\":\"صحيح. يغمر الصوديوم الأنابيب الجامعة، فتمتصه الخلايا الرئيسية عبر ENaC طارحة البوتاسيوم والهيدروجين، مما يحدث قلاءً استقلابياً بنقص البوتاسيوم.\",\"en\":\"Correct. Excessive distal sodium delivery stimulates electrogenic ENaC reabsorption, forcing principal cells to secrete K+ and H+ into urine.\"}},{\"id\":\"opt-l10-s2-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Aşağı akıştaki toplayıcı kanallar tüm iyon kanallarını tamamen kapatarak sodyum ve potasyumun eşit oranda dokunulmadan geçmesine izin verir.\",\"ar\":\"تغلق الأنابيب الجامعة السفلية جميع قنواتها كلياً، تاركة نسباً متساوية من الصوديوم والبوتاسيوم لتمر دون تعديل.\",\"en\":\"Downstream collecting ducts close all ion channels completely, allowing equal proportions of sodium and potassium to pass out untouched.\"},\"feedback\":{\"tr\":\"Yanlış. Toplayıcı kanallar kanallarını kapatmaz; aksine yüksek akış hızı ve aldosteron uyarımı potasyum atılımını maksimuma çıkarır.\",\"ar\":\"غير صحيح. لا تغلق الأنابيب قنواتها؛ بل يؤدي التدفق العالي وتحفيز الألدوستيرون لتعظيم إطراح البوتاسيوم.\",\"en\":\"Incorrect. Distal segments dramatically ramp up sodium-potassium exchange due to flow-dependent kaliuresis and lumen negativity.\"}},{\"id\":\"opt-l10-s2-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Aşağı akış segmentleri idrardan potasyumu aşırı geri emerek kıvrım diüretikleri uygulandığında yaşamı tehdit eden hiperkalemiye yol açar.\",\"ar\":\"تعيد الأجزاء السفلية امتصاص البوتاسيوم بشدة من البول، مسببة فرط بوتاسيوم مهدداً للحياة عند إعطاء مدرات العروة.\",\"en\":\"Downstream segments hyper-reabsorb potassium from urine, causing life-threatening hyperkalemia whenever loop diuretics are administered.\"},\"feedback\":{\"tr\":\"Yanlış. Kıvrım diüretikleri hiperkalemi değil hipokalemi yapar; potasyum atılımı belirgin şekilde artar.\",\"ar\":\"غير صحيح. تسبب مدرات العروة نقص البوتاسيوم وليس فرطه؛ حيث يتسارع إطراح البوتاسيوم بالبول بشدة.\",\"en\":\"Incorrect. Loop diuretics cause hypokalemia, not hyperkalemia; distal Na+/K+ exchange dumps potassium into urine.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-l10-s2-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Aşırı sodyumla taşan toplayıcı kanallar, ENaC ve ROMK üzerinden sodyumu yakalamak için umutsuzca potasyum ve proton feda eder; hipokalemik metabolik alkaloz gelişir.\",\"ar\":\"تضحي الأنابيب الجامعة المغمورة بالصوديوم بالبوتاسيوم والبروتونات لاستعادة الصوديوم عبر ENaC و ROMK، محدثة قلاءً استقلابياً بنقص البوتاسيوم.\",\"en\":\"Flooded downstream collecting ducts frantically exchange surging sodium for potassium and protons via ENaC and ROMK, triggering severe hypokalemic metabolic alkalosis.\"},\"feedback\":{\"tr\":\"Doğru. Henle kulpu bloke edildiğinde distal segmentlere devasa sodyum ulaşır. Esas hücreler ENaC ile sodyumu çekerken potasyum ve protonları idrara atarak alkaloz ve hipokalemi yapar.\",\"ar\":\"صحيح. يغمر الصوديوم الأنابيب الجامعة، فتمتصه الخلايا الرئيسية عبر ENaC طارحة البوتاسيوم والهيدروجين، مما يحدث قلاءً استقلابياً بنقص البوتاسيوم.\",\"en\":\"Correct. Excessive distal sodium delivery stimulates electrogenic ENaC reabsorption, forcing principal cells to secrete K+ and H+ into urine.\"}},{\"id\":\"opt-l10-s2-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Aşağı akıştaki toplayıcı kanallar tüm iyon kanallarını tamamen kapatarak sodyum ve potasyumun eşit oranda dokunulmadan geçmesine izin verir.\",\"ar\":\"تغلق الأنابيب الجامعة السفلية جميع قنواتها كلياً، تاركة نسباً متساوية من الصوديوم والبوتاسيوم لتمر دون تعديل.\",\"en\":\"Downstream collecting ducts close all ion channels completely, allowing equal proportions of sodium and potassium to pass out untouched.\"},\"feedback\":{\"tr\":\"Yanlış. Toplayıcı kanallar kanallarını kapatmaz; aksine yüksek akış hızı ve aldosteron uyarımı potasyum atılımını maksimuma çıkarır.\",\"ar\":\"غير صحيح. لا تغلق الأنابيب قنواتها؛ بل يؤدي التدفق العالي وتحفيز الألدوستيرون لتعظيم إطراح البوتاسيوم.\",\"en\":\"Incorrect. Distal segments dramatically ramp up sodium-potassium exchange due to flow-dependent kaliuresis and lumen negativity.\"}},{\"id\":\"opt-l10-s2-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Aşağı akış segmentleri idrardan potasyumu aşırı geri emerek kıvrım diüretikleri uygulandığında yaşamı tehdit eden hiperkalemiye yol açar.\",\"ar\":\"تعيد الأجزاء السفلية امتصاص البوتاسيوم بشدة من البول، مسببة فرط بوتاسيوم مهدداً للحياة عند إعطاء مدرات العروة.\",\"en\":\"Downstream segments hyper-reabsorb potassium from urine, causing life-threatening hyperkalemia whenever loop diuretics are administered.\"},\"feedback\":{\"tr\":\"Yanlış. Kıvrım diüretikleri hiperkalemi değil hipokalemi yapar; potasyum atılımı belirgin şekilde artar.\",\"ar\":\"غير صحيح. تسبب مدرات العروة نقص البوتاسيوم وليس فرطه؛ حيث يتسارع إطراح البوتاسيوم بالبول بشدة.\",\"en\":\"Incorrect. Loop diuretics cause hypokalemia, not hyperkalemia; distal Na+/K+ exchange dumps potassium into urine.\"}}],\"prompt\":{\"tr\":\"Nefronu kademeli barajları olan bir nehir gibi hayal edin. Henle kulpu filtrelenen sodyumun %25'ini tutan devasa bir barajdır. Bu barajı dinamitlemek aşağıdaki setleri taşırır. Distal setler buna nasıl yanıt verir?\",\"ar\":\"تخيل النفرون كنهرب سدود متتالية. عروة هنلي سد هائل يحجز 25% من الصوديوم. تفجير هذا السد يغمر الحواجز السفلية. كيف تستجيب الحواجز البعيدة؟\",\"en\":\"Imagine the nephron as a river with cascading floodgates. The loop of Henle is a massive dam holding 25% of sodium. Dynamiting this dam overwhelms downstream levees. How do distal levees respond?\"},\"title\":{\"tr\":\"Fiziksel Sezgi: Kademeli Barajlar Nehri Olarak Nefron\",\"ar\":\"الحدس الفيزيائي: النفرون كنهرب سدود متتالية\",\"en\":\"Physical Intuition: The Nephron as a Cascading Dam River\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":21}]},{\"id\":\"pharm-mod5-les2-step4\",\"order\":4,\"stageIndex\":4,\"stage\":\"visual_explanation\",\"type\":\"question\",\"title\":{\"tr\":\"Görsel Açıklama: Nefron Boyunca Taşıyıcı Mimarisi ve Etkinlik Tavanı\",\"ar\":\"شرح مرئي: بنية النواقل على طول النفرون وسقف الفعالية\",\"en\":\"Visual Explanation: Transporter Architecture Along the Nephron\"},\"prompt\":{\"tr\":\"Nefron boyunca diüretik hedeflerini haritalayın: TAL'de furosemid NKCC2'yi; DCT'de tiyazidler NCC'yi; CCD'de amilorid ENaC'ı, spironolakton MR'ı bloke eder. 'Yüksek tavanlı' etkinliği ne belirler?\",\"ar\":\"حدد أهداف المدرات على النفرون: في TAL يحصر فوروسيميد NKCC2؛ وفي DCT يحصر ثيازيد NCC؛ وفي CCD يحصر أميلوريد ENaC وسبيرونولاكتون MR. ما الذي يحدد الفعالية القصوى؟\",\"en\":\"Map the diuretic targets along the nephron: In TAL, furosemide blocks NKCC2; in DCT, thiazides block NCC; in CCD, amiloride blocks ENaC while spironolactone blocks MR. What defines high-ceiling potency?\"},\"technicalTerms\":[{\"term\":\"NKCC2 kotransportörü\",\"arContext\":\"ناقل NKCC2 المرافق (NKCC2 cotransporter)\"},{\"term\":\"NCC kotransportörü\",\"arContext\":\"ناقل NCC المرافق (NCC cotransporter)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Nefronun farklı bölümlerinde süzülen sodyumun yüzde kaçının geri emildiğini karşılaştırın.\",\"ar\":\"قارن بين النسبة المئوية للصوديوم المرتشف في كل جزء من النفرون.\",\"en\":\"Compare the percentage of filtered sodium reabsorbed in each nephron segment.\"},{\"tier\":2,\"tr\":\"TAL sodyumun %25'ini; DCT %5'ini; toplayıcı kanal ise yalnızca %2'sini geri emer.\",\"ar\":\"يرتشف TAL نحو 25% من الصوديوم، و DCT نحو 5%، والأنبوب الجامع نحو 2% فقط.\",\"en\":\"TAL reabsorbs ~25% of sodium; DCT ~5%; collecting duct only ~2%.\"},{\"tier\":3,\"tr\":\"Furosemid 'yüksek tavanlıdır' çünkü süzülen sodyumun %25'ini tutan NKCC2'yi kilitler; bu oran diğer tüm diüretik hedeflerini katlar.\",\"ar\":\"يعد فوروسيميد ذا 'سقف مرتفع' لأنه يعطل NKCC2 المسؤول عن 25% من الصوديوم، متجاوزاً بكثير بقية الأهداف.\",\"en\":\"Loop diuretics are 'high-ceiling' because blocking NKCC2 disables reclamation of 25% of filtered sodium, far exceeding other segments.\"}],\"widgetType\":\"MultipleChoice\",\"conceptCheck\":{\"question\":{\"tr\":\"Diüretiklerin natriüretik tavan gücünü (etkinlik kapasitesini) belirleyen temel faktör nedir?\",\"ar\":\"ما العامل الأساسي المحدد لسقف الفعالية الإدرارية للمدرات على طول النفرون؟\",\"en\":\"What primary factor dictates the maximal natriuretic ceiling capacity of diuretics along the nephron?\"},\"options\":[{\"id\":\"opt-l10-s4-1\",\"isCorrect\":true,\"text\":{\"tr\":\"NKCC2 süzülen sodyumun yaklaşık %25'ini geri emer; bu da kıvrım diüretiklerine DCT NCC (%5) veya CCD ENaC (%2) hedeflerine kıyasla devasa 'yüksek tavanlı' güç kazandırır.\",\"ar\":\"يعيد NKCC2 امتصاص 25% من الصوديوم في TAL، مما يمنح مدرات العروة قوة إدرار قصوى هائلة مقارنة بـ NCC في DCT (5%) أو ENaC (2%).\",\"en\":\"NKCC2 reabsorbs ~25% of filtered sodium in TAL, giving loop diuretics massive 'high-ceiling' natriuretic power compared to DCT NCC (~5%) or CCD ENaC (~2%).\"},\"feedback\":{\"tr\":\"Doğru. Hedef alınan nefron segmentinin sodyum taşıma kapasitesi tavanı belirler: TAL %25 (kıvrım: yüksek tavan), DCT %5 (tiyazid: orta), toplayıcı kanal %2 (K-tutucu: zayıf).\",\"ar\":\"صحيح. تحدد سعة ارتشاف الصوديوم في الجزء المستهدف سقف الفعالية: عروة هنلي 25% (سقف عالٍ)، الأنبوب البعيد 5% (متوسط)، والأنبوب الجامع 2% (ضعيف).\",\"en\":\"Correct. Segmental sodium reabsorption capacity dictates ceiling efficacy: TAL handles 25% (high ceiling), DCT handles 5% (moderate), CCD handles 2% (weak).\"}},{\"id\":\"opt-l10-s4-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Toplayıcı kanaldaki ENaC süzülen sodyumun %50'sinden fazlasını emer ve amiloridi en güçlü natriüretik ajan yapar.\",\"ar\":\"تعيد قنوات ENaC في الأنبوب الجامع امتصاص أكثر من 50% من الصوديوم، مما يجعل أميلوريد أقوى مدر للصوديوم.\",\"en\":\"ENaC in the collecting duct normally reabsorbs over 50% of filtered sodium, making amiloride the most potent natriuretic agent.\"},\"feedback\":{\"tr\":\"Yanlış. Toplayıcı kanal süzülen sodyumun yalnızca %1-3'ünü geri emer; potasyum tutucu diüretikler tek başlarına zayıf natriüretiklerdir.\",\"ar\":\"غير صحيح. يرتشف الأنبوب الجامع 1-3% فقط من الصوديوم المرتشح؛ ومدرات حفظ البوتاسيوم ضعيفة جداً بمفردها.\",\"en\":\"Incorrect. The collecting duct reabsorbs only 1–3% of filtered sodium; potassium-sparing diuretics are inherently weak natriuretics.\"}},{\"id\":\"opt-l10-s4-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Tiyazidlerin sonsuz doğrusal bir doz-yanıt eğrisi vardır ve yüksek dozlarda maksimum natriüretik kapasitede kıvrım diüretiklerini geçer.\",\"ar\":\"تمتلك الثيازيدات منحنى استجابة خطياً لا نهائياً، وتتجاوز مدرات العروة في قدرة طرح الصوديوم القصوى عند الجرعات العالية.\",\"en\":\"Thiazides have an infinite linear dose-response curve, exceeding loop diuretics in maximal natriuretic capacity at higher doses.\"},\"feedback\":{\"tr\":\"Yanlış. Tiyazidler düz bir doz-yanıt eğrisine sahiptir (düşük tavan); dozu artırmak diürezi artırmaz, sadece yan etkileri artırır.\",\"ar\":\"غير صحيح. للثيازيدات منحنى استجابة مسطح (سقف منخفض)؛ وزيادة الجرعة تزيد السمية دون مضاعفة الإدرار.\",\"en\":\"Incorrect. Thiazides have a flat dose-response curve (low ceiling); increasing dose beyond standard levels adds toxicity without enhancing diuresis.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-l10-s4-1\",\"isCorrect\":true,\"text\":{\"tr\":\"NKCC2 süzülen sodyumun yaklaşık %25'ini geri emer; bu da kıvrım diüretiklerine DCT NCC (%5) veya CCD ENaC (%2) hedeflerine kıyasla devasa 'yüksek tavanlı' güç kazandırır.\",\"ar\":\"يعيد NKCC2 امتصاص 25% من الصوديوم في TAL، مما يمنح مدرات العروة قوة إدرار قصوى هائلة مقارنة بـ NCC في DCT (5%) أو ENaC (2%).\",\"en\":\"NKCC2 reabsorbs ~25% of filtered sodium in TAL, giving loop diuretics massive 'high-ceiling' natriuretic power compared to DCT NCC (~5%) or CCD ENaC (~2%).\"},\"feedback\":{\"tr\":\"Doğru. Hedef alınan nefron segmentinin sodyum taşıma kapasitesi tavanı belirler: TAL %25 (kıvrım: yüksek tavan), DCT %5 (tiyazid: orta), toplayıcı kanal %2 (K-tutucu: zayıf).\",\"ar\":\"صحيح. تحدد سعة ارتشاف الصوديوم في الجزء المستهدف سقف الفعالية: عروة هنلي 25% (سقف عالٍ)، الأنبوب البعيد 5% (متوسط)، والأنبوب الجامع 2% (ضعيف).\",\"en\":\"Correct. Segmental sodium reabsorption capacity dictates ceiling efficacy: TAL handles 25% (high ceiling), DCT handles 5% (moderate), CCD handles 2% (weak).\"}},{\"id\":\"opt-l10-s4-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Toplayıcı kanaldaki ENaC süzülen sodyumun %50'sinden fazlasını emer ve amiloridi en güçlü natriüretik ajan yapar.\",\"ar\":\"تعيد قنوات ENaC في الأنبوب الجامع امتصاص أكثر من 50% من الصوديوم، مما يجعل أميلوريد أقوى مدر للصوديوم.\",\"en\":\"ENaC in the collecting duct normally reabsorbs over 50% of filtered sodium, making amiloride the most potent natriuretic agent.\"},\"feedback\":{\"tr\":\"Yanlış. Toplayıcı kanal süzülen sodyumun yalnızca %1-3'ünü geri emer; potasyum tutucu diüretikler tek başlarına zayıf natriüretiklerdir.\",\"ar\":\"غير صحيح. يرتشف الأنبوب الجامع 1-3% فقط من الصوديوم المرتشح؛ ومدرات حفظ البوتاسيوم ضعيفة جداً بمفردها.\",\"en\":\"Incorrect. The collecting duct reabsorbs only 1–3% of filtered sodium; potassium-sparing diuretics are inherently weak natriuretics.\"}},{\"id\":\"opt-l10-s4-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Tiyazidlerin sonsuz doğrusal bir doz-yanıt eğrisi vardır ve yüksek dozlarda maksimum natriüretik kapasitede kıvrım diüretiklerini geçer.\",\"ar\":\"تمتلك الثيازيدات منحنى استجابة خطياً لا نهائياً، وتتجاوز مدرات العروة في قدرة طرح الصوديوم القصوى عند الجرعات العالية.\",\"en\":\"Thiazides have an infinite linear dose-response curve, exceeding loop diuretics in maximal natriuretic capacity at higher doses.\"},\"feedback\":{\"tr\":\"Yanlış. Tiyazidler düz bir doz-yanıt eğrisine sahiptir (düşük tavan); dozu artırmak diürezi artırmaz, sadece yan etkileri artırır.\",\"ar\":\"غير صحيح. للثيازيدات منحنى استجابة مسطح (سقف منخفض)؛ وزيادة الجرعة تزيد السمية دون مضاعفة الإدرار.\",\"en\":\"Incorrect. Thiazides have a flat dose-response curve (low ceiling); increasing dose beyond standard levels adds toxicity without enhancing diuresis.\"}}],\"prompt\":{\"tr\":\"Nefron boyunca diüretik hedeflerini haritalayın: TAL'de furosemid NKCC2'yi; DCT'de tiyazidler NCC'yi; CCD'de amilorid ENaC'ı, spironolakton MR'ı bloke eder. 'Yüksek tavanlı' etkinliği ne belirler?\",\"ar\":\"حدد أهداف المدرات على النفرون: في TAL يحصر فوروسيميد NKCC2؛ وفي DCT يحصر ثيازيد NCC؛ وفي CCD يحصر أميلوريد ENaC وسبيرونولاكتون MR. ما الذي يحدد الفعالية القصوى؟\",\"en\":\"Map the diuretic targets along the nephron: In TAL, furosemide blocks NKCC2; in DCT, thiazides block NCC; in CCD, amiloride blocks ENaC while spironolactone blocks MR. What defines high-ceiling potency?\"},\"title\":{\"tr\":\"Görsel Açıklama: Nefron Boyunca Taşıyıcı Mimarisi ve Etkinlik Tavanı\",\"ar\":\"شرح مرئي: بنية النواقل على طول النفرون وسقف الفعالية\",\"en\":\"Visual Explanation: Transporter Architecture Along the Nephron\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":22}]},{\"id\":\"pharm-mod5-les2-step5\",\"order\":5,\"stageIndex\":5,\"stage\":\"interactive_artifact\",\"type\":\"interactive_artifact\",\"title\":{\"tr\":\"İnteraktif Simülatör: Tübüler Sıvı pH'sı ve Furosemid İyon Tuzağı\",\"ar\":\"محاكي تفاعلي: درجة حموضة السائل الأنبوبي وفخ تأين فوروسيميد\",\"en\":\"Interactive Simulator: Tubular pH & Furosemide Ion Trapping\"},\"prompt\":{\"tr\":\"Simülatörde tübüler sıvı pH sürgüsünü 5.5'ten 7.4'e getirin. Zayıf asit furosemidin (pKa 3.9) lümende iyonize halde tuzaklanarak zardan geri kaçmasını önleyen ve NKCC2'ye ulaşmasını sağlayan dengeyi keşfedin.\",\"ar\":\"حرك شريط pH البول في المحاكي من 5.5 إلى 7.4. اكتشف كيف يُحتجز حمض فوروسيميد الضعيف (pKa 3.9) متأيّناً في التجويف، مانعاً ارتداده عبر الغشاء ليبلغ هدفه NKCC2.\",\"en\":\"In the simulator, adjust tubular fluid pH from 5.5 to 7.4. Discover how weak acid furosemide (pKa 3.9) is trapped as an impermeant anion, preventing back-diffusion and delivering drug to luminal NKCC2.\"},\"predictThenReveal\":false,\"widgetType\":\"IonizationEquilibriumSlider\",\"widget\":{\"type\":\"IonizationEquilibriumSlider\",\"config\":{\"title\":\"Tübüler Sıvı pH'sı ve Furosemid İyon Tuzağı\",\"prompt\":\"Tübüler idrar pH'sını 5.5'ten 7.4'e yükseltin; furosemidin (pKa 3.9) lümende iyonize tuzaklanarak NKCC2 taşıyıcısına erişimini izleyin.\",\"drugName\":\"Furosemid (Furosemide)\",\"defaultPka\":3.9,\"defaultPh\":5.5,\"defaultDrugType\":\"acid\",\"locale\":\"tr\",\"showBioGradients\":true,\"source\":{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":24},\"explanation\":\"Furosemid zayıf bir organik asittir (pKa 3.9). Proksimal tübülde OAT taşıyıcılarıyla lümene salgılandıktan sonra, lümen pH'sında neredeyse tamamen iyonize kalarak lümende hapsolur ve Henle kulpundaki NKCC2 kotransportörünün lüminal yüzüne bağlanır.\"}},\"config\":{\"title\":\"Tübüler Sıvı pH'sı ve Furosemid İyon Tuzağı\",\"prompt\":\"Tübüler idrar pH'sını 5.5'ten 7.4'e yükseltin; furosemidin (pKa 3.9) lümende iyonize tuzaklanarak NKCC2 taşıyıcısına erişimini izleyin.\",\"drugName\":\"Furosemid (Furosemide)\",\"defaultPka\":3.9,\"defaultPh\":5.5,\"defaultDrugType\":\"acid\",\"locale\":\"tr\",\"showBioGradients\":true,\"source\":{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":24},\"explanation\":\"Furosemid zayıf bir organik asittir (pKa 3.9). Proksimal tübülde OAT taşıyıcılarıyla lümene salgılandıktan sonra, lümen pH'sında neredeyse tamamen iyonize kalarak lümende hapsolur ve Henle kulpundaki NKCC2 kotransportörünün lüminal yüzüne bağlanır.\"},\"technicalTerms\":[{\"term\":\"iyon tuzağı\",\"arContext\":\"فخ التأين (ion trapping)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Furosemidin NKCC2'yi inhibe edebilmesi için tübüler lümene salgılanması şarttır.\",\"ar\":\"يجب أن يصل فوروسيميد للمعة الأنبوبية ليثبط NKCC2 عبر إفرازه بنواقل OAT.\",\"en\":\"Furosemide must reach the luminal fluid to inhibit NKCC2; it is actively secreted by proximal OATs.\"},{\"tier\":2,\"tr\":\"Tübüler idrar pH'sında (5.5 - 7.4), zayıf asit furosemid (pKa 3.9) %99'un üzerinde iyonize kalır.\",\"ar\":\"في باهاء البول (5.5 - 7.4)، يتأين حمض فوروسيميد الضعيف (pKa 3.9) بنسبة تتجاوز 99%.\",\"en\":\"At tubular urine pH (5.5 to 7.4), weak acid furosemide (pKa 3.9) is >99% ionized into an impermeant conjugate base.\"},{\"tier\":3,\"tr\":\"İdrarda iyon tuzağına düşmesi furosemidin geri difüzyonunu önler ve lümendeki NKCC2 kotransportörüne ulaşmasını güvenceye alır.\",\"ar\":\"يمنع احتباس التأين في البول ارتشاف فوروسيميد بالانتشار، ضامناً وصوله لنواقل NKCC2 باللمعة.\",\"en\":\"Ion trapping in tubular fluid prevents furosemide from re-diffusing, ensuring delivery downstream to luminal NKCC2.\"}],\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":23}]},{\"id\":\"pharm-mod5-les2-step6\",\"order\":6,\"stageIndex\":6,\"stage\":\"guided_discovery\",\"type\":\"question\",\"title\":{\"tr\":\"Rehberli Keşif: Ters-Akım Çoğaltıcı Sisteminin Çöküşü\",\"ar\":\"استكشاف موجه: انهيار آلية التيار المتعاكس المضاعفة\",\"en\":\"Guided Discovery: Collapse of the Countercurrent Multiplier\"},\"prompt\":{\"tr\":\"Furosemid renal ters-akım çoğaltıcı mekanizmasını felç eder. NKCC2'nin bloke edilmesi, 1200 mOsm/L'lik kortikomedüller osmotik gradyanı neden tamamen yok ederek idrarı konsantre veya dilüe etme yeteneğini sıfırlar?\",\"ar\":\"يشل الفوروسيميد آلية التيار المتعاكس الكلوية. لماذا يؤدي حصر NKCC2 لتدمير المدروج التناضحي النخاعي (1200 mOsm/L) كلياً، عاجزاً الكلية عن تكثيف البول أو تمديده؟\",\"en\":\"Furosemide paralyzes the renal countercurrent multiplier. Why does blocking NKCC2 completely destroy the corticomedullary osmotic gradient (1200 mOsm/L), rendering the kidney incapable of concentrating or diluting urine?\"},\"technicalTerms\":[{\"term\":\"medüller ozmotik gradyan\",\"arContext\":\"الميل التناضحي اللبي (medullary osmotic gradient)\"}],\"hints\":[{\"tier\":1,\"tr\":\"ADH varlığında suyun toplayıcı kanallardan dışarı çıkmasını sağlayan osmotik çekici gücü düşünün.\",\"ar\":\"ما هي القوة التناضحية التي تجذب الماء خارج الأنابيب الجامعة بوجود هرمون ADH؟\",\"en\":\"What provides the osmotic driving force for water to leave collecting ducts when ADH is present?\"},{\"tier\":2,\"tr\":\"Medüller interstisyum, suyu çekebilmek için 1200 mOsm/L'ye kadar hipertonik olmak zorundadır.\",\"ar\":\"يجب أن يكون خلال النخاع مفرط التوتر (حتى 1200 mOsm/L) ليسحب الماء تناضحياً.\",\"en\":\"The medullary interstitium must be hypertonic (up to 1200 mOsm/L) to draw water out.\"},{\"tier\":3,\"tr\":\"Suya geçirimsiz TAL'de NKCC2 ile aktif NaCl pompalanması medüller gradyanı kurar. NKCC2 durunca interstisyum izotonikleşir (300 mOsm/L) ve izostenüri oluşur.\",\"ar\":\"يبني ضخ NaCl عبر NKCC2 في عروة هنلي الكتيمة للماء مدروج النخاع التناضحي. حصر هذا الناقل يسقط المدروج لسواء التوتر (300 mOsm/L).\",\"en\":\"Active NaCl pumping via NKCC2 in the water-impermeable TAL generates the medullary gradient. Blocking it collapses the gradient to 300 mOsm/L (isosthenuria).\"}],\"widgetType\":\"MultipleChoice\",\"conceptCheck\":{\"question\":{\"tr\":\"Furosemid medüller osmotik gradyanı ve idrar konsantre etme yeteneğini nasıl sıfırlar?\",\"ar\":\"كيف يلغي فوروسيميد المدروج التناضحي النخاعي وقدرة الكلية على تكثيف البول؟\",\"en\":\"How does furosemide abolish the medullary osmotic gradient and the ability to concentrate urine?\"},\"options\":[{\"id\":\"opt-l10-s6-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Medüller interstisyuma NKCC2 ile sodyum ve klor pompalanması hipertonik gradyanı yaratır; bu pompanın durması interstisyel osmolaliteyi izotonik seviyeye (300 mOsm/L) düşürür.\",\"ar\":\"يولد ضخ الصوديوم والكلور عبر NKCC2 إلى خلال النخاع المدروج مفرط التوتر؛ ويؤدي شل هذه المضخة لانهيار تناضح الخلال إلى السواء (300 mOsm/L).\",\"en\":\"NKCC2 sodium and chloride pumping into medullary interstitium generates the hypertonic gradient; abolishing this pump collapses interstitial osmolality to isotonic levels (300 mOsm/L).\"},\"feedback\":{\"tr\":\"Doğru. Henle çıkan kolu suya geçirimsizdir ancak NaCl'yi medüllaya aktif pompalar. Furosemid bu motoru kapatır; 1200 mOsm/L'lik gradyan 300 mOsm/L'ye (izostenüri) çöker.\",\"ar\":\"صحيح. عروة هنلي الصاعدة كتيمة للماء لكنها تضخ NaCl بنشاط إلى النخاع. يوقف فوروسيميد هذا المحرك فينهار المدروج إلى 300 mOsm/L.\",\"en\":\"Correct. The TAL pumps NaCl into medullary interstitium without water. Furosemide shuts down this salt engine, collapsing the 1200 mOsm/L gradient to 300 mOsm/L.\"}},{\"id\":\"opt-l10-s6-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Furosemid toplayıcı kanallardaki akuaporin-2 su kanallarını doğrudan bloke ederek su moleküllerinin membranlardan geçmesini engeller.\",\"ar\":\"يحصر الفوروسيميد قنوات الماء أكوابورين-2 في الأنابيب الجامعة مباشرة، مانعاً جزيئات الماء من عبور الأغشية.\",\"en\":\"Furosemide directly blocks aquaporin-2 water channels in collecting ducts, preventing water molecules from moving across membranes.\"},\"feedback\":{\"tr\":\"Yanlış. Furosemidin akuaporinler üzerinde etkisi yoktur; su emilemez çünkü dışarı çekecek medüller osmotik güç yok edilmiştir.\",\"ar\":\"غير صحيح. ليس للفوروسيميد تأثير على الأكوابورينات؛ بل يعجز الماء عن الخروج لزوال القوة التناضحية الجاذبة في النخاع.\",\"en\":\"Incorrect. Furosemide has no activity on aquaporins; water cannot be reabsorbed because the hypertonic osmotic driving force was erased.\"}},{\"id\":\"opt-l10-s6-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Furosemid vasa rekta kapillerlerini kasıp tromboze ederek tüm medüller kan akışını kalıcı olarak durdurur.\",\"ar\":\"يقبض الفوروسيميد شعيرات الأوعية المستقيمة ويخثرها، موقفاً تدفق الدم النخاعي تماماً.\",\"en\":\"Furosemide vasoconstricts and thromboses the vasa recta capillaries, stopping all medullary blood flow permanently.\"},\"feedback\":{\"tr\":\"Yanlış. Vasa rekta tamamen açıktır; gradyanın kaybolması damar tıkanıklığından değil, aktif tuz motorunun (NKCC2) kilitlenmesindendir.\",\"ar\":\"غير صحيح. تبقى الأوعية المستقيمة سالكة؛ وينجم زوال المدروج عن شل محرك النقل الفاعل (NKCC2) لا الانسداد الوعائي.\",\"en\":\"Incorrect. The vasa recta remain fully patent. The gradient is lost because the active transport engine (NKCC2) is blocked.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-l10-s6-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Medüller interstisyuma NKCC2 ile sodyum ve klor pompalanması hipertonik gradyanı yaratır; bu pompanın durması interstisyel osmolaliteyi izotonik seviyeye (300 mOsm/L) düşürür.\",\"ar\":\"يولد ضخ الصوديوم والكلور عبر NKCC2 إلى خلال النخاع المدروج مفرط التوتر؛ ويؤدي شل هذه المضخة لانهيار تناضح الخلال إلى السواء (300 mOsm/L).\",\"en\":\"NKCC2 sodium and chloride pumping into medullary interstitium generates the hypertonic gradient; abolishing this pump collapses interstitial osmolality to isotonic levels (300 mOsm/L).\"},\"feedback\":{\"tr\":\"Doğru. Henle çıkan kolu suya geçirimsizdir ancak NaCl'yi medüllaya aktif pompalar. Furosemid bu motoru kapatır; 1200 mOsm/L'lik gradyan 300 mOsm/L'ye (izostenüri) çöker.\",\"ar\":\"صحيح. عروة هنلي الصاعدة كتيمة للماء لكنها تضخ NaCl بنشاط إلى النخاع. يوقف فوروسيميد هذا المحرك فينهار المدروج إلى 300 mOsm/L.\",\"en\":\"Correct. The TAL pumps NaCl into medullary interstitium without water. Furosemide shuts down this salt engine, collapsing the 1200 mOsm/L gradient to 300 mOsm/L.\"}},{\"id\":\"opt-l10-s6-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Furosemid toplayıcı kanallardaki akuaporin-2 su kanallarını doğrudan bloke ederek su moleküllerinin membranlardan geçmesini engeller.\",\"ar\":\"يحصر الفوروسيميد قنوات الماء أكوابورين-2 في الأنابيب الجامعة مباشرة، مانعاً جزيئات الماء من عبور الأغشية.\",\"en\":\"Furosemide directly blocks aquaporin-2 water channels in collecting ducts, preventing water molecules from moving across membranes.\"},\"feedback\":{\"tr\":\"Yanlış. Furosemidin akuaporinler üzerinde etkisi yoktur; su emilemez çünkü dışarı çekecek medüller osmotik güç yok edilmiştir.\",\"ar\":\"غير صحيح. ليس للفوروسيميد تأثير على الأكوابورينات؛ بل يعجز الماء عن الخروج لزوال القوة التناضحية الجاذبة في النخاع.\",\"en\":\"Incorrect. Furosemide has no activity on aquaporins; water cannot be reabsorbed because the hypertonic osmotic driving force was erased.\"}},{\"id\":\"opt-l10-s6-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Furosemid vasa rekta kapillerlerini kasıp tromboze ederek tüm medüller kan akışını kalıcı olarak durdurur.\",\"ar\":\"يقبض الفوروسيميد شعيرات الأوعية المستقيمة ويخثرها، موقفاً تدفق الدم النخاعي تماماً.\",\"en\":\"Furosemide vasoconstricts and thromboses the vasa recta capillaries, stopping all medullary blood flow permanently.\"},\"feedback\":{\"tr\":\"Yanlış. Vasa rekta tamamen açıktır; gradyanın kaybolması damar tıkanıklığından değil, aktif tuz motorunun (NKCC2) kilitlenmesindendir.\",\"ar\":\"غير صحيح. تبقى الأوعية المستقيمة سالكة؛ وينجم زوال المدروج عن شل محرك النقل الفاعل (NKCC2) لا الانسداد الوعائي.\",\"en\":\"Incorrect. The vasa recta remain fully patent. The gradient is lost because the active transport engine (NKCC2) is blocked.\"}}],\"prompt\":{\"tr\":\"Furosemid renal ters-akım çoğaltıcı mekanizmasını felç eder. NKCC2'nin bloke edilmesi, 1200 mOsm/L'lik kortikomedüller osmotik gradyanı neden tamamen yok ederek idrarı konsantre veya dilüe etme yeteneğini sıfırlar?\",\"ar\":\"يشل الفوروسيميد آلية التيار المتعاكس الكلوية. لماذا يؤدي حصر NKCC2 لتدمير المدروج التناضحي النخاعي (1200 mOsm/L) كلياً، عاجزاً الكلية عن تكثيف البول أو تمديده؟\",\"en\":\"Furosemide paralyzes the renal countercurrent multiplier. Why does blocking NKCC2 completely destroy the corticomedullary osmotic gradient (1200 mOsm/L), rendering the kidney incapable of concentrating or diluting urine?\"},\"title\":{\"tr\":\"Rehberli Keşif: Ters-Akım Çoğaltıcı Sisteminin Çöküşü\",\"ar\":\"استكشاف موجه: انهيار آلية التيار المتعاكس المضاعفة\",\"en\":\"Guided Discovery: Collapse of the Countercurrent Multiplier\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":24}]},{\"id\":\"pharm-mod5-les2-step7\",\"order\":7,\"stageIndex\":7,\"stage\":\"formal_explanation\",\"type\":\"question\",\"title\":{\"tr\":\"Biçimsel Açıklama: Diüretik Metabolik Komplikasyonları: Gut ve Alkaloz\",\"ar\":\"شرح رسمي: الاختلاطات الاستقلابية للمدرات: النقرس والقلاء\",\"en\":\"Formal Explanation: Diuretic Metabolic Complications: Gout & Alkalosis\"},\"prompt\":{\"tr\":\"Kronik kıvrım ve tiyazid diüretikleri neden sıklıkla akut hiperürisemi ve gut ataklarını tetiklerken aynı zamanda hipokalemik metabolik alkaloza yol açar?\",\"ar\":\"لماذا تثير مدرات العروة والثيازيد المزمنة فرط حمض البول وهجمات النقرس، بالتزامن مع إحداث قلاء استقلابي بنقص البوتاسيوم؟\",\"en\":\"Why do chronic loop and thiazide diuretics frequently precipitate acute hyperuricemia and gout flares, while simultaneously causing hypokalemic metabolic alkalosis?\"},\"technicalTerms\":[{\"term\":\"hipokalemik metabolik alkaloz\",\"arContext\":\"قلاء استقلابي بنقص بوتاسيوم الدم (hypokalemic metabolic alkalosis)\"},{\"term\":\"hiperürisemi\",\"arContext\":\"فرط حمض يوريك الدم (hyperuricemia)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Organik asitlerin (diüretikler ve ürik asit) proksimal tübülde nasıl atıldığını düşünün.\",\"ar\":\"فكر في كيفية إفراز الأحماض العضوية (المدرات وحمض البول) في الأنبوب القريب.\",\"en\":\"Consider how organic acids (diuretics and uric acid) are cleared in the proximal tubule.\"},{\"tier\":2,\"tr\":\"Diüretikler OAT1/3 taşıyıcılarında ürik asitle yarışır; hipovolemi ise üratın geri emilimini artırır.\",\"ar\":\"تنافس المدرات حمض البول على نواقل OAT1/3؛ ويزيد نقص الحجم ارتشاف اليورات.\",\"en\":\"Diuretics compete with urate for OAT1/3 transporters, while hypovolemia drives proximal urate reabsorption.\"},{\"tier\":3,\"tr\":\"OAT yarışması ve hacim kaybı ürik asidi kanda yükseltir (gut). Distal sodyum akışı ise toplayıcı kanallarda H+ ve K+ kaybına yol açar (alkaloz).\",\"ar\":\"يرفع تنافس OAT ونقص الحجم حمض البول (نقرس)؛ بينما يحفز تدفق الصوديوم البعيد إطراح H+ و K+ (قلاء استقلابي).\",\"en\":\"OAT competition plus hypovolemia elevates serum uric acid (gout). Meanwhile, distal Na+ delivery drives aldosterone-mediated H+ and K+ wasting (alkalosis).\"}],\"widgetType\":\"MultipleChoice\",\"conceptCheck\":{\"question\":{\"tr\":\"Diüretiklerin hiperürisemi (gut) ve hipokalemik metabolik alkaloz yapma mekanizmaları nasıldır?\",\"ar\":\"ما هي آليات إحداث المدرات لفرط حمض البول (النقرس) والقلاء الاستقلابي بنقص البوتاسيوم؟\",\"en\":\"What are the mechanisms underlying diuretic-induced hyperuricemia and hypokalemic metabolic alkalosis?\"},\"options\":[{\"id\":\"opt-l10-s7-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Diüretikler proksimal OAT1/3 salgısında ürik asitle yarışır ve hacim kaybı ürat geri emilimini artırır; distal sodyum ise K+ ve H+ atılımını hızlandırır.\",\"ar\":\"تنافس المدرات حمض البول على الإفراز عبر OAT1/3 القريب ويزيد نقص الحجم ارتشافه؛ بينما يسرع تدفق الصوديوم البعيد إطراح K+ و H+.\",\"en\":\"Diuretics compete with uric acid for proximal OAT1/3 secretion and volume depletion enhances proximal urate reabsorption; distal sodium delivery accelerates K+ and H+ secretion.\"},\"feedback\":{\"tr\":\"Doğru. Diüretikler organik asit taşıyıcılarında (OAT) ürik asitle yarışır ve hipovolemi ürik asit emilimini artırır (gut). Distal sodyum yükü ise K+ ve H+ kaybına yol açar (alkaloz).\",\"ar\":\"صحيح. تنافس المدرات حمض البول على نواقل OAT ويزيد نقص الحجم امتصاصه (نقرس). كما يقود تدفق الصوديوم لإطراح البوتاسيوم والبروتون (قلاء).\",\"en\":\"Correct. Diuretics compete with uric acid at proximal OATs; hypovolemia enhances urate reabsorption. Distal Na+ delivery drives K+ and H+ wasting.\"}},{\"id\":\"opt-l10-s7-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Tiyazid molekülleri hepatik ksantin oksidaz tarafından doğrudan ürik asit kristallerine metabolize edilir.\",\"ar\":\"تستقلب جزيئات الثيازيد مباشرة إلى بلورات حمض البول بواسطة إنزيم أوكسيداز الزانثين الكبدي.\",\"en\":\"Thiazide molecules are metabolized directly into uric acid crystals by hepatic xanthine oxidase.\"},\"feedback\":{\"tr\":\"Yanlış. Diüretikler ürik aside dönüşmez; hiperürisemi proksimal tübüler OAT atılım yarışmasından kaynaklanır.\",\"ar\":\"غير صحيح. لا تتحول المدرات لحمض البول؛ بل ينجم فرط حمض البول عن تنافس الإطراح الأنبوبي عبر نواقل OAT.\",\"en\":\"Incorrect. Diuretics do not turn into uric acid; hyperuricemia is an excretory defect via OAT competition.\"}},{\"id\":\"opt-l10-s7-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Diüretikler devasa proksimal bikarbonat salınımını uyarır ve bu da paradoksal olarak arter kanını alkalileştirir.\",\"ar\":\"تحفز المدرات إفرازاً كبيباً هائلاً للبيكربونات، مما يقلي دم الشرايين بشكل متناقض.\",\"en\":\"Diuretics stimulate massive proximal bicarbonate secretion, which paradoxically alkalizes systemic arterial blood.\"},\"feedback\":{\"tr\":\"Yanlış. Bikarbonat atılımı metabolik asidoz yapar (asetazolamid gibi). Kıvrım ve tiyazid diüretikleri ise proton kaybı ve hacim daralması ile alkaloz yapar.\",\"ar\":\"غير صحيح. طرح البيكربونات يسبب حماضاً استقلابياً (كـ أسيتازولاميد). تحدث مدرات العروة قلاءً بفقدان البروتونات وانكماش الحجم.\",\"en\":\"Incorrect. Bicarbonate wasting causes metabolic acidosis (e.g., acetazolamide). Loop and thiazide diuretics cause alkalosis via proton loss and contraction.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-l10-s7-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Diüretikler proksimal OAT1/3 salgısında ürik asitle yarışır ve hacim kaybı ürat geri emilimini artırır; distal sodyum ise K+ ve H+ atılımını hızlandırır.\",\"ar\":\"تنافس المدرات حمض البول على الإفراز عبر OAT1/3 القريب ويزيد نقص الحجم ارتشافه؛ بينما يسرع تدفق الصوديوم البعيد إطراح K+ و H+.\",\"en\":\"Diuretics compete with uric acid for proximal OAT1/3 secretion and volume depletion enhances proximal urate reabsorption; distal sodium delivery accelerates K+ and H+ secretion.\"},\"feedback\":{\"tr\":\"Doğru. Diüretikler organik asit taşıyıcılarında (OAT) ürik asitle yarışır ve hipovolemi ürik asit emilimini artırır (gut). Distal sodyum yükü ise K+ ve H+ kaybına yol açar (alkaloz).\",\"ar\":\"صحيح. تنافس المدرات حمض البول على نواقل OAT ويزيد نقص الحجم امتصاصه (نقرس). كما يقود تدفق الصوديوم لإطراح البوتاسيوم والبروتون (قلاء).\",\"en\":\"Correct. Diuretics compete with uric acid at proximal OATs; hypovolemia enhances urate reabsorption. Distal Na+ delivery drives K+ and H+ wasting.\"}},{\"id\":\"opt-l10-s7-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Tiyazid molekülleri hepatik ksantin oksidaz tarafından doğrudan ürik asit kristallerine metabolize edilir.\",\"ar\":\"تستقلب جزيئات الثيازيد مباشرة إلى بلورات حمض البول بواسطة إنزيم أوكسيداز الزانثين الكبدي.\",\"en\":\"Thiazide molecules are metabolized directly into uric acid crystals by hepatic xanthine oxidase.\"},\"feedback\":{\"tr\":\"Yanlış. Diüretikler ürik aside dönüşmez; hiperürisemi proksimal tübüler OAT atılım yarışmasından kaynaklanır.\",\"ar\":\"غير صحيح. لا تتحول المدرات لحمض البول؛ بل ينجم فرط حمض البول عن تنافس الإطراح الأنبوبي عبر نواقل OAT.\",\"en\":\"Incorrect. Diuretics do not turn into uric acid; hyperuricemia is an excretory defect via OAT competition.\"}},{\"id\":\"opt-l10-s7-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Diüretikler devasa proksimal bikarbonat salınımını uyarır ve bu da paradoksal olarak arter kanını alkalileştirir.\",\"ar\":\"تحفز المدرات إفرازاً كبيباً هائلاً للبيكربونات، مما يقلي دم الشرايين بشكل متناقض.\",\"en\":\"Diuretics stimulate massive proximal bicarbonate secretion, which paradoxically alkalizes systemic arterial blood.\"},\"feedback\":{\"tr\":\"Yanlış. Bikarbonat atılımı metabolik asidoz yapar (asetazolamid gibi). Kıvrım ve tiyazid diüretikleri ise proton kaybı ve hacim daralması ile alkaloz yapar.\",\"ar\":\"غير صحيح. طرح البيكربونات يسبب حماضاً استقلابياً (كـ أسيتازولاميد). تحدث مدرات العروة قلاءً بفقدان البروتونات وانكماش الحجم.\",\"en\":\"Incorrect. Bicarbonate wasting causes metabolic acidosis (e.g., acetazolamide). Loop and thiazide diuretics cause alkalosis via proton loss and contraction.\"}}],\"prompt\":{\"tr\":\"Kronik kıvrım ve tiyazid diüretikleri neden sıklıkla akut hiperürisemi ve gut ataklarını tetiklerken aynı zamanda hipokalemik metabolik alkaloza yol açar?\",\"ar\":\"لماذا تثير مدرات العروة والثيازيد المزمنة فرط حمض البول وهجمات النقرس، بالتزامن مع إحداث قلاء استقلابي بنقص البوتاسيوم؟\",\"en\":\"Why do chronic loop and thiazide diuretics frequently precipitate acute hyperuricemia and gout flares, while simultaneously causing hypokalemic metabolic alkalosis?\"},\"title\":{\"tr\":\"Biçimsel Açıklama: Diüretik Metabolik Komplikasyonları: Gut ve Alkaloz\",\"ar\":\"شرح رسمي: الاختلاطات الاستقلابية للمدرات: النقرس والقلاء\",\"en\":\"Formal Explanation: Diuretic Metabolic Complications: Gout & Alkalosis\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":25}]},{\"id\":\"pharm-mod5-les2-step8\",\"order\":8,\"stageIndex\":8,\"stage\":\"concept_check\",\"type\":\"question\",\"title\":{\"tr\":\"Kavram Kontrolü: Furosemid ve Digoksin Ölümcül Aritmi Tuzağı\",\"ar\":\"تحقق مفاهيمي: فخ اضطراب النظم المميت بين فوروسيميد وديجوكسين\",\"en\":\"Concept Check: The Furosemide-Digoxin Lethal Arrhythmia Trap\"},\"prompt\":{\"tr\":\"Digoksin kullanan bir kalp yetmezliği hastasına potasyum desteği verilmeden yüksek doz furosemid başlanıyor. Günler içinde ventriküler bigemini ve ölümcül fibrilasyon gelişiyor. Hangi moleküler mekanizma bu aritmiyi tetikledi?\",\"ar\":\"بدأ مريض قصور قلب يعالج بالديجوكسين فوروسيميد عالي الجرعة دون تعويض البوتاسيوم. وخلال أيام حدث توأمية بطينية ورجفان مميت. ما الآلية الجزيئية المحفزة؟\",\"en\":\"A heart failure patient receiving digoxin is started on high-dose furosemide without potassium supplementation. Within days, ventricular bigeminy and fatal fibrillation occur. What molecular mechanism triggered this arrhythmia?\"},\"conceptCheck\":{\"question\":{\"tr\":\"Furosemid kaynaklı hipokalemi digoksin toksisitesini ve fatal aritmileri moleküler olarak nasıl tetikler?\",\"ar\":\"كيف يحفز نقص البوتاسيوم الناجم عن فوروسيميد سمية الديجوكسين واضطرابات النظم المميتة؟\",\"en\":\"How does furosemide-induced hypokalemia molecularly precipitate digoxin toxicity and fatal arrhythmias?\"},\"options\":[{\"id\":\"opt-l10-s8-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Furosemid kaynaklı hipokalemi, kardiyak Na+/K+-ATPazın ekstraselüler bölgesindeki potasyum yarışmasını kaldırır; digoksin bağlanmasını, toksisitesini ve ölümcül ard-depolarizasyonları aşırı artırır.\",\"ar\":\"يزيل نقص البوتاسيوم الناجم عن الفوروسيميد التنافس على الموقع الخارجي لمضخة Na+/K+ القلبية، مضاعفاً ارتباط الديجوكسين وسميته واضطرابات النظم.\",\"en\":\"Furosemide-induced hypokalemia removes potassium competition at the extracellular binding site of cardiac Na+/K+-ATPase, massively potentiating digoxin binding, toxicity, and triggered afterdepolarizations.\"},\"feedback\":{\"tr\":\"Doğru. Potasyum ve digoksin Na+/K+-ATPaz üzerindeki aynı ekstraselüler cep için yarışır. Hipokalemi koruyucu kalkanı kaldırır; terapötik digoksin seviyesi bile ölümcül kalsiyum yüklenmesine yol açar.\",\"ar\":\"صحيح. يتنافس البوتاسيوم والديجوكسين على نفس الجيب الخارجي للمضخة. يزيل نقص البوتاسيوم الحماية، مما يجعل الجرعات العلاجية سامة وقاتلة بتراكم الكالسيوم.\",\"en\":\"Correct. Extracellular potassium and digoxin compete for the same binding site on Na+/K+-ATPase. Hypokalemia removes competition, precipitating toxic calcium overload.\"}},{\"id\":\"opt-l10-s8-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Furosemid, renal digoksin salgısını durduran, serum digoksin konsantrasyonunu 10 kat artıran güçlü bir P-glikoprotein inhibitörüdür.\",\"ar\":\"الفوروسيميد مثبط قوي لبروتين P السكري يوقف إفراز الديجوكسين الكلوي، مضاعفاً تركيزه 10 أضعاف.\",\"en\":\"Furosemide is a potent P-glycoprotein inhibitor that halts renal digoxin secretion, multiplying serum digoxin concentrations 10-fold.\"},\"feedback\":{\"tr\":\"Yanlış. Furosemid P-glikoproteini inhibe etmez (amiodaron ve kinidin eder). Aritmi kan düzeyinden değil, hipokalemi kaynaklı farmakodinamik duyarlılıktan kaynaklanır.\",\"ar\":\"غير صحيح. لا يثبط فوروسيميد بروتين P السكري (بل يفعل ذلك كينيدين وأميودارون). ينجم التسمم عن حساسية ديناميكية دوائية بنقص البوتاسيوم.\",\"en\":\"Incorrect. Furosemide does not inhibit P-glycoprotein; the arrhythmia is driven by pharmacodynamic hypokalemia, not elevated drug levels.\"}},{\"id\":\"opt-l10-s8-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Furosemid ventriküler miyositlere girerek hızlı sodyum kanallarını doğrudan açar ve aksiyon potansiyelini uzatır.\",\"ar\":\"يعبر الفوروسيميد للخلايا البطينية فاتحاً قنوات الصوديوم السريعة مباشرة ومطولاً كمون العمل.\",\"en\":\"Furosemide crosses into ventricular myocytes and directly opens fast sodium channels, prolonging action potentials.\"},\"feedback\":{\"tr\":\"Yanlış. Furosemidin kardiyak hızlı sodyum kanalları üzerinde hiçbir doğrudan etkisi yoktur; toksisite tamamen hipokalemi kaynaklıdır.\",\"ar\":\"غير صحيح. ليس للفوروسيميد تأثير مباشر على قنوات الصوديوم القلبية؛ بل السمية ناجمة حصراً عن استنزاف البوتاسيوم الخارجي.\",\"en\":\"Incorrect. Furosemide has no direct action on cardiac sodium channels; toxicity is purely mediated by extracellular potassium depletion.\"}}]},\"technicalTerms\":[{\"term\":\"digoksin toksisitesi\",\"arContext\":\"سمية الديجوكسين (digoxin toxicity)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Digoksinin hedef enzimine bakın: kardiyak miyosit membranındaki Na+/K+-ATPaz pompası.\",\"ar\":\"انتبه للإنزيم المستهدف بالديجوكسين: مضخة Na+/K+-ATPase في غشاء الخلية القلبية.\",\"en\":\"Look at the target enzyme of digoxin: the cardiac sarcolemmal Na+/K+-ATPase pump.\"},{\"tier\":2,\"tr\":\"Ekstraselüler ortamda digoksin ile hangi fizyolojik katyon aynı bağlanma cebi için yarışır?\",\"ar\":\"أي كاتيون فسيولوجي ينافس الديجوكسين على جيب الارتباط الخارجي للمضخة؟\",\"en\":\"What physiological cation competes with digoxin for the extracellular binding pocket on the pump?\"},{\"tier\":3,\"tr\":\"Ekstraselüler K+ digoksinle yarışır. Furosemid hipokalemi yaptığında yarışma biter; digoksin aşırı bağlanarak hücre içi kalsiyum patlamasına ve ölümcül aritmiye yol açar.\",\"ar\":\"ينافس البوتاسيوم الديجوكسين. عند حدوث نقص البوتاسيوم بفوروسيميد، يرتبط الديجوكسين دون منازع مسبباً فرط الكالسيوم القاتل واضطراب النظم.\",\"en\":\"Extracellular K+ competes with digoxin for the Na+/K+-ATPase. When furosemide causes hypokalemia, digoxin binds unopposed, triggering toxic calcium overload and arrhythmias.\"}],\"widgetType\":\"MultipleChoice\",\"config\":{\"options\":[{\"id\":\"opt-l10-s8-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Furosemid kaynaklı hipokalemi, kardiyak Na+/K+-ATPazın ekstraselüler bölgesindeki potasyum yarışmasını kaldırır; digoksin bağlanmasını, toksisitesini ve ölümcül ard-depolarizasyonları aşırı artırır.\",\"ar\":\"يزيل نقص البوتاسيوم الناجم عن الفوروسيميد التنافس على الموقع الخارجي لمضخة Na+/K+ القلبية، مضاعفاً ارتباط الديجوكسين وسميته واضطرابات النظم.\",\"en\":\"Furosemide-induced hypokalemia removes potassium competition at the extracellular binding site of cardiac Na+/K+-ATPase, massively potentiating digoxin binding, toxicity, and triggered afterdepolarizations.\"},\"feedback\":{\"tr\":\"Doğru. Potasyum ve digoksin Na+/K+-ATPaz üzerindeki aynı ekstraselüler cep için yarışır. Hipokalemi koruyucu kalkanı kaldırır; terapötik digoksin seviyesi bile ölümcül kalsiyum yüklenmesine yol açar.\",\"ar\":\"صحيح. يتنافس البوتاسيوم والديجوكسين على نفس الجيب الخارجي للمضخة. يزيل نقص البوتاسيوم الحماية، مما يجعل الجرعات العلاجية سامة وقاتلة بتراكم الكالسيوم.\",\"en\":\"Correct. Extracellular potassium and digoxin compete for the same binding site on Na+/K+-ATPase. Hypokalemia removes competition, precipitating toxic calcium overload.\"}},{\"id\":\"opt-l10-s8-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Furosemid, renal digoksin salgısını durduran, serum digoksin konsantrasyonunu 10 kat artıran güçlü bir P-glikoprotein inhibitörüdür.\",\"ar\":\"الفوروسيميد مثبط قوي لبروتين P السكري يوقف إفراز الديجوكسين الكلوي، مضاعفاً تركيزه 10 أضعاف.\",\"en\":\"Furosemide is a potent P-glycoprotein inhibitor that halts renal digoxin secretion, multiplying serum digoxin concentrations 10-fold.\"},\"feedback\":{\"tr\":\"Yanlış. Furosemid P-glikoproteini inhibe etmez (amiodaron ve kinidin eder). Aritmi kan düzeyinden değil, hipokalemi kaynaklı farmakodinamik duyarlılıktan kaynaklanır.\",\"ar\":\"غير صحيح. لا يثبط فوروسيميد بروتين P السكري (بل يفعل ذلك كينيدين وأميودارون). ينجم التسمم عن حساسية ديناميكية دوائية بنقص البوتاسيوم.\",\"en\":\"Incorrect. Furosemide does not inhibit P-glycoprotein; the arrhythmia is driven by pharmacodynamic hypokalemia, not elevated drug levels.\"}},{\"id\":\"opt-l10-s8-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Furosemid ventriküler miyositlere girerek hızlı sodyum kanallarını doğrudan açar ve aksiyon potansiyelini uzatır.\",\"ar\":\"يعبر الفوروسيميد للخلايا البطينية فاتحاً قنوات الصوديوم السريعة مباشرة ومطولاً كمون العمل.\",\"en\":\"Furosemide crosses into ventricular myocytes and directly opens fast sodium channels, prolonging action potentials.\"},\"feedback\":{\"tr\":\"Yanlış. Furosemidin kardiyak hızlı sodyum kanalları üzerinde hiçbir doğrudan etkisi yoktur; toksisite tamamen hipokalemi kaynaklıdır.\",\"ar\":\"غير صحيح. ليس للفوروسيميد تأثير مباشر على قنوات الصوديوم القلبية؛ بل السمية ناجمة حصراً عن استنزاف البوتاسيوم الخارجي.\",\"en\":\"Incorrect. Furosemide has no direct action on cardiac sodium channels; toxicity is purely mediated by extracellular potassium depletion.\"}}],\"prompt\":{\"tr\":\"Digoksin kullanan bir kalp yetmezliği hastasına potasyum desteği verilmeden yüksek doz furosemid başlanıyor. Günler içinde ventriküler bigemini ve ölümcül fibrilasyon gelişiyor. Hangi moleküler mekanizma bu aritmiyi tetikledi?\",\"ar\":\"بدأ مريض قصور قلب يعالج بالديجوكسين فوروسيميد عالي الجرعة دون تعويض البوتاسيوم. وخلال أيام حدث توأمية بطينية ورجفان مميت. ما الآلية الجزيئية المحفزة؟\",\"en\":\"A heart failure patient receiving digoxin is started on high-dose furosemide without potassium supplementation. Within days, ventricular bigeminy and fatal fibrillation occur. What molecular mechanism triggered this arrhythmia?\"},\"title\":{\"tr\":\"Kavram Kontrolü: Furosemid ve Digoksin Ölümcül Aritmi Tuzağı\",\"ar\":\"تحقق مفاهيمي: فخ اضطراب النظم المميت بين فوروسيميد وديجوكسين\",\"en\":\"Concept Check: The Furosemide-Digoxin Lethal Arrhythmia Trap\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":26}]},{\"id\":\"pharm-mod5-les2-step9\",\"order\":9,\"stageIndex\":9,\"stage\":\"application\",\"type\":\"question\",\"title\":{\"tr\":\"Klinik Vaka: İleri Böbrek Yetmezliğinde Tiyazid Yetersizliği ve Kıvrım Zorunluluğu\",\"ar\":\"حالة سريرية: عجز الثيازيد في القصور الكلوي وإلزامية مدرات العروة\",\"en\":\"Clinical Vignette: Renal Failure: Thiazide Inefficacy vs High-Ceiling Loops\"},\"prompt\":{\"tr\":\"eGFR'si 22 mL/dak'ya gerileyen diyabetik nefropati hastasında, hidroklorotiyazid maksimum doza çıkılmasına rağmen dirençli sıvı retansiyonu görülür. Tiyazidler neden etkisizdir ve hangi tedavi değişikliği zorunludur?\",\"ar\":\"أصيب مريض اعتلال كلى سكري تراجع GFR لديه لـ 22 مل/د باحتباس سوائل معند رغم رفع هيدروكلوروثيازيد للحد الأقصى. لماذا تفشل الثيازيدات وما التعديل الإلزامي؟\",\"en\":\"A diabetic nephropathy patient whose eGFR declines to 22 mL/min exhibits refractory fluid retention despite increasing hydrochlorothiazide to maximum dose. Why are thiazides ineffective, and what therapeutic adjustment is mandatory?\"},\"conceptCheck\":{\"question\":{\"tr\":\"eGFR < 30 mL/dak olan hastalarda tiyazidlerin etkisiz kalma nedeni ve klinik çözüm nedir?\",\"ar\":\"ما سبب عجز الثيازيد حين يقل GFR عن 30 مل/د وما هو الحل السريري؟\",\"en\":\"Why do thiazides lose efficacy when eGFR falls below 30 mL/min, and what is the clinical solution?\"},\"options\":[{\"id\":\"opt-l10-s9-1\",\"isCorrect\":true,\"text\":{\"tr\":\"eGFR < 30 mL/dak olduğunda yetersiz distal sodyum iletimi nedeniyle tiyazidler etkisini kaybeder; tedavi yüksek tavanlı bir kıvrım diüretiğine (furosemid, torsemid) geçirilmelidir.\",\"ar\":\"تفقد الثيازيدات فعاليتها حين ينخفض GFR دون 30 مل/د لعدم كفاية الصوديوم الواصل للأنابيب البعيدة؛ ويجب الانتقال لمدرات العروة عالية الفعالية (فوروسيميد، تورسيميد).\",\"en\":\"Thiazides lose efficacy when eGFR < 30 mL/min due to inadequate distal sodium delivery; therapy must transition to a high-ceiling loop diuretic (e.g., furosemide, torsemide).\"},\"feedback\":{\"tr\":\"Doğru. Tiyazidlerin etkili olması için yeterli filtrasyon (eGFR > 30 mL/dak) gerekir. 30'un altında distal sodyum yetersiz kalır ve yüksek tavanlı kıvrım diüretiklerine geçiş zorunludur.\",\"ar\":\"صحيح. تتطلب الثيازيدات رشحاً كافياً (>30 مل/د) للوصول لموقع عملها؛ ودون ذلك يجب التحول فوراً لمدرات العروة عالية الفعالية.\",\"en\":\"Correct. Thiazides require adequate GFR (>30 mL/min) for distal delivery. When eGFR < 30 mL/min, high-ceiling loop diuretics are mandatory.\"}},{\"id\":\"opt-l10-s9-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Hidroklorotiyazidi, glomerüler filtrasyondan bağımsız etki eden yüksek doz spironolakton monoterapisine geçirin.\",\"ar\":\"استبدل هيدروكلوروثيازيد بجرعة عالية من سبيرونولاكتون كعلاج وحيد يعمل باستقلال عن الرشح الكبيبي.\",\"en\":\"Switch hydrochlorothiazide to high-dose spironolactone monotherapy, which acts independently of glomerular filtration.\"},\"feedback\":{\"tr\":\"Yanlış. eGFR < 30 mL/dak olan hastada spironolakton monoterapisi zayıf bir natriüretiktir ve ölümcül hiperkalemi riski taşır.\",\"ar\":\"غير صحيح. سبيرونولاكتون مدر ضعيف للصوديوم، ويشكل خطراً مميتاً لفرط البوتاسيوم في مرضى قصور الكلى الشديد.\",\"en\":\"Incorrect. Spironolactone monotherapy is a weak natriuretic and poses an extreme risk of fatal hyperkalemia in patients with eGFR < 30 mL/min.\"}},{\"id\":\"opt-l10-s9-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Hastalıklı böbrek, hidroklorotiyazidi aktif serbest sülfonamid formuna enzimatik olarak hidroksilleyemez.\",\"ar\":\"تعجز الكلى المصابة عن هدرجة هيدروكلوروثيازيد إنزيمياً إلى شكله النشط من السلفوناميد الحر.\",\"en\":\"The diseased kidney fails to enzymatically hydroxylate hydrochlorothiazide into its active free sulfonamide form.\"},\"feedback\":{\"tr\":\"Yanlış. Hidroklorotiyazid ön-ilaç değildir ve böbrekte metabolize edilmez; başarısızlık tamamen hemodinamik yetersizliktendir.\",\"ar\":\"غير صحيح. هيدروكلوروثيازيد دواء نشط بذاته ولا يحتاج استقلاباً كلوياً؛ بل الفشل ناتج عن نقص الحمل الهيدروديناميكي الواصل للأنبوب.\",\"en\":\"Incorrect. Hydrochlorothiazide is active parent drug; failure is purely hemodynamic due to insufficient filtration.\"}}]},\"technicalTerms\":[{\"term\":\"diüretik direnci\",\"arContext\":\"مقاومة مدرات البول (diuretic resistance)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Tiyazid diüretikleri için kritik eGFR eşiğini hatırlayın: 30 mL/dak.\",\"ar\":\"تذكر عتبة GFR الحرجة لفعالية مدرات الثيازيد: 30 مل/دقيقة.\",\"en\":\"Recall the critical eGFR threshold for thiazide diuretics: 30 mL/min.\"},{\"tier\":2,\"tr\":\"Glomerüler filtrasyon ciddi şekilde düştüğünde, distal kıvrımlı tübüle tiyazidlerin etki edebileceği kadar sodyum ulaşabilir mi?\",\"ar\":\"عند هبوط الرشح بشدة، هل يصل صوديوم كافٍ للأنبوب البعيد لتعمل عليه الثيازيدات؟\",\"en\":\"When GFR is severely reduced, does enough sodium reach the distal tubule for thiazides to work?\"},{\"tier\":3,\"tr\":\"eGFR < 30 mL/dak olduğunda yetersiz sodyum iletimi nedeniyle tiyazidler çalışmaz; tedavi yüksek tavanlı bir kıvrım diüretiğine (furosemid) geçirilmelidir.\",\"ar\":\"حين يقل GFR عن 30 مل/د تفقد الثيازيدات فعاليتها لقلة الصوديوم الواصل؛ ويجب الانتقال لمدرات العروة عالية الفعالية مثل فوروسيميد.\",\"en\":\"Thiazides fail when eGFR < 30 mL/min due to inadequate distal sodium delivery; transitioning to a high-ceiling loop diuretic (furosemide) is mandatory.\"}],\"widgetType\":\"MultipleChoice\",\"config\":{\"options\":[{\"id\":\"opt-l10-s9-1\",\"isCorrect\":true,\"text\":{\"tr\":\"eGFR < 30 mL/dak olduğunda yetersiz distal sodyum iletimi nedeniyle tiyazidler etkisini kaybeder; tedavi yüksek tavanlı bir kıvrım diüretiğine (furosemid, torsemid) geçirilmelidir.\",\"ar\":\"تفقد الثيازيدات فعاليتها حين ينخفض GFR دون 30 مل/د لعدم كفاية الصوديوم الواصل للأنابيب البعيدة؛ ويجب الانتقال لمدرات العروة عالية الفعالية (فوروسيميد، تورسيميد).\",\"en\":\"Thiazides lose efficacy when eGFR < 30 mL/min due to inadequate distal sodium delivery; therapy must transition to a high-ceiling loop diuretic (e.g., furosemide, torsemide).\"},\"feedback\":{\"tr\":\"Doğru. Tiyazidlerin etkili olması için yeterli filtrasyon (eGFR > 30 mL/dak) gerekir. 30'un altında distal sodyum yetersiz kalır ve yüksek tavanlı kıvrım diüretiklerine geçiş zorunludur.\",\"ar\":\"صحيح. تتطلب الثيازيدات رشحاً كافياً (>30 مل/د) للوصول لموقع عملها؛ ودون ذلك يجب التحول فوراً لمدرات العروة عالية الفعالية.\",\"en\":\"Correct. Thiazides require adequate GFR (>30 mL/min) for distal delivery. When eGFR < 30 mL/min, high-ceiling loop diuretics are mandatory.\"}},{\"id\":\"opt-l10-s9-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Hidroklorotiyazidi, glomerüler filtrasyondan bağımsız etki eden yüksek doz spironolakton monoterapisine geçirin.\",\"ar\":\"استبدل هيدروكلوروثيازيد بجرعة عالية من سبيرونولاكتون كعلاج وحيد يعمل باستقلال عن الرشح الكبيبي.\",\"en\":\"Switch hydrochlorothiazide to high-dose spironolactone monotherapy, which acts independently of glomerular filtration.\"},\"feedback\":{\"tr\":\"Yanlış. eGFR < 30 mL/dak olan hastada spironolakton monoterapisi zayıf bir natriüretiktir ve ölümcül hiperkalemi riski taşır.\",\"ar\":\"غير صحيح. سبيرونولاكتون مدر ضعيف للصوديوم، ويشكل خطراً مميتاً لفرط البوتاسيوم في مرضى قصور الكلى الشديد.\",\"en\":\"Incorrect. Spironolactone monotherapy is a weak natriuretic and poses an extreme risk of fatal hyperkalemia in patients with eGFR < 30 mL/min.\"}},{\"id\":\"opt-l10-s9-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Hastalıklı böbrek, hidroklorotiyazidi aktif serbest sülfonamid formuna enzimatik olarak hidroksilleyemez.\",\"ar\":\"تعجز الكلى المصابة عن هدرجة هيدروكلوروثيازيد إنزيمياً إلى شكله النشط من السلفوناميد الحر.\",\"en\":\"The diseased kidney fails to enzymatically hydroxylate hydrochlorothiazide into its active free sulfonamide form.\"},\"feedback\":{\"tr\":\"Yanlış. Hidroklorotiyazid ön-ilaç değildir ve böbrekte metabolize edilmez; başarısızlık tamamen hemodinamik yetersizliktendir.\",\"ar\":\"غير صحيح. هيدروكلوروثيازيد دواء نشط بذاته ولا يحتاج استقلاباً كلوياً؛ بل الفشل ناتج عن نقص الحمل الهيدروديناميكي الواصل للأنبوب.\",\"en\":\"Incorrect. Hydrochlorothiazide is active parent drug; failure is purely hemodynamic due to insufficient filtration.\"}}],\"prompt\":{\"tr\":\"eGFR'si 22 mL/dak'ya gerileyen diyabetik nefropati hastasında, hidroklorotiyazid maksimum doza çıkılmasına rağmen dirençli sıvı retansiyonu görülür. Tiyazidler neden etkisizdir ve hangi tedavi değişikliği zorunludur?\",\"ar\":\"أصيب مريض اعتلال كلى سكري تراجع GFR لديه لـ 22 مل/د باحتباس سوائل معند رغم رفع هيدروكلوروثيازيد للحد الأقصى. لماذا تفشل الثيازيدات وما التعديل الإلزامي؟\",\"en\":\"A diabetic nephropathy patient whose eGFR declines to 22 mL/min exhibits refractory fluid retention despite increasing hydrochlorothiazide to maximum dose. Why are thiazides ineffective, and what therapeutic adjustment is mandatory?\"},\"title\":{\"tr\":\"Klinik Vaka: İleri Böbrek Yetmezliğinde Tiyazid Yetersizliği ve Kıvrım Zorunluluğu\",\"ar\":\"حالة سريرية: عجز الثيازيد في القصور الكلوي وإلزامية مدرات العروة\",\"en\":\"Clinical Vignette: Renal Failure: Thiazide Inefficacy vs High-Ceiling Loops\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":27}]},{\"id\":\"pharm-mod5-les2-step10\",\"order\":10,\"stageIndex\":10,\"stage\":\"retrieval\",\"type\":\"question\",\"title\":{\"tr\":\"Geri Çağırma: Furosemid Ototoksisitesi ve Spironolakton Jinekomastisi\",\"ar\":\"استرجاع: سمية فوروسيميد السمعية وتثدي سبيرونولاكتون\",\"en\":\"Retrieval: Furosemide Ototoxicity vs Spironolactone Gynecomastia\"},\"prompt\":{\"tr\":\"Furosemid kaynaklı ototoksisite (tinnitus, sensörinöral sağırlık) ve spironolakton kaynaklı ağrılı jinekomastiyi hangi moleküler mekanizmalar açıklar?\",\"ar\":\"ما الآليتان الجزيئيتان المفسرتان للسمية السمعية الناجمة عن فوروسيميد (طنين، صمم عصبي) والتثدي المؤلم الناجم عن سبيرونولاكتون؟\",\"en\":\"Which molecular transport mechanisms account for furosemide-induced ototoxicity (tinnitus, sensorineural deafness) and spironolactone-induced painful gynecomastia?\"},\"technicalTerms\":[{\"term\":\"ototoksisite\",\"arContext\":\"السمية السمعية (ototoxicity)\"},{\"term\":\"jinekomasti\",\"arContext\":\"تثدي الرجل (gynecomastia)\"}],\"hints\":[{\"tier\":1,\"tr\":\"İç kulakta bulunan Na-K-2Cl kotransportörünün böbrek dışı izoformunu (NKCC1) düşünün.\",\"ar\":\"فكر في النمط الإنزيمي لناقل Na-K-2Cl الموجود في الأذن الداخلية (NKCC1).\",\"en\":\"Consider the non-renal isoform of the Na-K-2Cl cotransporter in the inner ear: NKCC1.\"},{\"tier\":2,\"tr\":\"Spironolakton, diğer nükleer steroid hormon reseptörleriyle çapraz reaksiyona giren steroid halkalı bir yapıya sahiptir.\",\"ar\":\"يمتلك سبيرونولاكتون بنية ستيرويدية تتفاعل تصالبياً مع مستقبلات الهرمونات الجنسية الأخرى.\",\"en\":\"Spironolactone possesses a steroid nucleus that cross-reacts with nuclear sex hormone receptors.\"},{\"tier\":3,\"tr\":\"Furosemid iç kulak stria vaskülaristeki NKCC1'i bloke ederek endolenf potansiyelini bozar. Spironolakton ise androjen reseptörlerini bloke ederek jinekomasti yapar (eplerenon selektiftir).\",\"ar\":\"يحصر فوروسيميد NKCC1 في السرة الوعائية للأذن معطلاً كمون اللمف الداخلي؛ ويحصر سبيرونولاكتون مستقبلات الأندروجين مسبباً التثدي (إبليرينون انتقائي).\",\"en\":\"Furosemide blocks NKCC1 in the stria vascularis, impairing endolymph generation. Spironolactone cross-reacts with androgen receptors, causing gynecomastia.\"}],\"widgetType\":\"MultipleChoice\",\"conceptCheck\":{\"question\":{\"tr\":\"Furosemidin iç kulak ototoksisitesi ve spironolaktonun jinekomasti yapmasının moleküler mekanizmaları nelerdir?\",\"ar\":\"ما الآليتان الجزيئيتان لإحداث فوروسيميد للسمية السمعية وسبيرونولاكتون للتثدي؟\",\"en\":\"What are the molecular mechanisms of furosemide ototoxicity and spironolactone-induced gynecomastia?\"},\"options\":[{\"id\":\"opt-l10-s10-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Furosemid iç kulak stria vaskülaristeki NKCC1'i inhibe eder (endolenf potansiyelini bozar); spironolakton ise androjen reseptörlerini non-selektif bloke ederek jinekomasti yapar.\",\"ar\":\"يثبط فوروسيميد NKCC1 في السرة الوعائية للأذن الداخلية (معطلاً كمون اللمف الداخلي)؛ بينما يحصر سبيرونولاكتون مستقبلات الأندروجين مسبباً التثدي.\",\"en\":\"Furosemide inhibits inner ear stria vascularis NKCC1 (disrupting endolymph potential); spironolactone non-selectively antagonizes androgen receptors and inhibits 17beta-hydroxysteroid dehydrogenase (causing gynecomastia).\"},\"feedback\":{\"tr\":\"Doğru. Furosemid iç kulaktaki NKCC1'i bloke ederek endolenf elektrolit dengesini bozar ve ototoksisite yapar. Spironolakton androjen reseptörlerini antagonize edip jinekomastiye yol açar.\",\"ar\":\"صحيح. يحصر فوروسيميد NKCC1 في الأذن الداخلية معطلاً شوارد اللمف الداخلي والسمع؛ بينما يحصر سبيرونولاكتون مستقبلات الأندروجين مسبباً التثدي.\",\"en\":\"Correct. Furosemide blocks NKCC1 in inner ear stria vascularis, abolishing endocochlear potential. Spironolactone cross-reacts with androgen receptors.\"}},{\"id\":\"opt-l10-s10-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Furosemid koklear tüy hücrelerini kalsifiye eder; spironolakton aromatazı aktive ederek meme dokusunda östrojen sentezini uyarır.\",\"ar\":\"يكلس فوروسيميد الخلايا الشعرية القوقعية؛ بينما ينشط سبيرونولاكتون اصطناع الإستروجين بتفعيل الأروماتاز.\",\"en\":\"Furosemide calcifies cochlear hair cells; spironolactone stimulates breast tissue estrogen synthesis via aromatase activation.\"},\"feedback\":{\"tr\":\"Yanlış. Furosemid ototoksisitesi kalsifikasyondan değil, stria vaskülaristeki NKCC1 blokajındandır. Spironolakton ise androjen reseptör blokajı yapar.\",\"ar\":\"غير صحيح. السمية السمعية ناتجة عن حصر NKCC1 في السرة الوعائية لا التكلس؛ والتثدي ناجم عن حصر مستقبلات الأندروجين.\",\"en\":\"Incorrect. Ototoxicity stems from NKCC1 inhibition altering endolymph K+; gynecomastia stems from androgen receptor blockade.\"}},{\"id\":\"opt-l10-s10-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Şiddetli sistemik hiperkalemi işitsel tüy hücrelerini depolarize eder ve hipofizden prolaktin salınımını uyarır.\",\"ar\":\"يؤدي فرط البوتاسيوم الجهازي الشديد لفرط استقطاب الخلايا السمعية وتحفيز إفراز البرولاكتين النخامي.\",\"en\":\"Severe systemic hyperkalemia depolarizes auditory hair cells and stimulates pituitary prolactin release.\"},\"feedback\":{\"tr\":\"Yanlış. Furosemid hiperkalemi değil hipokalemi yapar. Her iki toksisite de elektrolit seviyesinden bağımsız doğrudan moleküler etkilerdir.\",\"ar\":\"غير صحيح. يسبب فوروسيميد نقص البوتاسيوم لا فرطه. كلا الأثرين الجانبيين ناجمان عن أهداف جزيئية مباشرة خارج الكلية.\",\"en\":\"Incorrect. Furosemide causes hypokalemia, not hyperkalemia. Both toxicities are off-target molecular receptor/transporter effects.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-l10-s10-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Furosemid iç kulak stria vaskülaristeki NKCC1'i inhibe eder (endolenf potansiyelini bozar); spironolakton ise androjen reseptörlerini non-selektif bloke ederek jinekomasti yapar.\",\"ar\":\"يثبط فوروسيميد NKCC1 في السرة الوعائية للأذن الداخلية (معطلاً كمون اللمف الداخلي)؛ بينما يحصر سبيرونولاكتون مستقبلات الأندروجين مسبباً التثدي.\",\"en\":\"Furosemide inhibits inner ear stria vascularis NKCC1 (disrupting endolymph potential); spironolactone non-selectively antagonizes androgen receptors and inhibits 17beta-hydroxysteroid dehydrogenase (causing gynecomastia).\"},\"feedback\":{\"tr\":\"Doğru. Furosemid iç kulaktaki NKCC1'i bloke ederek endolenf elektrolit dengesini bozar ve ototoksisite yapar. Spironolakton androjen reseptörlerini antagonize edip jinekomastiye yol açar.\",\"ar\":\"صحيح. يحصر فوروسيميد NKCC1 في الأذن الداخلية معطلاً شوارد اللمف الداخلي والسمع؛ بينما يحصر سبيرونولاكتون مستقبلات الأندروجين مسبباً التثدي.\",\"en\":\"Correct. Furosemide blocks NKCC1 in inner ear stria vascularis, abolishing endocochlear potential. Spironolactone cross-reacts with androgen receptors.\"}},{\"id\":\"opt-l10-s10-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Furosemid koklear tüy hücrelerini kalsifiye eder; spironolakton aromatazı aktive ederek meme dokusunda östrojen sentezini uyarır.\",\"ar\":\"يكلس فوروسيميد الخلايا الشعرية القوقعية؛ بينما ينشط سبيرونولاكتون اصطناع الإستروجين بتفعيل الأروماتاز.\",\"en\":\"Furosemide calcifies cochlear hair cells; spironolactone stimulates breast tissue estrogen synthesis via aromatase activation.\"},\"feedback\":{\"tr\":\"Yanlış. Furosemid ototoksisitesi kalsifikasyondan değil, stria vaskülaristeki NKCC1 blokajındandır. Spironolakton ise androjen reseptör blokajı yapar.\",\"ar\":\"غير صحيح. السمية السمعية ناتجة عن حصر NKCC1 في السرة الوعائية لا التكلس؛ والتثدي ناجم عن حصر مستقبلات الأندروجين.\",\"en\":\"Incorrect. Ototoxicity stems from NKCC1 inhibition altering endolymph K+; gynecomastia stems from androgen receptor blockade.\"}},{\"id\":\"opt-l10-s10-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Şiddetli sistemik hiperkalemi işitsel tüy hücrelerini depolarize eder ve hipofizden prolaktin salınımını uyarır.\",\"ar\":\"يؤدي فرط البوتاسيوم الجهازي الشديد لفرط استقطاب الخلايا السمعية وتحفيز إفراز البرولاكتين النخامي.\",\"en\":\"Severe systemic hyperkalemia depolarizes auditory hair cells and stimulates pituitary prolactin release.\"},\"feedback\":{\"tr\":\"Yanlış. Furosemid hiperkalemi değil hipokalemi yapar. Her iki toksisite de elektrolit seviyesinden bağımsız doğrudan moleküler etkilerdir.\",\"ar\":\"غير صحيح. يسبب فوروسيميد نقص البوتاسيوم لا فرطه. كلا الأثرين الجانبيين ناجمان عن أهداف جزيئية مباشرة خارج الكلية.\",\"en\":\"Incorrect. Furosemide causes hypokalemia, not hyperkalemia. Both toxicities are off-target molecular receptor/transporter effects.\"}}],\"prompt\":{\"tr\":\"Furosemid kaynaklı ototoksisite (tinnitus, sensörinöral sağırlık) ve spironolakton kaynaklı ağrılı jinekomastiyi hangi moleküler mekanizmalar açıklar?\",\"ar\":\"ما الآليتان الجزيئيتان المفسرتان للسمية السمعية الناجمة عن فوروسيميد (طنين، صمم عصبي) والتثدي المؤلم الناجم عن سبيرونولاكتون؟\",\"en\":\"Which molecular transport mechanisms account for furosemide-induced ototoxicity (tinnitus, sensorineural deafness) and spironolactone-induced painful gynecomastia?\"},\"title\":{\"tr\":\"Geri Çağırma: Furosemid Ototoksisitesi ve Spironolakton Jinekomastisi\",\"ar\":\"استرجاع: سمية فوروسيميد السمعية وتثدي سبيرونولاكتون\",\"en\":\"Retrieval: Furosemide Ototoxicity vs Spironolactone Gynecomastia\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":28}]},{\"id\":\"pharm-mod5-les2-step11\",\"order\":11,\"stageIndex\":11,\"stage\":\"connection\",\"type\":\"question\",\"title\":{\"tr\":\"Bütünsel Bağlantı: Nöronal Klor Taşınması ve Kıvrım Taşıyıcıları\",\"ar\":\"ترابط شمولي: نقل الكلور العصبوني ونواقل العروة\",\"en\":\"Holistic Connection: Neuronal Chloride Transport & Loop Transporters\"},\"prompt\":{\"tr\":\"Renal NKCC2 taşıyıcısı nöronal NKCC1 ve KCC2 ile homoloji paylaşır. Nöronal klor taşınması GABA-A reseptör kanallarının hiperpolarizan inhibitör gücünü nasıl yönetir?\",\"ar\":\"يتشابه ناقل NKCC2 الكلوي بنيوياً مع NKCC1 و KCC2 العصبونيين. كيف يحكم نقل الكلور العصبوني قوة فرط الاستقطاب التثبيطية لقنوات مستقبلات GABA-A؟\",\"en\":\"The renal NKCC2 transporter shares homology with neuronal NKCC1 and KCC2. How does neuronal chloride transport govern the hyperpolarizing inhibitory power of GABA-A receptor channels?\"},\"technicalTerms\":[{\"term\":\"klorür dengesi\",\"arContext\":\"توازن شوارد الكلوريد (chloride equilibrium)\"}],\"hints\":[{\"tier\":1,\"tr\":\"GABA-A reseptörleri ligand kapılı klor iyon kanallarıdır.\",\"ar\":\"مستقبلات GABA-A هي قنوات كلور أيونية مبوبة بالربيطة.\",\"en\":\"GABA-A receptors are ligand-gated chloride ion channels.\"},{\"tier\":2,\"tr\":\"GABA bağlandığında klor içeri mi akar dışarı mı? Bu, KCC2 ve NKCC1'in belirlediği hücre içi klor konsantrasyonuna bağlıdır.\",\"ar\":\"هل يتدفق الكلور للداخل أم الخارج عند ارتباط GABA؟ يعتمد ذلك كلياً على تركيز الكلور الداخلي الذي يحدده KCC2 و NKCC1.\",\"en\":\"Whether chloride flows inward or outward depends on the intracellular chloride gradient set by KCC2 and NKCC1.\"},{\"tier\":3,\"tr\":\"KCC2 kloru olgun nöronların dışına atar; bu düşük iç klor seviyesi GABA-A açıldığında klorun içeri akmasını, membranın hiperpolarize olmasını ve nöbetlerin durmasını sağlar.\",\"ar\":\"يطرد KCC2 الكلور خارج العصبونات البالغة؛ ويضمن انخفاضه الداخلي تدفق الكلور للداخل عند فتح GABA-A، مما يفرط الاستقطاب ويكبح التشنجات.\",\"en\":\"KCC2 pumps chloride out of adult neurons. This low internal chloride ensures that opening GABA-A channels causes chloride influx, hyperpolarizing the membrane.\"}],\"widgetType\":\"MultipleChoice\",\"conceptCheck\":{\"question\":{\"tr\":\"Nöronal klor kotransportörleri GABA-A sinyallemesinin inhibitör doğasını nasıl belirler?\",\"ar\":\"كيف تحدد نواقل الكلور العصبونية الطبيعة التثبيطية لتأشير مستقبلات GABA-A؟\",\"en\":\"How do neuronal cation-chloride cotransporters establish the inhibitory nature of GABA-A receptor signaling?\"},\"options\":[{\"id\":\"opt-l10-s11-1\",\"isCorrect\":true,\"text\":{\"tr\":\"KCC2 olgun nöronlarda kloru dışarı atarak hücre içi [Cl-]'yi düşük tutar; GABA-A açıldığında klor içeri akar, nöronu hiperpolarize eder ve nöbetleri baskılar.\",\"ar\":\"يطرد KCC2 الكلور خارج العصبونات البالغة مبقياً تركيزه منخفضاً؛ وحين يفتح GABA-A يتدفق الكلور للداخل مفرطاً استقطاب الخلية وكابحاً النوبات.\",\"en\":\"KCC2 extrudes intracellular chloride in mature neurons, maintaining a low [Cl-]i; when GABA-A opens, chloride flows inward, hyperpolarizing the neuron and suppressing seizures.\"},\"feedback\":{\"tr\":\"Doğru. KCC2 nöron içi kloru düşük tutarak klorun denge potansiyelini negatifte tutar. Böylece GABA-A açıldığında klor içeri akar ve inhibitör hiperpolarizasyon oluşur.\",\"ar\":\"صحيح. يطرد KCC2 الكلور ليحافظ على تركيز داخلي منخفض؛ مما يجعل فتح قنوات GABA-A يدخل الكلور سالباً مفرطاً للاستقطاب وكابحاً للاستثارة.\",\"en\":\"Correct. Cation-chloride cotransporters dictate the chloride equilibrium potential. KCC2 extrudes Cl- to keep [Cl-]i low, ensuring GABA-A produces inhibitory hyperpolarization.\"}},{\"id\":\"opt-l10-s11-2\",\"isCorrect\":false,\"text\":{\"tr\":\"NKCC1 ve KCC2 nöronlara sodyum pompalayarak epileptik nöbetler sırasında GABA-A'yı uyarıcı bir sodyum kanalına dönüştürür.\",\"ar\":\"يضخ NKCC1 و KCC2 الصوديوم للعصبونات، محولين GABA-A إلى قناة صوديوم استثارية أثناء النوبات الصرعية.\",\"en\":\"NKCC1 and KCC2 pump sodium into neurons, transforming GABA-A into an excitatory sodium channel during epileptic seizures.\"},\"feedback\":{\"tr\":\"Yanlış. GABA-A katyon değil klor kanalıdır; taşıyıcılar klor gradyanını belirleyerek GABA yanıtının yönünü tayin eder.\",\"ar\":\"غير صحيح. مستقبل GABA-A قناة كلور وليس قناة صوديوم؛ وتحدد النواقل مدروج الكلور لتحديد اتجاه الاستجابة.\",\"en\":\"Incorrect. GABA-A is strictly a chloride channel. Transporters set the chloride gradient, determining whether GABA is inhibitory or depolarizing.\"}},{\"id\":\"opt-l10-s11-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Furosemid kan-beyin bariyerini serbestçe geçip nöronal KCC2'yi inhibe ederek status epileptikusu saniyeler içinde tamamen iyileştirir.\",\"ar\":\"يعبر فوروسيميد الحاجز الدماغي بحرية ليثبط KCC2 العصبوني، معالجاً الحالة الصرعية تماماً خلال ثوانٍ.\",\"en\":\"Furosemide freely crosses the blood-brain barrier to inhibit neuronal KCC2, completely curing status epilepticus within seconds.\"},\"feedback\":{\"tr\":\"Yanlış. Furosemid yüksek iyonizasyonu ve protein bağlanması nedeniyle kan-beyin bariyerini geçemez; santral NKCC1 blokajı için bumetanid türevleri araştırılmaktadır.\",\"ar\":\"غير صحيح. نفوذية فوروسيميد للدماغ شبه معدومة لتأينه العالي؛ وتدرس مشتقات بوميتانيد تجريبياً للنفاذ للجهاز العصبي.\",\"en\":\"Incorrect. Furosemide has very poor BBB penetration due to its high ionization and protein binding; it cannot be used to treat status epilepticus.\"}}]},\"config\":{\"options\":[{\"id\":\"opt-l10-s11-1\",\"isCorrect\":true,\"text\":{\"tr\":\"KCC2 olgun nöronlarda kloru dışarı atarak hücre içi [Cl-]'yi düşük tutar; GABA-A açıldığında klor içeri akar, nöronu hiperpolarize eder ve nöbetleri baskılar.\",\"ar\":\"يطرد KCC2 الكلور خارج العصبونات البالغة مبقياً تركيزه منخفضاً؛ وحين يفتح GABA-A يتدفق الكلور للداخل مفرطاً استقطاب الخلية وكابحاً النوبات.\",\"en\":\"KCC2 extrudes intracellular chloride in mature neurons, maintaining a low [Cl-]i; when GABA-A opens, chloride flows inward, hyperpolarizing the neuron and suppressing seizures.\"},\"feedback\":{\"tr\":\"Doğru. KCC2 nöron içi kloru düşük tutarak klorun denge potansiyelini negatifte tutar. Böylece GABA-A açıldığında klor içeri akar ve inhibitör hiperpolarizasyon oluşur.\",\"ar\":\"صحيح. يطرد KCC2 الكلور ليحافظ على تركيز داخلي منخفض؛ مما يجعل فتح قنوات GABA-A يدخل الكلور سالباً مفرطاً للاستقطاب وكابحاً للاستثارة.\",\"en\":\"Correct. Cation-chloride cotransporters dictate the chloride equilibrium potential. KCC2 extrudes Cl- to keep [Cl-]i low, ensuring GABA-A produces inhibitory hyperpolarization.\"}},{\"id\":\"opt-l10-s11-2\",\"isCorrect\":false,\"text\":{\"tr\":\"NKCC1 ve KCC2 nöronlara sodyum pompalayarak epileptik nöbetler sırasında GABA-A'yı uyarıcı bir sodyum kanalına dönüştürür.\",\"ar\":\"يضخ NKCC1 و KCC2 الصوديوم للعصبونات، محولين GABA-A إلى قناة صوديوم استثارية أثناء النوبات الصرعية.\",\"en\":\"NKCC1 and KCC2 pump sodium into neurons, transforming GABA-A into an excitatory sodium channel during epileptic seizures.\"},\"feedback\":{\"tr\":\"Yanlış. GABA-A katyon değil klor kanalıdır; taşıyıcılar klor gradyanını belirleyerek GABA yanıtının yönünü tayin eder.\",\"ar\":\"غير صحيح. مستقبل GABA-A قناة كلور وليس قناة صوديوم؛ وتحدد النواقل مدروج الكلور لتحديد اتجاه الاستجابة.\",\"en\":\"Incorrect. GABA-A is strictly a chloride channel. Transporters set the chloride gradient, determining whether GABA is inhibitory or depolarizing.\"}},{\"id\":\"opt-l10-s11-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Furosemid kan-beyin bariyerini serbestçe geçip nöronal KCC2'yi inhibe ederek status epileptikusu saniyeler içinde tamamen iyileştirir.\",\"ar\":\"يعبر فوروسيميد الحاجز الدماغي بحرية ليثبط KCC2 العصبوني، معالجاً الحالة الصرعية تماماً خلال ثوانٍ.\",\"en\":\"Furosemide freely crosses the blood-brain barrier to inhibit neuronal KCC2, completely curing status epilepticus within seconds.\"},\"feedback\":{\"tr\":\"Yanlış. Furosemid yüksek iyonizasyonu ve protein bağlanması nedeniyle kan-beyin bariyerini geçemez; santral NKCC1 blokajı için bumetanid türevleri araştırılmaktadır.\",\"ar\":\"غير صحيح. نفوذية فوروسيميد للدماغ شبه معدومة لتأينه العالي؛ وتدرس مشتقات بوميتانيد تجريبياً للنفاذ للجهاز العصبي.\",\"en\":\"Incorrect. Furosemide has very poor BBB penetration due to its high ionization and protein binding; it cannot be used to treat status epilepticus.\"}}],\"prompt\":{\"tr\":\"Renal NKCC2 taşıyıcısı nöronal NKCC1 ve KCC2 ile homoloji paylaşır. Nöronal klor taşınması GABA-A reseptör kanallarının hiperpolarizan inhibitör gücünü nasıl yönetir?\",\"ar\":\"يتشابه ناقل NKCC2 الكلوي بنيوياً مع NKCC1 و KCC2 العصبونيين. كيف يحكم نقل الكلور العصبوني قوة فرط الاستقطاب التثبيطية لقنوات مستقبلات GABA-A؟\",\"en\":\"The renal NKCC2 transporter shares homology with neuronal NKCC1 and KCC2. How does neuronal chloride transport govern the hyperpolarizing inhibitory power of GABA-A receptor channels?\"},\"title\":{\"tr\":\"Bütünsel Bağlantı: Nöronal Klor Taşınması ve Kıvrım Taşıyıcıları\",\"ar\":\"ترابط شمولي: نقل الكلور العصبوني ونواقل العروة\",\"en\":\"Holistic Connection: Neuronal Chloride Transport & Loop Transporters\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":29}]},{\"id\":\"pharm-mod5-les2-step12\",\"order\":12,\"stageIndex\":12,\"stage\":\"mastery_check\",\"type\":\"question\",\"title\":{\"tr\":\"Ustalık Sınavı: Elektrolit ve Kan Gazı Paneli ile Diüretik Teşhisi\",\"ar\":\"اختبار الإتقان: تشخيص صنف المدر عبر لوحة الغازات والشوارد\",\"en\":\"Mastery Check: Electrolyte & Arterial Blood Gas Panel Diagnosis\"},\"prompt\":{\"tr\":\"Laboratuvar sonuçları: Arter pH 7.52, serum HCO3- 34 mEq/L (metabolik alkaloz), potasyum 2.8 mEq/L, sodyum 132 mEq/L ve belirgin hiperkalsiüri (idrar Ca2+ > 350 mg/24 saat). Sorumlu diüretik sınıfını teşhis edin.\",\"ar\":\"أظهرت التحاليل: باهاء شرياني 7.52، بيكربونات 34 mEq/L (قلاء استقلابي)، بوتاسيوم 2.8 mEq/L، صوديوم 132 mEq/L، وفرط كلس بول مميز (>350 ملغ/24س). حدد صنف المدر.\",\"en\":\"Diagnostic labs reveal: Arterial pH 7.52, serum HCO3- 34 mEq/L (metabolic alkalosis), potassium 2.8 mEq/L, sodium 132 mEq/L, and marked hypercalciuria (urinary Ca2+ > 350 mg/24h). Diagnose the causative diuretic class.\"},\"conceptCheck\":{\"question\":{\"tr\":\"Bu kan gazı ve elektrolit tablosu hangi diüretik sınıfının kullanımını kesin olarak kanıtlar?\",\"ar\":\"أي صنف من المدرات تؤكده لوحة غازات الدم والشوارد المذكورة بشكل قاطع؟\",\"en\":\"Which diuretic class is definitively diagnosed by this blood gas and electrolyte panel?\"},\"options\":[{\"id\":\"opt-l10-s12-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Kıvrım Diüretiği (Furosemid); NKCC2 blokajı lümen-pozitif transepitelyal potansiyeli yıkarak kalsiyumu idrara döker; artan distal sodyum ise K+ ve H+ atılımını körükler.\",\"ar\":\"مدر عروة (فوروسيميد)؛ حصر NKCC2 يلغي الجهد الإيجابي طارحاً الكالسيوم بالبول، بينما يدفع تدفق الصوديوم البعيد إطراح K+ و H+.\",\"en\":\"Loop Diuretic (e.g., Furosemide); NKCC2 blockade wipes out the lumen-positive transepithelial potential, wasting calcium into urine while distal sodium delivery drives K+ and H+ excretion.\"},\"feedback\":{\"tr\":\"Doğru! Hiperkalsiüri (kalsiyum atılımı) ile birlikte hipokalemik metabolik alkaloz tablosu Kıvrım Diüretiklerinin (furosemid) patognomonik izidir. Tiyazidler ise kalsiyumu kanda tutarak hipokalsiüri yapar.\",\"ar\":\"صحيح! قلاء استقلابي بنقص البوتاسيوم مع فرط كلس البول هو البصمة المميزة لمدرات العروة (فوروسيميد). بينما تحبس الثيازيدات الكالسيوم بالدم مسببة نقص كلس البول.\",\"en\":\"Correct! The triad of hypokalemic metabolic alkalosis with hypercalciuria (calcium wasting) is pathognomonic for Loop Diuretics. Thiazides cause hypocalciuria.\"}},{\"id\":\"opt-l10-s12-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Tiyazid Diüretiği (Hidroklorotiyazid); çünkü distal kıvrımlı tübüldeki NCC'nin inhibisyonu hipokalemi ile birlikte idrara yoğun kalsiyum dökülmesine yol açar.\",\"ar\":\"مدر ثيازيدي (هيدروكلوروثيازيد)؛ لأن تثبيط NCC في الأنبوب البعيد يطرح الكالسيوم بكثافة في البول مترافقاً بنقص البوتاسيوم.\",\"en\":\"Thiazide Diuretic (Hydrochlorothiazide); because inhibiting distal convoluted tubule NCC causes massive calcium dumping into urine alongside hypokalemia.\"},\"feedback\":{\"tr\":\"Yanlış. Tiyazidler idrar kalsiyumunu azaltır (hipokalsiüri); bu yüzden böbrek taşı tedavisinde kullanılırlar. Belirgin hiperkalsiüri tiyazid olasılığını kesinlikle eler.\",\"ar\":\"غير صحيح. تخفض الثيازيدات كالسيوم البول (نقص كلس البول) ولذا تعالج الحصيات الكلسية؛ ووجود فرط كلس البول ينفي الثيازيد تماماً.\",\"en\":\"Incorrect. Thiazides decrease urinary calcium (hypocalciuria) by enhancing basolateral NCX1 in DCT; marked hypercalciuria definitively rules out thiazides.\"}},{\"id\":\"opt-l10-s12-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Karbonik Anhidraz İnhibitörü (Asetazolamid); çünkü bikarbonat geri emiliminin bloke edilmesi sistemik arteryel kanı alkalileştirir.\",\"ar\":\"مثبط الأنهيدراز الكربوني (أسيتازولاميد)؛ لأن حصر ارتشاف البيكربونات يقلي دم الشرايين الجهازي.\",\"en\":\"Carbonic Anhydrase Inhibitor (Acetazolamide); because blocking bicarbonate reabsorption alkalizes systemic arterial blood.\"},\"feedback\":{\"tr\":\"Yanlış. Asetazolamid bikarbonatı idrara dökerek metabolik ASİDOZ yapar (arter pH < 7.35, düşük HCO3-), metabolik alkaloz yapmaz.\",\"ar\":\"غير صحيح. يطرح أسيتازولاميد البيكربونات مسبباً حماضاً استقلابياً (pH < 7.35) وليس قلاءً استقلابياً.\",\"en\":\"Incorrect. Acetazolamide wastes bicarbonate, producing metabolic ACIDOSIS (arterial pH < 7.35), not metabolic alkalosis.\"}}]},\"technicalTerms\":[{\"term\":\"metabolik alkaloz\",\"arContext\":\"القلاء الاستقلابي (metabolic alkalosis)\"}],\"hints\":[{\"tier\":1,\"tr\":\"İdrardaki kalsiyuma bakın: kalsiyum idrara atılıyor mu (hiperkalsiüri) yoksa kanda mı tutuluyor (hipokalsiüri)?\",\"ar\":\"انظر إلى كالسيوم البول: هل يُطرح الكالسيوم بالبول (فرط كلس البول) أم يُحتبس بالدم (نقص كلس البول)؟\",\"en\":\"Look at urinary calcium: Is calcium being wasted into the urine (hypercalciuria) or retained in the blood (hypocalciuria)?\"},{\"tier\":2,\"tr\":\"Unutmayın: 'Kıvrım kalsiyumu döker, Tiyazid tutar'. Her ikisi de hipokalemik metabolik alkaloz yapar ancak kalsiyum üzerindeki etkileri zıttır.\",\"ar\":\"تذكر: مدرات العروة تطرح الكالسيوم والثيازيد تحبسه. كلاهما يحدث قلاءً بنقص البوتاسيوم ولكن تأثيرهما على الكالسيوم متعاكس تماماً.\",\"en\":\"Remember: 'Loops Lose calcium, Thiazides Take in calcium.' Both cause hypokalemic alkalosis, but their calcium effects are opposite.\"},{\"tier\":3,\"tr\":\"Hipokalemik metabolik alkaloz ile birlikte yüksek idrar kalsiyumu (>350 mg/gün), TAL lümen-pozitif potansiyelini yıkan Kıvrım Diüretiklerinin (furosemid) patognomonik tablosudur.\",\"ar\":\"القلاء الاستقلابي بنقص البوتاسيوم مع فرط كلس البول (>350 ملغ/يوم) بصمة مشخصة لمدرات العروة (فوروسيميد) لإلغائها الجهد الإيجابي باللمعة.\",\"en\":\"Hypokalemic metabolic alkalosis combined with high urinary calcium (>350 mg/24h) is diagnostic of loop diuretic (furosemide) therapy due to loss of the TAL lumen-positive potential.\"}],\"widgetType\":\"MultipleChoice\",\"config\":{\"options\":[{\"id\":\"opt-l10-s12-1\",\"isCorrect\":true,\"text\":{\"tr\":\"Kıvrım Diüretiği (Furosemid); NKCC2 blokajı lümen-pozitif transepitelyal potansiyeli yıkarak kalsiyumu idrara döker; artan distal sodyum ise K+ ve H+ atılımını körükler.\",\"ar\":\"مدر عروة (فوروسيميد)؛ حصر NKCC2 يلغي الجهد الإيجابي طارحاً الكالسيوم بالبول، بينما يدفع تدفق الصوديوم البعيد إطراح K+ و H+.\",\"en\":\"Loop Diuretic (e.g., Furosemide); NKCC2 blockade wipes out the lumen-positive transepithelial potential, wasting calcium into urine while distal sodium delivery drives K+ and H+ excretion.\"},\"feedback\":{\"tr\":\"Doğru! Hiperkalsiüri (kalsiyum atılımı) ile birlikte hipokalemik metabolik alkaloz tablosu Kıvrım Diüretiklerinin (furosemid) patognomonik izidir. Tiyazidler ise kalsiyumu kanda tutarak hipokalsiüri yapar.\",\"ar\":\"صحيح! قلاء استقلابي بنقص البوتاسيوم مع فرط كلس البول هو البصمة المميزة لمدرات العروة (فوروسيميد). بينما تحبس الثيازيدات الكالسيوم بالدم مسببة نقص كلس البول.\",\"en\":\"Correct! The triad of hypokalemic metabolic alkalosis with hypercalciuria (calcium wasting) is pathognomonic for Loop Diuretics. Thiazides cause hypocalciuria.\"}},{\"id\":\"opt-l10-s12-2\",\"isCorrect\":false,\"text\":{\"tr\":\"Tiyazid Diüretiği (Hidroklorotiyazid); çünkü distal kıvrımlı tübüldeki NCC'nin inhibisyonu hipokalemi ile birlikte idrara yoğun kalsiyum dökülmesine yol açar.\",\"ar\":\"مدر ثيازيدي (هيدروكلوروثيازيد)؛ لأن تثبيط NCC في الأنبوب البعيد يطرح الكالسيوم بكثافة في البول مترافقاً بنقص البوتاسيوم.\",\"en\":\"Thiazide Diuretic (Hydrochlorothiazide); because inhibiting distal convoluted tubule NCC causes massive calcium dumping into urine alongside hypokalemia.\"},\"feedback\":{\"tr\":\"Yanlış. Tiyazidler idrar kalsiyumunu azaltır (hipokalsiüri); bu yüzden böbrek taşı tedavisinde kullanılırlar. Belirgin hiperkalsiüri tiyazid olasılığını kesinlikle eler.\",\"ar\":\"غير صحيح. تخفض الثيازيدات كالسيوم البول (نقص كلس البول) ولذا تعالج الحصيات الكلسية؛ ووجود فرط كلس البول ينفي الثيازيد تماماً.\",\"en\":\"Incorrect. Thiazides decrease urinary calcium (hypocalciuria) by enhancing basolateral NCX1 in DCT; marked hypercalciuria definitively rules out thiazides.\"}},{\"id\":\"opt-l10-s12-3\",\"isCorrect\":false,\"text\":{\"tr\":\"Karbonik Anhidraz İnhibitörü (Asetazolamid); çünkü bikarbonat geri emiliminin bloke edilmesi sistemik arteryel kanı alkalileştirir.\",\"ar\":\"مثبط الأنهيدراز الكربوني (أسيتازولاميد)؛ لأن حصر ارتشاف البيكربونات يقلي دم الشرايين الجهازي.\",\"en\":\"Carbonic Anhydrase Inhibitor (Acetazolamide); because blocking bicarbonate reabsorption alkalizes systemic arterial blood.\"},\"feedback\":{\"tr\":\"Yanlış. Asetazolamid bikarbonatı idrara dökerek metabolik ASİDOZ yapar (arter pH < 7.35, düşük HCO3-), metabolik alkaloz yapmaz.\",\"ar\":\"غير صحيح. يطرح أسيتازولاميد البيكربونات مسبباً حماضاً استقلابياً (pH < 7.35) وليس قلاءً استقلابياً.\",\"en\":\"Incorrect. Acetazolamide wastes bicarbonate, producing metabolic ACIDOSIS (arterial pH < 7.35), not metabolic alkalosis.\"}}],\"prompt\":{\"tr\":\"Laboratuvar sonuçları: Arter pH 7.52, serum HCO3- 34 mEq/L (metabolik alkaloz), potasyum 2.8 mEq/L, sodyum 132 mEq/L ve belirgin hiperkalsiüri (idrar Ca2+ > 350 mg/24 saat). Sorumlu diüretik sınıfını teşhis edin.\",\"ar\":\"أظهرت التحاليل: باهاء شرياني 7.52، بيكربونات 34 mEq/L (قلاء استقلابي)، بوتاسيوم 2.8 mEq/L، صوديوم 132 mEq/L، وفرط كلس بول مميز (>350 ملغ/24س). حدد صنف المدر.\",\"en\":\"Diagnostic labs reveal: Arterial pH 7.52, serum HCO3- 34 mEq/L (metabolic alkalosis), potassium 2.8 mEq/L, sodium 132 mEq/L, and marked hypercalciuria (urinary Ca2+ > 350 mg/24h). Diagnose the causative diuretic class.\"},\"title\":{\"tr\":\"Ustalık Sınavı: Elektrolit ve Kan Gazı Paneli ile Diüretik Teşhisi\",\"ar\":\"اختبار الإتقان: تشخيص صنف المدر عبر لوحة الغازات والشوارد\",\"en\":\"Mastery Check: Electrolyte & Arterial Blood Gas Panel Diagnosis\"}},\"sources\":[{\"file\":\"Kardiyovasküler Sistem.pdf\",\"page\":30}]}]},\"pharm-mod6-les1\":{\"id\":\"pharm-mod6-les1\",\"courseId\":\"pharmacology\",\"moduleId\":\"ph-mod-06\",\"title\":{\"tr\":\"GABAerjik Nörotransmisyon ve Pozitif Allosterik Modülatörler\",\"ar\":\"النقل العصبي عبر GABA والمعدلات التفارغية الإيجابية\",\"en\":\"GABAergic Neurotransmission & Positive Allosteric Modulators\"},\"order\":1,\"access\":\"free\",\"objective\":{\"tr\":\"GABA-A klorür kanalı üzerinde benzodiyazepin ve barbitüratların allosterik mekanizmalarını ve güvenlik profillerini ayırt etmek.\",\"ar\":\"التمييز بين الآليات التفارغية للبنزوديازيبينات والباربيتورات على قناة كلوريد GABA-A وملفات أمانها.\",\"en\":\"Differentiate allosteric mechanisms and safety profiles of benzodiazepines versus barbiturates on GABA-A chloride channels.\"},\"misconceptions\":[{\"tr\":\"Benzodiyazepinlerin GABA yokluğunda da klorür kanalını doğrudan açabileceği yanılgısı (yalnızca GABA varlığında açılma frekansını artırırlar).\",\"ar\":\"الاعتقاد الخاطئ بأن البنزوديازيبينات تفتح قناة الكلوريد بمفردها غيابياً دون الحاجة لوجود GABA (هي تزيد تواتر الفتح فقط).\",\"en\":\"Benzodiazepines open chloride channels in the total absence of GABA.\"}],\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":6}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Goodman & Gilman's The Pharmacological Basis of Therapeutics\",\"edition\":\"14th ed.\",\"topic\":\"GABAergic Neurotransmission and Benzodiazepine Pharmacology\"}],\"spacedReviewCards\":[{\"cardId\":\"pharm-mod6-les1-card1\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Benzodiyazepin Mekanizması\",\"prompt\":\"Benzodiyazepinler GABA-A klorür kanalının açılma frekansını mı, yoksa açık kalma süresini mi artırır?\",\"answer\":\"Açılma frekansını (Frekans = Fren) artırır; doğrudan kanal açamazlar.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod6-les1-card2\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Barbitürat Tehlikesi\",\"prompt\":\"Barbitüratlar yüksek dozda neden ölümcül solunum depresyonu yapar?\",\"answer\":\"Kanalın açık kalma süresini artırır ve yüksek dozda GABA olmadan kanalı doğrudan açabilirler.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod6-les1-card3\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Flumazenil Antidotu\",\"prompt\":\"Benzodiyazepin aşırı dozunda allosterik bölgeyi yarışmalı bloke eden spesifik antidot nedir?\",\"answer\":\"Flumazenil spesifik yarışmalı antagonisttir.\",\"box\":1,\"intervalDays\":1}],\"translations\":{\"tr\":{\"title\":\"GABAerjik Nörotransmisyon ve Pozitif Allosterik Modülatörler\"},\"ar\":{\"title\":\"النقل العصبي عبر GABA والمعدلات التفارغية الإيجابية\"}},\"steps\":[{\"id\":\"pharm-mod6-les1-step-01\",\"stage\":\"hook\",\"stageIndex\":1,\"title\":{\"tr\":\"Beynin Ana Fren Pedalı\",\"ar\":\"كابح الدماغ الأساسي\",\"en\":\"The Brain's Master Brake Pedal\"},\"prompt\":{\"en\":\"A patient ingesting 40 diazepam tablets awakens safely, yet taking 10 phenobarbital tablets causes fatal respiratory arrest. Why do benzodiazepines have an insurmountable safety ceiling while barbiturates kill in overdose?\",\"tr\":\"40 tablet diyazepam alan hasta güvenle uyanırken, 10 tablet fenobarbital alan hasta solunum arrestinden ölür. Benzodiyazepinler aşılmaz bir güvenlik tavanına sahipken barbitüratlar neden ölümcüldür?\",\"ar\":\"يستيقظ مريض ابتلع 40 قرص ديازيبام بأمان، بينما 10 أقراص فينوباربيتال تسبب توقفاً تنفسياً مميتاً. لماذا تمتلك البنزوديازيبينات سقف أمان منيعاً بينما تقتل الباربيتورات؟\"},\"predictThenReveal\":true,\"config\":{\"options\":[{\"id\":\"opt_pam_vs_pore\",\"text\":{\"en\":\"Benzodiazepines are pure allosteric modulators requiring endogenous GABA, whereas barbiturates directly gate the chloride pore at high concentrations.\",\"tr\":\"Benzodiyazepinler endojen GABA'ya muhtaç saf allosterik modülatörlerdir; barbitüratlar ise yüksek dozda klorür kanalını doğrudan açarlar.\",\"ar\":\"البنزوديازيبينات معدلات تفارغية نقية تتطلب GABA داخلياً، بينما تفتح الباربيتورات قناة الكلوريد مباشرة عند التراكيز العالية.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! BZDs only increase GABA gating frequency and cannot open the pore alone. High-dose barbiturates directly gate chloride influx without GABA.\",\"tr\":\"Doğru! BZD'ler sadece GABA varlığında açılma frekansını artırır. Barbitüratlar ise GABA olmadan da kanalı açarak solunumu durdurur.\",\"ar\":\"صحيح! تزيد البنزوديازيبينات تردد الفتح بوجود GABA فقط، بينما تفتح الباربيتورات القناة مباشرة دون الحاجة لـ GABA مسببة شللاً تنفسياً.\"}},{\"id\":\"opt_hepatic_saturation\",\"text\":{\"en\":\"Diazepam undergoes saturable hepatic first-pass metabolism that limits toxic systemic drug delivery to medullary respiratory centers.\",\"tr\":\"Diyazepam, medüller solunum merkezlerine toksik ilaç ulaşımını sınırlayan doymuş hepatik ilk geçiş metabolizmasına uğrar.\",\"ar\":\"يخضع الديازيبام لاستقلاب كبدي أولي مشبع يحد من وصول الدواء السام إلى مراكز التنفس النخاعية.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Diazepam has high systemic bioavailability; its safety ceiling is purely pharmacodynamic (GABA dependence), not pharmacokinetic clearance saturation.\",\"tr\":\"Yanlış. Diyazepamın güvenliği farmakokinetik klirens satürasyonundan değil, tamamen GABA'ya bağımlı farmakodinamik tavandan kaynaklanır.\",\"ar\":\"غير صحيح. سلامة الديازيبام تنبع من آلية ديناميكية دوائية (الاعتماد الإجباري على GABA) وليس من تشبع الاستقلاب الكبدي.\"}},{\"id\":\"opt_receptor_endocytosis\",\"text\":{\"en\":\"High-dose benzodiazepines trigger immediate clathrin-mediated endocytosis of GABA-A receptors, desensitizing neurons to further depression.\",\"tr\":\"Yüksek doz benzodiyazepinler GABA-A reseptörlerinin klatrin aracılı endositozunu tetikleyerek nöronları depresyona karşı duyarsızlaştırır.\",\"ar\":\"تحفز الجرعات العالية من البنزوديازيبين بلعمة فورية لمستقبلات GABA-A مما يزيل حساسية الخلايا العصبية.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Acute receptor endocytosis does not occur in minutes during overdose. Tolerance and uncoupling require days to weeks of chronic exposure.\",\"tr\":\"Yanlış. Reseptör endositozu akut aşırı dozda dakikalar içinde oluşmaz; tolerans ve reseptör kopması kronik maruziyet gerektirir.\",\"ar\":\"غير صحيح. لا تحدث بلعمة المستقبلات الحادة خلال دقائق من الجرعة المفرطة؛ بل تتطلب تحملاً واستخداماً مزمناً لأسابيع.\"}},{\"id\":\"opt_gaba_depletion\",\"text\":{\"en\":\"Benzodiazepines deplete vesicular GABA stores, self-limiting their own inhibitory action once endogenous neurotransmitter runs out.\",\"tr\":\"Benzodiyazepinler veziküler GABA depolarını tüketerek, endojen nörotransmitter bittiğinde kendi inhibitör etkilerini sonlandırırlar.\",\"ar\":\"تستنفد البنزوديازيبينات مخازن GABA الحويصلية، مما يحد من تأثيرها المثبط تلقائياً عند نفاذ الناقل.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Benzodiazepines do not stimulate vesicular release or exhaust GABA stores. They allosterically enhance postsynaptic responsiveness to GABA.\",\"tr\":\"Yanlış. Benzodiyazepinler veziküler GABA salınımını veya tükenmesini tetiklemez; sadece postsinaptik reseptörün GABA'ya yanıtını artırırlar.\",\"ar\":\"غير صحيح. لا تستنزف البنزوديازيبينات حويصلات GABA، بل تعزز استجابة المستقبل البعد مشبكي للناقل الموجود تفارغياً.\"}}]},\"technicalTerms\":[{\"term\":\"GABA-A reseptörü\",\"arContext\":\"مستقبِل GABA-A\"}],\"hints\":[{\"tier\":1,\"tr\":\"Biri kapıyı çalmak için ev sahibine (GABA) muhtaçtır; diğeri ise ev sahibini beklemeden kapıyı kırıp içeri girer.\",\"ar\":\"أحدهما يحتاج لصاحب البيت (GABA) ليفتح الباب؛ والآخر يكسر الباب ويقتحم دون انتظار أحد.\",\"en\":\"One drug obligatorily requires endogenous GABA; the other can directly crowbar the door open without any host.\"},{\"tier\":2,\"tr\":\"Benzodiyazepinler tek başlarına kanalı açamazlar; sadece GABA'nın yaptığı açılmayı frekans düzeyinde kolaylaştırırlar.\",\"ar\":\"تعجز البنزوديازيبينات عن فتح القناة بمفردها؛ بل تسهل الفتح الذي يحدثه GABA بزيادة تردده فقط.\",\"en\":\"Benzodiazepines cannot gate the channel alone; they purely augment opening frequency in response to GABA.\"},{\"tier\":3,\"tr\":\"Barbitüratlar yüksek dozda doğrudan kanal açıcıdır (GABA-mimetik); bu da kontrolsüz solunum durmasına yol açar.\",\"ar\":\"أما الباربيتورات فتفتح القناة مباشرة عند التراكيز المرتفعة مسببة توقفاً تاماً لمركز التنفس النخاعي.\",\"en\":\"Barbiturates directly gate chloride channels at high doses without GABA, triggering fatal medullary respiratory arrest.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_pam_vs_pore\",\"text\":{\"en\":\"Benzodiazepines are pure allosteric modulators requiring endogenous GABA, whereas barbiturates directly gate the chloride pore at high concentrations.\",\"tr\":\"Benzodiyazepinler endojen GABA'ya muhtaç saf allosterik modülatörlerdir; barbitüratlar ise yüksek dozda klorür kanalını doğrudan açarlar.\",\"ar\":\"البنزوديازيبينات معدلات تفارغية نقية تتطلب GABA داخلياً، بينما تفتح الباربيتورات قناة الكلوريد مباشرة عند التراكيز العالية.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! BZDs only increase GABA gating frequency and cannot open the pore alone. High-dose barbiturates directly gate chloride influx without GABA.\",\"tr\":\"Doğru! BZD'ler sadece GABA varlığında açılma frekansını artırır. Barbitüratlar ise GABA olmadan da kanalı açarak solunumu durdurur.\",\"ar\":\"صحيح! تزيد البنزوديازيبينات تردد الفتح بوجود GABA فقط، بينما تفتح الباربيتورات القناة مباشرة دون الحاجة لـ GABA مسببة شللاً تنفسياً.\"}},{\"id\":\"opt_hepatic_saturation\",\"text\":{\"en\":\"Diazepam undergoes saturable hepatic first-pass metabolism that limits toxic systemic drug delivery to medullary respiratory centers.\",\"tr\":\"Diyazepam, medüller solunum merkezlerine toksik ilaç ulaşımını sınırlayan doymuş hepatik ilk geçiş metabolizmasına uğrar.\",\"ar\":\"يخضع الديازيبام لاستقلاب كبدي أولي مشبع يحد من وصول الدواء السام إلى مراكز التنفس النخاعية.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Diazepam has high systemic bioavailability; its safety ceiling is purely pharmacodynamic (GABA dependence), not pharmacokinetic clearance saturation.\",\"tr\":\"Yanlış. Diyazepamın güvenliği farmakokinetik klirens satürasyonundan değil, tamamen GABA'ya bağımlı farmakodinamik tavandan kaynaklanır.\",\"ar\":\"غير صحيح. سلامة الديازيبام تنبع من آلية ديناميكية دوائية (الاعتماد الإجباري على GABA) وليس من تشبع الاستقلاب الكبدي.\"}},{\"id\":\"opt_receptor_endocytosis\",\"text\":{\"en\":\"High-dose benzodiazepines trigger immediate clathrin-mediated endocytosis of GABA-A receptors, desensitizing neurons to further depression.\",\"tr\":\"Yüksek doz benzodiyazepinler GABA-A reseptörlerinin klatrin aracılı endositozunu tetikleyerek nöronları depresyona karşı duyarsızlaştırır.\",\"ar\":\"تحفز الجرعات العالية من البنزوديازيبين بلعمة فورية لمستقبلات GABA-A مما يزيل حساسية الخلايا العصبية.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Acute receptor endocytosis does not occur in minutes during overdose. Tolerance and uncoupling require days to weeks of chronic exposure.\",\"tr\":\"Yanlış. Reseptör endositozu akut aşırı dozda dakikalar içinde oluşmaz; tolerans ve reseptör kopması kronik maruziyet gerektirir.\",\"ar\":\"غير صحيح. لا تحدث بلعمة المستقبلات الحادة خلال دقائق من الجرعة المفرطة؛ بل تتطلب تحملاً واستخداماً مزمناً لأسابيع.\"}},{\"id\":\"opt_gaba_depletion\",\"text\":{\"en\":\"Benzodiazepines deplete vesicular GABA stores, self-limiting their own inhibitory action once endogenous neurotransmitter runs out.\",\"tr\":\"Benzodiyazepinler veziküler GABA depolarını tüketerek, endojen nörotransmitter bittiğinde kendi inhibitör etkilerini sonlandırırlar.\",\"ar\":\"تستنفد البنزوديازيبينات مخازن GABA الحويصلية، مما يحد من تأثيرها المثبط تلقائياً عند نفاذ الناقل.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Benzodiazepines do not stimulate vesicular release or exhaust GABA stores. They allosterically enhance postsynaptic responsiveness to GABA.\",\"tr\":\"Yanlış. Benzodiyazepinler veziküler GABA salınımını veya tükenmesini tetiklemez; sadece postsinaptik reseptörün GABA'ya yanıtını artırırlar.\",\"ar\":\"غير صحيح. لا تستنزف البنزوديازيبينات حويصلات GABA، بل تعزز استجابة المستقبل البعد مشبكي للناقل الموجود تفارغياً.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":1}]},{\"id\":\"pharm-mod6-les1-step-02\",\"stage\":\"question\",\"stageIndex\":2,\"title\":{\"tr\":\"Tahmin: Tek Başına Benzodiyazepin\",\"ar\":\"توقع: البنزوديازيبين بمفرده\",\"en\":\"Prediction: Benzodiazepine in the Absence of GABA\"},\"prompt\":{\"en\":\"Can a ligand at the GABA-A receptor gate the chloride channel in the complete absence of GABA? How do benzodiazepines and barbiturates behave under this condition?\",\"tr\":\"GABA-A reseptöründeki bir ligand, ortamda hiç GABA yokken klorür kanalını açabilir mi? Benzodiyazepinler ve barbitüratlar bu kuralda nasıl ayrışır?\",\"ar\":\"هل يمكن لربيطة عند مستقبل GABA-A أن تفتح قناة الكلوريد في الغياب التام لـ GABA؟ كيف يفترق سلوك البنزوديازيبينات والباربيتورات؟\"},\"predictThenReveal\":true,\"config\":{\"revealedOutcome\":\"Benzodiyazepinler doğrudan agonist değildir; yalnızca GABA nın etkisini amplifiye ederler.\",\"options\":[{\"id\":\"opt_direct_gating_diff\",\"text\":{\"en\":\"Diazepam produces zero chloride conductance without GABA, whereas barbiturates at anesthetic concentrations directly gate the open pore.\",\"tr\":\"Diyazepam ortamda GABA yokken sıfır klorür iletimi sağlar; barbitüratlar ise anestezik dozlarda kanalı doğrudan açarlar.\",\"ar\":\"لا ينتج الديازيبام أي توصيل للكلوريد بغياب GABA، بينما تفتح الباربيتورات القناة مباشرة بتراكيزها التخديرية.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! BZDs lack intrinsic efficacy to open the pore alone. Barbiturates possess direct GABA-mimetic gating capability at high doses.\",\"tr\":\"Doğru! BZD'ler tek başlarına kanalı açacak intrensek etkiye sahip değildir; barbitüratlar ise yüksek dozda doğrudan kanal açıcıdır.\",\"ar\":\"صحيح! تفتقر البنزوديازيبينات للقدرة على فتح القناة بمفردها، بينما تمتلك الباربيتورات تأثيراً محاكياً مباشراً لـ GABA.\"}},{\"id\":\"opt_both_orthosteric\",\"text\":{\"en\":\"Both drugs act as orthosteric agonists that open the channel identically, differing solely in their dissociation equilibrium constants (Kd).\",\"tr\":\"Her iki ilaç da kanalı aynı şekilde açan ortosterik agonistlerdir, yalnızca ayrışma denge sabitleri (Kd) farklıdır.\",\"ar\":\"كلا الدواءين ناهضان متماثلان في الموقع الأصلي يفتحان القناة، والاختلاف الوحيد بينهما هو ثابت التفكك (Kd).\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Neither drug binds the orthosteric GABA pocket. They bind distinct allosteric sites, but barbiturates can directly gate the pore.\",\"tr\":\"Yanlış. İki ilaç da ortosterik GABA cebine bağlanmaz. Farklı allosterik bölgelere bağlanırlar ancak barbitüratlar doğrudan gözenek açabilir.\",\"ar\":\"غير صحيح. لا يرتبط أي منهما بموقع GABA الأصلي، بل يرتبطان بمواقع تفارغية متمايزة، وتنفرد الباربيتورات بفتح القناة مباشرة.\"}},{\"id\":\"opt_pore_block_misconception\",\"text\":{\"en\":\"Barbiturates block the channel lumen while benzodiazepines allow inward chloride flow only when phosphorylated by protein kinase A.\",\"tr\":\"Barbitüratlar kanal lümenini tıkar; benzodiyazepinler ise sadece protein kinaz A ile fosforillendiğinde klorür girişine izin verir.\",\"ar\":\"تسد الباربيتورات لمعة القناة بينما تسمح البنزوديازيبينات بدخول الكلوريد فقط عند فسفرتها ببروتين كيناز A.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Barbiturates enhance and gate chloride influx rather than blocking it (picrotoxin blocks the pore lumen).\",\"tr\":\"Yanlış. Barbitüratlar kanalı tıkamaz, klorür akışını açarlar (kanal lümenini tıkayan pikrotoksindir).\",\"ar\":\"غير صحيح. تعزز الباربيتورات تدفق الكلوريد ولا تسده (البيكروتوكسين هو من يسد لمعة القناة).\"}},{\"id\":\"opt_covalent_locking\",\"text\":{\"en\":\"Both drugs require GABA, but barbiturates form an irreversible covalent adduct with the pore that prevents channel closure.\",\"tr\":\"Her iki ilaç da GABA gerektirir, ancak barbitüratlar gözenek ile kovalent bağ kurarak kanalın kapanmasını kalıcı olarak engeller.\",\"ar\":\"يتطلب كلاهما GABA، لكن الباربيتورات تشكل رابطة تساهمية غير عكوسة تمنع انغلاق القناة نهائياً.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Barbiturate binding is non-covalent and reversible. Their danger lies in direct GABA-independent pore gating at high doses.\",\"tr\":\"Yanlış. Barbitürat bağlanması kovalent değil tersinirdir. Tehlikeleri, yüksek dozda GABA'dan bağımsız doğrudan kanal açabilmeleridir.\",\"ar\":\"غير صحيح. ارتباط الباربيتورات غير تساهمي وعكوس؛ مكمن الخطر هو فتحها المباشر للقناة دون الحاجة لـ GABA.\"}}]},\"technicalTerms\":[{\"term\":\"etki mekanizması\",\"arContext\":\"آلية التأثير الدوائي\"},{\"term\":\"reseptör\",\"arContext\":\"المستقبِل الحيوي\"}],\"hints\":[{\"tier\":1,\"tr\":\"İki ilacın intrensek etkinliklerini ortamda hiç transmitter yokken karşılaştırın.\",\"ar\":\"قارن الفاعلية الذاتية لكلا الدواءين في غياب تام للناقل العصبي الداخلي.\",\"en\":\"Compare the intrinsic gating efficacy of both drug classes when neurotransmitter is completely absent.\"},{\"tier\":2,\"tr\":\"Pozitif allosterik modülatörler ortosterik agonist olmadan klor akışı sağlayamazlar.\",\"ar\":\"تعجز المعدلات التفارغية الإيجابية عن تمرير الكلوريد دون ارتباط ناهض أصلي بالمستقبل.\",\"en\":\"Positive allosteric modulators cannot elicit ion flux without orthosteric agonist receptor occupancy.\"},{\"tier\":3,\"tr\":\"Diyazepam sıfır klor iletir; yüksek doz barbitürat ise GABA olmadan da kanalı açarak iletkenlik üretir.\",\"ar\":\"يمرر الديازيبام صفراً من الكلوريد؛ بينما تفتح الباربيتورات العالية القناة مباشرة لتوليد تيار كلسيومي دون GABA.\",\"en\":\"Diazepam produces zero chloride conductance; high-dose barbiturates directly gate the channel without GABA.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_direct_gating_diff\",\"text\":{\"en\":\"Diazepam produces zero chloride conductance without GABA, whereas barbiturates at anesthetic concentrations directly gate the open pore.\",\"tr\":\"Diyazepam ortamda GABA yokken sıfır klorür iletimi sağlar; barbitüratlar ise anestezik dozlarda kanalı doğrudan açarlar.\",\"ar\":\"لا ينتج الديازيبام أي توصيل للكلوريد بغياب GABA، بينما تفتح الباربيتورات القناة مباشرة بتراكيزها التخديرية.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! BZDs lack intrinsic efficacy to open the pore alone. Barbiturates possess direct GABA-mimetic gating capability at high doses.\",\"tr\":\"Doğru! BZD'ler tek başlarına kanalı açacak intrensek etkiye sahip değildir; barbitüratlar ise yüksek dozda doğrudan kanal açıcıdır.\",\"ar\":\"صحيح! تفتقر البنزوديازيبينات للقدرة على فتح القناة بمفردها، بينما تمتلك الباربيتورات تأثيراً محاكياً مباشراً لـ GABA.\"}},{\"id\":\"opt_both_orthosteric\",\"text\":{\"en\":\"Both drugs act as orthosteric agonists that open the channel identically, differing solely in their dissociation equilibrium constants (Kd).\",\"tr\":\"Her iki ilaç da kanalı aynı şekilde açan ortosterik agonistlerdir, yalnızca ayrışma denge sabitleri (Kd) farklıdır.\",\"ar\":\"كلا الدواءين ناهضان متماثلان في الموقع الأصلي يفتحان القناة، والاختلاف الوحيد بينهما هو ثابت التفكك (Kd).\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Neither drug binds the orthosteric GABA pocket. They bind distinct allosteric sites, but barbiturates can directly gate the pore.\",\"tr\":\"Yanlış. İki ilaç da ortosterik GABA cebine bağlanmaz. Farklı allosterik bölgelere bağlanırlar ancak barbitüratlar doğrudan gözenek açabilir.\",\"ar\":\"غير صحيح. لا يرتبط أي منهما بموقع GABA الأصلي، بل يرتبطان بمواقع تفارغية متمايزة، وتنفرد الباربيتورات بفتح القناة مباشرة.\"}},{\"id\":\"opt_pore_block_misconception\",\"text\":{\"en\":\"Barbiturates block the channel lumen while benzodiazepines allow inward chloride flow only when phosphorylated by protein kinase A.\",\"tr\":\"Barbitüratlar kanal lümenini tıkar; benzodiyazepinler ise sadece protein kinaz A ile fosforillendiğinde klorür girişine izin verir.\",\"ar\":\"تسد الباربيتورات لمعة القناة بينما تسمح البنزوديازيبينات بدخول الكلوريد فقط عند فسفرتها ببروتين كيناز A.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Barbiturates enhance and gate chloride influx rather than blocking it (picrotoxin blocks the pore lumen).\",\"tr\":\"Yanlış. Barbitüratlar kanalı tıkamaz, klorür akışını açarlar (kanal lümenini tıkayan pikrotoksindir).\",\"ar\":\"غير صحيح. تعزز الباربيتورات تدفق الكلوريد ولا تسده (البيكروتوكسين هو من يسد لمعة القناة).\"}},{\"id\":\"opt_covalent_locking\",\"text\":{\"en\":\"Both drugs require GABA, but barbiturates form an irreversible covalent adduct with the pore that prevents channel closure.\",\"tr\":\"Her iki ilaç da GABA gerektirir, ancak barbitüratlar gözenek ile kovalent bağ kurarak kanalın kapanmasını kalıcı olarak engeller.\",\"ar\":\"يتطلب كلاهما GABA، لكن الباربيتورات تشكل رابطة تساهمية غير عكوسة تمنع انغلاق القناة نهائياً.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Barbiturate binding is non-covalent and reversible. Their danger lies in direct GABA-independent pore gating at high doses.\",\"tr\":\"Yanlış. Barbitürat bağlanması kovalent değil tersinirdir. Tehlikeleri, yüksek dozda GABA'dan bağımsız doğrudan kanal açabilmeleridir.\",\"ar\":\"غير صحيح. ارتباط الباربيتورات غير تساهمي وعكوس؛ مكمن الخطر هو فتحها المباشر للقناة دون الحاجة لـ GABA.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":2}]},{\"id\":\"pharm-mod6-les1-step-03\",\"stage\":\"intuition\",\"stageIndex\":3,\"title\":{\"tr\":\"Sezgisel Analoji: Kapının Menteşesini Yağlamak\",\"ar\":\"تشبيه حدسي: تزييت مفصلات الباب\",\"en\":\"Intuitive Analogy: Oiling the Door Hinges\"},\"prompt\":{\"en\":\"Picture the chloride channel as a bank vault: GABA is the key. Benzodiazepines oil the hinges so the key turns easily. What do barbiturates do at high doses?\",\"tr\":\"Klorür kanalını bir banka kasası, GABA'yı da anahtar olarak hayal edin. Benzodiyazepin menteşeyi yağlar. Yüksek doz barbitüratlar ne yapar?\",\"ar\":\"تخيل قناة الكلوريد كخزنة بنك وGABA كمفتاحها. تزيت البنزوديازيبينات المفصلات ليدور المفتاح بسهولة. ماذا تفعل الباربيتورات بالجرعات العالية؟\"},\"predictThenReveal\":false,\"config\":{\"options\":[{\"id\":\"opt_crowbar_analogy\",\"text\":{\"en\":\"Barbiturates crowbar the vault door wide open, forcing chloride influx continuously even if the GABA key is completely absent.\",\"tr\":\"Barbitüratlar kasa kapısını levye ile kırarak, GABA anahtarı hiç olmasa bile içeriye sürekli klorür akışı sağlarlar.\",\"ar\":\"تخلع الباربيتورات باب الخزنة عنوة، مما يدفق الكلوريد باستمرار حتى وإن غاب مفتاح GABA تماماً.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Barbiturates prolong channel open duration and directly force the pore open at anesthetic concentrations without GABA.\",\"tr\":\"Doğru! Barbitüratlar açık kalma süresini uzatır ve yüksek dozda GABA olmadan da kapıyı kırıp klorür akışı başlatırlar.\",\"ar\":\"صحيح! تطيل الباربيتورات مدة بقاء القناة مفتوحة وتجبرها على الانفتاح دون GABA عند التراكيز التخديرية.\"}},{\"id\":\"opt_conductance_increase\",\"text\":{\"en\":\"Barbiturates widen the physical diameter of the chloride filter, multiplying single-channel conductance five-fold without altering gating time.\",\"tr\":\"Barbitüratlar klorür filtresinin çapını genişleterek, açılma süresini değiştirmeden tek kanal iletkenliğini beş katına çıkarır.\",\"ar\":\"توسع الباربيتورات القطر الفيزيائي لمرشح الكلوريد مضاعفة توصيل القناة المفردة 5 أضعاف دون تغيير زمن الفتح.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Barbiturates alter gating kinetics (open duration and direct opening) rather than increasing the physical diameter or single-channel conductance.\",\"tr\":\"Yanlış. Barbitüratlar kanal çapını veya tekil iletkenliği artırmaz; açılma kinetiğini (süresini ve doğrudan açılmayı) değiştirir.\",\"ar\":\"غير صحيح. تعدل الباربيتورات حركية الفتح (إطالة زمن الانفتاح والفتح المباشر) ولا توسع القطر الفيزيائي للقناة.\"}},{\"id\":\"opt_kinetic_inversion\",\"text\":{\"en\":\"Barbiturates purely increase opening frequency while benzodiazepines prolong single-channel burst open duration.\",\"tr\":\"Barbitüratlar sadece açılma frekansını artırırken, benzodiyazepinler tek kanal patlama süresini uzatırlar.\",\"ar\":\"تزيد الباربيتورات تردد الفتح فقط، بينما تطيل البنزوديازيبينات مدة بقاء القناة مفتوحة.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Classic pharmacological rule: Benzodiazepines increase opening FREQUENCY; Barbiturates prolong opening DURATION.\",\"tr\":\"Yanlış. Klasik farmakoloji kuralı: Benzodiyazepinler açılma FREKANSINI artırır, Barbitüratlar ise açık kalma SÜRESİNİ uzatır.\",\"ar\":\"غير صحيح. القاعدة الدوائية الشهيرة: تزيد البنزوديازيبينات تردد الفتح، بينما تطيل الباربيتورات زمن الانفتاح.\"}},{\"id\":\"opt_destroy_hinges\",\"text\":{\"en\":\"Barbiturates weld the vault door shut, preventing chloride ions from entering the neuron and producing osmotic lysis.\",\"tr\":\"Barbitüratlar kasa kapısını kaynakla kapatır, klorür girişini engelleyerek nöronun ozmotik lizisine yol açar.\",\"ar\":\"تلحم الباربيتورات باب الخزنة مغلقاً مما يمنع دخول الكلوريد ويؤدي إلى انحلال الخلية تناضحياً.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Barbiturates open the door and increase inhibitory chloride influx; they never seal or weld it shut.\",\"tr\":\"Yanlış. Barbitüratlar kapıyı kaynaklamaz, aksine açarak aşırı inhibitör klorür girişine ve solunum arrestine yol açarlar.\",\"ar\":\"غير صحيح. تفتح الباربيتورات القناة وتدفق الكلوريد المثبط؛ ولا توصد الباب أو تغلقه أبداً.\"}}]},\"technicalTerms\":[{\"term\":\"allosterik modülasyon\",\"arContext\":\"التعديل التفارغي\"}],\"hints\":[{\"tier\":1,\"tr\":\"Anahtar (GABA) olmadan yağlanmış menteşe tek başına kapıyı açabilir mi? Asla.\",\"ar\":\"هل يمكن للمفصل المزيت أن يفتح الباب من تلقاء نفسه دون إدارة المفتاح؟ مستحيل.\",\"en\":\"Can oiled hinges swing the vault door open without someone turning the key? Never.\"},{\"tier\":2,\"tr\":\"Kapıyı levye ile kıran barbitürat ise anahtara ihtiyaç duymaz; içeri sel gibi klorür akar.\",\"ar\":\"أما من يخلع الباب (الباربيتورات) فلا يحتاج مفتاحاً؛ فيتدفق الكلوريد كالسيل دون مفتاح.\",\"en\":\"A crowbar (barbiturate) ignores the key entirely, letting a flood of chloride rush into the neuron.\"},{\"tier\":3,\"tr\":\"Bu yüzden benzodiyazepin güvenlidir: GABA yoksa kasa kapısı sıkıca kilitli kalır!\",\"ar\":\"لهذا السبب تعد البنزوديازيبينات آمنة: ففي غياب GABA يظل باب الخزنة موصداً بإحكام!\",\"en\":\"This is why benzodiazepines are safe: without GABA, the vault remains securely locked!\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_crowbar_analogy\",\"text\":{\"en\":\"Barbiturates crowbar the vault door wide open, forcing chloride influx continuously even if the GABA key is completely absent.\",\"tr\":\"Barbitüratlar kasa kapısını levye ile kırarak, GABA anahtarı hiç olmasa bile içeriye sürekli klorür akışı sağlarlar.\",\"ar\":\"تخلع الباربيتورات باب الخزنة عنوة، مما يدفق الكلوريد باستمرار حتى وإن غاب مفتاح GABA تماماً.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Barbiturates prolong channel open duration and directly force the pore open at anesthetic concentrations without GABA.\",\"tr\":\"Doğru! Barbitüratlar açık kalma süresini uzatır ve yüksek dozda GABA olmadan da kapıyı kırıp klorür akışı başlatırlar.\",\"ar\":\"صحيح! تطيل الباربيتورات مدة بقاء القناة مفتوحة وتجبرها على الانفتاح دون GABA عند التراكيز التخديرية.\"}},{\"id\":\"opt_conductance_increase\",\"text\":{\"en\":\"Barbiturates widen the physical diameter of the chloride filter, multiplying single-channel conductance five-fold without altering gating time.\",\"tr\":\"Barbitüratlar klorür filtresinin çapını genişleterek, açılma süresini değiştirmeden tek kanal iletkenliğini beş katına çıkarır.\",\"ar\":\"توسع الباربيتورات القطر الفيزيائي لمرشح الكلوريد مضاعفة توصيل القناة المفردة 5 أضعاف دون تغيير زمن الفتح.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Barbiturates alter gating kinetics (open duration and direct opening) rather than increasing the physical diameter or single-channel conductance.\",\"tr\":\"Yanlış. Barbitüratlar kanal çapını veya tekil iletkenliği artırmaz; açılma kinetiğini (süresini ve doğrudan açılmayı) değiştirir.\",\"ar\":\"غير صحيح. تعدل الباربيتورات حركية الفتح (إطالة زمن الانفتاح والفتح المباشر) ولا توسع القطر الفيزيائي للقناة.\"}},{\"id\":\"opt_kinetic_inversion\",\"text\":{\"en\":\"Barbiturates purely increase opening frequency while benzodiazepines prolong single-channel burst open duration.\",\"tr\":\"Barbitüratlar sadece açılma frekansını artırırken, benzodiyazepinler tek kanal patlama süresini uzatırlar.\",\"ar\":\"تزيد الباربيتورات تردد الفتح فقط، بينما تطيل البنزوديازيبينات مدة بقاء القناة مفتوحة.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Classic pharmacological rule: Benzodiazepines increase opening FREQUENCY; Barbiturates prolong opening DURATION.\",\"tr\":\"Yanlış. Klasik farmakoloji kuralı: Benzodiyazepinler açılma FREKANSINI artırır, Barbitüratlar ise açık kalma SÜRESİNİ uzatır.\",\"ar\":\"غير صحيح. القاعدة الدوائية الشهيرة: تزيد البنزوديازيبينات تردد الفتح، بينما تطيل الباربيتورات زمن الانفتاح.\"}},{\"id\":\"opt_destroy_hinges\",\"text\":{\"en\":\"Barbiturates weld the vault door shut, preventing chloride ions from entering the neuron and producing osmotic lysis.\",\"tr\":\"Barbitüratlar kasa kapısını kaynakla kapatır, klorür girişini engelleyerek nöronun ozmotik lizisine yol açar.\",\"ar\":\"تلحم الباربيتورات باب الخزنة مغلقاً مما يمنع دخول الكلوريد ويؤدي إلى انحلال الخلية تناضحياً.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Barbiturates open the door and increase inhibitory chloride influx; they never seal or weld it shut.\",\"tr\":\"Yanlış. Barbitüratlar kapıyı kaynaklamaz, aksine açarak aşırı inhibitör klorür girişine ve solunum arrestine yol açarlar.\",\"ar\":\"غير صحيح. تفتح الباربيتورات القناة وتدفق الكلوريد المثبط؛ ولا توصد الباب أو تغلقه أبداً.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":3}]},{\"id\":\"pharm-mod6-les1-step-04\",\"stage\":\"visual_explanation\",\"stageIndex\":4,\"title\":{\"tr\":\"GABA-A Pentamerik Klorür Kanal Kompleksi\",\"ar\":\"معقد قناة الكلوريد الخماسية GABA-A\",\"en\":\"GABA-A Pentameric Chloride Channel Complex\"},\"prompt\":{\"en\":\"The GABA-A receptor is a pentameric ($2\\\\alpha 2\\\\beta 1\\\\gamma$) chloride channel. Where do GABA and benzodiazepines bind, and what biophysical membrane event silences the neuron?\",\"tr\":\"GABA-A reseptörü pentamerik ($2\\\\alpha 2\\\\beta 1\\\\gamma$) bir klorür kanalıdır. GABA ve benzodiyazepinler nereye bağlanır ve hangi biyofiziksel olay nöronu susturur?\",\"ar\":\"مستقبل GABA-A قناة كلوريد خماسية الوحدات ($2\\\\alpha 2\\\\beta 1\\\\gamma$). أين يرتبط GABA والبنزوديازيبين، وما الحدث الحيوي الفيزيائي الذي يسكت العصبون؟\"},\"predictThenReveal\":false,\"config\":{\"options\":[{\"id\":\"opt_pentamer_architecture\",\"text\":{\"en\":\"GABA binds at alpha/beta interfaces; benzodiazepines bind at the alpha/gamma interface. Influxing Cl- hyperpolarizes membrane potential from -70 to -85 mV.\",\"tr\":\"GABA alfa/beta arayüzüne, benzodiyazepin alfa/gama arayüzüne bağlanır. Klor girişi zar potansiyelini -70'ten -85 mV'a hiperpolarize eder.\",\"ar\":\"يرتبط GABA بأسطح التماس ألفا/بيتا، والبنزوديازيبين بسطح ألفا/غاما. يدفق الكلوريد لفرط استقطاب الغشاء من -70 إلى -85 ميلي فولت.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Two GABA molecules bind between alpha and beta subunits. BZDs bind between alpha and gamma, enhancing Cl- influx and hyperpolarization.\",\"tr\":\"Doğru! GABA alfa/beta arasına, BZD ise alfa/gama arayüzüne bağlanır. Klor girişi zarı hiperpolarize ederek nöronda IPSP oluşturur.\",\"ar\":\"صحيح! يرتبط جزيئا GABA بين ألفا وبيتا، ويرتبط البنزوديازيبين بين ألفا وغاما معززاً فرط الاستقطاب وتثبيط العصبون.\"}},{\"id\":\"opt_orthosteric_competition\",\"text\":{\"en\":\"Benzodiazepines compete directly with GABA at both alpha/beta interfaces, acting as partial agonists that displace endogenous neurotransmitter.\",\"tr\":\"Benzodiyazepinler her iki alfa/beta arayüzünde GABA ile doğrudan yarışarak endojen nörotransmitterin yerini alan parsiyel agonistlerdir.\",\"ar\":\"تنافس البنزوديازيبينات GABA مباشرة عند سطحي ألفا/بيتا، كناهضات جزئية تزيح الناقل العصبي الداخلي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Benzodiazepines bind allosterically at the alpha/gamma interface, not the orthosteric alpha/beta GABA binding pocket.\",\"tr\":\"Yanlış. Benzodiyazepinler ortosterik alfa/beta cebine değil, allosterik alfa/gama arayüzüne bağlanırlar.\",\"ar\":\"غير صحيح. ترتبط البنزوديازيبينات تفارغياً عند سطح التماس ألفا/غاما وليس في جيب GABA الأصلي بين ألفا وبيتا.\"}},{\"id\":\"opt_pore_lumen_binding\",\"text\":{\"en\":\"Benzodiazepines bind inside the central pore lumen to physically pull the channel walls outward and enlarge the water-filled diameter.\",\"tr\":\"Benzodiyazepinler merkezi kanal lümenine bağlanarak kanal duvarlarını fiziksel olarak çeker ve klorür çapını genişletir.\",\"ar\":\"ترتبط البنزوديازيبينات داخل لمعة القناة المركزية لتسحب جدرانها فيزيائياً وتوسع قطرها المائي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Channel lumen blockers like picrotoxin bind inside the pore. Benzodiazepines bind the extracellular domain at the alpha/gamma interface.\",\"tr\":\"Yanlış. Kanal lümenine pikrotoksin gibi kanal blokörleri bağlanır; benzodiyazepinler ekstraselüler alfa/gama arayüzüne bağlanır.\",\"ar\":\"غير صحيح. ترتبط حاصرات اللمعة (مثل البيكروتوكسين) داخل القناة، بينما يرتبط البنزوديازيبين بالنطاق الخارجي عند ألفا/غاما.\"}},{\"id\":\"opt_depolarization_confusion\",\"text\":{\"en\":\"Chloride influx depolarizes the neuronal membrane from -70 to 0 mV, provoking rapid inactivation of voltage-gated sodium channels.\",\"tr\":\"Klorür girişi nöron zarını -70'ten 0 mV'a depolarize ederek voltaj kapılı sodyum kanallarını hızla inaktive eder.\",\"ar\":\"يؤدي دخول الكلوريد إلى نزع استقطاب الغشاء من -70 إلى 0 ميلي فولت مما يعطل قنوات الصوديوم.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Anion (Cl-) influx drives the resting membrane potential more negative (hyperpolarization, -70 to -85 mV), moving it away from threshold.\",\"tr\":\"Yanlış. Negatif klorür iyonlarının girişi zarı depolarize etmez; hiperpolarize ederek (-85 mV) aksiyon potansiyeli eşiğinden uzaklaştırır.\",\"ar\":\"غير صحيح. تدفق أنيونات الكلوريد السالبة يفرط استقطاب الغشاء نحو مزيد من السلبية (-85 ميلي فولت) مبعداً إياه عن عتبة التنبيه.\"}}]},\"technicalTerms\":[{\"term\":\"klorür kanalı\",\"arContext\":\"قناة الكلوريد\"}],\"hints\":[{\"tier\":1,\"tr\":\"GABA-A reseptörü beş alt birimden oluşan heteropentamerik bir anyon kanalıdır.\",\"ar\":\"مستقبل GABA-A قناة أنيونية خماسية خلوية متغايرة الوحدات.\",\"en\":\"The GABA-A receptor is a heteropentameric anion pore composed of five distinct protein subunits.\"},{\"tier\":2,\"tr\":\"GABA molekülleri alfa/beta arasına, benzodiyazepinler ise alfa/gama arayüzüne kenetlenir.\",\"ar\":\"ترتبط جزيئات GABA بين ألفا وبيتا، بينما تستقر البنزوديازيبينات عند سطح التماس بين ألفا وغاما.\",\"en\":\"GABA binds at the two alpha/beta interfaces; benzodiazepines nestle at the alpha/gamma interface.\"},{\"tier\":3,\"tr\":\"İçeri giren Cl- iyonları zarı -70'ten -85 mV'a hiperpolarize ederek aksiyon potansiyelini susturur.\",\"ar\":\"تدفق أيونات الكلوريد يفرط استقطاب الغشاء من -70 إلى -85 ميلي فولت مسكتاً جهود الفعل العصبية.\",\"en\":\"Influxing Cl- hyperpolarizes membrane potential from -70 to -85 mV, establishing a silencing IPSP.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_pentamer_architecture\",\"text\":{\"en\":\"GABA binds at alpha/beta interfaces; benzodiazepines bind at the alpha/gamma interface. Influxing Cl- hyperpolarizes membrane potential from -70 to -85 mV.\",\"tr\":\"GABA alfa/beta arayüzüne, benzodiyazepin alfa/gama arayüzüne bağlanır. Klor girişi zar potansiyelini -70'ten -85 mV'a hiperpolarize eder.\",\"ar\":\"يرتبط GABA بأسطح التماس ألفا/بيتا، والبنزوديازيبين بسطح ألفا/غاما. يدفق الكلوريد لفرط استقطاب الغشاء من -70 إلى -85 ميلي فولت.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Two GABA molecules bind between alpha and beta subunits. BZDs bind between alpha and gamma, enhancing Cl- influx and hyperpolarization.\",\"tr\":\"Doğru! GABA alfa/beta arasına, BZD ise alfa/gama arayüzüne bağlanır. Klor girişi zarı hiperpolarize ederek nöronda IPSP oluşturur.\",\"ar\":\"صحيح! يرتبط جزيئا GABA بين ألفا وبيتا، ويرتبط البنزوديازيبين بين ألفا وغاما معززاً فرط الاستقطاب وتثبيط العصبون.\"}},{\"id\":\"opt_orthosteric_competition\",\"text\":{\"en\":\"Benzodiazepines compete directly with GABA at both alpha/beta interfaces, acting as partial agonists that displace endogenous neurotransmitter.\",\"tr\":\"Benzodiyazepinler her iki alfa/beta arayüzünde GABA ile doğrudan yarışarak endojen nörotransmitterin yerini alan parsiyel agonistlerdir.\",\"ar\":\"تنافس البنزوديازيبينات GABA مباشرة عند سطحي ألفا/بيتا، كناهضات جزئية تزيح الناقل العصبي الداخلي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Benzodiazepines bind allosterically at the alpha/gamma interface, not the orthosteric alpha/beta GABA binding pocket.\",\"tr\":\"Yanlış. Benzodiyazepinler ortosterik alfa/beta cebine değil, allosterik alfa/gama arayüzüne bağlanırlar.\",\"ar\":\"غير صحيح. ترتبط البنزوديازيبينات تفارغياً عند سطح التماس ألفا/غاما وليس في جيب GABA الأصلي بين ألفا وبيتا.\"}},{\"id\":\"opt_pore_lumen_binding\",\"text\":{\"en\":\"Benzodiazepines bind inside the central pore lumen to physically pull the channel walls outward and enlarge the water-filled diameter.\",\"tr\":\"Benzodiyazepinler merkezi kanal lümenine bağlanarak kanal duvarlarını fiziksel olarak çeker ve klorür çapını genişletir.\",\"ar\":\"ترتبط البنزوديازيبينات داخل لمعة القناة المركزية لتسحب جدرانها فيزيائياً وتوسع قطرها المائي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Channel lumen blockers like picrotoxin bind inside the pore. Benzodiazepines bind the extracellular domain at the alpha/gamma interface.\",\"tr\":\"Yanlış. Kanal lümenine pikrotoksin gibi kanal blokörleri bağlanır; benzodiyazepinler ekstraselüler alfa/gama arayüzüne bağlanır.\",\"ar\":\"غير صحيح. ترتبط حاصرات اللمعة (مثل البيكروتوكسين) داخل القناة، بينما يرتبط البنزوديازيبين بالنطاق الخارجي عند ألفا/غاما.\"}},{\"id\":\"opt_depolarization_confusion\",\"text\":{\"en\":\"Chloride influx depolarizes the neuronal membrane from -70 to 0 mV, provoking rapid inactivation of voltage-gated sodium channels.\",\"tr\":\"Klorür girişi nöron zarını -70'ten 0 mV'a depolarize ederek voltaj kapılı sodyum kanallarını hızla inaktive eder.\",\"ar\":\"يؤدي دخول الكلوريد إلى نزع استقطاب الغشاء من -70 إلى 0 ميلي فولت مما يعطل قنوات الصوديوم.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Anion (Cl-) influx drives the resting membrane potential more negative (hyperpolarization, -70 to -85 mV), moving it away from threshold.\",\"tr\":\"Yanlış. Negatif klorür iyonlarının girişi zarı depolarize etmez; hiperpolarize ederek (-85 mV) aksiyon potansiyeli eşiğinden uzaklaştırır.\",\"ar\":\"غير صحيح. تدفق أنيونات الكلوريد السالبة يفرط استقطاب الغشاء نحو مزيد من السلبية (-85 ميلي فولت) مبعداً إياه عن عتبة التنبيه.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":4}]},{\"id\":\"pharm-mod6-les1-step-05\",\"stage\":\"interactive_artifact\",\"stageIndex\":5,\"title\":{\"tr\":\"İnteraktif Simülatör: Dose-Response Modulator (Allosterik Kayma)\",\"ar\":\"محاكي تفاعلي: معدل الجرعة والاستجابة (الإزاحة التفارغية)\",\"en\":\"Interactive Simulator: DoseResponse Modulator (Allosteric Shift)\"},\"prompt\":{\"en\":\"Observe the GABA concentration-response curve: add diazepam to witness the leftward shift, then add flumazenil to restore baseline.\",\"tr\":\"Konsantrasyon-yanıt eğrisini izleyin: sola kaymayı görmek için diyazepam ekleyin, ardından başlangıç çizgisine dönmek için flumazenil verin.\",\"ar\":\"راقب منحنى التركيز والاستجابة لـ GABA: أضف الديازيبام لمشاهدة الإزاحة نحو اليسار، ثم أضف الفلومازينيل لاستعادة خط الأساس.\"},\"predictThenReveal\":false,\"config\":{\"title\":\"GABA-A Konsantrasyon-Yanıt ve Allosterik Modülasyon\",\"prompt\":\"GABA konsantrasyonunu artırın; diazepam ekleyerek sola kaymayı ve flumazenil ile nötrleşmeyi izleyin.\",\"defaultEc50\":10,\"defaultEmax\":100,\"defaultHillSlope\":1,\"modes\":[\"agonist\",\"competitive_antagonist\",\"partial_agonist\"],\"source\":{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":6},\"explanation\":\"Diazepam pozitif allosterik modülatör (PAM) olarak GABA'nın afinitesini artırır ve eğriyi sola kaydırır (EC50 10 uM'den 1 uM'ye düşer). Flumazenil ise BZD bölgesinde yarışmalı nötral antagonist olarak etkiyi sıfırlar.\"},\"technicalTerms\":[{\"term\":\"etki mekanizması\",\"arContext\":\"آلية التأثير الدوائي\"},{\"term\":\"reseptör\",\"arContext\":\"المستقبِل الحيوي\"}],\"hints\":[{\"tier\":1,\"tr\":\"Eğrinin sağa mı sola mı kaydığını ve Emax tavanının değişip değişmediğini inceleyin.\",\"ar\":\"لاحظ هل ينزاح المنحنى يميناً أم يساراً، وما إذا كان سقف Emax يتغير أم يثبت.\",\"en\":\"Observe whether the curve shifts left or right, and note if the maximal efficacy ceiling changes.\"},{\"tier\":2,\"tr\":\"Diyazepam GABA afinitesini artırarak EC50 değerini düşürür, ancak Emax değerini artıramaz.\",\"ar\":\"يزيد الديازيبام ألفة GABA مخفضاً قيمة EC50، لكنه يعجز عن رفع Emax فوق سقفها الأصلي.\",\"en\":\"Diazepam augments GABA affinity to lower EC50, but cannot elevate Emax above baseline.\"},{\"tier\":3,\"tr\":\"Flumazenil eklendiğinde diyazepam BZD bölgesinden sökülür ve eğri tam orijinal baseline hattına döner.\",\"ar\":\"عند إضافة الفلومازينيل يُزاح الديازيبام من موقع البنزوديازيبين ويعود المنحنى لخط الأساس تماماً.\",\"en\":\"Adding flumazenil displaces diazepam from the BZD pocket, snapping the curve back to baseline.\"}],\"widgetType\":\"DoseResponseCurve\",\"widget\":{\"type\":\"DoseResponseCurve\",\"config\":{\"title\":\"GABA-A Konsantrasyon-Yanıt ve Allosterik Modülasyon\",\"prompt\":\"GABA konsantrasyonunu artırın; diazepam ekleyerek sola kaymayı ve flumazenil ile nötrleşmeyi izleyin.\",\"defaultEc50\":10,\"defaultEmax\":100,\"defaultHillSlope\":1,\"modes\":[\"agonist\",\"competitive_antagonist\",\"partial_agonist\"],\"source\":{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":6},\"explanation\":\"Diazepam pozitif allosterik modülatör (PAM) olarak GABA'nın afinitesini artırır ve eğriyi sola kaydırır (EC50 10 uM'den 1 uM'ye düşer). Flumazenil ise BZD bölgesinde yarışmalı nötral antagonist olarak etkiyi sıfırlar.\"}},\"conceptCheck\":{\"options\":[]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":5}]},{\"id\":\"pharm-mod6-les1-step-06\",\"stage\":\"guided_discovery\",\"stageIndex\":6,\"title\":{\"tr\":\"Rehberli Keşif: Benzodiyazepin vs Barbitürat Güvenliği\",\"ar\":\"استكشاف موجه: أمان البنزوديازيبين مقابل الباربيتورات\",\"en\":\"Guided Discovery: Benzodiazepine vs Barbiturate Safety\"},\"prompt\":{\"en\":\"In the concentration-response curve, diazepam shifts the curve leftward (lowering EC50) without elevating baseline Emax. Why does this pharmacodynamic ceiling protect against fatal overdose?\",\"tr\":\"Konsantrasyon-yanıt eğrisinde diyazepam EC50'yi düşürerek eğriyi sola kaydırır ancak Emax'ı artırmaz. Bu farmakodinamik tavan aşırı dozda neden hayat kurtarır?\",\"ar\":\"يزيح الديازيبام منحنى التركيز والاستجابة يساراً (يخفض EC50) دون رفع Emax. لماذا يحمي هذا السقف الديناميكي الدوائي من الموت بالجرعة الزائدة؟\"},\"predictThenReveal\":true,\"config\":{\"revealedOutcome\":\"Benzodiyazepinler GABA bağımlı tavan etkileri sayesinde çok daha güvenlidir.\",\"options\":[{\"id\":\"opt_gaba_ceiling_protects\",\"text\":{\"en\":\"Maximal inhibition is strictly limited by the finite amount of physiological GABA released, preventing uncontrolled hyperpolarization of respiratory pacemakers.\",\"tr\":\"Maksimal inhibisyon sinapsa salınan fizyolojik GABA miktarı ile sınırlıdır; solunum merkezlerinin kontrolsüz baskılanması engellenir.\",\"ar\":\"التثبيط الأعظمي مقيد بكمية GABA الفسيولوجية المفرزة، مما يمنع فرط الاستقطاب العشوائي لمراكز التنفس النخاعية.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Because PAMs require GABA, once all endogenous GABA is bound, no further hyperpolarization can occur regardless of BZD dose.\",\"tr\":\"Doğru! PAM'lar GABA'ya muhtaçtır; salınan tüm GABA bağlandığında BZD dozu ne kadar artarsa artsın daha fazla klorür girişi olamaz.\",\"ar\":\"صحيح! نظراً لأن المعدلات التفارغية تتطلب GABA، فبمجرد ارتباط كل GABA المفرز لا يمكن حدوث مزيد من التثبيط مهما زادت جرعة البنزوديازيبين.\"}},{\"id\":\"opt_full_agonist_confusion\",\"text\":{\"en\":\"Diazepam acts as an irreversible antagonist at high concentrations, automatically closing chloride channels when blood levels exceed therapeutic range.\",\"tr\":\"Diyazepam yüksek konsantrasyonlarda irreversibl antagoniste dönüşerek, terapötik düzey aşıldığında klorür kanallarını otomatik kapatır.\",\"ar\":\"يتحول الديازيبام لمناهض غير عكوس عند التراكيز العالية فيغلق قنوات الكلوريد تلقائياً عند تجاوز النطاق العلاجي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Diazepam remains a positive allosteric modulator at all doses; it never converts into an antagonist or channel blocker.\",\"tr\":\"Yanlış. Diyazepam tüm dozlarda pozitif allosterik modülatör kalır; asla antagoniste veya kanal blokörüne dönüşmez.\",\"ar\":\"غير صحيح. يظل الديازيبام معدلاً تفارغياً إيجابياً عند جميع الجرعات، ولا ينقلب لمناهض أو حاصِر للقناة أبداً.\"}},{\"id\":\"opt_exceed_emax_belief\",\"text\":{\"en\":\"PAMs elevate Emax beyond 100% by recruiting voltage-gated potassium channels to assist in inhibitory hyperpolarization.\",\"tr\":\"PAM'lar voltaj kapılı potasyum kanallarını da sürece dahil ederek Emax değerini %100'ün üzerine çıkarırlar.\",\"ar\":\"ترفع المعدلات التفارغية Emax فوق 100% بتجنيد قنوات البوتاسيوم المعتمدة على الفولتية للمساعدة بالتثبيط.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. A pure PAM modulates only the receptor it binds; it does not recruit potassium channels or exceed the full agonist's maximal efficacy.\",\"tr\":\"Yanlış. Saf bir PAM sadece kendi reseptörünü modüle eder; potasyum kanallarını aktive etmez veya Emax tavanını aşamaz.\",\"ar\":\"غير صحيح. تعدل الربيطة التفارغية مستقبلها فقط، ولا تجند قنوات بوتاسيوم أو ترفع Emax فوق سقف الناقل الأصلي.\"}},{\"id\":\"opt_renal_clearance_ceiling\",\"text\":{\"en\":\"The ceiling effect is an artifact caused by rapid glomerular filtration exceeding receptor binding saturation.\",\"tr\":\"Tavan etkisi, glomerüler filtrasyon hızının reseptör bağlanma doygunluğunu aşmasından kaynaklanan bir farmakokinetik yanılsamadır.\",\"ar\":\"تأثير السقف مجرد وهم حركي دوائي ناجم عن تجاوز معدل الترشيح الكبيبي لإشباع الارتباط بالمستقبلات.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. The safety ceiling is intrinsic to receptor pharmacodynamics (absence of direct pore gating), not renal clearance.\",\"tr\":\"Yanlış. Güvenlik tavanı böbrek atılımından değil, doğrudan kanal açamama şeklindeki reseptör farmakodinamiğinden kaynaklanır.\",\"ar\":\"غير صحيح. ينبع سقف الأمان من الديناميكا الدوائية للمستقبل وغياب الفتح المباشر للقناة، وليس من الإطراح الكلوي.\"}}]},\"technicalTerms\":[{\"term\":\"etki mekanizması\",\"arContext\":\"آلية التأثير الدوائي\"},{\"term\":\"reseptör\",\"arContext\":\"المستقبِل الحيوي\"}],\"hints\":[{\"tier\":1,\"tr\":\"Reseptörün verebileceği en yüksek yanıtı kim belirler: allosterik modülatör mü, yoksa nörotransmitter mi?\",\"ar\":\"من يحدد الاستجابة القصوى للمستقبل: المعدل التفارغي أم الناقل العصبي الفسيولوجي؟\",\"en\":\"What defines the ceiling of inhibition: the allosteric modulator or the physiological neurotransmitter?\"},{\"tier\":2,\"tr\":\"PAM sadece endojen GABA'nın etkinliğini artırır; sinapstaki tüm GABA bağlandığında etki doyar.\",\"ar\":\"يضاعف PAM كفاءة GABA الداخلي فقط؛ وعند ارتباط كامل GABA ينتهي أي تأثير إضافي.\",\"en\":\"A PAM purely amplifies endogenous GABA; once all released GABA is bound, effect saturates.\"},{\"tier\":3,\"tr\":\"Bu tavan, kontrolsüz aşırı hiperpolarizasyonu ve solunum merkezlerinin çökmesini önler.\",\"ar\":\"يحمي هذا السقف الدوائي من فرط الاستقطاب العشوائي وانهيار مركز التنفس بالجرعات المفرطة.\",\"en\":\"This ceiling prevents uncontrolled neuronal silencing and protects against fatal respiratory arrest.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_gaba_ceiling_protects\",\"text\":{\"en\":\"Maximal inhibition is strictly limited by the finite amount of physiological GABA released, preventing uncontrolled hyperpolarization of respiratory pacemakers.\",\"tr\":\"Maksimal inhibisyon sinapsa salınan fizyolojik GABA miktarı ile sınırlıdır; solunum merkezlerinin kontrolsüz baskılanması engellenir.\",\"ar\":\"التثبيط الأعظمي مقيد بكمية GABA الفسيولوجية المفرزة، مما يمنع فرط الاستقطاب العشوائي لمراكز التنفس النخاعية.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Because PAMs require GABA, once all endogenous GABA is bound, no further hyperpolarization can occur regardless of BZD dose.\",\"tr\":\"Doğru! PAM'lar GABA'ya muhtaçtır; salınan tüm GABA bağlandığında BZD dozu ne kadar artarsa artsın daha fazla klorür girişi olamaz.\",\"ar\":\"صحيح! نظراً لأن المعدلات التفارغية تتطلب GABA، فبمجرد ارتباط كل GABA المفرز لا يمكن حدوث مزيد من التثبيط مهما زادت جرعة البنزوديازيبين.\"}},{\"id\":\"opt_full_agonist_confusion\",\"text\":{\"en\":\"Diazepam acts as an irreversible antagonist at high concentrations, automatically closing chloride channels when blood levels exceed therapeutic range.\",\"tr\":\"Diyazepam yüksek konsantrasyonlarda irreversibl antagoniste dönüşerek, terapötik düzey aşıldığında klorür kanallarını otomatik kapatır.\",\"ar\":\"يتحول الديازيبام لمناهض غير عكوس عند التراكيز العالية فيغلق قنوات الكلوريد تلقائياً عند تجاوز النطاق العلاجي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Diazepam remains a positive allosteric modulator at all doses; it never converts into an antagonist or channel blocker.\",\"tr\":\"Yanlış. Diyazepam tüm dozlarda pozitif allosterik modülatör kalır; asla antagoniste veya kanal blokörüne dönüşmez.\",\"ar\":\"غير صحيح. يظل الديازيبام معدلاً تفارغياً إيجابياً عند جميع الجرعات، ولا ينقلب لمناهض أو حاصِر للقناة أبداً.\"}},{\"id\":\"opt_exceed_emax_belief\",\"text\":{\"en\":\"PAMs elevate Emax beyond 100% by recruiting voltage-gated potassium channels to assist in inhibitory hyperpolarization.\",\"tr\":\"PAM'lar voltaj kapılı potasyum kanallarını da sürece dahil ederek Emax değerini %100'ün üzerine çıkarırlar.\",\"ar\":\"ترفع المعدلات التفارغية Emax فوق 100% بتجنيد قنوات البوتاسيوم المعتمدة على الفولتية للمساعدة بالتثبيط.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. A pure PAM modulates only the receptor it binds; it does not recruit potassium channels or exceed the full agonist's maximal efficacy.\",\"tr\":\"Yanlış. Saf bir PAM sadece kendi reseptörünü modüle eder; potasyum kanallarını aktive etmez veya Emax tavanını aşamaz.\",\"ar\":\"غير صحيح. تعدل الربيطة التفارغية مستقبلها فقط، ولا تجند قنوات بوتاسيوم أو ترفع Emax فوق سقف الناقل الأصلي.\"}},{\"id\":\"opt_renal_clearance_ceiling\",\"text\":{\"en\":\"The ceiling effect is an artifact caused by rapid glomerular filtration exceeding receptor binding saturation.\",\"tr\":\"Tavan etkisi, glomerüler filtrasyon hızının reseptör bağlanma doygunluğunu aşmasından kaynaklanan bir farmakokinetik yanılsamadır.\",\"ar\":\"تأثير السقف مجرد وهم حركي دوائي ناجم عن تجاوز معدل الترشيح الكبيبي لإشباع الارتباط بالمستقبلات.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. The safety ceiling is intrinsic to receptor pharmacodynamics (absence of direct pore gating), not renal clearance.\",\"tr\":\"Yanlış. Güvenlik tavanı böbrek atılımından değil, doğrudan kanal açamama şeklindeki reseptör farmakodinamiğinden kaynaklanır.\",\"ar\":\"غير صحيح. ينبع سقف الأمان من الديناميكا الدوائية للمستقبل وغياب الفتح المباشر للقناة، وليس من الإطراح الكلوي.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":6}]},{\"id\":\"pharm-mod6-les1-step-07\",\"stage\":\"formal_explanation\",\"stageIndex\":7,\"title\":{\"tr\":\"Hiperpolarizasyon ve Nöronal İnhibisyon\",\"ar\":\"فرط الاستقطاب والتثبيط العصبي\",\"en\":\"Formal Electrophysiology: Hyperpolarization & Shunt Inhibition\"},\"prompt\":{\"en\":\"How do the molecular gating mechanisms of benzodiazepines and barbiturates fundamentally differ, and how does flumazenil interact with this system?\",\"tr\":\"Benzodiyazepinler ve barbitüratların moleküler kanal açma mekanizmaları nasıl ayrışır ve flumazenil bu sistemle nasıl etkileşir?\",\"ar\":\"كيف تختلف آليات الفتح الجزيئي للبنزوديازيبينات والباربيتورات، وكيف يتفاعل الفلومازينيل مع هذا النظام؟\"},\"predictThenReveal\":false,\"config\":{\"options\":[{\"id\":\"opt_freq_dur_flumazenil\",\"text\":{\"en\":\"BZDs increase opening FREQUENCY; barbiturates prolong open DURATION and directly gate the pore. Flumazenil is a neutral antagonist at the BZD site.\",\"tr\":\"BZD'ler açılma FREKANSINI artırır; barbitüratlar SÜREYİ uzatır ve doğrudan kanal açar. Flumazenil ise BZD bölgesinde nötral antagonisttir.\",\"ar\":\"تزيد البنزوديازيبينات تردد الفتح؛ بينما تطيل الباربيتورات مدة الفتح وتفتح القناة مباشرة. الفلومازينيل مناهض محايد في موقع البنزوديازيبين.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! BZDs increase frequency (GABA-dependent); barbiturates prolong duration and directly gate pore. Flumazenil competitively blocks the BZD site.\",\"tr\":\"Doğru! BZD frekansı artırır (GABA bağımlı), barbitürat süreyi uzatır ve doğrudan açar. Flumazenil BZD bölgesinde yarışmalı nötr antagonisttir.\",\"ar\":\"صحيح! تزيد البنزوديازيبينات التردد، وتطيل الباربيتورات المدة وتفتح مباشرة. يعاكس الفلومازينيل موقع البنزوديازيبين تنافسياً.\"}},{\"id\":\"opt_flumazenil_inverse\",\"text\":{\"en\":\"Flumazenil acts as a negative allosteric modulator (inverse agonist) that closes chloride channels below basal constitutive activity.\",\"tr\":\"Flumazenil, klorür kanallarını bazal düzeyin altına kapatan bir negatif allosterik modülatördür (invers agonisttir).\",\"ar\":\"يعمل الفلومازينيل كمعدل تفارغي سلبي (ناهض عكسي) يغلق قنوات الكلوريد لما دون النشاط التكويني الأساسي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Flumazenil is a NEUTRAL competitive antagonist with zero intrinsic efficacy; beta-carbolines (e.g. DMCM) are the inverse agonists.\",\"tr\":\"Yanlış. Flumazenil intrensek etkisi sıfır olan NÖTRAL antagonisttir; klorür akışını bazalin altına düşüren invers agonistler beta-karbolinlerdir.\",\"ar\":\"غير صحيح. الفلومازينيل مناهض تنافسي محايد بلا فاعلية ذاتية؛ أما من يخفض تدفق الكلوريد دون الأساس (ناهض عكسي) فهي البيتاركاربينات.\"}},{\"id\":\"opt_flumazenil_reverses_barbs\",\"text\":{\"en\":\"Flumazenil reverses barbiturate toxicity with high affinity by occupying the barbiturate-binding pocket inside the pore lumen.\",\"tr\":\"Flumazenil, lümendeki barbitürat cebine yüksek afiniteyle bağlanarak barbitürat zehirlenmesini tamamen geri çevirir.\",\"ar\":\"يعاكس الفلومازينيل سمية الباربيتورات بألفة عالية عبر احتلال جيب ارتباط الباربيتورات داخل لمعة القناة.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Flumazenil binds exclusively to the benzodiazepine site (alpha/gamma interface) and CANNOT reverse barbiturate toxicity.\",\"tr\":\"Yanlış. Flumazenil sadece benzodiyazepin bölgesine bağlanır; barbitürat zehirlenmesini ASLA geri döndüremez.\",\"ar\":\"غير صحيح. يرتبط الفلومازينيل حصرياً بموقع البنزوديازيبين (ألفا/غاما) ولا يعاكس إطلاقاً سمية الباربيتورات.\"}},{\"id\":\"opt_enzymatic_degradation\",\"text\":{\"en\":\"Flumazenil acts as an enzyme that catalytically hydrolyzes the 1,4-diazepine ring of circulating benzodiazepines into inactive metabolites.\",\"tr\":\"Flumazenil, kandaki benzodiyazepinlerin 1,4-diazepin halkasını hidroliz ederek inaktive eden bir enzimdir.\",\"ar\":\"يعمل الفلومازينيل كإنزيم يحلمئ حلقة 1,4-ديازيبين في البنزوديازيبينات الدورية إلى نواتج استقلاب غير فعالة.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Flumazenil is a competitive receptor antagonist that binds reversibly to the GABA-A receptor, not an enzyme.\",\"tr\":\"Yanlış. Flumazenil bir enzim değil, reseptöre tersinir bağlanan yarışmalı bir reseptör antagonistidir.\",\"ar\":\"غير صحيح. الفلومازينيل ربيطة مناهضة تنافسية ترتبط بالمستقبل عكوسياً وليس إنزيماً مفككاً للدواء.\"}}]},\"technicalTerms\":[{\"term\":\"hiperpolarizasyon\",\"arContext\":\"فرط الاستقطاب (Hyperpolarization)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Kanal kinetiğinde 'açılma sıklığı' ile 'açık kalma süresi' arasındaki farkı hatırlayın.\",\"ar\":\"تذكر الفرق الجوهري في حركية القنوات بين 'تردد مرات الفتح' و'مدة بقاء القناة مفتوحة'.\",\"en\":\"Recall the key biophysical distinction between channel opening frequency and open burst duration.\"},{\"tier\":2,\"tr\":\"Benzodiyazepinler frekansı artırır; barbitüratlar ise süreyi uzatır ve doğrudan kanalı açar.\",\"ar\":\"تزيد البنزوديازيبينات تردد الفتح؛ بينما تطيل الباربيتورات مدة الفتح وتفتح القناة مباشرة.\",\"en\":\"Benzodiazepines increase opening frequency; barbiturates prolong open duration and directly gate the pore.\"},{\"tier\":3,\"tr\":\"Flumazenil BZD bölgesinde yarışmalı nötral antagonisttir; etkiyi sıfırlar ama kanalı tek başına kapatmaz.\",\"ar\":\"الفلومازينيل مناهض تنافسي محايد؛ يعاكس تأثير البنزوديازيبين دون أن يثبط القناة بمفرده.\",\"en\":\"Flumazenil is a neutral competitive antagonist; it resets BZD effect with zero intrinsic inverse efficacy.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_freq_dur_flumazenil\",\"text\":{\"en\":\"BZDs increase opening FREQUENCY; barbiturates prolong open DURATION and directly gate the pore. Flumazenil is a neutral antagonist at the BZD site.\",\"tr\":\"BZD'ler açılma FREKANSINI artırır; barbitüratlar SÜREYİ uzatır ve doğrudan kanal açar. Flumazenil ise BZD bölgesinde nötral antagonisttir.\",\"ar\":\"تزيد البنزوديازيبينات تردد الفتح؛ بينما تطيل الباربيتورات مدة الفتح وتفتح القناة مباشرة. الفلومازينيل مناهض محايد في موقع البنزوديازيبين.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! BZDs increase frequency (GABA-dependent); barbiturates prolong duration and directly gate pore. Flumazenil competitively blocks the BZD site.\",\"tr\":\"Doğru! BZD frekansı artırır (GABA bağımlı), barbitürat süreyi uzatır ve doğrudan açar. Flumazenil BZD bölgesinde yarışmalı nötr antagonisttir.\",\"ar\":\"صحيح! تزيد البنزوديازيبينات التردد، وتطيل الباربيتورات المدة وتفتح مباشرة. يعاكس الفلومازينيل موقع البنزوديازيبين تنافسياً.\"}},{\"id\":\"opt_flumazenil_inverse\",\"text\":{\"en\":\"Flumazenil acts as a negative allosteric modulator (inverse agonist) that closes chloride channels below basal constitutive activity.\",\"tr\":\"Flumazenil, klorür kanallarını bazal düzeyin altına kapatan bir negatif allosterik modülatördür (invers agonisttir).\",\"ar\":\"يعمل الفلومازينيل كمعدل تفارغي سلبي (ناهض عكسي) يغلق قنوات الكلوريد لما دون النشاط التكويني الأساسي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Flumazenil is a NEUTRAL competitive antagonist with zero intrinsic efficacy; beta-carbolines (e.g. DMCM) are the inverse agonists.\",\"tr\":\"Yanlış. Flumazenil intrensek etkisi sıfır olan NÖTRAL antagonisttir; klorür akışını bazalin altına düşüren invers agonistler beta-karbolinlerdir.\",\"ar\":\"غير صحيح. الفلومازينيل مناهض تنافسي محايد بلا فاعلية ذاتية؛ أما من يخفض تدفق الكلوريد دون الأساس (ناهض عكسي) فهي البيتاركاربينات.\"}},{\"id\":\"opt_flumazenil_reverses_barbs\",\"text\":{\"en\":\"Flumazenil reverses barbiturate toxicity with high affinity by occupying the barbiturate-binding pocket inside the pore lumen.\",\"tr\":\"Flumazenil, lümendeki barbitürat cebine yüksek afiniteyle bağlanarak barbitürat zehirlenmesini tamamen geri çevirir.\",\"ar\":\"يعاكس الفلومازينيل سمية الباربيتورات بألفة عالية عبر احتلال جيب ارتباط الباربيتورات داخل لمعة القناة.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Flumazenil binds exclusively to the benzodiazepine site (alpha/gamma interface) and CANNOT reverse barbiturate toxicity.\",\"tr\":\"Yanlış. Flumazenil sadece benzodiyazepin bölgesine bağlanır; barbitürat zehirlenmesini ASLA geri döndüremez.\",\"ar\":\"غير صحيح. يرتبط الفلومازينيل حصرياً بموقع البنزوديازيبين (ألفا/غاما) ولا يعاكس إطلاقاً سمية الباربيتورات.\"}},{\"id\":\"opt_enzymatic_degradation\",\"text\":{\"en\":\"Flumazenil acts as an enzyme that catalytically hydrolyzes the 1,4-diazepine ring of circulating benzodiazepines into inactive metabolites.\",\"tr\":\"Flumazenil, kandaki benzodiyazepinlerin 1,4-diazepin halkasını hidroliz ederek inaktive eden bir enzimdir.\",\"ar\":\"يعمل الفلومازينيل كإنزيم يحلمئ حلقة 1,4-ديازيبين في البنزوديازيبينات الدورية إلى نواتج استقلاب غير فعالة.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Flumazenil is a competitive receptor antagonist that binds reversibly to the GABA-A receptor, not an enzyme.\",\"tr\":\"Yanlış. Flumazenil bir enzim değil, reseptöre tersinir bağlanan yarışmalı bir reseptör antagonistidir.\",\"ar\":\"غير صحيح. الفلومازينيل ربيطة مناهضة تنافسية ترتبط بالمستقبل عكوسياً وليس إنزيماً مفككاً للدواء.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":7}]},{\"id\":\"pharm-mod6-les1-step-08\",\"stage\":\"concept_check\",\"stageIndex\":8,\"title\":{\"tr\":\"Kavram Denetimi: Frekans mı Süre mi?\",\"ar\":\"فحص المفهوم: التواتر أم مدة الفتح؟\",\"en\":\"Concept Check: Frequency vs Duration of Channel Opening\"},\"prompt\":{\"en\":\"Why is administering flumazenil strictly contraindicated in an unconscious overdose patient suspected of mixed tricyclic antidepressant (TCA) and benzodiazepine ingestion?\",\"tr\":\"Bilinçsiz bir aşırı doz hastasında trisiklik antidepresan (TSA) ve benzodiyazepin karma alımı şüphesinde flumazenil uygulanması neden kesinlikle kontrendikedir?\",\"ar\":\"لماذا يُمنع إعطاء الفلومازينيل منعاً باتاً لمريض فاقد الوعي يُشتبه بتناوله جرعة مفرطة مختلطة من مضادات الاكتئاب ثلاثية الحلقات والبنزوديازيبين؟\"},\"predictThenReveal\":true,\"config\":{\"revealedOutcome\":\"Formül: Benzo = Frekans (Fren), Barbi = Süre (Duration).\",\"options\":[{\"id\":\"opt_tca_unmask_seizure\",\"text\":{\"en\":\"Removing the anticonvulsant BZD tone unmasks TCA-induced sodium channel and GABA blockade, triggering intractable status epilepticus and lethal arrhythmias.\",\"tr\":\"BZD'nin koruyucu antikonvülsan etkisinin kalkması, TSA'nın sodyum ve GABA blokajını açığa çıkararak dirençli status epileptikus ve ölümcül aritmiye yol açar.\",\"ar\":\"تجريد الحماية المضادة للاختلاج للبنزوديازيبين يكشف حظر قنوات الصوديوم وGABA بواسطة TCA، مفجراً حالة صرعية معندة واضطرابات نظم قاتلة.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! TCAs lower seizure threshold. The co-ingested BZD protects against seizures. Flumazenil strips this shield, precipitating fatal status epilepticus.\",\"tr\":\"Doğru! TSA'lar nöbet eşiğini düşürür. BZD nöbeti baskılar; flumazenil verilince koruyucu kalkan kalkar ve ölümcül status epileptikus patlak verir.\",\"ar\":\"صحيح! تخفض TCA عتبة التشنج بينما يحمي البنزوديازيبين المريض؛ فإذا أزيل هذا الدرع بالفلومازينيل اشتعل الصرع واضطراب النظم المميت.\"}},{\"id\":\"opt_tca_precipitation\",\"text\":{\"en\":\"Flumazenil reacts chemically with circulating amitriptyline to form insoluble microcrystals that embolize pulmonary capillaries.\",\"tr\":\"Flumazenil, kandaki amitriptilin ile kimyasal reaksiyona girerek pulmoner kapillerleri tıkayan çözünmez mikrokristaller oluşturur.\",\"ar\":\"يتفاعل الفلومازينيل كيميائياً مع الأميتريبتيلين في الدم مشكلاً بلورات دقيقة غير ذوابة تسد الشعيرات الرئوية.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. The danger is a pharmacodynamic loss of seizure protection, not physical chemical precipitation in the bloodstream.\",\"tr\":\"Yanlış. Tehlike kanda kristal oluşumu değil, nöbeti baskılayan farmakodinamik kalkanın aniden yok olmasıdır.\",\"ar\":\"غير صحيح. مكمن الخطر ديناميكي دوائي يتمثل في زوال الحماية من الاختلاج، وليس ترسيباً كيميائياً في مجرى الدم.\"}},{\"id\":\"opt_tca_cyp_inhibition\",\"text\":{\"en\":\"Flumazenil potently inhibits hepatic CYP2D6, instantly doubling free circulating TCA concentrations within 60 seconds.\",\"tr\":\"Flumazenil hepatik CYP2D6'yı güçlü şekilde inhibe ederek 60 saniye içinde serbest dolaşan TSA konsantrasyonunu iki katına çıkarır.\",\"ar\":\"يثبط الفلومازينيل إنزيم CYP2D6 الكبدي بقوة مما يضاعف تراكيز TCA الحرة في الدوران خلال 60 ثانية.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Flumazenil has no clinically significant CYP inhibitory properties; the seizure storm is mediated at postsynaptic GABA-A receptors.\",\"tr\":\"Yanlış. Flumazenil CYP enzimlerini inhibe etmez; nöbet fırtınası postsinaptik GABA-A reseptörlerinde korumanın kalkmasıyla oluşur.\",\"ar\":\"غير صحيح. لا يمتلك الفلومازينيل خصائص تثبيط لـ CYP، بل تنفجر النوبات لزوال التثبيط عند مستقبلات GABA-A.\"}},{\"id\":\"opt_direct_cardiac_beta\",\"text\":{\"en\":\"Flumazenil directly stimulates cardiac beta-1 adrenergic receptors, worsening TCA-induced anticholinergic sinus tachycardia.\",\"tr\":\"Flumazenil kardiyak beta-1 adrenerjik reseptörleri doğrudan uyararak TSA'ya bağlı sinüs taşikardisini kötüleştirir.\",\"ar\":\"يحفز الفلومازينيل مستقبلات بيتا-1 الأدرينالية القلبية مباشرة مما يفاقم تسرع القلب الجيبي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Flumazenil does not bind or stimulate beta-1 adrenergic receptors; arrhythmias stem from TCA-mediated fast sodium channel blockade.\",\"tr\":\"Yanlış. Flumazenil beta reseptörleri uyarmaz; aritmiler TSA'nın kardiyak sodyum kanallarını bloke etmesinden kaynaklanır.\",\"ar\":\"غير صحيح. لا يحفز الفلومازينيل مستقبلات بيتا؛ بل تنجم اضطرابات النظم عن حصار TCA لقنوات الصوديوم القلبية السريعة.\"}}]},\"technicalTerms\":[{\"term\":\"etki mekanizması\",\"arContext\":\"آلية التأثير الدوائي\"},{\"term\":\"reseptör\",\"arContext\":\"المستقبِل الحيوي\"}],\"hints\":[{\"tier\":1,\"tr\":\"Trisiklik antidepresanların (TSA) kalp ve beyindeki sodyum kanalları üzerindeki etkisini düşünün.\",\"ar\":\"فكر في التأثير السام لمضادات الاكتئاب ثلاثية الحلقات (TCA) على قنوات الصوديوم القلبية والعصبية.\",\"en\":\"Consider the cardiotoxic and proconvulsant effects of tricyclic antidepressants on sodium channels.\"},{\"tier\":2,\"tr\":\"Birlikte alınan benzodiyazepin, TSA'nın tetikleyeceği nöbetleri GABA üzerinden baskılayarak hastayı korur.\",\"ar\":\"يعمل البنزوديازيبين المتناول مشاركةً كدرع واقٍ يخمد النوبات الصرعية المحرضة بواسطة TCA.\",\"en\":\"The co-ingested benzodiazepine acts as a protective shield suppressing TCA-induced convulsions.\"},{\"tier\":3,\"tr\":\"Flumazenil verilirse koruyucu kalkan aniden kalkar; hasta durdurulamaz status epileptikusa ve aritmiye girer.\",\"ar\":\"إذا أُعطي الفلومازينيل زال هذا الدرع الواقي فجأة، مفجراً حالة صرعية معندة واضطرابات بطينية قاتلة.\",\"en\":\"Administering flumazenil strips away the anticonvulsant shield, precipitating refractory status epilepticus.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_tca_unmask_seizure\",\"text\":{\"en\":\"Removing the anticonvulsant BZD tone unmasks TCA-induced sodium channel and GABA blockade, triggering intractable status epilepticus and lethal arrhythmias.\",\"tr\":\"BZD'nin koruyucu antikonvülsan etkisinin kalkması, TSA'nın sodyum ve GABA blokajını açığa çıkararak dirençli status epileptikus ve ölümcül aritmiye yol açar.\",\"ar\":\"تجريد الحماية المضادة للاختلاج للبنزوديازيبين يكشف حظر قنوات الصوديوم وGABA بواسطة TCA، مفجراً حالة صرعية معندة واضطرابات نظم قاتلة.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! TCAs lower seizure threshold. The co-ingested BZD protects against seizures. Flumazenil strips this shield, precipitating fatal status epilepticus.\",\"tr\":\"Doğru! TSA'lar nöbet eşiğini düşürür. BZD nöbeti baskılar; flumazenil verilince koruyucu kalkan kalkar ve ölümcül status epileptikus patlak verir.\",\"ar\":\"صحيح! تخفض TCA عتبة التشنج بينما يحمي البنزوديازيبين المريض؛ فإذا أزيل هذا الدرع بالفلومازينيل اشتعل الصرع واضطراب النظم المميت.\"}},{\"id\":\"opt_tca_precipitation\",\"text\":{\"en\":\"Flumazenil reacts chemically with circulating amitriptyline to form insoluble microcrystals that embolize pulmonary capillaries.\",\"tr\":\"Flumazenil, kandaki amitriptilin ile kimyasal reaksiyona girerek pulmoner kapillerleri tıkayan çözünmez mikrokristaller oluşturur.\",\"ar\":\"يتفاعل الفلومازينيل كيميائياً مع الأميتريبتيلين في الدم مشكلاً بلورات دقيقة غير ذوابة تسد الشعيرات الرئوية.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. The danger is a pharmacodynamic loss of seizure protection, not physical chemical precipitation in the bloodstream.\",\"tr\":\"Yanlış. Tehlike kanda kristal oluşumu değil, nöbeti baskılayan farmakodinamik kalkanın aniden yok olmasıdır.\",\"ar\":\"غير صحيح. مكمن الخطر ديناميكي دوائي يتمثل في زوال الحماية من الاختلاج، وليس ترسيباً كيميائياً في مجرى الدم.\"}},{\"id\":\"opt_tca_cyp_inhibition\",\"text\":{\"en\":\"Flumazenil potently inhibits hepatic CYP2D6, instantly doubling free circulating TCA concentrations within 60 seconds.\",\"tr\":\"Flumazenil hepatik CYP2D6'yı güçlü şekilde inhibe ederek 60 saniye içinde serbest dolaşan TSA konsantrasyonunu iki katına çıkarır.\",\"ar\":\"يثبط الفلومازينيل إنزيم CYP2D6 الكبدي بقوة مما يضاعف تراكيز TCA الحرة في الدوران خلال 60 ثانية.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Flumazenil has no clinically significant CYP inhibitory properties; the seizure storm is mediated at postsynaptic GABA-A receptors.\",\"tr\":\"Yanlış. Flumazenil CYP enzimlerini inhibe etmez; nöbet fırtınası postsinaptik GABA-A reseptörlerinde korumanın kalkmasıyla oluşur.\",\"ar\":\"غير صحيح. لا يمتلك الفلومازينيل خصائص تثبيط لـ CYP، بل تنفجر النوبات لزوال التثبيط عند مستقبلات GABA-A.\"}},{\"id\":\"opt_direct_cardiac_beta\",\"text\":{\"en\":\"Flumazenil directly stimulates cardiac beta-1 adrenergic receptors, worsening TCA-induced anticholinergic sinus tachycardia.\",\"tr\":\"Flumazenil kardiyak beta-1 adrenerjik reseptörleri doğrudan uyararak TSA'ya bağlı sinüs taşikardisini kötüleştirir.\",\"ar\":\"يحفز الفلومازينيل مستقبلات بيتا-1 الأدرينالية القلبية مباشرة مما يفاقم تسرع القلب الجيبي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Flumazenil does not bind or stimulate beta-1 adrenergic receptors; arrhythmias stem from TCA-mediated fast sodium channel blockade.\",\"tr\":\"Yanlış. Flumazenil beta reseptörleri uyarmaz; aritmiler TSA'nın kardiyak sodyum kanallarını bloke etmesinden kaynaklanır.\",\"ar\":\"غير صحيح. لا يحفز الفلومازينيل مستقبلات بيتا؛ بل تنجم اضطرابات النظم عن حصار TCA لقنوات الصوديوم القلبية السريعة.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":8}]},{\"id\":\"pharm-mod6-les1-step-09\",\"stage\":\"application\",\"stageIndex\":9,\"title\":{\"tr\":\"Klinik Antidot: Flumazenil ile Kurtarma\",\"ar\":\"تطبيق سريري: الإنقاذ بترياق Flumazenil\",\"en\":\"Clinical Antidote: Rescue with Flumazenil\"},\"prompt\":{\"en\":\"A patient with long-term lorazepam dependence receives flumazenil for procedural sedation reversal and abruptly develops status epilepticus. What cellular mechanism precipitated this crisis?\",\"tr\":\"Uzun süredir lorazepam bağımlısı olan hastaya sedasyonu geri çevirmek için flumazenil verilir ve hasta aniden status epileptikusa girer. Hangi hücresel mekanizma bu krizi tetikledi?\",\"ar\":\"مريض يعتمد مزمناً على اللورازيبام يُعطى فلومازينيل لإلغاء التهدئة الجراحية فيصاب بصرع معند مفاجئ. ما الآلية الخلوية التي فجرت هذه الكارثة؟\"},\"predictThenReveal\":true,\"config\":{\"revealedOutcome\":\"Flumazenil benzodiyazepin zehirlenmesinin saf yarışmalı nötr antagonistidir.\",\"options\":[{\"id\":\"opt_uncoupling_glutamate_storm\",\"text\":{\"en\":\"Chronic BZD exposure uncouples GABA-A receptors and upregulates glutamate; displacing BZDs abruptly removes basal inhibition, unleashing a glutamate storm.\",\"tr\":\"Kronik BZD kullanımı GABA-A reseptörlerini desensitize eder ve glutamatı artırır; flumazenil korumayı aniden kaldırınca kontrolsüz glutamat fırtınası başlar.\",\"ar\":\"يؤدي التعرض المزمن للبنزوديازيبين لفصل المستقبلات وزيادة الغلوتامات؛ إزاحتها فجأة تزيل التثبيط مفجرة عاصفة استثارة غلوتاماتية.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Chronic BZDs cause receptor uncoupling and compensatory glutamatergic upregulation. Acute flumazenil precipitates catastrophic withdrawal seizures.\",\"tr\":\"Doğru! Kronik kullanımda GABA tonusu körelmiş, glutamat artmıştır. Flumazenil verilince kalan son inhibisyon da kalkar ve nöbet patlar.\",\"ar\":\"صحيح! يثبط الاستخدام المزمن كفاءة GABA ويرفع الغلوتامات تعويضياً؛ ويؤدي الفلومازينيل إلى إطلاق صرع انسحابي مهدد للحياة.\"}},{\"id\":\"opt_receptor_destruction\",\"text\":{\"en\":\"Flumazenil acts as a protease that irreversibly degrades and cleaves the alpha-1 subunit of GABA-A receptors from the neuronal membrane.\",\"tr\":\"Flumazenil, GABA-A reseptörlerinin alfa-1 alt birimini nöron zarından geri dönüşsüz şekilde koparan bir proteaz gibi davranır.\",\"ar\":\"يعمل الفلومازينيل كإنزيم بروتياز يحطم ويقطع تحت وحدة ألفا-1 لمستقبلات GABA-A من الغشاء العصبي بشكل غير عكوس.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Flumazenil is a reversible competitive antagonist, not a protease; it does not cleave or destroy receptor proteins.\",\"tr\":\"Yanlış. Flumazenil bir proteaz değildir, reseptörleri parçalamaz; sadece tersinir yarışmalı antagonisttir.\",\"ar\":\"غير صحيح. الفلومازينيل مناهض تنافسي عكوس وليس إنزيماً محللاً للبروتين؛ ولا يحطم المستقبلات.\"}},{\"id\":\"opt_hypocalcemia_seizure\",\"text\":{\"en\":\"Flumazenil triggers massive parathyroid hormone suppression, provoking profound hypocalcemia and hypocalcemic tetanic convulsions within minutes.\",\"tr\":\"Flumazenil paratiroid hormonunu baskılayarak dakikalar içinde şiddetli hipokalsemi ve hipokalsemik tetani nöbetlerine neden olur.\",\"ar\":\"يحفز الفلومازينيل تثبيطاً هائلاً لهرمون جارات الدرق مسبباً نقص كالسيوم حاداً ونوبات كزازية خلال دقائق.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Flumazenil has no effect on calcium homeostasis or the parathyroid gland; seizures are purely neurochemical (loss of GABA inhibition).\",\"tr\":\"Yanlış. Flumazenilin kalsiyum veya paratiroid üzerine etkisi yoktur; nöbet tamamen santral GABAerjik korumanın çökmesinden kaynaklanır.\",\"ar\":\"غير صحيح. لا يؤثر الفلومازينيل على الكالسيوم أو الغدد الدريقية؛ بل تنجم النوبات عن زوال التثبيط العصبي الكيميائي.\"}},{\"id\":\"opt_conversion_to_toxin\",\"text\":{\"en\":\"Flumazenil chemically converts remaining lorazepam molecules into strychnine, a glycine receptor antagonist that triggers spinal convulsions.\",\"tr\":\"Flumazenil, ortamdaki lorazepamı glisin antagonisti olan striknine dönüştürerek spinal konvülsiyonlara yol açar.\",\"ar\":\"يحول الفلومازينيل جزيئات اللورازيبام كيميائياً إلى ستريكنين، وهو مناهض لمستقبلات الغلايسين يسبب اختلاجات نخاعية.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. This is chemically impossible. Withdrawal seizures stem from abrupt unmasking of hyperexcitable glutamate circuits.\",\"tr\":\"Yanlış. Bu kimyasal olarak imkansızdır. Kriz, aşırı uyarılabilir glutamaterjik devrelerin aniden açığa çıkmasından kaynaklanır.\",\"ar\":\"غير صحيح. هذا مستحيل كيميائياً. تنجم نوبات الانسحاب عن انكشاف مسارات الغلوتامات مفرطة الاستثارة.\"}}]},\"technicalTerms\":[{\"term\":\"etki mekanizması\",\"arContext\":\"آلية التأثير الدوائي\"},{\"term\":\"reseptör\",\"arContext\":\"المستقبِل الحيوي\"}],\"hints\":[{\"tier\":1,\"tr\":\"Kronik sedatif kullanımında beynin geliştirdiği adaptif nöroplastik değişiklikleri hatırlayın.\",\"ar\":\"تذكر التغيرات العصبية التكيفية التي يحدثها الدماغ بعد التعرض المزمن للمهدئات.\",\"en\":\"Recall the homeostatic neuroadaptations the brain develops during long-term sedative exposure.\"},{\"tier\":2,\"tr\":\"GABA-A reseptörleri duyarsızlaşır ve uyarıcı glutamat devreleri (NMDA/AMPA) telafi amacıyla yukarı regüle olur.\",\"ar\":\"تنخفض حساسية مستقبلات GABA وتتكاثر مسارات الغلوتامات الاستثارية (NMDA) تعويضياً.\",\"en\":\"GABA-A receptors uncouple while excitatory glutamatergic NMDA/AMPA circuits upregulate compensatorily.\"},{\"tier\":3,\"tr\":\"Flumazenil kalan zayıf GABA tonusunu da aniden sıfırlayınca kontrolsüz bir glutamat fırtınası ve nöbet patlar.\",\"ar\":\"عندما يزيل الفلومازينيل ما تبقى من تثبيط GABA فجأة، تنفجر عاصفة استثارة غلوتاماتية مسببة نوبات صرع.\",\"en\":\"Flumazenil abruptly strips the remaining GABA tone, unleashing an unopposed glutamate storm and seizures.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_uncoupling_glutamate_storm\",\"text\":{\"en\":\"Chronic BZD exposure uncouples GABA-A receptors and upregulates glutamate; displacing BZDs abruptly removes basal inhibition, unleashing a glutamate storm.\",\"tr\":\"Kronik BZD kullanımı GABA-A reseptörlerini desensitize eder ve glutamatı artırır; flumazenil korumayı aniden kaldırınca kontrolsüz glutamat fırtınası başlar.\",\"ar\":\"يؤدي التعرض المزمن للبنزوديازيبين لفصل المستقبلات وزيادة الغلوتامات؛ إزاحتها فجأة تزيل التثبيط مفجرة عاصفة استثارة غلوتاماتية.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Chronic BZDs cause receptor uncoupling and compensatory glutamatergic upregulation. Acute flumazenil precipitates catastrophic withdrawal seizures.\",\"tr\":\"Doğru! Kronik kullanımda GABA tonusu körelmiş, glutamat artmıştır. Flumazenil verilince kalan son inhibisyon da kalkar ve nöbet patlar.\",\"ar\":\"صحيح! يثبط الاستخدام المزمن كفاءة GABA ويرفع الغلوتامات تعويضياً؛ ويؤدي الفلومازينيل إلى إطلاق صرع انسحابي مهدد للحياة.\"}},{\"id\":\"opt_receptor_destruction\",\"text\":{\"en\":\"Flumazenil acts as a protease that irreversibly degrades and cleaves the alpha-1 subunit of GABA-A receptors from the neuronal membrane.\",\"tr\":\"Flumazenil, GABA-A reseptörlerinin alfa-1 alt birimini nöron zarından geri dönüşsüz şekilde koparan bir proteaz gibi davranır.\",\"ar\":\"يعمل الفلومازينيل كإنزيم بروتياز يحطم ويقطع تحت وحدة ألفا-1 لمستقبلات GABA-A من الغشاء العصبي بشكل غير عكوس.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Flumazenil is a reversible competitive antagonist, not a protease; it does not cleave or destroy receptor proteins.\",\"tr\":\"Yanlış. Flumazenil bir proteaz değildir, reseptörleri parçalamaz; sadece tersinir yarışmalı antagonisttir.\",\"ar\":\"غير صحيح. الفلومازينيل مناهض تنافسي عكوس وليس إنزيماً محللاً للبروتين؛ ولا يحطم المستقبلات.\"}},{\"id\":\"opt_hypocalcemia_seizure\",\"text\":{\"en\":\"Flumazenil triggers massive parathyroid hormone suppression, provoking profound hypocalcemia and hypocalcemic tetanic convulsions within minutes.\",\"tr\":\"Flumazenil paratiroid hormonunu baskılayarak dakikalar içinde şiddetli hipokalsemi ve hipokalsemik tetani nöbetlerine neden olur.\",\"ar\":\"يحفز الفلومازينيل تثبيطاً هائلاً لهرمون جارات الدرق مسبباً نقص كالسيوم حاداً ونوبات كزازية خلال دقائق.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Flumazenil has no effect on calcium homeostasis or the parathyroid gland; seizures are purely neurochemical (loss of GABA inhibition).\",\"tr\":\"Yanlış. Flumazenilin kalsiyum veya paratiroid üzerine etkisi yoktur; nöbet tamamen santral GABAerjik korumanın çökmesinden kaynaklanır.\",\"ar\":\"غير صحيح. لا يؤثر الفلومازينيل على الكالسيوم أو الغدد الدريقية؛ بل تنجم النوبات عن زوال التثبيط العصبي الكيميائي.\"}},{\"id\":\"opt_conversion_to_toxin\",\"text\":{\"en\":\"Flumazenil chemically converts remaining lorazepam molecules into strychnine, a glycine receptor antagonist that triggers spinal convulsions.\",\"tr\":\"Flumazenil, ortamdaki lorazepamı glisin antagonisti olan striknine dönüştürerek spinal konvülsiyonlara yol açar.\",\"ar\":\"يحول الفلومازينيل جزيئات اللورازيبام كيميائياً إلى ستريكنين، وهو مناهض لمستقبلات الغلايسين يسبب اختلاجات نخاعية.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. This is chemically impossible. Withdrawal seizures stem from abrupt unmasking of hyperexcitable glutamate circuits.\",\"tr\":\"Yanlış. Bu kimyasal olarak imkansızdır. Kriz, aşırı uyarılabilir glutamaterjik devrelerin aniden açığa çıkmasından kaynaklanır.\",\"ar\":\"غير صحيح. هذا مستحيل كيميائياً. تنجم نوبات الانسحاب عن انكشاف مسارات الغلوتامات مفرطة الاستثارة.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":9}]},{\"id\":\"pharm-mod6-les1-step-10\",\"stage\":\"retrieval\",\"stageIndex\":10,\"title\":{\"tr\":\"Geri Çağırma: Reseptör Antagonizmi Tipleri\",\"ar\":\"استرجاع معرفي: أنماط مناهضة المستقبِلات\",\"en\":\"Retrieval: Types of Receptor Antagonism\"},\"prompt\":{\"en\":\"GABA-A alpha-1 subunits mediate sedation while alpha-2 and alpha-3 mediate anxiolysis and muscle relaxation. Why is zolpidem an effective hypnotic devoid of anxiolytic properties?\",\"tr\":\"GABA-A alfa-1 alt birimi sedasyon sağlarken, alfa-2 ve alfa-3 anksiyoliz ve kas gevşemesi sağlar. Zolpidem neden anksiyolitik etkisi olmayan saf bir hipnotiktir?\",\"ar\":\"تتوسط تحت وحدة ألفا-1 التهدئة، بينما تتوسط ألفا-2 وألفا-3 إزالة القلق وإرخاء العضلات. لماذا يعد الزولبيديم منوماً فعالاً بلا خصائص مزيلة للقلق؟\"},\"predictThenReveal\":false,\"config\":{\"options\":[{\"id\":\"opt_alpha1_selectivity\",\"text\":{\"en\":\"Zolpidem binds selectively to alpha-1-containing GABA-A receptors, inducing sleep while lacking meaningful affinity for alpha-2 and alpha-3 subunits.\",\"tr\":\"Zolpidem sadece alfa-1 içeren GABA-A reseptörlerine seçici bağlanarak uyku verir; alfa-2 ve alfa-3 alt birimlerine afinitesi yok denecek kadar azdır.\",\"ar\":\"يرتبط الزولبيديم انتقائياً بمستقبلات GABA-A الحاوية على ألفا-1 محدثاً النوم، بينما يفتقر للألفة تجاه تحت الوحدتين ألفا-2 وألفا-3.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! The 'Z-drugs' are subunit-selective PAMs targeted to alpha-1 for hypnosis, sparing alpha-2/alpha-3 (anxiolysis) and alpha-5 (cognition).\",\"tr\":\"Doğru! Z-ilaçları alfa-1 alt birimine seçicidir; bu yüzden hipnotik etki gösterirken belirgin kas gevşetici veya anksiyolitik etki oluşturmazlar.\",\"ar\":\"صحيح! أدوية Z معدلات انتقائية لتحت وحدة ألفا-1 المسؤولة عن النوم، مجنبةً ألفا-2 وألفا-3 المسؤولة عن إزالة القلق.\"}},{\"id\":\"opt_melatonin_agonist\",\"text\":{\"en\":\"Zolpidem does not modulate GABA-A receptors, acting instead as a synthetic agonist at hypothalamic melatonin MT1 and MT2 GPCRs.\",\"tr\":\"Zolpidem GABA-A reseptörlerini modüle etmez, hipotalamik melatonin MT1 ve MT2 GPCR reseptörlerinin sentetik agonistidir.\",\"ar\":\"لا يعدل الزولبيديم مستقبلات GABA-A، بل يعمل كناهض تركيبي لمستقبلات الميلاتونين MT1 وMT2 في الوطاء.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Ramelteon targets melatonin MT1/MT2 receptors. Zolpidem is a selective GABA-A alpha-1 positive allosteric modulator.\",\"tr\":\"Yanlış. Melatonin MT1/MT2 agonistleri ramelteondur. Zolpidem seçici bir GABA-A alfa-1 pozitif allosterik modülatörüdür.\",\"ar\":\"غير صحيح. الراميلتيون هو ناهض مستقبلات الميلاتونين؛ أما الزولبيديم فهو معدل تفارغي إيجابي انتقائي لـ GABA-A ألفا-1.\"}},{\"id\":\"opt_beta3_only\",\"text\":{\"en\":\"Zolpidem targets beta-3 subunits exclusively, bypassing alpha subunits entirely to activate chloride gating without sedation.\",\"tr\":\"Zolpidem yalnızca beta-3 alt birimine bağlanır, alfa alt birimlerini tamamen atlayarak sedasyon olmadan klorür açar.\",\"ar\":\"يستهدف الزولبيديم تحت وحدة بيتا-3 حصرياً متجاوزاً تحت وحدات ألفا ليفتح الكلوريد دون تهدئة.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. The benzodiazepine binding pocket resides at the alpha/gamma interface, and zolpidem's selectivity is determined by the alpha-1 subunit.\",\"tr\":\"Yanlış. BZD bağlanma cebi alfa/gama arayüzündedir ve zolpidemin seçiciliğini belirleyen alfa-1 alt birimidir.\",\"ar\":\"غير صحيح. يقع جيب الارتباط عند سطح التماس ألفا/غاما، وتتحدد انتقائية الزولبيديم بوجود تحت وحدة ألفا-1.\"}},{\"id\":\"opt_identical_affinity_short_half_life\",\"text\":{\"en\":\"Zolpidem has identical affinity for all alpha subunits, but its extremely rapid 10-minute clearance prevents anxiolytic activation.\",\"tr\":\"Zolpidem tüm alfa alt birimlerine eşit afinite gösterir, ancak 10 dakikalık aşırı hızlı klirensi anksiyolitik etkiyi önler.\",\"ar\":\"يمتلك الزولبيديم ألفة متطابقة لجميع تحت وحدات ألفا، لكن إطراحه فائق السرعة خلال 10 دقائق يمنع إزالة القلق.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Zolpidem has a half-life of 2–3 hours and exhibits genuine molecular subtype selectivity for alpha-1 over alpha-2/alpha-3.\",\"tr\":\"Yanlış. Zolpidemin yarı ömrü 2-3 saattir ve alfa-1 alt birimine karşı alfa-2/alfa-3'e kıyasla gerçek bir moleküler seçiciliği vardır.\",\"ar\":\"غير صحيح. يمتلك الزولبيديم نصف عمر يبلغ ساعتين إلى 3 ساعات، وانتقائية جزيئية حقيقية لألفا-1 مقارنة بألفا-2 وألفا-3.\"}}]},\"technicalTerms\":[{\"term\":\"yarışmalı antagonist\",\"arContext\":\"المناهض التنافسي\"}],\"hints\":[{\"tier\":1,\"tr\":\"GABA-A reseptörünün alfa alt birim tiplerinin farklı farmakolojik etkilerden sorumlu olduğunu hatırlayın.\",\"ar\":\"تذكر أن تحت وحدات ألفا المختلفة لمستقبل GABA-A مسؤولة عن تأثيرات دوائية متباينة.\",\"en\":\"Recall that distinct GABA-A alpha subunit isoforms mediate segregated pharmacological actions.\"},{\"tier\":2,\"tr\":\"Alfa-1 sedasyon ve uyku sağlar; alfa-2 ve alfa-3 ise anksiyoliz ve kas gevşemesinden sorumludur.\",\"ar\":\"تتوسط ألفا-1 التهدئة والنوم؛ بينما تتوسط ألفا-2 وألفا-3 إزالة القلق وإرخاء العضلات.\",\"en\":\"Alpha-1 mediates sedation and hypnosis; alpha-2 and alpha-3 mediate anxiolysis and myorelaxation.\"},{\"tier\":3,\"tr\":\"Zolpidem sadece alfa-1'e seçici bağlanır; bu yüzden kas gevşetmeden veya kaygı gidermeden uyutur.\",\"ar\":\"يرتبط الزولبيديم انتقائياً بألفا-1؛ لذلك يحث على النوم دون إرخاء العضلات أو تخفيف القلق سريرياً.\",\"en\":\"Zolpidem selectively targets alpha-1; thus it acts as a pure hypnotic devoid of anxiolytic properties.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_alpha1_selectivity\",\"text\":{\"en\":\"Zolpidem binds selectively to alpha-1-containing GABA-A receptors, inducing sleep while lacking meaningful affinity for alpha-2 and alpha-3 subunits.\",\"tr\":\"Zolpidem sadece alfa-1 içeren GABA-A reseptörlerine seçici bağlanarak uyku verir; alfa-2 ve alfa-3 alt birimlerine afinitesi yok denecek kadar azdır.\",\"ar\":\"يرتبط الزولبيديم انتقائياً بمستقبلات GABA-A الحاوية على ألفا-1 محدثاً النوم، بينما يفتقر للألفة تجاه تحت الوحدتين ألفا-2 وألفا-3.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! The 'Z-drugs' are subunit-selective PAMs targeted to alpha-1 for hypnosis, sparing alpha-2/alpha-3 (anxiolysis) and alpha-5 (cognition).\",\"tr\":\"Doğru! Z-ilaçları alfa-1 alt birimine seçicidir; bu yüzden hipnotik etki gösterirken belirgin kas gevşetici veya anksiyolitik etki oluşturmazlar.\",\"ar\":\"صحيح! أدوية Z معدلات انتقائية لتحت وحدة ألفا-1 المسؤولة عن النوم، مجنبةً ألفا-2 وألفا-3 المسؤولة عن إزالة القلق.\"}},{\"id\":\"opt_melatonin_agonist\",\"text\":{\"en\":\"Zolpidem does not modulate GABA-A receptors, acting instead as a synthetic agonist at hypothalamic melatonin MT1 and MT2 GPCRs.\",\"tr\":\"Zolpidem GABA-A reseptörlerini modüle etmez, hipotalamik melatonin MT1 ve MT2 GPCR reseptörlerinin sentetik agonistidir.\",\"ar\":\"لا يعدل الزولبيديم مستقبلات GABA-A، بل يعمل كناهض تركيبي لمستقبلات الميلاتونين MT1 وMT2 في الوطاء.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Ramelteon targets melatonin MT1/MT2 receptors. Zolpidem is a selective GABA-A alpha-1 positive allosteric modulator.\",\"tr\":\"Yanlış. Melatonin MT1/MT2 agonistleri ramelteondur. Zolpidem seçici bir GABA-A alfa-1 pozitif allosterik modülatörüdür.\",\"ar\":\"غير صحيح. الراميلتيون هو ناهض مستقبلات الميلاتونين؛ أما الزولبيديم فهو معدل تفارغي إيجابي انتقائي لـ GABA-A ألفا-1.\"}},{\"id\":\"opt_beta3_only\",\"text\":{\"en\":\"Zolpidem targets beta-3 subunits exclusively, bypassing alpha subunits entirely to activate chloride gating without sedation.\",\"tr\":\"Zolpidem yalnızca beta-3 alt birimine bağlanır, alfa alt birimlerini tamamen atlayarak sedasyon olmadan klorür açar.\",\"ar\":\"يستهدف الزولبيديم تحت وحدة بيتا-3 حصرياً متجاوزاً تحت وحدات ألفا ليفتح الكلوريد دون تهدئة.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. The benzodiazepine binding pocket resides at the alpha/gamma interface, and zolpidem's selectivity is determined by the alpha-1 subunit.\",\"tr\":\"Yanlış. BZD bağlanma cebi alfa/gama arayüzündedir ve zolpidemin seçiciliğini belirleyen alfa-1 alt birimidir.\",\"ar\":\"غير صحيح. يقع جيب الارتباط عند سطح التماس ألفا/غاما، وتتحدد انتقائية الزولبيديم بوجود تحت وحدة ألفا-1.\"}},{\"id\":\"opt_identical_affinity_short_half_life\",\"text\":{\"en\":\"Zolpidem has identical affinity for all alpha subunits, but its extremely rapid 10-minute clearance prevents anxiolytic activation.\",\"tr\":\"Zolpidem tüm alfa alt birimlerine eşit afinite gösterir, ancak 10 dakikalık aşırı hızlı klirensi anksiyolitik etkiyi önler.\",\"ar\":\"يمتلك الزولبيديم ألفة متطابقة لجميع تحت وحدات ألفا، لكن إطراحه فائق السرعة خلال 10 دقائق يمنع إزالة القلق.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Zolpidem has a half-life of 2–3 hours and exhibits genuine molecular subtype selectivity for alpha-1 over alpha-2/alpha-3.\",\"tr\":\"Yanlış. Zolpidemin yarı ömrü 2-3 saattir ve alfa-1 alt birimine karşı alfa-2/alfa-3'e kıyasla gerçek bir moleküler seçiciliği vardır.\",\"ar\":\"غير صحيح. يمتلك الزولبيديم نصف عمر يبلغ ساعتين إلى 3 ساعات، وانتقائية جزيئية حقيقية لألفا-1 مقارنة بألفا-2 وألفا-3.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":10}]},{\"id\":\"pharm-mod6-les1-step-11\",\"stage\":\"connection\",\"stageIndex\":11,\"title\":{\"tr\":\"İleri Bağlantı: Dopaminerjik Yolaklar ve Antipsikotikler (Ders 12)\",\"ar\":\"ربط مفاهيمي: المسارات الدوبامينية ومضادات الذهان (الدرس 12)\",\"en\":\"Connection: Dopaminergic Pathways & Antipsychotics (Lesson 12)\"},\"prompt\":{\"en\":\"While ionotropic GABA-A chloride channels mediate rapid millisecond inhibition, dopamine D2 GPCRs modulate cellular signaling via Gi. How do these two signaling architectures contrast?\",\"tr\":\"İyonotropik GABA-A klorür kanalları milisaniyelik hızlı inhibisyon yaparken, dopamin D2 GPCR reseptörleri Gi ile sinyal iletir. Bu iki yapı nasıl ayrışır?\",\"ar\":\"بينما تتوسط قنوات GABA-A الأيونية تثبيطاً سريعاً بالأجزاء من الثانية، تعدل مستقبلات D2 المقترنة ببروتين Gi الإشارات الخلوية. كيف تتباين بنيتا الإشارات؟\"},\"predictThenReveal\":false,\"config\":{\"options\":[{\"id\":\"opt_ionotropic_vs_gpcr\",\"text\":{\"en\":\"GABA-A directly fluxes chloride to hyperpolarize the membrane; D2 inhibits adenylyl cyclase, lowers cAMP, and modulates downstream channels via G-protein second messengers.\",\"tr\":\"GABA-A klorür geçirerek zarı doğrudan hiperpolarize eder; D2 adenilat siklazı inhibe eder, cAMP'yi düşürür ve G-proteini ile kanalları modüle eder.\",\"ar\":\"يمرر GABA-A الكلوريد مباشرة لفرط استقطاب الغشاء؛ بينما يثبط D2 محلقة الأدينيلات، ويخفض cAMP، ويعدل القنوات عبر مرسال ثانٍ.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Ionotropic channels provide instant millisecond conductance changes; metabotropic GPCRs trigger slower, amplified second-messenger cascades.\",\"tr\":\"Doğru! İyonotropik kanallar milisaniyede iyon akışı sağlar; metabotropik GPCR'ler ise hücre içi sinyal kaskadlarını kontrol eder.\",\"ar\":\"صحيح! تحدث القنوات الأيونية تغيرات فورية بالتوصيل؛ بينما تفعل المستقبلات المرتبطة بالبروتين G شلالات أبطأ وأكثر تضخيماً.\"}},{\"id\":\"opt_d2_is_ligand_gated\",\"text\":{\"en\":\"Dopamine D2 receptors are ligand-gated chloride channels with five transmembrane subunits identical to GABA-A pentamers.\",\"tr\":\"Dopamin D2 reseptörleri, GABA-A pentamerleri ile tamamen aynı beş transmembran alt birime sahip ligand kapılı klorür kanallarıdır.\",\"ar\":\"مستقبلات الدوبامين D2 قنوات كلوريد مبوبة بالربيطة خماسية الوحدات متطابقة تماماً مع بنية GABA-A.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Dopamine D2 receptors are monomeric 7-transmembrane GPCRs, not ligand-gated pentameric ion channels.\",\"tr\":\"Yanlış. Dopamin D2 reseptörleri iyon kanalı değil, 7 transmembranlı heptahelikal GPCR proteinleridir.\",\"ar\":\"غير صحيح. مستقبلات الدوبامين D2 مستقبلات مقترنة بالبروتين G بـ 7 نطاقات عبر الغشاء وليست قنوات أيونية خماسية.\"}},{\"id\":\"opt_gaba_a_is_gq\",\"text\":{\"en\":\"GABA-A is coupled to Gq proteins that stimulate phospholipase C to trigger rapid intracellular calcium release.\",\"tr\":\"GABA-A, fosfolipaz C'yi uyararak hızlı hücre içi kalsiyum salınımını tetikleyen Gq proteinlerine kenetlidir.\",\"ar\":\"يقترن GABA-A ببروتينات Gq التي تحفز فوسفوليباز C لإطلاق الكالسيوم داخل الخلوي بسرعة.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. GABA-A is an ionotropic channel that fluxes chloride directly without any G-protein coupling.\",\"tr\":\"Yanlış. GABA-A iyonotropik bir kanaldır; G-proteini kullanmaz, klorürü doğrudan içeri geçirir.\",\"ar\":\"غير صحيح. مستقبل GABA-A قناة أيونية تمرر الكلوريد مباشرة دون أي اقتران ببروتين G.\"}},{\"id\":\"opt_gpcr_faster_than_ion_channel\",\"text\":{\"en\":\"GPCR signaling occurs in microseconds, fundamentally faster than ion channels because second messengers bypass physical membrane barriers.\",\"tr\":\"GPCR sinyalizasyonu mikrosaniyeler içinde gerçekleşir, ikincil haberciler zar engellerini aştığı için iyon kanallarından çok daha hızlıdır.\",\"ar\":\"تحدث إشارات GPCR في أجزاء من المليون من الثانية وهي أسرع جوهرياً من القنوات الأيونية لتجاوزها حواجز الغشاء.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Ion channels open in milliseconds (<1 ms). GPCR cascades require biochemical steps (GDP-GTP exchange, cAMP) taking hundreds of milliseconds to seconds.\",\"tr\":\"Yanlış. İyon kanalları milisaniyede açılır; GPCR kaskadları ise biyokimyasal adımlar gerektirdiğinden yüzlerce milisaniye sürer.\",\"ar\":\"غير صحيح. تفتح القنوات الأيونية خلال أجزاء من الألف من الثانية، بينما تتطلب شلالات GPCR خطوات كيميائية تستغرق ثوانٍ.\"}}]},\"technicalTerms\":[{\"term\":\"dopaminerjik yolak\",\"arContext\":\"المسار الدوباميني\"}],\"hints\":[{\"tier\":1,\"tr\":\"İyonotropik kanal ile metabotropik GPCR reseptörlerinin sinyal iletim hızını ve mekanizmasını karşılaştırın.\",\"ar\":\"قارن سرعة وآلية نقل الإشارات بين القنوات الأيونية والمستقبلات الأيضية المقترنة بالبروتين G.\",\"en\":\"Contrast the signaling speed and biochemical cascade of ionotropic channels versus metabotropic GPCRs.\"},{\"tier\":2,\"tr\":\"GABA-A doğrudan klor geçirerek milisaniyede zarı hiperpolarize eder.\",\"ar\":\"يمرر GABA-A الكلوريد مباشرة لفرط استقطاب الغشاء خلال أجزاء من الألف من الثانية.\",\"en\":\"GABA-A fluxes chloride directly to hyperpolarize the resting membrane within milliseconds.\"},{\"tier\":3,\"tr\":\"Dopamin D2 reseptörleri ise Gi kenetlidir; adenilat siklazı baskılayıp cAMP'yi düşürerek hücresel yanıtı modüle eder.\",\"ar\":\"بينما تقترن مستقبلات D2 ببروتين Gi؛ فتثبط محلقة الأدينيلات وتخفض cAMP لتعديل وظيفة الخلية.\",\"en\":\"Dopamine D2 GPCRs couple to Gi, inhibiting adenylyl cyclase and lowering cAMP over hundreds of milliseconds.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_ionotropic_vs_gpcr\",\"text\":{\"en\":\"GABA-A directly fluxes chloride to hyperpolarize the membrane; D2 inhibits adenylyl cyclase, lowers cAMP, and modulates downstream channels via G-protein second messengers.\",\"tr\":\"GABA-A klorür geçirerek zarı doğrudan hiperpolarize eder; D2 adenilat siklazı inhibe eder, cAMP'yi düşürür ve G-proteini ile kanalları modüle eder.\",\"ar\":\"يمرر GABA-A الكلوريد مباشرة لفرط استقطاب الغشاء؛ بينما يثبط D2 محلقة الأدينيلات، ويخفض cAMP، ويعدل القنوات عبر مرسال ثانٍ.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Ionotropic channels provide instant millisecond conductance changes; metabotropic GPCRs trigger slower, amplified second-messenger cascades.\",\"tr\":\"Doğru! İyonotropik kanallar milisaniyede iyon akışı sağlar; metabotropik GPCR'ler ise hücre içi sinyal kaskadlarını kontrol eder.\",\"ar\":\"صحيح! تحدث القنوات الأيونية تغيرات فورية بالتوصيل؛ بينما تفعل المستقبلات المرتبطة بالبروتين G شلالات أبطأ وأكثر تضخيماً.\"}},{\"id\":\"opt_d2_is_ligand_gated\",\"text\":{\"en\":\"Dopamine D2 receptors are ligand-gated chloride channels with five transmembrane subunits identical to GABA-A pentamers.\",\"tr\":\"Dopamin D2 reseptörleri, GABA-A pentamerleri ile tamamen aynı beş transmembran alt birime sahip ligand kapılı klorür kanallarıdır.\",\"ar\":\"مستقبلات الدوبامين D2 قنوات كلوريد مبوبة بالربيطة خماسية الوحدات متطابقة تماماً مع بنية GABA-A.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Dopamine D2 receptors are monomeric 7-transmembrane GPCRs, not ligand-gated pentameric ion channels.\",\"tr\":\"Yanlış. Dopamin D2 reseptörleri iyon kanalı değil, 7 transmembranlı heptahelikal GPCR proteinleridir.\",\"ar\":\"غير صحيح. مستقبلات الدوبامين D2 مستقبلات مقترنة بالبروتين G بـ 7 نطاقات عبر الغشاء وليست قنوات أيونية خماسية.\"}},{\"id\":\"opt_gaba_a_is_gq\",\"text\":{\"en\":\"GABA-A is coupled to Gq proteins that stimulate phospholipase C to trigger rapid intracellular calcium release.\",\"tr\":\"GABA-A, fosfolipaz C'yi uyararak hızlı hücre içi kalsiyum salınımını tetikleyen Gq proteinlerine kenetlidir.\",\"ar\":\"يقترن GABA-A ببروتينات Gq التي تحفز فوسفوليباز C لإطلاق الكالسيوم داخل الخلوي بسرعة.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. GABA-A is an ionotropic channel that fluxes chloride directly without any G-protein coupling.\",\"tr\":\"Yanlış. GABA-A iyonotropik bir kanaldır; G-proteini kullanmaz, klorürü doğrudan içeri geçirir.\",\"ar\":\"غير صحيح. مستقبل GABA-A قناة أيونية تمرر الكلوريد مباشرة دون أي اقتران ببروتين G.\"}},{\"id\":\"opt_gpcr_faster_than_ion_channel\",\"text\":{\"en\":\"GPCR signaling occurs in microseconds, fundamentally faster than ion channels because second messengers bypass physical membrane barriers.\",\"tr\":\"GPCR sinyalizasyonu mikrosaniyeler içinde gerçekleşir, ikincil haberciler zar engellerini aştığı için iyon kanallarından çok daha hızlıdır.\",\"ar\":\"تحدث إشارات GPCR في أجزاء من المليون من الثانية وهي أسرع جوهرياً من القنوات الأيونية لتجاوزها حواجز الغشاء.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Ion channels open in milliseconds (<1 ms). GPCR cascades require biochemical steps (GDP-GTP exchange, cAMP) taking hundreds of milliseconds to seconds.\",\"tr\":\"Yanlış. İyon kanalları milisaniyede açılır; GPCR kaskadları ise biyokimyasal adımlar gerektirdiğinden yüzlerce milisaniye sürer.\",\"ar\":\"غير صحيح. تفتح القنوات الأيونية خلال أجزاء من الألف من الثانية، بينما تتطلب شلالات GPCR خطوات كيميائية تستغرق ثوانٍ.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":11}]},{\"id\":\"pharm-mod6-les1-step-12\",\"stage\":\"mastery_check\",\"stageIndex\":12,\"title\":{\"tr\":\"Ustalık Sınavı: GABA-A ve Pozitif Modülasyon\",\"ar\":\"اختبار الإتقان: مستقبِل GABA-A والتعديل الإيجابي\",\"en\":\"Mastery Assessment: GABA-A Modulation\"},\"prompt\":{\"en\":\"A comatose patient with suspected sedative overdose shows sinus tachycardia with QRS widening to 135 ms and terminal R wave in aVR. Why is IV flumazenil strictly contraindicated?\",\"tr\":\"Sedatif aşırı doz şüphesi olan komadaki hastada sinüs taşikardisi, QRS'te 135 ms genişleme ve aVR'de terminal R dalgası saptanıyor. IV flumazenil neden kesinlikle kontrendikedir?\",\"ar\":\"مريض بغيبوبة يُشتبه بتناوله مهدئات يظهر تسرع قلب جيبي، واتساع QRS إلى 135 ميلي ثانية وموجة R نهائية في aVR. لماذا يُمنع الفلومازينيل الوريدي منعاً باتاً؟\"},\"predictThenReveal\":true,\"config\":{\"revealedOutcome\":\"Ders başarıyla tamamlandı! 3 review cards eklendi. +50 XP.\",\"options\":[{\"id\":\"opt_tca_ecg_unmasking\",\"text\":{\"en\":\"The ECG reveals co-ingested TCA cardiotoxicity; flumazenil strips protective BZD anticonvulsant tone, unleashing refractory status epilepticus and lethal ventricular arrhythmias.\",\"tr\":\"EKG eşlik eden TSA toksisitesini gösterir; flumazenil BZD'nin nöbet önleyici kalkanını kaldırarak dirençli status epileptikus ve ölümcül ventriküler aritmiyi tetikler.\",\"ar\":\"يكشف التخطيط سمية قلبية مرافقة لمضادات الاكتئاب ثلاثية الحلقات؛ يجرد الفلومازينيل حماية البنزوديازيبين مفجراً حالة صرعية واضطرابات بطينية قاتلة.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Widened QRS (>100 ms) and prominent aVR R wave indicate TCA sodium channel blockade. BZDs suppress TCA seizures; flumazenil unleashes fatal convulsions.\",\"tr\":\"Doğru! Geniş QRS (>100 ms) ve aVR'de R dalgası TSA sodyum kanal blokajını kanıtlar. BZD nöbeti baskılar; flumazenil verilirse ölümcül nöbet fırtınası başlar.\",\"ar\":\"صحيح! يشير اتساع QRS وموجة R في aVR لحصار قنوات الصوديوم بواسطة TCA. يحمي البنزوديازيبين من النوبات؛ فإذا أزيل بالفلومازينيل حدثت الوفاة.\"}},{\"id\":\"opt_pure_barbiturate_reversal\",\"text\":{\"en\":\"The ECG indicates acute phenobarbital poisoning where flumazenil acts as a paradoxical agonist, deepening medullary coma and provoking immediate asystole.\",\"tr\":\"EKG, flumazenilin paradoksal agonist olarak komayı derinleştirdiği ve asistoli yaptığı akut fenobarbital zehirlenmesine işaret eder.\",\"ar\":\"يشير التخطيط لتسمم حاد بالفينوباربيتال حيث يعمل الفلومازينيل كناهض متناقض معمقاً الغيبوبة ومسبباً توقف القلب.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Barbiturate toxicity does not typically cause QRS widening, and flumazenil does not bind the barbiturate site or cause asystole.\",\"tr\":\"Yanlış. Barbitürat zehirlenmesi tipik QRS genişlemesi yapmaz ve flumazenil barbitürat bölgesine bağlanmaz.\",\"ar\":\"غير صحيح. لا يسبب التسمم بالباربيتورات اتساع QRS نوعياً، كما لا يرتبط الفلومازينيل بموقع الباربيتورات إطلاقاً.\"}},{\"id\":\"opt_mu_opioid_blockade\",\"text\":{\"en\":\"Flumazenil acts as a competitive antagonist at medullary mu-opioid receptors, precipitating severe pulmonary edema in patients with respiratory depression.\",\"tr\":\"Flumazenil medüller mü-opioid reseptörlerinde yarışmalı antagonist gibi davranarak solunum depresyonlu hastada akut akciğer ödemi başlatır.\",\"ar\":\"يعمل الفلومازينيل كمناهض تنافسي عند مستقبلات مو الأفيونية النخاعية مما يسبب وذمة رئوية حادة لدى مرضى التثبيط التنفسي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Naloxone, not flumazenil, antagonizes opioid mu receptors. Flumazenil is completely inactive at opioid receptors.\",\"tr\":\"Yanlış. Opioid mü reseptörlerini bloke eden naloksandır. Flumazenil opioid reseptörlerine bağlanmaz.\",\"ar\":\"غير صحيح. النالوكسون هو من يعاكس مستقبلات مو الأفيونية؛ بينما الفلومازينيل غير فعال تماماً عند المستقبلات الأفيونية.\"}},{\"id\":\"opt_romk_hyperkalemia\",\"text\":{\"en\":\"Flumazenil directly blocks renal apical ROMK channels, driving serum potassium above 7.5 mEq/L and precipitating hyperkalemic ventricular arrest.\",\"tr\":\"Flumazenil böbrek apikal ROMK kanallarını doğrudan bloke ederek serum potasyumunu 7.5 mEq/L üzerine çıkarır ve hiperkalemik arrest yapar.\",\"ar\":\"يحظر الفلومازينيل قنوات ROMK الكلوية مباشرة رافعاً بوتاسيوم المصل فوق 7.5 ميلي مكافئ/لتر ومسبباً توقف القلب بفرط البوتاسيوم.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Flumazenil has no renal ion channel interactions; the life-threatening danger is removing seizure suppression during TCA co-ingestion.\",\"tr\":\"Yanlış. Flumazenil böbrek kanallarını etkilemez; ölümcül tehlike TSA alımında nöbet kalkanının kalkmasıdır.\",\"ar\":\"غير صحيح. لا يؤثر الفلومازينيل على القنوات الكلوية؛ بل الخطر القاتل هو إزالة كبح التشنجات أثناء التسمم المشترك بـ TCA.\"}}]},\"technicalTerms\":[{\"term\":\"etki mekanizması\",\"arContext\":\"آلية التأثير الدوائي\"},{\"term\":\"reseptör\",\"arContext\":\"المستقبِل الحيوي\"}],\"hints\":[{\"tier\":1,\"tr\":\"EKG'deki QRS genişlemesi ve aVR'deki R dalgası hangi ölümcül ilaç zehirlenmesinin patognomonik bulgusudur?\",\"ar\":\"اتساع مركب QRS وظهور موجة R في اشتقاق aVR علامتان فارقتان لأي تسمم دوائي مهدد للحياة؟\",\"en\":\"What life-threatening drug toxicity is pathognomonically signaled by widened QRS and a tall terminal aVR R wave?\"},{\"tier\":2,\"tr\":\"Bu bulgular trisiklik antidepresan (TSA) sodyum kanal blokajını gösterir; hastadaki BZD nöbeti baskılamaktadır.\",\"ar\":\"تشير هذه التغيرات لحصار قنوات الصوديوم بمضادات الاكتئاب ثلاثية الحلقات؛ والبنزوديازيبين يكبح النوبات حالياً.\",\"en\":\"These findings confirm TCA cardiac sodium channel blockade; the co-ingested BZD is suppressing seizures.\"},{\"tier\":3,\"tr\":\"Flumazenil koruyucu BZD kalkanını yıkar ve hastayı tedavi edilemez status epileptikus ile ventriküler fibrilasyona sokar.\",\"ar\":\"إعطاء الفلومازينيل يسقط حماية البنزوديازيبين مفجراً حالة صرعية معندة ورجفاناً بطينياً مميتاً.\",\"en\":\"Flumazenil destroys the protective BZD tone, precipitating intractable status epilepticus and lethal arrhythmias.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_tca_ecg_unmasking\",\"text\":{\"en\":\"The ECG reveals co-ingested TCA cardiotoxicity; flumazenil strips protective BZD anticonvulsant tone, unleashing refractory status epilepticus and lethal ventricular arrhythmias.\",\"tr\":\"EKG eşlik eden TSA toksisitesini gösterir; flumazenil BZD'nin nöbet önleyici kalkanını kaldırarak dirençli status epileptikus ve ölümcül ventriküler aritmiyi tetikler.\",\"ar\":\"يكشف التخطيط سمية قلبية مرافقة لمضادات الاكتئاب ثلاثية الحلقات؛ يجرد الفلومازينيل حماية البنزوديازيبين مفجراً حالة صرعية واضطرابات بطينية قاتلة.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Widened QRS (>100 ms) and prominent aVR R wave indicate TCA sodium channel blockade. BZDs suppress TCA seizures; flumazenil unleashes fatal convulsions.\",\"tr\":\"Doğru! Geniş QRS (>100 ms) ve aVR'de R dalgası TSA sodyum kanal blokajını kanıtlar. BZD nöbeti baskılar; flumazenil verilirse ölümcül nöbet fırtınası başlar.\",\"ar\":\"صحيح! يشير اتساع QRS وموجة R في aVR لحصار قنوات الصوديوم بواسطة TCA. يحمي البنزوديازيبين من النوبات؛ فإذا أزيل بالفلومازينيل حدثت الوفاة.\"}},{\"id\":\"opt_pure_barbiturate_reversal\",\"text\":{\"en\":\"The ECG indicates acute phenobarbital poisoning where flumazenil acts as a paradoxical agonist, deepening medullary coma and provoking immediate asystole.\",\"tr\":\"EKG, flumazenilin paradoksal agonist olarak komayı derinleştirdiği ve asistoli yaptığı akut fenobarbital zehirlenmesine işaret eder.\",\"ar\":\"يشير التخطيط لتسمم حاد بالفينوباربيتال حيث يعمل الفلومازينيل كناهض متناقض معمقاً الغيبوبة ومسبباً توقف القلب.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Barbiturate toxicity does not typically cause QRS widening, and flumazenil does not bind the barbiturate site or cause asystole.\",\"tr\":\"Yanlış. Barbitürat zehirlenmesi tipik QRS genişlemesi yapmaz ve flumazenil barbitürat bölgesine bağlanmaz.\",\"ar\":\"غير صحيح. لا يسبب التسمم بالباربيتورات اتساع QRS نوعياً، كما لا يرتبط الفلومازينيل بموقع الباربيتورات إطلاقاً.\"}},{\"id\":\"opt_mu_opioid_blockade\",\"text\":{\"en\":\"Flumazenil acts as a competitive antagonist at medullary mu-opioid receptors, precipitating severe pulmonary edema in patients with respiratory depression.\",\"tr\":\"Flumazenil medüller mü-opioid reseptörlerinde yarışmalı antagonist gibi davranarak solunum depresyonlu hastada akut akciğer ödemi başlatır.\",\"ar\":\"يعمل الفلومازينيل كمناهض تنافسي عند مستقبلات مو الأفيونية النخاعية مما يسبب وذمة رئوية حادة لدى مرضى التثبيط التنفسي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Naloxone, not flumazenil, antagonizes opioid mu receptors. Flumazenil is completely inactive at opioid receptors.\",\"tr\":\"Yanlış. Opioid mü reseptörlerini bloke eden naloksandır. Flumazenil opioid reseptörlerine bağlanmaz.\",\"ar\":\"غير صحيح. النالوكسون هو من يعاكس مستقبلات مو الأفيونية؛ بينما الفلومازينيل غير فعال تماماً عند المستقبلات الأفيونية.\"}},{\"id\":\"opt_romk_hyperkalemia\",\"text\":{\"en\":\"Flumazenil directly blocks renal apical ROMK channels, driving serum potassium above 7.5 mEq/L and precipitating hyperkalemic ventricular arrest.\",\"tr\":\"Flumazenil böbrek apikal ROMK kanallarını doğrudan bloke ederek serum potasyumunu 7.5 mEq/L üzerine çıkarır ve hiperkalemik arrest yapar.\",\"ar\":\"يحظر الفلومازينيل قنوات ROMK الكلوية مباشرة رافعاً بوتاسيوم المصل فوق 7.5 ميلي مكافئ/لتر ومسبباً توقف القلب بفرط البوتاسيوم.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Flumazenil has no renal ion channel interactions; the life-threatening danger is removing seizure suppression during TCA co-ingestion.\",\"tr\":\"Yanlış. Flumazenil böbrek kanallarını etkilemez; ölümcül tehlike TSA alımında nöbet kalkanının kalkmasıdır.\",\"ar\":\"غير صحيح. لا يؤثر الفلومازينيل على القنوات الكلوية؛ بل الخطر القاتل هو إزالة كبح التشنجات أثناء التسمم المشترك بـ TCA.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":12}]}]},\"pharm-mod6-les2\":{\"id\":\"pharm-mod6-les2\",\"courseId\":\"pharmacology\",\"moduleId\":\"ph-mod-06\",\"title\":{\"tr\":\"Dopaminerjik Yolaklar ve Antipsikotik Reseptör Profilleri\",\"ar\":\"المسارات الدوبامينية والمظهر المستقبلاتي لمضادات الذهان\",\"en\":\"Dopaminergic Pathways & Antipsychotic Receptor Profiles\"},\"order\":2,\"access\":\"free\",\"objective\":{\"tr\":\"Dört merkezi dopaminerjik yolağı, D2 reseptör blokaj eşiğini (%65-80) ve atipik antipsikotiklerin 5-HT2A/D2 dengesini kavramak.\",\"ar\":\"إتقان المسارات الدوبامينية المركزية الأربعة، وعتبة حظر D2 (65-80%)، وتوازن 5-HT2A/D2 لمضادات الذهان غير النمطية.\",\"en\":\"Analyze four central dopaminergic pathways, the 65-80% D2 occupancy therapeutic window, and atypical 5-HT2A/D2 balance.\"},\"misconceptions\":[{\"tr\":\"D2 reseptörünü ne kadar çok bloke edersek antipsikotik etkinin o kadar iyi olacağı yanılgısı (%80 in üzerinde şiddetli parkinson benzeri ekstrapiramidal semptomlar çıkar).\",\"ar\":\"الظن الخاطئ بأن زيادة حظر D2 تحسن الفعالية دوماً (تجاوز 80% يفجر أعراضاً خارج هرمية شلل-رعاشية حادة).\",\"en\":\"Higher D2 receptor occupancy (>80%) provides superior antipsychotic efficacy without extrapyramidal symptoms.\"}],\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":22}],\"citations\":[{\"id\":\"cit-ref-01\",\"book\":\"Goodman & Gilman's The Pharmacological Basis of Therapeutics\",\"edition\":\"14th ed.\",\"topic\":\"Dopaminergic Pathways and Antipsychotic Receptor Profiles\"}],\"spacedReviewCards\":[{\"cardId\":\"pharm-mod6-les2-card1\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Terapötik D2 Blokaj Penceresi\",\"prompt\":\"Antipsikotik etkinlik ve ekstrapiramidal güvenliğin sağlandığı D2 reseptör doluluk penceresi nedir?\",\"answer\":\"%65 ila %80 doluluk aralığıdır. %65 in altında etki yetersiz, %80 in üstünde EPS gelişir.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod6-les2-card2\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Dört Dopamin Yolağı\",\"prompt\":\"Antipsikotik etkinin görüldüğü ve ekstrapiramidal yan etkinin (EPS) çıktığı iki yolak hangileridir?\",\"answer\":\"Antipsikotik etki Mezolimbik yolakta; motor yan etki (EPS) Nigrostriatal yolakta görülür.\",\"box\":1,\"intervalDays\":1},{\"cardId\":\"pharm-mod6-les2-card3\",\"courseId\":\"pharmacology\",\"drugOrConcept\":\"Atipik Antipsikotik Sırrı\",\"prompt\":\"İkinci kuşak atipik antipsikotikler (olanzapin, klozapin) neden daha az ekstrapiramidal yan etki yapar?\",\"answer\":\"Güçlü 5-HT2A serotonin blokajı nigrostriatal yolda dopamin salınımını serbest bırakarak EPS yi önler.\",\"box\":1,\"intervalDays\":1}],\"translations\":{\"tr\":{\"title\":\"Dopaminerjik Yolaklar ve Antipsikotik Reseptör Profilleri\"},\"ar\":{\"title\":\"المسارات الدوبامينية والمظهر المستقبلاتي لمضادات الذهان\"}},\"steps\":[{\"id\":\"pharm-mod6-les2-step-01\",\"stage\":\"hook\",\"stageIndex\":1,\"title\":{\"tr\":\"Halüsinasyonları Sustururken Bedeni Kilitlemek\",\"ar\":\"إسكات الهلاوس وتصلب الجسد\",\"en\":\"Quieting Hallucinations While Freezing the Body\"},\"prompt\":{\"en\":\"Haloperidol rapidly quells auditory hallucinations in the mesolimbic pathway, yet within two hours violently twists the patient's neck and eyes. Why does blocking D2 trigger acute muscle dystonia?\",\"tr\":\"Haloperidol mezolimbik yolda işitsel halüsinasyonları hızla dindirirken, iki saat içinde hastanın boynunu ve gözlerini şiddetle büker. D2 blokajı neden akut distoniye yol açar?\",\"ar\":\"يخمد الهالوبيريدول الهلاوس السمعية ميزولمبياً بسرعة، لكنه بعد ساعتين يلوي عنق المريض وعينيه بعنف. لماذا يفجر حظر D2 خلل التوتر العضلي الحاد؟\"},\"predictThenReveal\":true,\"config\":{\"options\":[{\"id\":\"opt_striatal_ach_surge\",\"text\":{\"en\":\"Blocking striatal D2 removes dopamine's tonic inhibitory brake on cholinergic interneurons, unleashing an unchecked acetylcholine surge that drives acute muscle dystonia.\",\"tr\":\"Striatal D2 blokajı, dopaminin kolinerjik internöronlar üzerindeki inhibitör frenini kaldırarak aşırı asetilkolin deşarjına ve kas distonisine yol açar.\",\"ar\":\"يزيل حظر D2 في المخطط كبح الدوبامين للخلية البينية الكولينية، مفرغاً تدفقاً هائلاً للأسيتيل كولين يقود لخلل التوتر العضلي الحاد.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! In the striatum, dopamine tonically inhibits acetylcholine release. Haloperidol removes this brake, producing an acute cholinergic spasm.\",\"tr\":\"Doğru! Striatumda dopamin asetilkolini frenler. D2 blokajı bu freni kaldırarak kolinerjik fırtınaya ve akut distoniye neden olur.\",\"ar\":\"صحيح! يكبح الدوبامين إفراز الأسيتيل كولين في المخطط؛ وحظر D2 يزيل هذا الكبح مفجراً تشنجاً كولينياً حاداً.\"}},{\"id\":\"opt_direct_nicotinic_stimulation\",\"text\":{\"en\":\"Haloperidol directly stimulates nicotinic acetylcholine receptors at peripheral neuromuscular junctions, triggering sustained muscle contraction.\",\"tr\":\"Haloperidol periferik nöromüsküler kavşaktaki nikotinik asetilkolin reseptörlerini doğrudan uyararak kalıcı kas kasılması başlatır.\",\"ar\":\"يحفز الهالوبيريدول مستقبلات الأسيتيل كولين النيكوتينية في الوصل العصبي العضلي المحيطي مباشرة مسبباً انقباضاً عضلياً.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Haloperidol does not bind peripheral nicotinic receptors; dystonia is a central striatal dopamine-acetylcholine imbalance.\",\"tr\":\"Yanlış. Haloperidol periferik nikotinik reseptörlere bağlanmaz; distoni santral striatal dopamin-asetilkolin dengesizliğidir.\",\"ar\":\"غير صحيح. لا يرتبط الهالوبيريدول بالمستقبلات النيكوتينية؛ بل خلل التوتر ناتج عن اختلال توازن الدوبامين والأسيتيل كولين في المخطط.\"}},{\"id\":\"opt_d1_agonist_belief\",\"text\":{\"en\":\"Striatal D2 receptors are Gs-coupled, and haloperidol acts as a full agonist that hyperactivates adenylyl cyclase to trigger spasms.\",\"tr\":\"Striatal D2 reseptörleri Gs kenetlidir ve haloperidol spazm oluşturmak için adenilat siklazı aşırı uyaran bir tam agonisttir.\",\"ar\":\"مستقبلات D2 مقترنة ببروتين Gs، ويعمل الهالوبيريدول كناهض تام يفرط في تنشيط محلقة الأدينيلات لإحداث التشنجات.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. D2 receptors are Gi-coupled, and haloperidol is a potent antagonist, not an agonist.\",\"tr\":\"Yanlış. D2 reseptörleri Gi kenetlidir ve haloperidol agonist değil çok güçlü bir antagonisttir.\",\"ar\":\"غير صحيح. مستقبلات D2 مقترنة ببروتين Gi المثبط، والهالوبيريدول مناهض قوي وليس ناهضاً.\"}},{\"id\":\"opt_hypocalcemia_belief\",\"text\":{\"en\":\"Haloperidol causes massive renal calcium wasting within two hours, producing severe hypocalcemic tetany resembling motor dystonia.\",\"tr\":\"Haloperidol iki saat içinde böbrekten aşırı kalsiyum atılımına yol açarak motor distoniyi taklit eden şiddetli hipokalsemik tetani yapar.\",\"ar\":\"يسبب الهالوبيريدول فقداناً كلوياً هائلاً للكالسيوم خلال ساعتين، محدثاً كزازاً بنقص الكالسيوم يشبه خلل التوتر الحركي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Haloperidol has no direct effect on renal tubular calcium handling; acute dystonia is exclusively a central extrapyramidal side effect.\",\"tr\":\"Yanlış. Haloperidol böbrek kalsiyum atılımını etkilemez; akut distoni tamamen santral ekstrapiramidal bir yan etkidir.\",\"ar\":\"غير صحيح. لا يؤثر الهالوبيريدول على إطراح الكالسيوم الكلوي؛ بل خلل التوتر هو عرض جانبي حركي خارج هرمي مركزي.\"}}]},\"technicalTerms\":[{\"term\":\"D2 reseptör blokajı\",\"arContext\":\"حظر مستقبِلات D2\"}],\"hints\":[{\"tier\":1,\"tr\":\"Dopaminin beyindeki tek bir bölgede değil, farklı anatomik yolaklarda farklı görevler yürüttüğünü hatırlayın.\",\"ar\":\"تذكر أن الدوبامين لا يعمل في مركز واحد، بل يدير وظائف متباينة في مسارات تشريحية مستقلة.\",\"en\":\"Remember that dopamine operates across segregated anatomical pathways with distinct physiological functions.\"},{\"tier\":2,\"tr\":\"Striatumdaki motor kontrol merkezinde dopamin ile asetilkolin arasında hassas bir denge tahterevallisi bulunur.\",\"ar\":\"يوجد في مركز التحكم الحركي بالمخطط أرجوحة توازن دقيقة بين الدوبامين والأسيتيل كولين.\",\"en\":\"In the striatal motor center, dopamine and acetylcholine exist in a delicately balanced seesaw equilibrium.\"},{\"tier\":3,\"tr\":\"D2 blokajı mezolimbikte psikozu dindirirken, nigrostriatal yolda dopaminin asetilkolin üzerindeki frenini kaldırarak akut distoni yapar.\",\"ar\":\"حظر D2 يخمد الذهان ميزولمبياً، لكنه يرفع كبح الدوبامين عن الأسيتيل كولين حركياً مفجراً تشنجاً كولينياً حاداً.\",\"en\":\"Blocking D2 quiets mesolimbic psychosis, but lifts dopamine's brake on striatal acetylcholine to cause acute dystonia.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_striatal_ach_surge\",\"text\":{\"en\":\"Blocking striatal D2 removes dopamine's tonic inhibitory brake on cholinergic interneurons, unleashing an unchecked acetylcholine surge that drives acute muscle dystonia.\",\"tr\":\"Striatal D2 blokajı, dopaminin kolinerjik internöronlar üzerindeki inhibitör frenini kaldırarak aşırı asetilkolin deşarjına ve kas distonisine yol açar.\",\"ar\":\"يزيل حظر D2 في المخطط كبح الدوبامين للخلية البينية الكولينية، مفرغاً تدفقاً هائلاً للأسيتيل كولين يقود لخلل التوتر العضلي الحاد.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! In the striatum, dopamine tonically inhibits acetylcholine release. Haloperidol removes this brake, producing an acute cholinergic spasm.\",\"tr\":\"Doğru! Striatumda dopamin asetilkolini frenler. D2 blokajı bu freni kaldırarak kolinerjik fırtınaya ve akut distoniye neden olur.\",\"ar\":\"صحيح! يكبح الدوبامين إفراز الأسيتيل كولين في المخطط؛ وحظر D2 يزيل هذا الكبح مفجراً تشنجاً كولينياً حاداً.\"}},{\"id\":\"opt_direct_nicotinic_stimulation\",\"text\":{\"en\":\"Haloperidol directly stimulates nicotinic acetylcholine receptors at peripheral neuromuscular junctions, triggering sustained muscle contraction.\",\"tr\":\"Haloperidol periferik nöromüsküler kavşaktaki nikotinik asetilkolin reseptörlerini doğrudan uyararak kalıcı kas kasılması başlatır.\",\"ar\":\"يحفز الهالوبيريدول مستقبلات الأسيتيل كولين النيكوتينية في الوصل العصبي العضلي المحيطي مباشرة مسبباً انقباضاً عضلياً.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Haloperidol does not bind peripheral nicotinic receptors; dystonia is a central striatal dopamine-acetylcholine imbalance.\",\"tr\":\"Yanlış. Haloperidol periferik nikotinik reseptörlere bağlanmaz; distoni santral striatal dopamin-asetilkolin dengesizliğidir.\",\"ar\":\"غير صحيح. لا يرتبط الهالوبيريدول بالمستقبلات النيكوتينية؛ بل خلل التوتر ناتج عن اختلال توازن الدوبامين والأسيتيل كولين في المخطط.\"}},{\"id\":\"opt_d1_agonist_belief\",\"text\":{\"en\":\"Striatal D2 receptors are Gs-coupled, and haloperidol acts as a full agonist that hyperactivates adenylyl cyclase to trigger spasms.\",\"tr\":\"Striatal D2 reseptörleri Gs kenetlidir ve haloperidol spazm oluşturmak için adenilat siklazı aşırı uyaran bir tam agonisttir.\",\"ar\":\"مستقبلات D2 مقترنة ببروتين Gs، ويعمل الهالوبيريدول كناهض تام يفرط في تنشيط محلقة الأدينيلات لإحداث التشنجات.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. D2 receptors are Gi-coupled, and haloperidol is a potent antagonist, not an agonist.\",\"tr\":\"Yanlış. D2 reseptörleri Gi kenetlidir ve haloperidol agonist değil çok güçlü bir antagonisttir.\",\"ar\":\"غير صحيح. مستقبلات D2 مقترنة ببروتين Gi المثبط، والهالوبيريدول مناهض قوي وليس ناهضاً.\"}},{\"id\":\"opt_hypocalcemia_belief\",\"text\":{\"en\":\"Haloperidol causes massive renal calcium wasting within two hours, producing severe hypocalcemic tetany resembling motor dystonia.\",\"tr\":\"Haloperidol iki saat içinde böbrekten aşırı kalsiyum atılımına yol açarak motor distoniyi taklit eden şiddetli hipokalsemik tetani yapar.\",\"ar\":\"يسبب الهالوبيريدول فقداناً كلوياً هائلاً للكالسيوم خلال ساعتين، محدثاً كزازاً بنقص الكالسيوم يشبه خلل التوتر الحركي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Haloperidol has no direct effect on renal tubular calcium handling; acute dystonia is exclusively a central extrapyramidal side effect.\",\"tr\":\"Yanlış. Haloperidol böbrek kalsiyum atılımını etkilemez; akut distoni tamamen santral ekstrapiramidal bir yan etkidir.\",\"ar\":\"غير صحيح. لا يؤثر الهالوبيريدول على إطراح الكالسيوم الكلوي؛ بل خلل التوتر هو عرض جانبي حركي خارج هرمي مركزي.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":17}]},{\"id\":\"pharm-mod6-les2-step-02\",\"stage\":\"question\",\"stageIndex\":2,\"title\":{\"tr\":\"Tahmin: İdeal Blokaj Yüzdesi\",\"ar\":\"توقع: نسبة الإشغال المثالية\",\"en\":\"Prediction: The Ideal D2 Receptor Occupancy Window\"},\"prompt\":{\"en\":\"Why does pure D2 receptor antagonism fail to effectively treat all schizophrenia symptoms simultaneously across the four major dopaminergic pathways?\",\"tr\":\"Saf D2 reseptör antagonizması dört ana dopaminerjik yolakta neden tüm şizofreni semptomlarını aynı anda başarıyla tedavi edemez?\",\"ar\":\"لماذا يفشل الحظر الخالص لمستقبلات D2 في علاج جميع أعراض الفصام في آن واحد عبر المسارات الدوبامينية الأربعة؟\"},\"predictThenReveal\":true,\"config\":{\"revealedOutcome\":\"%65-80 arası terapötik penceredir; %80 in üzeri kaçınılmaz motor blokaj yaratır.\",\"options\":[{\"id\":\"opt_pathway_divergence\",\"text\":{\"en\":\"Blocking D2 treats mesolimbic positive symptoms, but worsens mesocortical negative symptoms, causes nigrostriatal EPS, and triggers tuberoinfundibular hyperprolactinemia.\",\"tr\":\"D2 blokajı mezolimbik pozitif semptomları düzeltirken, mezokortikal negatif semptomları kötüleştirir, nigrostriatal EPS ve tüberoinfundibuler hiperprolaktinemi yapar.\",\"ar\":\"حظر D2 يعالج إيجابيات الميزولمبيك، لكنه يفاقم سلبيات الميزوكورتيكال، ويسبب أعراضاً خارج هرمية بالمخطط، وفرط برولاكتين بالمسار القمعي.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! D2 blockade quells mesolimbic hyperactivity, but aggravates hypodopaminergic mesocortical states, causes EPS, and disinhibits prolactin.\",\"tr\":\"Doğru! D2 blokajı mezolimbik hiperaktiviteyi dindirir; ancak kortikal negatif semptomları artırır, motor EPS ve prolaktin yüksekliği yapar.\",\"ar\":\"صحيح! يخمد حظر D2 نشاط الميزولمبيك المفرط، لكنه يفاقم نقص الدوبامين القشري، ويسبب أعراضاً خارج هرمية، ويحرر إفراز البرولاكتين.\"}},{\"id\":\"opt_mesocortical_cure\",\"text\":{\"en\":\"Pure D2 blockade selectively stimulates cortical dopamine release, curing negative symptoms while sparing motor and pituitary pathways.\",\"tr\":\"Saf D2 blokajı kortikal dopamin salınımını seçici uyararak motor ve hipofiz yollarını korurken negatif semptomları tamamen iyileştirir.\",\"ar\":\"يحفز حظر D2 الخالص إفراز الدوبامين القشري انتقائياً، فيشفي الأعراض السلبية مجنباً المسارات الحركية والنخامية.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Pure D2 blockade further suppresses already deficient mesocortical dopamine signaling, worsening emotional blunting and apathy.\",\"tr\":\"Yanlış. Saf D2 blokajı zaten yetersiz olan mezokortikal dopamini daha da bloke ederek negatif semptomları şiddetlendirir.\",\"ar\":\"غير صحيح. يزيد حظر D2 الخالص من خنق إشارات الدوبامين القشرية الضعيفة أصلاً، مفاقماً التبلد الانفعالي والانعزال.\"}},{\"id\":\"opt_prolactin_suppression_belief\",\"text\":{\"en\":\"D2 blockade in the tuberoinfundibular pathway shuts down pituitary lactotrophs, leading to complete cessation of prolactin production.\",\"tr\":\"Tüberoinfundibuler yolaktaki D2 blokajı hipofiz laktotrof hücrelerini susturarak prolaktin üretimini tamamen durdurur.\",\"ar\":\"يعطل حظر D2 في المسار القمعي خلايا اللاكتوتروف النخامية مما يؤدي لتوقف تام في إنتاج هرمون البرولاكتين.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Dopamine tonically INHIBITS prolactin release. Blocking D2 removes this inhibition, causing profound HYPERprolactinemia.\",\"tr\":\"Yanlış. Dopamin hipofizde prolaktin salınımını BASKILAR. D2 bloke edilince bu baskı kalkar ve HİPERprolaktinemi gelişir.\",\"ar\":\"غير صحيح. يثبط الدوبامين إفراز البرولاكتين طبيعياً؛ وبالتالي فحظر D2 يرفع البرولاكتين بشدة (فرط برولاكتين الدم).\"}},{\"id\":\"opt_bbb_exclusion_belief\",\"text\":{\"en\":\"Haloperidol cannot cross the blood-brain barrier into cortical regions, leaving mesocortical and nigrostriatal circuits completely untouched.\",\"tr\":\"Haloperidol kan-beyin bariyerini geçip kortikal bölgelere ulaşamaz; mezokortikal ve nigrostriatal devreleri tamamen dokunulmamış bırakır.\",\"ar\":\"يعجز الهالوبيريدول عن اختراق الحاجز الدموي الدماغي نحو المناطق القشرية، تاركاً مسارات الميزوكورتيكال والمخطط دون أي تأثير.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Haloperidol is highly lipophilic and readily distributes throughout the entire brain, occupying D2 receptors across all pathways.\",\"tr\":\"Yanlış. Haloperidol yüksek oranda lipofiliktir, tüm beyne dağılır ve her dört yolaktaki D2 reseptörlerini de bloke eder.\",\"ar\":\"غير صحيح. الهالوبيريدول شديد الذوبان بالدسم ويخترق الدماغ بأكمله محتلاً مستقبلات D2 في جميع المسارات.\"}}]},\"technicalTerms\":[{\"term\":\"etki mekanizması\",\"arContext\":\"آلية التأثير الدوائي\"},{\"term\":\"reseptör\",\"arContext\":\"المستقبِل الحيوي\"}],\"hints\":[{\"tier\":1,\"tr\":\"Dört dopamin yolağını gözünüzün önüne getirin: mezolimbik, mezokortikal, nigrostriatal ve tüberoinfundibuler.\",\"ar\":\"استحضر المسارات الدوبامينية الأربعة: الميزولمبي، الميزوكورتيكال، المخططي الأسود، والقمعي النخامي.\",\"en\":\"Envision the four core dopamine pathways: mesolimbic, mesocortical, nigrostriatal, and tuberoinfundibular.\"},{\"tier\":2,\"tr\":\"Şizofrenide mezolimbik yol hiperaktifken, mezokortikal yol zaten dopamin eksikliği nedeniyle hipoaktiftir.\",\"ar\":\"في الفصام يكون الميزولمبيك مفرط النشاط، بينما يعاني الميزوكورتيكال أصلاً من نقص الدوبامين وخمول النشاط.\",\"en\":\"In schizophrenia, the mesolimbic path is hyperactive, while the mesocortical path is already hypoactive.\"},{\"tier\":3,\"tr\":\"D2 antagonisti pozitif semptomları çözer ama negatif semptomları, motor hareketleri ve prolaktin yüksekliğini kötüleştirir.\",\"ar\":\"يعالج مناهض D2 الأعراض الإيجابية، لكنه يفاقم الأعراض السلبية، ويحدث اضطراب الحركة وفرط البرولاكتين.\",\"en\":\"Pure D2 blockade cures positive symptoms, but worsens negative symptoms, causes motor EPS, and elevates prolactin.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_pathway_divergence\",\"text\":{\"en\":\"Blocking D2 treats mesolimbic positive symptoms, but worsens mesocortical negative symptoms, causes nigrostriatal EPS, and triggers tuberoinfundibular hyperprolactinemia.\",\"tr\":\"D2 blokajı mezolimbik pozitif semptomları düzeltirken, mezokortikal negatif semptomları kötüleştirir, nigrostriatal EPS ve tüberoinfundibuler hiperprolaktinemi yapar.\",\"ar\":\"حظر D2 يعالج إيجابيات الميزولمبيك، لكنه يفاقم سلبيات الميزوكورتيكال، ويسبب أعراضاً خارج هرمية بالمخطط، وفرط برولاكتين بالمسار القمعي.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! D2 blockade quells mesolimbic hyperactivity, but aggravates hypodopaminergic mesocortical states, causes EPS, and disinhibits prolactin.\",\"tr\":\"Doğru! D2 blokajı mezolimbik hiperaktiviteyi dindirir; ancak kortikal negatif semptomları artırır, motor EPS ve prolaktin yüksekliği yapar.\",\"ar\":\"صحيح! يخمد حظر D2 نشاط الميزولمبيك المفرط، لكنه يفاقم نقص الدوبامين القشري، ويسبب أعراضاً خارج هرمية، ويحرر إفراز البرولاكتين.\"}},{\"id\":\"opt_mesocortical_cure\",\"text\":{\"en\":\"Pure D2 blockade selectively stimulates cortical dopamine release, curing negative symptoms while sparing motor and pituitary pathways.\",\"tr\":\"Saf D2 blokajı kortikal dopamin salınımını seçici uyararak motor ve hipofiz yollarını korurken negatif semptomları tamamen iyileştirir.\",\"ar\":\"يحفز حظر D2 الخالص إفراز الدوبامين القشري انتقائياً، فيشفي الأعراض السلبية مجنباً المسارات الحركية والنخامية.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Pure D2 blockade further suppresses already deficient mesocortical dopamine signaling, worsening emotional blunting and apathy.\",\"tr\":\"Yanlış. Saf D2 blokajı zaten yetersiz olan mezokortikal dopamini daha da bloke ederek negatif semptomları şiddetlendirir.\",\"ar\":\"غير صحيح. يزيد حظر D2 الخالص من خنق إشارات الدوبامين القشرية الضعيفة أصلاً، مفاقماً التبلد الانفعالي والانعزال.\"}},{\"id\":\"opt_prolactin_suppression_belief\",\"text\":{\"en\":\"D2 blockade in the tuberoinfundibular pathway shuts down pituitary lactotrophs, leading to complete cessation of prolactin production.\",\"tr\":\"Tüberoinfundibuler yolaktaki D2 blokajı hipofiz laktotrof hücrelerini susturarak prolaktin üretimini tamamen durdurur.\",\"ar\":\"يعطل حظر D2 في المسار القمعي خلايا اللاكتوتروف النخامية مما يؤدي لتوقف تام في إنتاج هرمون البرولاكتين.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Dopamine tonically INHIBITS prolactin release. Blocking D2 removes this inhibition, causing profound HYPERprolactinemia.\",\"tr\":\"Yanlış. Dopamin hipofizde prolaktin salınımını BASKILAR. D2 bloke edilince bu baskı kalkar ve HİPERprolaktinemi gelişir.\",\"ar\":\"غير صحيح. يثبط الدوبامين إفراز البرولاكتين طبيعياً؛ وبالتالي فحظر D2 يرفع البرولاكتين بشدة (فرط برولاكتين الدم).\"}},{\"id\":\"opt_bbb_exclusion_belief\",\"text\":{\"en\":\"Haloperidol cannot cross the blood-brain barrier into cortical regions, leaving mesocortical and nigrostriatal circuits completely untouched.\",\"tr\":\"Haloperidol kan-beyin bariyerini geçip kortikal bölgelere ulaşamaz; mezokortikal ve nigrostriatal devreleri tamamen dokunulmamış bırakır.\",\"ar\":\"يعجز الهالوبيريدول عن اختراق الحاجز الدموي الدماغي نحو المناطق القشرية، تاركاً مسارات الميزوكورتيكال والمخطط دون أي تأثير.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Haloperidol is highly lipophilic and readily distributes throughout the entire brain, occupying D2 receptors across all pathways.\",\"tr\":\"Yanlış. Haloperidol yüksek oranda lipofiliktir, tüm beyne dağılır ve her dört yolaktaki D2 reseptörlerini de bloke eder.\",\"ar\":\"غير صحيح. الهالوبيريدول شديد الذوبان بالدسم ويخترق الدماغ بأكمله محتلاً مستقبلات D2 في جميع المسارات.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":18}]},{\"id\":\"pharm-mod6-les2-step-03\",\"stage\":\"intuition\",\"stageIndex\":3,\"title\":{\"tr\":\"Sezgisel Model: 4 Farklı Odaya Açılan Tek Şalter\",\"ar\":\"تشبيه حدسي: مفتاح واحد يتحكم بأربع غرف متباينة\",\"en\":\"Intuitive Model: One Switch Controlling Four Distinct Rooms\"},\"prompt\":{\"en\":\"PET studies reveal antipsychotic response begins at 65% D2 occupancy, while exceeding 80% triggers extrapyramidal motor toxicity. What does this narrow 15% window dictate clinically?\",\"tr\":\"PET çalışmaları antipsikotik yanıtın %65 D2 doluluğunda başladığını, %80 aşılınca EPS motor toksisitesinin patlak verdiğini gösterir. Bu dar %15'lik pencere ne anlama gelir?\",\"ar\":\"تكشف دراسات PET أن الاستجابة المضادة للذهان تبدأ عند إشغال 65% لـ D2، وتجاوز 80% يفجر السمية الحركية. ماذا يملي هذا الهامش الضيق سريرياً؟\"},\"predictThenReveal\":false,\"config\":{\"options\":[{\"id\":\"opt_pet_window\",\"text\":{\"en\":\"Clinical antipsychotic efficacy requires at least 65% D2 occupancy, while exceeding 80% sharply unleashes extrapyramidal symptoms and hyperprolactinemia.\",\"tr\":\"Antipsikotik etkinlik en az %65 D2 doluluğu gerektirirken, %80'in aşılması ekstrapiramidal semptomları ve hiperprolaktinemiyi hızla tetikler.\",\"ar\":\"تتطلب الفعالية المضادة للذهان إشغال 65% على الأقل لـ D2، بينما يتسبب تجاوز 80% باندلاع حاد للأعراض خارج الهرمية وفرط البرولاكتين.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! The Nordström/Farde PET window proves that between 65% and 80% lies the sweet spot of efficacy without intolerable motor toxicity.\",\"tr\":\"Doğru! Nordström ve Farde'nin PET çalışmaları, %65-80 aralığının motor toksisite olmadan klinik etkinlik sağlayan dar pencere olduğunu kanıtlar.\",\"ar\":\"صحيح! أثبتت دراسات نوردستروم وفاردي أن نطاق 65-80% هو النافذة العلاجية المثلى للفعالية دون سمية حركية مفرطة.\"}},{\"id\":\"opt_total_blockade_needed\",\"text\":{\"en\":\"Antipsychotic efficacy requires 95% to 100% D2 occupancy to completely extinguish all dopaminergic firing in the frontal cortex.\",\"tr\":\"Antipsikotik etkinlik, frontal korteksteki tüm dopaminerjik uyarıları tamamen söndürmek için %95 ila %100 D2 doluluğu gerektirir.\",\"ar\":\"تتطلب الفعالية إشغال 95% إلى 100% لـ D2 لإخماد كافة الإشارات الدوبامينية في القشرة الجبهية نهائياً.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Near-total blockade (>90%) causes severe catatonia, neuroleptic malignant syndrome, and severe parkinsonism; 65% is sufficient.\",\"tr\":\"Yanlış. %90'ın üzerindeki doluluk şiddetli parkinsonizm ve nöroleptik malign sendrom yaratır; antipsikotik etki için %65 yeterlidir.\",\"ar\":\"غير صحيح. يسبب الإشغال شبه التام (>90%) جموداً حركياً خبيثاً وشللاً رعاشياً شديداً؛ ويكفي إشغال 65% للعلاج.\"}},{\"id\":\"opt_eps_at_low_occupancy\",\"text\":{\"en\":\"Extrapyramidal symptoms emerge at 30% occupancy, meaning motor toxicity always precedes any meaningful therapeutic antipsychotic relief.\",\"tr\":\"Ekstrapiramidal semptomlar %30 dolulukta ortaya çıkar, yani motor toksisite terapötik antipsikotik etkiden her zaman önce gelir.\",\"ar\":\"تظهر الأعراض خارج الهرمية عند إشغال 30%، مما يعني أن السمية الحركية تسبق دوماً أي تحسن علاجي ملموس.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Antipsychotic efficacy occurs FIRST at 65% occupancy; EPS emerges ONLY when occupancy exceeds the higher threshold of ~80%.\",\"tr\":\"Yanlış. Önce %65'te antipsikotik etki başlar; motor toksisite ise yalnızca %80 eşiği aşıldığında ortaya çıkar.\",\"ar\":\"غير صحيح. يبدأ التحسن العلاجي أولاً عند 65%؛ ولا تظهر الأعراض الحركية إلا بتجاوز العتبة العليا البالغة 80%.\"}},{\"id\":\"opt_no_correlation_occupancy\",\"text\":{\"en\":\"PET studies demonstrated that striatal D2 receptor occupancy has zero correlation with either clinical efficacy or adverse motor outcomes.\",\"tr\":\"PET çalışmaları, striatal D2 doluluğunun ne klinik etkiyle ne de motor yan etkilerle hiçbir korelasyonu olmadığını kanıtlamıştır.\",\"ar\":\"أثبتت دراسات PET عدم وجود أي ارتباط بين إشغال مستقبلات D2 بالمخطط وبين الفعالية السريرية أو الأعراض الحركية.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. D2 receptor occupancy measured by PET is one of the most rigorously validated quantitative biomarkers in neuropsychopharmacology.\",\"tr\":\"Yanlış. PET ile ölçülen D2 reseptör doluluğu, nöropsikofarmakolojideki en sağlam doğrulanmış kantitatif biyobelirteçtir.\",\"ar\":\"غير صحيح. يُعد إشغال D2 المقاس بالتصوير المقطعي بالإصدار البوزيتروني (PET) أحد أدق المؤشرات الحيوية المثبتة دوائياً.\"}}]},\"technicalTerms\":[{\"term\":\"ekstrapiramidal semptom\",\"arContext\":\"الأعراض خارج الهرمية (EPS)\"}],\"hints\":[{\"tier\":1,\"tr\":\"Nordström ve Farde'nin PET neuroimaging çalışmalarındaki terapötik pencere sınırlarını hatırlayın.\",\"ar\":\"تذكر حدود النافذة العلاجية المثبتة بدراسات التصوير البوزيتروني (PET) لنوردستروم وفاردي.\",\"en\":\"Recall the therapeutic occupancy boundaries established by Nordström and Farde PET neuroimaging studies.\"},{\"tier\":2,\"tr\":\"Antipsikotik etkinlik için gereken asgari doluluk oranı ile motor yan etkilerin patlak verdiği üst eşiği düşünün.\",\"ar\":\"فكر في الحد الأدنى للإشغال اللازم للفعالية، والعتبة العليا التي تندلع عندها السمية الحركية خارج الهرمية.\",\"en\":\"Consider the minimum occupancy needed for clinical efficacy versus the upper threshold triggering motor EPS.\"},{\"tier\":3,\"tr\":\"Klinik etki %65 D2 doluluğunda başlar; %80 aşıldığında ise ekstrapiramidal semptomlar ve hiperprolaktinemi fırlar.\",\"ar\":\"تبدأ الفعالية العلاجية عند إشغال 65% لـ D2؛ بينما يؤدي تجاوز 80% لاندلاع حاد للأعراض خارج الهرمية وفرط البرولاكتين.\",\"en\":\"Antipsychotic efficacy begins at 65% D2 occupancy; exceeding 80% occupancy triggers motor EPS and hyperprolactinemia.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_pet_window\",\"text\":{\"en\":\"Clinical antipsychotic efficacy requires at least 65% D2 occupancy, while exceeding 80% sharply unleashes extrapyramidal symptoms and hyperprolactinemia.\",\"tr\":\"Antipsikotik etkinlik en az %65 D2 doluluğu gerektirirken, %80'in aşılması ekstrapiramidal semptomları ve hiperprolaktinemiyi hızla tetikler.\",\"ar\":\"تتطلب الفعالية المضادة للذهان إشغال 65% على الأقل لـ D2، بينما يتسبب تجاوز 80% باندلاع حاد للأعراض خارج الهرمية وفرط البرولاكتين.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! The Nordström/Farde PET window proves that between 65% and 80% lies the sweet spot of efficacy without intolerable motor toxicity.\",\"tr\":\"Doğru! Nordström ve Farde'nin PET çalışmaları, %65-80 aralığının motor toksisite olmadan klinik etkinlik sağlayan dar pencere olduğunu kanıtlar.\",\"ar\":\"صحيح! أثبتت دراسات نوردستروم وفاردي أن نطاق 65-80% هو النافذة العلاجية المثلى للفعالية دون سمية حركية مفرطة.\"}},{\"id\":\"opt_total_blockade_needed\",\"text\":{\"en\":\"Antipsychotic efficacy requires 95% to 100% D2 occupancy to completely extinguish all dopaminergic firing in the frontal cortex.\",\"tr\":\"Antipsikotik etkinlik, frontal korteksteki tüm dopaminerjik uyarıları tamamen söndürmek için %95 ila %100 D2 doluluğu gerektirir.\",\"ar\":\"تتطلب الفعالية إشغال 95% إلى 100% لـ D2 لإخماد كافة الإشارات الدوبامينية في القشرة الجبهية نهائياً.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Near-total blockade (>90%) causes severe catatonia, neuroleptic malignant syndrome, and severe parkinsonism; 65% is sufficient.\",\"tr\":\"Yanlış. %90'ın üzerindeki doluluk şiddetli parkinsonizm ve nöroleptik malign sendrom yaratır; antipsikotik etki için %65 yeterlidir.\",\"ar\":\"غير صحيح. يسبب الإشغال شبه التام (>90%) جموداً حركياً خبيثاً وشللاً رعاشياً شديداً؛ ويكفي إشغال 65% للعلاج.\"}},{\"id\":\"opt_eps_at_low_occupancy\",\"text\":{\"en\":\"Extrapyramidal symptoms emerge at 30% occupancy, meaning motor toxicity always precedes any meaningful therapeutic antipsychotic relief.\",\"tr\":\"Ekstrapiramidal semptomlar %30 dolulukta ortaya çıkar, yani motor toksisite terapötik antipsikotik etkiden her zaman önce gelir.\",\"ar\":\"تظهر الأعراض خارج الهرمية عند إشغال 30%، مما يعني أن السمية الحركية تسبق دوماً أي تحسن علاجي ملموس.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Antipsychotic efficacy occurs FIRST at 65% occupancy; EPS emerges ONLY when occupancy exceeds the higher threshold of ~80%.\",\"tr\":\"Yanlış. Önce %65'te antipsikotik etki başlar; motor toksisite ise yalnızca %80 eşiği aşıldığında ortaya çıkar.\",\"ar\":\"غير صحيح. يبدأ التحسن العلاجي أولاً عند 65%؛ ولا تظهر الأعراض الحركية إلا بتجاوز العتبة العليا البالغة 80%.\"}},{\"id\":\"opt_no_correlation_occupancy\",\"text\":{\"en\":\"PET studies demonstrated that striatal D2 receptor occupancy has zero correlation with either clinical efficacy or adverse motor outcomes.\",\"tr\":\"PET çalışmaları, striatal D2 doluluğunun ne klinik etkiyle ne de motor yan etkilerle hiçbir korelasyonu olmadığını kanıtlamıştır.\",\"ar\":\"أثبتت دراسات PET عدم وجود أي ارتباط بين إشغال مستقبلات D2 بالمخطط وبين الفعالية السريرية أو الأعراض الحركية.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. D2 receptor occupancy measured by PET is one of the most rigorously validated quantitative biomarkers in neuropsychopharmacology.\",\"tr\":\"Yanlış. PET ile ölçülen D2 reseptör doluluğu, nöropsikofarmakolojideki en sağlam doğrulanmış kantitatif biyobelirteçtir.\",\"ar\":\"غير صحيح. يُعد إشغال D2 المقاس بالتصوير المقطعي بالإصدار البوزيتروني (PET) أحد أدق المؤشرات الحيوية المثبتة دوائياً.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":19}]},{\"id\":\"pharm-mod6-les2-step-04\",\"stage\":\"visual_explanation\",\"stageIndex\":4,\"title\":{\"tr\":\"Dört Dopaminerjik Yolak Haritası\",\"ar\":\"خارطة المسارات الدوبامينية الأربعة\",\"en\":\"Map of the Four Central Dopamine Pathways\"},\"prompt\":{\"en\":\"Picture the striatal seesaw: dopamine normally brakes acetylcholine release. When haloperidol cuts dopamine, acetylcholine skyrockets. What emergency drug restores balance against dystonia?\",\"tr\":\"Striatal tahterevalliyi hayal edin: dopamin normalde asetilkolini frenler. Haloperidol dopamini kesince asetilkolin fırlar. Distoniyi durdurmak için hangi acil ilaç verilir?\",\"ar\":\"تخيل أرجوحة المخطط: يكبح الدوبامين الأسيتيل كولين طبيعياً. عند حظر الدوبامين بالهالوبيريدول، يشتعل الأسيتيل كولين. ما الدواء الإسعافي الذي يعيد التوازن؟\"},\"predictThenReveal\":false,\"config\":{\"options\":[{\"id\":\"opt_anticholinergic_countermeasure\",\"text\":{\"en\":\"Centrally acting muscarinic antagonists like biperiden or benztropine block M1 receptors, lowering cholinergic tone back into equilibrium with deficient dopamine.\",\"tr\":\"Biperiden veya benztropin gibi santral etkili muskarinik antagonistler M1 reseptörlerini bloke ederek kolinerjik tonusu düşürür ve dengeyi kurar.\",\"ar\":\"حاصرات المسكارين المركزية مثل البيبيريدين أو البنزتروبين تحظر مستقبلات M1، خافضة التوتر الكوليني لإعادته للتوازن مع الدوبامين المنخفض.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Anticholinergics dampen the relative cholinergic excess caused by D2 blockade, rapidly aborting acute dystonic muscle spasms.\",\"tr\":\"Doğru! Antikolinerjikler, D2 blokajının yarattığı göreceli asetilkolin fazlalığını M1 üzerinden söndürerek distoniyi hızla çözer.\",\"ar\":\"صحيح! تخمد مضادات الكولين فرط الأسيتيل كولين النسبي الناجم عن حظر D2، موقفة تشنجات خلل التوتر الحاد بسرعة.\"}},{\"id\":\"opt_acetylcholinesterase_inhibitor\",\"text\":{\"en\":\"Cholinesterase inhibitors like physostigmine or pyridostigmine to boost acetylcholine further and overpower haloperidol at striatal synapses.\",\"tr\":\"Haloperidolü alt etmek için asetilkolini daha da artıracak fizostigmin veya piridostigmin gibi kolinesteraz inhibitörleri verilmelidir.\",\"ar\":\"مثبطات الكولينستراز مثل فيزوستيغمين لزيادة الأسيتيل كولين والتغلب على الهالوبيريدول في المشابك العصبية.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Dystonia is caused by EXCESS acetylcholine. Adding a cholinesterase inhibitor would drastically worsen the muscle spasms.\",\"tr\":\"Yanlış. Distoni zaten AŞIRI asetilkolinden kaynaklanır; kolinesteraz inhibitörü vermek kas spazmlarını ölümcül seviyeye taşır.\",\"ar\":\"غير صحيح. ينجم خلل التوتر عن فرط الأسيتيل كولين؛ وإعطاء مثبط كولينستراز سيفاقم التشنجات العضلية بشكل كارثي.\"}},{\"id\":\"opt_full_dopamine_agonist\",\"text\":{\"en\":\"High-dose levodopa/carbidopa or bromocriptine to stimulate mesolimbic dopamine receptors and displace haloperidol from cortical regions.\",\"tr\":\"Mezolimbik dopamin reseptörlerini uyarmak ve haloperidolü korteksten sökmek için yüksek doz levodopa veya bromokriptin verilmelidir.\",\"ar\":\"جرعات عالية من ليفودوبا أو بروموكريبتين لتحفيز مستقبلات الدوبامين الميزولمبية وإزاحة الهالوبيريدول من القشرة.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Full dopamine agonists can trigger severe psychotic relapse; emergency treatment of acute dystonia relies on anticholinergics.\",\"tr\":\"Yanlış. Tam dopamin agonistleri hastayı anında akut psikotik alevlenmeye sokar; distoninin acil tedavisi antikolinerjiktir.\",\"ar\":\"غير صحيح. تفجر ناهضات الدوبامين انتكاسة ذهانية حادة؛ ويعتمد العلاج الإسعافي لخلل التوتر على مضادات الكولين حصراً.\"}},{\"id\":\"opt_neuromuscular_blockade\",\"text\":{\"en\":\"Intravenous succinylcholine to permanently block striatal cholinergic interneurons without affecting peripheral muscle tone.\",\"tr\":\"Periferik kas tonusunu etkilemeden striatal kolinerjik internöronları kalıcı bloke etmek için intravenöz süksinilkolin verilmelidir.\",\"ar\":\"سكسينيل كولين وريدي لحظر العصبونات البينية الكولينية في المخطط بشكل دائم دون التأثير على التوتر العضلي المحيطي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Succinylcholine is a peripheral depolarizing paralytic that causes apnea; it does not cross the BBB to treat central dystonia.\",\"tr\":\"Yanlış. Süksinilkolin kan-beyin bariyerini geçemez; solunumu felç eden periferik bir paralitiktir ve distonide yeri yoktur.\",\"ar\":\"غير صحيح. السكسينيل كولين مشل عضلي محيطي يسبب توقف التنفس ولا يعبر الدماغ لعلاج خلل التوتر المركزي.\"}}]},\"technicalTerms\":[{\"term\":\"nigrostriatal yolak\",\"arContext\":\"المسار الأسود المخطط\"}],\"hints\":[{\"tier\":1,\"tr\":\"Dopamin eksikliğinde striatumda yükselen aşırı asetilkolin tonusunu nasıl bastırabilirsiniz?\",\"ar\":\"كيف يمكنك إخماد التوتر الكوليني المفرط في المخطط عند هبوط إشارات الدوبامين؟\",\"en\":\"How can you pharmacologically dampen the excessive striatal cholinergic tone caused by dopamine deficit?\"},{\"tier\":2,\"tr\":\"Santral etkili bir antimuskarinik (M1 blokörü) asetilkolinin kas spazmı yaptıran etkisini bloke eder.\",\"ar\":\"حاصرات المسكارين المركزية (حاصرات M1) تعطل تأثير الأسيتيل كولين المحرض للتشنج العضلي.\",\"en\":\"A centrally acting antimuscarinic (M1 antagonist) blocks acetylcholine's ability to drive muscle spasms.\"},{\"tier\":3,\"tr\":\"Biperiden veya benztropin M1 reseptörlerini bloke ederek dopamin-asetilkolin dengesini hızla kurar ve distoniyi çözer.\",\"ar\":\"يحظر البيبيريدين أو البنزتروبين مستقبلات M1، معيداً توازن الدوبامين والأسيتيل كولين ليحل التشنج فوراً.\",\"en\":\"Biperiden or benztropine blocks M1 receptors, promptly restoring the dopamine-acetylcholine balance to abort dystonia.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_anticholinergic_countermeasure\",\"text\":{\"en\":\"Centrally acting muscarinic antagonists like biperiden or benztropine block M1 receptors, lowering cholinergic tone back into equilibrium with deficient dopamine.\",\"tr\":\"Biperiden veya benztropin gibi santral etkili muskarinik antagonistler M1 reseptörlerini bloke ederek kolinerjik tonusu düşürür ve dengeyi kurar.\",\"ar\":\"حاصرات المسكارين المركزية مثل البيبيريدين أو البنزتروبين تحظر مستقبلات M1، خافضة التوتر الكوليني لإعادته للتوازن مع الدوبامين المنخفض.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Anticholinergics dampen the relative cholinergic excess caused by D2 blockade, rapidly aborting acute dystonic muscle spasms.\",\"tr\":\"Doğru! Antikolinerjikler, D2 blokajının yarattığı göreceli asetilkolin fazlalığını M1 üzerinden söndürerek distoniyi hızla çözer.\",\"ar\":\"صحيح! تخمد مضادات الكولين فرط الأسيتيل كولين النسبي الناجم عن حظر D2، موقفة تشنجات خلل التوتر الحاد بسرعة.\"}},{\"id\":\"opt_acetylcholinesterase_inhibitor\",\"text\":{\"en\":\"Cholinesterase inhibitors like physostigmine or pyridostigmine to boost acetylcholine further and overpower haloperidol at striatal synapses.\",\"tr\":\"Haloperidolü alt etmek için asetilkolini daha da artıracak fizostigmin veya piridostigmin gibi kolinesteraz inhibitörleri verilmelidir.\",\"ar\":\"مثبطات الكولينستراز مثل فيزوستيغمين لزيادة الأسيتيل كولين والتغلب على الهالوبيريدول في المشابك العصبية.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Dystonia is caused by EXCESS acetylcholine. Adding a cholinesterase inhibitor would drastically worsen the muscle spasms.\",\"tr\":\"Yanlış. Distoni zaten AŞIRI asetilkolinden kaynaklanır; kolinesteraz inhibitörü vermek kas spazmlarını ölümcül seviyeye taşır.\",\"ar\":\"غير صحيح. ينجم خلل التوتر عن فرط الأسيتيل كولين؛ وإعطاء مثبط كولينستراز سيفاقم التشنجات العضلية بشكل كارثي.\"}},{\"id\":\"opt_full_dopamine_agonist\",\"text\":{\"en\":\"High-dose levodopa/carbidopa or bromocriptine to stimulate mesolimbic dopamine receptors and displace haloperidol from cortical regions.\",\"tr\":\"Mezolimbik dopamin reseptörlerini uyarmak ve haloperidolü korteksten sökmek için yüksek doz levodopa veya bromokriptin verilmelidir.\",\"ar\":\"جرعات عالية من ليفودوبا أو بروموكريبتين لتحفيز مستقبلات الدوبامين الميزولمبية وإزاحة الهالوبيريدول من القشرة.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Full dopamine agonists can trigger severe psychotic relapse; emergency treatment of acute dystonia relies on anticholinergics.\",\"tr\":\"Yanlış. Tam dopamin agonistleri hastayı anında akut psikotik alevlenmeye sokar; distoninin acil tedavisi antikolinerjiktir.\",\"ar\":\"غير صحيح. تفجر ناهضات الدوبامين انتكاسة ذهانية حادة؛ ويعتمد العلاج الإسعافي لخلل التوتر على مضادات الكولين حصراً.\"}},{\"id\":\"opt_neuromuscular_blockade\",\"text\":{\"en\":\"Intravenous succinylcholine to permanently block striatal cholinergic interneurons without affecting peripheral muscle tone.\",\"tr\":\"Periferik kas tonusunu etkilemeden striatal kolinerjik internöronları kalıcı bloke etmek için intravenöz süksinilkolin verilmelidir.\",\"ar\":\"سكسينيل كولين وريدي لحظر العصبونات البينية الكولينية في المخطط بشكل دائم دون التأثير على التوتر العضلي المحيطي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Succinylcholine is a peripheral depolarizing paralytic that causes apnea; it does not cross the BBB to treat central dystonia.\",\"tr\":\"Yanlış. Süksinilkolin kan-beyin bariyerini geçemez; solunumu felç eden periferik bir paralitiktir ve distonide yeri yoktur.\",\"ar\":\"غير صحيح. السكسينيل كولين مشل عضلي محيطي يسبب توقف التنفس ولا يعبر الدماغ لعلاج خلل التوتر المركزي.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":20}]},{\"id\":\"pharm-mod6-les2-step-05\",\"stage\":\"interactive_artifact\",\"stageIndex\":5,\"title\":{\"tr\":\"İnteraktif Atölye: Receptor-Ligand Matcher (D2/5-HT2A)\",\"ar\":\"ورشة تفاعلية: مطابق مستقبلات D2 و 5-HT2A\",\"en\":\"Interactive Workshop: Receptor Matcher (D2 / 5-HT2A)\"},\"prompt\":{\"en\":\"Match haloperidol's functional groups with complementary amino acid residues inside the D2 receptor pocket to uncover high-affinity blockade architecture.\",\"tr\":\"Haloperidolün gruplarını D2 cebindeki amino asitlerle eşleştirerek yüksek afiniteli blokajın moleküler mimarisini çözün.\",\"ar\":\"طابق مجموعات الهالوبيريدول الوظيفية مع الأحماض الأمينية في جيب D2 لكشف معمارية الارتباط عالي الألفة.\"},\"predictThenReveal\":false,\"config\":{\"title\":\"Haloperidol - D2 Dopamin Reseptör Kenetlenmesi\",\"prompt\":\"Haloperidolün gruplarını D2 cebindeki amino asitlerle eşleştirerek yüksek affiniteli blokajın kimyasını çözün.\",\"drugName\":\"Haloperidol\",\"receptorName\":\"D2 Dopamin Reseptörü\",\"pairs\":[{\"id\":\"pair_tert_amine\",\"drugGroup\":\"Protonlanmış Tersiyer Amin (Piperidin)\",\"correctResidueId\":\"res_asp114\",\"bondType\":\"ionic\",\"energyKcalMol\":\"-8 ila -12 kcal/mol\",\"explanation\":\"Fizyolojik pH'ta pozitif yüklü piperidin azotu, TM3 heliksindeki negatif Asp114 karboksilatı ile en kritik elektrostatik tuz köprüsünü kurar.\"},{\"id\":\"pair_fluorophenyl\",\"drugGroup\":\"p-Fluorofenil Halkası (Bütirofenon)\",\"correctResidueId\":\"res_val115_trp386\",\"bondType\":\"van_der_waals\",\"energyKcalMol\":\"-3 ila -5 kcal/mol\",\"explanation\":\"Lipofilik p-fluorofenil ucu, TM3/TM6 helikslerindeki Val115 ve Trp386 kalıntılarının oluşturduğu derin hidrofobik cebe oturur.\"},{\"id\":\"pair_chlorophenyl\",\"drugGroup\":\"4-(p-Klorofenil) Aromatik Halkası\",\"correctResidueId\":\"res_phe390\",\"bondType\":\"pi_pi\",\"energyKcalMol\":\"-4 ila -6 kcal/mol\",\"explanation\":\"Klorlu benzen halkası, TM6'daki Phe390 aromatik halkasıyla paralel pi-pi istiflenme yaparak bağlanmayı sıkılaştırır.\"},{\"id\":\"pair_hydroxyl\",\"drugGroup\":\"4-Hidroksil Grubu (-OH)\",\"correctResidueId\":\"res_ser193\",\"bondType\":\"h_bond\",\"energyKcalMol\":\"-2 ila -4 kcal/mol\",\"explanation\":\"Piperidin C4 pozisyonundaki hidroksil grubu, TM5 heliksindeki Ser193 kalıntısıyla yönlendirici hidrojen bağı oluşturur.\"}],\"residues\":[{\"id\":\"res_asp114\",\"residueName\":\"Asp114 (TM3)\",\"description\":\"Negatif yüklü karboksilat kalıntısı (anyonik kenetlenme merkezi)\"},{\"id\":\"res_val115_trp386\",\"residueName\":\"Val115 / Trp386 (TM3/TM6)\",\"description\":\"Derin apolar hidrofobik cep kalıntıları\"},{\"id\":\"res_phe390\",\"residueName\":\"Phe390 (TM6)\",\"description\":\"Aromatik benzen halkalı fenilalanin kalıntısı\"},{\"id\":\"res_ser193\",\"residueName\":\"Ser193 (TM5)\",\"description\":\"Polar hidrojen bağı verici ve alıcı serin kalıntısı\"},{\"id\":\"res_glu95\",\"residueName\":\"Glu95 (TM2)\",\"description\":\"Ekstraselüler yüzey asidik kalıntısı (cep dışı tuzak kalıntı)\"}],\"source\":{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":22}},\"technicalTerms\":[{\"term\":\"etki mekanizması\",\"arContext\":\"آلية التأثير الدوائي\"},{\"term\":\"reseptör\",\"arContext\":\"المستقبِل الحيوي\"}],\"hints\":[{\"tier\":1,\"tr\":\"Haloperidolün fonksiyonel gruplarını D2 reseptör cebindeki komplementer amino asitlerle eşleştirin.\",\"ar\":\"طابق المجموعات الوظيفية للهالوبيريدول مع الأحماض الأمينية المكملة في جيب مستقبل D2.\",\"en\":\"Match haloperidol's functional moieties with complementary amino acids inside the D2 binding pocket.\"},{\"tier\":2,\"tr\":\"Tersiyer amin TM3'teki Asp114 ile tuz köprüsü kurar; aromatik halkalar ise Trp386 ve Phe390 ile etkileşir.\",\"ar\":\"يشكل الأمين الثالثي جسراً ملحياً مع Asp114 في TM3؛ وتتآثر الحلقات العطرية مع Trp386 و Phe390.\",\"en\":\"The tertiary amine forms an ionic salt bridge with Asp114 (TM3); aromatic rings interact with Trp386 and Phe390.\"},{\"tier\":3,\"tr\":\"4-hidroksil grubu Ser193 (TM5) ile hidrojen bağı yaparak yüksek afiniteli antagonist kenetlenmesini tamamlar.\",\"ar\":\"تشكل مجموعة 4-هيدروكسيل رابطة هيدروجينية مع Ser193 في TM5 متممة الالتحام عالي الألفة.\",\"en\":\"The 4-hydroxyl group hydrogen bonds with Ser193 (TM5), locking the high-affinity antagonistic conformation.\"}],\"widgetType\":\"ReceptorLigandMatcher\",\"widget\":{\"type\":\"ReceptorLigandMatcher\",\"config\":{\"title\":\"Haloperidol - D2 Dopamin Reseptör Kenetlenmesi\",\"prompt\":\"Haloperidolün gruplarını D2 cebindeki amino asitlerle eşleştirerek yüksek affiniteli blokajın kimyasını çözün.\",\"drugName\":\"Haloperidol\",\"receptorName\":\"D2 Dopamin Reseptörü\",\"pairs\":[{\"id\":\"pair_tert_amine\",\"drugGroup\":\"Protonlanmış Tersiyer Amin (Piperidin)\",\"correctResidueId\":\"res_asp114\",\"bondType\":\"ionic\",\"energyKcalMol\":\"-8 ila -12 kcal/mol\",\"explanation\":\"Fizyolojik pH'ta pozitif yüklü piperidin azotu, TM3 heliksindeki negatif Asp114 karboksilatı ile en kritik elektrostatik tuz köprüsünü kurar.\"},{\"id\":\"pair_fluorophenyl\",\"drugGroup\":\"p-Fluorofenil Halkası (Bütirofenon)\",\"correctResidueId\":\"res_val115_trp386\",\"bondType\":\"van_der_waals\",\"energyKcalMol\":\"-3 ila -5 kcal/mol\",\"explanation\":\"Lipofilik p-fluorofenil ucu, TM3/TM6 helikslerindeki Val115 ve Trp386 kalıntılarının oluşturduğu derin hidrofobik cebe oturur.\"},{\"id\":\"pair_chlorophenyl\",\"drugGroup\":\"4-(p-Klorofenil) Aromatik Halkası\",\"correctResidueId\":\"res_phe390\",\"bondType\":\"pi_pi\",\"energyKcalMol\":\"-4 ila -6 kcal/mol\",\"explanation\":\"Klorlu benzen halkası, TM6'daki Phe390 aromatik halkasıyla paralel pi-pi istiflenme yaparak bağlanmayı sıkılaştırır.\"},{\"id\":\"pair_hydroxyl\",\"drugGroup\":\"4-Hidroksil Grubu (-OH)\",\"correctResidueId\":\"res_ser193\",\"bondType\":\"h_bond\",\"energyKcalMol\":\"-2 ila -4 kcal/mol\",\"explanation\":\"Piperidin C4 pozisyonundaki hidroksil grubu, TM5 heliksindeki Ser193 kalıntısıyla yönlendirici hidrojen bağı oluşturur.\"}],\"residues\":[{\"id\":\"res_asp114\",\"residueName\":\"Asp114 (TM3)\",\"description\":\"Negatif yüklü karboksilat kalıntısı (anyonik kenetlenme merkezi)\"},{\"id\":\"res_val115_trp386\",\"residueName\":\"Val115 / Trp386 (TM3/TM6)\",\"description\":\"Derin apolar hidrofobik cep kalıntıları\"},{\"id\":\"res_phe390\",\"residueName\":\"Phe390 (TM6)\",\"description\":\"Aromatik benzen halkalı fenilalanin kalıntısı\"},{\"id\":\"res_ser193\",\"residueName\":\"Ser193 (TM5)\",\"description\":\"Polar hidrojen bağı verici ve alıcı serin kalıntısı\"},{\"id\":\"res_glu95\",\"residueName\":\"Glu95 (TM2)\",\"description\":\"Ekstraselüler yüzey asidik kalıntısı (cep dışı tuzak kalıntı)\"}],\"source\":{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":22}}},\"conceptCheck\":{\"options\":[]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":21}]},{\"id\":\"pharm-mod6-les2-step-06\",\"stage\":\"guided_discovery\",\"stageIndex\":6,\"title\":{\"tr\":\"Rehberli Keşif: Atipiklerin 5-HT2A Kurtarma Mekanizması\",\"ar\":\"استكشاف موجه: آلية إنقاذ 5-HT2A في مضادات الذهان غير النمطية\",\"en\":\"Guided Discovery: The 5-HT2A Rescue Mechanism\"},\"prompt\":{\"en\":\"Why do second-generation atypical antipsychotics (SGAs) cause substantially fewer extrapyramidal motor symptoms than typicals? What role does 5-HT2A receptor antagonism play in the striatum?\",\"tr\":\"İkinci kuşak atipik antipsikotikler tipiklere göre neden çok daha az motor yan etki (EPS) yapar? 5-HT2A reseptör antagonizması striatumda nasıl bir rol oynar?\",\"ar\":\"لماذا تسبب مضادات الذهان اللانمطية أعراضاً خارج هرمية أقل بكثير مقارنة بالنمطية؟ ما الدور الذي يلعبه حظر مستقبلات 5-HT2A في المخطط؟\"},\"predictThenReveal\":true,\"config\":{\"revealedOutcome\":\"5-HT2A antagonizması motor yolda dopamini kurtarır; atipik antipsikotiklerin sırrı budur.\",\"options\":[{\"id\":\"opt_5ht2a_disinhibition\",\"text\":{\"en\":\"Serotonin 5-HT2A receptors normally brake dopamine release; blocking them disinhibits striatal dopamine terminals, competing with D2 blockade to stay below 80% occupancy.\",\"tr\":\"5-HT2A normalde dopamin salınımını frenler; blokajı striatumda dopamin salınımını serbest bırakır ve D2 doluluğunu %80'in altında tutar.\",\"ar\":\"تكبح مستقبلات 5-HT2A إفراز الدوبامين طبيعياً؛ وحظرها يحرر إفراز الدوبامين بالمخطط ليزاحم حظر D2 ويبقيه تحت عتبة 80%.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! 5-HT2A antagonism disinhibits dopamine release in the nigrostriatal pathway, allowing dopamine to compete and protect against motor EPS.\",\"tr\":\"Doğru! 5-HT2A blokajı striatal dopamin salınımını artırır; açığa çıkan dopamin D2'de yarışarak doluluğu %80 altında tutar ve motor EPS'yi önler.\",\"ar\":\"صحيح! يحرر حظر 5-HT2A إفراز الدوبامين في المسار الحركي، ليتنافس محلياً مع الدواء ويبقي إشغال D2 دون 80% الحامية من EPS.\"}},{\"id\":\"opt_direct_d2_synthesis\",\"text\":{\"en\":\"5-HT2A antagonism directly mutates the genetic promoter of D2 receptors, transforming them into Gs-coupled excitatory dopamine receptors.\",\"tr\":\"5-HT2A antagonizması D2 reseptörlerinin genetik promotorunu mutasyona uğratarak onları Gs kenetli uyarıcı reseptörlere dönüştürür.\",\"ar\":\"يحدث حظر 5-HT2A طفرة جينية في محفز مستقبلات D2 محولاً إياها لمستقبلات منشطة مقترنة بـ Gs.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Pharmacological antagonists do not mutate genetic promoters or alter GPCR coupling identities.\",\"tr\":\"Yanlış. Farmakolojik antagonistler genetik promotor mutasyonu yapmaz veya G-proteini tipini değiştiremez.\",\"ar\":\"غير صحيح. لا تحدث المناهضات الدوائية طفرات جينية ولا تغير هوية البروتين G المقترن بالمستقبل.\"}},{\"id\":\"opt_cyp_induction_clearance\",\"text\":{\"en\":\"5-HT2A antagonism massively induces hepatic CYP3A4, completely clearing the antipsychotic from the brain within two minutes of administration.\",\"tr\":\"5-HT2A antagonizması karaciğer CYP3A4 enzimini aşırı uyararak ilacın iki dakika içinde beyinden tamamen temizlenmesini sağlar.\",\"ar\":\"يحفز حظر 5-HT2A إنزيم CYP3A4 الكبدي بشدة مما يطرد الدواء من الدماغ خلال دقيقتين من تناوله.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Antipsychotics remain in brain tissue for hours; motor sparing is mediated by local neurochemical striatal dopamine release.\",\"tr\":\"Yanlış. Antipsikotikler beyinde saatlerce kalır; motor koruma yerel striatal dopamin salınımının artmasıyla sağlanır.\",\"ar\":\"غير صحيح. تبقى مضادات الذهان في الدماغ لساعات؛ وتتحقق الحماية الحركية عبر تعزيز إفراز الدوبامين الموضعي بالمخطط.\"}},{\"id\":\"opt_peripheral_muscle_relaxant\",\"text\":{\"en\":\"5-HT2A blockers act as neuromuscular junction curare-like blockers, directly relaxing skeletal muscles independently of the central nervous system.\",\"tr\":\"5-HT2A blokörleri santral sinir sisteminden bağımsız olarak çizgili kasları gevşeten kürar benzeri periferik kas gevşeticilerdir.\",\"ar\":\"تعمل حاصرات 5-HT2A كمرخيات عضلية محيطية شبيهة بالكورار ترخي العضلات بمعزل عن الجهاز العصبي المركزي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. 5-HT2A receptors relevant to EPS mitigation operate centrally in cortical and striatal monoaminergic circuits, not peripheral muscles.\",\"tr\":\"Yanlış. 5-HT2A reseptörleri periferik kasta değil, santral korteks ve striatumdaki monoaminerjik devrelerde işlev görür.\",\"ar\":\"غير صحيح. تعمل مستقبلات 5-HT2A المسؤولة عن تخفيف EPS مركزياً في الدوائر العصبية القشرية والمخططية وليس في العضلات المحيطية.\"}}]},\"technicalTerms\":[{\"term\":\"etki mekanizması\",\"arContext\":\"آلية التأثير الدوائي\"},{\"term\":\"reseptör\",\"arContext\":\"المستقبِل الحيوي\"}],\"hints\":[{\"tier\":1,\"tr\":\"Serotonin 5-HT2A reseptörlerinin nigrostriatal dopamin terminalleri üzerindeki normal görevini hatırlayın.\",\"ar\":\"تذكر الوظيفة الفسيولوجية لمستقبلات السيروتونين 5-HT2A على نهايات الدوبامين في المسار الحركي.\",\"en\":\"Recall the normal physiological action of serotonin 5-HT2A heteroreceptors on motor dopamine terminals.\"},{\"tier\":2,\"tr\":\"5-HT2A normalde dopamin salınımını frenler; bu reseptör bloke edilirse dopamin salınımı serbest kalır.\",\"ar\":\"يكبح 5-HT2A إفراز الدوبامين فسيولوجياً؛ وحظر هذا المستقبل يحرر إفراز الدوبامين الموضعي بالمخطط.\",\"en\":\"5-HT2A normally brakes dopamine release; blocking it disinhibits local dopamine outflow in the striatum.\"},{\"tier\":3,\"tr\":\"Açığa çıkan dopamin striatal D2'de ilaçla yarışır ve doluluğu %80'in altında tutarak motor EPS'yi önler.\",\"ar\":\"يزاحم الدوبامين المحرر الدواء عند مستقبلات D2 بالمخطط، مبقياً الإشغال دون 80% ليحمي من EPS.\",\"en\":\"Released dopamine outcompetes the drug at striatal D2 receptors, keeping occupancy below 80% to spare EPS.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_5ht2a_disinhibition\",\"text\":{\"en\":\"Serotonin 5-HT2A receptors normally brake dopamine release; blocking them disinhibits striatal dopamine terminals, competing with D2 blockade to stay below 80% occupancy.\",\"tr\":\"5-HT2A normalde dopamin salınımını frenler; blokajı striatumda dopamin salınımını serbest bırakır ve D2 doluluğunu %80'in altında tutar.\",\"ar\":\"تكبح مستقبلات 5-HT2A إفراز الدوبامين طبيعياً؛ وحظرها يحرر إفراز الدوبامين بالمخطط ليزاحم حظر D2 ويبقيه تحت عتبة 80%.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! 5-HT2A antagonism disinhibits dopamine release in the nigrostriatal pathway, allowing dopamine to compete and protect against motor EPS.\",\"tr\":\"Doğru! 5-HT2A blokajı striatal dopamin salınımını artırır; açığa çıkan dopamin D2'de yarışarak doluluğu %80 altında tutar ve motor EPS'yi önler.\",\"ar\":\"صحيح! يحرر حظر 5-HT2A إفراز الدوبامين في المسار الحركي، ليتنافس محلياً مع الدواء ويبقي إشغال D2 دون 80% الحامية من EPS.\"}},{\"id\":\"opt_direct_d2_synthesis\",\"text\":{\"en\":\"5-HT2A antagonism directly mutates the genetic promoter of D2 receptors, transforming them into Gs-coupled excitatory dopamine receptors.\",\"tr\":\"5-HT2A antagonizması D2 reseptörlerinin genetik promotorunu mutasyona uğratarak onları Gs kenetli uyarıcı reseptörlere dönüştürür.\",\"ar\":\"يحدث حظر 5-HT2A طفرة جينية في محفز مستقبلات D2 محولاً إياها لمستقبلات منشطة مقترنة بـ Gs.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Pharmacological antagonists do not mutate genetic promoters or alter GPCR coupling identities.\",\"tr\":\"Yanlış. Farmakolojik antagonistler genetik promotor mutasyonu yapmaz veya G-proteini tipini değiştiremez.\",\"ar\":\"غير صحيح. لا تحدث المناهضات الدوائية طفرات جينية ولا تغير هوية البروتين G المقترن بالمستقبل.\"}},{\"id\":\"opt_cyp_induction_clearance\",\"text\":{\"en\":\"5-HT2A antagonism massively induces hepatic CYP3A4, completely clearing the antipsychotic from the brain within two minutes of administration.\",\"tr\":\"5-HT2A antagonizması karaciğer CYP3A4 enzimini aşırı uyararak ilacın iki dakika içinde beyinden tamamen temizlenmesini sağlar.\",\"ar\":\"يحفز حظر 5-HT2A إنزيم CYP3A4 الكبدي بشدة مما يطرد الدواء من الدماغ خلال دقيقتين من تناوله.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Antipsychotics remain in brain tissue for hours; motor sparing is mediated by local neurochemical striatal dopamine release.\",\"tr\":\"Yanlış. Antipsikotikler beyinde saatlerce kalır; motor koruma yerel striatal dopamin salınımının artmasıyla sağlanır.\",\"ar\":\"غير صحيح. تبقى مضادات الذهان في الدماغ لساعات؛ وتتحقق الحماية الحركية عبر تعزيز إفراز الدوبامين الموضعي بالمخطط.\"}},{\"id\":\"opt_peripheral_muscle_relaxant\",\"text\":{\"en\":\"5-HT2A blockers act as neuromuscular junction curare-like blockers, directly relaxing skeletal muscles independently of the central nervous system.\",\"tr\":\"5-HT2A blokörleri santral sinir sisteminden bağımsız olarak çizgili kasları gevşeten kürar benzeri periferik kas gevşeticilerdir.\",\"ar\":\"تعمل حاصرات 5-HT2A كمرخيات عضلية محيطية شبيهة بالكورار ترخي العضلات بمعزل عن الجهاز العصبي المركزي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. 5-HT2A receptors relevant to EPS mitigation operate centrally in cortical and striatal monoaminergic circuits, not peripheral muscles.\",\"tr\":\"Yanlış. 5-HT2A reseptörleri periferik kasta değil, santral korteks ve striatumdaki monoaminerjik devrelerde işlev görür.\",\"ar\":\"غير صحيح. تعمل مستقبلات 5-HT2A المسؤولة عن تخفيف EPS مركزياً في الدوائر العصبية القشرية والمخططية وليس في العضلات المحيطية.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":22}]},{\"id\":\"pharm-mod6-les2-step-07\",\"stage\":\"formal_explanation\",\"stageIndex\":7,\"title\":{\"tr\":\"PET Doluluk Penceresi ve Reseptör Kinetiği\",\"ar\":\"نافذة الإشغال في تصوير PET وحركية المستقبل\",\"en\":\"Formal Neuropharmacology: PET D2 Occupancy Window\"},\"prompt\":{\"en\":\"What two pharmacological properties define atypical antipsychotics: the Meltzer index and receptor dissociation kinetics (Kapur-Seeman hypothesis)?\",\"tr\":\"Atipik antipsikotikleri tanımlayan iki farmakolojik özellik nedir: Meltzer indeksi ve reseptör ayrışma kinetiği (Kapur-Seeman hipotezi)?\",\"ar\":\"ما الخاصيتان الدوائيتان اللتان تحددان مضادات الذهان اللانمطية: مؤشر ميلتزر وحركية التفكك عن المستقبل (فرضية كابور-سيمان)؟\"},\"predictThenReveal\":false,\"config\":{\"options\":[{\"id\":\"opt_atypicality_equation\",\"text\":{\"en\":\"High 5-HT2A/D2 affinity ratio (Meltzer index) and rapid D2 dissociation ('fast-off' kinetics) allowing endogenous dopamine surges to maintain physiological motor control.\",\"tr\":\"Yüksek 5-HT2A/D2 afinite oranı (Meltzer indeksi) ve endojen dopaminin fizyolojik motor iletimi sürdürmesini sağlayan hızlı D2 ayrışması ('fast-off' kinetiği).\",\"ar\":\"نسبة ألفة مرتفعة لـ 5-HT2A مقارنة بـ D2 (مؤشر ميلتزر) وتفكك سريع عن D2 (حركية fast-off) مما يتيح للدوبامين الحفاظ على التحكم الحركي.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! High 5-HT2A affinity and fast D2 dissociation allow atypicals (clozapine, quetiapine) to quell psychosis while sparing physiological motor signaling.\",\"tr\":\"Doğru! Yüksek 5-HT2A afinitesi ve D2'den hızla ayrılma (fast-off), atipiklerin psikozu çözerken motor kontrolü korumasını sağlar.\",\"ar\":\"صحيح! تتيح الألفة العالية لـ 5-HT2A والتفكك السريع عن D2 للأدوية اللانمطية خمد الذهان مع الحفاظ على الإشارات الحركية الفسيولوجية.\"}},{\"id\":\"opt_irreversible_binding\",\"text\":{\"en\":\"Irreversible covalent D2 binding paired with zero affinity for 5-HT2A receptors, ensuring permanent silencing of all dopaminergic synapses.\",\"tr\":\"D2'ye geri dönüşsüz kovalent bağlanma ve 5-HT2A'ya sıfır afinite, tüm dopaminerjik sinapsların kalıcı olarak susturulmasını sağlar.\",\"ar\":\"ارتباط تساهمي غير عكوس بمستقبلات D2 مع انعدام الألفة تجاه 5-HT2A، لضمان إسكات دائم لكافة المشابك الدوبامينية.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Irreversible binding would cause devastating, permanent extrapyramidal symptoms. Atypicals dissociate FASTER than typicals.\",\"tr\":\"Yanlış. Geri dönüşsüz bağlanma felç edici kalıcı EPS yapardı. Atipikler tipiklere göre D2'den ÇOK DAHA HIZLI ayrılırlar.\",\"ar\":\"غير صحيح. الارتباط غير العكوس يسبب شللاً رعاشياً مدمراً ودائماً؛ تتفكك اللانمطيات عن D2 بشكل أسرع بكثير من النمطية.\"}},{\"id\":\"opt_slow_off_superiority\",\"text\":{\"en\":\"Extremely slow D2 dissociation ('slow-off' kinetics with half-life of days) that outcompetes dopamine even under maximal physiological stress.\",\"tr\":\"Maksimal fizyolojik stres altında bile dopamini alt eden aşırı yavaş D2 ayrışması (günler süren 'slow-off' kinetiği).\",\"ar\":\"تفكك بطيء للغاية عن D2 (حركية slow-off بنصف عمر لأيام) يتغلب على الدوبامين حتى تحت وطأة الإجهاد الفسيولوجي الأقصى.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Slow-off kinetics (like haloperidol) produce continuous unrelenting receptor blockade and high EPS risk. Fast-off protects motor control.\",\"tr\":\"Yanlış. Haloperidol gibi yavaş ayrılan (slow-off) ilaçlar yüksek EPS yapar; motor fonksiyonları koruyan 'fast-off' (hızlı ayrışma) özelliğidir.\",\"ar\":\"غير صحيح. الحركية البطيئة (كالهالوبيريدول) تبقي المستقبل محظوراً بلا هوادة وتسبب EPS؛ بينما الحركية السريعة تحمي الحركة.\"}},{\"id\":\"opt_gastric_degradation_myth\",\"text\":{\"en\":\"Fast-off kinetics refers to rapid destruction of the drug by gastric acid, preventing high systemic bioavailability.\",\"tr\":\"Fast-off kinetiği, ilacın mide asidi tarafından hızla parçalanmasını ve yüksek biyoyararlanım oluşmamasını ifade eder.\",\"ar\":\"تشير حركية fast-off إلى التفكك السريع للدواء بواسطة حمض المعدة مما يمنع التوافر الحيوي الجهازي المرتفع.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. 'Fast-off' refers strictly to the microscopic dissociation rate constant (k-off) of the drug-receptor complex in the brain.\",\"tr\":\"Yanlış. 'Fast-off' mideyle ilgili değildir; ilacın beyindeki reseptörden mikroskobik ayrışma hız sabitini (k-off) tanımlar.\",\"ar\":\"غير صحيح. يشير fast-off حصراً إلى ثابت سرعة تفكك معقد الدواء والمستقبل (k-off) في أنسجة الدماغ.\"}}]},\"technicalTerms\":[{\"term\":\"PET doluluk penceresi\",\"arContext\":\"نافذة الإشغال في PET\"}],\"hints\":[{\"tier\":1,\"tr\":\"Meltzer oranı ve Kapur-Seeman 'fast-off' kinetik hipotezini bir arada değerlendirin.\",\"ar\":\"قيم معاً مؤشر ميلتزر وفرضية حركية التفكك السريع 'fast-off' لكابور وسيمان.\",\"en\":\"Evaluate the Meltzer affinity ratio together with the Kapur-Seeman fast-off kinetic hypothesis.\"},{\"tier\":2,\"tr\":\"Atipikler 5-HT2A'ya D2'den daha yüksek afiniteyle bağlanır ve D2 reseptöründen hızla ayrışırlar.\",\"ar\":\"ترتبط اللانمطيات بـ 5-HT2A بألفة أعلى من D2، وتتفكك عن مستقبلات D2 بسرعة فائقة مقارنة بالنمطية.\",\"en\":\"Atypicals bind 5-HT2A with higher affinity than D2 and dissociate rapidly from the D2 receptor pore.\"},{\"tier\":3,\"tr\":\"Hızlı ayrışma ('fast-off'), endojen dopamin dalgalarının fizyolojik motor sinyalleri iletmesine izin verir.\",\"ar\":\"يتيح التفكك السريع لموجات الدوبامين الطبيعية تمرير إشارات التحكم الحركي الفسيولوجية دون إعاقة.\",\"en\":\"Fast-off kinetics allows physiological pulses of endogenous dopamine to transmit essential motor signals.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_atypicality_equation\",\"text\":{\"en\":\"High 5-HT2A/D2 affinity ratio (Meltzer index) and rapid D2 dissociation ('fast-off' kinetics) allowing endogenous dopamine surges to maintain physiological motor control.\",\"tr\":\"Yüksek 5-HT2A/D2 afinite oranı (Meltzer indeksi) ve endojen dopaminin fizyolojik motor iletimi sürdürmesini sağlayan hızlı D2 ayrışması ('fast-off' kinetiği).\",\"ar\":\"نسبة ألفة مرتفعة لـ 5-HT2A مقارنة بـ D2 (مؤشر ميلتزر) وتفكك سريع عن D2 (حركية fast-off) مما يتيح للدوبامين الحفاظ على التحكم الحركي.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! High 5-HT2A affinity and fast D2 dissociation allow atypicals (clozapine, quetiapine) to quell psychosis while sparing physiological motor signaling.\",\"tr\":\"Doğru! Yüksek 5-HT2A afinitesi ve D2'den hızla ayrılma (fast-off), atipiklerin psikozu çözerken motor kontrolü korumasını sağlar.\",\"ar\":\"صحيح! تتيح الألفة العالية لـ 5-HT2A والتفكك السريع عن D2 للأدوية اللانمطية خمد الذهان مع الحفاظ على الإشارات الحركية الفسيولوجية.\"}},{\"id\":\"opt_irreversible_binding\",\"text\":{\"en\":\"Irreversible covalent D2 binding paired with zero affinity for 5-HT2A receptors, ensuring permanent silencing of all dopaminergic synapses.\",\"tr\":\"D2'ye geri dönüşsüz kovalent bağlanma ve 5-HT2A'ya sıfır afinite, tüm dopaminerjik sinapsların kalıcı olarak susturulmasını sağlar.\",\"ar\":\"ارتباط تساهمي غير عكوس بمستقبلات D2 مع انعدام الألفة تجاه 5-HT2A، لضمان إسكات دائم لكافة المشابك الدوبامينية.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Irreversible binding would cause devastating, permanent extrapyramidal symptoms. Atypicals dissociate FASTER than typicals.\",\"tr\":\"Yanlış. Geri dönüşsüz bağlanma felç edici kalıcı EPS yapardı. Atipikler tipiklere göre D2'den ÇOK DAHA HIZLI ayrılırlar.\",\"ar\":\"غير صحيح. الارتباط غير العكوس يسبب شللاً رعاشياً مدمراً ودائماً؛ تتفكك اللانمطيات عن D2 بشكل أسرع بكثير من النمطية.\"}},{\"id\":\"opt_slow_off_superiority\",\"text\":{\"en\":\"Extremely slow D2 dissociation ('slow-off' kinetics with half-life of days) that outcompetes dopamine even under maximal physiological stress.\",\"tr\":\"Maksimal fizyolojik stres altında bile dopamini alt eden aşırı yavaş D2 ayrışması (günler süren 'slow-off' kinetiği).\",\"ar\":\"تفكك بطيء للغاية عن D2 (حركية slow-off بنصف عمر لأيام) يتغلب على الدوبامين حتى تحت وطأة الإجهاد الفسيولوجي الأقصى.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Slow-off kinetics (like haloperidol) produce continuous unrelenting receptor blockade and high EPS risk. Fast-off protects motor control.\",\"tr\":\"Yanlış. Haloperidol gibi yavaş ayrılan (slow-off) ilaçlar yüksek EPS yapar; motor fonksiyonları koruyan 'fast-off' (hızlı ayrışma) özelliğidir.\",\"ar\":\"غير صحيح. الحركية البطيئة (كالهالوبيريدول) تبقي المستقبل محظوراً بلا هوادة وتسبب EPS؛ بينما الحركية السريعة تحمي الحركة.\"}},{\"id\":\"opt_gastric_degradation_myth\",\"text\":{\"en\":\"Fast-off kinetics refers to rapid destruction of the drug by gastric acid, preventing high systemic bioavailability.\",\"tr\":\"Fast-off kinetiği, ilacın mide asidi tarafından hızla parçalanmasını ve yüksek biyoyararlanım oluşmamasını ifade eder.\",\"ar\":\"تشير حركية fast-off إلى التفكك السريع للدواء بواسطة حمض المعدة مما يمنع التوافر الحيوي الجهازي المرتفع.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. 'Fast-off' refers strictly to the microscopic dissociation rate constant (k-off) of the drug-receptor complex in the brain.\",\"tr\":\"Yanlış. 'Fast-off' mideyle ilgili değildir; ilacın beyindeki reseptörden mikroskobik ayrışma hız sabitini (k-off) tanımlar.\",\"ar\":\"غير صحيح. يشير fast-off حصراً إلى ثابت سرعة تفكك معقد الدواء والمستقبل (k-off) في أنسجة الدماغ.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":23}]},{\"id\":\"pharm-mod6-les2-step-08\",\"stage\":\"concept_check\",\"stageIndex\":8,\"title\":{\"tr\":\"Kavram Denetimi: Tuberoinfundibuler Yol ve Prolaktin\",\"ar\":\"فحص المفهوم: المسار القمعي وهرمون البرولاكتين\",\"en\":\"Concept Check: Tuberoinfundibular Pathway & Prolactin\"},\"prompt\":{\"en\":\"A patient on long-term haloperidol develops involuntary lip-smacking and choreoathetoid tongue movements (tardive dyskinesia). Why is administering biperiden (an anticholinergic) clinically catastrophic?\",\"tr\":\"Uzun süredir haloperidol kullanan hastada istemsiz dudak şapırdatma ve koreoatetoit dil hareketleri (tardif diskinezi) başlıyor. Biperiden (antikolinerjik) vermek neden klinik bir felakettir?\",\"ar\":\"مريض يتناول الهالوبيريدول مزمناً يصاب بحركات لا إرادية للشفتين واللسان (عسر الحركة المتأخر). لماذا يُعد إعطاء البيبيريدين (مضاد كولين) كارثة سريرية؟\"},\"predictThenReveal\":true,\"config\":{\"revealedOutcome\":\"Tuberoinfundibuler blokaj hiperprolaktinemi yan etkisinden sorumludur.\",\"options\":[{\"id\":\"opt_td_supersensitivity_worsened\",\"text\":{\"en\":\"Tardive dyskinesia results from up-regulated, supersensitive D2 receptors; suppressing opposing cholinergic tone exacerbates dopamine dominance and worsens the chorea.\",\"tr\":\"Tardif diskinezi D2 reseptör süpersensitivitesinden kaynaklanır; karşıt kolinerjik tonusun kırılması dopamin hakimiyetini ve koreyi daha da azdırır.\",\"ar\":\"ينجم عسر الحركة المتأخر عن فرط حساسية مستقبلات D2 المتكاثرة؛ وتثبيط النغمة الكولينية المعاكسة يفاقم هيمنة الدوبامين ويزيد الحركات الرقصية سوءاً.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Anticholinergics treat acute dystonia, but worsen tardive dyskinesia! Treatment requires switching to clozapine or adding a VMAT2 inhibitor.\",\"tr\":\"Doğru! Antikolinerjikler akut distoniyi çözer ama tardif diskineziyi KÖTÜLEŞTİRİR! Tedavide klozapine geçilmeli veya VMAT2 inhibitörü verilmelidir.\",\"ar\":\"صحيح! تعالج مضادات الكولين خلل التوتر الحاد لكنها تفاقم عسر الحركة المتأخر! يتطلب العلاج التحويل إلى كلوزابين أو إضافة مثبط VMAT2.\"}},{\"id\":\"opt_biperiden_cures_td\",\"text\":{\"en\":\"Biperiden instantly cures tardive dyskinesia because the disorder is a peripheral acetylcholine receptor hypersensitivity at skeletal motor endplates.\",\"tr\":\"Biperiden tardif diskineziyi anında iyileştirir çünkü bozukluk çizgili kas son plaklarındaki periferik asetilkolin aşırı duyarlılığıdır.\",\"ar\":\"يشفي البيبيريدين عسر الحركة المتأخر فوراً لأن الاضطراب ناشئ عن فرط حساسية مستقبلات الأسيتيل كولين المحيطية في اللوحة المحركة.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. TD is a central striatal neuroplastic disorder of dopamine receptor supersensitivity, and anticholinergics severely exacerbate it.\",\"tr\":\"Yanlış. Tardif diskinezi periferik değil santral bir dopamin aşırı duyarlılığıdır ve antikolinerjikler bu tabloyu çok daha ağırlaştırır.\",\"ar\":\"غير صحيح. عسر الحركة المتأخر اضطراب مركزي ناجم عن فرط حساسية مستقبلات الدوبامين، ومضادات الكولين تزيده اشتعالاً.\"}},{\"id\":\"opt_double_haloperidol_dose\",\"text\":{\"en\":\"The haloperidol dose should be immediately tripled to irreversibly downregulate and destroy all supersensitive D2 receptors permanently.\",\"tr\":\"Tüm süpersensitif D2 reseptörlerini kalıcı olarak yok etmek ve desensitize etmek için haloperidol dozu derhal üç katına çıkarılmalıdır.\",\"ar\":\"يجب مضاعفة جرعة الهالوبيريدول 3 أضعاف فوراً لإزالة حساسية وتدمير كافة مستقبلات D2 مفرطة الحساسية نهائياً.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Increasing antipsychotic dose temporarily masks symptoms by blocking supersensitive receptors, but ultimately deepens and cements the pathology.\",\"tr\":\"Yanlış. Doz artırmak semptomları geçici maskeler ancak süpersensitiviteyi daha da derinleştirip patolojiyi kalıcılaştırır.\",\"ar\":\"غير صحيح. زيادة الجرعة تموه الأعراض مؤقتاً لكنها تعمق فرط الحساسية وترسخ التلف العصبي بشكل لا رجعة فيه.\"}},{\"id\":\"opt_irreversible_substantia_nigra_death\",\"text\":{\"en\":\"Tardive dyskinesia signifies complete coagulative necrosis of the substantia nigra, requiring emergent neurosurgical deep brain stimulation.\",\"tr\":\"Tardif diskinezi substantia nigra'nın koagülasyon nekrozuna uğradığını gösterir ve acil derin beyin stimülasyonu cerrahisi gerektirir.\",\"ar\":\"يدل عسر الحركة المتأخر على نخر تخثري كامل في المادة السوداء، مما يتطلب جراحة تحفيز عميق للدماغ بشكل إسعافي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. TD is not coagulative necrosis of the substantia nigra; it is receptor upregulation and maladaptive neuroplasticity in striatal synapses.\",\"tr\":\"Yanlış. Tardif diskinezi nekroz değildir; striatal postsinaptik reseptörlerin aşırı duyarlılaşması ve adaptif plastisite bozukluğudur.\",\"ar\":\"غير صحيح. ليس عسر الحركة المتأخر نخراً في المادة السوداء؛ بل هو تكاثر وفرط حساسية تكيفية لمستقبلات الدوبامين المشبكية.\"}}]},\"technicalTerms\":[{\"term\":\"etki mekanizması\",\"arContext\":\"آلية التأثير الدوائي\"},{\"term\":\"reseptör\",\"arContext\":\"المستقبِل الحيوي\"}],\"hints\":[{\"tier\":1,\"tr\":\"Uzun süre D2 blokajına maruz kalan postsinaptik reseptörlerin nasıl bir adaptasyon geliştirdiğini düşünün.\",\"ar\":\"فكر في التكيف العصبي الذي تطوره مستقبلات D2 البعد مشبكية بعد حظرها المزمن لسنوات.\",\"en\":\"Consider the compensatory adaptations developed by postsynaptic D2 receptors after years of chronic blockade.\"},{\"tier\":2,\"tr\":\"D2 reseptörleri aşırı çoğalır ve süpersensitif hale gelir; bu durumda dopamin sinyali aşırı uyarılabilir.\",\"ar\":\"تتكاثر مستقبلات D2 وتصبح مفرطة الحساسية؛ مما يجعل أي إشارة دوبامينية تنفجر كحركات رقصية.\",\"en\":\"D2 receptors upregulate and become supersensitive; motor circuits become exquisitely hypersensitive to dopamine.\"},{\"tier\":3,\"tr\":\"Antikolinerjik verilirse dopamini dengeleyen kolinerjik fren kalkar ve tardif diskinezi kore hareketleri azgınlaşır.\",\"ar\":\"إعطاء مضاد كولين يزيل الكبح الكوليني المعاكس للدوبامين، مما يؤدي لاشتعال عسر الحركة المتأخر وتفاقمه.\",\"en\":\"Administering anticholinergics eliminates the opposing cholinergic brake, disastrously worsening tardive chorea.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_td_supersensitivity_worsened\",\"text\":{\"en\":\"Tardive dyskinesia results from up-regulated, supersensitive D2 receptors; suppressing opposing cholinergic tone exacerbates dopamine dominance and worsens the chorea.\",\"tr\":\"Tardif diskinezi D2 reseptör süpersensitivitesinden kaynaklanır; karşıt kolinerjik tonusun kırılması dopamin hakimiyetini ve koreyi daha da azdırır.\",\"ar\":\"ينجم عسر الحركة المتأخر عن فرط حساسية مستقبلات D2 المتكاثرة؛ وتثبيط النغمة الكولينية المعاكسة يفاقم هيمنة الدوبامين ويزيد الحركات الرقصية سوءاً.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Anticholinergics treat acute dystonia, but worsen tardive dyskinesia! Treatment requires switching to clozapine or adding a VMAT2 inhibitor.\",\"tr\":\"Doğru! Antikolinerjikler akut distoniyi çözer ama tardif diskineziyi KÖTÜLEŞTİRİR! Tedavide klozapine geçilmeli veya VMAT2 inhibitörü verilmelidir.\",\"ar\":\"صحيح! تعالج مضادات الكولين خلل التوتر الحاد لكنها تفاقم عسر الحركة المتأخر! يتطلب العلاج التحويل إلى كلوزابين أو إضافة مثبط VMAT2.\"}},{\"id\":\"opt_biperiden_cures_td\",\"text\":{\"en\":\"Biperiden instantly cures tardive dyskinesia because the disorder is a peripheral acetylcholine receptor hypersensitivity at skeletal motor endplates.\",\"tr\":\"Biperiden tardif diskineziyi anında iyileştirir çünkü bozukluk çizgili kas son plaklarındaki periferik asetilkolin aşırı duyarlılığıdır.\",\"ar\":\"يشفي البيبيريدين عسر الحركة المتأخر فوراً لأن الاضطراب ناشئ عن فرط حساسية مستقبلات الأسيتيل كولين المحيطية في اللوحة المحركة.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. TD is a central striatal neuroplastic disorder of dopamine receptor supersensitivity, and anticholinergics severely exacerbate it.\",\"tr\":\"Yanlış. Tardif diskinezi periferik değil santral bir dopamin aşırı duyarlılığıdır ve antikolinerjikler bu tabloyu çok daha ağırlaştırır.\",\"ar\":\"غير صحيح. عسر الحركة المتأخر اضطراب مركزي ناجم عن فرط حساسية مستقبلات الدوبامين، ومضادات الكولين تزيده اشتعالاً.\"}},{\"id\":\"opt_double_haloperidol_dose\",\"text\":{\"en\":\"The haloperidol dose should be immediately tripled to irreversibly downregulate and destroy all supersensitive D2 receptors permanently.\",\"tr\":\"Tüm süpersensitif D2 reseptörlerini kalıcı olarak yok etmek ve desensitize etmek için haloperidol dozu derhal üç katına çıkarılmalıdır.\",\"ar\":\"يجب مضاعفة جرعة الهالوبيريدول 3 أضعاف فوراً لإزالة حساسية وتدمير كافة مستقبلات D2 مفرطة الحساسية نهائياً.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Increasing antipsychotic dose temporarily masks symptoms by blocking supersensitive receptors, but ultimately deepens and cements the pathology.\",\"tr\":\"Yanlış. Doz artırmak semptomları geçici maskeler ancak süpersensitiviteyi daha da derinleştirip patolojiyi kalıcılaştırır.\",\"ar\":\"غير صحيح. زيادة الجرعة تموه الأعراض مؤقتاً لكنها تعمق فرط الحساسية وترسخ التلف العصبي بشكل لا رجعة فيه.\"}},{\"id\":\"opt_irreversible_substantia_nigra_death\",\"text\":{\"en\":\"Tardive dyskinesia signifies complete coagulative necrosis of the substantia nigra, requiring emergent neurosurgical deep brain stimulation.\",\"tr\":\"Tardif diskinezi substantia nigra'nın koagülasyon nekrozuna uğradığını gösterir ve acil derin beyin stimülasyonu cerrahisi gerektirir.\",\"ar\":\"يدل عسر الحركة المتأخر على نخر تخثري كامل في المادة السوداء، مما يتطلب جراحة تحفيز عميق للدماغ بشكل إسعافي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. TD is not coagulative necrosis of the substantia nigra; it is receptor upregulation and maladaptive neuroplasticity in striatal synapses.\",\"tr\":\"Yanlış. Tardif diskinezi nekroz değildir; striatal postsinaptik reseptörlerin aşırı duyarlılaşması ve adaptif plastisite bozukluğudur.\",\"ar\":\"غير صحيح. ليس عسر الحركة المتأخر نخراً في المادة السوداء؛ بل هو تكاثر وفرط حساسية تكيفية لمستقبلات الدوبامين المشبكية.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":24}]},{\"id\":\"pharm-mod6-les2-step-09\",\"stage\":\"application\",\"stageIndex\":9,\"title\":{\"tr\":\"Klinik Karar: Tipikten Atipiğe Geçiş\",\"ar\":\"قرار سريري: التحول من النمطي إلى غير النمطي\",\"en\":\"Clinical Decision: Transitioning from Typical to Atypical\"},\"prompt\":{\"en\":\"Aripiprazole is termed a 'dopamine thermostat'. How does its high-affinity D2 partial agonism (~30% intrinsic activity) stabilize both hyperactive and hypoactive dopaminergic circuits?\",\"tr\":\"Aripiprazol 'dopamin termostatı' olarak adlandırılır. Yüksek afiniteli D2 parsiyel agonizmi (%30 intrensek etki) hem hiperaktif hem hipoaktif yolakları nasıl dengeler?\",\"ar\":\"يُلقب الأريبيبرازول بـ 'منظم حرارة الدوبامين'. كيف يوازن ناهضه الجزئي عالي الألفة لـ D2 (فاعلية ذاتية ~30%) المسارات مفرطة وضعيفة النشاط؟\"},\"predictThenReveal\":true,\"config\":{\"revealedOutcome\":\"Atipik antipsikotikler yaşam kalitesini ve motor güvenliği korur.\",\"options\":[{\"id\":\"opt_partial_agonist_thermostat\",\"text\":{\"en\":\"In hyperdopaminergic mesolimbic circuits it acts as a functional antagonist (capping activation at 30%); in hypodopaminergic mesocortical and pituitary paths it supplies essential basal tone.\",\"tr\":\"Mezolimbikte tam dopamini engelleyip aktiviteyi %30'a sınırlayarak fonksiyonel antagonist; kortikal ve hipofiz yollarında ise %30 bazal uyarı vererek agonist davranır.\",\"ar\":\"يعمل كمناهض وظيفي في الميزولمبيك بحد التنشيط عند 30%؛ بينما يوفر في المسارات القشرية والنخامية نغمة قاعدية محفزة بنسبة 30%.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! In high-dopamine areas, aripiprazole dampens signal to 30% (treating psychosis). In low-dopamine areas, it provides 30% tone (preventing EPS and prolactin elevation).\",\"tr\":\"Doğru! Dopamin fazlaysa %30'a indirir (psikozu çözer); azsa %30 uyarı verir (EPS ve prolaktin yüksekliğini önler).\",\"ar\":\"صحيح! إذا كان الدوبامين مرتفعاً خفضه إلى 30% (معالجاً الذهان)، وإذا كان منخفضاً رفع التنشيط إلى 30% (مانعاً EPS والبرولاكتين).\"}},{\"id\":\"opt_full_agonist_all_regions\",\"text\":{\"en\":\"Aripiprazole acts as a 100% full agonist throughout the entire brain, triggering massive dopamine release to wash out previous neuroleptics.\",\"tr\":\"Aripiprazol tüm beyinde %100 tam agonist olarak davranır, önceki nöroleptikleri temizlemek için devasa dopamin salınımı yaptırır.\",\"ar\":\"يعمل الأريبيبرازول كناهض تام بنسبة 100% في كامل الدماغ، محفزاً إفرازاً هائلاً للدوبامين لغسل مضادات الذهان السابقة.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Aripiprazole has only ~25–30% intrinsic efficacy, not 100%. A full agonist would exacerbate psychosis into acute mania.\",\"tr\":\"Yanlış. Aripiprazol tam agonist değil %25-30 parsiyel agonisttir. Tam agonist olsaydı psikozu mani krizine sokardı.\",\"ar\":\"غير صحيح. يمتلك الأريبيبرازول فاعلية ذاتية تبلغ ~30% فقط؛ والناهض التام كان سيفاقم الذهان إلى نوبة هوس حادة.\"}},{\"id\":\"opt_inverse_agonist_everywhere\",\"text\":{\"en\":\"Aripiprazole is a universal inverse agonist that silences baseline constitutively active D2 receptors below zero across all pathways.\",\"tr\":\"Aripiprazol tüm yolaklarda bazal D2 aktivitesini sıfırın altına düşüren evrensel bir invers agonisttir.\",\"ar\":\"الأريبيبرازول ناهض عكسي عام يخمد النشاط الأساسي لمستقبلات D2 لما دون الصفر في كافة المسارات.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. An inverse agonist suppresses basal constitutive activity and would produce severe motor EPS and massive hyperprolactinemia.\",\"tr\":\"Yanlış. İnvers agonist olsaydı bazal tonusu da sıfırlar, çok ağır EPS ve hiperprolaktinemi yapardı. Aripiprazol parsiyel agonisttir.\",\"ar\":\"غير صحيح. الناهض العكسي يقضي على النغمة القاعدية مسبباً شللاً حركياً وفرط برولاكتين حاد؛ بينما الأريبيبرازول ناهض جزئي.\"}},{\"id\":\"opt_h1_only_mechanism\",\"text\":{\"en\":\"Aripiprazole does not bind D2 receptors; its clinical antipsychotic action is mediated entirely by blocking peripheral histamine H1 receptors.\",\"tr\":\"Aripiprazol D2 reseptörlerine bağlanmaz; antipsikotik etkisi tamamen periferik histamin H1 reseptör blokajından kaynaklanır.\",\"ar\":\"لا يرتبط الأريبيبرازول بمستقبلات D2؛ بل يتوسط فعاليته المضادة للذهان حظر مستقبلات الهيستامين H1 المحيطية حصراً.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Aripiprazole has sub-nanomolar affinity for D2 receptors; its therapeutic profile is driven by D2 partial agonism, not H1 blockade.\",\"tr\":\"Yanlış. Aripiprazol D2'ye sub-nanomolar düzeyde çok güçlü bağlanır; etkinliği D2 parsiyel agonizmine dayanır.\",\"ar\":\"غير صحيح. يمتلك الأريبيبرازول ألفة دون النانومولار لمستقبلات D2؛ وتنبثق فعاليته من ميزان ناهضه الجزئي عند D2.\"}}]},\"technicalTerms\":[{\"term\":\"etki mekanizması\",\"arContext\":\"آلية التأثير الدوائي\"},{\"term\":\"reseptör\",\"arContext\":\"المستقبِل الحيوي\"}],\"hints\":[{\"tier\":1,\"tr\":\"Parsiyel agonistin 'ortamdaki ligand düzeyine göre davranış değiştiren' yapısını hatırlayın.\",\"ar\":\"تذكر طبيعة الناهض الجزئي الذي يتغير سلوكه السريري تبعاً لتركيز الناقل الطبيعي في البيئة المشبكية.\",\"en\":\"Recall how a partial agonist dynamically adapts its functional behavior based on local agonist tone.\"},{\"tier\":2,\"tr\":\"Aripiprazol %30 intrensek aktiviteye sahiptir; tam dopaminin (%100) olduğu yerde etkinliği %30'a çeker.\",\"ar\":\"يمتلك الأريبيبرازول فاعلية ذاتية ~30%؛ فيخفض التنشيط المفرط في الميزولمبيك (100%) إلى 30% فقط.\",\"en\":\"Aripiprazole has ~30% intrinsic efficacy; in hyperdopaminergic zones it dampens signaling down to 30%.\"},{\"tier\":3,\"tr\":\"Dopaminin az olduğu hipofiz ve striatumda ise %30 bazal uyarı vererek EPS ve hiperprolaktinemiyi önler.\",\"ar\":\"وفي النخامية والمخطط يوفر تنشيطاً قاعدياً بنسبة 30% كافياً لمنع الأعراض الحركية وفرط البرولاكتين.\",\"en\":\"In low-dopamine pituitary and striatal pathways, it provides 30% basal tone, preventing EPS and hyperprolactinemia.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_partial_agonist_thermostat\",\"text\":{\"en\":\"In hyperdopaminergic mesolimbic circuits it acts as a functional antagonist (capping activation at 30%); in hypodopaminergic mesocortical and pituitary paths it supplies essential basal tone.\",\"tr\":\"Mezolimbikte tam dopamini engelleyip aktiviteyi %30'a sınırlayarak fonksiyonel antagonist; kortikal ve hipofiz yollarında ise %30 bazal uyarı vererek agonist davranır.\",\"ar\":\"يعمل كمناهض وظيفي في الميزولمبيك بحد التنشيط عند 30%؛ بينما يوفر في المسارات القشرية والنخامية نغمة قاعدية محفزة بنسبة 30%.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! In high-dopamine areas, aripiprazole dampens signal to 30% (treating psychosis). In low-dopamine areas, it provides 30% tone (preventing EPS and prolactin elevation).\",\"tr\":\"Doğru! Dopamin fazlaysa %30'a indirir (psikozu çözer); azsa %30 uyarı verir (EPS ve prolaktin yüksekliğini önler).\",\"ar\":\"صحيح! إذا كان الدوبامين مرتفعاً خفضه إلى 30% (معالجاً الذهان)، وإذا كان منخفضاً رفع التنشيط إلى 30% (مانعاً EPS والبرولاكتين).\"}},{\"id\":\"opt_full_agonist_all_regions\",\"text\":{\"en\":\"Aripiprazole acts as a 100% full agonist throughout the entire brain, triggering massive dopamine release to wash out previous neuroleptics.\",\"tr\":\"Aripiprazol tüm beyinde %100 tam agonist olarak davranır, önceki nöroleptikleri temizlemek için devasa dopamin salınımı yaptırır.\",\"ar\":\"يعمل الأريبيبرازول كناهض تام بنسبة 100% في كامل الدماغ، محفزاً إفرازاً هائلاً للدوبامين لغسل مضادات الذهان السابقة.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Aripiprazole has only ~25–30% intrinsic efficacy, not 100%. A full agonist would exacerbate psychosis into acute mania.\",\"tr\":\"Yanlış. Aripiprazol tam agonist değil %25-30 parsiyel agonisttir. Tam agonist olsaydı psikozu mani krizine sokardı.\",\"ar\":\"غير صحيح. يمتلك الأريبيبرازول فاعلية ذاتية تبلغ ~30% فقط؛ والناهض التام كان سيفاقم الذهان إلى نوبة هوس حادة.\"}},{\"id\":\"opt_inverse_agonist_everywhere\",\"text\":{\"en\":\"Aripiprazole is a universal inverse agonist that silences baseline constitutively active D2 receptors below zero across all pathways.\",\"tr\":\"Aripiprazol tüm yolaklarda bazal D2 aktivitesini sıfırın altına düşüren evrensel bir invers agonisttir.\",\"ar\":\"الأريبيبرازول ناهض عكسي عام يخمد النشاط الأساسي لمستقبلات D2 لما دون الصفر في كافة المسارات.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. An inverse agonist suppresses basal constitutive activity and would produce severe motor EPS and massive hyperprolactinemia.\",\"tr\":\"Yanlış. İnvers agonist olsaydı bazal tonusu da sıfırlar, çok ağır EPS ve hiperprolaktinemi yapardı. Aripiprazol parsiyel agonisttir.\",\"ar\":\"غير صحيح. الناهض العكسي يقضي على النغمة القاعدية مسبباً شللاً حركياً وفرط برولاكتين حاد؛ بينما الأريبيبرازول ناهض جزئي.\"}},{\"id\":\"opt_h1_only_mechanism\",\"text\":{\"en\":\"Aripiprazole does not bind D2 receptors; its clinical antipsychotic action is mediated entirely by blocking peripheral histamine H1 receptors.\",\"tr\":\"Aripiprazol D2 reseptörlerine bağlanmaz; antipsikotik etkisi tamamen periferik histamin H1 reseptör blokajından kaynaklanır.\",\"ar\":\"لا يرتبط الأريبيبرازول بمستقبلات D2؛ بل يتوسط فعاليته المضادة للذهان حظر مستقبلات الهيستامين H1 المحيطية حصراً.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Aripiprazole has sub-nanomolar affinity for D2 receptors; its therapeutic profile is driven by D2 partial agonism, not H1 blockade.\",\"tr\":\"Yanlış. Aripiprazol D2'ye sub-nanomolar düzeyde çok güçlü bağlanır; etkinliği D2 parsiyel agonizmine dayanır.\",\"ar\":\"غير صحيح. يمتلك الأريبيبرازول ألفة دون النانومولار لمستقبلات D2؛ وتنبثق فعاليته من ميزان ناهضه الجزئي عند D2.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":25}]},{\"id\":\"pharm-mod6-les2-step-10\",\"stage\":\"retrieval\",\"stageIndex\":10,\"title\":{\"tr\":\"Geri Çağırma: Tersinir Kinetik ve Koff\",\"ar\":\"استرجاع معرفي: الحركية العكوسة ومعدل koff\",\"en\":\"Retrieval: Reversible Kinetics and Fast Koff\"},\"prompt\":{\"en\":\"Recall the four major dopaminergic pathways: match in sequence the pathways responsible for antipsychotic efficacy, extrapyramidal motor side effects, and hyperprolactinemia.\",\"tr\":\"Dört ana dopaminerjik yolağı hatırlayın: antipsikotik etkinlik, ekstrapiramidal motor yan etkiler ve hiperprolaktinemiden sorumlu yolakları sırasıyla eşleştirin.\",\"ar\":\"تذكر المسارات الدوبامينية الأربعة الكبرى: طابق بالترتيب المسارات المسؤولة عن الفعالية المضادة للذهان، والأعراض الحركية خارج الهرمية، وفرط برولاكتين الدم.\"},\"predictThenReveal\":false,\"config\":{\"options\":[{\"id\":\"opt_pathway_match_correct\",\"text\":{\"en\":\"Antipsychotic efficacy = Mesolimbic; Extrapyramidal motor symptoms = Nigrostriatal; Hyperprolactinemia = Tuberoinfundibular.\",\"tr\":\"Antipsikotik etkinlik = Mezolimbik; Ekstrapiramidal motor semptomlar = Nigrostriatal; Hiperprolaktinemi = Tüberoinfundibuler.\",\"ar\":\"الفعالية المضادة للذهان = الميزولمبيك؛ الأعراض الحركية خارج الهرمية = المخططي الأسود؛ فرط البرولاكتين = القمعي النخامي.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Mesolimbic mediates positive symptoms; Nigrostriatal controls motor execution; Tuberoinfundibular tonically suppresses prolactin.\",\"tr\":\"Doğru! Mezolimbik pozitif semptomları; Nigrostriatal motor hareketleri; Tüberoinfundibuler ise hipofizden prolaktin salınımını kontrol eder.\",\"ar\":\"صحيح! الميزولمبيك يتوسط الهلاوس والضلالات؛ المخططي الأسود يتحكم بالحركة؛ والقمعي النخامي يكبح إفراز البرولاكتين فسيولوجياً.\"}},{\"id\":\"opt_pathway_match_inverted\",\"text\":{\"en\":\"Antipsychotic efficacy = Tuberoinfundibular; Extrapyramidal symptoms = Mesocortical; Hyperprolactinemia = Nigrostriatal.\",\"tr\":\"Antipsikotik etkinlik = Tüberoinfundibuler; Ekstrapiramidal semptomlar = Mezokortikal; Hiperprolaktinemi = Nigrostriatal.\",\"ar\":\"الفعالية المضادة للذهان = القمعي النخامي؛ الأعراض خارج الهرمية = الميزوكورتيكال؛ فرط البرولاكتين = المخططي الأسود.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. The tuberoinfundibular pathway controls prolactin, not psychosis. The mesolimbic pathway mediates antipsychotic efficacy.\",\"tr\":\"Yanlış. Tüberoinfundibuler yolak psikozu değil prolaktini yönetir. Antipsikotik etki mezolimbik yoldaki blokajdan kaynaklanır.\",\"ar\":\"غير صحيح. يتحكم المسار القمعي بالبرولاكتين وليس بالذهان؛ والمسار الميزولمبي هو المسؤول عن إخماد الهلاوس والذهان.\"}},{\"id\":\"opt_pathway_match_nigrostriatal_psychosis\",\"text\":{\"en\":\"Antipsychotic efficacy = Nigrostriatal; Extrapyramidal symptoms = Mesolimbic; Hyperprolactinemia = Mesocortical.\",\"tr\":\"Antipsikotik etkinlik = Nigrostriatal; Ekstrapiramidal semptomlar = Mezolimbik; Hiperprolaktinemi = Mezokortikal.\",\"ar\":\"الفعالية المضادة للذهان = المخططي الأسود؛ الأعراض خارج الهرمية = الميزولمبيك؛ فرط البرولاكتين = الميزوكورتيكال.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Nigrostriatal blockade causes parkinsonian motor symptoms; mesolimbic blockade resolves hallucinations and delusions.\",\"tr\":\"Yanlış. Nigrostriatal yol motor kontrol merkezidir ve blokajı EPS yapar; mezolimbik yol ise pozitif semptomları dindirir.\",\"ar\":\"غير صحيح. حظر المسار المخططي يسبب الشلل الرعاشي وEPS؛ بينما حظر الميزولمبيك هو من يزيل الهلاوس السمعية والضلالات.\"}},{\"id\":\"opt_all_mesocortical\",\"text\":{\"en\":\"Antipsychotic efficacy = Mesocortical; Extrapyramidal symptoms = Tuberoinfundibular; Hyperprolactinemia = Mesolimbic.\",\"tr\":\"Antipsikotik etkinlik = Mezokortikal; Ekstrapiramidal semptomlar = Tüberoinfundibuler; Hiperprolaktinemi = Mezolimbik.\",\"ar\":\"الفعالية المضادة للذهان = الميزوكورتيكال؛ الأعراض خارج الهرمية = القمعي النخامي؛ فرط البرولاكتين = الميزولمبيك.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Mesocortical dopamine deficiency causes negative symptoms; tuberoinfundibular blockade causes hyperprolactinemia.\",\"tr\":\"Yanlış. Mezokortikal yol negatif semptomlarla ilişkilidir; prolaktin yükselmesi tüberoinfundibuler yolun bloke edilmesiyle oluşur.\",\"ar\":\"غير صحيح. يرتبط نقص الدوبامين بالميزوكورتيكال بالأعراض السلبية؛ بينما ينجم فرط البرولاكتين عن حظر المسار القمعي النخامي.\"}}]},\"technicalTerms\":[{\"term\":\"koff ayrışma hızı\",\"arContext\":\"معدل الانفصال koff\"}],\"hints\":[{\"tier\":1,\"tr\":\"Beyindeki dört dopamin yolağının adlarını ve anatomik sonlanma yerlerini gözden geçirin.\",\"ar\":\"راجع أسماء المسارات الدوبامينية الأربعة في الدماغ ومناطق انتهائها التشريحية.\",\"en\":\"Review the anatomical origins, trajectories, and terminal regions of the four major dopamine pathways.\"},{\"tier\":2,\"tr\":\"Limbik sistem duyguları, striatum hareketi, hipotalamus-hipofiz ekseni ise prolaktini yönetir.\",\"ar\":\"يدير الجهاز الحوفي العواطف والهلاوس، ويتحكم المخطط بالحركة، ويدير المحور النخامي هرمون الحليب.\",\"en\":\"The limbic system governs psychosis; the striatum coordinates movement; the pituitary axis regulates prolactin.\"},{\"tier\":3,\"tr\":\"Sıralama: Antipsikotik etkinlik = Mezolimbik; Motor EPS = Nigrostriatal; Hiperprolaktinemi = Tüberoinfundibuler.\",\"ar\":\"الترتيب: الفعالية = الميزولمبيك؛ الأعراض الحركية = المخططي الأسود؛ فرط البرولاكتين = القمعي النخامي.\",\"en\":\"Sequence: Antipsychotic efficacy = Mesolimbic; Motor EPS = Nigrostriatal; Hyperprolactinemia = Tuberoinfundibular.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_pathway_match_correct\",\"text\":{\"en\":\"Antipsychotic efficacy = Mesolimbic; Extrapyramidal motor symptoms = Nigrostriatal; Hyperprolactinemia = Tuberoinfundibular.\",\"tr\":\"Antipsikotik etkinlik = Mezolimbik; Ekstrapiramidal motor semptomlar = Nigrostriatal; Hiperprolaktinemi = Tüberoinfundibuler.\",\"ar\":\"الفعالية المضادة للذهان = الميزولمبيك؛ الأعراض الحركية خارج الهرمية = المخططي الأسود؛ فرط البرولاكتين = القمعي النخامي.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Mesolimbic mediates positive symptoms; Nigrostriatal controls motor execution; Tuberoinfundibular tonically suppresses prolactin.\",\"tr\":\"Doğru! Mezolimbik pozitif semptomları; Nigrostriatal motor hareketleri; Tüberoinfundibuler ise hipofizden prolaktin salınımını kontrol eder.\",\"ar\":\"صحيح! الميزولمبيك يتوسط الهلاوس والضلالات؛ المخططي الأسود يتحكم بالحركة؛ والقمعي النخامي يكبح إفراز البرولاكتين فسيولوجياً.\"}},{\"id\":\"opt_pathway_match_inverted\",\"text\":{\"en\":\"Antipsychotic efficacy = Tuberoinfundibular; Extrapyramidal symptoms = Mesocortical; Hyperprolactinemia = Nigrostriatal.\",\"tr\":\"Antipsikotik etkinlik = Tüberoinfundibuler; Ekstrapiramidal semptomlar = Mezokortikal; Hiperprolaktinemi = Nigrostriatal.\",\"ar\":\"الفعالية المضادة للذهان = القمعي النخامي؛ الأعراض خارج الهرمية = الميزوكورتيكال؛ فرط البرولاكتين = المخططي الأسود.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. The tuberoinfundibular pathway controls prolactin, not psychosis. The mesolimbic pathway mediates antipsychotic efficacy.\",\"tr\":\"Yanlış. Tüberoinfundibuler yolak psikozu değil prolaktini yönetir. Antipsikotik etki mezolimbik yoldaki blokajdan kaynaklanır.\",\"ar\":\"غير صحيح. يتحكم المسار القمعي بالبرولاكتين وليس بالذهان؛ والمسار الميزولمبي هو المسؤول عن إخماد الهلاوس والذهان.\"}},{\"id\":\"opt_pathway_match_nigrostriatal_psychosis\",\"text\":{\"en\":\"Antipsychotic efficacy = Nigrostriatal; Extrapyramidal symptoms = Mesolimbic; Hyperprolactinemia = Mesocortical.\",\"tr\":\"Antipsikotik etkinlik = Nigrostriatal; Ekstrapiramidal semptomlar = Mezolimbik; Hiperprolaktinemi = Mezokortikal.\",\"ar\":\"الفعالية المضادة للذهان = المخططي الأسود؛ الأعراض خارج الهرمية = الميزولمبيك؛ فرط البرولاكتين = الميزوكورتيكال.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Nigrostriatal blockade causes parkinsonian motor symptoms; mesolimbic blockade resolves hallucinations and delusions.\",\"tr\":\"Yanlış. Nigrostriatal yol motor kontrol merkezidir ve blokajı EPS yapar; mezolimbik yol ise pozitif semptomları dindirir.\",\"ar\":\"غير صحيح. حظر المسار المخططي يسبب الشلل الرعاشي وEPS؛ بينما حظر الميزولمبيك هو من يزيل الهلاوس السمعية والضلالات.\"}},{\"id\":\"opt_all_mesocortical\",\"text\":{\"en\":\"Antipsychotic efficacy = Mesocortical; Extrapyramidal symptoms = Tuberoinfundibular; Hyperprolactinemia = Mesolimbic.\",\"tr\":\"Antipsikotik etkinlik = Mezokortikal; Ekstrapiramidal semptomlar = Tüberoinfundibuler; Hiperprolaktinemi = Mezolimbik.\",\"ar\":\"الفعالية المضادة للذهان = الميزوكورتيكال؛ الأعراض خارج الهرمية = القمعي النخامي؛ فرط البرولاكتين = الميزولمبيك.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Mesocortical dopamine deficiency causes negative symptoms; tuberoinfundibular blockade causes hyperprolactinemia.\",\"tr\":\"Yanlış. Mezokortikal yol negatif semptomlarla ilişkilidir; prolaktin yükselmesi tüberoinfundibuler yolun bloke edilmesiyle oluşur.\",\"ar\":\"غير صحيح. يرتبط نقص الدوبامين بالميزوكورتيكال بالأعراض السلبية؛ بينما ينجم فرط البرولاكتين عن حظر المسار القمعي النخامي.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":26}]},{\"id\":\"pharm-mod6-les2-step-11\",\"stage\":\"connection\",\"stageIndex\":11,\"title\":{\"tr\":\"Büyük Final: 22 Derslik Müfredatın Tamamlanışı\",\"ar\":\"الختام الكبير: إتمام منهاج الـ 22 درساً\",\"en\":\"Grand Finale: Completing the 22-Lesson Curriculum\"},\"prompt\":{\"en\":\"Antipsychotics block multiple off-target receptors beyond D2. Which adverse clinical consequences emerge from off-target antagonism of H1, alpha-1, and muscarinic M1 receptors?\",\"tr\":\"Antipsikotikler D2 dışında birçok reseptörü bloke eder. H1, alfa-1 ve muskarinik M1 reseptörlerinin hedeften sapmış blokajı hangi yan etkileri doğurur?\",\"ar\":\"تحظر مضادات الذهان مستقبلات جانبية عديدة غير D2. ما العواقب السريرية الناجمة عن الحظر الجانبي لمستقبلات H1، وألفا-1، والمسكارين M1؟\"},\"predictThenReveal\":false,\"config\":{\"options\":[{\"id\":\"opt_off_target_trio\",\"text\":{\"en\":\"H1 antagonism drives sedation and metabolic weight gain; alpha-1 antagonism causes orthostatic hypotension; M1 antagonism provokes dry mouth, constipation, and blurred vision.\",\"tr\":\"H1 blokajı sedasyon ve kilo artışı yapar; alfa-1 blokajı ortostatik hipotansiyona yol açar; M1 blokajı ise ağız kuruluğu, kabızlık ve bulanık görme yaratır.\",\"ar\":\"حظر H1 يسبب التهدئة وزيادة الوزن؛ وحظر ألفا-1 يسبب هبوط الضغط الانتصابي؛ وحظر M1 يسبب جفاف الفم، والإمساك، وتشوش الرؤية.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Antihistaminic effects promote weight gain; antiadrenergic alpha-1 causes orthostatic syncope; anticholinergic M1 produces classic dry/constipated symptoms.\",\"tr\":\"Doğru! H1 kilo aldırır ve uyutur; alfa-1 tansiyonu düşürüp baş dönmesi yapar; M1 ise antikolinerjik yan etkileri tetikler.\",\"ar\":\"صحيح! حظر H1 مسؤول عن النعاس والبدانة؛ ألفا-1 يسبب الدوار الوضعي؛ وحظر M1 المسكاريني يطلق الأعراض المضادة للكولين.\"}},{\"id\":\"opt_h1_hypertension\",\"text\":{\"en\":\"H1 antagonism causes severe hypertensive crisis, alpha-1 antagonism causes priapism only, and M1 antagonism causes profuse bronchorrhea and diarrhea.\",\"tr\":\"H1 blokajı şiddetli hipertansif kriz yapar, alfa-1 sadece priapizm yapar, M1 blokajı ise aşırı bronkore ve ishal başlatır.\",\"ar\":\"يسبب حظر H1 نوبة فرط ضغط حادة، وألفا-1 قسوحاً فقط، ويسبب حظر M1 إسهالاً مفرطاً وسيلاناً قصبياً.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. H1 causes sedation, not hypertension; M1 blockade INHIBITS secretions (causing dry mouth and constipation), not diarrhea.\",\"tr\":\"Yanlış. H1 tansiyonu yükseltmez sedasyon yapar; M1 blokajı ise salgıları artırmaz, kurutur (ağız kuruluğu, kabızlık).\",\"ar\":\"غير صحيح. يسبب حظر H1 تهدئة وليس فرط ضغط؛ وحظر M1 يجفف الإفرازات (جفاف الفم وإمساك) ولا يسبب إسهالاً.\"}},{\"id\":\"opt_alpha1_anticonvulsant\",\"text\":{\"en\":\"Alpha-1 antagonism elevates seizure threshold, while muscarinic M1 blockade stimulates memory consolidation and prevents dementia.\",\"tr\":\"Alfa-1 blokajı nöbet eşiğini yükseltir, muskarinik M1 blokajı ise hafızayı güçlendirerek demansı önler.\",\"ar\":\"يرفع حظر ألفا-1 عتبة التشنج، بينما يقوي حظر المسكارين M1 الذاكرة ويقي من الخرف.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Alpha-1 blockade does not prevent seizures. M1 blockade IMPAIRS memory and worsens cognitive performance (anticholinergic burden).\",\"tr\":\"Yanlış. Alfa-1 nöbeti önlemez; M1 blokajı hafızayı güçlendirmez, aksine bilişsel performansı ve belleği bozar.\",\"ar\":\"غير صحيح. لا يقي حظر ألفا-1 من النوبات؛ وحظر M1 يضعف الذاكرة والأداء الإدراكي (العبء المضاد للكولين).\"}},{\"id\":\"opt_m1_weight_loss\",\"text\":{\"en\":\"Muscarinic M1 blockade causes profound anorexia and cachexia, while H1 blockade selectively eliminates extrapyramidal symptoms.\",\"tr\":\"Muskarinik M1 blokajı anoreksiya ve kaşeksiye yol açar, H1 blokajı ise ekstrapiramidal semptomları tamamen ortadan kaldırır.\",\"ar\":\"يسبب حظر المسكارين M1 فقدان شهية حاد وهزالاً، بينما يزيل حظر H1 الأعراض خارج الهرمية تماماً.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Weight gain is driven by H1 and 5-HT2C antagonism. M1 blockade causes constipation and autonomic side effects.\",\"tr\":\"Yanlış. Kilo alımı H1 ve 5-HT2C blokajından kaynaklanır; M1 blokajı ise otonomik kuruluğa ve kabızlığa yol açar.\",\"ar\":\"غير صحيح. تنجم زيادة الوزن عن حظر H1 و 5-HT2C؛ بينما يسبب حظر M1 إمساكاً وجفافاً في الأغشية المخاطية.\"}}]},\"technicalTerms\":[{\"term\":\"konsept ustalığı\",\"arContext\":\"إتقان المفاهيم\"}],\"hints\":[{\"tier\":1,\"tr\":\"Antipsikotiklerin yan etki profilini belirleyen hedeften sapmış H1, alfa-1 ve M1 reseptörlerini düşünün.\",\"ar\":\"فكر في المستقبلات الجانبية H1 وألفا-1 وM1 التي تحدد المظهر الجانبي لمضادات الذهان.\",\"en\":\"Consider the off-target H1, alpha-1, and muscarinic M1 receptors that govern antipsychotic adverse effects.\"},{\"tier\":2,\"tr\":\"Histamin iştah ve uyanıklığı, alfa-1 vasküler tonusu, muskarinik reseptörler ise salgıları yönetir.\",\"ar\":\"يتحكم الهيستامين باليقظة والشهية، وألفا-1 بالضغط الوعائي، والمسكارين بإفراز اللعاب وحركة الأمعاء.\",\"en\":\"Histamine controls wakefulness and appetite; alpha-1 maintains vascular tone; muscarinic receptors control secretions.\"},{\"tier\":3,\"tr\":\"H1 blokajı sedasyon ve kilo artışı; alfa-1 ortostatik hipotansiyon; M1 ise ağız kuruluğu ve kabızlık yapar.\",\"ar\":\"حظر H1 يسبب النعاس والبدانة؛ وألفا-1 يسبب هبوط الضغط الانتصابي؛ وM1 يسبب جفاف الفم والإمساك.\",\"en\":\"H1 blockade drives sedation and weight gain; alpha-1 causes orthostatic syncope; M1 causes dry mouth and constipation.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_off_target_trio\",\"text\":{\"en\":\"H1 antagonism drives sedation and metabolic weight gain; alpha-1 antagonism causes orthostatic hypotension; M1 antagonism provokes dry mouth, constipation, and blurred vision.\",\"tr\":\"H1 blokajı sedasyon ve kilo artışı yapar; alfa-1 blokajı ortostatik hipotansiyona yol açar; M1 blokajı ise ağız kuruluğu, kabızlık ve bulanık görme yaratır.\",\"ar\":\"حظر H1 يسبب التهدئة وزيادة الوزن؛ وحظر ألفا-1 يسبب هبوط الضغط الانتصابي؛ وحظر M1 يسبب جفاف الفم، والإمساك، وتشوش الرؤية.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Antihistaminic effects promote weight gain; antiadrenergic alpha-1 causes orthostatic syncope; anticholinergic M1 produces classic dry/constipated symptoms.\",\"tr\":\"Doğru! H1 kilo aldırır ve uyutur; alfa-1 tansiyonu düşürüp baş dönmesi yapar; M1 ise antikolinerjik yan etkileri tetikler.\",\"ar\":\"صحيح! حظر H1 مسؤول عن النعاس والبدانة؛ ألفا-1 يسبب الدوار الوضعي؛ وحظر M1 المسكاريني يطلق الأعراض المضادة للكولين.\"}},{\"id\":\"opt_h1_hypertension\",\"text\":{\"en\":\"H1 antagonism causes severe hypertensive crisis, alpha-1 antagonism causes priapism only, and M1 antagonism causes profuse bronchorrhea and diarrhea.\",\"tr\":\"H1 blokajı şiddetli hipertansif kriz yapar, alfa-1 sadece priapizm yapar, M1 blokajı ise aşırı bronkore ve ishal başlatır.\",\"ar\":\"يسبب حظر H1 نوبة فرط ضغط حادة، وألفا-1 قسوحاً فقط، ويسبب حظر M1 إسهالاً مفرطاً وسيلاناً قصبياً.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. H1 causes sedation, not hypertension; M1 blockade INHIBITS secretions (causing dry mouth and constipation), not diarrhea.\",\"tr\":\"Yanlış. H1 tansiyonu yükseltmez sedasyon yapar; M1 blokajı ise salgıları artırmaz, kurutur (ağız kuruluğu, kabızlık).\",\"ar\":\"غير صحيح. يسبب حظر H1 تهدئة وليس فرط ضغط؛ وحظر M1 يجفف الإفرازات (جفاف الفم وإمساك) ولا يسبب إسهالاً.\"}},{\"id\":\"opt_alpha1_anticonvulsant\",\"text\":{\"en\":\"Alpha-1 antagonism elevates seizure threshold, while muscarinic M1 blockade stimulates memory consolidation and prevents dementia.\",\"tr\":\"Alfa-1 blokajı nöbet eşiğini yükseltir, muskarinik M1 blokajı ise hafızayı güçlendirerek demansı önler.\",\"ar\":\"يرفع حظر ألفا-1 عتبة التشنج، بينما يقوي حظر المسكارين M1 الذاكرة ويقي من الخرف.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Alpha-1 blockade does not prevent seizures. M1 blockade IMPAIRS memory and worsens cognitive performance (anticholinergic burden).\",\"tr\":\"Yanlış. Alfa-1 nöbeti önlemez; M1 blokajı hafızayı güçlendirmez, aksine bilişsel performansı ve belleği bozar.\",\"ar\":\"غير صحيح. لا يقي حظر ألفا-1 من النوبات؛ وحظر M1 يضعف الذاكرة والأداء الإدراكي (العبء المضاد للكولين).\"}},{\"id\":\"opt_m1_weight_loss\",\"text\":{\"en\":\"Muscarinic M1 blockade causes profound anorexia and cachexia, while H1 blockade selectively eliminates extrapyramidal symptoms.\",\"tr\":\"Muskarinik M1 blokajı anoreksiya ve kaşeksiye yol açar, H1 blokajı ise ekstrapiramidal semptomları tamamen ortadan kaldırır.\",\"ar\":\"يسبب حظر المسكارين M1 فقدان شهية حاد وهزالاً، بينما يزيل حظر H1 الأعراض خارج الهرمية تماماً.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Weight gain is driven by H1 and 5-HT2C antagonism. M1 blockade causes constipation and autonomic side effects.\",\"tr\":\"Yanlış. Kilo alımı H1 ve 5-HT2C blokajından kaynaklanır; M1 blokajı ise otonomik kuruluğa ve kabızlığa yol açar.\",\"ar\":\"غير صحيح. تنجم زيادة الوزن عن حظر H1 و 5-HT2C؛ بينما يسبب حظر M1 إمساكاً وجفافاً في الأغشية المخاطية.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":27}]},{\"id\":\"pharm-mod6-les2-step-12\",\"stage\":\"mastery_check\",\"stageIndex\":12,\"title\":{\"tr\":\"Müfredat Ustalık Sınavı: D2 Terapötik Pencere\",\"ar\":\"اختبار الإتقان الختامي للمنهاج: نافذة D2 العلاجية\",\"en\":\"Curriculum Mastery Assessment: The D2 Therapeutic Window\"},\"prompt\":{\"en\":\"A patient on haloperidol 10 mg/day develops prolactin 85 ng/mL, severe cogwheel rigidity, and emotional blunting. PET shows 84% striatal D2 occupancy. Which rotation resolves all three adverse effects?\",\"tr\":\"Haloperidol 10 mg/gün alan hastada prolaktin 85 ng/mL, dişli çark rijiditesi ve duygusal küntlük gelişiyor. PET %84 D2 doluluğu gösteriyor. Hangi ilaca geçiş her üç yan etkiyi çözer?\",\"ar\":\"مريض يتناول هالوبيريدول 10 ملغ/يوم يعاني من برولاكتين 85 نغ/مل، وتيبس مسنن، وتبلد انفعالي. يُظهر PET إشغال 84% لـ D2. أي تحويل دوائي يحل الأعراض الثلاثة؟\"},\"predictThenReveal\":true,\"config\":{\"revealedOutcome\":\"22 Derslik Müfredat Başarıyla Tamamlandı! Büyük Ustalık Rozeti Kazanıldı! +50 XP.\",\"options\":[{\"id\":\"opt_rotate_aripiprazole\",\"text\":{\"en\":\"Switch to Aripiprazole: its D2 partial agonism (~30% intrinsic activity) supplies basal tone to resolve rigidity and prolactin, while controlling psychosis.\",\"tr\":\"Aripiprazole geçiş: D2 parsiyel agonizmi (%30 intrensek aktivite) rijiditeyi ve prolaktini düzeltecek bazal tonusu sağlar, psikozu da kontrol altında tutar.\",\"ar\":\"التحويل إلى أريبيبرازول: يوفر ناهضه الجزئي لـ D2 (فاعلية ذاتية ~30%) نغمة قاعدية تعالج التيبس والبرولاكتين، مع ضبط الذهان.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Exceeding 80% D2 occupancy causes EPS and hyperprolactinemia. Aripiprazole's ~30% intrinsic tone lowers effective blockade below 80%.\",\"tr\":\"Doğru! %80 üzerindeki D2 doluluğu EPS ve prolaktin yüksekliği yapar. Aripiprazolün %30 intrensek tonusu bu etkileri hızla geri çevirir.\",\"ar\":\"صحيح! يسبب تجاوز إشغال 80% لـ D2 أعراضاً حركية وفرط برولاكتين؛ وتوفر فاعلية الأريبيبرازول الذاتية (~30%) حلاً متكاملاً.\"}},{\"id\":\"opt_switch_risperidone\",\"text\":{\"en\":\"Switch to Risperidone, because all second-generation atypicals are completely excluded from the pituitary by the blood-brain barrier.\",\"tr\":\"Risperidona geçiş, çünkü tüm ikinci kuşak atipikler kan-beyin bariyeri sayesinde hipofiz dokusundan tamamen dışlanırlar.\",\"ar\":\"التحويل إلى ريسبيريدون، لأن جميع الأدوية اللانمطية تُحجب تماماً عن النخامية بواسطة الحاجز الدموي الدماغي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. The pituitary gland lies OUTSIDE the blood-brain barrier. Risperidone has potent D2 affinity and causes notorious hyperprolactinemia.\",\"tr\":\"Yanlış. Hipofiz bezi kan-beyin bariyerinin DIŞINDADIR. Risperidon güçlü D2 afinitesiyle çok şiddetli hiperprolaktinemi yapar.\",\"ar\":\"غير صحيح. تقع الغدة النخامية خارج الحاجز الدموي الدماغي؛ ويمتلك الريسبيريدون ألفة عالية لـ D2 مسبباً فرط برولاكتين حاداً.\"}},{\"id\":\"opt_add_biperiden_double_dose\",\"text\":{\"en\":\"Add biperiden 4 mg daily and double the haloperidol dose to 20 mg to overcome pituitary dopamine resistance and eliminate hallucinations.\",\"tr\":\"Günde 4 mg biperiden ekleyin ve hipofizdeki dopamin direncini kırıp halüsinasyonları bitirmek için haloperidolu 20 mg'a çıkarın.\",\"ar\":\"إضافة بيبيريدين 4 ملغ يومياً ومضاعفة جرعة الهالوبيريدول إلى 20 ملغ لكسر مقاومة الدوبامين النخامية وإنهاء الهلاوس.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Doubling haloperidol will worsen hyperprolactinemia and emotional blunting, and chronic anticholinergics increase the risk of tardive dyskinesia.\",\"tr\":\"Yanlış. Haloperidol dozunu artırmak prolaktini ve apatiyi daha da fırlatır; kronik antikolinerjik eklemek tardif diskinezi riskini katlar.\",\"ar\":\"غير صحيح. ستؤدي مضاعفة الهالوبيريدول لمفاقمة فرط البرولاكتين والتبلد؛ كما تزيد مضادات الكولين المزمنة خطر عسر الحركة المتأخر.\"}},{\"id\":\"opt_add_bromocriptine_full\",\"text\":{\"en\":\"Co-administer bromocriptine (a full D2 agonist) with haloperidol to stimulate pituitary receptors without affecting mesolimbic circuits.\",\"tr\":\"Mezolimbik devreleri etkilemeden hipofiz reseptörlerini uyarmak için haloperidolün yanına bromokriptin (tam D2 agonisti) ekleyin.\",\"ar\":\"المشاركة الدوائية مع بروموكريبتين (ناهض D2 تام) لتحفيز مستقبلات النخامية دون التأثير على دوائر الميزولمبيك.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Full dopamine agonists counteract antipsychotic efficacy across the entire brain, triggering immediate, violent psychotic relapse.\",\"tr\":\"Yanlış. Tam dopamin agonistleri tüm beyinde antipsikotik etkiyi sıfırlar ve hastayı derhal şiddetli psikotik alevlenmeye sokar.\",\"ar\":\"غير صحيح. تلغي ناهضات الدوبامين التامة الفعالية المضادة للذهان في كامل الدماغ مفجرة انتكاسة ذهانية عنيفة وفورية.\"}}]},\"technicalTerms\":[{\"term\":\"etki mekanizması\",\"arContext\":\"آلية التأثير الدوائي\"},{\"term\":\"reseptör\",\"arContext\":\"المستقبِل الحيوي\"}],\"hints\":[{\"tier\":1,\"tr\":\"PET'te %84 D2 doluluğu olan, prolaktini fırlamış ve rijiditesi olan hastaya hangi farmakodinamik profil gerekir?\",\"ar\":\"مريض بإشغال 84% لـ D2 في PET وفرط برولاكتين وتيبس؛ ما المظهر الديناميكي الدوائي القادر على إنقاذه؟\",\"en\":\"What pharmacodynamic profile is needed for a patient with 84% striatal D2 occupancy, hyperprolactinemia, and EPS?\"},{\"tier\":2,\"tr\":\"D2 doluluğunu %80'in altına çekecek ancak psikozu alevlendirmeyecek bir 'termostat' ajan seçilmelidir.\",\"ar\":\"يجب اختيار دواء 'منظم حرارة' يخفض الحظر الفعلي دون 80% دون أن يفجر انتكاسة ذهانية.\",\"en\":\"A 'thermostat' agent is required that lowers effective striatal blockade below 80% without psychotic relapse.\"},{\"tier\":3,\"tr\":\"Aripiprazol D2 parsiyel agonizmi (%30 tonus) ile haloperidolü söker, prolaktini ve rijiditeyi çözer, psikozu tutar.\",\"ar\":\"الأريبيبرازول بناهضه الجزئي لـ D2 (30%) يزيح الهالوبيريدول، ويعالج التيبس والبرولاكتين، مع ضبط الذهان تماماً.\",\"en\":\"Aripiprazole's ~30% intrinsic D2 tone displaces haloperidol, reversing hyperprolactinemia and tremor while stabilizing psychosis.\"}],\"conceptCheck\":{\"options\":[{\"id\":\"opt_rotate_aripiprazole\",\"text\":{\"en\":\"Switch to Aripiprazole: its D2 partial agonism (~30% intrinsic activity) supplies basal tone to resolve rigidity and prolactin, while controlling psychosis.\",\"tr\":\"Aripiprazole geçiş: D2 parsiyel agonizmi (%30 intrensek aktivite) rijiditeyi ve prolaktini düzeltecek bazal tonusu sağlar, psikozu da kontrol altında tutar.\",\"ar\":\"التحويل إلى أريبيبرازول: يوفر ناهضه الجزئي لـ D2 (فاعلية ذاتية ~30%) نغمة قاعدية تعالج التيبس والبرولاكتين، مع ضبط الذهان.\"},\"isCorrect\":true,\"feedback\":{\"en\":\"Correct! Exceeding 80% D2 occupancy causes EPS and hyperprolactinemia. Aripiprazole's ~30% intrinsic tone lowers effective blockade below 80%.\",\"tr\":\"Doğru! %80 üzerindeki D2 doluluğu EPS ve prolaktin yüksekliği yapar. Aripiprazolün %30 intrensek tonusu bu etkileri hızla geri çevirir.\",\"ar\":\"صحيح! يسبب تجاوز إشغال 80% لـ D2 أعراضاً حركية وفرط برولاكتين؛ وتوفر فاعلية الأريبيبرازول الذاتية (~30%) حلاً متكاملاً.\"}},{\"id\":\"opt_switch_risperidone\",\"text\":{\"en\":\"Switch to Risperidone, because all second-generation atypicals are completely excluded from the pituitary by the blood-brain barrier.\",\"tr\":\"Risperidona geçiş, çünkü tüm ikinci kuşak atipikler kan-beyin bariyeri sayesinde hipofiz dokusundan tamamen dışlanırlar.\",\"ar\":\"التحويل إلى ريسبيريدون، لأن جميع الأدوية اللانمطية تُحجب تماماً عن النخامية بواسطة الحاجز الدموي الدماغي.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. The pituitary gland lies OUTSIDE the blood-brain barrier. Risperidone has potent D2 affinity and causes notorious hyperprolactinemia.\",\"tr\":\"Yanlış. Hipofiz bezi kan-beyin bariyerinin DIŞINDADIR. Risperidon güçlü D2 afinitesiyle çok şiddetli hiperprolaktinemi yapar.\",\"ar\":\"غير صحيح. تقع الغدة النخامية خارج الحاجز الدموي الدماغي؛ ويمتلك الريسبيريدون ألفة عالية لـ D2 مسبباً فرط برولاكتين حاداً.\"}},{\"id\":\"opt_add_biperiden_double_dose\",\"text\":{\"en\":\"Add biperiden 4 mg daily and double the haloperidol dose to 20 mg to overcome pituitary dopamine resistance and eliminate hallucinations.\",\"tr\":\"Günde 4 mg biperiden ekleyin ve hipofizdeki dopamin direncini kırıp halüsinasyonları bitirmek için haloperidolu 20 mg'a çıkarın.\",\"ar\":\"إضافة بيبيريدين 4 ملغ يومياً ومضاعفة جرعة الهالوبيريدول إلى 20 ملغ لكسر مقاومة الدوبامين النخامية وإنهاء الهلاوس.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Doubling haloperidol will worsen hyperprolactinemia and emotional blunting, and chronic anticholinergics increase the risk of tardive dyskinesia.\",\"tr\":\"Yanlış. Haloperidol dozunu artırmak prolaktini ve apatiyi daha da fırlatır; kronik antikolinerjik eklemek tardif diskinezi riskini katlar.\",\"ar\":\"غير صحيح. ستؤدي مضاعفة الهالوبيريدول لمفاقمة فرط البرولاكتين والتبلد؛ كما تزيد مضادات الكولين المزمنة خطر عسر الحركة المتأخر.\"}},{\"id\":\"opt_add_bromocriptine_full\",\"text\":{\"en\":\"Co-administer bromocriptine (a full D2 agonist) with haloperidol to stimulate pituitary receptors without affecting mesolimbic circuits.\",\"tr\":\"Mezolimbik devreleri etkilemeden hipofiz reseptörlerini uyarmak için haloperidolün yanına bromokriptin (tam D2 agonisti) ekleyin.\",\"ar\":\"المشاركة الدوائية مع بروموكريبتين (ناهض D2 تام) لتحفيز مستقبلات النخامية دون التأثير على دوائر الميزولمبيك.\"},\"isCorrect\":false,\"feedback\":{\"en\":\"Incorrect. Full dopamine agonists counteract antipsychotic efficacy across the entire brain, triggering immediate, violent psychotic relapse.\",\"tr\":\"Yanlış. Tam dopamin agonistleri tüm beyinde antipsikotik etkiyi sıfırlar ve hastayı derhal şiddetli psikotik alevlenmeye sokar.\",\"ar\":\"غير صحيح. تلغي ناهضات الدوبامين التامة الفعالية المضادة للذهان في كامل الدماغ مفجرة انتكاسة ذهانية عنيفة وفورية.\"}}]},\"sources\":[{\"file\":\"Santral Sinir Sistemi.pdf\",\"page\":28}]}]}}") as unknown as Record<string, LessonData>;

